@Entry
@Component
struct RecipePhotoEditor {
  @StorageLink('recipe_steps') recipeSteps: string[] = ['Step 1: Prepare Ingredients', 'Step 2: Mix Ingredients', 'Step 3: Cook', 'Step 4: Garnish']
  @StorageLink('current_step') currentStep: number = 0
  @StorageLink('photo_cache') photoCache: string[] = ['app_icon', 'common_bg']

  build() {
    Column() {
      // Stepper for step-by-step editing
      Row() {
        ForEach(this.recipeSteps, (step: string, index: number) => {
          Column() {
            Circle()
              .width(40)
              .height(40)
              .fill(this.currentStep >= index ? '#4CAF50' : '#CCCCCC')
            Text(step)
              .fontSize(16)
              .margin({ top: 10 })
          }
          .margin({ right: 20 })
        })
      }
      .margin({ top: 20, bottom: 20 })

      // Navigation buttons
      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentStep > 0) {
              this.currentStep--
            }
          })
          .enabled(this.currentStep > 0)
          .margin({ right: 20 })

        Button('Next')
          .onClick(() => {
            if (this.currentStep < this.recipeSteps.length - 1) {
              this.currentStep++
            }
          })
          .enabled(this.currentStep < this.recipeSteps.length - 1)
      }

      // Photo cache display
      Text('Cached Photos')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 10 })

      List() {
        ForEach(this.photoCache, (photo: string) => {
          ListItem() {
            Image($r(`app.media.${photo}`))
              .width(100)
              .height(100)
              .margin(10)
          }
        })
      }
      .height('30%')
      .width('100%')
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

@Entry
@Component
struct NutritionFactsApp {
  @State searchText: string = '';
  @State selectedFood: FoodItem | null = null;
  @State showNutritionDialog: boolean = false;

  private foodItems: FoodItem[] = [
    {
      id: 1,
      name: 'Apple',
      image: $r('app.media.icon'),
      calories: 52,
      protein: 0.3,
      carbs: 14,
      fat: 0.2
    },
    {
      id: 2,
      name: 'Banana',
      image: $r('app.media.icon'),
      calories: 89,
      protein: 1.1,
      carbs: 22.8,
      fat: 0.3
    },
    {
      id: 3,
      name: 'Orange',
      image: $r('app.media.icon'),
      calories: 47,
      protein: 0.9,
      carbs: 11.8,
      fat: 0.1
    }
  ];

  private filteredFoodItems(): FoodItem[] {
    if (this.searchText.trim() === '') {
      return this.foodItems;
    } else {
      return this.foodItems.filter(item =>
        item.name.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  build() {
    Column() {
      TextInput({
        placeholder: 'Search for food...',
        text: this.searchText
      })
        .width('90%')
        .height(40)
        .onChange((value: string) => {
          this.searchText = value;
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      List() {
        ForEach(this.filteredFoodItems(), (item: FoodItem) => {
          ListItem() {
            Row() {
              Image(item.image)
                .width(60)
                .height(60)
                .borderRadius(8)
                .objectFit(ImageFit.Cover);

              Column() {
                Text(item.name)
                  .fontSize(18)
                  .fontWeight(FontWeight.Medium)
                  .margin({ left: 16 });

                Text(`${item.calories} kcal`)
                  .fontSize(14)
                  .fontColor('#666666')
                  .margin({ left: 16, top: 4 });
              }
              .layoutWeight(1)
              .alignItems(HorizontalAlign.Start);
            }
            .padding(16)
            .gesture(
              LongPressGesture()
                .onAction(() => {
                  this.selectedFood = item;
                  this.showNutritionDialog = true;
                })
            );
          }
          .margin({ bottom: 12 });
        });
      }
      .width('100%');

      if (this.showNutritionDialog && this.selectedFood) {
        Column() {
          Text(this.selectedFood.name)
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 16 });

          Row() {
            Text('Calories:')
              .fontSize(16)
              .layoutWeight(1);
            Text(`${this.selectedFood.calories} kcal`)
              .fontSize(16);
          }
          .margin({ bottom: 8 });

          Row() {
            Text('Protein:')
              .fontSize(16)
              .layoutWeight(1);
            Text(`${this.selectedFood.protein} g`)
              .fontSize(16);
          }
          .margin({ bottom: 8 });

          Row() {
            Text('Carbs:')
              .fontSize(16)
              .layoutWeight(1);
            Text(`${this.selectedFood.carbs} g`)
              .fontSize(16);
          }
          .margin({ bottom: 8 });

          Row() {
            Text('Fat:')
              .fontSize(16)
              .layoutWeight(1);
            Text(`${this.selectedFood.fat} g`)
              .fontSize(16);
          }
          .margin({ bottom: 16 });

          Button('Close')
            .onClick(() => {
              this.showNutritionDialog = false;
            });
        }
        .width('80%')
        .padding(24)
        .backgroundColor(Color.White)
        .borderRadius(16)
        .alignItems(HorizontalAlign.Center);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }
}

interface FoodItem {
  id: number;
  name: string;
  image: Resource;
  calories: number;
  protein: number;
  carbs: number;
  fat: number;
}

@Entry
@Component
struct MultiTabInterface {
  @State private currentIndex: number = 0;
  private tabsController: TabsController = new TabsController();
  @State sliderValue: number = 50;
  @State chipSelected: boolean = false;
  @State selectValue: number = 0;

  @Builder
  TabBuilder(index: number, label: string) {
    Column() {
      Text(label)
        .fontColor(this.currentIndex === index ? '#007DFF' : '#6B6B6B')
        .fontSize(16)
        .fontWeight(this.currentIndex === index ? 500 : 400)
        .margin({ top: 10, bottom: 5 });
      Divider()
        .strokeWidth(2)
        .color('#007DFF')
        .opacity(this.currentIndex === index ? 1 : 0);
    }
    .width('100%')
    .height(50)
    .justifyContent(FlexAlign.Center)
    .onClick(() => {
      this.currentIndex = index;
      this.tabsController.changeIndex(index);
    });
  }

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.Start, controller: this.tabsController }) {
        TabContent() {
          Column() {
            Slider({
              value: this.sliderValue,
              min: 0,
              max: 100,
              style: SliderStyle.OutSet
            })
            .width('80%')
            .onChange((value: number) => {
              this.sliderValue = value;
            });

            Toggle({ type: ToggleType.Checkbox, isOn: this.chipSelected })
            .onChange((isOn: boolean) => {
              this.chipSelected = isOn;
            });

            Select([
              { value: 'Option 1' },
              { value: 'Option 2' },
              { value: 'Option 3' }
            ])
            .selected(this.selectValue)
            .onSelect((index: number) => {
              this.selectValue = index;
            });
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center)
          .padding(20);
        }.tabBar(this.TabBuilder(0, 'Tab 1'));

        TabContent() {
          Column() {
            Slider({
              value: this.sliderValue,
              min: 0,
              max: 100,
              style: SliderStyle.OutSet
            })
            .width('80%')
            .onChange((value: number) => {
              this.sliderValue = value;
            });

            Toggle({ type: ToggleType.Checkbox, isOn: this.chipSelected })
            .onChange((isOn: boolean) => {
              this.chipSelected = isOn;
            });

            Select([
              { value: 'Option 1' },
              { value: 'Option 2' },
              { value: 'Option 3' }
            ])
            .selected(this.selectValue)
            .onSelect((index: number) => {
              this.selectValue = index;
            });
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center)
          .padding(20);
        }.tabBar(this.TabBuilder(1, 'Tab 2'));

        TabContent() {
          Column() {
            Slider({
              value: this.sliderValue,
              min: 0,
              max: 100,
              style: SliderStyle.OutSet
            })
            .width('80%')
            .onChange((value: number) => {
              this.sliderValue = value;
            });

            Toggle({ type: ToggleType.Checkbox, isOn: this.chipSelected })
            .onChange((isOn: boolean) => {
              this.chipSelected = isOn;
            });

            Select([
              { value: 'Option 1' },
              { value: 'Option 2' },
              { value: 'Option 3' }
            ])
            .selected(this.selectValue)
            .onSelect((index: number) => {
              this.selectValue = index;
            });
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center)
          .padding(20);
        }.tabBar(this.TabBuilder(2, 'Tab 3'));
      }
      .vertical(false)
      .barMode(BarMode.Fixed)
      .barWidth('100%')
      .barHeight(56)
      .animationDuration(400)
      .onChange((index: number) => {
        this.currentIndex = index;
      })
      .width('100%')
      .margin({ top: 10 })
      .backgroundColor('#F1F3F5');
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

interface Contact {
  name: string
  image: string
  isFavorite: boolean
}

@Entry
@Component
struct ContactManager {
  @State contacts: Array<Contact> = [
    { name: "John Doe", image: "contact_image1", isFavorite: false },
    { name: "Jane Smith", image: "contact_image2", isFavorite: true },
    { name: "Bob Johnson", image: "contact_image3", isFavorite: false }
  ]
  @State currentIndex: number = 0
  private swiperController: SwiperController = new SwiperController()

  build() {
    Column() {
      Swiper(this.swiperController) {
        ForEach(this.contacts, (contact: Contact, index: number) => {
          Column() {
            Image(contact.image)
              .width(200)
              .height(200)
              .borderRadius(100)
              .accessibilityText(contact.name)
            Text(contact.name)
              .fontSize(20)
              .margin({ top: 10 })
            Toggle({ type: ToggleType.Checkbox, isOn: contact.isFavorite })
              .onChange((isOn: boolean) => {
                this.contacts[index].isFavorite = isOn
              })
              .accessibilityText(`${contact.name} favorite toggle`)
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center)
          .accessibilityGroup(true)
        })
      }
      .loop(false)
      .indicator(false)
      .onChange((index: number) => {
        this.currentIndex = index
      })
      .accessibilityDescription("Contact swiper")
      .width('100%')
      .height('80%')
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
    .onAppear(() => {
      this.swiperController.showNext()
    })
  }
}

import promptAction from '@ohos.promptAction';

interface Article {
  id: number;
  title: string;
  summary: string;
  content: string;
  image: Resource;
}

@Entry
@Component
struct CRMNewsReader {
  @State articles: Article[] = [
    {
      id: 1,
      title: 'Article 1',
      summary: 'Summary of Article 1',
      content: 'Full content of Article 1.',
      image: $r('app.media.icon')
    },
    {
      id: 2,
      title: 'Article 2',
      summary: 'Summary of Article 2',
      content: 'Full content of Article 2.',
      image: $r('app.media.icon')
    },
    {
      id: 3,
      title: 'Article 3',
      summary: 'Summary of Article 3',
      content: 'Full content of Article 3.',
      image: $r('app.media.icon')
    },
    {
      id: 4,
      title: 'Article 4',
      summary: 'Summary of Article 4',
      content: 'Full content of Article 4.',
      image: $r('app.media.icon')
    }
  ];

  @State currentPage: number = 1;
  @State selectedArticle: Article | null = null;
  private articlesPerPage: number = 2;

  getPaginatedArticles(): Article[] {
    const startIndex = (this.currentPage - 1) * this.articlesPerPage;
    return this.articles.slice(startIndex, startIndex + this.articlesPerPage);
  }

  showAlert() {
    promptAction.showDialog({
      title: 'Alert',
      message: 'This is an alert message.',
      buttons: [
        { text: 'OK', color: '#000000' }
      ]
    });
  }

  build() {
    Column() {
      if (this.selectedArticle == null) {
        Column() {
          List() {
            ForEach(this.getPaginatedArticles(), (article: Article) => {
              ListItem() {
                Row() {
                  Image(article.image)
                    .width(80)
                    .height(80)
                    .margin({ right: 16 });
                  Column() {
                    Text(article.title)
                      .fontSize(18)
                      .fontWeight(FontWeight.Bold);
                    Text(article.summary)
                      .fontSize(14)
                      .margin({ top: 8 });
                  }
                }
                .padding(16)
                .onClick(() => {
                  this.selectedArticle = article;
                });
              }
            });
          }
          .width('100%')
          .height('70%');

          Row() {
            Button('Previous')
              .enabled(this.currentPage > 1)
              .onClick(() => {
                if (this.currentPage > 1) {
                  this.currentPage--;
                }
              });
            Text(`Page ${this.currentPage}`)
              .margin({ left: 16, right: 16 });
            Button('Next')
              .enabled(this.currentPage < Math.ceil(this.articles.length / this.articlesPerPage))
              .onClick(() => {
                if (this.currentPage < Math.ceil(this.articles.length / this.articlesPerPage)) {
                  this.currentPage++;
                }
              });
          }
          .justifyContent(FlexAlign.Center)
          .margin({ top: 16 });

          Button('Show Alert')
            .onClick(() => this.showAlert())
            .margin({ top: 16 });
        }
        .width('100%')
        .height('100%')
        .padding(16);
      } else {
        Column() {
          Button('Back')
            .onClick(() => {
              this.selectedArticle = null;
            })
            .margin({ bottom: 16 });

          Scroll() {
            Column() {
              Image(this.selectedArticle.image)
                .width('100%')
                .height(200);
              Text(this.selectedArticle.title)
                .fontSize(24)
                .fontWeight(FontWeight.Bold)
                .margin({ top: 16, bottom: 8 });
              Text(this.selectedArticle.content)
                .fontSize(16)
                .margin({ bottom: 16 });
            }
            .padding(16);
          }
          .width('100%')
          .height('80%');
        }
        .width('100%')
        .height('100%')
        .padding(16);
      }
    }
    .width('100%')
    .height('100%');
  }
}

@Entry
@Component
struct TimePickerWithVoiceInput {
  @State selectedTime: Date = new Date()
  @State displayTime: string = ''
  @State voiceInputActive: boolean = false

  aboutToAppear() {
    this.updateDisplayTime()
  }

  updateDisplayTime() {
    this.displayTime = this.selectedTime.toLocaleTimeString()
  }

  simulateVoiceInput() {
    this.voiceInputActive = true
    setTimeout(() => {
      this.voiceInputActive = false
    }, 2000)
  }

  build() {
    Column() {
      Text('Gesture-Controlled TimePicker')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      TimePicker({
        selected: this.selectedTime
      })
        .onChange((value: TimePickerResult) => {
          if (value.hour !== undefined && value.minute !== undefined) {
            this.selectedTime.setHours(value.hour, value.minute)
            this.updateDisplayTime()
          }
        })
        .gesture(
          TapGesture({ count: 2 })
            .onAction(() => {
              this.simulateVoiceInput()
            })
        )
        .margin({ bottom: 40 })

      Column() {
        Text('Selected Time:')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ bottom: 8 })

        Text(this.displayTime)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .fontColor('#007AFF')
      }
      .padding(16)
      .borderRadius(12)
      .backgroundColor('#F0F0F0')

      if (this.voiceInputActive) {
        Text('Voice Input Active...')
          .fontSize(18)
          .fontColor('#FF0000')
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
  }
}

import { promptAction } from '@kit.ArkUI';

interface Meal {
  id: string;
  name: string;
  ingredients: string[];
}

@Entry
@Component
struct MealPlannerApp {
  @State meals: Meal[] = [];
  @State newMealName: string = '';
  @State newMealIngredients: string = '';

  private generateId(): string {
    return Math.random().toString(36).substring(2, 9);
  }

  private addMeal() {
    if (!this.newMealName.trim() || !this.newMealIngredients.trim()) {
      promptAction.showToast({ message: 'Please fill in all fields.' });
      return;
    }
    const ingredients = this.newMealIngredients.split(',').map(item => item.trim());
    this.meals.push({
      id: this.generateId(),
      name: this.newMealName.trim(),
      ingredients,
    });
    this.newMealName = '';
    this.newMealIngredients = '';
  }

  private showAddMealDialog() {
    promptAction.showDialog({
      title: 'Add New Meal',
      message: 'Enter meal details',
      buttons: [
        {
          text: 'Cancel',
          color: '#FF0000',
        },
        {
          text: 'Save',
          color: '#0000FF',
        },
      ],
    }).then((result) => {
      if (result.index === 1) {
        this.addMeal();
      }
    });
  }

  build() {
    Column() {
      Text('Meal Planner')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Button('Add Meal')
        .onClick(() => this.showAddMealDialog())
        .width(150)
        .height(50)
        .margin({ bottom: 20 });

      List() {
        ForEach(this.meals, (meal: Meal) => {
          ListItem() {
            Column() {
              Text(meal.name)
                .fontSize(18)
                .fontWeight(FontWeight.Bold);
              ForEach(meal.ingredients, (ingredient: string) => {
                Text(`- ${ingredient}`)
                  .fontSize(14)
                  .margin({ left: 10 });
              });
            }
            .padding(10)
            .width('100%');
          }
          .borderRadius(5)
          .margin({ bottom: 10 });
        });
      }
      .width('100%')
      .height('60%');

      Column() {
        TextInput({ placeholder: 'Meal Name', text: this.newMealName })
          .onChange((value: string) => {
            this.newMealName = value;
          })
          .width('80%')
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Ingredients (comma-separated)', text: this.newMealIngredients })
          .onChange((value: string) => {
            this.newMealIngredients = value;
          })
          .width('80%')
          .margin({ bottom: 10 });

        Button('Save Meal')
          .onClick(() => this.addMeal())
          .width(150)
          .height(50);
      }
      .width('100%')
      .alignItems(HorizontalAlign.Center);
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

import router from '@ohos.router';

interface PDFItem {
  id: number;
  preview: Resource;
  title: string;
  path: string;
}

@Entry
@Component
struct PDFViewer {
  private swiperController: SwiperController = new SwiperController();

  @State private pdfItems: PDFItem[] = [
    { id: 1, preview: $r('app.media.icon'), title: 'Document 1', path: 'pages/pdf_1' },
    { id: 2, preview: $r('app.media.icon'), title: 'Document 2', path: 'pages/pdf_2' },
    { id: 3, preview: $r('app.media.icon'), title: 'Document 3', path: 'pages/pdf_3' },
    { id: 4, preview: $r('app.media.icon'), title: 'Document 4', path: 'pages/pdf_4' }
  ];

  @State private currentIndex: number = 0;

  build() {
    Column() {
      Text('PDF Viewer')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Column() {
        Swiper(this.swiperController) {
          ForEach(this.pdfItems, (item: PDFItem) => {
            Stack() {
              Image(item.preview)
                .width('100%')
                .height(300)
                .objectFit(ImageFit.Cover)
                .borderRadius(16);
            }
          });
        }
        .width('100%')
        .height(300)
        .margin({ bottom: 16 })
        .autoPlay(false)
        .indicator(true)
        .loop(false)
        .duration(500)
        .onChange((index: number) => {
          this.currentIndex = index;
        });

        Text(this.pdfItems[this.currentIndex].title)
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 8 })
          .textAlign(TextAlign.Center);
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(20);

      Row() {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });

        Button('View PDF')
          .onClick(() => {
            router.pushUrl({ url: this.pdfItems[this.currentIndex].path });
          });

        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

@Entry
@Component
struct VoiceInputButton {
  @State private voiceText: string = "Swipe and hold to speak";
  @State private isListening: boolean = false;
  @State private options: string[] = ["Option 1", "Option 2", "Option 3"];
  @State private selectedOption: number = -1;

  build() {
    Column() {
      Select(this.options.map((option: string): SelectOption => ({ value: option })))
        .selected(this.selectedOption)
        .onSelect((index: number) => {
          this.selectedOption = index;
        })
        .width(200)
        .height(40)
        .margin(20);

      Button(this.voiceText)
        .width(200)
        .height(60)
        .backgroundColor(this.isListening ? Color.Red : Color.Blue)
        .gesture(
          SwipeGesture({ direction: SwipeDirection.All, fingers: 1 })
            .onAction((event: GestureEvent) => {
              if (event.offsetX > 50 || event.offsetY > 50) {
                this.isListening = true;
                this.voiceText = "Listening...";
              } else {
                this.isListening = false;
                this.voiceText = "Swipe and hold to speak";
              }
            })
        );

      Text(this.selectedOption >= 0 ? this.options[this.selectedOption] : "")
        .fontSize(20)
        .margin(20);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

@Entry
@Component
struct CustomButtonOnboarding {
  @State buttonScale: number = 1
  @State buttonColor: Color = Color.Blue
  @State badgeCount: number = 1
  @State offsetX: number = 0
  @State offsetY: number = 0

  build() {
    Stack() {
      Column() {
        Text('Welcome to Onboarding')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 30 })

        Stack() {
          Button('Tap Me')
            .width(200)
            .height(50)
            .backgroundColor(this.buttonColor)
            .scale({ x: this.buttonScale, y: this.buttonScale })
            .onClick(() => {
              animateTo({
                duration: 200,
                curve: Curve.EaseInOut
              }, () => {
                this.buttonScale = 0.9
                this.buttonColor = Color.Green
              })

              setTimeout(() => {
                animateTo({
                  duration: 200,
                  curve: Curve.EaseInOut
                }, () => {
                  this.buttonScale = 1
                  this.buttonColor = Color.Blue
                  this.badgeCount += 1
                })
              }, 200)
            })
            .gesture(
              PanGesture({ direction: PanDirection.All })
                .onActionUpdate((event: GestureEvent) => {
                  this.offsetX = event.offsetX
                  this.offsetY = event.offsetY
                })
                .onActionEnd(() => {
                  animateTo({ duration: 300 }, () => {
                    this.offsetX = 0
                    this.offsetY = 0
                  })
                })
            )
            .transform({ translate: { x: this.offsetX, y: this.offsetY } })

          Badge({
            count: this.badgeCount,
            position: BadgePosition.RightTop,
            style: { color: Color.White, badgeColor: Color.Red }
          })
        }
      }
      .width('100%')
      .height('100%')
      .justifyContent(FlexAlign.Center)
      .alignItems(HorizontalAlign.Center)
    }
    .width('100%')
    .height('100%')
  }
}

interface Preferences {
  pref_theme: 'light' | 'dark' | 'system';
  pref_language: string;
  pref_notifications: string;
}

@Entry
@Component
struct UserPreferencesService {
  @State preferences: Preferences = {
    pref_theme: 'light',
    pref_language: 'en',
    pref_notifications: 'enabled'
  };

  @State selectedPreference: string = 'pref_theme';
  private scroller: Scroller = new Scroller();

  getSelectedIndex(key: string): number {
    let currentValue: string;
    switch (key) {
      case 'pref_theme':
        currentValue = this.preferences.pref_theme;
        const options = ['light', 'dark', 'system'];
        return options.indexOf(currentValue);
      case 'pref_language':
        currentValue = this.preferences.pref_language;
        return 0;
      case 'pref_notifications':
        currentValue = this.preferences.pref_notifications;
        return 0;
      default:
        return 0;
    }
  }

  updatePreference(value: string) {
    switch(this.selectedPreference) {
      case 'pref_theme':
        this.preferences.pref_theme = value as 'light' | 'dark' | 'system';
        break;
      case 'pref_language':
        this.preferences.pref_language = value;
        break;
      case 'pref_notifications':
        this.preferences.pref_notifications = value;
        break;
    }
    setTimeout(() => {
      console.info(`Preference updated: ${this.selectedPreference}=${value}`);
    }, 500);
  }

  build() {
    Column() {
      Scroll(this.scroller) {
        Column() {
          ForEach(['pref_theme', 'pref_language', 'pref_notifications'], (key: string) => {
            Column() {
              Text(key.replace('pref_', '').toUpperCase())
                .fontSize(18)
                .fontWeight(700)
                .margin({ bottom: 10 });

              Select([
                { value: 'light' },
                { value: 'dark' },
                { value: 'system' }
              ])
                .selected(this.getSelectedIndex(key))
                .onSelect((index: number, value: string) => {
                  this.selectedPreference = key;
                  this.updatePreference(value);
                })
                .width('100%')
                .margin({ bottom: 20 });
            }
            .width('90%')
            .padding(10)
            .backgroundColor(0xF5F5F5)
            .borderRadius(8)
            .margin({ bottom: 10 });
          })
        }
        .width('100%')
        .padding(20);
      }
      .scrollable(ScrollDirection.Vertical)
      .scrollBar(BarState.On)
      .edgeEffect(EdgeEffect.Spring)
      .height('80%');

      Button('Save Preferences')
        .onClick(() => {
          console.info('Preferences saved:', JSON.stringify(this.preferences));
        })
        .width('80%')
        .height(50)
        .margin({ top: 20 })
        .backgroundColor(0xFF6200EE)
        .fontColor(Color.White);
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

