@Entry
@Component
struct JournalTaskApp {
  private swiperController: SwiperController = new SwiperController();

  private carouselItems: CarouselItem[] = [
    {
      id: 1,
      image: $r('app.media.icon'),
      caption: 'Task 1: Complete UI Design'
    },
    {
      id: 2,
      image: $r('app.media.icon'),
