@Entry
@Component
struct TaskManagementApp {
  @State tasks: string[] = ['Task 1', 'Task 2', 'Task 3'];
  @State isRefreshing: boolean = false;
  @State showVoiceCommand: boolean = false;

  private refreshTasks() {
    this.isRefreshing = true;
    setTimeout(() => {
      this.tasks = ['New Task', ...this.tasks];
      this.isRefreshing = false;
    }, 2000);
  }

  private handleLongPress() {
    this.showVoiceCommand = true;
  }

  private executeVoiceCommand(command: string) {
    console.log(`Executing voice command: ${command}`);
    this.showVoiceCommand = false;
  }

  build() {
    Column() {
      List() {
        ForEach(this.tasks, (task: string) => {
          ListItem() {
            Text(task)
              .fontSize(16)
              .padding(10)
              .gesture(
                LongPressGesture()
                  .onAction(() => {
                    this.handleLongPress();
                  })
              );
          }
        });
      }
      .onScrollIndex((start: number, end: number, center: number) => {
        if (start < 0 && !this.isRefreshing) {
          this.refreshTasks();
        }
      })
      .height('80%');

      if (this.isRefreshing) {
        Text('Refreshing...')
          .fontSize(16)
          .padding(10);
      }

      if (this.showVoiceCommand) {
        Column() {
          Text('Voice Command Activated')
            .fontSize(20)
            .padding(10);
          Button('Complete Task')
            .onClick(() => {
              this.executeVoiceCommand('Complete Task');
            });
          Button('Delete Task')
            .onClick(() => {
              this.executeVoiceCommand('Delete Task');
            });
        }
        .backgroundColor('#f0f0f0')
        .borderRadius(10)
        .padding(20);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

