@Entry
@Component
struct ARServiceApp {
  @State arData: number[][] = [
    [1, 2, 3],
    [4, 5, 6],
    [7, 8, 9]
  ];

  @State processing: boolean = false;
  @State result: string = '';

  private processARData() {
    this.processing = true;
    setTimeout(() => {
      let sum = 0;
      for (let row of this.arData) {
        for (let num of row) {
          sum += num;
        }
      }
      this.result = `Processed AR Data Sum: ${sum}`;
      this.processing = false;
    }, 2000);
  }

  build() {
    Column() {
      Text('AR Data Grid')
        .fontSize(24)
        .margin({ bottom: 20 });

      Grid() {
        ForEach(this.arData, (row: number[], rowIndex: number) => {
          GridItem() {
            Column() {
              ForEach(row, (num: number, colIndex: number) => {
                Text(num.toString())
                  .fontSize(18)
                  .padding(10)
                  .backgroundColor('#F0F0F0')
                  .borderRadius(8)
                  .margin(5);
              });
            }
          }
        });
      }
      .columnsTemplate('1fr 1fr 1fr')
      .rowsGap(10)
      .columnsGap(10)
      .padding(10);

      Button(this.processing ? 'Processing...' : 'Process AR Data')
        .onClick(() => {
          if (!this.processing) {
            this.processARData();
          }
        })
        .margin({ top: 20 });

      Text(this.result)
        .fontSize(18)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

