        TextInput({ placeholder: 'Add new todo...' })
          .onChange((value: string) => {
            this.newTodo = value;
          })
          .width('70%');

        Button('Add')
          .onClick(() => {
            if (this.newTodo.trim()) {
              this.todoItems.push(this.newTodo);
