@Entry
@Component
struct GestureAudioCard {
  @State private playbackActive: boolean = false;
  @State private recordingActive: boolean = false;
  @State private cardColor: Color = Color.White;
  @State private gestureType: string = 'No gesture';
  @State private cardScale: number = 1.0;
  @State private offsetX: number = 0;
  @State private offsetY: number = 0;

  private handleTap() {
    this.gestureType = 'Tap';
    this.playbackActive = !this.playbackActive;
  }

  private handleSwipe(direction: string) {
    this.gestureType = `Swipe ${direction}`;
    this.cardColor = direction === 'Right' ? Color.Green : Color.Red;
    this.recordingActive = direction === 'Left';
  }

  private handlePinch(scale: number) {
    this.gestureType = 'Pinch';
    this.cardScale = scale;
  }

  private handlePan(event: GestureEvent) {
    this.gestureType = 'Pan';
    this.offsetX = event.offsetX;
    this.offsetY = event.offsetY;
  }

  build() {
    Column({ space: 20 }) {
      List({ space: 20 }) {
        ListItem() {
          Column({ space: 10 }) {
            Flex({ justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
              Image($r('app.media.icon'))
                .width(100)
                .height(100)
                .gesture(
                  TapGesture({ count: 1 })
                    .onAction(() => this.handleTap())
                )
                .transform({ scale: this.cardScale })
                .animation({ duration: 300 })

              Image($r('app.media.icon'))
                .width(100)
                .height(100)
                .gesture(
                  PinchGesture()
                    .onActionEnd((event: GestureEvent) => this.handlePinch(event.scale))
                )
                .transform({ scale: this.cardScale })
                .animation({ duration: 300 })
            }
            .backgroundColor(this.cardColor)
            .width('100%')
            .height(200)
            .gesture(
              SwipeGesture({ direction: SwipeDirection.Horizontal })
                .onAction((event: GestureEvent) => {
                  const direction = event.offsetX > 0 ? 'Right' : 'Left';
                  this.handleSwipe(direction);
                })
            )
            .gesture(
              PanGesture()
                .onActionUpdate((event: GestureEvent) => this.handlePan(event))
            )
            .transform({ translate: { x: this.offsetX, y: this.offsetY } })
            .animation({ duration: 300 })

            Text(`Gesture: ${this.gestureType}`)
              .fontSize(16)
              .fontColor(Color.Black)

            Text(this.playbackActive ? 'Playing audio...' : 'Audio stopped')
              .fontSize(14)
              .fontColor(Color.Gray)

            Text(this.recordingActive ? 'Recording...' : 'Not recording')
              .fontSize(14)
              .fontColor(Color.Gray)
          }
          .padding(20)
        }
        .backgroundColor(this.cardColor)
        .borderRadius(10)
        .margin({ top: 20, bottom: 20 })
      }
      .height('100%')
      .width('100%')
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

