@Component
struct TravelPlannerForm {
  @State destination: string = ''
  @State departureDate: string = ''
  @State returnDate: string = ''
  @State errorMessage: string = ''
  @State successMessage: string = ''
  @State offsetX: number = 0

  validateForm(): boolean {
    if (!this.destination || !this.departureDate || !this.returnDate) {
      this.errorMessage = 'All fields are required.'
      this.successMessage = ''
      return false
    }
    this.errorMessage = ''
    this.successMessage = 'Form submitted successfully!'
    return true
  }

  build() {
    Column({ space: 20 }) {
      Text('Travel Planner')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Destination' })
        .onChange((value: string) => {
          this.destination = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Departure Date (YYYY-MM-DD)' })
        .onChange((value: string) => {
          this.departureDate = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Return Date (YYYY-MM-DD)' })
        .onChange((value: string) => {
          this.returnDate = value
        })
        .margin({ bottom: 20 })

      Row()
        .width(300)
        .height(100)
        .backgroundColor(Color.Blue)
        .borderRadius(10)
        .gesture(
          PanGesture({ direction: PanDirection.Horizontal })
            .onActionStart(() => {
              console.info('Swipe started')
            })
            .onActionUpdate((event: GestureEvent) => {
              this.offsetX = event.offsetX
            })
            .onActionEnd(() => {
              if (Math.abs(this.offsetX) > 50) {
                console.info('Swipe validated')
                if (this.validateForm()) {
                  this.successMessage = 'Form submitted successfully!'
                }
              }
              animateTo({ duration: 300 }, () => {
                this.offsetX = 0
              })
            })
        )
        .transform({ translate: { x: this.offsetX } })
        .animation({ duration: 300 })

      Button('Submit')
        .onClick(() => {
          if (this.validateForm()) {
            this.successMessage = 'Form submitted successfully!'
          }
        })

      Text(this.errorMessage)
        .fontSize(14)
        .fontColor(Color.Red)
        .margin({ top: 10 })

      Text(this.successMessage)
        .fontSize(14)
        .fontColor(Color.Green)
        .margin({ top: 10 })
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct GestureRecognitionDemo {
  @State isRefreshing: boolean = false;
  @State progressValue: number = 0;
  private items: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4', 'Item 5'];

  build() {
    Column() {
      Refresh({ refreshing: this.isRefreshing, offset: 120, friction: 100 }) {
        Scroll() {
          Column() {
            ForEach(this.items, (item: string) => {
              Column() {
                Text(item)
                  .fontSize(20)
                  .padding(10)
                  .width('100%')
                  .backgroundColor('#f0f0f0');
              }
              .width('100%');
            });
          }
          .width('100%');
        }
        .width('100%')
        .height('80%');
      }
      .onStateChange((refreshStatus: RefreshStatus) => {
        if (refreshStatus === RefreshStatus.Refresh) {
          this.isRefreshing = true;
          this.progressValue = 0;
          let interval = setInterval(() => {
            this.progressValue += 10;
            if (this.progressValue >= 100) {
              clearInterval(interval);
              this.isRefreshing = false;
              this.items = [...this.items, `Item ${this.items.length + 1}`];
            }
          }, 200);
        }
      });

      Progress({ value: this.progressValue, total: 100 })
        .width('80%')
        .height(10)
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .padding(10);
  }
}

@Entry
@Component
struct TaskManagerForm {
  @State taskName: string = ''
  @State taskPriority: string = 'Low'
  @State taskDeadline: string = ''
  @State errorMessage: string = ''
  @State tasks: Array<Task> = []

  validateForm(): boolean {
    if (this.taskName.trim() === '') {
      this.errorMessage = 'Task name cannot be empty'
      return false
    }
    if (this.taskDeadline.trim() === '') {
      this.errorMessage = 'Deadline cannot be empty'
      return false
    }
    this.errorMessage = ''
    return true
  }

  addTask() {
    if (this.validateForm()) {
      const newTask: Task = {
        id: Date.now(),
        name: this.taskName,
        priority: this.taskPriority,
        deadline: this.taskDeadline
      }
      this.tasks.push(newTask)
      this.taskName = ''
      this.taskPriority = 'Low'
      this.taskDeadline = ''
    }
  }

  removeTask(index: number) {
    this.tasks.splice(index, 1)
  }

  build() {
    Column({ space: 20 }) {
      Text('Task Manager')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Task Name', text: this.taskName })
        .onChange((value: string) => {
          this.taskName = value
        })
        .width('100%')

      Row({ space: 10 }) {
        Text('Priority:')
          .fontSize(16)
        Radio({ group: 'priorityGroup', value: 'Low' })
          .onChange((isChecked: boolean) => {
            if (isChecked) this.taskPriority = 'Low'
          })
        Radio({ group: 'priorityGroup', value: 'Medium' })
          .onChange((isChecked: boolean) => {
            if (isChecked) this.taskPriority = 'Medium'
          })
        Radio({ group: 'priorityGroup', value: 'High' })
          .onChange((isChecked: boolean) => {
            if (isChecked) this.taskPriority = 'High'
          })
      }
      .width('100%')

      TextInput({ placeholder: 'Deadline (YYYY-MM-DD)', text: this.taskDeadline })
        .onChange((value: string) => {
          this.taskDeadline = value
        })
        .width('100%')

      Button('Add Task')
        .onClick(() => this.addTask())
        .width('100%')

      Text(this.errorMessage)
        .fontSize(14)
        .fontColor(Color.Red)

      List() {
        ForEach(this.tasks, (task: Task, index: number) => {
          ListItem() {
            Row() {
              Column() {
                Text(task.name)
                  .fontSize(18)
                  .fontWeight(FontWeight.Bold)
                Text(`Priority: ${task.priority}`)
                  .fontSize(14)
                  .fontColor(Color.Gray)
                Text(`Deadline: ${task.deadline}`)
                  .fontSize(14)
                  .fontColor(Color.Gray)
              }
              .layoutWeight(1)

              Button('Delete')
                .onClick(() => this.removeTask(index))
                .width(60)
                .height(40)
            }
            .padding(10)
            .width('100%')
          }
        })
      }
      .layoutWeight(1)
      .width('100%')
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

interface Task {
  id: number
  name: string
  priority: string
  deadline: string
}

@Entry
@Component
struct MeditationARApp {
  @State selectedMeditationType: string = 'Mindfulness'
  @State isSessionRunning: boolean = false
  @State progress: number = 0
  @State sessionDuration: number = 0
  private timerId: number = -1

  private meditationTypes: string[] = ['Mindfulness', 'Breathing', 'Visualization']
  private maxDuration: number = 300

  build() {
    Column() {
      Text('Meditation AR App')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      Column() {
        ForEach(this.meditationTypes, (type: string) => {
          Row() {
            Radio({ value: type, group: 'meditationGroup' })
              .checked(this.selectedMeditationType === type)
              .onChange((checked: boolean) => {
                if (checked) {
                  this.selectedMeditationType = type
                }
              })
            Text(type)
              .margin({ left: 8 })
          }
        })
      }
      .margin({ top: 20, bottom: 20 })

      Row() {
        Button(this.isSessionRunning ? 'Pause' : 'Start')
          .onClick(() => {
            if (this.isSessionRunning) {
              this.pauseSession()
            } else {
              this.startSession()
            }
          })
          .margin({ right: 10 })

        Button('Reset')
          .onClick(() => {
            this.resetSession()
          })
      }

      Progress({ value: this.progress, total: this.maxDuration })
        .width('90%')
        .height(10)
        .margin({ top: 20 })

      Text(`${this.sessionDuration}s / ${this.maxDuration}s`)
        .fontSize(18)
        .margin({ top: 10 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }

  startSession(): void {
    if (!this.isSessionRunning) {
      this.timerId = setInterval(() => {
        if (this.sessionDuration < this.maxDuration) {
          this.sessionDuration++
          this.progress = this.sessionDuration
        } else {
          this.pauseSession()
        }
      }, 1000)
      this.isSessionRunning = true
    }
  }

  pauseSession(): void {
    clearInterval(this.timerId)
    this.isSessionRunning = false
  }

  resetSession(): void {
    clearInterval(this.timerId)
    this.isSessionRunning = false
    this.sessionDuration = 0
    this.progress = 0
  }
}

@Entry
@Component
struct CalculatorAccordion {
  @State expandedIndex: number = -1;
  @State lazyLoadedItems: boolean[] = [false, false, false];
  @State selectedOperation: string = "Select an operation";
  @State panOffset: number = 0;

  private accordionItems: string[] = ["Basic Operations", "Scientific Operations", "History"];

  build() {
    Column() {
      ForEach(this.accordionItems, (item: string, index: number) => {
        Column() {
          Row() {
            Text(item)
              .fontSize(20)
              .margin({ left: 10 });

            Button(this.expandedIndex === index ? "▲" : "▼")
              .width(30)
              .height(30)
              .margin({ right: 10 })
              .onClick(() => {
                this.expandedIndex = this.expandedIndex === index ? -1 : index;
                if (!this.lazyLoadedItems[index]) {
                  this.lazyLoadedItems[index] = true;
                }
              });
          }
          .width('100%')
          .height(50)
          .backgroundColor('#F1F3F5')
          .borderRadius(5)
          .justifyContent(FlexAlign.SpaceBetween)
          .onClick(() => {
            this.expandedIndex = this.expandedIndex === index ? -1 : index;
            if (!this.lazyLoadedItems[index]) {
              this.lazyLoadedItems[index] = true;
            }
          });

          if (this.expandedIndex === index && this.lazyLoadedItems[index]) {
            Column() {
              if (index === 0) {
                Select([
                  { value: 'Add' },
                  { value: 'Subtract' },
                  { value: 'Multiply' },
                  { value: 'Divide' }
                ])
                .value(this.selectedOperation)
                .onSelect((i: number, value?: string) => {
                  if (value) {
                    this.selectedOperation = value;
                  }
                })
                .width('80%')
                .margin({ top: 10 });
              } else if (index === 1) {
                Text("Scientific operations will be loaded here.")
                  .fontSize(16)
                  .margin({ top: 10 });
              } else {
                Text("History will be loaded here.")
                  .fontSize(16)
                  .margin({ top: 10 });
              }
            }
            .width('100%')
            .padding(10)
            .backgroundColor('#FFFFFF')
            .borderRadius(5)
            .gesture(
              PanGesture({ direction: PanDirection.Horizontal })
                .onActionUpdate((event: GestureEvent) => {
                  this.panOffset = event.offsetX;
                })
                .onActionEnd(() => {
                  animateTo({ duration: 300 }, () => {
                    this.panOffset = 0;
                  });
                })
            )
            .transform({ translate: { x: this.panOffset } });
          }
        }
        .width('100%')
        .margin({ top: 10 });
      });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

