@Entry
@Component
struct MealPlanner {
  @State selectedDate: Date = new Date()
  @State meals: string[] = ['Breakfast', 'Lunch', 'Dinner']
  @State currentMeal: string = ''
  @State themeValue: number = 0
  @State textColor: Color = Color.Black

  aboutToAppear() {
    this.updateMeal()
  }

  updateMeal() {
    const index = Math.floor(Math.random() * this.meals.length)
    this.currentMeal = this.meals[index]
  }

  updateTheme(value: number) {
    this.themeValue = value
    if (value < 50) {
      this.textColor = Color.Black
    } else {
      this.textColor = Color.White
    }
  }

  build() {
    Column() {
      DatePicker({
        start: new Date('2000-01-01'),
        end: new Date('2030-12-31'),
        selected: this.selectedDate
      })
      .onDateChange((value: Date) => {
        this.selectedDate = value
        this.updateMeal()
      })
      .margin({top: 20})

      Text('Meal: ' + this.currentMeal)
        .fontSize(24)
        .fontColor(this.textColor)
        .margin({top: 20, bottom: 20})

      Slider({
        value: this.themeValue,
        min: 0,
        max: 100,
        step: 10
      })
      .onChange((value: number) => {
        this.updateTheme(value)
      })
      .margin({top: 20})
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.themeValue < 50 ? Color.White : Color.Black)
