@Entry
@Component
struct WeatherApp {
  @State temperature: string = '25\u00b0C';
  @State condition: string = 'Sunny';
  @State imgScale: number = 1.0;
  @State progress: number = 0;
  @State weatherIcon: Resource = $r('app.media.icon');

  build() {
    Column() {
      Column() {
        Text('Current Weather')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 10 });

        Image(this.weatherIcon)
          .width(100 * this.imgScale)
          .height(100 * this.imgScale)
          .gesture(
            GestureGroup(
              GestureMode.Exclusive,
              RotationGesture()
                .onActionUpdate((event) => {
                  const angle = Math.abs(event.angle);
                  this.imgScale = Math.min(Math.max(1.0, angle / 45), 2.0);
                })
                .onActionEnd(() => {
                  console.info('Rotation gesture ended');
                }),
              TapGesture({ count: 1 })
                .onAction(() => {
                  this.imgScale = 1.0;
                })
            )
          )
          .margin({ bottom: 20 });

        Text(`Temperature: ${this.temperature}`)
          .fontSize(20)
          .margin({ bottom: 5 });

        Text(`Condition: ${this.condition}`)
          .fontSize(20)
          .margin({ bottom: 20 });
      }

      Column() {
        Progress({ value: this.progress, total: 100 })
          .width(200)
          .height(200)
          .style({ strokeWidth: 10 })
          .margin({ bottom: 20 });

        Row() {
          Button('Increase Progress')
            .onClick(() => {
              this.progress = Math.min(this.progress + 10, 100);
            })
            .margin({ right: 10 });

          Button('Reset Progress')
            .onClick(() => {
              this.progress = 0;
            });
        }
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .padding(20);
  }
}

