@Entry
@Component
struct GestureAnimationList {
  @State selectedDate: string = '';
  @State isAnimated: boolean = false;

  build() {
    Column() {
      DatePicker({
        start: new Date(),
        end: new Date(),
        selected: new Date()
      })
      .onDateChange((value: Date) => {
        let month = value.getMonth() + 1;
        this.selectedDate = value.getFullYear() + '-' + month + '-' + value.getDate();
      })
      .margin(10)

      List() {
        ForEach([1, 2, 3, 4, 5], (item: number) => {
          ListItem() {
            Text(`Item ${item}`)
              .fontSize(20)
              .fontColor(Color.Black)
          }
          .gesture(
            TapGesture()
              .onAction(() => {
                animateTo({
                  duration: 300,
                  curve: Curve.EaseInOut,
                  delay: 0,
                  iterations: 1
                }, () => {
                  this.isAnimated = !this.isAnimated;
                });
              })
          )
          .transform({
            scale: { x: this.isAnimated ? 1.2 : 1.0, y: this.isAnimated ? 1.2 : 1.0 }
          })
          .animation({ duration: 300 })
        })
      }
      .width('100%')
      .height('80%')
      .margin(10)
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
  }
}

import mediaquery from '@ohos.mediaquery'
import promptAction from '@ohos.promptAction'

@Entry
@Component
struct TVPinchZoomApp {
  @State scaleValue: number = 1.0
  @State lastScale: number = 1.0
  @State initialDistance: number = 0
  @State selectedDate: Date = new Date()
  @State isPortrait: boolean = false

  aboutToAppear() {
    const mediaQueryListener = mediaquery.matchMediaSync('(orientation: portrait)')
    mediaQueryListener.on('change', (result: mediaquery.MediaQueryResult) => {
      this.isPortrait = result.matches
    })
  }

  build() {
    Column() {
      Image($r('app.media.icon'))
        .width('100%')
        .height('100%')
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .onTouch((event: TouchEvent) => {
          if (event.touches.length === 2) {
            const touch1 = event.touches[0]
            const touch2 = event.touches[1]
            const currentDistance = Math.sqrt(
              Math.pow(touch2.x - touch1.x, 2) + 
              Math.pow(touch2.y - touch1.y, 2))
            if (this.initialDistance === 0) {
              this.initialDistance = currentDistance
            } else {
              const scaleFactor = currentDistance / this.initialDistance
              this.scaleValue = this.lastScale * scaleFactor
            }
          } else if (event.type === TouchType.Up) {
            this.lastScale = this.scaleValue
            this.initialDistance = 0
          }
        })

      DatePicker({
        start: new Date(1970, 0, 1),
        end: new Date(2100, 11, 31),
        selected: this.selectedDate
      })
      .onDateChange((value: Date) => {
        this.selectedDate = value
        promptAction.showToast({ 
          message: 'Date selected: ' + 
          `${value.getFullYear()}-${value.getMonth() + 1}-${value.getDate()}`
        })
      })

      Text(this.isPortrait ? 'Portrait Mode' : 'Landscape Mode')
        .fontSize(24)
        .margin(20)
    }
    .width('100%')
    .height('100%')
  }
}

