import mediaquery from '@ohos.mediaquery';

@Entry
@Component
struct ResponsiveLayoutWithBackgroundService {
  @State isLargeScreen: boolean = false;
  @State isDarkMode: boolean = false;
  @State videoPlaceholderVisible: boolean = true;
  @State menuVisible: boolean = false;

  aboutToAppear() {
    const screenSizeListener = mediaquery.matchMediaSync('(min-width: 600vp)');
    const colorSchemeListener = mediaquery.matchMediaSync('(prefers-color-scheme: dark)');

    screenSizeListener.on('change', (result: mediaquery.MediaQueryResult) => {
      this.isLargeScreen = result.matches;
    });

    colorSchemeListener.on('change', (result: mediaquery.MediaQueryResult) => {
      this.isDarkMode = result.matches;
    });
  }

  private simulateBackgroundTask() {
    setTimeout(() => {
      this.videoPlaceholderVisible = false;
    }, 3000);
  }

  build() {
    Column() {
      Row() {
        Button('Menu')
          .onClick(() => {
            this.menuVisible = !this.menuVisible;
          })
          .margin(10)
          .backgroundColor(this.isDarkMode ? '#555555' : '#EEEEEE')
          .fontColor(this.isDarkMode ? Color.White : Color.Black);

        if (this.menuVisible) {
          Column() {
            Button('Option 1').margin(5);
            Button('Option 2').margin(5);
            Button('Option 3').margin(5);
          }
          .backgroundColor(this.isDarkMode ? '#333333' : '#FFFFFF')
          .borderRadius(5)
          .margin(10);
        }
      }
      .justifyContent(FlexAlign.Start)
      .width('100%');

      if (this.videoPlaceholderVisible) {
        Column() {
          Rect()
            .width(this.isLargeScreen ? 300 : 150)
            .height(this.isLargeScreen ? 200 : 100)
            .fill(this.isDarkMode ? '#555555' : '#EEEEEE')
            .borderRadius(8);
          Text('Loading video...')
            .fontSize(16)
            .margin({ top: 10 });
        }
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center)
        .width('100%')
        .margin({ top: 20 });
      } else {
        Column() {
          Text('Video content would appear here')
            .fontSize(16)
            .margin({ top: 20 });
        }
        .width('100%');
      }

      Button('Start Background Task')
        .onClick(() => {
          this.simulateBackgroundTask();
        })
        .margin(20)
        .width(this.isLargeScreen ? 200 : 150)
        .height(50)
        .backgroundColor(this.isDarkMode ? '#555555' : '#EEEEEE')
        .fontColor(this.isDarkMode ? Color.White : Color.Black);
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.isDarkMode ? '#333333' : '#FFFFFF')
    .padding(16);
  }
}

