        Row()
          .width('100%')
          .height(200)
          .backgroundColor('#E0E0E0')
          .gesture(
            PanGesture({ direction: PanDirection.Vertical })
              .onActionUpdate((event: GestureEvent) => {
                this.offsetY = event.offsetY;
                this.gestureProgress = Math.min(100, Math.max(0, (event.offsetY / 200) * 100));
              })
              .onActionEnd(() => {
                if (this.offsetY < -50) {
                  this.isBottomSheetOpen = true;
                } else {
                  this.isBottomSheetOpen = false;
                }
                this.offsetY = 0;
              })
          )
          .transform({ translate: { y: this.offsetY } })
          .animation({ duration: 300 });
      }
      .width('100%')
      .height('100%')
      .justifyContent(FlexAlign.Center)
      .alignItems(HorizontalAlign.Center);

      if (this.isBottomSheetOpen) {
        Column() {
          Text('BottomSheet Content')
            .fontSize(18)
            .margin({ top: 20 });
          Button('Close')
            .width(150)
            .height(50)
            .margin({ top: 20 })
            .onClick(() => {
              this.isBottomSheetOpen = false;
            });
        }
        .width('100%')
        .height(300)
        .backgroundColor('#FFFFFF')
        .borderRadius(10)
        .gesture(
          PanGesture({ direction: PanDirection.Vertical })
            .onActionUpdate((event: GestureEvent) => {
              this.offsetY = event.offsetY;
            })
            .onActionEnd(() => {
              if (this.offsetY > 50) {
                this.isBottomSheetOpen = false;
              }
              this.offsetY = 0;
            })
        )
        .transform({ translate: { y: this.offsetY } })
        .animation({ duration: 300 });
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

