@Component
struct WaterIntakeTracker {
  @State waterIntake: number = 0;
  @State progress: number = 0;

  updateProgress() {
    this.progress = (this.waterIntake / 2000) * 100;
  }

  build() {
    Column() {
      Text('Water Intake Tracker')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin(20);

      Text('Current Intake: ' + this.waterIntake + ' ml')
        .fontSize(18)
        .margin(10);

      Stack() {
        Circle()
          .width(200)
          .height(200)
          .stroke('#E0E0E0')
          .strokeWidth(15)
          .fill('transparent');

        Circle()
          .width(200)
          .height(200)
          .stroke('#4CAF50')
          .strokeWidth(15)
          .fill('transparent')
          .strokeDashArray([Math.PI * 200, Math.PI * 200])
          .strokeDashOffset(Math.PI * 200 * (1 - this.progress / 100))
          .rotate({ x: 0, y: 0, z: 1, angle: -90 });

        Text('' + Math.round(this.progress) + '%')
          .fontSize(24)
          .fontWeight(FontWeight.Bold);
