@Entry
@Component
struct InventoryManager {
  @State private items: Array<string> = [];
  @State private selectedItem: string = '';
  @State private loading: boolean = false;
  private page: number = 1;

  private selectOptions: SelectOption[] = [
    { value: 'All', icon: $r('app.media.icon') },
    { value: 'Available', icon: $r('app.media.icon') },
    { value: 'Out of stock', icon: $r('app.media.icon') }
  ];

  loadMoreItems() {
    this.loading = true;
    setTimeout(() => {
      const newItems: Array<string> = Array.from({ length: 10 }, (index: number) => 'Item ' + ((this.page - 1) * 10 + index + 1));
      this.items = this.items.concat(newItems);
      this.loading = false;
    }, 1000);
  }

  aboutToAppear() {
    this.loadMoreItems();
  }

  build() {
    Column() {
      Select(this.selectOptions)
      .onSelect((index: number, value: string) => {
        this.selectedItem = value;
      })
      .margin(10);

      Refresh({
        refreshing: this.loading,
        offset: 150,
        friction: 100
      }) {
        List() {
          ForEach(this.items, (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(18)
                .margin(10);
            }
          });
        }
        .onScrollIndex((index: number) => {
          if (index === this.items.length - 1) {
            this.page += 1;
            this.loadMoreItems();
          }
        })
      }
      .onRefreshing(() => {
        this.page = 1;
        this.items = [];
        this.loadMoreItems();
      });
    }
    .width('100%')
    .height('100%');
  }
}

