            .scale({ x: this.scaleValue, y: this.scaleValue })
            .gesture(
              PinchGesture()
                .onActionUpdate((event: GestureEvent) => {
                  if (this.isZoomEnabled) {
                    this.scaleValue *= event.scale
                  }
                })
            )
            .animation({ duration: 300 })
        }
        ListItem() {
          Text("Sample Item 1")
        }
        ListItem() {
          Text("Sample Item 2")
        }
      }
      .width('100%')
      .height('80%')
    }
    .width('100%')
    .height('100%')
  }
