interface EventItem {
  id: number;
  title: string;
  videoPlaceholder: Resource;
}

@Entry
@Component
struct EventPlannerSearch {
  @State items: Array<EventItem> = [
    { id: 1, title: 'Conference', videoPlaceholder: $r('sys.media.ohos_app_icon') },
    { id: 2, title: 'Workshop', videoPlaceholder: $r('sys.media.ohos_app_icon') },
    { id: 3, title: 'Meeting', videoPlaceholder: $r('sys.media.ohos_app_icon') },
    { id: 4, title: 'Seminar', videoPlaceholder: $r('sys.media.ohos_app_icon') },
    { id: 5, title: 'Webinar', videoPlaceholder: $r('sys.media.ohos_app_icon') },
    { id: 6, title: 'Training', videoPlaceholder: $r('sys.media.ohos_app_icon') },
    { id: 7, title: 'Hackathon', videoPlaceholder: $r('sys.media.ohos_app_icon') },
    { id: 8, title: 'Networking', videoPlaceholder: $r('sys.media.ohos_app_icon') }
  ];

  @State searchText: string = '';
  @State currentPage: number = 1;
  @State itemsPerPage: number = 4;

  filteredItems(): Array<EventItem> {
    if (this.searchText.trim() === '') {
      return this.items;
    } else {
      return this.items.filter(item =>
        item.title.toLowerCase().includes(this.searchText.toLowerCase()))
    }
  }

  paginatedItems(): Array<EventItem> {
    const startIndex = (this.currentPage - 1) * this.itemsPerPage;
    return this.filteredItems().slice(startIndex, startIndex + this.itemsPerPage);
  }

  totalPages(): number {
    return Math.ceil(this.filteredItems().length / this.itemsPerPage);
  }

  build() {
    Column() {
      TextInput({
        placeholder: 'Search events...',
        text: this.searchText
      })
        .width('100%')
        .onChange((value: string) => {
          this.searchText = value;
          this.currentPage = 1;
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      if (this.filteredItems().length > 0) {
        List() {
          ForEach(this.paginatedItems(), (item: EventItem) => {
            ListItem() {
              Row() {
                Image(item.videoPlaceholder)
                  .width(80)
                  .height(80)
                  .borderRadius(8)
                  .margin({ right: 12 });
                Text(item.title)
                  .fontSize(18)
                  .fontWeight(FontWeight.Bold);
              }
              .padding(12)
              .width('100%');
            }
          }, (item: EventItem) => item.id.toString());
        }
      } else {
        Text('No events found')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16);
      }

      if (this.totalPages() > 1) {
        Row() {
          Button('Previous')
            .onClick(() => {
              if (this.currentPage > 1) {
                this.currentPage -= 1;
              }
            })
            .enabled(this.currentPage > 1)
            .margin({ right: 8 });

          Text(`${this.currentPage} / ${this.totalPages()}`)
            .fontSize(16);

          Button('Next')
            .onClick(() => {
              if (this.currentPage < this.totalPages()) {
                this.currentPage += 1;
              }
            })
            .enabled(this.currentPage < this.totalPages())
            .margin({ left: 8 });
        }
        .justifyContent(FlexAlign.Center)
        .margin({ top: 16 });
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

