            .width('90%')
            .onChange((value: string) => {
              this.newNoteContent = value;
            })
            .margin(10);

          Button('Add Note')
            .onClick(() => {
              if (this.newNoteTitle.trim() && this.newNoteContent.trim()) {
                this.notes.push({
                  id: Date.now(),
                  title: this.newNoteTitle,
                  content: this.newNoteContent
                });
                this.newNoteTitle = '';
                this.newNoteContent = '';
