                      .width('80%');
                    Text(note.content)
                      .fontSize(16)
                      .width('80%');
                  }
                  .width('80%');

                  Button('Delete')
                    .onClick(() => {
                      this.notes = this.notes.filter(n => n.id !== note.id);
