                Button("Play")
                  .width(60)
                  .height(30)
                  .onClick(() => {
                    this.audioProgress = 0;
                    this.simulateAudioPlayback();
                  });

                Slider({
                  value: this.audioProgress,
                  min: 0,
                  max: 100,
                  step: 1,
                  style: SliderStyle.OutSet
                })
                  .width('70%')
                  .height(30)
                  .onChange((value: number) => {
                    this.audioProgress = value;
                  });
              }
              .width('100%')
              .margin({ top: 10 });
            }
            .width('100%')
            .padding(10)
            .borderRadius(8)
            .backgroundColor('#F5F5F5')
            .margin({ top: 10 });
          }
        });
      }
      .layoutWeight(1)
      .width('100%')
      .padding(10);

      Row() {
        Button("Add Post")
          .width('100%')
          .height(50)
          .fontSize(18)
          .backgroundColor('#007AFF')
          .onClick(async () => {
            try {
              const result = await promptAction.showDialog({
                title: "Add New Post",
                message: "Enter your post content:",
                buttons: [
                  { text: "Post", color: "#007AFF" },
                  { text: "Cancel", color: "#FF0000" }
                ]
              });

              if (result.index === 0) {
                this.posts.push("New Post: " + this.newPostContent);
                this.newPostContent = "";
              }
            } catch (error) {
              console.error("Dialog error: " + error);
            }
          });
      }
      .width('100%')
      .padding(10);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }

  simulateAudioPlayback() {
    let interval = setInterval(() => {
      if (this.audioProgress < 100) {
        this.audioProgress += 1;
      } else {
        clearInterval(interval);
      }
    }, 100);
  }
}

@Entry
@Component
struct CountdownTimer {
  @State timeLeft: number = 60;
  @State isRunning: boolean = false;
  @State showMarquee: boolean = false;
  @State userRating: number = 0;
  private timerId: number = -1;

  startTimer() {
    if (!this.isRunning) {
      this.isRunning = true;
      this.timerId = setInterval(() => {
        if (this.timeLeft > 0) {
          this.timeLeft -= 1;
          if (this.timeLeft <= 10) {
            this.showMarquee = true;
          }
        } else {
          this.stopTimer();
        }
      }, 1000);
    }
  }

  stopTimer() {
    this.isRunning = false;
    clearInterval(this.timerId);
  }

  resetTimer() {
    this.stopTimer();
    this.timeLeft = 60;
    this.showMarquee = false;
  }

  saveRating() {
    console.log(`Rating saved: ${this.userRating}`);
  }

  loadRating() {
    console.log("Rating loaded");
  }

  aboutToAppear() {
    this.loadRating();
  }

  build() {
    Column({ space: 20 }) {
      Text(`${this.timeLeft} seconds`)
        .fontSize(30)
        .fontWeight(FontWeight.Bold)
        .fontColor(Color.Black)
        .margin(10);

      if (this.showMarquee) {
        Text("Time is running out!")
          .fontSize(20)
          .fontColor(Color.Red)
          .margin(10);
      }

      Row({ space: 20 }) {
        Button(this.isRunning ? "Stop" : "Start")
          .onClick(() => {
            if (this.isRunning) {
              this.stopTimer();
            } else {
              this.startTimer();
            }
          })
          .backgroundColor(this.isRunning ? Color.Red : Color.Green)
          .fontColor(Color.White)
          .padding(10);

        Button("Reset")
          .onClick(() => {
            this.resetTimer();
          })
          .backgroundColor(Color.Blue)
          .fontColor(Color.White)
          .padding(10);
      }
      .justifyContent(FlexAlign.Center);

      Text("Rate the app:")
        .fontSize(20)
        .margin(10);

      Row({ space: 10 }) {
        ForEach([1, 2, 3, 4, 5], (star: number) => {
          Text(this.userRating >= star ? "★" : "☆")
            .fontSize(30)
            .fontColor(this.userRating >= star ? Color.Yellow : Color.Gray)
            .onClick(() => {
              this.userRating = star;
              this.saveRating();
            });
        });
      }
      .justifyContent(FlexAlign.Center);
    }
    .width("100%")
    .height("100%")
    .justifyContent(FlexAlign.Center)
    .backgroundColor(Color.White);
  }
}

@Entry
@Component
struct ProjectManagementQuizApp {
  @State searchText: string = '';
  @State selectedFilter: string = 'All';
  @State items: string[] = ['Project A', 'Project B', 'Project C', 'Task 1', 'Task 2', 'Task 3'];

  filteredItems(): string[] {
    return this.items.filter(item => {
      const matchesSearch = item.toLowerCase().includes(this.searchText.toLowerCase());
      const matchesFilter = this.selectedFilter === 'All' || item.startsWith(this.selectedFilter);
      return matchesSearch && matchesFilter;
    });
  }

  build() {
    Column() {
      TextInput({ placeholder: 'Search...', text: this.searchText })
        .onChange((value: string) => {
          this.searchText = value;
        })
        .width('100%')
        .margin(16)
        .backgroundColor(0xF0F0F0)
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      Row() {
        Text('Filter:')
          .fontSize(16)
          .margin({ right: 8 });
        Select([
          { value: 'All' },
          { value: 'Project' },
          { value: 'Task' }
        ])
          .selected(this.selectedFilter === 'All' ? 0 : this.selectedFilter === 'Project' ? 1 : 2)
          .onSelect((index: number) => {
            const options = ['All', 'Project', 'Task'];
            this.selectedFilter = options[index];
          })
          .width(150);
      }
      .margin(16);

      if (this.filteredItems().length > 0) {
        List() {
          ForEach(this.filteredItems(), (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(18)
                .padding(12);
            }
          }, (item: string) => item);
        }
      } else {
        Text('No items found')
          .fontSize(16)
          .fontColor(0x808080)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(0xFFFFFF);
  }
}

import promptAction from '@ohos.promptAction';

interface Message {
  text: string;
  isUser: boolean;
}

@Entry
@Component
struct ChatApp {
  @State messages: Array<Message> = [];
  @State inputText: string = '';
  @State showDialog: boolean = false;
  @State dialogMessage: string = '';
  @State abTestVariant: string = Math.random() > 0.5 ? 'A' : 'B';

  build() {
    Column() {
      // Chat Messages Display
      List({ space: 10 }) {
        ForEach(this.messages, (message: Message) => {
          ListItem() {
            Column() {
              Text(message.text)
                .fontSize(16)
                .padding(10)
                .backgroundColor(message.isUser ? '#007AFF' : '#f5f5f5')
                .borderRadius(10)
                .align(Alignment.Start)
                .margin({ left: message.isUser ? '50%' : '0%', right: message.isUser ? '0%' : '50%' })
            }
          }
        })
      }
      .layoutWeight(1)
      .width('100%')
      .padding(10)

      // Input Area
      Row() {
        TextInput({ placeholder: 'Type a message...' })
          .width('80%')
          .height(40)
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.inputText = value;
          })

        Button('Send')
          .width('20%')
          .height(40)
          .fontSize(16)
          .backgroundColor('#007AFF')
          .onClick(() => {
            if (this.inputText.trim()) {
              this.messages.push({ text: this.inputText, isUser: true });
              this.inputText = '';
              // Simulate a response
              setTimeout(() => {
                this.messages.push({ text: 'This is a response.', isUser: false });
                // A/B Testing Logic
                if (this.abTestVariant === 'A') {
                  this.dialogMessage = 'Thank you for your message! (Variant A)';
                } else {
                  this.dialogMessage = 'We appreciate your feedback! (Variant B)';
                }
                this.showDialog = true;
              }, 1000);
            } else {
              promptAction.showToast({
                message: 'Please enter a message'
              });
            }
          })
      }
      .width('100%')
      .padding(10)

      // Dialog for A/B Testing
      if (this.showDialog) {
        Column() {
          Text(this.dialogMessage)
            .fontSize(18)
            .margin(10)
          Button('OK')
            .onClick(() => {
              this.showDialog = false;
            })
            .margin(10)
        }
        .width('80%')
        .backgroundColor('#FFFFFF')
        .borderRadius(10)
        .padding(10)
        .align(Alignment.Center)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

@Entry
@Component
struct MultiTabInterface {
  @State private currentIndex: number = 0;
  @State count: number = 0;
  private tabsController: TabsController = new TabsController();

  @Builder
  TabBuilder(index: number, label: string) {
    Button(label)
      .width('100%')
      .height(50)
      .fontColor(this.currentIndex === index ? '#007DFF' : '#6B6B6B')
      .fontSize(16)
      .fontWeight(this.currentIndex === index ? 500 : 400)
      .backgroundColor('#F1F3F5')
      .onClick(() => {
        this.currentIndex = index;
        this.tabsController.changeIndex(index);
      });
  }

  @Builder
  CounterComponent(count: number) {
    Column() {
      Text(`Count: ${count}`)
        .fontSize(24)
        .margin(10);

      Row() {
        Button('Increment')
          .onClick(() => {
            this.count++;
          });
        Button('Decrement')
          .onClick(() => {
            this.count--;
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly);
    }
  }

  @Builder
  TagComponent() {
    Column() {
      Text('Tag Content')
        .fontSize(20)
        .textAlign(TextAlign.Center)
        .backgroundColor('#FFCCCC')
        .padding(10);
    }
  }

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.Start, controller: this.tabsController }) {
        TabContent() {
          this.CounterComponent(this.count);
        }.tabBar(this.TabBuilder(0, 'Counter'));

        TabContent() {
          this.TagComponent();
        }.tabBar(this.TabBuilder(1, 'Tag'));

        TabContent() {
          Column() {
            Text('Additional Content')
              .fontSize(20)
              .textAlign(TextAlign.Center)
              .backgroundColor('#CCFFCC')
              .padding(10);
          }
        }.tabBar(this.TabBuilder(2, 'Extra'));
      }
      .vertical(false)
      .barMode(BarMode.Fixed)
      .barWidth('100%')
      .barHeight(56)
      .animationDuration(400)
      .onChange((index: number) => {
        this.currentIndex = index;
      })
      .width('100%')
      .margin({ top: 10 })
      .backgroundColor('#FFFFFF');
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

