struct InventoryManagement {
  @State private selectedDate: string = '';
  @State private fruits: InventoryItem[] = [
    new InventoryItem(1, "Apple", 50, "2024-03-01"),
    new InventoryItem(2, "Banana", 30, "2024-02-28"),
    new InventoryItem(3, "Orange", 40, "2024-03-05")
  ];

  build() {
    Column() {
      Tabs() {
        TabContent() {
          List({ space: 10 }) {
            ForEach(this.fruits, (item: InventoryItem) => {
              ListItem() {
                Row() {
                  Column() {
                    Text(item.name)
                      .fontSize(16)
                    Text(`Quantity: ${item.quantity}`)
                      .fontSize(14)
                    Text(`Expires: ${item.expirationDate}`)
                      .fontSize(12)
                  }
                  Button('Update')
                    .onClick(() => {
                      this.updateQuantity(item);
                    })
                    .margin({ left: 10 })
                }
                .padding(10)
                .justifyContent(FlexAlign.SpaceBetween)
              }
            })
          }
        }
        .tabBar('Fruits')
      }

      DatePicker()
        .onDateChange((value: Date) => {
          const year = value.getFullYear();
          const month = value.getMonth() + 1;
          const day = value.getDate();
          this.selectedDate = `${year}-${month}-${day}`;
        })
        .margin({ top: 20 })

      Text(`Selected Date: ${this.selectedDate}`)
        .fontSize(16)
        .margin({ top: 10 })
    }
    .padding(20)
  }

  updateQuantity(item: InventoryItem) {
    item.quantity += 10;
  }
}

