@Entry
@Component
struct FilePickerSimulation {
  @State private currentStep: number = 0
  private totalSteps: number = 3
  private stepTitles: string[] = ["Select File", "Review Details", "Complete"]
  private fileContent: string = "Sample News Article Content"

  @Builder
  StepContent(step: number) {
    Column() {
      Text(this.stepTitles[step])
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      if (step === 0) {
        Text("[Placeholder Image]")
          .fontSize(16)
          .fontColor(Color.Gray)
          .width(100)
          .height(100)
          .textAlign(TextAlign.Center)
          .margin({ bottom: 20 })
        Text("Click Next to select file")
      } else if (step === 1) {
        Text("File Content Preview:")
          .fontSize(18)
          .margin({ bottom: 10 })
        Text(this.fileContent)
          .fontSize(14)
          .fontColor(Color.Gray)
      } else {
        Text("File processing complete!")
          .fontSize(18)
          .margin({ bottom: 20 })
        Text("[Placeholder Image]")
          .fontSize(16)
          .fontColor(Color.Gray)
          .width(100)
          .height(100)
          .textAlign(TextAlign.Center)
      }

      if (step < this.totalSteps - 1) {
        Divider()
          .strokeWidth(2)
          .color(Color.Gray)
          .margin({ top: 30, bottom: 30 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }

  build() {
    Column() {
      this.StepContent(this.currentStep)

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentStep > 0) {
              this.currentStep--
            }
          })
          .margin({ right: 20 })
          .enabled(this.currentStep > 0)

        Button('Next')
          .onClick(() => {
            if (this.currentStep < this.totalSteps - 1) {
              this.currentStep++
            }
          })
          .enabled(this.currentStep < this.totalSteps - 1)
      }
      .margin({ top: 50 })
    }
    .width('100%')
    .height('100%')
  }
}

