@Entry
@Component
struct IndexPage {
  @State currentPage: number = 1
  @State itemsPerPage: number = 10
  @State allItems: number[] = Array.from({length: 100}, (_: number) => _ + 1)
  @State visibleItems: number[] = []

  aboutToAppear() {
    this.loadMoreItems()
  }

  loadMoreItems() {
    const startIndex = (this.currentPage - 1) * this.itemsPerPage
    const endIndex = startIndex + this.itemsPerPage
    const newItems = this.allItems.slice(startIndex, endIndex)
    this.visibleItems = this.visibleItems.concat(newItems)
    this.currentPage++
  }

  build() {
    Column() {
      List() {
        ForEach(this.visibleItems, (item: number) => {
          ListItem() {
            Text(`Item ${item}`)
              .fontSize(18)
              .margin(10)
          }
        })
      }
      .onReachEnd(() => {
        this.loadMoreItems()
      })
      .width('100%')
      .height('80%')
    }
    .width('100%')
    .height('100%')
  }
}

