import webview from '@ohos.web.webview';
import { BusinessError } from '@ohos.base';

@Entry
@Component
struct PodcastPlayer {
  private podcastList: Array<PodcastItem> = [
    { title: 'Episode 1: Introduction', url: 'https://example.com/episode1.mp3' },
    { title: 'Episode 2: Deep Dive', url: 'https://example.com/episode2.mp3' },
    { title: 'Episode 3: Q&A', url: 'https://example.com/episode3.mp3' }
  ];

  @State currentEpisode: PodcastItem | null = null;
  @State isPlaying: boolean = false;
  @State progress: number = 0;
  private intervalId: number | null = null;
  private webViewRef: webview.WebviewController = new webview.WebviewController();

  build() {
    Column() {
      Web({ src: '', controller: this.webViewRef })
        .visibility(Visibility.None)

      List({ space: 10 }) {
        ForEach(this.podcastList, (item: PodcastItem) => {
          ListItem() {
            Column() {
              Text(item.title).fontSize(18).fontWeight(500);
              Text(item.url).fontSize(14).fontColor('#999');
            }
            .onClick(() => {
              this.currentEpisode = item;
              this.playEpisode(item.url);
            });
          }
        });
      }
      .layoutWeight(1);

      Row() {
        Button(this.isPlaying ? 'Pause' : 'Play')
          .onClick(() => {
            if (this.isPlaying) {
              this.pausePlayback();
            } else {
              this.resumePlayback();
            }
          });
        Slider({
          value: this.progress,
          min: 0,
          max: 100,
          step: 1
        })
          .onChange((value: number) => {
            this.seekPlayback(value);
          });
      }
      .width('100%')
      .padding(10);
    }
    .width('100%')
    .height('100%');
  }

  private playEpisode(url: string) {
    try {
      this.webViewRef.loadUrl(url);
      this.isPlaying = true;
      this.startProgressTracking();
    } catch (error) {
      console.error('Error loading URL:', (error as BusinessError).message);
    }
  }

  private pausePlayback() {
    this.isPlaying = false;
    this.clearProgressTracking();
  }

  private resumePlayback() {
    this.isPlaying = true;
    this.startProgressTracking();
  }

  private seekPlayback(value: number) {
    this.progress = value;
  }

  private startProgressTracking() {
    this.intervalId = setInterval(() => {
      this.progress = (this.progress + 1) % 100;
    }, 1000);
  }

  private clearProgressTracking() {
    if (this.intervalId !== null) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
  }

  onDestroy() {
    this.clearProgressTracking();
  }
}

