@Entry
@Component
struct StepperFormApp {
  @State currentStep: number = 0
  @State videoTitle: string = ''
  @State videoDescription: string = ''
  @State videoUrl: string = ''

  validateStep1(): boolean {
    return this.videoTitle.trim().length > 0 && this.videoDescription.trim().length > 0
  }

  validateStep2(): boolean {
    const urlPattern = /^(https?:\/\/)?([\da-z\.-]+)\.([a-z\.]{2,6})([\/\w \.-]*)*\/?$/
    return urlPattern.test(this.videoUrl)
  }

  build() {
    Column() {
      Stepper({
        index: this.currentStep
      }) {
        StepperItem() {
          Column() {
            TextInput({ placeholder: 'Enter video title' })
              .onChange((value: string) => {
                this.videoTitle = value
              })
            TextInput({ placeholder: 'Enter video description' })
              .onChange((value: string) => {
                this.videoDescription = value
              })
          }
        }
        StepperItem() {
          Column() {
            TextInput({ placeholder: 'Enter video URL' })
              .onChange((value: string) => {
                this.videoUrl = value
              })
          }
        }
      }

      Row() {
        Button('Back')
          .enabled(this.currentStep !== 0)
          .onClick(() => {
            if (this.currentStep > 0) {
              this.currentStep -= 1
            }
          })

        Button(this.currentStep === 1 ? 'Submit' : 'Next')
          .enabled(
            this.currentStep === 0 ? this.validateStep1() : this.validateStep2()
          )
          .onClick(() => {
            if (this.currentStep < 1) {
              this.currentStep += 1
            } else {
              console.log('Form submitted')
            }
          })
      }
    }
    .padding(20)
  }
}

