import util from '@ohos.util';

interface TimePickerResult {
    hour: number;
    minute: number;
    second: number;
}

@Entry
@Component
struct TimePickerEncryption {
    @State private selectedTime: Date = new Date();
    @State private stepperValue: number = 1;
    @State private encryptedData: string = '';

    private async encryptData(data: string, key: number): Promise<string> {
        let textEncoder = new util.TextEncoder();
        let uint8Array = await textEncoder.encodeInto(data);
        let base64Encoder = new util.Base64Helper();
        return base64Encoder.encodeToString(uint8Array);
    }

    build() {
        Column({ space: 20 }) {
            TimePicker({ selected: this.selectedTime })
                .onChange((value: TimePickerResult) => {
                    const now = new Date();
                    this.selectedTime = new Date(now.getFullYear(), now.getMonth(), now.getDate(), value.hour, value.minute, value.second);
                })
                .margin({ bottom: 20 })

            Stepper({ index: this.stepperValue })
                .onChange((value: number) => {
                    this.stepperValue = value;
                })
                .margin({ bottom: 20 })

            Button('Encrypt Time')
                .onClick(async () => {
                    const timeString = this.selectedTime.toLocaleTimeString();
                    this.encryptedData = await this.encryptData(timeString, this.stepperValue);
                })
                .margin({ bottom: 20 })

            if (this.encryptedData !== '') {
                Text('Encrypted Data: ' + this.encryptedData)
                    .fontSize(16)
                    .fontColor(Color.Black)
                    .margin({ bottom: 20 })
            }
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .padding(20)
    }
}

@Entry
@Component
struct PDFViewer {
  @State imageScale: Scale = { x: 1.0, y: 1.0 }
  @State lastImageScale: Scale = { x: 1.0, y: 1.0 }
  @State offsetX: number = 0
  @State offsetY: number = 0
  @State initialDistance: number = 0
  @State showToast: boolean = false
  @State toastMessage: string = ""

  private readonly PDF_RESOURCE = $r('app.media.icon')

  private showFeedback = (message: string) => {
    this.showToast = true
    this.toastMessage = message
    setTimeout(() => {
      this.showToast = false
    }, 2000)
  }

  build() {
    Stack() {
      Image(this.PDF_RESOURCE)
        .objectFit(ImageFit.Contain)
        .width('100%')
        .height('100%')
        .scale({ x: this.imageScale.x, y: this.imageScale.y })
        .translate({ x: this.offsetX, y: this.offsetY })
        .gesture(
          GestureGroup(GestureMode.Parallel,
            PinchGesture({ fingers: 2 })
            .onActionStart((event: PinchGestureEvent) => {
              this.initialDistance = event.scale
            })
            .onActionUpdate((event: PinchGestureEvent) => {
              const scaleFactor = event.scale
              const newScale = Math.min(Math.max(this.lastImageScale.x * scaleFactor, 0.5), 3)
              this.imageScale = { x: newScale, y: newScale }
            })
            .onActionEnd(() => {
              this.lastImageScale = this.imageScale
              this.showFeedback("Zoom: " + this.imageScale.x.toFixed(1) + "x")
            }),
            PanGesture()
            .onActionUpdate((event: PanGestureEvent) => {
              if (this.imageScale.x > 1) {
                this.offsetX = Math.min(Math.max(this.offsetX + event.offsetX, -100 * (this.imageScale.x - 1)), 100 * (this.imageScale.x - 1))
                this.offsetY = Math.min(Math.max(this.offsetY + event.offsetY, -100 * (this.imageScale.x - 1)), 100 * (this.imageScale.x - 1))
                this.showFeedback("Pan: X=" + this.offsetX.toFixed(0) + ", Y=" + this.offsetY.toFixed(0))
              }
            }),
            TapGesture()
            .onAction(() => {
              this.showFeedback("Tapped")
            })
          )
        )

      if (this.showToast) {
        Text(this.toastMessage)
          .fontSize(16)
          .backgroundColor('#333333')
          .padding(10)
          .borderRadius(5)
          .position({ x: '50%', y: '80%' })
          .translate({ x: -50, y: -20 })
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f0f0f0')
  }
}

interface Scale {
  x: number;
  y: number;
}

@Entry
@Component
struct GestureTextInput {
  @State private text: string = ''
  @State private isPressed: boolean = false

  build() {
    Column() {
      TextInput({ placeholder: 'Type here' })
        .width('80%')
        .height(50)
        .backgroundColor(this.isPressed ? Color.Gray : Color.White)
        .border({ width: 1, color: Color.Black })
        .gesture(
          TapGesture()
            .onAction(() => {
              this.isPressed = true
              setTimeout(() => {
                this.isPressed = false
              }, 100)
            })
        )
        .onChange((value: string) => {
