@Entry
@Component
struct PodcastPlayer {
  @State email: string = ''
  @State isEmailValid: boolean = true
  @State emailError: string = ''

  @State password: string = ''
  @State isPasswordValid: boolean = true
  @State passwordError: string = ''

  @State badgeValue: number = 5

  validateEmail(email: string): string | null {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return emailRegex.test(email) ? null : 'Please enter a valid email'
  }

  validatePassword(password: string): string | null {
    return password.length >= 6 ? null : 'Password must be at least 6 characters'
  }

  build() {
    Column({ space: 20 }) {
      // Badge for notifications
      Stack() {
        Image($r("app.media.app_icon"))
          .width(40)
          .height(40)

        if (this.badgeValue > 0) {
          Text(this.badgeValue.toString())
            .fontSize(12)
            .fontColor(Color.White)
            .backgroundColor(Color.Red)
            .borderRadius(10)
            .padding(5)
            .margin({ top: -10, right: -10 })
        }
      }

      // Form for login
      TextInput({ placeholder: 'Email' })
        .width('100%')
        .onChange((value: string) => {
          this.email = value
          const error = this.validateEmail(value)
          this.emailError = error || ''
          this.isEmailValid = !error
        })
        .border({
          width: 1,
          color: this.isEmailValid ? '#ddd' : '#ff0000'
        })

      if (this.emailError) {
        Text(this.emailError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      TextInput({ placeholder: 'Password' })
        .width('100%')
        .onChange((value: string) => {
          this.password = value
          const error = this.validatePassword(value)
          this.passwordError = error || ''
          this.isPasswordValid = !error
        })
        .border({
          width: 1,
          color: this.isPasswordValid ? '#ddd' : '#ff0000'
        })

      if (this.passwordError) {
        Text(this.passwordError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      Button('Submit')
        .enabled(this.isEmailValid && this.isPasswordValid)
        .onClick(() => {
          console.info('Form submitted')
        })
    }
    .padding(20)
    .width('100%')
  }
}

