      win.on('windowSizeChange', (data: window.Size) => {
        this.isPortrait = data.width < data.height;
      });
    });
  }

  build() {
    Column() {
      Flex({ direction: FlexDirection.Row, alignItems: ItemAlign.Center, justifyContent: FlexAlign.SpaceBetween }) {
        if (this.showBackButton) {
