            .margin({ left: 10 })
            .onClick(() => {
              router.back();
            });
        }
        Text(this.pageTitle)
          .fontSize(20)
          .fontColor(Color.Black)
          .layoutWeight(1)
          .textAlign(TextAlign.Center);
        Text('...')
          .width(30)
          .height(30)
          .margin({ right: 10 })
          .onClick(() => {
            console.info('Actionable icon clicked');
          });
      }
      .width('100%')
      .height(60)
      .backgroundColor(Color.White)
      .zIndex(99);

      Column() {
        if (this.isPortrait) {
          Column() {
            Row() {
              Button('-')
                .onClick(() => {
                  this.counterValue--;
                });
              Text(this.counterValue.toString())
                .fontSize(20);
              Button('+')
