                .fontSize(16);
              Slider({
                value: this.sliderValue,
                min: 0,
                max: 100,
                step: 1,
                style: SliderStyle.OutSet
              })
                .onChange((value: number) => {
                  this.sliderValue = value;
                });
              Text('100')
                .fontSize(16);
            }
            .margin({ top: 20 });
          }
          .width('100%');
        } else {
          Row() {
            Column() {
              Button('-')
                .onClick(() => {
                  this.counterValue--;
                });
              Text(this.counterValue.toString())
                .fontSize(20);
              Button('+')
                .onClick(() => {
                  this.counterValue++;
                });
            }
            .margin({ left: 20 });

            Column() {
              Text('0')
                .fontSize(16);
              Slider({
                value: this.sliderValue,
                min: 0,
                max: 100,
                step: 1,
                style: SliderStyle.OutSet
              })
                .onChange((value: number) => {
                  this.sliderValue = value;
                });
              Text('100')
                .fontSize(16);
            }
            .margin({ left: 20 });
          }
          .width('100%');
        }
      }
      .width('100%')
      .height('100%')
      .backgroundColor(Color.White);
    }
    .width('100%')
