@Entry
@Component
struct FileManagerList {
  @State items: string[] = ['File 1', 'File 2', 'File 3', 'File 4', 'File 5'];
  @State draggingIndex: number = -1;
  @State offsetY: number = 0;
  @State deviceType: string = 'Phone';
  @State isFeatureEnabled: boolean = false;

  handleDragStart(index: number, event: TouchEvent) {
    this.draggingIndex = index;
    this.offsetY = event.touches[0].y;
  }

  handleDragMove(event: TouchEvent) {
    if (this.draggingIndex === -1) return;
    const newY = event.touches[0].y;
    const deltaY = newY - this.offsetY;
    this.offsetY = newY;

    const newIndex = this.calculateNewIndex(deltaY);
    if (newIndex !== -1) {
      this.reorderItems(this.draggingIndex, newIndex);
      this.draggingIndex = newIndex;
    }
  }

  handleDragEnd() {
    this.draggingIndex = -1;
  }

  calculateNewIndex(deltaY: number): number {
    const dragItemHeight = 60;
    const threshold = dragItemHeight / 2;
    const newIndex = this.draggingIndex + Math.round(deltaY / threshold);

    if (newIndex < 0 || newIndex >= this.items.length) {
      return -1;
    }

    return newIndex;
  }

  reorderItems(fromIndex: number, toIndex: number) {
    const item = this.items[fromIndex];
    this.items.splice(fromIndex, 1);
    this.items.splice(toIndex, 0, item);
  }

  build() {
    Column() {
      Row() {
        Text('Device Type:').fontSize(16).margin({ right: 10 });
        // Simulate SegmentedControl with buttons
        Row() {
          Button('Phone')
            .backgroundColor(this.deviceType === 'Phone' ? '#007AFF' : '#E0E0E0')
            .onClick(() => { this.deviceType = 'Phone'; });
          Button('Tablet')
            .backgroundColor(this.deviceType === 'Tablet' ? '#007AFF' : '#E0E0E0')
            .onClick(() => { this.deviceType = 'Tablet'; });
          Button('Desktop')
            .backgroundColor(this.deviceType === 'Desktop' ? '#007AFF' : '#E0E0E0')
            .onClick(() => { this.deviceType = 'Desktop'; });
        }
      }
      .width('100%')
      .padding(10)

      Row() {
        Text('Enable Feature:').fontSize(16).margin({ right: 10 });
        // Simulate Switch with a Toggle
        Toggle({ type: ToggleType.Switch, isOn: this.isFeatureEnabled })
          .onChange((isOn: boolean) => { this.isFeatureEnabled = isOn; });
      }
      .width('100%')
      .padding(10)

      List() {
        ForEach(this.items, (item: string, index: number) => {
          ListItem() {
            Row() {
              Image($r('app.media.app_icon'))
                .width(40)
                .height(40)
                .margin(10)
              Text(item)
                .fontSize(18)
                .fontWeight(FontWeight.Medium)
                .margin(10)
            }
            .width('100%')
            .height(60)
            .backgroundColor(this.draggingIndex === index ? '#e0e0e0' : '#f5f5f5')
            .borderRadius(5)
            .onTouch((event: TouchEvent) => {
              if (event.type === TouchType.Down) {
                this.handleDragStart(index, event);
              } else if (event.type === TouchType.Move) {
                this.handleDragMove(event);
              } else if (event.type === TouchType.Up) {
                this.handleDragEnd();
              }
            })
          }
        })
      }
      .width('100%')
      .height('100%')
      .divider({ strokeWidth: 1, color: '#cccccc' })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff')
    .padding(10)
  }
}

