@Component
struct LoginScreen {
  @State username: string = ''
  @State password: string = ''
  @State isLoggedIn: boolean = false
  @State errorMessage: string = ''

  build() {
    Column() {
      if (!this.isLoggedIn) {
        Text('Username')
          .fontSize(18)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 10 })

        TextInput({ placeholder: 'Enter your username', text: this.username })
          .onChange((value: string) => {
            this.username = value
          })
          .width('80%')
          .margin({ bottom: 20 })

        Text('Password')
          .fontSize(18)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 10 })

        TextInput({ placeholder: 'Enter your password', text: this.password })
          .type(InputType.Password)
          .onChange((value: string) => {
            this.password = value
          })
          .width('80%')
          .margin({ bottom: 20 })

        Button('Login')
          .onClick(() => {
            if (this.username === 'admin' && this.password === 'password') {
              this.isLoggedIn = true
              this.errorMessage = ''
            } else {
              this.errorMessage = 'Invalid username or password'
            }
          })
          .width('60%')
          .backgroundColor('#4CAF50')
          .fontSize(18)
          .fontColor(Color.White)

        if (this.errorMessage) {
          Text(this.errorMessage)
            .fontSize(16)
            .margin({ top: 20 })
            .fontColor(Color.Red)
        }
      } else {
        Text(`Welcome, ${this.username}!`)
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 })

        Text('Map Placeholder Image Here')
          .width('90%')
          .height(300)
          .margin({ bottom: 20 })
          .textAlign(TextAlign.Center)
          .border({ width: 1, color: Color.Gray })

        Button('Logout')
          .onClick(() => {
            this.isLoggedIn = false
            this.username = ''
            this.password = ''
          })
          .width('60%')
          .backgroundColor('#F44336')
          .fontSize(18)
          .fontColor(Color.White)
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

interface Message {
  text: string;
  isUser: boolean;
  hasMap: boolean;
  hasAudio: boolean;
}

@Entry
@Component
struct MessagingApp {
  @State cachedMessages: Array<Message> = [];
  @State inputText: string = '';
  @State showCache: boolean = true;

  build() {
    Column({ space: 20 }) {
      Button(this.showCache ? 'Hide Cache' : 'Show Cache')
        .onClick(() => {
          this.showCache = !this.showCache;
        })
        .width('80%')
        .height(40)
        .margin(10);

      if (this.showCache) {
        List({ space: 10 }) {
          ForEach(this.cachedMessages, (message: Message) => {
            ListItem() {
              Column({ space: 10 }) {
                Text(message.text)
                  .fontSize(16)
                  .padding(10)
                  .backgroundColor(message.isUser ? '#007AFF' : '#f5f5f5')
                  .borderRadius(10);

                if (message.hasMap) {
                  Text('[Map Placeholder]')
                    .width(200)
                    .height(150)
                    .backgroundColor('#cccccc')
                    .textAlign(TextAlign.Center);
                }

                if (message.hasAudio) {
                  Button('Play Audio')
                    .width(120)
                    .height(40)
                    .onClick(() => {
                    });
                }
              }
            }
          })
        }
        .height('50%')
        .width('100%')
        .divider({ strokeWidth: 1, color: 0xcccccc });
      }

      TextInput({ placeholder: 'Type a message...' })
        .onChange((value: string) => {
          this.inputText = value;
        })
        .width('80%')
        .margin(10);

      Row({ space: 10 }) {
        Button('Add Map')
          .width('30%')
          .height(40)
          .onClick(() => {
            if (this.inputText.trim()) {
              this.cachedMessages.push({
                text: this.inputText,
                isUser: true,
                hasMap: true,
                hasAudio: false
              } as Message);
              this.inputText = '';
            }
          });

        Button('Add Audio')
          .width('30%')
          .height(40)
          .onClick(() => {
            if (this.inputText.trim()) {
              this.cachedMessages.push({
                text: this.inputText,
                isUser: true,
                hasMap: false,
                hasAudio: true
              } as Message);
              this.inputText = '';
            }
          });

        Button('Send')
          .width('30%')
          .height(40)
          .onClick(() => {
            if (this.inputText.trim()) {
              this.cachedMessages.push({
                text: this.inputText,
                isUser: true,
                hasMap: false,
                hasAudio: false
              } as Message);
              this.inputText = '';
            }
          });
      }
      .width('80%')
      .margin(10);

      Button('Clear Cache')
        .onClick(() => {
          this.cachedMessages = [];
        })
        .width('80%')
        .height(40)
        .margin(10)
        .backgroundColor(Color.Red)
        .fontColor(Color.White);
    }
    .width('100%')
    .height('100%')
    .padding(10);
  }
}

import promptAction from '@ohos.promptAction';

interface Message {
  id: string;
  text: string;
  isUser: boolean;
}

@Entry
@Component
struct MessagingApp {
  @State messages: Array<Message> = [
    { id: '1', text: 'Hello!', isUser: false },
    { id: '2', text: 'Hi there!', isUser: true },
    { id: '3', text: 'How are you?', isUser: false },
    { id: '4', text: 'I am good, thanks!', isUser: true }
  ];
  @State inputText: string = '';

  build() {
    Column() {
      Grid() {
        ForEach(this.messages, (message: Message) => {
          GridItem() {
            Column() {
              Text(message.text)
                .fontSize(16)
                .padding(10)
                .backgroundColor(message.isUser ? '#007AFF' : '#f5f5f5')
                .borderRadius(10)
                .textAlign(TextAlign.Center)
                .width('100%')
            }
            .width('100%')
            .margin(5)
          }
        }, (message: Message) => message.id)
      }
      .columnsTemplate('1fr 1fr')
      .rowsGap(10)
      .columnsGap(10)
      .padding(10)
      .layoutWeight(1)

      Row() {
        TextInput({ placeholder: 'Type a message...', text: this.inputText })
          .width('80%')
          .height(40)
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.inputText = value;
          })

        Button('Send')
          .width('20%')
          .height(40)
          .fontSize(16)
          .backgroundColor('#007AFF')
          .onClick(() => {
            if (this.inputText.trim()) {
              this.messages = [...this.messages, { id: Date.now().toString(), text: this.inputText, isUser: true }];
              this.inputText = '';
              setTimeout(() => {
                this.messages = [...this.messages, { id: Date.now().toString(), text: 'Response received!', isUser: false }];
              }, 1000);
            } else {
              promptAction.showToast({
                message: 'Please enter a message'
              });
            }
          })
      }
      .width('100%')
      .padding(10)
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

@Entry
@Component
struct StopwatchABTesting {
  @State elapsedTime: number = 0
  @State isRunning: boolean = false
  private timerId: number = -1
  @State variant: string = 'A'

  build() {
    Column() {
      Text(`Variant: ${this.variant}`)
        .fontSize(20)
        .margin({ bottom: 10 })

      Text(`${this.elapsedTime} seconds`)
        .fontSize(30)
        .margin({ bottom: 20 })

      Row() {
        Button(this.isRunning ? 'Stop' : 'Start')
          .onClick(() => {
            if (this.isRunning) {
              clearInterval(this.timerId)
            } else {
              this.timerId = setInterval(() => {
                this.elapsedTime += 1
              }, 1000)
            }
            this.isRunning = !this.isRunning
          })
          .margin(10)

        Button('Reset')
          .onClick(() => {
            clearInterval(this.timerId)
            this.elapsedTime = 0
            this.isRunning = false
          })
          .margin(10)
      }

      Button('Switch Variant')
        .onClick(() => {
          this.variant = this.variant === 'A' ? 'B' : 'A'
        })
        .margin({ top: 20 })
    }
    .padding(20)
  }
}

@Entry
@Component
struct TimePickerWithRefresh {
  @State private isRefreshing: boolean = false;
  @State private currentTime: string = "12:00 PM";

  private handleRefresh() {
    this.isRefreshing = true;
    setTimeout(() => {
      this.isRefreshing = false;
      this.currentTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    }, 1000);
  }

  build() {
    Column({ space: 20 }) {
      Text("Pull to Refresh Time")
        .fontSize(20)
        .fontColor(Color.Black);

      Row()
        .width(300)
        .height(200)
        .backgroundColor(Color.Gray)
        .borderRadius(10)
        .gesture(
          PanGesture({ direction: PanDirection.Vertical })
            .onActionStart(() => {
              console.info('Swipe gesture started');
            })
            .onActionUpdate((event: GestureEvent) => {
              if (event.offsetY < -50 && !this.isRefreshing) {
                this.handleRefresh();
              }
            })
            .onActionEnd(() => {
              console.info('Swipe gesture ended');
            })
        );

      if (this.isRefreshing) {
        Text("Refreshing...")
          .fontSize(16)
          .fontColor(Color.Gray);
      } else {
        Text("Current Time: " + this.currentTime)
          .fontSize(18)
          .fontColor(Color.Black);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(Color.White);
  }
}

@Entry
@Component
struct RecipePhotoEditor {
  @State private currentStep: number = 0;
  private totalSteps: number = 3;
  @State private isCaching: boolean = false;
  @State private isSynced: boolean = false;

  @Builder
  StepContent(step: number) {
    Column() {
      Text(`Step ${step + 1}`)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Image($r('app.media.icon'))
        .width(200)
        .height(200)
        .margin({ bottom: 20 });

      Row() {
        Image($r('app.media.icon'))
          .width(24)
          .height(24)
          .margin({ right: 10 });

        Text(this.isSynced ? 'Synced' : 'Not Synced')
          .fontSize(16)
          .fontColor(this.isSynced ? Color.Green : Color.Red);
      }
      .margin({ bottom: 20 });

      if (this.isCaching) {
        Text('Caching in progress...')
          .fontSize(16)
          .fontColor(Color.Blue)
          .margin({ bottom: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }

  build() {
    Column() {
      Navigation() {
        this.StepContent(this.currentStep);
      }

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentStep > 0) {
              this.currentStep--;
            }
          })
          .margin({ right: 20 })
          .enabled(this.currentStep > 0);

        Button('Next')
          .onClick(() => {
            if (this.currentStep < this.totalSteps - 1) {
              this.currentStep++;
            }
          })
          .enabled(this.currentStep < this.totalSteps - 1);
      }
      .margin({ top: 50 });

      Row() {
        Button('Cache')
          .onClick(() => {
            this.isCaching = true;
            setTimeout(() => {
              this.isCaching = false;
            }, 2000);
          })
          .margin({ right: 20 });

        Button('Sync')
          .onClick(() => {
            this.isSynced = !this.isSynced;
          });
      }
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

@Entry
@Component
struct MarqueeApp {
  @State private currentIndex: number = 0;
  @State private marqueeText: string = "Welcome to the Marquee App";
  @State private isTapped: boolean = false;
  @State private swipeDirection: string = "None";

  private languages: string[] = ["en", "es", "fr"];
  private languageTexts: Record<string, string> = {
    "en": "Welcome to the Marquee App",
    "es": "Bienvenido a la aplicación Marquee",
    "fr": "Bienvenue dans l'application Marquee"
  };

  build() {
    Column({ space: 20 }) {
      // Marquee Text with Gestures
      Text(this.marqueeText)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .textAlign(TextAlign.Center)
        .margin({ top: 20 })
        .gesture(
          TapGesture({ count: 1 })
            .onAction(() => {
              this.isTapped = !this.isTapped;
              this.marqueeText = this.isTapped ? "Tapped!" : this.languageTexts[this.languages[this.currentIndex]];
            })
        )
        .gesture(
          SwipeGesture({ direction: SwipeDirection.Horizontal })
            .onAction(() => {
              this.currentIndex = (this.currentIndex + 1) % this.languages.length;
              this.marqueeText = this.languageTexts[this.languages[this.currentIndex]];
              this.swipeDirection = "Swipe Detected";
            })
        );

      // Navigation Tabs
      Tabs({ barPosition: BarPosition.End }) {
        TabContent() {
          Column() {
            Text("Home Screen")
              .fontSize(20)
              .margin({ top: 20 });
          }
          .width('100%')
          .height('100%')
        }
        .tabBar("Home")

        TabContent() {
          Column() {
            Text("Settings Screen")
              .fontSize(20)
              .margin({ top: 20 });
          }
          .width('100%')
          .height('100%')
        }
        .tabBar("Settings")
      }
      .width('100%')
      .height('80%')

      // TabBar for Navigation
      Row() {
        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 });
          Text("Home")
            .fontSize(12)
            .fontColor(this.currentIndex === 0 ? '#1698CE' : '#666666');
        }
        .width('50%')
        .onClick(() => {
          this.currentIndex = 0;
        });

        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 });
          Text("Settings")
            .fontSize(12)
            .fontColor(this.currentIndex === 1 ? '#1698CE' : '#666666');
        }
        .width('50%')
        .onClick(() => {
          this.currentIndex = 1;
        });
      }
      .width('100%')
      .height(60)
      .backgroundColor(Color.White)
      .border({ width: { top: 0.5 }, color: '#cccccc' });
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }
}

import { Tabs, TabContent, ToggleType, FlexAlign, Text, Button, Column, Row, List, ListItem, Toggle } from '@ohos.arkui.component';

@Entry
@Component
struct StopwatchApp {
  @State elapsedTime: number = 0;
  @State isRunning: boolean = false;
  @State lapTimes: Array<string> = [];
  @State showLaps: boolean = true;
  @State showMetrics: boolean = true;
  private timerId: number | null = null;

  aboutToAppear() {
    if (this.isRunning) {
      this.startTimer();
    }
  }

  private startTimer() {
    this.timerId = setInterval(() => {
      this.elapsedTime += 1;
    }, 10);
  }

  aboutToDisappear() {
    if (this.timerId !== null) {
      clearInterval(this.timerId);
    }
  }

  build() {
    Column() {
      Tabs() {
        TabContent('Stopwatch') {
          Column() {
            Text(this.formatTime(this.elapsedTime))
              .fontSize(40)
              .margin(20);

            Row() {
              Button(this.isRunning ? 'Stop' : 'Start')
                .onClick(() => {
                  if (this.isRunning) {
                    clearInterval(this.timerId);
                  } else {
                    this.startTimer();
                  }
                  this.isRunning = !this.isRunning;
                })
                .margin(10);

              Button('Lap')
                .onClick(() => {
                  this.lapTimes = [...this.lapTimes, this.formatTime(this.elapsedTime)];
                })
                .margin(10);

              Button('Reset')
                .onClick(() => {
                  clearInterval(this.timerId);
                  this.elapsedTime = 0;
                  this.isRunning = false;
                  this.lapTimes = [];
                })
                .margin(10);
            }
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center);
        }

        TabContent('Lap Times') {
          Column() {
            Toggle({ type: ToggleType.Switch, isOn: this.showLaps })
              .onChange((isOn: boolean) => {
                this.showLaps = isOn;
              })
              .margin(10);

            if (this.showLaps) {
              if (this.lapTimes.length === 0) {
                Text('No lap times recorded')
                  .fontSize(20)
                  .margin(20);
              } else {
                List() {
                  ForEach(this.lapTimes, (lap: string, index: number) => {
                    ListItem() {
                      Text(`Lap ${index + 1}: ${lap}`)
                        .fontSize(16)
                        .margin(10);
                    }
                  });
                }
                .width('100%')
                .height(300);
              }
            }
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center);
        }

        TabContent('Metrics') {
          Column() {
            Toggle({ type: ToggleType.Switch, isOn: this.showMetrics })
              .onChange((isOn: boolean) => {
                this.showMetrics = isOn;
              })
              .margin(10);

            if (this.showMetrics) {
              if (this.lapTimes.length === 0) {
                Text('No metrics available')
                  .fontSize(20)
                  .margin(20);
              } else {
                Text(`Fastest Lap: ${this.calculateFastestLap()}`)
                  .fontSize(16)
                  .margin(10);
                Text(`Slowest Lap: ${this.calculateSlowestLap()}`)
                  .fontSize(16)
                  .margin(10);
                Text(`Average Lap: ${this.calculateAverageLap()}`)
                  .fontSize(16)
                  .margin(10);
              }
            }
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center);
        }
      }
      .width('100%')
      .height('100%');
    }
    .width('100%')
    .height('100%');
  }

  private formatTime(time: number): string {
    const minutes = Math.floor(time / 6000);
    const seconds = Math.floor((time % 6000) / 100);
    const centiseconds = time % 100;
    return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}.${centiseconds.toString().padStart(2, '0')}`;
  }

  private calculateFastestLap(): string {
    if (this.lapTimes.length === 0) return 'N/A';
    return this.lapTimes.reduce((a, b) => (a < b ? a : b));
  }

  private calculateSlowestLap(): string {
    if (this.lapTimes.length === 0) return 'N/A';
    return this.lapTimes.reduce((a, b) => (a > b ? a : b));
  }

  private calculateAverageLap(): string {
    if (this.lapTimes.length === 0) return 'N/A';
    const total = this.lapTimes.reduce((sum, lap) => sum + this.parseTime(lap), 0);
    const average = total / this.lapTimes.length;
    return this.formatTime(average);
  }

  private parseTime(timeStr: string): number {
    const parts = timeStr.split(':');
    const minutes = parts[0];
    const rest = parts[1];
    const restParts = rest.split('.');
    const seconds = restParts[0];
    const centiseconds = restParts[1];
    return parseInt(minutes) * 6000 + parseInt(seconds) * 100 + parseInt(centiseconds);
  }
}

import { Column, Row, Text, TextInput, Button } from '@ohos.arkui.advanced';
import { FlexAlign, FontWeight, Color, InputType, HorizontalAlign } from '@ohos.arkui.common';
import router from '@ohos.router';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct EventPlannerApp {
  @State currentPage: number = 1;
  @State name: string = '';
  @State email: string = '';
  @State eventType: string = '';
  @State eventDate: string = '';
  @State guestCount: number = 0;
  @State emailError: string = '';
  @State dateError: string = '';
  @State guestError: string = '';

  validateEmail(): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(this.email)) {
      this.emailError = 'Invalid email format';
      return false;
    }
    this.emailError = '';
    return true;
  }

  validateDate(): boolean {
    const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
    if (!dateRegex.test(this.eventDate)) {
      this.dateError = 'Invalid date format (YYYY-MM-DD)';
      return false;
    }
    this.dateError = '';
    return true;
  }

  validateGuestCount(): boolean {
    if (this.guestCount <= 0) {
      this.guestError = 'Guest count must be positive';
      return false;
    }
    this.guestError = '';
    return true;
  }

  nextPage(): void {
    if (this.currentPage === 1 && (!this.name || !this.email || !this.validateEmail())) {
      promptAction.showToast({ message: 'Please fill all fields correctly' });
      return;
    }
    if (this.currentPage === 2 && (!this.eventType || !this.eventDate || !this.validateDate())) {
      promptAction.showToast({ message: 'Please fill all fields correctly' });
      return;
    }
    if (this.currentPage === 3 && (!this.guestCount || !this.validateGuestCount())) {
      promptAction.showToast({ message: 'Please fill all fields correctly' });
      return;
    }
    this.currentPage += 1;
  }

  prevPage(): void {
    this.currentPage -= 1;
  }

  submit(): void {
    promptAction.showToast({ message: 'Event submitted successfully!' });
    router.pushUrl({ url: 'pages/Home' });
  }

  build() {
    Column() {
      if (this.currentPage === 1) {
        Text('Personal Details')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 });

        Text('Name')
          .fontSize(18)
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Enter your name', text: this.name })
          .onChange((value: string) => {
            this.name = value;
          })
          .width('80%')
          .margin({ bottom: 20 });

        Text('Email')
          .fontSize(18)
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Enter your email', text: this.email })
          .onChange((value: string) => {
            this.email = value;
          })
          .width('80%')
          .margin({ bottom: 20 });

        if (this.emailError) {
          Text(this.emailError)
            .fontSize(14)
            .fontColor(Color.Red)
            .margin({ bottom: 10 });
        }
      } else if (this.currentPage === 2) {
        Text('Event Details')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 });

        Text('Event Type')
          .fontSize(18)
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Enter event type', text: this.eventType })
          .onChange((value: string) => {
            this.eventType = value;
          })
          .width('80%')
          .margin({ bottom: 20 });

        Text('Event Date (YYYY-MM-DD)')
          .fontSize(18)
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Enter event date', text: this.eventDate })
          .onChange((value: string) => {
            this.eventDate = value;
          })
          .width('80%')
          .margin({ bottom: 20 });

        if (this.dateError) {
          Text(this.dateError)
            .fontSize(14)
            .fontColor(Color.Red)
            .margin({ bottom: 10 });
        }
      } else if (this.currentPage === 3) {
        Text('Guest Information')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 });

        Text('Guest Count')
          .fontSize(18)
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Enter guest count', text: this.guestCount.toString() })
          .type(InputType.Number)
          .onChange((value: string) => {
            this.guestCount = parseInt(value);
          })
          .width('80%')
          .margin({ bottom: 20 });

        if (this.guestError) {
          Text(this.guestError)
            .fontSize(14)
            .fontColor(Color.Red)
            .margin({ bottom: 10 });
        }

        Text('Review Details')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20, bottom: 20 });

        Text(`Name: ${this.name}`)
          .fontSize(16)
          .margin({ bottom: 10 });

        Text(`Email: ${this.email}`)
          .fontSize(16)
          .margin({ bottom: 10 });

        Text(`Event Type: ${this.eventType}`)
          .fontSize(16)
          .margin({ bottom: 10 });

        Text(`Event Date: ${this.eventDate}`)
          .fontSize(16)
          .margin({ bottom: 10 });

        Text(`Guest Count: ${this.guestCount}`)
          .fontSize(16)
          .margin({ bottom: 20 });
      }

      Row() {
        if (this.currentPage > 1) {
          Button('Previous')
            .onClick(() => this.prevPage())
            .width('40%')
            .backgroundColor('#FF9800')
            .fontColor(Color.White);
        }

        if (this.currentPage < 3) {
          Button('Next')
            .onClick(() => this.nextPage())
            .width('40%')
            .backgroundColor('#4CAF50')
            .fontColor(Color.White);
        } else {
          Button('Submit')
            .onClick(() => this.submit())
            .width('40%')
            .backgroundColor('#4CAF50')
            .fontColor(Color.White);
        }
      }
      .justifyContent(FlexAlign.SpaceBetween)
      .width('80%')
      .margin({ top: 20 });
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

import { Search } from '@ohos.arkui.advanced.Search';
