}

@Entry
@Component
struct NutritionFactsApp {
  @State private nutritionItems: NutritionItem[] = [
    {
      id: 1,
      name: 'Apple',
      calories: 52,
      protein: 0.3,
      carbs: 14,
      fat: 0.2,
      image: $r('app.media.food_icon')
    },
    {
      id: 2,
      name: 'Banana',
      calories: 89,
      protein: 1.1,
      carbs: 22.8,
      fat: 0.3,
      image: $r('app.media.food_icon')
    },
    {
      id: 3,
      name: 'Chicken Breast',
      calories: 165,
      protein: 31,
      carbs: 0,
      fat: 3.6,
      image: $r('app.media.food_icon')
