            .fontSize(18)
            .margin({ top: 8 });

          Text(`Protein: ${this.selectedItem.protein}g`)
            .fontSize(18)
            .margin({ top: 4 });

          Text(`Carbs: ${this.selectedItem.carbs}g`)
            .fontSize(18)
            .margin({ top: 4 });

          Text(`Fat: ${this.selectedItem.fat}g`)
