import { Column, Row, Text, Button, Slider, Stepper, Divider } from '@ohos.arkui.component';
import { State, Entry, Component } from '@ohos.arkui.decorator';
import { FlexAlign } from '@ohos.arkui.layout';
import { TransitionEffect, Curve } from '@ohos.arkui.animation';
import { Color } from '@ohos.arkui.theme';

@Entry
@Component
struct CountdownTimer {
  @State initialDuration: number = 60;
  @State timeLeft: number = 60;
  @State timerId: number = -1;
  @State isCounting: boolean = false;

  build() {
    Column({ space: 20 }) {
      Text('Set Timer Duration (1-300 seconds)')
        .fontSize(18)
        .fontColor(Color.Black);

      Row({ space: 10 }) {
        Stepper({
          value: this.initialDuration,
          min: 1,
          max: 300,
          step: 1,
          onChange: (value: number) => {
            this.initialDuration = value;
            if (!this.isCounting) {
              this.timeLeft = value;
            }
          }
        })
          .width('60%')
          .height(40);

        Text(`${this.initialDuration} seconds`)
          .fontSize(16)
          .fontColor(Color.Black);
      }
      .justifyContent(FlexAlign.Center)
      .width('100%');

      Divider()
        .strokeWidth(1)
        .color(Color.Gray);

      Text('Remaining Time')
        .fontSize(18)
        .fontColor(Color.Black);

      Text(`${this.timeLeft} seconds`)
        .fontSize(24)
        .fontColor(Color.Black)
        .transition(TransitionEffect.OPACITY.animation({ duration: 300, curve: Curve.EaseInOut }));

      Slider({
        value: this.timeLeft,
        min: 0,
        max: this.initialDuration,
        onChange: (value: number) => {
          if (!this.isCounting) {
            this.timeLeft = value;
          }
        }
      })
        .width('80%')
        .height(10)
        .transition(TransitionEffect.OPACITY.animation({ duration: 300, curve: Curve.EaseInOut }));

      Divider()
        .strokeWidth(1)
        .color(Color.Gray);

      Row({ space: 20 }) {
        Button(this.isCounting ? 'Stop' : 'Start')
          .onClick(() => {
            if (this.isCounting) {
              this.stopTimer();
            } else {
              this.startTimer();
            }
          })
          .backgroundColor(this.isCounting ? Color.Red : Color.Green)
          .fontColor(Color.White)
          .transition(TransitionEffect.OPACITY.animation({ duration: 300, curve: Curve.EaseInOut }));

        Button('Reset')
          .onClick(() => {
            this.resetTimer();
          })
          .backgroundColor(Color.Blue)
          .fontColor(Color.White)
          .transition(TransitionEffect.OPACITY.animation({ duration: 300, curve: Curve.EaseInOut }));
      }
      .justifyContent(FlexAlign.Center)
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
    .backgroundColor(Color.White);
  }

  startTimer() {
    if (!this.isCounting) {
      this.isCounting = true;
      this.timerId = setInterval(() => {
        if (this.timeLeft > 0) {
          this.timeLeft -= 1;
        } else {
          this.stopTimer();
        }
      }, 1000);
    }
  }

  stopTimer() {
    this.isCounting = false;
    clearInterval(this.timerId);
  }

  resetTimer() {
    this.stopTimer();
    this.timeLeft = this.initialDuration;
  }
}

@Entry
@Component
struct MultiTabApp {
  @State private currentIndex: number = 0;
  private tabsController: TabsController = new TabsController();

  @State private sliderValue: number = 50;
  @State private selectedChip: string = "Option 1";
  @State private selectedOptionIndex: number = 0;

  @Builder
  TabBuilder(index: number, label: string) {
    Column() {
      Text(label)
        .fontColor(this.currentIndex === index ? '#007DFF' : '#6B6B6B')
        .fontSize(16)
        .fontWeight(this.currentIndex === index ? FontWeight.Bold : FontWeight.Normal)
        .margin({ top: 10, bottom: 5 });
      Divider()
        .strokeWidth(2)
        .color('#007DFF')
        .opacity(this.currentIndex === index ? 1 : 0);
    }
    .width('100%')
    .height(50)
    .justifyContent(FlexAlign.Center)
    .onClick(() => {
      this.currentIndex = index;
      this.tabsController.changeIndex(index);
    });
  }

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.Start, controller: this.tabsController }) {
        TabContent() {
          Column() {
            Slider({
              value: this.sliderValue,
              min: 0,
              max: 100,
              step: 1,
              style: SliderStyle.OutSet
            })
            .width('80%')
            .onChange((value: number) => {
              this.sliderValue = value;
            });

            Text(`Current Value: ${this.sliderValue}`)
              .fontSize(16)
              .margin({ top: 10 });
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center);
        }.tabBar(this.TabBuilder(0, 'Tab 1'));

        TabContent() {
          Column() {
            Row() {
              ForEach(["Option 1", "Option 2", "Option 3"], (option: string) => {
                Column() {
                  Text(option)
                    .fontSize(16)
                    .fontColor(this.selectedChip === option ? '#007DFF' : '#6B6B6B')
                    .fontWeight(this.selectedChip === option ? FontWeight.Bold : FontWeight.Normal)
                    .padding(10)
                    .borderRadius(20)
                    .backgroundColor(this.selectedChip === option ? '#E6F2FF' : '#F1F3F5')
                    .onClick(() => {
                      this.selectedChip = option;
                    });
                }
                .margin({ right: 10 });
              });
            }
            .margin({ top: 20 });
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center);
        }.tabBar(this.TabBuilder(1, 'Tab 2'));

        TabContent() {
          Column() {
            Select([
              { value: 'Option A' },
              { value: 'Option B' },
              { value: 'Option C' }
            ])
            .width('80%')
            .selected(this.selectedOptionIndex)
            .onSelect((index: number) => {
              this.selectedOptionIndex = index;
            });

            Text(`Selected: ${['Option A', 'Option B', 'Option C'][this.selectedOptionIndex]}`)
              .fontSize(16)
              .margin({ top: 10 });
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center);
        }.tabBar(this.TabBuilder(2, 'Tab 3'));
      }
      .vertical(false)
      .barMode(BarMode.Fixed)
      .barWidth('100%')
      .barHeight(56)
      .animationDuration(400)
      .onChange((index: number) => {
        this.currentIndex = index;
      })
      .width('100%')
      .margin({ top: 10 })
      .backgroundColor('#F1F3F5');
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

