  @State currentLanguage: string = 'en';
  @State currentIndex: number = 0;

  private carouselItems: CarouselItem[] = [
    {
      id: 1,
      image: $r('app.media.image1'),
      caption: {
        en: 'Mountain View',
        es: 'Vista de la Montaña',
        fr: 'Vue sur la Montagne'
      }
    },
