      image: $r('app.media.image2'),
      caption: {
        en: 'Ocean Sunset',
        es: 'Atardecer en el Océano',
        fr: 'Coucher de Soleil sur l\'Océan'
      }
    },
    {
      id: 3,
      image: $r('app.media.image3'),
      caption: {
        en: 'Forest Path',
        es: 'Sendero del Bosque',
        fr: 'Chemin Forestier'
      }
    }
  ];

  private getCurrentCaption(): string {
    switch(this.currentLanguage) {
      case 'es': return this.carouselItems[this.currentIndex].caption.es;
