import { List, ListItem, Column, Row, Text, Button, Image } from '@ohos.arkui.component';
import { ImageFit } from '@ohos.arkui.common';
import { FontWeight, HorizontalAlign, FlexAlign } from '@ohos.arkui.common';
import { Resource } from '@ohos.resourceManager';
import prompt from '@ohos.promptAction';

interface Article {
  id: number;
  title: string;
  image: Resource;
  content: string;
}

@Entry
@Component
struct NewsReaderApp {
  private articles: Article[] = [
    {
      id: 1,
      title: 'Article 1',
      image: $r('app.media.icon'),
      content: 'This is the full content of Article 1. It contains detailed information about the topic.'
    },
    {
      id: 2,
      title: 'Article 2',
      image: $r('app.media.icon'),
      content: 'This is the full content of Article 2. It contains detailed information about the topic.'
    },
    {
      id: 3,
      title: 'Article 3',
      image: $r('app.media.icon'),
      content: 'This is the full content of Article 3. It contains detailed information about the topic.'
    }
  ];

  @State currentPage: number = 1;
  @State selectedArticle: Article | null = null;
  private itemsPerPage: number = 5;

  getPaginatedArticles(): Article[] {
    const startIndex = (this.currentPage - 1) * this.itemsPerPage;
    return this.articles.slice(startIndex, startIndex + this.itemsPerPage);
  }

  build() {
    Column() {
      Column() {
        List() {
          ForEach(this.getPaginatedArticles(), (article: Article) => {
            ListItem() {
              Row() {
                Image(article.image)
                  .width(80)
                  .height(80)
                  .borderRadius(8)
                  .objectFit(ImageFit.Cover)
                  .margin({ right: 10 });
                Column() {
                  Text(article.title)
                    .fontSize(18)
                    .fontWeight(FontWeight.Medium)
                    .margin({ bottom: 4 });
                  Text(article.content.substring(0, 50) + '...')
                    .fontSize(14)
                    .fontColor('#666666');
                }
                .layoutWeight(1)
                .alignItems(HorizontalAlign.Start);
              }
              .padding(16)
              .backgroundColor('#FFFFFF')
              .borderRadius(12)
              .onClick(() => {
                this.selectedArticle = article;
                prompt.showDialog({
                  title: this.selectedArticle.title,
                  message: this.selectedArticle.content,
                  buttons: [
                    {
                      text: 'Close',
                      color: '#000000'
                    }
                  ]
                });
              });
            }
            .margin({ bottom: 12 });
          });
        }
        .width('100%')
        .height('80%');

        Row() {
          Button('Previous')
            .enabled(this.currentPage > 1)
            .onClick(() => {
              if (this.currentPage > 1) {
                this.currentPage--;
              }
            })
            .margin({ right: 10 });

          Text(`Page ${this.currentPage}`)
            .fontSize(16);

          Button('Next')
            .enabled(this.currentPage * this.itemsPerPage < this.articles.length)
            .onClick(() => {
              if (this.currentPage * this.itemsPerPage < this.articles.length) {
                this.currentPage++;
              }
            })
            .margin({ left: 10 });
        }
        .width('100%')
        .justifyContent(FlexAlign.Center)
        .margin({ top: 20 });
      }
      .width('100%')
      .height('100%')
      .padding(20)
      .backgroundColor('#F5F5F5');
    }
    .width('100%')
    .height('100%');
  }
}

import { TimePicker } from '@ohos.picker';
import { Column, Text, Button, RefreshContainer } from '@ohos.arkui.advanced';
import web_webview from '@ohos.web.webview';

interface TimeValue {
  hour: number;
  minute: number;
}

@Entry
@Component
struct TimeSelectionApp {
  @State selectedTime: Date = new Date();
  @State displayTime: string = '';
  @State isVoiceInputActive: boolean = false;
  @State isRefreshing: boolean = false;
  private webController: web_webview.WebviewController = new web_webview.WebviewController();

  aboutToAppear() {
    this.updateDisplayTime();
  }

  updateDisplayTime() {
    this.displayTime = this.selectedTime.toLocaleTimeString();
  }

  handleTimeChange(value: TimeValue) {
    if (value.hour !== undefined && value.minute !== undefined) {
      this.selectedTime.setHours(value.hour, value.minute);
      this.updateDisplayTime();
    }
  }

  toggleVoiceInput() {
    this.isVoiceInputActive = !this.isVoiceInputActive;
  }

  handleRefresh() {
    this.isRefreshing = true;
    setTimeout(() => {
      this.isRefreshing = false;
    }, 1000);
  }

  build() {
    Column() {
      TimePicker({
        selected: this.selectedTime.getHours(),
        selectedMinute: this.selectedTime.getMinutes()
      })
        .onChange((hour: number, minute: number) => {
          this.handleTimeChange({hour, minute});
        })
        .margin({ bottom: 20 });

      Text(`Selected Time: ${this.displayTime}`)
        .fontSize(20)
        .fontWeight('500')
        .margin({ bottom: 20 });

      Button(this.isVoiceInputActive ? 'Voice Input Active' : 'Activate Voice Input')
        .backgroundColor(this.isVoiceInputActive ? 0x007AFF : 0xF0F0F0)
        .fontColor(this.isVoiceInputActive ? 0xFFFFFF : 0x000000)
        .onClick(() => {
          this.toggleVoiceInput();
        })
        .onDoubleClick(() => {
          this.toggleVoiceInput();
        })
        .margin({ bottom: 20 });

      RefreshContainer({ refreshing: this.isRefreshing }) {
        Web({
          src: 'https://example.com',
          controller: this.webController
        })
        .width('100%')
        .height(400);
      }
      .width('100%')
      .height(400);
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(0xFFFFFF)
    .justifyContent('center')
    .alignItems('center');
  }
}

