  @State mealPlans: string[] = [];
  @State newMealName: string = '';
  @State showAddMealScreen: boolean = false;
  @State showErrorDialog: boolean = false;
  @State errorMessage: string = '';

  private prefs = preferences.getPreferences(getContext(), 'MealPlannerPrefs');

  async onPageShow() {
    try {
      const prefs = await this.prefs;
      const savedPlans = await prefs.get('mealPlans', []);
      this.mealPlans = Array.isArray(savedPlans) ? savedPlans : [];
    } catch (error) {
      console.error('Failed to load meal plans:', error);
      this.mealPlans = [];
    }
  }

  async saveMealPlans() {
    try {
      const prefs = await this.prefs;
      await prefs.put('mealPlans', JSON.stringify(this.mealPlans));
    } catch (error) {
      console.error('Failed to save meal plans:', error);
    }
  }

  build() {
    Stack() {
      Column() {
        if (!this.showAddMealScreen) {
          Text('Meal Planner')
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          List() {
            ForEach(this.mealPlans, (meal: string, index: number) => {
              ListItem() {
                Row() {
                  Text(meal)
                    .fontSize(18)
                    .margin({ right: 10 });
                  Button('Delete')
                    .onClick(() => {
                      this.mealPlans = this.mealPlans.filter((_, i) => i !== index);
                      this.saveMealPlans();
                    });
                }
                .padding(10)
                .borderRadius(5)
                .backgroundColor(Color.White)
                .margin({ bottom: 5 });
              }
            });
          }
          .width('100%')
          .layoutWeight(1);

          Button('Add Meal')
            .onClick(() => {
              this.showAddMealScreen = true;
            })
            .margin({ top: 20 });
        } else {
          Column() {
            Text('Add New Meal')
              .fontSize(24)
              .fontWeight(FontWeight.Bold)
              .margin({ bottom: 20 });

            TextInput({ placeholder: 'Enter meal name', text: this.newMealName })
              .onChange((value: string) => {
                this.newMealName = value;
              })
              .margin({ bottom: 20 });

            Row() {
              Button('Save')
                .onClick(() => {
                  if (this.newMealName.trim() === '') {
                    this.errorMessage = 'Meal name cannot be empty';
                    this.showErrorDialog = true;
                  } else {
                    this.mealPlans = [...this.mealPlans, this.newMealName];
                    this.newMealName = '';
                    this.saveMealPlans();
                    this.showAddMealScreen = false;
                  }
                })
                .margin({ right: 10 });

              Button('Cancel')
                .onClick(() => {
                  this.newMealName = '';
                  this.showAddMealScreen = false;
                });
            }
          }
          .width('100%')
          .height('100%')
          .padding(20);
        }
      }
      .width('100%')
      .height('100%')
      .padding(20)
      .backgroundColor('#f5f5f5');
    }
    .onAppear(() => {
      if (this.showErrorDialog) {
        AlertDialog.show({
          title: 'Error',
          message: this.errorMessage,
          buttons: [
            {
              text: 'OK',
              action: () => {
                this.showErrorDialog = false;
              }
            }
          ]
        });
      }
    })
  }
}

import { Swiper, SwiperController } from '@ohos.arkui.advancedUI';
import { Tabs, TabContent, TabsController } from '@ohos.arkui.advancedUI';
import { Image, ImageFit } from '@ohos.arkui.component';
import { Column, Row, Text, Button, Stack, Slider, Toggle, ToggleType } from '@ohos.arkui.component';

@Entry
@Component
struct ImageGalleryApp {
  private swiperController: SwiperController = new SwiperController();
  private tabsController: TabsController = new TabsController();
  private images: Resource[] = [
    $r('app.media.image1'),
    $r('app.media.image2'),
    $r('app.media.image3')
  ];
  private tabTitles: string[] = ['Image 1', 'Image 2', 'Image 3'];

  @State currentIndex: number = 0;
  @State swipeThreshold: number = 50;
  @State enableAnimations: boolean = true;
  @State imageSize: number = 300;

  build() {
    Column() {
      Tabs({ index: this.currentIndex, controller: this.tabsController }) {
        ForEach(this.tabTitles, (title: string, index: number) => {
          TabContent() {
            Swiper(this.swiperController) {
              ForEach(this.images, (image: Resource) => {
                Image(image)
                  .width('100%')
                  .height(this.imageSize)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(8);
              });
            }
            .width('100%')
            .height(this.imageSize)
            .indicator(false)
            .loop(false)
            .duration(this.enableAnimations ? 300 : 0)
            .onChange((index: number) => {
              this.currentIndex = index;
              this.tabsController.changeIndex(index);
            });
          }
          .tabBar(title);
        });
      }
      .width('100%')
      .height('100%')
      .onChange((index: number) => {
        this.currentIndex = index;
        this.swiperController.showIndex(index);
      });

      Column() {
        Column() {
          Text('Settings').fontSize(20).margin({ bottom: 16 });
          Row() {
            Text('Swipe Threshold:');
            Slider({
              value: this.swipeThreshold,
              min: 10,
              max: 100,
              step: 5
            })
            .onChange((value: number) => {
              this.swipeThreshold = value;
            });
          }
          .margin({ bottom: 16 });

          Row() {
            Text('Enable Animations:');
            Toggle({ type: ToggleType.Switch, isOn: this.enableAnimations })
              .onChange((isOn: boolean) => {
                this.enableAnimations = isOn;
              });
          }
          .margin({ bottom: 16 });

          Row() {
            Text('Image Size:');
            Slider({
              value: this.imageSize,
              min: 200,
              max: 500,
              step: 50
            })
            .onChange((value: number) => {
              this.imageSize = value;
            });
          }
        }
        .padding(16);
      }
      .width('100%');
    }
    .width('100%')
    .height('100%');
  }
}

