@Entry
@Component
struct PDFViewer {
  @State currentPage: number = 0
  private pdfPages: Resource[] = [
    $r('app.media.ic_public_picture'),
    $r('app.media.ic_public_picture'),
    $r('app.media.ic_public_picture')
  ]
  private totalPages: number = this.pdfPages.length
  private swiperController: SwiperController = new SwiperController()
  @State isLoading: boolean = true

  build() {
    Column() {
      Text('PDF Viewer')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 16, bottom: 16 })

      if (this.isLoading) {
        Text('Loading...')
          .fontSize(18)
          .margin({ bottom: 16 })
      }

      if (this.pdfPages.length === 0) {
        Text('No PDF pages available')
          .fontSize(18)
          .margin(16)
      } else {
        Swiper(this.swiperController) {
          ForEach(this.pdfPages, (page: Resource, index: number) => {
            Image(page)
              .objectFit(ImageFit.Contain)
              .width('100%')
              .height('70%')
              .onComplete(() => {
                if (index === this.pdfPages.length - 1) {
                  this.isLoading = false
                }
              })
          })
        }
        .height('70%')
        .loop(false)
        .onChange((index: number) => {
          this.currentPage = index
        })
      }

      Row({ space: 20 }) {
        Button('Previous')
          .onClick(() => {
            if (this.currentPage > 0) {
              this.currentPage--
              this.swiperController.showPrevious()
            }
          })

        Text(`Page ${this.currentPage + 1} of ${this.totalPages}`)
          .fontSize(18)

        Button('Next')
          .onClick(() => {
            if (this.currentPage < this.totalPages - 1) {
              this.currentPage++
              this.swiperController.showNext()
            }
          })
      }
      .margin({ top: 16, bottom: 16 })
      .justifyContent(FlexAlign.Center)
    }
    .width('100%')
    .height('100%')
    .padding(16)
  }
}

import { Button, Column, Text, Select, FlexAlign, GestureGroup, PanGesture, PanDirection, GestureMode, GestureEvent } from '@ohos.arkui';
import animateTo from '@ohos.animator';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct VoiceInputApp {
  @State voiceInputText: string = 'Click the voice input button';
  @State selectedOption: string = 'Option 1';
  @State swipeMessage: string = 'Swipe left or right';

  build() {
    Column() {
      Button('Voice Input')
        .width('80%')
        .margin({ top: 20, bottom: 20 })
        .onClick(() => {
          promptAction.showToast({
            message: 'Voice input activated',
            duration: 2000
          });
          this.voiceInputText = 'Listening...';
        });

      Text(this.voiceInputText)
        .margin({ bottom: 20 });

      Select([
        { value: 'Option 1', label: 'Option 1' },
        { value: 'Option 2', label: 'Option 2' },
        { value: 'Option 3', label: 'Option 3' }
      ])
        .width('80%')
        .margin({ bottom: 20 })
        .onSelect((value: string) => {
          this.selectedOption = value;
        });

      Text(this.selectedOption)
        .margin({ bottom: 20 });

      Text(this.swipeMessage)
        .fontSize(16)
        .margin({ bottom: 20 });

      Column()
        .width('80%')
        .height(200)
        .backgroundColor('#F0F0F0')
        .gesture(
          GestureGroup(
            GestureMode.Exclusive,
            PanGesture({ direction: PanDirection.Horizontal })
              .onActionUpdate((event: GestureEvent) => {
                if (Math.abs(event.offsetX) > 100) {
                  this.swipeMessage = event.offsetX > 0 ? 'Swiped right' : 'Swiped left';
                }
              })
              .onActionEnd(() => {
                animateTo({ duration: 300 }, () => {
                  this.swipeMessage = 'Swipe left or right';
                });
              })
          )
        )
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(FlexAlign.Center)
    .padding(20);
  }
}

import { Column, Row, Text, Button, Swiper, SwiperController } from '@ohos.arkui.advancedUI';
import { FlexAlign, FontWeight } from '@ohos.arkui.advancedUI';
import window from '@ohos.window';
import common from '@ohos.app.ability.common';

interface Sensor {
  name: string;
  value: number;
}

@Entry
@Component
struct SensorDataApp {
  private context: common.UIAbilityContext = getContext(this) as common.UIAbilityContext;
  @State private sensors: Sensor[] = [
    { name: 'Temperature', value: 25 },
    { name: 'Humidity', value: 50 },
    { name: 'Pressure', value: 1013 }
  ];
  private swiperController: SwiperController = new SwiperController();
  private timerId: number = 0;

  aboutToAppear(): void {
    this.setLandscapeOrientation();
    this.startMockDataUpdates();
  }

  aboutToDisappear(): void {
    clearInterval(this.timerId);
  }

  setLandscapeOrientation(): void {
    try {
      window.getLastWindow(this.context).then((win) => {
        win.setPreferredOrientation(window.Orientation.LANDSCAPE);
      });
    } catch (error) {
      console.error('Failed to set landscape orientation:', error);
    }
  }

  startMockDataUpdates(): void {
    this.timerId = setInterval(() => {
      this.sensors = this.sensors.map((sensor: Sensor): Sensor => {
        return {
          name: sensor.name,
          value: Math.floor(Math.random() * 100)
        };
      });
    }, 1000);
  }

  build() {
    Column() {
      Swiper(this.swiperController) {
        ForEach(this.sensors, (sensor: Sensor) => {
          Column() {
            Text(sensor.name)
              .fontSize(30)
              .fontWeight(FontWeight.Bold)
              .margin({ bottom: 10 });
            Text(sensor.value.toString())
              .fontSize(24)
              .margin({ bottom: 20 });
          }
          .width('80%')
          .height('60%')
          .padding(20)
          .backgroundColor('#F5F5F5')
          .borderRadius(10)
          .margin({ left: 10, right: 10 });
        });
      }
      .indicator(false)
      .loop(false)
      .width('100%')
      .height('70%');

      Row() {
        Button('Previous')
          .onClick((): void => { this.swiperController.showPrevious(); })
          .width('40%')
          .height(50)
          .margin({ right: 10 });
        Button('Next')
          .onClick((): void => { this.swiperController.showNext(); })
          .width('40%')
          .height(50);
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

import { Column, Text, Button, Badge, PanGesture, ButtonType, FlexAlign, HorizontalAlign } from '@ohos.arkui';
import { animateTo } from '@ohos.arkui';

interface GestureOffset {
  offsetX: number;
  offsetY: number;
}

interface ScaleType {
  x: number;
  y: number;
}

interface TransformOptions {
  translate: {
    x: number;
    y: number;
  };
  scale: ScaleType;
}

@Entry
@Component
struct OnboardingButton {
  @State offsetX: number = 0;
  @State offsetY: number = 0;
  @State scale: ScaleType = { x: 1, y: 1 };

  build() {
    Column({ space: 10 }) {
      Column() {
        Badge({
          count: 1,
          position: 'rightTop',
          color: 0xFF0000,
          fontSize: 16,
          size: 16
        }) {
          Button({ type: ButtonType.Circle }) {
            Text('+')
              .fontSize(30)
              .fontColor(0xFFFFFF)
          }
          .width(80)
          .height(80)
          .backgroundColor(0x0000FF)
          .gesture(
            PanGesture()
              .onActionUpdate((event: GestureOffset) => {
                this.offsetX = event.offsetX;
                this.offsetY = event.offsetY;
                this.scale = { x: 1.1, y: 1.1 };
              })
              .onActionEnd(() => {
                animateTo({ duration: 300 }, () => {
                  this.offsetX = 0;
                  this.offsetY = 0;
                  this.scale = { x: 1, y: 1 };
                });
              })
          )
          .transform({ 
            translate: { x: this.offsetX, y: this.offsetY }, 
            scale: { x: this.scale.x, y: this.scale.y }
          })
        }
      }
      .margin({ top: 50 })

      Text('Drag the button to explore')
        .fontSize(18)
        .fontColor(0x000000)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(0xFFFFFF)
  }
}

import { Column, Row, Text, Button, List, ListItem, TextInput } from '@ohos.arkui.component';

interface Task {
  name: string;
  isSelected: boolean;
  isPlaying: boolean;
}

@Entry
@Component
struct TaskManagementApp {
  @State tasks: Task[] = [];
  @State newTaskName: string = '';
  @State currentView: string = 'Tasks';

  build() {
    Column() {
      Row() {
        Button('Home')
          .onClick(() => { this.currentView = 'Home'; })
          .margin(5);
        Button('Tasks')
          .onClick(() => { this.currentView = 'Tasks'; })
          .margin(5);
      }

      if (this.currentView === 'Tasks') {
        Column() {
          TextInput({ placeholder: 'Enter task name', text: this.newTaskName })
            .onChange((value: string) => { this.newTaskName = value; })
            .width('80%')
            .margin(10);

          Button('Add Task')
            .onClick(() => {
              if (this.newTaskName.trim() !== '') {
                this.tasks.push({
                  name: this.newTaskName,
                  isSelected: false,
                  isPlaying: false
                });
                this.newTaskName = '';
              }
            })
            .width('80%')
            .margin(10);

          List() {
            ForEach(this.tasks, (task: Task, index: number) => {
              ListItem() {
                Row() {
                  Text(task.name)
                    .fontSize(16)
                    .margin(10);

                  Button(task.isPlaying ? 'Stop' : 'Play')
                    .onClick(() => {
                      this.tasks.forEach((t: Task, i: number) => {
                        if (i === index) {
                          t.isPlaying = !t.isPlaying;
                          t.isSelected = true;
                        } else {
                          t.isPlaying = false;
                          t.isSelected = false;
                        }
                      });
                    })
                    .margin(10);
                }
              }
              .backgroundColor(task.isSelected ? '#e0e0e0' : 'transparent');
            });
          }
          .width('100%')
          .height('60%');
        }
      } else {
        Text('Home View')
          .fontSize(24)
          .margin(20);
      }
    }
    .width('100%')
    .height('100%')
    .padding(10);
  }
}

