                        .fontColor('#999999');
                    }
                    .width('100%')
                    .padding(10);
                  }
                  .onClick(() => {});
                }, (email: Email) => email.id);
              }
              .width('100%')
              .layoutWeight(1);
            }
            .tabBar('Meeting');

            TabContent() {
              List({ space: 10 }) {
                ForEach(this.filteredEmails, (email: Email) => {
                  ListItem() {
                    Column() {
                      Text(email.subject)
                        .fontSize(18)
                        .fontWeight('bold')
                        .margin({ bottom: 4 });
                      Text(email.sender)
                        .fontSize(14)
                        .fontColor('#666666')
                        .margin({ bottom: 4 });
                      Text(email.date)
                        .fontSize(12)
                        .fontColor('#999999');
                    }
                    .width('100%')
                    .padding(10);
                  }
                  .onClick(() => {});
                }, (email: Email) => email.id);
              }
              .width('100%')
              .layoutWeight(1);
            }
            .tabBar('Project');

            TabContent() {
              List({ space: 10 }) {
                ForEach(this.filteredEmails, (email: Email) => {
                  ListItem() {
                    Column() {
                      Text(email.subject)
                        .fontSize(18)
                        .fontWeight('bold')
                        .margin({ bottom: 4 });
                      Text(email.sender)
                        .fontSize(14)
                        .fontColor('#666666')
                        .margin({ bottom: 4 });
                      Text(email.date)
                        .fontSize(12)
                        .fontColor('#999999');
                    }
                    .width('100%')
                    .padding(10);
                  }
                  .onClick(() => {});
                }, (email: Email) => email.id);
              }
              .width('100%')
              .layoutWeight(1);
            }
            .tabBar('Report');
          }
          .onChange((index: number) => {
            const tabs = ['All', 'Meeting', 'Project', 'Report'];
            this.activeTab = tabs[index];
            this.filterEmails();
          })
          .width('100%')
          .height(40);
        }
        .width('100%')
        .height('100%')
        .padding(10)
        .backgroundColor('#f0f0f0');
      }
      .width('100%')
      .height('100%');
    }
    .width('100%')
    .height('100%')
    .onAppear(() => {
      this.filterEmails();
    });
  }

  private filterEmails() {
    this.filteredEmails = this.emails.filter(email => {
      const matchesSearch = this.searchQuery === '' ||
        email.subject.toLowerCase().includes(this.searchQuery) ||
        email.sender.toLowerCase().includes(this.searchQuery);
      const matchesTab = this.activeTab === 'All' || email.category === this.activeTab;
      return matchesSearch && matchesTab;
    });
  }
}

