import { Column, Row, Button, Text, Toggle, ToggleType } from '@ohos.arkui.advanced';
import { Canvas, RenderingContext } from '@ohos.arkui.node.Canvas';
import image from '@ohos.multimedia.image';
import camera from '@ohos.multimedia.camera';
import common from '@ohos.app.ability.common';

interface Size {
  width: number;
  height: number;
}

interface Region {
  size: Size;
  x: number;
  y: number;
  width: number;
  height: number;
}

interface PositionArea {
  pixels: Uint8Array;
  offset: number;
  stride: number;
  region: Region;
}

@Entry
@Component
struct DocumentScanner {
  @State isScanning: boolean = false;
  @State grayscaleEnabled: boolean = false;
  @State invertEnabled: boolean = false;
  @State blurEnabled: boolean = false;
  private camera: camera.CameraInput | null = null;
  private cameraManager: camera.CameraManager | null = null;
  private canvasContext: RenderingContext | null = null;

  build() {
    Column() {
      Canvas(this.canvasContext)
        .width('100%')
        .height('60%')
        .backgroundColor('#000000')
        .onReady((context: RenderingContext) => {
          this.canvasContext = context;
        });

      Row() {
        Toggle({ type: ToggleType.Switch })
          .isOn(this.grayscaleEnabled)
          .onChange((isOn: boolean) => {
            this.grayscaleEnabled = isOn;
          })
          .margin({ right: 10 });
        Text('Grayscale');

        Toggle({ type: ToggleType.Switch })
          .isOn(this.invertEnabled)
          .onChange((isOn: boolean) => {
            this.invertEnabled = isOn;
          })
          .margin({ right: 10 });
        Text('Invert');

        Toggle({ type: ToggleType.Switch })
          .isOn(this.blurEnabled)
          .onChange((isOn: boolean) => {
            this.blurEnabled = isOn;
          })
          .margin({ right: 10 });
        Text('Blur');
      }
      .margin({ top: 20, bottom: 20 });

      Button(this.isScanning ? 'Stop Scanning' : 'Start Scanning')
        .onClick(() => {
          this.isScanning = !this.isScanning;
          if (this.isScanning) {
            this.startCamera();
          } else {
            this.stopCamera();
          }
        })
        .width('80%')
        .height(50);
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }

  private async startCamera() {
    try {
      const context = getContext(this) as common.UIAbilityContext;
      this.cameraManager = camera.getCameraManager(context);
      const cameras = await this.cameraManager.getSupportedCameras();
      if (cameras.length > 0) {
        const input = this.cameraManager.createCameraInput(cameras[0]);
        await input.open();
        this.camera = input;
      }
    } catch (error) {
      console.error('Failed to start camera:', error);
    }
  }

  private stopCamera() {
    if (this.camera) {
      this.camera.close();
      this.camera = null;
    }
    if (this.cameraManager) {
      this.cameraManager = null;
    }
  }

  private async applyFilters(frame: image.PixelMap): Promise<void> {
    let processedFrame = frame;
    if (this.grayscaleEnabled) {
      processedFrame = await this.applyGrayscale(processedFrame);
    }
    if (this.invertEnabled) {
      processedFrame = await this.applyInvert(processedFrame);
    }
    if (this.blurEnabled) {
      processedFrame = await this.applyBlur(processedFrame);
    }
    if (this.canvasContext) {
      const imageInfo = await processedFrame.getImageInfo();
      const pixelBytes = await processedFrame.readPixelsToBuffer({
        region: {
          size: { width: imageInfo.size.width, height: imageInfo.size.height },
          x: 0,
          y: 0,
          width: imageInfo.size.width,
          height: imageInfo.size.height
        }
      });
      const pixelArray = new Uint8ClampedArray(pixelBytes);
      const imageData = new ImageData(
        pixelArray,
        imageInfo.size.width,
        imageInfo.size.height
      );
      this.canvasContext.putImageData(imageData, 0, 0);
    }
  }

  private async applyGrayscale(frame: image.PixelMap): Promise<image.PixelMap> {
    const imageInfo = await frame.getImageInfo();
    const area: PositionArea = {
      pixels: new Uint8Array(imageInfo.size.width * imageInfo.size.height * 4),
      offset: 0,
      stride: imageInfo.size.width * 4,
      region: {
        size: { width: imageInfo.size.width, height: imageInfo.size.height },
        x: 0,
        y: 0,
        width: imageInfo.size.width,
        height: imageInfo.size.height
      }
    };

    await frame.readPixels(area);
    const pixels = area.pixels;

    for (let i = 0; i < pixels.length; i += 4) {
      const avg = (pixels[i] + pixels[i + 1] + pixels[i + 2]) / 3;
      pixels[i] = avg;
      pixels[i + 1] = avg;
      pixels[i + 2] = avg;
    }

    await frame.writePixels(area);
    return frame;
  }

  private async applyInvert(frame: image.PixelMap): Promise<image.PixelMap> {
    const imageInfo = await frame.getImageInfo();
    const area: PositionArea = {
      pixels: new Uint8Array(imageInfo.size.width * imageInfo.size.height * 4),
      offset: 0,
      stride: imageInfo.size.width * 4,
      region: {
        size: { width: imageInfo.size.width, height: imageInfo.size.height },
        x: 0,
        y: 0,
        width: imageInfo.size.width,
        height: imageInfo.size.height
      }
    };

    await frame.readPixels(area);
    const pixels = area.pixels;

    for (let i = 0; i < pixels.length; i += 4) {
      pixels[i] = 255 - pixels[i];
      pixels[i + 1] = 255 - pixels[i + 1];
      pixels[i + 2] = 255 - pixels[i + 2];
    }

    await frame.writePixels(area);
    return frame;
  }

  private async applyBlur(frame: image.PixelMap): Promise<image.PixelMap> {
    const imageInfo = await frame.getImageInfo();
    const area: PositionArea = {
      pixels: new Uint8Array(imageInfo.size.width * imageInfo.size.height * 4),
      offset: 0,
      stride: imageInfo.size.width * 4,
      region: {
        size: { width: imageInfo.size.width, height: imageInfo.size.height },
        x: 0,
        y: 0,
        width: imageInfo.size.width,
        height: imageInfo.size.height
      }
    };

    await frame.readPixels(area);
    const pixels = area.pixels;
    const tempPixels = new Uint8Array(pixels.length);
    const width = imageInfo.size.width;
    const height = imageInfo.size.height;

    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const index = (y * width + x) * 4;
        let r = 0, g = 0, b = 0, count = 0;

        for (let dy = -1; dy <= 1; dy++) {
          for (let dx = -1; dx <= 1; dx++) {
            const nx = x + dx;
            const ny = y + dy;
            if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
              const nIndex = (ny * width + nx) * 4;
              r += pixels[nIndex];
              g += pixels[nIndex + 1];
              b += pixels[nIndex + 2];
              count++;
            }
          }
        }

        tempPixels[index] = r / count;
        tempPixels[index + 1] = g / count;
        tempPixels[index + 2] = b / count;
        tempPixels[index + 3] = pixels[index + 3];
      }
    }

    area.pixels = tempPixels;
    await frame.writePixels(area);
    return frame;
  }
}

import { Column, Text, Button } from '@ohos.arkui.component';
import ActionSheet from '@ohos.arkui.actionSheet';
