import { Refresh, List, ListItem, Text, Button, Column, LongPressGesture, TextAlign, Color, Visibility } from '@ohos.arkui.advancedUI';
import prompt from '@ohos.promptAction';

@Entry
@Component
struct TaskManager {
  @State tasks: Array<string> = ['Task 1', 'Task 2', 'Task 3'];
  @State isRefreshing: boolean = false;
  @State isVoiceActive: boolean = false;

  private refreshTasks(): void {
    this.isRefreshing = true;
    setTimeout(() => {
      this.tasks = [`New Task ${this.tasks.length + 1}`, ...this.tasks];
      this.isRefreshing = false;
    }, 2000);
  }

  private activateVoiceCommand(): void {
    this.isVoiceActive = true;
    setTimeout(() => {
      this.isVoiceActive = false;
    }, 3000);
  }

  build() {
    Column() {
      Refresh({ refreshing: this.isRefreshing, onRefresh: () => this.refreshTasks() }) {
        List() {
          ForEach(this.tasks, (task: string, index: number) => {
            ListItem() {
              Text(task)
                .fontSize(16)
                .margin({ top: 10, bottom: 10 })
                .width('100%')
                .textAlign(TextAlign.Start);
            }
          })
        }
        .width('100%')
        .height('80%')
      }
      .width('100%')
      .height('80%')

      Button('Voice Command')
        .onClick(() => {
          this.activateVoiceCommand();
        })
        .gesture(
          LongPressGesture()
            .onAction(() => {
              this.activateVoiceCommand();
            })
        )
        .width('90%')
        .height(50)
        .margin({ top: 20, bottom: 20 });

      Text('Voice Command Active')
        .fontSize(16)
        .fontColor(Color.Blue)
        .margin({ bottom: 20 })
        .visibility(this.isVoiceActive ? Visibility.Visible : Visibility.Hidden);
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White);
  }
}

import { Column, Text, Button, TextInput } from '@ohos.arkui.component';
import { timer } from '@ohos.arkui.base';
import { Color } from '@ohos.arkui.drawing';

@Entry
@Component
struct AlarmClockApp {
  @State currentTime: Date = new Date();
  @State alarmTime: string = '';
  @State isAlarmSet: boolean = false;
  @State barcodeInput: string = '';
  private timerId: number = -1;

  aboutToAppear() {
    this.timerId = timer.setInterval(() => {
      this.currentTime = new Date();
    }, 1000);
  }

  aboutToDisappear() {
    if (this.timerId !== -1) {
      timer.clearInterval(this.timerId);
    }
  }

  formatTime(date: Date): string {
    const hours = date.getHours().toString().padStart(2, '0');
    const minutes = date.getMinutes().toString().padStart(2, '0');
    return `${hours}:${minutes}`;
  }

  setAlarm() {
    this.isAlarmSet = true;
  }

  build() {
    Column({ space: 20 }) {
      Text('Current Time')
        .fontSize(24)
        .fontWeight(700)
        .margin({ bottom: 10 });

      Text(this.formatTime(this.currentTime))
        .fontSize(48)
        .fontColor(Color.Black)
        .margin({ bottom: 20 });

      if (this.isAlarmSet) {
        Text('Alarm Set: ' + this.alarmTime)
          .fontSize(24)
          .fontColor(Color.Red)
          .margin({ bottom: 20 });
      }

      TextInput({ placeholder: 'Set Alarm Time (HH:MM)' })
        .onChange((value: string) => {
          this.alarmTime = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Button('Set Alarm')
        .onClick(() => {
          this.setAlarm();
        })
        .width('80%')
        .margin({ bottom: 20 });

      Text('Barcode Scanner')
        .fontSize(24)
        .fontWeight(700)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Scan Barcode' })
        .onChange((value: string) => {
          this.barcodeInput = value;
        })
        .width('80%')
        .margin({ bottom: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent('center')
    .alignItems('center')
    .backgroundColor(Color.White);
  }
}

@Entry
@Component
struct BottomSheetApp {
  @State isBottomSheetVisible: boolean = false;
  @State progress: number = 0;

  @Builder
  CustomChip(label: string, selected: boolean, onSelected: () => void) {
    Button(label)
      .onClick(() => {
        onSelected();
      })
      .borderRadius(20)
      .backgroundColor(selected ? '#007AFF' : '#F5F5F5')
      .fontColor(selected ? Color.White : Color.Black)
      .padding({ left: 16, right: 16, top: 8, bottom: 8 })
      .margin({ bottom: 10 });
  }

  build() {
    Column() {
      Column() {
        Text('Gesture-Enabled BottomSheet')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20, bottom: 20 })
          .width('100%')
          .textAlign(TextAlign.Center);

        Button('Show BottomSheet')
          .onClick(() => {
            this.isBottomSheetVisible = true;
          })
          .width('80%')
          .height(50)
          .backgroundColor('#007AFF')
          .fontColor(Color.White)
          .fontSize(18)
          .margin({ top: 20 });
      }
      .width('100%')
      .height('100%')
      .backgroundColor('#F5F5F5');

      if (this.isBottomSheetVisible) {
        Column() {
          Row() {
            Text('Progress Tracking')
              .fontSize(20)
              .fontWeight(FontWeight.Bold)
              .margin({ left: 16 });

            Button() {
              Text('×')
                .fontSize(24)
                .fontWeight(FontWeight.Bold);
            }
            .backgroundColor('transparent')
            .onClick(() => {
              this.isBottomSheetVisible = false;
            })
            .margin({ right: 16 });
          }
          .width('100%')
          .height(56)
          .backgroundColor(Color.White)
          .justifyContent(FlexAlign.SpaceBetween);

          Flex({ direction: FlexDirection.Row, alignItems: ItemAlign.Center, justifyContent: FlexAlign.Center }) {
            Text('Progress:')
              .fontSize(16)
              .margin({ right: 10 });

            Text(`${this.progress}%`)
              .fontSize(16)
              .fontWeight(FontWeight.Bold);
          }
          .width('100%')
          .margin({ top: 16, bottom: 16 });

          Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Center }) {
            ForEach([0, 25, 50, 75, 100], (value: number) => {
              this.CustomChip(
                `${value}%`,
                this.progress === value,
                () => {
                  this.progress = value;
                }
              );
            });
          }
          .width('100%')
          .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.isBottomSheetVisible = false;
            })
            .width('80%')
            .height(50)
            .backgroundColor('#FF3B30')
            .fontColor(Color.White)
            .fontSize(18)
            .margin({ bottom: 20 });
        }
        .width('100%')
        .height('50%')
        .backgroundColor(Color.White)
        .position({ x: 0, y: '50%' })
        .borderRadius({ topLeft: 16, topRight: 16 })
        .shadow({ radius: 16, color: '#000000', offsetX: 0, offsetY: -4 })
        .gesture(
          PanGesture({})
            .onActionUpdate((event: GestureEvent) => {
              const newProgress = Math.min(100, Math.max(0, this.progress + event.offsetX / 2));
              this.progress = newProgress;
            })
        );
      }
    }
    .width('100%')
    .height('100%');
  }
}

import { Column, Row, Text, Button, TextInput, List, ListItem, State } from '@ohos.arkui';

interface DataPoint {
  x: number;
  y: number;
  label: string;
}

@Entry
@Component
struct ARDataVisualization {
  @State dataPoints: DataPoint[] = [];
  @State isLoading: boolean = true;
  @State showGrid: boolean = false;
  @State filterText: string = '';
  @State filteredData: DataPoint[] = [];

  build() {
    Column() {
      Column() {
        if (this.isLoading) {
          Text('Loading data...')
            .fontSize(20)
            .margin(20);
        } else {
          Text('Data Visualization Area')
            .fontSize(20)
            .margin(20);
        }
      }
      .height('60%')
      .width('100%')
      .backgroundColor('#D3D3D3');

      Column() {
        Row() {
          Button(this.showGrid ? 'Hide Grid' : 'Show Grid')
            .onClick(() => {
              this.showGrid = !this.showGrid;
            })
            .margin(10);

          TextInput({ placeholder: 'Filter data...' })
            .onChange((value: string) => {
              this.filterText = value;
              this.filterData();
            })
            .width('70%')
            .margin(10);
        }
      }
      .width('100%')
      .padding(10);

      if (this.showGrid) {
        List() {
          ForEach(this.filteredData, (item: DataPoint) => {
            ListItem() {
              Row() {
                Text(`X: ${item.x}, Y: ${item.y}`)
                  .fontSize(16)
                  .margin(5);
                Text(`Label: ${item.label}`)
                  .fontSize(16)
                  .margin(5);
              }
            }
          }, (item: DataPoint) => item.label)
        }
        .width('100%')
        .height('30%')
        .layoutWeight(1);
      }
    }
    .width('100%')
    .height('100%')
    .onAppear(() => {
      this.loadMockData();
    });
  }

  private loadMockData() {
    setTimeout(() => {
      this.dataPoints = [
        { x: 1, y: 2, label: 'Point 1' },
        { x: 2, y: 3, label: 'Point 2' },
        { x: 3, y: 4, label: 'Point 3' },
        { x: 4, y: 5, label: 'Point 4' },
        { x: 5, y: 6, label: 'Point 5' },
      ];
      this.filteredData = this.dataPoints;
      this.isLoading = false;
    }, 2000);
  }

  private filterData() {
    if (this.filterText === '') {
      this.filteredData = this.dataPoints;
    } else {
      this.filteredData = this.dataPoints.filter(item =>
        item.label.toLowerCase().includes(this.filterText.toLowerCase())
      );
    }
  }
}

import { Swiper, SwiperController, Image, Column, Row, Button, ImageFit, FlexAlign } from '@ohos.arkui.UIContext';
import window from '@ohos.window';
import common from '@ohos.app.ability.common';

@Entry
@Component
struct AdaptiveCarousel {
  private swiperController: SwiperController = new SwiperController();
  @State currentIndex: number = 0;
  @State isLandscape: boolean = false;
  @Consume context: common.UIAbilityContext;

  private carouselItems: CarouselItem[] = [
    { id: 1, image: $r('app.media.ic_public_picture1') },
    { id: 2, image: $r('app.media.ic_public_picture2') },
    { id: 3, image: $r('app.media.ic_public_picture3') }
  ];

  async aboutToAppear() {
    let win = await window.getLastWindow(this.context);
    win.on('windowStageEvent', async (event) => {
      if (event === window.WindowSizeChangeReason.ROTATION) {
        let properties = await win.getWindowProperties();
        this.isLandscape = properties.windowRect.width > properties.windowRect.height;
      }
    });
  }

  build() {
    Column() {
      Swiper(this.swiperController) {
        ForEach(this.carouselItems, (item: CarouselItem) => {
          Image(item.image)
            .width(this.isLandscape ? '50%' : '100%')
            .height(this.isLandscape ? 200 : 300)
            .objectFit(ImageFit.Cover);
        });
      }
      .autoPlay(true)
      .interval(3000)
      .loop(true)
      .duration(500)
      .indicator(true)
      .onChange((index: number) => {
        this.currentIndex = index;
      });

      Row({ space: 20 }) {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });
        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });
      }
      .margin({ top: 20 })
      .justifyContent(FlexAlign.Center);
    }
    .width('100%')
    .height('100%')
    .padding(16);
  }
}

interface CarouselItem {
  id: number;
  image: Resource;
}

import { SideBarContainer, SideBarPosition } from '@ohos.arkui.advanced';
import { Column, Row, Text, Button } from '@ohos.arkui.component';
import { Card } from '@ohos.arkui.component';
import { FontWeight } from '@ohos.arkui.advanced';
import geoLocation from '@ohos.geolocation';
import abilityAccessCtrl from '@ohos.abilityAccessCtrl';
import common from '@ohos.app.ability.common';
import { BusinessError } from '@ohos.base';

@Entry
@Component
struct NavigationDrawerApp {
  @State isDrawerOpen: boolean = false;
  @State currentScreen: string = 'Home';
  @State location: string = '';
  @State isLoading: boolean = false;
  @State error: string = '';

  aboutToAppear() {
    let permissions: Array<abilityAccessCtrl.Permissions> = [
      abilityAccessCtrl.Permissions.ACCESS_LOCATION,
      abilityAccessCtrl.Permissions.ACCESS_APPROXIMATE_LOCATION
    ];
    let atManager = abilityAccessCtrl.createAtManager();
    atManager.requestPermissionsFromUser(getContext(this) as common.UIAbilityContext, permissions).then((data) => {
      console.log('Permission request result:', data);
    }).catch((err: BusinessError) => {
      console.error('Permission request failed:', err);
      this.error = 'Location permission denied';
    });
  }

  build() {
    Column() {
      SideBarContainer({
        drawerWidth: '250px',
        drawerPosition: SideBarPosition.Start,
        isDrawerOpen: this.isDrawerOpen,
        onDrawerStateChange: (isOpen: boolean) => {
          this.isDrawerOpen = isOpen;
        }
      }) {
        Column() {
          if (this.currentScreen === 'Home') {
            this.HomeScreen();
          } else if (this.currentScreen === 'Location') {
            this.LocationScreen();
          }
        }
        .width('100%')
        .height('100%')

        Column() {
          Text('Menu')
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .padding(16);

          Button('Home')
            .onClick(() => {
              this.currentScreen = 'Home';
              this.isDrawerOpen = false;
            })
            .width('100%')
            .margin({ bottom: 8 });

          Button('Location')
            .onClick(() => {
              this.currentScreen = 'Location';
              this.isDrawerOpen = false;
              this.fetchLocation();
            })
            .width('100%')
            .margin({ bottom: 8 });
        }
        .width('100%')
        .height('100%')
        .backgroundColor('#F5F5F5')
      }
      .width('100%')
      .height('100%')
    }
    .width('100%')
    .height('100%')
  }

  @Builder HomeScreen() {
    Column() {
      Text('Welcome to the Home Screen')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .padding(16);
    }
    .width('100%')
    .height('100%')
  }

  @Builder LocationScreen() {
    Column() {
      if (this.isLoading) {
        Text('Fetching location...')
          .fontSize(16)
          .padding(16);
      } else if (this.error) {
        Text(this.error)
          .fontSize(16)
          .padding(16)
          .color('#FF0000');
      } else {
        Card() {
          Column() {
            Text('Current Location')
              .fontSize(18)
              .fontWeight(FontWeight.Bold)
              .margin({ bottom: 8 });

            Text(this.location)
              .fontSize(16);
          }
          .padding(16)
        }
        .width('90%')
        .margin(16)
      }
    }
    .width('100%')
    .height('100%')
  }

  async fetchLocation() {
    this.isLoading = true;
    this.error = '';
    try {
      let requestInfo: geoLocation.LocationRequest = {
        priority: geoLocation.LocationRequestPriority.FIRST_FIX,
        scenario: geoLocation.LocationRequestScenario.UNSET,
        timeInterval: 1,
        distanceInterval: 0,
        maxAccuracy: 0
      };
      let location = await geoLocation.getCurrentLocation(requestInfo);
      this.location = `Latitude: ${location.latitude.toFixed(6)}, Longitude: ${location.longitude.toFixed(6)}`;
    } catch (err) {
      if (err instanceof BusinessError) {
        this.error = 'Location error: ' + err.message;
      } else {
        this.error = 'Failed to fetch location';
      }
    } finally {
      this.isLoading = false;
    }
  }
}

