import { Video, VideoController } from '@ohos.multimedia.video';
import promptAction from '@ohos.promptAction';
import { Tabs, TabContent } from '@ohos.arkui.tabs';

interface PreparedEvent {
  duration: number;
}

interface UpdateEvent {
  time: number;
}

@Entry
@Component
struct VideoPlayer {
  private videoController: VideoController = new VideoController();
  @State isPlaying: boolean = false;
  @State currentTime: number = 0;
  @State duration: number = 0;
  @State activeTab: number = 0;

  build() {
    Column() {
      Tabs() {
        TabContent() {
          Column() {
            Video({
              src: $rawfile('video.mp4'),
              controller: this.videoController
            })
            .controls(false)
            .autoPlay(false)
            .loop(false)
            .onPrepared((event: PreparedEvent) => {
              this.duration = event.duration;
            })
            .onUpdate((event: UpdateEvent) => {
              this.currentTime = event.time;
            })
            .onError(() => {
              promptAction.showToast({ duration: 2000, message: "Video playback error." });
            })
            .width("100%")
            .height(300);

            Slider({
              value: this.currentTime,
              min: 0,
              max: this.duration,
              step: 1
            })
            .onChange((value: number) => {
              this.videoController.seek(value);
            })
            .width("100%")
            .margin({ top: 10 });

            Row({ space: 20 }) {
              Button(this.isPlaying ? "Pause" : "Play")
                .onClick(() => {
                  if (this.isPlaying) {
                    this.videoController.pause();
                  } else {
                    this.videoController.start();
                  }
                  this.isPlaying = !this.isPlaying;
                });

              Button("Stop")
                .onClick(() => {
                  this.videoController.stop();
                  this.isPlaying = false;
                  this.currentTime = 0;
                });
            }
            .margin({ top: 20 });

            Row({ space: 10 }) {
              Text(`Time: ${this.currentTime.toFixed(2)}`);
              Text("/");
              Text(`Duration: ${this.duration.toFixed(2)}`);
            }
            .margin({ top: 10 });
          }
          .padding(20);
        }
        .tabBar("Video");

        TabContent() {
          Column() {
            Text("Settings")
              .fontSize(20)
              .margin({ bottom: 20 });
          }
          .padding(20);
        }
        .tabBar("Settings");
      }
      .width("100%")
      .height("100%");
    }
    .width("100%")
    .height("100%");
  }
}

