import promptAction from '@ohos.promptAction';
import { Button, Column, Text, Image, Toggle, ToggleType } from '@ohos.arkui.component';
import configuration from '@ohos.app.ability.Configuration';
import ConfigurationConstant from '@ohos.app.ability.ConfigurationConstant';

@Entry
@Component
struct ThemeSwitcher {
  @State isDarkMode: boolean = false;

  aboutToAppear() {
    this.updateTheme();
  }

  build() {
    Column({ space: 20 }) {
      Button(this.isDarkMode ? 'Switch to Light Mode' : 'Switch to Dark Mode')
        .onClick(() => {
          this.isDarkMode = !this.isDarkMode;
          this.updateTheme();
          promptAction.showToast({ message: this.isDarkMode ? 'Dark Mode Activated' : 'Light Mode Activated' });
        })
        .backgroundColor($r('sys.color.ohos_id_color_background'))
        .fontColor($r('sys.color.ohos_id_color_foreground'))
        .margin({ top: 20 });

      Text('Hello, ArkTS!')
        .fontSize(30)
        .fontColor($r('sys.color.ohos_id_color_text_primary'))
        .margin({ top: 20 });

      Image($r('sys.media.ohos_app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 20 });

      Toggle({ type: ToggleType.Switch, isOn: this.isDarkMode })
        .onChange((isOn: boolean) => {
          this.isDarkMode = isOn;
          this.updateTheme();
        })
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor($r('sys.color.ohos_id_color_background'))
    .onClick(() => {
      this.isDarkMode = !this.isDarkMode;
      this.updateTheme();
    });
  }

  private updateTheme() {
    const config: configuration.Configuration = {
      colorMode: this.isDarkMode ? ConfigurationConstant.ColorMode.COLOR_MODE_DARK : 
                               ConfigurationConstant.ColorMode.COLOR_MODE_LIGHT
    };
    configuration.updateConfiguration(config)
      .then(() => {
        console.log('Configuration updated successfully');
      })
      .catch((error: Error) => {
        console.error('Failed to update configuration:', error);
      });
  }
}

import { Badge, BadgePosition } from '@ohos.arkui.badge';
import { Image } from '@ohos.arkui.component';
import mediaquery from '@ohos.mediaquery';

interface BadgeStyle {
  color: string;
  backgroundColor: string;
}

@Entry
@Component
struct VoiceRecorderStats {
  @State totalRecordings: number = 10;
  @State activeRecordings: number = 3;
  @State totalDuration: number = 120;

  private isLandscape: boolean = false;
  private mediaQueryListener: mediaquery.MediaQueryListener = mediaquery.matchMediaSync('(orientation: landscape)');

  aboutToAppear() {
    this.isLandscape = this.mediaQueryListener.matches;
    this.mediaQueryListener.on('change', (result: mediaquery.MediaQueryResult) => {
      this.isLandscape = result.matches;
    });
  }

  aboutToDisappear() {
    this.mediaQueryListener.off('change');
  }

  build() {
    Column() {
      if (this.isLandscape) {
        Stack() {
          Image($r('app.media.icon'))
            .width(100)
            .height(100)
            .margin(20);

          Row() {
            Badge({
              count: this.totalRecordings,
              position: BadgePosition.TOP_RIGHT,
              style: {
                color: '#FFFFFF',
                backgroundColor: '#0000FF'
              } as BadgeStyle
            });

            Badge({
              count: this.activeRecordings,
              position: BadgePosition.TOP_RIGHT,
              style: {
                color: '#FFFFFF',
                backgroundColor: '#00FF00'
              } as BadgeStyle
            });

            Badge({
              count: this.totalDuration,
              position: BadgePosition.TOP_RIGHT,
              style: {
                color: '#FFFFFF',
                backgroundColor: '#FF0000'
              } as BadgeStyle
            });
          }
          .width('100%')
          .justifyContent(FlexAlign.SpaceBetween)
          .padding(20);
        }
        .width('100%')
        .height('100%');
      } else {
        Text('Please rotate your device to landscape mode.')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .textAlign(TextAlign.Center)
          .margin(20);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

interface Task {
  id: number;
  content: string;
  priority: 'High' | 'Medium' | 'Low';
}

@Entry
@Component
struct TodoListApp {
  @State tasks: Task[] = [];
  @State newTask: string = '';
  @State priority: 'High' | 'Medium' | 'Low' = 'Medium';
  @State filter: 'All' | 'High' | 'Medium' | 'Low' = 'All';

  build() {
    Column() {
      Row() {
        Button('All')
          .onClick(() => { this.filter = 'All'; })
          .width('25%');
        Button('High')
          .onClick(() => { this.filter = 'High'; })
          .width('25%');
        Button('Medium')
          .onClick(() => { this.filter = 'Medium'; })
          .width('25%');
        Button('Low')
          .onClick(() => { this.filter = 'Low'; })
          .width('25%');
      }
      .width('100%')
      .margin({ bottom: 20 });

      Row() {
        TextInput({ placeholder: 'Enter a new task', text: this.newTask })
          .onChange((value: string) => { this.newTask = value; })
          .width('60%');
        TextPicker({ range: ['High', 'Medium', 'Low'], selected: 1 })
          .onChange((value: string | string[], index: number | number[]) => { 
            if (typeof value === 'string') {
              this.priority = value as 'High' | 'Medium' | 'Low';
            }
          })
          .width('20%');
        Button('Add')
          .onClick(() => {
            if (this.newTask.trim()) {
              this.tasks = [...this.tasks, { 
                id: Date.now(), 
                content: this.newTask, 
                priority: this.priority 
              }];
              this.newTask = '';
            }
          })
          .width('20%');
      }
      .width('100%')
      .margin({ bottom: 20 });

      ForEach(this.tasks.filter(task => this.filter === 'All' || task.priority === this.filter), 
        (task: Task) => {
          Row() {
            Text(task.content)
              .fontSize(18)
              .margin({ right: 10 });
            Badge({
              value: task.priority,
              position: BadgePosition.Right,
              style: { 
                color: task.priority === 'High' ? Color.Red : 
                       task.priority === 'Medium' ? Color.Orange : Color.Green 
              }
            });
            Button('Remove')
              .onClick(() => {
                this.tasks = this.tasks.filter(t => t.id !== task.id);
              });
          }
          .width('100%')
          .margin({ bottom: 10 });
        }
      );
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

import { Swiper, SwiperController } from '@ohos.arkui';
import { Image, Column, Row, Button, Stack } from '@ohos.arkui';
import { State } from '@ohos.arkui';
import { ForEach } from '@ohos.arkui';
import { FlexAlign, Resource } from '@ohos.arkui';

@Entry
@Component
struct ComicReader {
  private swiperController: SwiperController = new SwiperController();
  private pageCache: Map<number, Resource> = new Map();
  private totalPages: number = 5;

  @State currentPage: number = 0;

  private preloadPages(): void {
    const preloadRange: number[] = [this.currentPage - 1, this.currentPage + 1];
    preloadRange.forEach((page: number) => {
      if (page >= 0 && page < this.totalPages && !this.pageCache.has(page)) {
        this.pageCache.set(page, $r('app.media.page' + (page + 1)));
      }
    });
  }

  private loadPage(page: number): Resource {
    if (!this.pageCache.has(page)) {
      this.pageCache.set(page, $r('app.media.page' + (page + 1)));
    }
    return this.pageCache.get(page) as Resource;
  }

  build() {
    Column() {
      Swiper(this.swiperController) {
        ForEach(Array.from({ length: this.totalPages }, (v: undefined, i: number) => i), 
          (item: number) => {
            Stack() {
              Image(this.loadPage(item))
                .width('100%')
                .height('100%')
                .objectFit('contain');
            }
          }, 
          (item: number) => item.toString()
        )
      }
      .width('100%')
      .height('80%')
      .onChange((index: number) => {
        this.currentPage = index;
        this.preloadPages();
      });

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentPage > 0) {
              this.swiperController.showPrevious();
            }
          });

        Button('Next')
          .onClick(() => {
            if (this.currentPage < this.totalPages - 1) {
              this.swiperController.showNext();
            }
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#000000');
  }
}

