import { Text, Column, Row, Button, List, ListItem, TextInput, ActionSheet } from '@ohos.arkui.component';
import media from '@ohos.multimedia.media';
import abilityAccessCtrl from '@ohos.abilityAccessCtrl';
import common from '@ohos.app.ability.common';

interface Item {
  id: number;
  title: string;
  description: string;
}

interface AccelerometerData {
  x: number;
  y: number;
  z: number;
}

@Entry
@Component
struct SearchApp {
  @State items: Item[] = [
    { id: 1, title: 'Apple', description: 'A sweet and crunchy fruit.' },
    { id: 2, title: 'Banana', description: 'A tropical fruit with a soft texture.' },
    { id: 3, title: 'Orange', description: 'A citrus fruit rich in vitamin C.' },
    { id: 4, title: 'Grapes', description: 'Small, sweet fruits often used in winemaking.' },
    { id: 5, title: 'Mango', description: 'A juicy fruit with a unique flavor.' },
    { id: 6, title: 'Pineapple', description: 'A tropical fruit with a spiky exterior.' },
    { id: 7, title: 'Strawberry', description: 'A red, juicy fruit with a sweet taste.' },
    { id: 8, title: 'Watermelon', description: 'A large, refreshing fruit with high water content.' },
    { id: 9, title: 'Cherry', description: 'A small, sweet fruit with a pit.' },
    { id: 10, title: 'Blueberry', description: 'A small, blue fruit rich in antioxidants.' }
  ];

  @State searchText: string = '';
  @State selectedItem: Item | null = null;
  @State accelerometerData: AccelerometerData = { x: 0, y: 0, z: 0 };
  @State audioPlayer: media.AVPlayer | null = null;
  @State isPlaying: boolean = false;
  @State showActionSheet: boolean = false;
  @State context: common.UIAbilityContext = getContext(this) as common.UIAbilityContext;

  filteredItems(): Item[] {
    if (this.searchText.trim() === '') {
      return this.items;
    } else {
      return this.items.filter(item =>
        item.title.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  requestAccelerometerPermission() {
    abilityAccessCtrl.createAtManager().requestPermissionsFromUser(this.context, ['ohos.permission.ACCELEROMETER'])
      .then(() => {
        this.startAccelerometer();
      })
      .catch((err: Error) => {
        console.error('Permission request failed: ' + JSON.stringify(err));
      });
  }

  startAccelerometer() {
    try {
      this.accelerometerData = { x: 0, y: 0, z: 9.8 };
    } catch (e) {
      console.error('Sensor error:', e);
    }
  }

  stopAccelerometer() {
    try {
      this.accelerometerData = { x: 0, y: 0, z: 0 };
    } catch (e) {
      console.error('Sensor error:', e);
    }
  }

  initAudioPlayer() {
    media.createAVPlayer().then((player: media.AVPlayer) => {
      this.audioPlayer = player;
      if (this.audioPlayer) {
        this.audioPlayer.url = 'resource://media/audio_sample.mp3';
      }
    }).catch((err: Error) => {
      console.error('Audio player initialization failed:', err);
    });
  }

  toggleAudioPlayback() {
    if (!this.audioPlayer) {
      this.initAudioPlayer();
    }
    if (this.audioPlayer) {
      if (this.isPlaying) {
        this.audioPlayer.pause();
      } else {
        this.audioPlayer.play();
      }
      this.isPlaying = !this.isPlaying;
    }
  }

  stopAudioPlayback() {
    if (this.audioPlayer) {
      this.audioPlayer.stop();
      this.isPlaying = false;
    }
  }

  build() {
    Column() {
      TextInput({
        placeholder: 'Search items...',
        text: this.searchText
      })
        .width('100%')
        .onChange((value: string) => {
          this.searchText = value;
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      if (this.filteredItems().length > 0) {
        List() {
          ForEach(this.filteredItems(), (item: Item) => {
            ListItem() {
              Text(item.title)
                .fontSize(18)
                .padding(12)
                .onClick(() => {
                  this.selectedItem = item;
                });
            }
            .backgroundColor('#FFFFFF')
            .borderRadius(5)
            .margin({ bottom: 10 });
          }, (item: Item) => item.id.toString());
        }
      } else {
        Text('No items found')
          .fontSize(16)
          .fontColor('#808080')
          .padding(16);
      }

      Column() {
        Text('Accelerometer Data:')
          .fontSize(18)
          .fontWeight(500)
          .margin({ bottom: 8 });
        Text(`X: ${this.accelerometerData.x.toFixed(2)}`)
          .fontSize(16);
        Text(`Y: ${this.accelerometerData.y.toFixed(2)}`)
          .fontSize(16);
        Text(`Z: ${this.accelerometerData.z.toFixed(2)}`)
          .fontSize(16);
      }
      .margin({ top: 16, bottom: 16 });

      Row() {
        Button(this.isPlaying ? 'Pause' : 'Play')
          .onClick(() => {
            this.toggleAudioPlayback();
          })
          .margin({ right: 8 });
        Button('Stop')
          .onClick(() => {
            this.stopAudioPlayback();
          });
      }
      .margin({ bottom: 16 });

      Button('Options')
        .onClick(() => {
          ActionSheet({
            title: 'Options',
            message: 'Choose an action:',
            buttons: [
              {
                text: 'Refresh Sensor Data',
                onClick: () => {
                  this.requestAccelerometerPermission();
                }
              },
              {
                text: 'Reset Search Results',
                onClick: () => {
                  this.searchText = '';
                }
              }
            ]
          }).show();
        })
        .margin({ bottom: 16 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

