import { Column, Text, Button, TextInput, DatePicker, Flex } from '@ohos.arkui.component';
import { Color, FontWeight, FlexDirection } from '@ohos.arkui.component';
import { SwipeGesture, SwipeDirection } from '@ohos.arkui.gesture';

@Entry
@Component
struct TravelPlanner {
  @State destination: string = '';
  @State startDate: Date = new Date();
  @State endDate: Date = new Date();
  @State budget: string = '';
  @State isValid: boolean = false;

  aboutToAppear() {
    this.validateForm();
  }

  validateForm() {
    const isDestinationValid = this.destination.trim() !== '';
    const isBudgetValid = this.budget.trim() !== '';
    const isDateValid = this.endDate > this.startDate;
    this.isValid = isDestinationValid && isBudgetValid && isDateValid;
  }

  handleSubmit() {
    if (this.isValid) {
      console.log('Form submitted successfully!');
    } else {
      console.log('Please fill all fields correctly.');
    }
  }

  build() {
    Flex({ direction: FlexDirection.Column }) {
      Column() {
        Text('Travel Planner')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 });

        TextInput({ placeholder: 'Enter destination' })
          .width('90%')
          .height(40)
          .margin({ bottom: 10 })
          .onChange((value: string) => {
            this.destination = value;
            this.validateForm();
          });

        DatePicker({
          start: new Date('2000-01-01'),
          end: new Date('2030-12-31'),
          selected: this.startDate
        })
          .width('90%')
          .margin({ bottom: 10 })
          .onDateChange((value: Date) => {
            this.startDate = value;
            this.validateForm();
          });

        DatePicker({
          start: new Date('2000-01-01'),
          end: new Date('2030-12-31'),
          selected: this.endDate
        })
          .width('90%')
          .margin({ bottom: 10 })
          .onDateChange((value: Date) => {
            this.endDate = value;
            this.validateForm();
          });

        TextInput({ placeholder: 'Enter budget' })
          .width('90%')
          .height(40)
          .margin({ bottom: 20 })
          .onChange((value: string) => {
            this.budget = value;
            this.validateForm();
          });

        Button('Submit')
          .width('90%')
          .height(40)
          .backgroundColor(this.isValid ? '#007AFF' : '#CCCCCC')
          .onClick(() => {
            this.handleSubmit();
          });
      }
      .width('100%')
      .height('100%')
      .padding(20)
      .backgroundColor(Color.White)
      .gesture(
        SwipeGesture({ direction: SwipeDirection.Horizontal, fingers: 1 })
          .onSwipe(() => {
            this.handleSubmit();
          })
      );
    }
  }
}

import { Refresh, RefreshController, Scroll, Progress, ProgressStyle } from '@ohos.arkui'

@Entry
@Component
struct PullToRefreshComponent {
  @State refreshing: boolean = false
  @State scrollProgress: number = 0
  @State items: string[] = Array.from<number, string>({ length: 20 }, (_, i: number) => `Item ${i + 1}`)
  private refreshController: RefreshController = new RefreshController()

  build() {
    Column() {
      Progress({
        value: this.scrollProgress,
        total: 100,
        style: ProgressStyle.LINEAR
      })
        .width('80%')
        .height(8)
        .margin(10)

      Refresh({
        controller: this.refreshController,
        refreshing: this.refreshing,
        onRefresh: () => {
          this.refreshing = true
          setTimeout(() => {
            this.items = Array.from<number, string>({ length: 20 }, (_, i: number) => `Refreshed Item ${i + 1}`)
            this.refreshing = false
            this.refreshController.finishRefresh()
          }, 1500)
        }
      }) {
        Scroll() {
          Column() {
            ForEach(this.items, (item: string) => {
              Text(item)
                .fontSize(16)
                .padding(10)
                .width('100%')
                .backgroundColor('#f5f5f5')
                .margin({ bottom: 5 })
            })
          }
          .width('100%')
        }
        .onScroll((scrollOffset: number) => {
          this.scrollProgress = Math.min(Math.max(scrollOffset / 100, 0), 100)
        })
      }

      if (this.refreshing) {
        Text('Refreshing...')
          .fontSize(16)
          .padding(10)
          .width('100%')
          .textAlign(TextAlign.Center)
      }
    }
    .width('100%')
    .height('100%')
  }
}

interface PriorityOption {
