import { Column, Row, List, ListItem, Checkbox, Text, Refresh, FlexAlign, Toast } from '@ohos.arkui.advanced';

@Entry
@Component
struct CheckboxList {
  @State items: string[] = ['Option 1', 'Option 2', 'Option 3', 'Option 4', 'Option 5'];
  @State refreshing: boolean = false;
  @State selectedItems: boolean[] = Array(this.items.length).fill(false);

  private loadMoreItems(): void {
    this.refreshing = true;
    setTimeout(() => {
      const newItems = [...this.items, `Option ${this.items.length + 1}`, `Option ${this.items.length + 2}`];
      this.items = newItems;
      this.selectedItems = [...this.selectedItems, false, false];
      this.refreshing = false;
      Toast.show({
        message: 'New items loaded',
        duration: 2000
      });
    }, 1000);
  }

  private handleCheckboxChange(index: number, isChecked: boolean): void {
    const updatedSelection = [...this.selectedItems];
    updatedSelection[index] = isChecked;
    this.selectedItems = updatedSelection;
    Toast.show({
      message: `Checkbox ${isChecked ? 'checked' : 'unchecked'}`,
      duration: 2000
    });
  }

  build() {
    Column() {
      Refresh({
        refreshing: this.refreshing,
        onRefresh: () => this.loadMoreItems()
      }) {
        List() {
          ForEach(this.items, (item: string, index: number) => {
            ListItem() {
              Row() {
                Checkbox({ name: item })
                  .selected(this.selectedItems[index])
                  .onChange((isChecked: boolean) => this.handleCheckboxChange(index, isChecked))
                  .margin(10);
                Text(item)
                  .fontSize(16)
                  .margin(10);
              }
              .width('100%')
              .height(60)
              .justifyContent(FlexAlign.Start)
              .padding(10)
            }
          })
        }
        .width('100%')
        .height('100%')
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
    .padding(10)
  }
}

import { Tabs, TabContent, List, ListItem, Image, Text, Button, Column, Row, ImageFit } from '@ohos.arkui.component';
import { animateTo, EaseInOut } from '@ohos.arkui.animation';
import media from '@ohos.multimedia.media';

class Seat {
  id: number = 0;
  isBooked: boolean = false;
  isSelected: boolean = false;
}

interface Movie {
  id: number;
  title: string;
  description: string;
  poster: Resource;
}

const movie: Movie = {
  id: 1,
  title: 'Inception',
  description: 'A skilled thief who steals corporate secrets through dream-sharing technology is tasked with planting an idea into a CEO\'s mind.',
  poster: $r('app.media.movie_poster')
};

const seats: Seat[] = Array.from({ length: 20 }, (_, i) => {
  let seat = new Seat();
  seat.id = i + 1;
  return seat;
});

@Entry
@Component
struct MovieBookingApp {
  @State currentTab: number = 0;
  @State seatList: Seat[] = seats;
  @State isPlaying: boolean = false;
  private audioPlayer: media.AVPlayer | null = null;

  async aboutToAppear() {
    this.audioPlayer = await media.createAVPlayer();
  }

  build() {
    Column() {
      Tabs({ barPosition: 'start' }) {
        TabContent() {
          Column() {
            Image(movie.poster)
              .width('100%')
              .height(300)
              .objectFit(ImageFit.Cover);
            Text(movie.title)
              .fontSize(24)
              .fontWeight(FontWeight.Bold)
              .padding(16);
            Text(movie.description)
              .fontSize(16)
              .padding(16);
          }
        }.tabBar('Details');

        TabContent() {
          Column() {
            List() {
              ForEach(this.seatList, (seat: Seat) => {
                ListItem() {
                  Image(seat.isBooked ? $r('app.media.seat_booked') : $r('app.media.seat_available'))
                    .width(50)
                    .height(50)
                    .opacity(seat.isSelected ? 0.7 : 1)
                    .onClick(() => {
                      if (!seat.isBooked) {
                        animateTo({
                          duration: 300,
                          curve: EaseInOut
                        }, () => {
                          this.seatList = this.seatList.map(s => {
                            if (s.id === seat.id) {
                              let newSeat = new Seat();
                              newSeat.id = s.id;
                              newSeat.isBooked = s.isBooked;
                              newSeat.isSelected = !s.isSelected;
                              return newSeat;
                            }
                            return s;
                          });
                        });
                      }
                    });
                }
              });
            }
            Button('Book Selected Seats')
              .onClick(() => {
                this.seatList = this.seatList.map(seat => {
                  if (seat.isSelected) {
                    let newSeat = new Seat();
                    newSeat.id = seat.id;
                    newSeat.isBooked = true;
                    newSeat.isSelected = false;
                    return newSeat;
                  }
                  return seat;
                });
              })
              .margin(16);
          }
        }.tabBar('Seats');
      }

      Button(this.isPlaying ? 'Pause Audio' : 'Play Audio')
        .onClick(() => {
          if (this.audioPlayer) {
            if (this.isPlaying) {
              this.audioPlayer.pause();
            } else {
              this.audioPlayer.url = 'resource://rawfile/movie_audio';
              this.audioPlayer.play((err: Error) => {
                if (err) {
                  console.error('Audio playback failed:', err);
                }
              });
            }
            this.isPlaying = !this.isPlaying;
          }
        })
        .margin(16);
    }
  }

  onDestroy() {
    if (this.audioPlayer) {
      this.audioPlayer.release();
    }
  }
}

import { Panel } from '@ohos.arkui.component.Panel';
import { PanGesture } from '@ohos.arkui.gesture';

@Entry
@Component
struct CalculatorApp {
  @State isExpanded: boolean = false;
  @State currentResult: string = '0';
  @State currentInput: string = '';
  @State selectedOperation: string = '+';
  @State selectedIndex: number = 0;
  @State operationHistory: Array<string> = [];

  build() {
    Column() {
      Panel({ isExpanded: this.isExpanded }) {
        Column() {
          Text(this.currentResult)
            .fontSize(40)
            .textAlign(TextAlign.End)
            .width('100%')
            .margin({ bottom: 20 });

          Grid() {
            ForEach(['7', '8', '9', '/', '4', '5', '6', '*', '1', '2', '3', '-', 'C', '0', '=', '+'], (button: string) => {
              GridItem() {
                Button(button)
                  .width('100%')
                  .height(60)
                  .onClick(() => this.handleButtonPress(button));
              }
            });
          }
          .columnsTemplate('1fr 1fr 1fr 1fr')
          .rowsTemplate('1fr 1fr 1fr 1fr')
          .width('100%')
          .height(300);

          Select([
            { value: '+', label: 'Addition' },
            { value: '-', label: 'Subtraction' },
            { value: '*', label: 'Multiplication' },
            { value: '/', label: 'Division' }
          ])
          .selected(this.selectedIndex)
          .onSelect((index: number) => {
            this.selectedIndex = index;
            this.selectedOperation = ['+', '-', '*', '/'][index];
          })
          .width('100%')
          .margin({ top: 20 });
        }
        .width('100%')
        .padding(20);
      }
      .header('Calculator')
      .headerStyle({
        fontSize: 20,
        margin: 10
      })
      .onGesture((event: PanGesture) => {
        if (event.offsetY < -10) {
          this.isExpanded = true;
        } else if (event.offsetY > 10) {
          this.isExpanded = false;
        }
      })
      .width('100%');
    }
    .width('100%')
    .height('100%');
  }

  handleButtonPress(button: string) {
    if (button >= '0' && button <= '9') {
      this.currentInput += button;
      this.currentResult = this.currentInput;
    } else if (button === 'C') {
      this.currentResult = '0';
      this.currentInput = '';
      this.selectedOperation = '+';
      this.selectedIndex = 0;
      this.operationHistory = [];
    } else if (button === '=') {
      this.calculateResult();
    } else {
      this.selectedOperation = button;
      this.currentResult = this.currentInput;
      this.currentInput = '';
    }
  }

  calculateResult() {
    const num1 = parseFloat(this.currentResult);
    const num2 = parseFloat(this.currentInput);
    let calculatedResult = 0;

    switch (this.selectedOperation) {
      case '+':
        calculatedResult = num1 + num2;
        break;
      case '-':
        calculatedResult = num1 - num2;
        break;
      case '*':
        calculatedResult = num1 * num2;
        break;
      case '/':
        if (num2 === 0) {
          this.currentResult = 'Error';
          return;
        }
        calculatedResult = num1 / num2;
        break;
    }

    this.currentResult = calculatedResult.toString();
    this.operationHistory.push(`${num1} ${this.selectedOperation} ${num2} = ${calculatedResult}`);
    this.currentInput = '';
  }
}

import { PanGesture, Gesture, PanGestureEvent } from '@ohos.multimodalinput.gesture';
import { CanvasRenderingContext2D } from '@ohos.graphics.canvas';

@Entry
@Component
struct CalendarStatsApp {
  @State selectedDate: Date = new Date()
  @State displayDate: string = ''
  @State statsData: number[] = [10, 20, 30, 40, 50, 60, 70]
  private context: CanvasRenderingContext2D | null = null

  aboutToAppear() {
    this.updateDisplayDate()
  }

  updateDisplayDate() {
    this.displayDate = this.selectedDate.toLocaleDateString()
  }

  drawBarChart(context: CanvasRenderingContext2D) {
    const canvasWidth = 300
    const canvasHeight = 200
    const barWidth = 30
    const maxValue = Math.max(...this.statsData)
    const scale = canvasHeight / maxValue

    context.clearRect(0, 0, canvasWidth, canvasHeight)
    context.fillStyle = '#007AFF'

    this.statsData.forEach((value, index) => {
      const barHeight = value * scale
      const x = index * (barWidth + 10) + 20
      const y = canvasHeight - barHeight
      context.fillRect(x, y, barWidth, barHeight)
    })
  }

  build() {
    Column() {
      Text('Calendar Statistics')
        .fontSize(28)
        .fontWeight(700)
        .margin({ top: 20, bottom: 20 })

      DatePicker({
        start: new Date('2000-01-01'),
        end: new Date('2030-12-31'),
        selected: this.selectedDate
      })
        .onDateChange((date: Date) => {
          this.selectedDate = date
          this.updateDisplayDate()
        })
        .margin({ bottom: 40 })

      Column() {
        Text('Selected Date:')
          .fontSize(20)
          .fontWeight(500)
          .margin({ bottom: 8 })

        Text(this.displayDate)
          .fontSize(24)
          .fontWeight(700)
          .fontColor('#007AFF')
      }
      .padding(16)
      .borderRadius(12)
      .backgroundColor('#F0F0F0')

      Stack() {
        Gesture(
          PanGesture({ direction: PanDirection.Horizontal })
            .onActionStart(() => {})
            .onActionUpdate((event: PanGestureEvent) => {
              if (event.offsetX > 50) {
                this.statsData = this.statsData.map(() => Math.floor(Math.random() * 70) + 10)
                if (this.context) {
                  this.drawBarChart(this.context)
                }
              }
            })
        ) {
          Canvas()
            .width('100%')
            .height(200)
            .margin({ top: 20 })
            .onReady(() => {
              if (this.context) {
                this.drawBarChart(this.context)
              }
            })
        }
      }
      .width('100%')
      .height(200)
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
  }
}

@Entry
@Component
struct Calculator {
  @StorageLink('result') result: string = '0';
  @StorageLink('currentInput') currentInput: string = '';
  @StorageLink('operator') operator: string = '';
  @StorageLink('themeColor') themeColor: string = '#007AFF';

  build() {
    Column() {
      Text(this.result)
        .fontSize(40)
        .width('100%')
        .textAlign(TextAlign.End)
        .margin({ bottom: 20 })
        .fontColor(this.themeColor)

      Grid() {
        ForEach(['7', '8', '9', '/', '4', '5', '6', '*', '1', '2', '3', '-', 'C', '0', '=', '+'], (button: string) => {
          GridItem() {
            Button(button)
              .width('100%')
              .height(60)
              .backgroundColor(this.themeColor)
              .onClick(() => this.handleButtonPress(button))
          }
        })
      }
      .columnsTemplate('1fr 1fr 1fr 1fr')
      .rowsTemplate('1fr 1fr 1fr 1fr')
      .width('100%')
      .height(300)

      Button('Change Theme')
        .width('80%')
        .height(50)
        .margin({ top: 20 })
        .backgroundColor(this.themeColor)
        .onClick(() => {
          AlertDialog.show({
            title: 'Select Theme Color',
            message: 'Choose a color for the calculator theme',
            buttons: [
              {
                value: 'Blue',
                action: () => { this.themeColor = '#007AFF'; }
              },
              {
                value: 'Red',
                action: () => { this.themeColor = '#FF3B30'; }
              },
              {
                value: 'Green',
                action: () => { this.themeColor = '#34C759'; }
              }
            ]
          })
        })
    }
    .width('100%')
    .padding(20)
    .backgroundColor('#ffffff')
  }

  handleButtonPress(button: string) {
    if (button >= '0' && button <= '9') {
      this.currentInput += button;
      this.result = this.currentInput;
    } else if (button === 'C') {
      this.result = '0';
      this.currentInput = '';
      this.operator = '';
    } else if (button === '=') {
      this.calculateResult();
    } else {
      this.operator = button;
      this.result = this.currentInput;
      this.currentInput = '';
    }
  }

  calculateResult() {
    const num1 = parseFloat(this.result);
    const num2 = parseFloat(this.currentInput);
    let calculatedResult = 0;

    switch (this.operator) {
      case '+':
        calculatedResult = num1 + num2;
        break;
      case '-':
        calculatedResult = num1 - num2;
        break;
      case '*':
        calculatedResult = num1 * num2;
        break;
      case '/':
        if (num2 === 0) {
          AlertDialog.show({
            title: 'Error',
            message: 'Division by zero is not allowed',
            buttons: [{
              value: 'OK',
              action: () => {}
            }]
          });
          return;
        }
        calculatedResult = num1 / num2;
        break;
    }

    this.result = calculatedResult.toString();
    this.currentInput = '';
    this.operator = '';
  }
}

@Entry
@Component
struct TVRatingCalculator {
  @State ratings: number[] = [];
  @State averageRating: number = 0;
  @State inputValue: string = '';

  build() {
    Column() {
      Text('TV Rating Calculator')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })
        .width('100%')
        .textAlign(TextAlign.Center)
        .accessibilityText('TV Rating Calculator heading');

      TextInput({ placeholder: 'Enter TV show name' })
        .width('80%')
        .height(40)
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.inputValue = value;
        })
        .accessibilityText('Input field for TV show name');

      Row() {
        ForEach([1, 2, 3, 4, 5], (index: number) => {
          Image($r('app.media.app_icon'))
            .width(30)
            .height(30)
            .margin({ right: 5 })
            .onClick(() => {
              this.ratings.push(index);
              this.calculateAverageRating();
            })
            .accessibilityText(`Rate ${index} star`);
        });
      }
      .margin({ bottom: 20 });

      Text(`Average Rating: ${this.averageRating.toFixed(2)}`)
        .fontSize(18)
        .fontWeight(FontWeight.Medium)
        .margin({ bottom: 20 })
        .accessibilityText(`Average rating is ${this.averageRating.toFixed(2)}`);

      NavDestination() {
        Text('View Results')
          .fontSize(16)
          .fontWeight(FontWeight.Medium)
          .padding(10)
          .backgroundColor('#6200EE')
          .fontColor(Color.White)
          .borderRadius(8)
          .onClick(() => {
            // Navigation logic will go here
          })
          .accessibilityText('View results button');
      }
      .margin({ bottom: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5');
  }

  calculateAverageRating() {
    if (this.ratings.length > 0) {
      const sum = this.ratings.reduce((acc, curr) => acc + curr, 0);
      this.averageRating = sum / this.ratings.length;
    } else {
      this.averageRating = 0;
    }
  }
}

