import { Column, Text, Button, Flex, Toggle, ToggleType, CustomDialogController } from '@ohos.arkui.advanced';
import { Color } from '@ohos.arkui.advanced';
import { FlexAlign, FlexJustify } from '@ohos.arkui.advanced';

@Component
struct ConfirmQuizDialog {
  controller: CustomDialogController;
  cancel?: () => void;
  confirm?: () => void;

  @State isConfirmed: boolean = false;
  @State showTooltip: boolean = false;

  constructor(controller: CustomDialogController, cancel?: () => void, confirm?: () => void) {
    super();
    this.controller = controller;
    this.cancel = cancel;
    this.confirm = confirm;
  }

  build() {
    Column() {
      Text('Confirm Quiz Submission')
        .fontSize(20)
        .margin({ bottom: 10 });

      Column() {
        Toggle({ type: ToggleType.Checkbox, isOn: this.isConfirmed })
          .onChange((isOn: boolean) => {
            this.isConfirmed = isOn;
          })
          .onHover(() => {
            this.showTooltip = true;
          })
          .onBlur(() => {
            this.showTooltip = false;
          });

        if (this.showTooltip) {
          Text('Check this box to confirm your answers are final.')
            .fontSize(12)
            .margin({ top: 5 })
            .backgroundColor('#F5F5F5')
            .padding(5)
            .borderRadius(4);
        }
      }
      .margin({ bottom: 20 });

      Flex({ justifyContent: FlexJustify.SpaceAround }) {
        Button('Cancel')
          .onClick(() => {
            this.controller.close();
            this.cancel?.();
          });

        Button('Submit')
          .onClick(() => {
            this.controller.close();
            this.confirm?.();
          });
      }
    }
    .width('80%')
    .padding(20)
    .backgroundColor(Color.White)
    .borderRadius(10);
  }
}

