import { Swiper, SwiperController } from '@ohos.arkui.advanced';
import { Canvas, CanvasRenderer } from '@ohos.arkui.drawing';

interface CarouselItem {
  id: number;
  image: Resource;
  title: string;
}

interface AnalyticsData {
  month: string;
  value: number;
}

@Entry
@Component
struct TravelPlanningApp {
  private swiperController: SwiperController = new SwiperController();
  private analyticsData: AnalyticsData[] = [
    { month: 'Jan', value: 150 },
    { month: 'Feb', value: 200 },
    { month: 'Mar', value: 180 },
    { month: 'Apr', value: 220 },
    { month: 'May', value: 250 },
    { month: 'Jun', value: 300 },
  ];

  @State currentIndex: number = 0;
  private maxValue: number = 0;

  private carouselItems: CarouselItem[] = [
    { id: 1, image: $r('app.media.image1'), title: 'Paris' },
    { id: 2, image: $r('app.media.image2'), title: 'Tokyo' },
    { id: 3, image: $r('app.media.image3'), title: 'New York' },
    { id: 4, image: $r('app.media.image4'), title: 'Sydney' },
  ];

  build() {
    Column() {
      Column() {
        Swiper(this.swiperController) {
          ForEach(this.carouselItems, (item: CarouselItem) => {
            Stack() {
              Image(item.image)
                .width('100%')
                .height(300)
                .objectFit(ImageFit.Cover);
              Text(item.title)
                .fontSize(24)
                .fontWeight(FontWeight.Bold)
                .margin({ top: 20, left: 20 })
                .textAlign(TextAlign.Start);
            }
          });
        }
        .width('100%')
        .height(300)
        .autoPlay(true)
        .interval(3000)
        .indicator(true)
        .loop(true)
        .onChange((index: number) => {
          this.currentIndex = index;
        });

        Row() {
          Button('Previous')
            .onClick(() => {
              this.swiperController.showPrevious();
            });
          Button('Next')
            .onClick(() => {
              this.swiperController.showNext();
            });
        }
        .width('100%')
        .justifyContent(FlexAlign.SpaceEvenly)
        .margin({ top: 20 });
      }
      .width('100%')
      .padding(16);

      Column() {
        Canvas()
          .width('100%')
          .height(200)
          .margin({ top: 20 })
          .onReady((context: CanvasRenderer) => {
            try {
              this.drawAnalyticsChart(context);
            } catch (e) {
              console.error('Canvas rendering error:', e);
            }
          });
      }
      .width('100%')
      .padding(16);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }

  aboutToAppear() {
    this.maxValue = Math.max(...this.analyticsData.map(item => item.value));
  }

  private drawAnalyticsChart(context: CanvasRenderer): void {
    const canvasWidth = 300;
    const canvasHeight = 200;
    const barWidth = 30;
    const gap = 10;
    const maxBarHeight = 150;

    context.clearRect(0, 0, canvasWidth, canvasHeight);

    this.analyticsData.forEach((item, index) => {
      const barHeight = (item.value / this.maxValue) * maxBarHeight;
      const x = index * (barWidth + gap);
      const y = canvasHeight - barHeight;

      context.fillStyle = '#4CAF50';
      context.fillRect(x, y, barWidth, barHeight);

      context.fillStyle = '#000';
      context.font = '12px sans-serif';
      context.fillText(item.month, x, canvasHeight - 5);
    });
  }
}

