import { Column, Text, Button, ForEach, Slider, SliderStyle } from '@ohos.arkui';
import { FlexAlign, FontWeight, TextAlign } from '@ohos.arkui';

class QuizQuestion {
  question: string;
  options: Array<string>;
  correctAnswer: number;

  constructor(question: string, options: Array<string>, correctAnswer: number) {
    this.question = question;
    this.options = options;
    this.correctAnswer = correctAnswer;
  }
}

@Entry
@Component
struct QuizApp {
  @State currentQuestionIndex: number = 0;
  @State score: number = 0;
  @State showScore: boolean = false;
  @State showFeedback: boolean = false;
  @State isCorrect: boolean = false;

  private questions: Array<QuizQuestion> = [
    new QuizQuestion(
      'What is the capital of France?',
      ['London', 'Berlin', 'Paris', 'Madrid'],
      2
    ),
    new QuizQuestion(
      'Which planet is closest to the Sun?',
      ['Mars', 'Venus', 'Mercury', 'Jupiter'],
      2
    ),
    new QuizQuestion(
      'What is the largest mammal?',
      ['African Elephant', 'Blue Whale', 'Giraffe', 'Hippopotamus'],
      1
    )
  ];

  checkAnswer(selectedIndex: number) {
    const correct = selectedIndex === this.questions[this.currentQuestionIndex].correctAnswer;
    this.isCorrect = correct;
    if (correct) {
      this.score++;
    }
    this.showFeedback = true;

    setTimeout(() => {
      this.showFeedback = false;
      if (this.currentQuestionIndex < this.questions.length - 1) {
        this.currentQuestionIndex++;
      } else {
        this.showScore = true;
      }
    }, 1000);
  }

  build() {
    Column() {
      if (!this.showScore) {
        Slider({
          value: ((this.currentQuestionIndex + 1) / this.questions.length) * 100,
          min: 0,
          max: 100,
          style: SliderStyle.OutSet
        })
          .width('90%')
          .height(10)
          .margin({ top: 20, bottom: 20 });

        Text(`Question ${this.currentQuestionIndex + 1}/${this.questions.length}`)
          .fontSize(16)
          .margin({ bottom: 10 });

        Text(this.questions[this.currentQuestionIndex].question)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .textAlign(TextAlign.Center)
          .margin({ bottom: 40 })
          .padding({ left: 20, right: 20 });

        ForEach(this.questions[this.currentQuestionIndex].options, (option: string, index: number) => {
          Button(option)
            .width('80%')
            .height(50)
            .margin({ bottom: 10 })
            .backgroundColor(
              this.showFeedback && index === this.questions[this.currentQuestionIndex].correctAnswer
                ? '#4CAF50'
                : '#007AFF'
            )
            .onClick(() => {
              if (!this.showFeedback) {
                this.checkAnswer(index);
              }
            });
        });

        if (this.showFeedback) {
          Text(this.isCorrect ? 'Correct!' : 'Incorrect!')
            .fontSize(20)
            .fontColor(this.isCorrect ? '#4CAF50' : '#F44336')
            .margin({ top: 20 });
        }
      } else {
        Column() {
          Text('Quiz Complete!')
            .fontSize(28)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Your Score: ${this.score}/${this.questions.length}`)
            .fontSize(24)
            .margin({ bottom: 40 });

          Button('Try Again')
            .onClick(() => {
              this.currentQuestionIndex = 0;
              this.score = 0;
              this.showScore = false;
            });
        }
        .justifyContent(FlexAlign.Center);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

@Entry  
@Component  
struct FoodDeliveryApp {  
  @State progressValue: number = 0;  
  @State scaleValue: number = 1;  
  @State data: string[] = [];  
  @State isLoading: boolean = false;  

  aboutToAppear() {  
    this.fetchData();  
  }  

  private fetchData() {  
    this.isLoading = true;  
    this.progressValue = 0;  
    let interval = setInterval(() => {  
      if (this.progressValue < 100) {  
        this.progressValue += 10;  
      } else {  
        clearInterval(interval);  
        this.isLoading = false;  
        this.data = ['Pizza', 'Burger', 'Sushi', 'Pasta'];  
      }  
    }, 500);  
  }  

  build() {  
    Column() {  
      if (this.isLoading) {  
        Progress({  
          value: this.progressValue,  
          total: 100,  
          type: ProgressType.Linear  
        })  
        .size({ width: '80%', height: 20 })  
        .color(Color.Blue);  
        Text('Loading...').fontSize(20).margin(10);  
      } else {  
        List() {  
          ForEach(this.data, (item: string) => {  
            ListItem() {  
              Text(item)  
                .fontSize(30)  
                .gesture(  
                  PinchGesture({ fingers: 2 })  
                    .onActionUpdate((event: GestureEvent) => {  
                      if (event) {  
                        this.scaleValue = event.scale;  
                      }  
                    })  
                );  
            };  
          }, (item: string) => item);  
        };  
      }  
    }  
    .width('100%')  
    .height('100%')  
    .padding(20)  
    .backgroundColor(Color.White);  
  }  
}

import { TimePicker } from '@ohos.arkui.advanced';
import { Stack, Column, Text, Video } from '@ohos.arkui.advanced';
import { Color, Curve } from '@ohos.arkui.advanced';
import { Alignment, FlexAlign } from '@ohos.arkui.advanced';

@Entry
@Component
struct CustomTimePicker {
  @State selectedTime: Date = new Date();
  @State isAnimating: boolean = false;
  @State bgColor: Color = Color.Gray;

  build() {
    Stack({ alignContent: Alignment.Center }) {
      Video({
        src: $rawfile('media/placeholder.mp4')
      })
        .opacity(0.5)
        .width('100%')
        .height('100%');

      Column({ space: 20 }) {
        Text(this.selectedTime.toLocaleTimeString())
          .fontSize(24)
          .fontColor(Color.White);

        TimePicker({
          selected: this.selectedTime
        })
          .onChange((value: TimePickerResult) => {
            this.isAnimating = true;
            this.bgColor = Color.Blue;
            animateTo({
              duration: 500,
              curve: Curve.EaseInOut
            }, () => {
              this.selectedTime = new Date(
                this.selectedTime.getFullYear(),
                this.selectedTime.getMonth(),
                this.selectedTime.getDate(),
                value.hour,
                value.minute,
                this.selectedTime.getSeconds()
              );
              this.isAnimating = false;
              this.bgColor = Color.Gray;
            });
          });
      }
      .width('100%')
      .height('100%')
      .justifyContent(FlexAlign.Center)
      .alignItems(HorizontalAlign.Center)
      .backgroundColor(this.bgColor);
    }
    .width('100%')
    .height('100%');
  }
}

@Entry
@Component
struct WeatherOnboarding {
  @State currentStep: number = 1;
  @State totalSteps: number = 3;

  nextStep(): void {
    if (this.currentStep < this.totalSteps) {
      this.currentStep++;
    }
  }

  prevStep(): void {
    if (this.currentStep > 1) {
      this.currentStep--;
    }
  }

  build() {
    Column() {
      Text(`Step ${this.currentStep} of ${this.totalSteps}`)
        .margin({ top: 20, bottom: 20 });

      Text(this.getStepDescription(this.currentStep))
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row() {
        Button('Previous')
          .onClick(() => this.prevStep())
          .width('40%')
          .margin({ right: 10 });

        Button('Next')
          .onClick(() => this.nextStep())
          .width('40%');
      }
      .justifyContent(FlexAlign.Center)
      .width('100%');
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%');
  }

  private getStepDescription(step: number): string {
    switch (step) {
      case 1:
        return 'Welcome to Weather App! Get started by setting up your location.';
      case 2:
        return 'Choose your preferred weather units (Celsius or Fahrenheit).';
      case 3:
        return 'Enable notifications for weather alerts and updates.';
      default:
        return '';
    }
  }
}

