struct CalendarComponent {
  @State selectedDate: Date = new Date()
  @State isDarkMode: boolean = false

  build() {
    Column() {
      Row() {
        Button(this.isDarkMode ? 'Switch to Light Mode' : 'Switch to Dark Mode')
          .onClick(() => {
            this.isDarkMode = !this.isDarkMode
          })
          .margin({ bottom: 20 })
      }

      DatePicker({
        start: new Date('2000-01-01'),
        end: new Date('2030-12-31'),
        selected: this.selectedDate
      })
      .onDateChange((value: Date) => {
        this.selectedDate = value
        promptAction.showToast({
          message: 'Date selected: ' + value.toLocaleDateString(),
          duration: 2000
        })
      })
      .width('90%')
      .margin({ bottom: 20 })

      Text('Selected Date: ' + this.selectedDate.toLocaleDateString())
        .fontSize(20)
        .margin({ bottom: 20 })

      Button('Confirm Date')
        .onClick(() => {
          promptAction.showDialog({
            title: 'Confirm Date',
            message: 'You selected: ' + this.selectedDate.toLocaleDateString(),
            buttons: [
              {
                text: 'Cancel',
                color: '#FF0000'
              },
              {
                text: 'OK',
                color: '#0000FF'
              }
            ]
          }).then((result: DialogResult) => {
            if (result.index === 1) {
              promptAction.showToast({
                message: 'Date confirmed!',
                duration: 2000
              })
            }
          })
        })
        .width(200)
        .height(50)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .padding(20)
    .backgroundColor(this.isDarkMode ? '#333333' : '#FFFFFF')
  }
}

import { Component, Entry, State } from '@ohos.arkui.base';
import { ForEach, List, ListItem, Row, Column, Text, Button, Image, Divider } from '@ohos.arkui.base';

interface Product {
  id: number;
  name: string;
  price: number;
}

interface CartItem {
  product: Product;
  quantity: number;
}

@Entry
@Component
struct ShoppingCartScreen {
  @State products: Product[] = [
    { id: 1, name: 'Laptop', price: 1200 },
    { id: 2, name: 'Smartphone', price: 800 },
    { id: 3, name: 'Tablet', price: 400 },
    { id: 4, name: 'Headphones', price: 150 },
    { id: 5, name: 'Mouse', price: 50 },
    { id: 6, name: 'Keyboard', price: 100 },
  ];

  @State cartItems: CartItem[] = [];
  @State currentPage: number = 0;
  private itemsPerPage: number = 3;

  private getPaginatedProducts(): Product[] {
    const startIndex = this.currentPage * this.itemsPerPage;
    return this.products.slice(startIndex, startIndex + this.itemsPerPage);
  }

  private addToCart(product: Product): void {
    const existingItem = this.cartItems.find(item => item.product.id === product.id);
    if (existingItem) {
      existingItem.quantity++;
    } else {
      this.cartItems.push({ product, quantity: 1 });
    }
  }

  private removeFromCart(item: CartItem): void {
    this.cartItems = this.cartItems.filter(cartItem => cartItem.product.id !== item.product.id);
  }

  private calculateGrandTotal(): number {
    return this.cartItems.reduce((total, item) => total + (item.product.price * item.quantity), 0);
  }

  build() {
    Column() {
      List() {
        ForEach(this.getPaginatedProducts(), (product: Product) => {
          ListItem() {
            Row() {
              Image($r('app.media.ic_public_app'))
                .width(50)
                .height(50)
                .margin({ right: 10 });

              Column() {
                Text(product.name)
                  .fontSize(18);
                Text(`$${product.price}`)
                  .fontSize(16)
                  .fontColor('#666666');
              }

              Button('Add to Cart')
                .onClick(() => this.addToCart(product))
                .margin({ left: 10 });
            }
            .padding(10);
          }
          .margin({ bottom: 10 });
        });
      }
      .width('100%')
      .layoutWeight(1);

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentPage > 0) this.currentPage--;
          })
          .disabled(this.currentPage === 0)
          .margin({ right: 10 });

        Text(`Page ${this.currentPage + 1}`)
          .fontSize(16);

        Button('Next')
          .onClick(() => {
            if ((this.currentPage + 1) * this.itemsPerPage < this.products.length) this.currentPage++;
          })
          .disabled((this.currentPage + 1) * this.itemsPerPage >= this.products.length)
          .margin({ left: 10 });
      }
      .justifyContent(FlexAlign.Center)
      .width('100%')
      .margin({ top: 10, bottom: 20 });

      Column() {
        Text('Shopping Cart')
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 10 });

        ForEach(this.cartItems, (item: CartItem) => {
          Row() {
            Text(`${item.product.name} x${item.quantity}`)
              .fontSize(16);
            Text(`$${item.product.price * item.quantity}`)
              .fontSize(16)
              .margin({ left: 10 });
            Button('Remove')
              .onClick(() => this.removeFromCart(item))
              .margin({ left: 10 });
          }
          .padding(10)
          .backgroundColor('#F0F0F0')
          .borderRadius(5)
          .margin({ bottom: 10 });
        });

        Divider()
          .color('#CCCCCC')
          .margin({ top: 10, bottom: 10 });

        Text(`Grand Total: $${this.calculateGrandTotal()}`)
          .fontSize(18)
          .fontWeight(FontWeight.Bold);
      }
      .width('100%')
      .padding(10)
      .backgroundColor('#F0F0F0');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

import promptAction from '@ohos.promptAction';
import mediaquery from '@ohos.mediaquery';
import media from '@ohos.multimedia.media';

@Entry
@Component
struct UserOnboardingApp {
  @State private onboardingStep: number = 0;
  @State private showAlert: boolean = false;
  @State private alertMessage: string = '';

  private handleNextStep(): void {
    this.onboardingStep++;
    if (this.onboardingStep === 3) {
      this.alertMessage = 'Onboarding complete!';
      promptAction.showDialog({
        title: 'Onboarding Complete',
        message: this.alertMessage,
        buttons: [
          {
            text: 'OK',
            color: '#000000'
          }
        ]
      }).then((data) => {
        if (data.index === 0) {
          this.handleAlertClose();
        }
      });
    }
  }

  private handleAlertClose(): void {
    this.showAlert = false;
  }

  build() {
    Column() {
      if (this.onboardingStep === 0) {
        Text('Welcome to the Video Streaming App')
          .fontSize(24)
          .margin({ bottom: 20 });
        Button('Get Started')
          .onClick(() => this.handleNextStep())
          .width(200);
      } else if (this.onboardingStep === 1) {
        Text('Step 1: Explore Features')
          .fontSize(24)
          .margin({ bottom: 20 });
        Button('Next')
          .onClick(() => this.handleNextStep())
          .width(200);
      } else if (this.onboardingStep === 2) {
        Text('Step 2: Watch a Video')
          .fontSize(24)
          .margin({ bottom: 20 });
        Button('Finish')
          .onClick(() => this.handleNextStep())
          .width(200);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

