interface SleepRecord {
  id: string;
  date: string;
  duration: number;
  hasNotification: boolean;
}

@Entry
@Component
struct SleepTracker {
  @State sleepData: Array<SleepRecord> = [
    { id: '1', date: '2023-10-01', duration: 7.5, hasNotification: true },
    { id: '2', date: '2023-10-02', duration: 6.0, hasNotification: false },
    { id: '3', date: '2023-10-03', duration: 8.0, hasNotification: true },
    { id: '4', date: '2023-10-04', duration: 7.0, hasNotification: false },
    { id: '5', date: '2023-10-05', duration: 6.5, hasNotification: true }
  ]

  @State selectedId: string = ''

  build() {
    Column() {
      Text('Sleep Tracker')
        .fontSize(24)
        .margin({ bottom: 20 })

      Scroll() {
        Column() {
          ForEach(this.sleepData, (item: SleepRecord) => {
            Column() {
              Row() {
                Text(item.date)
                  .fontSize(18)
                  .margin({ right: 10 })

                if (item.hasNotification) {
                  Badge({ value: '1', style: { color: '#FFFFFF' } })
                    .position({ x: '80%', y: '10%' })
                }

                Text('🌙')
                  .fontSize(30)
                  .margin({ left: 10 })
              }
              .width('100%')
              .justifyContent(FlexAlign.SpaceBetween)
              .margin({ bottom: 10 })

              Text(`Duration: ${item.duration} hours`)
                .fontSize(16)
                .margin({ bottom: 10 })

              Text('🌙')
                .fontSize(100)
                .rotate({ x: 0, y: 0, z: 1, angle: item.duration * 10 })
                .gesture(
                  RotationGesture()
                    .onActionUpdate((event: RotationGestureEvent) => {
                      const index = this.sleepData.findIndex((data) => data.id === item.id)
                      if (index !== -1) {
                        this.sleepData[index].duration = Math.max(0, Math.min(12, item.duration + event.angle / 10))
                      }
                    })
                )
            }
            .width('90%')
            .padding(10)
            .margin({ bottom: 10 })
            .borderRadius(10)
            .backgroundColor('#f0f0f0')
          })
        }
      }
      .height('80%')
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .alignItems(HorizontalAlign.Center)
  }
}

@Entry
@Component
struct AvatarWithFilePicker {
  @State private selectedImage: string = '';
  @State private counterValue: number = 0;
  @State private chartData: number[] = [10, 20, 30, 40, 50];

  private handleImageSelection(): void {
    this.selectedImage = 'avatar_image';
  }

  private incrementCounter(): void {
    this.counterValue += 1;
  }

  private decrementCounter(): void {
    this.counterValue -= 1;
  }

  private updateChartData(): void {
    this.chartData = this.chartData.map(value => value + 5);
  }

  build() {
    Column({ space: 10 }) {
      Text('Avatar with File Picker')
        .fontSize(24)
        .margin({ bottom: 20 });

      if (this.selectedImage) {
        Image(this.selectedImage)
          .width(100)
          .height(100)
          .margin({ bottom: 20 });
      } else {
        Text('No image selected')
          .fontSize(16)
          .margin({ bottom: 20 });
      }

      Button('Select Image')
        .width(200)
        .onClick(() => this.handleImageSelection())
        .margin({ bottom: 20 });

      Row({ space: 10 }) {
        Text('Counter:')
          .fontSize(16);
        Text(this.counterValue.toString())
          .fontSize(16);
      }
      .margin({ bottom: 20 });

      Row({ space: 10 }) {
        Button('+')
          .width(50)
          .onClick(() => this.incrementCounter());
        Button('-')
          .width(50)
          .onClick(() => this.decrementCounter());
      }
      .margin({ bottom: 20 });

      Text('Chart Data:')
        .fontSize(16)
        .margin({ bottom: 10 });

      ForEach(this.chartData, (value: number, index: number) => {
        Text(`Data ${index + 1}: ${value}`)
          .fontSize(14)
          .margin({ bottom: 5 });
      });

      Button('Update Chart Data')
        .width(200)
        .onClick(() => this.updateChartData())
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

import curves from '@ohos.curves';

@Entry
@Component
struct CustomBreadcrumb {
  @State private breadcrumbs: string[] = ['Home', 'Category', 'Product'];
  @State private selectedDate: Date = new Date('2023-10-01');

  @Builder
  BreadcrumbItem(text: string, index: number) {
    Text(text)
      .fontColor(this.breadcrumbs.length - 1 === index ? '#1698CE' : '#6B6B6B')
      .fontSize(16)
      .margin({ right: 8 })
      .onClick(() => {
        this.breadcrumbs = this.breadcrumbs.slice(0, index + 1);
      });
  }

  build() {
    Column() {
      Row() {
        ForEach(this.breadcrumbs, (item: string, index: number) => {
          this.BreadcrumbItem(item, index);
          if (index < this.breadcrumbs.length - 1) {
            Text('>')
              .fontColor('#6B6B6B')
              .fontSize(16)
              .margin({ right: 8 });
          }
        });
      }
      .padding(16)

      DatePicker({
        start: new Date('1970-1-1'),
        end: new Date('2100-1-1'),
        selected: this.selectedDate
      })
      .onDateChange((value: Date) => {
        this.selectedDate = value;
      })
    }
  }
}

@Entry
@Component
struct EventPlannerApp {
  @State events: Array<PlannerEvent> = [
    { id: 1, title: 'Tech Conference', description: 'Annual tech conference for developers.', videoPlaceholder: 'video_placeholder_tech' },
    { id: 2, title: 'Music Festival', description: 'Live music and performances.', videoPlaceholder: 'video_placeholder_music' },
    { id: 3, title: 'Art Exhibition', description: 'Contemporary art showcase.', videoPlaceholder: 'video_placeholder_art' },
    { id: 4, title: 'Business Summit', description: 'Networking and business growth.', videoPlaceholder: 'video_placeholder_business' },
    { id: 5, title: 'Sports Event', description: 'Annual sports championship.', videoPlaceholder: 'video_placeholder_sports' }
  ];

  @State searchText: string = '';
  @State currentPage: number = 1;
  @State itemsPerPage: number = 2;

  filteredEvents(): Array<PlannerEvent> {
    let filtered = this.events;
    if (this.searchText.trim() !== '') {
      filtered = filtered.filter(event =>
        event.title.toLowerCase().includes(this.searchText.toLowerCase()) ||
        event.description.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
    const startIndex = (this.currentPage - 1) * this.itemsPerPage;
    return filtered.slice(startIndex, startIndex + this.itemsPerPage);
  }

  totalPages(): number {
    return Math.ceil(this.events.length / this.itemsPerPage);
  }

  build() {
    Column() {
      TextInput({
        placeholder: 'Search events...',
        text: this.searchText
      })
        .width('90%')
        .height(40)
        .margin({ top: 10, bottom: 10 })
        .onChange((value: string) => {
          this.searchText = value;
          this.currentPage = 1;
        })
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      List() {
        ForEach(this.filteredEvents(), (event: PlannerEvent) => {
          ListItem() {
            Column() {
              Image($r(`app.media.${event.videoPlaceholder}`))
                .width('100%')
                .height(150)
                .borderRadius(8)
                .margin({ bottom: 10 });

              Text(event.title)
                .fontSize(18)
                .fontWeight(FontWeight.Bold)
                .margin({ bottom: 5 });

              Text(event.description)
                .fontSize(14)
                .fontColor(Color.Gray)
                .margin({ bottom: 10 });
            }
            .padding(10)
            .backgroundColor(Color.White)
            .borderRadius(8)
            .margin({ bottom: 10 });
          }
        }, (event: PlannerEvent) => event.id.toString());
      }
      .width('100%')
      .height('60%')
      .margin({ bottom: 10 });

      Row() {
        Button('Previous', { type: ButtonType.Normal })
          .onClick(() => {
            if (this.currentPage > 1) {
              this.currentPage--;
            }
          })
          .margin({ right: 10 });

        Text(`Page ${this.currentPage} of ${this.totalPages()}`)
          .fontSize(14);

        Button('Next', { type: ButtonType.Normal })
          .onClick(() => {
            if (this.currentPage < this.totalPages()) {
              this.currentPage++;
            }
          })
          .margin({ left: 10 });
      }
      .justifyContent(FlexAlign.Center)
      .width('100%')
      .margin({ bottom: 10 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }
}

