interface Post {
  id: number;
  username: string;
  content: string;
  audioProgress: number;
}

@Entry
@Component
struct SocialMediaApp {
  @State posts: Post[] = [
    { id: 1, username: 'user1', content: 'Post 1 content', audioProgress: 0 },
    { id: 2, username: 'user2', content: 'Post 2 content', audioProgress: 0 },
    { id: 3, username: 'user3', content: 'Post 3 content', audioProgress: 0 }
  ];
  @State isRecording: boolean = false;
  @State showDialog: boolean = false;
  @State dialogContent: string = '';

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.posts, (post: Post) => {
          ListItem() {
            Column({ space: 8 }) {
              Text(post.username).fontSize(16).fontWeight(FontWeight.Bold);
              Text(post.content).fontSize(14);
              Slider({
                value: post.audioProgress,
                min: 0,
                max: 100,
                step: 1,
                style: SliderStyle.OutSet
              }).onChange((value: number) => {
                this.posts = this.posts.map(p => p.id === post.id ? { id: p.id, username: p.username, content: p.content, audioProgress: value } : p);
              });
              Row({ space: 8 }) {
                Button('Play').onClick(() => {
                  this.posts = this.posts.map(p => p.id === post.id ? { id: p.id, username: p.username, content: p.content, audioProgress: 50 } : p);
                });
                Button('Record').onClick(() => {
                  this.isRecording = !this.isRecording;
                });
              }
            }
            .padding(16)
            .borderRadius(8)
            .backgroundColor('#f5f5f5')
          }
        })
      }
      .layoutWeight(1)
      .width('100%')

      Button('New Post')
        .onClick(() => {
          this.showDialog = true;
          this.dialogContent = '';
        })
        .margin(16)

      if (this.showDialog) {
        Column() {
          TextInput({ placeholder: 'Enter post content', text: this.dialogContent })
            .onChange((value: string) => {
              this.dialogContent = value;
            })
            .margin(16);
          Row({ space: 8 }) {
            Button('Cancel')
              .onClick(() => {
                this.showDialog = false;
              });
            Button('Post')
              .onClick(() => {
                if (this.dialogContent.trim()) {
                  this.posts = [...this.posts, { id: this.posts.length + 1, username: 'currentUser', content: this.dialogContent, audioProgress: 0 }];
                  this.showDialog = false;
                  this.dialogContent = '';
                }
              });
          }
          .margin(16)
        }
        .padding(16)
        .borderRadius(8)
        .backgroundColor('#ffffff')
        .width('80%')
      }
    }
    .width('100%')
    .height('100%')
    .padding(16)
  }
}

interface PanEvent {
  offsetX: number;
}

@Entry
@Component
struct SwipeGestureApp {
  @State swipeMessage: string = "Swipe Here";
  @State showPopup: boolean = false;

  handleSwipe(event: PanEvent) {
    if (event.offsetX > 100) {
      this.swipeMessage = "Swiped Right";
      this.playSound();
      this.showPopup = true;
    } else if (event.offsetX < -100) {
      this.swipeMessage = "Swiped Left";
      this.playSound();
      this.showPopup = true;
    }
  }

  playSound() {
    console.log("Playing swipe sound");
  }

  build() {
    Column() {
      Text(this.swipeMessage)
        .fontSize(20)
        .margin({ bottom: 20 });

      Row()
        .width(300)
        .height(200)
        .backgroundColor(Color.Gray)
        .gesture(
          PanGesture()
            .onActionStart(() => {
              this.swipeMessage = "Swipe Here";
            })
            .onActionUpdate((event: PanEvent) => {
              this.handleSwipe(event);
            })
            .onActionEnd(() => {
              this.swipeMessage = "Swipe Here";
            })
        );

      if (this.showPopup) {
        Text("Swipe Confirmed")
          .fontSize(18)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

@Entry
@Component
struct CountdownTimer {
  @State timeLeft: number = 60;
  @State isRunning: boolean = false;
  private timerId: number = -1;
  @State messages: string[] = ["Promotional Message 1", "Promotional Message 2"];
  @State currentMessageIndex: number = 0;
  @State rating: number = 3;
  @State showRating: boolean = false;

  startTimer() {
    if (!this.isRunning) {
      this.isRunning = true;
      this.timerId = setInterval(() => {
        if (this.timeLeft > 0) {
          this.timeLeft -= 1;
        } else {
          this.stopTimer();
          this.logCompletion();
          this.showRating = true;
          this.currentMessageIndex = (this.currentMessageIndex + 1) % this.messages.length;
        }
      }, 1000);
    }
  }

  stopTimer() {
    this.isRunning = false;
    clearInterval(this.timerId);
  }

  resetTimer() {
    this.stopTimer();
    this.timeLeft = 60;
  }

  logCompletion() {
    const timestamp = new Date().toISOString();
    const logEntry = `Timer completed at ${timestamp} with duration 60 seconds\n`;
    console.log(logEntry); // Replace with actual file write operation
  }

  saveRating() {
    console.log(`Rating saved: ${this.rating}`); // Replace with actual storage operation
    this.showRating = false;
    this.resetTimer();
  }

  build() {
    Column() {
      // Marquee Component
      Text(this.messages[this.currentMessageIndex])
        .fontSize(16)
        .margin({ bottom: 20 })
        .width('100%')
        .textAlign(TextAlign.Center);

      // Timer Display
      Text(`${this.timeLeft} seconds`)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      // Timer Controls
      Row() {
        Button(this.isRunning ? 'Stop' : 'Start')
          .onClick(() => {
            if (this.isRunning) {
              this.stopTimer();
            } else {
              this.startTimer();
            }
          })
          .margin({ right: 10 });

        Button('Reset')
          .onClick(() => {
            this.resetTimer();
          });
      }
      .justifyContent(FlexAlign.Center)
      .margin({ bottom: 20 });

      // Rating Component
      if (this.showRating) {
        Column() {
          Text('Rate your experience:')
            .fontSize(16)
            .margin({ bottom: 10 });

          Row() {
            ForEach([1, 2, 3, 4, 5], (star: number) => {
              Button(star <= this.rating ? '\u2605' : '\u2606')
                .onClick(() => {
                  this.rating = star;
                })
                .margin({ right: 5 });
            });
          }
          .justifyContent(FlexAlign.Center);

          Button('Submit Rating')
            .onClick(() => {
              this.saveRating();
            })
            .margin({ top: 10 });
        }
        .width('100%')
        .alignItems(HorizontalAlign.Center);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }
}

@Entry
@Component
struct QuizApp {
  @State currentQuestionIndex: number = 0;
  @State score: number = 0;
  @State showScore: boolean = false;
  @State showFeedback: boolean = false;
  @State isCorrect: boolean = false;
  @State searchQuery: string = '';
  @State filteredQuestions: Array<QuizQuestion> = [];

  private questions: Array<QuizQuestion> = [
    new QuizQuestion(
      'What is the capital of France?',
      ['London', 'Berlin', 'Paris', 'Madrid'],
      2
    ),
    new QuizQuestion(
      'Which planet is closest to the Sun?',
      ['Mars', 'Venus', 'Mercury', 'Jupiter'],
      2
    ),
    new QuizQuestion(
      'What is the largest mammal?',
      ['African Elephant', 'Blue Whale', 'Giraffe', 'Hippopotamus'],
      1
    )
  ];

  checkAnswer(selectedIndex: number) {
    const correct = selectedIndex === this.questions[this.currentQuestionIndex].correctAnswer;
    this.isCorrect = correct;
    if (correct) {
      this.score++;
    }
    this.showFeedback = true;

    setTimeout(() => {
      this.showFeedback = false;
      if (this.currentQuestionIndex < this.questions.length - 1) {
        this.currentQuestionIndex++;
      } else {
        this.showScore = true;
      }
    }, 1000);
  }

  filterQuestions() {
    if (this.searchQuery.trim() === '') {
      this.filteredQuestions = [...this.questions];
    } else {
      this.filteredQuestions = this.questions.filter(question =>
        question.question.toLowerCase().includes(this.searchQuery.toLowerCase())
      );
    }
  }

  build() {
    Column() {
      // Search Bar
      TextInput({ placeholder: 'Search questions...' })
        .width('90%')
        .height(40)
        .margin({ top: 20, bottom: 20 })
        .onChange((value: string) => {
          this.searchQuery = value;
          this.filterQuestions();
        });

      if (!this.showScore) {
        // Progress bar
        Progress({
          value: ((this.currentQuestionIndex + 1) / this.questions.length) * 100,
          total: 100
        })
          .width('90%')
          .height(10)
          .margin({ bottom: 20 });

        // Question
        Text(`Question ${this.currentQuestionIndex + 1}/${this.questions.length}`)
          .fontSize(16)
          .margin({ bottom: 10 });

        Text(this.questions[this.currentQuestionIndex].question)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .textAlign(TextAlign.Center)
          .margin({ bottom: 40 })
          .padding({ left: 20, right: 20 });

        // Options
        ForEach(this.questions[this.currentQuestionIndex].options, (option: string, index: number) => {
          Button(option)
            .width('80%')
            .height(50)
            .margin({ bottom: 10 })
            .backgroundColor(this.showFeedback && index === this.questions[this.currentQuestionIndex].correctAnswer ? '#4CAF50' : '#007AFF')
            .onClick(() => {
              if (!this.showFeedback) {
                this.checkAnswer(index);
              }
            });
        });

        // Feedback
        if (this.showFeedback) {
          Text(this.isCorrect ? 'Correct!' : 'Incorrect!')
            .fontSize(20)
            .fontColor(this.isCorrect ? '#4CAF50' : '#F44336')
            .margin({ top: 20 });
        }
      } else {
        // Final score
        Column() {
          Text('Quiz Complete!')
            .fontSize(28)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Your Score: ${this.score}/${this.questions.length}`)
            .fontSize(24)
            .margin({ bottom: 40 });

          Button('Try Again')
            .onClick(() => {
              this.currentQuestionIndex = 0;
              this.score = 0;
              this.showScore = false;
            });
        }
        .justifyContent(FlexAlign.Center);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

class QuizQuestion {
  question: string;
  options: Array<string>;
  correctAnswer: number;

  constructor(question: string, options: Array<string>, correctAnswer: number) {
    this.question = question;
    this.options = options;
    this.correctAnswer = correctAnswer;
  }
}

