@Entry
@Component
struct CountdownTimer {
  @State private timeLeft: number = 60;
  @State private isRunning: boolean = false;
  @State private isDarkMode: boolean = false;
  private timerId: number = -1;

  private startTimer() {
    if (!this.isRunning) {
      this.isRunning = true;
      this.timerId = setInterval(() => {
        if (this.timeLeft > 0) {
          this.timeLeft -= 1;
        } else {
          this.stopTimer();
        }
      }, 1000);
    }
  }

  private stopTimer() {
    this.isRunning = false;
    clearInterval(this.timerId);
  }

  private resetTimer() {
    this.stopTimer();
    this.timeLeft = 60;
  }

  private toggleDarkMode() {
    this.isDarkMode = !this.isDarkMode;
  }

  build() {
    Column({ space: 10 }) {
      Text(`${this.timeLeft} seconds`)
        .fontSize(24)
        .fontColor(this.isDarkMode ? Color.White : Color.Black)
        .margin(10)
        .width('80%')
        .textAlign(TextAlign.Center)
        .backgroundColor(this.isDarkMode ? '#333333' : '#ffe5c2c2')
        .padding(10);

      Row({ space: 20 }) {
        Button(this.isRunning ? 'Stop' : 'Start')
          .onClick(() => {
            if (this.isRunning) {
              this.stopTimer();
            } else {
              this.startTimer();
            }
          })
          .backgroundColor(this.isRunning ? '#ff5722' : '#4caf50')
          .fontColor(Color.White)
          .padding(10)
          .margin(5)
          .borderRadius(5);

        Button('Reset')
          .onClick(() => {
            this.resetTimer();
          })
          .backgroundColor('#2196f3')
          .fontColor(Color.White)
          .padding(10)
          .margin(5)
          .borderRadius(5);
      }
      .justifyContent(FlexAlign.Center)
      .width('80%')
      .margin(10);

      Toggle({ type: ToggleType.Switch, isOn: this.isDarkMode })
        .onChange((isOn: boolean) => {
          this.toggleDarkMode();
        })
        .margin(10)
        .width('80%');

      Column() {
        Text('Map Placeholder')
          .fontSize(16)
          .textAlign(TextAlign.Center)
      }
      .width('80%')
      .height(200)
      .margin(10)
      .backgroundColor('#eeeeee')
      .border({ width: 1, color: '#999999' });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor(this.isDarkMode ? '#121212' : '#ffffff');
  }
}

