@Entry
@Component
struct Main {
  @State sliderValue: number = 50;
  @State progressValue: number = 0;
  @State selectedOption: string = 'Option 1';

  build() {
    Column() {
      // Circular Progress Indicator
      Stack() {
        Circle()
          .width(200)
          .height(200)
          .stroke('#E0E0E0')
          .strokeWidth(10)
          .fill('transparent')

        Circle()
          .width(200)
          .height(200)
          .stroke('#4CAF50')
          .strokeWidth(10)
          .fill('transparent')
          .strokeDashArray([Math.PI * 200, Math.PI * 200])
          .strokeDashOffset(Math.PI * 200 * (1 - this.progressValue / 100))
          .rotate({ x: 0, y: 0, z: 1, angle: -90 })

        Text(`${Math.round(this.progressValue)}%`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
      }
      .width(200)
      .height(200)
      .margin({ top: 40 })

      // Slider
      Slider({
        value: this.sliderValue,
        min: 0,
        max: 100,
        step: 1,
        style: SliderStyle.OutSet
      })
        .width('80%')
        .height(40)
        .trackColor('#4CAF50')
        .backgroundColor('#FFFFFF')
        .onChange((value: number) => {
          this.sliderValue = value;
        })
        .margin({ top: 20 })

      // Radio Buttons
      Column() {
        Radio({ value: 'Option 1', group: 'mode' })
          .checked(this.selectedOption === 'Option 1')
          .onChange((checked: boolean) => {
            if (checked) this.selectedOption = 'Option 1';
          })
          .margin({ top: 10 })

        Radio({ value: 'Option 2', group: 'mode' })
          .checked(this.selectedOption === 'Option 2')
          .onChange((checked: boolean) => {
            if (checked) this.selectedOption = 'Option 2';
          })
          .margin({ top: 10 })

        Radio({ value: 'Option 3', group: 'mode' })
          .checked(this.selectedOption === 'Option 3')
          .onChange((checked: boolean) => {
            if (checked) this.selectedOption = 'Option 3';
          })
          .margin({ top: 10 })
      }
      .margin({ top: 20 })

      // Update Button
      Button('Update Progress')
        .onClick(() => {
          this.progressValue = this.sliderValue;
        })
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

