import media from '@ohos.multimedia.media';
import { AppStorage, LocalStorage, FontWeight, Slider, Button, Column, Text, Row, PromptDialog } from '@ohos.arkui.advanced';
import { BusinessError } from '@ohos.base';

interface Song {
  title: string;
  artist: string;
}

interface PlaybackState {
  currentSong: Song;
  isPlaying: boolean;
  progress: number;
}

type InitialPlaybackState = PlaybackState;

@Entry
@Component
struct MusicPlayer {
  @StorageLink('currentSong') currentSong: Song = { title: '', artist: '' };
  @StorageLink('isPlaying') isPlaying: boolean = false;
  @StorageLink('progress') progress: number = 0;
  private avPlayer: media.AVPlayer | null = null;
  private localStorage: LocalStorage = new LocalStorage({
    'playbackState': {
      currentSong: { title: '', artist: '' },
      isPlaying: false,
      progress: 0
    } as InitialPlaybackState
  });

  aboutToAppear(): void {
    media.createAVPlayer().then((player: media.AVPlayer) => {
      this.avPlayer = player;
      this.avPlayer.on('stateChange', (state: string) => {
        if (state === 'playing') {
          this.isPlaying = true;
        } else if (state === 'paused' || state === 'stopped') {
          this.isPlaying = false;
        }
      });

      this.avPlayer.on('timeUpdate', (currentTime: number) => {
        this.progress = currentTime;
      });

      this.avPlayer.on('error', (err: BusinessError) => {
        console.error(`Media error: ${err.message}`);
      });

      let savedState = this.localStorage.get<PlaybackState>('playbackState');
      if (savedState) {
        this.currentSong = savedState.currentSong;
        this.isPlaying = savedState.isPlaying;
        this.progress = savedState.progress;
      }
    }).catch((err: BusinessError) => {
      console.error(`Failed to create AVPlayer: ${err.message}`);
    });
  }

  aboutToDisappear(): void {
    if (this.avPlayer) {
      this.avPlayer.release();
    }
  }

  playPause(): void {
    if (this.avPlayer) {
      if (this.isPlaying) {
        this.avPlayer.pause();
      } else {
        this.avPlayer.play();
      }
    }
  }

  stop(): void {
    if (this.avPlayer) {
      this.avPlayer.stop();
      this.progress = 0;
    }
  }

  deleteSong(): void {
    PromptDialog.show({
      title: 'Delete Song',
      message: 'Are you sure you want to delete this song?',
      buttons: [
        {
          text: 'Cancel',
          color: '#000000'
        },
        {
          text: 'Delete',
          color: '#000000'
        }
      ]
    }).then((result: { index: number }) => {
      if (result.index === 1) {
        this.currentSong = { title: '', artist: '' };
        this.isPlaying = false;
        this.progress = 0;
        this.localStorage.set('playbackState', { 
          currentSong: this.currentSong, 
          isPlaying: this.isPlaying, 
          progress: this.progress 
        });
      }
    });
  }

  build() {
    Column() {
      Text(this.currentSong.title)
        .fontSize(24)
        .fontWeight(FontWeight.Bold);
      Text(this.currentSong.artist)
        .fontSize(18)
        .margin({ top: 8 });

      Slider({
        value: this.progress,
        min: 0,
        max: this.avPlayer ? this.avPlayer.duration : 100,
        onChange: (value: number) => {
          if (this.avPlayer) {
            this.avPlayer.seek(value);
          }
        }
      })
        .margin({ top: 16 });

      Row() {
        Button(this.isPlaying ? 'Pause' : 'Play')
          .onClick(() => this.playPause())
          .margin({ right: 16 });
        Button('Stop')
          .onClick(() => this.stop())
          .margin({ right: 16 });
        Button('Delete')
          .onClick(() => this.deleteSong());
      }
      .margin({ top: 16 });
    }
    .padding(16);
  }
}

import { PersistentStorage } from '@ohos.data.storage';

class QuizQuestion {
  question: string;
  options: string[];
  correctAnswer: number;

  constructor(question: string, options: string[], correctAnswer: number) {
    this.question = question;
    this.options = options;
    this.correctAnswer = correctAnswer;
  }
}

@Entry
@Component
struct QuizApp {
  @PersistStorageProp('isDarkMode') isDarkMode: boolean = false;
  @State currentQuestionIndex: number = 0;
  @State score: number = 0;
  @State showScore: boolean = false;
  @State showFeedback: boolean = false;
  @State isCorrect: boolean = false;

  private questions: QuizQuestion[] = [
    new QuizQuestion(
      'What is the capital of France?',
      ['London', 'Berlin', 'Paris', 'Madrid'],
      2
    ),
    new QuizQuestion(
      'Which planet is closest to the Sun?',
      ['Mars', 'Venus', 'Mercury', 'Jupiter'],
      2
    ),
    new QuizQuestion(
      'What is the largest mammal?',
      ['African Elephant', 'Blue Whale', 'Giraffe', 'Hippopotamus'],
      1
    ),
    new QuizQuestion(
      'What is the chemical symbol for gold?',
      ['Go', 'Gd', 'Au', 'Ag'],
      2
    ),
    new QuizQuestion(
      'Who painted the Mona Lisa?',
      ['Vincent van Gogh', 'Pablo Picasso', 'Leonardo da Vinci', 'Claude Monet'],
      2
    )
  ];

  toggleTheme() {
    this.isDarkMode = !this.isDarkMode;
  }

  checkAnswer(selectedIndex: number) {
    const correct = selectedIndex === this.questions[this.currentQuestionIndex].correctAnswer;
    this.isCorrect = correct;
    if (correct) {
      this.score++;
    }
    this.showFeedback = true;

    setTimeout(() => {
      this.showFeedback = false;
      if (this.currentQuestionIndex < this.questions.length - 1) {
        this.currentQuestionIndex++;
      } else {
        this.showScore = true;
      }
    }, 1000);
  }

  nextQuestion() {
    if (this.currentQuestionIndex < this.questions.length - 1) {
      this.currentQuestionIndex++;
    }
  }

  prevQuestion() {
    if (this.currentQuestionIndex > 0) {
      this.currentQuestionIndex--;
    }
  }

  build() {
    Column() {
      Row() {
        Text('Dark Mode')
          .fontSize(16)
          .margin({ right: 10 });
        Toggle({ type: ToggleType.Switch, isOn: this.isDarkMode })
          .onChange((isOn: boolean) => {
            this.toggleTheme();
          });
      }
      .margin({ top: 20, bottom: 20 })
      .justifyContent(FlexAlign.Center);

      if (!this.showScore) {
        Progress({
          value: ((this.currentQuestionIndex + 1) / this.questions.length) * 100,
          total: 100,
          style: ProgressStyle.Linear
        })
          .width('90%')
          .height(10)
          .margin({ top: 20, bottom: 20 });

        Text(`Question ${this.currentQuestionIndex + 1}/${this.questions.length}`)
          .fontSize(16)
          .margin({ bottom: 10 });

        Text(this.questions[this.currentQuestionIndex].question)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .textAlign(TextAlign.Center)
          .margin({ bottom: 40 })
          .padding({ left: 20, right: 20 });

        ForEach(this.questions[this.currentQuestionIndex].options, (option: string, index: number) => {
          Button(option)
            .width('80%')
            .height(50)
            .margin({ bottom: 10 })
            .backgroundColor(this.showFeedback && index === this.questions[this.currentQuestionIndex].correctAnswer ? '#4CAF50' : '#007AFF')
            .onClick(() => {
              if (!this.showFeedback) {
                this.checkAnswer(index);
              }
            });
        });

        Row() {
          Button('Previous')
            .enabled(this.currentQuestionIndex > 0)
            .onClick(() => this.prevQuestion())
            .margin({ right: 10 });
          Button('Next')
            .enabled(this.currentQuestionIndex < this.questions.length - 1)
            .onClick(() => this.nextQuestion())
            .margin({ left: 10 });
        }
        .margin({ top: 20 })
        .justify

import { Column, Row, Text, Image, Grid, GridItem, Toggle } from '@ohos.arkui.advancedUI';
import { FlexAlign, FontWeight, ToggleType } from '@ohos.arkui.advancedUI';

interface Product {
  id: number;
  name: string;
  image: Resource;
  price: number;
  category: string;
}

interface Category {
  id: number;
  name: string;
  products: Product[];
}

@Entry
@Component
struct ECommerceUI {
  @State categories: Category[] = [
    {
      id: 1,
      name: 'Electronics',
      products: [
        { id: 101, name: 'Laptop', image: $r('app.media.icon'), price: 1200, category: 'Electronics' },
        { id: 102, name: 'Smartphone', image: $r('app.media.icon'), price: 800, category: 'Electronics' },
      ],
    },
    {
      id: 2,
      name: 'Fashion',
      products: [
        { id: 201, name: 'T-Shirt', image: $r('app.media.icon'), price: 25, category: 'Fashion' },
        { id: 202, name: 'Jeans', image: $r('app.media.icon'), price: 45, category: 'Fashion' },
      ],
    },
  ];

  @State expandedCategoryIds: number[] = [];
  @State filterUnder50: boolean = false;

  toggleCategory(categoryId: number): void {
    if (this.expandedCategoryIds.includes(categoryId)) {
      this.expandedCategoryIds = this.expandedCategoryIds.filter(id => id !== categoryId);
    } else {
      this.expandedCategoryIds = [...this.expandedCategoryIds, categoryId];
    }
  }

  getFilteredProducts(products: Product[]): Product[] {
    return this.filterUnder50 ? products.filter(product => product.price < 50) : products;
  }

  build() {
    Column() {
      Row() {
        Text('Filter by Price')
          .fontSize(16)
          .margin({ right: 10 });
        Toggle({ type: ToggleType.Switch, isOn: this.filterUnder50 })
          .onChange((isOn: boolean) => {
            this.filterUnder50 = isOn;
          });
      }
      .padding(10)
      .justifyContent(FlexAlign.Start);

      ForEach(this.categories, (category: Category) => {
        Column() {
          Row() {
            Text(category.name)
              .fontSize(18)
              .fontWeight(FontWeight.Bold);
            Image($r('app.media.icon'))
              .width(20)
              .height(20)
              .margin({ left: 10 })
              .onClick(() => this.toggleCategory(category.id));
          }
          .padding(10)
          .borderRadius(10)
          .backgroundColor('#f0f0f0')
          .width('100%');

          if (this.expandedCategoryIds.includes(category.id)) {
            Grid() {
              ForEach(this.getFilteredProducts(category.products), (product: Product) => {
                GridItem() {
                  Column() {
                    Image(product.image)
                      .width(100)
                      .height(100)
                      .borderRadius(10);
                    Text(product.name)
                      .fontSize(14)
                      .margin({ top: 5 });
                    Text(`$${product.price}`)
                      .fontSize(12)
                      .fontColor('#666');
                  }
                  .padding(10)
                  .borderRadius(10)
                  .backgroundColor('#ffffff')
                  .margin(5);
                }
              });
            }
            .columnsTemplate('1fr 1fr')
            .columnsGap(10)
            .rowsGap(10)
            .padding(10);
          }
        }
        .margin({ bottom: 10 });
      });
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff');
  }
}

