interface Note {
  id: number;
  title: string;
  content: string;
  priority: number;
}

@Entry
@Component
struct NoteApp {
  @State notes: Note[] = [];
  @State newNoteTitle: string = '';
  @State newNoteContent: string = '';
  @State priority: number = 1;

  build() {
    Column() {
      TextInput({ placeholder: 'Enter note title...', text: this.newNoteTitle })
        .height(50)
        .width('90%')
        .onChange((value: string) => {
          this.newNoteTitle = value;
        })
        .margin(10);

      TextArea({ placeholder: 'Enter note content...', text: this.newNoteContent })
        .height(150)
        .width('90%')
        .onChange((value: string) => {
          this.newNoteContent = value;
        })
        .margin(10);

      Row() {
        Text('Priority:')
          .fontSize(16)
          .margin({ right: 10 });
        Button('-')
          .onClick(() => {
            if (this.priority > 1) {
              this.priority--;
            }
          })
          .width(40);
        Text(this.priority.toString())
          .fontSize(16)
          .margin({ left: 10, right: 10 });
        Button('+')
          .onClick(() => {
            if (this.priority < 5) {
              this.priority++;
            }
          })
          .width(40);
      }
      .margin(10);

      Button('Add Note')
        .onClick(() => {
          if (this.newNoteTitle.trim() && this.newNoteContent.trim()) {
            this.notes.push({
              id: Date.now(),
              title: this.newNoteTitle,
              content: this.newNoteContent,
              priority: this.priority
            });
            this.newNoteTitle = '';
            this.newNoteContent = '';
            this.priority = 1;
          }
        })
        .margin(10);

      Grid() {
        ForEach(this.notes, (note: Note) => {
          GridItem() {
            Column() {
              Text(note.title)
                .fontSize(18)
                .fontWeight(FontWeight.Bold);
              Text(note.content)
                .fontSize(14)
                .margin({ top: 5 });
              Text(`Priority: ${note.priority}`)
                .fontSize(12)
                .fontColor(Color.Gray)
                .margin({ top: 5 });
              Button('Delete')
                .onClick(() => {
                  this.notes = this.notes.filter(n => n.id !== note.id);
                })
                .margin({ top: 10 });
            }
            .padding(10)
            .width('100%')
          }
        })
      }
      .columnsTemplate('1fr 1fr')
      .rowsTemplate('auto')
      .width('100%')
      .height('100%')
      .margin(10);
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

