import { ActionSheet } from '@ohos.arkui.advanced';
import { Gesture, PinchGestureEvent } from '@ohos.arkui.gesture';
import { Column, Text, Button, Stack, Image } from '@ohos.arkui.component';
import { Color, ImageFit, FontWeight, FlexAlign, HorizontalAlign } from '@ohos.arkui.drawing';

interface ActionSheetResult {
  text: string;
}

@Entry
@Component
struct PDFViewerApp {
  @State zoomLevel: number = 1.0;
  @State showTooltip: boolean = false;
  @State sensorData: number = 0.0;

  private timerId: number = 0;

  aboutToAppear(): void {
    this.startSensorSimulation();
  }

  aboutToDisappear(): void {
    clearInterval(this.timerId);
  }

  private startSensorSimulation(): void {
    this.timerId = setInterval(() => {
      this.sensorData = Math.random();
    }, 1000);
  }

  private showActionSheet(): void {
    ActionSheet.show({
      title: 'PDF Options',
      message: 'Choose an action',
      buttons: [
        { text: 'Open in Full Screen' },
        { text: 'Download' },
        { text: 'Print' },
        { text: 'Cancel' }
      ]
    }).then((result: ActionSheetResult) => {
      this.handleActionSheetOption(result.text);
    }).catch((err: Error) => {
      console.error(`Error showing action sheet: ${err}`);
    });
  }

  private handleActionSheetOption(option: string): void {
    console.log(`Selected option: ${option}`);
  }

  private handlePinchGesture(event: PinchGestureEvent): void {
    let newZoom = this.zoomLevel * event.scale;
    newZoom = Math.max(0.5, Math.min(3.0, newZoom));
    this.zoomLevel = parseFloat(newZoom.toFixed(2));
  }

  build() {
    Column() {
      Stack() {
        Image($r('app.media.icon'))
          .width('100%')
          .height('100%')
          .objectFit(ImageFit.Contain)
          .gesture(
            Gesture.Pinch({ fingers: 2 })
              .onActionUpdate((event: PinchGestureEvent) => {
                this.handlePinchGesture(event);
              })
          );

        Text(`Zoom: ${this.zoomLevel}x`)
          .fontSize(16)
          .fontColor(Color.White)
          .backgroundColor(Color.Black)
          .opacity(0.7)
          .padding(8)
          .borderRadius(4)
          .margin({ top: 20, left: 20 });

        Text(`Data: ${this.sensorData.toFixed(2)}`)
          .fontSize(16)
          .fontColor(Color.White)
          .backgroundColor(Color.Black)
          .opacity(0.7)
          .padding(8)
          .borderRadius(4)
          .margin({ top: 60, left: 20 });
      }
      .width('100%')
      .height('80%');

      Button('Show Options')
        .width('50%')
        .height(40)
        .margin(20)
        .onClick(() => {
          this.showActionSheet();
        });

      Button(this.showTooltip ? 'Hide Instructions' : 'Show Instructions')
        .width('50%')
        .height(40)
        .margin(20)
        .onClick(() => {
          this.showTooltip = !this.showTooltip;
        });

      if (this.showTooltip) {
        Column() {
          Text('Pinch to Zoom')
            .fontSize(18)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 8 });

          Text('Use two fingers to pinch in or out to adjust the zoom level.')
            .fontSize(14)
            .margin({ bottom: 16 });
        }
        .width('80%')
        .padding(16)
        .backgroundColor(Color.White)
        .borderRadius(8)
        .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

