import { SegmentedControl, Column, Row, Text, Image, List, ListItem, ForEach, Button, Toggle, Resource, ToggleType } from '@ohos.arkui';

interface Article {
  id: number;
  title: string;
  category: string;
  thumbnail: Resource;
}

@Entry
@Component
struct CRMNewsReader {
  @State syncEnabled: boolean = false;
  @State selectedCategory: string = 'All';
  @State articles: Array<Article> = [
    { id: 1, title: 'Business News', category: 'Business', thumbnail: $r('app.media.ic_public_picture') },
    { id: 2, title: 'Tech Update', category: 'Technology', thumbnail: $r('app.media.ic_public_picture') },
    { id: 3, title: 'Market Trends', category: 'Business', thumbnail: $r('app.media.ic_public_picture') },
    { id: 4, title: 'Innovation in AI', category: 'Technology', thumbnail: $r('app.media.ic_public_picture') }
  ];

  filteredArticles(): Array<Article> {
    if (this.selectedCategory === 'All') {
      return this.articles;
    }
    return this.articles.filter(article => article.category === this.selectedCategory);
  }

  handleSyncToggle(): void {
    if (this.syncEnabled) {
      setTimeout(() => {
        console.log('Sync completed');
      }, 2000);
    }
  }

  deleteArticle(id: number): void {
    this.articles = this.articles.filter(article => article.id !== id);
  }

  build() {
    Column() {
      Row() {
        Toggle({ type: ToggleType.Switch })
          .isOn(this.syncEnabled)
          .onChange((isOn: boolean) => {
            this.syncEnabled = isOn;
            this.handleSyncToggle();
          })
          .margin(16);

        Text('Sync Data')
          .fontSize(16)
          .margin({ left: 8 });
      }
      .alignItems('center')
      .width('100%')
      .padding({ top: 16 });

      SegmentedControl()
        .selected(this.selectedCategory)
        .options(['All', 'Business', 'Technology'])
        .onChange((index: number) => {
          this.selectedCategory = ['All', 'Business', 'Technology'][index];
        })
        .margin(16)
        .selectedColor('#007AFF');

      List() {
        ForEach(this.filteredArticles(), (article: Article) => {
          ListItem() {
            Row() {
              Image(article.thumbnail)
                .width(60)
                .height(60)
                .margin(8);

              Column() {
                Text(article.title)
                  .fontWeight('bold')
                  .fontSize(16);

                Text(article.category)
                  .fontColor('#888888')
                  .fontSize(14);
              }
              .margin({ left: 8 });
            }
            .width('100%')
            .height(80)
            .onClick(() => {
              console.log('Article clicked:', article.id);
            });
          }
          .swipeAction({
            end: {
              builder: () => {
                return Button('Delete')
                  .backgroundColor('#FF0000')
                  .onClick(() => {
                    this.deleteArticle(article.id);
                  });
              }
            }
          });
        });
      }
      .width('100%')
      .layoutWeight(1)
      .backgroundColor('#F5F5F5');
    }
    .width('100%')
    .height('100%');
  }
}

import { Column, Row, Text, Button, Stack, TextInput } from '@ohos.arkui.dom';
import { State, Curve, Color, FlexAlign } from '@ohos.arkui.dom';

@Entry
@Component
struct CounterApp {
  @State count: number = 0;
  @State scaleValue: number = 1;
  @State rotateValue: number = 0;
  @State colorValue: Color = Color.Black;
  @State searchText: string = '';
  @State selectedDate: string = 'Select Date';

  build() {
    Column() {
      // Search Bar
      Row() {
        TextInput({ placeholder: 'Search...' })
          .width('80%')
          .height(40)
          .onChange((value: string) => {
            this.searchText = value;
          })
          .margin(10);
      }
      .width('100%')
      .justifyContent(FlexAlign.Center);

      // Date Picker
      Row() {
        Button(this.selectedDate)
          .width(200)
          .height(40)
          .onClick(() => {
            this.selectedDate = '2023-10-05';
          })
          .margin(10);
      }
      .width('100%')
      .justifyContent(FlexAlign.Center);

      // Counter with Animation
      Stack() {
        Text(`Count: ${this.count}`)
          .fontSize(36)
          .fontWeight('bold')
          .fontColor(this.colorValue)
          .scale({ x: this.scaleValue, y: this.scaleValue })
          .rotate({ angle: this.rotateValue })
          .animation({
            duration: 300,
            curve: Curve.EaseInOut
          })
          .margin(20);

        Row() {
          Button('Increment')
            .onClick(() => {
              this.count++;
              this.scaleValue = 1.2;
              this.rotateValue = 5;
              this.colorValue = Color.Green;
              setTimeout(() => {
                this.scaleValue = 1;
                this.rotateValue = 0;
                this.colorValue = Color.Black;
              }, 300);
            })
            .width(120)
            .height(50)
            .margin(10);

          Button('Decrement')
            .onClick(() => {
              if (this.count > 0) {
                this.count--;
                this.scaleValue = 1.2;
                this.rotateValue = -5;
                this.colorValue = Color.Red;
                setTimeout(() => {
                  this.scaleValue = 1;
                  this.rotateValue = 0;
                  this.colorValue = Color.Black;
                }, 300);
              }
            })
            .width(120)
            .height(50)
            .margin(10);
        }
        .justifyContent(FlexAlign.SpaceEvenly)
        .width('100%');
      }
      .width('100%')
      .height('100%')
      .justifyContent(FlexAlign.Center)
      .alignItems(FlexAlign.Center);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(FlexAlign.Center);
  }
}

