      .justifyContent(FlexAlign.SpaceBetween)
      .padding(10);

      Row() {
        Text('Font Size')
          .fontSize(this.fontSize);
        Button('Increase')
          .onClick(() => {
            this.fontSize += 2;
          })
          .margin({ left: 10 });
        Button('Decrease')
