      .justifyContent(FlexAlign.SpaceBetween)
      .padding(10);

      Scroll() {
        Column() {
          ForEach(this.articles, (article: Article) => {
            Row() {
              Image(article.image)
                .width(50)
                .height(50)
                .objectFit(ImageFit.Cover)
                .margin({ right: 10 });
              Text(article.title)
                .fontSize(this.fontSize)
                .fontWeight(FontWeight.Medium)
                .width('70%');
            }
            .padding(10)
            .onClick(() => {
              this.selectedArticle = article;
            })
            .backgroundColor('#FFFFFF')
            .borderRadius(5)
            .margin({ bottom: 10 });
          });
        }
        .width('100%');
      }
      .width('100%')
      .height('70%');
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(this.isDarkMode ? '#333333' : '#F5F5F5');
  }
}

