import { Column, Row, Text, Button, Tabs, TabContent, TabsController } from '@ohos.arkui.dom';
import { animateTo, Curve } from '@ohos.arkui.animator';

interface Notification {
  id: string;
  message: string;
  type: 'info' | 'warning' | 'error';
  timestamp: number;
}

@Entry
@Component
struct NotificationSystem {
  @State notifications: Notification[] = [];
  @State filteredNotifications: Notification[] = [];
  @State activeTab: number = 0;
  @State showPopup: boolean = false;
  @State popupNotification: Notification | null = null;

  private controller: TabsController = new TabsController();

  build() {
    Column() {
      Tabs({ controller: this.controller }) {
        TabContent() {
          this.NotificationList('All');
        }.tabBar('All')

        TabContent() {
          this.NotificationList('Info');
        }.tabBar('Info')

        TabContent() {
          this.NotificationList('Warning');
        }.tabBar('Warning')

        TabContent() {
          this.NotificationList('Error');
        }.tabBar('Error')
      }
      .onChange((index: number) => {
        this.activeTab = index;
        this.updateFilteredNotifications();
      })

      Row() {
        Button('Add Info').onClick(() => this.addNotification('System update available', 'info'))
        Button('Add Warning').onClick(() => this.addNotification('Disk space low', 'warning'))
        Button('Add Error').onClick(() => this.addNotification('Connection failed', 'error'))
      }
      .justifyContent('space-between')
      .width('100%')

      if (this.showPopup && this.popupNotification) {
        this.PopupNotification(this.popupNotification)
      }
    }
    .width('100%')
    .height('100%')
  }

  @Builder
  NotificationList(filter: string) {
    Column() {
      ForEach(this.filteredNotifications, (notification: Notification) => {
        Row() {
          Text(notification.message)
            .fontColor(this.getColor(notification.type))
          Button('×')
            .onClick(() => this.removeNotification(notification.id))
        }
        .width('100%')
        .justifyContent('space-between')
        .padding(10)
        .borderRadius(5)
        .backgroundColor('#f5f5f5')
      })
    }
    .width('100%')
    .onAppear(() => this.updateFilteredNotifications())
  }

  @Builder
  PopupNotification(notification: Notification) {
    Column() {
      Text(notification.message)
        .fontColor(this.getColor(notification.type))
      Button('×')
        .onClick(() => this.closePopup())
    }
    .width('80%')
    .padding(20)
    .backgroundColor('#ffffff')
    .borderRadius(10)
    .shadow({ radius: 10, color: 0x000000, offsetX: 0, offsetY: 0 })
    .onClick(() => this.closePopup())
    .opacity(this.showPopup ? 1 : 0)
    .transition({ type: 'all', opacity: { duration: 300, curve: Curve.Ease } })
  }

  getColor(type: 'info' | 'warning' | 'error'): string {
    switch (type) {
      case 'info': return '#00aa00';
      case 'warning': return '#ffaa00';
      case 'error': return '#ff0000';
      default: return '#000000';
    }
  }

  addNotification(message: string, type: 'info' | 'warning' | 'error'): void {
    const newNotification: Notification = {
      id: Date.now().toString(),
      message,
      type,
      timestamp: Date.now()
    };
    this.notifications = [...this.notifications, newNotification];
    this.updateFilteredNotifications();

    this.popupNotification = newNotification;
    this.showPopup = true;

    setTimeout(() => {
      this.closePopup();
    }, 3000);
  }

  removeNotification(id: string): void {
    this.notifications = this.notifications.filter(notification => notification.id !== id);
    this.updateFilteredNotifications();
  }

  closePopup(): void {
    this.showPopup = false;
  }

  updateFilteredNotifications(): void {
    switch (this.activeTab) {
      case 0:
        this.filteredNotifications = this.notifications;
        break;
      case 1:
        this.filteredNotifications = this.notifications.filter(n => n.type === 'info');
        break;
      case 2:
        this.filteredNotifications = this.notifications.filter(n => n.type === 'warning');
        break;
