@Entry
@Component
struct NoteTakingApp {
  @State private currentStep: number = 0;
  private totalSteps: number = 3;
  private noteStatistics: string[] = ["Words: 150", "Characters: 750", "Audio Clips: 3"];
  private audioFiles: string[] = ["audio_clip1", "audio_clip2", "audio_clip3"];

  @Builder
  StepContent(step: number) {
    Column() {
      Text(`Step ${step + 1}`)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Text(this.noteStatistics[step])
        .fontSize(18)
        .fontColor(Color.Gray)
        .margin({ bottom: 20 });

      Button('Play Audio')
        .onClick(() => {
          // Placeholder for audio playback logic
          console.log(`Playing audio: ${this.audioFiles[step]}`);
        })
        .margin({ bottom: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }

  build() {
    Column() {
      this.StepContent(this.currentStep);

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentStep > 0) {
              this.currentStep--;
            }
          })
          .margin({ right: 20 })
          .enabled(this.currentStep > 0);

        Button('Next')
          .onClick(() => {
            if (this.currentStep < this.totalSteps - 1) {
              this.currentStep++;
            }
          })
          .enabled(this.currentStep < this.totalSteps - 1);
      }
      .margin({ top: 50 });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

