@Entry
@Component
struct ECommerceApp {
  @State products: Product[] = [
    { id: 1, name: 'Smartphone', category: 'Electronics', image: $r('sys.media.ic_default') },
    { id: 2, name: 'Laptop', category: 'Electronics', image: $r('sys.media.ic_default') },
    { id: 3, name: 'T-Shirt', category: 'Clothing', image: $r('sys.media.ic_default') },
    { id: 4, name: 'Jeans', category: 'Clothing', image: $r('sys.media.ic_default') },
    { id: 5, name: 'Sneakers', category: 'Footwear', image: $r('sys.media.ic_default') },
    { id: 6, name: 'Boots', category: 'Footwear', image: $r('sys.media.ic_default') }
  ];

  @State filteredProducts: Product[] = this.products;
  @State searchText: string = '';
  @State selectedCategory: string = 'All';

  private filterProducts(): void {
    this.filteredProducts = this.products.filter(product => {
      const matchesSearch = product.name.toLowerCase().includes(this.searchText.toLowerCase());
      const matchesCategory = this.selectedCategory === 'All' || product.category === this.selectedCategory;
      return matchesSearch && matchesCategory;
    });
  }

  private handleSearch(text: string): void {
    this.searchText = text;
    this.filterProducts();
  }

  private handleCategorySelect(category: string): void {
    this.selectedCategory = category;
    this.filterProducts();
  }

  build() {
    Column() {
      Row() {
        TextInput({ placeholder: 'Search products...' })
          .onChange((text: string) => this.handleSearch(text))
          .width('80%')
          .height(40)
          .margin(10);

        Button('Voice')
          .width('20%')
          .height(40)
          .margin(10)
          .onClick(() => console.log('Voice command placeholder'));
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceBetween);

      Row() {
        Button('All')
          .onClick(() => this.handleCategorySelect('All'))
          .margin(5);
        Button('Electronics')
          .onClick(() => this.handleCategorySelect('Electronics'))
          .margin(5);
        Button('Clothing')
          .onClick(() => this.handleCategorySelect('Clothing'))
          .margin(5);
        Button('Footwear')
          .onClick(() => this.handleCategorySelect('Footwear'))
          .margin(5);
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .margin(10);

      Grid() {
        ForEach(this.filteredProducts, (product: Product) => {
          GridItem() {
            Column() {
              Image(product.image)
                .width(100)
                .height(100)
                .alt($r('sys.media.ic_default'))
                .onError(() => {
                  product.image = $r('sys.media.ic_default');
                });
              Text(product.name)
                .fontSize(16)
                .margin(5);
              Text(product.category)
                .fontSize(12)
                .margin(5);
            }
            .width('100%')
            .justifyContent(FlexAlign.Center)
            .padding(10);
          }
        });
      }
      .columnsTemplate('1fr 1fr 1fr')
      .rowsGap(10)
      .columnsGap(10)
      .width('100%')
      .height('100%')
      .margin(10);
    }
    .width('100%')
    .height('100%')
    .padding(10);
  }
}

