import { Chip } from '@ohos.arkui.advanced';
import { Color } from '@ohos.arkui.drawing';

interface WeatherData {
  condition: string;
  temperature: string;
  day: string;
}

@Entry
@Component
struct WeatherForecast {
  @State weatherData: WeatherData[] = [
    { day: 'Today', condition: 'Sunny', temperature: '25°C' },
    { day: 'Tomorrow', condition: 'Rainy', temperature: '18°C' },
    { day: 'Wednesday', condition: 'Cloudy', temperature: '20°C' }
  ];

  private getBackgroundColor(condition: string): Color {
    switch (condition) {
      case 'Sunny': return Color.Yellow;
      case 'Rainy': return Color.Blue;
      case 'Cloudy': return Color.Gray;
      default: return Color.White;
    }
  }

  private onChipSelect(day: string): void {
    console.log(`Selected day: ${day}`);
  }

  build() {
    Column() {
      ForEach(this.weatherData, (item: WeatherData, index: number) => {
        Chip() {
          Column() {
            Text(item.day)
              .fontColor(Color.White)
            Text(item.condition)
              .fontColor(Color.White)
            Text(item.temperature)
              .fontColor(Color.White)
          }
        }
        .backgroundColor(this.getBackgroundColor(item.condition))
        .accessibilityDescription(`${item.day}, ${item.condition}, ${item.temperature}`)
        .minTouchTarget({ width: 48, height: 48 })
        .focusable(true)
        .focusOnTouch(true)
        .onClick(() => this.onChipSelect(item.day))
        .margin({ bottom: 10 })
        .width('100%')
      })
    }
    .padding(20)
    .width('100%')
  }
}

import { Chip, Tabs, TabContent, Button, Text, Row, Column } from '@ohos.arkui.advanced';
import { FontWeight } from '@ohos.arkui.advanced';

@Component
struct ExerciseCard {
  @State title: string = '';
  @State tags: string[] = [];
  @State duration: number = 0;
  @State remainingTime: number = 0;
  @State isRunning: boolean = false;
  private timerId: number | null = null;

  aboutToDisappear(): void {
    if (this.timerId) {
      clearInterval(this.timerId);
    }
  }

  startTimer(): void {
    if (this.isRunning) {
      clearInterval(this.timerId);
      this.isRunning = false;
    } else {
      this.isRunning = true;
      this.timerId = setInterval(() => {
        if (this.remainingTime > 0) {
          this.remainingTime--;
        } else {
          clearInterval(this.timerId);
          this.isRunning = false;
        }
      }, 1000);
    }
  }

  resetTimer(): void {
    clearInterval(this.timerId);
    this.remainingTime = this.duration;
    this.isRunning = false;
  }

  @Builder
  build() {
    Column() {
      Text(this.title)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      Row() {
        ForEach(this.tags, (tag: string) => {
          Chip() {
            Text(tag)
          }
          .margin({ right: 5 });
        });
      }
      .margin({ bottom: 15 });

      Text(`${this.remainingTime}s`)
        .fontSize(24)
        .margin({ bottom: 15 });

      Row() {
        Button(this.isRunning ? 'Pause' : 'Start')
          .onClick(() => this.startTimer())
          .enabled(this.remainingTime > 0 || !this.isRunning)
          .margin({ right: 10 });

        Button('Reset')
          .onClick(() => this.resetTimer())
          .enabled(this.remainingTime !== this.duration || this.isRunning);
      }
    }
    .padding(20)
    .width('100%');
  }
}

