import { PanGesture, GestureEvent } from '@ohos.arkui.gesture'
import promptAction from '@ohos.promptAction'

@Entry
@Component
struct PDFViewer {
  @State currentPage: number = 1
  @State totalPages: number = 10

  showToast(message: string) {
    promptAction.showToast({
      message: message,
      duration: 1000
    })
  }

  handleSwipe(event: GestureEvent) {
    if (event.offsetX > 50) {
      if (this.currentPage > 1) {
        this.currentPage--
        this.showToast(`Page ${this.currentPage} of ${this.totalPages}`)
      } else {
        this.showToast('Already at first page')
      }
    } else if (event.offsetX < -50) {
      if (this.currentPage < this.totalPages) {
        this.currentPage++
        this.showToast(`Page ${this.currentPage} of ${this.totalPages}`)
      } else {
        this.showToast('Already at last page')
      }
    }
  }

  build() {
    Stack() {
      Image($r('app.media.icon'))
        .width('100%')
        .height('100%')
        .gesture(
          PanGesture({ distance: 5 })
            .onActionUpdate((event: GestureEvent) => {
              this.handleSwipe(event)
            })
        )

      Text(`Page ${this.currentPage} of ${this.totalPages}`)
        .fontSize(16)
        .fontColor(Color.White)
        .backgroundColor('#80000000')
        .borderRadius(8)
        .padding(10)
        .margin({ bottom: 20, right: 20 })
        .align(Alignment.BottomEnd)
    }
    .width('100%')
    .height('100%')
  }
}

