@Component
struct PaginationControls {
  @State currentPage: number = 1;
  private totalPages: number = Math.ceil(videos.length / 4);

  build() {
    Row() {
      Button('Previous')
        .onClick(() => {
          if (this.currentPage > 1) {
            this.currentPage--;
          }
        })
        .disabled(this.currentPage === 1)
        .focusable(true)
        .accessibilityText('Previous page button. Current page: ' + this.currentPage);

      Text(`Page ${this.currentPage} of ${this.totalPages}`)
        .fontSize(16)
        .margin({ left: 16, right: 16 })
        .focusable(true)
        .accessibilityText('Current page: ' + this.currentPage + ' of ' + this.totalPages);

      Button('Next')
        .onClick(() => {
          if (this.currentPage < this.totalPages) {
            this.currentPage++;
          }
        })
        .disabled(this.currentPage === this.totalPages)
        .focusable(true)
        .accessibilityText('Next page button. Current page: ' + this.currentPage);
    }
    .justifyContent(FlexAlign.Center)
    .margin({ top: 16, bottom: 16 });
  }
}

@Entry
@Component
struct VideoStreamingApp {
  @State currentPage: number = 1;
  private videosPerPage: number = 4;

  private getPaginatedVideos(): Video[] {
    const startIndex = (this.currentPage - 1) * this.videosPerPage;
    return videos.slice(startIndex, startIndex + this.videosPerPage);
  }

  build() {
    Column() {
      Grid() {
        ForEach(this.getPaginatedVideos(), (video: Video) => {
          GridItem() {
            VideoItem({ video });
          }
          .columnSpan(1)
          .rowSpan(1)
        });
      }
      .columnsTemplate('1fr 1fr')
      .rowsTemplate('1fr 1fr')
      .rowsGap(16)
      .columnsGap(16)
      .padding(16);

      PaginationControls();
    }
    .width('100%')
    .height('100%');
  }
}

import { Column, Text, Button, TextInput } from '@ohos.arkui.advanced.Component';
import { FlexAlign } from '@ohos.arkui.advanced.Common';

interface Question {
  question: string;
  answer: string;
}

@Entry
@Component
struct QuizApp {
  @State currentQuestionIndex: number = 0;
  @State score: number = 0;
  @State userAnswer: string = '';
  @State feedback: string = '';
  @State showFeedback: boolean = false;
  @State quizCompleted: boolean = false;

  private questions: Array<Question> = [
    { question: 'What is the capital of France?', answer: 'Paris' },
    { question: 'Which planet is closest to the Sun?', answer: 'Mercury' },
    { question: 'What is the largest mammal?', answer: 'Blue Whale' }
  ];

  private checkAnswer = () => {
    const correctAnswer = this.questions[this.currentQuestionIndex].answer.toLowerCase();
    const userAnswer = this.userAnswer.toLowerCase();
    if (userAnswer === correctAnswer) {
      this.score += 1;
      this.feedback = 'Correct!';
    } else {
      this.feedback = `Incorrect! The correct answer is ${this.questions[this.currentQuestionIndex].answer}.`;
    }
    this.showFeedback = true;
    setTimeout(() => {
      this.nextQuestion();
    }, 1000);
  }

  private nextQuestion = () => {
    if (this.currentQuestionIndex < this.questions.length - 1) {
      this.currentQuestionIndex += 1;
      this.userAnswer = '';
      this.showFeedback = false;
    } else {
      this.quizCompleted = true;
    }
  }

  private restartQuiz = () => {
    this.currentQuestionIndex = 0;
    this.score = 0;
    this.userAnswer = '';
    this.feedback = '';
    this.showFeedback = false;
    this.quizCompleted = false;
  }

  build() {
    Column() {
      if (!this.quizCompleted) {
        Text(`Question ${this.currentQuestionIndex + 1}/${this.questions.length}`)
          .fontSize(20)
          .margin({ top: 20, bottom: 10 });

        Text(this.questions[this.currentQuestionIndex].question)
          .fontSize(18)
          .margin({ bottom: 20 });

        TextInput({ placeholder: 'Your answer', text: this.userAnswer })
          .onChange((value: string) => {
            this.userAnswer = value;
          })
          .margin({ bottom: 20 });

        Button('Submit')
          .onClick(this.checkAnswer)
          .margin({ bottom: 20 });

        if (this.showFeedback) {
          Text(this.feedback)
            .fontSize(16)
            .margin({ bottom: 20 });
        }
      } else {
        Text('Quiz Completed!')
          .fontSize(24)
          .margin({ top: 20, bottom: 10 });

        Text(`Your score: ${this.score}/${this.questions.length}`)
          .fontSize(20)
          .margin({ bottom: 20 });

        Button('Restart Quiz')
          .onClick(this.restartQuiz)
          .margin({ bottom: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
  }
}

@Entry
@Component
struct GestureTextInputExample {
  @State private text: string = '';
  @State private tapCount: number = 0;
  @State private longPressActive: boolean = false;
  @State private swipeText: string = 'Swipe Me';
  @State private offsetX: number = 0;

  build() {
    Column({ space: 20 }) {
      TextInput({ text: this.text })
        .width('80%')
        .height(48)
        .fontSize(16)
        .onChange((value: string) => {
          this.text = value;
        })
        .gesture(
          TapGesture({ count: 1 })
            .onAction(() => {
              this.tapCount++;
            })
        )
        .gesture(
          LongPressGesture({ repeat: false })
            .onAction(() => {
              this.longPressActive = true;
            })
            .onActionEnd(() => {
              this.longPressActive = false;
            })
        )
        .gesture(
          PanGesture({ direction: PanDirection.Horizontal })
            .onActionStart(() => {
              console.log('Swipe started');
            })
            .onActionUpdate((event: GestureEvent) => {
              this.offsetX = event.offsetX;
            })
            .onActionEnd(() => {
              if (this.offsetX > 50) {
                this.swipeText = 'Swiped Right';
              } else if (this.offsetX < -50) {
                this.swipeText = 'Swiped Left';
              }
              animateTo({ duration: 300 }, () => {
                this.offsetX = 0;
              });
            })
        )
        .transform({ translate: { x: this.offsetX } });

      Text(`Tapped ${this.tapCount} times`)
        .fontSize(16);

      Text(this.swipeText)
        .fontSize(16);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(0xF5F5F5);
  }
}

