          });
        }
        .width('90%')
        .padding(10)
        .backgroundColor('#f5f5f5')
        .borderRadius(12)
        .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White);
  }
}

import { Column, Text, Image, Flex, Slider, Counter } from '@ohos.arkui.component';
import { ImageFit } from '@ohos.arkui.common';
import display from '@ohos.display';

@Entry
@Component
struct DocumentScanner {
  @State counterValue: number = 1;
  @State zoomValue: number = 1.0;
  @State isPortrait: boolean = true;

  private displayListener: display.DisplayListener = {
    onDisplayChange: (newDisplay: display.Display) => {
      this.isPortrait = newDisplay.width < newDisplay.height;
    }
  };

  onPageShow(): void {
    display.getDefaultDisplaySync().then(display => {
      this.isPortrait = display.width < display.height;
      display.on('displayChange', this.displayListener);
    });
  }

  onPageHide(): void {
    display.getDefaultDisplaySync().then(display => {
      display.off('displayChange', this.displayListener);
    });
  }

  build() {
    Column() {
      if (this.isPortrait) {
        Column() {
          Column() {
            Text('Page Navigation')
              .fontSize(16)
              .margin({ bottom: 8 });
            Counter()
              .value(this.counterValue)
              .onInc(() => { this.counterValue++ })
              .onDec(() => { this.counterValue-- })
              .margin({ bottom: 16 });

            Text('Zoom Adjustment')
              .fontSize(16)
              .margin({ bottom: 8 });
            Slider({
              value: this.zoomValue,
              min: 0.5,
              max: 2.0,
              step: 0.1
            })
              .onChange((value: number) => { this.zoomValue = value; })
              .margin({ bottom: 16 });
          }
          .padding(16);

          Image($r('sys.media.ic_public_picture'))
            .width('100%')
            .height('70%')
            .objectFit(ImageFit.Contain);
        }
      } else {
        Flex({ direction: FlexDirection.Row }) {
          Column() {
            Text('Page Navigation')
              .fontSize(16)
              .margin({ bottom: 8 });
            Counter()
              .value(this.counterValue)
              .onInc(() => { this.counterValue++ })
              .onDec(() => { this.counterValue-- })
              .margin({ bottom: 16 });

            Text('Zoom Adjustment')
              .fontSize(16)
              .margin({ bottom: 8 });
            Slider({
              value: this.zoomValue,
              min: 0.5,
              max: 2.0,
              step: 0.1
            })
              .onChange((value: number) => { this.zoomValue = value; })
              .margin({ bottom: 16 });
          }
          .padding(16)
          .width('20%');

          Image($r('sys.media.ic_public_picture'))
            .width('80%')
            .height('100%')
            .objectFit(ImageFit.Contain);
        }
      }
    }
    .width('100%')
    .height('100%')
    .onPageShow(() => this.onPageShow())
    .onPageHide(() => this.onPageHide());
  }
}

import promptAction from '@ohos.promptAction';
import router from '@ohos.router';

interface Alarm {
  id: number;
  time: string;
  active: boolean;
}

@Entry
@Component
struct AlarmClockApp {
  @State alarms: Alarm[] = [
    { id: 1, time: "08:00", active: true },
    { id: 2, time: "12:30", active: false },
    { id: 3, time: "18:45", active: true }
  ];
  @State currentTab: string = "Alarms";
  @State isAuthenticated: boolean = false;

  private mockAuthenticate(): void {
    promptAction.showToast({
      message: "Authentication required",
      duration: 2000
    });
    setTimeout(() => {
      this.isAuthenticated = true;
      promptAction.showToast({
        message: "Authenticated",
        duration: 2000
      });
    }, 1000);
  }

  private toggleAlarm(id: number): void {
    if (!this.isAuthenticated) {
      this.mockAuthenticate();
      return;
    }
    this.alarms = this.alarms.map(alarm => {
      if (alarm.id === id) {
        return { id: alarm.id, time: alarm.time, active: !alarm.active };
      }
      return alarm;
    });
  }

  @Builder
  private renderAlarms() {
    List({ space: 10 }) {
