            backgroundColor: "#f0f0f0"
          }
        });
      Button("About")
        .onClick(() => { this.currentTab = "About"; })
        .stateStyles({
          pressed: {
            backgroundColor: "#f0f0f0"
          }
        });
    }
    .width('100%')
    .justifyContent(FlexAlign.SpaceEvenly)
    .padding(10);
  }

  build() {
    Column() {
      this.renderTabs();
