      } else {
        Text("About Page")
          .fontSize(20)
          .textAlign(TextAlign.Center);
      }
    }
    .width('100%')
    .height('100%');
  }
}

@Entry
@Component
struct PodcastPlayer {
  @State currentIndex: number = 0
  @State isPlaying: boolean = false
  @State selectedDate: string = '2023-01-01'
  @State progressValue: number = 0
  @State duration: number = 3600

  formatTime(seconds: number): string {
    const mins = Math.floor(seconds / 60).toString().padStart(2, '0')
    const secs = (seconds % 60).toString().padStart(2, '0')
    return `${mins}:${secs}`
  }

  build() {
    Column() {
      Row() {
        Text('Podcast Player')
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
        Image($r('app.media.user_avatar'))
          .width(40)
          .height(40)
          .backgroundColor('#CCCCCC')
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceBetween)
      .padding(15)

      Image($r('app.media.podcast_cover'))
        .width(200)
        .height(200)
        .backgroundColor('#DDDDDD')
        .margin({top: 20, bottom: 20})

      DatePicker({
        start: new Date('1970-1-1'),
        end: new Date('2100-1-1'),
        selected: new Date(this.selectedDate)
      })
      .onDateChange((value: Date) => {
        this.selectedDate = `${value.getFullYear()}-${value.getMonth()+1}-${value.getDate()}`
      })

      Row() {
        Button(this.isPlaying ? 'Pause' : 'Play')
          .onClick(() => {
            this.isPlaying = !this.isPlaying
          })
      }

      Row() {
        Text(this.formatTime(this.progressValue))
        Slider({value: this.progressValue, min: 0, max: this.duration})
          .onChange((value: number) => {
            this.progressValue = value
          })
        Text(this.formatTime(this.duration))
      }
