        Column() {
          Text('Settings')
            .fontColor(this.currentIndex === 2 ? '#1698CE' : '#666666')
        }
        .width('33%')
        .onClick(() => this.currentIndex = 2)
      }
      .width('100%')
      .height(60)
      .backgroundColor('#f5f5f5')
    }
    .width('100%')
    .height('100%')
  }
}

import { Column, Row, Text, Button, Progress, Swiper, SwiperController } from '@ohos.arkui.advanced';
import prompt from '@system.prompt';

@Entry
@Component
struct FitnessTracker {
  @State steps: number = 0;
  @State calories: number = 0;
  @State distance: number = 0;
  @State activeTab: number = 0;
  @State showSettings: boolean = false;

  private swiperController: SwiperController = new SwiperController();

  incrementSteps(): void {
    this.steps += 100;
    if (this.steps > 10000) this.steps = 10000;
    prompt.showToast({ message: 'Steps incremented!' });
  }

  incrementCalories(): void {
    this.calories += 5;
    if (this.calories > 500) this.calories = 500;
    prompt.showToast({ message: 'Calories incremented!' });
  }

  incrementDistance(): void {
    this.distance += 0.5;
    if (this.distance > 10) this.distance = 10;
    prompt.showToast({ message: 'Distance incremented!' });
  }

  resetData(): void {
    this.steps = 0;
    this.calories = 0;
    this.distance = 0;
    prompt.showToast({ message: 'Data reset!' });
    this.showSettings = false;
  }

  build() {
    Column() {
      Swiper({ index: this.activeTab, controller: this.swiperController }) {
        Column() {
          Text('Steps: ' + this.steps)
            .fontSize(24)
            .margin({ bottom: 16 });
          Progress({ value: this.steps, total: 10000 })
            .width('80%')
            .height(10)
            .margin({ bottom: 16 });
          Button('Add Steps')
            .onClick(() => this.incrementSteps())
            .margin({ bottom: 16 });
        }
        .width('100%')
        .height('100%')
        .justifyContent('center');

        Column() {
          Text('Calories: ' + this.calories)
            .fontSize(24)
            .margin({ bottom: 16 });
          Progress({ value: this.calories, total: 500 })
            .width('80%')
            .height(10)
            .margin({ bottom: 16 });
          Button('Add Calories')
            .onClick(() => this.incrementCalories())
            .margin({ bottom: 16 });
        }
        .width('100%')
        .height('100%')
        .justifyContent('center');

        Column() {
          Text('Distance: ' + this.distance + ' km')
            .fontSize(24)
            .margin({ bottom: 16 });
          Progress({ value: this.distance, total: 10 })
            .width('80%')
            .height(10)
            .margin({ bottom: 16 });
          Button('Add Distance')
            .onClick(() => this.incrementDistance())
            .margin({ bottom: 16 });
        }
        .width('100%')
        .height('100%')
        .justifyContent('center');
      }
      .width('100%')
      .height('80%')
      .onChange((index: number) => {
        this.activeTab = index;
      });

      Button('Settings')
        .onClick(() => {
          this.showSettings = true;
        })
        .margin({ top: 16 });

      if (this.showSettings) {
        Column() {
          Text('Settings')
            .fontSize(24)
            .margin({ bottom: 16 });
          Button('Reset Data')
            .onClick(() => this.resetData())
            .margin({ bottom: 16 });
        }
        .width('100%')
        .height(200)
        .backgroundColor('#ffffff')
        .borderRadius(16)
        .justifyContent('center');
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent('center');
  }
}

@Entry
@Component
struct RefreshApp {
  @State refreshing: boolean = false
  @State selectedIndex: number = 0
  @State listData: string[] = ['Item 1', 'Item 2', 'Item 3']
  @State rotationAngle: number = 0
  private timerId: number = 0

  build() {
    Column() {
      TextPicker({
        range: ['Default', 'Custom']
      })
      .onChange((value: string | string[], index: number | number[]) => {
        if (typeof index === 'number') {
          this.selectedIndex = index
        }
      })

      Refresh({ refreshing: this.refreshing }) {
        List() {
          ForEach(this.listData, (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(16)
                .padding(16)
                .width('100%')
            }
          }, (item: string) => item)
        }
        .width('100%')
        .height('100%')
      }
      .onRefreshing(() => {
        this.refreshing = true
        if (this.selectedIndex === 1) {
          this.startRotationAnimation()
        }
        setTimeout(() => {
          this.listData = ['New Item', ...this.listData]
          this.refreshing = false
          if (this.selectedIndex === 1) {
            this.stopRotationAnimation()
          }
        }, 2000)
      })

      if (this.selectedIndex === 1 && this.refreshing) {
        Canvas()
          .width(100)
          .height(100)
          .onReady(() => {
            const ctx = new CanvasRenderingContext2D()
            ctx.clearRect(0, 0, 100, 100)
            ctx.save()
            ctx.translate(50, 50)
            ctx.rotate(this.rotationAngle * Math.PI / 180)
            ctx.beginPath()
            ctx.moveTo(0, -20)
            ctx.lineTo(10, 10)
            ctx.lineTo(-10, 10)
            ctx.closePath()
            ctx.fillStyle = '#000000'
            ctx.fill()
            ctx.restore()
            ctx.font = '14px sans-serif'
            ctx.fillText('Refreshing...', 10, 80)
          })
      }
    }
    .width('100%')
    .height('100%')
  }

  private startRotationAnimation() {
    this.timerId = setInterval(() => {
      this.rotationAngle = (this.rotationAngle + 10) % 360
    }, 50)
  }

  private stopRotationAnimation() {
    if (this.timerId) {
      clearInterval(this.timerId)
      this.timerId = 0
    }
  }
}

