@Entry
@Component
struct LoginScreen {
  @State username: string = '';
  @State password: string = '';
  @State loginMessage: string = '';
  @State showMessage: boolean = false;
  @State isAuthenticated: boolean = false;
  @State isLoading: boolean = false;
  @State stepData: Array<StepDataItem> = [
    { date: '2023-10-01', steps: 5000, previousSteps: 4500 },
    { date: '2023-10-02', steps: 6000, previousSteps: 5000 },
    { date: '2023-10-03', steps: 5500, previousSteps: 6000 },
    { date: '2023-10-04', steps: 7000, previousSteps: 5500 },
    { date: '2023-10-05', steps: 8000, previousSteps: 7000 },
    { date: '2023-10-06', steps: 7500, previousSteps: 8000 },
    { date: '2023-10-07', steps: 9000, previousSteps: 7500 }
  ];
  @State currentPage: number = 1;
  @State showForgotPassword: boolean = false;

  build() {
    Column() {
      if (!this.isAuthenticated) {
        Column() {
          Text('Username')
            .fontSize(18)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 10 });

          TextInput({ placeholder: 'Enter your username', text: this.username })
            .onChange((value: string) => {
              this.username = value;
            })
            .width('80%')
            .margin({ bottom: 20 });

          Text('Password')
            .fontSize(18)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 10 });

          TextInput({ placeholder: 'Enter your password', text: this.password })
            .type(InputType.Password)
            .onChange((value: string) => {
              this.password = value;
            })
            .width('80%')
            .margin({ bottom: 20 });

          if (this.showMessage) {
            Text(this.loginMessage)
              .fontSize(14)
              .fontColor(Color.Red)
              .margin({ bottom: 20 });
          }

          Button('Login')
            .width('50%')
            .height(40)
            .backgroundColor(Color.Green)
            .fontColor(Color.White)
            .onClick(() => {
              if (this.username.length < 4 || this.password.length < 6) {
                this.loginMessage = 'Username must be at least 4 characters and password at least 6 characters.';
                this.showMessage = true;
              } else {
                this.isLoading = true;
                setTimeout(() => {
                  this.isAuthenticated = true;
                  this.isLoading = false;
                }, 1000);
              }
            })
            .margin({ bottom: 20 });

          Button('Forgot Password')
            .width('50%')
            .height(40)
            .backgroundColor(Color.Gray)
            .fontColor(Color.White)
            .onClick(() => {
              this.showForgotPassword = true;
            })
            .margin({ bottom: 20 });

          if (this.isLoading) {
            Progress({ value: 0 })
              .width('50%')
              .height(40)
              .margin({ bottom: 20 });
          }
        }
        .width('100%')
        .height('100%')
        .padding(20)
        .backgroundColor(Color.White);
      } else {
        Column() {
          Text('Step Data')
            .fontSize(24)
            .fontColor(Color.Black)
            .margin({ top: 20, bottom: 20 });

          Flex({ direction: FlexDirection.Column, justifyContent: FlexAlign.Start, alignItems: ItemAlign.Start }) {
            ForEach(this.stepData, (item: StepDataItem) => {
              Column() {
                Text(`Date: ${item.date}`)
                  .fontSize(16)
                  .fontColor(Color.Black)
                  .margin({ bottom: 10 });

                Text(`Steps: ${item.steps}`)
                  .fontSize(16)
                  .fontColor(Color.Black)
                  .margin({ bottom: 10 });
              }
            })
          }
        }
      }
    }
  }
}

