import prompt from '@ohos.promptAction';
import webview from '@ohos.web.webview';

@Entry
@Component
struct AuthApp {
  @State email: string = '';
  @State password: string = '';
  @State isLoggedIn: boolean = false;
  @State countdown: number = 60;
  @State currentPage: number = 1;
  @State totalPages: number = 5;
  webController: webview.WebviewController = new webview.WebviewController();

  build() {
    Column() {
      if (!this.isLoggedIn) {
        Text('Email:')
          .fontSize(18)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Enter your email' })
          .width('80%')
          .margin({ bottom: 20 })
          .onChange((value: string) => {
            this.email = value;
          });

        Text('Password:')
          .fontSize(18)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Enter your password' })
          .type(InputType.Password)
          .width('80%')
          .margin({ bottom: 20 })
          .onChange((value: string) => {
            this.password = value;
          });

        Button('Login')
          .onClick(() => {
            if (this.email && this.password) {
              this.isLoggedIn = true;
            } else {
              prompt.showToast({
                message: 'Please fill in all fields',
                duration: 2000
              });
            }
          })
          .width('60%')
          .backgroundColor('#4CAF50')
          .fontSize(18)
          .fontColor(Color.White);
      } else {
        Text(`Time remaining: ${this.countdown}s`)
          .fontSize(20)
          .margin({ bottom: 20 });

        Row() {
          Button('Previous')
            .onClick(() => {
              if (this.currentPage > 1) {
                this.currentPage--;
              }
            })
            .width('30%')
            .margin({ right: 10 });

          Text(`Page ${this.currentPage} of ${this.totalPages}`)
            .fontSize(16);

          Button('Next')
            .onClick(() => {
              if (this.currentPage < this.totalPages) {
                this.currentPage++;
              }
            })
            .width('30%')
            .margin({ left: 10 });
        }
        .justifyContent(FlexAlign.Center)
        .margin({ bottom: 20 });

        Web({
          src: 'https://example.com/page' + this.currentPage,
          controller: this.webController
        })
          .width('100%')
          .height('60%');
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }

  aboutToAppear() {
    setInterval(() => {
      if (this.countdown > 0) {
        this.countdown--;
      }
    }, 1000);
  }
}

