import window from '@ohos.window';
import display from '@ohos.display';
import { SegmentedControl } from '@ohos.arkui.component';

@Entry
@Component
struct ResponsiveApp {
  @State refreshing: boolean = false;
  @State progressValue: number = 0;
  @State selectedSegment: number = 0;
  @State isPortrait: boolean = true;
  private timerId: number = -1;
  private context = getContext(this);

  aboutToAppear() {
    this.detectOrientation();
    window.getLastWindow(this.context).then((win) => {
      win.on('windowSizeChange', () => {
        this.detectOrientation();
      });
    });
  }

  aboutToDisappear() {
    if (this.timerId !== -1) {
      clearInterval(this.timerId);
    }
  }

  detectOrientation() {
    window.getLastWindow(this.context).then((win) => {
      const rect = win.getWindowProperties().windowRect;
      this.isPortrait = rect.width < rect.height;
    });
  }

  startRefresh() {
    this.refreshing = true;
    this.progressValue = 0;
    this.timerId = setInterval(() => {
      this.progressValue += 10;
      if (this.progressValue >= 100) {
        clearInterval(this.timerId);
        this.refreshing = false;
      }
    }, 500);
  }

  build() {
    Column() {
      Text(this.isPortrait ? 'Portrait Mode' : 'Landscape Mode')
        .fontSize(20)
        .margin(10);

      SegmentedControl({ selected: this.selectedSegment }) {
        Text('Option 1')
        Text('Option 2')
      }
      .onChange((index: number) => {
        this.selectedSegment = index;
      })
      .margin(10);

      Refresh({ refreshing: this.refreshing }) {
        Column() {
          if (this.refreshing) {
            Progress({ value: this.progressValue, total: 100 })
              .width('80%')
              .margin(10);
          }
          Text('Pull to Refresh')
            .fontSize(16)
            .margin(10);
        }
        .width('100%')
        .height(this.isPortrait ? '60%' : '40%')
        .justifyContent(FlexAlign.Center);
      }
      .onRefreshing(() => {
        this.startRefresh();
      });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

