import { Column, Text, Button, TextInput, Row } from '@ohos.arkui';

@Entry
@Component
struct AuthTimerApp {
  @State isAuthenticated: boolean = false;
  @State username: string = '';
  @State password: string = '';
  @State loginMessage: string = '';
  @State showMessage: boolean = false;
  @State timeLeft: number = 60;
  @State isRunning: boolean = false;
  private timerId: number = -1;

  build() {
    Column() {
      if (!this.isAuthenticated) {
        this.buildAuthScreen();
      } else {
        this.buildTimerScreen();
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }

  @Builder
  buildAuthScreen() {
    Column() {
      Text('Username')
        .fontSize(18)
        .fontWeight('bold')
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your username', text: this.username })
        .onChange((value: string) => {
          this.username = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Text('Password')
        .fontSize(18)
        .fontWeight('bold')
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type('password')
        .onChange((value: string) => {
          this.password = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Button('Login')
        .onClick(() => {
          if (this.validateCredentials()) {
            this.loginMessage = 'Login successful!';
            this.showMessage = true;
            this.isAuthenticated = true;
          } else {
            this.loginMessage = 'Invalid username or password.';
            this.showMessage = true;
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor('#FFFFFF');

      if (this.showMessage) {
        Text(this.loginMessage)
          .fontSize(16)
          .margin({ top: 20 })
          .fontColor('#FF0000');
      }
    }
    .padding(20)
    .alignItems('center')
    .justifyContent('center');
  }

  @Builder
  buildTimerScreen() {
    Column() {
      Text(`Time Left: ${this.timeLeft}s`)
        .fontSize(24)
        .margin({ bottom: 20 });

      Row() {
        Button('Start')
          .onClick(() => {
            this.startTimer();
          })
          .width('30%')
          .margin({ right: 10 });

        Button('Stop')
          .onClick(() => {
            this.stopTimer();
          })
          .width('30%')
          .margin({ right: 10 });

        Button('Reset')
          .onClick(() => {
            this.resetTimer();
          })
          .width('30%');
      }
      .margin({ bottom: 20 });

      Button('Logout')
        .onClick(() => {
          this.isAuthenticated = false;
          this.username = '';
          this.password = '';
          this.showMessage = false;
        })
        .width('60%')
        .backgroundColor('#FF5722')
        .fontSize(18)
        .fontColor('#FFFFFF');
    }
    .padding(20)
    .alignItems('center')
    .justifyContent('center');
  }

  private validateCredentials(): boolean {
    return this.username === 'admin' && this.password === 'password123';
  }

  private startTimer() {
    if (!this.isRunning) {
      this.isRunning = true;
      this.timerId = setInterval(() => {
        if (this.timeLeft > 0) {
          this.timeLeft--;
        } else {
          this.stopTimer();
        }
      }, 1000);
    }
  }

  private stopTimer() {
    if (this.isRunning) {
      clearInterval(this.timerId);
      this.isRunning = false;
    }
  }

  private resetTimer() {
    this.stopTimer();
    this.timeLeft = 60;
  }
}

@Entry
@Component
struct FileManager {
  @State items: string[] = ['File 1', 'File 2', 'File 3', 'File 4', 'File 5']
  @State draggingIndex: number = -1
  @State targetIndex: number = -1
  @State viewMode: string = 'List'
  @State enableDrag: boolean = true

  build() {
    Column() {
      Row() {
        Text('View Mode:')
        Column() {
          Text('List')
            .onClick(() => {
              this.viewMode = 'List'
            })
          Text('Grid')
            .onClick(() => {
              this.viewMode = 'Grid'
            })
        }
      }
      .margin(10)

      Row() {
        Text('Enable Drag & Drop')
        Column() {
          Text('ON')
            .onClick(() => {
              this.enableDrag = true
            })
          Text('OFF')
            .onClick(() => {
              this.enableDrag = false
            })
        }
      }
      .margin(10)

      List({ space: 10 }) {
        ForEach(this.items, (item: string, index: number) => {
          ListItem() {
            Text(item)
              .fontSize(18)
              .width('100%')
              .height(60)
              .backgroundColor(this.draggingIndex === index ? '#e0e0e0' : '#f5f5f5')
              .borderRadius(8)
              .onTouch((event: TouchEvent) => {
                if (!this.enableDrag) return
                if (event.type === TouchType.Down) {
                  this.draggingIndex = index
                } else if (event.type === TouchType.Move) {
                  const currentY = event.touches[0].y
                  this.targetIndex = Math.min(Math.max(0, index + (currentY > event.touches[0].y ? 1 : -1)), this.items.length - 1)
                } else if (event.type === TouchType.Up) {
                  if (this.draggingIndex >= 0 && this.targetIndex >= 0 && this.draggingIndex !== this.targetIndex) {
                    const newItems = [...this.items]
                    const removed = newItems[this.draggingIndex]
                    newItems.splice(this.draggingIndex, 1)
                    newItems.splice(this.targetIndex, 0, removed)
                    this.items = newItems
                  }
                  this.draggingIndex = -1
                  this.targetIndex = -1
                }
              })
          }
          .opacity(this.draggingIndex === index ? 0.5 : 1)
        })
      }
      .width('100%')
    }
    .width('100%')
    .height('100%')
  }
}

