import { Card, List, ListItem, Column, Row, Image, Text, Button } from '@ohos.arkui.advanced';
import { ActionSheet } from '@ohos.promptAction';

interface Song {
  id: number;
  title: string;
  artist: string;
  cover: Resource;
  duration: number;
}

@Entry
@Component
struct MusicPlayer {
  @State currentSong: Song | null = null;
  @State isPlaying: boolean = false;
  @State showActionSheet: boolean = false;

  private songs: Song[] = [
    { id: 1, title: 'Song 1', artist: 'Artist 1', cover: $r('app.media.icon'), duration: 180 },
    { id: 2, title: 'Song 2', artist: 'Artist 2', cover: $r('app.media.icon'), duration: 210 },
    { id: 3, title: 'Song 3', artist: 'Artist 3', cover: $r('app.media.icon'), duration: 195 },
  ];

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.songs, (song: Song) => {
          ListItem() {
            Card({
              onClick: () => {
                this.currentSong = song;
                this.isPlaying = true;
              }
            }) {
              Row() {
                Image(song.cover)
                  .width(50)
                  .height(50)
                  .margin(10);
                Column() {
                  Text(song.title)
                    .fontSize(16);
                  Text(song.artist)
                    .fontSize(12)
                    .fontColor('#808080');
                }
              }
            }
          }
        }, (song: Song) => song.id.toString());
      }
      .width('100%')
      .height('60%');

      if (this.currentSong) {
        Column() {
          Image(this.currentSong.cover)
            .width(100)
            .height(100)
            .margin(10);
          Text(this.currentSong.title)
            .fontSize(16);
          Text(this.currentSong.artist)
            .fontSize(12)
            .fontColor('#808080');
          Row() {
            Button('Previous')
              .onClick(() => this.playPrevious());
            Button(this.isPlaying ? 'Pause' : 'Play')
              .onClick(() => this.togglePlay());
            Button('Next')
              .onClick(() => this.playNext());
          }
          .margin(10);
          Button('More')
            .onClick(() => {
              this.showActionSheetMenu();
            });
        }
        .width('100%')
        .alignItems(HorizontalAlign.Center);
      }
    }
    .width('100%')
    .height('100%');
  }

  private togglePlay(): void {
    this.isPlaying = !this.isPlaying;
  }

  private playNext(): void {
    if (!this.currentSong) return;
    const currentIndex = this.songs.findIndex(song => song.id === this.currentSong?.id);
    const nextIndex = (currentIndex + 1) % this.songs.length;
    this.currentSong = this.songs[nextIndex];
  }

  private playPrevious(): void {
    if (!this.currentSong) return;
    const currentIndex = this.songs.findIndex(song => song.id === this.currentSong?.id);
    const prevIndex = (currentIndex - 1 + this.songs.length) % this.songs.length;
    this.currentSong = this.songs[prevIndex];
  }

  private addToPlaylist(): void {
    this.showActionSheet = false;
  }

  private shareSong(): void {
    this.showActionSheet = false;
  }

  private closeActionSheet(): void {
    this.showActionSheet = false;
  }

  private showActionSheetMenu(): void {
    ActionSheet.show({
      title: 'Options',
      message: 'Choose an action',
      autoCancel: true,
      confirm: {
        value: 'Add to Playlist',
        action: () => this.addToPlaylist()
      },
      sheets: [
        {
          value: 'Share',
          action: () => this.shareSong()
        }
      ],
      cancel: () => this.closeActionSheet()
    });
  }
}

