  @State croppedImage: string = ''
  @State showCropper: boolean = false
  @State showResult: boolean = false

  private images: string[] = [
    'app.media.app_icon1',
    'app.media.app_icon2',
    'app.media.app_icon3',
    'app.media.app_icon4'
  ]

  build() {
