import promptAction from '@ohos.promptAction';

interface Message {
  text: string;
  isUser: boolean;
}

@Entry
@Component
struct MessagingApp {
  @State messages: Array<Message> = [];
  @State inputText: string = '';
  @State cachedMap: Resource = $r('app.media.icon');
  @State isAudioPlaying: boolean = false;
  @State cachedAudio: Resource = $r('app.media.icon');

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.messages, (message: Message) => {
          ListItem() {
            Column() {
              Text(message.text)
                .fontSize(16)
                .padding(10)
                .backgroundColor(message.isUser ? '#007AFF' : '#f5f5f5')
                .borderRadius(10)
                .align(Alignment.Start)
                .margin({ left: message.isUser ? '50%' : '0%', right: message.isUser ? '0%' : '50%' })
            }
          }
        })
      }
      .layoutWeight(1)
      .width('100%')
      .padding(10)

      Image(this.cachedMap)
        .width('100%')
        .height(200)
        .margin(10)
        .onClick(() => {
          promptAction.showToast({ message: 'Map loaded from cache' });
        })

      Button(this.isAudioPlaying ? 'Stop Audio' : 'Play Audio')
        .width('50%')
        .height(40)
        .fontSize(16)
        .backgroundColor('#007AFF')
        .margin(10)
        .onClick(() => {
          this.isAudioPlaying = !this.isAudioPlaying;
          promptAction.showToast({ message: this.isAudioPlaying ? 'Audio playing' : 'Audio stopped' });
        })

      Row() {
        TextInput({ placeholder: 'Type a message...' })
          .width('80%')
          .height(40)
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.inputText = value;
          })

        Button('Send')
          .width('20%')
          .height(40)
          .fontSize(16)
          .backgroundColor('#007AFF')
          .onClick(() => {
            if (this.inputText.trim()) {
              this.messages.push({ text: this.inputText, isUser: true } as Message);
              this.inputText = '';
              setTimeout(() => {
                this.messages.push({ text: 'This is a response.', isUser: false } as Message);
              }, 1000);
            } else {
              promptAction.showToast({
                message: 'Please enter a message'
              });
            }
          })
      }
      .width('100%')
      .padding(10)
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

import promptAction from '@ohos.promptAction';

@Entry
@Component
struct PodcastManager {
  @State podcastTitle: string = '';
  @State podcastDescription: string = '';
  @State podcastHost: string = '';
  @State podcastCategory: string = '';
  @State validationErrors: Record<string, string> = {};
  @State activeTab: number = 0;

  validateForm(): boolean {
    this.validationErrors = {};
    let isValid = true;

    if (!this.podcastTitle.trim()) {
      this.validationErrors['title'] = 'Title is required';
      isValid = false;
    }

    if (!this.podcastDescription.trim()) {
      this.validationErrors['description'] = 'Description is required';
      isValid = false;
    }

    if (!this.podcastHost.trim()) {
      this.validationErrors['host'] = 'Host is required';
      isValid = false;
    }

    if (!this.podcastCategory.trim()) {
      this.validationErrors['category'] = 'Category is required';
      isValid = false;
    }

    return isValid;
  }

  submitForm() {
    if (this.validateForm()) {
      promptAction.showToast({ message: 'Podcast submitted successfully', duration: 2000 });
    } else {
      promptAction.showToast({ message: 'Please fix the errors', duration: 2000 });
    }
  }

  build() {
    Column() {
      Row() {
        Button('Podcast Form')
          .onClick(() => { this.activeTab = 0; })
          .backgroundColor(this.activeTab === 0 ? '#007AFF' : '#E5E5EA')
          .margin(5);
        Button('Podcast List')
          .onClick(() => { this.activeTab = 1; })
          .backgroundColor(this.activeTab === 1 ? '#007AFF' : '#E5E5EA')
          .margin(5);
      }
      .width('100%')
      .justifyContent(FlexAlign.Center);

      if (this.activeTab === 0) {
        Column() {
          TextInput({ placeholder: 'Title', text: this.podcastTitle })
            .onChange((value: string) => { this.podcastTitle = value; })
            .width('100%')
            .margin({ bottom: 10 });
          if (this.validationErrors['title']) {
            Text(this.validationErrors['title'])
              .fontSize(12)
              .fontColor(Color.Red)
              .margin({ bottom: 10 });
          }

          TextInput({ placeholder: 'Description', text: this.podcastDescription })
            .onChange((value: string) => { this.podcastDescription = value; })
            .width('100%')
            .margin({ bottom: 10 });
          if (this.validationErrors['description']) {
            Text(this.validationErrors['description'])
              .fontSize(12)
              .fontColor(Color.Red)
              .margin({ bottom: 10 });
          }

          TextInput({ placeholder: 'Host', text: this.podcastHost })
            .onChange((value: string) => { this.podcastHost = value; })
            .width('100%')
            .margin({ bottom: 10 });
          if (this.validationErrors['host']) {
            Text(this.validationErrors['host'])
              .fontSize(12)
              .fontColor(Color.Red)
              .margin({ bottom: 10 });
          }

          TextInput({ placeholder: 'Category', text: this.podcastCategory })
            .onChange((value: string) => { this.podcastCategory = value; })
            .width('100%')
            .margin({ bottom: 10 });
          if (this.validationErrors['category']) {
            Text(this.validationErrors['category'])
              .fontSize(12)
              .fontColor(Color.Red)
              .margin({ bottom: 10 });
          }

          Button('Submit')
            .onClick(() => { this.submitForm(); })
            .width('100%')
            .height(50)
            .margin({ top: 20 });
        }
        .padding(20)
        .width('100%');
      } else {
        Column() {
          Text('Podcast List')
            .fontSize(20)
            .margin({ bottom: 20 });
          List() {
            ListItem() {
              Text('Sample Podcast 1');
            }
            ListItem() {
              Text('Sample Podcast 2');
            }
          }
          .width('100%')
          .height('100%');
        }
        .padding(20)
        .width('100%');
      }
    }
    .width('100%')
    .height('100%');
  }
}

import { TimePicker, Progress, Button, Text, Column, Row } from '@ohos.arkui.component';
