interface Email {
  id: number;
  sender: string;
  subject: string;
  time: string;
}

interface TimePickerResult {
  hour: number;
  minute: number;
}

@Entry
@Component
struct EmailClient {
  @State selectedTime: string = '00:00';
  @State progressValue: number = 0;
  @State emails: Email[] = [];

  private mockEmails: Array<Email> = [
    { id: 1, sender: 'John Doe', subject: 'Meeting Tomorrow', time: '10:30 AM' } as Email,
    { id: 2, sender: 'Jane Smith', subject: 'Project Update', time: '11:45 AM' } as Email,
    { id: 3, sender: 'Alex Johnson', subject: 'Feedback Request', time: '2:15 PM' } as Email
  ];

  build() {
    Column() {
      Text('Email Client')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      TimePicker({ selected: this.selectedTime })
        .onChange((value: TimePickerResult) => {
          this.selectedTime = `${value.hour}:${value.minute}`;
        })
        .margin({ bottom: 20 });

      Button('Sync')
        .width('80%')
        .height(50)
        .backgroundColor('#007AFF')
        .onClick(() => {
          this.progressValue = 0;
          const interval = setInterval(() => {
            if (this.progressValue >= 100) {
              clearInterval(interval);
              this.emails = this.mockEmails;
              promptAction.showToast({
                message: 'Sync completed!',
                duration: 2000
              });
            } else {
              this.progressValue += 1;
            }
          }, 30);
        })
        .margin({ bottom: 20 });

      Progress({ value: this.progressValue, total: 100 })
        .width('80%')
        .height(10)
        .margin({ bottom: 20 });

      List({ space: 10, divider: { strokeWidth: 1, color: '#f5f5f5' } }) {
        ForEach(this.emails, (email: Email) => {
          ListItem() {
            Column() {
              Text(email.sender)
                .fontSize(16)
                .fontWeight(FontWeight.Bold)
                .margin({ bottom: 5 });

              Text(email.subject)
                .fontSize(14)
                .margin({ bottom: 5 });

              Text(email.time)
                .fontSize(12);
            }
            .width('100%')
            .padding(10)
            .backgroundColor('#f5f5f5')
            .borderRadius(8);
          }
        })
      }
      .width('100%')
      .layoutWeight(1);
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

@Entry
@Component
struct SmartwatchApp {
  @State progressValue: number = 0
  @State isRefreshing: boolean = false
  @State sensors: Array<string> = ['Sensor 1', 'Sensor 2', 'Sensor 3']
  @State newSensorName: string = ''
  private timerId: number = -1
  private refreshTimerId: number = -1

  build() {
    Column() {
      // Progress Indicator
      Progress({ value: this.progressValue, total: 100, style: ProgressStyle.Ring })
        .width(150)
        .height(150)
        .margin(20)
      Text(`${this.progressValue}%`)
        .fontSize(20)
        .margin({ bottom: 20 })

      // Pull-to-Refresh
      if (this.isRefreshing) {
        Text('Refreshing...')
          .fontSize(16)
          .margin({ bottom: 20 })
      }

      // Sensor Management UI
      TextInput({ placeholder: 'Enter sensor name', text: this.newSensorName })
        .onChange((value: string) => {
          this.newSensorName = value
        })
        .margin({ bottom: 10 })
      Button('Add Sensor')
        .onClick(() => {
          if (this.newSensorName.trim() !== '') {
            this.sensors.push(this.newSensorName)
            this.newSensorName = ''
          }
        })
        .margin({ bottom: 20 })

      List() {
        ForEach(this.sensors, (sensor: string, index: number) => {
          ListItem() {
            Button(sensor)
              .margin(5)
              .borderRadius(20)
              .backgroundColor('#f0f0f0')
              .onClick(() => {
                this.sensors.splice(index, 1)
              })
          }
        })
      }
      .layoutWeight(1)
      .width('100%')
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .onAppear(() => {
      this.startProgressAnimation()
    })
    .onDisAppear(() => {
      this.stopProgressAnimation()
    })
  }

  private startProgressAnimation() {
    this.timerId = setInterval(() => {
      if (this.progressValue < 100) {
        this.progressValue += 1
      } else {
        this.progressValue = 0
      }
    }, 50)
  }

  private stopProgressAnimation() {
    if (this.timerId !== -1) {
      clearInterval(this.timerId)
      this.timerId = -1
    }
  }

  private handleRefresh() {
    this.isRefreshing = true
    this.refreshTimerId = setTimeout(() => {
      this.isRefreshing = false
      this.progressValue = 0
      this.startProgressAnimation()
    }, 1000)
  }
}

