@Entry
@Component
struct StopwatchABTestingApp {
  @State elapsedTime: number = 0
  @State isRunning: boolean = false
  private timerId: number = -1
  @State testGroups: string[] = ['Group A', 'Group B']
  @State activeGroup: string = 'Group A'
  @State results: Record<string, number[]> = { 'Group A': [], 'Group B': [] }

  build() {
    Column() {
      Text('A/B Testing Stopwatch')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      Row() {
        ForEach(this.testGroups, (group: string) => {
          Button(group)
            .onClick(() => {
              this.activeGroup = group
            })
            .backgroundColor(this.activeGroup === group ? Color.Blue : Color.Gray)
            .fontColor(Color.White)
            .margin(10)
        })
      }

      Text(`Active Group: ${this.activeGroup}`)
        .fontSize(18)
        .margin({ bottom: 20 })

      Text(this.formatTime(this.elapsedTime))
        .fontSize(40)
        .margin(20)

      Row() {
        Button(this.isRunning ? 'Stop' : 'Start')
          .onClick(() => {
            if (this.isRunning) {
              clearInterval(this.timerId)
            } else {
              this.timerId = setInterval(() => {
                this.elapsedTime += 1
              }, 10)
            }
            this.isRunning = !this.isRunning
          })
          .margin(10)

        Button('Reset')
          .onClick(() => {
            clearInterval(this.timerId)
            this.elapsedTime = 0
            this.isRunning = false
          })
          .margin(10)

        Button('Save Result')
          .onClick(() => {
            this.results[this.activeGroup].push(this.elapsedTime)
            this.elapsedTime = 0
            this.isRunning = false
            clearInterval(this.timerId)
          })
          .margin(10)
      }

      Text('Results:')
        .fontSize(18)
        .margin({ top: 20 })

      ForEach(this.testGroups, (group: string) => {
        Column() {
          Text(`${group}: ${this.results[group].join(', ')}`)
            .fontSize(16)
            .margin(5)
        }
      })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }

  private formatTime(time: number): string {
    const minutes = Math.floor(time / 6000)
    const seconds = Math.floor((time % 6000) / 100)
    const centiseconds = time % 100
    return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}.${centiseconds.toString().padStart(2, '0')}`
  }
}

@Entry
@Component
struct TimePickerApp {
  @State selectedTime: Date = new Date()
  @State displayTime: string = ''
  @State isRefreshing: boolean = false
  @State refreshMessage: string = ''

  aboutToAppear() {
    this.updateDisplayTime()
  }

  updateDisplayTime() {
    this.displayTime = this.selectedTime.toLocaleTimeString()
  }

  refreshTime() {
    this.isRefreshing = true
    this.refreshMessage = 'Refreshing...'
    setTimeout(() => {
      this.selectedTime = new Date()
      this.updateDisplayTime()
      this.refreshMessage = 'Refreshed!'
      this.isRefreshing = false
    }, 1000)
  }

  build() {
    Column() {
      Text('Time Picker')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      TimePicker({
        selected: this.selectedTime
      })
        .onChange((value: TimePickerResult) => {
          if (value.hour !== undefined && value.minute !== undefined) {
            this.selectedTime.setHours(value.hour, value.minute)
            this.updateDisplayTime()
          }
        })
        .margin({ bottom: 40 })

      Column() {
        Text('Selected Time:')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ bottom: 8 })

        Text(this.displayTime)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .fontColor('#007AFF')
      }
      .padding(16)
      .borderRadius(12)
      .backgroundColor('#F0F0F0')

      if (this.isRefreshing || this.refreshMessage) {
        Column() {
          Text(this.refreshMessage)
            .fontSize(16)
            .fontColor('#007AFF')
        }
        .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White)
  }
}

