import promptAction from '@ohos.promptAction';

@Entry
@Component
struct TranslationPodcastPlayer {
  @State private isPlaying: boolean = false;
  @State private currentTime: number = 0;
  @State private translationText: string = '';
  @State private alertMessage: string = '';

  build() {
    Column() {
      Row({ space: 10 }) {
        Button(this.isPlaying ? 'Pause' : 'Play')
          .onClick(() => {
            this.isPlaying = !this.isPlaying;
          })
          .width(100)
          .height(50);

        Slider({
          value: this.currentTime,
          min: 0,
          max: 100,
          step: 1,
          style: SliderStyle.OutSet
        })
          .width('70%')
          .onChange((value: number) => {
            this.currentTime = value;
          });
      }
      .width('100%')
      .margin({ bottom: 20 });

      TextInput({ placeholder: 'Enter translation...' })
        .width('80%')
        .height(100)
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.translationText = value;
        });

      Button('Submit Translation')
        .onClick(() => {
          if (this.translationText.trim() === '') {
            this.alertMessage = 'Translation cannot be empty!';
            promptAction.showDialog({
              title: 'Error',
              message: this.alertMessage,
              buttons: [
                {
                  text: 'OK',
                  color: '#000000'
                }
              ]
            }).then((result) => {
              if (result.index === 0) {
                console.log('Dialog closed');
              }
            });
          } else {
            console.log('Translation submitted:', this.translationText);
          }
        })
        .width(200)
        .height(50);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

@Entry
@Component
struct MeditationApp {
  @State refreshing: boolean = false
  @State listData: string[] = ['Placeholder 1', 'Placeholder 2', 'Placeholder 3']
  @State userRating: number = 0

  build() {
    Column() {
      // Custom Refresh Component
      Column() {
        List() {
          ForEach(this.listData, (item: string, index: number) => {
            ListItem() {
              Row() {
                Image($r('app.media.video_placeholder_' + (index + 1)))
                  .width(100)
                  .height(100)
                  .margin(10)
                Text(item)
                  .fontSize(16)
                  .padding(16)
              }
            }
          }, (item: string) => item)
        }
        .width('100%')
      }
      .onTouch((event: TouchEvent) => {
        if (event.type === TouchType.Down) {
          this.refreshing = true
          setTimeout(() => {
            this.listData = ['New Placeholder 1', 'New Placeholder 2', 'New Placeholder 3']
            this.refreshing = false
          }, 2000)
        }
      })

      // Custom RatingBar Component
      Row() {
        ForEach(new Array(5).fill(0), (item: number, index: number) => {
          Image(index < this.userRating ? $r('app.media.app_icon') : $r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ right: 5 })
            .onClick(() => {
              this.userRating = index + 1
            })
        })
      }
      .margin({ top: 20 })

      Text(`Your rating: ${this.userRating}`)
        .fontSize(18)
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

