@Entry
@Component
struct GestureRecognitionExample {
  @State private tapCount: number = 0;
  @State private swipeDirection: string = "None";
  @State private drawerOpen: boolean = false;

  build() {
    Column({ space: 20 }) {
      Text(`Tap Count: ${this.tapCount}`)
        .fontSize(20)
        .fontColor(Color.Black);

      Text(`Swipe Direction: ${this.swipeDirection}`)
        .fontSize(20)
        .fontColor(Color.Black);

      Button('Toggle Drawer')
        .width(150)
        .height(50)
        .backgroundColor(Color.Blue)
        .onClick(() => {
          this.drawerOpen = !this.drawerOpen;
        });

      Flex({ justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
        Text("Tap or Swipe Here")
          .fontSize(18)
          .padding(20)
          .backgroundColor(0xeeeeee)
          .borderRadius(10)
          .gesture(
            TapGesture()
              .onAction(() => {
                this.tapCount += 1;
              })
          )
          .gesture(
            PanGesture()
              .onActionStart((event: GestureEvent) => {
                if (event.offsetX > 5) {
                  this.swipeDirection = "Right";
                } else if (event.offsetX < -5) {
                  this.swipeDirection = "Left";
                } else if (event.offsetY > 5) {
                  this.swipeDirection = "Down";
                } else if (event.offsetY < -5) {
                  this.swipeDirection = "Up";
                }
              })
          );
      }
      .width('100%')
      .height(200);

      if (this.drawerOpen) {
        Column() {
          Text("Drawer Content")
            .fontSize(20)
            .fontColor(Color.Black)
            .margin({ bottom: 10 });

          Button("Close Drawer")
            .width(150)
            .height(50)
            .backgroundColor(Color.Red)
            .onClick(() => {
              this.drawerOpen = false;
            });
        }
        .width('80%')
        .height('50%')
        .backgroundColor(Color.White)
        .borderRadius(10)
        .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(Color.White);
  }
}

