@Entry
@Component
struct TaskManagerApp {
  @State activeTab: number = 0;
  @State searchText: string = '';
  @State tasks: string[] = ['Task 1', 'Task 2', 'Task 3'];
  @State completedTasks: string[] = ['Completed Task 1', 'Completed Task 2'];
  @State archivedTasks: string[] = ['Archived Task 1'];
  @State showDeleteDialog: boolean = false;
  @State taskToDelete: string = '';

  build() {
    Column() {
      Row() {
        TextInput({ placeholder: 'Search tasks...', text: this.searchText })
          .width('80%')
          .onChange((value: string) => {
            this.searchText = value;
          });
        Button('Search')
          .onClick(() => {
          });
      }
      .width('100%')
      .padding(16);

      Tabs({ barPosition: BarPosition.End }) {
        TabContent() {
          List() {
            ForEach(this.tasks, (task: string) => {
              ListItem() {
                Row() {
                  Text(task)
                    .fontSize(18);
                  Button('Delete')
                    .onClick(() => {
                      this.taskToDelete = task;
                      this.showDeleteDialog = true;
                    });
                }
                .justifyContent(FlexAlign.SpaceBetween);
              }
            });
          }
          .width('100%');
        }
        .tabBar('Tasks');

        TabContent() {
          List() {
            ForEach(this.completedTasks, (task: string) => {
              ListItem() {
                Row() {
                  Text(task)
                    .fontSize(18);
                  Button('Delete')
                    .onClick(() => {
                      this.taskToDelete = task;
                      this.showDeleteDialog = true;
                    });
                }
                .justifyContent(FlexAlign.SpaceBetween);
              }
            });
          }
          .width('100%');
        }
        .tabBar('Completed');

        TabContent() {
          List() {
            ForEach(this.archivedTasks, (task: string) => {
              ListItem() {
                Row() {
                  Text(task)
                    .fontSize(18);
                  Button('Delete')
                    .onClick(() => {
                      this.taskToDelete = task;
                      this.showDeleteDialog = true;
                    });
                }
                .justifyContent(FlexAlign.SpaceBetween);
              }
            });
          }
          .width('100%');
        }
        .tabBar('Archived');
      }
      .onChange((index: number) => {
        this.activeTab = index;
      });

      if (this.showDeleteDialog) {
        Column() {
          Text('Delete Task')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 16 });
          Text(`Are you sure you want to delete \"${this.taskToDelete}\"?`)
            .margin({ bottom: 24 });
          Row() {
            Button('Cancel')
              .onClick(() => {
                this.showDeleteDialog = false;
              })
              .margin({ right: 16 });
            Button('Delete')
              .onClick(() => {
                this.deleteTask(this.taskToDelete);
                this.showDeleteDialog = false;
              });
          }
          .justifyContent(FlexAlign.Center);
        }
        .width('80%')
        .padding(24)
        .backgroundColor(Color.White)
        .borderRadius(8)
        .shadow({ radius: 8, color: Color.Gray })
      }
    }
    .width('100%')
    .height('100%');
  }

  private deleteTask(task: string) {
    if (this.activeTab === 0) {
      this.tasks = this.tasks.filter(t => t !== task);
    } else if (this.activeTab === 1) {
      this.completedTasks = this.completedTasks.filter(t => t !== task);
    } else {
      this.archivedTasks = this.archivedTasks.filter(t => t !== task);
    }
  }
}

