@Entry
@Component
struct MealPlanningApp {
  @State searchText: string = '';
  @State meals: string[] = [
    'Pasta Carbonara',
    'Chicken Curry',
    'Vegetable Stir Fry',
    'Beef Tacos',
    'Salmon Salad',
    'Mushroom Risotto',
    'Pizza Margherita',
    'Greek Salad',
    'Burger and Fries',
    'Sushi Rolls'
  ];
  @State filteredMeals: string[] = this.meals;
  @State email: string = '';
  @State password: string = '';
  @State acceptedTerms: boolean = false;
  @State showError: boolean = false;
  @State errorMessage: string = '';

  filteredMealsList(): string[] {
    if (this.searchText.trim() === '') {
      return this.meals;
    } else {
      return this.meals.filter(meal =>
        meal.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  handleLogin() {
    if (!this.email || !this.password) {
      this.errorMessage = 'Email and password are required.';
      this.showError = true;
      return;
    }
    if (!this.acceptedTerms) {
      this.errorMessage = 'Please accept the terms and conditions.';
      this.showError = true;
      return;
    }
    this.errorMessage = 'Login successful!';
    this.showError = true;
  }

  build() {
    Column() {
      // Authentication Section
      Column() {
        Text('Meal Planner Login')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 });

        TextInput({ placeholder: 'Email', text: this.email })
          .onChange((value: string) => {
            this.email = value;
          })
          .width('80%')
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Password', text: this.password })
          .type(InputType.Password)
          .onChange((value: string) => {
            this.password = value;
          })
          .width('80%')
          .margin({ bottom: 10 });

        Row() {
          Text('Accept Terms and Conditions')
            .fontSize(16)
            .margin({ right: 10 });
          // Custom Checkbox implementation
          Column()
            .width(24)
            .height(24)
            .borderRadius(4)
            .borderWidth(1)
            .borderColor(this.acceptedTerms ? '#4CAF50' : '#000000')
            .backgroundColor(this.acceptedTerms ? '#4CAF50' : '#FFFFFF')
            .onClick(() => {
              this.acceptedTerms = !this.acceptedTerms;
            });
        }
        .margin({ bottom: 20 });

        Button('Login')
          .onClick(() => {
            this.handleLogin();
          })
          .width('60%')
          .backgroundColor('#4CAF50')
          .fontColor(Color.White)
          .fontSize(18);

        if (this.showError) {
          Text(this.errorMessage)
            .fontSize(16)
            .fontColor(this.errorMessage.includes('successful') ? '#4CAF50' : '#FF0000')
            .margin({ top: 10 });
        }
      }
      .padding(20)
      .width('100%')
      .alignItems(HorizontalAlign.Center);

      // Search and Meal List Section
      Column() {
        TextInput({ placeholder: 'Search meals...', text: this.searchText })
          .onChange((value: string) => {
            this.searchText = value;
            this.filteredMeals = this.filteredMealsList();
          })
          .width('90%')
          .margin(16)
          .backgroundColor('#F0F0F0')
          .borderRadius(8)
          .padding({ left: 12, right: 12, top: 8, bottom: 8 });

        if (this.filteredMeals.length > 0) {
          List() {
            ForEach(this.filteredMeals, (meal: string) => {
              ListItem() {
                Text(meal)
                  .fontSize(18)
                  .padding(12);
              }
            }, (meal: string) => meal);
          }
        } else {
          Text('No meals found')
            .fontSize(16)
            .fontColor('#808080')
            .padding(16);
        }
      }
      .width('100%')
      .height('60%');
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

