        .width(100)
        .height(100)
        .gesture(
          GestureGroup(
            GestureMode.Sequence,
            PanGesture({ direction: PanDirection.All })
              .onActionUpdate((event: GestureEvent) => {
                this.offsetX = event.offsetX;
                this.offsetY = event.offsetY;
              }),
            PinchGesture()
              .onActionUpdate((event: PinchGestureEvent) => {
                this.currentScale = event.scale;
              }),
            RotationGesture()
              .onActionUpdate((event: RotationGestureEvent) => {
                this.rotation = event.angle;
              }),
            TapGesture({ count: 1 })
              .onAction(() => {
                animateTo({ duration: 300, curve: Curves.EASE_IN_OUT }, () => {
                  this.offsetX = 0;
                  this.offsetY = 0;
                  this.currentScale = 1;
                  this.rotation = 0;
                });
              })
          )
        )
        .transform({ translate: { x: this.offsetX, y: this.offsetY }, scale: this.currentScale, rotate: this.rotation })
        .animation({ duration: 300, curve: Curves.EASE_IN_OUT });

      Row() {
        Button('Scale Up')
          .onClick(() => {
            animateTo({ duration: 300, curve: Curves.EASE_IN_OUT }, () => {
              this.currentScale *= 1.5;
            });
          });
        Button('Rotate')
          .onClick(() => {
            animateTo({ duration: 300, curve: Curves.EASE_IN_OUT }, () => {
              this.rotation += 45;
            });
          });
        Button('Reset')
          .onClick(() => {
            animateTo({ duration: 300, curve: Curves.EASE_IN_OUT }, () => {
              this.offsetX = 0;
              this.offsetY = 0;
              this.currentScale = 1;
              this.rotation = 0;
            });
          });
      }
      .justifyContent(FlexAlign.SpaceAround)
      .width('100%')
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }
}

