    { id: '2', subject: 'Project Update', sender: 'jane.smith@example.com', time: 'Yesterday', isRead: true },
    { id: '3', subject: 'Weekly Newsletter', sender: 'newsletter@example.com', time: '2 days ago', isRead: false }
  ]
  @State isOffline: boolean = false

  build() {
    Column() {
      Row() {
        Text('Email Client')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
