@Entry
@Component
struct PullToRefreshApp {
  @State private offsetY: number = 0;
  @State private isRefreshing: boolean = false;
  @State private refreshText: string = "Pull to refresh";

  build() {
    Column() {
      Text(this.refreshText)
        .fontSize(20)
        .fontColor(Color.Black)
        .margin({ top: 20 });

      Canvas()
        .width('100%')
        .height(200)
        .backgroundColor(Color.Gray)
        .gesture(
          PanGesture({ direction: PanDirection.Down })
            .onActionStart(() => {
              this.refreshText = "Release to refresh";
            })
            .onActionUpdate((event: GestureEvent) => {
              this.offsetY = event.offsetY;
            })
            .onActionEnd(() => {
              if (this.offsetY > 100) {
                this.isRefreshing = true;
                this.refreshText = "Refreshing...";
                setTimeout(() => {
                  this.isRefreshing = false;
                  this.refreshText = "Pull to refresh";
                }, 2000);
              } else {
                this.refreshText = "Pull to refresh";
              }
              this.offsetY = 0;
            })
        );

      if (this.isRefreshing) {
        LoadingProgress()
          .width(50)
          .height(50)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Start)
    .backgroundColor(Color.White);
  }
}

@Entry
@Component
struct DatePickerApp {
  @State selectedDate: Date = new Date()
  @State displayDate: string = ''
  @State backgroundColor: ResourceColor = '#FFFFFF'

  aboutToAppear() {
    this.updateDisplayDate()
  }

  updateDisplayDate() {
    this.displayDate = this.selectedDate.toLocaleDateString()
  }

  onOrientationChange(isLandscape: boolean) {
    this.backgroundColor = isLandscape ? '#808080' : '#FFFFFF'
  }

  onSwipeLeft() {
    this.selectedDate = new Date(this.selectedDate.setDate(this.selectedDate.getDate() - 1))
    this.updateDisplayDate()
  }

  onSwipeRight() {
    this.selectedDate = new Date(this.selectedDate.setDate(this.selectedDate.getDate() + 1))
    this.updateDisplayDate()
  }

  build() {
    Column() {
      Text('Select a Date')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      DatePicker({
        start: new Date('2000-01-01'),
        end: new Date('2030-12-31'),
        selected: this.selectedDate
      })
        .onDateChange((value: Date) => {
          this.selectedDate = value
          this.updateDisplayDate()
        })
        .margin({ bottom: 40 })

      Column() {
        Text('Selected Date:')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ bottom: 8 })

        Text(this.displayDate)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .fontColor('#007AFF')
      }
      .padding(16)
      .borderRadius(12)
      .backgroundColor('#F0F0F0')
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(this.backgroundColor)
    .gesture(
      PanGesture({ direction: PanDirection.Horizontal })
        .onActionStart(() => {
        })
        .onActionUpdate((event: GestureEvent) => {
          if (event.offsetX > 0) {
            this.onSwipeRight()
          } else if (event.offsetX < 0) {
            this.onSwipeLeft()
          }
        })
    )
  }
}

