        });

      Button('Authenticate')
        .width('50%')
        .onClick(() => {
          this.dialogVisible = true;
          this.mockBiometricAuth();
        });

      if (this.dialogVisible) {
        Column() {
          Text('Biometric Authentication')
            .fontSize(20)
            .fontWeight(700);
          Text('Please authenticate to proceed.')
            .margin({ top: 10, bottom: 20 });
          Row() {
            Button('Authenticate')
              .onClick(() => {
                this.dialogVisible = false;
              });
            Button('Cancel')
              .margin({ left: 10 })
              .onClick(() => {
                this.dialogVisible = false;
              });
