import { Column, Text, Stack, ForEach, Tabs, TabContent } from '@ohos.arkui.dom';
import { PanGesture, GestureEvent } from '@ohos.arkui.gesture';
import { AlertDialog } from '@ohos.arkui.dialog';

interface EmailItem {
  id: number;
  subject: string;
  sender: string;
  content: string;
  isSelected: boolean;
}

@Entry
@Component
struct EmailClient {
  @State emails: EmailItem[] = [
    { id: 1, subject: 'Meeting', sender: 'john@example.com', content: 'Discuss project updates', isSelected: false },
    { id: 2, subject: 'Report', sender: 'jane@example.com', content: 'Monthly report attached', isSelected: false },
  ];
  @State draggedItem: EmailItem | null = null;
  @State showAlert: boolean = false;

  build() {
    Column() {
      Tabs() {
        ForEach(this.emails, (email: EmailItem) => {
          TabContent() {
            Stack() {
              Column() {
                Text(email.subject).fontSize(16).margin(5);
                Text(`From: ${email.sender}`).fontSize(14).margin(5);
                Text(email.content).fontSize(12).margin(5);
              }
              .width('100%')
              .padding(10)
              .border({ width: 1, color: '#CCCCCC' })
              .gesture(
                PanGesture({
                  onActionStart: (event: GestureEvent) => {
                    if (Math.abs(event.offsetX) > 5 || Math.abs(event.offsetY) > 5) {
                      this.draggedItem = email;
                    }
                  },
                  onActionUpdate: (event: GestureEvent) => {
                  },
                  onActionEnd: () => {
                    if (this.draggedItem) {
                      this.showAlert = true;
                    }
                  }
                })
              );
            }
          }
        }, (email: EmailItem) => email.id.toString());
      }

      Stack() {
        Text('Drop Zone').fontSize(16).margin(10);
      }
      .width('100%')
      .height(100)
      .border({ width: 2, color: '#0000FF' })
      .onClick(() => {
        if (this.draggedItem) {
          this.showAlert = true;
        }
      });

      this.showAlert ?
      AlertDialog({
        title: 'Email Dropped',
        message: `Email \"${this.draggedItem?.subject}\" dropped successfully`,
        confirm: {
          value: 'OK',
          action: () => {
            this.showAlert = false;
            this.draggedItem = null;
          }
        }
      }) : null
    }
    .width('100%')
    .height('100%')
    .padding(10);
  }
}

import media from '@ohos.multimedia.media';
import { BusinessError } from '@ohos.base';

@Entry
@Component
struct LanguageLearningTranslator {
  @State currentText: string = '';
  @State translatedText: string = '';
  @State translationHistory: string[] = [];
  @State showBottomSheet: boolean = false;
  private avPlayer: media.AVPlayer | null = null;

  build() {
    Column() {
      TextInput({ placeholder: 'Enter text to translate' })
        .width('90%')
        .height(50)
        .margin({ top: 20, bottom: 20 })
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .onChange((value: string) => {
          this.currentText = value;
        });

      Button('Translate')
        .width('90%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.currentText) {
            this.translatedText = 'Translated: ' + this.currentText;
            this.translationHistory.unshift(this.translatedText);
            this.playNotificationSound();
          }
        });

      Text('History:')
        .fontSize(18)
        .margin({ top: 20, bottom: 10 });

      List({ space: 10 }) {
        ForEach(this.translationHistory, (item: string) => {
          ListItem() {
            Text(item)
              .fontSize(16)
              .padding(10);
          }
          .borderRadius(5)
          .backgroundColor('#f0f0f0');
        });
      }
      .width('90%')
      .height('40%');

      Button('Options')
        .width('90%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .margin({ top: 20 })
        .onClick(() => {
          this.showBottomSheet = true;
        });

      if (this.showBottomSheet) {
        Column()
          .width('100%')
          .height('100%')
          .backgroundColor('#000000')
          .opacity(0.5)
          .onClick(() => {
            this.showBottomSheet = false;
          })
          .position({ x: 0, y: 0 })
          .zIndex(1);

        Column() {
          Column() {
            Button('Play Audio')
              .width('90%')
              .height(50)
              .fontSize(18)
              .backgroundColor('#007AFF')
              .margin({ top: 20 })
              .onClick(() => {
                this.playAudio();
              });

            Button('Close')
              .width('90%')
              .height(50)
              .fontSize(18)
              .backgroundColor('#FF3B30')
              .margin({ top: 20 })
              .onClick(() => {
                this.showBottomSheet = false;
              });
          }
          .width('100%')
          .height('50%')
          .backgroundColor('#e0e0e0')
          .alignItems(HorizontalAlign.Center);
        }
        .width('100%')
        .position({ x: 0, y: '50%' })
        .zIndex(2);
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }

  private playNotificationSound() {
    try {
      media.createAVPlayer().then((avPlayer: media.AVPlayer) => {
        this.avPlayer = avPlayer;
        this.avPlayer.url = 'resource://rawfile/notification.mp3';
        this.avPlayer.on('error', (err: BusinessError) => {
          console.error('Audio error:', err);
        });
        this.avPlayer.play();
      }).catch((err: BusinessError) => {
        console.error('Failed to create AVPlayer:', err);
      });
    } catch (err) {
      console.error('Unexpected error:', err);
    }
  }

  private playAudio() {
    if (this.translatedText) {
      this.playNotificationSound();
    }
  }

  aboutToDisappear() {
    if (this.avPlayer) {
      this.avPlayer.release().then(() => {
        this.avPlayer = null;
      }).catch((err: BusinessError) => {
        console.error('Failed to release AVPlayer:', err);
      });
    }
  }
}

import { DatePicker, Image, Button } from '@ohos.arkui.component';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct MovieTicketBooking {
  @State selectedDate: string = '';
  @State showTimes: string[] = [];
  @State selectedTime: string = '';
  @State voiceCommand: string = '';

  build() {
    Column() {
      Image($r('app.media.theater_map'))
        .width('100%')
        .height(200)
        .margin({ top: 10, bottom: 10 });

      DatePicker({
        start: new Date().toISOString().split('T')[0],
        end: new Date(Date.now() + 90 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        selected: this.selectedDate
      })
      .onChange((date: string) => {
        this.selectedDate = date;
        this.updateShowTimes(date);
      })
      .margin({ bottom: 10 });

      if (this.showTimes.length > 0) {
        Column() {
          Text('Select Showtime:')
            .fontSize(18)
            .margin({ bottom: 5 });
          ForEach(this.showTimes, (time: string) => {
            Button(time)
              .onClick(() => {
                this.selectedTime = time;
              })
              .margin({ bottom: 5 });
          });
        }
        .margin({ bottom: 10 });
      }

      Button($r('app.media.mic_icon'))
        .onClick(() => {
          this.handleVoiceCommand();
        })
        .margin({ top: 10 });

      if (this.selectedDate && this.selectedTime) {
        Button('Confirm Booking')
          .onClick(() => {
            promptAction.showToast({
              message: `Booking confirmed for ${this.selectedDate} at ${this.selectedTime}`,
              duration: 2000
            });
          })
          .margin({ top: 10 });
      }
    }
    .padding(16);
  }

  private updateShowTimes(date: string) {
    this.showTimes = ['10:00 AM', '2:00 PM', '6:00 PM', '10:00 PM'];
  }

  private handleVoiceCommand() {
    if (this.voiceCommand.includes('select date')) {
      const date = this.voiceCommand.split('select date ')[1];
      this.selectedDate = date;
      this.updateShowTimes(date);
    } else if (this.voiceCommand.includes('confirm booking')) {
      promptAction.showToast({
        message: `Booking confirmed for ${this.selectedDate} at ${this.selectedTime}`,
        duration: 2000
      });
    }
  }
}

