          .height('70%')
          .objectFit(ImageFit.Cover)
      } else {
        Text('Please authenticate to view the map')
          .fontSize(18)
          .margin({ bottom: 20 })
      }

      Checkbox({ name: 'Biometric Authentication', group: 'auth' })
        .onChange((isChecked: boolean) => {
          this.isAuthenticated = isChecked
          if (this.isAuthenticated) {
            this.showMap = true
          } else {
            this.showMap = false
          }
        })
        .select(this.isAuthenticated)
        .width('80%')
        .height(40)
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
  }
}

