interface Note {
  id: number;
  content: string;
  rotation: number;
}

@Entry
@Component
struct NoteApp {
  @State notes: Array<Note> = [];
  @State newNote: string = '';
  @State rotationAngle: number = 0;
  @State progressValue: number = 0;
  @State isLayoutA: boolean = true;

  build() {
    Column() {
      TextInput({ placeholder: 'Enter new note...', text: this.newNote })
        .height(100)
        .width('90%')
        .onChange((value: string) => {
          this.newNote = value;
        })
        .margin(10)
        .gesture(
          RotationGesture()
            .onActionStart(() => {
              this.rotationAngle = 0;
            })
            .onActionUpdate((event: RotationGestureEvent) => {
              this.rotationAngle = event.angle;
            })
        )

      Button('Add Note')
        .onClick(() => {
          if (this.newNote.trim()) {
            this.notes.push({
              id: Date.now(),
              content: this.newNote,
              rotation: this.rotationAngle
            })
            this.newNote = ''
            this.rotationAngle = 0
          }
        })
        .margin(10)

      Progress({ value: this.progressValue, total: 100 })
        .width('90%')
        .margin(10)

      Button('Toggle Layout')
        .onClick(() => {
          this.isLayoutA = !this.isLayoutA
          this.progressValue = this.isLayoutA ? 0 : 50
        })
        .margin(10)

      List() {
        ForEach(this.notes, (note: Note) => {
          ListItem() {
            Row() {
              Text(note.content)
                .width('80%')
                .rotate({ angle: note.rotation })
              Button('Delete')
                .onClick(() => {
                  this.notes = this.notes.filter((n: Note) => n.id !== note.id)
                })
            }
            .padding(10)
          }
        })
      }
      .width('100%')
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

