@Entry
@Component
struct MoodTracker {
  private moodItems: MoodItem[] = [
    { id: 1, mood: 'Happy', icon: $r('app.media.happy'), description: 'Feeling joyful and cheerful' },
    { id: 2, mood: 'Sad', icon: $r('app.media.sad'), description: 'Feeling down or unhappy' },
    { id: 3, mood: 'Angry', icon: $r('app.media.angry'), description: 'Feeling frustrated or irritated' },
    { id: 4, mood: 'Calm', icon: $r('app.media.calm'), description: 'Feeling relaxed and peaceful' }
  ];

  @State currentMood: MoodItem = this.moodItems[0];

  build() {
    Column() {
      Swiper() {
        ForEach(this.moodItems, (item: MoodItem) => {
          Column() {
            Image(item.icon)
              .width(100)
