      Column() {
        Text(this.currentMood.mood)
          .fontSize(24)
          .margin(10)
          .accessibilityDescription(`Current mood: ${this.currentMood.mood}`);
        Text(this.currentMood.description)
          .fontSize(16)
          .margin(10)
