}

@Entry
@Component
struct MealPlanner {
  @State selectedDate: Date = new Date();
  @State meals: string[] = ['Breakfast', 'Lunch', 'Dinner'];
  @State currentMeal: string = '';
  @State themeValue: number = 0;
  @State timerId: number = -1;

  aboutToAppear() {
    this.updateCurrentMeal();
    this.timerId = setInterval(() => {
      this.updateCurrentMeal();
    }, 1000);
  }

  aboutToDisappear() {
    if (this.timerId !== -1) {
      clearInterval(this.timerId);
    }
  }

  updateCurrentMeal() {
    const hours = new Date().getHours();
    if (hours < 10) {
      this.currentMeal = this.meals[0]; // Breakfast
    } else if (hours < 15) {
      this.currentMeal = this.meals[1]; // Lunch
    } else {
      this.currentMeal = this.meals[2]; // Dinner
    }
  }

  onDateChange(value: Date) {
    this.selectedDate = value;
  }

  onThemeChange(value: number) {
    this.themeValue = value;
  }

  build() {
    Column() {
      Text('Meal Planner')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      DatePicker({
        start: new Date('2000-01-01'),
        end: new Date('2030-12-31'),
        selected: this.selectedDate
      })
        .onDateChange((value: Date) => {
          this.onDateChange(value);
        })
        .margin({ bottom: 20 });

      Text(`Current Meal: ${this.currentMeal}`)
        .fontSize(18)
        .margin({ bottom: 20 });

      Slider({
        value: this.themeValue,
        min: 0,
        max: 2,
        step: 1,
        style: SliderStyle.OutSet
      })
        .onChange((value: number) => {
          this.onThemeChange(value);
        })
        .margin({ bottom: 20 });

      Text(`Theme: ${this.themeValue === 0 ? 'Light' : this.themeValue === 1 ? 'Dark' : 'Auto'}`)
        .fontSize(16);
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(this.themeValue === 0 ? Color.White : this.themeValue === 1 ? Color.Black : Color.Gray);
  }
}

