import { TextInput, TextArea, Button, List, ListItem, Column, Row, Text } from '@ohos.arkui.dom';
import Web from '@ohos.web.webview';
import WebviewController from '@ohos.web.webview';

interface Note {
  id: number;
  title: string;
  content: string;
}

@Entry
@Component
struct NoteApp {
  @State notes: Note[] = [];
  @State currentPage: number = 1;
  @State pageSize: number = 5;
  @State newTitle: string = '';
  @State newContent: string = '';
  @State renderTime: number = 0;
  @State loadTime: number = 0;
  @State webviewController: WebviewController = new WebviewController();

  get paginatedNotes(): Note[] {
    const start = (this.currentPage - 1) * this.pageSize;
    return this.notes.slice(start, start + this.pageSize);
  }

  get totalPages(): number {
    return Math.ceil(this.notes.length / this.pageSize);
  }

  build() {
    Column() {
      Column() {
        TextInput({ placeholder: 'Note title', text: this.newTitle })
          .onChange((value: string) => {
            this.newTitle = value;
          })
          .margin(10);

        TextArea({ placeholder: 'Note content', text: this.newContent })
          .onChange((value: string) => {
            this.newContent = value;
          })
          .margin(10);

        Row() {
          Button('Add Note')
            .onClick(() => {
              if (this.newTitle && this.newContent) {
                this.notes.unshift({
                  id: Date.now(),
                  title: this.newTitle,
                  content: this.newContent
                });
                this.newTitle = '';
                this.newContent = '';
              }
            })
            .margin(10);

          Button('Clear All')
            .onClick(() => {
              this.notes = [];
              this.currentPage = 1;
            })
            .margin(10);
        }
      }

      List() {
        ForEach(this.paginatedNotes, (note: Note) => {
          ListItem() {
            Column() {
              Text(note.title)
                .fontSize(18)
                .fontWeight(700)
                .margin({ bottom: 4 });

              Text(note.content)
                .fontSize(14)
                .fontColor('#666666');
            }
            .padding(10)
            .backgroundColor('#FFFFFF')
            .borderRadius(12)
            .margin({ bottom: 12 });
          }
        });
      }
      .height('40%');

      Row() {
        Button('Prev')
          .onClick(() => {
            if (this.currentPage > 1) {
              this.currentPage--;
            }
          })
          .enabled(this.currentPage > 1)
          .margin(10);

        Text(`Page ${this.currentPage} of ${this.totalPages}`)
          .margin(10);

        Button('Next')
          .onClick(() => {
            if (this.currentPage < this.totalPages) {
              this.currentPage++;
            }
          })
          .enabled(this.currentPage < this.totalPages)
          .margin(10);
      }

      Web({ src: '', controller: this.webviewController })
        .height('40%')
        .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#f5f5f5');
  }
}

@Entry
@Component
struct CustomActionSheet {
  @State isVisible: boolean = false;
  @State offsetY: number = 0;
  @State selectedItems: string[] = [];

  private items: string[] = ['Option 1', 'Option 2', 'Option 3', 'Option 4'];

  build() {
    Column() {
      Button('Show ActionSheet')
        .onClick(() => {
          this.isVisible = true;
        })
        .margin(20);

      if (this.isVisible) {
        Column()
          .width('100%')
          .height('60%')
          .backgroundColor('#FFFFFF')
          .borderRadius(10)
          .position({ x: 0, y: '40%' })
          .gesture(
            PanGesture()
              .onActionStart(() => {
                console.info('Pan start');
              })
              .onActionUpdate((event: GestureEvent) => {
                this.offsetY = event.offsetY;
              })
              .onActionEnd(() => {
                animateTo({ duration: 300 }, () => {
                  if (this.offsetY > 100) {
                    this.isVisible = false;
                  }
                  this.offsetY = 0;
                });
              })
          )
          .transform({ translate: { y: this.offsetY } })
          .animation({ duration: 300 })
          .onClick(() => {
          }) {

          Column()
            .width('100%')
            .padding(20)
            .justifyContent(FlexAlign.Start)
            .alignItems(HorizontalAlign.Start)
            .onClick(() => {
            }) {
              Text('Select Options')
                .fontSize(20)
                .margin({ bottom: 20 });

              ForEach(this.items, (item: string) => {
                Row()
                  .width('100%')
                  .margin({ bottom: 10 })
                  .alignItems(VerticalAlign.Center) {
                    Text(item)
                      .fontSize(16)
                      .margin({ right: 10 });

                    Checkbox()
                      .select(this.selectedItems.includes(item))
                      .onChange((isSelected: boolean) => {
                        let newSelected = [...this.selectedItems];
                        if (isSelected) {
                          newSelected.push(item);
                        } else {
                          newSelected = newSelected.filter(i => i !== item);
                        }
                        this.selectedItems = newSelected;
                      });
                  }
              });

              Button('Confirm')
                .onClick(() => {
                  this.isVisible = false;
                  console.info('Selected Items:', this.selectedItems);
                })
                .margin({ top: 20 });
            }
        }
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

