interface PasswordEntry {
  id: string
  title: string
  username: string
  password: string
  notes: string
}

@Entry
@Component
struct PasswordList {
  @State passwords: PasswordEntry[] = []
  @State selectedEntry: PasswordEntry = { id: '', title: '', username: '', password: '', notes: '' }

  build() {
    Column() {
      Scroll() {
        List({ space: 10 }) {
          ForEach(this.passwords, (item: PasswordEntry) => {
            ListItem() {
              Column() {
                Text(item.title).fontSize(18).fontWeight(FontWeight.Bold)
                Text('Username: ' + item.username).fontSize(14)
                Text('Password: ••••••••').fontSize(14)
              }
              .onClick(() => {
                this.selectedEntry = item
                router.pushUrl({
                  url: 'pages/PasswordDetail',
                  params: { entry: item }
                })
              })
            }
          })
        }
      }
      .width('100%')
      .height('80%')

      Button('Add New')
        .onClick(() => {
          this.selectedEntry = { id: '', title: '', username: '', password: '', notes: '' }
          router.pushUrl({
            url: 'pages/PasswordDetail',
            params: { entry: this.selectedEntry }
          })
        })
        .width('80%')
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .padding(10)
  }

  handleSave(entry: PasswordEntry): void {
    if (entry.id) {
      const index = this.passwords.findIndex(p => p.id === entry.id)
      if (index >= 0) {
        this.passwords[index] = entry
      }
    } else {
      entry.id = Math.random().toString(36).substring(2, 9)
      this.passwords.push(entry)
    }
  }
}

