import { Column, Row, Text, Button, TextInput, List, ListItem, Refresh } from '@ohos.arkui.component';
import preferences from '@ohos.data.preferences';
import common from '@ohos.app.ability.common';

interface Habit {
  id: number;
  name: string;
  completed: boolean;
}

@Entry
@Component
struct HabitTracker {
  @State habits: Habit[] = [];
  @State newHabit: string = '';
  @State refreshing: boolean = false;

  aboutToAppear() {
    this.loadHabits();
  }

  async loadHabits(): Promise<void> {
    try {
      const context = getContext(this) as common.UIAbilityContext;
      const prefs = await preferences.getPreferences(context, 'habits_preferences');
      const storedHabits = await prefs.get('habits', '[]');
      this.habits = JSON.parse(storedHabits as string);
    } catch (err: unknown) {
      console.error('Failed to load habits:', err);
    }
  }

  async saveHabits(): Promise<void> {
    try {
      const context = getContext(this) as common.UIAbilityContext;
      const prefs = await preferences.getPreferences(context, 'habits_preferences');
      await prefs.put('habits', JSON.stringify(this.habits));
      await prefs.flush();
    } catch (err: unknown) {
      console.error('Failed to save habits:', err);
    }
  }

  addHabit(): void {
    if (this.newHabit.trim()) {
      const newHabit: Habit = {
        id: Date.now(),
        name: this.newHabit,
        completed: false,
      };
      this.habits = [...this.habits, newHabit];
      this.newHabit = '';
      this.saveHabits();
    }
  }

  toggleHabit(habit: Habit): void {
    const updatedHabits = this.habits.map((h) => {
      if (h.id === habit.id) {
        return { id: h.id, name: h.name, completed: !h.completed };
      }
      return h;
    });
    this.habits = updatedHabits;
    this.saveHabits();
  }

  onRefresh(): void {
    this.refreshing = true;
    setTimeout(() => {
      this.loadHabits();
      this.refreshing = false;
    }, 1000);
  }

  build() {
    Column() {
      Row() {
        TextInput({ placeholder: 'Enter a new habit' })
          .onChange((value: string) => {
            this.newHabit = value;
          })
          .width('70%');

        Button('Add')
          .onClick(() => {
            this.addHabit();
          })
          .width('30%');
      }
      .padding(10);

      Refresh({ refreshing: this.refreshing, onRefresh: () => this.onRefresh() }) {
        List() {
          ForEach(this.habits, (habit: Habit) => {
            ListItem() {
              Column() {
                Text(habit.name)
                  .fontSize(16)
                  .margin({ top: 5 });

                Text(habit.completed ? 'Completed' : 'Not Completed')
                  .fontSize(16)
                  .margin({ top: 5 });

                Button(habit.completed ? 'Undo' : 'Done')
                  .onClick(() => {
                    this.toggleHabit(habit);
                  })
                  .margin({ top: 10 });
              }
              .padding(10);
            }
          });
        }
      }
    }
    .padding(20);
  }
}

import { Column, Row, Text, ForEach, Grid, GridItem } from '@ohos.arkui.advanced.UI';
import { FlexAlign, HorizontalAlign, FontWeight } from '@ohos.arkui.advanced.Common';

@Entry
@Component
struct CalendarComponent {
  @State selectedDate: Date = new Date();
  @State currentMonth: number = new Date().getMonth();
  @State currentYear: number = new Date().getFullYear();

  get daysInMonth(): number {
    return new Date(this.currentYear, this.currentMonth + 1, 0).getDate();
  }

  get firstDayOfMonth(): number {
    return new Date(this.currentYear, this.currentMonth, 1).getDay();
  }

  changeMonth(direction: number): void {
    this.currentMonth += direction;
    if (this.currentMonth < 0) {
      this.currentMonth = 11;
      this.currentYear--;
    } else if (this.currentMonth > 11) {
      this.currentMonth = 0;
      this.currentYear++;
    }
  }

  selectDate(day: number): void {
    this.selectedDate = new Date(this.currentYear, this.currentMonth, day);
  }

  build() {
    Column() {
      Row() {
        Text(`${this.currentYear} - ${this.currentMonth + 1}`)
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .margin({ right: 10 });

        Text('<')
          .fontSize(20)
          .onClick(() => this.changeMonth(-1));

        Text('>')
          .fontSize(20)
          .onClick(() => this.changeMonth(1));
      }
      .justifyContent(FlexAlign.SpaceBetween)
      .width('100%')
      .margin({ bottom: 10 });

      Row() {
        ForEach<string>(['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], (day: string) => {
          Text(day)
            .fontSize(16)
            .fontWeight(FontWeight.Bold)
            .width('14%')
            .textAlign(HorizontalAlign.Center);
        });
      }
      .width('100%')
      .margin({ bottom: 10 });

      Grid() {
        ForEach<number>(Array.from({ length: this.firstDayOfMonth }, (_, i: number) => i), (i: number) => {
          GridItem() {
            Text('')
              .width('100%')
              .height('100%');
          }
          .width('14%');
        });

        ForEach<number>(Array.from({ length: this.daysInMonth }, (_, i: number) => i + 1), (day: number) => {
          GridItem() {
            Text(day.toString())
              .fontSize(16)
              .fontWeight(this.selectedDate.getDate() === day && this.selectedDate.getMonth() === this.currentMonth && this.selectedDate.getFullYear() === this.currentYear ? FontWeight.Bold : FontWeight.Normal)
              .width('100%')
              .height('100%')
              .textAlign(HorizontalAlign.Center)
              .onClick(() => this.selectDate(day));
          }
          .width('14%');
        });
      }
      .columnsTemplate('1fr 1fr 1fr 1fr 1fr 1fr 1fr')
      .rowsGap(10)
      .columnsGap(10)
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

import promptAction from '@ohos.promptAction';

@Entry
@Component
struct ResponsiveUI {
  @State selectedDate: Date = new Date()
  @State chartData: number[] = [10, 20, 30, 40, 50]
  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D()

  updateChartData() {
    this.chartData = Array.from<number, number>({ length: 5 }, (_, i) => Math.floor(Math.random() * 100))
    promptAction.showToast({ message: 'Chart data updated!' })
  }

  build() {
    Column() {
      DatePicker({
        start: new Date('1970-01-01'),
        end: new Date('2100-12-31'),
        selected: this.selectedDate
      })
      .onDateChange((value: Date) => {
        this.selectedDate = value
        promptAction.showToast({ message: `Selected date: ${value.toLocaleDateString()}` })
      })
      .margin({ bottom: 20 })

      Canvas()
        .width('100%')
        .height(200)
        .margin({ bottom: 20 })
        .onReady(() => {
          const ctx = this.context
          ctx.beginPath()
          this.chartData.forEach((value, index) => {
            const x = index * (ctx.width / (this.chartData.length - 1))
            const y = ctx.height - (value / 100 * ctx.height)
            if (index === 0) {
              ctx.moveTo(x, y)
            } else {
              ctx.lineTo(x, y)
            }
          })
          ctx.stroke()
        })

      Button('Update Chart')
        .onClick(() => this.updateChartData())
        .width('50%')
        .margin({ bottom: 20 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

