@Entry
@Component
struct AlarmClockForm {
  @State hour: string = '';
  @State minute: string = '';
  @State errorMessage: string = '';
  @State showDialog: boolean = false;

  validateTime(): boolean {
    const hourNum = parseInt(this.hour);
    const minuteNum = parseInt(this.minute);

    if (isNaN(hourNum) || isNaN(minuteNum)) {
      this.errorMessage = 'Please enter valid numbers for time.';
      return false;
    }

    if (hourNum < 0 || hourNum > 23) {
      this.errorMessage = 'Hour must be between 0 and 23.';
      return false;
    }

    if (minuteNum < 0 || minuteNum > 59) {
      this.errorMessage = 'Minute must be between 0 and 59.';
      return false;
    }

    return true;
  }

  build() {
    Column() {
      Text('Set Alarm Time')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row() {
        Text('Hour:')
          .fontSize(16)
          .margin({ right: 10 });

        TextInput({ placeholder: 'HH' })
          .width(60)
          .height(40)
          .onChange((value: string) => {
            this.hour = value;
          });
      }
      .margin({ bottom: 20 });

      Row() {
        Text('Minute:')
          .fontSize(16)
          .margin({ right: 10 });

        TextInput({ placeholder: 'MM' })
          .width(60)
          .height(40)
          .onChange((value: string) => {
            this.minute = value;
          });
      }
      .margin({ bottom: 30 });

      Button('Set Alarm')
        .width('60%')
        .height(50)
        .fontSize(18)
