import { Column, Text, Button, Slider, Row, List, ListItem, PanGesture } from '@ohos.arkui.advanced';

interface Song {
  title: string;
  artist: string;
}

interface PanGestureEvent {
  offsetX: number;
  offsetY: number;
  type: number;
  timestamp: number;
}

@Entry
@Component
struct AudioPlayerCard {
  @State private currentSongIndex: number = 0;
  @State private isPlaying: boolean = false;
  @State private progress: number = 0;
  @State private cardBackgroundColor: string = '#FFFFFF';
  @State private textColor: string = '#000000';

  private songs: Array<Song> = [
    { title: 'Song 1', artist: 'Artist 1' },
    { title: 'Song 2', artist: 'Artist 2' },
    { title: 'Song 3', artist: 'Artist 3' }
  ];

  build() {
    Column() {
      Column() {
        Text(this.songs[this.currentSongIndex].title)
          .fontSize(24)
          .fontColor(this.textColor)
          .margin({ bottom: 10 });

        Text(this.songs[this.currentSongIndex].artist)
          .fontSize(18)
          .fontColor(this.textColor)
          .margin({ bottom: 20 });

        Slider({
          value: this.progress,
          min: 0,
          max: 100,
          step: 1
        })
          .width('80%')
          .onChange((value: number) => {
            this.progress = value;
          });

        Row({ space: 20 }) {
          Button('Previous')
            .onClick(() => {
              if (this.currentSongIndex > 0) {
                this.currentSongIndex--;
                this.progress = 0;
              }
            });

          Button(this.isPlaying ? 'Pause' : 'Play')
            .onClick(() => {
              this.isPlaying = !this.isPlaying;
              console.info(`Play/Pause button tapped: ${this.isPlaying ? 'Playing' : 'Paused'}`);
            });

          Button('Next')
            .onClick(() => {
              if (this.currentSongIndex < this.songs.length - 1) {
                this.currentSongIndex++;
                this.progress = 0;
              }
            });
        }
        .margin({ top: 20 });

        Row({ space: 10 }) {
          Button('Red')
            .backgroundColor('#FF0000')
            .onClick(() => {
              this.cardBackgroundColor = '#FF0000';
              this.textColor = '#FFFFFF';
            });

          Button('Blue')
            .backgroundColor('#0000FF')
            .onClick(() => {
              this.cardBackgroundColor = '#0000FF';
              this.textColor = '#FFFFFF';
            });

          Button('Green')
            .backgroundColor('#00FF00')
            .onClick(() => {
              this.cardBackgroundColor = '#00FF00';
              this.textColor = '#000000';
            });
        }
        .margin({ top: 20 });
      }
      .width(200)
      .height(200)
      .borderRadius(10)
      .backgroundColor(this.cardBackgroundColor)
      .padding(10)
      .gesture(
        PanGesture()
          .onActionUpdate((event: PanGestureEvent) => {
            if (event.offsetX > 50) {
              if (this.currentSongIndex < this.songs.length - 1) {
                this.currentSongIndex++;
                this.progress = 0;
              }
            } else if (event.offsetX < -50) {
              if (this.currentSongIndex > 0) {
                this.currentSongIndex--;
                this.progress = 0;
              }
            }
          })
      );

      List() {
        ForEach(this.songs, (song: Song, index: number) => {
          ListItem() {
            Column() {
              Text(song.title)
                .fontSize(18)
                .fontColor(this.textColor);

              Text(song.artist)
                .fontSize(14)
                .fontColor(this.textColor);
            }
            .width('100%')
            .padding(10)
            .onClick(() => {
              this.currentSongIndex = index;
              this.progress = 0;
            });
          }
          .backgroundColor(index === this.currentSongIndex ? '#DDDDDD' : 'transparent');
        });
      }
      .height(150)
      .width('100%')
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

