  question: string;
  answer: string;
}

@Entry
@Component
struct FlashcardApp {
  @State flashcards: Flashcard[] = [
    { question: "What is the capital of France?", answer: "Paris" },
    { question: "What is the largest planet in our solar system?", answer: "Jupiter" }
  ];
  @State currentIndex: number = 0;
  @State showAnswer: boolean = false;
  @State drawerOpen: boolean = false;

  flipCard() {
    this.showAnswer = !this.showAnswer;
  }

  nextCard() {
    this.currentIndex = (this.currentIndex + 1) % this.flashcards.length;
    this.showAnswer = false;
  }

  toggleDrawer() {
    this.drawerOpen = !this.drawerOpen;
  }

  build() {
    Column() {
      Row() {
        Button("Menu")
          .onClick(() => {
            this.toggleDrawer();
          })
          .id("menuButton")
          .accessibilityText("Toggle navigation drawer")
          .focusable(true);
      }
      .width('100%')
      .justifyContent(FlexAlign.Start)
      .padding(10);

      Divider();

      Column() {
        if (this.flashcards.length > 0) {
          Column() {
            Text(this.showAnswer ? this.flashcards[this.currentIndex].answer : this.flashcards[this.currentIndex].question)
              .fontSize(20)
              .fontWeight(FontWeight.Bold)
              .margin({ bottom: 10 })
              .id("flashcardText")
              .accessibilityText(this.showAnswer ? "Answer: " + this.flashcards[this.currentIndex].answer : "Question: " + this.flashcards[this.currentIndex].question)
              .focusable(true);

            Button(this.showAnswer ? "Next Card" : "Show Answer")
              .onClick(() => {
                this.flipCard();
              })
              .margin({ bottom: 20 })
              .id("flipButton")
              .accessibilityText(this.showAnswer ? "Next card" : "Show answer")
              .focusable(true);
          }
          .padding(20)
          .backgroundColor('#f0f0f0')
          .borderRadius(10);
        } else {
          Text("No flashcards added yet.")
            .fontSize(18)
            .id("emptyText")
            .accessibilityText("No flashcards added yet")
            .focusable(true);
        }
      }
      .width('100%')
      .height('100%')
      .justifyContent(FlexAlign.Center);

      SideBarContainer(SideBarContainerType.Embed) {
        Column() {
          Text("Flashcard Sets")
            .fontSize(18)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 10 });

          ForEach(this.flashcards, (flashcard: Flashcard, index: number) => {
            Button(flashcard.question)
              .onClick(() => {
                this.currentIndex = index;
                this.showAnswer = false;
                this.drawerOpen = false;
              })
              .margin({ bottom: 5 })
              .id("setButton_" + index)
              .accessibilityText("Flashcard set: " + flashcard.question)
              .focusable(true);
          });
        }
        .padding(20);
      }
      .showSideBar(this.drawerOpen)
      .sideBarWidth('60%')
    }
    .width('100%')
    .height('100%');
  }
}

@Entry
@Component
struct RecipePhotoEditor {
  @State private currentStep: number = 0;
  private totalSteps: number = 3;
  private recipeSteps: string[] = ["Step 1: Prepare Ingredients", "Step 2: Cook the Dish", "Step 3: Garnish and Serve"];
  @State private isCaching: boolean = false;

  @Builder
  StepContent(step: number) {
    Column() {
      Text(this.recipeSteps[step])
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Image($r('sys.media.ohos_app_icon'))
        .width(200)
        .height(200)
        .margin({ bottom: 20 });

      if (this.isCaching) {
        Text("Caching...")
          .fontSize(18)
          .fontColor(Color.Gray);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }

  build() {
    Column() {
      this.StepContent(this.currentStep);

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentStep > 0) {
              this.currentStep--;
            }
          })
          .margin({ right: 20 })
          .enabled(this.currentStep > 0);

        Button('Next')
          .onClick(() => {
            if (this.currentStep < this.totalSteps - 1) {
              this.currentStep++;
              this.isCaching = true;
              setTimeout(() => {
                this.isCaching = false;
              }, 1000);
            }
          })
          .enabled(this.currentStep < this.totalSteps - 1);
      }
      .margin({ top: 50 });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
