import { Column, Text, Button, TextInput, Radio, RadioGroup, InputType, FlexAlign } from '@ohos.arkui.component';

@Entry
@Component
struct CurrencyConverter {
  @State fromCurrency: string = 'USD';
  @State toCurrency: string = 'EUR';
  @State amount: string = '';
  @State result: string = '';
  @State error: string = '';

  private exchangeRates: Map<string, number> = new Map([
    ['USD', 1.0],
    ['EUR', 0.85],
    ['GBP', 0.72],
    ['JPY', 110.0]
  ]);

  private convertCurrency(): void {
    if (!this.amount) {
      this.error = 'Please enter an amount';
      this.result = '';
      return;
    }

    const numericAmount = parseFloat(this.amount);
    if (isNaN(numericAmount)) {
      this.error = 'Invalid amount';
      this.result = '';
      return;
    }

    const fromRate = this.exchangeRates.get(this.fromCurrency) || 1.0;
    const toRate = this.exchangeRates.get(this.toCurrency) || 1.0;
    const convertedAmount = (numericAmount * (toRate / fromRate)).toFixed(2);
    this.result = `${convertedAmount} ${this.toCurrency}`;
    this.error = '';
  }

  build() {
    Column() {
      Text('Currency Converter')
        .fontSize(24)
        .margin(10);

      TextInput({ placeholder: 'Enter amount', text: this.amount })
        .type(InputType.Number)
        .onChange((value: string) => {
          this.amount = value;
        })
        .margin(10)
        .accessibilityDescription('Enter the amount to convert');

      Text('From:')
        .fontSize(18)
        .margin(10);

      RadioGroup({ groupName: 'fromCurrency' }) {
        Radio({ value: 'USD' }).accessibilityDescription('From USD')
        Radio({ value: 'EUR' }).accessibilityDescription('From EUR')
        Radio({ value: 'GBP' }).accessibilityDescription('From GBP')
        Radio({ value: 'JPY' }).accessibilityDescription('From JPY')
      }
      .onChange((value: string) => {
        this.fromCurrency = value;
      })
      .margin(10)
      .accessibilityDescription('Select the currency to convert from');

      Text('To:')
        .fontSize(18)
        .margin(10);

      RadioGroup({ groupName: 'toCurrency' }) {
        Radio({ value: 'USD' }).accessibilityDescription('To USD')
        Radio({ value: 'EUR' }).accessibilityDescription('To EUR')
        Radio({ value: 'GBP' }).accessibilityDescription('To GBP')
        Radio({ value: 'JPY' }).accessibilityDescription('To JPY')
      }
      .onChange((value: string) => {
        this.toCurrency = value;
      })
      .margin(10)
      .accessibilityDescription('Select the currency to convert to');

      Button('Convert')
        .onClick(() => {
          this.convertCurrency();
        })
        .margin(10)
        .accessibilityDescription('Convert the amount');

      if (this.error) {
        Text(this.error)
          .fontSize(16)
          .fontColor(0xFFFF0000)
          .margin(10);
      }

      if (this.result) {
        Text(this.result)
          .fontSize(20)
          .fontColor(0xFF000000)
          .margin(10);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }
}

