interface ConversionResult {
  amount: number;
  fromCurrency: string;
  toCurrency: string;
  convertedAmount: number;
  timestamp: number;
}

@Entry
@Component
struct CurrencyConverterApp {
  private exchangeRates: Record<string, number> = {
    USD: 1,
    EUR: 0.85,
    GBP: 0.75,
    JPY: 110
  };

  private currencies: string[] = ['USD', 'EUR', 'GBP', 'JPY'];

  @State amount: string = '';
  @State fromCurrency: string = 'USD';
  @State toCurrency: string = 'EUR';
  @State conversionResults: ConversionResult[] = [];
  @State chartData: number[] = [];
  @State canvasCtx: CanvasRenderingContext2D | null = null;

  private prefs: preferences.Preferences | null = null;

  async aboutToAppear(): Promise<void> {
    this.prefs = await preferences.getPreferences(getContext(this));
    this.loadHistory();
  }

  private async loadHistory(): Promise<void> {
    if (!this.prefs) return;
    try {
      const value: string = await this.prefs.get('history', '');
      if (value) {
        this.conversionResults = JSON.parse(value) as ConversionResult[];
        this.updateChartData();
      }
    } catch (err: Error) {
      console.error('Failed to load history:', err);
    }
  }

  private async saveHistory(): Promise<void> {
    if (this.prefs) {
      await this.prefs.put('history', JSON.stringify(this.conversionResults));
      await this.prefs.flush();
    }
  }

  private updateChartData(): void {
    this.chartData = this.conversionResults.map(result => result.convertedAmount);
  }

  private convertCurrency(): void {
    if (!this.amount || isNaN(Number(this.amount))) {
      return;
    }

    const amount = Number(this.amount);
    const fromRate = this.exchangeRates[this.fromCurrency];
    const toRate = this.exchangeRates[this.toCurrency];
    const convertedAmount = (amount / fromRate) * toRate;

    const result: ConversionResult = {
      amount,
      fromCurrency: this.fromCurrency,
      toCurrency: this.toCurrency,
      convertedAmount,
      timestamp: Date.now()
    };

    this.conversionResults = [result, ...this.conversionResults];
    this.updateChartData();
    this.saveHistory();
  }

  private drawChart(): void {
    if (!this.canvasCtx) return;
    const canvas = this.canvasCtx;
    const width = 300;
    const height = 200;
    const maxValue = Math.max(...this.chartData, 1);
    const barWidth = width / this.chartData.length;

    canvas.clearRect(0, 0, width, height);
    canvas.fillStyle = '#007AFF';

    this.chartData.forEach((value, index) => {
      const barHeight = (value / maxValue) * height;
      canvas.fillRect(index * barWidth, height - barHeight, barWidth - 2, barHeight);
    });
  }

  build() {
    Column() {
      Text('Currency Converter')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Row() {
        TextInput({ placeholder: 'Amount' })
          .width('40%')
          .onChange((value: string) => {
            this.amount = value;
          });

        Picker({ selected: this.fromCurrency })
          .width('25%')
          .onChange((value: string) => {
            this.fromCurrency = value;
          })
          .onAppear(() => {
            ForEach(this.currencies, (currency: string) => {
              Text(currency)
            })
          });

        Picker({ selected: this.toCurrency })
          .width('25%')
          .onChange((value: string) => {
            this.toCurrency = value;
          })
          .onAppear(() => {
            ForEach(this.currencies, (currency: string) => {
              Text(currency)
            })
          });
      }
      .margin({ bottom: 20 });

      Button('Convert')
        .onClick(() => {
          this.convertCurrency();
        })
        .margin({ bottom: 20 });

      Canvas(this.canvasCtx)
        .width(300)
        .height(200)
        .onReady(() => {
          this.canvasC

