import { TextInput, Picker, Column, Row, Text, Button } from '@ohos.arkui.advanced';
import { FlexAlign, FontWeight, InputType } from '@ohos.arkui.common';
import { gesture } from '@ohos.multimodalinput.gesture';
import { GestureType } from '@ohos.multimodalinput.gesture';

interface CurrencyRate {
  EUR: number;
  GBP: number;
  USD: number;
}

interface ConversionRates {
  USD: CurrencyRate;
  EUR: CurrencyRate;
  GBP: CurrencyRate;
}

@Entry
@Component
struct CurrencyConverter {
  @State amount: string = '';
  @State fromCurrency: string = 'USD';
  @State toCurrency: string = 'EUR';
  @State convertedAmount: number = 0;
  @State showHelp: boolean = false;
  @State gesture: gesture.Gesture = new gesture.Gesture(gesture.GestureType.LONG_PRESS);

  private currencyItems: string[] = ['USD', 'EUR', 'GBP'];
  private conversionRates: ConversionRates = {
    USD: { EUR: 0.85, GBP: 0.75, USD: 1 },
    EUR: { USD: 1.18, GBP: 0.88, EUR: 1 },
    GBP: { USD: 1.33, EUR: 1.14, GBP: 1 }
  };

  aboutToAppear() {
    this.gesture.onAction(() => {
      this.showHelp = true;
    });
  }

  build() {
    Column() {
      Text('Currency Converter')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      TextInput({ placeholder: 'Enter amount', text: this.amount })
        .type(InputType.Number)
        .onChange((value: string) => {
          if (/^\d*\.?\d*$/.test(value)) {
            this.amount = value;
            this.convertCurrency();
          }
        })
        .width('80%')
        .margin({ bottom: 20 });

      Row() {
        Picker({ items: this.currencyItems, selected: this.fromCurrency })
          .onChange((value: string) => {
            this.fromCurrency = value;
            this.convertCurrency();
          })
          .width('40%')
          .margin({ right: 10 });

        Picker({ items: this.currencyItems, selected: this.toCurrency })
          .onChange((value: string) => {
            this.toCurrency = value;
            this.convertCurrency();
          })
          .width('40%');
      }
      .margin({ bottom: 20 });

      Text(`Converted Amount: ${this.convertedAmount.toFixed(2)} ${this.toCurrency}`)
        .fontSize(18)
        .margin({ bottom: 20 });

      Column()
        .gesture(this.gesture);

      if (this.showHelp) {
        Column() {
          Text('Conversion Rates:')
            .fontSize(16)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 10 });

          Text('USD -> EUR: 0.85')
            .margin({ bottom: 5 });
          Text('USD -> GBP: 0.75')
            .margin({ bottom: 5 });
          Text('EUR -> USD: 1.18')
            .margin({ bottom: 5 });
          Text('EUR -> GBP: 0.88')
            .margin({ bottom: 5 });
          Text('GBP -> USD: 1.33')
            .margin({ bottom: 5 });
          Text('GBP -> EUR: 1.14')
            .margin({ bottom: 5 });

          Button('Close')
            .onClick(() => {
              this.showHelp = false;
            })
            .width('50%')
            .margin({ top: 10 });
        }
        .padding(20)
        .backgroundColor('#f0f0f0')
        .borderRadius(10)
        .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center);
  }

  private convertCurrency() {
    const amount = parseFloat(this.amount);
    if (isNaN(amount)) {
      this.convertedAmount = 0;
      return;
    }

    const fromRate: CurrencyRate = this.conversionRates[this.fromCurrency];
    const rate: number = fromRate[this.toCurrency];
    this.convertedAmount = amount * rate;
  }
}

import { TimePicker, Image } from '@ohos.arkui.component';
import { animateTo, Easing } from '@ohos.arkui.animation';
