interface WaterIntakeRecord {
  date: string;
  amount: number;
}

@Entry
@Component
struct WaterIntakeTracker {
  @State waterIntake: number = 0;
  @State dailyGoal: number = 2000;
  @State progress: number = 0;
  @State history: Array<WaterIntakeRecord> = [];
  @State selectedPeriod: string = 'Today';

  updateProgress() {
    this.progress = (this.waterIntake / this.dailyGoal) * 100;
  }

  logWaterIntake(amount: number) {
    this.waterIntake += amount;
    this.history.push({ date: new Date().toLocaleDateString(), amount: amount } as WaterIntakeRecord);
    this.updateProgress();
  }

  filterHistoryByPeriod(period: string) {
    this.selectedPeriod = period;
  }

  build() {
    Column() {
      Text('Daily Water Intake Tracker')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin(20);

      Text(`Goal: ${this.dailyGoal} ml`)
        .fontSize(18)
        .margin(10);

      Text(`Consumed: ${this.waterIntake} ml`)
        .fontSize(18)
        .margin(10);

      Stack() {
        Circle()
          .width(200)
          .height(200)
          .stroke('#E0E0E0')
          .strokeWidth(15)
          .fill('transparent');

        Circle()
          .width(200)
          .height(200)
          .stroke('#4CAF50')
          .strokeWidth(15)
          .fill('transparent')
          .strokeDashArray([Math.PI * 200, Math.PI * 200])
          .strokeDashOffset(Math.PI * 200 * (1 - this.progress / 100))
          .rotate({ x: 0, y: 0, z: 1, angle: -90 });

        Text(`${Math.round(this.progress)}%`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold);
      }
      .width(200)
      .height(200)
      .margin({ top: 50 });

      Row() {
        Button('250 ml')
          .onClick(() => this.logWaterIntake(250))
          .width(100)
          .height(50)
          .margin(10);

        Button('500 ml')
          .onClick(() => this.logWaterIntake(500))
          .width(100)
          .height(50)
          .margin(10);
      }
      .margin({ top: 40 });

      Button('Reset')
        .onClick(() => {
          this.waterIntake = 0;
          this.updateProgress();
        })
        .width(200)
        .height(50)
        .margin({ top: 20 });

      Text('History')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 30, bottom: 10 });

      Row() {
        Button('Today')
          .onClick(() => this.filterHistoryByPeriod('Today'))
          .width(100)
          .height(40)
          .margin(5);

        Button('Week')
          .onClick(() => this.filterHistoryByPeriod('Week'))
          .width(100)
          .height(40)
          .margin(5);

        Button('Month')
          .onClick(() => this.filterHistoryByPeriod('Month'))
          .width(100)
          .height(40)
          .margin(5);
      }
      .margin({ bottom: 20 });

      Column() {
        ForEach(this.history, (item: WaterIntakeRecord) => {
          Row() {
            Text(item.date)
              .fontSize(16)
              .margin(5);

            Text(`${item.amount} ml`)
              .fontSize(16)
              .margin(5);
          }
          .width('100%')
          .justifyContent(FlexAlign.SpaceBetween)
          .margin({ bottom: 10 });
        });
      }
      .width('100%')
      .margin({ bottom: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }
}

