import { TimePicker, List, Button, Column, Text, Row, ListItem } from '@ohos.arkui.advancedUI';
import { animateTo, Curve } from '@ohos.arkui.animation';

interface TimeChangeValue {
  hour: number;
  minute: number;
  second: number;
}

interface MessageItem {
  id: string;
  content: string;
}

@Entry
@Component
struct TimePickerApp {
  @State selectedTime: Date = new Date();
  @State messages: MessageItem[] = [];

  addMessage() {
    const timeStr = this.selectedTime.toLocaleTimeString();
    this.messages = [...this.messages, {
      id: Date.now().toString(),
      content: `Message at ${timeStr}`
    }];
  }

  clearMessages() {
    this.messages = [];
  }

  handleTimeChange(value: TimeChangeValue) {
    animateTo({
      duration: 500,
      curve: Curve.EaseInOut
    }, () => {
      this.selectedTime = new Date(
        this.selectedTime.getFullYear(),
        this.selectedTime.getMonth(),
        this.selectedTime.getDate(),
        value.hour,
        value.minute,
        value.second
      );
    });
  }

  build() {
    Column() {
      TimePicker({ selected: this.selectedTime })
        .onChange((value: TimeChangeValue) => {
          this.handleTimeChange(value);
        })
        .width('80%')
        .margin({ bottom: 20 });

      List({ space: 10 }) {
        ForEach(this.messages, (message: MessageItem) => {
          ListItem() {
            Text(message.content)
              .fontSize(16)
              .fontColor('#333')
              .padding(10)
              .backgroundColor('#F0F0F0')
              .borderRadius(8);
          }
        }, (message: MessageItem) => message.id);
      }
      .height('40%')
      .width('100%')
      .margin({ bottom: 20 });

      Row({ space: 20 }) {
        Button('Add Message')
          .onClick(() => {
            this.addMessage();
          })
          .width('40%');

        Button('Clear Messages')
          .onClick(() => {
            this.clearMessages();
          })
          .width('40%');
      }
      .width('100%')
      .justifyContent(FlexAlign.Center);
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

interface PanEvent {
  offsetX: number;
}

@Entry
@Component
struct EnhancedPromptApp {
  @State userInput: string = '';
  @State selectedOption: string = 'Option 1';
  @State swipeMessage: string = 'Swipe Here';

  handleTextChange(value: string) {
    this.userInput = value;
  }

  handleButtonClick() {
    console.log('Button clicked!');
  }

  handleOptionChange(index: number, value: string) {
    this.selectedOption = value;
  }

  handleSwipe(event: PanEvent) {
    if (event.offsetX > 50) {
      this.swipeMessage = 'Swiped Right';
    } else if (event.offsetX < -50) {
      this.swipeMessage = 'Swiped Left';
    }
  }

  build() {
    Column() {
      TextInput({ placeholder: 'Enter text here' })
        .width('80%')
        .height(40)
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.handleTextChange(value);
        });

      Button('Click Me')
        .width('80%')
        .height(40)
        .margin({ bottom: 20 })
        .onClick(() => {
          this.handleButtonClick();
        });

      Select([
        { value: 'Option 1' },
        { value: 'Option 2' },
        { value: 'Option 3' },
      ])
        .width('80%')
        .margin({ bottom: 20 })
        .onSelect((index: number, value: string) => {
          this.handleOptionChange(index, value);
        });

      Text(this.swipeMessage)
        .fontSize(20)
        .margin({ bottom: 20 });

      Row()
        .width(200)
        .height(100)
        .backgroundColor('#f0f0f0')
        .gesture(
          PanGesture({ direction: PanDirection.Horizontal })
            .onActionUpdate((event: PanEvent) => {
              this.handleSwipe(event);
            })
            .onActionEnd(() => {
              this.swipeMessage = 'Swipe Here';
            })
        )
        .margin({ bottom: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

import { Button, Column, Text, Image, Row } from '@ohos.arkui.advanced';
import { CustomDialogController, CustomDialog } from '@ohos.arkui.advanced';
import { HorizontalAlign, FlexAlign } from '@ohos.arkui.advanced';
import { Gesture } from '@ohos.multimodalinput.gesture';

@Entry
@Component
struct MainPage {
  @State scaleValue: number = 1.0;
  @State lastScale: number = 1.0;
  dialogController?: CustomDialogController;

  aboutToAppear() {
    this.dialogController = new CustomDialogController({
      builder: CustomDialogExample({
        message: 'Do you want to proceed?',
        confirmLabel: 'OK',
        cancelLabel: 'Cancel',
        confirmAction: () => {},
        cancelAction: () => {},
        controller: this.dialogController
      }),
      autoCancel: true
    });
  }

  build() {
    Column() {
      Button('Show Alert Dialog')
        .width('80%')
        .height(50)
        .margin(20)
        .onClick(() => {
          this.dialogController?.open();
        });

      Image($r('app.media.icon'))
        .width('100%')
        .height('60%')
        .gesture(
          Gesture.Pinch()
            .onActionStart(() => {
              this.lastScale = this.scaleValue;
            })
            .onActionUpdate((event: Gesture.PinchGesture) => {
              let newScale = this.lastScale * event.scale;
              this.scaleValue = Math.max(0.5, Math.min(newScale, 3.0));
            })
            .onActionEnd(() => {
              this.lastScale = this.scaleValue;
            })
        )
        .scale({ x: this.scaleValue, y: this.scaleValue });
    }
    .width('100%')
    .height('100%')
    .alignItems(HorizontalAlign.Center);
  }
}

@CustomDialog
