  message: string = '';
  confirmLabel: string = 'OK';
  cancelLabel: string = 'Cancel';
  confirmAction: () => void = () => {};
  cancelAction: () => void = () => {};

  build() {
    Column() {
      Text(this.message)
        .fontSize(18)
        .margin(10);

      Row() {
