      .margin(10);
    }
    .padding(20);
  }
}

@Entry
@Component
struct TaskManagementApp {
  @State tasks: Array<string> = ['Task 1', 'Task 2', 'Task 3'];
  @State newTask: string = '';
  @State isPlaying: boolean = false;

  private playAudioSimulation() {
    this.isPlaying = !this.isPlaying;
    console.log(`Audio simulation ${this.isPlaying ? 'started' : 'stopped'}`);
  }

  private addTask() {
    if (this.newTask.trim()) {
      this.tasks.push(this.newTask);
      this.newTask = '';
