  private removeTask(index: number) {
    this.tasks.splice(index, 1);
  }

  build() {
    Column({ space: 10 }) {
      Text('Project Task Manager')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

