import promptAction from '@ohos.promptAction';

@Entry
@Component
struct SwipeRatingComponent {
  @State private rating: number = 0;
  @State private maxRating: number = 5;

  private handleSwipe(event: GestureEvent) {
    if (event.offsetX > 50) {
      this.rating = Math.min(this.rating + 1, this.maxRating);
      promptAction.showToast({
        message: 'Rating: ' + this.rating,
        duration: 1000
      });
    } else if (event.offsetX < -50) {
      this.rating = Math.max(this.rating - 1, 0);
      promptAction.showToast({
        message: 'Rating: ' + this.rating,
        duration: 1000
      });
    }
  }

  build() {
    Column() {
      Text('Swipe left/right to rate')
        .fontSize(20)
        .margin({ bottom: 20 });

      Progress({
        value: this.rating,
        total: this.maxRating,
        style: ProgressStyle.Linear
      })
        .width('80%')
        .height(20)
        .margin({ bottom: 20 });

      Column()
        .width('100%')
        .height(100)
        .backgroundColor('#f0f0f0')
        .gesture(
          PanGesture()
            .onActionUpdate((event: GestureEvent) => {
              this.handleSwipe(event);
            })
        );
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center);
  }
}

@Entry
@Component
struct AlarmClockApp {
  @State currentTime: string = this.getFormattedTime()
  @State alarmTime: string = ""
  private timerId: number = -1

  aboutToAppear() {
    this.timerId = setInterval(() => {
      this.currentTime = this.getFormattedTime()
    }, 1000)
  }

  aboutToDisappear() {
    if (this.timerId !== -1) {
      clearInterval(this.timerId)
    }
  }

  getFormattedTime(): string {
    const now = new Date()
    const hours = String(now.getHours()).padStart(2, '0')
    const minutes = String(now.getMinutes()).padStart(2, '0')
    const seconds = String(now.getSeconds()).padStart(2, '0')
    return `${hours}:${minutes}:${seconds}`
  }

  setAlarm() {
    if (this.alarmTime === this.currentTime) {
      console.log("Alarm triggered!")
    }
  }

  build() {
    Column({ space: 20 }) {
      Text("Current Time: " + this.currentTime)
        .fontSize(30)
        .margin({ top: 20 })

      TextInput({ placeholder: "Enter alarm time (HH:MM:SS)" })
        .width(200)
        .height(40)
        .onChange((value: string) => {
          this.alarmTime = value
        })

      Button("Set Alarm")
        .width(150)
        .height(40)
        .onClick(() => {
          this.setAlarm()
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

interface ChartData {
  values: number[]
  labels: string[]
}

@Entry
@Component
struct DataVisualizationApp {
  @State dataReady: boolean = false
  @State isLoading: boolean = false

  private chartData: ChartData = {
    values: [],
    labels: []
  }

  aboutToAppear(): void {
    this.generateChartData()
  }

  generateChartData(): void {
    this.isLoading = true
    setTimeout(() => {
      this.chartData = {
        values: Array.from<number, number>({length: 20}, () => Math.random() * 500),
        labels: Array.from<string, string>({length: 20}, (_: number, i: number) => "Label " + (i + 1).toString())
      }
      this.dataReady = true
      this.isLoading = false
    }, 1000)
  }

