            .height('100%')
            .backgroundColor(Color.White)
            .borderRadius(12)
        } else {
          LoadingProgress()
            .color(Color.Blue)
            .width(30)
            .height(30)
        }
      }
      .height('50%')
      .width('100%')
      .padding(10)

      Column() {
        Grid() {
          ForEach(Array.from({length: 6}), (item: undefined, index: number) => {
            GridItem() {
              Text("Item " + (index + 1))
