            .borderRadius(12)
            .padding(10)
          })
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsGap(10)
        .columnsGap(10)
        .height('100%')
        .width('100%')
      }
      .height('50%')
      .width('100%')
