import { State } from '@ohos.arkui.component';

@Entry
@Component
struct HabitTracker {
  @State selectedHabit: string = '';
  @State selectedFrequency: string = 'Daily';
  @State canvasColor: string = '#4CAF50';
  @State paymentTriggered: boolean = false;

  private habits: string[] = ['Exercise', 'Read', 'Meditate', 'Hydrate'];
  private frequencies: string[] = ['Daily', 'Weekly', 'Monthly'];

  build() {
    Column({ space: 20 }) {
      Text('Select a Habit')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      Row({ space: 10 }) {
        ForEach(this.habits, (habit: string) => {
          Button(habit)
            .borderRadius(20)
            .padding({ left: 20, right: 20, top: 10, bottom: 10 })
            .backgroundColor(this.selectedHabit === habit ? '#007AFF' : '#E0E0E0')
            .onClick(() => {
              this.selectedHabit = habit;
              this.canvasColor = this.getRandomColor();
            });
        });
      }
      .justifyContent(FlexAlign.Center)
      .margin({ bottom: 20 });

      Text('Select Frequency')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      Row({ space: 10 }) {
        ForEach(this.frequencies, (frequency: string) => {
          Button(frequency)
            .borderRadius(20)
            .padding({ left: 20, right: 20, top: 10, bottom: 10 })
            .backgroundColor(this.selectedFrequency === frequency ? '#007AFF' : '#E0E0E0')
            .onClick(() => {
              this.selectedFrequency = frequency;
            });
        });
      }
      .justifyContent(FlexAlign.Center)
      .margin({ bottom: 20 });

      Text('Selected Habit: ' + (this.selectedHabit || 'None'))
        .fontSize(20)
        .fontWeight(FontWeight.Medium)
        .margin({ bottom: 10 });

      Canvas()
        .width(200)
        .height(200)
        .backgroundColor(this.canvasColor)
        .borderRadius(10)
        .margin({ bottom: 20 });

      Button('Mock Payment')
        .width(200)
        .height(50)
        .backgroundColor(this.paymentTriggered ? '#FF9800' : '#007AFF')
        .borderRadius(25)
        .onClick(() => {
          this.paymentTriggered = !this.paymentTriggered;
          this.canvasColor = this.getRandomColor();
        });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }

  private getRandomColor(): string {
    const colors = ['#4CAF50', '#2196F3', '#FF9800', '#9C27B0'];
    return colors[Math.floor(Math.random() * colors.length)];
  }
}

import { CustomDialogController, Curve, TransitionEffect } from '@ohos.arkui.advanced';

struct CustomDialogExample {
  controller: CustomDialogController = new CustomDialogController();
  cancel: () => void = () => {};
  confirm: () => void = () => {};

  build(): void {
    Column() {
      Text('Custom Dialog')
        .fontSize(20)
        .margin(10)
        .fontColor('#000000')

      Flex({ justifyContent: FlexAlign.SpaceAround }) {
        Button('Cancel')
          .onClick(() => {
            this.controller.close();
            this.cancel();
          })
          .backgroundColor('#E0E0E0')
          .fontColor('#000000')
          .borderRadius(5)
          .padding(10)

        Button('Confirm')
          .onClick(() => {
            this.controller.close();
            this.confirm();
          })
          .backgroundColor('#4CAF50')
          .fontColor('#FFFFFF')
          .borderRadius(5)
          .padding(10)
      }
      .margin({ bottom: 10 })
    }
    .width('80%')
    .height('30%')
    .backgroundColor('#FFFFFF')
    .borderRadius(10)
    .padding(20)
    .scale({ x: 0.5, y: 0.5 })
    .opacity(0)
    .transition(TransitionEffect.OPACITY
      .animation({ duration: 300, curve: Curve.EaseInOut }))
    .transition(TransitionEffect.SCALE
      .animation({ duration: 300, curve: Curve.EaseInOut }))
  }
}

