        .fontColor('#FFFFFF')
        .borderRadius(5)
    }
  }
}

import { Column, Row, Text, Button, Image, Swiper, SwiperController, State, FlexAlign, ImageFit, Gesture } from '@ohos.arkui.component';

interface SwipeEvent {
  offsetX: number;
}

@Entry
@Component
struct PDFViewerApp {
  @State currentPage: number = 1;
  @State totalPages: number = 10;
  @State rating: number = 3;
  swiperController: SwiperController = new SwiperController();

  build() {
    Column() {
      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentPage > 1) {
              this.currentPage--;
              this.swiperController.showPrevious();
            }
          })
          .disabled(this.currentPage === 1);

        Text(`Page ${this.currentPage} of ${this.totalPages}`)
          .margin({ left: 16, right: 16 });

        Button('Next')
          .onClick(() => {
            if (this.currentPage < this.totalPages) {
              this.currentPage++;
              this.swiperController.showNext();
            }
          })
          .disabled(this.currentPage === this.totalPages);
      }
      .justifyContent(FlexAlign.Center)
      .margin({ top: 16, bottom: 16 });

      Swiper(this.swiperController) {
        ForEach(Array.from<number, number>({ length: this.totalPages }, (_, i) => i + 1), (page: number) => {
          Image($r('app.media.pdf_placeholder'))
            .width('100%')
            .height(400)
            .objectFit(ImageFit.Contain)
            .gesture(
              Gesture()
                .onSwipe((event: SwipeEvent) => {
                  if (event.offsetX > 50 && this.currentPage > 1) {
                    this.currentPage--;
                    this.swiperController.showPrevious();
                  } else if (event.offsetX < -50 && this.currentPage < this.totalPages) {
                    this.currentPage++;
                    this.swiperController.showNext();
                  }
                })
            );
        });
      }
      .indicator(false)
      .autoPlay(false)
      .margin({ bottom: 16 });

      Row() {
        ForEach(Array.from<number, number>({ length: 5 }, (_, i) => i + 1), (star: number) => {
          Image(star <= this.rating ? $r('app.media.star_filled') : $r('app.media.star_outline'))
            .width(32)
            .height(32)
            .margin(4)
            .onClick(() => {
              this.rating = star;
            });
        });
      }
      .justifyContent(FlexAlign.Center)
      .margin({ top: 16, bottom: 16 });
    }
    .width('100%')
    .height('100%')
    .padding(16);
  }
}

