import { Accordion, AccordionItem, Tabs, TabContent, Progress, PanGesture, ProgressType, GestureEvent } from '@ohos.arkui.component';

@Entry
@Component
struct PullToRefreshApp {
  @State refreshing: boolean = false;
  @State activeTab: number = 0;
  @State accordionExpanded: boolean[] = [false, false, false];
  @State tabData: TabData[] = [
    { id: 0, title: 'Tab 1', content: ['Content 1.1', 'Content 1.2'] },
    { id: 1, title: 'Tab 2', content: ['Content 2.1', 'Content 2.2'] },
    { id: 2, title: 'Tab 3', content: ['Content 3.1', 'Content 3.2'] }
  ];

  build() {
    Column() {
      Image($r('app.media.ic_public_refresh'))
        .width(50)
        .height(50)
        .margin({ top: 20 })
        .gesture(
          PanGesture()
            .onActionUpdate((event: GestureEvent) => {
              if (event.offsetY > 50 && !this.refreshing) {
                this.refreshing = true;
                setTimeout(() => {
                  this.refreshing = false;
                  promptAction.showToast({ message: 'Refresh completed' });
                }, 2000);
              }
            })
        )

      Button('Refresh')
        .onClick(() => {
          if (!this.refreshing) {
            this.refreshing = true;
            setTimeout(() => {
              this.refreshing = false;
              promptAction.showToast({ message: 'Refresh completed' });
            }, 2000);
          }
        })

      Tabs({ barPosition: 'Start' }) {
        ForEach(this.tabData, (tab: TabData) => {
          TabContent() {
            Column() {
              Accordion() {
                ForEach(tab.content, (content: string, index: number) => {
                  AccordionItem({
                    expanded: this.accordionExpanded[index],
                    onChange: (expanded: boolean) => {
                      this.accordionExpanded[index] = expanded;
                    }
                  }) {
                    Text(content)
                      .fontSize(16)
                      .padding(16)
                      .backgroundColor('#f0f0f0')
                      .width('100%')
                  }
                })
              }
            }
          }
        })
      }

      if (this.refreshing) {
        Progress({ type: ProgressType.Ring })
          .width(50)
          .height(50)
      }
    }
    .width('100%')
    .height('100%')
  }
}

interface TabData {
  id: number;
  title: string;
  content: string[];
}

