    { driverName: 'Bob Johnson', distance: '3.2 km', eta: '7 mins' }
  ];
  @State refreshing: boolean = false;

  private refreshRides() {
    this.refreshing = true;
    setTimeout(() => {
      this.rides = [
        { driverName: 'John Doe', distance: '2.1 km', eta: '4 mins' },
        { driverName: 'Jane Smith', distance: '1.5 km', eta: '2 mins' },
        { driverName: 'Bob Johnson', distance: '3.0 km', eta: '6 mins' },
        { driverName: 'Alice Brown', distance: '4.0 km', eta: '8 mins' }
      ];
      this.refreshing = false;
    }, 1500);
  }

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.rides, (ride: Ride) => {
          ListItem() {
            Column() {
              Text(`Driver: ${ride.driverName}`)
                .fontSize(18)
                .fontWeight(FontWeight.Bold)
                .margin({ bottom: 5 });
              Row() {
                Text(`Distance: ${ride.distance}`)
                  .fontSize(14);
                Text(` | `)
                  .fontSize(14);
                Text(`ETA: ${ride.eta}`)
                  .fontSize(14);
              }
            }
            .padding(15)
            .width('100%')
            .borderRadius(8)
            .backgroundColor('#f5f5f5')
          }
        })
      }
      .width('100%')
      .layoutWeight(1)
      .onScrollIndex((index: number) => {
        if (index === 0 && !this.refreshing) {
          this.refreshRides();
        }
      })
