interface Sensor {
  id: number
  name: string
  value: number
}

@Entry
@Component
struct SensorApp {
  @State searchText: string = ''
  @State sensorData: Array<Sensor> = [
    { id: 1, name: 'Temperature', value: 25 } as Sensor,
    { id: 2, name: 'Humidity', value: 60 } as Sensor,
    { id: 3, name: 'Pressure', value: 1013 } as Sensor,
    { id: 4, name: 'Light', value: 300 } as Sensor,
    { id: 5, name: 'Motion', value: 0 } as Sensor
  ]
  @State filteredData: Array<Sensor> = []
  @State showActionSheet: boolean = false

  aboutToAppear(): void {
    this.filteredData = this.sensorData
  }

  build() {
    Column() {
      Search({ placeholder: 'Search sensors' })
        .onChange((value: string) => {
          this.searchText = value
          this.filterSensorData()
        })

      List() {
        ForEach(this.filteredData, (item: Sensor) => {
          ListItem() {
            Column() {
              Text(item.name).fontSize(18)
              Text(`Value: ${item.value}`).fontSize(14)
            }
          }
          .onClick(() => {
            this.showActionSheet = true
          })
        })
      }

      if (this.showActionSheet) {
        Column() {
          Button('Refresh')
            .onClick(() => {
              this.refreshSensorData()
              this.showActionSheet = false
            })
          Button('Reset')
            .onClick(() => {
              this.resetSensorData()
              this.showActionSheet = false
            })
          Button('Cancel')
            .onClick(() => {
              this.showActionSheet = false
            })
        }
      }
    }
  }

  filterSensorData(): void {
    this.filteredData = this.sensorData.filter((item: Sensor) =>
      item.name.toLowerCase().includes(this.searchText.toLowerCase())
    )
  }

  refreshSensorData(): void {
    this.sensorData = this.sensorData.map((item: Sensor) => {
      return {
        id: item.id,
        name: item.name,
        value: Math.floor(Math.random() * 100)
      } as Sensor
    })
    this.filterSensorData()
  }

  resetSensorData(): void {
    this.sensorData = [
      { id: 1, name: 'Temperature', value: 25 } as Sensor,
      { id: 2, name: 'Humidity', value: 60 } as Sensor,
      { id: 3, name: 'Pressure', value: 1013 } as Sensor,
      { id: 4, name: 'Light', value: 300 } as Sensor,
      { id: 5, name: 'Motion', value: 0 } as Sensor
    ]
    this.filterSensorData()
  }
}

