@Entry
@Component
struct FoodDeliveryTrackingApp {
  @State private deliveryData: number[] = [10, 20, 30, 40, 50, 60, 70];
  @State private chartScale: number = 1.0;
  @State private isRecording: boolean = false;

  private handlePinch(event: PinchGestureEvent) {
    this.chartScale = event.scale;
  }

  private resetZoom() {
    this.chartScale = 1.0;
  }

  private toggleRecording() {
    this.isRecording = !this.isRecording;
  }

  build() {
    Column() {
      Text('Delivery Performance Metrics')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })
        .textAlign(TextAlign.Center);

      Canvas()
        .width('90%')
        .height(300)
        .backgroundColor('#f5f5f5')
        .onDraw((context: CanvasRenderingContext2D) => {
          context.beginPath();
          context.moveTo(0, 300 - this.deliveryData[0] * 3);
          for (let i = 1; i < this.deliveryData.length; i++) {
            context.lineTo(i * 50, 300 - this.deliveryData[i] * 3);
          }
          context.strokeStyle = '#ff0000';
          context.lineWidth = 2;
          context.stroke();
        })
        .gesture(
          PinchGesture()
            .onActionUpdate((event: PinchGestureEvent) => {
              this.handlePinch(event);
            })
        );

      Row() {
        Button('Reset Zoom')
          .onClick(() => {
            this.resetZoom();
          })
          .margin({ right: 10 });

        Button(this.isRecording ? 'Stop Recording' : 'Start Recording')
          .onClick(() => {
            this.toggleRecording();
          });
      }
      .margin({ top: 20, bottom: 20 })
      .justifyContent(FlexAlign.Center);

      Text(this.isRecording ? 'Recording Active' : 'Recording Inactive')
        .fontSize(16)
        .fontColor(this.isRecording ? '#00ff00' : '#ff0000')
        .textAlign(TextAlign.Center);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff');
  }
}

import router from '@ohos.router';
