@Entry
@Component
struct VideoPlaceholderComponent {
    @State isLoading: boolean = true;
    @State sensorData: string = "Mock Sensor Data: 25°C, 60%";
    @State progressValue: number = 0;

    aboutToAppear() {
        try {
            setTimeout(() => {
                this.isLoading = false;
            }, 3000);

            const interval = setInterval(() => {
                if (this.progressValue < 100) {
                    this.progressValue += 10;
                } else {
                    clearInterval(interval);
                }
            }, 300);
        } catch (error) {
            console.error('Error in aboutToAppear:', error);
            this.sensorData = 'Sensor data unavailable';
        }
    }

    navigateToNext() {
        router.pushUrl({ url: 'pages/NextPage' });
    }

    build() {
        Column() {
            if (this.isLoading) {
                Column() {
                    Progress({ value: this.progressValue })
                        .width('80%')
                        .height(10)
                        .margin({ bottom: 20 });
                    Text('Loading...')
                        .fontSize(20);
                }
                .justifyContent(FlexAlign.Center)
                .width('100%')
                .height('100%');
            } else {
                Column() {
                    Image($r('app.media.video_placeholder'))
                        .width('100%')
