@Entry
@Component
struct PullToRefreshExample {
  @State refreshing: boolean = false
  @State items: string[] = ['Item 1', 'Item 2', 'Item 3']
  @State rotateAngle: number = 0
  @State showRefresh: boolean = true
  private timerId: number = -1

  build() {
    Column() {
      Row() {
        Button(this.showRefresh ? 'Hide Refresh' : 'Show Refresh')
          .onClick(() => {
            this.showRefresh = !this.showRefresh
          })
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .padding(10)

      if (this.showRefresh) {
        Column() {
          Row() {
            Image($r('app.media.app_icon'))
              .width(30)
              .height(30)
              .rotate({ x: 0, y: 0, z: 1, angle: this.rotateAngle })
            Text(this.refreshing ? 'Refreshing...' : 'Pull to Refresh')
              .margin({ left: 10 })
          }
          .width('100%')
          .justifyContent(FlexAlign.Center)
          .padding(10)
          .onClick(() => {
            if (!this.refreshing) {
              this.refreshing = true
              animateTo({
                duration: 1000,
                curve: Curve.Linear,
                iterations: -1,
                playMode: PlayMode.Normal
              }, () => {
                this.rotateAngle = 360
              })
              this.timerId = setTimeout(() => {
                this.items = ['New Item ' + (this.items.length + 1), ...this.items]
                this.refreshing = false
              }, 2000)
            }
          })
        }
      }

      List() {
        ForEach(this.items, (item: string) => {
          ListItem() {
            Text(item)
              .width('100%')
              .height(50)
              .fontSize(16)
              .textAlign(TextAlign.Center)
              .backgroundColor('#f5f5f5')
              .margin({ top: 10 })
          }
        })
      }
      .width('100%')
      .height('100%')
    }
    .width('100%')
    .height('100%')
  }

  aboutToDisappear() {
    if (this.timerId !== -1) {
      clearTimeout(this.timerId)
    }
  }
}

