@Entry
@Component
struct SleepTracker {
    @State progress: number = 0
    @State isRunning: boolean = false
    @State currentPage: number = 1
    private intervalId: number = -1

    startProgress() {
        if (this.progress < 100) {
            this.intervalId = setInterval(() => {
                if (this.progress < 100) {
                    this.progress += 1
                } else {
                    clearInterval(this.intervalId)
                }
            }, 100)
        }
    }

    stopProgress() {
        clearInterval(this.intervalId)
    }

    resetProgress() {
        clearInterval(this.intervalId)
        this.progress = 0
        this.isRunning = false
    }

    nextPage() {
        if (this.currentPage < 3) {
            this.currentPage += 1
        }
    }

    prevPage() {
        if (this.currentPage > 1) {
            this.currentPage -= 1
        }
    }

    build() {
        Column() {
            Text('Sleep Tracker')
                .fontSize(24)
                .margin({ bottom: 20 })

            Progress({ value: this.progress, total: 100 })
                .size({ width: '80%', height: 20 })
                .color('#4CAF50')
                .margin({ bottom: 20 })

            Row({ space: 20 }) {
                Button('Start')
                    .onClick(() => {
                        this.startProgress()
                        this.isRunning = true
                    })
                Button('Pause')
                    .onClick(() => {
                        this.stopProgress()
                        this.isRunning = false
                    })
                Button('Reset')
                    .onClick(() => this.resetProgress())
            }
            .margin({ bottom: 20 })

            Row({ space: 20 }) {
                Button('Prev')
                    .onClick(() => this.prevPage())
                Text(`Page ${this.currentPage}`)
                Button('Next')
                    .onClick(() => this.nextPage())
            }
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .padding(20)
    }
}

