@Entry
@Component
struct Calculator {
  @State result: string = '0'
  @State currentInput: string = ''
  @State operator: string = ''
  @State themeColor: string = '#FFFFFF'

  build() {
    Column() {
      Text(this.result)
        .fontSize(40)
        .width('100%')
        .textAlign(TextAlign.End)
        .margin({ bottom: 20 })

      Grid() {
        ForEach(['7', '8', '9', '/', '4', '5', '6', '*', '1', '2', '3', '-', 'C', '0', '=', '+'], (button: string) => {
          GridItem() {
            Button(button)
              .width('100%')
              .height(60)
              .onClick(() => this.handleButtonPress(button))
          }
        })
      }
      .columnsTemplate('1fr 1fr 1fr 1fr')
      .rowsTemplate('1fr 1fr 1fr 1fr')
      .width('100%')
      .height(300)

      Row() {
        Text('Theme Color:')
          .fontSize(20)
          .margin({ right: 10 })

        Button('Pick Color')
          .onClick(() => this.showColorPicker())
          .margin({ right: 10 })

        Row()
          .width(50)
          .height(50)
          .backgroundColor(this.themeColor)
          .borderRadius(25)
      }
      .margin({ top: 20 })
    }
    .width('100%')
    .padding(20)
    .backgroundColor(this.themeColor)
  }

  handleButtonPress(button: string) {
    if (button >= '0' && button <= '9') {
      this.currentInput += button
      this.result = this.currentInput
    } else if (button === 'C') {
      this.result = '0'
      this.currentInput = ''
      this.operator = ''
    } else if (button === '=') {
      this.calculateResult()
    } else {
      this.operator = button
      this.result = this.currentInput
      this.currentInput = ''
    }
  }

  calculateResult() {
    const num1 = parseFloat(this.result)
    const num2 = parseFloat(this.currentInput)
    let calculatedResult = 0

    switch (this.operator) {
      case '+':
        calculatedResult = num1 + num2
        break
      case '-':
        calculatedResult = num1 - num2
        break
      case '*':
        calculatedResult = num1 * num2
        break
      case '/':
        calculatedResult = num1 / num2
        break
    }

    this.result = calculatedResult.toString()
    this.currentInput = ''
    this.operator = ''
  }

  showColorPicker() {
    // Custom implementation for ColorPicker
    // This would typically open a dialog or modal to select a color
    // For simplicity, we simulate a color change here
    const colors = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FF00FF', '#FFA500']
    const randomColor = colors[Math.floor(Math.random() * colors.length)]
    this.themeColor = randomColor
  }
}

