import { Swiper, SwiperController, SwiperItem } from '@ohos.arkui.advanced';
import { Column, Text, Button, Row } from '@ohos.arkui.component';
import { FlexAlign, FontWeight, TextAlign } from '@ohos.arkui.enums';

@Entry
@Component
struct LocationPagination {
  @State private currentPageIndex: number = 0;
  private locationData: string[] = ["Location 1", "Location 2", "Location 3"];
  private swiperController: SwiperController = new SwiperController();

  @Builder
  private buildLocationPage(location: string) {
    Column() {
      Text(location)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });
      Text(`Details for ${location}`)
        .fontSize(16)
        .textAlign(TextAlign.Center);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }

  @Builder
  private buildNavigationButtons() {
    Row() {
      Button('Previous')
        .onClick(() => {
          if (this.currentPageIndex > 0) {
            this.currentPageIndex--;
            this.swiperController.showPrevious();
          }
        })
        .margin({ right: 10 });
      Button('Next')
        .onClick(() => {
          if (this.currentPageIndex < this.locationData.length - 1) {
            this.currentPageIndex++;
            this.swiperController.showNext();
          }
        });
    }
    .margin({ top: 20 });
  }

  @Builder
  private buildStatusMessage() {
    Column() {
      if (this.currentPageIndex === 0) {
        Text('First Location')
          .fontSize(18)
          .margin({ top: 10 });
      } else if (this.currentPageIndex === this.locationData.length - 1) {
        Text('Last Location')
          .fontSize(18)
          .margin({ top: 10 });
      } else {
        Text('Middle Location')
          .fontSize(18)
          .margin({ top: 10 });
      }
    }
  }

  build() {
    Column() {
      Swiper({ controller: this.swiperController }) {
        ForEach(this.locationData, (location: string) => {
          SwiperItem() {
            this.buildLocationPage(location);
          }
        });
      }
      .width('100%')
      .height('60%');

      this.buildStatusMessage();
      this.buildNavigationButtons();
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

