import { Tabs, TabContent, Button, Text, Row, Column } from '@ohos.arkui.advanced';

@Entry
@Component
struct AudioPlayer {
  @State isPlaying: boolean = false;
  @State isStopped: boolean = true;
  @State currentTrack: string = 'Movie Preview Track';

  private playAudio(): void {
    this.isPlaying = true;
    this.isStopped = false;
    console.info('Playing: ' + this.currentTrack);
  }

  private pauseAudio(): void {
    this.isPlaying = false;
    console.info('Paused: ' + this.currentTrack);
  }

  private stopAudio(): void {
    this.isPlaying = false;
    this.isStopped = true;
    console.info('Stopped: ' + this.currentTrack);
  }

  build() {
    Column() {
      Tabs({ barPosition: 'start' }) {
        TabContent() {
          Column() {
            Text('Now Playing: ' + this.currentTrack)
              .fontSize(20)
              .margin({ bottom: 20 });

            Row({ space: 20 }) {
              Button('Play')
                .enabled(!this.isPlaying || this.isStopped)
                .onClick(() => this.playAudio());

              Button('Pause')
                .enabled(this.isPlaying)
                .onClick(() => this.pauseAudio());

              Button('Stop')
                .enabled(!this.isStopped)
                .onClick(() => this.stopAudio());
            }.justifyContent('center').padding(20);
          }.width('100%').height('100%').padding(20);
        }.tabBar('Player');
      }.width('100%').height('100%');
    }.width('100%').height('100%');
  }
}

import { Swiper, SwiperController } from '@ohos.arkui.swiper';
import { Button } from '@ohos.arkui.component.Button';
import { Text } from '@ohos.arkui.component.Text';
import { Column } from '@ohos.arkui.component.Column';
import { Row } from '@ohos.arkui.component.Row';
import { Flex } from '@ohos.arkui.component.Flex';
import { TextInput } from '@ohos.arkui.component.TextInput';

interface Task {
  id: number;
  title: string;
  completed: boolean;
}

@Entry
@Component
struct TaskManager {
  @State tasks: Task[] = [
    { id: 1, title: 'Task 1', completed: false } as Task,
    { id: 2, title: 'Task 2', completed: false } as Task,
    { id: 3, title: 'Task 3', completed: false } as Task
  ];
  @State newTaskTitle: string = '';
  swiperController: SwiperController = new SwiperController();

  private findMaxId(): number {
    let max = 0;
    this.tasks.forEach(task => {
      if (task.id > max) max = task.id;
    });
    return max;
  }

  addTask(): void {
    if (this.newTaskTitle.trim() === '') return;
    const newId = this.tasks.length > 0 ? this.findMaxId() + 1 : 1;
    this.tasks = this.tasks.concat([{
      id: newId,
      title: this.newTaskTitle,
      completed: false
    } as Task]);
    this.newTaskTitle = '';
  }

  toggleTaskCompletion(taskId: number): void {
    this.tasks = this.tasks.map(task => {
      if (task.id === taskId) {
        return {
          id: task.id,
          title: task.title,
          completed: !task.completed
        } as Task;
      }
      return task;
    });
  }

  deleteTask(taskId: number): void {
    this.tasks = this.tasks.filter(task => task.id !== taskId);
  }

  build() {
    Column() {
      Text('Task Manager')
        .fontSize(24)
        .margin({ bottom: 20 });

      Swiper(this.swiperController) {
        ForEach(this.tasks, (task: Task) => {
          Column() {
            Text(task.title)
              .fontSize(18)
              .margin({ bottom: 10 });
            Row() {
              Button(task.completed ? 'Undo' : 'Complete')
                .onClick(() => this.toggleTaskCompletion(task.id));
              Button('Delete')
                .onClick(() => this.deleteTask(task.id))
                .margin({ left: 10 });
            }
          }
          .padding(20)
          .borderRadius(8)
          .backgroundColor('#f5f5f5')
          .margin({ bottom: 10 });
        });
      }
      .height('60%')
      .indicator(false)
      .autoPlay(false)
      .loop(false);

      Row() {
        TextInput({ placeholder: 'Enter new task' })
          .width('70%')
          .onChange((value: string) => {
            this.newTaskTitle = value;
          });
        Button('Add Task')
          .onClick(() => this.addTask())
          .margin({ left: 10 });
      }
      .margin({ top: 20 });
    }
    .padding(20)
    .width('100%')
    .height('100%');
  }
}

import { Column, Row, Text, Button, List, ListItem, TextInput, TimePicker } from '@ohos.arkui.UIContext';
import { State, Entry, Component } from '@ohos.arkui.advancedUI';
import { ResourceStr } from '@ohos.resourceManager';

interface Note {
  id: number;
  content: string;
  reminderTime: string;
}

interface TimeValue {
  hour: ResourceStr;
  minute: ResourceStr;
}

@Entry
@Component
struct NoteApp {
  @State notes: Note[] = [];
  @State newNoteContent: string = '';
  @State reminderTime: string = '00:00';
  @State isReminderSet: boolean = false;

  build() {
    Column({ space: 10 }) {
      TextInput({ placeholder: 'Enter your note...', text: this.newNoteContent })
        .height(100)
        .width('90%')
        .onChange((value: string) => {
          this.newNoteContent = value;
        });

      TimePicker({ selected: this.reminderTime })
        .width('90%')
        .onChange((value: TimeValue) => {
          this.reminderTime = value.hour.toString().padStart(2, '0') + ':' + value.minute.toString().padStart(2, '0');
          this.isReminderSet = true;
        });

      Row({ space: 10 }) {
        Button('Save')
          .onClick(() => {
            if (this.newNoteContent.trim()) {
              let newNote: Note = {
                id: Date.now(),
                content: this.newNoteContent,
                reminderTime: this.isReminderSet ? this.reminderTime : 'No reminder'
              };
              this.notes.push(newNote);
              this.newNoteContent = '';
              this.reminderTime = '00:00';
              this.isReminderSet = false;
            }
          });

        Button('Clear')
          .onClick(() => {
            this.newNoteContent = '';
            this.reminderTime = '00:00';
            this.isReminderSet = false;
          });
      }

      List({ space: 10 }) {
        ForEach(this.notes, (note: Note, index: number) => {
          ListItem() {
            Column({ space: 5 }) {
              Text(note.content)
                .fontSize(16);
              Text(note.reminderTime)
                .fontSize(12)
                .fontColor('#808080');
            }
            .width('100%')
            .padding(10);
          }
          .swipeAction({
            end: {
              builder: () => {
                Button('Delete')
                  .width(80)
                  .height('100%')
                  .backgroundColor('#ff4d4f')
                  .onClick(() => {
                    this.notes = this.notes.filter((item: Note) => item.id !== note.id);
                  })
              }
            },
            distance: 50
          })
          .height(80);
        });
      }
      .layoutWeight(1)
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

