import { Tabs, TabContent, List, ListItem, Checkbox, TextInput, Text, Button, Row, Column } from '@ohos.arkui.component';
import { animateTo } from '@ohos.arkui.animate';
import { TextDecorationType, BarPosition } from '@ohos.arkui.common';

interface Task {
  id: number;
  title: string;
  completed: boolean;
  category: string;
}

@Entry
@Component
struct TaskManagementApp {
  @State tasks: Task[] = [
    { id: 1, title: 'Complete project', completed: false, category: 'Work' },
    { id: 2, title: 'Buy groceries', completed: false, category: 'Personal' },
    { id: 3, title: 'Call mom', completed: false, category: 'Personal' },
  ];

  @State activeTab: string = 'Work';
  @State showDialog: boolean = false;
  @State currentTask: Task = { id: 0, title: '', completed: false, category: 'Work' };

  toggleTaskCompletion(id: number, completed: boolean) {
    const index = this.tasks.findIndex(task => task.id === id);
    if (index !== -1) {
      this.tasks[index].completed = completed;
    }
  }

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.START }) {
        TabContent({ tabBar: 'Work' }) {
          List() {
            ForEach(
              this.tasks.filter(task => task.category === 'Work'),
              (task: Task) => {
                ListItem() {
                  Row() {
                    Checkbox()
                      .select(task.completed)
                      .onChange((value: boolean) => {
                        this.toggleTaskCompletion(task.id, value);
                      });
                    Text(task.title)
                      .fontSize(18)
                      .margin({ left: 10 })
                      .decoration({ type: task.completed ? TextDecorationType.LINE_THROUGH : TextDecorationType.NONE });
                  }
                  .padding(10)
                  .onClick(() => {
                    this.currentTask = {
                      id: task.id,
                      title: task.title,
                      completed: task.completed,
                      category: task.category
                    };
                    this.showDialog = true;
                  });
                }
              }
            );
          }
          .width('100%');
        }
        TabContent({ tabBar: 'Personal' }) {
          List() {
            ForEach(
              this.tasks.filter(task => task.category === 'Personal'),
              (task: Task) => {
                ListItem() {
                  Row() {
                    Checkbox()
                      .select(task.completed)
                      .onChange((value: boolean) => {
                        this.toggleTaskCompletion(task.id, value);
                      });
                    Text(task.title)
                      .fontSize(18)
                      .margin({ left: 10 })
                      .decoration({ type: task.completed ? TextDecorationType.LINE_THROUGH : TextDecorationType.NONE });
                  }
                  .padding(10)
                  .onClick(() => {
                    this.currentTask = {
                      id: task.id,
                      title: task.title,
                      completed: task.completed,
                      category: task.category
                    };
                    this.showDialog = true;
                  });
                }
              }
            );
          }
          .width('100%');
        }
      }
      .onChange((index: number) => {
        this.activeTab = index === 0 ? 'Work' : 'Personal';
      })
      .width('100%')
      .height('100%');

      if (this.showDialog) {
        Column() {
          TextInput({ placeholder: 'Task title' })
            .value(this.currentTask.title)
            .onChange((value: string) => {
              this.currentTask.title = value;
            })
            .width('80%')
            .margin(10);

          Button('Save')
            .onClick(() => {
              if (this.currentTask.id === 0) {
                this.currentTask.id = this.tasks.length + 1;
                this.tasks.push({
                  id: this.currentTask.id,
                  title: this.currentTask.title,
                  completed: this.currentTask.completed,
                  category: this.currentTask.category
                });
              } else {
                const index = this.tasks.findIndex(t => t.id === this.currentTask.id);
                if (index !== -1) {
                  this.tasks[index] = {
                    id: this.currentTask.id,
                    title: this.currentTask.title,
                    completed: this.currentTask.completed,
                    category: this.currentTask.category
                  };
                }
              }
              this.showDialog = false;
              this.currentTask = { id: 0, title: '', completed: false, category: this.activeTab };
            })
            .width('80%');

@Entry
@Component
struct ColorPickerApp {
  @State selectedColor: string = '#FF0000'
  @State showDialog: boolean = false
  @State progress: number = 0
  private colors: string[] = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FF00FF']

  build() {
