      }

      if (this.showDialog) {
        Column()
          .width('80%')
          .height(150)
          .backgroundColor('#FFFFFF')
          .borderRadius(10)
          .padding(20)
          .justifyContent(FlexAlign.Center)
          .alignItems(HorizontalAlign.Center)
        {
          Text('Progress Completed!')
            .fontSize(18)
            .margin({ bottom: 10 })
          Button('Close')
            .onClick(() => {
              this.showDialog = false
              this.progress = 0
            })
        }
      }
    }
    .width('100%')
    .padding(20)
  }
}

