import { Checkbox, Column, Text, FlexAlign } from '@ohos.arkui.component';
import vibrator from '@ohos.vibrator';
import abilityAccessCtrl from '@ohos.abilityAccessCtrl';
import deviceInfo from '@ohos.deviceInfo';
import { BusinessError } from '@ohos.base';

@Entry
@Component
struct CustomCheckbox {
  @State isChecked: boolean = false;
  @State statusText: string = 'Unchecked';

  private isVibrationSupported(): boolean {
    try {
      const deviceType = deviceInfo.getDeviceTypeSync();
      const isMobile = deviceType === 'phone' || deviceType === 'tablet';
      return isMobile && typeof vibrator.startVibration === 'function';
    } catch {
      return false;
    }
  }

  private async requestVibrationPermission(): Promise<boolean> {
    try {
      const atManager = abilityAccessCtrl.createAtManager();
      const context = getContext(this);
      const result = await atManager.requestPermissionsFromUser(context, ['ohos.permission.VIBRATE']);
      return result.authResults[0] === abilityAccessCtrl.GrantStatus.PERMISSION_GRANTED;
    } catch {
      console.error('Permission request failed');
      return false;
    }
  }

  private async performHapticFeedback(): Promise<void> {
    if (!this.isVibrationSupported()) {
      console.log('Vibration not supported on this device');
      return;
    }

    try {
      const hasPermission = await this.requestVibrationPermission();
      if (!hasPermission) {
        console.log('Vibration permission not granted');
        return;
      }

      vibrator.startVibration({
        type: 'time',
        duration: 100
      }, {
        usage: 'alarm'
      }, (err: BusinessError) => {
        if (err) {
          console.error('Vibration failed: ' + JSON.stringify(err));
        }
      });
    } catch (err) {
      console.error('Vibration error: ' + JSON.stringify(err));
    }
  }

  private updateCheckboxState(value: boolean): void {
    this.isChecked = value;
    this.statusText = value ? 'Checked' : 'Unchecked';
    this.performHapticFeedback();
  }

  build() {
    Column() {
      Checkbox({ name: 'customCheckbox' })
        .selected(this.isChecked)
        .selectedColor(0x0000FF)
        .width(100)
        .height(100)
        .onChange((value: boolean) => {
          this.updateCheckboxState(value);
        });

      Text(this.statusText)
        .fontSize(16)
        .margin({ top: 10 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

@Entry
@Component
struct BottomSheetApp {
  @State isBottomSheetVisible: boolean = false;
  @State offsetY: number = 0;

  build() {
    Column() {
      Button('Show Bottom Sheet')
        .onClick(() => {
          this.isBottomSheetVisible = true;
        })
        .margin(20)
        .width('80%')
        .height(50)
        .backgroundColor('#007AFF')
        .fontColor(Color.White)
        .fontSize(18);

      if (this.isBottomSheetVisible) {
        Column()
          .width('100%')
          .height('60%')
          .backgroundColor(Color.White)
          .borderRadius(20)
          .gesture(
            PanGesture({ direction: PanDirection.Vertical })
              .onActionUpdate((event: GestureEvent) => {
                this.offsetY = event.offsetY;
              })
              .onActionEnd(() => {
                if (this.offsetY > 100) {
                  this.isBottomSheetVisible = false;
                } else {
                  animateTo({ duration: 300 }, () => {
                    this.offsetY = 0;
                  });
                }
              })
          )
          .transform({ translate: { y: this.offsetY } })
          .animation({ duration: 300 }) {
          Row() {
            Text('Bottom Sheet Title')
              .fontSize(20)
              .fontWeight(FontWeight.Bold)
              .margin({ top: 20, left: 20 });

            Button() {
              Image($r('app.media.app_icon'))
                .width(24)
                .height(24)
            }
            .backgroundColor('transparent')
            .onClick(() => {
              this.isBottomSheetVisible = false;
            })
            .margin({ top: 20, right: 20 });
          }
          .width('100%')
          .justifyContent(FlexAlign.SpaceBetween);

          Text('This is the content of the bottom sheet. You can add more components here.')
            .fontSize(16)
            .margin({ top: 20, left: 20, right: 20, bottom: 20 });
        }
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

