                        });
                });
            }
            .margin({ top: 20 });

            // Color Picker
            Text('Select Rating Color:')
                .fontSize(16)
                .margin({ top: 20 });

            Flex({ wrap: FlexWrap.Wrap, justifyContent: FlexAlign.SpaceAround }) {
                ForEach(this.colors, (color: string) => {
                    Row()
                        .width(40)
                        .height(40)
