@Entry
@Component
struct EventPlanner {
  @State events: Array<string> = ['Meeting at 10 AM', 'Lunch at 1 PM', 'Team Sync at 3 PM'];
  @State currentPage: number = 1;
  @State itemsPerPage: number = 2;

  build() {
    Column() {
      Text('Event Planner')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      ForEach(this.getPaginatedEvents(), (event: string) => {
        ListItem() {
          Text(event)
            .fontSize(16)
            .margin({ bottom: 5 });
        }
      });

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentPage > 1) {
              this.currentPage -= 1;
            }
          })
          .margin(10);

        Text(`Page ${this.currentPage}`)
          .fontSize(16)
          .margin(10);

        Button('Next')
          .onClick(() => {
            if (this.currentPage < Math.ceil(this.events.length / this.itemsPerPage)) {
              this.currentPage += 1;
            }
          })
          .margin(10);
      }
      .justifyContent(FlexAlign.Center);

      Button('Add Event')
        .onClick(() => {
          const newEvent = `New Event at ${new Date().toLocaleTimeString()}`;
          this.events = [...this.events, newEvent];
          // Simulate real-time update
          setTimeout(() => {
            // Show toast notification
            console.info(`Event added: ${newEvent}`);
          }, 500);
        })
        .margin(20);
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }

  private getPaginatedEvents(): Array<string> {
    const startIndex = (this.currentPage - 1) * this.itemsPerPage;
    const endIndex = startIndex + this.itemsPerPage;
    return this.events.slice(startIndex, endIndex);
  }
}

