@Entry
@Component
struct PaymentToggleComponent {
  @State isToggled: boolean = false;
  @State paymentMethod: string = 'Credit Card';
  @State refreshing: boolean = false;
  @State transactions: string[] = ['Transaction 1', 'Transaction 2', 'Transaction 3'];
  private timerId: number = -1;

  build() {
    Column() {
      // Custom switch with animation
      Row() {
        Button(this.isToggled ? 'ON' : 'OFF')
          .width(80)
          .height(40)
          .backgroundColor(this.isToggled ? '#4CAF50' : '#F44336')
          .onClick(() => {
            animateTo({
              duration: 200
            }, () => {
              this.isToggled = !this.isToggled;
            });
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .margin({ bottom: 20 });

      // Payment method selector
      Row() {
        Button('Credit Card')
          .width('50%')
          .height(40)
          .backgroundColor(this.paymentMethod === 'Credit Card' ? '#4CAF50' : '#F44336')
          .onClick(() => {
            this.paymentMethod = 'Credit Card';
          });
        Button('PayPal')
          .width('50%')
          .height(40)
          .backgroundColor(this.paymentMethod === 'PayPal' ? '#4CAF50' : '#F44336')
          .onClick(() => {
            this.paymentMethod = 'PayPal';
          });
      }
      .width('100%')
      .margin({ bottom: 20 });

      // Refreshable transaction list
      Scroll() {
        List() {
          ForEach(this.transactions, (transaction: string) => {
            ListItem() {
              Text(transaction)
                .width('100%')
                .height(50)
                .fontSize(16)
                .textAlign(TextAlign.Center)
                .backgroundColor('#f5f5f5')
                .margin({ top: 10 });
            }
          });
        }
      }
      .onScrollEdge((side: Edge) => {
        if (side === Edge.Bottom && !this.refreshing) {
          this.refreshing = true;
          this.timerId = setTimeout(() => {
            this.transactions = [...this.transactions, `New Transaction ${this.transactions.length + 1}`];
            this.refreshing = false;
          }, 2000);
        }
      });

      // Display selected payment method
      Text(`Selected: ${this.paymentMethod}`)
        .width('100%')
        .textAlign(TextAlign.Center)
        .margin({ top: 20 });

      // Loading indicator during refresh
      if (this.refreshing) {
        Row() {
          LoadingProgress()
            .width(30)
            .height(30);
          Text('Refreshing...')
            .margin({ left: 10 });
        }
        .width('100%')
        .justifyContent(FlexAlign.Center)
        .padding(10);
      }
    }
    .width('100%')
    .height('100%');
  }

  aboutToDisappear() {
    if (this.timerId !== -1) {
      clearTimeout(this.timerId);
    }
  }
}

