import { Column, Row, Text, ScrollView, TextInput, Button, Toggle, Progress, ToggleType, Web } from '@ohos.arkui.advanced';
import webview from '@ohos.web.webview';

interface Task {
  name: string;
  completed: boolean;
}

@Entry
@Component
struct TaskManagerApp {
  @State tasks: Array<Task> = [];
  @State newTaskName: string = '';
  @State progress: number = 0;

  build() {
    Column({ space: 20 }) {
      Row({ space: 10 }) {
        TextInput({ placeholder: 'Enter task name' })
          .width('70%')
          .onChange((value: string) => {
            this.newTaskName = value;
          });
        Button('Add Task')
          .width('30%')
          .onClick(() => {
            if (this.newTaskName.trim()) {
              this.tasks.push({ name: this.newTaskName, completed: false } as Task);
              this.newTaskName = '';
              this.updateProgress();
            }
          });
      }
      .width('100%')
      .padding(10);

      Row() {
        Text('Progress: ' + this.progress + '%');
        Progress({ value: this.progress, total: 100 })
          .width('70%');
      }
      .width('100%')
      .padding(10);

      ScrollView() {
        Column() {
          ForEach(this.tasks, (task: Task, index: number) => {
            Row({ space: 10 }) {
              Toggle({ type: ToggleType.Checkbox, isOn: task.completed })
                .onChange((isOn: boolean) => {
                  this.tasks[index].completed = isOn;
                  this.updateProgress();
                });
              Text(task.name)
                .fontSize(16);
            }
            .width('100%')
            .padding(10);
          });
        }
        .width('100%');
      }
      .height('40%');

      Web({ src: 'https://www.example.com' })
        .height('30%')
        .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }

  private updateProgress() {
    const completedTasks = this.tasks.filter(task => task.completed).length;
    this.progress = this.tasks.length ? Math.round((completedTasks / this.tasks.length) * 100) : 0;
  }
}

@Entry
@Component
struct TranslationQuiz {
  @State currentQuestion: number = 1
  private totalQuestions: number = 5
  @State progress: number = 0
  @State accessibilityMode: boolean = false

  @Builder
  Breadcrumb() {
    Row() {
      ForEach([1, 2, 3, 4, 5], (step: number) => {
        Column() {
          Circle()
            .width(30)
            .height(30)
            .fill(this.currentQuestion >= step ? '#0000FF' : '#CCCCCC')
          Text(`Q${step}`)
            .fontSize(14)
            .margin({ top: 5 })
        }
        .margin({ right: 10 })

        if (step < this.totalQuestions) {
          Divider()
            .width(30)
            .strokeWidth(2)
            .color(this.currentQuestion > step ? '#0000FF' : '#CCCCCC')
        }
      })
    }
    .margin({ top: 20, bottom: 20 })
  }

  @Builder
  QuizContent() {
    Column() {
      Text(`Question ${this.currentQuestion}`)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      Text("Translate this sentence: 'Hello, world!'")
        .fontSize(18)
        .margin({ bottom: 20 })

      TextInput({ placeholder: "Your answer here..." })
        .width('80%')
        .height(50)
        .margin({ bottom: 20 })

      Button("Submit")
        .onClick(() => {
          if (this.currentQuestion < this.totalQuestions) {
            this.currentQuestion++
            this.progress = (this.currentQuestion / this.totalQuestions) * 100
          }
        })
    }
    .width('100%')
    .alignItems(HorizontalAlign.Center)
  }

  @Builder
  AccessibilityToggle() {
    Row() {
