@Entry
@Component
struct TravelPlanningCRM {
  @State private travelItems: TravelItem[] = [];
  @State private loading: boolean = false;
  @State private page: number = 1;
  @State private hasMore: boolean = true;

  private loadTravelItems() {
    if (this.loading || !this.hasMore) return;
    this.loading = true;

    setTimeout(() => {
      const newItems: TravelItem[] = Array.from({ length: 10 }, (_: undefined, i: number): TravelItem => ({
        id: this.page + '-' + i,
        title: 'Travel Destination ' + this.page + '-' + i,
        rating: Math.floor(Math.random() * 5) + 1,
        counter: Math.floor(Math.random() * 100),
      }));

      this.travelItems = [...this.travelItems, ...newItems];
      this.page += 1;
      this.hasMore = this.page < 5;
      this.loading = false;
    }, 1000);
  }

  @Builder
  private TravelItemRow(item: TravelItem) {
    Row() {
      Column() {
        Text(item.title)
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .accessibilityDescription('Travel destination: ' + item.title);

        Text('\\u2605'.repeat(item.rating) + '\\u2606'.repeat(5 - item.rating))
          .fontSize(20)
          .accessibilityDescription('Rating: ' + item.rating + ' out of 5');

        Text('Visits: ' + item.counter)
          .fontSize(14)
          .accessibilityDescription('Number of visits: ' + item.counter);
      }
      .padding(10)
      .width('100%')
      .borderRadius(8)
      .backgroundColor('#FFFFFF')
      .shadow(2)
      .focusable(true)
      .onClick(() => {
      });
    }
    .padding(10)
    .width('100%')
    .accessibilityGroup(true);
  }

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.travelItems, (item: TravelItem) => {
          ListItem({}) {
            this.TravelItemRow(item);
          }
        });

        if (this.loading) {
          ListItem({}) {
            Column() {
              LoadingProgress()
                .width(50)
                .height(50)
                .accessibilityDescription('Loading more items');
              Text('Loading...')
                .fontSize(14)
                .margin({ top: 10 });
            }
            .width('100%')
            .height(100)
            .justifyContent(FlexAlign.Center)
            .alignItems(HorizontalAlign.Center);
          }
        }
      }
      .width('100%')
      .height('100%')
      .accessibilityGroup(true)
      .onScrollIndex((startIndex: number) => {
        if (startIndex >= this.travelItems.length - 5 && !this.loading) {
          this.loadTravelItems();
        }
      });
    }
    .width('100%')
    .height('100%')
    .onAppear(() => {
      this.loadTravelItems();
    });
  }
}

interface TravelItem {
  id: string;
  title: string;
  rating: number;
  counter: number;
}

