import { Stack, Image, ImageFit } from '@ohos.arkui.advanced';
import prompt from '@ohos.prompt';

@Entry
@Component
struct DocumentViewer {
  @State currentPage: number = 0;
  private pages: string[] = ['page1', 'page2', 'page3', 'page4'];
  private lastX: number = 0;

  handleSwipe(offsetX: number) {
    if (offsetX < -50 && this.currentPage < this.pages.length - 1) {
      this.currentPage++;
      prompt.showToast({ message: 'Next page', duration: 2000 });
    } else if (offsetX > 50 && this.currentPage > 0) {
      this.currentPage--;
      prompt.showToast({ message: 'Previous page', duration: 2000 });
    }
  }

  build() {
    Stack() {
      Image($r('app.media.' + this.pages[this.currentPage]))
        .objectFit(ImageFit.Contain)
        .width('100%')
        .height('100%')
        .onTouch((event: TouchEvent) => {
          if (event.type === TouchType.Move && event.touches.length > 0) {
            const touch = event.touches[0];
            this.handleSwipe(touch.screenX - this.lastX);
            this.lastX = touch.screenX;
          }
        });
    }
    .width('100%')
    .height('100%');
  }
}

