@Entry
@Component
struct App {
    @State elapsedTime: number = 0
    @State isRunning: boolean = false
    private timerId: number = -1
    @State currentScreen: string = 'stopwatch'
    @State ratingValue: number = 3
    @State pdfList: string[] = ['pdf_document1', 'pdf_document2', 'pdf_document3']

    build() {
        Navigation() {
            if (this.currentScreen === 'stopwatch') {
                Column() {
                    Text(this.formatTime(this.elapsedTime))
                        .fontSize(40)
                        .margin(20)

                    Row() {
                        Button(this.isRunning ? 'Stop' : 'Start')
                            .onClick(() => {
                                if (this.isRunning) {
                                    clearInterval(this.timerId)
                                } else {
                                    this.timerId = setInterval(() => {
                                        this.elapsedTime += 1
                                    }, 10)
                                }
                                this.isRunning = !this.isRunning
                            })
                            .margin(10)

                        Button('Reset')
                            .onClick(() => {
                                clearInterval(this.timerId)
                                this.elapsedTime = 0
                                this.isRunning = false
                            })
                            .margin(10)
                    }

                    Rating({ rating: this.ratingValue })
                        .onChange((value: number) => {
                            this.ratingValue = value
                        })
                        .margin(20)

                    Button('View PDFs')
                        .onClick(() => {
                            this.currentScreen = 'pdfviewer'
                        })
                        .margin(20)
                }
                .width('100%')
                .height('100%')
                .justifyContent(FlexAlign.Center)
            } else {
                Column() {
                    List({ space: 10 }) {
                        ForEach(this.pdfList, (pdf: string) => {
                            ListItem() {
                                Text(pdf)
                                    .fontSize(20)
                                    .margin(10)
                            }
                        })
                    }

                    Button('Back to Stopwatch')
                        .onClick(() => {
                            this.currentScreen = 'stopwatch'
                        })
                        .margin(20)
                }
                .width('100%')
                .height('100%')
            }
        }
    }

    private formatTime(time: number): string {
        const minutes = Math.floor(time / 6000)
        const seconds = Math.floor((time % 6000) / 100)
        const centiseconds = time % 100
        return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}.${centiseconds.toString().padStart(2, '0')}`
    }
}

