import { Column, Text, Button, List, ListItem, Row, TextInput, TextArea, ForEach, Checkbox, Stack, Page, FlexAlign } from '@ohos.arkui.advanced';
import { State, Entry, Component } from '@ohos.arkui.ability';

interface Note {
  id: number;
  title: string;
  content: string;
  selected: boolean;
}

interface ThemeColors {
  background: string;
  text: string;
  cardBackground: string;
}

interface ColorScheme {
  light: ThemeColors;
  dark: ThemeColors;
}

@Entry
@Component
struct NoteApp {
  @State notes: Note[] = [];
  @State newNoteTitle: string = '';
  @State newNoteContent: string = '';
  @State isDarkMode: boolean = false;

  private colors: ColorScheme = {
    light: {
      background: '#FFFFFF',
      text: '#000000',
      cardBackground: '#F5F5F5',
    },
    dark: {
      background: '#121212',
      text: '#FFFFFF',
      cardBackground: '#1E1E1E',
    },
  };

  private generateId(): number {
    return Math.floor(Math.random() * 1000000);
  }

  private getThemeColors(): ThemeColors {
    return this.isDarkMode ? this.colors.dark : this.colors.light;
  }

  private addNote(): void {
    if (this.newNoteTitle.trim() && this.newNoteContent.trim()) {
      const newNote: Note = {
        id: this.generateId(),
        title: this.newNoteTitle,
        content: this.newNoteContent,
        selected: false,
      };
      this.notes = this.notes.concat(newNote);
      this.newNoteTitle = '';
      this.newNoteContent = '';
    }
  }

  private deleteNote(id: number): void {
    this.notes = this.notes.filter(note => note.id !== id);
  }

  private toggleNoteSelection(id: number): void {
    this.notes = this.notes.map(note => {
      if (note.id === id) {
        return {...note, selected: !note.selected};
      }
      return note;
    });
  }

  private toggleTheme(): void {
    this.isDarkMode = !this.isDarkMode;
  }

  build() {
    const theme = this.getThemeColors();

    Column() {
      Page() {
        Stack() {
          Column() {
            Row() {
              Text('Note App')
                .fontSize(24)
                .fontColor(theme.text);
              Button(this.isDarkMode ? 'Light Mode' : 'Dark Mode')
                .onClick(() => this.toggleTheme())
                .margin({ left: 20 });
            }
            .width('100%')
            .justifyContent(FlexAlign.SpaceBetween)
            .padding(20);

            TextInput({ placeholder: 'Note Title', text: this.newNoteTitle })
              .onChange((value: string) => {
                this.newNoteTitle = value;
              })
              .width('90%')
              .margin(10)
              .backgroundColor(theme.cardBackground)
              .fontColor(theme.text);

            TextArea({ placeholder: 'Note Content', text: this.newNoteContent })
              .onChange((value: string) => {
                this.newNoteContent = value;
              })
              .width('90%')
              .height(100)
              .margin(10)
              .backgroundColor(theme.cardBackground)
              .fontColor(theme.text);

            Button('Add Note')
              .onClick(() => this.addNote())
              .width('90%')
              .margin(10);

            List() {
              ForEach(this.notes, (note: Note) => {
                ListItem() {
                  Row() {
                    Checkbox()
                      .selected(note.selected)
                      .onChange((isChecked: boolean) => {
                        this.toggleNoteSelection(note.id);
                      })
                      .margin(10);
                    Column() {
                      Text(note.title)
                        .fontSize(18)
                        .fontColor(theme.text);
                      Text(note.content)
                        .fontSize(14)
                        .fontColor(theme.text)
                        .margin({ top: 5 });
                    }
                    .margin({ left: 10 });
                    Button('Delete')
                      .onClick(() => this.deleteNote(note.id))
                      .margin(10);
                  }
                  .width('100%')
                  .justifyContent(FlexAlign.SpaceBetween)
                  .padding(10)
                  .backgroundColor(theme.cardBackground);
                }
              });
            }
            .width('100%')
            .layoutWeight(1);
          }
          .width('100%')
          .height('100%');
        }
        .width('100%')
        .height('100%');

