enum HorizontalAlign {
  Center = 'center'
}

enum FlexAlign {
  Center = 'center'
}

@Entry
@Component
struct LoginScreen {
  @State username: string = '';
  @State password: string = '';
  @State rememberMe: boolean = false;
  @State loginMessage: string = '';
  @State showMessage: boolean = false;

  build() {
    Column() {
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your username', text: this.username })
        .onChange((value: string) => {
          this.username = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Row() {
        Toggle({ type: ToggleType.Switch, isOn: this.rememberMe })
          .onChange((isOn: boolean) => {
            this.rememberMe = isOn;
          });
        Text('Remember Me')
          .fontSize(16)
          .margin({ left: 10 });
      }
      .margin({ bottom: 20 });

      Button('Login')
        .onClick(() => {
          if (this.validateCredentials()) {
            this.loginMessage = 'Login successful!';
            this.showMessage = true;
            router.pushUrl({ url: 'pages/Dashboard' });
          } else {
            this.loginMessage = 'Invalid username or password.';
            this.showMessage = true;
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White);

      if (this.showMessage) {
        Text(this.loginMessage)
          .fontSize(16)
          .margin({ top: 20 })
          .fontColor(this.loginMessage === 'Login successful!' ? Color.Green : Color.Red);
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }

  validateCredentials(): boolean {
    return this.username.trim() !== '' && this.password.trim() !== '';
  }
}

import preferences from '@ohos.data.preferences';
import promptAction from '@ohos.promptAction';
import { BusinessError } from '@ohos.base';
import { FontWeight } from '@ohos.arkui';
import commonContext from '@ohos.app.ability.commonContext';

interface IGridItem {
  id: number;
  title: string;
}

@Entry
@Component
struct GridApp {
  @State private items: IGridItem[] = [
    { id: 1, title: 'Item 1' },
    { id: 2, title: 'Item 2' },
    { id: 3, title: 'Item 3' },
    { id: 4, title: 'Item 4' }
  ];
  @State private isOffline: boolean = false;
  @State private selectedItem: IGridItem | null = null;
  @State private showBottomSheet: boolean = false;

  private pref: preferences.Preferences | null = null;
  private persistKey: string = 'gridItems';

  async aboutToAppear() {
    this.pref = await preferences.getPreferences(commonContext.getContext(this), 'gridItemsStorage');
    await this.loadItems();
    setTimeout(() => {
      this.isOffline = true;
      this.showOfflineAlert();
    }, 3000);
  }

  private async loadItems() {
    if (!this.pref) return;
    try {
      const data = await this.pref.get(this.persistKey, '[]');
      if (data) {
        this.items = JSON.parse(data as string);
      }
    } catch (error) {
      console.error('Failed to load items:', error);
    }
  }

  private async saveItems() {
    if (!this.pref) return;
    try {
      await this.pref.put(this.persistKey, JSON.stringify(this.items));
      await this.pref.flush();
    } catch (error) {
      console.error('Failed to save items:', error);
    }
  }

  private showOfflineAlert() {
    try {
      promptAction.showDialog({
        title: 'Offline Alert',
        message: 'Please check your internet connection.',
        buttons: [{ text: 'OK', color: '#000000' }]
      });
    } catch (error) {
      console.error('Failed to show offline alert:', error);
    }
  }

  private deleteItem(item: IGridItem) {
    this.items = this.items.filter(i => i.id !== item.id);
    this.saveItems();
    this.showBottomSheet = false;
  }

  build() {
    Column() {
      Grid() {
        ForEach(this.items, (item: IGridItem) => {
          GridItem() {
            Column() {
              Text(item.title)
                .fontSize(16)
                .margin({ bottom: 8 });
              Button('More Options')
                .onClick(() => {
                  this.selectedItem = item;
                  this.showBottomSheet = true;
                })
                .width(120)
                .height(40)
                .backgroundColor('#FFFFFF')
                .fontColor('#000000');
            }
            .padding(16)
            .borderRadius(8)
            .border({ width: 1, color: '#CCCCCC' })
            .width('100%')
            .height('100%');
          }
          .margin(8);
        });
      }
      .columnsTemplate('1fr 1fr')
      .columnsGap(16)
      .rowsGap(16)
      .width('100%')
      .height('100%');

      if (this.showBottomSheet) {
        Stack() {
          Column() {
            Text('Options')
              .fontSize(20)
              .fontWeight(FontWeight.Bold)
              .margin({ top: 16, bottom: 16 });
            List() {
              ListItem() {
                Text('Edit')
                  .fontSize(16)
                  .onClick(() => {
                    this.showBottomSheet = false;
                  });
              }
              .height(48);
              ListItem() {
                Text('Delete')
                  .fontSize(16)
                  .onClick(() => {
                    if (this.selectedItem) {
                      this.deleteItem(this.selectedItem);
                    }
                  });
              }
              .height(48);
            }
            .width('100%');
            Button('Close')
              .onClick(() => {
                this.showBottomSheet = false;
              })
              .width('100%')
              .margin({ top: 16 })
              .backgroundColor('#FFFFFF')
              .fontColor('#000000');
          }
          .width('100%')
          .backgroundColor('#FFFFFF')
          .borderRadius(16);
        }
        .width('100%')
        .height('50%')
        .position({ x: 0, y: '50%' });
      }

