import { Toggle, ToggleType, FlexAlign, State } from '@ohos.arkui.component';
import { Canvas } from '@ohos.arkui.component';

interface CanvasReadyEvent {
  context: CanvasRenderingContext2D;
}

interface Page {
  id: number;
  content: string;
}

interface Chapter {
  id: number;
  title: string;
  pages: Page[];
}

@Entry
@Component
struct BookReaderApp {
  @State isNightMode: boolean = false;
  @State currentPage: Page | null = null;
  @State context: CanvasRenderingContext2D | null = null;
  @State chapters: Chapter[] = [
    {
      id: 1,
      title: 'Chapter 1',
      pages: [
        { id: 1, content: 'This is the first page of Chapter 1.' },
        { id: 2, content: 'This is the second page of Chapter 1.' },
      ],
    },
    {
      id: 2,
      title: 'Chapter 2',
      pages: [
        { id: 1, content: 'This is the first page of Chapter 2.' },
        { id: 2, content: 'This is the second page of Chapter 2.' },
      ],
    },
  ];

  onCanvasReady(event: CanvasReadyEvent): void {
    this.context = event.context;
    if (this.currentPage) {
      this.renderPage(this.context);
    }
  }

  renderPage(context: CanvasRenderingContext2D): void {
    if (!context) return;
    const backgroundColor = this.isNightMode ? '#000000' : '#FFFFFF';
    const textColor = this.isNightMode ? '#FFFFFF' : '#000000';

    context.fillStyle = backgroundColor;
    context.fillRect(0, 0, 1000, 1000);

    context.fillStyle = textColor;
    context.font = '16px sans-serif';
    context.fillText(this.currentPage?.content || '', 20, 30);
  }

  toggleNightMode(): void {
    this.isNightMode = !this.isNightMode;
  }

  navigateToPage(page: Page): void {
    this.currentPage = page;
    if (this.context) {
      this.renderPage(this.context);
    }
  }

  build() {
    Column() {
      Row() {
        Text('Book Reader')
          .fontSize(24)
          .fontWeight('bold');
        Toggle({ type: ToggleType.Switch })
          .isOn(this.isNightMode)
          .onChange(() => this.toggleNightMode())
          .margin({ left: 16 });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceBetween)
      .padding(16);

      Canvas(this.context)
        .width('100%')
        .height('60%')
        .backgroundColor(this.isNightMode ? '#000000' : '#FFFFFF')
        .onReady((event: CanvasReadyEvent) => {
          this.onCanvasReady(event);
        });

      Column() {
        ForEach(this.chapters, (chapter: Chapter) => {
          Column() {
            Text(chapter.title)
              .fontSize(18)
              .fontWeight('bold')
              .margin({ bottom: 8 });
            ForEach(chapter.pages, (page: Page) => {
              Button(page.content)
                .width('100%')
                .height(40)
                .margin({ bottom: 8 })
                .onClick(() => this.navigateToPage(page));
            });
          }
          .width('100%')
          .padding(8);
        });
      }
      .width('100%')
      .margin({ top: 16 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.isNightMode ? '#000000' : '#FFFFFF');
  }
}

