import { Divider, Image } from '@ohos.arkui.advanced';
import { PanGesture, PanGestureEvent } from '@ohos.arkui.gesture';
import prompt from '@system.prompt';

@Entry
@Component
struct VideoFrameNavigation {
  @State currentFrameIndex: number = 0;
  private frameResources: string[] = [
    'media/frame1.jpg',
    'media/frame2.jpg',
    'media/frame3.jpg',
    'media/frame4.jpg'
  ];

  @Builder DialogBuilder() {
    Column() {
      ForEach(this.frameResources, (frame: string, index: number) => {
        Image($rawfile(frame))
          .width(100)
          .height(100)
          .margin(4)
          .onClick(() => {
            this.currentFrameIndex = index;
            prompt.showToast({ message: 'Frame selected', duration: 2000 });
          });
      });
    }
    .padding(16)
    .width('80%')
    .backgroundColor(0xFFFFFF)
    .borderRadius(8);
  }

  build() {
    Column() {
      Divider()
        .strokeWidth(2)
        .color(0x000000)
        .onClick(() => {
          prompt.showDialog({
            title: 'Select Frame',
            message: 'Choose a frame',
            buttons: [{ text: 'Close', color: '#000000' }]
          });
        })
        .gesture(
          PanGesture()
            .onActionStart(() => {})
            .onActionUpdate((event: PanGestureEvent) => {
              if (Math.abs(event.offsetX) > 20) {
                if (event.offsetX > 0) {
                  this.currentFrameIndex = Math.min(this.currentFrameIndex + 1, this.frameResources.length - 1);
                } else {
                  this.currentFrameIndex = Math.max(this.currentFrameIndex - 1, 0);
                }
              }
            })
        );

      Image($rawfile(this.frameResources[this.currentFrameIndex]))
        .width('100%')
        .height(200)
        .margin({ top: 16 });
    }
    .width('100%')
    .height('100%')
    .padding(16);
  }
}

@Entry
@Component
struct Main {
  @State progressValue: number = 0;
  @State isVisible: boolean = true;
  @State dragOffset: number = 0;

  build() {
    Column() {
      Toggle({ type: ToggleType.Switch, isOn: this.isVisible })
        .onChange((isOn: boolean) => {
          this.isVisible = isOn;
        })
        .margin(10)

      Scroll() {
        Column() {
          if (this.isVisible) {
            Progress({
              value: this.progressValue,
              total: 100,
              type: ProgressType.Linear
            })
              .size({ width: "80%", height: 20 })
              .color(Color.Blue)
              .onTouch((event: TouchEvent) => {
                if (event.type === TouchType.Move) {
                  this.progressValue = Math.min(100, Math.max(0, this.progressValue + event.touches[0].x - this.dragOffset));
                  this.dragOffset = event.touches[0].x;
                } else if (event.type === TouchType.Down) {
                  this.dragOffset = event.touches[0].x;
                }
              })
          }
        }
        .width("100%")
        .height("100%")
      }
    }
    .width("100%")
    .height("100%")
    .padding(20)
    .backgroundColor("#ffffff")
  }
}

import promptAction from '@ohos.promptAction';

interface VideoItem {
  id: number;
  title: string;
  url: string;
  isFavorite: boolean;
}

const videos: VideoItem[] = [
  { id: 1, title: 'Video 1', url: 'video_test1', isFavorite: false },
  { id: 2, title: 'Video 2', url: 'video_test2', isFavorite: true },
  { id: 3, title: 'Video 3', url: 'video_test3', isFavorite: false },
];

@Entry
@Component
struct VideoPlaybackApp {
  @State searchText: string = '';
  @State selectedFilter: string = 'All';
  @State filteredVideos: VideoItem[] = videos;
  @State selectedVideo: VideoItem | null = null;

  private filterVideos() {
    let result = videos;
    if (this.searchText) {
      result = result.filter(video => video.title.toLowerCase().includes(this.searchText.toLowerCase()));
    }
    if (this.selectedFilter === 'Recent') {
      result = result.filter(video => !video.isFavorite);
    } else if (this.selectedFilter === 'Favorites') {
      result = result.filter(video => video.isFavorite);
    }
    this.filteredVideos = result;
  }

  build() {
    Column() {
      // Search Bar
      TextInput({ placeholder: 'Search videos...' })
        .onChange((value: string) => {
          this.searchText = value;
          this.filterVideos();
        })
        .margin(16);

      // Filter Buttons
      Row({ space: 10 }) {
        Button('All')
          .onClick(() => {
            this.selectedFilter = 'All';
            this.filterVideos();
          })
          .stateEffect(this.selectedFilter === 'All');
        Button('Recent')
          .onClick(() => {
            this.selectedFilter = 'Recent';
            this.filterVideos();
          })
          .stateEffect(this.selectedFilter === 'Recent');
        Button('Favorites')
          .onClick(() => {
            this.selectedFilter = 'Favorites';
            this.filterVideos();
          })
          .stateEffect(this.selectedFilter === 'Favorites');
      }
      .margin({ bottom: 16 });

      // Video List
      Column() {
        ForEach(this.filteredVideos, (video: VideoItem) => {
          Button(video.title)
            .onClick(() => {
              this.selectedVideo = video;
            })
            .margin({ bottom: 8 });
        });
      }
      .margin(16);

      // Video Player
      if (this.selectedVideo) {
        Text('Video Player Placeholder')
          .width('100%')
          .height(300);

        Button('Back')
          .onClick(() => {
            this.selectedVideo = null;
          })
          .margin(16);
      }
    }
    .width('100%')
    .height('100%');
  }
}

