interface Note {
  id: number;
  title: string;
  content: string;
}

@Entry
@Component
struct NoteApp {
  @State notes: Note[] = [];
  @State newNoteTitle: string = '';
  @State newNoteContent: string = '';
  @State editNoteId: number | null = null;

  build() {
    Column() {
      TextInput({ placeholder: 'Enter note title...', text: this.newNoteTitle })
        .height(50)
        .width('90%')
        .onChange((newValue: string) => {
          this.newNoteTitle = newValue;
        })
        .margin(10);

      TextInput({ placeholder: 'Enter note content...', text: this.newNoteContent })
        .height(100)
        .width('90%')
        .onChange((newValue: string) => {
          this.newNoteContent = newValue;
        })
        .margin(10);

      Button(this.editNoteId !== null ? 'Update' : 'Add')
        .onClick(() => {
          if (this.newNoteTitle && this.newNoteContent) {
            if (this.editNoteId !== null) {
              this.notes = this.notes.map(note => 
                note.id === this.editNoteId ? 
                {
                  id: note.id,
                  title: this.newNoteTitle,
                  content: this.newNoteContent
                } : note
              );
              this.editNoteId = null;
            } else {
              this.notes.push({
                id: Date.now(),
                title: this.newNoteTitle,
                content: this.newNoteContent
              });
            }
            this.newNoteTitle = '';
            this.newNoteContent = '';
          }
        })
        .margin(10);

      List() {
        ForEach(this.notes, (note: Note) => {
          ListItem() {
            Column() {
              Text(note.title)
                .fontSize(16)
                .fontWeight(700);
              Text(note.content.length > 30 ? note.content.substring(0, 30) + '...' : note.content)
                .fontSize(14);
            }
            .width('100%')
            .margin({ top: 5, bottom: 5 });
          }
          .onClick(() => {
            this.editNoteId = note.id;
            this.newNoteTitle = note.title;
            this.newNoteContent = note.content;
          });
        }, (note: Note) => note.id.toString())
      }
