@Entry
@Component
struct LanguageLearningApp {
  @State progress: number = 0;
  @State isDragging: boolean = false;
  @State dragButtonX: number = 0;
  @State dragButtonY: number = 0;
  @State audioPlaying: boolean = false;

  build() {
    Column() {
      // Progress Slider
      Slider({
        value: this.progress,
        min: 0,
        max: 100,
        step: 1,
        style: SliderStyle.OutSet
      })
        .width('90%')
        .height(40)
        .margin({ top: 20, bottom: 20 })
        .onChange((value: number) => {
          this.progress = value;
        });

      // Drag-and-Drop Button
      Button('Drag Me')
        .width(100)
        .height(50)
        .position({ x: this.dragButtonX, y: this.dragButtonY })
        .onTouch((event: TouchEvent) => {
          if (event.type === TouchType.Down) {
            this.isDragging = true;
          } else if (event.type === TouchType.Move && this.isDragging) {
            this.dragButtonX = event.touches[0].x;
            this.dragButtonY = event.touches[0].y;
          } else if (event.type === TouchType.Up) {
            this.isDragging = false;
          }
        });

      // Audio Playback Button
      Button(this.audioPlaying ? 'Pause' : 'Play')
        .width(100)
        .height(50)
        .margin({ top: 20 })
        .onClick(() => {
          this.audioPlaying = !this.audioPlaying;
        });

      // Progress Text
      Text(`Progress: ${this.progress}%`)
        .fontSize(16)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

