@Entry
@Component
struct BarChartExample {
  @State currentIndex: number = 0;
  private dataPoints: number[] = [30, 60, 45, 80, 20];

  build() {
    Column() {
      Card() {
        Column() {
          Row() {
            ForEach(this.dataPoints, (value: number, index: number) => {
              Column() {
                Stack() {
                  Column()
                    .width('100%')
                    .height(`${value}%`)
                    .backgroundColor(this.currentIndex === index ? '#0000FF' : '#CCCCCC')
                    .onClick(() => {
                      animateTo({
                        duration: 300
                      }, () => {
