              .enabled(this.currentIndex > 0);

            Text(`Value: ${this.dataPoints[this.currentIndex]}`)
              .fontSize(18)
              .margin({ left: 20, right: 20 });

            Button('Next')
              .onClick(() => {
                animateTo({
