    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

import promptAction from '@ohos.promptAction';

interface Note {
  id: number;
  title: string;
  content: string;
  timestamp: string;
  image?: string;
}

@Entry
@Component
struct NoteApp {
  @State notes: Array<Note> = [];
  @State newNoteTitle: string = '';
  @State newNoteContent: string = '';
  @State editNoteId: number | null = null;
  @State showCropper: boolean = false;
  @State croppedImage: string = '';

  build() {
    Column() {
      TextArea({ placeholder: 'Enter note title...', text: this.newNoteTitle })
        .height(50)
        .width('90%')
        .onChange((value: string) => {
          this.newNoteTitle = value;
        })
        .margin(10);

      TextArea({ placeholder: 'Enter note content...', text: this.newNoteContent })
        .height(100)
        .width('90%')
        .onChange((value: string) => {
          this.newNoteContent = value;
        })
        .margin(10);

      Button('Add Image')
        .onClick(() => {
          this.showCropper = true;
        })
        .margin(10);

      Button(this.editNoteId !== null ? 'Update Note' : 'Add Note')
        .onClick(() => {
          if (this.newNoteTitle.trim() && this.newNoteContent.trim()) {
            const timestamp = new Date().toLocaleString();
            if (this.editNoteId !== null) {
              const index = this.notes.findIndex(note => note.id === this.editNoteId);
              this.notes[index] = {
                id: this.editNoteId,
                title: this.newNoteTitle,
                content: this.newNoteContent,
                timestamp: timestamp,
                image: this.croppedImage
              } as Note;
              this.editNoteId = null;
            } else {
              this.notes.push({
                id: Date.now(),
                title: this.newNoteTitle,
                content: this.newNoteContent,
                timestamp: timestamp,
                image: this.croppedImage
              } as Note);
            }
            this.newNoteTitle = '';
            this.newNoteContent = '';
            this.croppedImage = '';
          }
        })
        .margin(10);

      Scroll() {
        List() {
          ForEach(this.notes, (note: Note) => {
            ListItem() {
              Column() {
                Text(note.title)
                  .fontSize(18)
                  .fontWeight(FontWeight.Bold);
                Text(note.content)
                  .fontSize(14);
                Text(note.timestamp)
                  .fontSize(12)
                  .fontColor(Color.Gray);
                if (note.image) {
                  Image(note.image)
                    .width(100)
                    .height(100);
                }
                Row() {
                  Button('Edit')
                    .onClick(() => {
                      this.newNoteTitle = note.title;
                      this.newNoteContent = note.content;
                      this.editNoteId = note.id;
                      this.croppedImage = note.image || '';
                    });
                  Button('Delete')
                    .onClick(() => {
                      this.notes = this.notes.filter(n => n.id !== note.id);
                    });
                }
              }
            }
          });
        }
        .width('100%')
      }

      if (this.showCropper) {
        Column() {
          Text('Crop Image')
            .fontSize(18)
            .margin(10);
          Text('Drag to crop the image.')
            .margin(10);
          Row() {
            Button('Confirm')
              .onClick(() => {
                this.croppedImage = 'common/images/cropped_image.png';
                this.showCropper = false;
              })
              .margin(10);
            Button('Cancel')
              .onClick(() => {
                this.showCropper = false;
              })
              .margin(10);
          }
        }
        .width('80%')
        .height('40%')
        .backgroundColor(Color.White)
        .borderRadius(10)
        .shadow({ radius: 10, color: Color.Gray })
      }
    }
  }
}

