import { TimePicker } from '@ohos.arkui.component';
import { Toggle, ToggleType } from '@ohos.arkui.component';
import { Checkbox } from '@ohos.arkui.component';
import { Color } from '@ohos.graphics.color';
import { Curve } from '@ohos.animation';

interface TimeValue {
  hour: number;
  minute: number;
}

@Entry
@Component
struct ThemeApp {
  @State isDarkTheme: boolean = true;
  @State selectedTime: Date = new Date();
  @State displayedTime: string = '12:00';
  @State isChecked: boolean = false;

  build() {
    Column({ space: 20 }) {
      Row() {
        Text('Dark Theme')
          .fontSize(18)
          .margin({ right: 20 })
          .fontColor(this.isDarkTheme ? Color.White : Color.Black);
        Toggle({ type: ToggleType.Switch, isOn: this.isDarkTheme })
          .onChange((isOn: boolean) => {
            this.isDarkTheme = isOn;
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.Start)
      .padding(10);

      TimePicker({ selected: this.selectedTime })
        .onChange((value: TimeValue) => {
          this.selectedTime = new Date();
          this.selectedTime.setHours(value.hour, value.minute);
          this.displayedTime = `${value.hour}:${value.minute}`;
          this.isChecked = !this.isChecked;
        })
        .margin({ top: 20 });

      Checkbox()
        .select(this.isChecked)
        .onChange((checked: boolean) => {
          this.isChecked = checked;
        })
        .animation({ duration: 300, curve: Curve.EaseInOut })
        .selectedColor(this.isDarkTheme ? '#39a2db' : '#0078d7')
        .margin({ top: 20 });

      Row({ space: 10 }) {
        Text('Morning')
          .fontSize(16)
          .padding(10)
          .borderRadius(5)
          .backgroundColor(this.isDarkTheme ? '#555555' : '#EEEEEE')
          .fontColor(this.isDarkTheme ? Color.White : Color.Black);
        Text('Afternoon')
          .fontSize(16)
          .padding(10)
          .borderRadius(5)
          .backgroundColor(this.isDarkTheme ? '#555555' : '#EEEEEE')
          .fontColor(this.isDarkTheme ? Color.White : Color.Black);
        Text('Evening')
          .fontSize(16)
          .padding(10)
          .borderRadius(5)
          .backgroundColor(this.isDarkTheme ? '#555555' : '#EEEEEE')
          .fontColor(this.isDarkTheme ? Color.White : Color.Black);
      }
      .margin({ top: 20 });
