import { FlexAlign, HorizontalAlign, Color } from '@ohos.arkui.advancedUI';
import { DatePicker } from '@ohos.arkui.component';
import { animateTo, Curve } from '@ohos.arkui.animation';

@Entry
@Component
struct CustomToggle {
  @State isDatePickerVisible: boolean = false;
  @State selectedDate: string = 'No date selected';
  @State buttonText: string = 'Show DatePicker';
  @State buttonColor: Color = Color.Red;
  @State scaleValue: number = 1;

  build() {
    Column({ space: 20 }) {
      Button(this.buttonText)
        .width('80%')
        .height(50)
        .backgroundColor(this.buttonColor)
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .onClick(() => {
          animateTo({
            duration: 300,
            curve: Curve.EaseInOut
          }, () => {
            this.scaleValue = 0.9;
            this.buttonColor = this.isDatePickerVisible ? Color.Red : Color.Green;
          });

          setTimeout(() => {
            animateTo({
              duration: 300,
              curve: Curve.EaseInOut
            }, () => {
              this.scaleValue = 1;
              this.isDatePickerVisible = !this.isDatePickerVisible;
              this.buttonText = this.isDatePickerVisible ? 'Hide DatePicker' : 'Show DatePicker';
            });
          }, 300);
        });

      if (this.isDatePickerVisible) {
        DatePicker({
          start: new Date(1970, 0, 1),
          end: new Date(2100, 11, 31),
          selected: new Date()
        })
          .width('80%')
          .scale({ x: this.scaleValue, y: this.scaleValue })
          .onChange((date: Date) => {
            this.selectedDate = date.toLocaleDateString();
          });
      }

      Text(this.selectedDate)
        .fontSize(16)
        .margin({ top: 10 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

