@Entry
@Component
struct MealPlannerApp {
  @State isVideoLoading: boolean = true;
  @State selectedMeals: string[] = [];
  private mealCategories: string[] = ['Breakfast', 'Lunch', 'Dinner', 'Snacks'];
  private mealItems: Record<string, string[]> = {
    Breakfast: ['Pancakes', 'Omelette', 'Smoothie', 'Toast'],
    Lunch: ['Salad', 'Sandwich', 'Soup', 'Pasta'],
    Dinner: ['Steak', 'Fish', 'Chicken', 'Vegetables'],
    Snacks: ['Fruits', 'Nuts', 'Yogurt', 'Chips']
  };

  toggleVideoLoading(): void {
    this.isVideoLoading = !this.isVideoLoading;
    if (this.isVideoLoading) {
      animateTo({
        duration: 1000,
        curve: Curve.EaseInOut,
        iterations: -1,
        playMode: PlayMode.Alternate
      }, () => {
      });
    }
  }

  toggleMealSelection(item: string): void {
    if (this.selectedMeals.includes(item)) {
      this.selectedMeals = this.selectedMeals.filter(meal => meal !== item);
