                .margin({ bottom: 10 });

              ForEach(this.mealItems[category], (item: string) => {
                Row() {
                  Text(item)
                    .fontSize(16)
                    .margin({ right: 10 });
                  Checkbox()
                    .select(this.selectedMeals.includes(item))
                    .onChange((selected: boolean) => {
                      this.toggleMealSelection(item);
                    });
                }
                .padding(10)
                .margin({ bottom: 5 });
              });

              Divider()
                .strokeWidth(1)
                .color('#D3D3D3')
                .margin({ top: 10, bottom: 10 });
            }
            .width('100%')
            .padding(10);
          }
        });
      }
      .width('100%')
      .layoutWeight(1);
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#f5f5f5');
  }
}

import { Column, Text, Row, Button, Progress } from '@ohos.arkui.directional';
import { State } from '@ohos.arkui.advanced';
import { FontWeight, TextAlign, FlexAlign } from '@ohos.arkui.advanced';

interface Question {
  question: string;
  options: string[];
  correctAnswer: number;
}

@Entry
@Component
struct QuizApp {
  @State currentQuestionIndex: number = 0;
  @State score: number = 0;
  @State showScore: boolean = false;
  @State showFeedback: boolean = false;
  @State isCorrect: boolean = false;
  @State quizMode: boolean = false;

  private questions: Question[] = [
    {
      question: 'What is the first phase of project management?',
      options: ['Planning', 'Execution', 'Monitoring', 'Closure'],
      correctAnswer: 0
    },
    {
      question: 'Which tool is used for project scheduling?',
      options: ['Gantt Chart', 'PERT Chart', 'Both', 'None'],
      correctAnswer: 2
    },
    {
      question: 'What is the key output of the initiation phase?',
      options: ['Project Charter', 'Risk Register', 'Scope Statement', 'Budget'],
      correctAnswer: 0
    }
  ];

  checkAnswer(selectedIndex: number): void {
    const correct = selectedIndex === this.questions[this.currentQuestionIndex].correctAnswer;
    this.isCorrect = correct;
    if (correct) {
      this.score++;
    }
    this.showFeedback = true;

    setTimeout(() => {
      this.showFeedback = false;
      if (this.currentQuestionIndex < this.questions.length - 1) {
        this.currentQuestionIndex++;
      } else {
        this.showScore = true;
      }
    }, 1000);
  }

  toggleQuizMode(): void {
    this.quizMode = !this.quizMode;
    this.currentQuestionIndex = 0;
    this.score = 0;
    this.showScore = false;
    this.showFeedback = false;
  }

  build() {
    Column() {
      Row() {
        Text('Quiz Mode:')
          .fontSize(16)
          .margin({ right: 10 });
        Button(this.quizMode ? 'Test' : 'Practice')
          .onClick(() => this.toggleQuizMode())
          .width(100)
          .height(30);
      }
      .margin({ top: 20, bottom: 20 });

      if (!this.showScore) {
        Progress({
          value: ((this.currentQuestionIndex + 1) / this.questions.length) * 100,
          total: 100
        })
          .width('90%')
          .height(10)
          .margin({ top: 20, bottom: 20 });

        Text(`Question ${this.currentQuestionIndex + 1}/${this.questions.length}`)
          .fontSize(16)
          .margin({ bottom: 10 });

        Text(this.questions[this.currentQuestionIndex].question)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .textAlign(TextAlign.Center)
          .margin({ bottom: 40 })
          .padding({ left: 20, right: 20 });

        ForEach(this.questions[this.currentQuestionIndex].options, (option: string, index: number) => {
          Button(option)
            .width('80%')
            .height(50)
            .margin({ bottom: 10 })
            .backgroundColor(this.showFeedback && index === this.questions[this.currentQuestionIndex].correctAnswer ? '#4CAF50' : '#FFFFFF')
            .onClick(() => this.checkAnswer(index));
        });
      } else {
        Text(`Your Score: ${this.score}/${this.questions.length}`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .textAlign(TextAlign.Center)
          .margin({ top: 40 });

        Button('Restart Quiz')
          .width('50%')
          .height(50)
          .margin({ top: 20 })
          .onClick(() => {
            this.currentQuestionIndex = 0;
            this.score = 0;
            this.showScore = false;
          });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

interface MoodEntry {
  date: string;
  mood: string;
}

@Entry
@Component
struct MoodTracker {
  @State currentMood: string = '';
  @State moodHistory: MoodEntry[] = [];
  @State showSummary: boolean = false;

  private moods: string[] = ['\ud83d\ude0a', '\ud83d\ude04', '\ud83d\ude10', '\ud83d\ude20', '\ud83d\ude21'];

  build() {
    Column() {
      Text('How are you feeling today?')
        .fontSize(24)
        .margin(20)
        .accessibilityDescription('Question about current mood');

      Row() {
        ForEach(this.moods, (mood: string) => {
          Button(mood)
            .fontSize(40)
            .margin(10)
            .accessibilityDescription(`Select mood: ${mood}`)
            .onClick(() => {
              this.currentMood = mood;
              this.moodHistory.push({
                date: new Date().toLocaleDateString(),
                mood: mood
              });
            });
        });
      }

      if (this.currentMood) {
        Text(`Today's mood: ${this.currentMood}`)
          .fontSize(24)
          .margin(20)
          .accessibilityDescription(`Current mood is ${this.currentMood}`);
      }

      Button('View Weekly Summary')
        .onClick(() => {
          this.showSummary = !this.showSummary;
        })
        .margin(20)
        .accessibilityDescription('Toggle weekly summary view');

      if (this.showSummary) {
        List() {
          ForEach(this.moodHistory.slice(-7), (entry: MoodEntry) => {
            ListItem() {
              Row() {
                Text(entry.date)
                  .width('70%')
                  .accessibilityDescription(`Mood recorded on ${entry.date}`);
                Text(entry.mood)
                  .fontSize(30)
                  .accessibilityDescription(`Mood was ${entry.mood}`);
              }
              .padding(10);
            }
            .accessibilityDescription(`Mood entry for ${entry.date}: ${entry.mood}`);
          });
        }
      }
    }
    .width('100%')
    .padding(20);
  }
}

