import { Tabs, TabContent, BarPosition, Column, Text, Button, Grid, GridItem, ForEach } from '@ohos.arkui.advanced';
import { PinchGesture, PinchGestureEvent } from '@ohos.arkui.gesture';

@Entry
@Component
struct CalculatorApp {
  @State fontSize: number = 16;
  @State activeTab: number = 0;
  private calculatorModes: string[] = ['Basic', 'Scientific', 'Converter'];

  @Builder
  getBasicCalculator() {
    Grid() {
      ForEach(['7','8','9','/','4','5','6','*','1','2','3','-','0','.','=','+'], 
        (item: string) => {
          GridItem() {
            Button(item)
              .width('100%')
              .height('100%')
              .accessibilityLabel(`Button ${item}`)
              .onClick(() => {
              });
          }
        }
      )
    }
    .columnsTemplate('1fr 1fr 1fr 1fr')
    .columnsGap(10)
    .rowsGap(10)
    .height('60%')
    .width('100%');
  }

  @Builder
  getScientificCalculator() {
    Column() {
      Text('Scientific Calculator')
        .fontSize(20);
    }
    .width('100%')
    .height('60%');
  }

  @Builder
  getConverterCalculator() {
    Column() {
      Text('Converter Calculator')
        .fontSize(20);
    }
    .width('100%')
    .height('60%');
  }

  build() {
    Column() {
      Text('0')
        .fontSize(this.fontSize)
        .accessibilityLabel('Display')
        .accessibilityHint('Shows the current calculation result')
        .gesture(
          PinchGesture()
            .onActionStart(() => {
              console.log('Pinch gesture started');
            })
            .onActionUpdate((event: PinchGestureEvent) => {
              const scale = event.scale;
              this.fontSize = Math.max(10, Math.min(30, this.fontSize * scale));
              console.log(`Font size: ${this.fontSize}`);
            })
        );

      Tabs({ barPosition: BarPosition.BOTTOM }) {
        ForEach(this.calculatorModes, (mode: string, index: number) => {
          TabContent() {
            if (mode === 'Basic') {
              this.getBasicCalculator();
            } else if (mode === 'Scientific') {
              this.getScientificCalculator();
            } else {
              this.getConverterCalculator();
            }
          }
          .tabBar(mode)
          .accessibilityLabel(`${mode} Calculator Mode`);
        });
      }
      .onChange((index: number) => {
        this.activeTab = index;
      });
    }
    .width('100%')
    .height('100%')
    .padding(10);
  }
}

import { Button, Column, Stack, Canvas, Text, Marquee, FlexAlign, AnimationStatus, Curve, PlayMode } from '@ohos.arkui';
import { CanvasContext } from '@ohos.arkui';

@Entry
@Component
struct ErrorPopupApp {
  @State isPopupVisible: boolean = false;
  @State errorMessage: string = "An error occurred. Please try again later.";

  private canvasContext: CanvasContext | null = null;

  aboutToDisappear() {
    this.cleanup();
  }

  cleanup() {
    this.canvasContext = null;
  }

  drawErrorIndicator(canvasContext: CanvasContext) {
    canvasContext.fillStyle = '#FF0000';
    canvasContext.fillRect(10, 10, 50, 50);
    canvasContext.fill();
  }

  build() {
    Column() {
      Button('Trigger Error')
        .onClick(() => {
          this.isPopupVisible = true;
        })
        .margin(20)
        .width('80%')
        .height(50)
        .backgroundColor('#0000FF')
        .fontColor('#FFFFFF');

      if (this.isPopupVisible) {
        Stack() {
          Column() {
            Canvas()
              .width(70)
              .height(70)
              .backgroundColor('#FFFFFF')
              .onReady((ctx: CanvasContext) => {
                this.canvasContext = ctx;
                this.drawErrorIndicator(ctx);
              });

            Marquee({
              text: this.errorMessage,
              fontColor: '#FF0000',
              fontSize: 16
            })
            .margin({ top: 10, bottom: 10 })
            .loop(-1)
            .allowScale(true);

            Button('Close')
              .onClick(() => {
                this.isPopupVisible = false;
                this.cleanup();
              })
              .margin(10)
              .width('80%')
              .height(40)
              .backgroundColor('#FF0000')
              .fontColor('#FFFFFF');
          }
          .width('80%')
          .padding(20)
          .backgroundColor('#FFFFFF')
          .borderRadius(10)
          .shadow({ radius: 10, color: '#808080' });
        }
        .width('100%')
        .height('100%')
        .backgroundColor(0x0000007F)
        .onClick(() => {
          this.isPopupVisible = false;
          this.cleanup();
        });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor('#FFFFFF');
  }
}

@Entry
