            .onActionUpdate((event: RotationGestureEvent) => {
              this.angle = event.angle
              this.progress = Math.min(Math.max(0, Math.round(this.angle / 3.6)), 100)
              console.info(`Progress updated: ${this.progress}%`)
            })
            .onActionEnd(() => {
              console.info('Rotation ended')
            })
        )

      Stepper({
        index: this.habitCount
      })
        .width('80%')
        .margin({ top: 20 })
        .onChange((value: number) => {
          this.habitCount = Math.min(10, Math.max(0, value))
          console.info(`Habit count updated: ${this.habitCount}`)
        })

      Text(`Habits Completed: ${this.habitCount}`)
        .fontSize(18)
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

