import http from '@ohos.net.http';
import { LineChart, Series } from '@ohos.arkui.advanced';

class LineSeriesItem {
  x: string = '';
  y: number = 0;
}

class ChartSeries {
  lineSeries: Array<LineSeriesItem> = [];
}

class AxisLabel {
  formatter: (value: string) => string = (value) => value;
}

class ChartAxis {
  axisLabel: AxisLabel = new AxisLabel();
}

interface WeatherDataPoint {
  timestamp: string;
  temperature: number;
}

interface WeatherApiResponse {
  data: Array<WeatherDataPoint>;
}

interface ChartConfig {
  series: ChartSeries;
  xAxis: ChartAxis;
  yAxis: ChartAxis;
}

@Entry
@Component
struct WeatherForecastApp {
  @State weatherData: Array<WeatherDataPoint> = [];
  @State isLoading: boolean = true;
  @State errorMessage: string = '';
  @State temperatureUnit: string = '\u00b0C';
  @State chartData: ChartConfig = {
    series: new ChartSeries(),
    xAxis: new ChartAxis(),
    yAxis: new ChartAxis()
  };

  private apiUrl: string = 'https://api.example.com/weather';
  private httpRequest = http.createHttp();

  private prepareChartData(): ChartConfig {
    let series = new ChartSeries();
    series.lineSeries = this.weatherData.map(item => {
      const point = new LineSeriesItem();
      point.x = item.timestamp;
      point.y = item.temperature;
      return point;
    });

    let xAxis = new ChartAxis();
    xAxis.axisLabel.formatter = (value: string) => value;

    let yAxis = new ChartAxis();
    yAxis.axisLabel.formatter = (value: string) => `${parseFloat(value)}${this.temperatureUnit}`;

    return {series, xAxis, yAxis};
  }

  fetchWeatherData(): void {
    this.isLoading = true;
    this.errorMessage = '';
    this.httpRequest.request(this.apiUrl, { method: http.RequestMethod.GET })
      .then((response: http.HttpResponse) => {
        if (response.responseCode === http.ResponseCode.OK) {
          const data: WeatherApiResponse = JSON.parse(response.result.toString());
          this.weatherData = data.data;
          this.chartData = this.prepareChartData();
          this.isLoading = false;
        } else {
          this.errorMessage = 'Failed to fetch weather data. Please try again.';
          this.isLoading = false;
        }
      })
      .catch((error: Error) => {
        this.errorMessage = 'An error occurred. Please check your connection.';
        this.isLoading = false;
        console.error('Error:', error);
      });
  }

  toggleTemperatureUnit(): void {
    this.temperatureUnit = this.temperatureUnit === '\u00b0C' ? '\u00b0F' : '\u00b0C';
    this.chartData = this.prepareChartData();
  }

  build() {
    Column() {
      if (this.isLoading) {
        Progress({ value: 0 })
          .width(100)
          .height(100)
          .margin(20);
        Text('Loading weather data...')
          .fontSize(20)
          .margin(10);
      } else if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(20)
          .fontColor(Color.Red)
          .margin(20);
      } else {
        Row() {
          Text('Temperature Forecast')
            .fontSize(24)
            .fontWeight(FontWeight.Bold);
          Button(this.temperatureUnit)
            .onClick(() => this.toggleTemperatureUnit())
            .margin({ left: 10 });
        }
        .margin({ bottom: 20 });

        LineChart() {
          ForEach(this.chartData.series.lineSeries, (item: LineSeriesItem) => {
            Series(item)
              .xAxis(this.chartData.xAxis)
              .yAxis(this.chartData.yAxis)
          })
          .width('100%')
          .height(300)
        }

        Button('Refresh Data')
          .onClick(() => this.fetchWeatherData())
          .margin(20);
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .onAppear(() => {
      this.fetchWeatherData();
    });
  }
}

