@Entry
@Component
struct InventoryManagementApp {
  @State currentStep: number = 0;
  @State isLandscape: boolean = false;
  private avPlayer: media.AVPlayer | null = null;
  private videoPath: string = 'inventory_video_placeholder';

  async aboutToAppear() {
    await this.setupVideoPlayer();
    this.setupOrientationListener();
  }

  async setupVideoPlayer() {
    try {
      this.avPlayer = await media.createAVPlayer();
      if (this.avPlayer) {
        this.avPlayer.url = this.videoPath;
        this.avPlayer.on('error', (error: BusinessError) => {
          console.error('Video playback error:', error);
        });
      }
    } catch (error) {
      console.error('Failed to create AVPlayer:', error);
    }
  }

  setupOrientationListener() {
    window.getLastWindow(getContext(this)).then((win: window.Window) => {
      const properties = win.getWindowProperties();
      this.isLandscape = properties.windowRect.width > properties.windowRect.height;

      win.on('windowSizeChange', (data: window.Size) => {
        this.isLandscape = data.width > data.height;
      });
    });
  }

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.Start }) {
        TabContent() {
          this.ViewStep();
        }
        .tabBar('View')

        TabContent() {
          this.EditStep();
        }
        .tabBar('Edit')

        TabContent() {
          this.ConfirmStep();
        }
        .tabBar('Confirm')
      }
      .onChange((index: number) => {
        this.currentStep = index;
      })

      if (this.isLandscape) {
        this.VideoPlaceholder();
      }
    }
    .width('100%')
    .height('100%')
  }

  @Builder
  ViewStep() {
    Column() {
      Text('View Inventory')
        .fontSize(24)
        .margin(10)
      List() {
        ListItem() {
          Text('Item 1')
        }
        ListItem() {
          Text('Item 2')
        }
      }
      .layoutWeight(1)
    }
  }

  @Builder
  EditStep() {
    Column() {
      Text('Edit Inventory')
        .fontSize(24)
        .margin(10)
      Button('Save Changes')
        .onClick(() => {
          router.pushUrl({ url: 'pages/confirm' });
        })
    }
  }

  @Builder
  ConfirmStep() {
    Column() {
      Text('Confirm Changes')
        .fontSize(24)
        .margin(10)
      Button('Submit')
        .onClick(() => {
          console.log('Inventory updated');
        })
    }
  }

  @Builder
  VideoPlaceholder() {
    XComponent({
      id: 'video_component',
      type: 'surface',
      libraryname: 'videoplayer'
    })
    .width('100%')
    .height('50%')
    .aspectRatio(16 / 9)
  }
}

import http from '@ohos.net.http';

interface MainData {
  temp: number;
}

interface WeatherItem {
  main: string;
  description: string;
}

interface WeatherData {
  main: MainData;
  weather: WeatherItem[];
  name: string;
}

@Entry
@Component
struct WeatherApp {
  @State temperature: string = '';
  @State condition: string = '';
  @State location: string = '';
  @State isLoading: boolean = true;
  @State weatherIcon: Resource = $r('app.media.icon');
  @State themeColor: string = '#4CAF50';
  @State isABTesting: boolean = false;

  private apiKey: string = 'YOUR_API_KEY';
  private apiUrl: string = `https://api.openweathermap.org/data/2.5/weather?q=London&appid=${this.apiKey}&units=metric`;

  private httpRequest = http.createHttp();

  fetchWeatherData(): void {
    this.isLoading = true;
    this.httpRequest.request(this.apiUrl, { method: http.RequestMethod.GET })
      .then((response: http.HttpResponse) => {
        if (response.responseCode === http.ResponseCode.OK) {
          const data: WeatherData = JSON.parse(response.result.toString());
          this.temperature = `${Math.round(data.main.temp)}\u00b0C`;
          this.condition = data.weather[0].main;
          this.location = data.name;
          this.updateWeatherIcon(data.weather[0].main);
        }
        this.isLoading = false;
      })
      .catch(() => {
        this.isLoading = false;
      });
  }

  updateWeatherIcon(condition: string): void {
    this.weatherIcon = $r('app.media.icon');
  }

  toggleABTesting(): void {
    this.isABTesting = !this.isABTesting;
  }

  build() {
    Column() {
      if (this.isLoading) {
        Text('Loading weather data...')
          .fontSize(20)
          .margin(20);
      } else {
        Text(this.location)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 });

        Image(this.weatherIcon)
          .width(100)
          .height(100)
          .margin({ bottom: 20 });

        Text(this.temperature)
          .fontSize(32)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 10 });

        Text(this.condition)
          .fontSize(20)
          .margin({ bottom: 20 });

        Button('Refresh')
          .onClick(() => this.fetchWeatherData())
          .margin({ top: 20 });

        Button(this.isABTesting ? 'Disable A/B Testing' : 'Enable A/B Testing')
          .onClick(() => this.toggleABTesting())
          .margin({ top: 10 });

        Text('Theme Color:')
          .fontSize(16)
          .margin({ top: 20 });

        TextInput({ placeholder: 'Enter hex color (e.g., #4CAF50)' })
          .onChange((value: string) => {
            this.themeColor = value;
          })
          .margin({ top: 5 });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(this.themeColor)
    .onAppear(() => {
      this.fetchWeatherData();
    });
  }
}

import { Column, Row, Grid, GridItem, Image, FlexAlign } from '@ohos.arkui.component';
import { Chip, ChipType } from '@ohos.arkui.component';
import { animator, curves } from '@ohos.animation';

const animateTo: animator.AnimateToFunction = animator.animateTo;

interface ImageState {
  scale: number;
  opacity: number;
}

@Entry
@Component
struct ABTestingApp {
  @State selectedVariation: number = 0;
  @State imageStates: ImageState[] = [
    {scale: 1, opacity: 1},
    {scale: 1, opacity: 1},
    {scale: 1, opacity: 1}
  ];

  build() {
    Column() {
      Grid() {
        ForEach([0, 1, 2], (index: number) => {
          GridItem() {
            Image($r('app.media.placeholder'))
              .width('100%')
              .height('100%')
              .scale({ x: this.imageStates[index].scale, y: this.imageStates[index].scale })
              .opacity(this.imageStates[index].opacity)
              .onClick(() => {
                animateTo({
                  duration: 300,
                  curve: curves.easeInOut
                }, () => {
                  this.imageStates[index].scale = 0.9;
                  this.imageStates[index].opacity = 0.8;
                });
                setTimeout(() => {
                  animateTo({
                    duration: 300,
                    curve: curves.easeInOut
                  }, () => {
                    this.imageStates[index].scale = 1;
                    this.imageStates[index].opacity = 1;
                  });
                }, 300);
              });
          }
          .width('33%')
          .height('60%')
          .margin(10);
        });
      }
      .columnsGap(10)
      .rowsGap(10)
      .height('60%');

      Row() {
        ForEach([0, 1, 2], (index: number) => {
          Chip({
            type: ChipType.Filter,
            label: `Variation ${index + 1}`,
            selected: this.selectedVariation === index
          })
          .onClick(() => {
            this.selectedVariation = index;
          });
        });
      }
      .justifyContent(FlexAlign.Center)
      .width('100%')
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

