  build() {
    Column() {
      Text(`Habit Tracker - ${this.getMonthName()} ${this.currentYear}`)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row() {
        Button('Previous')
          .onClick(() => this.navigateMonth(-1));
        Button('Next')
          .onClick(() => this.navigateMonth(1));
      }
      .justifyContent(FlexAlign.SpaceBetween)
      .width('100%')
      .margin({ bottom: 20 });

      Grid() {
        ForEach(['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], (day: string) => {
          GridItem() {
            Text(day)
              .fontSize(16)
              .fontWeight(FontWeight.Bold);
          }
        });

        ForEach(this.getDaysInMonth(), (day: number) => {
          GridItem() {
            Column() {
              Text(day.toString())
                .fontSize(14);
              ForEach(this.habits, (habit: Habit) => {
                Toggle({ type: ToggleType.Switch })
                  .onChange((isOn: boolean) => {
                    habit.completed[day - 1] = isOn;
                  });
              });
            }
          }
        });
      }
      .columnsTemplate('1fr 1fr 1fr 1fr 1fr 1fr 1fr')
      .rowsTemplate('auto auto auto auto auto auto auto')
      .width('100%')
      .height('70%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }

  private getMonthName(): string {
    const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
    return months[this.currentMonth];
  }

  private getDaysInMonth(): number[] {
    const daysInMonth = new Date(this.currentYear, this.currentMonth + 1, 0).getDate();
    return Array.from<number, number>({ length: daysInMonth }, (_, i) => i + 1);
  }

  private navigateMonth(direction: number): void {
    this.currentMonth += direction;
    if (this.currentMonth < 0) {
      this.currentMonth = 11;
      this.currentYear--;
    } else if (this.currentMonth > 11) {
      this.currentMonth = 0;
      this.currentYear++;
    }
  }
}

