@Entry
@Component
struct GestureTooltipProgress {
  @State private progress: number = 0;
  @State private showToast: boolean = false;
  @State private toastMessage: string = "";

  build() {
    Column({ space: 10 }) {
      Text("Gesture Tooltip Progress Tracking")
        .fontSize(20)
        .fontColor(Color.Black)
        .margin({ bottom: 20 });

      Flex({ direction: FlexDirection.Row, wrap: FlexWrap.Wrap }) {
        ForEach(Array.from({ length: 10 }, (_: undefined, i: number) => i + 1), (item: number) => {
          Column() {
            Button(`Step ${item}`)
              .width(100)
              .height(50)
              .backgroundColor(this.progress >= item ? Color.Green : Color.Gray)
              .gesture(
                TapGesture()
                  .onAction(() => {
                    this.progress = item;
                    this.toastMessage = `Progress updated to step ${item}`;
                    this.showToast = true;
                  })
              );
          }
          .margin(5);
        })
      }
      .width('100%');

      if (this.showToast) {
        Text(this.toastMessage)
          .fontSize(16)
          .fontColor(Color.Black)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(Color.White);
  }
}

import { SegmentedControl, SegmentedControlItem, List, ListItem, Checkbox, Tag, Text, Row, Column, Button } from '@ohos.arkui.advanced';
import wantAgent from '@ohos.app.ability.wantAgent';
import common from '@ohos.app.ability.common';

interface Task {
  id: number;
  title: string;
  completed: boolean;
  category: 'Work' | 'Personal';
}

@Entry
@Component
struct TaskManager {
  @State tasks: Task[] = [
    { id: 1, title: 'Complete project', completed: false, category: 'Work' },
    { id: 2, title: 'Buy groceries', completed: true, category: 'Personal' },
    { id: 3, title: 'Call mom', completed: false, category: 'Personal' },
    { id: 4, title: 'Meeting with team', completed: false, category: 'Work' }
  ];

  @State selectedCategory: string = 'All';

  build() {
    Column() {
      SegmentedControl() {
        SegmentedControlItem('All')
        SegmentedControlItem('Work')
        SegmentedControlItem('Personal')
      }
      .selected(this.selectedCategory === 'All' ? 0 : this.selectedCategory === 'Work' ? 1 : 2)
      .onChange((index: number) => {
        this.selectedCategory = index === 0 ? 'All' : index === 1 ? 'Work' : 'Personal';
      })
      .margin(10);

      List({ space: 10 }) {
        ForEach(this.tasks.filter(task => this.selectedCategory === 'All' || task.category === this.selectedCategory), (task: Task) => {
          ListItem() {
            Row() {
              Checkbox({ name: task.id.toString(), group: 'tasks' })
                .select(task.completed)
                .onChange((checked: boolean) => {
                  task.completed = checked;
                })
                .margin(5);

              Text(task.title)
                .fontSize(16)
                .decoration({ type: task.completed ? TextDecorationType.LineThrough : TextDecorationType.None })
                .margin(5);

              Tag() {
                Text(task.category)
              }
              .type(task.category === 'Work' ? TagType.Primary : TagType.Success)
              .margin(5);
            }
            .width('100%')
            .justifyContent(FlexAlign.SpaceBetween)
            .padding(10)
            .backgroundColor('#FFFFFF')
            .borderRadius(5);
          }
        });
      }
      .width('100%')
      .layoutWeight(1);

      Button('Share Tasks')
        .onClick(() => {
          const visibleTasks = this.tasks.filter(task => this.selectedCategory === 'All' || task.category === this.selectedCategory);
          const taskTitles = visibleTasks.map(task => task.title).join('\n');
          let wantAgentInfo = {
            wants: [
              {
                bundleName: '',
                abilityName: '',
                action: 'ohos.want.action.send',
                entities: ['entity.system.sharing'],
                uri: '',
                type: 'text/plain'
              }
            ],
            operationType: wantAgent.OperationType.SEND_COMMON_EVENT,
            requestCode: 0,
            wantAgentFlags: [wantAgent.WantAgentFlags.CONSTANT_FLAG]
          };
          try {
            wantAgent.getWantAgent(wantAgentInfo).then((agent) => {
              wantAgent.trigger(agent);
            });
          } catch (err) {
            console.error('Share failed:', err);
          }
        })
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .padding(10)
    .backgroundColor('#F5F5F5');
  }
}

import { Column, Text, Image, Segmented, SegmentedItem, ForEach } from '@ohos.arkui.advanced';
import { RotateGesture, RotateGestureEvent, FlexAlign } from '@ohos.arkui.advanced';
import { State } from '@ohos.arkui.advanced';

interface ThemeOption {
  value: string;
  icon?: Resource;
}

@Entry
@Component
struct ThemeSwitcher {
  @State currentTheme: string = 'Light';
  @State rotationAngle: number = 0;
  @State gestureState: string = 'None';
  private themes: ThemeOption[] = [
    {value: "Light", icon: $r('app.media.icon_light')},
    {value: "Dark", icon: $r('app.media.icon_dark')},
    {value: "System"}
  ];

  build() {
    Column({ space: 20 }) {
      Text(`Current Theme: ${this.currentTheme}`)
        .fontSize(20)
        .fontColor(this.currentTheme === 'Light' ? 0x000000 : 0xFFFFFF)

      Text(`Rotation Angle: ${Math.round(this.rotationAngle)}\u00b0`)
        .fontSize(20)
        .fontColor(this.currentTheme === 'Light' ? 0x000000 : 0xFFFFFF)

      Text(`Gesture State: ${this.gestureState}`)
        .fontSize(20)
        .fontColor(this.currentTheme === 'Light' ? 0x000000 : 0xFFFFFF)

      Segmented({ selected: this.currentTheme })
        .onChange((index: number) => {
          this.currentTheme = this.themes[index].value;
        }) {
        ForEach(this.themes, (item: ThemeOption, index: number) => {
          SegmentedItem() {
            if (item.icon) {
              Image(item.icon)
            }
            Text(item.value)
          }
        })
      }

      Image($r('app.media.icon_theme'))
        .width(100)
        .height(100)
        .rotate({ angle: this.rotationAngle })
        .gesture(
          RotateGesture()
            .onActionStart(() => {
              this.gestureState = 'Start';
            })
            .onActionUpdate((event: RotateGestureEvent) => {
              this.rotationAngle = event.angle;
              this.gestureState = 'Update';

              if (Math.round(this.rotationAngle) % 120 === 0) {
                const themeIndex = Math.floor(this.rotationAngle / 120) % this.themes.length;
                this.currentTheme = this.themes[themeIndex].value;
              }
            })
            .onActionEnd(() => {
              this.gestureState = 'End';
            })
            .onActionCancel(() => {
              this.gestureState = 'Cancel';
            })
        )
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor(this.currentTheme === 'Light' ? 0xFFFFFF : 0x000000)
  }
}

