@Entry
@Component
struct NewsReaderApp {
  @State articles: Article[] = [
    new Article('Breaking News 1', $r('app.media.ic_public_picture'), 'Content of breaking news 1.'),
    new Article('Breaking News 2', $r('app.media.ic_public_picture'), 'Content of breaking news 2.'),
    new Article('Breaking News 3', $r('app.media.ic_public_picture'), 'Content of breaking news 3.')
  ];
  @State expandedArticleId: string | null = null;
  @State isAuthenticated: boolean = false;
  dialogController: CustomDialogController = new CustomDialogController({
    builder: AuthDialog({
      onAuthenticate: this.handleAuthentication.bind(this)
    })
  });

  private handleAuthentication(): void {
    const authInstance = userIAM.getAuthInstance({
      challenge: new Uint8Array([0]),
      authType: [userIAM.UserAuthType.FACE],
      authTrustLevel: userIAM.AuthTrustLevel.ATL1
    });
    authInstance.execute().then(() => {
      this.isAuthenticated = true;
    }).catch(() => {
      promptAction.showToast({ message: 'Authentication failed' });
    });
  }

  build() {
    Column() {
      Scroll() {
        Column() {
          ForEach(this.articles, (article: Article) => {
            Column() {
              Row() {
                Image(article.image)
                  .width(80)
                  .height(80)
                  .margin({ right: 12 });
                Text(article.title)
                  .fontSize(18)
                  .fontWeight(FontWeight.Bold)
                  .margin({ bottom: 8 });
              }
              .width('100%')
              .padding(12)
              .onClick(() => {
                if (this.isAuthenticated) {
                  this.expandedArticleId = this.expandedArticleId === article.id ? null : article.id;
                } else {
                  this.dialogController.open();
                }
              });

              if (this.expandedArticleId === article.id) {
                Text(article.content)
                  .fontSize(14)
                  .margin({ top: 8, bottom: 12, left: 12, right: 12 });
              }
            }
            .width('100%')
            .borderRadius(8)
            .margin({ bottom: 12 })
            .backgroundColor(Color.White)
            .shadow({
              radius: 4,
              color: '#CCCCCC',
              offsetX: 0,
              offsetY: 2
            });
          });
        }
        .width('100%')
        .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.LightGrey);
  }
}

@Entry
@Component
struct TimelineApp {
  @State message: string = ''
  @State shift: number = 3
  @State encryptedMessage: string = ''
  @State encryptedData: number[] = []

  encryptMessage(): void {
    let result = ''
    for (let i = 0; i < this.message.length; i++) {
      let char = this.message[i]
      if (char.match(/[a-z]/i)) {
        const code = this.message.charCodeAt(i)
        if (code >= 65 && code <= 90) {
          char = String.fromCharCode(((code - 65 + this.shift) % 26) + 65)
        } else if (code >= 97 && code <= 122) {
          char = String.fromCharCode(((code - 97 + this.shift) % 26) + 97)
        }
      }
      result += char
    }
    this.encryptedMessage = result
    this.updateEncryptedData()
  }

  updateEncryptedData(): void {
    this.encryptedData = []
    for (let i = 0; i < this.encryptedMessage.length; i++) {
      this.encryptedData.push(this.encryptedMessage.charCodeAt(i))
    }
  }

  build() {
    Column() {
      Text('Encrypted Data Visualization')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      TextInput({
        placeholder: 'Enter your message',
        text: this.message
      })
      .width('80%')
      .height(50)
      .backgroundColor('#f5f5f5')
      .onChange((value: string) => {
        this.message = value
      })
      .margin({ bottom: 20 })

      Text('Shift Value: ' + this.shift)
        .fontSize(18)
        .margin({ bottom: 10 })

      Slider({ value: this.shift, min: 1, max: 25, step: 1 })
        .onChange((value: number) => {
          this.shift = value
        })
        .margin({ bottom: 20 })

      Button('Encrypt Message')
        .width('60%')
        .height(50)
        .fontSize(20)
        .onClick(() => this.encryptMessage())
        .margin({ bottom: 20 })

      if (this.encryptedMessage) {
        Text('Encrypted Message: ' + this.encryptedMessage)
          .fontSize(20)
          .fontColor('#4CAF50')
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })

        // Placeholder for Chart component
        // Replace with actual Chart implementation once available
        Text('Chart visualization will be displayed here')
          .fontSize(16)
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

@Entry
@Component
struct CropSelectionApp {
  @State selectedCrop: string = 'square';
  @State animate: boolean = false;

  private cropOptions: string[] = ['square', 'circle', 'freeform'];

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width('100%')
        .height(300)
        .objectFit(ImageFit.Contain)
        .margin({ bottom: 20 })

      Column() {
        ForEach(this.cropOptions, (option: string) => {
          Row() {
            Image($r(`app.media.crop_${option}`))
              .width(30)
              .height(30)
              .margin({ right: 10 })
            Text(option.toUpperCase())
              .fontSize(16)
              .fontColor(this.selectedCrop === option ? Color.Blue : Color.Black)
          }
          .width('100%')
          .height(50)
          .justifyContent(FlexAlign.Start)
          .alignItems(VerticalAlign.Center)
          .padding(10)
          .borderRadius(5)
          .backgroundColor(this.selectedCrop === option ? Color.Gray : Color.White)
          .onClick(() => {
            this.animate = true;
            this.selectedCrop = option;
            setTimeout(() => {
              this.animate = false;
            }, 300);
          })
          .animation({
            duration: 300,
            curve: Curve.EaseInOut,
            iterations: 1,
            playMode: PlayMode.Normal
          })
        })
      }
      .width('100%')
      .padding(10)
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White)
  }
}

