@Entry
@Component
struct SearchApp {
  @State private searchText: string = '';
  @State private counterValue: number = 0;
  @State private stepperValue: number = 0;

  build() {
    Column() {
      // SearchBar
      Row() {
        TextInput({ placeholder: 'Search...', text: this.searchText })
          .onChange((value: string) => {
            this.searchText = value;
          })
          .width('80%')
          .height(40)
          .margin({ right: 10 });

        Button('Search')
          .onClick(() => {
            console.log(`Searching for: ${this.searchText}`);
          })
          .width('20%')
          .height(40);
      }
      .width('100%')
      .margin({ top: 20, bottom: 20 });

      // Counter
      Row() {
        Button('-')
          .onClick(() => {
            if (this.counterValue > 0) {
              this.counterValue--;
            }
          })
          .width(40)
          .height(40);

        Text(`${this.counterValue}`)
          .fontSize(20)
          .margin({ left: 20, right: 20 });

        Button('+')
          .onClick(() => {
            this.counterValue++;
          })
          .width(40)
          .height(40);
      }
      .margin({ bottom: 20 });

      // Stepper
      Row() {
        Button('-')
          .onClick(() => {
            if (this.stepperValue > 0) {
              this.stepperValue--;
            }
          })
          .width(40)
          .height(40);

        Text(`${this.stepperValue}`)
          .fontSize(20)
          .margin({ left: 20, right: 20 });

        Button('+')
          .onClick(() => {
            this.stepperValue++;
          })
          .width(40)
          .height(40);
      }
      .margin({ bottom: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

@Entry
@Component
struct QRScannerApp {
  @State scannedData: string = '';
  @State isScanning: boolean = false;

  scanQRCode() {
    this.isScanning = true;
    setTimeout(() => {
      this.scannedData = 'Scanned QR Code Data';
      this.isScanning = false;
    }, 2000);
  }

  clearScan() {
    this.scannedData = '';
  }

  build() {
    Column() {
      Text('QR Code Scanner')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Canvas()
        .width('100%')
        .height('60%')
        .backgroundColor('#f5f5f5')
        .onTouch((event: TouchEvent) => {
          if (event.type === TouchType.Down) {
            this.clearScan();
            this.scanQRCode();
          }
        })

      if (this.isScanning) {
        Text('Scanning...')
          .fontSize(18)
          .margin({ top: 20 });
      }

      if (this.scannedData) {
        Text('Scanned Data:')
          .fontSize(18)
          .margin({ top: 20, bottom: 10 });

        Text(this.scannedData)
          .fontSize(16)
          .padding(10)
          .backgroundColor('#f5f5f5')
          .borderRadius(5);
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

