import prompt from '@ohos.prompt';
import { DatePicker, InputType } from '@ohos.arkui';

@Entry
@Component
struct MealPlannerApp {
  @State username: string = '';
  @State password: string = '';
  @State selectedDate: string = '';
  @State loginSuccess: boolean = false;
  @State errorMessage: string = '';

  private validateInputs(): boolean {
    if (!this.username.trim()) {
      this.errorMessage = 'Username is required';
      return false;
    }
    if (!this.password.trim()) {
      this.errorMessage = 'Password is required';
      return false;
    }
    this.errorMessage = '';
    return true;
  }

  private handleLogin() {
    if (this.validateInputs()) {
      this.loginSuccess = true;
      prompt.showToast({ message: 'Login successful', duration: 2000 });
    } else {
      prompt.showToast({ message: this.errorMessage, duration: 2000 });
    }
  }

  build() {
    Column() {
      Image($r('app.media.ic_public_user'))
        .width(100)
        .height(100)
        .margin({ top: 20, bottom: 20 })

      TextInput({ placeholder: 'Enter username' })
        .onChange((value: string) => {
          this.username = value;
        })
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value;
        })
        .margin({ bottom: 10 })

      DatePicker({ start: new Date('2023-01-01'), end: new Date('2023-12-31') })
        .onDateChange((value: Date) => {
          this.selectedDate = value.getFullYear() + '-' + (value.getMonth() + 1) + '-' + value.getDate();
        })
        .margin({ bottom: 20 })

      Button('Login')
        .onClick(() => {
          this.handleLogin();
        })
        .width('80%')
        .height(50)
        .margin({ bottom: 20 })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontColor(Color.Red)
          .margin({ bottom: 10 })
      }

      if (this.loginSuccess) {
        Text('Welcome, ' + this.username)
          .fontColor(Color.Green)
          .margin({ bottom: 10 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White)
  }
}

import { Swiper, SwiperController } from '@ohos.arkui.component';
import { Button, Text, Image } from '@ohos.arkui.component';
import { Badge } from '@ohos.arkui.component';
import { Color, FontWeight, FlexAlign, TextAlign } from '@ohos.arkui.component';

interface MeditationItem {
  title: string;
}

interface PositionStyle {
  right: number;
  top: number;
}

interface BadgeStyle {
  color: Color;
  backgroundColor: Color;
  position: PositionStyle;
}

@Entry
@Component
struct MeditationSwiper {
  @State currentIndex: number = 0;
  private swiperController: SwiperController = new SwiperController();
  private meditationData: Array<MeditationItem> = [
    { title: "Meditation 1" },
    { title: "Meditation 2" },
    { title: "Meditation 3" },
    { title: "Meditation 4" },
    { title: "Meditation 5" }
  ];

  build() {
    Column({ space: 16 }) {
      Swiper(this.swiperController) {
        ForEach(this.meditationData, (item: MeditationItem, index: number) => {
          Column() {
            Text(item.title)
              .fontSize(24)
              .fontWeight(FontWeight.Bold)
              .textAlign(TextAlign.Center)
              .margin({ top: 20 });
            Image($r('app.media.placeholder'))
              .width('80%')
              .height(200)
              .margin({ top: 10 });
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center);
        })
      }
      .height(300)
      .loop(true)
      .onChange((index: number) => {
        this.currentIndex = index;
      });

      Row({ space: 10 }) {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });
        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });
      }
      .justifyContent(FlexAlign.Center)
      .margin({ top: 20 });

      Badge({
        count: this.currentIndex + 1,
        style: { 
          color: Color.White, 
          backgroundColor: Color.Black,
          position: { right: 0, top: 0 }
        } as BadgeStyle
      })
      .position({ x: '90%', y: '10%' })
      .width(30)
      .height(30);
    }
    .width('100%')
    .padding(16);
  }
}

@Entry
@Component
struct MapApp {
  @State mapImage: Resource = $r('app.media.icon')
  @State statusTags: string[] = ['Online', 'Active', 'Syncing']
  @State dataUpdates: string[] = ['Update 1: Device connected', 'Update 2: Data synced', 'Update 3: System stable']
  @State currentUpdate: string = ''

  aboutToAppear() {
    this.startMarqueeUpdates()
  }

  startMarqueeUpdates() {
    let index = 0
    setInterval(() => {
      this.currentUpdate = this.dataUpdates[index % this.dataUpdates.length]
      index++
    }, 2000)
  }

  build() {
