import { Column, Row, List, Image, Text } from '@ohos.arkui.advanced';
import { Toggle, ToggleType } from '@ohos.arkui.advanced';
import type { Resource } from '@ohos.resourceManager';

interface Comic {
  id: number;
  title: string;
  cover: Resource | string;
}

interface Settings {
  darkMode: boolean;
  autoPlay: boolean;
}

@Entry
@Component
struct ComicReader {
  @State comics: Comic[] = [];
  @State settings: Settings = {
    darkMode: false,
    autoPlay: false,
  };
  @State isLoading: boolean = false;

  aboutToAppear() {
    this.fetchComics();
  }

  fetchComics() {
    this.isLoading = true;
    setTimeout(() => {
      this.comics = [
        { id: 1, title: 'Comic One', cover: $r('app.media.comic1') },
        { id: 2, title: 'Comic Two', cover: $r('app.media.comic2') },
        { id: 3, title: 'Comic Three', cover: $r('app.media.comic3') },
      ];
      this.isLoading = false;
    }, 1000);
  }

  build() {
    Column() {
      Column() {
        Row() {
          Toggle({ type: ToggleType.Switch, isOn: this.settings.darkMode })
            .onChange((isOn: boolean) => {
              this.settings.darkMode = isOn;
            });
          Text('Dark Mode').margin({ left: 10 });
        }.margin({ bottom: 10 });

        Row() {
          Toggle({ type: ToggleType.Switch, isOn: this.settings.autoPlay })
            .onChange((isOn: boolean) => {
              this.settings.autoPlay = isOn;
            });
          Text('Auto Play').margin({ left: 10 });
        }.margin({ bottom: 10 });
      }.padding(20);

      List({ space: 10 }) {
        ForEach(this.comics, (comic: Comic) => {
          ListItem() {
            Row() {
              Image(comic.cover)
                .width(100)
                .height(150);
              Text(comic.title)
                .margin({ left: 10 });
            }.width('100%').padding(10);
          }.onClick(() => {
          });
        });
      }
      .width('100%')
      .height('100%')
      .onScrollIndex((start: number) => {
        if (start === this.comics.length - 1 && !this.isLoading) {
          this.fetchComics();
        }
      });

      if (this.isLoading) {
        Text('Loading...')
          .fontSize(20)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.settings.darkMode ? '#333' : '#fff');
  }
}

