@Entry
@Component
struct CalculatorApp {
  @State searchQuery: string = '';
  @State counter: number = 0;
  @State expression: string = '';
  @State result: string = '';

  private calculateExpression(expr: string): number {
    const tokens = expr.split(/([+\-*/])/).filter(token => token.trim() !== '');
    if (tokens.length !== 3) throw new Error('Invalid expression');

    const num1 = parseFloat(tokens[0]);
    const op = tokens[1];
    const num2 = parseFloat(tokens[2]);

    switch (op) {
      case '+': return num1 + num2;
      case '-': return num1 - num2;
      case '*': return num1 * num2;
      case '/': return num1 / num2;
      default: throw new Error('Invalid operator');
    }
  }

  build() {
    Column() {
      TextInput({ placeholder: 'Search...' })
        .width('80%')
        .height(40)
        .backgroundColor('#FFFFFF')
        .borderRadius(5)
        .padding(5)
        .margin(10)
        .onChange((value: string) => {
          this.searchQuery = value;
        });

      Text('Search Query: ' + this.searchQuery)
        .margin({ bottom: 20 });

      Row() {
        Button('-')
          .onClick(() => {
            this.counter--;
          })
          .margin({ right: 10 });

        Text('' + this.counter)
          .fontSize(24);

        Button('+')
          .onClick(() => {
            this.counter++;
          })
          .margin({ left: 10 });
      }
      .margin({ bottom: 20 });

      TextInput({ placeholder: 'Enter expression (e.g., 2+2)' })
        .width('80%')
        .height(40)
        .backgroundColor('#FFFFFF')
        .borderRadius(5)
        .padding(5)
        .margin(10)
        .onChange((value: string) => {
          this.expression = value;
        });

      Button('Calculate')
        .width('80%')
        .height(40)
        .backgroundColor('#FFFFFF')
        .borderRadius(5)
        .padding(5)
        .margin(10)
        .onClick(() => {
          try {
            let res = this.calculateExpression(this.expression);
            this.result = 'Result: ' + res;
          } catch (error) {
            this.result = 'Error: Invalid expression';
          }
        });

      Text(this.result)
        .fontColor('#00FF00')
        .margin({ top: 10 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#f0f0f0');
  }
}

import promptAction from '@ohos.promptAction';

@Entry
@Component
struct VoiceRecorderApp {
  @State recordings: string[] = [];
  @State isRecording: boolean = false;
  @State showActionSheet: boolean = false;

  build() {
    Column() {
      Button(this.isRecording ? 'Stop Recording' : 'Start Recording')
        .onClick(() => {
          this.isRecording = !this.isRecording;
          if (this.isRecording) {
            this.recordings.push(`Recording ${this.recordings.length + 1}`);
            promptAction.showToast({ message: 'Recording started', duration: 2000 });
          } else {
            promptAction.showToast({ message: 'Recording stopped', duration: 2000 });
          }
        });

      List() {
        ForEach(this.recordings, (item: string) => {
          ListItem() {
            Text(item)
              .onClick(() => {
                promptAction.showActionMenu({
                  title: 'Options',
                  buttons: [
                    { 
                      text: 'Share', 
                      color: '#000000'
                    },
                    { 
                      text: 'Delete', 
                      color: '#FF0000'
                    },
                    { 
                      text: 'Cancel', 
                      color: '#999999'
                    }
                  ]
                }).then((response: promptAction.ActionMenuSuccessResponse) => {
                  if (response.index === 0) {
                    this.shareRecording();
                  } else if (response.index === 1) {
                    this.deleteRecording();
                  }
                });
              });
          }
        }, (item: string) => item)
      }
    }
  }

  shareRecording(): void {
    promptAction.showToast({ message: 'Sharing recording', duration: 2000 });
    this.showActionSheet = false;
  }

  deleteRecording(): void {
    promptAction.showToast({ message: 'Recording deleted', duration: 2000 });
    this.showActionSheet = false;
  }
}

import promptAction from '@ohos.promptAction';
import { Tabs, TabContent, ImageFit, ProgressType } from '@ohos.arkui.component';

interface Restaurant {
  name: string;
  rating: number;
  distance: string;
  image: Resource;
}

@Entry
@Component
struct RestaurantFinder {
  @State activeTab: number = 0;
  @State restaurants: Restaurant[] = [];
  @State isLoading: boolean = false;
  @State hasMore: boolean = true;

  private mockRestaurants: Restaurant[] = [
    { name: 'Restaurant A', rating: 4.5, distance: '0.5 km', image: $r('app.media.icon') },
    { name: 'Restaurant B', rating: 4.0, distance: '1.2 km', image: $r('app.media.icon') },
    { name: 'Restaurant C', rating: 3.8, distance: '0.8 km', image: $r('app.media.icon') },
    { name: 'Restaurant D', rating: 4.2, distance: '1.5 km', image: $r('app.media.icon') },
    { name: 'Restaurant E', rating: 4.7, distance: '2.0 km', image: $r('app.media.icon') },
  ];

  onInit() {
    this.loadRestaurants();
  }

  loadRestaurants(): void {
    if (this.isLoading || !this.hasMore) return;
    this.isLoading = true;

    setTimeout(() => {
      const newRestaurants = [...this.restaurants, ...this.mockRestaurants];
      this.restaurants = newRestaurants;
      this.hasMore = newRestaurants.length < 15;
      this.isLoading = false;
    }, 1000);
  }

  onTabChange(index: number): void {
    this.activeTab = index;
    promptAction.showToast({ message: `Switched to ${['Nearby', 'Popular', 'New'][index]}`, duration: 2000 });
  }

  build() {
    Column() {
      Tabs() {
        TabContent() {
          this.buildRestaurantList();
        }.tabBar('Nearby')

        TabContent() {
          this.buildRestaurantList();
        }.tabBar('Popular')

        TabContent() {
          this.buildRestaurantList();
        }.tabBar('New')
      }
      .onChange((index: number) => this.onTabChange(index))
      .width('100%')
      .height('100%')
    }
  }

  @Builder
  buildRestaurantList() {
    List({ space: 10 }) {
      ForEach(this.restaurants, (restaurant: Restaurant) => {
        ListItem() {
          Row() {
            Image(restaurant.image)
              .width(80)
              .height(80)
              .objectFit(ImageFit.Cover)
              .borderRadius(8)

            Column() {
              Text(restaurant.name)
                .fontSize(18)
                .fontWeight(FontWeight.Bold)
                .margin({ bottom: 4 })

              Row() {
                Text(`Rating: ${restaurant.rating}`)
                  .fontSize(14)
                  .margin({ right: 8 })

                Text(`Distance: ${restaurant.distance}`)
                  .fontSize(14)
              }
            }
            .margin({ left: 12 })
          }
          .padding(12)
          .width('100%')
        }
      })

      if (this.isLoading) {
        ListItem() {
          Progress({ type: ProgressType.Ring, value: 0 })
            .width(40)
            .height(40)
        }
      }
    }
    .onReachEnd(() => this.loadRestaurants())
    .width('100%')
    .height('100%')
  }
}

