import media from '@ohos.multimedia.media';
const VideoController = media.VideoController;
import { Video } from '@ohos.arkui.advanced';
import { Accordion, AccordionItem } from '@ohos.arkui.advanced';
import promptAction from '@ohos.promptAction';

interface PreparedEvent {
  duration: number;
}

interface UpdateEvent {
  time: number;
}

@Entry
@Component
struct VideoPlaybackApp {
  private videoController: VideoController = new VideoController();
  @State isPlaying: boolean = false;
  @State currentTime: number = 0;
  @State duration: number = 0;
  @State isMuted: boolean = false;
  @State breadcrumbs: string[] = ['Home', 'Video', 'Playback'];
  @State selectedQuality: string = 'HD';
  @State selectedSubtitle: string = 'English';
  @State selectedAudioTrack: string = 'Default';

  build() {
    Column() {
      Row({ space: 10 }) {
        ForEach(this.breadcrumbs, (item: string, index: number) => {
          Text(item)
            .fontColor(index === this.breadcrumbs.length - 1 ? '#000000' : '#007AFF')
            .onClick(() => {
              if (index < this.breadcrumbs.length - 1) {
                this.breadcrumbs = this.breadcrumbs.slice(0, index + 1);
              }
            });
          if (index < this.breadcrumbs.length - 1) {
            Text('>').margin({ left: 5, right: 5 });
          }
        });
      }
      .padding(10)
      .width('100%');

      Video({
        src: $rawfile('sample_video.mp4'),
        controller: this.videoController
      })
      .controls(false)
      .autoPlay(false)
      .loop(false)
      .muted(this.isMuted)
      .onPrepared((event: PreparedEvent) => {
        this.duration = event.duration;
      })
      .onUpdate((event: UpdateEvent) => {
        this.currentTime = event.time;
      })
      .onError(() => {
        promptAction.showToast({ message: 'Video playback error.', duration: 2000 });
      })
      .width('100%')
      .height(300);

      Row({ space: 10 }) {
        Button(this.isPlaying ? 'Pause' : 'Play')
          .onClick(() => {
            if (this.isPlaying) {
              this.videoController.pause();
            } else {
              this.videoController.start();
            }
            this.isPlaying = !this.isPlaying;
          });
        Button('Stop')
          .onClick(() => {
            this.videoController.stop();
            this.isPlaying = false;
          });
        Button(this.isMuted ? 'Unmute' : 'Mute')
          .onClick(() => {
            this.isMuted = !this.isMuted;
          });
      }
      .margin({ top: 20 });

      Row({ space: 10 }) {
        Text(`Time: ${this.currentTime.toFixed(2)}`);
        Text('/');
        Text(`Duration: ${this.duration.toFixed(2)}`);
      }
      .margin({ top: 10 });

      Accordion()
        .margin({ top: 20 }) {
        AccordionItem({ title: 'Quality' }) {
          Column() {
            ForEach(['HD', 'SD', 'Low'], (quality: string) => {
              Row() {
                Text(quality)
                  .fontColor(this.selectedQuality === quality ? '#007AFF' : '#000000')
                  .onClick(() => {
                    this.selectedQuality = quality;
