import { Button, Text, Column, Row, Popup } from '@ohos.arkui.advanced';
import { FlexAlign, TextAlign } from '@ohos.arkui.ability';

@Entry
@Component
struct VoiceRecorderApp {
  @State isRecording: boolean = false;
  @State volumeLevel: number = 50;
  @State showSettings: boolean = false;

  toggleRecording(): void {
    this.isRecording = !this.isRecording;
  }

  increaseVolume(): void {
    if (this.volumeLevel < 100) {
      this.volumeLevel += 5;
    }
  }

  decreaseVolume(): void {
    if (this.volumeLevel > 0) {
      this.volumeLevel -= 5;
    }
  }

  toggleSettings(): void {
    this.showSettings = !this.showSettings;
  }

  build() {
    Column({ space: 20 }) {
      Button(this.isRecording ? 'Stop Recording' : 'Start Recording')
        .onClick(() => this.toggleRecording())
        .width(200)
        .height(50)
        .margin({ bottom: 20 });

      Column()
        .width('100%')
        .height(200)
        .backgroundColor('#CCCCCC')
        .margin({ bottom: 20 });

      Row({ space: 10 }) {
        Button('-')
          .onClick(() => this.decreaseVolume())
          .width(50)
          .height(50);

        Text(`Volume: ${this.volumeLevel}`)
          .fontSize(18)
          .width(100)
          .textAlign(TextAlign.Center);

        Button('+')
          .onClick(() => this.increaseVolume())
          .width(50)
          .height(50);
      }
      .justifyContent(FlexAlign.Center)
      .margin({ bottom: 20 });

      Button('Settings')
        .onClick(() => this.toggleSettings())
        .width(150)
        .height(50);

      Popup({ show: this.showSettings }) {
        Column({ space: 10 }) {
          Text('Settings')
            .fontSize(20)
            .margin({ bottom: 10 });

          Button('Close')
            .onClick(() => {
              this.toggleSettings();
            })
            .width(100)
            .height(40);
        }
        .width('80%')
        .height('40%')
        .backgroundColor('#FFFFFF')
        .borderRadius(10)
        .padding(20)
        .justifyContent(FlexAlign.Center);
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center);
  }
}

