interface EventType {
  name: string;
  selected: boolean;
}

interface StatData {
  type: string;
  value: number;
}

@Entry
@Component
struct EventPlannerStats {
  private eventTypes: Array<EventType> = [
    { name: 'Corporate', selected: false },
    { name: 'Wedding', selected: false },
    { name: 'Birthday', selected: false },
    { name: 'Conference', selected: false }
  ];

  private statsData: Array<StatData> = [
    { type: 'Corporate', value: 45 },
    { type: 'Wedding', value: 30 },
    { type: 'Birthday', value: 20 },
    { type: 'Conference', value: 15 }
  ];

  private context: CanvasRenderingContext2D = {} as CanvasRenderingContext2D;

  build() {
    Column() {
      Text('Event Planner Statistics')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Column() {
        ForEach(this.eventTypes, (event: EventType, index: number) => {
          Row() {
            Checkbox()
              .select(event.selected)
              .onChange((selected: boolean) => {
                this.eventTypes[index].selected = selected;
                this.drawChart();
              });
            Text(event.name)
              .fontSize(16)
              .margin({ left: 10 });
          }
          .margin({ bottom: 10 });
        });
      }
      .width('100%')
      .padding(10);

      Canvas(this.context)
        .width('100%')
        .height(300)
        .backgroundColor('#FFFFFF')
        .onReady(() => {
          this.drawChart();
        });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5');
  }

  private drawChart(): void {
    const ctx = this.context;
    const canvasWidth = 300;
    const canvasHeight = 300;
    const margin = 20;
    const chartWidth = canvasWidth - 2 * margin;
    const chartHeight = canvasHeight - 2 * margin;
    const barWidth = chartWidth / this.statsData.length - 10;

    ctx.clearRect(0, 0, canvasWidth, canvasHeight);

    ctx.beginPath();
    ctx.moveTo(margin, margin);
    ctx.lineTo(margin, canvasHeight - margin);
    ctx.lineTo(canvasWidth - margin, canvasHeight - margin);
    ctx.strokeStyle = '#000000';
    ctx.stroke();

    ctx.font = '12px Arial';
    ctx.fillStyle = '#000000';
    this.statsData.forEach((stat: StatData, index: number) => {
      const x = margin + (index * (barWidth + 10)) + barWidth / 2;
      ctx.fillText(stat.type, x, canvasHeight - margin + 15);
    });

    this.statsData.forEach((stat: StatData, index: number) => {
      const barHeight = (stat.value / 50) * chartHeight;
      const x = margin + (index * (barWidth + 10));
      const y = canvasHeight - margin - barHeight;

      ctx.fillStyle = this.eventTypes[index].selected ? '#FF6347' : '#4682B4';
      ctx.fillRect(x, y, barWidth, barHeight);
    });
  }
}

