@Entry
@Component
struct StopwatchApp {
  @State elapsedTime: number = 0
  @State isRunning: boolean = false
  @State searchQuery: string = ''
  @State color: string = '#007AFF'
  @State showFilter: boolean = false
  private timerId: number = -1

  build() {
    Column() {
      // Header with search and filter toggle
      Row() {
        TextInput({ placeholder: 'Search' })
          .width('70%')
          .onChange((value: string) => {
            this.searchQuery = value
          })
        Button(this.showFilter ? 'Hide Filter' : 'Show Filter')
          .onClick(() => {
            this.showFilter = !this.showFilter
          })
          .width('30%')
      }
      .margin(10)

      // Filter options (Toggle components)
      if (this.showFilter) {
        Column() {
          Text('Filter Options')
            .fontSize(16)
            .margin({ bottom: 10 })
          Row() {
            Text('Option 1')
            Toggle({ type: ToggleType.Checkbox })
              .onChange((isChecked: boolean) => {
                // Handle filter logic
              })
          }
          .margin({ bottom: 5 })
          Row() {
            Text('Option 2')
            Toggle({ type: ToggleType.Checkbox })
              .onChange((isChecked: boolean) => {
                // Handle filter logic
              })
          }
          .margin({ bottom: 5 })
        }
        .padding(10)
        .borderRadius(8)
        .backgroundColor('#F0F0F0')
        .margin({ bottom: 10 })
      }

      // Stopwatch display
      Text(this.formatTime(this.elapsedTime))
        .fontSize(40)
        .fontColor(this.color)
        .margin(20)

      // Stopwatch controls
      Row() {
        Button(this.isRunning ? 'Stop' : 'Start')
          .onClick(() => {
            if (this.isRunning) {
              clearInterval(this.timerId)
            } else {
              this.timerId = setInterval(() => {
                this.elapsedTime += 1
              }, 10)
            }
            this.isRunning = !this.isRunning
          })
          .margin(10)
        Button('Reset')
          .onClick(() => {
            clearInterval(this.timerId)
            this.elapsedTime = 0
            this.isRunning = false
          })
          .margin(10)
      }

      // Color picker for customization
      Row() {
        Text('Pick a color:')
          .margin({ right: 10 })
        // Custom ColorPicker implementation
        Button('Change Color')
          .onClick(() => {
            // Simulate color picker dialog
            this.color = '#4CAF50' // Example color change
          })
      }
      .margin(20)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }

  private formatTime(time: number): string {
    const minutes = Math.floor(time / 6000)
    const seconds = Math.floor((time % 6000) / 100)
    const centiseconds = time % 100
    return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}.${centiseconds.toString().padStart(2, '0')}`
  }
}

