struct TranslationForm {
  @State sourceText: string = '';
  @State targetText: string = '';
  @State validationMessage: string = '';
  @State isValidationError: boolean = false;

  validateForm(): boolean {
    if (!this.sourceText || !this.targetText) {
      this.validationMessage = 'Please fill in both fields';
      this.isValidationError = true;
      return false;
    }
    if (this.sourceText.length > 500) {
      this.validationMessage = 'Source text too long (max 500 characters)';
      this.isValidationError = true;
      return false;
    }
    this.validationMessage = 'Translation submitted successfully';
    this.isValidationError = false;
    return true;
  }

  build() {
    Column() {
      TextInput({ placeholder: 'Source Text' })
        .width('90%')
        .height(60)
        .margin(10)
        .onChange((value: string) => {
          this.sourceText = value;
