        .height(60)
        .margin(10)
        .onChange((value: string) => {
          this.targetText = value;
        });

      Button('Translate')
        .width('90%')
        .height(60)
        .margin(10)
        .onClick(() => {
          if (this.validateForm()) {
            // Handle successful translation
          }
        });

      if (this.validationMessage) {
        Text(this.validationMessage)
          .fontSize(14)
