import promptAction from '@ohos.promptAction';
import { ActionSheet, ActionSheetItem } from '@ohos.arkui.component';
import { Gesture, LongPressGesture } from '@ohos.arkui.component';

@Entry
@Component
struct RatingSystem {
  @State private rating: number = 0;
  @State private isRatingActive: boolean = false;
  @State private showActionSheet: boolean = false;

  private handleLongPress(): void {
    this.isRatingActive = true;
    this.rating = 1;
  }

  private handleLongPressEnd(): void {
    this.isRatingActive = false;
    if (this.rating > 0) {
      this.showActionSheet = true;
    } else {
      this.rating = 0;
    }
  }

  private handleRatingChange(value: number): void {
    if (this.isRatingActive) {
      this.rating = value;
    }
  }

  private handleActionSheetSubmit(): void {
    this.showActionSheet = false;
  }

  private handleActionSheetCancel(): void {
    this.showActionSheet = false;
    this.rating = 0;
  }

  build() {
    Column() {
      Text('Rate Us')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })
        .width('100%')
        .textAlign(TextAlign.Center);

      Row() {
        ForEach([1, 2, 3, 4, 5], (index: number) => {
          Image($r('app.media.star'))
            .width(40)
            .height(40)
            .objectFit(ImageFit.Contain)
            .opacity(index <= this.rating ? 1 : 0.3)
            .onClick(() => this.handleRatingChange(index))
            .gesture(
              LongPressGesture()
                .onAction(() => this.handleLongPress())
                .onActionEnd(() => this.handleLongPressEnd())
            );
        });
      }
      .width('100%')
      .justifyContent(FlexAlign.Center);

      if (this.showActionSheet) {
        ActionSheet() {
          ActionSheetItem({ label: 'Confirm Rating' })
          ActionSheetItem({ label: `You rated us ${this.rating} stars` })
          ActionSheetItem({ label: 'Submit', action: () => this.handleActionSheetSubmit() })
          ActionSheetItem({ label: 'Cancel', action: () => this.handleActionSheetCancel() })
        }
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5');
  }
}

