      .width('100%')
      .justifyContent(FlexAlign.Start)
      .margin({ bottom: 20 })

      Row() {
        Text('Additional Feature:')
          .fontSize(16)
          .margin({ right: 10 })
        Checkbox({ name: 'feature' })
          .checked(this.isCheckboxChecked)
          .onChange((checked: boolean) => {
