@Entry
@Component
struct WaterIntakeTracker {
  @State waterIntake: number = 0;
  @State dailyGoal: number = 2000;
  @State progress: number = 0;
  @State isDarkMode: boolean = false;
  @State progressColor: string = '#4CAF50';

  updateProgress() {
    this.progress = (this.waterIntake / this.dailyGoal) * 100;
  }

  toggleDarkMode() {
    this.isDarkMode = !this.isDarkMode;
  }

  toggleProgressColor() {
    this.progressColor = this.progressColor === '#4CAF50' ? '#2196F3' : '#4CAF50';
  }

  build() {
    Column() {
      Text('Daily Water Intake Tracker')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin(20)
        .fontColor(this.isDarkMode ? '#FFFFFF' : '#000000');

      Text(`Goal: ${this.dailyGoal} ml`)
        .fontSize(18)
        .margin(10)
        .fontColor(this.isDarkMode ? '#FFFFFF' : '#000000');

      Text(`Consumed: ${this.waterIntake} ml`)
        .fontSize(18)
        .margin(10)
        .fontColor(this.isDarkMode ? '#FFFFFF' : '#000000');

      Stack() {
        Circle()
          .width(200)
          .height(200)
          .stroke('#E0E0E0')
          .strokeWidth(15)
          .fill('transparent');

        Path()
          .width(200)
          .height(200)
          .commands(`M100,100 m0,-85 a85,85 0 1,1 0,170 a85,85 0 1,1 0,-170`)
          .stroke(this.progressColor)
          .strokeWidth(15)
          .strokeDashArray([this.progress * 5.34, 534])
          .fill('transparent');

        Text(`${Math.round(this.progress)}%`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .fontColor(this.isDarkMode ? '#FFFFFF' : '#000000');
      }
      .margin(20);

      Row() {
        Button('+250 ml')
          .onClick(() => {
            this.waterIntake += 250;
            this.updateProgress();
          })
          .margin(10)
          .backgroundColor(this.isDarkMode ? '#333333' : '#F5F5F5')
          .fontColor(this.isDarkMode ? '#FFFFFF' : '#000000');

        Button('Reset')
          .onClick(() => {
            this.waterIntake = 0;
            this.updateProgress();
          })
          .margin(10)
          .backgroundColor(this.isDarkMode ? '#333333' : '#F5F5F5')
          .fontColor(this.isDarkMode ? '#FFFFFF' : '#000000');
      }

      Row() {
        Button('Toggle Theme')
          .onClick(() => {
            this.toggleDarkMode();
          })
          .margin(10)
          .backgroundColor(this.isDarkMode ? '#333333' : '#F5F5F5')
          .fontColor(this.isDarkMode ? '#FFFFFF' : '#000000');

        Button('Toggle Color')
          .onClick(() => {
            this.toggleProgressColor();
          })
          .margin(10)
          .backgroundColor(this.isDarkMode ? '#333333' : '#F5F5F5')
          .fontColor(this.isDarkMode ? '#FFFFFF' : '#000000');
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor(this.isDarkMode ? '#121212' : '#FFFFFF');
  }
}

