import { Column, Row, Text, Button, ForEach } from '@ohos.arkui.advanced';

interface FontWeight {
  Bold: string;
}

interface Color {
  Gray: string;
  Green: string;
  Red: string;
}

const fontWeight: FontWeight = {
  Bold: 'bold'
};

const color: Color = {
  Gray: '#808080',
  Green: '#008000',
  Red: '#FF0000'
};

interface Question {
  question: string;
  audio: string;
  options: string[];
  correctAnswer: number;
}

@Entry
@Component
struct QuizAccordion {
  @State questions: Question[] = [
    {
      question: "What is the capital of France?",
      audio: "audio_france",
      options: ["Berlin", "Madrid", "Paris", "Rome"],
      correctAnswer: 2,
    },
    {
      question: "Which planet is known as the Red Planet?",
      audio: "audio_mars",
      options: ["Venus", "Mars", "Jupiter", "Saturn"],
      correctAnswer: 1,
    },
  ];

  @State expandedIndex: number = -1;
  @State isPlaying: boolean = false;
  @State score: number = 0;
  @State selectedAnswers: number[] = Array(this.questions.length).fill(-1);

  toggleQuestion(index: number): void {
    if (this.expandedIndex === index) {
      this.expandedIndex = -1;
    } else {
      this.expandedIndex = index;
    }
  }

  toggleAudio(): void {
    this.isPlaying = !this.isPlaying;
  }

  selectAnswer(questionIndex: number, optionIndex: number): void {
    if (this.selectedAnswers[questionIndex] === -1) {
      this.selectedAnswers[questionIndex] = optionIndex;
      if (optionIndex === this.questions[questionIndex].correctAnswer) {
        this.score += 1;
      }
    }
  }

  build() {
    Column() {
      ForEach(this.questions, (question: Question, index: number) => {
        Column() {
          Row({ space: 10 }) {
            Text(question.question)
              .fontSize(16)
              .fontWeight(fontWeight.Bold)
              .layoutWeight(1);
            Button(this.isPlaying ? "Playing..." : "Play")
              .onClick(() => this.toggleAudio())
              .width(80);
          }
          .padding(10)
          .onClick(() => this.toggleQuestion(index));

          if (this.expandedIndex === index) {
            Column() {
              ForEach(question.options, (option: string, optionIndex: number) => {
                Row({ space: 10 }) {
                  Text(option)
                    .fontSize(14);
                  if (this.selectedAnswers[index] === optionIndex) {
                    Text(optionIndex === question.correctAnswer ? "✓" : "✗")
                      .fontSize(14)
                      .fontColor(optionIndex === question.correctAnswer ? color.Green : color.Red);
                  }
                }
                .padding(5)
                .onClick(() => this.selectAnswer(index, optionIndex));
              });
            }
            .padding({ left: 20, right: 20, bottom: 10 });
          }
        }
        .border({ width: 1, color: color.Gray })
        .margin({ bottom: 10 });
      });

      Text(`Score: ${this.score}/${this.questions.length}`)
        .fontSize(18)
        .fontWeight(fontWeight.Bold)
        .margin({ top: 20 });
    }
    .padding(20);
  }
}

