        ForEach(this.breadcrumbs, (item: string, index: number) => {
          this.BreadcrumbItem(item, index);
          if (index < this.breadcrumbs.length - 1) {
            Text('>')
              .fontColor('#6B6B6B')
              .fontSize(16)
              .margin({ right: 8 });
          }
        });
      }
      .padding(16)
      .width('100%')
      .justifyContent(FlexAlign.Start);

      if (this.breadcrumbs[this.breadcrumbs.length - 1] === 'Home') {
        Text('Home Content')
          .fontSize(20)
          .margin({ top: 16 });
      } else if (this.breadcrumbs[this.breadcrumbs.length - 1] === 'Category') {
        Text('Category Content')
          .fontSize(20)
          .margin({ top: 16 });
      } else if (this.breadcrumbs[this.breadcrumbs.length - 1] === 'Product') {
        Text('Product Content')
          .fontSize(20)
          .margin({ top: 16 });
      }

      Button('Show ActionSheet')
        .onClick(() => {
          promptAction.showActionMenu({
            title: 'Options',
            buttons: [
              { text: 'Option 1', color: '#007DFF' },
              { text: 'Option 2', color: '#007DFF' }
            ]
          }).then((response: promptAction.ActionMenuSuccessResponse) => {
            if (response.index === 0) {
              console.log('Option 1 selected');
            } else if (response.index === 1) {
              console.log('Option 2 selected');
            }
          }).catch((err: Error) => {
            console.error(`showActionMenu error: ${JSON.stringify(err)}`);
          });
        })
        .margin({ top: 16 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.isDarkTheme ? '#333333' : '#FFFFFF')
    .padding(16);
  }
}

