import { Grid, GridItem } from '@ohos.arkui.advanced';
import { TextInput, Button, Text, Column, Row } from '@ohos.arkui.advanced';

interface TodoItem {
  id: string;
  text: string;
  completed: boolean;
  rating: number;
}

@Entry
@Component
struct TodoList {
  @State todoItems: TodoItem[] = [];
  @State newTodoText: string = '';

  private generateId(): string {
    return Math.random().toString(36).substring(2, 9);
  }

  private addTodo(): void {
    if (this.newTodoText.trim()) {
      let newItem: TodoItem = {
        id: this.generateId(),
        text: this.newTodoText,
        completed: false,
        rating: 1
      };
      this.todoItems.push(newItem);
      this.newTodoText = '';
    }
  }

  private toggleTodo(id: string): void {
    this.todoItems = this.todoItems.map(item => {
      if (item.id === id) {
        return {
          id: item.id,
          text: item.text,
          completed: !item.completed,
          rating: item.rating
        };
      }
      return item;
    });
  }

  private updateRating(id: string, rating: number): void {
    this.todoItems = this.todoItems.map(item => {
      if (item.id === id) {
        return {
          id: item.id,
          text: item.text,
          completed: item.completed,
          rating: rating
        };
      }
      return item;
    });
  }

  private deleteTodo(id: string): void {
    this.todoItems = this.todoItems.filter(item => item.id !== id);
  }

  @Builder
  private renderStars(rating: number, id: string) {
    Row() {
      ForEach([1, 2, 3, 4, 5], (i: number) => {
        Text(i <= rating ? '\u2605' : '\u2606')
          .onClick(() => this.updateRating(id, i))
          .fontColor(i <= rating ? '#FFD700' : '#CCCCCC')
          .margin({ right: 5 });
      });
    }
  }

  build() {
    Column() {
      Row() {
        TextInput({ placeholder: 'Add new todo...', text: this.newTodoText })
          .onChange((value: string) => {
            this.newTodoText = value;
          })
          .width('70%');

        Button('Add')
          .onClick(() => this.addTodo())
          .width('30%');
      }
      .padding(20);

      Grid() {
        ForEach(this.todoItems, (item: TodoItem) => {
          GridItem() {
            Column() {
              Text(item.text)
                .fontSize(18)
                .textDecoration(item.completed ? 'LineThrough' : 'None');

              this.renderStars(item.rating, item.id);

              Row() {
                Button(item.completed ? 'Undo' : 'Complete')
                  .onClick(() => this.toggleTodo(item.id))
                  .margin({ right: 5 });

                Button('Delete')
                  .onClick(() => this.deleteTodo(item.id));
              }
              .margin({ top: 10 });
            }
            .padding(10)
            .backgroundColor('#F5F5F5')
            .borderRadius(8);
          }
          .margin(5);
        });
      }
      .columnsTemplate('1fr 1fr')
      .columnsGap(10)
      .rowsGap(10)
      .width('100%');
    }
    .width('100%')
    .padding(10);
  }
}

