import { TimePicker, Toggle, Tabs, TabContent, AlertDialog, ToggleType } from '@ohos.arkui.component';
import { Text, Column, Stack } from '@ohos.arkui.component';
import { TextAlign, FlexAlign, FlexDirection, HorizontalAlign } from '@ohos.arkui.common';

interface TimePickerResult {
  hour: number;
  minute: number;
}

@Entry
@Component
struct AlarmClockApp {
  @State currentTime: Date = new Date();
  @State alarmTime: Date = new Date();
  @State isAlarmOn: boolean = false;
  private timerId: number | undefined = undefined;

  aboutToAppear() {
    this.timerId = setInterval(() => {
      this.currentTime = new Date();
      if (this.isAlarmOn && this.isAlarmTriggered()) {
        this.showAlarmAlert();
      }
    }, 1000);
  }

  aboutToDisappear() {
    if (this.timerId !== undefined) {
      clearInterval(this.timerId);
    }
  }

  isAlarmTriggered(): boolean {
    return (
      this.currentTime.getHours() === this.alarmTime.getHours() &&
      this.currentTime.getMinutes() === this.alarmTime.getMinutes() &&
      this.currentTime.getSeconds() === 0
    );
  }

  showAlarmAlert() {
    AlertDialog.show({
      title: 'Alarm',
      message: 'Time to wake up!',
      confirm: {
        value: 'Dismiss',
        action: () => {
          this.isAlarmOn = false;
        }
      },
      cancel: () => {}
    });
  }

  formatTime(date: Date): string {
    const hours = date.getHours().toString().padStart(2, '0');
    const minutes = date.getMinutes().toString().padStart(2, '0');
    const seconds = date.getSeconds().toString().padStart(2, '0');
    return `${hours}:${minutes}:${seconds}`;
  }

  build() {
    Column() {
      Tabs() {
        TabContent() {
          Column() {
            Text(this.formatTime(this.currentTime))
              .fontSize(48)
              .fontColor('#000000')
              .textAlign(TextAlign.Center)
              .margin({ top: 20 });

            TimePicker({
              selected: this.alarmTime
            })
            .onChange((value: TimePickerResult) => {
              this.alarmTime = new Date();
              this.alarmTime.setHours(value.hour);
              this.alarmTime.setMinutes(value.minute);
            });

            Toggle({ type: ToggleType.Switch, isOn: this.isAlarmOn })
              .onChange((isOn: boolean) => {
                this.isAlarmOn = isOn;
              })
              .margin({ top: 20 });
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center)
          .alignItems(HorizontalAlign.Center);
        }.tabBar('Alarm Settings');

        TabContent() {
          Column() {
            Text('Alarm Statistics')
              .fontSize(24)
              .fontColor('#000000')
              .textAlign(TextAlign.Center)
              .margin({ top: 20 });

            Text('Total Alarms: 0')
              .fontSize(18)
              .fontColor('#808080')
              .textAlign(TextAlign.Center)
              .margin({ top: 10 });
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center)
          .alignItems(HorizontalAlign.Center);
        }.tabBar('Statistics');
      }
      .width('100%')
      .height('100%');
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

