import fs from '@ohos.file.fs';
import { Rating } from '@ohos.arkui.advanced';
import { Popup } from '@ohos.arkui.advanced';

interface Transaction {
  type: 'income' | 'expense';
  amount: number;
  category: string;
  description: string;
  date: string;
}

@Entry
@Component
struct Index {
  @State transactions: Array<Transaction> = [];
  @State message: string = '';
  @State rating: number = 0;
  @State showPopup: boolean = false;

  async saveTransactions() {
    try {
      const path = getContext().filesDir + '/transactions.json';
      const file = await fs.open(path, fs.OpenMode.READ_WRITE | fs.OpenMode.CREATE);
      if (this.transactions && this.transactions.length > 0) {
        const data = JSON.stringify(this.transactions);
        await fs.write(file.fd, data);
      }
      await fs.close(file.fd);
      this.message = 'Transactions saved successfully';
      this.showPopup = true;
    } catch {
      this.message = 'Failed to save transactions';
      this.showPopup = true;
    }
  }

  async loadTransactions() {
    try {
      const path = getContext().filesDir + '/transactions.json';
      const file = await fs.open(path, fs.OpenMode.READ_ONLY);
      const content = await fs.readText(file.fd);
      if (content) {
        this.transactions = JSON.parse(content) as Array<Transaction>;
      }
      await fs.close(file.fd);
      this.message = 'Transactions loaded successfully';
      this.showPopup = true;
    } catch {
      this.message = 'Failed to load transactions';
      this.showPopup = true;
    }
  }

  clearMessage() {
    this.message = '';
    this.showPopup = false;
  }

  build() {
    Column() {
      Button('Save Transactions')
        .onClick(() => {
          this.saveTransactions();
        })

      Button('Load Transactions')
        .onClick(() => {
          this.loadTransactions();
        })

      Rating({ rating: this.rating, indicator: true })
        .onChange((value: number) => {
          this.rating = value;
        })

      Popup({ show: this.showPopup }) {
        Column() {
          Text(this.message)
            .fontSize(16)
            .margin(10)
          Button('OK')
            .onClick(() => {
              this.clearMessage();
            })
        }
        .width('80%')
        .padding(20)
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

