import { Column, Row, Text, TextInput, Button, Image, Refresh, Color, InputType } from '@ohos.arkui.node';

enum Currency {
  USD = 'USD',
  EUR = 'EUR',
  GBP = 'GBP',
  JPY = 'JPY'
}

interface ExchangeRates {
  USD: number;
  EUR: number;
  GBP: number;
  JPY: number;
}

@Entry
@Component
struct CurrencyConverter {
  @State amount: string = '';
  @State sourceCurrency: Currency = Currency.USD;
  @State targetCurrency: Currency = Currency.EUR;
  @State convertedAmount: string = '';
  @State error: string = '';
  @State showVideoPlaceholder: boolean = false;
  @State refreshing: boolean = false;
  @State exchangeRates: ExchangeRates = {
    USD: 1,
    EUR: 0.85,
    GBP: 0.73,
    JPY: 110
  };

  getRate(currency: Currency): number {
    switch(currency) {
      case Currency.USD: return this.exchangeRates.USD;
      case Currency.EUR: return this.exchangeRates.EUR;
      case Currency.GBP: return this.exchangeRates.GBP;
      case Currency.JPY: return this.exchangeRates.JPY;
    }
  }

  convertCurrency() {
    const amountValue = parseFloat(this.amount);
    if (isNaN(amountValue)) {
      this.error = 'Please enter a valid amount.';
      this.convertedAmount = '';
      return;
    }

    const sourceRate = this.getRate(this.sourceCurrency);
    const targetRate = this.getRate(this.targetCurrency);
    const rate = targetRate / sourceRate;
    this.convertedAmount = (amountValue * rate).toFixed(2);
    this.error = '';
  }

  refreshRates() {
    this.refreshing = true;
    const randomAdjustment = (Math.random() * 0.1) - 0.05;
    this.exchangeRates = {
      USD: 1,
      EUR: 0.85 + randomAdjustment,
      GBP: 0.73 + randomAdjustment,
      JPY: 110 + randomAdjustment * 10
    };
    this.refreshing = false;
  }

  build() {
    Column() {
      Refresh({ refreshing: $$this.refreshing }) {
        Column() {
          Text('Currency Converter')
            .fontSize(24)
            .margin({ bottom: 20 });

          Row() {
            TextInput({ placeholder: 'Amount', text: this.amount })
              .type(InputType.Number)
              .onChange((value: string) => {
                this.amount = value;
              })
              .layoutWeight(1);

            TextInput({ placeholder: 'Source', text: this.sourceCurrency })
              .onChange((value: string) => {
                this.sourceCurrency = value as Currency;
              })
              .layoutWeight(1);

            TextInput({ placeholder: 'Target', text: this.targetCurrency })
              .onChange((value: string) => {
                this.targetCurrency = value as Currency;
              })
              .layoutWeight(1);
          }
          .margin({ bottom: 20 });

          Button('Convert')
            .onClick(() => {
              this.convertCurrency();
            })
            .margin({ bottom: 20 });

          if (this.error) {
            Text(this.error)
              .fontColor(Color.Red)
              .margin({ bottom: 20 });
          }

          if (this.convertedAmount) {
            Text(`Converted Amount: ${this.convertedAmount}`)
              .fontSize(18)
              .margin({ bottom: 20 });
          }

          Button(this.showVideoPlaceholder ? 'Hide Video' : 'Show Video')
            .onClick(() => {
              this.showVideoPlaceholder = !this.showVideoPlaceholder;
            })
            .margin({ bottom: 20 });

          if (this.showVideoPlaceholder) {
            Image($r('app.media.ic_default_image'))
              .width(200)
              .height(150)
              .border({ width: 1, color: Color.Black })
              .margin({ bottom: 20 });
          }
        }
        .padding(20);
      }
      .onRefresh(() => {
        this.refreshRates();
      });
    }
    .width('100%')
    .height('100%');
  }
}

