}

@Entry
@Component
struct QuizApp {
  @State currentQuestionIndex: number = 0;
  @State score: number = 0;
  @State showScore: boolean = false;
  @State showFeedback: boolean = false;
  @State isCorrect: boolean = false;
  @State refreshing: boolean = false;
  private avPlayer: media.AVPlayer | null = null;

  private questions: Question[] = [
    {
      question: 'What is the capital of France?',
      options: ['London', 'Berlin', 'Paris', 'Madrid'],
      correctAnswer: 2,
    },
    {
      question: 'Which planet is closest to the Sun?',
      options: ['Mars', 'Venus', 'Mercury', 'Jupiter'],
      correctAnswer: 2,
    },
    {
      question: 'What is the largest mammal?',
      options: ['African Elephant', 'Blue Whale', 'Giraffe', 'Hippopotamus'],
      correctAnswer: 1,
    },
  ];

  aboutToAppear(): void {
    let context = getContext(this);
    let atManager = abilityAccessCtrl.createAtManager();
    atManager.requestPermissionsFromUser(context, ['ohos.permission.READ_MEDIA']).then(() => {
      this.initializeAudioPlayer();
    }).catch((err: BusinessError) => {
      console.error('Failed to request permissions:', err);
    });
  }

  aboutToDisappear(): void {
    this.releaseAudioPlayer();
  }

  initializeAudioPlayer(): void {
    media.createAVPlayer().then((avPlayer: media.AVPlayer) => {
      this.avPlayer = avPlayer;
      this.avPlayer.on('error', (error: BusinessError) => {
        console.error('Audio playback error:', error);
      });
    }).catch((error: BusinessError) => {
      console.error('Failed to create AVPlayer:', error);
    });
  }

  releaseAudioPlayer(): void {
    if (this.avPlayer) {
      this.avPlayer.release();
      this.avPlayer = null;
    }
  }

  playAudioFeedback(isCorrect: boolean): void {
    if (!this.avPlayer) {
      console.error('Audio player not initialized');
      return;
    }
    const audioResource = isCorrect ? 'correct' : 'wrong';
    this.avPlayer.reset();
    this.avPlayer.url = `resource://rawfile/${audioResource}.mp3`;
    this.avPlayer.play().then(() => {
      console.log('Audio playback started');
    }).catch((error: BusinessError) => {
      console.error('Failed to play audio:', error);
    });
  }

  checkAnswer(selectedIndex: number): void {
    const correct = selectedIndex === this.questions[this.currentQuestionIndex].correctAnswer;
    this.isCorrect = correct;
    if (correct) {
      this.score++;
    }
    this.showFeedback = true;
    this.playAudioFeedback(correct);

    setTimeout(() => {
      this.showFeedback = false;
      if (this.currentQuestionIndex < this.questions.length - 1) {
        this.currentQuestionIndex++;
      } else {
        this.showScore = true;
      }
    }, 1000);
  }

  resetQuiz(): void {
    this.currentQuestionIndex = 0;
    this.score = 0;
    this.showScore = false;
    this.showFeedback = false;
    this.isCorrect = false;
  }

  onRefresh(): void {
    this.refreshing = true;
    setTimeout(() => {
      this.resetQuiz();
      this.refreshing = false;
    }, 1000);
  }

  build() {
    Column() {
      SwipeRefresh({
        refreshing: this.refreshing,
        onRefresh: () => this.onRefresh()
      }) {
        Column() {
          if (!this.showScore) {
            Progress({
              value: ((this.currentQuestionIndex + 1) / this.questions.length) * 100,
              total: 100
            })
            .width('90%')
            .height(10)
            .margin({ top: 20, bottom: 20 });

            Text(`Question ${this.currentQuestionIndex + 1}/${this.questions.length}`)
              .fontSize(16)
              .margin({ bottom: 10 });

            Text(this.questions[this.currentQuestionIndex].question)
              .fontSize(

