import media from '@ohos.multimedia.media';
import fs from '@ohos.file.fs';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct VideoPlayerWithFrames {
  private videoController: media.AVPlayer | null = null;
  @State videoFrames: Array<string> = [];
  @State isPlaying: boolean = false;
  @State currentFrame: number = 0;

  async aboutToAppear() {
    this.videoController = await media.createAVPlayer();
  }

  async aboutToDisappear() {
    if (this.videoController) {
      this.videoController.release();
      this.videoController = null;
    }
  }

  simulateFrames() {
    for (let i = 0; i < 10; i++) {
      this.videoFrames.push("frame_" + i + ".png");
    }
  }

  async saveFrame(frameName: string) {
    try {
      const context = getContext(this);
      const rawFile = await context.resourceManager.getRawFileContent('video.mp4');
      const filePath = context.filesDir + '/' + frameName;
      const file = await fs.open(filePath, fs.OpenMode.READ_WRITE | fs.OpenMode.CREATE);
      await fs.write(file.fd, rawFile);
      await fs.close(file.fd);
      this.showToastMessage("Frame saved: " + frameName);
    } catch (error) {
      this.showToastMessage("Error saving frame: " + error);
    }
  }

  showToastMessage(message: string) {
    promptAction.showToast({ message: message, duration: 2000 });
  }

  async loadVideo() {
    if (!this.videoController) return;
    try {
      this.videoController.url = 'resource://rawfile/video.mp4';
      await this.videoController.prepare();
      this.videoController.on('stateChange', (state) => {
      });
    } catch (error) {
      this.showToastMessage('Video load error: ' + error);
    }
  }

  build() {
    Column() {
      Row() {
        Text('Video Player')
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)

      Row({ space: 10 }) {
        Button(this.isPlaying ? 'Pause' : 'Play')
          .onClick(async () => {
            if (!this.videoController) return;
            if (this.isPlaying) {
              await this.videoController.pause();
            } else {
              await this.videoController.play();
            }
            this.isPlaying = !this.isPlaying;
          })
        Button('Stop')
          .onClick(() => {
            if (!this.videoController) return;
            this.videoController.stop();
            this.isPlaying = false;
          })
      }.margin({ top: 10 })

      List({ space: 10 }) {
        ForEach(this.videoFrames, (frame: string) => {
          ListItem() {
            Row() {
              Text(frame)
                .fontSize(16)
              Button('Save')
                .onClick(() => {
                  this.saveFrame(frame);
                })
            }
          }
        }, (frame: string) => frame)
      }
      .layoutWeight(1)
      .width('100%')
    }
    .width('100%')
    .height('100%')
    .onAppear(() => {
      this.simulateFrames();
      this.loadVideo();
    })
  }
}

interface Flashcard {
  id: number;
  title: string;
  content: string;
  category: string;
}

@Entry
@Component
struct FitnessFlashcardApp {
  @State private flashcards: Array<Flashcard> = [
    { id: 1, title: "Push-Ups", content: "A basic upper-body exercise.", category: "Strength" },
    { id: 2, title: "Running", content: "Cardiovascular exercise for endurance.", category: "Cardio" },
    { id: 3, title: "Squats", content: "Lower-body strength exercise.", category: "Strength" },
    { id: 4, title: "Cycling", content: "Low-impact cardio exercise.", category: "Cardio" },
  ];

  @State private searchQuery: string = "";
  @State private selectedCategory: string = "All";
  @State private showTooltip: boolean = false;

  private filteredFlashcards(): Array<Flashcard> {
    return this.flashcards.filter(flashcard => {
      const matchesSearch = flashcard.title.toLowerCase().includes(this.searchQuery.toLowerCase()) ||
                         flashcard.content.toLowerCase().includes(this.searchQuery.toLowerCase());
      const matchesCategory = this.selectedCategory === "All" || flashcard.category === this.selectedCategory;
      return matchesSearch && matchesCategory;
    });
  }

  build() {
    Column() {
      Row() {
        TextInput({ placeholder: "Search flashcards..." })
          .width("70%")
          .onChange((value: string) => {
            this.searchQuery = value;
          });

        Button("Filter")
