            this.showTooltip = !this.showTooltip;
          });
      }
      .padding(10)
      .width("100%")

      if (this.showTooltip) {
        Text("Use the search bar to find flashcards by title or content.")
          .padding(10)
          .backgroundColor("#f0f0f0")
          .borderRadius(5)
          .margin({ top: 5, bottom: 10 });
      }

      Row() {
        Text("Category:")
          .margin({ right: 10 });

        Button(this.selectedCategory)
          .onClick(() => {
          });
