      .padding(10)
      .width("100%")

      List({ space: 10 }) {
        ForEach(this.filteredFlashcards(), (flashcard: Flashcard) => {
          ListItem() {
            Column() {
              Text(flashcard.title)
                .fontSize(18)
                .fontWeight(FontWeight.Bold);
