import preferences from '@ohos.data.preferences';
import { LongPressGesture, GestureGroup, GestureMode } from '@ohos.arkui.gesture';
import prompt from '@ohos.prompt';
import { PersistentStorage } from '@ohos.data.storage';
import { Toggle, ToggleType } from '@ohos.arkui.component';

interface Exercise {
  id: string;
  name: string;
  sets?: number;
  reps?: number;
}

const storage = PersistentStorage.getStorage();
@Entry(storage)
@Component
struct WorkoutPlanner {
  @LocalStorageLink('workoutEnabled') workoutEnabled: boolean = false;
  @State exercises: Exercise[] = [
    { id: '1', name: 'Push-ups', sets: 3, reps: 15 },
    { id: '2', name: 'Squats', sets: 3, reps: 20 },
    { id: '3', name: 'Pull-ups', sets: 3, reps: 10 },
    { id: '4', name: 'Plank', sets: 3, reps: 1 }
  ];
  @State editingExercise: Exercise | null = null;

  aboutToAppear() {
    preferences.getPreferences(getContext(this), 'workout_prefs').then((prefs: preferences.Preferences) => {
      prefs.get('workoutEnabled', false).then((value: boolean) => {
        this.workoutEnabled = value;
      });
    });
  }

  toggleWorkoutEnabled(): void {
    this.workoutEnabled = !this.workoutEnabled;
    preferences.getPreferences(getContext(this), 'workout_prefs').then((prefs: preferences.Preferences) => {
      prefs.put('workoutEnabled', this.workoutEnabled).then(() => {
        prefs.flush();
      });
    });
  }

  showEditDialog(): void {
    if (this.editingExercise) {
      prompt.showDialog({
        title: 'Edit Exercise',
        message: `Editing: ${this.editingExercise.name}`,
        buttons: [
          {
            text: 'Cancel',
            color: '#000000'
          },
          {
            text: 'Save',
            color: '#000000'
          }
        ]
      }).then((result: prompt.ShowDialogSuccessResponse) => {
        if (result.index === 1) {
          this.saveExercise();
        } else {
          this.cancelEdit();
        }
      });
    }
  }

  handleLongPress(exercise: Exercise): void {
    this.editingExercise = exercise;
    this.showEditDialog();
  }

  saveExercise(): void {
    if (this.editingExercise) {
      const index = this.exercises.findIndex((ex) => ex.id === this.editingExercise!.id);
      if (index !== -1) {
        this.exercises[index] = {
          id: this.editingExercise.id,
          name: this.editingExercise.name,
          sets: this.editingExercise.sets,
          reps: this.editingExercise.reps
        };
      }
    }
  }

  cancelEdit(): void {
    this.editingExercise = null;
  }

  build() {
    Column() {
      Row() {
        Text('Workout Planner')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 });
      }

      Row() {
        Text('Enable Workout Planning')
          .fontSize(18)
          .margin({ right: 10 });
        Toggle({ type: ToggleType.Switch, isOn: this.workoutEnabled })
          .onChange(() => this.toggleWorkoutEnabled());
      }
      .margin({ bottom: 20 });

      List({ space: 10 }) {
        ForEach(this.exercises, (exercise: Exercise) => {
          ListItem() {
            Row() {
              Text(exercise.name)
                .fontSize(16)
                .margin({ right: 10 });
              Text(`Sets: ${exercise.sets}, Reps: ${exercise.reps}`)
                .fontSize(14);
            }
            .padding(10)
            .gesture(
              GestureGroup(GestureMode.Sequence,
                LongPressGesture()
                  .onAction(() => this.handleLongPress(exercise))
              )
            );
          }
        });
      }
      .width('100%')
      .height('60%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

