import { Column, Text, FlexAlign, FlexJustify } from '@ohos.arkui.component';
import vibrator from '@ohos.vibrator';
import { BusinessError } from '@ohos.base';

@Entry
@Component
struct MarqueeWithHaptic {
  @State private marqueeText: string = "This is a scrolling marquee text with haptic feedback!";

  private async isVibrationSupported(): Promise<boolean> {
    try {
      return await vibrator.isSupportEffect('haptic.common');
    } catch (error) {
      return false;
    }
  }

  private triggerVibration() {
    try {
      vibrator.startVibration({
        type: 'time',
        effectId: 'haptic.common',
        duration: 100
      }, {
        callback: (error: BusinessError) => {
          if (error) {
            console.error('Vibration failed:', error);
          }
        }
      });
    } catch (error) {
      console.error('Vibration failed:', error);
    }
  }

  build() {
    Column() {
      Text(this.marqueeText)
        .marquee({
          loop: -1,
          scrollAmount: 5,
          startDelay: 1000,
        })
        .fontSize(20)
        .fontColor('#000000')
        .backgroundColor('#F5F5F5')
        .margin({ top: 20, bottom: 20 })
        .padding(10)
        .onClick(async () => {
          if (await this.isVibrationSupported()) {
            this.triggerVibration();
          }
        });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexJustify.Center)
    .alignItems(FlexAlign.Center)
    .backgroundColor('#FFFFFF');
  }
}

