@Entry
@Component
struct FoodDeliveryTracker {
  @State orderStatus: string = 'Order Placed';
  @State progressValue: number = 25;
  @State selectedTime: Date = new Date();
  @State isDeliveryStarted: boolean = false;
  private timerId: number | null = null;

  updateStatus(): void {
    if (this.progressValue < 100) {
      this.progressValue += 25;
      switch (this.progressValue) {
        case 50:
          this.orderStatus = 'Preparing';
          break;
        case 75:
          this.orderStatus = 'On the Way';
          break;
        case 100:
          this.orderStatus = 'Delivered';
          if (this.timerId) {
            clearInterval(this.timerId);
            this.timerId = null;
          }
          break;
      }
    }
  }

  startDelivery(): void {
    if (!this.isDeliveryStarted) {
      this.isDeliveryStarted = true;
      this.timerId = setInterval(() => this.updateStatus(), 2000);
    }
  }

  onTimeChange(value: TimePickerResult): void {
    this.selectedTime = new Date(
      this.selectedTime.getFullYear(),
      this.selectedTime.getMonth(),
      this.selectedTime.getDate(),
      value.hour,
      value.minute,
      this.selectedTime.getSeconds()
    );
  }

  build() {
    Column() {
      Text('Food Delivery Tracker')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Progress({ value: this.progressValue, total: 100 })
        .width('80%')
        .height(10)
        .margin({ bottom: 20 });

      Text(this.orderStatus)
        .fontSize(18)
        .margin({ bottom: 20 });

      TimePicker({ selected: this.selectedTime })
        .onChange((value: TimePickerResult) => this.onTimeChange(value))
        .width('80%')
        .margin({ bottom: 20 });

      Text(`Selected Time: ${this.selectedTime.getHours()}:${this.selectedTime.getMinutes().toString().padStart(2, '0')}`)
        .fontSize(16)
        .margin({ bottom: 20 });

      Button('Start Delivery')
        .onClick(() => this.startDelivery())
        .width('80%')
        .height(50)
        .backgroundColor(Color.Blue)
        .fontColor(Color.White)
        .margin({ bottom: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#ffffff');
  }
}

import prompt from '@ohos.promptAction';
