@Entry
@Component
struct FormValidationPopup {
  @State selectedOption: string = '';
  dialogController: CustomDialogController = new CustomDialogController({
    builder: () => this.DialogBuilder(),
    alignment: DialogAlignment.Center
  });

  @Builder
  DialogBuilder(): void {
    Column({ space: 10 }) {
      Text('Select an option')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      RadioGroup({ group: 'options' })
        .margin({ bottom: 20 }) {
        Radio({ value: 'Option 1', group: 'options' })
          .checked(this.selectedOption === 'Option 1')
          .onChange((isChecked: boolean) => {
            if (isChecked) this.selectedOption = 'Option 1';
          });

        Radio({ value: 'Option 2', group: 'options' })
          .checked(this.selectedOption === 'Option 2')
          .onChange((isChecked: boolean) => {
            if (isChecked) this.selectedOption = 'Option 2';
          });
      }

      Row({ space: 10 }) {
        Button('Cancel')
          .onClick(() => {
            this.dialogController.close();
          });

        Button('Submit')
          .onClick(() => {
            if (this.selectedOption) {
              prompt.showToast({ message: `Selected: ${this.selectedOption}`, duration: 2000 });
              this.dialogController.close();
            } else {
              prompt.showToast({ message: 'Please select an option', duration: 2000 });
            }
          });
      }
      .justifyContent(FlexAlign.End);
    }
    .padding(20)
    .backgroundColor(Color.White)
    .borderRadius(10);
  }

  build() {
    Column() {
      Button('Show Popup')
        .onClick(() => {
          this.dialogController.open();
        });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

