@Entry
@Component
struct AnimatedTextApp {
  @State private anim_texts: string[] = ['Hello', 'ArkTS', 'Animation', 'Effects'];
  @State private anim_opacity: number[] = [0, 0, 0, 0];
  @State private anim_scale: number[] = [0.5, 0.5, 0.5, 0.5];

  build() {
    Column({ space: 20 }) {
      ForEach(this.anim_texts, (text: string, index: number) => {
        Text(text)
          .fontSize(24)
          .fontColor(Color.Black)
          .opacity(this.anim_opacity[index])
          .scale({ x: this.anim_scale[index], y: this.anim_scale[index] })
          .onClick(() => {
            animateTo({
              duration: 1000,
              curve: Curve.EaseInOut
            }, () => {
              this.anim_opacity[index] = 1;
              this.anim_scale[index] = 1;
            });
          })
      })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor(Color.White)
    .onAppear(() => {
      this.anim_texts.forEach((_, index) => {
        setTimeout(() => {
          animateTo({
            duration: 1000,
            curve: Curve.EaseInOut
          }, () => {
            this.anim_opacity[index] = 1;
            this.anim_scale[index] = 1;
          });
        }, index * 500);
      });
    })
  }
}

import { Text, Button, Column, Row, FlexAlign, FontWeight, DatePicker, SideBarContainer, SideBar } from '@ohos.arkui.component';

@Entry
@Component
struct MultilingualDatePicker {
  @State selectedDate: Date = new Date();
  @State currentLanguage: string = 'en';
  @State isDrawerOpen: boolean = false;

  private supportedLanguages: string[] = ['en', 'es', 'fr', 'de'];

  private updateDisplayDate(): string {
    const intlObj = new Intl.DateTimeFormat(this.currentLanguage, {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
    return intlObj.format(this.selectedDate);
  }

  private changeLanguage(lang: string): void {
    this.currentLanguage = lang;
    this.isDrawerOpen = false;
  }

  build() {
    Column() {
      Row() {
        Text(this.currentLanguage.toUpperCase())
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ right: 10 });

        Button('Change Language')
          .onClick(() => {
            this.isDrawerOpen = true;
          });
      }
      .justifyContent(FlexAlign.SpaceBetween)
      .width('100%')
      .padding(20);

      Text(this.updateDisplayDate())
        .fontSize(32)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      DatePicker({
        start: new Date('2000-01-01'),
        end: new Date('2030-12-31'),
        selected: this.selectedDate
      })
        .onChange((value: Date) => {
          this.selectedDate = value;
        })
        .width('100%')
        .margin({ bottom: 20 });

      SideBarContainer({
        showSideBar: this.isDrawerOpen,
        sideBarWidth: '60%',
        controlStyle: { position: 'absolute' }
      }) {
        SideBar() {
          Column() {
            ForEach(this.supportedLanguages, (lang: string) => {
              Button(lang.toUpperCase())
                .onClick(() => {
                  this.changeLanguage(lang);
                })
