@Entry
@Component
struct CounterApp {
  @State count: number = 0;
  @State currentPage: number = 0;
  @State languageContent: string[] = ['Hello', 'Bonjour', 'Hola', 'Ciao', 'Hallo'];
  @State animatedText: string = '';

  build() {
    Column() {
      Text(this.animatedText)
        .fontSize(24)
        .margin(10)
        .animation({ duration: 1000, curve: Curve.EaseInOut })

      Row() {
        Button('Prev')
          .onClick(() => {
