              this.currentPage--;
              this.animatedText = this.languageContent[this.currentPage];
            }
          })
          .margin(10)
          .backgroundColor(Color.Blue)
          .fontColor(Color.White)

        Button('Next')
          .onClick(() => {
            if (this.currentPage < this.languageContent.length - 1) {
              this.currentPage++;
              this.animatedText = this.languageContent[this.currentPage];
            }
          })
          .margin(10)
          .backgroundColor(Color.Blue)
          .fontColor(Color.White)
      }
