            this.count++;
          })
          .margin(10)
          .backgroundColor(Color.Green)
          .fontColor(Color.White)

        Button('Decrement')
          .onClick(() => {
            this.count--;
          })
          .margin(10)
          .backgroundColor(Color.Red)
          .fontColor(Color.White)
      }
      .justifyContent(FlexAlign.SpaceEvenly)

      Text(`Count: ${this.count}`)
        .fontSize(24)
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
    .backgroundColor('#ffffff')
    .onAppear(() => {
      this.animatedText = this.languageContent[this.currentPage];
    })
  }
}

@Entry
@Component
struct DocumentScannerApp {
  @State private dividerColor: string = '#000000'
  @State private dividerStrokeWidth: number = 2
  @State private isRefreshing: boolean = false
  @State private content: string = 'Pull down to refresh'
  @State private lastRefreshTime: string = ''

  private toggleDividerStyle() {
    this.dividerColor = this.dividerColor === '#000000' ? '#FF0000' : '#000000'
    this.dividerStrokeWidth = this.dividerStrokeWidth === 2 ? 4 : 2
  }

  private handleRefresh() {
    this.isRefreshing = true
    setTimeout(() => {
      this.content = 'Content refreshed'
      this.lastRefreshTime = new Date().toLocaleTimeString()
      this.isRefreshing = false
    }, 2000)
  }

  build() {
    Column() {
      Text(this.content)
        .fontSize(20)
        .margin({ top: 20 })

      Text(`Last refreshed: ${this.lastRefreshTime}`)
        .fontSize(16)
        .margin({ top: 10 })

      Divider()
        .color(this.dividerColor)
        .strokeWidth(this.dividerStrokeWidth)
        .margin({ top: 20, bottom: 20 })

      Button('Toggle Divider Style')
        .width('80%')
        .height(40)
        .margin({ top: 10 })
        .onClick(() => {
          this.toggleDividerStyle()
        })

      Refresh({
        refreshing: this.isRefreshing
      }) {
        Column() {
          Text('Pull down to refresh')
            .fontSize(16)
            .margin({ top: 20 })
        }
        .width('100%')
        .height('100%')
      }
      .onRefreshing(() => {
        this.handleRefresh()
      })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

import media from '@ohos.multimedia.media';
import promptAction from '@ohos.promptAction';
import { TimePickerResult } from '@ohos.arkui.UIContext';
import { Color } from '@ohos.arkui.drawing';

@Entry
@Component
struct VideoPlayerApp {
  private avPlayer: media.AVPlayer | null = null;
  private avPlayerController: media.AVPlayerController = new media.AVPlayerController();
  @State isPlaying: boolean = false;
  @State currentTime: number = 0;
  @State duration: number = 0;
  @State isMuted: boolean = false;
  @State marqueeText: string = "Sample Marquee Text - Scrolls Right to Left";
  @State marqueeSpeed: number = 50;
  @State showSettings: boolean = false;
  @State scheduledTime: Date = new Date();

  async aboutToAppear() {
    try {
      this.avPlayer = await media.createAVPlayer();
    } catch (error) {
      promptAction.showToast({ message: "Failed to initialize player", duration: 2000 });
    }
  }

  async aboutToDisappear() {
    if (this.avPlayer) {
      await this.avPlayer.release();
      this.avPlayer = null;
    }
  }

  build() {
    Column() {
      Video({
        src: $rawfile('sample.mp4'),
        controller: this.avPlayerController
      })
      .controls(false)
      .autoPlay(false)
      .loop(false)
      .muted(this.isMuted)
      .onPrepared((event) => {
        this.duration = event.duration;
      })
      .onUpdate((event) => {
        this.currentTime = event.time;
      })
      .onError(() => {
        promptAction.showToast({ message: "Video playback error.", duration: 2000 });
      })
      .width("100%")
      .height(300);

      Row() {
        Text(this.marqueeText)
          .fontSize(16)
          .translate({ x: -1000 })
          .animation({
            duration: this.marqueeSpeed * 1000,
            iterations: -1,
            curve: "linear",
            onFinish: () => {
              this.marqueeText = this.marqueeText;
            }
          });
      }
      .width("100%")
      .height(50)
      .clip(true)
      .margin({ top: 20 });

      Row({ space: 10 }) {
        Button(this.isPlaying ? "Pause" : "Play")
          .onClick(async () => {
            if (!this.avPlayer) return;
            if (this.isPlaying) {
              await this.avPlayer.pause();
            } else {
              await this.avPlayer.play();
            }
            this.isPlaying = !this.isPlaying;
          })
          .padding(10);

        Button("Stop")
          .onClick(async () => {
            if (!this.avPlayer) return;
            await this.avPlayer.stop();
            this.isPlaying = false;
          })
          .padding(10);

        Button(this.isMuted ? "Unmute" : "Mute")
          .onClick(() => {
            this.isMuted = !this.isMuted;
          })
          .padding(10);

        Button("Settings")
          .onClick(() => {
            this.showSettings = true;
          })
          .padding(10);
      }
      .margin({ top: 20 });

      Row({ space: 10 }) {
        Text(`Time: ${this.currentTime.toFixed(2)}`);
        Text("/");
        Text(`Duration: ${this.duration.toFixed(2)}`);
      }
      .margin({ top: 10 });

      if (this.showSettings) {
        Column({ space: 20 }) {
          Text("Settings")
            .fontSize(20)
            .margin({ bottom: 20 });

          TimePicker({
            selected: this.scheduledTime,
            onChange: (value: TimePickerResult) => {
              this.scheduledTime = new Date(value.hour, value.minute, value.second);
            }
          });

          Button("Close")
            .onClick(() => {
              this.showSettings = false;
            })
            .width("100%");
        }
        .padding(20)
        .width("80%")
        .height("50%")
        .backgroundColor(Color.White)
        .borderRadius(10)
        .margin({ top: 20 });
      }
    }
    .padding(20)
    .width("100%")
    .height("100%");
  }
}

@Entry
@Component
struct TimerPodcastPlayer {
  @State private timeLeft: number = 60;
  @State private isRunning: boolean = false;
  @State private showSettings: boolean = false;
  @State private timerDuration: number = 60;
  private timerId: number = -1;

  private startTimer() {
    if (!this.isRunning) {
      this.isRunning = true;
      this.timerId = setInterval(() => {
        if (this.timeLeft > 0) {
          this.timeLeft -= 1;
        } else {
          this.stopTimer();
        }
      }, 1000);
    }
  }

  private stopTimer() {
    this.isRunning = false;
    clearInterval(this.timerId);
  }

  private resetTimer() {
    this.stopTimer();
    this.timeLeft = this.timerDuration;
  }

  private openSettings() {
    this.showSettings = true;
  }

  private closeSettings() {
    this.showSettings = false;
  }

  private updateTimerDuration(value: number) {
    this.timerDuration = value;
    this.timeLeft = value;
  }

  build() {
    Column({ space: 10 }) {
      Text(`${this.timeLeft} seconds`)
        .fontSize(24)
        .fontColor(Color.Black)
        .margin(10)
        .width('80%')
        .textAlign(TextAlign.Center)
        .backgroundColor('#ffe5c2c2')
        .padding(10)
        .accessibilityDescription('Time left');

      Row({ space: 20 }) {
        Button(this.isRunning ? 'Stop' : 'Start')
          .onClick(() => {
            if (this.isRunning) {
              this.stopTimer();
            } else {
              this.startTimer();
            }
          })
          .backgroundColor(this.isRunning ? '#ff5722' : '#4caf50')
          .fontColor(Color.White)
          .padding(10)
          .margin(5)
          .borderRadius(5)
          .accessibilityDescription(this.isRunning ? 'Stop timer' : 'Start timer');

        Button('Reset')
          .onClick(() => {
            this.resetTimer();
          })
          .backgroundColor('#2196f3')
          .fontColor(Color.White)
          .padding(10)
          .margin(5)
          .borderRadius(5)
          .accessibilityDescription('Reset timer');

        Button('Settings')
          .onClick(() => {
            this.openSettings();
          })
          .backgroundColor('#9c27b0')
          .fontColor(Color.White)
          .padding(10)
          .margin(5)
          .borderRadius(5)
          .accessibilityDescription('Open settings');
      }
      .justifyContent(FlexAlign.Center)
      .width('80%')
      .margin(10);

      if (this.showSettings) {
        Column() {
          Text('Timer Duration')
            .fontSize(18)
            .margin(5)
            .accessibilityDescription('Timer duration settings');

          Row({ space: 10 }) {
            Button('-')
              .onClick(() => {
                if (this.timerDuration > 1) {
                  this.updateTimerDuration(this.timerDuration - 1);
                }
              })
              .width(40)
              .height(40)
              .accessibilityDescription('Decrease timer duration');

            Text(`${this.timerDuration} seconds`)
              .fontSize(16)
              .accessibilityDescription('Current timer duration');

            Button('+')
              .onClick(() => {
                this.updateTimerDuration(this.timerDuration + 1);
              })
              .width(40)
              .height(40)
              .accessibilityDescription('Increase timer duration');
          }
          .justifyContent(FlexAlign.Center)
          .margin(5);

          Button('Close')
            .onClick(() => {
              this.closeSettings();
            })
            .margin(5)
            .accessibilityDescription('Close settings');
        }
        .width('80%')
        .padding(10)
        .backgroundColor('#f5f5f5')
        .borderRadius(5);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor('#ffffff');
  }
}

