import { Tabs, TabContent, BarPosition, Gesture, GestureType } from '@ohos.arkui.component';
import image from '@ohos.multimedia.image';

interface Scale {
  x: number;
  y: number;
}

interface PinchEvent {
  scale: number;
}

interface PanEvent {
  offsetX: number;
  offsetY: number;
}

@Entry
@Component
struct ExpenseTracker {
  @State imageScale: Scale = { x: 1.0, y: 1.0 };
  @State offsetX: number = 0;
  @State offsetY: number = 0;
  @State activeTab: number = 0;

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.End }) {
        TabContent() {
          Column() {
            Canvas()
              .width('100%')
              .height('60%')
              .onReady(() => {
              })
              .gesture(
                Gesture()
                  .type(GestureType.Pinch)
                  .onPinchUpdate((event: PinchEvent) => {
                    const newScale = Math.max(0.5, Math.min(5, event.scale));
                    this.imageScale = { x: newScale, y: newScale };
                  })
                  .type(GestureType.Pan)
                  .onPanUpdate((event: PanEvent) => {
                    if (this.imageScale.x > 1) {
                      this.offsetX += event.offsetX;
                      this.offsetY += event.offsetY;
                    }
                  })
              )
          }
        }.tabBar('Receipts')

        TabContent() {
          Column() {
            Text('Expenses Tab')
          }
        }.tabBar('Expenses')

        TabContent() {
          Column() {
            Text('Reports Tab')
          }
        }.tabBar('Reports')
      }
    }
  }
}

