import { CalendarController, Calendar } from '@ohos.arkui.advanced.Calendar';
import { PanGesture, GestureEvent, PanDirection } from '@ohos.arkui.advanced.Gesture';
import { Column, Text, FontWeight, Color } from '@ohos.arkui.component';

@Entry
@Component
struct CalendarApp {
  @State selectedDate: Date = new Date()
  @State displayDate: string = ''
  @State currentMonth: Date = new Date()
  private calendarController: CalendarController = new CalendarController()

  aboutToAppear() {
    this.updateDisplayDate()
  }

  updateDisplayDate() {
    this.displayDate = this.selectedDate.toISOString().split('T')[0]
  }

  handleSwipe(direction: string) {
    console.log(`Swipe ${direction} detected`)
    const newMonth = new Date(this.currentMonth)
    if (direction === 'right') {
      newMonth.setMonth(newMonth.getMonth() - 1)
    } else {
      newMonth.setMonth(newMonth.getMonth() + 1)
    }
    this.currentMonth = newMonth
  }

  build() {
    const panGesture = new PanGesture({ direction: PanDirection.Horizontal })
    panGesture.onActionUpdate((event: GestureEvent) => {
      if (event.offsetX > 0) {
        this.handleSwipe('right')
      } else if (event.offsetX < 0) {
        this.handleSwipe('left')
      }
    })

    Column() {
      Text('Calendar')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      Calendar({
        controller: this.calendarController,
        current: this.currentMonth
      })
      .onSelectedChange((date: Date) => {
        this.selectedDate = date
        this.updateDisplayDate()
      })
      .margin({ bottom: 20 })

      Column()
        .gesture(panGesture)
        .width('100%')
        .height(200)

      Column() {
        Text('Selected Date:')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ bottom: 8 })

        Text(this.displayDate)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .fontColor('#007AFF')
      }
      .padding(16)
      .borderRadius(12)
      .backgroundColor('#F0F0F0')
      .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White)
  }
}

import { Column, Text, TextInput, TextArea, Button, List, AlertDialog } from '@ohos.arkui.advanced';
import { FontWeight } from '@ohos.arkui.advanced';
import media from '@ohos.multimedia.media';
import { AVPlayer, AVRecorder, AudioProfile, CodecMimeType, ContainerFormatType, AudioSourceType } from '@ohos.multimedia.media';
import { BusinessError } from '@ohos.base';

interface Note {
  id: number;
  title: string;
  description: string;
  audioPath?: string;
}

@Entry
@Component
struct NoteApp {
  @State notes: Note[] = [];
  @State newTitle: string = '';
  @State newDescription: string = '';
  @State audioRecorder: AVRecorder | null = null;
  @State audioPlayer: AVPlayer | null = null;
  @State isRecording: boolean = false;
  @State currentRecordingPath: string = '';

  build() {
    Column({ space: 10 }) {
      TextInput({ placeholder: 'Enter title...', text: this.newTitle })
        .height(50)
        .width('90%')
        .onChange((value: string) => {
          this.newTitle = value;
        })
        .margin(10);

      TextArea({ placeholder: 'Enter description...', text: this.newDescription })
        .height(100)
        .width('90%')
        .onChange((value: string) => {
          this.newDescription = value;
        })
        .margin(10);

      Button(this.isRecording ? 'Stop Recording' : 'Start Recording')
        .onClick(() => {
          if (this.isRecording) {
            this.stopRecording();
          } else {
            this.startRecording();
          }
        })
        .margin(10);

      Button('Add Note')
        .onClick(() => {
          if (this.newTitle.trim() && this.newDescription.trim()) {
            this.notes.push({
              id: Date.now(),
              title: this.newTitle,
              description: this.newDescription,
              audioPath: this.currentRecordingPath
            });
            this.newTitle = '';
            this.newDescription = '';
            this.currentRecordingPath = '';
          }
        })
        .margin(10);

      List({ space: 10 }) {
        ForEach(this.notes, (note: Note, index?: number) => {
          ListItem() {
            Column({ space: 5 }) {
              Text(note.title)
                .fontSize(18)
                .fontWeight(FontWeight.Bold)
                .margin({ bottom: 5 });

              Text(note.description)
                .fontSize(14)
                .margin({ bottom: 10 });

              if (note.audioPath) {
                Button('Play Audio')
                  .onClick(() => {
                    this.playAudio(note.audioPath!);
                  })
                  .margin({ bottom: 10 });
              }

              Button('Delete')
                .onClick(() => {
                  this.showDeleteConfirmation(note.id);
                })
                .width('100%')
                .margin({ top: 10 });
            }
            .padding(10)
            .width('100%')
          }
        })
      }
      .width('100%')
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }

  private playAudio(path: string): void {
    this.audioPlayer = new AVPlayer();
    if (this.audioPlayer) {
      this.audioPlayer.url = path;
      this.audioPlayer.play();
    }
  }

  private stopRecording(): void {
    if (this.audioRecorder) {
      this.audioRecorder.stop();
      this.audioRecorder.release();
      this.isRecording = false;
    }
  }

  private showDeleteConfirmation(id: number): void {
    AlertDialog.show({
      title: 'Delete Note',
      message: 'Are you sure?',
      buttons: [
        { text: 'Cancel', color: '#000000' },
        { 
          text: 'Delete', 
          action: () => {
            this.notes = this.notes.filter(note => note.id !== id);
          }
        }
      ]
    });
  }

  private startRecording(): void {
    let audioProfile: AudioProfile = {
      audioBitrate: 48000,
      audioChannels: 2,
      audioCodec: CodecMimeType.AUDIO_AAC,
      audioSampleRate: 44100,
      fileFormat: ContainerFormatType.CFT_MPEG_4
    };

    this.audioRecorder = new AVRecorder();
    this.currentRecordingPath = 'path/to/recording.mp3';
    this.isRecording = true;
  }
}

