import webview from '@ohos.web.webview';
import { CanvasRenderingContext2D } from '@ohos.graphics.canvas';

interface RoutePoint {
  x: number;
  y: number;
}

interface PageEndEvent {
  url: string;
}

@Entry
@Component
struct TravelPlanner {
  private webViewController: webview.WebviewController = new webview.WebviewController();
  private canvasContext: CanvasRenderingContext2D | null = null;
  private routePoints: RoutePoint[] = [
    { x: 50, y: 50 },
    { x: 150, y: 100 },
    { x: 250, y: 50 },
    { x: 350, y: 100 }
  ];
  @State private isAnimating: boolean = false;

  private animateRoute() {
    this.isAnimating = true;
    setTimeout(() => {
      this.isAnimating = false;
    }, 2000);
  }

  private drawRoute() {
    if (!this.canvasContext || this.routePoints.length === 0) {
      return;
    }
    const ctx = this.canvasContext;
    ctx.beginPath();
    ctx.moveTo(this.routePoints[0].x, this.routePoints[0].y);
    for (let i = 1; i < this.routePoints.length; i++) {
      ctx.lineTo(this.routePoints[i].x, this.routePoints[i].y);
    }
    ctx.strokeStyle = '#3498db';
    ctx.lineWidth = 3;
    ctx.stroke();
  }

  build() {
    Column() {
      Web({ 
        src: 'https://example.com/travel',
        controller: this.webViewController
      })
      .onPageEnd((event: PageEndEvent) => {
        console.log('Page loaded: ' + event.url);
      })
      .height('40%')
      .margin({ top: 10, bottom: 10 });

      Canvas()
        .width('100%')
        .height(200)
        .onReady(() => {
          this.canvasContext = new CanvasRenderingContext2D();
          this.drawRoute();
        })
        .margin({ top: 10 });

      Button('Plan Route')
        .width('50%')
        .height(40)
        .margin({ top: 20 })
        .onClick(() => {
          this.animateRoute();
        });

      Text(this.isAnimating ? 'Animating...' : 'Ready to plan')
        .fontSize(16)
        .margin({ top: 10 });
    }
    .padding(20)
    .width('100%')
    .height('100%');
  }
}

