        Column() {
          ForEach(this.screens, (item: string, index: number) => {
            Text(item)
              .fontSize(20)
              .padding(16)
              .onClick(() => {
                this.currentScreen = index;
                this.isDrawerOpen = false;
              });
          });
        }
        .width('100%')
        .height('100%');
      }

      Column() {
        Image($r(`app.media.${this.imageResources[this.currentScreen]}`))
          .width(300)
          .height(200);
        Text(`Screen ${this.currentScreen + 1}`)
          .fontSize(24)
          .margin(16);
      }
      .width('100%')
      .height('100%')
      .justifyContent(FlexAlign.Center)
      .alignItems(HorizontalAlign.Center)
      .gesture(
        PanGesture({ fingers: 1 })
          .onActionStart((event: PanGestureEvent) => {
            if (event.offsetX > 0) {
              this.currentScreen = (this.currentScreen - 1 + this.screens.length) % this.screens.length;
            } else {
              this.currentScreen = (this.currentScreen + 1) % this.screens.length;
            }
          })
      );

      Button('Toggle Drawer')
        .onClick(() => {
          this.isDrawerOpen = !this.isDrawerOpen;
        })
        .margin(16);
    }
    .width('100%')
    .height('100%');
  }
}

@Entry
@Component
struct CustomProgressApp {
  @State private progressValue: number = 0;
  @State private rotationAngle: number = 0;

  build() {
    Column({ space: 20 }) {
      Stack() {
        Circle()
          .width(200)
          .height(200)
          .stroke('#E0E0E0')
          .strokeWidth(10)
          .fill('transparent')

        Circle()
          .width(200)
          .height(200)
          .stroke('#007AFF')
          .strokeWidth(10)
          .fill('transparent')
          .strokeDashArray([Math.PI * 200, Math.PI * 200])
          .strokeDashOffset(Math.PI * 200 * (1 - this.progressValue / 100))
          .rotate({ x: 0, y: 0, z: 1, angle: -90 })

        Text(`${Math.round(this.progressValue)}%`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
      }
      .width(200)
      .height(200)
      .gesture(
        RotationGesture()
          .onActionUpdate((event: GestureEvent) => {
            this.rotationAngle = event.angle;
            this.progressValue = Math.min(100, Math.max(0, (this.rotationAngle / 360) * 100));
          })
      )

      Text('Rotate the circle to adjust progress')
        .fontSize(16)
        .fontColor(Color.Black)

      Button('Reset Progress')
        .onClick(() => {
          this.progressValue = 0;
          this.rotationAngle = 0;
        })
        .width('50%')
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20)
  }
}

import { Toggle, ToggleType } from '@ohos.arkui.component.Toggle';
import { RotationGesture, RotationGestureEvent } from '@ohos.arkui.advancedUI.Gesture';
import { Color, FlexAlign } from '@ohos.arkui.advancedUI.Common';

@Entry
@Component
struct MyToggle {
  @State isActive: boolean = false;
  @State rotationAngle: number = 0;

  build() {
    Column({ space: 20 }) {
      Toggle({ type: ToggleType.Switch, isOn: this.isActive })
        .onChange((isOn: boolean) => {
          this.isActive = isOn;
        });

      Divider()
        .strokeWidth(2)
        .color(Color.Black)
        .height(100)
        .width(2)
        .gesture(
          RotationGesture()
            .onActionUpdate((event: RotationGestureEvent) => {
              this.rotationAngle = event.angle;
              if (Math.abs(this.rotationAngle) > 45) {
                this.isActive = !this.isActive;
                this.rotationAngle = 0;
              }
            })
        );

      Text(this.isActive ? 'ON' : 'OFF')
        .fontSize(24)
        .fontColor(this.isActive ? Color.Green : Color.Red);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

@Entry
@Component
struct SwipeListWithDatePicker {
  @State items: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4'];
  @State swipeText: string[] = ['', '', '', ''];
  @State tapCounts: number[] = [0, 0, 0, 0];
  @State showDatePicker: boolean = false;
  @State selectedDate: string = 'No date selected';

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.items, (item: string, index: number) => {
          ListItem() {
            Column() {
              Text(this.swipeText[index] || item)
                .fontSize(16)
                .padding(10);
              Text(`Taps: ${this.tapCounts[index]}`)
                .fontSize(12)
                .padding(5);
            }
          }
          .gesture(
            GestureGroup(
              GestureMode.Sequence,
              PanGesture({ direction: PanDirection.Horizontal })
                .onActionUpdate((event: GestureEvent) => {
                  if (event.offsetX < -100) {
                    this.swipeText[index] = 'Left Swipe Detected';
                  } else if (event.offsetX > 100) {
                    this.swipeText[index] = 'Right Swipe Detected';
                  }
                }),
              TapGesture()
                .onAction(() => {
                  this.tapCounts[index]++;
                })
            )
          );
        });
      }
      .width('100%')
      .height('60%');

      Button('Toggle DatePicker')
        .onClick(() => {
          this.showDatePicker = !this.showDatePicker;
        })
        .margin(10);

      if (this.showDatePicker) {
        DatePicker({
          start: new Date('1970-01-01'),
          end: new Date('2100-01-01'),
          selected: new Date()
        })
        .onDateChange((value: Date) => {
          this.selectedDate = value.toLocaleDateString();
        })
        .margin(10);
      }

      Text(`Selected Date: ${this.selectedDate}`)
        .fontSize(16)
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

import { Tabs, TabContent, List, ListItem, TextInput, Button, Toggle, Row, Column, Text, CustomDialog } from '@ohos.ark.ui';
