interface Habit {
  id: number;
  name: string;
  completed: boolean;
}

@Entry
@Component
struct HabitTracker {
  @State habits: Array<Habit> = [
    { id: 1, name: 'Drink Water', completed: false },
    { id: 2, name: 'Exercise', completed: false },
    { id: 3, name: 'Read', completed: false }
  ];
  @State activeTab: number = 0;
  @State showDialog: boolean = false;
  @State newHabitName: string = '';

  @Builder
  HabitItem(habit: Habit, index: number) {
    Row() {
      Text(habit.name)
        .fontSize(16)
        .margin({ right: 10 });
      Toggle({ type: ToggleType.Checkbox, isOn: habit.completed })
        .onChange((value: boolean) => {
          this.habits[index].completed = value;
          this.habits = [...this.habits];
        });
    }
    .justifyContent(FlexAlign.SpaceBetween)
    .padding(10)
    .borderRadius(5)
    .backgroundColor('#f5f5f5')
    .margin({ bottom: 5 });
  }

  @Builder
  AddHabitDialog() {
    CustomDialog({
      title: 'Add New Habit',
      confirm: {
        value: 'Save',
        action: () => {
          if (this.newHabitName) {
            this.habits.push({
              id: this.habits.length + 1,
              name: this.newHabitName,
              completed: false
            });
            this.habits = [...this.habits];
            this.showDialog = false;
            this.newHabitName = '';
          }
        }
      },
      cancel: () => {
        this.showDialog = false;
        this.newHabitName = '';
      }
    }) {
      Column() {
        TextInput({ placeholder: 'Enter habit name' })
          .onChange((value: string) => {
            this.newHabitName = value;
          })
          .margin({ bottom: 20 });
      }
      .padding(20);
    }
    .onClick(() => {
      this.showDialog = false;
    })
  }

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.Start }) {
        TabContent() {
          List({ space: 10 }) {
            ForEach(this.habits.filter(habit => true), (habit: Habit, index: number) => {
              ListItem() {
                this.HabitItem(habit, index);
              }
            })
          }
          .width('100%')
          .height('100%');
        }
        .tabBar('All Habits');

        TabContent() {
          List({ space: 10 }) {
            ForEach(this.habits.filter(habit => habit.completed), (habit: Habit, index: number) => {
              ListItem() {
                this.HabitItem(habit, index);
              }
            })
          }
          .width('100%')
          .height('100%');
        }
        .tabBar('Completed');

        TabContent() {
          List({ space: 10 }) {
            ForEach(this.habits.filter(habit => !habit.completed), (habit: Habit, index: number) => {
              ListItem() {
                this.HabitItem(habit, index);
              }
            })
          }
          .width('100%')
          .height('100%');
        }
        .tabBar('Pending');
      }
      .width('100%')

      Button('Add Habit', { type: ButtonType.Normal })
        .onClick(() => {
          this.showDialog = true;
        })
        .margin(20);
    }
    .width('100%')
    .height('100%');
  }
}

