import { Slider, Button, Text, Column, Row, Image } from '@ohos.arkui.advanced';

@Entry
@Component
struct FitnessTracker {
  @State isPlaying: boolean = false;
  @State videoProgress: number = 0;
  @State audioProgress: number = 0;
  private videoTimer: number = 0;
  private audioTimer: number = 0;

  aboutToDisappear(): void {
    if (this.videoTimer) {
      clearInterval(this.videoTimer);
    }
    if (this.audioTimer) {
      clearInterval(this.audioTimer);
    }
  }

  togglePlay(): void {
    this.isPlaying = !this.isPlaying;
    if (this.isPlaying) {
      this.videoTimer = setInterval(() => {
        this.videoProgress = (this.videoProgress + 1) % 100;
      }, 100);
      this.audioTimer = setInterval(() => {
        this.audioProgress = (this.audioProgress + 1) % 100;
      }, 100);
    } else {
      if (this.videoTimer) {
        clearInterval(this.videoTimer);
      }
      if (this.audioTimer) {
        clearInterval(this.audioTimer);
      }
    }
  }

  build() {
    Column() {
      Image($r('app.media.ic_public_filled'))
        .width('100%')
        .height('60%')
        .onClick(() => this.togglePlay());

      Row() {
        Text('Video Progress: ' + this.videoProgress + '%')
          .fontSize(12);
        Slider({
          value: this.videoProgress,
          min: 0,
          max: 100
        })
        .width('40%');
      }
      .width('100%')
      .padding(10);

      Row() {
        Text('Audio Progress: ' + this.audioProgress + '%')
          .fontSize(12);
        Slider({
          value: this.audioProgress,
          min: 0,
          max: 100
        })
        .width('40%');
      }
      .width('100%')
      .padding(10);

      Button(this.isPlaying ? 'Pause' : 'Play')
        .width('80%')
        .height('10%')
        .margin(20)
        .onClick(() => this.togglePlay());
    }
    .width('100%')
    .height('100%');
  }
}

