interface PinchEvent {
  scale: number;
  centerX: number;
  centerY: number;
}

@Entry
@Component
struct StarRatingComponent {
  @State rating: number = 0;
  @State selectedColor: string = '#FF0000';
  @State starScale: number = 1.0;

  private colors: string[] = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FF00FF'];

  build() {
    Column() {
      Text(`Rating: ${this.rating}`)
