@Entry
@Component
struct ExpenseTrackerPagination {
  @State private currentPage: number = 1;
  @State private totalPages: number = 5;
  @State private expenseItems: Array<ExpenseItem> = [
    { id: 1, name: 'Groceries', amount: 50, rating: 4 } as ExpenseItem,
    { id: 2, name: 'Dining', amount: 30, rating: 3 } as ExpenseItem,
    { id: 3, name: 'Transport', amount: 20, rating: 5 } as ExpenseItem,
    { id: 4, name: 'Entertainment', amount: 40, rating: 2 } as ExpenseItem,
    { id: 5, name: 'Utilities', amount: 60, rating: 4 } as ExpenseItem
  ];
  @State private isLoading: boolean = false;

  private scroller: Scroller = new Scroller();

  build() {
    Column() {
      List({ scroller: this.scroller }) {
        ForEach(this.expenseItems, (item: ExpenseItem) => {
          ListItem() {
            Row() {
              Column() {
                Text(item.name)
                  .fontSize(18)
                  .fontWeight(FontWeight.Bold)
                  .margin({ bottom: 8 });

                Text(`$${item.amount}`)
                  .fontSize(16)
                  .margin({ bottom: 8 });
              }
              .width('70%')

              Rating({
                rating: item.rating,
                indicator: true
              })
              .stars(5)
              .stepSize(1)
              .width('30%')
              .margin({ left: 16 });
            }
            .padding(16)
            .width('100%')
            .backgroundColor('#f0f0f0')
            .borderRadius(8)
            .margin({ bottom: 8 });
          }
        })
      }
      .width('100%')
      .height('80%')
      .onReachEnd(() => {
        if (!this.isLoading && this.currentPage < this.totalPages) {
          this.loadMoreData();
        }
      })

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentPage > 1) {
              this.currentPage--;
              this.loadPageData();
            }
          })
          .margin({ right: 16 });

        Text(`Page ${this.currentPage} of ${this.totalPages}`)
          .fontSize(16);

        Button('Next')
          .onClick(() => {
            if (this.currentPage < this.totalPages) {
              this.currentPage++;
              this.loadPageData();
            }
          })
          .margin({ left: 16 });
      }
      .justifyContent(FlexAlign.Center)
      .width('100%')
      .margin({ top: 16 })

      if (this.isLoading) {
        Text('Loading...')
          .fontSize(16)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .padding(16)
  }

  loadMoreData() {
    this.isLoading = true;
    setTimeout(() => {
      const newItems: Array<ExpenseItem> = [
        { id: 6, name: 'Clothing', amount: 70, rating: 3 } as ExpenseItem,
        { id: 7, name: 'Healthcare', amount: 45, rating: 4 } as ExpenseItem,
        { id: 8, name: 'Education', amount: 90, rating: 5 } as ExpenseItem,
        { id: 9, name: 'Travel', amount: 120, rating: 2 } as ExpenseItem,
        { id: 10, name: 'Miscellaneous', amount: 25, rating: 1 } as ExpenseItem
      ];
      this.expenseItems = [...this.expenseItems, ...newItems];
      this.currentPage++;
      this.isLoading = false;
    }, 1500);
  }

  loadPageData() {
    this.isLoading = true;
    setTimeout(() => {
      this.isLoading = false;
    }, 1000);
  }
}

import { Grid, GridItem, Column, Row, Button, Text, Image, Video, Popup } from '@ohos.arkui.component';
import { ActionSheet } from '@ohos.arkui.advanced';
import media from '@ohos.multimedia.media';

interface VideoItem {
  id: number;
  title: string;
  url: string;
}

const videos: VideoItem[] = [
  { id: 1, title: 'Video 1', url: 'https://example.com/video1.mp4' },
  { id: 2, title: 'Video 2', url: 'https://example.com/video2.mp4' },
  { id: 3, title: 'Video 3', url: 'https://example.com/video3.mp4' }
];

@Entry
@Component
struct TVVideoPlayer {
  @State currentVideo: VideoItem | null = null;
  @State showControls: boolean = false;
  @State showActionSheet: boolean = false;
  private avPlayer?: media.AVPlayer;

  async aboutToAppear() {
    try {
      this.avPlayer = await media.createAVPlayer();
    } catch (error) {
      console.error('Failed to create AVPlayer:', error);
    }
  }

  build() {
    Column() {
      if (this.currentVideo) {
        this.buildPlayerView();
      } else {
        this.buildLibraryView();
      }
    }
    .width('100%')
    .height('100%');
  }

  @Builder
  buildLibraryView() {
    Grid() {
      ForEach(videos, (video: VideoItem) => {
        GridItem() {
          Column() {
            Image($r('app.media.placeholder'))
              .width(200)
              .height(120);
            Text(video.title)
              .fontSize(16)
              .margin({ top: 8 });
            Button('Play')
              .onClick(() => {
                this.currentVideo = video;
              });
          }
          .padding(10)
          .backgroundColor('#f0f0f0')
          .borderRadius(8);
        }
        .margin(10);
      });
    }
    .columnsTemplate('1fr 1fr 1fr')
    .columnsGap(10)
    .rowsGap(10)
    .padding(20);
  }

  @Builder
  buildPlayerView() {
    Column() {
      Video({
        src: this.currentVideo!.url,
        controller: this.avPlayer
      })
      .width('100%')
      .height(400)
      .onClick(() => {
        this.showControls = !this.showControls;
      });

      if (this.showControls) {
        Popup() {
          Row({ space: 20 }) {
            Button(this.avPlayer?.state === 'playing' ? 'Pause' : 'Play')
              .onClick(() => {
                if (this.avPlayer?.state === 'playing') {
                  this.avPlayer.pause();
                } else {
                  this.avPlayer?.play();
                }
              });
            Button('Stop')
              .onClick(() => {
                this.currentVideo = null;
                this.avPlayer?.stop();
              });
            Button('More')
              .onClick(() => {
                ActionSheet.show({
                  title: 'Options',
                  message: 'Select an option',
                  autoCancel: true,
                  confirm: {
                    value: 'Close',
                    action: () => {
                      this.showActionSheet = false;
                    }
                  },
                  sheets: [
                    { value: 'Quality Settings' },
                    { value: 'Subtitles' }
                  ]
                });
              });
          }
          .padding(10)
          .backgroundColor('#ffffff');
        }
      }
    }
    .width('100%')
    .height('100%');
  }
}

