import { BusinessError } from '@ohos.base';
import abilityAccessCtrl from '@ohos.abilityAccessCtrl';
import common from '@ohos.app.ability.common';
import distributedKVStore from '@ohos.data.distributedKVStore';
import geolocation from '@ohos.geolocation';

interface Location {
  coords: {
    latitude: number;
    longitude: number;
    altitude?: number;
    accuracy?: number;
  };
  time?: number;
}

interface RideData {
  rideType: 'Standard' | 'Premium' | 'Pool';
  location: Location;
  deviceId: string;
}

@Entry
@Component
struct RideSharingApp {
  @State currentLocation: Location = { coords: { latitude: 0, longitude: 0 } };
  @State rideType: 'Standard' | 'Premium' | 'Pool' = 'Standard';
  @State isConnected: boolean = false;
  @State locationHistory: Location[] = [];
  @State showRideSelection: boolean = false;

  private locationInterval: number | null = null;
  private storage: distributedKVStore.SingleKVStore | null = null;

  async aboutToAppear() {
    await this.requestLocationPermissions();
  }

  private async requestLocationPermissions() {
    try {
      const atManager = abilityAccessCtrl.createAtManager();
      const permissions: Array<abilityAccessCtrl.Permissions> = [
        abilityAccessCtrl.Permissions.LOCATION,
        abilityAccessCtrl.Permissions.APPROXIMATELY_LOCATION
      ];
      await atManager.requestPermissionsFromUser(getContext(this), permissions);
    } catch (err) {
      console.error('Failed to request permissions:', err);
    }
  }

  onPageShow() {
    this.initLocationTracking();
    this.initStorage();
  }

  onPageHide() {
    this.stopLocationUpdates();
  }

  private initLocationTracking() {
    try {
      geolocation.getCurrentLocation((err, location) => {
        if (err) {
          console.error('Failed to get location:', err);
          return;
        }
        this.updateLocation(location);
      });
      this.locationInterval = setInterval(() => {
        geolocation.getCurrentLocation((err, location) => {
          if (err) {
