        longitude: location.coords.longitude
      },
      time: Date.now()
    };
    this.locationHistory.push(this.currentLocation);
  }

  private stopLocationUpdates() {
    if (this.locationInterval) {
      clearInterval(this.locationInterval);
      this.locationInterval = null;
    }
  }

