import media from '@ohos.multimedia.media';
import abilityAccessCtrl from '@ohos.abilityAccessCtrl';
import { Column, Text, Button, Progress, Card, Row } from '@ohos.arkui.advanced';

@Entry
@Component
struct VoiceRecorder {
  @State status: string = 'Stopped';
  @State currentTime: string = '00:00';
  @State progress: number = 0;
  private recorder: media.AVRecorder | null = null;
  private player: media.AVPlayer | null = null;
  private timer: number = 0;

  aboutToAppear(): void {
    let permissions: Array<abilityAccessCtrl.Permissions> = [abilityAccessCtrl.Permissions.MICROPHONE];
    try {
      let atManager = abilityAccessCtrl.createAtManager();
      atManager.requestPermissionsFromUser(getContext(this), permissions).then(() => {
        console.log('Permissions granted');
      });
    } catch (err) {
      console.error('Failed to request permissions: ' + JSON.stringify(err));
    }
  }

  aboutToDisappear(): void {
    this.cleanup();
  }

  cleanup(): void {
    if (this.recorder && this.recorder.state === 'started') {
      this.recorder.stop();
      this.recorder.release();
      this.recorder = null;
    }
    if (this.player && this.player.state === 'playing') {
      this.player.stop();
      this.player.release();
      this.player = null;
    }
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = 0;
    }
  }

  formatTime(seconds: number): string {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  }

  async startRecording(): Promise<void> {
    this.cleanup();
    this.recorder = await media.createAVRecorder();
    const profile: media.AVRecorderProfile = {
      audioBitrate: 48000,
      audioChannels: 2,
      audioCodec: media.CodecMimeType.AUDIO_AAC,
      fileFormat: media.ContainerFormatType.CFT_MPEG_4
    };
    const config: media.AVRecorderConfig = {
      audioSourceType: media.AudioSourceType.AUDIO_SOURCE_TYPE_MIC,
      profile: profile,
      url: 'file://data/storage/el2/base/haps/entry/files/recording.mp4'
    };
    (this.recorder as media.AVRecorder).prepare(config).then(() => {
      (this.recorder as media.AVRecorder).start();
      this.status = 'Recording';
      let elapsed = 0;
      this.timer = setInterval(() => {
        elapsed++;
        this.currentTime = this.formatTime(elapsed);
        this.progress = (elapsed % 60) / 60;
      }, 1000);
    }).catch((err: Error) => {
      console.error('Recording failed: ' + err.message);
    });
  }

  stopRecording(): void {
    if (this.recorder && this.recorder.state === 'started') {
      this.recorder.stop();
      this.recorder.release();
      this.recorder = null;
    }
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = 0;
    }
    this.status = 'Stopped';
  }

  async startPlayback(): Promise<void> {
    this.cleanup();
    this.player = await media.createAVPlayer();
    (this.player as media.AVPlayer).url = 'file://data/storage/el2/base/haps/entry/files/recording.mp4';
    (this.player as media.AVPlayer).on('stateChange', (state: string) => {
      if (state === 'playing') {
        this.status = 'Playing';
        let elapsed = 0;
        this.timer = setInterval(() => {
          elapsed++;
          this.currentTime = this.formatTime(elapsed);
          this.progress = (elapsed % 60) / 60;
        }, 1000);
      }
    });
    (this.player as media.AVPlayer).prepare();
  }

  stopPlayback(): void {
    if (this.player && this.player.state === 'playing') {
      this.player.stop();
      this.player.release();
      this.player = null;
    }
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = 0;
    }
    this.status = '

import { Column, Row, Text, TextInput, Button, List, ListItem, Radio } from '@ohos.arkui.advancedUI';
import { InputType } from '@ohos.arkui.text';
