@Entry
@Component
struct SensorEncryptionChart {
  @State sensorData: number[] = [10, 20, 30, 40, 50]
  @State encryptedData: number[] = []
  @State message: string = ''
  @State shift: number = 3

  encryptMessage(): void {
    let result = ''
    for (let i = 0; i < this.message.length; i++) {
      let char = this.message[i]
      if (char.match(/[a-z]/i)) {
        const code = this.message.charCodeAt(i)
        if (code >= 65 && code <= 90) {
          char = String.fromCharCode(((code - 65 + this.shift) % 26) + 65)
        } else if (code >= 97 && code <= 122) {
          char = String.fromCharCode(((code - 97 + this.shift) % 26) + 97)
        }
      }
      result += char
    }
    this.encryptedData = this.sensorData.map(value => value + this.shift)
  }

  build() {
    Column() {
      Text('Sensor Data Encryption')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      TextInput({
        placeholder: 'Enter your message',
        text: this.message
      })
      .width('80%')
      .height(50)
      .backgroundColor('#f5f5f5')
      .onChange((value: string) => {
        this.message = value
      })
      .margin({ bottom: 20 })

      Text('Shift Value: ' + this.shift)
        .fontSize(18)
        .margin({ bottom: 10 })

      Slider({ value: this.shift, min: 1, max: 25, step: 1 })
        .onChange((value: number) => {
          this.shift = value
        })
        .margin({ bottom: 20 })

      Button('Encrypt Data')
        .width('60%')
        .height(50)
        .fontSize(20)
        .onClick(() => this.encryptMessage())
        .margin({ bottom: 20 })

      if (this.encryptedData.length > 0) {
        Text('Encrypted Data: ' + this.encryptedData.join(', '))
          .fontSize(20)
          .fontColor('#4CAF50')
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
      }

      Text('Sensor Data: ' + this.sensorData.join(', '))
        .fontSize(18)
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

