              .margin({ top: 10 })
          }
          .margin({ right: 20 })
        })
      }
      .margin({ top: 50, bottom: 50 })
      .justifyContent(FlexAlign.Center)

      // Step Content
      Column() {
        Text(`Current Step: ${this.currentStep + 1}`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 })

        if (this.currentStep === 0) {
          Text("Step 1: Setup")
            .fontSize(18)
        } else if (this.currentStep === 1) {
          Text("Step 2: Recording")
            .fontSize(18)
        } else {
          Text("Step 3: Playback")
            .fontSize(18)
        }
      }
      .width('100%')
      .height(200)
      .justifyContent(FlexAlign.Center)
      .alignItems(HorizontalAlign.Center)

      // Navigation Buttons
      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentStep > 0) {
              this.currentStep--;
            }
          })
          .enabled(this.currentStep > 0)
          .margin({ right: 20 })

        Button('Next')
          .onClick(() => {
            if (this.currentStep < this.totalSteps - 1) {
              this.currentStep++;
            }
          })
          .enabled(this.currentStep < this.totalSteps - 1)
      }
      .margin({ top: 20 })

      // Audio Controls
      Row() {
        Button(this.isPlaying ? 'Pause' : 'Play')
          .onClick(() => {
            this.isPlaying = !this.isPlaying;
          })
          .margin({ right: 20 })

        Button(this.isRecording ? 'Stop' : 'Record')
          .onClick(() => {
            this.isRecording = !this.isRecording;
          })
      }
      .margin({ top: 20 })

      // BottomSheet Trigger
      Button('Show Controls')
        .onClick(() => {
          this.isBottomSheetVisible = true;
        })
        .margin({ top: 20 })

      // BottomSheet
      if (this.isBottomSheetVisible) {
        Column() {
          Text("Additional Controls")
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 })

          Button('Close')
            .onClick(() => {
              this.isBottomSheetVisible = false;
            })
        }
        .width('100%')
        .height(200)
        .backgroundColor('#FFFFFF')
        .borderRadius(10)
        .padding(20)
        .margin({ top: 20 })
      }

      // TabBar
      Row() {
        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Home')
            .fontSize(12)
        }
        .width('33%')
        .onClick(() => {
          // Handle tab click
        })

        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Record')
            .fontSize(12)
        }
        .width('33%')
        .onClick(() => {
          // Handle tab click
        })

        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Play')
            .fontSize(12)
        }
        .width('33%')
        .onClick(() => {
          // Handle tab click
        })
      }
      .width('100%')
      .height(60)
      .backgroundColor('#F5F5F5')
      .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
