class Contact {
  name: string
  phone: string
  email: string
  address: string

  constructor(name: string, phone: string, email: string, address: string) {
    this.name = name
    this.phone = phone
    this.email = email
    this.address = address
  }
}

@Entry
@Component
struct ContactManager {
  @State contacts: Array<Contact> = [
    new Contact('Alice Smith', '123-456-7890', 'alice@example.com', '123 Main St'),
    new Contact('Bob Johnson', '234-567-8901', 'bob@example.com', '456 Elm St'),
    new Contact('Charlie Brown', '345-678-9012', 'charlie@example.com', '789 Oak St')
  ]

  @State selectedContact: Contact | null = null
  @State isEditing: boolean = false
  @State tempName: string = ''
  @State tempPhone: string = ''
  @State tempEmail: string = ''
  @State tempAddress: string = ''

  @Builder
  ContactItem(contact: Contact) {
    Row() {
      Column() {
        Text(contact.name)
          .fontSize(16)
          .fontWeight(FontWeight.Medium)
        Text(contact.phone)
          .fontSize(14)
          .fontColor(Color.Gray)
      }
    }
    .width('100%')
    .padding(10)
    .backgroundColor(Color.White)
    .onClick(() => {
      this.selectedContact = contact
      this.isEditing = false
      this.tempName = contact.name
      this.tempPhone = contact.phone
      this.tempEmail = contact.email
      this.tempAddress = contact.address
    })
  }

  build() {
    Column() {
      if (this.selectedContact) {
        Column() {
          Text('Contact Details')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 })

          TextInput({ placeholder: 'Name', text: this.tempName })
            .onChange((value: string) => {
              this.tempName = value
            })
            .enabled(this.isEditing)
            .margin({ bottom: 10 })

          TextInput({ placeholder: 'Phone', text: this.tempPhone })
            .onChange((value: string) => {
              this.tempPhone = value
            })
            .enabled(this.isEditing)
            .margin({ bottom: 10 })

          TextInput({ placeholder: 'Email', text: this.tempEmail })
            .onChange((value: string) => {
              this.tempEmail = value
            })
            .enabled(this.isEditing)
            .margin({ bottom: 10 })

          TextInput({ placeholder: 'Address', text: this.tempAddress })
            .onChange((value: string) => {
              this.tempAddress = value
            })
            .enabled(this.isEditing)
            .margin({ bottom: 20 })

          Row() {
            Button(this.isEditing ? 'Save' : 'Edit')
              .onClick(() => {
                if (this.isEditing) {
                  this.selectedContact!.name = this.tempName
                  this.selectedContact!.phone = this.tempPhone
                  this.selectedContact!.email = this.tempEmail
                  this.selectedContact!.address = this.tempAddress
                }
                this.isEditing = !this.isEditing
              })
              .margin({ right: 10 })

            Button('Back')
              .onClick(() => {
                this.selectedContact = null
              })
          }
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
      } else {
        Scroll() {
          Column() {
            ForEach(this.contacts, (contact: Contact) => {
              this.ContactItem(contact)
            })
          }
          .width('100%')
        }
        .scrollBar(BarState.Off)
        .edgeEffect(EdgeEffect.Spring)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
  }
}

import prompt from '@ohos.promptAction';

class Item {
  image: Resource;
  title: string;
  isVideo: boolean;
  badgeCount: number;

  constructor(image: Resource, title: string, isVideo: boolean, badgeCount: number) {
    this.image = image;
    this.title = title;
    this.isVideo = isVideo;
    this.badgeCount = badgeCount;
  }
}

@Entry
@Component
struct EnhancedPhotoEditor {
  @State selectedTitle: string = '';
  @State refreshing: boolean = false;
  private items: Item[] = [
    new Item($r('app.media.app_icon'), 'Image 1', false, 0),
    new Item($r('app.media.app_icon'), 'Video 1', true, 3),
    new Item($r('app.media.app_icon'), 'Image 2', false, 0),
    new Item($r('app.media.app_icon'), 'Video 2', true, 5),
  ];

  private onRefresh() {
    this.refreshing = true;
    setTimeout(() => {
      this.refreshing = false;
    }, 1000);
  }

  build() {
    Column() {
      List() {
        ForEach(this.items, (item: Item) => {
          ListItem() {
            Column() {
              Stack() {
                Image(item.image)
                  .width('100%')
                  .aspectRatio(1)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(5);
                if (item.isVideo) {
                  Text('▶')
                    .fontSize(24)
                    .fontColor(Color.White)
                    .margin(5);
                }
                if (item.badgeCount > 0) {
                  Text(item.badgeCount.toString())
                    .fontSize(12)
                    .fontWeight(FontWeight.Bold)
                    .backgroundColor(Color.Red)
                    .borderRadius(10)
                    .padding(5)
                    .margin(5);
                }
              }
              Text(item.title)
                .fontSize(16)
                .fontWeight(FontWeight.Medium)
                .margin({ top: 5 })
                .textAlign(TextAlign.Center);
            }
            .width('100%')
            .onClick(() => {
              this.selectedTitle = item.title;
              prompt.showDialog({
                title: 'Item Tapped',
                message: `You tapped on: ${this.selectedTitle}`,
                buttons: [
                  {
                    text: 'OK',
                    color: '#000000'
                  }
                ]
              });
            });
          }
        })
      }
      .width('100%')
      .height('100%')
      .onScroll(() => {
        if (!this.refreshing) {
          this.onRefresh();
        }
      });
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5');
  }
}

