interface EventItem {
  id: number
  title: string
  selected: boolean
}

@Entry
@Component
struct CalendarApp {
  @State selectedDate: Date = new Date()
  @State displayDate: string = ''
  @State events: Array<EventItem> = [
    { id: 1, title: 'Meeting', selected: false },
    { id: 2, title: 'Lunch', selected: false },
    { id: 3, title: 'Workout', selected: false }
  ]
  @State currentScale: number = 1.0

  aboutToAppear() {
    this.updateDisplayDate()
  }

  updateDisplayDate() {
    this.displayDate = this.selectedDate.toLocaleDateString()
  }

  toggleEventSelection(id: number) {
    this.events = this.events.map(event => {
      if (event.id === id) {
        return {
          id: event.id,
          title: event.title,
          selected: !event.selected
        }
      }
      return event
    })
  }

  handlePinch(event: PinchGestureEvent) {
    this.currentScale = event.scale
  }

  build() {
    Column() {
      Text('Calendar Widget')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      DatePicker({
        start: new Date('2000-01-01'),
        end: new Date('2030-12-31'),
        selected: this.selectedDate
      })
        .onDateChange((value: Date) => {
          this.selectedDate = value
          this.updateDisplayDate()
        })
        .margin({ bottom: 40 })

      Column() {
        Text('Selected Date:')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ bottom: 8 })

        Text(this.displayDate)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .fontColor('#007AFF')
      }
      .padding(16)
      .borderRadius(12)
      .backgroundColor('#F0F0F0')

      Column() {
        Text('Events:')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ bottom: 8 })

        ForEach(this.events, (event: EventItem) => {
          Row() {
            Text(event.title)
              .fontSize(18)
              .margin({ right: 10 })
            Checkbox()
              .select(event.selected)
              .onChange((checked: boolean) => {
                this.toggleEventSelection(event.id)
              })
          }
          .margin({ bottom: 8 })
        })
      }
      .padding(16)
      .borderRadius(12)
      .backgroundColor('#F0F0F0')
      .scale({ x: this.currentScale, y: this.currentScale })
      .gesture(
        PinchGesture()
          .onActionUpdate((event: PinchGestureEvent) => {
            this.handlePinch(event)
          })
      )

      Column() {
        Text('Document Viewer')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ bottom: 8 })

        Text('Document content goes here...')
          .fontSize(16)
      }
      .padding(16)
      .borderRadius(12)
      .backgroundColor('#F0F0F0')
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White)
  }
}

