@Entry
@Component
struct ProgressTrackerWithTabs {
  @State currentStep: number = 1
  @State activeTab: number = 0
  private totalSteps: number = 4
  private tabs: string[] = ['Progress', 'Details']

  @Builder
  StepCircle(step: number) {
    Stack() {
      Circle()
        .width(40)
        .height(40)
        .fill(this.currentStep >= step ? '#0000FF' : '#CCCCCC')
      Text(step.toString())
        .fontSize(20)
        .fontColor(Color.White)
    }
  }

  build() {
    Column() {
      Row() {
        ForEach(this.tabs, (tab: string, index: number) => {
          Button(tab)
            .onClick(() => {
              this.activeTab = index
            })
            .backgroundColor(this.activeTab === index ? '#0000FF' : '#CCCCCC')
            .margin({ right: 10 })
        })
      }
      .margin({ top: 20, bottom: 20 })

      if (this.activeTab === 0) {
        Column() {
          Row() {
            ForEach([1, 2, 3, 4], (step: number) => {
              Column() {
                this.StepCircle(step)
                Text(`Step ${step}`)
                  .fontSize(16)
                  .margin({ top: 10 })
              }

              if (step < this.totalSteps) {
                Divider()
                  .width(50)
                  .strokeWidth(2)
                  .color(this.currentStep > step ? '#0000FF' : '#CCCCCC')
              }
            })
          }
          .margin({ top: 50, bottom: 50 })

          Row() {
            Button('Previous')
              .onClick(() => {
                if (this.currentStep > 1) {
                  this.currentStep--
                }
              })
              .margin({ right: 20 })
              .enabled(this.currentStep > 1)

            Button('Next')
              .onClick(() => {
                if (this.currentStep < this.totalSteps) {
                  this.currentStep++
                }
              })
              .enabled(this.currentStep < this.totalSteps)
          }

          Progress({ value: (this.currentStep / this.totalSteps) * 100, style: ProgressStyle.Linear })
            .width('80%')
            .margin({ top: 20 })
        }
      } else {
        Text('Details Tab Content')
          .fontSize(20)
          .margin({ top: 50 })
      }
    }
    .width('100%')
    .padding(20)
  }
}

import { CustomDialogController } from '@ohos.arkui.advanced.CustomDialogController';
import { Column, Text, Button, Radio, Flex, RadioGroup } from '@ohos.arkui.advanced.UIComponent';
import { FlexAlign } from '@ohos.arkui.advanced.Common';
import { TapGesture } from '@ohos.arkui.advanced.Gesture';

@Component
struct AlarmConfirmationDialog {
  controller: CustomDialogController;
  @State selectedOption: string = 'Snooze';
  confirmAction: () => void = () => {};
  cancelAction: () => void = () => {};

  build() {
    Column({ space: 10 }) {
      Text('Alarm Action')
        .fontSize(20)
        .margin({ bottom: 10 });

      RadioGroup({ group: 'alarmActions' }) {
        Radio({ value: 'Snooze', checked: this.selectedOption === 'Snooze' })
          .onChange((isChecked: boolean) => {
            if (isChecked) {
              this.selectedOption = 'Snooze';
            }
          })
          .gesture(
            TapGesture()
              .onAction(() => {
                this.selectedOption = 'Snooze';
              })
          )
          .accessibilityDescription('Snooze for 10 minutes');

        Radio({ value: 'Dismiss', checked: this.selectedOption === 'Dismiss' })
          .onChange((isChecked: boolean) => {
            if (isChecked) {
              this.selectedOption = 'Dismiss';
            }
          })
          .gesture(
            TapGesture()
              .onAction(() => {
                this.selectedOption = 'Dismiss';
              })
          )
          .accessibilityDescription('Dismiss the alarm');
      }

      Flex({ justifyContent: FlexAlign.SpaceAround }) {
        Button('Cancel')
          .onClick(() => {
            this.controller.close();
            this.cancelAction?.();
          })
          .backgroundColor('#FF6B6B')
          .fontColor('#FFFFFF')
          .accessibilityDescription('Cancel the alarm action');

        Button('Confirm')
          .onClick(() => {
            this.controller.close();
            this.confirmAction?.();
          })
          .backgroundColor('#4CAF50')
          .fontColor('#FFFFFF')
          .accessibilityDescription('Confirm the alarm action');
      }
      .margin({ top: 20 });
    }
    .padding(20)
    .width('100%');
  }
}

