import window from '@ohos.window';

@Entry
@Component
struct RecipeECommerceApp {
  private context = getContext(this);
  @State angle: number = 0;
  @State rotationText: string = "Rotation Angle: 0°";
  @State isLandscape: boolean = false;

  build() {
    Stack() {
      Column({ space: 20 }) {
        Text(this.rotationText)
          .fontSize(24)
          .fontColor(Color.Black)
          .margin({ bottom: 20 })

        Image($r("app.media.app_icon"))
          .width(150)
          .height(150)
          .rotate({ angle: this.angle })
          .gesture(
            RotationGesture()
              .onActionStart(() => {
                console.info("Rotation started");
              })
              .onActionUpdate((event: RotationGestureEvent) => {
                this.angle = event.angle;
                this.rotationText = `Rotation Angle: ${Math.round(this.angle)}°`;
              })
              .onActionEnd(() => {
                console.info("Rotation ended");
              })
          )

        Text(this.isLandscape ? "Landscape Mode" : "Portrait Mode")
          .fontSize(20)
          .fontColor(Color.Blue)
          .margin({ top: 20 })
      }
      .width('100%')
      .height('100%')
      .justifyContent(FlexAlign.Center)
      .backgroundColor(Color.White)
      .onAppear(async () => {
        await this.checkOrientation();
      })
    }
    .onAreaChange(() => {
      this.checkOrientation();
    })
  }

  private async checkOrientation() {
    try {
      const windowClass = await window.getLastWindow(this.context);
      const properties = await windowClass.getWindowProperties();
      this.isLandscape = properties.windowRect.width > properties.windowRect.height;
    } catch (error) {
      console.error('Failed to get window info: ' + error);
    }
  }
}

import http from '@ohos.net.http';
import { Column, Text, Image, Button, FlexAlign, FontWeight } from '@ohos.arkui.component';

interface MainData {
  temp: number;
}

interface WeatherItem {
  main: string;
  description: string;
}

interface WeatherData {
  main: MainData;
  weather: WeatherItem[];
  name: string;
}

@Entry
@Component
struct WeatherApp {
  @State temperature: string = '';
  @State condition: string = '';
  @State location: string = '';
  @State isLoading: boolean = true;
  @State weatherIcon: Resource = $r('app.media.ic_launcher');

  private apiKey: string = 'YOUR_API_KEY';
  private apiUrl: string = `https://api.openweathermap.org/data/2.5/weather?q=London&appid=${this.apiKey}&units=metric`;

  private httpRequest = http.createHttp();

  fetchWeatherData(): void {
    this.isLoading = true;
    this.httpRequest.request(this.apiUrl, { method: http.RequestMethod.GET })
      .then((response: http.HttpResponse) => {
        if (response.responseCode === http.ResponseCode.OK) {
          const data: WeatherData = JSON.parse(response.result.toString());
          this.temperature = `${Math.round(data.main.temp)}\u00b0C`;
          this.condition = data.weather[0].main;
          this.location = data.name;
          this.updateWeatherIcon(data.weather[0].main);
        }
        this.isLoading = false;
      })
      .catch(() => {
        this.isLoading = false;
      });
  }

  updateWeatherIcon(condition: string): void {
    this.weatherIcon = $r('app.media.ic_launcher');
  }

  build() {
    Column() {
      if (this.isLoading) {
        Text('Loading weather data...')
          .fontSize(20)
          .margin(20)
          .accessibilityDescription('Loading weather data');
      } else {
        Text(this.location)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 })
          .accessibilityDescription(`Location: ${this.location}`)
          .accessibilityImportance('high');

        Image(this.weatherIcon)
          .width(100)
          .height(100)
          .margin({ bottom: 20 })
          .accessibilityDescription(`Weather condition: ${this.condition}`);

        Text(this.temperature)
          .fontSize(32)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 10 })
          .accessibilityDescription(`Temperature: ${this.temperature}`)
          .accessibilityImportance('high');

        Text(this.condition)
          .fontSize(20)
          .margin({ bottom: 20 })
          .accessibilityDescription(`Weather condition: ${this.condition}`);

        Button('Refresh')
          .onClick(() => this.fetchWeatherData())
          .margin({ top: 20 })
          .accessibilityDescription('Refresh weather data')
          .accessibilityImportance('high');
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

import { State } from '@ohos.arkui.UIContext';

interface Flashcard {
  id: number;
  question: string;
  answer: string;
  tags: string[];
  isExpanded: boolean;
}

@Entry
@Component
struct FlashcardManager {
  @State flashcards: Flashcard[] = [
    { id: 1, question: 'What is ArkTS?', answer: 'ArkTS is a programming language for HarmonyOS.', tags: ['HarmonyOS', 'Programming'], isExpanded: false },
    { id: 2, question: 'What is ArkUI?', answer: 'ArkUI is the declarative UI framework for HarmonyOS.', tags: ['UI', 'Framework'], isExpanded: false },
    { id: 3, question: 'What is State?', answer: 'State is a decorator for reactive data in ArkTS.', tags: ['State', 'Reactive'], isExpanded: false }
  ];

  @State currentIndex: number = 0;

  build() {
    Column() {
      List({ space: 12 }) {
        ForEach(this.flashcards, (flashcard: Flashcard, index: number) => {
          ListItem() {
            Column() {
              Row() {
                Text(flashcard.question)
                  .fontSize(18)
                  .fontWeight('bold')
                  .margin({ bottom: 8 });
              }

              if (flashcard.isExpanded) {
                Text(flashcard.answer)
                  .fontSize(16)
                  .margin({ bottom: 8 });
              }

              Row() {
                ForEach(flashcard.tags, (tag: string) => {
                  Text(tag)
                    .fontSize(12)
                    .backgroundColor('#e0e0e0')
                    .borderRadius(12)
                    .padding({ left: 8, right: 8, top: 4, bottom: 4 })
                    .margin({ right: 4 });
                });
              }

              Button(flashcard.isExpanded ? 'Collapse' : 'Expand')
                .onClick(() => {
                  this.flashcards[index].isExpanded = !this.flashcards[index].isExpanded;
                })
                .margin({ top: 8 });
            }
            .width('100%')
            .padding(16)
            .backgroundColor('#ffffff')
            .borderRadius(12)
            .margin({ bottom: 12 });
          }
        });
      }
      .layoutWeight(1)
      .padding(16)
      .backgroundColor('#f5f5f5');

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentIndex > 0) {
              this.currentIndex--;
            }
          })
          .margin({ right: 8 });

        Button('Next')
          .onClick(() => {
            if (this.currentIndex < this.flashcards.length - 1) {
              this.currentIndex++;
            }
          });
      }
      .margin({ top: 16 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }
}

import { Button, Toggle, Column, Row, Text } from '@ohos.arkui.component';
import { ToggleType } from '@ohos.arkui.component';
import { FontWeight, FlexAlign } from '@ohos.arkui.common';

enum Color {
  White = '#FFFFFF',
  Black = '#000000'
}

interface LocalizedText {
  title: string;
  scanButton: string;
  stopButton: string;
  englishButton: string;
  spanishButton: string;
}

interface Localization {
  en: LocalizedText;
  es: LocalizedText;
}

@Entry
@Component
struct DocumentScannerApp {
  @State isScannerActive: boolean = false;
  @State selectedLanguage: string = 'en';

  private localizedText: Localization = {
    en: {
      title: 'Document Scanner',
      scanButton: 'Start Scanning',
      stopButton: 'Stop Scanning',
      englishButton: 'English',
      spanishButton: 'Español'
    },
    es: {
      title: 'Scanner de documentos',
      scanButton: 'Iniciar escaneo',
      stopButton: 'Detener escaneo',
      englishButton: 'English',
      spanishButton: 'Español'
    }
  };

  private toggleScanner(): void {
    this.isScannerActive = !this.isScannerActive;
  }

  private setLanguage(language: string): void {
    this.selectedLanguage = language;
  }

  build() {
    Column() {
      Text(this.selectedLanguage === 'en' ? this.localizedText.en.title : this.localizedText.es.title)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Button(this.isScannerActive ? (this.selectedLanguage === 'en' ? this.localizedText.en.stopButton : this.localizedText.es.stopButton) : (this.selectedLanguage === 'en' ? this.localizedText.en.scanButton : this.localizedText.es.scanButton))
        .onClick(() => this.toggleScanner())
        .width('80%')
        .height(50)
        .backgroundColor('#007AFF')
        .fontColor(Color.White)
        .fontSize(18)
        .margin({ bottom: 20 });

      Toggle({ type: ToggleType.Switch, isOn: this.isScannerActive })
        .onChange((isOn: boolean) => {
          this.isScannerActive = isOn;
        })
        .margin({ bottom: 20 });

      Row() {
        Button(this.selectedLanguage === 'en' ? this.localizedText.en.englishButton : this.localizedText.es.englishButton)
          .onClick(() => this.setLanguage('en'))
          .width('40%')
          .height(40)
          .backgroundColor(this.selectedLanguage === 'en' ? '#007AFF' : '#F5F5F5')
          .fontColor(this.selectedLanguage === 'en' ? Color.White : Color.Black)
          .margin({ right: 10 });

        Button(this.selectedLanguage === 'en' ? this.localizedText.en.spanishButton : this.localizedText.es.spanishButton)
          .onClick(() => this.setLanguage('es'))
          .width('40%')
          .height(40)
          .backgroundColor(this.selectedLanguage === 'es' ? '#007AFF' : '#F5F5F5')
          .fontColor(this.selectedLanguage === 'es' ? Color.White : Color.Black);
      }
      .justifyContent(FlexAlign.Center)
      .width('80%')
      .margin({ bottom: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(FlexAlign.Center)
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

enhanced_prompt:
# Enhanced Prompt

**Create an ArkTS todo list application with the following features:**

1. **Breadcrumb Navigation**:
   - Use the `Breadcrumb` component with `BreadcrumbItem` to show hierarchical navigation ('Home' > 'Todo List')
   - Each breadcrumb item should be clickable and keyboard-navigable (respond to Enter/Space keys)
   - Include proper ARIA labels for accessibility

2. **Todo List Functionality**:
   - Implement a text input field with an "Add" button to create new todo items
   - Display todo items in a scrollable list with:
     - Each item showing its text
     - A "Done" button to mark items as complete
   - Track and display completed/total count (e.g., "Completed: 2/5")

3. **Clear All Confirmation**:
   - Add a "Clear All" button that shows a confirmation dialog before removing all items
   - Dialog should have "Confirm" and "Cancel" options

4. **Technical Requirements**:
   - Use standard HarmonyOS components (no '@ohos.arkui' imports - use '@ohos.arkui.advanced' if needed)
   - Implement proper state management using `@State` decorators
   - Ensure all interactive elements have proper accessibility attributes
   - Follow ArkUI component structure with `@Entry` and `@Component`

5. **Example Structure**:
   ```typescript
   @Entry
   @Component
   struct TodoApp {
     @State items: string[] = [];
     // Other state variables

     build() {
       Column() {
         // Breadcrumb
         // Input row
         // Todo list
         // Clear button
       }
     }
   }
   ```

# Explanation of Changes

1. **Removed Incorrect Imports**: The original prompt didn't specify correct import paths, leading to compilation errors. The enhanced prompt clarifies to use standard HarmonyOS components without '@ohos.arkui'.

2. **Added Structure Guidance**: Included an example component structure to prevent syntax errors and ensure proper ArkTS component architecture.

3. **Detailed Functional Requirements**: Broke down requirements into clear sections (navigation, todo functionality, confirmation) to ensure all aspects are covered.

4. **Added Technical Constraints**: Explicitly mentioned state management and accessibility requirements to prevent common implementation issues.

5. **Improved Clarity**: Reorganized the prompt to flow logically from UI structure to functionality to technical requirements.

These changes would help prevent the compilation errors seen in the feedback while still maintaining all the original functionality requirements. The prompt now better aligns with HarmonyOS development practices and ArkTS syntax conventions.

final_code:
import { Column, Row, Text, Button, TextInput, List, ListItem } from '@ohos.arkui.component';
import prompt from '@ohos.prompt';
import promptAction from '@ohos.promptAction';

interface TodoItem {
  text: string;
  completed: boolean;
}

@Entry
@Component
struct TodoApp {
  @State items: TodoItem[] = [];
  @State newTask: string = '';
  @State showDialog: boolean = false;

  private showClearDialog() {
    prompt.showDialog({
      title: 'Clear All Tasks',
      message: 'Are you sure you want to clear all tasks?',
      buttons: [
        {
          text: 'Cancel',
          color: '#000000',
          action: () => {
            this.showDialog = false;
          }
        },
        {
          text: 'Confirm',
          color: '#FF0000',
          action: () => {
            this.items = [];
            this.showDialog = false;
          }
        }
      ]
    });
  }

  build() {
    Column() {
      Row() {
        Text('Home > Todo List')
          .fontSize(18)
      }
      .margin({ bottom: 20 });

      Row() {
        TextInput({ placeholder: 'Enter a new task', text: this.newTask })
          .onChange((value: string) => {
            this.newTask = value;
          })
          .width('70%');
        Button('Add')
          .onClick(() => {
            if (this.newTask.trim() !== '') {
              this.items.push({
                text: this.newTask.trim(),
                completed: false
              });
              this.newTask = '';
            }
          })
          .width('30%');
      }
      .margin({ bottom: 20 });

      List() {
        ForEach(this.items, (item: TodoItem, index: number) => {
          ListItem() {
            Row() {
              Text(item.text)
                .fontSize(18)
                .margin({ right: 10 });
              Button(item.completed ? 'Undo' : 'Done')
                .onClick(() => {
                  this.items[index].completed = !this.items[index].completed;
                });
            }
            .width('100%');
          }
        }, (item: TodoItem) => JSON.stringify(item));
      }
      .height('60%');

      Text(`Completed: ${this.items.filter(item => item.completed).length}/${this.items.length}`)
        .fontSize(16)
        .margin({ top: 10 });

      Button('Clear All')
        .onClick(() => {
          this.showClearDialog();
        })
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

@Entry
@Component
struct SwipeableTagApp {
  @State tags: string[] = ['Tag 1', 'Tag 2', 'Tag 3', 'Tag 4']
  @State selectedTags: boolean[] = [false, false, false, false]
  @State offsets: number[] = [0, 0, 0, 0]

  handleSwipe(index: number, event: PanGestureEvent) {
    if (event.offsetX < -50) {
      this.offsets[index] = -100
      animateTo({ duration: 300 }, () => {
        this.offsets[index] = -100
      })
    } else if (event.offsetX > 50) {
      this.offsets[index] = 0
      animateTo({ duration: 300 }, () => {
        this.offsets[index] = 0
      })
    }
  }

  toggleSelection(index: number) {
    this.selectedTags[index] = !this.selectedTags[index]
  }

  build() {
    Column() {
      ForEach(this.tags, (tag: string, index: number) => {
        Row() {
          Text(tag)
            .fontSize(18)
            .fontColor(Color.White)
            .padding(10)
            .backgroundColor(Color.Blue)
            .borderRadius(5)
            .width('90%')
          Checkbox()
            .select(this.selectedTags[index])
            .onChange((isSelected: boolean) => {
              this.toggleSelection(index)
            })
            .margin(10)
        }
        .width('90%')
        .margin({ top: 10 })
        .gesture(
          PanGesture({ direction: PanDirection.Horizontal })
            .onActionUpdate((event: PanGestureEvent) => {
              this.handleSwipe(index, event)
            })
        )
        .transform({ translate: { x: this.offsets[index] } })
        .animation({ duration: 300 })
      })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

