import { Refresh } from '@ohos.pullrefresh';
import { CustomDialogController, CustomDialog } from '@ohos.arkui.advancedUI';
import { ImageFit, BorderStyle } from '@ohos.arkui.component';

@Entry
@Component
struct ImageFilterApp {
  @State private images: Resource[] = [
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon')
  ]

  @State private filteredImages: Resource[] = []
  @State private isLoading: boolean = false
  private dialogController: CustomDialogController = new CustomDialogController({
    builder: (): CustomDialog => {
      return CustomDialog({
        title: 'Success',
        message: 'Images filtered successfully!',
        buttons: [
          {
            text: 'OK',
            action: () => {
              this.dialogController.close()
            }
          }
        ]
      })
    }
  })

  build() {
    Column() {
      Button('Apply Filter')
        .onClick(() => {
          this.filterImages()
        })
        .margin(10)

      Refresh({
        isRefreshing: this.isLoading,
        onRefreshing: () => {
          this.refreshImages()
        }
      }) {
        Grid() {
          ForEach(this.filteredImages.length > 0 ? this.filteredImages : this.images, (image: Resource) => {
            GridItem() {
              Image(image)
                .width('100%')
                .aspectRatio(1)
                .objectFit(ImageFit.Cover)
                .border({ width: 2, color: '#000000', radius: 5, style: BorderStyle.Solid })
            }
          })
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsGap(10)
        .columnsGap(10)
        .padding(10)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }

  private filterImages() {
    this.filteredImages = this.images.map(() => $r('app.media.icon'))
    this.dialogController.open()
  }

  private refreshImages() {
    this.isLoading = true
    setTimeout(() => {
      this.isLoading = false
    }, 1000)
  }
}

