import { Column, Text, Button, List, ListItem, ForEach } from '@ohos.arkui.component';
import { State } from '@ohos.arkui.component';
import { Toggle, ToggleType } from '@ohos.arkui.component';
import { Alignment, FontWeight } from '@ohos.arkui.component';
import { Badge, BadgePosition } from '@ohos.arkui.component';

interface Post {
  id: number;
  title: string;
  content: string;
  expanded: boolean;
}

@Entry
@Component
struct SocialMediaApp {
  @State posts: Post[] = [
    { id: 1, title: 'First Post', content: 'This is the content of the first post. It is short.', expanded: false },
    { id: 2, title: 'Second Post', content: 'This is the content of the second post. It is a bit longer and contains more details about the topic.', expanded: false },
    { id: 3, title: 'Third Post', content: 'This is the content of the third post. It is very long and includes multiple paragraphs to demonstrate the expandable feature of the accordion-style list.', expanded: false }
  ];

  @State notificationCount: number = 5;
  @State interactionsEnabled: boolean = true;

  build() {
    Column() {
      Badge({
        count: this.notificationCount,
        position: BadgePosition.RIGHT_TOP
      }) {
        Button() {
          Text('Notifications')
            .fontSize(16)
            .fontWeight(FontWeight.Bold)
        }
        .onClick(() => {
          this.notificationCount = 0;
        })
      }
      .margin({ top: 10, right: 10 })
      .align(Alignment.End)

      Toggle({ type: ToggleType.Switch, isOn: this.interactionsEnabled })
        .onChange((isOn: boolean) => {
          this.interactionsEnabled = isOn;
        })
        .margin({ top: 10 })

      List() {
