import { Toggle, Progress, LoadingProgress, Column, Row, Text, Button, ToggleType } from '@ohos.arkui.advanced';

interface HabitDate {
  date: string;
  completed: boolean;
}

interface Habit {
  name: string;
  dates: Array<HabitDate>;
}

@Entry
@Component
struct HabitTracker {
  @State habits: Array<Habit> = [
    { name: 'Exercise', dates: new Array<HabitDate>() },
    { name: 'Read', dates: new Array<HabitDate>() },
    { name: 'Meditate', dates: new Array<HabitDate>() }
  ]

  @State currentMonth: string = ''
  @State isDrawerOpen: boolean = false
  @State isProcessingPayment: boolean = false

  aboutToAppear() {
    this.generateCurrentMonthDates()
  }

  generateCurrentMonthDates() {
    const now = new Date()
    const year = now.getFullYear()
    const month = now.getMonth()
    const daysInMonth = new Date(year, month + 1, 0).getDate()
    this.currentMonth = `${year}-${month + 1}`

    this.habits.forEach(habit => {
      habit.dates = Array.from({ length: daysInMonth }, (_: never, i: number): HabitDate => {
        return {
          date: `${year}-${month + 1}-${i + 1}`,
          completed: false
        }
      })
    })
  }

  toggleHabitCompletion(habitIndex: number, dateIndex: number) {
    this.habits[habitIndex].dates[dateIndex].completed = !this.habits[habitIndex].dates[dateIndex].completed
  }

  calculateCompletionPercentage(habitIndex: number): number {
    const completedDates = this.habits[habitIndex].dates.filter(date => date.completed).length
    return (completedDates / this.habits[habitIndex].dates.length) * 100
  }

  simulatePayment() {
    this.isProcessingPayment = true
    setTimeout(() => {
      this.isProcessingPayment = false
    }, 2000)
  }

  build() {
    Column() {
      Row() {
        Text('Habit Tracker')
          .fontSize(24)
          .fontWeight(FontWeight.Bolder)
          .margin({ left: 16 })
        Button('Menu')
          .onClick(() => {
            this.isDrawerOpen = !this.isDrawerOpen
          })
          .margin({ right: 16 })
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceBetween)
      .padding({ top: 16, bottom: 16 })

      Column() {
        ForEach(this.habits, (habit: Habit, habitIndex: number) => {
          Column() {
            Text(habit.name)
              .fontSize(18)
              .fontWeight(FontWeight.Bolder)
              .margin({ bottom: 8 })

            Progress({ value: this.calculateCompletionPercentage(habitIndex), total: 100 })
              .width('90%')
              .margin({ bottom: 16 })

            Row() {
              ForEach(habit.dates, (date: HabitDate, dateIndex: number) => {
                Toggle({ type: ToggleType.Switch, isOn: date.completed })
                  .onChange(() => {
                    this.toggleHabitCompletion(habitIndex, dateIndex)
                  })
                  .margin({ right: 8 })
              })
            }
            .margin({ bottom: 16 })
          }
          .width('100%')
          .padding(16)
          .borderRadius(8)
          .backgroundColor('#f5f5f5')
          .margin({ bottom: 16 })
        })
      }
      .width('100%')
      .padding(16)

      if (this.isDrawerOpen) {
        Column() {
          Text('Menu')
            .fontSize(20)
            .fontWeight(FontWeight.Bolder)
            .margin({ top: 16, left: 16, bottom: 16 })

          Button('Process Payment')
            .onClick(() => {
              this.simulatePayment()
            })
            .width('80%')
            .margin({ bottom: 16 })
            .enabled(!this.isProcessingPayment)

          if (this.isProcessingPayment) {
            LoadingProgress()
              .width(32)
              .height(32)
              .margin({ bottom: 16 })
          }

          Button('Close')
            .onClick(() => {
              this.isDrawerOpen = false
            })
            .width('80%')
        }
        .width('60

@Entry
@Component
struct ZoomableImageApp {
  @State scaleValue: number = 1.0
  @State lastScale: number = 1.0
  @State offsetX: number = 0
  @State offsetY: number = 0
  @State initialDistance: number = 0

  build() {
    Column() {
      Stack() {
        Image($r('app.media.app_icon'))
          .objectFit(ImageFit.Contain)
          .width('100%')
          .height('100%')
          .scale({ x: this.scaleValue, y: this.scaleValue })
          .translate({ x: this.offsetX, y: this.offsetY })
          .onTouch((event: TouchEvent) => {
            if (event.touches.length === 2) {
              const touch1 = event.touches[0]
              const touch2 = event.touches[1]
              const currentDistance = Math.sqrt(
                Math.pow(touch2.x - touch1.x, 2) + 
                Math.pow(touch2.y - touch1.y, 2)
              )
              if (this.initialDistance === 0) {
                this.initialDistance = currentDistance
              } else {
                const scaleFactor = currentDistance / this.initialDistance
                this.scaleValue = this.lastScale * scaleFactor
              }
            } else if (event.type === TouchType.Up) {
              this.lastScale = this.scaleValue
              this.initialDistance = 0
            }
          })

        Text(`Zoom: ${this.scaleValue.toFixed(2)}x`)
          .fontSize(20)
          .fontColor('#FFFFFF')
          .backgroundColor('#00000080')
          .padding(10)
          .borderRadius(5)
          .position({ x: 20, y: 20 })
      }
      .width('100%')
      .height('100%')
      .backgroundColor('#F5F5F5')
    }
  }
}

@Entry
@Component
struct QuizApp {
  @State currentQuestionIndex: number = 0;
  @State score: number = 0;
  @State showScore: boolean = false;
  @State showFeedback: boolean = false;
  @State isCorrect: boolean = false;

  private questions: Array<QuizQuestion> = [
    new QuizQuestion(
      'What is the capital of France?',
      ['London', 'Berlin', 'Paris', 'Madrid'],
      2
    ),
    new QuizQuestion(
      'Which planet is closest to the Sun?',
      ['Mars', 'Venus', 'Mercury', 'Jupiter'],
      2
    ),
    new QuizQuestion(
      'What is the largest mammal?',
      ['African Elephant', 'Blue Whale', 'Giraffe', 'Hippopotamus'],
      1
    )
  ];

  checkAnswer(selectedIndex: number) {
    const correct = selectedIndex === this.questions[this.currentQuestionIndex].correctAnswer;
    this.isCorrect = correct;
    if (correct) {
      this.score++;
    }
    this.showFeedback = true;

    setTimeout(() => {
      this.showFeedback = false;
      if (this.currentQuestionIndex < this.questions.length - 1) {
        this.currentQuestionIndex++;
      } else {
        this.showScore = true;
      }
    }, 1000);
  }

  restartQuiz() {
    this.currentQuestionIndex = 0;
    this.score = 0;
    this.showScore = false;
    this.showFeedback = false;
    this.isCorrect = false;
  }

  build() {
    Column() {
      if (!this.showScore) {
        Progress({
          value: ((this.currentQuestionIndex + 1) / this.questions.length) * 100,
          total: 100
        })
          .width('90%')
          .height(10)
          .margin({ top: 20, bottom: 20 });

        Text(`Question ${this.currentQuestionIndex + 1}/${this.questions.length}`)
          .fontSize(16)
          .margin({ bottom: 10 });

        Text(this.questions[this.currentQuestionIndex].question)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .textAlign(TextAlign.Center)
          .margin({ bottom: 40 })
          .padding({ left: 20, right: 20 });

        ForEach(this.questions[this.currentQuestionIndex].options, (option: string, index: number) => {
          Button(option)
            .width('80%')
            .height(50)
            .margin({ bottom: 10 })
            .onClick(() => this.checkAnswer(index));
        });

        if (this.showFeedback) {
          Text(this.isCorrect ? 'Correct!' : 'Incorrect!')
            .fontSize(18)
            .fontColor(this.isCorrect ? Color.Green : Color.Red)
            .margin({ top: 20 });
        }
      } else {
        Text(`Your Score: ${this.score}/${this.questions.length}`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 });

        Button('Restart Quiz')
          .width('50%')
          .height(50)
          .onClick(() => this.restartQuiz());
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

class QuizQuestion {
  question: string;
  options: Array<string>;
  correctAnswer: number;

  constructor(question: string, options: Array<string>, correctAnswer: number) {
    this.question = question;
    this.options = options;
    this.correctAnswer = correctAnswer;
  }
}

@Entry
@Component
struct CountdownTimerWithImageCrop {
  @State private timeLeft: number = 60;
  @State private isRunning: boolean = false;
  @State private selectedImage: Resource = $r('app.media.app_icon');
  @State private showCropOptions: boolean = false;
  private timerId: number = -1;

  private startTimer() {
    if (!this.isRunning) {
      this.isRunning = true;
      this.timerId = setInterval(() => {
        if (this.timeLeft > 0) {
          this.timeLeft -= 1;
        } else {
          this.stopTimer();
        }
      }, 1000);
    }
  }

  private stopTimer() {
    this.isRunning = false;
    clearInterval(this.timerId);
  }

  private resetTimer() {
    this.stopTimer();
    this.timeLeft = 60;
  }

  private openCropOptions() {
    this.showCropOptions = true;
  }

  private closeCropOptions() {
    this.showCropOptions = false;
  }

  private cropImage() {
    this.selectedImage = $r('app.media.app_icon');
    this.closeCropOptions();
  }

  build() {
    Column({ space: 10 }) {
      Text(`${this.timeLeft} seconds`)
        .fontSize(24)
        .fontColor(Color.Black)
        .margin(10)
        .width('80%')
        .textAlign(TextAlign.Center)
        .backgroundColor('#ffe5c2c2')
        .padding(10);

      Image(this.selectedImage)
        .width(200)
        .height(200)
        .margin(10)
        .borderRadius(10);

      Button('Crop Image')
        .onClick(() => this.openCropOptions())
        .backgroundColor('#4caf50')
        .fontColor(Color.White)
        .padding(10)
        .margin(5)
        .borderRadius(5);

      Row({ space: 20 }) {
        Button(this.isRunning ? 'Stop' : 'Start')
          .onClick(() => {
            if (this.isRunning) {
              this.stopTimer();
            } else {
              this.startTimer();
            }
          })
          .backgroundColor(this.isRunning ? '#ff5722' : '#4caf50')
          .fontColor(Color.White)
          .padding(10)
          .margin(5)
          .borderRadius(5);

        Button('Reset')
          .onClick(() => this.resetTimer())
          .backgroundColor('#2196f3')
          .fontColor(Color.White)
          .padding(10)
          .margin(5)
          .borderRadius(5);
      }
      .justifyContent(FlexAlign.Center);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor('#ffffff');
  }
}

