@Entry
@Component
struct DocumentScannerApp {
  @State currentTab: number = 0;
  @State phoneNumber: string = '';
  @State phoneError: string = '';
  @State scanStep: number = 0;
  @State scannedDocuments: Array<string> = [];
  @State showPlaceholder: boolean = true;

  validatePhoneNumber() {
    if (this.phoneNumber.length < 10) {
      this.phoneError = 'Phone number must be at least 10 digits';
      return false;
    }
    if (!/^\d+$/.test(this.phoneNumber)) {
      this.phoneError = 'Phone number must contain only digits';
      return false;
    }
    this.phoneError = '';
    return true;
  }

  handleScanStep() {
    if (this.scanStep < 2) {
      this.scanStep++;
    } else {
      this.scanStep = 0;
      this.scannedDocuments.push('placeholder');
      this.showPlaceholder = false;
    }
  }

  build() {
    Column() {
      Row() {
        Button('Scan')
          .onClick(() => { this.currentTab = 0; })
          .backgroundColor(this.currentTab === 0 ? '#007AFF' : '#CCCCCC')
          .fontColor(Color.White)
          .margin({ right: 10 });

        Button('Authenticate')
          .onClick(() => { this.currentTab = 1; })
          .backgroundColor(this.currentTab === 1 ? '#007AFF' : '#CCCCCC')
          .fontColor(Color.White);
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .margin({ bottom: 20 });

      if (this.currentTab === 0) {
        Column() {
          Text('Document Scanner')
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Step ${this.scanStep + 1}/3`)
            .fontSize(18)
            .margin({ bottom: 10 });

          Button('Next Step')
            .onClick(() => this.handleScanStep())
            .width('80%')
            .height(50)
            .backgroundColor('#007AFF')
            .fontColor(Color.White)
            .margin({ bottom: 20 });

          if (this.showPlaceholder) {
            Column() {
              Text('No Documents Scanned')
                .fontSize(16)
                .fontColor(Color.Gray)
            }
            .width(200)
            .height(200)
            .backgroundColor('#F5F5F5')
            .borderRadius(8)
            .margin({ bottom: 20 });
          } else {
            Grid() {
              ForEach(this.scannedDocuments, (item: string) => {
                GridItem() {
                  Image(item)
                    .width(150)
                    .height(150)
                    .margin(10)
                    .alt('Scanned document')
                    .objectFit(ImageFit.Contain);
                }
              });
            }
            .columnsTemplate('1fr 1fr')
            .rowsTemplate('1fr 1fr')
            .width('100%')
            .height(400);
          }
        }
        .width('100%')
        .height('100%')
        .padding(20);
      } else {
        Column() {
          Text('Phone Authentication')
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          TextInput({ placeholder: 'Enter phone number' })
            .width('80%')
            .height(50)
            .type(InputType.Number)
            .onChange((value: string) => {
              this.phoneNumber = value;
              this.validatePhoneNumber();
            })
            .margin({ bottom: 10 });

          if (this.phoneError) {
            Text(this.phoneError)
              .fontSize(14)
              .fontColor(Color.Red)
              .margin({ bottom: 10 });
          }

          Button('Submit')
            .onClick(() => {
              if (this.validatePhoneNumber()) {
                // Handle successful authentication
              }
            })
            .width('80%')
            .height(50)
            .backgroundColor('#007AFF')
            .fontColor(Color.White);
        }
        .width('100%')
        .height('100%')
        .padding(20);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

