import { PanGesture, PanGestureEvent } from '@ohos.multimodalinput.gesture';
import window from '@ohos.window';
import { FontWeight } from '@ohos.arkui.text';
import { FlexAlign } from '@ohos.arkui.common';
import common from '@ohos.app.ability.common';

@Entry
@Component
struct BookReader {
  @State private currentPage: number = 1;
  @State private totalPages: number = 100;
  @State private isPortrait: boolean = true;
  private context: common.UIAbilityContext = getContext(this) as common.UIAbilityContext;

  private onPanGesture(event: PanGestureEvent) {
    if (event.offsetX > 50 && this.currentPage < this.totalPages) {
      this.currentPage++;
    } else if (event.offsetX < -50 && this.currentPage > 1) {
      this.currentPage--;
    }
  }

  private async updateOrientation() {
    try {
      const windowClass = await window.getLastWindow(this.context);
      const windowSize = windowClass.getWindowProperties().windowRect;
      this.isPortrait = windowSize.width < windowSize.height;
      windowClass.on('windowSizeChange', () => {
        this.updateOrientation();
      });
    } catch (error) {
      console.error('Window operation failed: ' + JSON.stringify(error));
    }
  }

  async aboutToAppear() {
    await this.updateOrientation();
  }

  build() {
    Column() {
      Text(`Page ${this.currentPage} of ${this.totalPages}`)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin(10);

      Row()
        .width(this.isPortrait ? '90%' : '80%')
        .height(this.isPortrait ? '70%' : '60%')
        .backgroundColor('#F5F5F5')
        .gesture(
          PanGesture({ fingers: 1 })
            .onActionStart((event: PanGestureEvent) => {
              this.onPanGesture(event);
            })
        )
        .margin(10);

      Row() {
        Button('Previous')
          .width('60%')
          .backgroundColor('#00FF00')
          .onClick(() => {
            if (this.currentPage > 1) {
              this.currentPage--;
            }
          });

        Button('Next')
          .width('60%')
          .backgroundColor('#00FF00')
          .onClick(() => {
            if (this.currentPage < this.totalPages) {
              this.currentPage++;
            }
          });
      }
      .justifyContent(FlexAlign.SpaceAround)
      .width('100%')
      .margin(10);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

