class Contact {
  name: string;
  phone: string;

  constructor(name: string, phone: string) {
    this.name = name;
    this.phone = phone;
  }
}

@Entry
@Component
struct ContactManagementApp {
  @State contacts: Contact[] = [
    new Contact("John Doe", "123-456-7890"),
    new Contact("Jane Smith", "987-654-3210")
  ];

  @State selectedContact: Contact | null = null;
  @State editable: boolean = false;
  @State tempName: string = "";
  @State tempPhone: string = "";
  @State isNameValid: boolean = true;
  @State isPhoneValid: boolean = true;
  @State performanceTimestamp: string = "";

  validateName(name: string): boolean {
    return name.trim().length > 0;
  }

  validatePhone(phone: string): boolean {
    const phoneRegex = /^\d{3}-\d{3}-\d{4}$/;
    return phoneRegex.test(phone);
  }

  updatePerformanceTimestamp(event: string) {
    this.performanceTimestamp = `${event} at ${new Date().toLocaleTimeString()}`;
  }

  saveContact() {
    if (!this.validateName(this.tempName)) {
      promptAction.showToast({ message: "Name cannot be empty", duration: 2000 });
      return;
    }
    if (!this.validatePhone(this.tempPhone)) {
      promptAction.showToast({ message: "Invalid phone format (XXX-XXX-XXXX)", duration: 2000 });
      return;
    }

    if (this.selectedContact) {
      const index = this.contacts.indexOf(this.selectedContact);
      this.contacts[index] = new Contact(this.tempName, this.tempPhone);
    } else {
      this.contacts.push(new Contact(this.tempName, this.tempPhone));
    }
    this.selectedContact = null;
    this.editable = false;
    this.updatePerformanceTimestamp("Saved contact");
    promptAction.showToast({ message: "Contact saved", duration: 2000 });
  }

  deleteContact() {
    if (this.selectedContact) {
      const index = this.contacts.indexOf(this.selectedContact);
      this.contacts.splice(index, 1);
      this.selectedContact = null;
      this.updatePerformanceTimestamp("Deleted contact");
      promptAction.showToast({ message: "Contact deleted", duration: 2000 });
    }
  }

  build() {
    Column() {
      Text(this.performanceTimestamp)
        .fontSize(14)
        .fontColor(Color.Gray)
        .margin({ bottom: 10 });

      List() {
        ForEach(this.contacts, (contact: Contact, index: number) => {
          ListItem() {
            Row() {
              Text(contact.name)
                .fontSize(18)
                .fontWeight(FontWeight.Medium);
              Text(contact.phone)
                .fontSize(16)
                .fontColor(Color.Gray);
            }
            .onClick(() => {
              this.selectedContact = contact;
              this.editable = false;
              this.tempName = contact.name;
              this.tempPhone = contact.phone;
              this.updatePerformanceTimestamp("Selected contact");
            });
          }
        });
      }
      .height("40%");

      if (this.selectedContact != null) {
        Column() {
          Text("Contact Details")
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text("Name:")
            .fontSize(16)
            .margin({ bottom: 5 });

          TextInput({ placeholder: "Enter name", text: this.tempName })
            .onChange((value: string) => {
              this.tempName = value;
              this.isNameValid = this.validateName(value);
              this.updatePerformanceTimestamp("Name input changed");
            })
            .enabled(this.editable)
            .backgroundColor(this.isNameValid ? "#f5f5f5" : "#ffcccc")
            .margin({ bottom: 10 });

          Text("Phone:")
            .fontSize(16)
            .margin({ bottom: 5 });

          TextInput({ placeholder: "Enter phone", text: this.tempPhone })
            .onChange((value: string) => {
              this.tempPhone = value;
              this.isPhoneValid = this.validatePhone(value);
              this.updatePerformanceTimestamp("Phone input changed");
            })
            .enabled(this.editable)
            .backgroundColor(this.isPhoneValid ? "#f5f5f5" : "#ffcccc")
            .margin({ bottom: 20 });

          Row() {
            Button("Edit")
              .

