interface ExerciseOption {
  value: string;
  label: string;
}

interface WorkoutSession {
  exerciseType: string;
  duration: number;
}

@Entry
@Component
struct FitnessTracker {
  private exerciseOptions: ExerciseOption[] = [
    { value: 'Running', label: 'Running' },
    { value: 'Cycling', label: 'Cycling' },
    { value: 'Swimming', label: 'Swimming' },
    { value: 'Weight Training', label: 'Weight Training' }
  ];

  @State exerciseTypes: ExerciseOption[] = this.exerciseOptions;
  @State selectedIndex: number = 0;
  @State duration: number = 0;
  @State sessions: WorkoutSession[] = [];

  aboutToAppear() {
    const storedSessions = AppStorage.get<WorkoutSession[]>('workout_sessions') || [];
    this.sessions = storedSessions;
  }

  build() {
    Column() {
      Select(this.exerciseTypes)
        .selected(this.selectedIndex)
        .onSelect((index: number) => {
          this.selectedIndex = index;
        })
        .margin(10);

      Text(`Duration: ${this.duration} minutes`)
        .fontSize(20)
        .margin(10);

      Row() {
        Button('+5 min')
          .onClick(() => {
            this.duration += 5;
          })
          .margin(5);

        Button('Reset')
          .onClick(() => {
            this.duration = 0;
          })
          .margin(5);

        Button('Save Session')
          .onClick(() => {
            const newSession: WorkoutSession = {
              exerciseType: this.exerciseTypes[this.selectedIndex].value,
              duration: this.duration
            };
            this.sessions = [...this.sessions, newSession];
            AppStorage.set('workout_sessions', this.sessions);
            this.duration = 0;
          })
          .margin(5);
      }
      .margin(10);

      Text('Session History')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin(10);

      List() {
        ForEach(this.sessions, (session: WorkoutSession) => {
          ListItem() {
            Text(`${session.exerciseType}: ${session.duration} minutes`)
              .fontSize(16)
              .margin(5);
          }
        });
      }
      .layoutWeight(1)
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

