@Component
struct DocumentScanningForm {
  @State documentNumber: string = '';
  @State isDocumentNumberValid: boolean = true;
  @State documentNumberError: string = '';

  @State scanResult: string = '';
  @State isScanning: boolean = false;

  validateDocumentNumber(number: string): string | null {
    const regex = /^[A-Za-z0-9]{8,}$/;
    return regex.test(number) ? null : 'Document number must be at least 8 alphanumeric characters';
  }

  handleScan() {
    this.isScanning = true;
    setTimeout(() => {
      this.scanResult = 'Scanned successfully';
      this.isScanning = false;
    }, 2000);
  }

  build() {
    Column({ space: 20 }) {
      Column() {
        TextInput({ placeholder: 'Document Number' })
          .width('100%')
          .onChange((value: string) => {
            this.documentNumber = value;
            const error = this.validateDocumentNumber(value);
            this.documentNumberError = error || '';
            this.isDocumentNumberValid = !error;
          })
          .border({
            width: 1,
            color: this.isDocumentNumberValid ? '#ddd' : '#ff0000'
          });

        if (this.documentNumberError) {
          Text(this.documentNumberError)
            .fontSize(12)
            .fontColor('#ff0000')
            .margin({ top: 5 });
        }

        Button('Scan Document')
          .enabled(this.isDocumentNumberValid && !this.isScanning)
          .onClick(() => {
            this.handleScan();
          });

        if (this.isScanning) {
          Text('Scanning...')
            .fontSize(14)
            .fontColor('#0000ff');
        }

        if (this.scanResult) {
          Text(this.scanResult)
            .fontSize(14)
            .fontColor('#008000');
        }
      }
    }
    .padding(20)
    .width('100%');
  }
}

