  @State showMenu: boolean = false;
  @State selectedRestaurant: Restaurant | null = null;
  @State menuPosition: Position = { x: 0, y: 0 };

  private restaurants: Restaurant[] = [
    { id: 1, name: 'Italian Bistro', cuisine: 'Italian', rating: 4.5 },
    { id: 2, name: 'Mexican Grill', cuisine: 'Mexican', rating: 4.0 },
    { id: 3, name: 'Sushi Place', cuisine: 'Japanese', rating: 4.7 },
    { id: 4, name: 'Burger Joint', cuisine: 'American', rating: 3.8 },
    { id: 5, name: 'Thai Kitchen', cuisine: 'Thai', rating: 4.2 }
  ];

  build() {
    Column() {
