import { Swiper, SwiperController } from '@ohos.arkui.component.Swiper';
import { Grid, GridItem, Button, Text, Column, Row, Image } from '@ohos.arkui.component';
import { FontWeight, FlexAlign, FlexDirection } from '@ohos.arkui.common';

interface OnboardingStep {
  title: string;
  description: string;
  image: Resource;
}

interface ColorOption {
  name: string;
  value: string;
}

@Entry
@Component
struct TravelPlannerApp {
  private swiperController: SwiperController = new SwiperController();
  @State currentStep: number = 0;
  @State selectedColor: string = '#FF0000';

  private onboardingSteps: OnboardingStep[] = [
    { title: 'Welcome', description: 'Plan your travels with ease!', image: $r('app.media.icon') },
    { title: 'Choose a Color', description: 'Pick your favorite color for the app theme.', image: $r('app.media.icon') },
    { title: 'Swipe Tutorial', description: 'Swipe left or right to navigate.', image: $r('app.media.icon') },
    { title: 'Ready to Go!', description: 'Start planning your next adventure.', image: $r('app.media.icon') }
  ];

  private colors: ColorOption[] = [
    { name: 'Red', value: '#FF0000' },
    { name: 'Blue', value: '#0000FF' },
    { name: 'Green', value: '#00FF00' },
    { name: 'Yellow', value: '#FFFF00' },
    { name: 'Purple', value: '#800080' },
    { name: 'Orange', value: '#FFA500' }
  ];

  build() {
    Column() {
      Swiper(this.swiperController) {
        ForEach(this.onboardingSteps, (step: OnboardingStep, index: number) => {
          Column() {
            Image(step.image)
              .width(200)
              .height(200)
              .margin({ top: 40, bottom: 20 });
            Text(step.title)
              .fontSize(24)
              .fontWeight(FontWeight.Bold)
              .margin({ bottom: 10 });
            Text(step.description)
              .fontSize(16)
              .margin({ bottom: 20 });

            if (index === 1) {
              Grid() {
                ForEach(this.colors, (color: ColorOption) => {
                  GridItem() {
                    Column() {
                      Row()
                        .width(60)
                        .height(60)
                        .backgroundColor(color.value)
                        .borderRadius(30)
                        .border({
                          width: this.selectedColor === color.value ? 4 : 0,
                          color: '#000000'
                        })
                        .margin({ bottom: 8 });
                      Text(color.name)
                        .fontSize(14)
                        .fontColor(this.selectedColor === color.value ? color.value : '#000000');
                    }
                    .onClick(() => {
                      this.selectedColor = color.value;
                    });
                  }
                });
              }
              .columnsTemplate('1fr 1fr 1fr')
              .rowsGap(20)
              .columnsGap(20)
              .padding(20);
            }

            if (index === this.onboardingSteps.length - 1) {
              Button('Get Started')
                .width(200)
                .height(50)
                .margin({ top: 20 })
                .onClick(() => {
                  // Navigate to main app
                });
            } else {
              Button('Next')
                .width(200)
                .height(50)
                .margin({ top: 20 })
                .onClick(() => {
                  this.swiperController.showNext();
                  this.currentStep++;
                });
            }
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center)
          .alignItems(FlexAlign.Center);
        });
      }
      .index(this.currentStep)
      .onChange((index: number) => {
        this.currentStep = index;
      })
      .width('100%')
      .height('100%');
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.selectedColor);
  }
}

import { Swiper, SwiperController } from '@ohos.arkui.component';
import { Toggle, ToggleType } from '@ohos.arkui.component';
import { Image, Column, Row, Text } from '@ohos.arkui.component';
import { ImageFit } from '@ohos.multimedia.image';

@Entry
@Component
struct TravelPlanner {
  private swiperController: SwiperController = new SwiperController();
  @State isPremiumEnabled: boolean = false;
  @State currentFilter: string = 'none';
  @State currentImageIndex: number = 0;

  private destinationImages: Resource[] = [
    $r('app.media.ic_public_picture1'),
    $r('app.media.ic_public_picture2'),
    $r('app.media.ic_public_picture3')
  ];

  private toggleFilter(): void {
    this.currentFilter = this.currentFilter === 'none' ? 'grayscale' : 'none';
  }

  build() {
    Column() {
      Swiper(this.swiperController) {
        ForEach(this.destinationImages, (image: Resource, index: number) => {
          Image(image)
            .width('100%')
            .height(300)
            .objectFit(ImageFit.Cover)
            .borderRadius(16)
            .filter(this.currentFilter === 'grayscale' ? 'grayscale(100%)' : 'none')
            .onClick(() => {
              this.toggleFilter();
              this.currentImageIndex = index;
            });
        });
      }
      .width('100%')
      .height(300)
      .margin({ bottom: 16 })
      .autoPlay(true)
      .interval(3000)
      .indicator(true)
      .loop(true)
      .duration(500)
      .onChange((index: number) => {
        this.currentImageIndex = index;
      });

      Text(`Filter: ${this.currentFilter}`)
        .fontSize(16)
        .margin({ bottom: 16 });

      Row() {
        Text('Enable Premium Features')
          .fontSize(16)
          .margin({ right: 8 });
        Toggle({ type: ToggleType.Switch, isOn: this.isPremiumEnabled })
          .onChange((isOn: boolean) => {
            this.isPremiumEnabled = isOn;
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .margin({ bottom: 16 });
    }
    .width('100%')
    .height('100%')
    .padding(16)
    .backgroundColor('#F5F5F5');
  }
}

