@Entry
@Component
struct ColorPickerMealPlanner {
  @State selectedColor: string = '#FF0000'
  @State progressValue: number = 0
  @State currentScale: number = 1
  private colors: string[] = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FF00FF']

  updateProgress() {
    if (this.progressValue < 100) {
      this.progressValue += 10
      if (this.progressValue <= 30) {
        this.selectedColor = '#FF0000'
      } else if (this.progressValue <= 60) {
        this.selectedColor = '#FFFF00'
      } else {
        this.selectedColor = '#00FF00'
      }
    }
  }

  build() {
    Column() {
      Text('Selected Color: ' + this.selectedColor)
        .fontSize(20)
        .margin({ bottom: 20 })

      Row()
        .width(100)
        .height(100)
        .backgroundColor(this.selectedColor)
        .margin({ bottom: 20 })
        .borderRadius(10)

      Flex({ wrap: FlexWrap.Wrap, justifyContent: FlexAlign.SpaceAround }) {
        ForEach(this.colors, (color: string) => {
          Row()
            .width(50)
            .height(50)
            .backgroundColor(color)
            .borderRadius(25)
            .margin(10)
            .onClick(() => {
              this.selectedColor = color
            })
        })
      }

      Progress({ value: this.progressValue, total: 100 })
        .size({ width: '80%', height: 20 })
        .color(this.selectedColor)
        .margin({ top: 20 })

      Button('Increase Progress')
        .onClick(() => {
          this.updateProgress()
        })
        .margin({ top: 20 })

      Stack() {
        Circle()
          .width(100 * this.currentScale)
          .height(100 * this.currentScale)
          .fill(this.selectedColor)
          .gesture(
            PinchGesture()
              .onActionUpdate((event: GestureEvent) => {
                this.currentScale = event.scale
              })
          )
      }
      .margin({ top: 20 })
    }
    .padding(20)
  }
}

