import { Tabs, TabContent, Button, Image, Column, Row, Text } from '@ohos.arkui.component';
import display from '@ohos.display';

@Entry
@Component
struct WorkoutPlanner {
  @State workouts: string[] = ["Warm-Up", "Cardio", "Strength Training", "Cooldown"];
  @State currentStep: number = 0;
  @State isPlaying: boolean = false;
  @State isPortrait: boolean = true;

  aboutToAppear() {
    this.isPortrait = display.getDefaultDisplaySync().orientation === display.Orientation.PORTRAIT;
  }

  build() {
    Column() {
      Tabs({ index: this.currentStep }) {
        ForEach(this.workouts, (workout: string, index: number) => {
          TabContent() {
            Column() {
              Text(`Step ${index + 1}`)
                .fontSize(24)
                .fontWeight('bold');
              Text(workout)
                .fontSize(20)
                .margin({ top: 16 });
              Image($r('app.media.ic_public_picture'))
                .width(this.isPortrait ? '300vp' : '200vp')
                .height(this.isPortrait ? '300vp' : '200vp')
                .margin({ top: 24 });
              Button(this.isPlaying ? 'Pause' : 'Play')
                .onClick(() => {
                  this.isPlaying = !this.isPlaying;
                })
                .margin({ top: 16 });
            }
            .width('100%')
            .height('100%')
            .padding(16)
            .justifyContent('center');
          }
        });
      }
      .width('100%')
      .height('80%');

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentStep > 0) {
              this.currentStep--;
            }
          })
          .margin({ right: 16 });
        Button('Next')
          .onClick(() => {
            if (this.currentStep < this.workouts.length - 1) {
              this.currentStep++;
            }
          });
      }
      .margin({ top: 16 })
      .justifyContent('center');
    }
    .width('100%')
    .height('100%')
    .padding(16);
  }
}

import sensor from '@ohos.sensor';
import { BusinessError } from '@ohos.base';
import abilityAccessCtrl from '@ohos.abilityAccessCtrl';
import common from '@ohos.app.ability.common';

@Entry
@Component
struct SensorApp {
  @State selectedSensor: string = 'Accelerometer';
  @State sensorData: string = 'No data';
  @State encryptedData: string = '';
  @State isPopupVisible: boolean = false;
  @State currentPage: number = 0;

  private sensorSubscription: sensor.SensorId | null = null;
  private sensorType: number = 1;
  private sensorCallback: (data: sensor.SensorResponse) => void = (data: sensor.SensorResponse) => {
    this.sensorData = 'Sensor data: ' + JSON.stringify(data);
  };

  onPageChange(index: number) {
    this.currentPage = index;
  }

  onSensorChange(value: string) {
    this.selectedSensor = value;
    this.unsubscribeSensor();
    this.subscribeSensor();
  }

  async requestPermissions() {
    try {
      await abilityAccessCtrl.createAtManager().requestPermissionsFromUser(
        this.context as common.Context,
        ['ohos.permission.ACCELEROMETER', 'ohos.permission.GYROSCOPE']
      );
    } catch (err) {
      console.error('Failed to request permissions: ' + (err as BusinessError).message);
    }
  }

  subscribeSensor() {
    switch (this.selectedSensor) {
      case 'Accelerometer':
        this.sensorType = 1;
        break;
      case 'Gyroscope':
        this.sensorType = 2;
        break;
      case 'Light':
        this.sensorType = 5;
        break;
    }

    try {
      if (globalThis.abilityContext) {
        this.sensorSubscription = sensor.on(this.sensorType, this.sensorCallback);
      } else {
        this.sensorData = 'Mock sensor data';
      }
    } catch (error) {
      console.error('Failed to subscribe to sensor: ' + (error as BusinessError).message);
    }
  }

  unsubscribeSensor() {
    if (this.sensorSubscription !== null && globalThis.abilityContext) {
      try {
        sensor.off(this.sensorType, this.sensorCallback);
      } catch (error) {
        console.error('Failed to unsubscribe sensor: ' + (error as BusinessError).message);
      }
      this.sensorSubscription = null;
    }
  }

  encryptData() {
    this.encryptedData = 'Encrypted: ' + this.sensorData;
    this.isPopupVisible = true;
  }

  build() {
    Column() {
      Segmented({ selected: 0 }) {
        ForEach(['Accelerometer', 'Gyroscope', 'Light'], (item: string) => {
          Text(item)
        })
      }
      .onChange((index: number) => {
        this.onSensorChange(['Accelerometer', 'Gyroscope', 'Light'][index]);
      })
      .margin(10);

      Swiper() {
        Column() {
          Text('Sensor Data: ' + this.sensorData)
            .fontSize(16)
            .margin(10);
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center);

        Column() {
          Button('Encrypt Data')
            .onClick(() => {
              this.encryptData();
            })
            .margin(10);
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center);

        Column() {
          Text('Settings Placeholder')
            .fontSize(16)
            .margin(10);
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center);
      }
      .index(this.currentPage)
      .onChange((index: number) => {
        this.onPageChange(index);
      })
      .width('100%')
      .height('60%');

      if (this.isPopupVisible) {
        Column() {
          Text(this.encryptedData)
            .fontSize(16)
            .margin(10);
          Button('Close')
            .onClick(() => {
              this.isPopupVisible = false;
            })
            .margin(10);
        }
        .width('80%')
        .padding(20)
        .popup(true)
        .onDismiss(() => {
          this.isPopupVisible = false;
        });
      }
    }
    .width('100%')
    .height('100%')
  }
}

interface QuizOption {
  id: string;
  text: string;
  selected: boolean;
}

interface QuizQuestion {
  id: string;
  text: string;
  options: QuizOption[];
}

@Entry
@Component
struct QuizApp {
  @State questions: QuizQuestion[] = [
    {
      id: 'quiz_question_1',
      text: 'What is the capital of France?',
      options: [
        { id: 'checkbox_1', text: 'Berlin', selected: false },
        { id: 'checkbox_2', text: 'Madrid', selected: false },
        { id: 'checkbox_3', text: 'Paris', selected: false },
        { id: 'checkbox_4', text: 'Rome', selected: false }
      ]
    },
    {
      id: 'quiz_question_2',
      text: 'Which planet is known as the Red Planet?',
      options: [
        { id: 'checkbox_5', text: 'Venus', selected: false },
        { id: 'checkbox_6', text: 'Mars', selected: false },
        { id: 'checkbox_7', text: 'Jupiter', selected: false },
        { id: 'checkbox_8', text: 'Saturn', selected: false }
      ]
    }
  ];

  @State currentQuestionIndex: number = 0;

  toggleOption(questionId: string, optionId: string) {
    this.questions = this.questions.map(question => {
      if (question.id === questionId) {
        const newOptions = question.options.map(option => {
          if (option.id === optionId) {
            return { id: option.id, text: option.text, selected: !option.selected };
          }
          return option;
        });
        return { id: question.id, text: question.text, options: newOptions };
      }
      return question;
    });
  }

  loadNextQuestion() {
    if (this.currentQuestionIndex < this.questions.length - 1) {
      this.currentQuestionIndex++;
    }
  }

  build() {
    Column() {
      Text(this.questions[this.currentQuestionIndex].text)
        .fontSize(24)
        .margin(16);

      ForEach(this.questions[this.currentQuestionIndex].options, (option: QuizOption) => {
        Row() {
          Checkbox({ name: option.id })
            .select(option.selected)
            .onChange((checked: boolean) => {
              this.toggleOption(this.questions[this.currentQuestionIndex].id, option.id);
            })
            .margin(8);

          Text(option.text)
            .fontSize(18)
            .margin(8);
        }
        .width('100%')
        .justifyContent(FlexAlign.Start);
      });

      Button('Next Question')
        .onClick(() => {
          this.loadNextQuestion();
        })
        .margin(16);
    }
    .width('100%')
    .height('100%')
    .padding(16);
  }
}

@Entry
@Component
struct PaginationExample {
  @State listData: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4', 'Item 5']
  @State isLoading: boolean = false
  private scroller: Scroller = new Scroller()

  build() {
    Column() {
      List({ scroller: this.scroller }) {
        ForEach(this.listData, (item: string) => {
          ListItem() {
            Text(item)
              .fontSize(18)
              .padding(16)
              .backgroundColor('#f0f0f0')
              .width('100%')
          }
        })
      }
      .width('100%')
      .height('90%')
      .onReachEnd(() => {
        if (!this.isLoading) {
          this.loadMoreData()
        }
      })

      if (this.isLoading) {
        Text('Loading more...')
          .fontSize(16)
          .padding(16)
      }
    }
    .width('100%')
    .height('100%')
  }

  loadMoreData() {
    this.isLoading = true
    setTimeout(() => {
      const newItems = ['Item 6', 'Item 7', 'Item 8', 'Item 9', 'Item 10']
      this.listData = [...this.listData, ...newItems]
      this.isLoading = false
    }, 2000)
  }
}

