@Entry
@Component
struct MessageForm {
  @State form_sender: string = ''
  @State form_recipient: string = ''
  @State form_message: string = ''
  @State errorMessage: string = ''
  @State successMessage: string = ''

  validateForm(): boolean {
    if (!this.form_sender || !this.form_recipient || !this.form_message) {
      this.errorMessage = 'Please fill in all fields'
      return false
    }
    this.errorMessage = ''
    return true
  }

  build() {
    Column({ space: 20 }) {
      Text('Messaging Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 })

      TextInput({ placeholder: 'Sender' })
        .onChange((value: string) => {
          this.form_sender = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Recipient' })
        .onChange((value: string) => {
          this.form_recipient = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Message' })
        .onChange((value: string) => {
          this.form_message = value
        })
        .margin({ bottom: 30 })

      Button('Send Message')
        .onClick(() => {
          if (this.validateForm()) {
            this.successMessage = 'Message sent successfully!'
            this.form_sender = ''
            this.form_recipient = ''
            this.form_message = ''
          }
        })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 10 })
      }

      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(18)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

