import { Gesture } from '@ohos.arkui.gesture';

interface Workout {
  id: string;
  name: string;
  duration: string;
  calories: string;
  date: string;
}

@Entry
@Component
struct FitnessTracker {
  @State workouts: Workout[] = [
    { id: '1', name: 'Morning Run', duration: '45 mins', calories: '320 cal', date: 'Today, 7:30 AM' },
    { id: '2', name: 'Evening Walk', duration: '30 mins', calories: '150 cal', date: 'Today, 6:00 PM' },
    { id: '3', name: 'Yoga Session', duration: '60 mins', calories: '200 cal', date: 'Yesterday, 8:00 AM' }
  ];
  @State zoomLevel: number = 1.0;
  @State refreshing: boolean = false;

  private onRefresh(): void {
    this.refreshing = true;
    setTimeout(() => {
      this.workouts = [...this.workouts, { id: '4', name: 'New Workout', duration: '50 mins', calories: '250 cal', date: 'Just now' }];
      this.refreshing = false;
    }, 1000);
  }

  private onPinch(event: GestureEvent): void {
    const newZoom = Math.max(0.8, Math.min(1.5, this.zoomLevel * event.scale));
    this.zoomLevel = newZoom;
  }

  build() {
    Column() {
      Text('Fitness Tracker')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 16, bottom: 16 });

      Refresh({ refreshing: this.refreshing }) {
        Gesture(Gesture.Pinch)
          .onPinchUpdate((event: GestureEvent) => this.onPinch(event))
          .onPinchEnd(() => {})
        {
          List() {
            ForEach(this.workouts, (workout: Workout) => {
              ListItem() {
                Column() {
                  Text(workout.name)
                    .fontSize(18 * this.zoomLevel)
                    .fontWeight(FontWeight.Bold);
                  Row() {
                    Text(workout.duration)
                      .fontSize(14 * this.zoomLevel);
                    Text(workout.calories)
                      .fontSize(14 * this.zoomLevel)
                      .margin({ left: 8 });
                  }
                  Text(workout.date)
                    .fontSize(12 * this.zoomLevel)
                    .margin({ top: 4 });
                }
                .padding(16)
                .backgroundColor('#F5F5F5')
                .borderRadius(8)
                .margin({ bottom: 8 })
              }
            })
          }
          .width('100%')
          .height('100%')
        }
      }
      .onRefresh(() => this.onRefresh())
    }
    .width('100%')
    .height('100%')
    .padding(16)
  }
}

@Entry
@Component
struct WaterIntakeTracker {
  @State waterIntake: number = 0
  @State dailyGoal: number = 2000
  @State progress: number = 0
  @State showReminders: boolean = false
  @State inputValue: string = ''
  @State isInputValid: boolean = true

  updateProgress() {
    this.progress = (this.waterIntake / this.dailyGoal) * 100
    if (this.progress > 100) this.progress = 100
  }

  logIntake() {
    const amount = parseInt(this.inputValue)
    if (!isNaN(amount) && amount > 0) {
      this.waterIntake += amount
      this.updateProgress()
      this.inputValue = ''
      this.isInputValid = true
    } else {
      this.isInputValid = false
    }
  }

  build() {
    Column() {
      Text('Water Intake Tracker')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin(20)

      Text(`Goal: ${this.dailyGoal} ml`)
        .fontSize(18)
        .margin(10)

      Text(`Consumed: ${this.waterIntake} ml`)
        .fontSize(18)
        .margin(10)

      Stack() {
        Circle()
          .width(200)
          .height(200)
          .stroke('#E0E0E0')
          .strokeWidth(15)
          .fill('transparent')

        Circle()
          .width(200)
          .height(200)
          .stroke('#4CAF50')
          .strokeWidth(15)
          .fill('transparent')
          .strokeDashArray([Math.PI * 200, Math.PI * 200])
          .strokeDashOffset(Math.PI * 200 * (1 - this.progress / 100))
          .rotate({ x: 0, y: 0, z: 1, angle: -90 })

        Text(`${Math.round(this.progress)}%`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
      }
      .width(200)
      .height(200)
      .margin({ top: 50 })

      Toggle({ type: ToggleType.Switch, isOn: this.showReminders })
        .onChange((isOn: boolean) => {
          this.showReminders = isOn
        })
        .margin(20)

      TextInput({ placeholder: 'Enter ml amount' })
        .width(200)
        .height(40)
        .margin(10)
        .borderColor(this.isInputValid ? '#CCCCCC' : '#FF0000')
        .borderWidth(1)
        .onChange((value: string) => {
          this.inputValue = value
        })

      Button('Log Intake')
        .onClick(() => this.logIntake())
        .width(200)
        .height(50)
        .margin({ top: 20 })

      Button('Reset')
        .onClick(() => {
          this.waterIntake = 0
          this.updateProgress()
        })
        .width(200)
        .height(50)
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

