import { Column, Row, Text, Button, Toggle, ToggleType } from '@ohos.arkui.advanced';
import { animateTo } from '@ohos.animation';
import { PanGesture } from '@ohos.gesture';

interface SwipeEvent {
  offsetX: number;
  offsetY?: number;
  type?: number;
}

interface GestureEvent {
  offsetX: number;
  offsetY: number;
  velocityX?: number;
  velocityY?: number;
}

@Entry
@Component
struct CustomToast {
  @State isVisible: boolean = false;
  @State offsetX: number = 0;
  @State selectedOption: string = 'Option 1';

  private dismissToast() {
    animateTo({ duration: 300 }, () => {
      this.offsetX = 0;
      this.isVisible = false;
    });
  }

  private handleSwipe(event: SwipeEvent) {
    if (Math.abs(event.offsetX) > 50) {
      animateTo({ duration: 300 }, () => {
        this.offsetX = event.offsetX > 0 ? 200 : -200;
        this.isVisible = false;
      });
    }
  }

  build() {
    Column() {
      Button('Show Toast')
        .onClick(() => {
          this.isVisible = true;
          this.offsetX = 0;
        })
        .margin({ bottom: 20 });

      if (this.isVisible) {
        Column()
          .width('80%')
          .height(100)
          .backgroundColor('#FFD700')
          .borderRadius(10)
          .justifyContent(FlexAlign.Center)
          .alignItems(HorizontalAlign.Center)
          .gesture(
            PanGesture()
              .onActionUpdate((event: GestureEvent) => {
                this.offsetX = event.offsetX;
              })
              .onActionEnd(() => {
                this.handleSwipe({ offsetX: this.offsetX, type: 1 });
              })
          )
          .onClick(() => {
            this.dismissToast();
          })
          .transform({ translate: { x: this.offsetX } })
          .animation({ duration: 300 })
          .children([
            Text('This is a custom toast')
              .fontSize(16)
              .textAlign(TextAlign.Center),
            Row()
              .margin({ top: 10 })
              .children([
                Toggle({ type: ToggleType.Radio, isOn: this.selectedOption === 'Option 1' })
                  .onChange((isOn: boolean) => {
                    if (isOn) this.selectedOption = 'Option 1';
                  }),
                Text('Option 1')
                  .margin({ left: 5 }),
                Toggle({ type: ToggleType.Radio, isOn: this.selectedOption === 'Option 2' })
                  .onChange((isOn: boolean) => {
                    if (isOn) this.selectedOption = 'Option 2';
                  }),
                Text('Option 2')
                  .margin({ left: 5 })
              ])
          ]);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

