class Contact {
  name: string;
  phone: string;
  email: string;
  address: string;

  constructor(name: string, phone: string, email: string, address: string) {
    this.name = name;
    this.phone = phone;
    this.email = email;
    this.address = address;
  }
}

@Entry
@Component
struct ContactManager {
  @State contacts: Array<Contact> = [
    new Contact('Alice Smith', '123-456-7890', 'alice@example.com', '123 Main St'),
    new Contact('Bob Johnson', '234-567-8901', 'bob@example.com', '456 Elm St'),
    new Contact('Charlie Brown', '345-678-9012', 'charlie@example.com', '789 Oak St')
  ];

  @State selectedContact: Contact | null = null;
  @State isABTesting: boolean = false;
  @State editMode: boolean = false;
  @State editedContact: Contact = new Contact('', '', '', '');
  @State nameError: string = '';
  @State phoneError: string = '';
  @State emailError: string = '';

  validateName(name: string): boolean {
    if (!name.trim()) {
      this.nameError = 'Name cannot be empty';
      return false;
    }
    this.nameError = '';
    return true;
  }

  validatePhone(phone: string): boolean {
    const phoneRegex = /^\d{3}-\d{3}-\d{4}$/;
    if (!phoneRegex.test(phone)) {
      this.phoneError = 'Invalid phone format (xxx-xxx-xxxx)';
      return false;
    }
    this.phoneError = '';
    return true;
  }

  validateEmail(email: string): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      this.emailError = 'Invalid email format';
      return false;
    }
    this.emailError = '';
    return true;
  }

  saveContact(): void {
    if (!this.validateName(this.editedContact.name)) return;
    if (!this.validatePhone(this.editedContact.phone)) return;
    if (!this.validateEmail(this.editedContact.email)) return;

    if (this.selectedContact) {
      const index = this.contacts.indexOf(this.selectedContact);
      this.contacts[index] = new Contact(
        this.editedContact.name,
        this.editedContact.phone,
        this.editedContact.email,
        this.editedContact.address
      );
    } else {
      this.contacts.push(new Contact(
        this.editedContact.name,
        this.editedContact.phone,
        this.editedContact.email,
        this.editedContact.address
      ));
    }
    this.editMode = false;
    this.selectedContact = null;
  }

  @Builder
  ContactItem(contact: Contact) {
    ListItem() {
      Row() {
        Column() {
          Text(contact.name)
            .fontSize(16)
            .fontWeight(FontWeight.Medium);
          Text(contact.phone)
            .fontSize(14)
            .fontColor(Color.Gray);
        }
      }
      .width('100%')
      .padding(10)
      .backgroundColor(Color.White)
      .onClick(() => {
        this.selectedContact = contact;
        this.editedContact = new Contact(
          contact.name,
          contact.phone,
          contact.email,
          contact.address
        );
      });
    }
  }

  build() {
    Column() {
      Row() {
        Text('Contact Manager')
          .fontSize(24)
          .fontWeight(FontWeight.Bold);
        Switch({ type: SwitchType.Toggle })
          .isOn(this.isABTesting)
          .onChange((isOn: boolean) => {
            this.isABTesting = isOn;
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceBetween)
      .padding(10);

      if (this.editMode) {
        Column() {
          TextInput({ placeholder: 'Name', text: this.editedContact.name })
            .width('100%')
            .onChange((value: string) => {
              this.editedContact.name = value;
              this.validateName(value);
            });
          if (this.nameError) {
            Text(this.nameError)
              .fontSize(12)
              .fontColor(Color.Red);

