@Entry
@Component
struct StopwatchApp {
    @State elapsedTime: number = 0
    @State isRunning: boolean = false
    @State currentTab: number = 0
    @State laps: Array<string> = []
    private timerId: number = -1

    private formatTime(time: number): string {
        const minutes = Math.floor(time / 6000)
        const seconds = Math.floor((time % 6000) / 100)
        const centiseconds = time % 100
        return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}.${centiseconds.toString().padStart(2, '0')}`
    }

    build() {
        Column() {
            Tabs({ barPosition: BarPosition.End }) {
                TabContent() {
                    Column() {
                        Text(this.formatTime(this.elapsedTime))
                            .fontSize(40)
                            .margin({ top: 20, bottom: 20 })

                        Row() {
                            Button(this.isRunning ? 'Stop' : 'Start')
                                .onClick(() => {
                                    if (this.isRunning) {
                                        clearInterval(this.timerId)
                                    } else {
                                        this.timerId = setInterval(() => {
                                            this.elapsedTime += 1
                                        }, 10)
                                    }
                                    this.isRunning = !this.isRunning
                                })
                                .margin(10)

                            Button('Reset')
                                .onClick(() => {
                                    clearInterval(this.timerId)
                                    this.elapsedTime = 0
                                    this.isRunning = false
                                })
                                .margin(10)

                            Button('Lap')
                                .onClick(() => {
                                    this.laps.push(this.formatTime(this.elapsedTime))
                                })
                                .margin(10)
                        }
                    }
                    .width('100%')
                    .height('100%')
                    .justifyContent(FlexAlign.Center)
                }
                .tabBar('Stopwatch')

                TabContent() {
                    List() {
                        ForEach(this.laps, (lap: string, index: number) => {
                            ListItem() {
                                Column() {
                                    Text(`Lap ${index + 1}: ${lap}`)
                                        .margin({ top: 10, bottom: 10 })
                                }
                            }
                        })
                    }
                    .width('100%')
                    .height('100%')
                }
                .tabBar('Laps')
            }
            .animation({ duration: 300, curve: Curve.EaseInOut })
        }
        .width('100%')
        .height('100%')
    }
}

