interface Question {
  question: string
  options: string[]
  correctAnswer: number
}

@Entry
@Component
struct QuizApp {
  @State currentQuestionIndex: number = 0
  @State score: number = 0
  @State selectedOption: number = -1
  @State isAnimating: boolean = false

  private questions: Question[] = [
    {
      question: "What is the capital of France?",
      options: ["Berlin", "Madrid", "Paris", "Rome"],
      correctAnswer: 2
    },
    {
      question: "Which planet is known as the Red Planet?",
      options: ["Venus", "Mars", "Jupiter", "Saturn"],
      correctAnswer: 1
    }
  ]

  private animateOption(index: number) {
    this.isAnimating = true
    this.selectedOption = index
    setTimeout(() => {
      this.isAnimating = false
      const currentQuestion = this.questions[this.currentQuestionIndex]
      if (index === currentQuestion.correctAnswer) {
        this.score += 1
      }
      if (this.currentQuestionIndex < this.questions.length - 1) {
        this.currentQuestionIndex += 1
        this.selectedOption = -1
      }
    }, 1000)
  }

  build() {
    Column() {
      Text(`Question ${this.currentQuestionIndex + 1}/${this.questions.length}`)
        .fontSize(20)
        .margin({ bottom: 10 })

      Text(this.questions[this.currentQuestionIndex].question)
        .fontSize(18)
        .margin({ bottom: 20 })

      Grid() {
        ForEach(this.questions[this.currentQuestionIndex].options, (item: string, index: number) => {
          GridItem() {
            Button(item)
              .onClick(() => this.animateOption(index))
              .stateEffect(this.selectedOption === index && this.isAnimating)
              .animation({ duration: 1000, curve: Curve.EaseInOut })
          }
        })
      }
      .columnsTemplate('1fr 1fr')
      .rowsTemplate('1fr 1fr')
      .columnsGap(10)
      .rowsGap(10)
      .height(200)
      .margin({ bottom: 20 })

      Text(`Score: ${this.score}`)
        .fontSize(18)
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

import window from '@ohos.window';
import common from '@ohos.app.ability.common';
import { FlexDirection, FlexAlign } from '@ohos.arkui.d';

@Entry
@Component
struct OrientationAdaptiveApp {
  @State isPortrait: boolean = true;
  @State checkboxState: boolean = false;
  @State rating: number = 0;
  @State orientationStatus: string = 'Portrait';
  private context: common.UIAbilityContext = getContext(this) as common.UIAbilityContext;

  aboutToAppear() {
    this.detectOrientation();
  }

  detectOrientation() {
    try {
      window.getLastWindow(this.context).then((win: window.Window) => {
        win.on('windowSizeChange', () => {
          win.getWindowAvoidArea(window.AvoidAreaType.TYPE_SYSTEM).then((area: window.AvoidArea) => {
            this.isPortrait = area.rightRect.width < area.rightRect.height;
            this.orientationStatus = this.isPortrait ? 'Portrait' : 'Landscape';
          });
        });
      }).catch((err: Error) => {
        console.error('Failed to get window:', err);
      });
    } catch (err) {
      console.error('Error detecting orientation:', err);
    }
  }

  updateRating(value: number) {
    this.rating = value;
  }

  build() {
    Column() {
      Text('Orientation: ' + this.orientationStatus)
        .fontSize(20)
        .margin(10);

      Row() {
        Text('Enable Feature:')
          .fontSize(16)
          .margin(10);
        Checkbox()
          .select(this.checkboxState)
          .onChange((isChecked: boolean) => {
            this.checkboxState = isChecked;
          });
      }
      .justifyContent(FlexAlign.Start)
      .width('100%')
      .margin(10);

      Column() {
        Text('Rate Us:')
          .fontSize(16)
          .margin(10);
        Row() {
          ForEach([1, 2, 3, 4, 5], (index: number) => {
            Image($r('app.media.star'))
              .width(30)
              .height(30)
              .margin(5)
              .onClick(() => {
                this.updateRating(index);
              })
              .opacity(index <= this.rating ? 1 : 0.3);
          });
        }
        .justifyContent(FlexAlign.Center)
        .width('100%');
      }
      .width('100%')
      .margin(10);

      Text('Current Rating: ' + this.rating + ' stars')
        .fontSize(16)
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .direction(this.isPortrait ? FlexDirection.Column : FlexDirection.Row)
    .justifyContent(FlexAlign.Center)
    .alignItems(FlexAlign.Center);
  }
}

