  private languages: LanguageMap = {
    en: {
      home: 'Home',
      category: 'Category',
      product: 'Product',
      toggleLanguage: 'Switch to Spanish',
    },
    es: {
      home: 'Inicio',
      category: 'Categoría',
      product: 'Producto',
      toggleLanguage: 'Cambiar a Inglés',
    },
  };

  @Builder
  BreadcrumbItem(text: string, index: number) {
    Text(text)
      .fontColor(this.breadcrumbs.length - 1 === index ? '#1698CE' : '#666666')
      .fontSize(16)
      .margin({ right: 8 })
      .onClick(() => {
        this.breadcrumbs = this.breadcrumbs.slice(0, index + 1);
      });
  }

  private toggleLanguage(): void {
    this.currentLanguage = this.currentLanguage === 'en' ? 'es' : 'en';
  }

  private getCurrentItemText(): string {
    const lastItem = this.breadcrumbs[this.breadcrumbs.length - 1];
    const lang = this.currentLanguage === 'en' ? this.languages.en : this.languages.es;
    switch (lastItem) {
      case 'Home':
        return lang.home;
      case 'Category':
        return lang.category;
      case 'Product':
        return lang.product;
      default:
        return '';
    }
  }

  build() {
    Column() {
      Row() {
        ForEach(this.breadcrumbs, (item: string, index: number) => {
          this.BreadcrumbItem(item, index);
          if (index < this.breadcrumbs.length - 1) {
            Text('>')
              .fontColor('#666666')
              .fontSize(16)
              .margin({ right: 8 });
          }
        });
      }
      .padding(16)
      .width('100%')
      .justifyContent(FlexAlign.Start)
      .backgroundColor('#f5f5f5');

      Button(this.currentLanguage === 'en' ? this.languages.en.toggleLanguage : this.languages.es.toggleLanguage)
        .onClick(() => this.toggleLanguage())
        .margin({ top: 16 });

      Text(this.getCurrentItemText())
        .fontSize(20)
        .margin({ top: 16 });
    }
    .width('100%')
    .height('100%')
    .padding(16);
  }
}

import { Column, Text, LoadingProgress, Refresh } from '@ohos.arkui';
import { LineChart, LineSeries } from '@ohos.charts';
import { FontWeight } from '@ohos.arkui';

interface ReadingProgress {
  page: number;
  completionPercentage: number;
}

interface ChartPoint {
  x: number;
  y: number;
}

interface PointClickEvent {
  value: ChartPoint;
}

@Entry
@Component
struct BookReaderApp {
  @State readingData: ReadingProgress[] = [];
  @State isLoading: boolean = false;
  @State selectedPoint: ReadingProgress | null = null;

  aboutToAppear(): void {
    this.generateSampleData();
  }

  generateSampleData(): void {
    const data: ReadingProgress[] = [];
    for (let i = 1; i <= 10; i++) {
      data.push({
        page: i,
        completionPercentage: Math.floor(Math.random() * 100),
      });
    }
    this.readingData = data;
  }

  onRefresh(): void {
    this.isLoading = true;
    setTimeout(() => {
      this.generateSampleData();
      this.isLoading = false;
    }, 1000);
  }

  onPointSelect(point: ReadingProgress): void {
    this.selectedPoint = point;
  }

  build() {
    Column() {
      Text('Reading Progress')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Refresh({
        refreshing: this.isLoading,
        onRefresh: () => this.onRefresh(),
      }) {
        Column() {
          if (this.isLoading) {
            LoadingProgress()
              .width(50)
              .height(50);
          } else {
            LineChart()
              .width('100%')
              .height(300)
            {
              LineSeries()
                .data(this.readingData.map(item => {
                  return { x: item.page, y: item.completionPercentage } as ChartPoint;
                }))
                .onPointClick((event: PointClickEvent) => {
                  this.onPointSelect({
                    page: event.value.x,
                    completionPercentage: event.value.y
                  } as ReadingProgress);
                });
            }
          }

          if (this.selectedPoint) {
            Text('Page ' + this.selectedPoint.page + ': ' + this.selectedPoint.completionPercentage + '% completed')
              .fontSize(16)
              .margin({ top: 16 });
          }
        }
        .width('100%')
        .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }
}

