  @State username: string = '';
  @State password: string = '';
  @State termsAccepted: boolean = false;
  @State successMessage: string = '';
  @State errorMessage: string = '';

  validateCredentials(): boolean {
    if (!this.username.trim()) {
      this.errorMessage = 'Username cannot be empty';
      this.successMessage = '';
      return false;
    }
    if (!this.password.trim()) {
      this.errorMessage = 'Password cannot be empty';
      this.successMessage = '';
      return false;
    }
    if (!this.termsAccepted) {
      this.errorMessage = 'Please accept the terms and conditions';
      this.successMessage = '';
      return false;
    }
    if (this.username.trim() === 'admin' && this.password.trim() === 'admin123') {
      this.successMessage = 'Login successful!';
      this.errorMessage = '';
      return true;
    } else {
      this.errorMessage = 'Invalid username or password';
      this.successMessage = '';
      return false;
    }
  }

  build() {
    Column() {
      Text('Login')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your username' })
        .onChange((value: string) => {
          this.username = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Row() {
        Checkbox()
          .onChange((checked: boolean) => {
            this.termsAccepted = checked;
          })
          .margin({ right: 10 });

        Text('I accept the terms and conditions')
          .fontSize(16);
      }
      .margin({ bottom: 20 });

      Button('Login')
        .onClick(() => {
          if (this.validateCredentials()) {
            promptAction.showToast({ message: this.successMessage });
          } else {
            promptAction.showToast({ message: this.errorMessage });
