  @State private currentIndex: number = 0;

  @Builder
  BreadcrumbItem(text: string, index: number) {
    Text(text)
      .fontColor(this.breadcrumbs.length - 1 === index ? '#1698CE' : '#6B6B6B')
      .fontSize(16)
      .margin({ right: 8 })
      .onClick(() => {
        this.breadcrumbs = this.breadcrumbs.slice(0, index + 1);
        this.currentIndex = index;
      });
  }

  build() {
    Column() {
      Row() {
        ForEach(this.breadcrumbs, (item: string, index: number) => {
          this.BreadcrumbItem(item, index);
          if (index < this.breadcrumbs.length - 1) {
            Text('>')
              .fontColor('#6B6B6B')
              .fontSize(16)
              .margin({ right: 8 });
          }
        });
      }
      .padding(16)
      .width('100%')
      .justifyContent(FlexAlign.Start);

      Column()
        .width('100%')
        .height('80%')
        .gesture(
          PanGesture()
            .onActionStart(() => {})
            .onActionUpdate((event: GestureEvent) => {
              if (event.offsetX < -50 && this.currentIndex < this.breadcrumbs.length - 1) {
                this.currentIndex++;
                this.breadcrumbs = this.breadcrumbs.slice(0, this.currentIndex + 1);
              } else if (event.offsetX > 50 && this.currentIndex > 0) {
                this.currentIndex--;
                this.breadcrumbs = this.breadcrumbs.slice(0, this.currentIndex + 1);
              }
            })
            .onActionEnd(() => {})
        );

      if (this.breadcrumbs[this.currentIndex] === 'Home') {
        Text('Home Content')
          .fontSize(20)
          .margin({ top: 16 });
      } else if (this.breadcrumbs[this.currentIndex] === 'Category') {
        Text('Category Content')
          .fontSize(20)
          .margin({ top: 16 });
      } else if (this.breadcrumbs[this.currentIndex] === 'Product') {
        Text('Product Content')
          .fontSize(20)
          .margin({ top: 16 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(16);
  }
}

