@Entry
@Component
struct NewsReaderApp {
  @State private showOnboarding: boolean = true;
  @State private selectedArticle: number = -1;
  @State private paths: Array<Array<number>> = [];
  @State private currentPath: Array<number> = [];
  @State private isDrawing: boolean = false;
  @State private scheduledTime: Date = new Date();
  private context?: CanvasRenderingContext2D;

  private articles: Array<Article> = [
    {
      id: 0,
      title: 'Breaking News',
      image: $r('app.media.ic_public_news_filled'),
      content: 'This is the content of the breaking news article.'
    },
    {
      id: 1,
      title: 'Tech Update',
      image: $r('app.media.ic_public_news_filled'),
      content: 'Latest updates in the tech world.'
    }
  ];

  build() {
    Stack() {
      if (this.showOnboarding) {
        Column() {
          Text('Welcome to News Reader')
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });
          Image($r('app.media.ic_public_news_filled'))
            .width(200)
            .height(200)
            .margin({ bottom: 20 });
          Button('Get Started')
            .width('80%')
            .onClick(() => {
              this.showOnboarding = false;
            });
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center);
      } else if (this.selectedArticle === -1) {
        List() {
          ForEach(this.articles, (article: Article) => {
            ListItem() {
              Row() {
                Image(article.image)
                  .width(50)
                  .height(50)
                  .margin({ right: 10 });
                Text(article.title)
                  .fontSize(16);
              }
              .width('100%')
              .padding(10);
            }
            .onClick(() => {
              this.selectedArticle = article.id;
            });
          });
        }
        .width('100%')
        .height('100%');
      } else {
        Column() {
          Row() {
            Button('Back')
              .onClick(() => {
                this.selectedArticle = -1;
              });
          }
          .width('100%')
          .padding(10);

          Text(this.articles[this.selectedArticle].title)
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 10 });

          Image(this.articles[this.selectedArticle].image)
            .width(200)
            .height(200)
            .margin({ bottom: 10 });

          Text(this.articles[this.selectedArticle].content)
            .fontSize(16)
            .margin({ bottom: 20 });

          TimePicker({ selected: this.scheduledTime })
            .width('80%')
            .onChange((value: TimePickerResult) => {
              this.scheduledTime = new Date();
              this.scheduledTime.setHours(value.hour);
              this.scheduledTime.setMinutes(value.minute);
            });

          Canvas()
            .width('100%')
            .height(200)
            .backgroundColor('#F0F0F0')
            .onReady(() => {
              this.context = $canvas.getContext('2d');
            })
            .onTouch((event: TouchEvent) => {
              if (!this.context) return;
              if (event.type === TouchType.Down) {
                this.isDrawing = true;
                this.context.beginPath();
                this.context.moveTo(event.touches[0].x, event.touches[0].y);
              } else if (event.type === TouchType.Move && this.isDrawing) {
                this.context.lineTo(event.touches[0].x, event.touches[0].y);
                this.context.stroke();
              } else if (event.type === TouchType.Up) {
                this.isDrawing = false;
              }
            });
        }
      }
    }
  }
}

