import { Column, Text, Button, List, ForEach, ListItem, Row, TextInput, Scroll } from '@ohos.arkui.advanced';
import { Tooltip, Rating } from '@ohos.arkui.advanced';
import { FontWeight, Color } from '@ohos.arkui.advanced';

class Contact {
  name: string;
  phone: string;
  rating: number;

  constructor(name: string, phone: string, rating: number = 0) {
    this.name = name;
    this.phone = phone;
    this.rating = rating;
  }
}

@Entry
@Component
struct ContactManagementApp {
  @State contacts: Contact[] = [
    new Contact("John Doe", "123-456-7890", 3),
    new Contact("Jane Smith", "987-654-3210", 4),
    new Contact("Alice Brown", "555-123-4567", 2),
    new Contact("Bob White", "111-222-3333", 5)
  ];

  @State searchQuery: string = '';
  @State totalContacts: number = 4;
  @State groupedContacts: Map<string, Contact[]> = new Map<string, Contact[]>();
  @State sections: string[] = [];

  aboutToAppear(): void {
    this.groupContacts();
  }

  groupContacts(): void {
    const grouped = new Map<string, Contact[]>();
    const filteredContacts = this.contacts.filter(contact =>
      contact.name.toLowerCase().includes(this.searchQuery.toLowerCase()) ||
      contact.phone.includes(this.searchQuery)
    );

    filteredContacts.forEach(contact => {
      const firstLetter = contact.name.charAt(0).toUpperCase();
      if (!grouped.has(firstLetter)) {
        grouped.set(firstLetter, []);
      }
      grouped.get(firstLetter)?.push(contact);
    });

    this.groupedContacts = grouped;
    this.sections = Array.from(grouped.keys()).sort();
  }

  incrementContacts(): void {
    this.totalContacts++;
  }

  decrementContacts(): void {
    if (this.totalContacts > 0) {
      this.totalContacts--;
    }
  }

  updateRating(contact: Contact, rating: number): void {
    contact.rating = rating;
  }

  build() {
    Column() {
      Row() {
        TextInput({ placeholder: "Search by name or phone", text: this.searchQuery })
          .onChange((value: string) => {
            this.searchQuery = value;
            this.groupContacts();
          })
          .accessibilityText("Search contacts by name or phone number")
          .margin({ right: 10 });

        Tooltip({ content: "Clear search", placement: "top" }) {
          Button("Clear")
            .onClick(() => {
              this.searchQuery = '';
              this.groupContacts();
            })
            .accessibilityText("Clear search");
        }
      }
      .margin({ bottom: 20 });

      Row() {
        Text(`Total Contacts: ${this.totalContacts}`)
          .fontSize(16)
          .margin({ right: 10 });

        Tooltip({ content: "Increment total contacts", placement: "top" }) {
          Button("+")
            .onClick(() => this.incrementContacts())
            .accessibilityText("Increment total contacts");
        }

        Tooltip({ content: "Decrement total contacts", placement: "top" }) {
          Button("-")
            .onClick(() => this.decrementContacts())
            .accessibilityText("Decrement total contacts");
        }
      }
      .margin({ bottom: 20 });

      Scroll() {
        Column() {
          ForEach(this.sections, (section: string) => {
            Column() {
              Text(section)
                .fontSize(18)
                .fontWeight(FontWeight.Bold)
                .margin({ bottom: 10 });

              ForEach(this.groupedContacts.get(section), (contact: Contact) => {
                ListItem() {
                  Row() {
                    Column() {
                      Text(contact.name)
                        .fontSize(16)
                        .fontWeight(FontWeight.Medium);

                      Text(contact.phone)
                        .fontSize(14)
                        .fontColor(Color.Gray);
                    }

                    Rating({ rating: contact.rating, indicator: true })
                      .onChange((rating: number) => this.updateRating(contact, rating))
                      .accessibilityText(`Rate ${contact.name}`);
                  }
                }
                .accessibilityText(`Contact: ${contact.name}, Phone: ${contact.phone}`);
              });
            }
            .margin({ bottom: 20 });
          });
        }
      }
      .height("60%");

      if (this.sections.length === 0) {
        Column() {
          Text("No contacts found")
            .fontSize(16)
            .margin({ top: 20 });
        }

@Entry
@Component
struct StepCounterApp {
  @State steps: number[] = [1000, 2000, 3000, 4000, 5000, 6000, 7000, 8000, 9000, 10000]
  @State filteredSteps: number[] = []
  @State searchQuery: string = ''
  @State activeFilter: string = 'All'

  build() {
    Column() {
      // Search functionality
      TextInput({ placeholder: 'Search steps...' })
        .width('90%')
        .height(40)
        .margin(10)
        .onChange((value: string) => {
          this.searchQuery = value
          this.filterSteps()
        })

      // Breadcrumb navigation for filtering
      Row() {
        Button('All')
          .onClick(() => {
            this.activeFilter = 'All'
            this.filterSteps()
          })
          .backgroundColor(this.activeFilter === 'All' ? '#4CAF50' : '#E0E0E0')
          .margin(5)

        Button('Low')
          .onClick(() => {
            this.activeFilter = 'Low'
            this.filterSteps()
          })
          .backgroundColor(this.activeFilter === 'Low' ? '#4CAF50' : '#E0E0E0')
          .margin(5)

        Button('High')
          .onClick(() => {
            this.activeFilter = 'High'
            this.filterSteps()
          })
          .backgroundColor(this.activeFilter === 'High' ? '#4CAF50' : '#E0E0E0')
          .margin(5)
      }
      .justifyContent(FlexAlign.Center)
      .margin(10)

      // ScrollView for displaying steps
      Scroll() {
        Column() {
          ForEach(this.filteredSteps.length > 0 ? this.filteredSteps : this.steps, (step: number, index: number) => {
            Text(`Step ${index + 1}: ${step} steps`)
              .fontSize(16)
              .margin(5)
              .padding(10)
              .backgroundColor('#F5F5F5')
              .borderRadius(5)
          })
        }
        .width('100%')
      }
      .height('70%')
      .margin(10)
    }
    .width('100%')
    .height('100%')
  }

  filterSteps() {
    this.filteredSteps = this.steps.filter((step: number) => {
      const matchesSearch = step.toString().includes(this.searchQuery)
      if (this.activeFilter === 'All') return matchesSearch
      if (this.activeFilter === 'Low') return matchesSearch && step <= 5000
      if (this.activeFilter === 'High') return matchesSearch && step > 5000
      return false
    })
  }
}

