import promptAction from '@ohos.promptAction';

interface FormData {
  title: string;
  description: string;
  duration: string;
}

interface FormErrors {
  title: string;
  description: string;
  duration: string;
}

@Entry
@Component
struct VideoStreamingStepper {
  @State currentStep: number = 1;
  @State formData: FormData = {
    title: '',
    description: '',
    duration: ''
  };
  @State errors: FormErrors = {
    title: '',
    description: '',
    duration: ''
  };

  private validateStep(step: number): boolean {
    switch (step) {
      case 1:
        if (!this.formData.title.trim()) {
          this.errors.title = 'Title is required';
          return false;
        }
        this.errors.title = '';
        return true;
      case 2:
        if (!this.formData.description.trim()) {
          this.errors.description = 'Description is required';
          return false;
        }
        this.errors.description = '';
        return true;
      case 3:
        if (!this.formData.duration.trim() || isNaN(Number(this.formData.duration))) {
          this.errors.duration = 'Valid duration is required';
          return false;
        }
        this.errors.duration = '';
        return true;
      default:
        return true;
    }
  }

  private nextStep() {
    if (this.validateStep(this.currentStep)) {
      this.currentStep++;
    }
  }

  private prevStep() {
    this.currentStep--;
  }

  private submitForm() {
    if (this.validateStep(this.currentStep)) {
      promptAction.showToast({
        message: 'Form submitted successfully',
        duration: 2000
      });
    }
  }

  build() {
    Column() {
      Row() {
        ForEach([1, 2, 3], (step: number) => {
          Column() {
            Circle()
              .width(30)
              .height(30)
              .fill(this.currentStep >= step ? '#007AFF' : '#CCCCCC');
            Text(`Step ${step}`)
              .fontSize(12)
              .margin({ top: 5 });
          }
          .margin({ right: 20 });
        });
      }
      .margin({ top: 20, bottom: 20 });

      Divider();

      if (this.currentStep === 1) {
        Column() {
          TextInput({ placeholder: 'Enter video title' })
            .onChange((value: string) => {
              this.formData.title = value;
            });
          if (this.errors.title) {
            Text(this.errors.title)
              .fontColor('#FF0000')
              .fontSize(12);
          }
        }
      } else if (this.currentStep === 2) {
        Column() {
          TextInput({ placeholder: 'Enter video description' })
            .onChange((value: string) => {
              this.formData.description = value;
            });
          if (this.errors.description) {
            Text(this.errors.description)
              .fontColor('#FF0000')
              .fontSize(12);
          }
        }
      } else if (this.currentStep === 3) {
        Column() {
          TextInput({ placeholder: 'Enter video duration (seconds)' })
            .onChange((value: string) => {
              this.formData.duration = value;
            });
          if (this.errors.duration) {
            Text(this.errors.duration)
              .fontColor('#FF0000')
              .fontSize(12);
          }
        }
      }

      Row() {
        Button('Previous')
          .onClick(() => this.prevStep())
          .enabled(this.currentStep > 1);
        Button(this.currentStep === 3 ? 'Submit' : 'Next')
          .onClick(() => this.currentStep === 3 ? this.submitForm() : this.nextStep());
      }
      .margin({ top: 20 });
    }
    .padding(20);
  }
}

