                      .controls(false)
                      .autoPlay(true)
                      .loop(false)
                      .objectFit(ImageFit.Contain)
                      .onPrepared((event: media.AVPlayerEvent) => {
                        console.info(`Video prepared. Duration: ${event.duration}`);
                      })
                      .onError(() => {
                        promptAction.showToast({ message: 'Error playing video' });
                        this.selectedVideo = null;
                      });
                    }
                    Button('Back')
                      .onClick(() => {
                        this.selectedVideo = null;
                      })
                      .margin(16);
                  }
                  .width('100%')
                  .height('100%');
                }
              }
            }.tabBar('Videos')

            TabContent() {
              Column() {
                Text('Analytics')
                  .fontSize(18)
                  .fontWeight(FontWeight.Bold)
                  .padding(16);
                Text('Analytics content will be displayed here.')
                  .fontSize(16)
                  .padding(16);
              }
            }.tabBar('Analytics')
          }
        }
      }
    }
  }
}

@Entry
@Component
struct FormWithStopwatch {
  @State elapsedTime: number = 0
  @State isRunning: boolean = false
  @State rotationAngle: number = 0
  @State formData: FormData = { name: '', email: '', agree: false }
  private timerId: number = -1
  private minAngle: number = -45
  private maxAngle: number = 45

  build() {
    Scroll() {
      Column() {
        Text('User Information')
          .fontSize(24)
          .margin({ bottom: 20 })

        Row() {
          Text('Name:')
            .fontSize(16)
            .margin({ right: 10 })
          TextInput({ placeholder: 'Enter your name' })
            .width('70%')
            .onChange((value: string) => {
              this.formData.name = value
            })
        }
        .margin({ bottom: 15 })

        Row() {
          Text('Email:')
            .fontSize(16)
            .margin({ right: 10 })
          TextInput({ placeholder: 'Enter your email' })
            .width('70%')
            .onChange((value: string) => {
              this.formData.email = value
            })
        }
        .margin({ bottom: 15 })

        Row() {
          Checkbox()
            .select(this.formData.agree)
            .onChange((isChecked: boolean) => {
              this.formData.agree = isChecked
            })
          Text('I agree to the terms and conditions')
            .fontSize(16)
            .margin({ left: 10 })
        }
        .margin({ bottom: 20 })

        Text('Stopwatch')
          .fontSize(24)
          .margin({ bottom: 10 })

        Text(this.formatTime(this.elapsedTime))
          .fontSize(40)
          .margin({ bottom: 20 })

        Row() {
          Button(this.isRunning ? 'Stop' : 'Start')
            .onClick(() => {
              if (this.isRunning) {
                clearInterval(this.timerId)
              } else {
                this.timerId = setInterval(() => {
                  this.elapsedTime += 1
                }, 10)
              }
              this.isRunning = !this.isRunning
            })
            .margin({ right: 10 })

          Button('Reset')
            .onClick(() => {
              clearInterval(this.timerId)
              this.elapsedTime = 0
              this.isRunning = false
            })
        }
        .margin({ bottom: 20 })

        Text('Rotation Gesture Validation')
          .fontSize(24)
          .margin({ bottom: 10 })

        Image($r('app.media.app_icon'))
          .width(150)
          .height(150)
          .rotate({ x: 0, y: 0, z: 1, angle: this.rotationAngle })
          .gesture(
            RotationGesture()
              .onActionStart(() => {
                console.info('Rotation started')
              })
              .onActionUpdate((event: RotationGestureEvent) => {
                let newAngle = this.rotationAngle + event.angle
                if (newAngle < this.minAngle) {
                  newAngle = this.minAngle
                } else if (newAngle > this.maxAngle) {
                  newAngle = this.maxAngle
                }
                this.rotationAngle = newAngle
                console.info(`Rotation angle updated to: ${this.rotationAngle}`)
              })
              .onActionEnd(() => {
                console.info('Rotation ended')
              })
          )

        Text(`Current Angle: ${this.rotationAngle.toFixed(2)}\u00b0`)
          .fontSize(20)
          .margin({ top: 10 })

        Button('Submit Form')
          .onClick(() => {
            console.info('Form submitted:', this.formData)
          })
          .margin({ top: 20 })
      }
      .width('100%')
      .padding(20)
    }
    .scrollable(ScrollDirection.Vertical)
    .scrollBar(BarState.On)
    .scrollBarColor(Color.Gray)
    .scrollBarWidth(10)
    .edgeEffect(EdgeEffect.Spring)
  }

  private formatTime(time: number): string {
    const minutes = Math.floor(time / 6000)
    const seconds = Math.floor((time % 6000) / 100)
    const centiseconds = time % 100
    return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}.${centiseconds.toString().padStart(2, '0')}`
  }
}

interface FormData {
  name: string
  email: string
  agree: boolean
}

@Entry
@Component
struct TabbedInterface {
  @State private currentIndex: number = 0;
  private tabsController: TabsController = new TabsController();
  @State private showMenu: boolean = false;
  @State private selectedTabIndex: number = 0;

  @Builder
  TabBuilder(index: number, label: string, color: string) {
    Column() {
      Text(label)
        .fontColor(this.currentIndex === index ? '#007DFF' : '#6B6B6B')
        .fontSize(16)
        .fontWeight(this.currentIndex === index ? 500 : 400)
        .margin({ top: 10, bottom: 5 });
      Divider()
        .strokeWidth(2)
        .color('#007DFF')
        .opacity(this.currentIndex === index ? 1 : 0);
    }
    .width('100%')
    .height(50)
    .justifyContent(FlexAlign.Center)
    .onClick(() => {
      this.currentIndex = index;
      this.tabsController.changeIndex(index);
    })
    .gesture(
      LongPressGesture()
        .onAction(() => {
          this.selectedTabIndex = index;
          this.showMenu = true;
        })
    );
  }

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.Start, controller: this.tabsController }) {
        TabContent() {
          Text('Content for Tab 1')
            .fontSize(20)
            .textAlign(TextAlign.Center)
            .backgroundColor('#FFCCCC');
        }.tabBar(this.TabBuilder(0, 'Tab 1', '#FFCCCC'));

        TabContent() {
          Text('Content for Tab 2')
            .fontSize(20)
            .textAlign(TextAlign.Center)
            .backgroundColor('#CCFFCC');
        }.tabBar(this.TabBuilder(1, 'Tab 2', '#CCFFCC'));

        TabContent() {
          Text('Content for Tab 3')
            .fontSize(20)
            .textAlign(TextAlign.Center)
            .backgroundColor('#CCCCFF');
        }.tabBar(this.TabBuilder(2, 'Tab 3', '#CCCCFF'));

        TabContent() {
          Text('Content for Tab 4')
            .fontSize(20)
            .textAlign(TextAlign.Center)
            .backgroundColor('#FFFFCC');
        }.tabBar(this.TabBuilder(3, 'Tab 4', '#FFFFCC'));
      }
      .vertical(false)
      .barMode(BarMode.Fixed)
      .barWidth('100%')
      .barHeight(56)
      .animationDuration(400)
      .onChange((index: number) => {
        this.currentIndex = index;
      })
      .width('100%')
      .margin({ top: 10 })
      .backgroundColor('#F1F3F5');

      if (this.showMenu) {
        Column() {
          Text('Menu Item 1')
            .fontSize(16)
            .padding(10)
            .onClick(() => {
              this.showMenu = false;
            });
          Text('Menu Item 2')
            .fontSize(16)
            .padding(10)
            .onClick(() => {
              this.showMenu = false;
            });
        }
        .width(200)
        .backgroundColor('#FFFFFF')
        .border({ width: 1, color: '#CCCCCC' })
        .position({ x: 100, y: 100 });
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

import promptAction from '@ohos.promptAction';
import { Rating } from '@ohos.arkui.component';
import { Dialog } from '@ohos.arkui.component';

interface Task {
  id: number;
  name: string;
  duration: string;
  deadline: string;
  completed: boolean;
}

@Entry
@Component
struct TaskManagerApp {
  @State tasks: Array<Task> = [];
  @State newTaskName: string = '';
  @State newTaskDuration: string = '';
  @State newTaskDeadline: string = '';
  @State showCompleted: boolean = false;
  @State ratingValue: number = 0;

  private generateTaskId(): number {
    return this.tasks.length + 1;
  }

  private isDeadlineApproaching(deadline: string): boolean {
    try {
      const deadlineDate = new Date(deadline);
      const today = new Date();
      const daysDifference = Math.floor((deadlineDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
      return daysDifference <= 3 && daysDifference >= 0;
    } catch (e) {
      console.error('Invalid date format:', e);
      return false;
    }
  }

  private addTask() {
    if (this.newTaskName.trim() && this.newTaskDuration.trim() && this.newTaskDeadline.trim()) {
      this.tasks.push({
        id: this.generateTaskId(),
        name: this.newTaskName,
        duration: this.newTaskDuration,
        deadline: this.newTaskDeadline,
        completed: false
      } as Task);
      this.newTaskName = '';
      this.newTaskDuration = '';
      this.newTaskDeadline = '';
    }
  }

  private toggleTaskCompletion(taskId: number) {
    const taskIndex = this.tasks.findIndex(task => task.id === taskId);
    if (taskIndex !== -1) {
      this.tasks[taskIndex].completed = !this.tasks[taskIndex].completed;
    }
  }

  private onRatingChange(newValue: number) {
    this.ratingValue = newValue;
    Dialog.show({
      title: 'Rating Updated',
      message: `You rated this app ${newValue} stars.`,
      buttons: [
        {
          text: 'OK',
          color: '#000000'
        }
      ]
    });
  }

  build() {
    Column() {
      TextInput({ placeholder: 'Task Name', text: this.newTaskName })
        .onChange((value: string) => { this.newTaskName = value; })
        .width('90%')
        .height(50)
        .margin({ top: 20, bottom: 10 });

      TextInput({ placeholder: 'Duration (e.g., 2 hours)', text: this.newTaskDuration })
        .onChange((value: string) => { this.newTaskDuration = value; })
        .width('90%')
        .height(50)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Deadline (YYYY-MM-DD)', text: this.newTaskDeadline })
        .onChange((value: string) => { this.newTaskDeadline = value; })
        .width('90%')
        .height(50)
        .margin({ bottom: 20 });

      Button('Add Task')
        .onClick(() => { this.addTask(); })
        .width('90%')
        .height(50)
        .margin({ bottom: 20 });

      Image($r('app.media.task_map'))
        .width('90%')
        .height(200)
        .margin({ bottom: 20 });

      List({ space: 10 }) {
        ForEach(this.tasks, (task: Task) => {
          ListItem() {
            Row() {
              Checkbox()
                .select(task.completed)
                .onChange((checked: boolean) => { this.toggleTaskCompletion(task.id); });
              Column() {
                Text(task.name)
                  .fontSize(16);
                Text(`Duration: ${task.duration}`)
                  .fontSize(14);
                Text(`Deadline: ${task.deadline}`)
                  .fontSize(14)
                  .fontColor(this.isDeadlineApproaching(task.deadline) ? '#FF0000' : '#000000');
              }
            }
          }
        })
      }
      .width('100%')
      .height('40%')
      .margin({ bottom: 20 });

      Rating({ rating: this.ratingValue })
        .onChange((value: number) => { this.onRatingChange(value); })
        .width('90%')
        .margin({ bottom: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20);

@Entry
@Component
struct StopwatchApp {
  @State elapsedTime: number = 0
  @State isRunning: boolean = false
  private timerId: number = -1
  private dialogController: CustomDialogController = new CustomDialogController({
    builder: StopwatchDialog({
      cancel: this.onCancel.bind(this),
      confirm: this.onConfirm.bind(this),
      controller: undefined
    }),
    autoCancel: true
  })

  build() {
    Column() {
      Text(this.formatTime(this.elapsedTime))
        .fontSize(40)
        .margin(20)

      Row() {
        Button(this.isRunning ? 'Stop' : 'Start')
          .onClick(() => {
            if (this.isRunning) {
              this.dialogController.open()
            } else {
              this.startStopwatch()
            }
          })
          .margin(10)

        Button('Reset')
          .onClick(() => {
            this.dialogController.open()
          })
          .margin(10)
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }

  private startStopwatch() {
    this.timerId = setInterval(() => {
      this.elapsedTime += 1
    }, 10)
    this.isRunning = true
  }

  private stopStopwatch() {
    clearInterval(this.timerId)
    this.isRunning = false
  }

  private resetStopwatch() {
    clearInterval(this.timerId)
    this.elapsedTime = 0
    this.isRunning = false
  }

  private formatTime(time: number): string {
    const minutes = Math.floor(time / 6000)
    const seconds = Math.floor((time % 6000) / 100)
    const centiseconds = time % 100
    return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}.${centiseconds.toString().padStart(2, '0')}`
  }

  private onCancel() {
    console.info('Dialog canceled')
  }

  private onConfirm() {
    if (this.isRunning) {
      this.stopStopwatch()
    } else {
      this.resetStopwatch()
    }
  }
}

@CustomDialog
struct StopwatchDialog {
  controller: CustomDialogController
  cancel?: () => void
  confirm?: () => void

  build() {
    Column() {
      Text('Are you sure?')
        .fontSize(20)
        .margin(10)

      Flex({ justifyContent: FlexAlign.SpaceAround }) {
        Button('Cancel')
          .onClick(() => {
            this.controller.close()
            this.cancel?.()
          })

        Button('Confirm')
          .onClick(() => {
            this.controller.close()
            this.confirm?.()
          })
      }
    }
  }
}

