  rating: number;
  image: Resource;
}

@Entry
@Component
struct InventoryManager {
  @State drawerOpen: boolean = false;
  @State activeSection: string = 'Inventory';
  @State inventoryItems: Array<InventoryItem> = [
    { name: 'Item 1', rating: 3, image: $r('app.media.ic_default') },
    { name: 'Item 2', rating: 4, image: $r('app.media.ic_default') },
    { name: 'Item 3', rating: 2, image: $r('app.media.ic_default') }
  ];
