        .width('100%')
        .height('100%');
      }

      Panel({
        show: this.drawerOpen,
        onDismiss: () => this.toggleDrawer()
      }) {
        Column() {
          Button('Inventory')
            .onClick(() => this.changeSection('Inventory'))
            .focusable(true)
            .focusOnTouch(true);
          Button('Profile')
