            .onClick(() => this.changeSection('Settings'))
            .focusable(true)
            .focusOnTouch(true);
        }
        .width(200)
        .height('100%')
        .backgroundColor('#ffffff')
        .padding(16);
      }
      .position({ x: 0, y: 0 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff');
  }
}

import prompt from '@ohos.prompt';

@Entry
@Component
struct RecipeFormValidation {
  @State recipeName: string = '';
  @State ingredients: string = '';
  @State steps: string = '';
  @State recipeNameError: string = '';
  @State ingredientsError: string = '';
  @State stepsError: string = '';
  @State isFormValid: boolean = false;
  @State progressValue: number = 0;

  validateRecipeName(name: string): string | null {
    if (name.length < 3) {
      return 'Recipe name must be at least 3 characters long';
    }
    return null;
  }

  validateIngredients(ingredients: string): string | null {
    if (ingredients.length === 0) {
      return 'Ingredients cannot be empty';
    }
    return null;
  }

  validateSteps(steps: string): string | null {
    if (steps.length === 0) {
      return 'Steps cannot be empty';
    }
    return null;
  }

  validateForm() {
    const recipeNameError = this.validateRecipeName(this.recipeName);
    const ingredientsError = this.validateIngredients(this.ingredients);
    const stepsError = this.validateSteps(this.steps);
    this.recipeNameError = recipeNameError || '';
    this.ingredientsError = ingredientsError || '';
    this.stepsError = stepsError || '';
    this.isFormValid = !recipeNameError && !ingredientsError && !stepsError;
    this.updateProgress();
  }

  updateProgress() {
    let completedFields = 0;
    if (this.recipeName.length >= 3) completedFields++;
    if (this.ingredients.length > 0) completedFields++;
    if (this.steps.length > 0) completedFields++;
    this.progressValue = (completedFields / 3) * 100;
  }

  build() {
    Column() {
      Text('Recipe Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      TextInput({ placeholder: 'Recipe Name' })
        .width('80%')
        .height(40)
        .margin({ bottom: 10 })
        .onChange((value: string) => {
          this.recipeName = value;
          this.validateForm();
        });

      if (this.recipeNameError) {
        Text(this.recipeNameError)
          .fontSize(12)
          .fontColor('#FF0000')
          .margin({ bottom: 10 });
      }

      TextInput({ placeholder: 'Ingredients' })
        .width('80%')
        .height(40)
        .margin({ bottom: 10 })
        .onChange((value: string) => {
          this.ingredients = value;
          this.validateForm();
        });

      if (this.ingredientsError) {
        Text(this.ingredientsError)
          .fontSize(12)
          .fontColor('#FF0000')
          .margin({ bottom: 10 });
      }

      TextInput({ placeholder: 'Steps' })
        .width('80%')
        .height(40)
        .margin({ bottom: 10 })
        .onChange((value: string) => {
          this.steps = value;
          this.validateForm();
        });

      if (this.stepsError) {
        Text(this.stepsError)
          .fontSize(12)
          .fontColor('#FF0000')
          .margin({ bottom: 10 });
      }

      Progress({ value: this.progressValue, total: 100 })
        .width('80%')
        .height(10)
        .margin({ bottom: 20 });

      Button('Submit')
        .type(ButtonType.Normal)
        .width('80%')
        .height(40)
