import { Tabs, TabContent, BarPosition, TabsController, Curve, Color, Column, Text, Image, FontWeight } from '@ohos.arkui.advanced';
import { PinchGesture, PinchGestureEvent } from '@ohos.multimodalinput.gesture';

@Entry
@Component
struct DataVisualizationApp {
  @State currentTab: number = 0;
  @State zoomScale: number = 1.0;
  @State showDialog: boolean = false;
  @State dialogTitle: string = '';
  @State dialogImage: Resource = $r('app.media.icon');

  private tabsController: TabsController = new TabsController();

  @Builder
  buildTabContent(title: string, image: Resource) {
    Column() {
      Image(image)
        .width('100%')
        .height('100%')
        .scale({ x: this.zoomScale, y: this.zoomScale })
        .gesture(
          PinchGesture()
            .onActionStart(() => {})
            .onActionUpdate((event: PinchGestureEvent) => {
              this.zoomScale = Math.max(0.5, Math.min(3.0, this.zoomScale * event.scale));
            })
            .onActionEnd(() => {})
        )
        .onClick(() => {
          this.dialogTitle = title;
          this.dialogImage = image;
          this.showDialog = true;
        })
    }
  }

  @Builder
  buildDialog() {
    Column() {
      Text(this.dialogTitle)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      Image(this.dialogImage)
        .width('80%')
        .height('80%')
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .onClick(() => {
      this.showDialog = false;
    })
  }

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.End, controller: this.tabsController }) {
        TabContent() {
          this.buildTabContent('Home', $r('app.media.icon'))
        }.tabBar('Home')

        TabContent() {
          this.buildTabContent('Data', $r('app.media.icon'))
        }.tabBar('Data')

        TabContent() {
          this.buildTabContent('Settings', $r('app.media.icon'))
        }.tabBar('Settings')

        TabContent() {
          this.buildTabContent('About', $r('app.media.icon'))
        }.tabBar('About')
      }
      .animationDuration(300)
      .animationCurve(Curve.EaseInOut)
      .onChange((index: number) => {
        this.currentTab = index;
      })

      if (this.showDialog) {
        this.buildDialog()
      }
    }
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct ExpenseTrackerForm {
  @State expenseName: string = '';
  @State expenseAmount: string = '';
  @State expenseDate: string = '';
  @State expenseCategory: string = '';
  @State nameError: string = '';
  @State amountError: string = '';
  @State dateError: string = '';
  @State categoryError: string = '';
  @State isFormValid: boolean = false;

  validateName(name: string): string | null {
    if (name.length === 0) {
      return 'Expense name cannot be empty';
    }
    return null;
  }

  validateAmount(amount: string): string | null {
    if (amount.length === 0) {
      return 'Amount cannot be empty';
    }
    if (isNaN(Number(amount))) {
      return 'Amount must be a number';
    }
    return null;
  }

  validateDate(date: string): string | null {
    if (date.length === 0) {
      return 'Date cannot be empty';
    }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      return 'Date must be in YYYY-MM-DD format';
    }
    return null;
  }

  validateCategory(category: string): string | null {
    if (category.length === 0) {
      return 'Category cannot be empty';
    }
    return null;
  }

  validateForm() {
    const nameError = this.validateName(this.expenseName);
    const amountError = this.validateAmount(this.expenseAmount);
    const dateError = this.validateDate(this.expenseDate);
    const categoryError = this.validateCategory(this.expenseCategory);

    this.nameError = nameError || '';
    this.amountError = amountError || '';
    this.dateError = dateError || '';
    this.categoryError = categoryError || '';

    this.isFormValid = !nameError && !amountError && !dateError && !categoryError;
  }

  build() {
    Column({ space: 20 }) {
      TextInput({ placeholder: 'Expense Name' })
        .onChange((value: string) => {
          this.expenseName = value;
          this.validateForm();
        })
        .border({
          width: 1,
          color: this.nameError ? '#ff0000' : '#ddd'
        })
        .width('100%');

      if (this.nameError) {
        Text(this.nameError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 });
      }

      TextInput({ placeholder: 'Amount' })
        .type(InputType.Number)
        .onChange((value: string) => {
          this.expenseAmount = value;
          this.validateForm();
        })
        .border({
          width: 1,
          color: this.amountError ? '#ff0000' : '#ddd'
        })
        .width('100%');

      if (this.amountError) {
        Text(this.amountError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 });
      }

      TextInput({ placeholder: 'Date (YYYY-MM-DD)' })
        .onChange((value: string) => {
          this.expenseDate = value;
          this.validateForm();
        })
        .border({
          width: 1,
          color: this.dateError ? '#ff0000' : '#ddd'
        })
        .width('100%');

      if (this.dateError) {
        Text(this.dateError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 });
      }

      TextInput({ placeholder: 'Category' })
        .onChange((value: string) => {
          this.expenseCategory = value;
          this.validateForm();
        })
        .border({
          width: 1,
          color: this.categoryError ? '#ff0000' : '#ddd'
        })
        .width('100%');

      if (this.categoryError) {
        Text(this.categoryError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 });
      }

      Button('Submit')
        .enabled(this.isFormValid)
        .onClick(() => {
          console.info('Form submitted successfully');
        });
    }
    .padding(20)
    .width('100%');
  }
}

@Entry
@Component
struct CustomCalendarApp {
  @State selectedDate: Date = new Date()
  @State showCalendar: boolean = false
  @State refreshing: boolean = false
  @State items: string[] = ['Document 1', 'Document 2', 'Document 3']
  @State marqueeText: string = 'Latest updates: New features added to the app!'

  build() {
    Column() {
      // Calendar Section
      Text('Selected Date: ' + this.selectedDate.toLocaleDateString())
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      Button('Show Calendar')
        .onClick(() => {
          this.showCalendar = !this.showCalendar
        })
        .width(200)
        .height(50)
        .margin({ bottom: 20 })

      if (this.showCalendar) {
        DatePicker({
          start: new Date('2000-01-01'),
          end: new Date('2030-12-31'),
          selected: this.selectedDate
        })
        .onDateChange((value: Date) => {
          this.selectedDate = value
          this.showCalendar = false
        })
        .width('90%')
        .margin({ top: 10 })
      }

      // Marquee Section
      Text(this.marqueeText)
        .fontSize(16)
        .fontColor('#333333')
        .margin({ top: 20, bottom: 20 })
        .animation({ duration: 1000, curve: Curve.Linear, iterations: -1 })

      // Refresh Section
      Refresh({ refreshing: $$this.refreshing }) {
        List() {
          ForEach(this.items, (item: string) => {
            ListItem() {
              Text(item)
                .width('100%')
                .height(50)
                .fontSize(16)
                .textAlign(TextAlign.Center)
                .backgroundColor('#f5f5f5')
                .margin({ top: 10 })
            }
          })
        }
        .width('100%')
        .height('100%')
      }
      .onRefreshing(() => {
        this.refreshing = true
        setTimeout(() => {
          this.items = [...this.items, 'New Document ' + (this.items.length + 1)]
          this.refreshing = false
        }, 2000)
      })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .padding(20)
  }
}

import prompt from '@ohos.promptAction';
import webview from '@ohos.web.webview';

interface Message {
  text: string;
  isUser: boolean;
  isAudio: boolean;
  isWebView: boolean;
}

@Entry
@Component
struct CRMMessagingApp {
  @State messages: Array<Message> = [];
  @State inputText: string = '';
  @State isPlaying: boolean = false;

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.messages, (message: Message, index: number) => {
          ListItem() {
            Column() {
              if (message.isAudio) {
                Row() {
                  Button(this.isPlaying ? 'Pause' : 'Play')
                    .onClick(() => {
                      this.isPlaying = !this.isPlaying;
                    });
                  Text('Audio Message');
                }
              } else if (message.isWebView) {
                Text('Embedded Content');
              } else {
                Text(message.text)
                  .fontSize(16)
                  .padding(10)
                  .backgroundColor(message.isUser ? '#007AFF' : '#f5f5f5')
                  .borderRadius(10)
                  .align(Alignment.Start)
                  .margin({ left: message.isUser ? '50%' : '0%', right: message.isUser ? '0%' : '50%' });
              }
            }
          }
        }, (item: Message) => JSON.stringify(item))
      }
      .layoutWeight(1)
      .width('100%')
      .padding(10)

      Row() {
        TextInput({ placeholder: 'Type a message...' })
          .width('70%')
          .height(40)
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.inputText = value;
          })

        Button('Audio')
          .width('15%')
          .height(40)
          .fontSize(16)
          .backgroundColor('#007AFF')
          .onClick(() => {
            this.messages.push({ text: '', isUser: true, isAudio: true, isWebView: false });
          })

        Button('Web')
          .width('15%')
          .height(40)
          .fontSize(16)
          .backgroundColor('#007AFF')
          .onClick(() => {
            this.messages.push({ text: '', isUser: true, isAudio: false, isWebView: true });
          })

        Button('Send')
          .width('15%')
          .height(40)
          .fontSize(16)
          .backgroundColor('#007AFF')
          .onClick(() => {
            if (this.inputText.trim()) {
              this.messages.push({ text: this.inputText, isUser: true, isAudio: false, isWebView: false });
              this.inputText = '';
              setTimeout(() => {
                this.messages.push({ text: 'This is a response.', isUser: false, isAudio: false, isWebView: false });
              }, 1000);
            } else {
              prompt.showToast({
                message: 'Please enter a message'
              });
            }
          })
      }
      .width('100%')
      .padding(10)
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

@Entry
@Component
struct EventPlanningForm {
  @State eventName: string = ''
  @State eventDate: string = ''
  @State eventLocation: string = ''
  @State errorMessage: string = ''
  @State isPinchValid: boolean = false
  @State pinchCount: number = 0

  validateForm(): boolean {
    if (this.eventName.length < 3) {
      this.errorMessage = 'Event name must be at least 3 characters long'
      return false
    }
    if (this.eventDate.length === 0) {
      this.errorMessage = 'Event date is required'
      return false
    }
    if (this.eventLocation.length < 3) {
      this.errorMessage = 'Event location must be at least 3 characters long'
      return false
    }
    if (!this.isPinchValid) {
      this.errorMessage = 'Pinch gesture validation required'
      return false
    }
    this.errorMessage = ''
    return true
  }

  handlePinch() {
    this.pinchCount++
    if (this.pinchCount >= 2) {
      this.isPinchValid = true
    }
  }

  build() {
    Column({ space: 20 }) {
      TextInput({ placeholder: 'Event Name' })
        .onChange((value: string) => {
          this.eventName = value
        })

      TextInput({ placeholder: 'Event Date' })
        .onChange((value: string) => {
          this.eventDate = value
        })

      TextInput({ placeholder: 'Event Location' })
        .onChange((value: string) => {
          this.eventLocation = value
        })

      Text('Perform a pinch gesture to validate')
        .fontSize(14)
        .onClick(() => {
          this.handlePinch()
        })

      if (this.isPinchValid) {
        Text('Pinch gesture validated!')
          .fontSize(14)
          .fontColor(Color.Green)
      }

      Button('Submit')
        .onClick(() => {
          if (this.validateForm()) {
            console.info('Form submitted successfully')
          }
        })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
      }
    }
    .width('100%')
    .padding(20)
  }
}

