import { Column, Text, Divider, Button, Color } from '@ohos.arkui';
import router from '@ohos.router';

@Entry
@Component
struct MarqueeComponent {
  @State private marqueeText: string = 'This is a horizontally scrolling marquee text. ';
  @State private marqueePosition: number = 0;
  @State private dividerColor: Color = Color.Black;
  @State private dividerThickness: number = 2;

  private marqueeInterval: number | null = null;

  aboutToAppear(): void {
    this.startMarquee();
  }

  aboutToDisappear(): void {
    if (this.marqueeInterval !== null) {
      clearInterval(this.marqueeInterval);
      this.marqueeInterval = null;
    }
  }

  private startMarquee(): void {
    this.marqueeInterval = setInterval(() => {
      this.marqueePosition -= 1;
      if (this.marqueePosition <= -this.marqueeText.length * 10) {
        this.marqueePosition = 0;
      }
    }, 50);
  }

  private toggleDivider(): void {
    this.dividerColor = this.dividerColor === Color.Black ? Color.Red : Color.Black;
    this.dividerThickness = this.dividerThickness === 2 ? 4 : 2;
  }

  private navigateToPage(): void {
    router.pushUrl({ url: 'pages/NextPage' });
  }

  build() {
    Column() {
      Column() {
        Text(this.marqueeText)
          .fontSize(16)
          .fontColor(Color.Black)
          .margin({ left: this.marqueePosition })
          .width('100%')
          .textOverflow({ overflow: TextOverflow.Clip })
          .maxLines(1);

        Divider()
          .strokeWidth(this.dividerThickness)
          .color(this.dividerColor)
          .margin({ top: 10, bottom: 10 })
          .onClick(() => this.toggleDivider());

        Button('Navigate')
          .width(120)
          .height(40)
          .fontSize(16)
          .fontColor(Color.White)
          .backgroundColor(Color.Blue)
          .onClick(() => this.navigateToPage());
      }
      .width('100%')
      .padding(20)
      .backgroundColor(0xF5F5F5);
    }
    .width('100%')
    .height('100%');
  }
}

@Entry
@Component
struct ThemeSwitchingList {
