import { Image, Video, VideoController, Column, Row, Stack, Text, Button } from '@ohos.arkui';
import { FontWeight, FlexAlign, HorizontalAlign } from '@ohos.arkui';

@Entry
@Component
struct WorkoutPlanner {
  @State count: number = 0;
  @State currentExerciseIndex: number = 0;
  @State isVideoPlaying: boolean = false;

  private exercises: string[] = ['Push-ups', 'Squats', 'Lunges', 'Plank'];
  private videoController: VideoController = new VideoController();

  private incrementCount(): void {
    this.count += 1;
  }

  private decrementCount(): void {
    if (this.count > 0) {
      this.count -= 1;
    }
  }

  private toggleVideoPlayback(): void {
    if (this.isVideoPlaying) {
      this.videoController.pause();
    } else {
      this.videoController.start();
    }
    this.isVideoPlaying = !this.isVideoPlaying;
  }

  private navigatePrevious(): void {
    if (this.currentExerciseIndex > 0) {
      this.currentExerciseIndex -= 1;
    }
  }

  private navigateNext(): void {
    if (this.currentExerciseIndex < this.exercises.length - 1) {
      this.currentExerciseIndex += 1;
    }
  }

  build() {
    Column() {
      Stack() {
        Image($r('app.media.workout_image'))
          .width(200)
          .height(200)
          .margin({ top: 20, bottom: 20 });

        Column() {
          Text(this.exercises[this.currentExerciseIndex])
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Row() {
            Button('Previous')
              .onClick(() => this.navigatePrevious())
              .margin({ right: 10 });
            Button('Next')
              .onClick(() => this.navigateNext());
          }
          .justifyContent(FlexAlign.Center)
          .margin({ bottom: 20 });

          Text(`Count: ${this.count}`)
            .fontSize(20)
            .margin({ bottom: 10 });

          Row() {
            Button('+')
              .onClick(() => this.incrementCount())
              .margin({ right: 10 });
            Button('-')
              .onClick(() => this.decrementCount());
          }
          .justifyContent(FlexAlign.Center)
          .margin({ bottom: 20 });

          Video({
            src: $r('app.media.workout_video'),
            controller: this.videoController
          })
            .width(300)
            .height(200)
            .controls(false)
            .onClick(() => this.toggleVideoPlayback());
        }
        .width('100%')
        .alignItems(HorizontalAlign.Center)
      }
      .width('100%')
      .height('100%')
      .padding(20)
    }
  }
}

import { Column, Text, Button, ScrollView, Row, ForEach } from '@ohos.arkui.dom';
import { BottomSheet } from '@ohos.arkui.advancedUI';

@Entry
@Component
struct Calculator {
  @State input: string = '';
  @State result: string = '';
  @State error: string = '';
  @State isBottomSheetVisible: boolean = false;

  private buttons: string[][] = [
    ['7', '8', '9', '/'],
    ['4', '5', '6', '*'],
    ['1', '2', '3', '-'],
    ['0', '.', '=', '+']
  ];

  private calculate(): void {
    try {
      if (this.input.includes('/0')) {
        throw new Error('Division by zero');
      }
      if (/[+\-*/]{2,}/.test(this.input)) {
        throw new Error('Invalid operator sequence');
      }
      this.result = this.safeEval(this.input).toString();
      this.error = '';
    } catch (e) {
      this.error = e.message || 'Invalid expression';
      this.result = '';
    }
  }

  private safeEval(expr: string): number {
    const tokens = expr.split(/([+\-*/])/);
    let result = parseFloat(tokens[0]);
    for (let i = 1; i < tokens.length; i += 2) {
      const op = tokens[i];
      const num = parseFloat(tokens[i+1]);
      switch(op) {
        case '+': result += num; break;
        case '-': result -= num; break;
        case '*': result *= num; break;
        case '/': result /= num; break;
      }
    }
    return result;
  }

  private handleButtonPress(button: string): void {
    if (button === '=') {
      this.calculate();
    } else {
      this.input += button;
      this.error = '';
    }
  }

  build() {
    Column() {
      Button('Open Calculator')
        .onClick(() => {
          this.isBottomSheetVisible = true;
        });

      BottomSheet({
        show: this.isBottomSheetVisible,
        height: '60%',
        onDismiss: () => { this.isBottomSheetVisible = false; }
      }) {
        Column() {
          Text(this.input)
            .fontSize(24)
            .margin(10);

          Text(this.result)
            .fontSize(24)
            .margin(10);

          Text(this.error)
            .fontSize(16)
            .fontColor(0xFF0000)
            .margin(10);

          ScrollView() {
            Column() {
              ForEach(this.buttons, (row: string[]) => {
                Row() {
                  ForEach(row, (button: string) => {
                    Button(button)
                      .width('25%')
                      .height(60)
                      .margin(5)
                      .onClick(() => {
                        this.handleButtonPress(button);
                      });
                  });
                }
                .width('100%');
              });
            }
          }
          .width('100%')
          .height('100%');
        }
        .width('100%')
        .height('100%');
      }
    }
    .width('100%')
    .height('100%');
  }
}

