@Entry
@Component
struct FoodDeliveryApp {
    @State isLoading: boolean = false
    @State progressValue: number = 0
    @State foodItems: string[] = []
    @State selectedItem: string = ""
    @State isPlaying: boolean = false

    aboutToAppear() {
        this.fetchFoodItems()
    }

    private fetchFoodItems() {
        this.isLoading = true
        this.progressValue = 0
        let interval = setInterval(() => {
            if (this.progressValue < 100) {
                this.progressValue += 10
            } else {
                clearInterval(interval)
                this.isLoading = false
                this.foodItems = ['Pizza', 'Burger', 'Sushi', 'Pasta', 'Salad']
            }
        }, 500)
    }

    private toggleAudioPlayback() {
        this.isPlaying = !this.isPlaying
    }

    build() {
        Column() {
            if (this.isLoading) {
                Progress({
                    value: this.progressValue,
                    total: 100,
                    type: ProgressType.Linear
                })
                .size({ width: '80%', height: 20 })
                .color(Color.Blue)
                Text('Loading Menu...').fontSize(20).margin(10)
            } else {
                List() {
                    ForEach(this.foodItems, (item: string) => {
                        ListItem() {
                            Row() {
                                Image($r('app.media.app_icon'))
                                    .width(50)
                                    .height(50)
                                    .margin(10)
                                Text(item).fontSize(20)
                            }
                            .onClick(() => {
                                this.selectedItem = item
                            })
                        }
                    }, (item: string) => item)
                }
                .onScrollIndex((start: number, end: number) => {
                    console.log(`Scrolled from ${start} to ${end}`)
                })
                .divider({ strokeWidth: 1, color: Color.Gray })

                if (this.selectedItem) {
                    Text(`Selected: ${this.selectedItem}`).fontSize(20).margin(10)
                    Button(this.isPlaying ? 'Stop Audio' : 'Play Audio')
                        .onClick(() => this.toggleAudioPlayback())
                        .margin(10)
                }
            }
        }
        .width('100%')
        .height('100%')
        .padding(20)
        .backgroundColor(Color.White)
    }
}

