import promptAction from '@ohos.promptAction';

@Entry
@Component
struct LoginCard {
  @State email: string = '';
  @State password: string = '';
  @State isLoggedIn: boolean = false;
  @State welcomeMessage: string = '';

  build() {
    Column() {
      if (!this.isLoggedIn) {
        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
          .margin({ bottom: 20 });

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 10 })
          .onChange((value: string) => {
            this.email = value;
          });

        TextInput({ placeholder: 'Enter your password' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .type(InputType.Password)
          .onChange((value: string) => {
            this.password = value;
          });

        Button('Login')
          .width('100%')
          .height(40)
          .onClick(() => {
            if (this.email.trim() === '' || this.password.trim() === '') {
              promptAction.showToast({ message: 'Please fill in all fields', duration: 2000 });
            } else {
              this.isLoggedIn = true;
              this.welcomeMessage = `Welcome, ${this.email}`;
              promptAction.showToast({ message: 'Login successful', duration: 2000 });
            }
          });
      } else {
        Text(this.welcomeMessage)
          .fontSize(20)
          .margin({ bottom: 20 });

        Button('Logout')
          .width('100%')
          .height(40)
          .onClick(() => {
            this.isLoggedIn = false;
            this.email = '';
            this.password = '';
            promptAction.showToast({ message: 'Logged out successfully', duration: 2000 });
          });
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

import { Switch } from '@ohos.arkui.component';
import { Gesture, GestureEvent, RotationGestureEvent } from '@ohos.multimodalInput.gesture';
import promptAction from '@ohos.promptAction';
import { Color } from '@ohos.arkui.drawing';

@Entry
@Component
struct MarqueeApp {
  @State marqueeText: string = "Customizable Marquee Text";
  @State marqueeSpeed: number = 2;
  @State marqueePosition: number = 0;
  @State isMarqueeRunning: boolean = true;
  @State gestureEnabled: boolean = true;
  private timer: number = 0;

  aboutToDisappear() {
    if (this.timer) {
      clearTimeout(this.timer);
    }
  }

  startMarquee() {
    if (this.timer) {
      clearTimeout(this.timer);
    }
    const animate = () => {
      if (this.isMarqueeRunning) {
        this.marqueePosition -= this.marqueeSpeed;
        if (this.marqueePosition <= -this.marqueeText.length * 20) {
          this.marqueePosition = 0;
        }
        this.timer = setTimeout(animate, 16);
      }
    };
    animate();
  }

  stopMarquee() {
    this.isMarqueeRunning = false;
    if (this.timer) {
      clearTimeout(this.timer);
    }
  }

  handleVoiceCommand(command: string) {
    if (command === "start marquee") {
      this.isMarqueeRunning = true;
      this.startMarquee();
    } else if (command === "stop marquee") {
      this.stopMarquee();
    }
  }

  build() {
    Column() {
      Text(this.marqueeText)
        .fontSize(20)
        .fontColor(Color.Black)
        .margin({ top: 20 })
        .translate({ x: this.marqueePosition, y: 0 })
        .gesture(
          Gesture()
            .onPan((event: GestureEvent) => {
              if (this.gestureEnabled) {
                this.marqueePosition += event.offsetX;
              }
            })
            .onPinch((event: GestureEvent) => {
              if (this.gestureEnabled) {
                this.marqueeSpeed = Math.max(1, Math.min(5, this.marqueeSpeed + event.scale));
              }
            })
            .onRotation((event: RotationGestureEvent) => {
              if (this.gestureEnabled) {
                this.marqueeText = `Rotated: ${event.angle.toFixed(1)}\u00b0`;
              }
            })
            .onTap(() => {
              if (this.gestureEnabled) {
                this.marqueeText = "Tapped!";
              }
            })
        )

      Switch({ isOn: this.gestureEnabled })
        .onChange((isChecked: boolean) => {
          this.gestureEnabled = isChecked;
        })
        .margin({ top: 20 })

      Button("Start Marquee")
        .onClick(() => {
          this.isMarqueeRunning = true;
          this.startMarquee();
        })
        .margin({ top: 20 })

      Button("Stop Marquee")
        .onClick(() => {
          this.stopMarquee();
        })
        .margin({ top: 20 })
    }
    .width("100%")
    .height("100%")
    .backgroundColor(Color.White)
    .onAppear(() => {
      this.startMarquee();
    })
  }
}

import { Column, Text, Row, Button, TextInput } from '@ohos.arkui.advanced';
import { BottomSheet } from '@ohos.arkui.advanced';
import { Chip } from '@ohos.arkui.advanced';
import { FlexAlign } from '@ohos.arkui.advanced';

@Entry
@Component
struct FileHandlingComponent {
  @State fileList: string[] = ['notes.txt', 'tasks.json', 'meeting.pdf'];
  @State selectedFile: string = '';
  @State showBottomSheet: boolean = false;
  @State locationData: string = '';
  @State errorMessage: string = '';

  @Builder
  bottomSheetBuilder() {
    Column() {
      Text(`Selected File: ${this.selectedFile}`)
        .fontSize(18)
        .margin(10);

      TextInput({ placeholder: 'Enter location data' })
        .width('90%')
        .height(50)
        .onChange((value: string) => {
          this.locationData = value;
        })
        .margin(10);

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor('#ff0000')
          .margin(10);
      }

      Row() {
        Button('Save')
          .onClick(() => {
            if (!this.locationData.trim()) {
              this.errorMessage = 'Location data cannot be empty';
              return;
            }
            this.errorMessage = '';
            this.showBottomSheet = false;
          })
          .width('40%')
          .margin(10);

        Button('Cancel')
          .onClick(() => {
            this.showBottomSheet = false;
          })
          .width('40%')
          .margin(10);
      }
      .justifyContent(FlexAlign.SpaceAround);
    }
    .width('100%')
    .padding(20);
  }

  build() {
    Column() {
      Column() {
        ForEach(this.fileList, (file: string) => {
          Chip({ type: 'input' }) {
            Text(file)
          }
          .onClick(() => {
            this.selectedFile = file;
            this.showBottomSheet = true;
          })
          .minWidth(100)
          .minHeight(40)
          .borderRadius(20)
          .padding(10)
          .margin(5);
        });
      }
      .width('100%')
      .padding(10);

      if (this.showBottomSheet) {
        BottomSheet({
          height: '40%',
          dragBar: true,
          showClose: true
        })
        .onClose(() => {
          this.showBottomSheet = false;
        })
        .animation({ duration: 300, curve: 'ease' }) {
          this.bottomSheetBuilder()
        }
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff');
  }
}

import { Column, Text, Button, Image, Slider, Row, Entry, Component } from '@ohos.arkui.advanced';
import { State } from '@ohos.arkui.common';
import { FlexAlign, FontWeight, Color } from '@ohos.arkui.advanced';

interface Track {
  title: string;
  artist: string;
}

@Entry
@Component
struct MusicPlayer {
  @State currentTrackIndex: number = 0;
  @State isPlaying: boolean = false;
  @State progress: number = 0;
  @State cachedTracks: boolean = false;

  private tracks: Track[] = [
    { title: 'Track 1', artist: 'Artist 1' },
    { title: 'Track 2', artist: 'Artist 2' },
    { title: 'Track 3', artist: 'Artist 3' }
  ];

  build() {
    Column() {
      Image($r('app.media.icon'))
        .width(200)
        .height(200)
        .borderRadius(10)
        .margin({ top: 20 });

      Text(this.tracks[this.currentTrackIndex].title)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20 });

      Text(this.tracks[this.currentTrackIndex].artist)
        .fontSize(18)
        .margin({ top: 5 });

      Slider({
        value: this.progress,
        min: 0,
        max: 100,
        step: 1
      })
        .width('80%')
        .margin({ top: 20 });

      Row({ space: 20 }) {
        Button('Previous')
          .enabled(this.currentTrackIndex > 0)
          .onClick(() => {
            if (this.currentTrackIndex > 0) {
              this.currentTrackIndex--;
            }
          });

        Button(this.isPlaying ? 'Pause' : 'Play')
          .onClick(() => {
            this.isPlaying = !this.isPlaying;
          });

        Button('Next')
          .enabled(this.currentTrackIndex < this.tracks.length - 1)
          .onClick(() => {
            if (this.currentTrackIndex < this.tracks.length - 1) {
              this.currentTrackIndex++;
            }
          });
      }
