      Button(this.cachedTracks ? 'Cached' : 'Cache All')
        .onClick(() => {
          this.cachedTracks = !this.cachedTracks;
        })
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor(Color.White);
  }
}

import router from '@ohos.router';
import { Column, Text, Image, Stack, Button, Row, ForEach } from '@ohos.arkui.advanced';
import { TapGesture, PanGesture, PinchGesture } from '@ohos.multimodalInput.gesture';
import { Curve } from '@ohos.animation';

interface PanEvent {
  offsetX: number;
  offsetY: number;
}

interface PinchEvent {
  scale: number;
}

@Entry
@Component
struct VideoPicker {
  @State private selectedFile: string = '';
  @State private gestureState: string = 'No gesture detected';
  @State private videoScale: number = 1.0;
  @State private videoOffsetX: number = 0;
  @State private videoOffsetY: number = 0;

  private fileList: string[] = ['File 1', 'File 2', 'File 3', 'File 4'];

  build() {
    Column() {
      Text(this.gestureState)
        .fontSize(16)
        .margin({ bottom: 10 });

      Stack() {
        Image($r('app.media.ic_public_picture'))
          .width(300)
          .height(200)
          .gesture(
            TapGesture()
              .onAction(() => {
                this.gestureState = 'Tap detected';
              }),
            PanGesture()
              .onActionUpdate((event: PanEvent) => {
                this.videoOffsetX = event.offsetX;
                this.videoOffsetY = event.offsetY;
                this.gestureState = 'Pan: X=' + event.offsetX + ', Y=' + event.offsetY;
              }),
            PinchGesture()
              .onActionUpdate((event: PinchEvent) => {
                this.videoScale = event.scale;
                this.gestureState = 'Pinch: Scale=' + event.scale;
              })
          )
          .transform({ translate: { x: this.videoOffsetX, y: this.videoOffsetY }, scale: { x: this.videoScale, y: this.videoScale } })
          .animation({ duration: 300, curve: Curve.Ease });
      }
      .width(300)
      .height(200)
      .margin({ bottom: 20 });

      Column() {
        ForEach(this.fileList, (file: string) => {
          Button(file)
            .onClick(() => {
              this.selectedFile = file;
              this.gestureState = 'Selected: ' + file;
            })
            .margin({ bottom: 5 });
        });
      }
      .width('100%')
      .alignItems(HorizontalAlign.Start)
      .margin({ bottom: 20 });

      Button('Navigate to Second Page')
        .onClick(() => {
          router.pushUrl({ url: 'pages/SecondPage' });
        });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5');
  }
}

import promptAction from '@ohos.promptAction';
import { DatePicker } from '@ohos.arkui.advanced';

interface DatePickerValue {
  year: number;
  month: number;
  day: number;
}

@Entry
@Component
struct FitnessTracker {
  @State selectedDate: Date = new Date();
  @State displayDate: string = '';

  aboutToAppear() {
    this.updateDisplayDate();
  }

  updateDisplayDate() {
    this.displayDate = this.selectedDate.toLocaleDateString();
  }

  showAlert() {
    promptAction.showDialog({
      title: 'Alert',
      message: 'Fitness goal achieved!',
      buttons: [
        {
          text: 'OK',
          color: '#000000'
        }
      ]
    }).then(() => {
      console.log('Alert dialog closed');
    });
  }

  build() {
    Column() {
      Text('Fitness Tracker')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      DatePicker({
        start: new Date('2000-01-01'),
        end: new Date('2030-12-31'),
        selected: this.selectedDate
      })
        .onChange((value: DatePickerValue) => {
          this.selectedDate = new Date(value.year, value.month - 1, value.day);
          this.updateDisplayDate();
        })
        .margin({ bottom: 20 });

      Canvas()
        .width('100%')
        .height(200)
        .backgroundColor('#f0f0f0')
        .onReady((canvas: CanvasRenderingContext2D) => {
          const ctx = canvas.getContext('2d');
          ctx.fillStyle = '#4CAF50';
          ctx.fillRect(0, 0, canvas.width, canvas.height);
        });

      Button('Trigger Alert')
        .onClick(() => {
          this.showAlert();
        })
        .margin({ top: 20 });
    }
    .padding(16)
    .width('100%')
    .height('100%');
  }
}

