import { List, ListItem, Column, Row, Text, Radio, RadioGroup, Video, VideoController, Resource } from '@ohos.arkui.advanced';

interface Message {
  id: number;
  text: string;
  videoUrl: Resource;
  isPlaying: boolean;
  playbackState: 'play' | 'pause' | 'stop';
  controller: VideoController;
}

@Entry
@Component
struct MessagingInterface {
  @State messages: Message[] = [
    { 
      id: 1, 
      text: 'Message 1', 
      videoUrl: $r('app.media.video'),
      isPlaying: false, 
      playbackState: 'stop',
      controller: new VideoController()
    },
    { 
      id: 2, 
      text: 'Message 2', 
      videoUrl: $r('app.media.video'),
      isPlaying: false, 
      playbackState: 'stop',
      controller: new VideoController()
    },
    { 
      id: 3, 
      text: 'Message 3', 
      videoUrl: $r('app.media.video'),
      isPlaying: false, 
      playbackState: 'stop',
      controller: new VideoController()
    }
  ];

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.messages, (message: Message) => {
          ListItem() {
            Column() {
              Text(message.text)
                .fontSize(16)
                .margin({ bottom: 10 });

              Video({
                src: message.videoUrl,
                controller: message.controller
              })
                .width('100%')
                .height(200)
                .onPrepared(() => {
                  console.log('Video prepared');
                });

              RadioGroup({ group: `group_${message.id}` }) {
                Row() {
                  Radio({ value: 'play' })
                    .checked(message.playbackState === 'play')
                    .onChange((isChecked: boolean) => {
                      if (isChecked) {
                        this.messages = this.messages.map(msg => {
                          if (msg.id === message.id) {
                            return {
                              id: msg.id,
                              text: msg.text,
                              videoUrl: msg.videoUrl,
                              isPlaying: true,
                              playbackState: 'play',
                              controller: msg.controller
                            };
                          }
                          return msg;
                        });
                      }
                    });

                  Radio({ value: 'pause' })
                    .checked(message.playbackState === 'pause')
                    .onChange((isChecked: boolean) => {
                      if (isChecked) {
                        this.messages = this.messages.map(msg => {
                          if (msg.id === message.id) {
                            return {
                              id: msg.id,
                              text: msg.text,
                              videoUrl: msg.videoUrl,
                              isPlaying: false,
                              playbackState: 'pause',
                              controller: msg.controller
                            };
                          }
                          return msg;
                        });
                      }
                    });

                  Radio({ value: 'stop' })
                    .checked(message.playbackState === 'stop')
                    .onChange((isChecked: boolean) => {
                      if (isChecked) {
                        this.messages = this.messages.map(msg => {
                          if (msg.id === message.id) {
                            return {
                              id: msg.id,
                              text: msg.text,
                              videoUrl: msg.videoUrl,
                              isPlaying: false,
                              playbackState: 'stop',
                              controller: msg.controller
                            };
                          }
                          return msg;
                        });
                      }
                    });
                }
              }
            }
            .width('100%')
            .padding(10)
          }
        })
      }
      .layoutWeight(1)
      .width('100%')
    }
    .width('100%')
    .height('100%')
  }
}

