interface DialogProps {
  title: string;
  message: string;
  confirm: ConfirmAction;
  cancel: () => void;
}

interface ConfirmAction {
  value: string;
  action: () => void;
}

@Entry
@Component
struct OnboardingActionSheet {
  @State currentStep: number = 0;
  @State isActionSheetVisible: boolean = false;
  @State buttonScale: number = 1;
  @State buttonColor: Color = Color.Blue;

  private steps: string[] = ['Welcome to the App', 'Choose Preferences', 'Complete Setup'];

  @Builder
  CustomDialogContent(dialogProps: DialogProps) {
    Column() {
      Text(dialogProps.title).fontSize(20).fontWeight(FontWeight.Bold);
      Text(dialogProps.message).margin({ top: 10 });

      Row() {
        Button(dialogProps.confirm.value)
          .onClick(dialogProps.confirm.action);
        Button('Cancel')
          .onClick(dialogProps.cancel);
      }.margin({ top: 20 });
    }
  }

  build() {
    Column() {
      Button('Start Onboarding')
        .width(200)
        .height(50)
        .backgroundColor(this.buttonColor)
        .scale({ x: this.buttonScale, y: this.buttonScale })
        .onClick(() => {
          animateTo({
            duration: 200,
            curve: Curve.EaseInOut
          }, () => {
            this.buttonScale = 0.9;
            this.buttonColor = Color.Green;
          });

          setTimeout(() => {
            animateTo({
              duration: 200,
              curve: Curve.EaseInOut
            }, () => {
              this.buttonScale = 1;
              this.buttonColor = Color.Blue;
              this.isActionSheetVisible = true;
            });
          }, 200);
        });

      if (this.isActionSheetVisible) {
        this.CustomDialogContent({
          title: 'Onboarding Steps',
          message: 'This will guide you through the app setup.',
          confirm: {
            value: 'Next',
            action: () => {
              if (this.currentStep < this.steps.length - 1) {
                this.currentStep++;
              } else {
                this.isActionSheetVisible = false;
              }
            }
          } as ConfirmAction,
          cancel: () => {
            this.isActionSheetVisible = false;
          }
        } as DialogProps);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

import { Column, Row, Text } from '@ohos.arkui.UIContext';
import { Component, State, Entry, Builder } from '@ohos.arkui.component';

@Entry
@Component
struct BreadcrumbNavigation {
  @State breadcrumbs: string[] = ['Home', 'Quiz', 'Question'];
  @State currentContent: string = 'Home Content';

  @Builder
  BreadcrumbItem(text: string, index: number) {
    Text(text)
      .fontColor(this.breadcrumbs.length - 1 === index ? '#1698CE' : '#6B6B6B')
      .fontSize(16)
      .margin({ right: 8 })
      .accessibilityLabel(`Breadcrumb ${text}`)
      .onClick(() => {
        this.breadcrumbs = this.breadcrumbs.slice(0, index + 1);
        this.updateContent();
      });
  }

  updateContent() {
    const lastItem = this.breadcrumbs[this.breadcrumbs.length - 1];
    this.currentContent = `${lastItem} Content`;
  }

  build() {
    Column() {
      Row() {
        ForEach(this.breadcrumbs, (item: string, index: number) => {
          this.BreadcrumbItem(item, index);
          if (index < this.breadcrumbs.length - 1) {
            Text('>')
              .fontColor('#6B6B6B')
              .fontSize(16)
              .margin({ right: 8 })
              .accessibilityLabel('Breadcrumb separator');
          }
        });
      }
      .padding(16)
      .width('100%')
      .justifyContent('flex-start');

      Text(this.currentContent)
        .fontSize(20)
        .margin({ top: 16 })
        .accessibilityLabel(`Content for ${this.breadcrumbs[this.breadcrumbs.length - 1]}`);
    }
    .width('100%')
    .height('100%')
    .padding(16);
  }
}

