import { Column, Row, List, ListItem, Text, Image, TextInput, Checkbox, ImageFit, FontWeight } from '@ohos.arkui.component';
import { Gesture, GestureType, RotationGestureEvent } from '@ohos.arkui.gesture';
import { State } from '@ohos.arkui.advancedUI';

interface Comic {
  id: number;
  title: string;
  cover: Resource;
  genre: string;
}

@Entry
@Component
struct ComicReaderApp {
  @State comics: Comic[] = [
    { id: 1, title: 'Comic 1', cover: $r('app.media.ic_default_image'), genre: 'Action' },
    { id: 2, title: 'Comic 2', cover: $r('app.media.ic_default_image'), genre: 'Adventure' },
    { id: 3, title: 'Comic 3', cover: $r('app.media.ic_default_image'), genre: 'Comedy' },
    { id: 4, title: 'Comic 4', cover: $r('app.media.ic_default_image'), genre: 'Drama' },
    { id: 5, title: 'Comic 5', cover: $r('app.media.ic_default_image'), genre: 'Sci-Fi' }
  ];

  @State searchQuery: string = '';
  @State selectedGenres: string[] = [];
  @State currentPage: number = 1;
  @State totalPages: number = 5;

  private genres: string[] = ['Action', 'Adventure', 'Comedy', 'Drama', 'Sci-Fi'];

  get filteredComics(): Comic[] {
    let filtered = this.comics;
    if (this.searchQuery) {
      filtered = filtered.filter(comic => comic.title.toLowerCase().includes(this.searchQuery.toLowerCase()));
    }
    if (this.selectedGenres.length > 0) {
      filtered = filtered.filter(comic => this.selectedGenres.includes(comic.genre));
    }
    return filtered;
  }

  build() {
    Column() {
      TextInput({ placeholder: 'Search comics...' })
        .width('90%')
        .height(40)
        .margin({ top: 10, bottom: 10 })
        .onChange((value: string) => {
          this.searchQuery = value;
        });

      Column() {
        ForEach(this.genres, (genre: string) => {
          Row() {
            Checkbox()
              .onChange((isChecked: boolean) => {
                if (isChecked) {
                  this.selectedGenres.push(genre);
                } else {
                  this.selectedGenres = this.selectedGenres.filter(g => g !== genre);
                }
              });
            Text(genre)
              .fontSize(14)
              .margin({ left: 5 });
          }
          .margin({ bottom: 5 });
        });
      }
      .width('90%')
      .margin({ bottom: 10 });

      List() {
        ForEach(this.filteredComics, (comic: Comic) => {
          ListItem() {
            Row() {
              Image(comic.cover)
                .width(100)
                .height(150)
                .objectFit(ImageFit.Contain)
                .margin({ right: 10 });
              Column() {
                Text(comic.title)
                  .fontSize(18)
                  .fontWeight(FontWeight.Bold);
                Text(comic.genre)
                  .fontSize(14)
                  .opacity(0.7);
              }
            }
            .padding(10);
          }
          .margin({ bottom: 10 });
        });
      }
      .width('100%')
      .layoutWeight(1);

      Stack() {
        Column() {
          Gesture(GestureType.Rotation)
            .onRotate((event: RotationGestureEvent) => {
              if (event.angle > 0) {
                this.currentPage = Math.min(this.currentPage + 1, this.totalPages);
              } else {
                this.currentPage = Math.max(this.currentPage - 1, 1);
              }
            })
        }
        .width('100%')
        .height(100);
      }

      Text(`Page ${this.currentPage} of ${this.totalPages}`)
        .fontSize(16)
        .margin({ top: 10, bottom: 10 });
    }
    .width('100%')
    .height('100%')
    .padding(10);
  }
}

