import { Column, Text, Button, Stack } from '@ohos.arkui.advanced.UI';
import { Color, FontWeight, TextAlign, FlexAlign, HorizontalAlign } from '@ohos.arkui.advanced.UI';
import { animateTo, curves } from '@ohos.arkui.advanced.anim';
import { ActionSheet } from '@ohos.arkui.advanced.UI';

@Entry
@Component
struct CustomNavigationApp {
  @State currentScreen: number = 0;
  @State buttonScale: number = 1;
  @State buttonColor: Color = Color.Blue;
  @State isActionSheetVisible: boolean = false;
  @State isPlaying: boolean = false;

  build() {
    Stack() {
      if (this.currentScreen === 0) {
        Column() {
          Text('Home Screen')
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 30 })
            .transition({ type: 'Insert', opacity: 0, translate: { x: 0, y: -100 } })
            .transition({ type: 'Delete', opacity: 0, translate: { x: 0, y: 100 } });

          Button('Go to Video Screen')
            .width(200)
            .height(50)
            .backgroundColor(this.buttonColor)
            .scale({ x: this.buttonScale, y: this.buttonScale })
            .onClick(() => {
              animateTo({
                duration: 200,
                curve: curves.EaseInOut
              }, () => {
                this.buttonScale = 0.9;
                this.buttonColor = Color.Green;
              });

              setTimeout(() => {
                animateTo({
                  duration: 200,
                  curve: curves.EaseInOut
                }, () => {
                  this.buttonScale = 1;
                  this.buttonColor = Color.Blue;
                  this.currentScreen = 1;
                });
              }, 200);
            })
            .margin({ top: 20 });
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center);
      }

      if (this.currentScreen === 1) {
        Column() {
          Text('Video Player')
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 30 })
            .transition({ type: 'Insert', opacity: 0, translate: { x: 100, y: 0 } })
            .transition({ type: 'Delete', opacity: 0, translate: { x: -100, y: 0 } });

          Text('Video Placeholder')
            .width(300)
            .height(200)
            .backgroundColor(Color.Gray)
            .textAlign(TextAlign.Center)
            .fontSize(18)
            .margin({ bottom: 20 });

          Button('Show Controls')
            .width(200)
            .height(50)
            .backgroundColor(this.buttonColor)
            .scale({ x: this.buttonScale, y: this.buttonScale })
            .onClick(() => {
              animateTo({
                duration: 200,
                curve: curves.EaseInOut
              }, () => {
                this.buttonScale = 0.9;
                this.buttonColor = Color.Red;
              });

              setTimeout(() => {
                animateTo({
                  duration: 200,
                  curve: curves.EaseInOut
                }, () => {
                  this.buttonScale = 1;
                  this.buttonColor = Color.Blue;
                  ActionSheet.showActionSheet({
                    title: 'Video Controls',
                    buttons: [
                      { text: this.isPlaying ? 'Pause' : 'Play' },
                      { text: 'Stop' },
                      { text: 'Cancel' }
                    ]
                  }).then((index: number) => {
                    try {
                      if (index === 0) {
                        this.isPlaying = !this.isPlaying;
                      } else if (index === 1) {
                        this.isPlaying = false;
                      }
                    } catch (error) {
                      console.error('Playback control error:', error.message);
                    }
                  }).catch((error: Error) => {
                    console.error('ActionSheet error:', error.message);
                  });
                });
              }, 200);
            })
            .margin({ top: 20 });

          Button('Go Back')
            .width(200)
            .height(50)
            .backgroundColor(this.buttonColor)
            .scale({ x: this.buttonScale, y: this.buttonScale })
            .onClick(() => {
              animateTo({
                duration: 200,
                curve: curves.EaseInOut
              }, () => {
                this.buttonScale = 0.9;
                this.buttonColor = Color.Red;
              });

@Entry
@Component
struct BreadcrumbWithSensors {
  @State breadcrumbItems: string[] = ['Home', 'Audio', 'Playback'];
  @State selectedItem: string = '';
  @State isPlaying: boolean = false;
  @State showBadge: boolean = false;
  @State toastMessage: string = '';
  @State toastVisible: boolean = false;

  private showToast(message: string) {
    this.toastMessage = message;
    this.toastVisible = true;
    setTimeout(() => {
      this.toastVisible = false;
    }, 3000);
  }

  private togglePlayback() {
    this.isPlaying = !this.isPlaying;
    this.showBadge = this.isPlaying;
    this.showToast(this.isPlaying ? 'Playback started' : 'Playback stopped');
  }

  private selectBreadcrumbItem(item: string) {
    this.selectedItem = item;
    this.showToast(`Selected: ${item}`);
  }

  build() {
    Column({ space: 20 }) {
      Row({ space: 10 }) {
        ForEach(this.breadcrumbItems, (item: string) => {
          Text(item)
            .fontSize(16)
            .fontColor(this.selectedItem === item ? '#007AFF' : '#000000')
            .onClick(() => {
              this.selectBreadcrumbItem(item);
            });
          if (item !== this.breadcrumbItems[this.breadcrumbItems.length - 1]) {
            Text('>')
              .fontSize(16)
              .fontColor('#000000');
          }
        });
      }

      Button(this.isPlaying ? 'Stop Playback' : 'Start Playback')
        .onClick(() => {
          this.togglePlayback();
        })
        .width('50%')
        .height('10%');

      if (this.showBadge) {
        Text('Playing')
          .fontSize(14)
          .backgroundColor('#FF0000')
          .padding(5)
          .borderRadius(10)
          .margin({ top: 10 });
      }

      if (this.toastVisible) {
        Text(this.toastMessage)
          .fontSize(16)
          .backgroundColor('#CCCCCC')
          .padding(10)
          .borderRadius(5)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

import { Column, Row, Stack, Image, Text, Button, Divider } from '@ohos.arkui.advanced';
import { ImageFit, FlexAlign } from '@ohos.arkui.advanced';
import { animateTo, Curve } from '@ohos.animation';

@Entry
@Component
struct ComicReader {
  @State private currentPage: number = 0;
  @State private isAnimating: boolean = false;
  private comicPages: Resource[] = [
    $r('app.media.example_image1'),
    $r('app.media.example_image2'),
    $r('app.media.example_image3'),
    $r('app.media.example_image4'),
    $r('app.media.example_image5')
  ];

  private navigateToPage(direction: number): void {
    if (this.isAnimating) return;
    const newPage = this.currentPage + direction;
    if (newPage < 0 || newPage >= this.comicPages.length) return;

    this.isAnimating = true;
    animateTo({
      duration: 500,
      curve: Curve.EaseOut,
      onFinish: () => {
        this.currentPage = newPage;
        this.isAnimating = false;
      }
    });
  }

  build() {
    Column() {
      Stack() {
        Image(this.comicPages[this.currentPage])
          .width('100%')
          .height('100%')
          .objectFit(ImageFit.Contain)
          .opacity(this.isAnimating ? 0.5 : 1)
      }
      .width('100%')
      .height('80%')

      Divider()

      Row() {
        Button('Previous')
          .onClick(() => this.navigateToPage(-1))
          .enabled(this.currentPage > 0 && !this.isAnimating)

        Text((this.currentPage + 1).toString() + ' of ' + this.comicPages.length.toString())
          .fontSize(16)
          .margin({ left: 20, right: 20 })

        Button('Next')
          .onClick(() => this.navigateToPage(1))
          .enabled(this.currentPage < this.comicPages.length - 1 && !this.isAnimating)
      }
      .justifyContent(FlexAlign.Center)
      .width('100%')
      .margin({ top: 10, bottom: 10 })
    }
    .width('100%')
    .height('100%')
    .padding(10)
  }
}

