import { Column, Text, Button, FlexAlign, FontWeight, ButtonType } from '@ohos.arkui';
import promptAction from '@ohos.promptAction';
import common from '@ohos.app.ability.common';

@Entry
@Component
struct StepCounter {
  @State steps: number = 0;
  private context = getContext(this) as common.UIAbilityContext;

  private async authenticateAndIncrement() {
    try {
      const mockAuth = await this.mockAuthentication();
      if (mockAuth) {
        this.steps++;
        promptAction.showToast({ message: 'Step counted!' });
      }
    } catch (error) {
      console.error('Authentication failed:', error.message);
      promptAction.showToast({ message: 'Authentication failed' });
    }
  }

  private mockAuthentication(): Promise<boolean> {
    return new Promise((resolve) => {
      setTimeout(() => resolve(Math.random() < 0.8), 500);
    });
  }

  build() {
    Column() {
      Text(`Steps: ${this.steps}`)
        .fontSize(36)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Button('Increment Step')
        .type(ButtonType.Capsule)
        .width('60%')
        .height(50)
        .backgroundColor('#007DFF')
        .onClick(() => {
          this.authenticateAndIncrement();
        })
        .margin({ bottom: 20 });

      Button('Reset')
        .type(ButtonType.Capsule)
        .width('60%')
        .height(50)
        .backgroundColor('#FF0000')
        .onClick(() => {
          this.steps = 0;
          promptAction.showToast({ message: 'Counter reset' });
        });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

