import { Button, Column, Row, Text, Checkbox, CustomDialogController, DialogAlignment, HorizontalAlign } from '@ohos.arkui.advancedUI';
import { FontWeight, FlexAlign, GestureEvent } from '@ohos.arkui.common';
import { animateTo, Curve } from '@ohos.arkui.animator';
import { PanGesture } from '@ohos.arkui.gesture';

@Entry
@Component
struct MainScreen {
  @State dialogAnimationEnabled: boolean = true;
  @State dialogGestureEnabled: boolean = true;
  @State offsetX: number = 0;
  @State offsetY: number = 0;
  @State originalX: number = 0;
  @State originalY: number = 0;

  private dialogController: CustomDialogController = new CustomDialogController({
    builder: this.DialogBuilder,
    customStyle: true,
    alignment: DialogAlignment.Center
  });

  @Builder DialogBuilder() {
    Column() {
      Row() {
        Checkbox({ name: 'Enable Animation', group: 'controls' })
          .onChange((isChecked: boolean) => {
            this.dialogAnimationEnabled = isChecked;
          });
        Text('Enable Animation')
          .margin({ left: 8 });
      }
      .margin({ bottom: 16 });

      Row() {
        Checkbox({ name: 'Enable Gesture', group: 'controls' })
          .onChange((isChecked: boolean) => {
            this.dialogGestureEnabled = isChecked;
          });
        Text('Enable Gesture')
          .margin({ left: 8 });
      }
      .margin({ bottom: 16 });

      this.DraggableSquare();

      Button('Close')
        .width('100%')
        .height(40)
        .margin({ top: 16 })
        .onClick(() => {
          this.dialogController.close();
        });
    }
    .padding(24)
    .width('80%')
    .backgroundColor('#FFFFFF')
    .borderRadius(16)
    .shadow({ radius: 16, color: '#000000', offsetX: 4, offsetY: 4 });
  }

  @Builder DraggableSquare() {
    Column() {
      Text('Drag Me!')
        .fontSize(16)
        .fontWeight(FontWeight.Medium);
    }
    .width(200)
    .height(200)
    .backgroundColor('#4CAF50')
    .borderRadius(8)
    .gesture(
      PanGesture()
        .onActionStart(() => {
          if (this.dialogGestureEnabled) {
            this.originalX = this.offsetX;
            this.originalY = this.offsetY;
          }
        })
        .onActionUpdate((event: GestureEvent) => {
          if (this.dialogGestureEnabled) {
            this.offsetX = this.originalX + event.offsetX;
            this.offsetY = this.originalY + event.offsetY;
          }
        })
        .onActionEnd(() => {
          if (this.dialogGestureEnabled && this.dialogAnimationEnabled) {
            animateTo({
              duration: 300,
              curve: Curve.EaseOut
            }, () => {
              this.offsetX = 0;
              this.offsetY = 0;
            });
          }
        })
    )
    .translate({ x: this.offsetX, y: this.offsetY });
  }

  build() {
    Column() {
      Button('Open Dialog')
        .width(200)
        .height(50)
        .margin({ top: 20 })
        .onClick(() => {
          this.dialogController.open();
        });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

import { Progress } from '@ohos.multimedia.image';
import { Button, Column, Row, Text, Divider, Stack, Tabs, TabContent, FontWeight, FlexAlign } from '@ohos.arkui.ets';

@Entry
@Component
struct WorkoutPlanner {
  @State currentStep: number = 1;
  @State progressValue: number = 0;
  private totalSteps: number = 4;
  private workoutSteps: string[] = ['Warm-Up', 'Cardio', 'Strength Training', 'Cooldown'];

  updateProgress(): void {
    this.progressValue = (this.currentStep - 1) / (this.totalSteps - 1) * 100;
  }

  nextStep(): void {
    if (this.currentStep < this.totalSteps) {
      this.currentStep++;
      this.updateProgress();
    }
  }

  @Builder
  StepCircle(step: number) {
    Stack() {
      Stack()
        .width(40)
        .height(40)
        .borderRadius(20)
        .backgroundColor(this.currentStep >= step ? '#0000FF' : '#CCCCCC');
      Text(step.toString())
        .fontSize(20)
        .fontColor('#FFFFFF');
    }
  }

  build() {
    Column() {
      Row() {
        ForEach(this.workoutSteps, (step: string, index: number) => {
          Column() {
            this.StepCircle(index + 1);
            Text(step)
              .fontSize(16)
              .margin({ top: 10 });
          }
          .margin({ right: 20 });
        });
      }
      .justifyContent(FlexAlign.SpaceAround)
      .width('100%')
      .margin({ bottom: 20 });

      Progress({ value: this.progressValue })
        .width('90%')
        .height(10)
        .margin({ bottom: 20 });

      Tabs({ index: this.currentStep - 1 }) {
        ForEach(this.workoutSteps, (step: string) => {
          TabContent() {
            Column() {
              Text(`Step ${this.currentStep}`)
                .fontSize(24)
                .fontWeight(FontWeight.Bold);
              Text(step)
                .fontSize(20)
                .margin({ top: 16 });
            }
            .width('100%')
            .height('100%')
            .justifyContent(FlexAlign.Center);
          }
        });
      }
      .onChange((index: number) => {
        this.currentStep = index + 1;
        this.updateProgress();
      })
      .width('100%')
