import { Text, Button, Column, Image, Row, TextAlign, FlexAlign, Color } from '@ohos.arkui.advanced';

@Entry
@Component
struct CountdownTimer {
  @State timeLeft: number = 60;
  @State timerId: number | null = null;
  @State isCounting: boolean = false;
  @State buttonColor: Color = Color.Blue;

  aboutToDisappear() {
    if (this.timerId !== null) {
      clearInterval(this.timerId);
      this.timerId = null;
    }
  }

  build() {
    Column({ space: 10 }) {
      Image($r('app.media.ic_public_timer'))
        .width(100)
        .height(100)
        .margin({ bottom: 20 });

      Text(`Time left: ${this.timeLeft} seconds`)
        .fontSize(24)
        .textAlign(TextAlign.Center)
        .margin({ bottom: 20 });

      Row({ space: 10 }) {
        Button(this.isCounting ? 'Stop' : 'Start')
          .backgroundColor(this.buttonColor)
          .borderRadius(8)
          .padding(10)
          .onClick(() => {
            if (this.isCounting) {
              if (this.timerId !== null) {
                clearInterval(this.timerId);
                this.timerId = null;
              }
              this.isCounting = false;
            } else {
              this.isCounting = true;
              this.startTimer();
            }
          });

        Button('Reset')
          .backgroundColor(this.buttonColor)
          .borderRadius(8)
          .padding(10)
          .onClick(() => {
            if (this.timerId !== null) {
              clearInterval(this.timerId);
              this.timerId = null;
            }
            this.timeLeft = 60;
            this.isCounting = false;
          });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }

  startTimer() {
    this.timerId = setInterval(() => {
      if (this.timeLeft > 0) {
        this.timeLeft -= 1;
      } else {
        if (this.timerId !== null) {
          clearInterval(this.timerId);
          this.timerId = null;
        }
        this.isCounting = false;
      }
    }, 1000);
  }
}

import { Tabs, TabContent } from '@ohos.arkui.advanced';
import { Scroll } from '@ohos.arkui.component';
import { Web } from '@ohos.web.webview';
import webview from '@ohos.web.webview';

@Entry
@Component
struct MainApp {
  @State currentIndex: number = 0
  private webControllers: webview.WebviewController[] = [
    new webview.WebviewController(),
    new webview.WebviewController()
  ]
  @State isRefreshing: boolean = false
  @State refreshThreshold: number = 100

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.Bottom }) {
        TabContent() {
          this.FirstTab()
        }.tabBar('First')

        TabContent() {
          this.SecondTab()
        }.tabBar('Second')
      }
      .onChange((index: number) => {
        this.currentIndex = index
      })
    }
  }

  @Builder FirstTab() {
    Column() {
      Scroll() {
        Column() {
          Web({
            controller: this.webControllers[0],
            src: 'https://example.com'
          })
          .width('100%')
          .height('100%')
          .onPageBegin(() => {
            console.log('First tab page loading')
          })
        }
      }
      .onScroll((xOffset: number, yOffset: number) => {
        if (yOffset > this.refreshThreshold && !this.isRefreshing) {
          this.isRefreshing = true
          setTimeout(() => {
            this.webControllers[0].refresh()
            this.isRefreshing = false
          }, 1000)
        }
      })
    }
    .width('100%')
    .height('100%')
  }

  @Builder SecondTab() {
    Column() {
      Scroll() {
        Column() {
          Web({
            controller: this.webControllers[1],
            src: 'https://example.com'
          })
          .width('100%')
          .height('100%')
          .onPageBegin(() => {
            console.log('Second tab page loading')
          })
        }
      }
      .onScroll((xOffset: number, yOffset: number) => {
        if (yOffset > this.refreshThreshold && !this.isRefreshing) {
          this.isRefreshing = true
          setTimeout(() => {
            this.webControllers[1].refresh()
            this.isRefreshing = false
          }, 1000)
        }
      })
    }
    .width('100%')
    .height('100%')
  }
}

import promptAction from '@ohos.promptAction';

interface Task {
  id: number;
  title: string;
  completed: boolean;
}

@Entry
@Component
struct TaskManager {
  @State tasks: Task[] = [
    { id: 1, title: 'Task 1', completed: false },
    { id: 2, title: 'Task 2', completed: false },
    { id: 3, title: 'Task 3', completed: false }
  ];

  @State draggedTaskId: number | null = null;

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.tasks, (task: Task) => {
          ListItem() {
            Row() {
              Checkbox()
                .select(task.completed)
                .onChange((isSelected: boolean) => {
                  task.completed = isSelected;
                });
              Text(task.title)
                .fontSize(16)
                .margin({ left: 10 });
            }
            .width('100%')
            .justifyContent(FlexAlign.SpaceBetween)
            .gesture(
              PanGesture()
                .onActionStart(() => {
                  this.draggedTaskId = task.id;
                })
            );
          }
          .gesture(
            GestureGroup(GestureMode.Exclusive,
              PanGesture({ direction: PanDirection.Horizontal })
                .onActionEnd(() => {
                  promptAction.showActionMenu({
                    title: 'Delete Task',
                    buttons: [
                      { text: 'Delete', color: '#FF0000' },
