import { Column, Text, Stack } from '@ohos.arkui.component';
import { Alignment } from '@ohos.arkui.common';
import { animateTo, EaseInOut } from '@ohos.animator';
import { PanGesture, Gesture } from '@ohos.arkui.gesture';
import { ResourceColor } from '@ohos.arkui.common';

@Entry
@Component
struct CustomToast {
  @State message: string = 'This is a toast message';
  @State duration: number = 2000;
  @State isVisible: boolean = false;
  @State offsetY: number = 0;
  @State backgroundColor: ResourceColor = '#333333';
  @State textColor: ResourceColor = '#FFFFFF';

  private timer: number | undefined = undefined;

  aboutToAppear(): void {
    this.showToast();
  }

  aboutToDisappear(): void {
    this.hideToast();
  }

  showToast() {
    this.isVisible = true;
    animateTo({
      duration: 300,
      curve: EaseInOut
    }, () => {
      this.offsetY = 0;
    });

    this.timer = setTimeout(() => {
      this.hideToast();
    }, this.duration);
  }

  hideToast() {
    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = undefined;
    }

    animateTo({
      duration: 300,
      curve: EaseInOut
    }, () => {
      this.offsetY = 100;
    }, () => {
      this.isVisible = false;
    });
  }

  build() {
    Stack({ alignContent: Alignment.Center }) {
      if (this.isVisible) {
        Column() {
          Text(this.message)
            .fontSize(16)
            .fontColor(this.textColor)
            .margin(10)
        }
        .width('80%')
        .backgroundColor(this.backgroundColor)
        .borderRadius(8)
        .padding(10)
        .gesture(
          PanGesture()
            .onActionStart(() => {
              if (this.timer) {
                clearTimeout(this.timer);
                this.timer = undefined;
              }
            })
            .onActionUpdate((event: Gesture) => {
              this.offsetY = event.offsetY;
            })
            .onActionEnd(() => {
              if (Math.abs(this.offsetY) > 50) {
                this.hideToast();
              } else {
                animateTo({
                  duration: 300,
                  curve: EaseInOut
                }, () => {
                  this.offsetY = 0;
                });
                this.timer = setTimeout(() => {
                  this.hideToast();
                }, this.duration);
              }
            })
        )
        .offset({ y: this.offsetY })
      }
    }
    .width('100%')
    .height('100%')
  }
}

import { Swiper, SwiperController } from '@ohos.arkui.component';
import { FlexAlign, HorizontalAlign } from '@ohos.arkui.common';
import promptAction from '@ohos.promptAction';

interface AudioItem {
  id: number;
  title: string;
}

@Entry
@Component
struct AudioPlayer {
  @State currentIndex: number = 0
  @State isPlaying: boolean = false
  private swiperController: SwiperController = new SwiperController()

  private audioItems: AudioItem[] = [
    { id: 1, title: 'Audio 1' },
    { id: 2, title: 'Audio 2' },
    { id: 3, title: 'Audio 3' },
    { id: 4, title: 'Audio 4' }
  ]

  build() {
    Column() {
      Swiper(this.swiperController) {
        ForEach(this.audioItems, (item: AudioItem) => {
          Column() {
            Image(this.isPlaying ? $r('sys.media.ic_media_pause') : $r('sys.media.ic_media_play'))
              .width(50)
              .height(50)
              .margin({ top: 20 })
            Text(item.title)
              .fontSize(20)
              .margin({ top: 10 })
          }
          .width('100%')
          .height(200)
          .justifyContent(FlexAlign.Center)
          .alignItems(HorizontalAlign.Center)
          .onClick(() => {
            this.showActionSheet()
          })
        })
      }
      .width('100%')
      .height(300)
      .loop(true)
      .onChange((index: number) => {
        this.currentIndex = index
      })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }

  private showActionSheet() {
    promptAction.showActionMenu({
      title: 'Playback Controls',
      buttons: [
        {
          text: this.isPlaying ? 'Pause' : 'Play',
          color: '#000000'
        },
        {
          text: 'Details',
          color: '#000000'
        },
        {
          text: 'Cancel',
          color: '#000000'
        }
      ]
    }).then((response: promptAction.ActionMenuSuccessResponse) => {
      if (response.index === 0) {
        this.isPlaying = !this.isPlaying
      } else if (response.index === 1) {
        this.showDetailsDialog()
      }
    })
  }

  private showDetailsDialog() {
    promptAction.showDialog({
      title: 'Audio Details',
      message: `Currently playing: ${this.audioItems[this.currentIndex].title}`,
      buttons: [
        {
          text: 'Close',
          color: '#000000'
        }
      ]
    })
  }
}

