import { Stepper, StepperItem, Progress, TouchEvent, TouchType, ProgressStyle, Column, Text, Stack, Divider, State, Component, Entry } from '@ohos.arkui.component';

@Entry
@Component
struct StepperWithRefresh {
  @State currentStep: number = 0;
  @State isRefreshing: boolean = false;

  private stepTitles: string[] = ['Step 1: Setup', 'Step 2: Configuration', 'Step 3: Completion'];

  private handleRefresh() {
    this.isRefreshing = true;
    setTimeout(() => {
      this.isRefreshing = false;
    }, 2000);
  }

  private handleStepChange(step: number) {
    this.currentStep = step;
  }

  build() {
    Column() {
      Stack() {
        Column() {
          Stepper({
            current: this.currentStep,
            onChange: (step: number) => {
              this.handleStepChange(step);
            }
          }) {
            ForEach(this.stepTitles, (title: string, index: number) => {
              StepperItem() {
                Column() {
                  Text(title)
                    .fontSize(18)
                    .margin({ bottom: 10 });
                  Divider()
                    .strokeWidth(1)
                    .color('#CCCCCC');
                }
                .width('100%')
                .margin({ bottom: 20 });
              }
            });
          }

          if (this.isRefreshing) {
            Progress({
              style: ProgressStyle.Circular,
              value: 100
            })
            .width(50)
            .height(50)
            .margin({ top: 20 });
          }
        }
        .width('100%')
        .padding(20);
      }
    }
    .width('100%')
    .height('100%')
    .onTouch((event: TouchEvent) => {
      if (event.type === TouchType.Down) {
        const touchY = event.touches[0].y;
        if (touchY < 50) {
          this.handleRefresh();
        }
      }
    });
  }
}

