struct MainPage {
  @State selectedTheme: string = 'Light';
  @State isDialogVisible: boolean = false;
  @State dialogWidth: number = 300;
  @State dialogHeight: number = 200;

  private minWidth: number = 200;
  private minHeight: number = 150;

  build() {
    Stack() {
      Column() {
        Button('Open Dialog')
          .onClick(() => {
            this.isDialogVisible = true;
          })
          .margin(20);

        SegmentedControl()
          .options(['Light', 'Dark', 'System'])
          .selected(this.selectedTheme)
          .onChange((index: number) => {
            this.selectedTheme = ['Light', 'Dark', 'System'][index];
          })
          .margin(20);
      }
      .width('100%')
      .height('100%')
      .justifyContent('center');

      if (this.isDialogVisible) {
        Stack() {
          Column() {
            Text('Resizable Dialog')
              .fontSize(18)
              .fontWeight('bold')
              .margin(10);

            this.buildDialogContent();

            Button('Close')
              .onClick(() => {
                this.isDialogVisible = false;
              })
              .margin(10);
          }
        }
        .width(this.dialogWidth)
        .height(this.dialogHeight)
        .backgroundColor('#FFFFFF')
        .borderRadius(10)
        .shadow({ radius: 10, color: '#808080' })
        .gesture(
          PinchGesture()
            .onAction((event: PinchGestureEvent) => {
              const aspectRatio = this.dialogWidth / this.dialogHeight;
              const newWidth = Math.max(this.minWidth, this.dialogWidth * event.scale);
              const newHeight = newWidth / aspectRatio;
              this.dialogWidth = newWidth;
              this.dialogHeight = Math.max(this.minHeight, newHeight);
            })
        );
      }
    }
    .width('100%')
    .height('100%');
  }

  @Builder
  buildDialogContent() {
    Column() {
      Text('This is a resizable dialog.')
        .fontSize(16)
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .justifyContent('center');
  }
}

import webview from '@ohos.web.webview';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct DocumentScanner {
  @State isDarkMode: boolean = false;
  @State currentStep: number = 0;
  private webController: webview.WebviewController = new webview.WebviewController();
  private steps: string[] = ['Prepare Document', 'Scan Document', 'Review Document'];
  private stepDescriptions: string[] = [
    'Place your document on a flat surface with good lighting',
    'Align your document within the frame and hold steady',
    'Review the scanned document and make adjustments if needed'
  ];

  private toggleDarkMode() {
    this.isDarkMode = !this.isDarkMode;
    promptAction.showToast({
      message: this.isDarkMode ? 'Dark Mode Enabled' : 'Light Mode Enabled'
    });
  }

  private nextStep() {
    if (this.currentStep < this.steps.length - 1) {
      this.currentStep++;
    }
  }

  private prevStep() {
    if (this.currentStep > 0) {
      this.currentStep--;
    }
  }

  build() {
    Column() {
      Row() {
        Text('Document Scanner')
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .fontColor(this.isDarkMode ? 0xE6E6E6 : 0x333333)

        Toggle({ type: ToggleType.Switch })
          .selected(this.isDarkMode)
          .onChange((isOn: boolean) => {
            this.isDarkMode = isOn;
            this.toggleDarkMode();
          })
          .margin({ left: 20 })
      }
      .justifyContent(FlexAlign.SpaceBetween)
      .width('100%')
      .padding(15)
      .backgroundColor(this.isDarkMode ? 0x1A1A1A : 0xFFFFFF)

      Column() {
        Text(`Step ${this.currentStep + 1}: ${this.steps[this.currentStep]}`)
          .fontSize(18)
          .fontWeight(FontWeight.Bold)
          .fontColor(this.isDarkMode ? 0xE6E6E6 : 0x333333)

        Text(this.stepDescriptions[this.currentStep])
          .fontSize(16)
          .margin({ top: 10 })
          .fontColor(this.isDarkMode ? 0xE6E6E6 : 0x333333)

        Image($r('app.media.scanner_placeholder'))
          .width(300)
          .height(400)
          .margin({ top: 20 })
      }
      .width('100%')
      .alignItems(HorizontalAlign.Center)
      .padding(20)

      Column() {
        Web({ src: 'https://example.com', controller: this.webController })
          .width('100%')
          .height('30%')
      }

      Row() {
        Button('Previous')
          .onClick(() => this.prevStep())
          .enabled(this.currentStep > 0)
          .margin({ right: 20 })

        Button('Next')
          .onClick(() => this.nextStep())
          .enabled(this.currentStep < this.steps.length - 1)
      }
      .margin({ top: 20, bottom: 30 })
      .justifyContent(FlexAlign.Center)
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.isDarkMode ? 0x1A1A1A : 0xFFFFFF)
  }
}

