import { Column, Row, Text, Divider, FlexAlign } from '@ohos.arkui.component';
import { PinchGesture, PinchGestureEvent } from '@ohos.arkui.gesture';

@Entry
@Component
struct BreadcrumbNavigation {
  @State private breadcrumbs: string[] = ['Home'];
  @State private pinchScale: number = 1.0;

  @Builder
  BreadcrumbItem(text: string, index: number) {
    Text(text)
      .fontColor(this.breadcrumbs.length - 1 === index ? '#1698CE' : '#6B6B6B')
      .fontSize(16)
      .margin({ right: 8 })
      .onClick(() => {
        this.breadcrumbs = this.breadcrumbs.slice(0, index + 1);
      });
  }

  build() {
    Column() {
      Row() {
        ForEach(this.breadcrumbs, (item: string, index: number) => {
          this.BreadcrumbItem(item, index);
          if (index < this.breadcrumbs.length - 1) {
            Text('>')
              .fontColor('#6B6B6B')
              .fontSize(16)
              .margin({ right: 8 });
          }
        });
      }
      .padding(16)
      .width('100%')
      .justifyContent(FlexAlign.Start)
      .gesture(
        PinchGesture()
          .onActionUpdate((event: PinchGestureEvent) => {
            this.pinchScale = event.scale;
            if (this.pinchScale > 1.5 && this.breadcrumbs.length < 5) {
              this.breadcrumbs.push(`Level ${this.breadcrumbs.length + 1}`);
              this.pinchScale = 1.0;
            } else if (this.pinchScale < 0.8 && this.breadcrumbs.length > 1) {
              this.breadcrumbs.pop();
              this.pinchScale = 1.0;
            }
          })
      );

      Divider()
        .strokeWidth(1)
        .color('#6B6B6B')
        .margin({ top: 8, bottom: 8 });

      if (this.breadcrumbs[this.breadcrumbs.length - 1] === 'Home') {
        Text('Home Content')
          .fontSize(20)
          .margin({ top: 16 });
      } else if (this.breadcrumbs[this.breadcrumbs.length - 1] === 'Level 2') {
        Text('Level 2 Content')
          .fontSize(20)
          .margin({ top: 16 });
      } else if (this.breadcrumbs[this.breadcrumbs.length - 1] === 'Level 3') {
        Text('Level 3 Content')
          .fontSize(20)
          .margin({ top: 16 });
      } else if (this.breadcrumbs[this.breadcrumbs.length - 1] === 'Level 4') {
        Text('Level 4 Content')
          .fontSize(20)
          .margin({ top: 16 });
      } else if (this.breadcrumbs[this.breadcrumbs.length - 1] === 'Level 5') {
        Text('Level 5 Content')
          .fontSize(20)
          .margin({ top: 16 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(16);
  }
}

import { Column, Row, Button, List, ListItem, Text, Stack } from '@ohos.arkui.advanced';
import { FlexAlign, HorizontalAlign, FontWeight } from '@ohos.arkui.advanced';
import userIAM from '@ohos.userIAM.userAuth';
import router from '@ohos.router';
import promptAction from '@ohos.promptAction';
import { BusinessError } from '@ohos.base';
import abilityAccessCtrl from '@ohos.abilityAccessCtrl';
import { platform } from '@ohos.arkui.advanced';

@Entry
@Component
struct PodcastPlayer {
  @State isDrawerOpen: boolean = false;
  @State isAuthenticated: boolean = false;
  @State currentPodcast: string = '';
  @State isPlaying: boolean = false;
  @State podcasts: string[] = ['Podcast 1', 'Podcast 2', 'Podcast 3'];

  aboutToAppear() {
    const atManager = abilityAccessCtrl.createAtManager();
    atManager.requestPermissionsFromUser(getContext(this), ['ohos.permission.ACCESS_BIOMETRIC'])
      .then(() => {
        console.log('Permission granted');
      })
      .catch((err: BusinessError) => {
        console.error('Permission denied');
      });
  }

  build() {
    Column() {
      Row() {
        Button('Menu')
          .onClick(() => {
            this.isDrawerOpen = !this.isDrawerOpen;
          });
        Text('Podcast Player')
          .fontSize(20)
          .fontWeight(FontWeight.Bold);
      }
      .width('100%')
      .padding(10)
      .backgroundColor('#f5f5f5');

      if (this.isDrawerOpen) {
        Column() {
          Button('Home')
            .onClick(() => {
              router.pushUrl({ url: 'pages/home' });
              this.isDrawerOpen = false;
            });
          Button('Settings')
            .onClick(() => {
              router.pushUrl({ url: 'pages/settings' });
              this.isDrawerOpen = false;
            });
        }
        .width('70%')
        .height('100%')
        .backgroundColor('#ffffff')
        .position({ x: 0, y: 0 })
        .zIndex(1);
      }

      Stack() {
        if (!this.isAuthenticated) {
          Column() {
            Text('Authenticate to access content')
              .fontSize(18)
              .margin({ bottom: 20 });
            Button('Authenticate')
              .onClick(() => {
                this.authenticate();
              });
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center)
          .alignItems(HorizontalAlign.Center);
        } else {
          Column() {
            Text(this.currentPodcast || 'No podcast selected')
              .fontSize(24)
              .fontWeight(FontWeight.Bold)
              .margin({ bottom: 20 });

            Row() {
              Button('Play')
                .onClick(() => {
                  this.isPlaying = !this.isPlaying;
                });
              Button('Pause')
                .onClick(() => {
                  this.isPlaying = false;
                });
            }
            .width('100%')
            .justifyContent(FlexAlign.SpaceAround)
            .margin({ bottom: 20 });

            List() {
              ForEach(this.podcasts, (podcast: string) => {
                ListItem() {
                  Text(podcast)
                    .fontSize(18)
                    .onClick(() => {
                      this.currentPodcast = podcast;
                    });
                }
              });
            }
            .width('100%')
            .layoutWeight(1);
          }
          .width('100%')
          .height('100%')
          .padding(10);
        }
      }
      .width('100%')
      .height('100%');
    }
    .width('100%')
    .height('100%');
  }

  async authenticate() {
    try {
      if (platform.isHarmonyOS) {
        const auth = userIAM.getAuthInstance(9, 0xFFFF, 0);
        const result = await auth.auth({
          challenge: 'podcast_challenge',
          authType: [1, 2],
          authTrustLevel: 1
        });

        if (result.result === 0) {
          this.isAuthenticated = true;
          promptAction.showToast({ message: 'Authentication successful' });
        }
      } else {
        this.isAuthenticated = true;
        promptAction.showToast({ message: 'Authentication simulated' });
      }
    } catch (err) {
      console.error('Authentication failed');
      promptAction.showToast({ message: 'Authentication failed' });
    }
  }
}

import { GestureGroup, GestureMode, PinchGesture } from '@ohos.ui.advanced';
import { PinchGestureEvent } from '@ohos.ui.advanced';
import { CustomDialogController } from '@ohos.arkui.UIContext';

@CustomDialog
struct ZoomDialog {
  controller: CustomDialogController
  @State content: string = ''
  @State zoomScale: number = 1.0

  build() {
    Column() {
      Text(this.content)
        .fontSize(16 * this.zoomScale)
      Button('Close')
        .onClick(() => {
          this.controller.close()
          this.zoomScale = 1.0
        })
    }
    .padding(20)
  }
}

@Entry
@Component
struct PinchZoomList {
  @State private data: string[] = ['Item 1', 'Item 2', 'Item 3'];
  @State private zoomScale: number = 1.0;
  @State private showDialog: boolean = false;
  @State private dialogContent: string = '';

  private onPinch(event: PinchGestureEvent, index: number) {
    this.zoomScale = event.scale;
    if (this.zoomScale >= 1.5) {
      this.dialogContent = this.data[index];
      this.showDialog = true;
    }
  }

  build() {
    Column() {
      List() {
        ForEach(this.data, (item: string, index: number) => {
          ListItem() {
            Text(item)
              .fontSize(16)
              .padding(10)
              .gesture(
                GestureGroup(GestureMode.Exclusive,
                  PinchGesture()
                    .onActionStart((event: PinchGestureEvent) => {
                      this.onPinch(event, index);
                    })
                    .onActionUpdate((event: PinchGestureEvent) => {
                      this.onPinch(event, index);
                    })
                )
              )
          }
        })
      }
      .height('80%')

      if (this.showDialog) {
        ZoomDialog({
          controller: new CustomDialogController({
            builder: ZoomDialog({
              content: this.dialogContent,
              zoomScale: this.zoomScale
            }),
            cancel: () => {
              this.showDialog = false
              this.zoomScale = 1.0
            }
          })
        })
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

