  @State newNoteContent: string = '';
  @State editNoteId: number | null = null;
  @StorageLink('theme') theme: string = 'light';
  @StorageLink('fontSize') fontSize: number = 16;

  build() {
    Column() {
      Tabs() {
        TabContent('Notes') {
          Column() {
            TextInput({ placeholder: 'Note Title', text: this.newNoteTitle })
              .height(50)
              .width('90%')
              .onChange((value: string) => {
                this.newNoteTitle = value;
              })
              .margin(10);

            TextArea({ placeholder: 'Note Content', text: this.newNoteContent })
              .height(100)
              .width('90%')
              .onChange((value: string) => {
                this.newNoteContent = value;
              })
              .margin(10);

            Button(this.editNoteId !== null ? 'Update Note' : 'Add Note')
              .onClick(() => {
                if (this.newNoteTitle.trim() && this.newNoteContent.trim()) {
                  const timestamp = new Date().toLocaleString();
                  if (this.editNoteId !== null) {
                    const index = this.notes.findIndex(note => note.id === this.editNoteId);
                    this.notes[index] = {
                      id: this.editNoteId,
                      title: this.newNoteTitle,
                      content: this.newNoteContent,
                      timestamp: timestamp
                    };
                    this.editNoteId = null;
                  } else {
                    this.notes.push({
                      id: Date.now(),
                      title: this.newNoteTitle,
                      content: this.newNoteContent,
                      timestamp: timestamp
                    });
                  }
                  this.newNoteTitle = '';
                  this.newNoteContent = '';
                }
              })
              .margin(10);

            List() {
              ForEach(this.notes, (note: Note) => {
                ListItem() {
                  Row() {
                    Column() {
                      Text(note.title)
                        .fontSize(this.fontSize)
                        .fontWeight('Bold')
                        .width('80%');
                      Text(note.content)
                        .fontSize(this.fontSize - 2)
                        .width('80%');
                      Text(note.timestamp)
                        .fontSize(this.fontSize - 4)
                        .width('80%');
                    }
                    .width('100%')
                    .margin(5);
                  }
                  .onClick(() => {
                    this.newNoteTitle = note.title;
                    this.newNoteContent = note.content;
                    this.editNoteId = note.id;
                  });
                }
              });
            }
            .width('100%')
            .height('60%');
          }
          .width('100%')
          .height('100%');
        }

        TabContent('Settings') {
          Column() {
            Text('Theme')
              .fontSize(this.fontSize)
              .margin(10);

            Row() {
              Button('Light')
                .onClick(() => {
                  this.theme = 'light';
                })
                .margin(5);

              Button('Dark')
                .onClick(() => {
                  this.theme = 'dark';
                })
                .margin(5);
            }

            Text('Font Size')
              .fontSize(this.fontSize)
              .margin(10);

            Row() {
              Button('Small')
                .onClick(() => {
                  if (this.fontSize > 12) {
                    this.fontSize -= 2;
                  }
                })
                .margin(5);

              Button('Medium')
                .onClick(() => {
                  this.fontSize = 16;
                })
                .margin(5);

              Button('Large')
                .onClick(() => {
                  if (this.fontSize < 24) {
                    this.fontSize += 2;
                  }
                })
                .margin(5);
            }
          }
          .width('100%')
          .height('100%');
        }
      }
      .barWidth('100%')
      .barHeight(50);
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.theme === 'light' ? '#FFFFFF' : '#333333');
  }
}

import promptAction from '@ohos.promptAction';
import router from '@ohos.router';
import { ScaleOptions, RotateOptions } from '@ohos.arkui.component';

@Entry
@Component
struct VideoPlaceholderComponent {
  @State scale: ScaleOptions = { x: 1.0, y: 1.0 };
  @State rotate: RotateOptions = { angle: 0 };
  @State hapticEnabled: boolean = false;

  playAnimation() {
    animateTo({ duration: 500 }, () => {
      this.scale = { x: 1.5, y: 1.5 };
      this.rotate = { angle: 45 };
    });
    animateTo({ duration: 500, delay: 500 }, () => {
      this.scale = { x: 1.0, y: 1.0 };
      this.rotate = { angle: 90 };
    });
  }

  triggerHaptic() {
    try {
      this.hapticEnabled = true;
      promptAction.showToast({ message: "Haptic feedback activated", duration: 2000 });
    } catch (error) {
      console.error("Haptic feedback not supported: " + error);
      promptAction.showToast({ message: "Haptic feedback not supported", duration: 2000 });
    }
  }

  navigate() {
    router.pushUrl({
      url: 'pages/DetailPage',
      params: { id: '123' }
    });
  }

  build() {
    Column() {
      Stack() {
        Image($r('app.media.icon'))
          .width(300)
          .height(200)
          .borderRadius(10)
          .scale(this.scale)
          .rotate(this.rotate)
          .onClick(() => {
            this.playAnimation();
            this.triggerHaptic();
          })
      }
      .width('100%')
      .height(200)
      .margin({ top: 20 })

      Column() {
        Button("Animate")
          .onClick(() => {
            this.playAnimation();
          })
          .margin({ top: 10 })

        Button("Navigate")
          .onClick(() => {
            this.navigate();
          })
          .margin({ top: 10 })
      }
      .width('100%')
      .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

