class QuizQuestion {
  question: string;
  options: string[];
  correctAnswer: number;

  constructor(question: string, options: string[], correctAnswer: number) {
    this.question = question;
    this.options = options;
    this.correctAnswer = correctAnswer;
  }
}

@Entry
@Component
struct QuizApp {
  @State currentQuestionIndex: number = 0;
  @State score: number = 0;
  @State showScore: boolean = false;
  @State showFeedback: boolean = false;
  @State isCorrect: boolean = false;
  @State scaleValue: number = 1.0;

  private questions: QuizQuestion[] = [
    new QuizQuestion(
      'What is the capital of France?',
      ['London', 'Berlin', 'Paris', 'Madrid'],
      2
    ),
    new QuizQuestion(
      'Which planet is closest to the Sun?',
      ['Mars', 'Venus', 'Mercury', 'Jupiter'],
      2
    ),
    new QuizQuestion(
      'What is the largest mammal?',
      ['African Elephant', 'Blue Whale', 'Giraffe', 'Hippopotamus'],
      1
    )
  ];

  checkAnswer(selectedIndex: number) {
    const correct = selectedIndex === this.questions[this.currentQuestionIndex].correctAnswer;
    this.isCorrect = correct;
    if (correct) {
      this.score++;
    }
    this.showFeedback = true;

    setTimeout(() => {
      this.showFeedback = false;
      if (this.currentQuestionIndex < this.questions.length - 1) {
        this.currentQuestionIndex++;
      } else {
        this.showScore = true;
      }
    }, 1000);
  }

  restartQuiz() {
    this.currentQuestionIndex = 0;
    this.score = 0;
    this.showScore = false;
    this.showFeedback = false;
    this.isCorrect = false;
    this.scaleValue = 1.0;
  }

  build() {
    Column() {
      if (!this.showScore) {
        Progress({
          value: ((this.currentQuestionIndex + 1) / this.questions.length) * 100,
          style: { strokeWidth: 10 } as ProgressStyle
        })
          .width('90%')
          .height(10)
          .margin({ top: 20, bottom: 20 });

        Text(`Question ${this.currentQuestionIndex + 1}/${this.questions.length}`)
          .fontSize(16)
          .margin({ bottom: 10 });

        Text(this.questions[this.currentQuestionIndex].question)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .textAlign(TextAlign.Center)
          .margin({ bottom: 40 })
          .padding({ left: 20, right: 20 })
          .scale({ x: this.scaleValue, y: this.scaleValue } as ScaleOptions)
          .gesture(
            PinchGesture()
              .onActionStart(() => {})
              .onActionUpdate((event: PinchEvent) => {
                this.scaleValue = event.scale;
              })
              .onActionEnd(() => {})
          );

        ForEach(this.questions[this.currentQuestionIndex].options, (option: string, index: number) => {
          Button(option)
            .width('80%')
            .height(50)
            .margin({ bottom: 10 })
            .onClick(() => {
              this.checkAnswer(index);
            });
        }, (option: string) => option);

        if (this.showFeedback) {
          Text(this.isCorrect ? 'Correct!' : 'Incorrect!')
            .fontSize(20)
            .fontColor(this.isCorrect ? '#00FF00' : '#FF0000')
            .margin({ top: 20 });
        }
      } else {
        Text(`Your score: ${this.score}/${this.questions.length}`)
          .fontSize(24)
          .margin({ bottom: 20 });

        Button('Restart Quiz')
          .width('50%')
          .height(50)
          .onClick(() => {
            this.restartQuiz();
          });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(H

@Entry
@Component
struct MeditationTimer {
  @State soundEnabled: boolean = true
  @State selectedColor: string = '#007AFF'
  @State timerValue: string = '00:00'
  @State isRunning: boolean = false
  private timerId: number = -1
  private seconds: number = 0

  build() {
    Column() {
      Row() {
        Text('Theme:')
          .margin(10)
        Button('Blue')
          .onClick(() => {
            this.selectedColor = '#007AFF'
          })
          .margin(5)
        Button('Green')
          .onClick(() => {
            this.selectedColor = '#34C759'
          })
          .margin(5)
        Button('Red')
          .onClick(() => {
            this.selectedColor = '#FF3B30'
          })
          .margin(5)
      }
      .margin(20)

      Row() {
        Text('Enable Sound:')
          .margin(10)
        Toggle({ type: ToggleType.Switch, isOn: this.soundEnabled })
          .onChange((isOn: boolean) => {
            this.soundEnabled = isOn
          })
          .margin(10)
      }
      .margin(20)

      Text(this.timerValue)
        .fontSize(40)
        .margin(20)
        .textAlign(TextAlign.Center)
        .width('100%')

      Row() {
        Button(this.isRunning ? 'Stop' : 'Start')
          .onClick(() => {
            if (this.isRunning) {
              clearInterval(this.timerId)
            } else {
              this.timerId = setInterval(() => {
                this.seconds++
                this.timerValue = this.formatTime(this.seconds)
              }, 1000)
            }
            this.isRunning = !this.isRunning
          })
          .margin(10)
        Button('Reset')
          .onClick(() => {
            clearInterval(this.timerId)
            this.seconds = 0
            this.timerValue = '00:00'
            this.isRunning = false
          })
          .margin(10)
      }
      .margin(20)
      .justifyContent(FlexAlign.Center)
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.selectedColor)
    .gesture(
      PanGesture()
        .onActionStart(() => {
        })
        .onActionUpdate((event: GestureEvent) => {
          if (Math.abs(event.offsetX) > 50) {
            animateTo({ duration: 200 }, () => {
              this.selectedColor = this.selectedColor === '#007AFF' ? '#34C759' : '#007AFF'
            })
          }
        })
    )
  }

  private formatTime(seconds: number): string {
    const minutes = Math.floor(seconds / 60)
    const remainingSeconds = seconds % 60
    return `${minutes.toString().padStart(2, '0')}:${remainingSeconds.toString().padStart(2, '0')}`
  }
}

