@Entry
@Component
struct AnimationDemo {
  @State currentFrame: number = 0
  @State isPlaying: boolean = false
  @State scaleValue: number = 1
  @State opacityValue: number = 1
  @State rotationAngle: number = 0

  private frames: Resource[] = [
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon')
  ]

  private videoSrc: string = 'video_demo.mp4'

  build() {
    Column() {
      // Video Component
      Video({
        src: this.videoSrc,
        controller: new VideoController()
      })
        .width('100%')
        .height(200)
        .margin({ bottom: 20 })

      // Image Component for Frame-by-Frame Animation
      Image(this.frames[this.currentFrame])
        .width(200)
        .height(200)
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .opacity(this.opacityValue)
        .rotate({ angle: this.rotationAngle })
        .margin({ bottom: 20 })

      // Animation Controls
      Row() {
        Button(this.isPlaying ? 'Pause' : 'Play')
          .width(100)
          .height(40)
          .onClick(() => {
            this.isPlaying = !this.isPlaying
            if (this.isPlaying) {
              this.startFrameAnimation()
            }
          })

        Button('Next Frame')
          .width(100)
          .height(40)
          .margin({ left: 10 })
          .onClick(() => {
            this.nextFrame()
          })
      }
      .margin({ bottom: 20 })

      // Animation Effects
      Button('Scale & Rotate')
        .width(200)
        .height(40)
        .onClick(() => {
          animateTo({
            duration: 500,
            curve: Curve.EaseInOut
          }, () => {
            this.scaleValue = 1.5
            this.rotationAngle = 180
            this.opacityValue = 0.7
          })

          setTimeout(() => {
            animateTo({
              duration: 500,
              curve: Curve.EaseInOut
            }, () => {
              this.scaleValue = 1
              this.rotationAngle = 0
              this.opacityValue = 1
            })
          }, 500)
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .padding(16)
  }

  private nextFrame() {
    this.currentFrame = (this.currentFrame + 1) % this.frames.length
  }

  private startFrameAnimation() {
    if (this.isPlaying) {
      setTimeout(() => {
        this.nextFrame()
        this.startFrameAnimation()
      }, 300)
    }
  }
}

import { Badge, BadgePosition } from '@ohos.arkui.advanced';
import { LongPressGesture } from '@ohos.arkui.advanced';
import { FontWeight, FlexAlign, TextAlign } from '@ohos.arkui.advanced';
import { HorizontalAlign } from '@ohos.arkui.advanced';
import { Button } from '@ohos.arkui.advanced';
import { Text } from '@ohos.arkui.advanced';
import { Column, Row } from '@ohos.arkui.advanced';

@Entry
@Component
struct CountdownTimer {
  @State private remainingTime: number = 300;
  @State private isRunning: boolean = false;
  @State private showCompletion: boolean = false;
  private timerId: number | null = null;

  private formatTime(seconds: number): string {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = seconds % 60;
    return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  }

  private startTimer(): void {
    if (!this.isRunning) {
      this.timerId = setInterval(() => {
        if (this.remainingTime > 0) {
          this.remainingTime -= 1;
        } else {
          this.stopTimer();
          this.showCompletion = true;
        }
      }, 1000);
      this.isRunning = true;
    }
  }

  private stopTimer(): void {
    if (this.timerId) {
      clearInterval(this.timerId);
      this.timerId = null;
    }
    this.isRunning = false;
  }

  private resetTimer(): void {
    this.stopTimer();
    this.remainingTime = 300;
    this.showCompletion = false;
  }

  build() {
    Column() {
      if (this.showCompletion) {
        Badge({ count: 1, position: BadgePosition.RIGHT_TOP }) {
          Text('Timer completed!')
            .fontSize(20)
            .margin({ bottom: 20 });
        }
      }

      Text(this.formatTime(this.remainingTime))
        .fontSize(48)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 30 });

      Row() {
        Button(this.isRunning ? 'Pause' : 'Start')
          .onClick(() => {
            if (this.isRunning) {
              this.stopTimer();
            } else {
              this.startTimer();
            }
          })
          .margin({ right: 20 });

        Button('Reset')
          .onClick(() => this.resetTimer());
      }
      .justifyContent(FlexAlign.Center)
      .margin({ bottom: 30 });

      Text('Long press for action')
        .gesture(
          LongPressGesture({ repeat: false })
            .onActionStart(() => {
              console.log('Long press action started');
            })
            .onActionEnd(() => {
              console.log('Long press action ended');
            })
            .onActionCancel(() => {
              console.log('Long press action canceled');
            })
        )
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

import { Text, Button, Column, Row, TimePicker } from '@ohos.arkui.component';
import { FlexAlign, FontWeight } from '@ohos.arkui.common';

interface TimerSelection {
  hour: number;
  minute: number;
  second: number;
}

@Entry
@Component
struct CountdownTimer {
  @State selectedTime: TimerSelection = { hour: 0, minute: 0, second: 0 };
  @State remainingSeconds: number = 0;
  @State isRunning: boolean = false;
  @State timerId: number = -1;

  private formatTime(seconds: number): string {
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    return `${minutes.toString().padStart(2, '0')}:${remainingSeconds.toString().padStart(2, '0')}`;
  }

  private startTimer() {
    this.remainingSeconds = this.selectedTime.hour * 3600 + this.selectedTime.minute * 60 + this.selectedTime.second;
    if (this.remainingSeconds <= 0) return;

    this.isRunning = true;
    this.timerId = setInterval(() => {
      if (this.remainingSeconds > 0) {
        this.remainingSeconds -= 1;
      } else {
        this.stopTimer();
      }
    }, 1000);
  }

  private stopTimer() {
    clearInterval(this.timerId);
    this.isRunning = false;
  }

  private resetTimer() {
    this.stopTimer();
    this.remainingSeconds = 0;
  }

  aboutToDisappear() {
    this.stopTimer();
  }

  build() {
    Column({ space: 20 }) {
      TimePicker({
        selected: this.selectedTime,
        onDateChange: (value: TimerSelection) => {
          this.selectedTime = value;
        }
      })
      .width('80%')
      .margin({ top: 20 });

      Text(this.formatTime(this.remainingSeconds))
        .fontSize(40)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Row({ space: 20 }) {
        Button(this.isRunning ? 'Stop' : 'Start')
          .width('40%')
          .backgroundColor(this.isRunning ? '#FF0000' : '#00FF00')
          .onClick(() => {
            if (this.isRunning) {
              this.stopTimer();
            } else {
              this.startTimer();
            }
          });

        Button('Reset')
          .width('40%')
          .backgroundColor('#0000FF')
          .onClick(() => {
            this.resetTimer();
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.Center);
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center);
  }
}

