import { Tabs, TabBar, TextInput, Column, Text, Select, InputType, FlexAlign } from '@ohos.arkui.advanced';
import { PinchGesture } from '@ohos.arkui.advanced';

interface ConversionHistory {
  amount: number;
  from: string;
  to: string;
  result: number;
}

interface ExchangeRates {
  USD: number;
  EUR: number;
  GBP: number;
}

interface PinchGestureEvent {
  scale: number;
  centerX: number;
  centerY: number;
  pinchCenterX: number;
  pinchCenterY: number;
}

@Entry
@Component
struct CurrencyConverter {
  @State amount: number = 0;
  @State fromCurrencyIndex: number = 0;
  @State toCurrencyIndex: number = 1;
  @State convertedAmount: number = 0;
  @State scaleOptions: {x: number, y: number} = { x: 1.0, y: 1.0 };
  @State history: ConversionHistory[] = [];

  private currencyOptions = ['USD', 'EUR', 'GBP'];
  private exchangeRates: Record<string, number> = {
    USD: 1,
    EUR: 0.85,
    GBP: 0.75
  };

  private getCurrencyByIndex(index: number): string {
    return this.currencyOptions[index];
  }

  private convert() {
    const fromCurrency = this.getCurrencyByIndex(this.fromCurrencyIndex);
    const toCurrency = this.getCurrencyByIndex(this.toCurrencyIndex);

    if (fromCurrency === toCurrency) {
      this.convertedAmount = this.amount;
      return;
    }

    const fromRate = this.exchangeRates[fromCurrency];
    const toRate = this.exchangeRates[toCurrency];
    const rate = toRate / fromRate;
    this.convertedAmount = this.amount * rate;

    this.history.unshift({
      amount: this.amount,
      from: fromCurrency,
      to: toCurrency,
      result: this.convertedAmount
    });
  }

  build() {
    Tabs() {
      TabContent() {
        Column()
          .gesture(
            PinchGesture()
              .onActionStart(() => {})
              .onActionUpdate((event: PinchGestureEvent) => {
                const newScale = Math.min(Math.max(this.scaleOptions.x * event.scale, 0.5), 2.0);
                this.scaleOptions = { x: newScale, y: newScale };
              })
          )
          .scale(this.scaleOptions)
        {
          TextInput({ placeholder: 'Enter amount' })
            .type(InputType.Number)
            .onChange((value: string) => {
              this.amount = parseFloat(value) || 0;
              this.convert();
            });

          Select(this.currencyOptions)
            .selected(this.fromCurrencyIndex)
            .onSelect((index: number) => {
              this.fromCurrencyIndex = index;
              this.convert();
            });

          Select(this.currencyOptions)
            .selected(this.toCurrencyIndex)
            .onSelect((index: number) => {
              this.toCurrencyIndex = index;
              this.convert();
            });

          Text(`Converted: ${this.convertedAmount.toFixed(2)}`);
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
      }
      .tabBar('Converter')

      TabContent() {
        Column() {
          ForEach(this.history, (item: ConversionHistory) => {
            Text(`${item.amount} ${item.from} → ${item.result.toFixed(2)} ${item.to}`)
          })
        }
        .width('100%')
        .height('100%')
      }
      .tabBar('History')
    }
  }
}

