import { Column, Text, Button } from '@ohos.arkui.advanced';
import { Color, FlexAlign } from '@ohos.arkui.advanced';
import webview from '@ohos.web.webview';
import cryptoFramework from '@ohos.security.cryptoFramework';

@Entry
@Component
struct StepCounter {
  @State private stepCount: number = 0;
  @State private encryptedData: string = '';
  private webController: webview.WebviewController = new webview.WebviewController();

  private async encryptStepCount(): Promise<void> {
    try {
      const symKeyGenerator = cryptoFramework.createSymKeyGenerator('AES256');
      const symKey = await symKeyGenerator.generateSymKey();
      const cipher = cryptoFramework.createCipher('AES256|PKCS7');
      await cipher.init(cryptoFramework.CryptoMode.ENCRYPT_MODE, symKey, null);
      const input: cryptoFramework.DataBlob = { data: new Uint8Array([this.stepCount]) };
      const encrypted = await cipher.doFinal(input);
      this.encryptedData = Array.from(encrypted.data).map(byte => byte.toString(16).padStart(2, '0')).join('');
    } catch (error) {
      console.error('Encryption failed:', error);
    }
  }

  private incrementStepCount(): void {
    this.stepCount++;
    this.encryptStepCount();
  }

  build() {
    Column({ space: 20 }) {
      Text(`Step Count: ${this.stepCount}`)
        .fontSize(24)
        .fontColor(Color.Black);

      Text(`Encrypted Data: ${this.encryptedData}`)
        .fontSize(16)
        .fontColor(Color.Gray);

      Button('Increment Step')
        .onClick(() => this.incrementStepCount())
        .width(200)
        .height(50);

      Web({
        controller: this.webController,
        src: 'https://example.com'
      })
      .width('100%')
      .height(300);
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center);
  }
}

