import { Column, Row, Text, Button, List, TextInput, Checkbox, ForEach } from '@ohos.arkui.component';
import { FontWeight, TextDecorationType } from '@ohos.arkui.component';
import fs from '@ohos.file.fs';
import common from '@ohos.app.ability.common';
import { TextEncoder, TextDecoder } from '@ohos.util';

interface Task {
  id: string;
  content: string;
  color: string;
  isCompleted: boolean;
}

@Entry
@Component
struct TodoListApp {
  @State tasks: Task[] = [];
  @State newTask: string = '';
  @State selectedColor: string = '#FF5733';
  private context: common.UIAbilityContext = getContext() as common.UIAbilityContext;
  private filePath: string = this.context.filesDir + '/tasks.json';

  aboutToAppear(): void {
    this.loadTasks();
  }

  private loadTasks(): void {
    try {
      try {
        fs.accessSync(this.filePath);
      } catch {
        return;
      }
      let file = fs.openSync(this.filePath, fs.OpenMode.READ_ONLY);
      let content = fs.readSync(file.fd, new ArrayBuffer(4096));
      fs.closeSync(file);
      let uint8Array = new Uint8Array(content);
      this.tasks = JSON.parse(new TextDecoder().decode(uint8Array));
    } catch {
      this.tasks = [];
    }
  }

  private saveTasks(): void {
    try {
      let file = fs.openSync(this.filePath, fs.OpenMode.READ_WRITE | fs.OpenMode.CREATE);
      let data = new TextEncoder().encode(JSON.stringify(this.tasks));
      fs.writeSync(file.fd, data);
      fs.closeSync(file);
    } catch {
      console.error('Failed to save tasks');
    }
  }

  private addTask(): void {
    if (this.newTask.trim()) {
      this.tasks.push({
        id: Date.now().toString(),
        content: this.newTask.trim(),
        color: this.selectedColor,
        isCompleted: false,
      });
      this.newTask = '';
      this.saveTasks();
    }
  }

  private toggleTaskCompletion(index: number): void {
    this.tasks[index].isCompleted = !this.tasks[index].isCompleted;
    this.saveTasks();
  }

  private deleteTask(index: number): void {
    this.tasks.splice(index, 1);
    this.saveTasks();
  }

  build() {
    Column() {
      Text('Todo List')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row() {
        TextInput({ placeholder: 'Enter a new task', text: this.newTask })
          .onChange((value: string) => {
            this.newTask = value;
          })
          .width('70%');

        Button('Add')
          .onClick(() => this.addTask())
          .width('30%');
      }
      .width('100%')
      .margin({ bottom: 20 });

      Row() {
        Button('Red')
          .backgroundColor('#FF5733')
          .onClick(() => {
            this.selectedColor = '#FF5733';
          });
        Button('Blue')
          .backgroundColor('#3385FF')
          .onClick(() => {
            this.selectedColor = '#3385FF';
          });
        Button('Green')
          .backgroundColor('#33FF57')
          .onClick(() => {
            this.selectedColor = '#33FF57';
          });
      }
      .width('100%')
      .margin({ bottom: 20 });

      List() {
        ForEach(this.tasks, (task: Task, index: number) => {
          ListItem() {
            Row() {
              Checkbox()
                .select(task.isCompleted)
                .onChange((value: boolean) => {
                  this.toggleTaskCompletion(index);
                });
              Text(task.content)
                .fontSize(18)
                .margin({ left: 10 })
                .decoration({ type: task.isCompleted ? TextDecorationType.LineThrough : TextDecorationType.None })
                .fontColor(task.color);
              Button('Delete')
                .onClick(() => {
                  this.deleteTask(index);
                });
            }
            .width('100%')
            .padding(10);
          }
        });
      }
      .width('100%')
      .height('60%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

import { TimePicker, Flex, FlexAlign, FlexDirection, ItemAlign, Button, Column, Row, Text, FontWeight } from '@ohos.arkui';

interface TimeSelection {
  hour: number;
  minute: number;
  second: number;
}

@Entry
@Component
struct RestaurantReservationApp {
  @State selectedTime: string = 'Select a time';
  @State currentRating: number = 0;
  @State isRowLayout: boolean = false;

  private handleTimeChange(time: TimeSelection): void {
    const hours = time.hour % 12 || 12;
    const minutes = time.minute.toString().padStart(2, '0');
    const period = time.hour >= 12 ? 'PM' : 'AM';
    this.selectedTime = `${hours}:${minutes} ${period}`;
  }

  private handleRatingChange(rating: number): void {
    this.currentRating = rating;
  }

  private toggleLayout(): void {
    this.isRowLayout = !this.isRowLayout;
  }

  build() {
    Flex({ direction: FlexDirection.Column, justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
      Column() {
        Text('Restaurant Reservation')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 });

        TimePicker()
          .onChange((time: TimeSelection) => this.handleTimeChange(time))
          .margin({ bottom: 20 });

        Text(`Selected Time: ${this.selectedTime}`)
          .fontSize(18)
          .margin({ bottom: 20 });

        Row() {
          ForEach([1, 2, 3, 4, 5], (star: number) => {
            Text(this.currentRating >= star ? '\u2605' : '\u2606')
              .width(30)
              .height(30)
              .margin({ right: 5 })
              .onClick(() => this.handleRatingChange(star));
          });
        }
        .margin({ bottom: 20 });

        Text(`Rating: ${'\u2605'.repeat(this.currentRating)}${'\u2606'.repeat(5 - this.currentRating)} (${this.currentRating})`)
          .fontSize(18)
          .margin({ bottom: 20 });

        Button('Toggle Layout')
          .onClick(() => this.toggleLayout())
          .margin({ bottom: 20 });

        if (this.isRowLayout) {
          Row({ space: 10 }) {
            Text('Layout Variant B (Row)')
              .fontSize(16);
          }
          .justifyContent(FlexAlign.Center)
          .alignItems(ItemAlign.Center);
        } else {
          Column({ space: 10 }) {
            Text('Layout Variant A (Column)')
              .fontSize(16);
          }
          .justifyContent(FlexAlign.Center)
          .alignItems(ItemAlign.Center);
        }
      }
      .width('80%')
      .padding(20)
      .backgroundColor('#f5f5f5')
      .borderRadius(12);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff');
  }
}

import { Checkbox, Card, Column, Text, Row } from '@ohos.arkui.component';
import { SwipeGesture } from '@ohos.arkui.gesture';

interface ExpenseItem {
  id: number;
  name: string;
  amount: number;
  checked: boolean;
}

@Entry
@Component
struct ExpenseTracker {
  @State expenses: ExpenseItem[] = [
    { id: 1, name: 'Groceries', amount: 50.00, checked: false },
    { id: 2, name: 'Transport', amount: 20.00, checked: false },
    { id: 3, name: 'Utilities', amount: 100.00, checked: false }
  ];

  build() {
    Column() {
      ForEach(this.expenses, (item: ExpenseItem) => {
        Card() {
          Row() {
            Checkbox()
              .checked(item.checked)
              .onChange((isChecked: boolean) => {
                this.expenses = this.expenses.map(exp => {
                  if (exp.id === item.id) {
                    return { id: exp.id, name: exp.name, amount: exp.amount, checked: isChecked };
                  }
                  return exp;
                });
              })
              .accessibilityDescription(`Mark ${item.name} as paid`)
              .accessibilityRole('checkbox')
              .accessibilityState({ checked: item.checked });

            Column() {
              Text(item.name)
                .fontSize(16)
                .margin({ left: 10 })
                .accessibilityImportance('high');
              Text(`$${item.amount.toFixed(2)}`)
                .fontSize(14)
                .margin({ left: 10 });
            }
            .margin({ left: 10 })
            .accessibilityGroup(true);
          }
          .padding(10)
          .justifyContent(FlexAlign.SpaceBetween);
        }
        .margin({ top: 5, bottom: 5 })
        .gesture(
          SwipeGesture()
            .onAction(() => {
              this.expenses = this.expenses.filter(expense => expense.id !== item.id);
            })
            .accessibilityDescription(`Swipe to delete ${item.name}`)
        );
      });
    }
    .width('100%')
    .padding(20);
  }
}

