import { Flex, FlexDirection, FlexAlign, Column, Row, Text, Button } from '@ohos.arkui.advanced';
import { State } from '@ohos.arkui.dfx';
import { Tag, TagType } from '@ohos.arkui.component';
import { Tabs, TabContent, BarPosition } from '@ohos.arkui.advanced';

enum MeditationState {
  Ready = 'Ready',
  InProgress = 'In Progress',
  Completed = 'Completed'
}

@Entry
@Component
struct MeditationTimer {
  @State elapsedTime: number = 0;
  @State meditationState: MeditationState = MeditationState.Ready;
  @State timerActive: boolean = false;
  private timerId: number = 0;

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.Start }) {
        TabContent() {
          Column() {
            Text(`Elapsed Time: ${this.elapsedTime}s`)
              .fontSize(24)
              .margin({ bottom: 20 })
            Column() {
              Tag({
                type: TagType.Normal
              }) {
                Text(this.meditationState)
              }
              .margin({ bottom: 20 })
            }
            Row() {
              Button('Start')
                .onClick(() => {
                  if (!this.timerActive) {
                    this.timerActive = true;
                    this.meditationState = MeditationState.InProgress;
                    this.timerId = setInterval(() => {
                      this.elapsedTime++;
                    }, 1000);
                  }
                })
              Button('Pause')
                .onClick(() => {
                  if (this.timerActive) {
                    this.timerActive = false;
                    clearInterval(this.timerId);
                  }
                })
              Button('Reset')
                .onClick(() => {
                  this.timerActive = false;
                  clearInterval(this.timerId);
                  this.elapsedTime = 0;
                  this.meditationState = MeditationState.Ready;
                })
            }
            .justifyContent(FlexAlign.SpaceAround)
            .width('100%')
            .margin({ top: 20 })
          }
          .width('100%')
          .height('100%')
          .padding(20)
        }
        .tabBar('Timer')

        TabContent() {
          Column() {
            Text('Guided Meditations')
              .fontSize(24)
              .margin({ bottom: 20 })
          }
          .width('100%')
          .height('100%')
          .padding(20)
        }
        .tabBar('Guided')

        TabContent() {
          Column() {
            Text('Settings')
              .fontSize(24)
              .margin({ bottom: 20 })
          }
          .width('100%')
          .height('100%')
          .padding(20)
        }
        .tabBar('Settings')
      }
      .width('100%')
      .height('100%')
    }
    .width('100%')
    .height('100%')
  }

  aboutToDisappear() {
    if (this.timerId) {
      clearInterval(this.timerId);
    }
  }
}

