@Entry
@Component
struct LanguageLearningApp {
  @State refreshing: boolean = false
  @State currentIndex: number = 0
  @State currentLanguage: string = 'en'
  @State phrases: string[] = ['Hello', 'Goodbye', 'Thank you', 'Please', 'Yes', 'No']

  private translations: Record<string, Record<string, string>> = {
    'en': { 'Hello': 'Hello', 'Goodbye': 'Goodbye', 'Thank you': 'Thank you', 'Please': 'Please', 'Yes': 'Yes', 'No': 'No' },
    'es': { 'Hello': 'Hola', 'Goodbye': 'Adiós', 'Thank you': 'Gracias', 'Please': 'Por favor', 'Yes': 'Sí', 'No': 'No' },
    'fr': { 'Hello': 'Bonjour', 'Goodbye': 'Au revoir', 'Thank you': 'Merci', 'Please': "S'il vous plaît", 'Yes': 'Oui', 'No': 'Non' }
  }

  private swiperController: SwiperController = new SwiperController()

  translateText(text: string): string {
    return this.translations[this.currentLanguage][text] || text
  }

  onRefresh(): void {
    this.refreshing = true
    setTimeout(() => {
      this.phrases = this.phrases.concat(['Welcome', 'Sorry', 'Excuse me'])
      this.refreshing = false
    }, 2000)
  }

  nextPhrase(): void {
    if (this.currentIndex < this.phrases.length - 1) {
      this.currentIndex++
      this.swiperController.showNext()
    }
  }

  prevPhrase(): void {
    if (this.currentIndex > 0) {
      this.currentIndex--
      this.swiperController.showPrevious()
    }
  }

  build() {
    Column() {
      Row({ space: 10 }) {
        Button('English').onClick(() => { this.currentLanguage = 'en' })
        Button('Español').onClick(() => { this.currentLanguage = 'es' })
        Button('Français').onClick(() => { this.currentLanguage = 'fr' })
      }
      .margin({ top: 20, bottom: 20 })

      Refresh({ refreshing: this.refreshing }) {
        Swiper(this.swiperController) {
          ForEach(this.phrases, (phrase: string) => {
            Column({ space: 10 }) {
              Text(this.translateText(phrase))
                .fontSize(24)
                .fontWeight(FontWeight.Bold)
                .textAlign(TextAlign.Center)
              Image($r('app.media.ic_default_image'))
                .width(100)
                .height(100)
            }
            .width('100%')
            .height('100%')
            .justifyContent(FlexAlign.Center)
          })
        }
        .index(this.currentIndex)
        .width('100%')
        .height('60%')
      }
      .onRefreshing(() => this.onRefresh())

      Row({ space: 20 }) {
        Button('Previous').onClick(() => this.prevPhrase())
        Button('Next').onClick(() => this.nextPhrase())
      }
      .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

@Entry
@Component
struct CalculatorApp {
  @State displayText: string = '0'
  @State isRecording: boolean = false
  @State audioVisualization: string = ''
  private currentExpression: string = ''

  build() {
    Column() {
      Text(this.displayText)
        .fontSize(48)
        .margin({ bottom: 20 })
        .width('100%')
        .textAlign(TextAlign.End)

      Row() {
        Text(this.isRecording ? 'Recording...' : '')
          .fontSize(16)
          .margin({ right: 10 })
        Text(this.audioVisualization)
          .fontSize(16)
      }
      .margin({ bottom: 20 })

      Column() {
        Row() {
          Button('7').onClick(() => this.appendToExpression('7'))
          Button('8').onClick(() => this.appendToExpression('8'))
          Button('9').onClick(() => this.appendToExpression('9'))
          Button('/').onClick(() => this.appendToExpression('/'))
        }
        Row() {
          Button('4').onClick(() => this.appendToExpression('4'))
          Button('5').onClick(() => this.appendToExpression('5'))
          Button('6').onClick(() => this.appendToExpression('6'))
          Button('*').onClick(() => this.appendToExpression('*'))
        }
        Row() {
          Button('1').onClick(() => this.appendToExpression('1'))
          Button('2').onClick(() => this.appendToExpression('2'))
          Button('3').onClick(() => this.appendToExpression('3'))
          Button('-').onClick(() => this.appendToExpression('-'))
        }
        Row() {
          Button('0').onClick(() => this.appendToExpression('0'))
          Button('.').onClick(() => this.appendToExpression('.'))
          Button('=').onClick(() => this.evaluateExpression())
          Button('+').onClick(() => this.appendToExpression('+'))
        }
      }
      .margin({ bottom: 20 })
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .gesture(
      SwipeGesture({ direction: SwipeDirection.Vertical })
        .onAction(() => {
          this.isRecording = !this.isRecording
          if (this.isRecording) {
            this.startAudioVisualization()
          } else {
            this.clearAudioVisualization()
          }
        })
    )
  }

  private appendToExpression(value: string): void {
    if (this.displayText === '0' && value !== '.') {
      this.displayText = value
    } else {
      this.displayText += value
    }
    this.currentExpression += value
  }

  private evaluateExpression(): void {
    try {
      const result = this.safeEval(this.currentExpression)
      this.displayText = result.toString()
      this.currentExpression = result.toString()
    } catch (error) {
      this.displayText = 'Error'
      setTimeout(() => {
        this.displayText = '0'
        this.currentExpression = ''
      }, 1000)
    }
  }

  private safeEval(expr: string): number {
    const parts = expr.split(/([+\-*/])/).filter(Boolean)
    let result = parseFloat(parts[0])

    for (let i = 1; i < parts.length; i += 2) {
      const op = parts[i]
      const num = parseFloat(parts[i+1])

      switch (op) {
        case '+': result += num; break
        case '-': result -= num; break
        case '*': result *= num; break
        case '/': result /= num; break
        default: throw new Error('Invalid operator')
      }
    }
    return result
  }

  private startAudioVisualization(): void {
    this.audioVisualization = '|||||'
    const interval = setInterval(() => {
      if (!this.isRecording) {
        clearInterval(interval)
        return
      }
      this.audioVisualization = this.audioVisualization.length > 10 ? '|' : this.audioVisualization + '|'
    }, 300)
  }

  private clearAudioVisualization(): void {
    this.audioVisualization = ''
  }
}

