struct SleepTrackerApp {
  @State sleepData: Array<SleepData> = [
    { date: '2023-10-01', hours: 7, sleepType: 'deep' },
    { date: '2023-10-02', hours: 6.5, sleepType: 'light' },
    { date: '2023-10-03', hours: 8, sleepType: 'deep' },
    { date: '2023-10-04', hours: 5.5, sleepType: 'light' },
    { date: '2023-10-05', hours: 7.5, sleepType: 'deep' },
  ];
  @State searchQuery: string = '';
  @State showDeepSleep: boolean = true;
  @State showLightSleep: boolean = true;

  private filteredData(): Array<SleepData> {
    return this.sleepData.filter(data => {
      const matchesSearch = data.date.includes(this.searchQuery);
      const matchesDeep = this.showDeepSleep && data.sleepType === 'deep';
      const matchesLight = this.showLightSleep && data.sleepType === 'light';
      return matchesSearch && (matchesDeep || matchesLight);
    });
  }

  build() {
    Column() {
      // Search Bar
