              .fontColor('#FFFFFF');

            Button('Blue')
              .onClick(() => {
                this.popupBackgroundColor = '#007AFF';
              })
              .width(80)
              .height(40)
              .backgroundColor('#007AFF')
              .fontColor('#FFFFFF');

            Button('Green')
              .onClick(() => {
                this.popupBackgroundColor = '#34C759';
              })
              .width(80)
              .height(40)
              .backgroundColor('#34C759')
              .fontColor('#FFFFFF');
          }
