import { Entry, Component, State } from '@ohos.arkui.component';
import { Column, Text, Button, Radio, Tabs, TabContent, Row } from '@ohos.arkui.advanced';
import { FlexAlign, FontWeight, TextAlign } from '@ohos.arkui.base';

interface QuizQuestion {
  question: string;
  answers: string[];
  correctAnswer: string;
}

@Entry
@Component
struct PublicTransportQuiz {
  @State isAuthenticated: boolean = false;
  @State currentQuestionIndex: number = 0;
  @State selectedAnswer: string = '';
  @State questions: QuizQuestion[] = [
    {
      question: 'What is the most common mode of public transport in cities?',
      answers: ['Bus', 'Train', 'Taxi', 'Bicycle'],
      correctAnswer: 'Bus'
    },
    {
      question: 'Which of these is NOT a type of rail transport?',
      answers: ['Subway', 'Tram', 'Monorail', 'Helicopter'],
      correctAnswer: 'Helicopter'
    },
    {
      question: 'What is the primary benefit of public transport?',
      answers: ['Cost savings', 'Environmental impact', 'Convenience', 'All of the above'],
      correctAnswer: 'All of the above'
    }
  ];

  toggleAuthentication(): void {
    this.isAuthenticated = !this.isAuthenticated;
  }

  handleAnswerSelection(answer: string): void {
    this.selectedAnswer = answer;
  }

  submitAnswer(): void {
    if (this.selectedAnswer === this.questions[this.currentQuestionIndex].correctAnswer) {
      console.log('Correct answer!');
    } else {
      console.log('Incorrect answer!');
    }
    if (this.currentQuestionIndex < this.questions.length - 1) {
      this.currentQuestionIndex++;
      this.selectedAnswer = '';
    }
  }

  build() {
    Column() {
      Button(this.isAuthenticated ? 'Logout' : 'Login')
        .onClick(() => this.toggleAuthentication())
        .margin(20);

      Tabs({ barPosition: 'bottom' }) {
        ForEach(this.questions, (question: QuizQuestion, index: number) => {
          TabContent() {
            Column() {
              Text(question.question)
                .fontSize(24)
                .fontWeight(FontWeight.Bold)
                .textAlign(TextAlign.Center)
                .margin({ bottom: 40 })
                .padding({ left: 20, right: 20 });

              ForEach(question.answers, (answer: string) => {
                Row() {
                  Radio({ value: answer, group: 'answers' })
                    .checked(this.selectedAnswer === answer)
                    .onChange((isChecked: boolean) => {
                      if (isChecked) {
                        this.handleAnswerSelection(answer);
                      }
                    });
                  Text(answer)
                    .fontSize(18)
                    .margin({ left: 10 });
                }
                .alignItems(FlexAlign.Center)
                .margin({ bottom: 10 });
              });

              Button('Submit Answer')
                .onClick(() => this.submitAnswer())
                .margin({ top: 20 });
            }
            .width('100%')
            .height('100%');
          }
        });
      }
      .width('100%')
      .height('80%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

import webview from '@ohos.web.webview';
import router from '@ohos.router';

interface PDFMetadata {
  author: string;
  creationDate: string;
  fileSize: string;
}

@Entry
@Component
struct PDFViewer {
  @State currentPage: number = 1;
  @State totalPages: number = 0;
  @State pdfUrl: string = 'https://example.com/sample.pdf';
  @State author: string = 'Unknown Author';
  @State creationDate: string = 'Unknown Date';
  @State fileSize: string = 'Unknown Size';
  @State errorMessage: string = '';
  @State headerMessage: string = 'Welcome to PDF Viewer - Scroll to see more!';
  @State windowHeight: number = 0;

  private webController: webview.WebviewController = new webview.WebviewController();

  build() {
    Column({ space: 10 }) {
      Text(this.headerMessage)
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })
        .marquee({ loop: -1, scrollAmount: 5 });

      Row({ space: 10 }) {
        Column({ space: 5 }) {
          Text('Author: ' + this.author)
            .fontSize(14);
          Text('Created: ' + this.creationDate)
            .fontSize(14);
          Text('Size: ' + this.fileSize)
            .fontSize(14);
        }
        .padding(10)
        .borderRadius(5)
        .backgroundColor('#f0f0f0');
      }
      .width('100%')
      .justifyContent(FlexAlign.Start)
      .padding({ left: 10, right: 10 });

      Web({ src: this.pdfUrl, controller: this.webController })
        .onPageEnd((event: { pageNumber: number }) => {
          this.currentPage = event.pageNumber;
        })
        .onErrorReceive((event: { description: string }) => {
          this.errorMessage = 'Failed to load PDF: ' + event.description;
        })
        .onAreaChange((oldValue: { height: number }, newValue: { height: number }) => {
          this.windowHeight = newValue.height;
        })
        .width('100%')
        .height('60%');

      Row({ space: 20 }) {
        Button('Previous')
          .onClick(() => {
            if (this.currentPage > 1) {
              this.currentPage--;
              this.webController.scrollTo(0, this.currentPage * -this.windowHeight);
            }
          })
          .width('40%')
          .height(50);

        Text(`Page ${this.currentPage} of ${this.totalPages}`)
          .fontSize(16)
          .fontWeight(FontWeight.Bold);

        Button('Next')
          .onClick(() => {
            if (this.currentPage < this.totalPages) {
              this.currentPage++;
              this.webController.scrollTo(0, this.currentPage * this.windowHeight);
            }
          })
          .width('40%')
          .height(50);
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .margin({ top: 10 });

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 10 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(10);
  }
}

import hilog from '@ohos.hilog';
import { Divider, Stepper, Button, Column, Text } from '@ohos.arkui.ets';
import { Curve, FontWeight, TextAlign } from '@ohos.arkui.ets';

@Entry
@Component
struct InteractiveDividerDemo {
  @State private dividerWidth: number = 1;
  @State private dividerColor: string = '#808080';
  @State private stepperValue: number = 1;
  @State private isAnimating: boolean = false;

  private toggleAnimation(): void {
    this.isAnimating = !this.isAnimating;
    hilog.info(0x0000, 'analytics_divider', 'Divider animation toggled: %{public}s', this.isAnimating ? 'ON' : 'OFF');
  }

  private handleStepperChange(value: number): void {
    this.stepperValue = value;
    hilog.info(0x0000, 'analytics_stepper', 'Stepper value changed: %{public}d', value);
  }

  build() {
    Column({ space: 20 }) {
      Text('Interactive Divider Demo')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .textAlign(TextAlign.Center);

      Divider()
        .strokeWidth(this.dividerWidth)
        .color(this.dividerColor)
        .margin({ left: 20, right: 20 })
        .animation({
          duration: 500,
          curve: Curve.EaseInOut,
          onFinish: () => {
            if (this.isAnimating) {
              this.dividerWidth = this.dividerWidth === 1 ? 3 : 1;
              this.dividerColor = this.dividerColor === '#808080' ? '#FF0000' : '#808080';
            }
          }
        });

      Stepper({
        value: this.stepperValue,
        min: 1,
        max: 5,
        step: 1
      })
        .onChange((value: number) => this.handleStepperChange(value));

      if (this.stepperValue > 2) {
        Button('Toggle Animation')
          .onClick(() => this.toggleAnimation())
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5');
  }
}

import { Text, Button, Column, Row, List, Scroll } from '@ohos.arkui.advanced.Components';
import { State } from '@ohos.arkui.advanced.StateManagement';
import { CustomDialogController } from '@ohos.arkui.advanced.PopupDialog';

interface SensorData {
  timestamp: string;
  value: number;
}

@Entry
@Component
struct SensorMonitor {
  @State sensorData: SensorData[] = [];
  private dialogController: CustomDialogController = new CustomDialogController({
    builder: () => this.DialogBuilder(),
    cancel: () => {},
    autoCancel: true
  });

  private addSensorReading(): void {
    const newReading: SensorData = {
      timestamp: new Date().toLocaleTimeString('en-US', { hour12: false }),
      value: Number((Math.random() * 100).toFixed(2))
    };
    this.sensorData = [newReading, ...this.sensorData].slice(0, 10);
  }

  @Builder
  DialogBuilder(): Column {
    Column() {
      Text('Latest Reading')
        .fontSize(20)
        .margin({ bottom: 10 });
      Text(`Value: ${this.sensorData[0]?.value?.toFixed(2) || 'N/A'}`)
        .fontSize(16);
      Button('Close')
        .onClick(() => this.dialogController.close())
        .margin({ top: 20 });
    }
    .padding(20)
  }

  build(): Column {
    Column() {
      Row() {
        Button('Refresh Data')
          .onClick(() => this.addSensorReading())
          .margin(10);
        Button('Show Current Value')
          .onClick(() => this.dialogController.open())
          .margin(10);
      }

      Scroll() {
        List() {
          ForEach(this.sensorData, (item: SensorData, index: number) => {
            List.Item() {
              Row() {
                Text(item.timestamp)
                  .fontSize(16)
                  .margin({ right: 20 });
                Text(item.value.toFixed(2))
                  .fontSize(16);
              }
              .padding(10);
            }
            .key(index.toString())
          });
        }
        .width('100%');
      }
      .layoutWeight(1);
    }
    .padding(20);
  }
}

import { Column, List, ListItem, Text, Button, Modal, Stack } from '@ohos.arkui.advancedUI';
import { animate, EaseIn } from '@ohos.arkui.animator';
import { TextDecorationType, FontWeight } from '@ohos.arkui.common';

interface Task {
  id: number;
  title: string;
  description: string;
  completed: boolean;
}

@Entry
@Component
struct TaskJournal {
  @State tasks: Task[] = [
    { id: 1, title: 'Task 1', description: 'Description for Task 1', completed: false },
    { id: 2, title: 'Task 2', description: 'Description for Task 2', completed: true },
    { id: 3, title: 'Task 3', description: 'Description for Task 3', completed: false }
  ];

  @State selectedTask: Task | null = null;
  @State showBottomSheet: boolean = false;

  build() {
    Stack() {
      Column() {
        List() {
          ForEach(this.tasks, (task: Task) => {
            ListItem() {
              Column() {
                Text(task.title)
                  .fontSize(16)
                  .fontColor(task.completed ? '#888888' : '#000000')
                  .textDecoration(task.completed ? TextDecorationType.LineThrough : TextDecorationType.None);
              }
              .onClick(() => {
                animate(this, {
                  duration: 200,
                  curve: EaseIn,
                  onFinish: () => {
                    this.selectedTask = task;
                    this.showBottomSheet = true;
                  }
                });
              });
            }
          });
        }
      }
      .width('100%')
      .height('100%')
      .padding(20);

      Modal({
        show: this.showBottomSheet,
        onDismiss: () => {
          this.showBottomSheet = false;
        }
      }) {
        Column() {
          Text(this.selectedTask?.title ?? '')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 10 });

          Text(this.selectedTask?.description ?? '')
            .fontSize(16);

          Button('Close')
            .onClick(() => {
              this.showBottomSheet = false;
            })
            .margin({ top: 20 });
        }
        .width('100%')
        .padding(20)
        .backgroundColor('#ffffff')
        .borderRadius(10)
      }
    }
  }
}

import { Tabs, TabContent, BarPosition } from '@ohos.arkui.advanced';
import { FlexAlign } from '@ohos.arkui.advanced';
import sensor from '@ohos.sensor';

@Entry
@Component
struct OnboardingApp {
  @State currentIndex: number = 0;
  @State accelerometerData: string = 'No sensor data available';

  private sensorId: number = -1;

  aboutToAppear() {
    try {
      this.sensorId = sensor.on(sensor.SensorType.SENSOR_TYPE_ID_ACCELEROMETER, (data) => {
        this.accelerometerData = `X: ${data.x.toFixed(2)}, Y: ${data.y.toFixed(2)}, Z: ${data.z.toFixed(2)}`;
      });
    } catch (error) {
      this.accelerometerData = 'Sensor not available';
    }
  }

  aboutToDisappear() {
    if (this.sensorId !== -1) {
      sensor.off(this.sensorId);
    }
  }

  @Builder
  HomeTabContent() {
    Column() {
      Text('Home')
        .fontSize(28)
        .margin({ bottom: 20 });
      Text(this.accelerometerData)
        .fontSize(16);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(FlexAlign.Center);
  }

  @Builder
  ProfileTabContent() {
    Column() {
      Text('Profile')
        .fontSize(28)
        .margin({ bottom: 20 });
      Text('User profile information goes here.')
        .fontSize(16);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(FlexAlign.Center);
  }

  @Builder
  SettingsTabContent() {
    Column() {
      Text('Settings')
        .fontSize(28)
        .margin({ bottom: 20 });
      Text('App settings go here.')
        .fontSize(16);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(FlexAlign.Center);
  }

  @Builder
  AboutTabContent() {
    Column() {
      Text('About')
        .fontSize(28)
        .margin({ bottom: 20 });
      Text('App version and information go here.')
        .fontSize(16);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(FlexAlign.Center);
  }

  build() {
    Tabs({ barPosition: BarPosition.End }) {
      TabContent() {
        this.HomeTabContent();
      }.tabBar('Home');

      TabContent() {
        this.ProfileTabContent();
      }.tabBar('Profile');

      TabContent() {
        this.SettingsTabContent();
      }.tabBar('Settings');

      TabContent() {
        this.AboutTabContent();
      }.tabBar('About');
    }
    .width('100%')
    .height('100%');
  }
}

import { Swiper, SwiperController } from '@ohos.arkui.component';
import { Breadcrumb, BreadcrumbItem } from '@ohos.arkui.component';
import { Image, Column, Text } from '@ohos.arkui.component';
import { ImageFit } from '@ohos.arkui.component';
import { State } from '@ohos.arkui.abilitycommon';

@Entry
@Component
struct PDFViewer {
  @State currentIndex: number = 0;
  private swiperController: SwiperController = new SwiperController();
  private pdfPages: Array<string> = ['page1', 'page2', 'page3'];

  build() {
    Column() {
      Swiper(this.swiperController) {
        ForEach(this.pdfPages, (page: string) => {
          Image($r('app.media.' + page))
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%')
            .borderRadius(16);
        });
      }
      .loop(false)
      .onChange((index: number) => {
        this.currentIndex = index;
      });

      Breadcrumb()
        .margin({ top: 20 }) {
        ForEach(this.pdfPages, (page: string, index: number) => {
          BreadcrumbItem() {
            Text(`Page ${index + 1}`)
              .onClick(() => {
                this.swiperController.showIndex(index);
                this.currentIndex = index;
              });
          }
        });
      }
    }
    .width('100%')
    .height('100%')
    .padding(16);
  }
}

@Entry
@Component
struct TransportStepperApp {
  @State private currentStep: number = 0;
  private totalSteps: number = 4;
  private transportStops: string[] = ["Stop A", "Stop B", "Stop C", "Stop D"];
  @State private latitude: number = 37.7749;
  @State private longitude: number = -122.4194;

  @Builder
  StepContent(step: number) {
    Column() {
      Text(`Current Stop: ${this.transportStops[step]}`)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Text(`Coordinates: ${this.latitude}, ${this.longitude}`)
        .fontSize(16)
        .margin({ bottom: 20 });

      Image($r('sys.media.ohos_app_icon'))
        .width(100)
        .height(100)
        .margin({ bottom: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }

  build() {
    Column() {
      this.StepContent(this.currentStep);

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentStep > 0) {
              this.currentStep--;
            }
          })
          .margin({ right: 20 })
          .enabled(this.currentStep > 0);

        Button('Next')
          .onClick(() => {
            if (this.currentStep < this.totalSteps - 1) {
              this.currentStep++;
            }
          })
          .enabled(this.currentStep < this.totalSteps - 1);
      }
      .margin({ top: 50 });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

import { SideBarContainer } from '@ohos.arkui.advanced';
import { Text, Button, Column, Row, List, ListItem, Scroll } from '@ohos.arkui.component';
import { TimePicker } from '@ohos.arkui.component';
import { FontWeight, Color, ButtonType } from '@ohos.arkui.component';

interface Movie {
  id: number;
  title: string;
  showtimes: string[];
}

@Entry
@Component
struct MovieBookingApp {
  @State movies: Movie[] = [
    { id: 1, title: 'Inception', showtimes: ['10:00 AM', '02:00 PM', '06:00 PM'] },
    { id: 2, title: 'The Matrix', showtimes: ['11:00 AM', '03:00 PM', '07:00 PM'] },
    { id: 3, title: 'Interstellar', showtimes: ['09:00 AM', '01:00 PM', '05:00 PM'] },
  ];
  @State selectedMovie: Movie | null = null;
  @State selectedTime: string = '';
  @State isTimeValid: boolean = false;
  @State errorMessage: string = '';

  build() {
    SideBarContainer() {
      Column() {
        Text('Movie List')
          .fontSize(24)
          .fontWeight(FontWeight.Bolder)
          .padding(16);

        Scroll() {
          List() {
            ForEach(this.movies, (movie: Movie) => {
              ListItem() {
                Row() {
                  Text(movie.title)
                    .fontSize(18)
                    .fontWeight(FontWeight.Medium)
                    .padding(10);
                  Button('Select')
                    .onClick(() => {
                      this.selectedMovie = movie;
                      this.selectedTime = '';
                      this.isTimeValid = false;
                      this.errorMessage = '';
                    });
                }
              }
            });
          }
        }
      }

      Column() {
        if (this.selectedMovie) {
          Text(`Selected: ${this.selectedMovie.title}`)
            .fontSize(20)
            .fontWeight(FontWeight.Bolder)
            .padding(16);

          TimePicker()
            .selected(this.selectedTime)
            .onChange((time: string) => {
              this.selectedTime = time;
              this.validateTime();
            });

          if (this.errorMessage) {
            Text(this.errorMessage)
              .fontColor(Color.RED)
              .fontSize(14)
              .padding(10);
          }

          Button('Confirm Booking', { type: ButtonType.Capsule, stateEffect: true })
            .enabled(this.isTimeValid)
            .onClick(() => {
              // Handle booking confirmation
            });
        } else {
          Text('Select a movie to book')
            .fontSize(18)
            .padding(16);
        }
      }
    }
  }

  private validateTime() {
    if (!this.selectedMovie) {
      this.isTimeValid = false;
      this.errorMessage = 'Please select a movie first';
      return;
    }

    if (!this.selectedTime) {
      this.isTimeValid = false;
      this.errorMessage = 'Please select a showtime';
      return;
    }

    if (!this.selectedMovie.showtimes.includes(this.selectedTime)) {
      this.isTimeValid = false;
      this.errorMessage = 'Invalid showtime for selected movie';
      return;
    }

    this.isTimeValid = true;
    this.errorMessage = '';
  }
}

@Entry
@Component
struct CurrencyConverterCard {
  @State amount: number = 0;
  @State convertedAmount: number = 0;
  @State showResult: boolean = false;
  private exchangeRate: number = 0.85;

  build() {
    Column() {
      Column() {
        Row() {
          Text('USD to EUR')
            .fontSize(18)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 10 });
        }

        Text(`Rate: ${this.exchangeRate}`)
          .fontSize(14)
          .textOverflow({ overflow: TextOverflow.MARQUEE })
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Enter amount' })
          .type(InputType.Number)
          .height(40)
          .width('80%')
          .margin({ bottom: 10 })
          .onChange((value: string) => {
            this.amount = parseFloat(value) || 0;
          });

        Button('Convert')
          .width('50%')
          .margin({ bottom: 10 })
          .onClick(() => {
            this.convertedAmount = this.amount * this.exchangeRate;
            this.showResult = !this.showResult;
          });

        if (this.showResult) {
          Text(`Converted: ${this.convertedAmount.toFixed(2)} EUR`)
            .fontSize(16)
            .margin({ top: 10 });
        }
      }
      .width('90%')
      .padding(20)
      .backgroundColor(Color.White)
      .borderRadius(10)
      .shadow({ radius: 5, color: Color.Gray, offsetX: 2, offsetY: 2 })
      .gesture(
        TapGesture()
          .onAction(() => {
            this.showResult = !this.showResult;
          })
      );
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f0f0f0')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

