import { Checkbox, Button, List, Image, Text, Column, Row } from '@ohos.arkui.advanced';
import { FontWeight } from '@ohos.arkui.advanced';

interface ForecastItem {
  day: string;
  temperature: number;
  condition: string;
}

interface Settings {
  unit: 'Celsius' | 'Fahrenheit';
  language: 'English' | 'Spanish';
}

interface CurrentWeather {
  temperature: number;
  condition: string;
  location: string;
}

@Entry
@Component
struct WeatherApp {
  @State currentWeather: CurrentWeather = {
    temperature: 25,
    condition: 'Sunny',
    location: 'New York'
  };

  @State forecast: ForecastItem[] = [
    { day: 'Monday', temperature: 23, condition: 'Cloudy' },
    { day: 'Tuesday', temperature: 26, condition: 'Sunny' },
    { day: 'Wednesday', temperature: 21, condition: 'Rainy' },
    { day: 'Thursday', temperature: 24, condition: 'Partly Cloudy' },
    { day: 'Friday', temperature: 27, condition: 'Sunny' }
  ];

  @State settings: Settings = {
    unit: 'Celsius',
    language: 'English'
  };

  private getWeatherIcon(condition: string): Resource {
    switch (condition.toLowerCase()) {
      case 'sunny':
        return $r('app.media.sunny');
      case 'cloudy':
        return $r('app.media.cloudy');
      case 'rainy':
        return $r('app.media.rainy');
      default:
        return $r('app.media.weather_app_logo');
    }
  }

  private convertTemperature(temp: number): string {
    if (this.settings.unit === 'Fahrenheit') {
      return `${Math.round((temp * 9) / 5 + 32)}\u00b0F`;
    }
    return `${temp}\u00b0C`;
  }

  private toggleUnit(): void {
    this.settings.unit = this.settings.unit === 'Celsius' ? 'Fahrenheit' : 'Celsius';
  }

  private toggleLanguage(): void {
    this.settings.language = this.settings.language === 'English' ? 'Spanish' : 'English';
  }

  build() {
    Column() {
      Image($r('app.media.weather_app_logo'))
        .width(100)
        .height(100)
        .margin({ bottom: 20 });

      Text(this.currentWeather.location)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      Row() {
        Text(this.convertTemperature(this.currentWeather.temperature))
          .fontSize(20)
          .margin({ right: 10 });

        Image(this.getWeatherIcon(this.currentWeather.condition))
          .width(30)
          .height(30);
      }
      .margin({ bottom: 20 });

      Row() {
        Checkbox({ name: 'Celsius', group: 'unit' })
          .checked(this.settings.unit === 'Celsius')
          .onChange(() => this.toggleUnit());

        Checkbox({ name: 'Fahrenheit', group: 'unit' })
          .checked(this.settings.unit === 'Fahrenheit')
          .onChange(() => this.toggleUnit());
      }
      .margin({ bottom: 20 });

      Button(this.settings.language === 'English' ? 'Español' : 'English')
        .onClick(() => this.toggleLanguage())
        .margin({ bottom: 20 });

      Text('5-Day Forecast')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      List() {
        ForEach(this.forecast, (item: ForecastItem) => {
          ListItem() {
            Row() {
              Text(item.day)
                .fontSize(18)
                .fontWeight(FontWeight.Bold)
                .margin({ right: 10 });

              Text(this.convertTemperature(item.temperature))
                .fontSize(18)
                .margin({ right: 10 });

              Image(this.getWeatherIcon(item.condition))
                .width(20)
                .height(20);
            }
            .padding(10);
          }
        });
      }
      .height(300);
    }
    .padding(20);
  }
}

import promptAction from '@ohos.promptAction';

@Entry
@Component
struct WaterIntakeTracker {
  @State waterIntake: number = 0;
  @State dailyGoal: number = 2000;
  @State progress: number = 0;

  updateProgress() {
    this.progress = (this.waterIntake / this.dailyGoal) * 100;
    if (this.progress >= 100) {
      this.showGoalAchievedAlert();
    }
  }

  showGoalAchievedAlert() {
    promptAction.showDialog({
      title: 'Goal Achieved!',
      message: 'You have reached your daily water intake goal.',
      buttons: [
        {
          text: 'OK',
          color: '#000000'
        }
      ]
    });
  }

  build() {
    Column() {
      Text('Daily Water Intake Tracker')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin(20);

      Text(`Goal: ${this.dailyGoal} ml`)
        .fontSize(18)
        .margin(10);

      Text(`Consumed: ${this.waterIntake} ml`)
        .fontSize(18)
        .margin(10);

      Stack() {
        Circle()
          .width(200)
          .height(200)
          .stroke('#E0E0E0')
          .strokeWidth(15)
          .fill('transparent');

        Circle()
          .width(200)
          .height(200)
          .stroke('#4CAF50')
          .strokeWidth(15)
          .fill('transparent')
          .strokeDashArray([Math.PI * 200, Math.PI * 200])
          .strokeDashOffset(Math.PI * 200 * (1 - this.progress / 100))
          .rotate({ x: 0, y: 0, z: 1, angle: -90 });

        Text(`${Math.round(this.progress)}%`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold);
      }
      .width(200)
      .height(200)
      .margin({ top: 50 });

      Button('Log 250 ml')
        .onClick(() => {
          this.waterIntake += 250;
          this.updateProgress();
        })
        .width(200)
        .height(50)
        .margin({ top: 40 });

      Button('Reset')
        .onClick(() => {
          this.waterIntake = 0;
          this.updateProgress();
        })
        .width(200)
        .height(50)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

