interface Expense {
  amount: number;
  description: string;
  date: string;
  category: string;
}

@Entry
@Component
struct ExpenseTracker {
  @State expenses: Expense[] = [];
  @State activeTab: string = 'expenses';
  @State newAmount: string = '';
  @State newDescription: string = '';
  @State newDate: string = '';
  @State newCategory: string = 'food';

  @Builder
  ExpensesTab(comp: ExpenseTracker) {
    Column() {
      List() {
        ForEach(['food', 'transport', 'entertainment', 'utilities'], (category: string) => {
          ListItem() {
            Column() {
              Text(category.toUpperCase())
                .fontSize(20)
                .fontWeight(FontWeight.Bold)
                .margin({ bottom: 10 });
              ForEach(comp.expenses.filter(expense => expense.category === category), (expense: Expense) => {
                Row() {
                  Column() {
                    Text(`$${expense.amount.toFixed(2)}`)
                      .fontSize(18);
                    Text(expense.description)
                      .fontSize(14);
                    Text(expense.date)
                      .fontSize(12);
                  }
                  Button('Edit')
                    .onClick(() => {
                      comp.newAmount = expense.amount.toString();
                      comp.newDescription = expense.description;
                      comp.newDate = expense.date;
                      comp.newCategory = expense.category;
                      comp.expenses = comp.expenses.filter(e => e !== expense);
                    });
                }
                .margin({ bottom: 10 });
              })
            }
            .margin({ bottom: 20 });
          }
        })
      }
    }
    .padding(20);
  }

  @Builder
  AddExpenseTab(comp: ExpenseTracker) {
    Column() {
      TextInput({ placeholder: 'Amount', text: comp.newAmount })
        .onChange((value: string) => {
          if (/^\d*\.?\d*$/.test(value)) {
            comp.newAmount = value;
          }
        });
      TextInput({ placeholder: 'Description', text: comp.newDescription })
        .onChange((value: string) => {
          comp.newDescription = value;
        });
      TextInput({ placeholder: 'Date', text: comp.newDate })
        .onChange((value: string) => {
          comp.newDate = value;
        });
      Row() {
        ForEach(['food', 'transport', 'entertainment', 'utilities'], (category: string) => {
          Radio({ value: category, group: 'category' })
            .checked(comp.newCategory === category)
            .onChange((isChecked: boolean) => {
              if (isChecked) comp.newCategory = category;
            });
          Text(category);
        })
      }
      Button('Add Expense')
        .onClick(() => {
          if (comp.newAmount && comp.newDescription && comp.newDate) {
            comp.expenses.push({
              amount: parseFloat(comp.newAmount),
              description: comp.newDescription,
              date: comp.newDate,
              category: comp.newCategory
            });
            comp.newAmount = '';
            comp.newDescription = '';
            comp.newDate = '';
          }
        });
    }
    .padding(20);
  }

  build() {
    Column() {
      Row() {
        Button('Expenses')
          .onClick(() => { this.activeTab = 'expenses'; })
          .backgroundColor(this.activeTab === 'expenses' ? '#0000FF' : '#808080');
        Button('Add Expense')
          .onClick(() => { this.activeTab = 'addExpense'; })
          .backgroundColor(this.activeTab === 'addExpense' ? '#0000FF' : '#808080');
      }
      if (this.activeTab === 'expenses') {
        this.ExpensesTab(this);
      } else {
        this.AddExpenseTab(this);
      }
    }
  }
}

import { Text, Button, Column, Row, FontWeight, FlexAlign } from '@ohos.arkui.UIContext';
import { animateTo, Curve } from '@ohos.arkui.animation';

interface JournalEntry {
  title: string;
  content: string;
}

@Entry
@Component
struct JournalPodcastPlayer {
  @State currentIndex: number = 0;
  private entries: JournalEntry[] = [
    { title: 'Entry 1', content: 'This is the content for journal entry 1.' },
    { title: 'Entry 2', content: 'This is the content for journal entry 2.' },
    { title: 'Entry 3', content: 'This is the content for journal entry 3.' }
  ];

  private navigate(direction: number): void {
    const newIndex = this.currentIndex + direction;
    if (newIndex >= 0 && newIndex < this.entries.length) {
      animateTo({
        duration: 400,
        curve: Curve.EaseInOut
      }, () => {
        this.currentIndex = newIndex;
      });
    }
  }

  build() {
    Column() {
      Column() {
        Text(this.entries[this.currentIndex].title)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 10 });

        Text(this.entries[this.currentIndex].content)
          .fontSize(16)
          .margin({ bottom: 20 });
      }
      .width('100%')
      .padding(20)
      .backgroundColor('#f5f5f5')
      .borderRadius(8)
      .margin({ bottom: 20 });

      Row() {
        Button('Previous')
          .onClick(() => this.navigate(-1))
          .enabled(this.currentIndex > 0)
          .width('40%')
          .height(50)
          .margin({ right: 10 });

        Button('Next')
          .onClick(() => this.navigate(1))
          .enabled(this.currentIndex < this.entries.length - 1)
          .width('40%')
          .height(50);
      }
      .width('100%')
      .justifyContent(FlexAlign.Center);
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#ffffff');
  }
}

@Entry
@Component
struct InfiniteScrollAnimation {
  @State private items: string[] = Array.from<number, string>({ length: 10 }, (_, i) => `Item ${i + 1}`);
  @State private loading: boolean = false;
  private colors: string[] = ['#FF6B6B', '#4ECDC4', '#45B7D1', '#96CEB4', '#FFEEAD'];

  loadMoreItems() {
    if (this.loading) return;
    this.loading = true;
    setTimeout(() => {
      const newItems = Array.from<number, string>({ length: 10 }, (_, i) => `Item ${this.items.length + i + 1}`);
      this.items = [...this.items, ...newItems];
      this.loading = false;
    }, 1000);
  }

  onItemClick(index: number) {
    console.log(`Item clicked: ${this.items[index]}`);
  }

  build() {
    Scroll() {
      Column() {
        ForEach(this.items, (item: string, index: number) => {
          Row() {
            Text(item)
              .fontSize(16)
              .fontWeight(FontWeight.Bold)
              .margin({ left: 10 });
          }
          .width('100%')
          .height(60)
          .backgroundColor(this.colors[index % this.colors.length])
          .borderRadius(8)
          .margin({ top: 5, bottom: 5 })
          .onClick(() => this.onItemClick(index));
        })
      }
      .width('100%')
    }
    .width('100%')
    .height('100%')
    .onReachEnd(() => {
      if (!this.loading) {
        this.loadMoreItems();
      }
    })
  }
}

