import media from '@ohos.multimedia.media';
import { Image, Button, Slider, Text, Column, Row } from '@ohos.arkui';
import { ImageFit, FontWeight, SliderStyle } from '@ohos.arkui';

@Entry
@Component
struct VideoPlayerApp {
  private avPlayer: media.AVPlayer | null = null;
  @State isPlaying: boolean = false;
  @State currentTime: number = 0;
  @State totalDuration: number = 0;
  @State filterType: string = 'None';
  @State marqueeText: string = 'Now Playing: Sample Video';

  build() {
    Column() {
      Image($r('app.media.ic_public_video'))
        .width(300)
        .height(200)
        .objectFit(ImageFit.Cover)
        .margin({ bottom: 16 });

      Text(this.marqueeText)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 16 })
        .marquee({ loop: -1, scrollAmount: 5 });

      Row() {
        Button(this.isPlaying ? 'Pause' : 'Play')
          .onClick(() => {
            if (this.avPlayer) {
              if (this.isPlaying) {
                this.avPlayer.pause();
              } else {
                this.avPlayer.play();
              }
              this.isPlaying = !this.isPlaying;
            }
          })
          .margin({ right: 8 });

        Button('Stop')
          .onClick(() => {
            if (this.avPlayer) {
              this.avPlayer.stop();
              this.isPlaying = false;
              this.currentTime = 0;
            }
          });
      }
      .margin({ bottom: 16 });

      Slider({
        value: this.currentTime,
        min: 0,
        max: this.totalDuration,
        step: 1,
        style: SliderStyle.OutSet
      })
        .onChange((value: number) => {
          this.currentTime = value;
          if (this.avPlayer) {
            this.avPlayer.seek(value);
          }
        })
        .margin({ bottom: 16 });

      Row() {
        Button('None')
          .onClick(() => {
            this.filterType = 'None';
          })
          .margin({ right: 8 });

        Button('Sepia')
          .onClick(() => {
            this.filterType = 'Sepia';
          })
          .margin({ right: 8 });

        Button('Grayscale')
          .onClick(() => {
            this.filterType = 'Grayscale';
          });
      }
      .margin({ bottom: 16 });
    }
    .padding(16)
    .onAppear(() => {
      this.initAVPlayer();
    })
    .onDisappear(() => {
      this.cleanupAVPlayer();
    });
  }

  private async initAVPlayer() {
    try {
      this.avPlayer = await media.createAVPlayer();
      if (this.avPlayer) {
        this.avPlayer.on('stateChange', (state: string) => {
          if (state === 'prepared') {
            this.totalDuration = this.avPlayer?.duration || 0;
          }
        });
        this.avPlayer.on('timeUpdate', (currentTime: number) => {
          this.currentTime = currentTime;
        });
        const fdPath = await getContext(this).resourceManager.getRawFd('video.mp4');
        this.avPlayer.fdSrc = {
          fd: fdPath.fd,
          offset: fdPath.offset,
          length: fdPath.length
        };
      }
    } catch (err) {
      console.error(`Failed to initialize AVPlayer: ${err.message}`);
    }
  }

  private cleanupAVPlayer() {
    if (this.avPlayer) {
      this.avPlayer.release();
      this.avPlayer = null;
    }
  }
}

import { ScrollView, TextInput, Button, Column, Row, Text } from '@ohos.arkui.component';
import { List, ListItem, FlexAlign, HorizontalAlign } from '@ohos.arkui.advanced';
