@Entry
@Component
struct NoteApp {
  @State notes: string[] = [];
  @State noteInput: string = '';
  @State totalNotes: number = 0;
  @State averageLength: number = 0;

  private validateNote(note: string): boolean {
    return note.trim().length > 0;
  }

  private updateAnalytics(): void {
    this.totalNotes = this.notes.length;
    if (this.totalNotes > 0) {
      const totalLength = this.notes.reduce((sum, note) => sum + note.length, 0);
      this.averageLength = parseFloat((totalLength / this.totalNotes).toFixed(2));
    } else {
      this.averageLength = 0;
    }
  }

  private saveNote(): void {
    if (this.validateNote(this.noteInput)) {
      this.notes.push(this.noteInput);
      this.noteInput = '';
      this.updateAnalytics();
    }
  }

  private clearNotes(): void {
    this.notes = [];
    this.updateAnalytics();
  }

  build() {
    Column() {
      ScrollView() {
        Column() {
          TextInput({ placeholder: 'Enter your note...', text: this.noteInput })
            .height(100)
            .width('90%')
            .onChange((value: string) => {
              this.noteInput = value;
            })
            .margin(10);

          Row() {
            Button('Save Note')
              .onClick(() => this.saveNote())
              .margin(5);

            Button('Clear Notes')
              .onClick(() => this.clearNotes())
              .margin(5);
          }
          .justifyContent(FlexAlign.Center)
          .width('90%');

          Text(`Total Notes: ${this.totalNotes}`)
            .fontSize(16)
            .margin(10);

          Text(`Average Note Length: ${this.averageLength}`)
            .fontSize(16)
            .margin(10);

          List() {
            ForEach(this.notes, (note: string, index: number) => {
              ListItem() {
                Text(`${index + 1}. ${note}`)
                  .fontSize(14)
                  .margin(10);
              }
            });
          }
          .width('90%')
          .margin(10);
        }
        .width('100%')
        .alignItems(HorizontalAlign.Center);
      }
      .width('100%')
      .height('100%');
    }
  }
}

