  @State errorMessage: string = "";
  @State isError: boolean = false;
  private controller: ErrorController = new ErrorController();

  handleErrorScenario() {
    try {
      const result = this.controller.simulateError(this.isError);
      this.errorMessage = result;
    } catch (error) {
      this.errorMessage = error.message;
    }
  }

  build() {
    Column() {
      Tabs({ barPosition: 0, index: this.activeTab }) {
        TabContent() {
          Column() {
            Grid() {
              GridItem() {
                Text("Grid Item 1")
                  .fontSize(16)
                  .textAlign(TextAlign.Center)
                  .width('100%')
                  .height('100%')
                  .backgroundColor('#f0f0f0')
              }
              GridItem() {
                Text("Grid Item 2")
                  .fontSize(16)
                  .textAlign(TextAlign.Center)
                  .width('100%')
                  .height('100%')
                  .backgroundColor('#e0e0e0')
              }
              GridItem() {
                Text("Grid Item 3")
                  .fontSize(16)
                  .textAlign(TextAlign.Center)
                  .width('100%')
                  .height('100%')
                  .backgroundColor('#d0d0d0')
              }
              GridItem() {
                Text("Grid Item 4")
                  .fontSize(16)
                  .textAlign(TextAlign.Center)
                  .width('100%')
                  .height('100%')
                  .backgroundColor('#c0c0c0')
              }
            }
            .columnsTemplate('1fr 1fr')
            .rowsTemplate('1fr 1fr')
            .height('60%')
            .width('100%')
          }
          .width('100%')
          .height('100%')
        }
        .tabBar("Tab 1")

        TabContent() {
          Column() {
            Text("Content for Tab 2")
              .fontSize(16)
              .textAlign(TextAlign.Center)
              .width('100%')
              .height('100%')
          }
          .width('100%')
          .height('100%')
        }
        .tabBar("Tab 2")
      }
      .onChange((index: number) => {
        this.activeTab = index;
      })
      .width('100%')
      .height('80%')

      Column() {
        Text(this.errorMessage)
          .fontSize(16)
          .fontColor(this.isError ? '#ff0000' : '#00ff00')
          .margin({ bottom: 20 })

        Button(this.isError ? 'Retry' : 'Simulate Error')
          .onClick(() => {
            this.isError = !this.isError;
            this.handleErrorScenario();
          })
          .width('50%')
          .height(40)
          .backgroundColor(this.isError ? '#ff0000' : '#00ff00')
          .fontColor('#ffffff')
      }
      .padding(20)
      .width('100%')
      .height('20%')
    }
    .width('100%')
    .height('100%')
  }
}

