@Entry
@Component
struct FlashcardMeditationApp {
  @State showOnboarding: boolean = true;
  @State flashcards: Array<Flashcard> = [
    { id: 1, front: "Breathe In", back: "Hold for 4 seconds", flipped: false } as Flashcard,
    { id: 2, front: "Breathe Out", back: "Hold for 4 seconds", flipped: false } as Flashcard,
    { id: 3, front: "Relax", back: "Hold for 4 seconds", flipped: false } as Flashcard
  ];

  build() {
    Column() {
      if (this.showOnboarding) {
        Text("Welcome to Flashcard Meditation")
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .textAlign(TextAlign.Center)
          .margin({ top: 20 });
        Text("Tap on flashcards to flip them and follow the meditation steps.")
          .fontSize(16)
          .textAlign(TextAlign.Center)
          .margin({ top: 10, bottom: 20 });
        Button("Got it!")
          .onClick(() => {
            this.showOnboarding = false;
          })
          .width('50%')
          .margin({ bottom: 20 });
      }

      ForEach(this.flashcards, (flashcard: Flashcard) => {
        Column() {
          Text(flashcard.flipped ? flashcard.back : flashcard.front)
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .textAlign(TextAlign.Center)
