            .backgroundColor(Color.White)
            .borderRadius(10)
            .width('80%')
            .margin({ top: 20 })
            .gesture(
              TapGesture()
                .onAction(() => {
                  this.flashcards = this.flashcards.map(item => {
                    if (item.id === flashcard.id) {
                      const newItem: Flashcard = { id: item.id, front: item.front, back: item.back, flipped: !item.flipped };
                      return newItem;
                    }
                    return item;
                  });
                })
            )
        }
        .width('100%')
        .alignItems(HorizontalAlign.Center)
      })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

