import { 
  Column, 
  Text, 
  ForEach, 
  Row, 
  TimePicker, 
  TextInput, 
  Toggle, 
  Button, 
  Badge,
  FontWeight,
  ToggleType,
  FlexAlign,
  BadgePosition
} from '@ohos.arkui_components';

interface Alarm {
  id: number;
  time: string;
  label: string;
  active: boolean;
  hasNotification: boolean;
}

interface TimePickerResult {
  hour: number;
  minute: number;
  second?: number;
}

@Entry
@Component
struct AlarmClockApp {
  @State alarms: Alarm[] = [
    { id: 1, time: '08:00', label: 'Morning Alarm', active: true, hasNotification: false },
    { id: 2, time: '12:30', label: 'Lunch Alarm', active: false, hasNotification: true },
    { id: 3, time: '18:45', label: 'Evening Alarm', active: true, hasNotification: false },
    { id: 4, time: '22:15', label: 'Night Alarm', active: false, hasNotification: true }
  ];

  @State currentPage: number = 0;
  @State newTime: string = '00:00';
  @State newLabel: string = '';

  private pageSize: number = 2;

  getPaginatedAlarms(): Alarm[] {
    const startIndex = this.currentPage * this.pageSize;
    return this.alarms.slice(startIndex, startIndex + this.pageSize);
  }

  addAlarm(): void {
    if (!this.newTime || !this.newLabel) return;

    const timeRegex = /^([0-1]?[0-9]|2[0-3]):[0-5][0-9]$/;
    if (!timeRegex.test(this.newTime)) return;

    const newAlarm: Alarm = {
      id: this.alarms.length + 1,
      time: this.newTime,
      label: this.newLabel,
      active: true,
      hasNotification: false,
    };

    this.alarms = this.alarms.concat([newAlarm]);
    this.newTime = '00:00';
    this.newLabel = '';
  }

  toggleAlarm(id: number): void {
    this.alarms = this.alarms.map(alarm => {
      if (alarm.id === id) {
        let newAlarm: Alarm = {
          id: alarm.id,
          time: alarm.time,
          label: alarm.label,
          active: !alarm.active,
          hasNotification: alarm.hasNotification
        };
        return newAlarm;
      }
      return alarm;
    });
  }

  nextPage(): void {
    if ((this.currentPage + 1) * this.pageSize < this.alarms.length) {
      this.currentPage += 1;
    }
  }

  prevPage(): void {
    if (this.currentPage > 0) {
      this.currentPage -= 1;
    }
  }

  build() {
    Column() {
      Column() {
        ForEach(this.getPaginatedAlarms(), (alarm: Alarm) => {
          Column() {
            Row() {
              if (alarm.hasNotification) {
                Badge({ count: 1, position: BadgePosition.Right }) {
                  Text(alarm.time)
                    .fontSize(24)
                    .fontWeight(FontWeight.Bold);
                }
              } else {
                Text(alarm.time)
                  .fontSize(24)
                  .fontWeight(FontWeight.Bold);
              }
            }
            Text(alarm.label)
              .fontSize(16)
              .margin({ top: 8 });
            Toggle({ type: ToggleType.Switch, isOn: alarm.active })
              .onChange(() => this.toggleAlarm(alarm.id))
              .margin({ top: 8 });
          }
          .padding(16)
          .borderRadius(8)
          .backgroundColor('#F0F0F0')
          .margin({ bottom: 16 });
        });
      }
      .width('100%')
      .padding(16);

      Row() {
        Button('Previous')
          .onClick(() => this.prevPage())
          .enabled(this.currentPage > 0);
        Button('Next')
          .onClick(() => this.nextPage())
          .enabled((this.currentPage + 1) * this.pageSize < this.alarms.length);
      }
      .justifyContent(FlexAlign.SpaceBetween)
      .width('100%')
      .padding(16);

      Column() {
        TimePicker()
          .selected({hour: 0, minute: 0})
          .onChange((value: TimePickerResult) => {
            this.newTime = `${value.hour.toString().padStart(2, '0')}:${value.minute.toString().padStart(2, '0')}`;
          })
          .margin({ bottom: 16 });
        TextInput({ placeholder: 'Label', text: this.newLabel })
          .onChange((value: string) => {
            this.newLabel = value;
          })
          .margin({ bottom: 16 });
        Button('Add Alarm')
          .onClick(() => this.addAlarm())
          .enabled(this.newTime && this.newLabel);
      }
      .width('100%')
      .padding(16);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

