import { Tabs, TabContent, List, ListItem, TabsController, FlexAlign, BarPosition, TextDecorationType } from '@ohos.arkui.component';
import { TextInput, Button, Column, Row, Text } from '@ohos.arkui.component';
import preferences from '@ohos.data.preferences';
import common from '@ohos.app.ability.common';

interface Task {
  id: string;
  content: string;
  completed: boolean;
}

@Entry
@Component
struct TodoListApp {
  @State tasks: Task[] = [];
  @State newTask: string = '';
  @State activeTab: number = 0;

  private tabsController: TabsController = new TabsController();
  private context = getContext(this) as common.UIAbilityContext;

  async onPageShow() {
    await this.loadTasks();
  }

  async loadTasks(): Promise<void> {
    if (!this.context) {
      console.error('Context is not available');
      return;
    }
    try {
      const pref = await preferences.getPreferences(this.context, 'todo_preferences');
      const encryptedTasks = await pref.get('tasks', '') as string;
      if (encryptedTasks) {
        const decryptedTasks = this.decrypt(encryptedTasks);
        this.tasks = JSON.parse(decryptedTasks) as Task[];
      }
    } catch (error) {
      console.error('Failed to load tasks:', error.message);
    }
  }

  async saveTasks(): Promise<void> {
    try {
      const pref = await preferences.getPreferences(this.context, 'todo_preferences');
      const encryptedTasks = this.encrypt(JSON.stringify(this.tasks));
      await pref.put('tasks', encryptedTasks);
      await pref.flush();
    } catch (error) {
      console.error('Failed to save tasks:', error.message);
    }
  }

  encrypt(data: string): string {
    return data;
  }

  decrypt(data: string): string {
    return data;
  }

  addTask(): void {
    if (this.newTask.trim()) {
      this.tasks.push({
        id: `task_${Date.now()}`,
        content: this.newTask.trim(),
        completed: false,
      });
      this.newTask = '';
      this.saveTasks();
    }
  }

  toggleTaskCompletion(taskId: string): void {
    const taskIndex = this.tasks.findIndex((task) => task.id === taskId);
    if (taskIndex !== -1) {
      this.tasks[taskIndex].completed = !this.tasks[taskIndex].completed;
      this.saveTasks();
    }
  }

  deleteTask(taskId: string): void {
    this.tasks = this.tasks.filter((task) => task.id !== taskId);
    this.saveTasks();
  }

  getFilteredTasks(): Task[] {
    switch (this.activeTab) {
      case 1:
        return this.tasks.filter((task) => !task.completed);
      case 2:
        return this.tasks.filter((task) => task.completed);
      default:
        return this.tasks;
    }
  }

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.Start, controller: this.tabsController }) {
        TabContent() {
          List({ space: 10 }) {
            ForEach(this.getFilteredTasks(), (task: Task) => {
              ListItem() {
                Row() {
                  Text(task.content)
                    .fontSize(18)
                    .textDecoration(task.completed ? TextDecorationType.LineThrough : TextDecorationType.None);
                  Button(task.completed ? 'Undo' : 'Complete')
                    .onClick(() => this.toggleTaskCompletion(task.id));
                  Button('Delete')
                    .onClick(() => this.deleteTask(task.id));
                }
                .justifyContent(FlexAlign.SpaceBetween)
                .width('100%')
              }
            })
          }
        }.tabBar('All Tasks')

        TabContent() {
          List({ space: 10 }) {
            ForEach(this.getFilteredTasks(), (task: Task) => {
              ListItem() {
                Row() {
                  Text(task.content)
                    .fontSize(18);
                  Button('Complete')
                    .onClick(() => this.toggleTaskCompletion(task.id));
                }
                .justifyContent(FlexAlign.SpaceBetween)
                .width('100%')
              }
            })
          }
        }.tabBar('Active')

        TabContent() {
          List({ space: 10 }) {
            ForEach(this.getFilteredTasks(), (task: Task) => {
              ListItem() {
                Row() {
                  Text(task.content)
                    .fontSize(18)
                    .textDecoration(TextDecorationType.LineThrough);
                  Button('Undo')
                    .onClick(() => this.toggleTaskCompletion(task.id));

import { BusinessError } from '@ohos.base';
import preferences from '@ohos.data.preferences';
import common from '@ohos.app.ability.common';

interface Task {
  id: string;
  name: string;
  completed: boolean;
}

@Entry
@Component
struct TaskManager {
  @State tasks: Array<Task> = [];
  @State newTaskName: string = '';
  private pref: preferences.Preferences | undefined = undefined;

  async aboutToAppear() {
    try {
      this.pref = await preferences.getPreferences(getContext(this), 'taskStorage');
      await this.loadTasks();
    } catch (err) {
      console.error(`Failed to get preferences: ${err}`);
    }
  }

  async loadTasks() {
    try {
      if (this.pref) {
        const storedTasks = await this.pref.get('tasks', '[]') as string;
        this.tasks = JSON.parse(storedTasks) as Array<Task>;
      }
    } catch (err) {
      console.error(`Failed to load tasks: ${err}`);
    }
  }

  async saveTasks() {
    try {
      if (this.pref) {
        await this.pref.put('tasks', JSON.stringify(this.tasks));
        await this.pref.flush();
      }
    } catch (err) {
      console.error(`Failed to save tasks: ${err}`);
    }
  }

  async addTask() {
    if (this.newTaskName.trim()) {
      const newTask: Task = {
        id: Date.now().toString(),
        name: this.newTaskName,
        completed: false
      };
      this.tasks = this.tasks.concat([newTask]);
      this.newTaskName = '';
      await this.saveTasks();
    }
  }

  async toggleTaskCompletion(taskId: string) {
    this.tasks = this.tasks.map(task => 
      task.id === taskId ? {
        id: task.id,
        name: task.name,
        completed: !task.completed
      } : task
    );
    await this.saveTasks();
  }

  async deleteTask(taskId: string) {
    this.tasks = this.tasks.filter(task => task.id !== taskId);
    await this.saveTasks();
  }

  build() {
    Column() {
      Row() {
        TextInput({ placeholder: 'Enter task name' })
          .onChange((value: string) => {
            this.newTaskName = value;
          })
          .width('70%')
          .margin(10);

        Button('Add')
          .onClick(() => this.addTask())
          .width('30%')
          .margin(10);
      }
      .width('100%')
      .padding(10);

      List() {
        ForEach(this.tasks, (task: Task) => {
          ListItem() {
            Row() {
              Text(task.completed ? '✓' : '✗')
                .fontSize(24)
                .margin(10);

              Text(task.name)
                .fontSize(16)
                .decoration({ type: task.completed ? TextDecorationType.LineThrough : TextDecorationType.None })
                .layoutWeight(1);

              Button(task.completed ? 'Undo' : 'Done')
                .onClick(() => this.toggleTaskCompletion(task.id))
                .margin(10);

              Button('Delete')
                .onClick(() => this.deleteTask(task.id))
                .margin(10);
            }
            .width('100%')
            .padding(10);
          }
        });
      }
      .layoutWeight(1)
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(10);
  }
}

