@Entry
@Component
struct Index {
  @State isDialogVisible: boolean = false;
  @State isLocationEnabled: boolean = false;
  @State selectedPrecision: string = 'High';

  build() {
    Column({ space: 20 }) {
      Button('Open Location Settings')
        .width('80%')
        .height(50)
        .backgroundColor('#007BFF')
        .fontColor('#FFFFFF')
        .onClick(() => {
          this.isDialogVisible = true;
        })
        .margin({ top: 20 });

      if (this.isDialogVisible) {
        Column({ space: 10 }) {
          Text('Location Tracking')
            .fontSize(16)
            .margin({ bottom: 10 });

          Row({ space: 10 }) {
            Text('Enable Location')
              .fontSize(14);
            Toggle({ type: ToggleType.Switch, isOn: this.isLocationEnabled })
              .onChange((isOn: boolean) => {
                this.isLocationEnabled = isOn;
              });
          }
          .margin({ bottom: 20 });

          Text('Precision Options')
            .fontSize(16)
            .margin({ bottom: 10 });

          Column({ space: 5 }) {
            Radio({ value: 'High', group: 'precision' })
              .checked(this.selectedPrecision === 'High')
              .onChange((isChecked: boolean) => {
                if (isChecked) {
                  this.selectedPrecision = 'High';
                }
              });
            Text('High')
              .fontSize(14);

            Radio({ value: 'Medium', group: 'precision' })
              .checked(this.selectedPrecision === 'Medium')
              .onChange((isChecked: boolean) => {
                if (isChecked) {
                  this.selectedPrecision = 'Medium';
                }
              });
            Text('Medium')
              .fontSize(14);

            Radio({ value: 'Low', group: 'precision' })
              .checked(this.selectedPrecision === 'Low')
              .onChange((isChecked: boolean) => {
                if (isChecked) {
                  this.selectedPrecision = 'Low';
                }
              });
            Text('Low')
              .fontSize(14);
          }
          .margin({ bottom: 20 });

          Row({ space: 10 }) {
            Button('Save')
              .width('40%')
              .height(40)
              .backgroundColor('#007BFF')
              .fontColor('#FFFFFF')
              .onClick(() => {
                this.isDialogVisible = false;
              });

            Button('Cancel')
              .width('40%')
              .height(40)
              .backgroundColor('#6C757D')
              .fontColor('#FFFFFF')
              .onClick(() => {
                this.isDialogVisible = false;
              });
          }
        }
        .width('90%')
        .padding(20)
        .backgroundColor('#FFFFFF')
        .borderRadius(10)
        .shadow({ radius: 10, color: '#000000', offsetX: 0, offsetY: 0 });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#F5F5F5');
  }
}

@Entry
@Component
struct RideSharingApp {
  @State rideType: string = 'Standard';
  @State isPoolingEnabled: boolean = false;
  @State pickupLocation: string = '';
  @State dropLocation: string = '';
  @State showConfirmation: boolean = false;
  @State errorMessage: string = '';

  private validateInputs(): boolean {
    if (!this.pickupLocation.trim() || !this.dropLocation.trim()) {
      this.errorMessage = 'Please enter both pickup and drop locations';
      return false;
    }
    this.errorMessage = '';
    return true;
  }

  private handleBooking() {
    if (this.validateInputs()) {
      this.showConfirmation = true;
    }
  }

  build() {
    Column({ space: 10 }) {
      // Ride Type Selection
      Text('Select Ride Type')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });
      Row({ space: 20 }) {
        Button('Standard')
          .stateEffect(true)
          .backgroundColor(this.rideType === 'Standard' ? '#007AFF' : '#F5F5F5')
          .onClick(() => this.rideType = 'Standard')
          .width('40%');
        Button('Premium')
          .stateEffect(true)
          .backgroundColor(this.rideType === 'Premium' ? '#007AFF' : '#F5F5F5')
          .onClick(() => this.rideType = 'Premium')
          .width('40%');
      }
      .margin({ bottom: 20 });

      // Ride Pooling Toggle
      Row({ space: 10 }) {
        Text('Enable Ride Pooling')
          .fontSize(16);
        Toggle({ type: ToggleType.Switch, isOn: this.isPoolingEnabled })
          .onChange((isOn: boolean) => this.isPoolingEnabled = isOn);
      }
      .margin({ bottom: 20 });

      // Pickup and Drop Locations
      TextInput({ placeholder: 'Enter pickup location' })
        .onChange((value: string) => this.pickupLocation = value)
        .margin({ bottom: 10 })
        .width('100%');
      TextInput({ placeholder: 'Enter drop location' })
        .onChange((value: string) => this.dropLocation = value)
        .margin({ bottom: 10 })
        .width('100%');

      // Error Message
      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ bottom: 10 });
      }

      // Book Ride Button
      Button('Book Ride')
        .onClick(() => this.handleBooking())
        .width('100%')
        .height(50)
        .margin({ top: 20 });

      // Booking Confirmation
      if (this.showConfirmation) {
        Column({ space: 10 }) {
          Text('Booking Confirmation')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 10 });
          Text(`Ride Type: ${this.rideType}`)
            .fontSize(16);
          Text(`Ride Pooling: ${this.isPoolingEnabled ? 'Enabled' : 'Disabled'}`)
            .fontSize(16);
          Text(`Pickup: ${this.pickupLocation}`)
            .fontSize(16);
          Text(`Drop: ${this.dropLocation}`)
            .fontSize(16);
        }
        .padding(20)
        .backgroundColor('#F5F5F5')
        .borderRadius(10)
        .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center);
  }
}

