@Component
struct CalculatorScreen {
  @State result: string = '0'
  @State currentInput: string = ''
  @State operator: string = ''

  build() {
    Column() {
      Text(this.result)
        .fontSize(40)
        .width('100%')
        .textAlign(TextAlign.End)
        .margin({ bottom: 20 })

      Grid() {
        ForEach(['7', '8', '9', '/', '4', '5', '6', '*', '1', '2', '3', '-', 'C', '0', '=', '+'], (button: string) => {
          GridItem() {
            Button(button)
              .width('100%')
              .height(60)
              .onClick(() => this.handleButtonPress(button))
          }
        })
      }
      .columnsTemplate('1fr 1fr 1fr 1fr')
      .rowsTemplate('1fr 1fr 1fr 1fr')
      .width('100%')
      .height(300)
    }
    .width('100%')
    .padding(20)
  }

  handleButtonPress(button: string) {
    if (button >= '0' && button <= '9') {
      this.currentInput += button
      this.result = this.currentInput
    } else if (button === 'C') {
      this.result = '0'
      this.currentInput = ''
      this.operator = ''
    } else if (button === '=') {
      this.calculateResult()
    } else {
      this.operator = button
      this.result = this.currentInput
      this.currentInput = ''
    }
  }

  calculateResult() {
    const num1 = parseFloat(this.result)
    const num2 = parseFloat(this.currentInput)
    let calculatedResult = 0

    switch (this.operator) {
      case '+':
        calculatedResult = num1 + num2
        break
      case '-':
        calculatedResult = num1 - num2
        break
      case '*':
        calculatedResult = num1 * num2
        break
      case '/':
        calculatedResult = num1 / num2
        break
    }

    this.result = calculatedResult.toString()
    this.currentInput = ''
    this.operator = ''
  }
}

import { Entry, Component, State } from '@ohos.arkui.d';
import { Column, Row, List, ListItem, Button, Text, FlexAlign } from '@ohos.arkui.d';
import { Canvas, CanvasRenderingContext2D } from '@ohos.graphics';

@Entry
@Component
struct PodcastPlayer {
  @State episodes: string[] = ['Episode 1', 'Episode 2', 'Episode 3', 'Episode 4', 'Episode 5'];
  @State currentPage: number = 1;
  @State language: string = 'en';

  build() {
    Column() {
      Row() {
        Button(this.language === 'en' ? 'English' : '中文')
          .onClick(() => {
            this.language = this.language === 'en' ? 'zh' : 'en';
          })
          .margin(10);
      }
      .justifyContent(FlexAlign.End)
      .width('100%');

      Canvas()
        .width('100%')
        .height('200vp')
        .onReady((ctx: CanvasRenderingContext2D) => {
          let x = 0;
          const animate = () => {
            ctx.clearRect(0, 0, ctx.canvas.width, ctx.canvas.height);
            ctx.fillStyle = '#1698CE';
            ctx.fillRect(x, 50, 50, 50);
            x = (x + 2) % ctx.canvas.width;
            setTimeout(animate, 16);
          };
          animate();
        });

      List() {
        ForEach(this.episodes, (episode: string) => {
          ListItem() {
            Text(episode)
              .fontSize(18)
              .margin({ top: 10, bottom: 10 });
          }
        });
      }
      .layoutWeight(1)
      .width('100%');

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentPage > 1) {
              this.currentPage--;
            }
          })
          .margin(10);

        Text(`Page ${this.currentPage}`)
          .fontSize(16)
          .margin(10);

        Button('Next')
          .onClick(() => {
            if (this.currentPage < Math.ceil(this.episodes.length / 3)) {
              this.currentPage++;
            }
          })
          .margin(10);
      }
      .justifyContent(FlexAlign.Center)
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(10);
  }
}

