import promptAction from '@ohos.promptAction';

@Entry
@Component
struct MusicPlayer {
  @State isPlaying: boolean = false;
  @State currentTrackIndex: number = 0;
  @State progress: number = 0;
  @State playbackMode: string = 'Normal';
  @State isLayoutA: boolean = true;

  private tracks: Array<string> = ['Track 1', 'Track 2', 'Track 3'];
  private playbackModes: Array<string> = ['Normal', 'Shuffle', 'Repeat'];

  private togglePlayback(): void {
    this.isPlaying = !this.isPlaying;
    promptAction.showToast({
      message: this.isPlaying ? 'Playback started' : 'Playback paused',
      duration: 2000
    });
  }

  private nextTrack(): void {
    if (this.currentTrackIndex < this.tracks.length - 1) {
      this.currentTrackIndex++;
    }
  }

  private prevTrack(): void {
    if (this.currentTrackIndex > 0) {
      this.currentTrackIndex--;
    }
  }

  private changePlaybackMode(mode: string): void {
    this.playbackMode = mode;
    promptAction.showToast({
      message: `Playback mode: ${mode}`,
      duration: 2000
    });
  }

  private toggleLayout(): void {
    this.isLayoutA = !this.isLayoutA;
  }

  build() {
    Column() {
      Image($r('app.media.music_icon'))
        .width(this.isLayoutA ? 200 : 150)
        .height(this.isLayoutA ? 200 : 150)
        .margin({ top: 20 });

      Text(this.tracks[this.currentTrackIndex])
        .fontSize(this.isLayoutA ? 24 : 20)
        .margin({ top: 10 });

      Slider({
        value: this.progress,
        min: 0,
        max: 100,
        step: 1
      })
        .width(this.isLayoutA ? '80%' : '70%')
        .margin({ top: 20 });

      Row({ space: this.isLayoutA ? 20 : 10 }) {
        Button('Previous')
          .onClick(() => this.prevTrack());
        Button(this.isPlaying ? 'Pause' : 'Play')
          .onClick(() => this.togglePlayback());
        Button('Next')
          .onClick(() => this.nextTrack());
      }
      .margin({ top: 20 });

      Row({ space: 10 }) {
        ForEach(this.playbackModes, (mode: string) => {
          Button(mode)
            .backgroundColor(this.playbackMode === mode ? '#007DFF' : '#F1F3F5')
            .onClick(() => this.changePlaybackMode(mode))
        })
      }
      .margin({ top: 20 });

      Button('Toggle Layout')
        .onClick(() => this.toggleLayout())
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }
}

