import { Column, Text, Image, Button, Row, Progress } from '@ohos.arkui.advanced';
import { FontWeight, FlexAlign } from '@ohos.arkui.advanced';
import http from '@ohos.net.http';
type HttpRequestOptions = http.HttpRequestOptions;

interface MainData {
  temp: number;
}

interface WeatherItem {
  main: string;
  description: string;
}

interface WeatherData {
  main: MainData;
  weather: WeatherItem[];
  name: string;
}

@Entry
@Component
struct WeatherApp {
  @State temperature: string = '';
  @State condition: string = '';
  @State location: string = 'London';
  @State isLoading: boolean = true;
  @State weatherIcon: Resource = $r('app.media.weather_refresh');
  @State isCelsius: boolean = true;
  @State onboardingStep: number = 0;
  @State onboardingProgress: number = 0;

  apiKey: string = 'YOUR_API_KEY';
  apiUrl: string = '';
  httpRequest = http.createHttp();

  aboutToAppear() {
    this.updateApiUrl();
  }

  updateApiUrl() {
    this.apiUrl = `https://api.openweathermap.org/data/2.5/weather?q=${this.location}&appid=${this.apiKey}&units=metric`;
  }

  async fetchWeatherData(): Promise<void> {
    this.isLoading = true;
    let requestOptions: HttpRequestOptions = {
      method: http.RequestMethod.GET
    };
    try {
      const response = await this.httpRequest.request(this.apiUrl, requestOptions) as http.HttpResponse;
      if (response.responseCode === 200) {
        const data: WeatherData = JSON.parse(response.result as string);
        this.temperature = `${Math.round(data.main.temp)}${this.isCelsius ? 'C' : 'F'}`;
        this.condition = data.weather[0].main;
        this.location = data.name;
        this.updateWeatherIcon(data.weather[0].main);
      }
      this.isLoading = false;
    } catch {
      this.isLoading = false;
    }
  }

  updateWeatherIcon(condition: string): void {
    switch (condition.toLowerCase()) {
      case 'sunny':
        this.weatherIcon = $r('app.media.weather_sunny');
        break;
      case 'rainy':
        this.weatherIcon = $r('app.media.weather_rain');
        break;
      default:
        this.weatherIcon = $r('app.media.weather_refresh');
    }
  }

  toggleTemperatureUnit(): void {
    this.isCelsius = !this.isCelsius;
    if (!this.isLoading) {
      this.fetchWeatherData();
    }
  }

  nextOnboardingStep(): void {
    if (this.onboardingStep < 2) {
      this.onboardingStep++;
      this.onboardingProgress = (this.onboardingStep / 2) * 100;
    } else {
      this.onboardingStep = 0;
      this.onboardingProgress = 0;
    }
  }

  build() {
    Column() {
      if (this.onboardingStep < 2) {
        Text(`Onboarding Step ${this.onboardingStep + 1}`)
          .fontSize(24)
          .margin(20);
        Progress({ value: this.onboardingProgress, total: 100 })
          .width('80%')
          .height(10)
          .margin(20);
        Button('Next')
          .onClick(() => this.nextOnboardingStep())
          .margin(20);
      } else {
        if (this.isLoading) {
          Text('Loading weather data...')
            .fontSize(20)
            .margin(20);
        } else {
          Text(this.location)
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Image(this.weatherIcon)
            .width(100)
            .height(100)
            .margin({ bottom: 20 });

          Row() {
            Text(this.temperature)
              .fontSize(32)
              .fontWeight(FontWeight.Bold)
              .margin({ bottom: 10 });
            Button(this.isCelsius ? 'Switch to F' : 'Switch to C')
              .onClick(() => this.toggleTemperatureUnit())
              .margin({ left: 10 });
          }

          Text(this.condition)
            .fontSize(20)
            .margin({ bottom: 20 });

          Button('Refresh')
            .onClick(() => this.fetchWeatherData())
            .margin(20);
        }
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

import { Column, Row, Text, Button, Image, Progress } from '@ohos.arkui';
import { FontWeight, FlexAlign } from '@ohos.arkui';

@Entry
@Component
struct FitnessTracker {
  @State workoutPhases: string[] = ['Warm-Up', 'Cardio', 'Strength Training', 'Cooldown'];
  @State currentPhaseIndex: number = 0;
  @State progress: number = 0;
  @State isRecording: boolean = false;

  private timerId: number | null = null;

  startWorkout() {
    this.isRecording = true;
    this.timerId = setInterval(() => {
      this.progress += 1;
      if (this.progress >= 100) {
        this.progress = 0;
        this.currentPhaseIndex = (this.currentPhaseIndex + 1) % this.workoutPhases.length;
      }
    }, 1000);
  }

  stopWorkout() {
    this.isRecording = false;
    if (this.timerId) {
      clearInterval(this.timerId);
      this.timerId = null;
    }
  }

  aboutToDisappear() {
    if (this.timerId) {
      clearInterval(this.timerId);
    }
  }

  build() {
    Column() {
      Text('Fitness Tracker')
        .fontSize(24)
        .fontWeight(FontWeight.Bolder)
        .margin({ bottom: 20 });

      Image($r('app.media.fitness_placeholder'))
        .width(200)
        .height(200)
        .margin({ bottom: 20 });

      Progress({ value: this.progress })
        .width('80%')
        .height(10)
        .margin({ bottom: 20 });

      Row() {
        ForEach(this.workoutPhases, (phase: string, index: number) => {
          Column() {
            Text(phase)
              .fontSize(16)
              .fontWeight(this.currentPhaseIndex === index ? FontWeight.Bolder : FontWeight.Normal)
              .textColor(this.currentPhaseIndex === index ? '#FF0000' : '#000000');
          }
          .margin({ right: 10 });
        });
      }
      .margin({ bottom: 20 });

      Button(this.isRecording ? 'Stop Workout' : 'Start Workout')
        .onClick(() => {
          if (this.isRecording) {
            this.stopWorkout();
          } else {
            this.startWorkout();
          }
        })
        .width('50%')
        .height(40);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }
}

