@Component
struct CustomCheckbox {
  @Link isChecked: boolean;
  @State private scaleValue: number = 1.0;
  @State private opacityValue: number = 1.0;
  onCheckChange?: (value: boolean) => void;

  build() {
    Column() {
      Checkbox({ name: 'termsCheckbox', group: 'checkboxGroup' })
        .select(this.isChecked)
        .selectedColor(0x39a2db)
        .mark({
          strokeColor: 0xFFFFFF,
          size: 20,
          strokeWidth: 2
        })
        .onChange((value: boolean) => {
          this.isChecked = value;
          this.onCheckChange?.(value);
          animateTo({
            duration: 300,
            curve: Curve.EaseInOut
          }, () => {
            this.scaleValue = value ? 1.1 : 1.0;
            this.opacityValue = value ? 0.8 : 1.0;
          });
        })
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .opacity(this.opacityValue);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

import { Column, Row, Text, List, ListItem, ForEach, Button, Checkbox } from '@ohos.arkui.component';
