  screenY: number;
}

@Entry
@Component
struct InventoryManagerApp {
  @State userPreferences: UserPreferences = {
    theme: 'light',
    notifications: true
  };

  @State inventoryCategories: InventoryCategory[] = [
    { name: 'Electronics', items: ['Laptop', 'Smartphone', 'Tablet'], expanded: false },
    { name: 'Clothing', items: ['Shirt', 'Pants', 'Shoes'], expanded: false },
    { name: 'Groceries', items: ['Milk', 'Bread', 'Eggs'], expanded: false }
  ];

  @State swipedItemIndex: number = -1;

  updateTheme(theme: string): void {
    this.userPreferences.theme = theme;
  }

  toggleNotifications(): void {
    this.userPreferences.notifications = !this.userPreferences.notifications;
  }

  toggleCategoryExpansion(index: number): void {
    this.inventoryCategories[index].expanded = !this.inventoryCategories[index].expanded;
  }

