        Row() {
          Text('Notifications:')
            .fontSize(16)
            .margin({ right: 10 });

          Checkbox({ checked: this.userPreferences.notifications })
            .onChange(() => this.toggleNotifications());
        }
      }
      .padding(20)
      .backgroundColor('#f0f0f0')
      .borderRadius(10)
      .margin({ bottom: 20 });

      List() {
        ForEach(this.inventoryCategories, (category: InventoryCategory, index: number) => {
          ListItem() {
            Column() {
              Row() {
                Text(category.name)
                  .fontSize(18)
                  .fontWeight(FontWeight.Medium);

                Button(category.expanded ? '-' : '+')
                  .onClick(() => this.toggleCategoryExpansion(index));
              }
              .justifyContent(FlexAlign.SpaceBetween)
              .width('100%')
              .padding(10);

              if (category.expanded) {
                ForEach(category.items, (item: string, itemIndex: number) => {
                  Row() {
                    Text(item)
                      .fontSize(16)
                      .margin({ left: 20 });
                  }
                  .onTouch((event: TouchEvent) => {
                    if (event.type === TouchType.Move && event.touches.length > 0) {
                      const touch = event.touches[0];
                      this.handleSwipe(itemIndex, touch.screenX);
                    }
                  })
                  .backgroundColor(this.swipedItemIndex === itemIndex ? '#d3d3d3' : '#ffffff')
                  .borderRadius(5)
                  .margin({ bottom: 5 });
                });
              }
            }
          }
        });
      }
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(this.userPreferences.theme === 'light' ? '#ffffff' : '#333333');
  }
}

import window from '@ohos.window';
import common from '@ohos.app.ability.common';

interface InventoryItem {
  id: string;
  name: string;
  quantity: number;
}

@Entry
@Component
struct InventoryManager {
  @State inventoryItems: Array<InventoryItem> = [
    { id: '1', name: 'inv_sword', quantity: 5 },
    { id: '2', name: 'inv_shield', quantity: 3 },
    { id: '3', name: 'inv_potion', quantity: 10 }
  ];
  @State errorMessage: string = '';
  @State selectedItem: string = '';

  aboutToAppear() {
    try {
      let context = getContext(this) as common.UIAbilityContext;
      let windowClass = window.getLastWindow(context);
      windowClass.then((win: window.Window) => {
        win.setPreferredOrientation(window.Orientation.LANDSCAPE);
      }).catch((error: Error) => {
        console.error('Failed to set orientation:', error);
        this.errorMessage = 'Failed to set landscape mode';
      });
    } catch (error) {
      console.error('Window initialization error:', error);
    }
  }

  build() {
    Column() {
      Image($r('app.media.icon'))
        .width(100)
        .height(100)
        .borderRadius(50)
        .margin({ bottom: 20 })

      List({ space: 10 }) {
        ForEach(this.inventoryItems, (item: InventoryItem) => {
          ListItem() {
            Row() {
              Text(item.name)
                .fontSize(16)
                .margin({ right: 10 })
              Text(`Quantity: ${item.quantity}`)
                .fontSize(14)
                .fontColor(Color.Gray)
            }
            .width('100%')
            .justifyContent(FlexAlign.SpaceBetween)
            .padding(10)
            .borderRadius(5)
            .backgroundColor('#F5F5F5')
          }
          .gesture(
            LongPressGesture()
              .onAction(() => {
                this.selectedItem = item.id;
                console.log(`Long press on item: ${item.name}`);
              })
          )
        })
      }
      .layoutWeight(1)
      .width('100%')
      .height('60%')

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 10 })
      }

      Row() {
        Button('Add Item')
          .width('40%')
          .height(40)
          .onClick(() => {
            try {
              const newItem: InventoryItem = { id: `${this.inventoryItems.length + 1}`, name: `inv_item_${this.inventoryItems.length + 1}`, quantity: 1 };
              this.inventoryItems = [...this.inventoryItems, newItem];
            } catch (error) {
              this.errorMessage = 'Failed to add item';
            }
          })
          .margin({ right: 10 })

        Button('Remove Item')
          .width('40%')
          .height(40)
          .onClick(() => {
            try {
              if (this.selectedItem) {
                this.inventoryItems = this.inventoryItems.filter(item => item.id !== this.selectedItem);
                this.selectedItem = '';
              } else {
                this.errorMessage = 'No item selected';
              }
            } catch (error) {
              this.errorMessage = 'Failed to remove item';
            }
          })
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
  }
}

