import { Column, Row, Text, Image, Button, List, ListItem, ForEach, Drawer, DrawerType, FlexAlign, Rating, State } from '@ohos.arkui.component';
import { PanGesture, PanGestureEvent } from '@ohos.arkui.advancedUI.Gesture';
import { animateTo } from '@ohos.arkui.advancedUI.Animation';

@Entry
@Component
struct ScannerApp {
  @State isDrawerOpen: boolean = false;
  @State currentPage: number = 1;
  @State scannerActive: boolean = false;
  @State ratingValue: number = 0;
  @State swipeOffset: number = 0;

  private handleSwipe(event: PanGestureEvent) {
    if (Math.abs(event.offsetX) >= 50) {
      this.scannerActive = !this.scannerActive;
      animateTo({ duration: 300 }, () => {
        this.swipeOffset = 0;
      });
    }
  }

  private navigateToPage(page: number) {
    animateTo({ duration: 300 }, () => {
      this.currentPage = page;
    });
  }

  private toggleDrawer() {
    this.isDrawerOpen = !this.isDrawerOpen;
  }

  private handleRatingChange(value: number) {
    this.ratingValue = value;
  }

  build() {
    Column() {
      Drawer({ type: DrawerType.Temporary, isOpen: this.isDrawerOpen })
        .onChange((isOpen: boolean) => {
          this.isDrawerOpen = isOpen;
        }) {
        Column() {
          List() {
            ForEach(['Home', 'Profile', 'Settings'], (item: string) => {
              ListItem() {
                Text(item)
                  .fontSize(20)
                  .margin({ left: 20 });
              }
              .onClick(() => {
                this.toggleDrawer();
              });
            });
          }
          .width('100%');
        }
        .width('80%')
        .height('100%');
      }

      Column() {
        Row()
          .width('100%')
          .height(200)
          .gesture(
            PanGesture({ direction: PanGesture.Direction.Horizontal })
              .onActionUpdate((event: PanGestureEvent) => {
                this.handleSwipe(event);
              })
          ) {
          Image(this.scannerActive ? $r('app.media.scanner_icon') : $r('app.media.scanner_icon'))
            .width(100)
            .height(100);
        }

        Row() {
          ForEach([1, 2, 3], (page: number) => {
            Button(`Page ${page}`)
              .onClick(() => {
                this.navigateToPage(page);
              });
          });
        }
        .width('100%')
        .justifyContent(FlexAlign.SpaceAround);

        Column() {
          Text(`Page ${this.currentPage} Content`)
            .fontSize(24);
        }
        .width('100%')
        .margin({ top: 20 });

        Row() {
          Rating({ rating: this.ratingValue, indicator: false })
            .stars(5)
            .stepSize(1)
            .onChange((value: number) => {
              this.handleRatingChange(Math.round(value));
            });
        }
        .width('100%')
        .justifyContent(FlexAlign.Center)
        .margin({ top: 20 });

        Button('Toggle Drawer')
          .onClick(() => {
            this.toggleDrawer();
          })
          .margin({ top: 20 });
      }
      .width('100%')
      .height('100%')
      .padding(20);
    }
    .width('100%')
    .height('100%');
  }
}

