import { Button, Text, Column, Row, Stepper, StepperItem } from '@ohos.arkui.component';
import { FontWeight, Color, FlexAlign, HorizontalAlign } from '@ohos.arkui.drawing';
import accessibility from '@ohos.accessibility';

@Entry
@Component
struct QuizApp {
  @State private currentQuestionIndex: number = 0;
  private totalQuestions: number = 5;
  private questions: string[] = [
    "What is the capital of France?",
    "Which planet is known as the Red Planet?",
    "What is the largest mammal?",
    "Who wrote 'Romeo and Juliet'?",
    "What is the chemical symbol for gold?"
  ];
  private answers: string[] = [
    "Paris",
    "Mars",
    "Blue Whale",
    "William Shakespeare",
    "Au"
  ];

  @Builder
  QuestionContent(questionIndex: number) {
    Column() {
      Text(`Question ${questionIndex + 1}/${this.totalQuestions}`)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })
        .accessibilityLabel(`Question ${questionIndex + 1} of ${this.totalQuestions}`);

      Text(this.questions[questionIndex])
        .fontSize(18)
        .fontColor(Color.Black)
        .margin({ bottom: 20 })
        .accessibilityLabel(`Question: ${this.questions[questionIndex]}`);

      Text(`Answer: ${this.answers[questionIndex]}`)
        .fontSize(16)
        .fontColor(Color.Gray)
        .margin({ bottom: 20 })
        .accessibilityLabel(`Answer: ${this.answers[questionIndex]}`);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }

  build() {
    Column() {
      Stepper({ index: this.currentQuestionIndex }) {
        ForEach(this.questions, (question: string, index: number) => {
          StepperItem() {
            this.QuestionContent(index);
          }
        })
      }

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentQuestionIndex > 0) {
              this.currentQuestionIndex--;
            }
          })
          .margin({ right: 20 })
          .enabled(this.currentQuestionIndex > 0)
          .accessibilityRole('button')
          .accessibilityLabel('Previous question');

        Button('Next')
          .onClick(() => {
            if (this.currentQuestionIndex < this.totalQuestions - 1) {
              this.currentQuestionIndex++;
            }
          })
          .enabled(this.currentQuestionIndex < this.totalQuestions - 1)
          .accessibilityRole('button')
          .accessibilityLabel('Next question');
      }
      .margin({ top: 50 });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

import { List, ListItem, Text, Button, Column, Row, Image, Switch, SwitchType } from 'arkui';
import { State } from 'arkui';
import { FlexAlign, FontWeight, TextAlign } from 'arkui';

interface Event {
  id: number;
  title: string;
  description: string;
  isActive: boolean;
}

@Entry
@Component
struct EventPlanner {
  @State events: Array<Event> = [
    { id: 1, title: "Team Meeting", description: "Discuss project updates", isActive: true },
    { id: 2, title: "Lunch Break", description: "Enjoy a meal", isActive: false },
    { id: 3, title: "Client Call", description: "Review requirements", isActive: true }
  ];

  @State isScanning: boolean = false;

  build() {
    Column() {
      Text("Event Planner")
        .fontSize(24)
        .fontWeight(FontWeight.Medium)
        .margin({ top: 20, bottom: 20 })
        .textAlign(TextAlign.Center);

      List({ space: 10 }) {
        ForEach(this.events, (event: Event) => {
          ListItem() {
            Row() {
              Image($r('app.media.icon'))
                .width(50)
                .height(50)
                .margin({ right: 10 });

              Column() {
                Text(event.title)
                  .fontSize(18)
                  .fontWeight(FontWeight.Medium);

                Text(event.description)
                  .fontSize(14)
                  .opacity(0.7);
              }

              Switch({ type: SwitchType.Toggle })
                .isOn(event.isActive)
                .onChange((isChecked: boolean) => {
                  const index = this.events.findIndex(e => e.id === event.id);
                  if (index >= 0) {
                    this.events[index].isActive = isChecked;
                  }
                });
            }
            .padding(10)
            .backgroundColor("#f5f5f5")
            .borderRadius(8);
          }
        }, (event: Event) => event.id.toString())
      }
      .width("100%")
      .height("70%");

      Button(this.isScanning ? "Scanning..." : "Scan Events")
        .onClick(() => {
          this.isScanning = true;
          setTimeout(() => {
            this.isScanning = false;
          }, 2000);
        })
        .width("80%")
        .height(50)
        .margin({ top: 20 });
    }
    .width("100%")
    .height("100%")
    .padding(20)
    .justifyContent(FlexAlign.Center);
  }
}

