@Entry
@Component
struct FilePickerStepper {
  @State currentStep: number = 0;
  @State selectedItems: string[] = [];
  steps: string[] = ['Step 1', 'Step 2', 'Step 3', 'Step 4'];
  items: string[][] = [
    ['File 1', 'File 2', 'File 3'],
    ['Folder 1', 'Folder 2', 'Folder 3'],
    ['Image 1', 'Image 2', 'Image 3'],
    ['Document 1', 'Document 2', 'Document 3']
  ];

  build() {
    Column() {
      Text('File Picker')
        .fontSize(24)
        .margin({ bottom: 20 });

      Row() {
        ForEach(this.steps, (step: string, index: number) => {
          Column() {
            Circle()
              .width(30)
              .height(30)
              .backgroundColor(this.currentStep === index ? '#007DFF' : '#CCCCCC')
              .margin({ bottom: 5 })
              .gesture(
                TapGesture()
                  .onAction(() => {
                    this.currentStep = index;
                  })
              );
            Text(step)
              .fontSize(12);
          }
          .margin({ right: 20 });
        });
      }
      .margin({ bottom: 20 });

      Divider();

      ForEach(this.items[this.currentStep], (item: string) => {
        Row() {
          Text(item)
            .fontSize(16)
            .margin({ left: 10 });
        }
        .width('100%')
        .height(50)
        .backgroundColor(this.selectedItems.includes(item) ? '#E6F7FF' : '#FFFFFF')
        .borderRadius(5)
        .margin({ bottom: 5 })
        .gesture(
          TapGesture()
            .onAction(() => {
              if (this.selectedItems.includes(item)) {
                this.selectedItems = this.selectedItems.filter(i => i !== item);
              } else {
                this.selectedItems.push(item);
              }
            })
        );
      });

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentStep > 0) {
              this.currentStep--;
            }
          })
          .enabled(this.currentStep > 0)
          .margin({ right: 10 });

        Button('Next')
          .onClick(() => {
            if (this.currentStep < this.steps.length - 1) {
              this.currentStep++;
            }
          })
          .enabled(this.currentStep < this.steps.length - 1);
      }
      .margin({ top: 20 });
    }
    .padding(20)
    .width('100%')
    .height('100%');
  }
}

