import { FlexAlign } from '@ohos.arkui.component.Flex';
import { Column, Text, Button } from '@ohos.arkui.component';

@Entry
@Component
struct QuizApp {
  @State currentQuestionIndex: number = 0
  @State score: number = 0
  @State showScore: boolean = false

  questions: Question[] = [
    {
      question: "What is the capital of France?",
      options: ["London", "Berlin", "Paris", "Madrid"],
      correctAnswer: 2
    }
  ]

  build() {
    Column() {
      if (!this.showScore) {
        Text(`Question ${this.currentQuestionIndex + 1}/${this.questions.length}`)
          .fontSize(20)
          .margin({ bottom: 20 })

        Text(this.questions[this.currentQuestionIndex].question)
          .fontSize(18)
          .margin({ bottom: 30 })

        Column() {
          ForEach(this.questions[this.currentQuestionIndex].options, (item: string, index: number) => {
            Button(item)
              .width('80%')
              .margin({ bottom: 10 })
              .onClick(() => {
                if (index === this.questions[this.currentQuestionIndex].correctAnswer) {
                  this.score++
                }
                if (this.currentQuestionIndex < this.questions.length - 1) {
                  this.currentQuestionIndex++
                } else {
                  this.showScore = true
                }
              })
          })
        }
      } else {
        Text(`Your Score: ${this.score}/${this.questions.length}`)
          .fontSize(24)
          .margin({ bottom: 30 })

        Button('Restart Quiz')
          .width('60%')
          .height(50)
          .onClick(() => {
            this.currentQuestionIndex = 0
            this.score = 0
            this.showScore = false
          })
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(FlexAlign.Center)
  }
}

interface Question {
  question: string
  options: string[]
  correctAnswer: number
}

import { Checkbox, Marquee, Video } from '@ohos.arkui.advanced';
