      Marquee({
        text: this.isDarkTheme ? 'Dark Theme' : 'Light Theme',
        fontSize: 20,
        fontColor: this.isDarkTheme ? Color.White : Color.Black,
        loop: true
      })
      .width('100%')
      .margin({ top: 20 });

      Checkbox({
        name: 'themeToggle',
        isOn: this.isDarkTheme,
        onChange: (isOn: boolean) => {
          this.isDarkTheme = isOn;
        }
      })
      .gesture(
        PanGesture()
          .onActionStart(() => {
            this.isDarkTheme = !this.isDarkTheme;
          })
      )
      .width(100)
      .height(100)
      .margin({ top: 20 });

      Video({
        src: $rawfile('video_placeholder.png'),
        width: 300,
        height: 200
      })
      .margin({ top: 20 });

      Text('Swipe or tap the checkbox to toggle theme')
        .fontSize(16)
        .fontColor(this.isDarkTheme ? Color.White : Color.Black)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.isDarkTheme ? Color.Black : Color.White)
