import { Column, Row, Text, Button, ForEach, Tabs, TabContent, Counter, Tag, Progress, FontWeight, FlexAlign } from '@ohos.arkui';

interface Workout {
  name: string;
  reps: number;
  rating: number;
  tags: string[];
}

@Entry
@Component
struct WorkoutPlanner {
  @State workouts: Workout[] = [
    { name: 'Push-ups', reps: 10, rating: 4, tags: ['Strength', 'Upper Body'] },
    { name: 'Squats', reps: 15, rating: 5, tags: ['Strength', 'Lower Body'] },
    { name: 'Plank', reps: 1, rating: 3, tags: ['Core', 'Stability'] }
  ];

  @State selectedTab: number = 0;

  @Builder
  RatingComponent(rating: number, onChange: (value: number) => void) {
    Row() {
      ForEach([1, 2, 3, 4, 5], (i: number) => {
        Text(i <= rating ? '\\u2605' : '\\u2606')
          .fontSize(24)
          .fontColor(i <= rating ? '#FFD700' : '#CCCCCC')
          .onClick(() => {
            onChange(i);
          });
      });
    }.margin({ left: 8 })
