  build() {
    Column() {
      Tabs({ index: this.selectedTab }) {
        ForEach(this.workouts, (workout: Workout, index: number) => {
          TabContent() {
            Column() {
              Text(workout.name)
                .fontSize(24)
                .fontWeight(FontWeight.Bold)
                .margin({ bottom: 16 });

              Row() {
                Text('Reps:')
                  .fontSize(18);
                Counter({
                  value: workout.reps,
                  min: 1,
                  max: 50,
                  onChange: (value: number) => {
                    this.workouts[index].reps = value;
                  }
                })
                  .margin({ left: 8 });
              }
              .margin({ bottom: 16 });

              Row() {
                Text('Rating:')
                  .fontSize(18);
                this.RatingComponent(workout.rating, (value: number) => {
                  this.workouts[index].rating = value;
                })
              }
              .margin({ bottom: 16 });

              Row() {
                ForEach(workout.tags, (tag: string) => {
                  Row() {
                    Tag() {
                      Text(tag)
                    }
