              }
              .margin({ bottom: 16 });

              Progress({
                value: workout.reps / 50 * 100
              })
                .width('80%')
                .height(8)
                .margin({ bottom: 16 });

              Button('Start Workout')
                .width('80%')
                .height(40)
                .onClick(() => {
                  // Handle workout start
                });
            }
            .width('100%')
            .height('100%')
            .padding(16)
            .justifyContent(FlexAlign.Center);
          }
        });
      }
      .width('100%')
      .height('100%')
      .barWidth(0)
      .onChange((index: number) => {
        this.selectedTab = index;
      });
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5');
  }
}

@Entry
@Component
struct MusicPlayer {
  @State isPlaying: boolean = false
  @State currentSong: string = 'Awesome Song'
  @State currentArtist: string = 'Cool Artist'
  @State progress: number = 0
  @State searchQuery: string = ''
  @State showLayoutA: boolean = Math.random() < 0.5

  private songs: Array<Song> = [
    { title: 'Song 1', artist: 'Artist 1' },
    { title: 'Song 2', artist: 'Artist 2' },
    { title: 'Song 3', artist: 'Artist 3' }
  ]

  private filteredSongs(): Array<Song> {
    if (!this.searchQuery) return this.songs
    const query = this.searchQuery.toLowerCase()
    return this.songs.filter(
      song =>
        song.title.toLowerCase().includes(query) ||
        song.artist.toLowerCase().includes(query)
    )
  }

  build() {
    Column() {
      if (this.showLayoutA) {
        TextInput({ placeholder: 'Search songs or artists' })
          .width('80%')
          .height(40)
