        List({ space: 10 }) {
          ForEach(this.filteredSongs(), (song: Song) => {
            ListItem() {
              Column() {
                Text(song.title)
                  .fontSize(18)
                  .fontWeight(FontWeight.Bold)
                Text(song.artist)
                  .fontSize(14)
              }
              .width('100%')
              .padding(10)
