        Image($r('sys.media.ohos_app_icon'))
          .width(300)
          .height(300)
          .borderRadius(10)
          .margin({ top: 20 })

        Text(this.currentSong)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })

        Text(this.currentArtist)
          .fontSize(18)
          .margin({ top: 5 })

        Slider({
          value: this.progress,
          min: 0,
          max: 100,
          step: 1
        })
          .width('80%')
          .margin({ top: 20 })

        Row({ space: 20 }) {
          Button('Previous')
            .width(100)
            .height(40)
            .onClick(() => {
              console.info('Previous song')
            })

          Button(this.isPlaying ? 'Pause' : 'Play')
            .width(100)
            .height(40)
            .onClick(() => {
              this.isPlaying = !this.isPlaying
            })

          Button('Next')
            .width(100)
            .height(40)
            .onClick(() => {
              console.info('Next song')
            })
        }
        .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
