import promptAction from '@ohos.promptAction';
import { Gesture, GestureEvent } from '@ohos.arkui.UIContext';
import deviceManager from '@ohos.distributedHardware.deviceManager';
import { BusinessError } from '@ohos.base';

@Entry
@Component
struct SocialSharingComponent {
  @State private swipeDirection: string = '';
  private mockData: number[] = [30, 50, 20, 80, 40];
  private labels: string[] = ['Facebook', 'Twitter', 'WhatsApp', 'Instagram', 'LinkedIn'];
  private dmInstance: deviceManager.DeviceManager | null = null;

  aboutToAppear() {
    deviceManager.createDeviceManager('com.example.socialshare', (err: BusinessError, manager: deviceManager.DeviceManager) => {
      if (err) {
        console.error('Failed to create device manager');
      } else {
        this.dmInstance = manager;
      }
    });
  }

  build() {
    Column() {
      Button('Share')
        .onClick(() => {
          promptAction.showActionMenu({
            title: 'Share via',
            buttons: [
              { text: 'Facebook', color: '#1877F2' },
              { text: 'Twitter', color: '#1DA1F2' },
              { text: 'WhatsApp', color: '#25D366' },
              { text: 'Instagram', color: '#E4405F' },
              { text: 'Cancel', color: '#FF3B30' }
            ]
          }).then((result: promptAction.ShowActionResult) => {
            console.log(`Selected: ${result.index}`);
          });
        });

      Text(`Swipe Direction: ${this.swipeDirection}`)
        .margin({ top: 20 });

      Row() {
        ForEach(this.mockData, (value: number, index: number) => {
          Column() {
            Text(this.labels[index])
              .fontSize(12)
              .margin({ bottom: 5 });
            Column()
              .width(30)
              .height(value)
              .backgroundColor('#007AFF')
              .margin({ right: 10 });
          }
        });
      }
      .margin({ top: 20 })
      .gesture(
        Gesture()
          .onSwipe((event: GestureEvent) => {
            if (Math.abs(event.offsetX) > 50 || Math.abs(event.offsetY) > 50) {
              this.swipeDirection = event.offsetX > 0 ? 'Right' : event.offsetX < 0 ? 'Left' : event.offsetY > 0 ? 'Down' : 'Up';
              console.log(`Swipe Direction: ${this.swipeDirection}`);
            }
          })
      );

      Button('Discover Devices')
        .onClick(() => {
          this.dmInstance?.getTrustedDeviceListSync().then((devices) => {
            console.log(`Discovered devices: ${JSON.stringify(devices)}`);
          }).catch((err: BusinessError) => {
            console.error(`Device discovery failed: ${err.code}`);
          });
        })
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

