@Entry
@Component
struct ImageFilterApp {
  @State images: string[] = ['sample1', 'sample2', 'sample3'];
  @State filteredImage: string = '';
  @State statusMessage: string = 'Swipe to filter';
  @State showWeb: boolean = false;

  build() {
    Column() {
      Text(this.statusMessage)
        .fontSize(16)
        .margin({ top: 10, bottom: 10 });

      List({ space: 10 }) {
        ForEach(this.images, (image: string) => {
          ListItem() {
            Row() {
              Image($r('app.media.' + image))
                .width(100)
