import { CanvasRenderingContext2D } from '@ohos.graphics.canvas';
import { Swiper, Scroll } from '@ohos.arkui.advanced.UI';
import { TextInput, Button } from '@ohos.arkui.component';
import { PinchGesture } from '@ohos.multimodalinput.gesture';
import { TouchEvent } from '@ohos.multimodalinput.touch';

interface PinchEvent {
  scale: number;
  centerX: number;
  centerY: number;
}

@Entry
@Component
struct DrawingMessagingApp {
  @State brushSize: number = 2;
  @State brushColor: string = '#000000';
  @State messages: string[] = [];
  @State currentMessage: string = '';
  @State canvasContext: CanvasRenderingContext2D | null = null;

  private handleCanvasReady(context: CanvasRenderingContext2D): void {
    if (context) {
      this.canvasContext = context;
      this.canvasContext.lineWidth = this.brushSize;
      this.canvasContext.strokeStyle = this.brushColor;
      this.canvasContext.beginPath();
    }
  }

  private handleCanvasTouch(event: TouchEvent): void {
    if (!this.canvasContext || !event.touches.length) return;
    const touch = event.touches[0];
    this.canvasContext.lineTo(touch.globalX, touch.globalY);
    this.canvasContext.stroke();
  }

  private handleBrushChange(size: number, color: string): void {
    this.brushSize = size;
    this.brushColor = color;
    if (this.canvasContext) {
      this.canvasContext.lineWidth = size;
      this.canvasContext.strokeStyle = color;
    }
  }

  private handleSendMessage(): void {
    if (this.currentMessage.trim() === '') return;
    this.messages = [...this.messages, this.currentMessage];
    this.currentMessage = '';
  }

  build() {
    Column() {
      Canvas({ width: '100%', height: '60%' })
        .onReady(() => {
          this.handleCanvasReady(this.canvasContext);
        })
        .onTouch((event: TouchEvent) => this.handleCanvasTouch(event))
        .gesture(
          PinchGesture({ fingers: 2 })
            .onAction((event: PinchEvent) => {
              if (this.canvasContext) {
                this.canvasContext.scale(event.scale, event.scale);
              }
            })
        )

      Swiper({ loop: false, index: 0 })
        .height(80)
        .onChange((index: number) => {
          const sizes: number[] = [2, 4, 6, 8];
          const colors: string[] = ['#000000', '#FF0000', '#00FF00', '#0000FF'];
          this.handleBrushChange(sizes[index], colors[index]);
        }) {
        ForEach([2, 4, 6, 8], (size: number) => {
          Column() {
            Circle()
              .width(size * 2)
              .height(size * 2)
              .fill('#000000')
          }
          .margin(10)
        })
      }

      Column() {
        Scroll() {
          Column() {
            ForEach(this.messages, (message: string) => {
              Text(message)
                .fontSize(16)
                .margin(5)
            })
          }
        }
        .flexGrow(1)

        Row() {
          TextInput({ placeholder: 'Type a message...', text: this.currentMessage })
            .onChange((value: string) => {
              this.currentMessage = value;
            })
            .flexGrow(1)

          Button('Send')
            .onClick(() => {
              this.handleSendMessage();
            })
        }
        .padding(10)
      }
      .flexGrow(1)
    }
    .width('100%')
    .height('100%')
    .padding(10)
  }
}

import { Column, Row, Text, Image, FlexAlign, HorizontalAlign } from '@ohos.arkui.uicomponent';
import { Tabs, TabContent } from '@ohos.arkui.uicomponent';
import audio from '@ohos.multimedia.audio';

interface OnboardingStep {
  title: string;
  image: Resource;
  audio: Resource;
}

@Entry
@Component
struct OnboardingScreen {
  @State currentStep: number = 0;
  private audioPlayer: audio.AVPlayer | null = null;
  private onboardingSteps: OnboardingStep[] = [
    {
      title: 'Welcome',
      image: $r('app.media.icon'),
      audio: $r('app.media.sound')
    },
    {
      title: 'Features',
      image: $r('app.media.icon'),
      audio: $r('app.media.sound')
    },
    {
      title: 'Get Started',
      image: $r('app.media.icon'),
      audio: $r('app.media.sound')
    }
  ];

  aboutToDisappear() {
    if (this.audioPlayer !== null) {
      this.audioPlayer.release();
      this.audioPlayer = null;
    }
  }

  private async playAudio(audioResource: Resource) {
    try {
      if (this.audioPlayer !== null) {
        await this.audioPlayer.stop();
        this.audioPlayer.release();
      }
      this.audioPlayer = new audio.AVPlayer();
      if (this.audioPlayer !== null) {
        await this.audioPlayer.init({
          source: {
            fdSrc: audioResource,
            fdStart: 0,
            fdLength: 0
          },
          audioInterruptMode: audio.InterruptMode.SHARE_MODE
        });
        await this.audioPlayer.play();
      }
    } catch (error) {
      console.error('Audio playback error:', error);
    }
  }

  build() {
    Column() {
      Tabs({ index: this.currentStep }) {
        ForEach(this.onboardingSteps, (step: OnboardingStep, index: number) => {
          TabContent() {
            Column() {
              Text(step.title)
                .fontSize(24)
                .margin({ bottom: 20 });
              Image(step.image)
                .width(200)
                .height(200)
                .margin({ bottom: 20 });
            }
            .width('100%')
            .height('100%')
            .justifyContent(FlexAlign.Center)
            .alignItems(HorizontalAlign.Center)
          }
        })
      }
      .onChange((index: number) => {
        this.currentStep = index;
        this.playAudio(this.onboardingSteps[index].audio);
      })
      .barWidth(0)
      .barHeight(0)
      .width('100%')
      .height('80%')

      Row() {
        ForEach(this.onboardingSteps, (step: OnboardingStep, index: number) => {
          Image($r('app.media.icon'))
            .width(10)
            .height(10)
            .margin(5)
            .opacity(index === this.currentStep ? 1 : 0.5)
        })
      }
      .justifyContent(FlexAlign.Center)
      .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
  }
}

