import promptAction from '@ohos.promptAction';

@Entry
@Component
struct SleepTrackerApp {
  @State currentStage: number = 0
  @State progressValue: number = 0
  private readonly stages: string[] = ['Light Sleep', 'Deep Sleep', 'REM Sleep', 'Awake']
  private readonly maxProgress: number = 100

  build() {
    Column() {
      // Moon icon
      Image($r('app.media.ic_default'))
        .width(50)
        .height(50)
        .margin({ top: 20 })

      // Stage name display
      Text(this.stages[this.currentStage])
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 10, bottom: 20 })

      // Progress bar
      Progress({
        value: this.progressValue,
        total: this.maxProgress,
        type: ProgressType.Linear
      })
        .width('80%')
        .height(20)
        .margin({ bottom: 20 })

      // Update button
      Button('Update Progress')
        .onClick(() => {
          if (this.progressValue < this.maxProgress) {
            this.progressValue += 10
            if (this.progressValue % 20 === 0) {
              promptAction.showToast({ message: 'Progress: ' + this.progressValue + '%' })
            }
          }
        })
        .enabled(this.progressValue < this.maxProgress)
        .margin({ bottom: 20 })

      // Tabs for stage navigation
      Tabs({ barPosition: BarPosition.End }) {
        ForEach(this.stages, (stage: string, index: number) => {
          TabContent() {
            Column() {
              // Empty content for tabs
            }
          }
          .tabBar(stage)
        })
      }
      .onChange((index: number) => {
        this.currentStage = index
      })
      .width('100%')
      .height(100)
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
  }
}

@Entry
@Component
struct MultiTabApp {
