import { Column, Row, List, Text, Button, TextInput, ListItem, TimePicker } from '@ohos.arkui.component';
import { FontWeight } from '@ohos.arkui.common';
import storage from '@ohos.data.storage';

interface TimeValue {
  hour: number;
  minute: number;
}

const storageInstance = new storage.LocalStorage({ 'inv_items': '[]' });

interface InventoryItem {
  id: number;
  name: string;
  quantity: number;
  time: string;
}

@Entry(storageInstance)
@Component
struct InventoryManager {
  @LocalStorageLink('inv_items') inventoryItemsStr: string = '[]';
  @State inventoryItems: InventoryItem[] = [];
  @State newItemName: string = '';
  @State newItemQuantity: string = '';
  @State selectedTime: string = '';
  @State showTimePicker: boolean = false;

  aboutToAppear(): void {
    this.loadInventoryItems();
  }

  loadInventoryItems(): void {
    try {
      const storedItems = storageInstance.get<string>('inv_items') || '[]';
      this.inventoryItems = JSON.parse(storedItems) as InventoryItem[];
    } catch (error: Error) {
      console.error('Failed to load inventory items');
    }
  }

  saveInventoryItems(): void {
    try {
      storageInstance.set('inv_items', JSON.stringify(this.inventoryItems));
    } catch (error: Error) {
      console.error('Failed to save inventory items');
    }
  }

  async addItem(): Promise<void> {
    if (!this.newItemName.trim() || !this.newItemQuantity.trim() || !this.selectedTime) {
      return;
    }

    const quantity = parseInt(this.newItemQuantity);
    if (isNaN(quantity) || quantity <= 0) {
      return;
    }

    const newItem: InventoryItem = {
      id: Date.now(),
      name: this.newItemName.trim(),
      quantity: quantity,
      time: this.selectedTime,
    };

    this.inventoryItems = [...this.inventoryItems, newItem];
    this.saveInventoryItems();

    this.newItemName = '';
    this.newItemQuantity = '';
    this.selectedTime = '';
  }

  async deleteItem(id: number): Promise<void> {
    this.inventoryItems = this.inventoryItems.filter(item => item.id !== id);
    this.saveInventoryItems();
  }

  build() {
    Column() {
      Text('Inventory Management')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row() {
        TextInput({ placeholder: 'Item Name', text: this.newItemName })
          .onChange((value: string) => {
            this.newItemName = value;
          })
          .width('40%')
          .margin({ right: 10 });

        TextInput({ placeholder: 'Quantity', text: this.newItemQuantity })
          .onChange((value: string) => {
            this.newItemQuantity = value;
          })
          .width('30%')
          .margin({ right: 10 });

        Button('Select Time')
          .onClick(() => {
            this.showTimePicker = true;
          })
          .width('20%');
      }
      .margin({ bottom: 20 });

      if (this.showTimePicker) {
        TimePicker()
          .onChange((value: TimeValue) => {
            this.selectedTime = `${value.hour}:${value.minute}`;
            this.showTimePicker = false;
          });
      }

      Button('Add Item')
        .onClick(() => this.addItem())
        .width('80%')
        .margin({ bottom: 20 });

      List() {
        ForEach(this.inventoryItems, (item: InventoryItem) => {
          ListItem() {
            Row() {
              Column() {
                Text(item.name)
                  .fontSize(18);
                Text(`Quantity: ${item.quantity}`)
                  .fontSize(14);
                Text(`Time: ${item.time}`)
                  .fontSize(14);
              }
              .margin({ right: 10 });
            }
            .padding(10)
            .swipeAction({
              end: {
                builder: () => {
                  Button('Delete')
                    .onClick(() => this.deleteItem(item.id))
                    .width(80)
                    .height('100%')
                }
              }
            });
          }
        });
      }
      .width('100%');
    }
    .padding(20);
  }
}

