import { Video, VideoController } from '@ohos.multimedia.media';
import { Chip, ChipType } from '@ohos.arkui.component';
import { TextInput, InputType } from '@ohos.arkui.component';

interface Expense {
  category: string;
  amount: number;
  description: string;
}

@Entry
@Component
struct ExpenseTracker {
  @State videoSrc: Resource = $r('app.media.video');
  @State isAuthenticated: boolean = false;
  @State selectedCategory: string = '';
  @State amount: number = 0;
  @State description: string = '';
  @State expenses: Array<Expense> = [];

  build() {
    Column() {
      Video({
        src: this.videoSrc,
        controller: new VideoController()
      })
        .width('100%')
        .height(200)
        .controls(true)

      Button('Authenticate')
        .onClick(() => {
          this.isAuthenticated = true;
        })
      Text(this.isAuthenticated ? 'Authenticated' : 'Not Authenticated')

      Row() {
        ForEach(['Food', 'Transport', 'Entertainment', 'Utilities', 'Others'], (category: string) => {
          Chip({
            type: ChipType.Filter,
            label: category
          })
            .selected(this.selectedCategory === category)
            .onClick(() => {
              this.selectedCategory = category;
            })
        })
      }

      Column() {
        TextInput({ placeholder: 'Amount' })
          .type(InputType.Number)
          .onChange((value: string) => {
            this.amount = parseFloat(value);
          })

        TextInput({ placeholder: 'Description' })
          .onChange((value: string) => {
            this.description = value;
          })

        Button('Add Expense')
          .onClick(() => {
            if (this.amount && this.description && this.selectedCategory) {
              this.expenses.push({
                category: this.selectedCategory,
                amount: this.amount,
                description: this.description
              });
              this.amount = 0;
              this.description = '';
            }
          })
      }

      List() {
        ForEach(this.expenses, (expense: Expense) => {
          ListItem() {
            Column() {
              Text(expense.category)
              Text(expense.amount.toString())
              Text(expense.description)
            }
          }
        })
      }
    }
  }
}

@Entry
@Component
struct FormValidationCard {
  @State email: string = ''
  @State isEmailValid: boolean = true
  @State emailError: string = ''

  @State password: string = ''
  @State isPasswordValid: boolean = true
  @State passwordError: string = ''

  validateEmail(email: string): string | null {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return emailRegex.test(email) ? null : 'Please enter a valid email'
  }

  validatePassword(password: string): string | null {
    return password.length >= 6 ? null : 'Password must be at least 6 characters'
  }

  build() {
    Column({ space: 20 }) {
      Column() {
        Column({ space: 10 }) {
          TextInput({ placeholder: 'Email' })
            .width('100%')
            .onChange((value: string) => {
              this.email = value
              const error = this.validateEmail(value)
              this.emailError = error || ''
              this.isEmailValid = !error
            })
            .border({
              width: 1,
              color: this.isEmailValid ? '#ddd' : '#ff0000'
            })

          if (this.emailError) {
            Text(this.emailError)
              .fontSize(12)
              .fontColor('#ff0000')
              .margin({ top: 5 })
          }

          TextInput({ placeholder: 'Password' })
            .width('100%')
            .onChange((value: string) => {
              this.password = value
              const error = this.validatePassword(value)
              this.passwordError = error || ''
              this.isPasswordValid = !error
            })
            .border({
              width: 1,
              color: this.isPasswordValid ? '#ddd' : '#ff0000'
            })

          if (this.passwordError) {
            Text(this.passwordError)
              .fontSize(12)
              .fontColor('#ff0000')
              .margin({ top: 5 })
          }

          Button('Submit')
            .enabled(this.isEmailValid && this.isPasswordValid)
            .onClick(() => {
              console.info('Form submitted')
            })
        }
        .padding(20)
      }
      .width('100%')
    }
    .padding(20)
    .width('100%')
  }
}

import promptAction from '@ohos.promptAction';
import { InputType } from '@ohos.arkui.advanced';

interface Credential {
  id: string;
  username: string;
  password: string;
}

@Entry
@Component
struct PasswordManager {
  @State username: string = '';
  @State password: string = '';
  @State credentials: Credential[] = [];
  @State showPassword: boolean = false;

  private generateId(): string {
    return Math.random().toString(36).substring(2, 9);
  }

  private handleSubmit() {
    if (!this.username || !this.password) {
      promptAction.showToast({ message: 'Please fill in all fields' });
      return;
    }

    const newCredential: Credential = {
      id: this.generateId(),
      username: this.username,
      password: this.password,
    };

    this.credentials = [...this.credentials, newCredential];
    this.username = '';
    this.password = '';

    promptAction.showDialog({
      title: 'Success',
      message: 'Credential added successfully',
      buttons: [{ text: 'OK', color: '#000000' }],
    });
  }

  private handleDelete(id: string) {
    promptAction.showDialog({
      title: 'Confirm',
      message: 'Are you sure you want to delete this credential?',
      buttons: [
        { text: 'Confirm', color: '#000000' },
        { text: 'Cancel', color: '#000000' },
      ],
    }).then((result) => {
      if (result.index === 0) {
        this.credentials = this.credentials.filter((cred) => cred.id !== id);
      }
    });
  }

  build() {
    Column() {
      Column() {
        Text('Username')
          .fontSize(18)
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Enter username' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.username = value;
          });

        Text('Password')
          .fontSize(18)
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Enter password' })
          .type(InputType.Password)
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.password = value;
          });

        Button('Toggle Password Visibility')
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .onClick(() => {
            this.showPassword = !this.showPassword;
          });

        Button('Submit')
          .width('100%')
          .height(50)
          .fontSize(18)
          .backgroundColor('#007AFF')
          .onClick(() => this.handleSubmit());
      }
      .width('100%')
      .padding(20);

      List({ space: 10 }) {
        ForEach(this.credentials, (credential: Credential) => {
          ListItem() {
            Column() {
              Text(`Username: ${credential.username}`)
                .fontSize(16)
                .margin({ bottom: 5 });

              Text(`Password: ${this.showPassword ? credential.password : '••••••••'}`)
                .fontSize(16)
                .margin({ bottom: 10 });

              Button('Delete')
                .width(100)
                .height(30)
                .backgroundColor('#FF3B30')
                .onClick(() => this.handleDelete(credential.id));
            }
            .width('100%')
            .padding(10)
            .backgroundColor('#FFFFFF')
            .borderRadius(8);
          }
        });
      }
      .width('100%')
      .layoutWeight(1)
      .divider({ strokeWidth: 1, color: '#f0f0f0' });
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

import { Flex, Row, Column, Button, Text, Radio } from '@ohos.arkui.advanced.Components';
