@Entry
@Component
struct BiometricAuthApp {
  @State selectedAuth: 'Fingerprint' | 'FaceID' = 'Fingerprint';
  @State authStatus: string = 'Perform gesture for authentication';
  @State isAuthenticated: boolean = false;

  build() {
    Flex({ direction: FlexDirection.Column, justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
      Column() {
        Row() {
          Column() {
            Radio({ value: 'Fingerprint' })
              .checked(this.selectedAuth === 'Fingerprint')
