                if (isChecked) this.selectedAuth = 'Fingerprint';
              });
            Text('Fingerprint').margin({ left: 10 });
          }
          Column() {
            Radio({ value: 'FaceID' })
              .checked(this.selectedAuth === 'FaceID')
              .onChange((isChecked: boolean) => {
                if (isChecked) this.selectedAuth = 'FaceID';
              });
