import { DatePicker, Stack, Column, Image, Text, Circle } from '@ohos.arkui.advanced';
import { PanGesture, PanGestureEvent } from '@ohos.arkui.gesture';
import { Color } from '@ohos.arkui.drawing';
import { Curve, animateTo } from '@ohos.animation';
import { FlexAlign } from '@ohos.arkui.layout';

interface Position {
  x: number;
  y: number;
}

@Entry
@Component
struct RecordingBadgeApp {
  @State isRecording: boolean = false;
  @State badgeScale: number = 1.0;
  @State badgePosition: Position = { x: 0, y: 0 };
  @State selectedDate: string = 'Select a date';

  build() {
    Column({ space: 20 }) {
      Stack() {
        Image($r('app.media.icon'))
          .width(50)
          .height(50)
          .gesture(
            PanGesture()
              .onActionStart(() => {
                this.isRecording = true;
                animateTo({ duration: 300, curve: Curve.EaseInOut }, () => {
                  this.badgeScale = 1.1;
                });
              })
              .onActionUpdate((event: PanGestureEvent) => {
                this.badgePosition = { x: event.offsetX, y: event.offsetY };
              })
              .onActionEnd(() => {
                this.isRecording = false;
                animateTo({ duration: 300, curve: Curve.EaseInOut }, () => {
                  this.badgeScale = 1.0;
                });
              })
          );

        if (this.isRecording) {
          Circle({ radius: 10, color: Color.Red })
            .width(20)
            .height(20)
            .position({ x: this.badgePosition.x, y: this.badgePosition.y })
            .scale({ x: this.badgeScale, y: this.badgeScale })
            .animation({ duration: 300, curve: Curve.EaseInOut });
        }
      }
      .width(50)
      .height(50);

      DatePicker({
        start: new Date('2020-01-01'),
        end: new Date('2030-12-31'),
        selected: new Date(),
      })
      .onChange((date: Date) => {
        this.selectedDate = date.toLocaleDateString();
      });

      Text(this.selectedDate)
        .fontSize(16)
        .margin({ top: 10 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }
}

