import { Column, Row, Text, List, ListItem, Button, TextInput } from '@ohos.arkui.advancedUI';
import { SearchBar } from '@ohos.arkui.advancedUI';
import { PanGesture, GestureEvent, PanGestureDirection } from '@ohos.arkui.gesture';
import AppStorage from '@ohos.data.storage';
import { FontWeight } from '@ohos.arkui.advancedUI';

interface Event {
  id: string;
  title: string;
  description: string;
  date: string;
}

@Entry
@Component
struct EventPlanner {
  @State events: Event[] = [];
  @State searchText: string = '';
  @State filteredEvents: Event[] = [];
  @State titleInput: string = '';
  @State descInput: string = '';
  @State dateInput: string = '';
  private searchController: SearchBar.Controller = new SearchBar.Controller();

  aboutToAppear() {
    this.loadEvents();
  }

  private loadEvents() {
    const storedEvents: string = AppStorage.get<string>('events') || '';
    if (storedEvents) {
      this.events = JSON.parse(storedEvents) as Event[];
      this.filteredEvents = this.events;
    }
  }

  private saveEvents() {
    AppStorage.set<string>('events', JSON.stringify(this.events));
  }

  private addEvent(title: string, description: string, date: string) {
    const newEvent: Event = {
      id: Date.now().toString(),
      title,
      description,
      date,
    };
    this.events = [...this.events, newEvent];
    this.filteredEvents = this.events;
    this.saveEvents();
  }

  private deleteEvent(id: string) {
    this.events = this.events.filter(event => event.id !== id);
    this.filteredEvents = this.filteredEvents.filter(event => event.id !== id);
    this.saveEvents();
  }

  private handleSearch() {
    if (this.searchText.trim() === '') {
      this.filteredEvents = this.events;
    } else {
      this.filteredEvents = this.events.filter(event =>
        event.title.toLowerCase().includes(this.searchText.toLowerCase()) ||
        event.description.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  build() {
    Column() {
      SearchBar({
        placeholder: 'Search events...',
        controller: this.searchController,
        onChange: (value: string) => {
          this.searchText = value;
          this.handleSearch();
        }
      })
      .width('100%')
      .margin({ top: 10, bottom: 10 });

      List() {
        ForEach(this.filteredEvents, (event: Event) => {
          ListItem() {
            Column() {
              Text(event.title)
                .fontSize(18)
                .fontWeight(FontWeight.Bold);
              Text(event.description)
                .fontSize(14)
                .margin({ top: 5 });
              Text(event.date)
                .fontSize(12)
                .fontColor($r('app.color.gray'))
                .margin({ top: 5 });
            }
            .width('100%')
            .padding(10);
          }
          .onGesture(new PanGesture({ direction: PanGestureDirection.Horizontal }), (gesture: GestureEvent) => {
            if (gesture.offsetX < -100) {
              this.deleteEvent(event.id);
            }
          });
        });
      }
      .layoutWeight(1)
      .width('100%');

      Row() {
        TextInput({ placeholder: 'Title', text: this.titleInput })
          .onChange((value: string) => { this.titleInput = value; })
          .width('30%');
        TextInput({ placeholder: 'Description', text: this.descInput })
          .onChange((value: string) => { this.descInput = value; })
          .width('40%');
        TextInput({ placeholder: 'Date (YYYY-MM-DD)', text: this.dateInput })
          .onChange((value: string) => { this.dateInput = value; })
          .width('30%');
        Button('Add')
          .onClick(() => {
            if (this.titleInput && this.descInput && this.dateInput) {
              this.addEvent(this.titleInput, this.descInput, this.dateInput);
            }
          });
      }
      .width('100%')
      .padding(10);
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

import promptAction from '@ohos.promptAction';
import { Toggle, ToggleType, TextInput, Button, Text, Column, Row } from '@ohos.arkui.advanced';

interface ActionSheetButton {
  text: string;
  color: string;
}

@Entry
@Component
struct WorkoutPlanner {
  @State isTextMode: boolean = false;
  @State selectedWorkout: string = '';
  @State customWorkout: string = '';

  private predefinedWorkouts: string[] = ['Running', 'Cycling', 'Swimming', 'Yoga'];

  showActionSheet() {
    const buttons: ActionSheetButton[] = this.predefinedWorkouts.map((workout) => ({
      text: workout,
      color: '#000000'
    }));

    promptAction.showActionMenu({
      title: 'Select Workout',
      buttons: buttons,
      cancel: true
    }).then((value: promptAction.ActionMenuSuccessResponse) => {
      if (value.index >= 0 && value.index < this.predefinedWorkouts.length) {
        this.selectedWorkout = this.predefinedWorkouts[value.index];
      }
    });
  }

  build() {
    Column() {
      Row() {
        Text('Workout Selection Mode:')
          .fontSize(16)
          .margin({ right: 10 });
        Toggle({ type: ToggleType.Switch, isOn: this.isTextMode })
          .onChange((isOn: boolean) => {
            this.isTextMode = isOn;
          });
      }
      .margin({ bottom: 20 });

      if (this.isTextMode) {
        TextInput({ placeholder: 'Enter custom workout' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .onChange((value: string) => {
            this.customWorkout = value;
          });
      } else {
        Button('Select Workout')
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .onClick(() => this.showActionSheet());
      }

      Text('Selected Workout:')
        .fontSize(16)
        .margin({ bottom: 10 });
      Text(this.isTextMode ? this.customWorkout : this.selectedWorkout)
        .fontSize(18)
        .fontWeight(700);
    }
    .padding(20)
    .width('100%')
    .height('100%');
  }
}

