import router from '@ohos.router';
import promptAction from '@ohos.promptAction';
import { FontWeight } from '@ohos.arkui.dialog';

interface Trip {
  id: string;
  date: string;
  status: 'Completed' | 'In Progress' | 'Scheduled';
  details: string;
}

interface RouteParams {
  tripId: string;
}

@Entry
@Component
struct App {
  build() {
    Column() {
      TripTimeline();
    }
  }
}

@Component
struct TripTimeline {
  @State trips: Trip[] = [
    { id: '1', date: '2023-10-01', status: 'Completed', details: 'Trip to downtown' },
    { id: '2', date: '2023-10-02', status: 'In Progress', details: 'Airport pickup' },
    { id: '3', date: '2023-10-03', status: 'Scheduled', details: 'Weekend getaway' }
  ];

  @State isLoading: boolean = false;

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.trips, (trip: Trip) => {
          ListItem() {
            Column() {
              Text(trip.date)
                .fontSize(16)
                .fontWeight(FontWeight.Bold);
              Text(trip.status)
                .fontSize(14)
                .fontColor(this.getStatusColor(trip.status));
              Text(trip.details)
                .fontSize(12)
                .margin({ top: 5 });
            }
            .padding(10)
            .borderRadius(8)
            .backgroundColor('#f5f5f5')
            .onClick(() => {
              router.pushUrl({
                url: 'pages/TripDetail',
                params: { tripId: trip.id }
              }).catch((err: Error) => {
                promptAction.showToast({ message: 'Navigation failed' });
              });
            });
          }
        });
      }
      .width('100%')
      .height('80%');

      Button('Sync Data')
        .width('80%')
        .margin({ top: 20 })
        .onClick(() => {
          promptAction.showDialog({
            title: 'Sync Data',
            message: 'Are you sure you want to sync trip data?',
            buttons: [
              { text: 'Cancel', color: '#000000' },
              { text: 'Sync', color: '#007AFF' }
            ]
          }).then((result) => {
            if (result.index === 1) {
              this.syncData();
            }
          });
        });
    }
    .width('100%')
    .height('100%')
    .padding(16);
  }

  private getStatusColor(status: string): string {
    switch (status) {
      case 'Completed': return '#4CAF50';
      case 'In Progress': return '#2196F3';
      case 'Scheduled': return '#FF9800';
      default: return '#000000';
    }
  }

  private syncData(): void {
    this.isLoading = true;
    setTimeout(() => {
      try {
        this.trips.push({
          id: `${this.trips.length + 1}`,
          date: '2023-10-04',
          status: 'Scheduled',
          details: 'New trip added'
        });
        promptAction.showToast({ message: 'Data synced successfully' });
      } catch (err) {
        promptAction.showToast({ message: 'Sync failed' });
      } finally {
        this.isLoading = false;
      }
    }, 1000);
  }
}

