import { Column, Row, Text, Button, Image, Progress } from '@ohos.arkui.component';
import { ImageFit, FontWeight, FlexAlign, HorizontalAlign } from '@ohos.arkui.common';

@Entry
@Component
struct MeditationApp {
  @State currentStep: number = 0;
  @State progress: number = 0;
  @State isRunning: boolean = false;
  @State sessionDuration: number = 5;
  private steps: string[] = ["Breathe In", "Hold", "Breathe Out", "Relax"];
  private timerId: number = -1;
  private totalSteps: number = 4;
  private stepDuration: number = 60;

  build() {
    Column() {
      Image($r('app.media.ic_public_picture'))
        .width('100%')
        .height('100%')
        .objectFit(ImageFit.Cover)

      Column() {
        Text(this.steps[this.currentStep])
          .fontSize(30)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 })

        Progress({ value: this.progress, total: 100 })
          .width('80%')
          .height(10)
          .margin({ bottom: 20 })

        Row() {
          Button('Previous')
            .width('30%')
            .onClick(() => this.handlePrevious())
            .margin({ right: 10 })

          Button(this.isRunning ? 'Pause' : 'Start')
            .width('30%')
            .onClick(() => this.handleStartPause())
            .margin({ right: 10 })

          Button('Next')
            .width('30%')
            .onClick(() => this.handleNext())
        }
        .width('100%')
        .justifyContent(FlexAlign.Center)
        .margin({ bottom: 20 })

        Button('Session Options')
          .width('50%')
          .onClick(() => this.handleSessionOptions())
      }
      .width('80%')
      .height('60%')
      .justifyContent(FlexAlign.Center)
      .alignItems(HorizontalAlign.Center)
      .backgroundColor('#FFFFFF')
      .opacity(0.8)
      .borderRadius(20)
      .padding(20)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }

  private handleStartPause(): void {
    if (this.isRunning) {
      clearInterval(this.timerId);
      this.isRunning = false;
    } else {
      this.isRunning = true;
      this.startTimer();
    }
  }

  private handlePrevious(): void {
    if (this.currentStep > 0) {
      this.currentStep--;
      this.updateProgress();
    }
  }

  private handleNext(): void {
    if (this.currentStep < this.totalSteps - 1) {
      this.currentStep++;
      this.updateProgress();
    }
  }

  private handleSessionOptions(): void {
  }

  private startTimer(): void {
    this.timerId = setInterval(() => {
      this.progress += (100 / (this.sessionDuration * 60));
      if (this.progress >= 100) {
        clearInterval(this.timerId);
        this.isRunning = false;
        this.progress = 0;
        this.currentStep = 0;
      } else if (this.progress % (100 / this.totalSteps) === 0) {
        this.currentStep = (this.currentStep + 1) % this.totalSteps;
      }
    }, 1000);
  }

  private updateProgress(): void {
    this.progress = (this.currentStep / this.totalSteps) * 100;
  }
}

import { Tabs, TabContent, BarPosition } from '@ohos.arkui.advanced';
import { List, ListItem } from '@ohos.arkui.advanced';
import { ContextMenu } from '@ohos.arkui.advanced';
import { LongPressGesture, GestureEvent } from '@ohos.arkui.advanced';
import vibrator from '@ohos.vibrator';
import { BusinessError } from '@ohos.base';
import deviceInfo from '@ohos.deviceInfo';

interface Position {
  x: number;
  y: number;
}

@Entry
@Component
struct TabNavigationApp {
  @State currentTab: number = 0;
  @State showMenu: boolean = false;
  @State menuPosition: Position = { x: 0, y: 0 };

  private async triggerHapticFeedback(): Promise<void> {
    try {
      if (deviceInfo.deviceType === 'phone') {
        const vibratorInstance = await vibrator.getVibrator();
        await vibratorInstance.startVibration({
          effectId: 'haptic_clock_timer',
          count: 1
        });
      }
    } catch (error: BusinessError) {
      console.error('Failed to trigger haptic feedback:', error);
    }
  }

  private handleLongPress(event: GestureEvent): void {
    this.triggerHapticFeedback();
    this.menuPosition = { x: event.globalX, y: event.globalY };
    this.showMenu = true;
  }

  private closeMenu(): void {
    this.showMenu = false;
  }

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.End }) {
        TabContent() {
          List() {
            ForEach([1, 2, 3, 4, 5], (item: number) => {
              ListItem() {
                Text(`Home Item ${item}`)
                  .fontSize(20)
                  .margin(10)
              }
            })
          }
          .onLongPress((event: GestureEvent) => this.handleLongPress(event))
        }.tabBar('Home')

        TabContent() {
          List() {
            ForEach([1, 2, 3, 4, 5], (item: number) => {
              ListItem() {
                Text(`Profile Item ${item}`)
                  .fontSize(20)
                  .margin(10)
              }
            })
          }
          .onLongPress((event: GestureEvent) => this.handleLongPress(event))
        }.tabBar('Profile')

        TabContent() {
          List() {
            ForEach([1, 2, 3, 4, 5], (item: number) => {
              ListItem() {
                Text(`Settings Item ${item}`)
                  .fontSize(20)
                  .margin(10)
              }
            })
          }
          .onLongPress((event: GestureEvent) => this.handleLongPress(event))
        }.tabBar('Settings')
      }
      .onChange((index: number) => {
        this.currentTab = index;
      })

      if (this.showMenu) {
        ContextMenu({
          position: this.menuPosition,
          onDismiss: () => this.closeMenu()
        }) {
          Text('Option 1')
            .onClick(() => this.closeMenu())
          Text('Option 2')
            .onClick(() => this.closeMenu())
          Text('Option 3')
            .onClick(() => this.closeMenu())
        }
      }
    }
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct MeditationApp {
