import { Column, Stack, Image, Text, FontWeight, Color, ImageFit } from '@ohos.arkui.advanced';
import { PanGesture, GestureEvent } from '@ohos.arkui.gesture';

@Entry
@Component
struct ImageCropper {
  @State imageWidth: number = 200;
  @State imageHeight: number = 200;
  @State isResizing: boolean = false;
  @State startX: number = 0;
  @State startY: number = 0;
  @State startWidth: number = 0;
  @State startHeight: number = 0;

  private panGesture: PanGesture = new PanGesture()
    .onActionStart(() => {
      this.isResizing = true;
      this.startWidth = this.imageWidth;
      this.startHeight = this.imageHeight;
    })
    .onActionUpdate((event: GestureEvent) => {
      if (this.isResizing) {
        this.imageWidth = this.startWidth + event.offsetX;
        this.imageHeight = this.startHeight + event.offsetY;
      }
    })
    .onActionEnd(() => {
      this.isResizing = false;
    });

  build() {
    Column() {
      Text('Image Cropper')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Stack() {
        Image($r('app.media.app_icon'))
          .width(this.imageWidth)
          .height(this.imageHeight)
          .border({ width: 1, color: Color.Gray })
          .objectFit(ImageFit.Contain);

        Column() {
          Text('\\u2194')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .gesture(this.panGesture);
        }
        .position({ x: this.imageWidth - 20, y: this.imageHeight - 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

