import { ScrollView, Row, Column, Image, Button, Progress, Card } from '@ohos.arkui.advanced';

interface ImageItem {
  id: number;
  image: Resource;
  isFiltered: boolean;
}

@Entry
@Component
struct ImageFilterApp {
  private images: ImageItem[] = [
    { id: 1, image: $r('app.media.icon'), isFiltered: false },
    { id: 2, image: $r('app.media.icon'), isFiltered: false },
    { id: 3, image: $r('app.media.icon'), isFiltered: false }
  ];

  @State private progressValue: number = 0;
  @State private isFiltering: boolean = false;

  private applyFilter(imageId: number): void {
    this.isFiltering = true;
    this.progressValue = 0;

    const interval = setInterval(() => {
      this.progressValue += 10;
      if (this.progressValue >= 100) {
        clearInterval(interval);
        this.isFiltering = false;
        this.images = this.images.map(item =>
          item.id === imageId ? { id: item.id, image: item.image, isFiltered: !item.isFiltered } : item
        );
      }
    }, 200);
  }

  build() {
    Column() {
      ScrollView() {
        Column() {
          ForEach(this.images, (item: ImageItem) => {
            Card() {
              Column() {
                Image(item.image)
                  .width(200)
                  .height(200)
                  .margin({ top: 10, bottom: 10, left: 10, right: 10 });

                Button(item.isFiltered ? 'Remove Filter' : 'Apply Filter')
                  .onClick(() => this.applyFilter(item.id))
                  .margin({ top: 10, bottom: 10, left: 10, right: 10 });
              }
            }
            .margin({ top: 10, bottom: 10, left: 10, right: 10 });
          });

          if (this.isFiltering) {
            Progress({ value: this.progressValue, total: 100 })
              .width('90%')
              .margin({ top: 10, bottom: 10, left: 10, right: 10 });
          }
        }
        .width('100%')
        .padding(10);
      }
      .width('100%')
      .height('100%');
    }
    .width('100%')
    .height('100%');
  }
}

@Entry
@Component
struct StepCounterForm {
  @State steps: number = 0
  @State username: string = ''
  @State password: string = ''
  @State errorMessage: string = ''
  @State successMessage: string = ''
  @State isSwipeActive: boolean = false

  validateInput(): boolean {
    if (!this.username.trim() || !this.password.trim()) {
      this.errorMessage = 'Please enter both username and password.'
      return false
    }
    this.errorMessage = ''
    return true
  }

  handleSwipe(event: PanGestureEvent) {
    if (event.offsetX > 50) {
      this.isSwipeActive = true
      this.steps += 1
    } else {
      this.isSwipeActive = false
    }
  }

  handleLogin() {
    if (this.validateInput()) {
      this.successMessage = 'Login successful!'
      this.password = this.password.replace(/</g, '&lt;').replace(/>/g, '&gt;')
    } else {
      this.successMessage = ''
    }
  }

  build() {
    Column() {
      Text('Welcome to Step Counter App')
        .fontSize(20)
        .fontColor(Color.Black)
        .width('100%')
        .margin({ bottom: 20 })

      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your username' })
        .width('80%')
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.username = value
        })

      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password' })
        .width('80%')
        .type(InputType.Password)
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.password = value
        })

      Row()
        .width('80%')
        .height(60)
        .backgroundColor('#EEEEEE')
        .gesture(
          PanGesture()
            .onActionStart(() => {
              this.isSwipeActive = false
            })
            .onActionUpdate((event: PanGestureEvent) => {
              this.handleSwipe(event)
            })
            .onActionEnd(() => {
              this.isSwipeActive = false
            })
        )
        .margin({ bottom: 20 })

      Text(`Steps: ${this.steps}`)
        .fontSize(18)
        .margin({ bottom: 20 })

      Button('Login')
        .onClick(() => {
          this.handleLogin()
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(16)
