import { Column, Text, Button, Divider } from '@ohos.arkui.advanced';
import { Tag } from '@ohos.arkui.extended';
import { Curves } from '@ohos.arkui.animation';

@Entry
@Component
struct ScanningInterface {
  @State isScanning: boolean = false;
  @State scanProgress: number = 0;

  private startScanning() {
    this.isScanning = true;
    this.scanProgress = 0;
  }

  private stopScanning() {
    this.isScanning = false;
  }

  private updateProgress() {
    if (this.scanProgress < 100) {
      this.scanProgress += 10;
    } else {
      this.stopScanning();
    }
  }

  build() {
    Column({ space: 20 }) {
      Text(this.isScanning ? 'Scanning in progress...' : 'Ready to scan')
        .fontSize(20)
        .fontWeight(FontWeight.Bold);

      Divider()
        .strokeWidth(2)
        .color(Color.Blue)
        .animation({
          duration: 1000,
          curve: Curves.EaseInOut,
          iterations: -1,
          playMode: 'normal'
        })
        .visibility(this.isScanning ? Visibility.Visible : Visibility.Hidden);

      Text(`Progress: ${this.scanProgress}%`)
        .fontSize(16);

      Column({ space: 10 }) {
        ForEach([1, 2, 3], (index: number) => {
          Button(`Tag ${index}`)
            .width(80)
            .height(40)
            .borderRadius(20)
            .backgroundColor(Color.Blue)
            .fontColor(Color.White)
            .onClick(() => {
              if (this.isScanning) {
                this.updateProgress();
              }
            });
        });
      }

      Button(this.isScanning ? 'Stop Scanning' : 'Start Scanning')
        .onClick(() => {
          if (this.isScanning) {
            this.stopScanning();
          } else {
            this.startScanning();
          }
        });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

