            Button('Verify')
              .width('100%')
              .height(50)
              .backgroundColor(this.isValidOtp ? '#4CAF50' : '#CCCCCC')
              .enabled(this.isValidOtp)
              .onClick(() => {
                if (this.isValidOtp) {
                  // Handle successful verification
                }
              });
