@Entry
@Component
struct SegmentedControlWithRotation {
  @State angle: number = 0;
  @State selectedIndex: number = 0;
  @State rotationText: string = "Rotation Angle: 0°";
  @State segmentText: string = "Selected Segment: 1";

  private segments: string[] = ["Segment1", "Segment2", "Segment3", "Segment4"];

  build() {
    Column({ space: 20 }) {
      Text(this.rotationText)
        .fontSize(20)
        .fontColor(Color.Black);

      Text(this.segmentText)
        .fontSize(20)
        .fontColor(Color.Black);

      Tabs({ barPosition: BarPosition.End }) {
        ForEach(this.segments, (item: string, index: number) => {
          TabContent() {
            Column() {
              Text(item)
                .fontSize(16)
                .fontColor(Color.Black);
            }
            .width('100%')
            .height('100%')
            .justifyContent(FlexAlign.Center);
          }
          .tabBar(item);
        });
      }
      .width('80%')
      .height(50)
      .onChange((index: number) => {
        this.selectedIndex = index;
        this.segmentText = `Selected Segment: ${index + 1}`;
      })
      .gesture(
        RotationGesture()
          .onActionStart(() => {
            console.info("Rotation started");
          })
          .onActionUpdate((event: RotationGestureEvent) => {
            this.angle = event.angle;
            this.rotationText = `Rotation Angle: ${Math.round(this.angle)}°`;
            const segmentCount = this.segments.length;
            const anglePerSegment = 360 / segmentCount;
            const newIndex = Math.floor((this.angle % 360) / anglePerSegment);
            if (newIndex >= 0 && newIndex < segmentCount && newIndex !== this.selectedIndex) {
              this.selectedIndex = newIndex;
              this.segmentText = `Selected Segment: ${newIndex + 1}`;
            }
          })
          .onActionEnd(() => {
            console.info("Rotation ended");
          })
      );

      Stepper({
        index: this.selectedIndex + 1
      })
        .width('80%')
        .height(50)
        .onChange((value: number) => {
          this.selectedIndex = value - 1;
          this.segmentText = `Selected Segment: ${value}`;
        });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor(Color.White);
  }
}

