import router from '@ohos.router';

enum SwipeDirection {
  Left = 'Left',
  Right = 'Right',
  Up = 'Up',
  Down = 'Down'
}

interface SwipeHistoryItem {
  direction: string;
  timestamp: number;
}

interface SwipeGestureEvent {
  direction: string;
}

@Entry
@Component
struct SwipeTracker {
  @State swipeDirection: string = 'None'
  @State swipeHistory: Array<SwipeHistoryItem> = []

  private startX: number = 0
  private startY: number = 0

  handleSwipe(event: SwipeGestureEvent) {
    this.swipeDirection = event.direction
    this.swipeHistory.push({ direction: this.swipeDirection, timestamp: Date.now() })
  }

  build() {
    Column() {
      Text(`Swipe Direction: ${this.swipeDirection}`)
        .fontSize(20)
        .margin({ bottom: 20 })

      Row()
        .width(300)
        .height(200)
        .backgroundColor('#EEEEEE')
        .onTouch((event: TouchEvent) => {
          if (event.type === TouchType.Down) {
            this.startX = event.touches[0].x
            this.startY = event.touches[0].y
          } else if (event.type === TouchType.Move) {
            const deltaX = event.touches[0].x - this.startX
            const deltaY = event.touches[0].y - this.startY
            let direction = ''
            if (Math.abs(deltaX) > Math.abs(deltaY)) {
              direction = deltaX > 0 ? 'Right' : 'Left'
            } else {
              direction = deltaY > 0 ? 'Down' : 'Up'
            }
            this.handleSwipe({direction: direction})
          }
        })
        .margin({ bottom: 20 })

      List({ space: 10 }) {
        ForEach(this.swipeHistory, (item: SwipeHistoryItem) => {
          ListItem() {
            Text(`${item.direction} - ${new Date(item.timestamp).toLocaleTimeString()}`)
              .fontSize(16)
          }
        })
      }
      .width('100%')
      .height(200)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .padding(20)
  }
}

import { Toggle, ToggleType } from '@ohos.arkui.component';
import { Tooltip } from '@ohos.arkui.component';
import { AlertDialog } from '@ohos.arkui.dialog';
import { Gesture, GestureGroup, Direction } from '@ohos.arkui.gesture';

@Entry
@Component
struct ToggleWithGestures {
  @State private isToggleOn: boolean = false;
  @State private showTooltip: boolean = false;
  @State private showAlert: boolean = false;

  private tooltipTimeout: number = 0;

  private showLongPressAlert(): void {
    AlertDialog.show({
      title: 'Long Press Detected',
      message: 'You long-pressed the toggle!',
      confirm: {
        value: 'OK',
        action: () => {
          this.showAlert = false;
        }
      }
    });
  }

  build() {
    Column() {
      Toggle({ type: ToggleType.Switch, isOn: this.isToggleOn })
        .onChange((isOn: boolean) => {
          this.isToggleOn = isOn;
        })
        .gesture(
          GestureGroup(
            Gesture.PanGesture({ direction: Direction.Horizontal })
              .onActionUpdate((event: GestureEvent) => {
                if (Math.abs(event.offsetX) > 50) {
                  this.showTooltip = true;
                  if (this.tooltipTimeout) {
                    clearTimeout(this.tooltipTimeout);
                  }
                  this.tooltipTimeout = setTimeout(() => {
                    this.showTooltip = false;
                  }, 2000);
                }
              }),
            Gesture.LongPressGesture({ repeat: false, duration: 500 })
              .onAction(() => {
                this.showLongPressAlert();
              })
          )
        )
        .tooltip({
          content: 'Swipe detected!',
          placement: 'bottom',
          show: this.showTooltip
        })
        .margin(20)
        .width(100)
        .height(50);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

