            .height(300)
            .controls(false)
            .autoPlay(true)
            .loop(false)
            .objectFit(ImageFit.Contain)
            .onPrepared((event: VideoPreparedEvent) => {
              console.info("Video prepared. Duration: " + event.duration);
            })
            .onError(() => {
              promptAction.showToast({ duration: 2000, message: "Video playback error." });
            })
            .accessibilityText('Video player')
            .focusable(this.accessibilityEnabled);

            Row() {
              Button('Play')
                .onClick(() => {
                  this.videoController.play();
                })
                .accessibilityText('Play button')
                .focusable(this.accessibilityEnabled)
                .margin(8);

              Button('Pause')
                .onClick(() => {
                  this.videoController.pause();
                })
                .accessibilityText('Pause button')
                .focusable(this.accessibilityEnabled)
                .margin(8);

              Button('Fullscreen')
                .onClick(() => {
                  console.log("Fullscreen requested");
                })
                .accessibilityText('Fullscreen button')
                .focusable(this.accessibilityEnabled)
                .margin(8);
            }
            .justifyContent(FlexAlign.Center)
            .margin({ top: 16 });
          }
        }
        .width('100%')
        .padding(16)
      }
      .onRefresh(() => {
        this.isRefreshing = true;
        setTimeout(() => {
          this.isRefreshing = false;
        }, 1000);
      })
      .accessibilityText('Pull to refresh container')
      .focusable(this.accessibilityEnabled);

      Button(this.accessibilityEnabled ? 'Disable Accessibility' : 'Enable Accessibility')
        .onClick(() => {
          this.accessibilityEnabled = !this.accessibilityEnabled;
        })
        .margin({ top: 16 })
        .accessibilityText('Toggle accessibility features')
        .focusable(true);
    }
    .width('100%')
    .height('100%');
  }
}

import sensor from '@ohos.sensor';
import { CustomDialogController, DialogAlignment } from '@ohos.arkui.UIContext';
import { animateTo, Curve } from '@ohos.arkui.animator';
import { Color, FontWeight, FlexAlign, ItemAlign, Column, Text, Button, Flex, ScaleOptions, RotateOptions } from '@ohos.arkui.UIContext';

interface ScaleState extends ScaleOptions {
  x: number;
  y: number;
}

interface RotateState extends RotateOptions {
  angle: number;
}

@Entry
@Component
struct SensorAnimationApp {
  @State scale: ScaleState = { x: 1.0, y: 1.0 };
  @State rotate: RotateState = { angle: 0 };
  @State showDialog: boolean = false;
  dialogController: CustomDialogController = new CustomDialogController({
    builder: this.DialogBuilder.bind(this),
    alignment: DialogAlignment.CENTER,
    customStyle: true
  });

  aboutToAppear(): void {
    try {
      const sensorManager = sensor.getSensorManager();
      const accelerometer = sensorManager.getDefaultSensor(sensor.SensorType.SENSOR_TYPE_ACCELEROMETER);
      sensorManager.on(accelerometer, (data: sensor.SensorData) => {
        if (Math.abs(data.values[0]) > 15 || 
            Math.abs(data.values[1]) > 15 || 
            Math.abs(data.values[2]) > 15) {
          this.triggerAnimation();
          this.showDialog = true;
        } else {
          this.resetAnimation();
          this.showDialog = false;
        }
      });
    } catch (error) {
      console.error('Sensor error:', error);
    }
  }

  onPageHide(): void {
    try {
      const sensorManager = sensor.getSensorManager();
      const accelerometer = sensorManager.getDefaultSensor(sensor.SensorType.SENSOR_TYPE_ACCELEROMETER);
      sensorManager.off(accelerometer);
    } catch (error) {
      console.error('Sensor error:', error);
    }
  }

  triggerAnimation(): void {
    animateTo({
      duration: 500,
      curve: Curve.EaseInOut
    }, () => {
      this.scale = { x: 1.2, y: 1.2 };
      this.rotate = { angle: 10 };
      this.dialogController.open();
    });
  }

  resetAnimation(): void {
    animateTo({
      duration: 500,
      curve: Curve.EaseInOut
    }, () => {
      this.scale = { x: 1.0, y: 1.0 };
      this.rotate = { angle: 0 };
      this.dialogController.close();
    });
  }

  @Builder
  DialogBuilder() {
    Column() {
      Text('Movement Detected!')
        .fontSize(20)
        .fontWeight(FontWeight.BOLD)
        .margin({ bottom: 10 });
      Text('Significant device movement has been detected.')
        .fontSize(16)
        .margin({ bottom: 20 });
      Button('OK')
        .onClick(() => {
          this.dialogController.close();
        });
    }
    .padding(20)
    .backgroundColor(Color.White)
    .borderRadius(10);
  }

  build() {
    Column() {
      Text('Sensor Animation App')
        .fontSize(24)
        .fontWeight(FontWeight.BOLD)
        .margin({ top: 20, bottom: 20 });
      Button('Toggle Dialog')
        .onClick(() => {
          if (this.showDialog) {
            this.dialogController.close();
          } else {
            this.dialogController.open();
          }
          this.showDialog = !this.showDialog;
        });
      Flex({ justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
        Text('Animate Me!')
          .fontSize(18);
      }
      .width(200)
      .height(200)
      .backgroundColor(Color.Blue)
      .scale(this.scale)
      .rotate(this.rotate);
    }
    .width('100%')
    .height('100%')
    .alignItems(ItemAlign.Center);
  }
}

import promptAction from '@ohos.promptAction';
import { InputType } from '@ohos.arkui';
import { Tooltip, Placement } from '@ohos.arkui.tooltip';
import { AlertDialog } from '@ohos.arkui.dialog';
import { FontWeight, Color } from '@ohos.arkui.common';
import { FlexAlign, HorizontalAlign } from '@ohos.arkui.layout';

@Entry
@Component
struct PasswordManager {
  @State username: string = '';
  @State password: string = '';
  @State showDialog: boolean = false;

  build() {
    Column() {
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bolder)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your username' })
        .onChange((value: string) => {
          this.username = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Row() {
        Text('Password')
          .fontSize(18)
          .fontWeight(FontWeight.Bolder)
          .margin({ bottom: 10 });

        Tooltip({
          content: 'Minimum 8 characters',
          placement: Placement.Bottom
        }) {
          Button('?')
            .width(30)
            .height(30)
            .fontSize(14);
        }
      }
      .width('80%')
      .justifyContent(FlexAlign.SpaceBetween);

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Button('Save Password')
        .onClick(() => {
          if (this.username && this.password) {
            if (this.password.length >= 8) {
              AlertDialog.show({
                title: 'Confirm Save',
                message: 'Are you sure you want to save this password?',
                confirm: {
                  value: 'Save',
                  action: () => {
                    promptAction.showToast({
                      message: 'Password saved successfully'
                    });
                    this.username = '';
                    this.password = '';
