import { Column, Row, Text, Button, Progress, FlexAlign, ForEach } from '@ohos.arkui.advanced';

@Entry
@Component
struct MarqueeVoiceApp {
  @State marqueeText: string = 'Welcome to the Marquee Voice App!';
  @State marqueePos: number = 0;
  @State isListening: boolean = false;
  @State processing: boolean = false;
  @State progressValue: number = 0;
  @State dataArray: number[] = [10, 20, 30, 40, 50];

  aboutToAppear(): void {
    setInterval(() => {
      this.marqueePos -= 2;
      if (this.marqueePos <= -500) {
        this.marqueePos = 400;
      }
    }, 50);
  }

  toggleVoiceListening(): void {
    this.isListening = !this.isListening;
    if (this.isListening) {
      this.simulateVoiceCommand();
    }
  }

  simulateVoiceCommand(): void {
    this.processing = true;
    this.progressValue = 0;
    const interval = setInterval(() => {
      this.progressValue += 10;
      if (this.progressValue >= 100) {
        clearInterval(interval);
        setTimeout(() => {
          this.processing = false;
          this.marqueeText = 'Voice command processed!';
          this.dataArray = this.dataArray.map(value => value + 5);
        }, 2000);
      }
    }, 200);
  }

  build() {
    Column({ space: 10 }) {
      Text(this.marqueeText)
        .fontSize(20)
        .textOverflow({ overflow: 'MARQUEE' })
        .position({ x: this.marqueePos })
        .width('80%')
        .height(50)
        .backgroundColor(0xFFFFFF)
        .border({ width: 1, color: 0x808080, style: 'solid' })
        .margin(10)
        .padding(10)

      Progress({ value: this.progressValue, total: 100 })
        .width('80%')
        .height(10)
        .color(0x0000FF)
        .margin(10)

      Text(this.isListening ? 'Listening...' : this.processing ? 'Processing...' : 'Idle')
        .fontSize(16)
        .margin(10)

      Button(this.isListening ? 'Stop Listening' : 'Start Listening')
        .onClick(() => this.toggleVoiceListening())
        .width('80%')
        .height(40)
        .backgroundColor(this.isListening ? 0xFF0000 : 0x00FF00)
        .borderRadius(20)
        .margin(10)

      Column({ space: 5 }) {
        ForEach(this.dataArray, (item: number, index: number) => {
          Text(`Data ${index + 1}: ${item}`)
            .fontSize(14)
            .margin(5)
        })
      }
      .width('80%')
      .margin(10)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20)
  }
}

