interface Article {
  id: number;
  title: string;
  content: string;
  image: Resource;
  isRead: boolean;
}

@Entry
@Component
struct RecipeNewsApp {
  @State articles: Article[] = [
    {
      id: 1,
      title: 'Delicious Pasta Recipe',
      content: 'A simple yet delicious pasta recipe that everyone will love.',
      image: $r('app.media.ic_default_image'),
      isRead: false
    },
    {
      id: 2,
      title: 'Healthy Salad Bowl',
      content: 'A refreshing and nutritious salad bowl for a light meal.',
      image: $r('app.media.ic_default_image'),
      isRead: false
    },
    {
      id: 3,
      title: 'Chocolate Cake',
      content: 'A rich and moist chocolate cake recipe for dessert lovers.',
      image: $r('app.media.ic_default_image'),
      isRead: false
    }
  ];

  @State readCount: number = 0;
  @State isDarkMode: boolean = false;

  toggleReadStatus(article: Article): void {
    this.articles = this.articles.map(a => {
      if (a.id === article.id) {
        return {
          id: a.id,
          title: a.title,
          content: a.content,
          image: a.image,
          isRead: !a.isRead
        };
      }
      return a;
    });
    this.readCount = this.articles.filter(a => a.isRead).length;
  }

  toggleTheme(): void {
    this.isDarkMode = !this.isDarkMode;
  }

  build() {
    Column() {
      Row() {
        Text('Recipe News')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20, bottom: 20 })
