        Button(this.isDarkMode ? 'Light Mode' : 'Dark Mode')
          .onClick(() => this.toggleTheme())
          .margin({ right: 20 });
      }

      Text(`Read: ${this.readCount}/${this.articles.length}`)
        .fontSize(16)
        .margin({ bottom: 10 });

      Scroll() {
        List() {
          ForEach(this.articles, (article: Article) => {
            ListItem() {
              Column() {
                Image(article.image)
                  .width('100%')
                  .height(150)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(8);

                Text(article.title)
                  .fontSize(18)
                  .fontWeight(FontWeight.Bold)
                  .margin({ top: 8 });

                Text(article.content)
