                Button(article.isRead ? 'Read' : 'Mark as Read')
                  .onClick(() => this.toggleReadStatus(article))
                  .width('100%');
              }
              .padding(16)
              .backgroundColor(this.isDarkMode ? '#333333' : '#FFFFFF')
              .borderRadius(8)
              .margin({ bottom: 16 });
            }
          });
        }
        .width('100%')
        .listDirection(Axis.Vertical);
      }
      .width('100%')
      .height('100%')
      .padding(16);
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.isDarkMode ? '#1A1A1A' : '#F5F5F5');
  }
}

