interface EventItem {
  title: string;
  content: string;
}

@Entry
@Component
struct EventPlannerApp {
  private controller: CanvasRenderingContext2D = new CanvasRenderingContext2D();

  @State events: Array<EventItem> = [
    { title: "Meeting", content: "Discuss project updates" },
    { title: "Lunch", content: "Team lunch at 12 PM" },
    { title: "Workout", content: "Gym session at 5 PM" }
  ];

  @State currentEventIndex: number = 0;
  @State isPlaying: boolean = false;
  @State canvasScale: number = 1;

  build() {
    Row() {
      Column({ space: 10 }) {
        ForEach(this.events, (event: EventItem, index: number) => {
          Row() {
            Text(event.title)
              .fontSize(16)
              .fontWeight(FontWeight.Bold)
              .onClick(() => {
                animateTo({
                  duration: 300,
                  curve: Curve.EaseInOut
                }, () => {
                  this.currentEventIndex = index;
                  this.canvasScale = 1.1;
                });
                setTimeout(() => {
                  animateTo({
                    duration: 300,
                    curve: Curve.EaseInOut
                  }, () => {
                    this.canvasScale = 1;
                  });
                }, 300);
              })
          }
          .width('100%')
          .padding(10)
          .borderRadius(8)
          .backgroundColor('#FFFFFF')
        })

        Row({ space: 20 }) {
          Button(this.isPlaying ? "Pause" : "Play")
            .width(80)
            .height(40)
            .onClick(() => {
              this.isPlaying = !this.isPlaying;
            })
          Button("Next")
            .width(80)
            .height(40)
            .onClick(() => {
              animateTo({
                duration: 300,
                curve: Curve.EaseInOut
              }, () => {
                this.currentEventIndex = (this.currentEventIndex + 1) % this.events.length;
                this.canvasScale = 1.1;
              });
              setTimeout(() => {
                animateTo({
                  duration: 300,
                  curve: Curve.EaseInOut
                }, () => {
                  this.canvasScale = 1;
                });
              }, 300);
            })
        }
        .margin({ top: 20 })
      }
      .width('40%')
      .height('100%')
      .padding(10)

      Stack() {
        Canvas(this.controller)
          .width('100%')
          .height('100%')
          .scale({ x: this.canvasScale, y: this.canvasScale })
          .onReady(() => {
            this.controller.fillStyle = '#FFA500';
            this.controller.fillRect(0, 0, 100, 100);
          })
      }
      .width('60%')
      .height('100%')
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

import vibrator from '@ohos.vibrator';
import { ActionSheet } from '@ohos.arkui.advanced';
import { Rating } from '@ohos.arkui.advanced';

@Entry
@Component
struct MainPage {
  @State ratingValue: number = 0;

  private async tryVibrate(): Promise<void> {
    try {
      if (vibrator.hasVibrator()) {
        await vibrator.vibrate({
          duration: 100,
          effectId: 'time'
        });
      }
    } catch (err) {
      console.error('Vibration failed:', err);
    }
  }

  showActionSheet(): void {
    this.tryVibrate();

    ActionSheet.show({
      title: 'Choose an Option',
      buttons: [
        {
          text: 'Option 1',
          action: () => {
            this.tryVibrate();
            console.log('Option 1 selected');
          }
        },
        {
          text: 'Option 2',
          action: () => {
            this.tryVibrate();
            console.log('Option 2 selected');
          }
        },
        {
          text: 'Cancel',
          role: 'cancel',
          action: () => {
            this.tryVibrate();
            console.log('ActionSheet canceled');
          }
        }
      ]
    });
  }

  onRatingChange(newValue: number): void {
    this.ratingValue = newValue;
    this.tryVibrate();
  }

  build() {
    Column() {
      Button('Show ActionSheet')
        .onClick(() => this.showActionSheet())
        .margin(20)
        .width('80%')
        .height(50)

      Rating({
        rating: this.ratingValue,
        indicator: false
      })
      .starStyle({
        backgroundUri: $r('app.media.star_off'),
        foregroundUri: $r('app.media.star_on'),
        secondaryUri: $r('app.media.star_half')
      })
      .starCount(5)
      .stepSize(0.5)
      .onChange((newValue: number) => this.onRatingChange(newValue))
      .margin(20)
      .width('80%')
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

