            if (index < this.orderStatus.length - 1) {
              Divider()
                .strokeWidth(2)
                .color(index < this.currentStatusIndex ? Color.Blue : Color.Gray)
                .margin({ top: 10, bottom: 10 });
            }
          }
          .margin({ left: 20, right: 20 });
        });
      }
      .width('100%')
      .margin({ top: 20 });

      Button('Update Status')
        .onClick(() => {
          if (this.currentStatusIndex < this.orderStatus.length - 1) {
            this.currentStatusIndex++;
          }
        })
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#f5f5f5');
  }
}

