import promptAction from '@ohos.promptAction';
import common from '@ohos.app.ability.common';
import { Button, Text, Column, Stack } from '@ohos.arkui.advanced';
import ConfigurationConstant from '@ohos.app.ability.ConfigurationConstant';

enum ThemeMode {
  LIGHT = 'light',
  DARK = 'dark',
  UNSPECIFIED = 'auto'
}

interface ActionSheetItem {
  text: string;
  color: string;
}

interface ActionSheetResult {
  index: number;
}

interface Configuration {
  colorMode: string;
  fontScale: number;
}

@Entry
@Component
struct ThemeSwitcher {
  @State currentTheme: string = 'Auto';
  @State themeMode: ThemeMode = ThemeMode.UNSPECIFIED;
  @State abilityContext: common.Context = getContext(this) as common.Context;

  build() {
    Stack() {
      Column({ space: 20 }) {
        Button('Change Theme')
          .onClick(() => {
            promptAction.showActionMenu({
              title: 'Select Theme',
              buttons: [
                { text: 'Light', color: '#000000' },
                { text: 'Dark', color: '#000000' },
                { text: 'Auto', color: '#000000' }
              ],
              callback: (err: Error, selected: ActionSheetResult) => {
                if (err) {
                  promptAction.showToast({ message: 'Theme selection failed' });
                  return;
                }
                const themes = ['Light', 'Dark', 'Auto'];
                this.currentTheme = themes[selected.index];
                this.updateTheme(this.currentTheme);
                promptAction.showToast({ message: `Theme set to ${this.currentTheme}` });
              }
            });
          })
          .margin({ top: 20 });

        Text(`Current Theme: ${this.currentTheme}`)
          .fontSize(18)
          .margin({ top: 20 });
      }
      .width('100%')
      .height('100%')
      .justifyContent(FlexAlign.Center);
    }
  }

  private updateTheme(theme: string) {
    try {
      let config: Configuration = {
        colorMode: theme === 'Light' ? 'light' :
                 theme === 'Dark' ? 'dark' :
                 'auto',
        fontScale: 1.0
      };
      this.abilityContext.updateConfiguration(config);
      this.themeMode = theme === 'Light' ? ThemeMode.LIGHT : 
                      theme === 'Dark' ? ThemeMode.DARK : ThemeMode.UNSPECIFIED;
    } catch (error) {
      promptAction.showToast({ message: 'Failed to update theme' });
    }
  }
}

@Entry
@Component
struct VideoSearchApp {
  @State searchText: string = '';
  @State isLoggedIn: boolean = false;
  @State username: string = '';
  @State password: string = '';
  @State searchResults: string[] = ['Video 1', 'Video 2', 'Video 3', 'Video 4', 'Video 5'];

  filterResults(): string[] {
    if (this.searchText.trim() === '') {
      return this.searchResults;
    } else {
      return this.searchResults.filter(item =>
        item.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  handleLogin() {
    if (this.username && this.password) {
      this.isLoggedIn = true;
    }
  }

  handleLogout() {
    this.isLoggedIn = false;
    this.username = '';
    this.password = '';
  }

  build() {
    Column() {
      if (!this.isLoggedIn) {
        // Login UI
        Column() {
          Text('Login')
            .fontSize(24)
            .margin({ bottom: 20 });

          TextInput({ placeholder: 'Username', text: this.username })
            .width('80%')
            .height(40)
            .margin({ bottom: 10 })
            .onChange((value: string) => {
              this.username = value;
            });

          TextInput({ placeholder: 'Password', text: this.password })
            .width('80%')
            .height(40)
            .margin({ bottom: 20 })
            .type(InputType.Password)
            .onChange((value: string) => {
              this.password = value;
            });

          Button('Login', { type: ButtonType.Capsule })
            .width('80%')
            .height(40)
            .onClick(() => {
              this.handleLogin();
            });
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center);
      } else {
        // Search UI
        Column() {
          Row() {
            Text('Welcome, ' + this.username)
              .fontSize(18)
              .margin({ right: 10 });

            Button('Logout', { type: ButtonType.Capsule })
              .onClick(() => {
                this.handleLogout();
              });
          }
          .width('100%')
          .justifyContent(FlexAlign.SpaceBetween)
          .margin({ bottom: 20 });

          TextInput({ placeholder: 'Search videos...', text: this.searchText })
            .width('90%')
            .height(40)
            .onChange((value: string) => {
              this.searchText = value;
            })
            .margin({ bottom: 16 });

          if (this.filterResults().length > 0) {
            List() {
              ForEach(this.filterResults(), (item: string) => {
                ListItem() {
                  Text(item)
                    .fontSize(18)
                    .padding(12);
                }
              }, (item: string) => item);
            }
          } else {
            Text('No results found')
              .fontSize(16)
              .fontColor(Color.Gray)
              .padding(16);
          }
        }
        .width('100%')
        .height('100%');
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

import webview from '@ohos.web.webview';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct WebViewWithPerformance {
  private webController: webview.WebviewController = new webview.WebviewController();
  @State loadingTime: number = 0;
  @State memoryUsage: string = '0 MB';
  @State cpuUsage: string = '0%';
  @State isMonitoring: boolean = false;
  @State startTime: number = 0;
  private intervalId: number = -1;

  aboutToAppear() {
    this.startPerformanceMonitoring();
  }

  aboutToDisappear() {
    if (this.intervalId !== -1) {
      clearInterval(this.intervalId);
    }
  }

  startPerformanceMonitoring() {
    this.isMonitoring = true;
    this.intervalId = setInterval(() => {
      this.loadingTime = (Date.now() - this.startTime) / 1000;
      this.memoryUsage = `${(Math.random() * 100).toFixed(2)} MB`;
      this.cpuUsage = `${(Math.random() * 100).toFixed(2)}%`;
    }, 1000);
  }

  stopPerformanceMonitoring() {
    this.isMonitoring = false;
    if (this.intervalId !== -1) {
      clearInterval(this.intervalId);
      this.intervalId = -1;
    }
    promptAction.showToast({
      message: 'Performance monitoring stopped',
      duration: 2000
    });
  }

  build() {
    Column({ space: 20 }) {
      Web({
        src: 'https://www.example.com',
        controller: this.webController
      })
      .width('100%')
      .height('60%')
      .onPageEnd(() => {
        this.startTime = Date.now();
      });

      Column({ space: 10 }) {
        Row() {
          Text('Loading Time:')
            .fontSize(18)
            .fontColor(Color.Gray);
          Text(`${this.loadingTime.toFixed(2)}s`)
            .fontSize(18)
            .fontColor(Color.Blue)
            .margin({ left: 10 });
        }

        Row() {
          Text('Memory Usage:')
            .fontSize(18)
            .fontColor(Color.Gray);
          Text(this.memoryUsage)
            .fontSize(18)
            .fontColor(Color.Blue)
            .margin({ left: 10 });
        }

        Row() {
          Text('CPU Usage:')
            .fontSize(18)
            .fontColor(Color.Gray);
          Text(this.cpuUsage)
            .fontSize(18)
            .fontColor(Color.Blue)
            .margin({ left: 10 });
        }
      }
      .width('80%')
      .padding(20)
      .borderRadius(10)
      .backgroundColor(Color.White)
      .shadow({ radius: 10, color: Color.Gray, offsetX: 2, offsetY: 2 });

      if (!this.isMonitoring) {
        Button('Start Monitoring')
          .width(200)
          .height(50)
          .backgroundColor(Color.Green)
          .fontColor(Color.White)
          .onClick(() => {
            this.startPerformanceMonitoring();
          });
      } else {
        Button('Stop Monitoring')
          .width(200)
          .height(50)
          .backgroundColor(Color.Red)
          .fontColor(Color.White)
          .onClick(() => {
            this.stopPerformanceMonitoring();
          });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#F5F5F5');
  }
}

