@Entry
@Component
struct MovieTicketBookingApp {
  @State selectedMovie: Movie | null = null;
  @State selectedSeats: Seat[] = [];
  @State showError: boolean = false;
  @State seats: Seat[] = [
    { id: 1, row: 'A', number: 1, isSelected: false, isAvailable: true },
    { id: 2, row: 'A', number: 2, isSelected: false, isAvailable: true },
    { id: 3, row: 'A', number: 3, isSelected: false, isAvailable: false },
    { id: 4, row: 'B', number: 1, isSelected: false, isAvailable: true },
    { id: 5, row: 'B', number: 2, isSelected: false, isAvailable: true },
    { id: 6, row: 'B', number: 3, isSelected: false, isAvailable: false },
    { id: 7, row: 'C', number: 1, isSelected: false, isAvailable: true },
    { id: 8, row: 'C', number: 2, isSelected: false, isAvailable: true },
    { id: 9, row: 'C', number: 3, isSelected: false, isAvailable: false },
  ];

  build() {
    if (this.selectedMovie == null) {
      Column() {
        Text('Movie List')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .padding(16);

        Scroll() {
          Row() {
            ForEach(movies, (movie: Movie) => {
              Column() {
                Image(movie.poster)
                  .width(150)
                  .height(200)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(8)
                  .margin(10);
                Text(movie.title)
                  .fontSize(18)
                  .fontWeight(FontWeight.Medium)
                  .margin({ bottom: 4 });
                Text(`Release Date: ${movie.releaseDate}`)
                  .fontSize(14)
                  .margin({ bottom: 4 });
                Text(`Director: ${movie.director}`)
                  .fontSize(14)
                  .margin({ bottom: 8 });
              }
              .onClick(() => {
                this.selectedMovie = movie;
                this.selectedSeats = [];
              });
            });
          }
          .padding(10);
        }
      }
    } else {
      Column() {
        Text(this.selectedMovie.title)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .padding(16);

        Image(this.selectedMovie.poster)
          .width('100%')
          .height(300)
          .objectFit(ImageFit.Cover)
          .padding({ bottom: 16 });

        Text(`Release Date: ${this.selectedMovie.releaseDate}`)
          .fontSize(18)
          .padding({ left: 16, right: 16, bottom: 8 });

        Text(`Director: ${this.selectedMovie.director}`)
          .fontSize(18)
          .padding({ left: 16, right: 16, bottom: 16 });

        Text('Select Seats')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .padding({ left: 16, right: 16, bottom: 8 });

        Grid() {
          ForEach(this.seats, (seat: Seat) => {
            GridItem() {
              Column() {
                Text(`${seat.row}${seat.number}`)
                  .fontSize(16)
                  .fontWeight(FontWeight.Medium);
              }
              .width(50)
              .height(50)
              .borderRadius(4)
              .backgroundColor(seat.isAvailable ? (seat.isSelected ? '#4CAF50' : '#FFFFFF') : '#CCCCCC')
              .border({ width: 1, color: '#000000' })
              .onClick(() => {
                if (seat.isAvailable) {
                  this.seats = this.seats.map(s => {
                    if (s.id === seat.id) {
                      return {
                        id: s.id,
                        row: s.row,
                        number: s.number,
                        isSelected: !s.isSelected,
                        isAvailable: s.isAvailable
                      };
                    }
                    return s;
                  });
                  this.selectedSeats = this.seats.filter(s => s.isSelected);
                }
              });
            }
          });
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsTemplate('1fr 1fr 1fr')
        .padding(16);

        if (this.showError) {
          Text('Please select at least one seat.')
            .fontSize(16)
            .fontColor('#FF0000')
            .padding({ left: 16, right: 16, bottom: 8 });
        }

        Button('Book Tickets')
          .onClick(() => {
            if (this.selectedSeats.length === 0) {
              this.showError = true;
            } else {
              this.showError = false;
              router.pushUrl({
                url: 'pages/confirmation',
                params: { movie: this.selectedMovie, seats: this.selectedSeats }
              });
            }
          })
          .padding(16);

        Button('Back')
          .onClick(() => {
            this.selectedMovie = null;
            this.selectedSeats = [];
            this.showError = false;
          })
          .padding(16);
      }
    }
  }
}

interface PostOption {
  label: string;
  selected: boolean;
}

@Entry
@Component
struct SocialMediaPostCreator {
  @State private selectedFiles: string[] = [];
  @State private uploadProgress: number = 0;
  @State private isUploading: boolean = false;
  @State private errorMessage: string = '';
  @State private options: PostOption[] = [
    { label: 'Public', selected: false },
    { label: 'Friends Only', selected: false },
    { label: 'Private', selected: false }
  ];

  private async handleFileSelection(): Promise<void> {
    try {
      const files: string[] = ['file1.jpg', 'file2.jpg'];
      this.selectedFiles = files;
      this.errorMessage = '';
    } catch (error) {
      this.errorMessage = 'Failed to select files. Please try again.';
    }
  }

  private async handleUpload(): Promise<void> {
    if (this.selectedFiles.length === 0) {
      this.errorMessage = 'No files selected.';
      return;
    }

    this.isUploading = true;
    this.uploadProgress = 0;

    try {
      for (let i = 0; i < this.selectedFiles.length; i++) {
        const file: string = this.selectedFiles[i];
        for (let progress = 0; progress <= 100; progress += 10) {
          await new Promise<void>((resolve) => setTimeout(resolve, 100));
          this.uploadProgress = progress;
        }
      }
      this.errorMessage = '';
      this.isUploading = false;
      this.selectedFiles = [];
    } catch (error) {
      this.errorMessage = 'Upload failed. Please check your connection and try again.';
      this.isUploading = false;
    }
  }

  private toggleOption(index: number): void {
    this.options[index].selected = !this.options[index].selected;
  }

  build() {
    Column({ space: 10 }) {
      Text('Create a Post')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(16)
          .fontColor(Color.Red)
          .margin({ bottom: 20 });
      }

      Row({ space: 10 }) {
        ForEach(this.options, (option: PostOption, index: number) => {
          Row() {
            Text(option.label)
              .fontSize(16)
              .margin({ right: 10 });
            Checkbox()
              .select(option.selected)
              .onChange(() => this.toggleOption(index));
          }
        });
      }
      .margin({ bottom: 20 });

      Button('Select Files')
        .width(200)
        .onClick(() => this.handleFileSelection())
        .enabled(!this.isUploading)
        .margin({ bottom: 20 });

      if (this.selectedFiles.length > 0) {
        Column() {
          ForEach(this.selectedFiles, (file: string) => {
            Text(file)
              .fontSize(14)
              .margin({ bottom: 5 });
          });
        }
        .margin({ bottom: 20 });
      }

      Button('Upload')
        .width(200)
        .onClick(() => this.handleUpload())
        .enabled(!this.isUploading && this.selectedFiles.length > 0)
        .margin({ bottom: 20 });

      if (this.isUploading) {
        Progress({ value: this.uploadProgress, total: 100 })
          .width(300)
          .margin({ bottom: 20 });

        Text(`Uploading: ${this.uploadProgress}%`)
          .fontSize(14)
          .margin({ bottom: 20 });
      }
    }
    .width('100%')
    .padding(20);
  }
}

