import promptAction from '@ohos.promptAction';

@Entry
@Component
struct CountdownTimer {
  @State timeLeft: number = 60
  @State timerId: number = -1
  @State isCounting: boolean = false

  build() {
    Column() {
      Text(`Time left: ${this.timeLeft} seconds`)
        .fontSize(30)
        .margin({ bottom: 20 })
        .accessibilityText(`Time left: ${this.timeLeft} seconds`)

      Row() {
        Button(this.isCounting ? 'Stop' : 'Start')
          .onClick(() => {
            if (this.isCounting) {
              clearInterval(this.timerId)
              this.isCounting = false
            } else {
              this.isCounting = true
              this.startTimer()
            }
          })
          .focusable(true)
          .focusOnTouch(true)
          .accessibilityText(this.isCounting ? 'Stop countdown' : 'Start countdown')
          .backgroundColor(this.isCounting ? '#FF0000' : '#00FF00')
          .borderRadius(8)
          .padding(10)
          .margin(5)

        Button('Reset')
          .onClick(() => {
            clearInterval(this.timerId)
            this.timeLeft = 60
            this.isCounting = false
          })
          .focusable(true)
          .focusOnTouch(true)
          .accessibilityText('Reset countdown')
          .backgroundColor('#0000FF')
          .borderRadius(8)
          .padding(10)
          .margin(5)
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }

  startTimer() {
    this.timerId = setInterval(() => {
      if (this.timeLeft > 0) {
        this.timeLeft -= 1
      } else {
        clearInterval(this.timerId)
        this.isCounting = false
        promptAction.showToast({
          message: 'The countdown has finished!',
          duration: 2000
        })
      }
    }, 1000)
  }
}

