import { Tabs, TabContent } from '@ohos.arkui.advanced';

interface Project {
  name: string;
  color: Color;
  status: 'Active' | 'Pending' | 'Completed';
}

@Entry
@Component
struct ProjectManagementApp {
  @State projects: Project[] = [
    { name: 'Project A', color: Color.Red, status: 'Active' },
    { name: 'Project B', color: Color.Green, status: 'Pending' },
    { name: 'Project C', color: Color.Blue, status: 'Completed' }
  ];
  @State filterStatus: 'All' | 'Active' | 'Pending' | 'Completed' = 'All';
  @State newProjectName: string = '';
  @State newProjectColor: Color = Color.Black;
  @State newProjectStatus: 'Active' | 'Pending' | 'Completed' = 'Active';

  build() {
    Column({ space: 10 }) {
      Tabs({ barPosition: 'start' }) {
        TabContent() {
        }.tabBar('All').onClick(() => { this.filterStatus = 'All'; });
        TabContent() {
        }.tabBar('Active').onClick(() => { this.filterStatus = 'Active'; });
        TabContent() {
        }.tabBar('Pending').onClick(() => { this.filterStatus = 'Pending'; });
        TabContent() {
        }.tabBar('Completed').onClick(() => { this.filterStatus = 'Completed'; });
      }

      List({ space: 10 }) {
        ForEach(this.filteredProjects, (project: Project) => {
          ListItem() {
            Flex({ justifyContent: FlexAlign.SpaceBetween, alignItems: FlexAlign.Center }) {
              Text(project.name).fontSize(16);
              Text(project.status).fontSize(14).fontColor(Color.Gray);
            }
            .backgroundColor(project.color)
            .padding(10)
            .borderRadius(5)
            .width('100%');
          }
        });
      }

      Column({ space: 10 }) {
        TextInput({ placeholder: 'Project Name', text: this.newProjectName })
          .onChange((value: string) => { this.newProjectName = value; })
          .width('80%');

        Text('Select Color:').fontSize(14);
        TextInput({ placeholder: 'Color (e.g., Red, Green, Blue)', text: this.newProjectColor.toString() })
          .onChange((value: string) => { 
            switch(value.toLowerCase()) {
              case 'red': this.newProjectColor = Color.Red; break;
              case 'green': this.newProjectColor = Color.Green; break;
              case 'blue': this.newProjectColor = Color.Blue; break;
              default: this.newProjectColor = Color.Black;
            }
          })
          .width('80%');

        Tabs({ barPosition: 'start' }) {
          TabContent() {
          }.tabBar('Active').onClick(() => { this.newProjectStatus = 'Active'; });
          TabContent() {
          }.tabBar('Pending').onClick(() => { this.newProjectStatus = 'Pending'; });
          TabContent() {
          }.tabBar('Completed').onClick(() => { this.newProjectStatus = 'Completed'; });
        }

        Button('Add Project')
          .onClick(() => {
            if (this.newProjectName.trim() === '') return;
            this.projects.push({
              name: this.newProjectName,
              color: this.newProjectColor,
              status: this.newProjectStatus
            });
            this.newProjectName = '';
            this.newProjectColor = Color.Black;
            this.newProjectStatus = 'Active';
          })
          .width('50%');

        Button('Refresh')
          .onClick(() => {
            this.projects = [...this.projects];
          })
          .width('50%');
      }
      .padding(10)
      .width('100%');
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }

  get filteredProjects(): Project[] {
    return this.filterStatus === 'All'
      ? this.projects
      : this.projects.filter(project => project.status === this.filterStatus);
  }
}

import { Stepper, StepperItem } from '@ohos.arkui.advanced.Components';
import { PanGesture } from '@ohos.arkui.gesture';
import curves from '@ohos.curves';

interface Step {
  title: string;
  image: Resource;
}

@Entry
@Component
struct StepperApp {
  @State currentStep: number = 1;
  @State steps: Step[] = [
    { title: "Step 1", image: $r('app.media.step1') },
    { title: "Step 2", image: $r('app.media.step2') },
    { title: "Step 3", image: $r('app.media.step3') },
    { title: "Step 4", image: $r('app.media.step4') }
  ];

  build() {
    Column() {
      Stepper({ current: this.currentStep }) {
        ForEach(this.steps, (step: Step, index: number) => {
          StepperItem() {
            Column() {
              Text(step.title)
                .fontSize(24)
                .margin({ bottom: 20 });
              Image(step.image)
                .width(200)
                .height(200)
                .margin({ bottom: 20 });
            }
            .width('100%')
            .height('100%')
            .justifyContent(FlexAlign.Center)
            .alignItems(HorizontalAlign.Center)
          }
        })
      }
      .onChange((index: number) => {
        this.currentStep = index + 1;
        console.log(`Step changed to: ${this.currentStep}`);
      })

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentStep > 1) {
              this.currentStep--;
              console.log(`Navigated to step: ${this.currentStep}`);
            }
          })
          .enabled(this.currentStep > 1)
          .margin({ right: 20 });

        Button('Next')
          .onClick(() => {
            if (this.currentStep < this.steps.length) {
              this.currentStep++;
              console.log(`Navigated to step: ${this.currentStep}`);
            }
          })
          .enabled(this.currentStep < this.steps.length)
      }
      .margin({ top: 20 })
      .justifyContent(FlexAlign.Center)
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

