import { Grid, GridItem } from '@ohos.arkui.advanced';

@Entry
@Component
struct InfiniteScrollGrid {
  @State items: GridItemData[] = [];
  private loading: boolean = false;

  aboutToAppear() {
    this.loadItems();
  }

  loadItems() {
    if (this.loading) return;
    this.loading = true;
    setTimeout(() => {
      const newItems: GridItemData[] = [];
      const startIndex = this.items.length + 1;
      for (let i = startIndex; i < startIndex + 10; i++) {
        newItems.push({
          id: i,
          title: `Item ${i}`,
          rating: Math.floor(Math.random() * 5) + 1,
          loading: false
        });
      }
      this.items = [...this.items, ...newItems];
      this.loading = false;
    }, 1000);
  }

  build() {
    Column() {
      Grid() {
        ForEach(this.items, (item: GridItemData) => {
          GridItem() {
            if (item.loading) {
              Column()
                .width('100%')
                .height('100%')
                .backgroundColor('#f0f0f0')
                .border({ width: 1, color: '#cccccc' });
            } else {
              Column() {
                Text(item.title)
                  .fontSize(16)
                  .textAlign(TextAlign.Center);
                Text('\u2605'.repeat(item.rating))
                  .fontSize(16)
                  .textAlign(TextAlign.Center);
              }
              .width('100%')
              .height('100%')
              .justifyContent(FlexAlign.Center);
            }
          }
          .aspectRatio(1);
        })
      }
      .columnsTemplate('1fr 1fr')
      .columnsGap(10)
      .rowsGap(10)
      .onScrollIndex((firstIndex: number) => {
        const triggerPoint = this.items.length - 4;
        if (firstIndex >= triggerPoint) {
          this.loadItems();
        }
      })
      .scrollBar(BarState.On);
    }
    .width('100%')
    .height('100%');
  }
}

interface GridItemData {
  id: number;
  title: string;
  rating: number;
  loading: boolean;
}

import { Stack, Column, Row, Text, Button } from '@ohos.arkui';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct MultiStepProcess {
  @State currentStep: number = 1;
  @State isProcessActive: boolean = false;
  private totalSteps: number = 4;

  @Builder
  StepCircle(step: number) {
    Stack() {
      Circle()
        .width(40)
        .height(40)
        .fillColor(this.currentStep >= step ? '#000000' : '#999999');
      Text(step.toString())
        .fontSize(20)
        .fontColor('#FFFFFF');
    }
  }

  private showActionMenu() {
    promptAction.showActionMenu({
      title: `Current Step: ${this.currentStep}`,
      buttons: [
        {
          text: 'Next',
          color: this.currentStep >= this.totalSteps ? '#999999' : '#000000'
        },
        {
          text: 'Cancel',
          color: '#000000'
        }
      ]
    }).then((button) => {
      if (button.index === 0 && this.currentStep < this.totalSteps) {
        this.currentStep++;
      } else if (button.index === 1) {
        this.currentStep = 1;
        this.isProcessActive = false;
      }
    });
  }

  build() {
    Stack() {
      Column() {
        Row() {
          ForEach([1, 2, 3, 4], (step: number) => {
            Column() {
              this.StepCircle(step);
              Text(`Step ${step}`)
                .fontSize(16)
                .margin({ top: 10 })
                .fontColor(this.currentStep >= step ? '#000000' : '#999999');
            }

            if (step < this.totalSteps) {
              Row()
                .width(50)
                .height(2)
                .backgroundColor(this.currentStep > step ? '#000000' : '#999999');
            }
          });
        }
        .margin({ top: 50, bottom: 50 });

        Row() {
          Button('Start Process')
            .onClick(() => {
              this.currentStep = 1;
              this.isProcessActive = true;
              this.showActionMenu();
            })
            .enabled(!this.isProcessActive)
            .margin({ right: 20 });

          Button('Cancel Process')
            .onClick(() => {
              this.currentStep = 1;
              this.isProcessActive = false;
            })
            .enabled(this.isProcessActive);
        }
      }
      .width('100%')
      .padding(20);
    }
  }
}

