import { Slider, PanGesture, PanGestureEvent, FlexAlign } from '@ohos.arkui.component';
import { animateTo, Curve } from '@ohos.arkui.animation';

@Entry
@Component
struct EncryptionSlider {
  @State sliderValue: number = 0;
  @State opacityValue: number = 1.0;
  @State isSliding: boolean = false;

  build() {
    Column() {
      Text('Encryption Level')
        .fontSize(18)
        .margin({ bottom: 10 });

      Text(`${this.sliderValue}%`)
        .fontSize(16)
        .opacity(this.opacityValue)
        .margin({ bottom: 20 });

      Row() {
        Slider({
          min: 0,
          max: 100,
          value: this.sliderValue,
          step: 1
        })
          .width('80%')
          .height(50)
          .onChange((value: number) => {
            this.sliderValue = value;
          })
          .gesture(
            PanGesture()
              .onActionStart(() => {
                this.isSliding = true;
                this.opacityValue = 0.7;
              })
              .onActionUpdate((event: PanGestureEvent) => {
                this.sliderValue = Math.min(100, Math.max(0, event.offsetX / 0.8));
              })
              .onActionEnd(() => {
                this.isSliding = false;
                animateTo({
                  duration: 300,
                  curve: Curve.EaseOut
                }, () => {
                  this.sliderValue = Math.round(this.sliderValue);
                  this.opacityValue = 1.0;
                });
              })
          )
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .padding(20)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

