@Entry
@Component
struct AuthListWithGesture {
  @State private data: string[] = ['Item 1', 'Item 2', 'Item 3'];
  @State private isRefreshing: boolean = false;
  @State private isAuthenticated: boolean = false;
  @State private showBiometricUI: boolean = false;

  private refreshData() {
    this.isRefreshing = true;
    setTimeout(() => {
      this.data = ['New Item 1', 'New Item 2', 'New Item 3', ...this.data];
      this.isRefreshing = false;
    }, 2000);
  }

  private handleGesture() {
    this.showBiometricUI = true;
    setTimeout(() => {
      this.isAuthenticated = true;
      this.showBiometricUI = false;
    }, 1500);
  }

  build() {
    Column() {
      if (this.showBiometricUI) {
        Column() {
          Image($r('app.media.app_icon'))
            .width(100)
            .height(100)
            .margin({ bottom: 20 });
          Text('Authenticating...')
            .fontSize(18)
            .fontWeight(FontWeight.Bold);
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center)
        .backgroundColor('#F5F5F5');
      } else {
        List() {
          ForEach(this.data, (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(16)
                .padding(10);
            }
            .gesture(
              TapGesture()
                .onAction(() => {
                  this.handleGesture();
                })
            );
          });
        }
        .height('80%')
        .onScrollIndex((start: number, end: number) => {
          if (start < -100 && !this.isRefreshing) {
            this.refreshData();
          }
        });

        if (this.isRefreshing) {
          Text('Refreshing...')
            .fontSize(16)
            .padding(10);
        }
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

