import { Refresh, Popup } from '@ohos.arkui.component';
import { animateTo, Curves } from '@ohos.arkui.ability.animator';

@Entry
@Component
struct VideoApp {
  @State isDarkTheme: boolean = false;
  @State showThemePopup: boolean = false;
  @State refreshing: boolean = false;
  @State videoPlaceholderClicked: boolean = false;
  @State items: string[] = ['Item 1', 'Item 2', 'Item 3'];
  private timerId: number | null = null;

  build() {
    Column() {
      Image($r('app.media.icon'))
        .width(200)
        .height(150)
        .opacity(this.videoPlaceholderClicked ? 0.7 : 1)
        .scale({ x: this.videoPlaceholderClicked ? 0.9 : 1, y: this.videoPlaceholderClicked ? 0.9 : 1 })
        .onClick(() => {
          animateTo({
            duration: 300,
            curve: Curves.EASE_IN_OUT
          }, () => {
            this.videoPlaceholderClicked = !this.videoPlaceholderClicked;
          });
        });

      Button(this.isDarkTheme ? 'Switch to Light Theme' : 'Switch to Dark Theme')
        .onClick(() => {
          this.showThemePopup = true;
        });

      if (this.showThemePopup) {
        Popup({
          placement: 'bottom',
          onDismiss: () => {
            this.showThemePopup = false;
          }
        }) {
          Column() {
            Button('Light Theme')
              .onClick(() => {
                this.isDarkTheme = false;
                this.showThemePopup = false;
              });
            Button('Dark Theme')
              .onClick(() => {
                this.isDarkTheme = true;
                this.showThemePopup = false;
              });
          }
          .width('100%')
          .padding(20)
        }
      }

      Refresh({ refreshing: $$this.refreshing, friction: 100 }) {
        List() {
          ForEach(this.items, (item: string) => {
            ListItem() {
              Text(item)
                .width('100%')
                .height(50)
                .fontSize(16)
                .textAlign(TextAlign.Center)
                .backgroundColor(this.isDarkTheme ? '#333333' : '#f5f5f5')
                .margin({ top: 10 });
            }
          });
        }
        .width('100%')
        .height('100%');
      }
      .onRefreshing(() => {
        this.timerId = setTimeout(() => {
          this.items = ['New Item ' + (this.items.length + 1), ...this.items];
          this.refreshing = false;
        }, 2000);
      });

      Column()
        .width('100%')
        .height('100%')
        .backgroundColor(this.isDarkTheme ? '#222222' : '#ffffff');
    }
    .width('100%')
    .height('100%');
  }

  aboutToDisappear() {
    if (this.timerId !== null) {
      clearTimeout(this.timerId);
      this.timerId = null;
    }
  }
}

import { Column, Row, Button, Text, Stack } from '@ohos.arkui.UIContext';
import { Select } from '@ohos.arkui.UIContext';
import { ForEach } from '@ohos.arkui.UIContext';
import { PanGesture } from '@ohos.arkui.UIContext';
import { animateTo, Easing } from '@ohos.animation';
import { Color, FlexAlign, FontWeight } from '@ohos.arkui.UIContext';

interface SelectOption {
  value: string;
  label: string;
}

interface PanGestureEvent {
  offsetX: number;
  offsetY: number;
  velocityX: number;
  velocityY: number;
}

@Entry
@Component
struct SegmentedControlApp {
  @State selectedIndex: number = 0;
  private segmentLabels: string[] = ['Segment 1', 'Segment 2', 'Segment 3'];
  @State offsetX: number = 0;

  private handleButtonClick(index: number): void {
    animateTo({ duration: 300 }, () => {
      this.selectedIndex = index;
    });
  }

  private handleSwipe(event: PanGestureEvent): void {
    this.offsetX = event.offsetX;
  }

  private handleSwipeEnd(): void {
    if (Math.abs(this.offsetX) > 100) {
      const direction = this.offsetX > 0 ? -1 : 1;
      const newIndex = Math.max(0, Math.min(this.segmentLabels.length - 1, this.selectedIndex + direction));
      animateTo({ duration: 300 }, () => {
        this.selectedIndex = newIndex;
        this.offsetX = 0;
      });
    } else {
      animateTo({ duration: 300 }, () => {
        this.offsetX = 0;
      });
    }
  }

  build() {
    Column({ space: 20 }) {
      Row({ space: 10 }) {
        ForEach(this.segmentLabels, (label: string, index: number) => {
          Button(label)
            .backgroundColor(this.selectedIndex === index ? '#007AFF' : '#808080')
            .fontColor('#FFFFFF')
            .borderRadius(8)
            .onClick(() => this.handleButtonClick(index))
            .animation({ duration: 300, curve: Easing.InOut })
        })
      }
      .justifyContent(FlexAlign.Center)
      .margin({ bottom: 20 })

      Stack() {
        Column() {
          Text(`Content for ${this.segmentLabels[this.selectedIndex]}`)
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ top: 20 })
        }
        .width('100%')
        .height(200)
        .backgroundColor('#F0F0F0')
        .borderRadius(10)
        .gesture(
          PanGesture()
            .onActionUpdate((event: PanGestureEvent) => this.handleSwipe(event))
            .onActionEnd(() => this.handleSwipeEnd())
        )
        .translate({ x: this.offsetX })
        .animation({ duration: 300 })

        Select()
          .selected(this.segmentLabels[this.selectedIndex])
          .options(this.segmentLabels.map((label, index) => {
            return { value: index.toString(), label: label } as SelectOption
          }))
          .onSelect((index: string) => this.handleButtonClick(parseInt(index)))
          .margin({ top: 20 })
      }
      .width('100%')
      .height('100%')
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20)
  }
}

