                .textAlign(TextAlign.Center)
                .backgroundColor(Color.Black)
                .opacity(0.7)
                .padding(8)
                .borderRadius(8);
            }
          });
        }
        .width('100%')
        .height(300)
        .margin({ bottom: 16 })
        .autoPlay(true)
        .interval(3000)
        .indicator(true)
        .loop(true)
        .duration(500)
        .onChange((index: number) => {
          this.currentIndex = index;
        });
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(20);

      Row() {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });

        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });

        Button('Confirm Payment')
          .onClick(() => {
            promptAction.showToast({ message: 'Payment Confirmed!', duration: 2000 });
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

import { Column, Row, Grid, Image, Button, Text, GridItem, ImageFit } from '@ohos.arkui.advanced'

@Entry
@Component
struct ImageGallery {
  @State currentPage: number = 1
  @State totalPages: number = 3
  private images: Resource[] = [
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon')
  ]

  build() {
    Column() {
      Text(`Page ${this.currentPage} of ${this.totalPages}`)
        .fontSize(16)
        .margin(12)

      Grid() {
        ForEach(this.getCurrentPageImages(), (image: Resource) => {
          GridItem() {
            Image(image)
              .width('100%')
              .aspectRatio(1)
              .objectFit(ImageFit.Cover)
              .borderRadius(8)
          }
        })
      }
      .columnsTemplate('1fr 1fr')
      .rowsGap(12)
      .columnsGap(12)
      .padding(12)

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentPage > 1) {
              this.currentPage--
            }
          })
          .enabled(this.currentPage > 1)
          .flexGrow(1)
          .margin(8)

        Button('Next')
          .onClick(() => {
            if (this.currentPage < this.totalPages) {
              this.currentPage++
            }
          })
          .enabled(this.currentPage < this.totalPages)
          .flexGrow(1)
          .margin(8)
      }
      .width('100%')
      .padding(12)
    }
    .width('100%')
    .height('100%')
  }

  private getCurrentPageImages(): Resource[] {
    const startIdx = (this.currentPage - 1) * 4
    return this.images.slice(startIdx, startIdx + 4)
  }
}

@Entry
@Component
struct FoodDeliveryApp {
  @State selectedCategory: string = 'All'
  @State cachedViews: Map<string, ViewCache> = new Map<string, ViewCache>()

  private categories: string[] = ['All', 'Pizza', 'Burger', 'Sushi', 'Dessert']
  private foodItems: Record<string, string[]> = {
    'All': ['Margherita Pizza', 'Cheeseburger', 'California Roll', 'Chocolate Cake'],
    'Pizza': ['Margherita Pizza', 'Pepperoni Pizza', 'Vegetarian Pizza'],
    'Burger': ['Cheeseburger', 'Bacon Burger', 'Veggie Burger'],
    'Sushi': ['California Roll', 'Spicy Tuna Roll', 'Salmon Nigiri'],
    'Dessert': ['Chocolate Cake', 'Cheesecake', 'Ice Cream']
  }

  private getOrCreateView(category: string): ViewCache {
    let view = this.cachedViews.get(category)
    if (!view) {
      view = new ViewCache()
      view.category = category
      view.items = this.foodItems[category]
      this.cachedViews.set(category, view)
    }
    return view
  }

  @Builder
  CategoryView(category: string) {
    let viewCache = this.getOrCreateView(category)
    Column() {
      viewCache.build()
    }
  }

  build() {
    Column() {
      Row() {
        ForEach(this.categories, (category: string) => {
          Button(category)
            .onClick(() => {
              this.selectedCategory = category
            })
            .backgroundColor(this.selectedCategory === category ? '#007AFF' : '#E0E0E0')
            .margin(5)
        })
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .padding(10)

      Column() {
        this.CategoryView(this.selectedCategory)
      }
    }
    .width('100%')
    .height('100%')
    .padding(10)
  }
}

