import { CustomDialogController, DialogAlignment, PanGesture, GestureEvent, ImageFit, FontWeight } from '@ohos.arkui.advanced';

interface CardItem {
  id: number;
  title: string;
  image: Resource;
  description: string;
  price: string;
}

@Entry
@Component
struct FlashcardECommerceApp {
  @State private cards: CardItem[] = [
    {
      id: 1,
      title: 'Product 1',
      image: $r('app.media.icon'),
      description: 'Description for Product 1',
      price: '$19.99'
    },
    {
      id: 2,
      title: 'Product 2',
      image: $r('app.media.icon'),
      description: 'Description for Product 2',
      price: '$29.99'
    },
    {
      id: 3,
      title: 'Product 3',
      image: $r('app.media.icon'),
      description: 'Description for Product 3',
      price: '$39.99'
    }
  ];

  @State private currentIndex: number = 0;
  private dialogController: CustomDialogController = new CustomDialogController({
    builder: this.DialogBuilder,
    customStyle: true,
    alignment: DialogAlignment.Center
  });

  @Builder
  DialogBuilder() {
    Column() {
      Image(this.cards[this.currentIndex].image)
        .width('100%')
        .height(200)
        .borderRadius(8)
        .objectFit(ImageFit.Cover);

      Text(this.cards[this.currentIndex].title)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 16, bottom: 8 });

      Text(this.cards[this.currentIndex].description)
        .fontSize(16)
        .lineHeight(24);

      Text(this.cards[this.currentIndex].price)
        .fontSize(18)
        .fontColor('#FF5722')
        .margin({ top: 16 });

      Button('Close')
        .width('100%')
        .height(40)
        .margin({ top: 24 })
        .onClick(() => {
          this.dialogController.close();
        });
    }
    .padding(24)
    .backgroundColor('#FFFFFF')
    .borderRadius(16);
  }

  build() {
    Stack() {
      Column() {
        Image($r('app.media.icon'))
          .width(40)
          .height(40)
          .margin({ top: 16, left: 16 });

        Swiper()
          .gesture(
            PanGesture()
              .onActionUpdate((event: GestureEvent) => {
                if (Math.abs(event.offsetX) > 50) {
                  if (event.offsetX > 0) {
                    this.currentIndex = Math.max(0, this.currentIndex - 1);
                  } else {
                    this.currentIndex = Math.min(this.cards.length - 1, this.currentIndex + 1);
                  }
                }
              })
          )
          .indicator(true)
          .loop(false)
          .onChange((index: number) => {
            this.currentIndex = index;
          }) {
          ForEach(this.cards, (item: CardItem) => {
            Column() {
              Image(item.image)
                .width('100%')
                .height(200)
                .borderRadius(16)
                .objectFit(ImageFit.Cover);

              Text(item.title)
                .fontSize(20)
                .fontWeight(FontWeight.Bold)
                .margin({ top: 8 });

              Text(item.description)
                .fontSize(14)
                .margin({ top: 4 });

              Text(item.price)
                .fontSize(16)
                .fontColor('#FF5722')
                .margin({ top: 8 });

              Button('View Details')
                .width('100%')
                .height(40)
                .margin({ top: 16 })
                .onClick(() => {
                  this.dialogController.open();
                });
            }
            .width('90%')
            .padding(16)
            .backgroundColor('#FFFFFF')
            .borderRadius(16)
            .margin({ top: 16, bottom: 16 });
          });
        }
      }
      .width('100%')
      .height('100%')
      .backgroundColor('#D3D3D3');
    }
  }
}

@Entry
@Component
struct CustomBottomSheetApp {
  @State isBottomSheetVisible: boolean = false;
  @State refreshing: boolean = false;
  @State items: string[] = ['Item 1', 'Item 2', 'Item 3'];
  @State rotateAngle: number = 0;
  private timerId: number = -1;

  build() {
    Column() {
      // Main Content
      Column() {
        Text('Main Content')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20, bottom: 20 });
        Button('Toggle BottomSheet')
          .onClick(() => {
            this.isBottomSheetVisible = !this.isBottomSheetVisible;
          });
      }
      .width('100%')
      .alignItems(HorizontalAlign.Center);

      // BottomSheet
      if (this.isBottomSheetVisible) {
        Column() {
          // Pull-to-refresh animation
          if (this.refreshing) {
            Row() {
              Image($r('app.media.app_icon'))
                .width(30)
                .height(30)
                .rotate({ x: 0, y: 0, z: 1, angle: this.rotateAngle });
              Text('Refreshing...')
                .margin({ left: 10 });
            }
            .width('100%')
            .justifyContent(FlexAlign.Center)
            .padding(10)
            .onAppear(() => {
              animateTo({
                duration: 1000,
                curve: Curve.Linear,
                iterations: -1,
                playMode: PlayMode.Normal
              }, () => {
                this.rotateAngle = 360;
              });
            });
          }

          // List with pull-to-refresh
          Refresh({ refreshing: $$this.refreshing, friction: 100 }) {
            List() {
              ForEach(this.items, (item: string) => {
                ListItem() {
                  Text(item)
                    .width('100%')
                    .height(50)
                    .fontSize(16)
                    .textAlign(TextAlign.Center)
                    .backgroundColor('#f5f5f5')
                    .margin({ top: 10 });
                }
              });
            }
            .width('100%')
            .height('100%');
          }
          .onStateChange((refreshStatus: RefreshStatus) => {
            console.info('Refresh status changed to: ' + refreshStatus);
          })
          .onRefreshing(() => {
            this.timerId = setTimeout(() => {
              this.items = ['New Item ' + (this.items.length + 1), ...this.items];
              this.refreshing = false;
            }, 2000);
          });
        }
        .width('100%')
        .height('60%')
        .backgroundColor('#ffffff')
        .borderRadius(20)
        .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f0f0f0');
  }

  aboutToDisappear() {
    if (this.timerId !== -1) {
      clearTimeout(this.timerId);
    }
  }
}

import { Refresh } from '@ohos.arkui.refresh';
import { List, ListItem, Divider, TextInput, Button, Column, Text } from '@ohos.arkui.advanced';
import { AppStorage } from '@ohos.data.storage';

interface Post {
  id: number;
  content: string;
  timestamp: number;
}

@Entry
@Component
struct JournalFeedApp {
  @StorageLink('posts') private posts: Post[] = [];
  @State private newPostContent: string = '';
  @State private isLoading: boolean = false;

  aboutToAppear() {
    this.loadPosts();
  }

  loadPosts() {
    this.isLoading = true;
    try {
      const storedPosts = AppStorage.get('posts') || [];
      this.posts = storedPosts.sort((a: Post, b: Post) => b.timestamp - a.timestamp);
    } catch (error) {
      console.error('Failed to load posts:', error);
    }
    this.isLoading = false;
  }

  addPost() {
    if (this.newPostContent.trim()) {
      const newPost: Post = {
        id: Date.now(),
        content: this.newPostContent,
        timestamp: Date.now()
      };
      this.posts = [newPost, ...this.posts];
      this.newPostContent = '';
      try {
        AppStorage.set('posts', this.posts);
      } catch (error) {
        console.error('Failed to save post:', error);
      }
    }
  }

  handleRefresh() {
    this.loadPosts();
  }

  build(): Column {
    return Column() {
      TextInput({ placeholder: 'Write a new post...', text: this.newPostContent })
        .width('100%')
        .height(80)
        .margin(16)
        .onChange((value: string) => {
          this.newPostContent = value;
        });

      Button('Post')
        .width('100%')
        .height(50)
        .margin({ bottom: 16 })
        .onClick(() => {
          this.addPost();
        });

      Refresh({ refreshing: this.isLoading, onRefresh: () => this.handleRefresh() }) {
        List() {
          ForEach(this.posts, (post: Post) => {
            ListItem() {
              Column() {
                Column() {
                  Text(post.content)
                    .fontSize(16)
                    .margin({ bottom: 8 });
                  Text(new Date(post.timestamp).toLocaleString())
                    .fontSize(12)
                    .fontColor('#666666');
                }
                .padding(16)
                .width('100%');
                Divider()
                  .strokeWidth(1)
                  .color('#f0f0f0');
              }
            }
          });
        }
        .width('100%')
        .height('100%');
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }
}

import { Column, Row, List, ListItem, Text, Button, TextInput, FontWeight } from '@ohos.arkui.component';
import { PanGesture, PanGestureEvent } from '@ohos.arkui.gesture';
import { animateTo } from '@ohos.arkui.animation';

@Entry
@Component
struct TodoListApp {
  @State tasks: string[] = [];
  @State newTask: string = '';

  build() {
    Column() {
      Text('Todo List')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      TextInput({ placeholder: 'Enter a new task', text: this.newTask })
        .onChange((value: string) => {
          this.newTask = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Button('Add Task')
        .onClick(() => {
          if (this.newTask.trim() !== '') {
            this.tasks.push(this.newTask.trim());
            this.newTask = '';
          }
        })
        .margin({ bottom: 20 });

      List() {
        ForEach(this.tasks, (task: string, index: number) => {
          ListItem() {
            Row() {
              Text(task)
                .fontSize(18)
                .margin({ right: 10 });

              Button('Remove')
                .onClick(() => {
                  this.tasks.splice(index, 1);
                });
            }
            .width('80%')
            .margin({ bottom: 10 });
          }
          .gesture(
            PanGesture()
              .onActionUpdate((event: PanGestureEvent) => {
                if (Math.abs(event.offsetX) >= 50) {
                  animateTo({ duration: 300 }, () => {
                    this.tasks.splice(index, 1);
                  });
                }
              })
          );
        });
      }
      .width('100%')
      .height('60%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

import { Column, Text, Grid, GridItem, Image } from '@ohos.arkui.UIContext';
import { FontWeight, Color } from '@ohos.arkui.drawing';
import { PanGesture } from '@ohos.multimodalInput.pointer';

@Entry
@Component
struct CalendarApp {
  @State currentDate: Date = new Date();
  @State month: string = '';
  @State year: string = '';

  aboutToAppear() {
    this.updateMonthYear();
  }

  updateMonthYear(): void {
    this.month = (this.currentDate.getMonth() + 1).toString().padStart(2, '0');
    this.year = this.currentDate.getFullYear().toString();
  }

  handleSwipe(event: PanGesture.Event): void {
    if (event.offsetX > 50) {
      this.currentDate = new Date(this.currentDate.getFullYear(), this.currentDate.getMonth() - 1, 1);
    } else if (event.offsetX < -50) {
      this.currentDate = new Date(this.currentDate.getFullYear(), this.currentDate.getMonth() + 1, 1);
    }
    this.updateMonthYear();
  }

  getDaysInMonth(): number {
    const year = this.currentDate.getFullYear();
    const month = this.currentDate.getMonth();
    return new Date(year, month + 1, 0).getDate();
  }

  getFirstDayOfMonth(): number {
    const year = this.currentDate.getFullYear();
    const month = this.currentDate.getMonth();
    return new Date(year, month, 1).getDay();
  }

  build() {
    Column() {
      Text(`${this.year}-${this.month}`)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Grid() {
        ForEach(Array.from({ length: this.getDaysInMonth() }), (item: undefined, index: number) => {
          GridItem() {
            Text((index + 1).toString())
              .fontSize(18)
              .margin(5);
          }
        })
      }
      .columnsTemplate('1fr 1fr 1fr 1fr 1fr 1fr 1fr')
      .columnsGap(5)
      .rowsGap(5)
      .backgroundColor('#F0F0F0')
      .height(300)
      .width('100%')
      .onPanGesture((event: PanGesture.Event) => this.handleSwipe(event));

      Image($r('app.media.example'))
        .width('100%')
        .height(150)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White);
  }
}

interface Alarm {
  time: string;
  active: boolean;
}

@Entry
@Component
struct AlarmClockApp {
  @State alarmList: Array<Alarm> = [];
  @State newAlarmTime: string = '';
  @State errorMessage: string = '';

  addAlarm() {
    if (!this.newAlarmTime) {
      this.errorMessage = 'Please enter a valid time';
      return;
    }
    const timeRegex = /^([0-1]?[0-9]|2[0-3]):[0-5][0-9]$/;
    if (!timeRegex.test(this.newAlarmTime)) {
      this.errorMessage = 'Invalid time format (HH:MM)';
      return;
    }
    this.alarmList.push({ time: this.newAlarmTime, active: true });
    this.newAlarmTime = '';
    this.errorMessage = '';
  }

  toggleAlarm(index: number) {
    this.alarmList[index].active = !this.alarmList[index].active;
  }

  removeAlarm(index: number) {
    this.alarmList.splice(index, 1);
  }

  build() {
    Column() {
      Text('Set Alarm')
        .fontSize(24)
        .margin(10);

      TextInput({ placeholder: 'Enter time (HH:MM)' })
        .type(InputType.Normal)
        .onChange((value: string) => {
          this.newAlarmTime = value;
        })
        .margin(10);

      Button('Add Alarm')
        .onClick(() => {
          this.addAlarm();
        })
        .margin(10);

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(16)
          .fontColor(Color.Red)
          .margin(10);
      }

      Text('Active Alarms')
        .fontSize(24)
        .margin(10);

      List() {
        ForEach(this.alarmList, (alarm: Alarm, index: number) => {
          ListItem() {
            Row() {
              Text(alarm.time)
                .fontSize(18)
                .margin(10);

              Toggle({ type: ToggleType.Switch, isOn: alarm.active })
                .onChange((isOn: boolean) => {
                  this.toggleAlarm(index);
                })
                .margin(10);

              Button('Remove')
                .onClick(() => {
                  this.removeAlarm(index);
                })
                .margin(10);
            }
          }
        })
      }
      .width('100%')
      .height(300)
      .margin(10);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Start)
    .alignItems(HorizontalAlign.Center);
  }
}

