import { Column, Row, Text, TextInput, Slider, Button, List, ListItem, Chip, ChipType } from '@ohos.arkui';
import { State } from '@ohos.arkui';

@Entry
@Component
struct SmartwatchMessagingApp {
  @State brightness: number = 50;
  @State messages: Array<string> = ['Hello!', 'How are you?', 'Meeting at 3 PM'];
  @State currentMessage: string = '';

  build() {
    Column() {
      Row() {
        Text('Messages > Inbox')
          .fontSize(16)
          .fontWeight(500)
          .margin({ bottom: 10 });
      }

      List() {
        ForEach(this.messages, (message: string, index: number) => {
          ListItem() {
            Text(message)
              .fontSize(14)
              .margin({ top: 5, bottom: 5 })
              .padding(10)
              .backgroundColor('#f5f5f5')
              .borderRadius(8);
          }
        }, (item, index) => index.toString());
      }
      .layoutWeight(1)
      .width('100%')
      .margin({ bottom: 10 });

      Row() {
        TextInput({ placeholder: 'Type a message', text: this.currentMessage })
          .width('80%')
          .height(40)
          .accessibilityDescription('Message input field')
          .onChange((value: string) => {
            this.currentMessage = value;
          });
        Button('Send')
          .width('20%')
          .height(40)
          .borderRadius(20)
          .fontSize(14)
          .accessibilityDescription('Send message button')
          .onClick(() => {
            if (this.currentMessage.trim() !== '') {
              this.messages = [...this.messages, this.currentMessage];
              this.currentMessage = '';
            }
          });
      }
      .width('100%')
      .margin({ bottom: 10 });

      Row({ space: 10 }) {
        Chip({
          type: ChipType.Normal,
          content: {
            Text('Scan')
              .fontSize(14)
          }
        })
        .width('45%')
        .height(40)
        .borderRadius(20)
        .accessibilityDescription('Scan action')
        .onClick(() => {
        });

        Chip({
          type: ChipType.Normal,
          content: {
            Text('Reply')
              .fontSize(14)
          }
        })
        .width('45%')
        .height(40)
        .borderRadius(20)
        .accessibilityDescription('Reply action')
        .onClick(() => {
        });
      }
      .width('100%')
      .margin({ bottom: 10 });

      Column() {
        Text('Brightness')
          .fontSize(14)
          .margin({ bottom: 5 });
        Slider({
          value: this.brightness,
          min: 0,
          max: 100,
          step: 1
        })
          .width('100%')
          .accessibilityDescription(`Brightness set to ${this.brightness}%`)
          .onChange((value: number) => {
            this.brightness = value;
          });
      }
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

import { Tabs, TabContent } from '@ohos.arkui.advanced.Tabs';
import { TabsBarPosition } from '@ohos.arkui.advanced.TabsController';
import { Placement } from '@ohos.arkui.advanced.Tooltip';
import { FlexAlign } from '@ohos.arkui.advanced.Flex';
import { HorizontalAlign } from '@ohos.arkui.advanced.Common';
import { FontWeight } from '@ohos.arkui.advanced.Text';

@Entry
@Component
struct SleepTrackerApp {
  @State currentTabIndex: number = 0;
  @State showTooltip: boolean = false;

  build() {
    Column() {
      Tabs({ barPosition: TabsBarPosition.Start }) {
        TabContent() {
          this.SleepLogTab();
        }
        .tabBar('Sleep Log')

        TabContent() {
          this.StatisticsTab();
        }
        .tabBar('Statistics')

        TabContent() {
          this.SettingsTab();
        }
        .tabBar('Settings')
      }
      .width('100%')
      .height('100%')
      .layoutWeight(1)

      Row() {
        Button('Show Tooltip')
          .onClick(() => {
            this.showTooltip = !this.showTooltip;
          })
          .bindTooltip({
            content: 'This is a tooltip',
            placement: Placement.Bottom,
            show: this.showTooltip
          })
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .margin({ top: 20, bottom: 20 })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }

  @Builder SleepLogTab() {
    Column() {
      Text('Sleep Log')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })
      Text('Placeholder content for Sleep Log tab')
        .fontSize(16)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }

  @Builder StatisticsTab() {
    Column() {
      Text('Statistics')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })
      Text('Placeholder content for Statistics tab')
        .fontSize(16)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }

  @Builder SettingsTab() {
    Column() {
      Text('Settings')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })
      Text('Placeholder content for Settings tab')
        .fontSize(16)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

@Entry
@Component
struct BreadcrumbNavigation {
  @State currentStep: number = 0;
  private steps: string[] = ['Login', 'Verification', 'Delivery'];

  @Builder
  BreadcrumbItem(text: string, index: number) {
    Row() {
      Text(text)
        .fontSize(16)
        .fontColor(this.currentStep === index ? '#1698CE' : '#6B6B6B')
        .onClick(() => {
          this.currentStep = index;
        });
      if (index < this.steps.length - 1) {
        Divider()
          .vertical(true)
          .height(16)
          .margin({ left: 8, right: 8 });
      }
    }
  }

  build() {
    Column() {
      Row() {
        ForEach(this.steps, (item: string, index: number) => {
          this.BreadcrumbItem(item, index);
        });
      }
      .padding(16)
      .justifyContent(FlexAlign.SpaceBetween)
      .width('100%');

      Divider()
        .width('100%')
        .margin({ top: 8, bottom: 8 });

      Column() {
        Text(this.steps[this.currentStep])
          .fontSize(20)
          .margin({ top: 16 });
      }
      .width('100%')
      .padding(16);
    }
    .width('100%')
    .height('100%');
  }
}

interface Note {
  id: number;
  content: string;
  rating: number;
  progress: number;
}

@Entry
@Component
struct NoteApp {
  @State notes: Note[] = [];
  @State newNote: string = '';
  @State currentRating: number = 0;
  @State currentProgress: number = 0;

  build() {
    Column() {
      TextArea({ placeholder: 'Enter new note...', text: this.newNote })
        .height(100)
        .width('90%')
        .onChange((value: string) => {
          this.newNote = value;
        })
        .margin(10);

      Row() {
        Text('Rating:')
          .margin({ right: 10 });
        ForEach([1, 2, 3, 4, 5], (star: number) => {
          Text(star <= this.currentRating ? '★' : '☆')
            .fontSize(30)
            .onClick(() => {
              this.currentRating = star;
            });
        });
      }
      .margin(10);

      Row() {
        Text('Progress:')
          .margin({ right: 10 });
        Slider({ value: this.currentProgress, min: 0, max: 100 })
          .width('70%')
          .onChange((value: number) => {
            this.currentProgress = value;
          });
      }
      .margin(10);

      Button('Add Note')
        .onClick(() => {
          if (this.newNote.trim()) {
            this.notes.push({
              id: Date.now(),
              content: this.newNote,
              rating: this.currentRating,
              progress: this.currentProgress,
            });
            this.newNote = '';
            this.currentRating = 0;
            this.currentProgress = 0;
          }
        })
        .margin(10);

      List() {
        ForEach(this.notes, (note: Note) => {
          ListItem() {
            Column() {
              Text(note.content)
                .width('80%');
              Row() {
                Text(`Rating: ${note.rating}/5`);
                Text(`Progress: ${note.progress}%`);
              }
              .margin({ top: 5 });
            }
            .padding(10);
          }
          .onClick(() => {
            this.notes = this.notes.filter((n) => n.id !== note.id);
          });
        });
      }
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

import { TimePicker } from '@ohos.picker';
import promptAction from '@ohos.promptAction';

interface TimeValue {
  hour: number;
  minute: number;
}

@Entry
@Component
struct ProgressTracker {
  @State progress: number = 0;
  @State timerActive: boolean = false;
  @State selectedTime: string = '00:00';
  private timer: number = 0;

  build() {
    Column() {
      Image($r('app.media.ic_public_map'))
        .width('100%')
        .height(200)

      TimePicker({ selected: this.selectedTime })
        .width('80%')
        .onChange((value: TimeValue) => {
          this.selectedTime = `${value.hour}:${value.minute}`;
        })

      Button('Start Tracking')
        .width('80%')
        .height(50)
        .onClick(() => {
          this.startProgressTracking();
        })
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }

  startProgressTracking() {
    this.timerActive = true;
    this.progress = 0;
    this.timer = setInterval(() => {
      if (this.progress >= 100) {
        clearInterval(this.timer);
        this.timerActive = false;
        this.showProgressDialog();
        return;
      }
      this.progress += 10;
    }, 1000);
  }

  showProgressDialog() {
    promptAction.showToast({
      message: `Progress: ${this.progress}% complete`,
      duration: 2000
    });
  }
}

import { Radio, RadioGroup } from '@ohos.arkui.advanced';
import media from '@ohos.multimedia.media';

@Entry
@Component
struct VideoToggleApp {
  @State showVideo: boolean = false;

  build() {
    Column() {
      Row() {
        RadioGroup({ group: 'videoToggle' })
          .onChange((index: number) => {
            this.showVideo = (index === 0);
          }) {
            Radio({ value: 'show' })
              .checked(this.showVideo);
            Text('Show Video')
              .fontSize(16)
              .fontColor('#000000')
              .margin({ left: 10 });

            Radio({ value: 'hide' })
              .checked(!this.showVideo);
            Text('Hide Video')
              .fontSize(16)
              .fontColor('#000000')
              .margin({ left: 10 });
          }
      }
      .justifyContent(FlexAlign.Center)
      .width('100%')
      .padding(20);

      if (this.showVideo) {
        media.Video({
          src: 'common/media/example.mp4'
        })
          .width('100%')
          .height(200)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#ffffff');
  }
}

import promptAction from '@ohos.promptAction';

@Entry
@Component
struct StepCounterApp {
  @State isTracking: boolean = false;
  @State stepCount: number = 0;
  @State selectedDate: Date = new Date();

  private resetSteps() {
    promptAction.showDialog({
      title: 'Reset Steps',
      message: 'Are you sure you want to reset your step count?',
      buttons: [
        { 
          text: 'Reset', 
          color: '#FF0000', 
          onAccept: () => { this.stepCount = 0; } 
        },
        { 
          text: 'Cancel', 
          onCancel: () => {} 
        }
      ]
    });
  }

  build() {
    Column() {
      Text('Step Counter')
        .fontSize(24)
        .margin({ bottom: 20 });

      Row() {
        Checkbox({ name: 'Toggle Tracking' })
          .select(this.isTracking)
          .onChange((isChecked: boolean) => {
            this.isTracking = isChecked;
          })
          .accessibilityDescription('Toggle step tracking');
        Text('Track Steps')
          .margin({ left: 10 });
      }
      .margin({ bottom: 20 });

      DatePicker({ start: new Date('2023-01-01'), end: new Date(), selected: this.selectedDate })
        .onDateChange((date: Date) => {
          this.selectedDate = date;
        })
        .accessibilityDescription('Select date');

      Text(`Steps: ${this.stepCount}`)
        .fontSize(20)
        .margin({ top: 20, bottom: 20 });

      Button('Reset Steps')
        .onClick(() => {
          this.resetSteps();
        })
        .accessibilityDescription('Reset step count');
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

import { Grid, GridItem, Canvas } from '@ohos.arkui.advanced';
import { FlexAlign } from '@ohos.arkui.common';

@Entry
@Component
struct AccessibleCalculator {
  @State currentInput: string = '';
  @State result: string = '';
  @State currentPage: number = 1;
  @State highContrastMode: boolean = false;

  private calculate(): void {
    try {
      const parts = this.currentInput.split(/([+\-*/])/);
      let res = parseFloat(parts[0]);
      for (let i = 1; i < parts.length; i += 2) {
        const op = parts[i];
        const num = parseFloat(parts[i+1]);
        switch(op) {
          case '+': res += num; break;
          case '-': res -= num; break;
          case '*': res *= num; break;
          case '/': res /= num; break;
        }
      }
      this.result = res.toString();
    } catch (error) {
      this.result = 'Error';
    }
  }

  private handleButtonPress(value: string): void {
    this.currentInput += value;
  }

  private clearInput(): void {
    this.currentInput = '';
    this.result = '';
  }

  private toggleHighContrastMode(): void {
    this.highContrastMode = !this.highContrastMode;
  }

  private navigatePage(direction: number): void {
    this.currentPage = Math.max(1, Math.min(3, this.currentPage + direction));
  }

  build() {
    Column() {
      Canvas()
        .width('100%')
        .height(100)
        .backgroundColor(this.highContrastMode ? '#000000' : '#f0f0f0');

      Text(this.currentInput)
        .fontSize(24)
        .margin(10)
        .accessibilityDescription('Current Input: ' + this.currentInput);

      Text(this.result)
        .fontSize(24)
        .margin(10)
        .accessibilityDescription('Result: ' + this.result);

      Grid() {
        ForEach(['7', '8', '9', '/', '4', '5', '6', '*', '1', '2', '3', '-', '0', '.', '=', '+'], (item: string) => {
          GridItem() {
            Button(item)
              .width('100%')
              .height(80)
              .margin(5)
              .onClick(() => {
                if (item === '=') {
                  this.calculate();
                } else {
                  this.handleButtonPress(item);
                }
              })
              .accessibilityDescription('Button: ' + item);
          }
        });
      }
      .columnsTemplate('1fr 1fr 1fr 1fr')
      .width('100%')
      .margin(10);

      Row() {
        Button('Previous')
          .width('30%')
          .height(50)
          .margin(5)
          .onClick(() => this.navigatePage(-1))
          .accessibilityDescription('Previous Page');

        Text(`Page ${this.currentPage}`)
          .fontSize(18)
          .margin(5)
          .accessibilityDescription(`Current Page: ${this.currentPage}`);

        Button('Next')
          .width('30%')
          .height(50)
          .margin(5)
          .onClick(() => this.navigatePage(1))
          .accessibilityDescription('Next Page');
      }
      .width('100%')
      .justifyContent(FlexAlign.Center);

      Button('Clear')
        .width('90%')
        .height(50)
        .margin(10)
        .onClick(() => this.clearInput())
        .accessibilityDescription('Clear Input');

      Button('Toggle High Contrast')
        .width('90%')
        .height(50)
        .margin(10)
        .onClick(() => this.toggleHighContrastMode())
        .accessibilityDescription('Toggle High Contrast Mode');
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(this.highContrastMode ? '#000000' : '#ffffff');
  }
}

