@Entry
@Component
struct ResponsiveScrollView {
  @State items: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4', 'Item 5'];
  @State showActionSheet: boolean = false;

  build() {
    Column() {
      // Header
      Row() {
        Text('Responsive ScrollView')
          .fontSize(20)
          .textAlign(TextAlign.Center)
          .width('100%')
          .height(50)
          .backgroundColor('#f0f0f0')
      }
      .width('100%')
      .height(50)

      // Scrollable Content
      Scroll() {
        Column() {
          ForEach(this.items, (item: string) => {
            Row() {
              Text(item)
                .fontSize(16)
                .padding(10)
                .backgroundColor('#ffffff')
                .border({ width: 1, color: '#000000', radius: 4, style: BorderStyle.Solid })
                .margin({ bottom: 10 })
                .onClick(() => {
                  this.showActionSheet = true;
                });
            }
            .width('100%')
          })
        }
        .width('100%')
        .padding(10)
      }
      .height('70%')
      .edgeEffect(EdgeEffect.Spring)

      // Footer with Button
      Row() {
        Button('Add Item')
          .onClick(() => {
            this.items.push(`Item ${this.items.length + 1}`);
          })
          .width('50%')
          .height(40)
          .backgroundColor('#6200ee')
          .fontColor(Color.White)
          .margin(10)
      }
      .width('100%')
      .height(60)
      .justifyContent(FlexAlign.Center)

      // ActionSheet (simulated)
      if (this.showActionSheet) {
        Column() {
          Text('Action Sheet')
            .fontSize(18)
            .padding(10)
            .backgroundColor('#f0f0f0')
            .width('100%')
            .textAlign(TextAlign.Center)
          Button('Close')
            .onClick(() => {
              this.showActionSheet = false;
            })
            .width('100%')
            .height(40)
            .backgroundColor('#6200ee')
            .fontColor(Color.White)
            .margin(10)
        }
        .width('80%')
        .backgroundColor('#ffffff')
        .border({ width: 1, color: '#000000', radius: 4, style: BorderStyle.Solid })
        .alignItems(HorizontalAlign.Center)
        .position({ x: '10%', y: '20%' })
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff')
  }
}

@Entry
@Component
struct LazyLoadingDialogApp {
  @State isDialogVisible: boolean = false;
  @State loadedContent: string = '';

  loadContent() {
    setTimeout(() => {
      this.loadedContent = 'Content loaded successfully!';
    }, 2000);
  }

  build() {
    Column() {
      Button('Show Dialog')
        .onClick(() => {
          this.isDialogVisible = true;
          this.loadedContent = '';
          this.loadContent();
        })
        .margin(20)
        .width(200)
        .height(50)
        .fontColor(Color.White)
        .backgroundColor(Color.Blue)
        .borderRadius(10);

      if (this.isDialogVisible) {
        Stack({ alignContent: Alignment.Center }) {
          Column() {
            Text('Loading Dialog')
              .fontSize(20)
              .fontWeight(FontWeight.Bold)
              .margin({ top: 20, bottom: 10 });

            if (this.loadedContent) {
              Text(this.loadedContent)
                .fontSize(16)
                .margin({ bottom: 20 });
            } else {
              Image($r("app.media.app_icon"))
                .width(50)
                .height(50)
                .margin(10);
              Text('Loading...')
                .fontSize(16)
                .margin({ bottom: 20 });
            }

            Button('Close')
              .onClick(() => {
                this.isDialogVisible = false;
              })
              .width(100)
              .height(40)
              .fontColor(Color.White)
              .backgroundColor(Color.Red)
              .borderRadius(10);
          }
          .width('80%')
          .padding(20)
          .backgroundColor(Color.Gray)
          .borderRadius(15)
          .shadow({ radius: 10, color: Color.Black, offsetX: 5, offsetY: 5 });
