@Entry
@Component
struct WaterIntakeTracker {
  @State waterIntake: number = 0;
  @State dailyGoal: number = 2000;
  @State progress: number = 0;
  @State message: string = '';
  @State showMessage: boolean = false;

  updateProgress() {
    this.progress = (this.waterIntake / this.dailyGoal) * 100;
  }

  showConfirmation(text: string) {
    this.message = text;
    this.showMessage = true;
    setTimeout(() => {
      this.showMessage = false;
    }, 2000);
  }

  onPan(event: PanGestureEvent) {
    if (event.offsetX > 0) {
      this.waterIntake += 50;
    } else if (event.offsetX < 0) {
      this.waterIntake = Math.max(0, this.waterIntake - 50);
    }
    this.updateProgress();
  }

  build() {
    Column() {
      Text('Daily Water Intake Tracker')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin(20);

      Text(`Goal: ${this.dailyGoal} ml`)
        .fontSize(18)
        .margin(10);

      Text(`Consumed: ${this.waterIntake} ml`)
        .fontSize(18)
        .margin(10);

      Stack() {
        Circle()
          .width(200)
          .height(200)
          .stroke('#E0E0E0')
          .strokeWidth(15)
          .fill('transparent');

        Circle()
          .width(200)
          .height(200)
          .stroke('#4CAF50')
          .strokeWidth(15)
          .fill('transparent')
          .strokeDashArray([Math.PI * 200, Math.PI * 200])
          .strokeDashOffset(Math.PI * 200 * (1 - this.progress / 100))
          .rotate({ x: 0, y: 0, z: 1, angle: -90 });

        Text(`${Math.round(this.progress)}%`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold);
      }
      .width(200)
      .height(200)
      .margin({ top: 50 })
      .gesture(
        PanGesture()
          .onActionUpdate((event: PanGestureEvent) => this.onPan(event))
      );

      Row() {
        Button('+250ml')
          .onClick(() => {
            this.waterIntake += 250;
            this.updateProgress();
            this.showConfirmation('Added 250ml!');
          })
          .width(120)
          .height(50)
          .margin(10);

        Button('Reset')
          .onClick(() => {
            this.waterIntake = 0;
            this.updateProgress();
            this.showConfirmation('Reset successful!');
          })
          .width(120)
          .height(50)
          .margin(10);
      }
      .margin({ top: 40 });

      Text('Location Reminder')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 40 });

      Image($r('app.media.ic_public'))
        .width(300)
        .height(200)
        .margin({ top: 10 });

      if (this.showMessage) {
        Text(this.message)
          .fontSize(16)
          .fontColor('#4CAF50')
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

import { Navigation, NavDestination } from '@ohos.arkui.navigation';
import { Column, Row, Text, TextInput, Button, ButtonType } from '@ohos.arkui.component';
import { List, ListItem } from '@ohos.arkui.list';
import preferences from '@ohos.data.preferences';
import common from '@ohos.app.ability.common';

@Entry
@Component
struct TodoListApp {
  @State todoItems: string[] = [];
  @State completedCount: number = 0;
  @State newTodoText: string = '';
  private context: common.UIAbilityContext = getContext(this) as common.UIAbilityContext;
  private preferencesKey: string = 'todoAppData';

  aboutToAppear() {
    preferences.getPreferences(this.context, this.preferencesKey, (err, pref) => {
      if (err) {
        console.error(`Failed to get preferences: ${err.message}`);
        return;
      }
      pref.get('todoItems', '[]', (err, value: preferences.ValueType) => {
        if (!err && typeof value === 'string') {
          this.todoItems = JSON.parse(value);
        }
      });
      pref.get('completedCount', '0', (err, value: preferences.ValueType) => {
        if (!err && typeof value === 'string') {
          this.completedCount = parseInt(value, 10);
        }
      });
    });
  }

  saveData() {
    preferences.getPreferences(this.context, this.preferencesKey, (err, pref) => {
      if (err) {
        console.error(`Failed to get preferences: ${err.message}`);
        return;
      }
      pref.put('todoItems', JSON.stringify(this.todoItems), (err) => {
        if (err) {
          console.error(`Failed to save todo items: ${err.message}`);
        }
      });
      pref.put('completedCount', this.completedCount.toString(), (err) => {
        if (err) {
          console.error(`Failed to save completed count: ${err.message}`);
        }
      });
      pref.flush((err) => {
        if (err) {
          console.error(`Failed to flush preferences: ${err.message}`);
        }
      });
    });
  }

  addTodo() {
    if (this.newTodoText.trim() === '') return;
    this.todoItems = [...this.todoItems, this.newTodoText];
    this.newTodoText = '';
    this.saveData();
  }

  completeTodo(index: number) {
    this.todoItems.splice(index, 1);
    this.completedCount += 1;
    this.todoItems = [...this.todoItems];
    this.saveData();
  }

  build() {
    Navigation() {
      NavDestination() {
        Column() {
          Row() {
            TextInput({ placeholder: 'Add a new todo', text: this.newTodoText })
              .onChange((value: string): void => {
                this.newTodoText = value;
              })
              .layoutWeight(1);
            Button('Add', { type: ButtonType.Normal })
              .onClick((): void => this.addTodo());
          }
          .width('100%')
          .padding(10);

          Text(`Completed: ${this.completedCount}`)
            .fontSize(16)
            .margin({ top: 10, bottom: 10 });

          List() {
            ForEach(this.todoItems, (item: string, index: number) => {
              ListItem() {
                Row() {
                  Text(item)
                    .fontSize(16)
                    .layoutWeight(1);
                  Button('Complete', { type: ButtonType.Normal })
                    .onClick((): void => this.completeTodo(index));
                }
                .width('100%')
                .padding(10);
              }
            });
          }
          .width('100%')
          .layoutWeight(1);
        }
        .width('100%')
        .height('100%')
        .padding(20);
      }
      .title('Todo List');
    }
    .width('100%')
    .height('100%');
  }
}

