}

@Entry
@Component
struct TodoListApp {
  @State isLoggedIn: boolean = false;
  @State username: string = '';
  @State password: string = '';
  @State tasks: Array<Task> = [];
  @State newTask: string = '';
  @State selectedTime: string = '';
  @State activeTab: number = 0;

  build() {
    Column() {
      if (!this.isLoggedIn) {
        this.LoginScreen()
      } else {
        Tabs({ barPosition: 'End' }) {
          TabContent() {
            this.TasksTab()
          }.tabBar('Tasks')
          TabContent() {
            this.SettingsTab()
          }.tabBar('Settings')
        }
      }
    }
    .width('100%')
    .height('100%')
  }

  @Builder
  LoginScreen() {
    Column() {
      TextInput({ placeholder: 'Username' })
        .onChange((value: string) => {
          this.username = value;
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Password', type: 'password' })
        .onChange((value: string) => {
          this.password = value;
        })
        .margin({ bottom: 20 })

      Button('Login')
        .onClick(() => {
