interface WaterIntakeEntry {
  amount: number;
  timestamp: string;
}

@Entry
@Component
struct WaterIntakeTracker {
  @State waterIntake: number = 0
  @State dailyGoal: number = 2000
  @State progress: number = 0
  @State history: Array<WaterIntakeEntry> = []

  updateProgress(): void {
    this.progress = (this.waterIntake / this.dailyGoal) * 100
  }

  logWaterIntake(amount: number): void {
    this.waterIntake += amount
    this.history.push({ 
      amount: amount, 
      timestamp: new Date().toLocaleTimeString() 
    } as WaterIntakeEntry)
    this.updateProgress()
  }

  reset(): void {
    this.waterIntake = 0
    this.history = []
    this.updateProgress()
  }

  build() {
    Column() {
      Text('Daily Water Intake Tracker')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin(20)

      Text(`Goal: ${this.dailyGoal} ml`)
        .fontSize(18)
        .margin(10)

      Text(`Consumed: ${this.waterIntake} ml`)
        .fontSize(18)
        .margin(10)

      Progress({ value: this.progress, total: 100 })
        .width('80%')
        .height(20)
        .margin(20)

      Row() {
        Button('+250 ml')
          .onClick(() => {
            this.logWaterIntake(250)
          })
          .margin(10)

        Button('+500 ml')
          .onClick(() => {
            this.logWaterIntake(500)
          })
          .margin(10)
      }

      Button('Reset')
        .onClick(() => {
          this.reset()
        })
        .margin(20)

      List() {
        ForEach(this.history, (item: WaterIntakeEntry) => {
          ListItem() {
            Row() {
              Image($r('app.media.icon'))
                .width(40)
                .height(40)
                .margin(10)

              Column() {
                Text(`${item.amount} ml`)
                  .fontSize(16)

                Text(item.timestamp)
                  .fontSize(12)
                  .opacity(0.7)
              }
            }
            .width('100%')
            .justifyContent(FlexAlign.SpaceBetween)
          }
        })
      }
      .width('100%')
      .height(200)
      .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

