    { title: 'Mock News 1', date: '2023-10-01', location: 'New York' },
    { title: 'Mock News 2', date: '2023-10-02', location: 'San Francisco' },
    { title: 'Mock News 3', date: '2023-10-03', location: 'Chicago' }
  ];

  aboutToAppear() {
    this.updateDisplayDate();
    this.requestLocationPermission();
  }

  updateDisplayDate(): void {
    this.displayDate = this.selectedDate.toLocaleDateString();
  }

  requestLocationPermission(): void {
    let atManager = abilityAccessCtrl.createAtManager();
    atManager.requestPermissionsFromUser(getContext(this), ['ohos.permission.APPROXIMATELY_LOCATION'], 
    (err: BusinessError, data) => {
      if (err) {
        promptAction.showToast({ message: 'Location permission denied', duration: 2000 });
      } else {
        this.fetchLocation();
      }
    });
  }

  fetchLocation(): void {
    this.isLoading = true;
    setTimeout(() => {
      this.location = 'Mock Location: 40.7128° N, 74.0060° W';
      this.isLoading = false;
    }, 1000);
  }

  refreshLocation(): void {
    this.fetchLocation();
  }

  build() {
    Column() {
      Text('News Reader')
        .fontSize(28)
        .fontWeight('700')
        .margin({ top: 20, bottom: 20 });

      DatePicker({
        start: new Date('2000-01-01'),
        end: new Date('2030-12-31'),
        selected: this.selectedDate
      })
        .onDateChange((value: Date) => {
          this.selectedDate = value;
          this.updateDisplayDate();
        })
        .margin({ bottom: 20 });

      Row() {
        Text('Location:')
          .fontSize(18)
          .margin({ right: 10 });

        Text(this.location)
          .fontSize(18)
          .fontColor(this.isLoading ? '#999999' : '#000000');

        Button('Refresh')
          .onClick(() => this.refreshLocation())
          .margin({ left: 10 });
      }
      .margin({ bottom: 20 });

      Scroll() {
        Column() {
          ForEach(this.newsList, (item: NewsItem) => {
            Column() {
              Text(item.title)
                .fontSize(20)
                .fontWeight('700')
                .margin({ bottom: 8 });

              Text(`Published: ${item.date}`)
                .fontSize(16)
                .margin({ bottom: 4 });

              Text(`Location: ${item.location}`)
                .fontSize(16)
                .margin({ bottom: 16 });
            }
            .padding(16)
            .borderRadius(12)
            .backgroundColor('#F0F0F0')
            .margin({ bottom: 16 });
          });
        }
        .width('100%')
      }
      .width('100%')
      .height('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

import { Tabs, TabContent, Column, Row, Image, Text } from '@ohos.arkui.advanced';
import { FlexAlign } from '@ohos.arkui.advanced';
import { Curve } from '@ohos.arkui.advanced';

@Entry
@Component
struct RatingApp {
  @State currentTab: number = 0;
  @State rating: number = 0;
  @State showNotification: boolean = false;

  private tabChangeHandler(index: number): void {
    this.currentTab = index;
  }

  @Builder
  RatingBar() {
    Row() {
      ForEach([0, 1, 2, 3, 4], (index: number) => {
        Image(index < this.rating ? $r('app.media.star_filled') : $r('app.media.star_outline'))
          .width(32)
          .height(32)
          .margin({ right: 8 })
          .onClick(() => {
            this.rating = index + 1;
            this.showNotification = true;
          })
          .animation({
            duration: 300,
            curve: Curve.Ease,
            iterations: 1
          })
      })
    }
    .margin({ top: 20, bottom: 20 })
  }

  @Builder
  NotificationArea() {
    if (this.showNotification) {
      Column() {
        Text('Thank you for your rating!')
          .fontSize(18)
          .fontColor('#FFFFFF')
          .margin({ bottom: 10 })
      }
      .width('80%')
      .height(80)
      .backgroundColor('#4CAF50')
      .borderRadius(8)
      .opacity(this.showNotification ? 1 : 0)
      .animation({
        duration: 500,
        curve: Curve.Ease,
        iterations: 1
      })
      .onClick(() => {
        this.showNotification = false;
      })
    }
  }

  build() {
    Column() {
      Tabs({ barPosition: 'start' }) {
        TabContent() {
          Column() {
            this.RatingBar()
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center)
        }
        .tabBar('Rate Us')

        TabContent() {
          Column() {
            this.NotificationArea()
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center)
        }
        .tabBar('Notifications')
      }
      .onChange((index: number) => {
        this.tabChangeHandler(index);
      })
      .width('100%')
      .height('100%')
    }
    .width('100%')
    .height('100%')
  }
}

import { Stepper } from '@ohos.arkui.component';
import { PinchGesture } from '@ohos.multimodalinput.gesture';

interface MediaItem {
  title: string;
  image: Resource;
}

interface PinchEvent {
  scale: number;
}

@Entry
@Component
struct MediaViewerApp {
  @State currentStep: number = 0;
  @State scaleValue: number = 1.0;
  @State lastScale: number = 1.0;
  @State initialDistance: number = 0;
  @State isPlaying: boolean = false;

  private mediaItems: MediaItem[] = [
    { title: "Inception", image: $r('app.media.media1') },
    { title: "Interstellar", image: $r('app.media.media2') },
    { title: "The Dark Knight", image: $r('app.media.media3') }
  ];

  private resetZoom(): void {
    this.scaleValue = 1.0;
    this.lastScale = 1.0;
    this.initialDistance = 0;
  }

  private handlePinch(event: PinchEvent): void {
    if (event.scale > 0.5 && event.scale < 3.0) {
      this.scaleValue = event.scale;
      this.lastScale = event.scale;
    }
  }

  private nextStep(): void {
    if (this.currentStep < this.mediaItems.length - 1) {
      this.currentStep++;
      this.resetZoom();
    }
  }

  private prevStep(): void {
    if (this.currentStep > 0) {
      this.currentStep--;
      this.resetZoom();
    }
  }

  private togglePlayPause(): void {
    this.isPlaying = !this.isPlaying;
  }

  build() {
    Column() {
      Stepper({ index: this.currentStep }) {
        ForEach(this.mediaItems, (item: MediaItem, index: number) => {
          Column() {
            Text(`Step ${index + 1}: ${item.title}`)
              .fontSize(18)
              .margin({ bottom: 10 });

            Stack() {
              Image(item.image)
                .objectFit(ImageFit.Contain)
                .width('100%')
                .height('100%')
                .scale({ x: this.scaleValue, y: this.scaleValue })
                .gesture(
                  PinchGesture()
                    .onActionStart(() => {
                      this.initialDistance = 0;
                    })
                    .onActionUpdate((event: PinchEvent) => {
                      this.handlePinch(event);
                    })
                    .onActionEnd(() => {
                      this.lastScale = this.scaleValue;
                    })
                );
            }
            .width('100%')
            .height('60%')
            .backgroundColor('#F5F5F5');

            Row() {
              Button('Previous')
                .onClick(() => this.prevStep())
                .enabled(this.currentStep > 0);

              Button(this.isPlaying ? 'Pause' : 'Play')
                .onClick(() => this.togglePlayPause())
                .margin({ left: 20, right: 20 });

              Button('Next')
                .onClick(() => this.nextStep())
                .enabled(this.currentStep < this.mediaItems.length - 1);
            }
            .justifyContent(FlexAlign.Center)
            .margin({ top: 20 });
          }
        });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

