@Entry
@Component
struct MessagingApp {
  @State currentStep: number = 1;
  @State messages: string[] = [];
  @State inputMessage: string = '';
  @State showError: boolean = false;
  @State activityData: number[] = [5, 10, 15, 20, 25, 30, 35];

  private encryptMessage(message: string): string {
    return message.split('').map(char => String.fromCharCode(char.charCodeAt(0) + 1)).join('');
  }

  private decryptMessage(message: string): string {
    return message.split('').map(char => String.fromCharCode(char.charCodeAt(0) - 1)).join('');
  }

  private validateMessage(): boolean {
    return this.inputMessage.trim().length > 0;
  }

  private addMessage() {
    if (this.validateMessage()) {
      const encryptedMessage = this.encryptMessage(this.inputMessage);
      this.messages = [...this.messages, encryptedMessage];
      this.inputMessage = '';
    } else {
      this.showError = true;
    }
  }

  build() {
    Column() {
      // Stepper Navigation
      Row() {
        Button('Messaging')
          .onClick(() => { this.currentStep = 1; })
          .backgroundColor(this.currentStep === 1 ? '#0000FF' : '#CCCCCC')
          .margin(10);
        Button('Activity Chart')
          .onClick(() => { this.currentStep = 2; })
          .backgroundColor(this.currentStep === 2 ? '#0000FF' : '#CCCCCC')
          .margin(10);
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly);

      // Step 1: Messaging Interface
      if (this.currentStep === 1) {
        Column() {
          // Message List
          Scroll() {
            Column() {
              ForEach(this.messages, (message: string, index: number) => {
                Text(this.decryptMessage(message))
                  .fontSize(16)
                  .padding(10)
                  .backgroundColor('#F0F0F0')
                  .borderRadius(8)
                  .margin({ bottom: 5 });
              });
            }
            .width('100%')
            .padding(10);
          }
          .height('70%');

          // Message Input
          Row() {
            TextInput({ placeholder: 'Type a message...', text: this.inputMessage })
              .onChange((value: string) => { this.inputMessage = value; })
              .width('80%')
              .height(40)
              .margin(10);
            Button('Send')
              .onClick(() => { this.addMessage(); })
              .width('20%')
              .height(40)
              .backgroundColor('#0000FF')
              .fontColor(Color.White)
              .margin(10);
          }
          .width('100%');
        }
        .width('100%')
        .height('100%');
      }

      // Step 2: Activity Chart
      if (this.currentStep === 2) {
        Column() {
          Text('Message Activity')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          // Line Chart (simulated with rectangles)
          Row() {
            ForEach(this.activityData, (count: number, index: number) => {
              Column() {
                Text(count.toString())
                  .fontSize(12)
                  .margin({ bottom: 5 });
                Stack() {
                  Rect()
                    .width(30)
                    .height(count * 2)
                    .fill('#0000FF');
                  Circle()
                    .width(10)
                    .height(10)
                    .backgroundColor('#FFFFFF')
                    .margin({ top: count * 2 - 5 });
                }
                Text(['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'][index])
                  .fontSize(12)
                  .margin({ top: 5 });
              }
              .margin({ right: 10 });
            });
          }
          .width('100%')
          .justifyContent(FlexAlign.SpaceEvenly);
        }
        .width('100%')
        .height('100%')
        .padding(20);
      }

      // Error Dialog
      if (this.showError) {
        Column() {
          Text('Error: Message cannot be empty')
            .fontSize(16)
            .fontColor(Color.Red)
            .margin(10);
          Button('OK')
            .onClick(() => { this.showError = false; })
            .width(100)
            .height(40)
            .margin(10);
        }
        .width('80%')
        .backgroundColor('#FFFFFF')
        .borderRadius(8)
        .shadow({ radius: 10, color: '#000000', offsetX: 0, offsetY: 0 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

