import { Column, Row, Flex, Text } from '@ohos.arkui.component';
import { Canvas, CanvasRenderingContext2D } from '@ohos.arkui.UIContext';
import { TouchEvent } from '@ohos.arkui.component';

@Entry
@Component
struct CustomColorPicker {
  @State selectedColor: string = '#FF0000';
  private colors: string[] = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FF00FF'];
  @State private swipeCoordinates: string = '';
  private context: CanvasRenderingContext2D | null = null;

  build() {
    Column({ space: 10 }) {
      Row()
        .width(100)
        .height(100)
        .backgroundColor(this.selectedColor)
        .borderRadius(10)
        .margin({ bottom: 20 });

      Text(`Selected Color: ${this.selectedColor}`)
        .fontSize(16)
        .margin({ bottom: 20 });

      Flex({ wrap: FlexWrap.Wrap, justifyContent: FlexAlign.SpaceAround }) {
        ForEach(this.colors, (color: string) => {
          Row()
            .width(50)
            .height(50)
            .backgroundColor(color)
            .borderRadius(25)
            .margin(10)
            .onClick(() => {
              this.selectedColor = color;
            });
        });
      }
      .margin({ bottom: 20 });

      Canvas(this.context)
        .width(200)
        .height(200)
        .backgroundColor('#F5F5F5')
        .onTouch((event: TouchEvent) => {
          if (event.type === 'down') {
            this.swipeCoordinates = `X: ${event.touches[0].x}, Y: ${event.touches[0].y}`;
            console.log(this.swipeCoordinates);
          }
        })
        .onReady(() => {
          if (this.context) {
            this.context.fillStyle = this.selectedColor;
            this.context.fillRect(0, 0, 200, 200);
          }
        });
    }
    .padding(20)
    .width('100%')
    .height('100%');
  }
}

