import { Tabs, TabContent, TextInput, Button, Text, Column, Stack } from '@ohos.arkui.advanced'
import { FlexAlign, HorizontalAlign, FontWeight, BarPosition } from '@ohos.arkui.common'
import { PanGesture, GestureType } from '@ohos.multimodalInput.gesture'

@Entry
@Component
struct DataEncryptionApp {
  @State activeTab: number = 0
  @State message: string = ''
  @State encryptedMessage: string = ''

  encryptMessage(): void {
    let result = ''
    for (let i = 0; i < this.message.length; i++) {
      let char = this.message[i]
      if (char.match(/[a-z]/i)) {
        const code = this.message.charCodeAt(i)
        if (code >= 65 && code <= 90) {
          char = String.fromCharCode(((code - 65 + 3) % 26) + 65)
        } else if (code >= 97 && code <= 122) {
          char = String.fromCharCode(((code - 97 + 3) % 26) + 97)
        }
      }
      result += char
    }
    this.encryptedMessage = result
  }

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.Start }) {
        TabContent() {
          Column() {
            TextInput({
              placeholder: 'Enter your message',
              text: this.message
            })
            .width('80%')
            .height(50)
            .backgroundColor('#f5f5f5')
            .onChange((value: string) => {
              this.message = value
            })
            .margin({ bottom: 20 })

            Button('Encrypt Message')
              .width('60%')
              .height(50)
              .fontSize(20)
              .onClick(() => this.encryptMessage())
              .margin({ bottom: 20 })

            if (this.encryptedMessage) {
              Text('Encrypted Message: ' + this.encryptedMessage)
                .fontSize(20)
                .fontColor('#4CAF50')
                .fontWeight(FontWeight.Bold)
                .margin({ top: 20 })
            }
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center)
          .alignItems(HorizontalAlign.Center)
        }
        .tabBar('Encrypt')

        TabContent() {
          Column() {
            Text('Swipe left or right to switch tabs')
              .fontSize(18)
              .fontWeight(FontWeight.Bold)
              .margin({ bottom: 20 })

            Stack() {
              Column() {
                Text('Swipe here')
                  .gesture(
                    PanGesture({ type: GestureType.Pan })
                      .onActionStart(() => {
                        // Handle swipe gesture for tab navigation
                      })
                  )
              }
              .width('100%')
              .height(100)
            }
            .width('100%')
            .height(100)
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center)
          .alignItems(HorizontalAlign.Center)
        }
        .tabBar('Gesture')
      }
      .width('100%')
      .height('100%')
    }
    .width('100%')
    .height('100%')
  }
}

