  sliderTrack: string;
  sliderThumb: string;
  starFilled: string;
  starEmpty: string;
}

@Entry
@Component
struct ThemeApp {
  @State currentTheme: string = 'light';
  @State sliderValue: number = 50;
  @State ratingValue: number = 2.5;
  @State windowOrientation: window.WindowMode = window.WindowMode.FULLSCREEN;

  private lightThemeColors: ThemeColors = {
    background: '#FFFFFF',
    text: '#000000',
    sliderTrack: '#CCCCCC',
    sliderThumb: '#007AFF',
    starFilled: '#FFD700',
    starEmpty: '#CCCCCC',
  };

  private darkThemeColors: ThemeColors = {
    background: '#000000',
    text: '#FFFFFF',
    sliderTrack: '#333333',
    sliderThumb: '#0A84FF',
    starFilled: '#FFD700',
    starEmpty: '#666666',
  };

  private getThemeColors(): ThemeColors {
    return this.currentTheme === 'light' ? this.lightThemeColors : this.darkThemeColors;
  }

  aboutToAppear() {
    const context = getContext(this) as common.UIAbilityContext;
    window.getLastWindow(context).then((win) => {
      this.windowOrientation = win.getWindowMode();
      win.on('windowSizeChange', () => {
        this.windowOrientation = win.getWindowMode();
      });
    });
  }

  build() {
    const colors = this.getThemeColors();

    Flex({ direction: FlexDirection.Column, alignItems: FlexAlign.Center }) {
      Column() {
        Text('Select Theme')
          .fontSize(18)
          .fontColor(colors.text);

        RadioGroup({ name: 'themeGroup' })
          .margin({ bottom: 20 }) {
          Column() {
            Row() {
              Radio({ value: 'light' })
                .checked(this.currentTheme === 'light')
                .onChange((isChecked: boolean) => {
                  if (isChecked) this.currentTheme = 'light';
                });
              Text('Light Theme')
                .fontColor(colors.text);
            }
            Row() {
              Radio({ value: 'dark' })
                .checked(this.currentTheme === 'dark')
                .onChange((isChecked: boolean) => {
                  if (isChecked) this.currentTheme = 'dark';
                });
              Text('Dark Theme')
                .fontColor(colors.text);
            }
          }
        }

        Text(`Slider Value: ${this.sliderValue}`)
          .fontSize(16)
          .fontColor(colors.text);

        Slider({
          value: this.sliderValue,
          min: 0,
          max: 100,
          step: 1
        })
          .blockColor(colors.sliderThumb)
          .trackColor(colors.sliderTrack)
          .onChange((value: number) => {
            this.sliderValue = value;
          });

        Text(`Rating: ${this.ratingValue}`)
          .fontSize(16)
          .fontColor(colors.text);

        Rating({
          rating: this.ratingValue,
          indicator: true
        })
          .stars(5)
          .stepSize(0.5)
          .backgroundStyle(colors.starEmpty)
          .foregroundStyle(colors.starFilled)
          .onChange((value: number) => {
            this.ratingValue = value;
          });
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(colors.background);
  }
}

@Entry
@Component
struct ColorPickerApp {
  @State selectedColor: string = '#FF0000'
  @State colorHistory: string[] = []
  private colors: string[] = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FF00FF', '#FFA500']

  build() {
    Column() {
      // Display selected color
      Row() {
        Text('Selected Color:')
          .fontSize(20)
          .margin({ bottom: 10 })

        Row()
          .width(50)
          .height(50)
          .backgroundColor(this.selectedColor)
          .borderRadius(25)
      }
      .margin({ bottom: 20 })

      // Color options with SwipeGesture
      Flex({ wrap: FlexWrap.Wrap, justifyContent: FlexAlign.SpaceAround }) {
        ForEach(this.colors, (color: string) => {
          Row()
            .width(50)
            .height(50)
            .backgroundColor(color)
            .borderRadius(25)
            .onClick(() => {
              this.selectedColor = color
              this.colorHistory.push(color)
            })
            .gesture(
              SwipeGesture({ direction: SwipeDirection.All })
                .onAction(() => {
                  this.selectedColor = color
                  this.colorHistory.push(color)
                })
            )
            .margin(5)
        })
      }

      // Chart for color history
      if (this.colorHistory.length > 0) {
        Text('Color History Chart')
          .fontSize(16)
          .margin({ top: 20 })
      }
    }
    .padding(20)
    .backgroundColor('#FFFFFF')
    .width('100%')
    .height('100%')
  }
}

import media from '@ohos.multimedia.media';
import { Button, Row, Column, Text } from '@ohos.arkui.advanced';

interface Question {
  text: string;
  options: string[];
  correctAnswer: number;
}

@Entry
@Component
struct QuizApp {
  @State questions: Question[] = [
    {
      text: "Sample question 1",
      options: ["Option A", "Option B", "Option C", "Option D"],
      correctAnswer: 1
    }
  ];
  @State currentQuestionIndex: number = 0;
  @State score: number = 0;
  @State showFeedback: boolean = false;
  @State isCorrect: boolean = false;

  private videoController: media.AVPlayerController = new media.AVPlayerController();
  @State isPlaying: boolean = false;

  checkAnswer(selectedIndex: number): void {
    const correct = selectedIndex === this.questions[this.currentQuestionIndex].correctAnswer;
    this.isCorrect = correct;
    this.showFeedback = true;
    if (correct) {
      this.score++;
    }
  }

  nextQuestion(): void {
    this.showFeedback = false;
    if (this.currentQuestionIndex < this.questions.length - 1) {
      this.currentQuestionIndex++;
    }
  }

  build() {
    Column() {
      if (this.currentQuestionIndex < this.questions.length) {
        Text(this.questions[this.currentQuestionIndex].text)
          .fontSize(20)
          .margin({ bottom: 20 });

        ForEach(this.questions[this.currentQuestionIndex].options, (option: string, index: number) => {
          Button(option)
            .onClick(() => this.checkAnswer(index))
            .margin({ bottom: 10 });
        }, (option: string) => option);

        if (this.showFeedback) {
          Text(this.isCorrect ? 'Correct!' : 'Incorrect!')
            .fontSize(18)
            .margin({ top: 20 });
        }

        Button('Next Question')
          .onClick(() => this.nextQuestion())
          .margin({ top: 20 });
      } else {
        Column() {
          Text('Quiz Completed!')
            .fontSize(24)
            .margin({ bottom: 20 });

          Text(`Score: ${this.score}/${this.questions.length}`)
            .fontSize(20);
        }
      }

      Video({
        src: $rawfile('video_sample.mp4'),
        controller: this.videoController
      })
      .width('100%')
      .height(300)
      .onStart(() => {
        this.isPlaying = true;
      })
      .onPause(() => {
        this.isPlaying = false;
      });

      Button(this.isPlaying ? 'Pause' : 'Play')
        .onClick(() => {
          if (this.isPlaying) {
            this.videoController.pause();
          } else {
            this.videoController.play();
          }
        });
    }
    .width('100%')
    .padding(20);
  }
}

@Entry
@Component
struct MultiTabApp {
  @State currentIndex: number = 0;
  private tabLabels: string[] = ["Home", "Profile", "Settings"];
  private tabContents: string[] = ["Home Content", "Profile Content", "Settings Content"];
  @State badgeCounts: number[] = [1, 0, 3];
  @State marqueeOffset: number = 0;

  build() {
    Column() {
      Row() {
        ForEach(this.tabLabels, (label: string, index: number) => {
          Column() {
            Stack() {
              Text(label)
                .fontSize(16)
                .fontColor(this.currentIndex === index ? Color.Blue : Color.Gray)
                .margin(10)
                .onClick(() => {
                  this.currentIndex = index;
                });

              if (this.badgeCounts[index] > 0) {
                Text(this.badgeCounts[index].toString())
                  .fontSize(12)
                  .fontColor(Color.White)
                  .backgroundColor(Color.Red)
                  .borderRadius(10)
                  .padding(5)
                  .position({ x: '80%', y: '0%' });
              }
            }
          }
          .width('33%')
          .height(50)
          .justifyContent(FlexAlign.Center);
        });
      }
      .width('100%')
      .height(50)
      .backgroundColor('#F5F5F5');

      Text(this.tabContents[this.currentIndex])
        .fontSize(20)
        .textAlign(TextAlign.Center)
        .margin(20);

      Text("This is a scrolling marquee text for dynamic content display.")
        .fontSize(16)
        .fontColor(Color.Black)
        .width('90%')
        .height(30)
        .margin(20)
        .clip(true)
        .onAppear(() => {
          animateTo({ duration: 10000, curve: Curve.Linear }, () => {
            this.marqueeOffset = -200;
          });
        })
        .translate({ x: this.marqueeOffset });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

