import { SegmentedControl, SegmentedItem, Rating } from '@ohos.arkui.advancedUI';
import { FlexAlign } from '@ohos.arkui.advancedUI';

@Entry
@Component
struct FitnessTracker {
  @State currentView: number = 0;
  @State steps: number = 0;
  @State calories: number = 0;
  @State heartRate: number = 70;
  private intervalId: number = 0;

  aboutToAppear() {
    this.startUpdates();
  }

  aboutToDisappear() {
    clearInterval(this.intervalId);
  }

  startUpdates() {
    this.intervalId = setInterval(() => {
      this.steps += Math.floor(Math.random() * 10) + 1;
      this.calories += Math.random() * 4.5 + 0.5;
      this.heartRate = Math.floor(Math.random() * 41) + 60;
    }, 1000);
  }

  build() {
    Column({ space: 20 }) {
      SegmentedControl() {
        SegmentedItem('Steps')
        SegmentedItem('Calories')
        SegmentedItem('Heart Rate')
      }
      .selected(this.currentView)
      .margin({ top: 20 })
      .onChange((index: number) => {
        this.currentView = index;
      });

      Column() {
        if (this.currentView === 0) {
          Text('Steps')
            .fontSize(18);
          Text(this.steps.toString())
            .fontSize(48);
        } else if (this.currentView === 1) {
          Text('Calories Burned')
            .fontSize(18);
          Text(this.calories.toFixed(1))
            .fontSize(48);
        } else {
          Text('Heart Rate')
            .fontSize(18);
          Text(this.heartRate.toString() + ' bpm')
            .fontSize(48);
        }
      }
      .opacity(1)
      .animation({ duration: 300, curve: 'ease-in-out' });

      Rating({ rating: 3, indicator: true })
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

