import { Tabs, TabContent, BarPosition } from '@ohos.arkui.tabs';
import { Button, Text, Progress } from '@ohos.arkui.component';
import { FlexAlign } from '@ohos.arkui.layout';

interface Session {
  duration: string;
}

@Entry
@Component
struct MeditationTimer {
  @State minutes: number = 5;
  @State seconds: number = 0;
  @State isRunning: boolean = false;
  @State sessions: Array<Session> = [];
  private timerId: number = -1;

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.Start }) {
        TabContent() {
          Column() {
            Text(`${this.minutes.toString().padStart(2, '0')}:${this.seconds.toString().padStart(2, '0')}`)
              .fontSize(48)
              .margin({ bottom: 20 });

            Row({ space: 20 }) {
              Button(this.isRunning ? 'Stop' : 'Start')
                .width(120)
                .height(50)
                .backgroundColor(this.isRunning ? '#FF0000' : '#00FF00')
                .onClick(() => {
                  if (this.isRunning) {
                    clearInterval(this.timerId);
                  } else {
                    this.timerId = setInterval(() => {
                      if (this.seconds === 0) {
                        if (this.minutes === 0) {
                          clearInterval(this.timerId);
                          this.isRunning = false;
                          this.sessions.push({ duration: `${this.minutes.toString().padStart(2, '0')}:${this.seconds.toString().padStart(2, '0')}` } as Session);
                        } else {
                          this.minutes--;
                          this.seconds = 59;
                        }
                      } else {
                        this.seconds--;
                      }
                    }, 1000);
                  }
                  this.isRunning = !this.isRunning;
                });

              Button('Reset')
                .width(120)
                .height(50)
                .backgroundColor('#808080')
                .onClick(() => {
                  clearInterval(this.timerId);
                  this.minutes = 5;
                  this.seconds = 0;
                  this.isRunning = false;
                });
            }
            .justifyContent(FlexAlign.Center)
            .margin({ bottom: 20 });
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center);
        }
        .tabBar('Timer');

        TabContent() {
          Column() {
            ForEach(this.sessions, (session: Session, index: number) => {
              Row() {
                Text(`Session ${index + 1}: ${session.duration}`)
                  .fontSize(18)
                  .margin({ right: 10 });

                Progress({ value: parseInt(session.duration.split(':')[0]), total: 10 })
                  .width('60%')
                  .height(10)
                  .backgroundColor('#808080');
              }
              .width('100%')
              .margin({ bottom: 10 });
            });
          }
          .width('100%')
          .height('100%')
          .padding(20);
        }
        .tabBar('Statistics');
      }
    }
    .width('100%')
    .height('100%');
  }

  aboutToDisappear() {
    if (this.timerId !== -1) {
      clearInterval(this.timerId);
    }
  }
}

@Entry
@Component
struct TimerQuiz {
  @State timeLeft: number = 30;
  @State currentQuestion: number = 0;
  @State score: number = 0;
  @State isRunning: boolean = false;
  @State enableCaching: boolean = false;
  @State cacheQuestions: boolean = false;
  private intervalId: number = -1;

  private questions: string[] = [
    "What is the capital of France?",
    "Which planet is known as the Red Planet?",
    "What is the largest mammal?"
  ];

  private answers: string[] = ["Paris", "Mars", "Blue Whale"];

  startTimer() {
    if (this.intervalId === -1) {
      this.isRunning = true;
      this.intervalId = setInterval(() => {
        if (this.timeLeft > 0) {
          this.timeLeft--;
        } else {
          clearInterval(this.intervalId);
          this.intervalId = -1;
          this.isRunning = false;
          this.nextQuestion();
        }
      }, 1000);
    }
  }

  stopTimer() {
    clearInterval(this.intervalId);
    this.intervalId = -1;
    this.isRunning = false;
  }

  resetTimer() {
    this.stopTimer();
    this.timeLeft = 30;
  }

  nextQuestion() {
    if (this.currentQuestion < this.questions.length - 1) {
      this.currentQuestion++;
      this.resetTimer();
    } else {
      this.stopTimer();
    }
  }

  submitAnswer(answer: string) {
    if (answer === this.answers[this.currentQuestion]) {
      this.score++;
    }
    this.nextQuestion();
  }

  build() {
    Column() {
      Text(`Time Left: ${this.timeLeft}s`)
        .fontSize(24)
        .margin(20);

      Text(`Question: ${this.questions[this.currentQuestion]}`)
        .fontSize(20)
        .margin(10);

      Row() {
        Button("Start Timer")
          .onClick(() => this.startTimer())
          .margin(5);

        Button("Stop Timer")
          .onClick(() => this.stopTimer())
          .margin(5);

        Button("Reset Timer")
          .onClick(() => this.resetTimer())
          .margin(5);
      }

      Row() {
        Button("Paris")
          .onClick(() => this.submitAnswer("Paris"))
          .margin(5);

        Button("Mars")
          .onClick(() => this.submitAnswer("Mars"))
          .margin(5);

        Button("Blue Whale")
          .onClick(() => this.submitAnswer("Blue Whale"))
          .margin(5);
      }

      Text(`Score: ${this.score}`)
        .fontSize(20)
        .margin(10);

      Row() {
        Text("Enable Caching")
          .fontSize(16)
          .margin(5);

        Toggle({ type: ToggleType.Checkbox })
          .onChange((isOn: boolean) => {
            this.enableCaching = isOn;
          })
          .margin(5);
      }

      Row() {
        Text("Cache Questions")
          .fontSize(16)
          .margin(5);

        Toggle({ type: ToggleType.Checkbox })
          .onChange((isOn: boolean) => {
            this.cacheQuestions = isOn;
          })
          .margin(5);
      }
    }
    .width("100%")
    .height("100%")
    .backgroundColor("#ffffff");
  }
}

