@Component
struct LanguageLearningApp {
  @State selectedDate: Date = new Date()
  @State displayDate: string = ''
  @State inputText: string = ''
  @State canvasContext: CanvasRenderingContext2D | null = null

  updateDisplayDate() {
    this.displayDate = this.selectedDate.toLocaleDateString()
  }

  drawText() {
    if (this.canvasContext) {
      this.canvasContext.clearRect(0, 0, 1000, 200)
      this.canvasContext.fillStyle = '#000000'
      this.canvasContext.font = '20px sans-serif'
      this.canvasContext.fillText(this.inputText, 10, 30)
    }
  }

  build() {
    Column() {
      Text('Language Learning App')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      DatePicker({
        start: new Date('2000-01-01'),
        end: new Date('2030-12-31'),
        selected: this.selectedDate
      })
      .onDateChange((value: Date) => {
        this.selectedDate = value
        this.updateDisplayDate()
      })
      .margin({ bottom: 20 })

      Text(`Selected: ${this.displayDate}`)
        .fontSize(18)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter text' })
        .onChange((value: string) => {
          this.inputText = value
