import { List, ListItem, Column, Row, Text, Image, Toggle, FontWeight, ToggleType } from '@ohos.arkui.advanced';
import { TouchEvent, TouchType } from '@ohos.arkui.gesture.Gesture';

interface Order {
  id: string;
  name: string;
  status: boolean;
}

@Entry
@Component
struct FoodDeliveryApp {
  @State orders: Order[] = [
    { id: '1', name: 'Burger', status: false },
    { id: '2', name: 'Pizza', status: true },
    { id: '3', name: 'Salad', status: false },
    { id: '4', name: 'Pasta', status: true },
    { id: '5', name: 'Sushi', status: false }
  ];

  @State draggingIndex: number = -1;
  @State targetIndex: number = -1;

  build() {
    Column() {
      Text('Food Delivery Orders')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      List() {
        ForEach(this.orders, (order: Order, index: number) => {
          ListItem() {
            Row() {
              Image($r('app.media.food_placeholder'))
                .width(40)
                .height(40)
                .margin({ right: 10 });

              Column() {
                Text(order.name)
                  .fontSize(18)
                  .fontWeight(FontWeight.Medium);

                Toggle({ type: ToggleType.Switch, isOn: order.status })
                  .onChange((isOn: boolean) => {
                    this.orders[index].status = isOn;
                  });
              }
              .alignItems(HorizontalAlign.Start)
              .justifyContent(FlexAlign.SpaceBetween)
              .width('70%');
            }
            .padding(10)
            .width('100%')
            .opacity(this.draggingIndex === index ? 0.5 : 1)
            .backgroundColor(this.targetIndex === index ? '#e6f7ff' : '#ffffff')
            .border({ width: 1, color: '#d9d9d9' })
            .onTouch((event: TouchEvent) => {
              if (event.type === TouchType.Down) {
                this.draggingIndex = index;
              }
              if (event.type === TouchType.Move && this.draggingIndex >= 0) {
                this.targetIndex = index;
              }
              if (event.type === TouchType.Up) {
                if (this.draggingIndex >= 0 && this.targetIndex >= 0 && this.draggingIndex !== this.targetIndex) {
                  const newOrders = [...this.orders];
                  const removed = newOrders.splice(this.draggingIndex, 1)[0];
                  newOrders.splice(this.targetIndex, 0, removed);
                  this.orders = newOrders;
                }
                this.draggingIndex = -1;
                this.targetIndex = -1;
              }
            });
          }
        }, (order: Order) => order.id);
      }
      .width('100%')
      .height('80%')
      .divider({ strokeWidth: 1, color: '#f0f0f0' });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

