@Entry
@Component
struct EventPlanningApp {
  @State selectedTab: string = 'Home';
  @State eventName: string = '';
  @State eventDate: string = '';
  @State eventLocation: string = '';
  @State tags: string[] = [];
  @State newTag: string = '';
  @State errors: FormErrors = { name: false, date: false, location: false };

  build() {
    Column() {
      // Navigation Menu
      Tabs({ barPosition: 'top' }) {
        TabContent() {
          Text('Home Content')
            .fontSize(16);
        }.tabBar('Home')
        TabContent() {
          Text('Events Content')
            .fontSize(16);
        }.tabBar('Events')
        TabContent() {
          Text('Settings Content')
            .fontSize(16);
        }.tabBar('Settings')
        TabContent() {
          Text('Profile Content')
            .fontSize(16);
        }.tabBar('Profile')
      }
      .onChange((index: number) => {
        const tabs = ['Home', 'Events', 'Settings', 'Profile'];
        this.selectedTab = tabs[index];
      })
      .width('100%')
      .height(48);

      // Event Form
      Column() {
        TextInput({ placeholder: 'Event Name' })
          .onChange((value: string) => {
            this.eventName = value;
            this.errors.name = value === '';
          })
          .width('100%')
          .margin({ bottom: 8 });
        if (this.errors.name) {
          Text('Event name is required')
            .fontSize(12)
            .fontColor('#FF3B30')
            .margin({ bottom: 8 });
        }

        TextInput({ placeholder: 'Event Date' })
          .onChange((value: string) => {
            this.eventDate = value;
            this.errors.date = value === '';
          })
          .width('100%')
          .margin({ bottom: 8 });
        if (this.errors.date) {
          Text('Event date is required')
            .fontSize(12)
            .fontColor('#FF3B30')
            .margin({ bottom: 8 });
        }

        TextInput({ placeholder: 'Event Location' })
          .onChange((value: string) => {
            this.eventLocation = value;
            this.errors.location = value === '';
          })
          .width('100%')
          .margin({ bottom: 8 });
        if (this.errors.location) {
          Text('Event location is required')
            .fontSize(12)
            .fontColor('#FF3B30')
            .margin({ bottom: 8 });
        }

        // Tag Management
        Row() {
          TextInput({ placeholder: 'Add Tag' })
            .onChange((value: string) => {
              this.newTag = value;
            })
            .width('70%')
            .margin({ right: 8 });
          Button('Add')
            .onClick(() => {
              if (this.newTag.trim() !== '') {
                this.tags.push(this.newTag.trim());
                this.newTag = '';
              }
            })
            .width('30%');
        }
        .width('100%')
        .margin({ bottom: 8 });

        Flex({ wrap: 'wrap' }) {
          ForEach(this.tags, (tag: string, index: number) => {
            Button(tag)
              .borderRadius(20)
              .backgroundColor('#E5E5EA')
              .fontColor('#000000')
              .margin({ right: 8, bottom: 8 })
              .onClick(() => {
                this.tags.splice(index, 1);
              });
          });
        }
        .width('100%');

        // Form Submission
        Button('Submit')
          .onClick(() => {
            const isValid = this.eventName !== '' && this.eventDate !== '' && this.eventLocation !== '';
            if (isValid) {
              console.log('Event Data:', {
                name: this.eventName,
                date: this.eventDate,
                location: this.eventLocation,
                tags: this.tags
              });
            } else {
              this.errors = {
                name: this.eventName === '',
                date: this.eventDate === '',
                location: this.eventLocation === ''
              };
            }
          })
          .width('100%')
          .margin({ top: 16 });
      }
      .width('100%');
    }
  }
}

interface TimeValue {
  hour: number;
  minute: number;
}

@Entry
@Component
struct ABTestingApp {
  @State currentStep: number = 0;
  @State selectedDate: Date = new Date();
  @State selectedTime: Date = new Date();
  @State currentVariation: string = 'A';

  updateVariation() {
    const hour = this.selectedTime.getHours();
    this.currentVariation = hour < 12 ? 'A' : 'B';
  }

  build() {
    Column() {
      Text('A/B Testing with Stepper')
        .fontSize(20)
        .margin({ bottom: 20 });

      Stepper() {
        StepperItem() {
          Text('Step 1')
        }
        StepperItem() {
          Text('Step 2')
        }
        StepperItem() {
          Text('Step 3')
        }
      }
      .margin({ bottom: 20 });

      DatePicker({
        start: new Date(new Date().getFullYear(), 0, 1),
        end: new Date(new Date().getFullYear(), 11, 31),
        selected: this.selectedDate
      })
      .onDateChange((value: Date) => {
        this.selectedDate = value;
        this.updateVariation();
      })
      .margin({ bottom: 20 });

      TimePicker({
        selected: this.selectedTime
      })
      .onChange((value: TimeValue) => {
        const newTime = new Date();
        newTime.setHours(value.hour, value.minute);
        this.selectedTime = newTime;
        this.updateVariation();
      })
      .margin({ bottom: 20 });

      Text(`Current Variation: ${this.currentVariation}`)
        .fontSize(16)
        .margin({ bottom: 20 });

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentStep > 0) {
              this.currentStep--;
            }
          })
          .margin({ right: 10 });

        Button('Next')
          .onClick(() => {
            if (this.currentStep < 2) {
              this.currentStep++;
            }
          });
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

