import { Breadcrumb, BreadcrumbItem, Button, Column, Text, TextInput, Dialog } from '@ohos.arkui.component';
import sensor from '@ohos.sensors.service';
import abilityAccessCtrl from '@ohos.abilityAccessCtrl';
import common from '@ohos.app.ability.common';

@Entry
@Component
struct GestureDialogApp {
  @State name: string = '';
  @State age: number = 0;
  @State gestureType: string = 'No gesture detected';
  @State showDialog: boolean = false;

  aboutToAppear() {
    this.requestPermission();
  }

  aboutToDisappear() {
    this.cleanupSensor();
  }

  private requestPermission() {
    try {
      let context = getContext(this) as common.UIAbilityContext;
      let atManager = abilityAccessCtrl.createAtManager();
      atManager.requestPermissionsFromUser(context, ['ohos.permission.ACCELEROMETER'])
        .then((data) => {
          this.setupGestureDetection();
        })
        .catch((err) => {
          console.error(`Failed to request permissions, error: ${JSON.stringify(err)}`);
        });
    } catch (err) {
      console.error(`Failed to request permissions, error: ${JSON.stringify(err)}`);
    }
  }

  private setupGestureDetection() {
    try {
      sensor.on(sensor.SensorType.SENSOR_TYPE_GESTURE, (data) => {
        if (data === sensor.Gesture.SHAKE) {
          this.gestureType = 'Shake detected';
        } else if (data === sensor.Gesture.FLIP) {
          this.gestureType = 'Flip detected';
        }
      }, { interval: 200 });
    } catch (error) {
      console.error('Failed to setup gesture detection');
    }
  }

  private cleanupSensor() {
    try {
      sensor.off(sensor.SensorType.SENSOR_TYPE_GESTURE);
    } catch (error) {
      console.error('Failed to cleanup sensor');
    }
  }

  private toggleDialog() {
    this.showDialog = !this.showDialog;
  }

  build() {
    Column({ space: 20 }) {
      Breadcrumb() {
        BreadcrumbItem() {
          Text('Home')
        }
        BreadcrumbItem() {
          Text('Gesture')
        }
        BreadcrumbItem() {
          Text('Dialog')
        }
      }

      TextInput({ placeholder: 'Enter your name' })
        .onChange((value: string) => {
          this.name = value;
        })

      TextInput({ placeholder: 'Enter your age' })
        .onChange((value: string) => {
          const parsedAge = parseInt(value);
          this.age = isNaN(parsedAge) ? 0 : parsedAge;
        })

      Text(`Last Gesture: ${this.gestureType}`)
        .fontSize(16)

      Button('Toggle Dialog')
        .onClick(() => {
          this.toggleDialog();
        })

      if (this.showDialog) {
        Dialog({
          title: 'Gesture Recognition',
          message: 'Perform a gesture to detect',
          confirm: {
            value: 'Close',
            action: () => {
              this.toggleDialog();
            }
          }
        })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

