import { Swiper, SwiperController, Chip, Badge, Image, Column, Row, Button, Stack } from '@ohos.arkui.advanced';
import { ChipType, FlexAlign } from '@ohos.arkui.component';

@Entry
@Component
struct StepCounterMap {
  @State currentIndex: number = 0;
  @State stepCounts: number[] = [2500, 5000, 7500, 10000];
  @State activities: string[] = ['Walking', 'Running', 'Cycling', 'Hiking'];
  private swiperController: SwiperController = new SwiperController();

  build() {
    Column() {
      Row() {
        ForEach(this.activities, (activity: string, index: number) => {
          Chip({
            type: ChipType.Filter,
            label: activity
          })
          .margin(5)
          .selected(this.currentIndex === index)
          .selectedBackgroundColor('#007DFF')
          .selectedTextColor('#FFFFFF')
          .onClick(() => {
            this.currentIndex = index;
            this.swiperController.showNext({ index: index });
          });
        })
      }
      .justifyContent(FlexAlign.Center)
      .margin({ top: 20, bottom: 20 });

      Swiper(this.swiperController) {
        ForEach(this.activities, (activity: string, index: number) => {
          Stack() {
            Image($r('app.media.ic_public_map'))
              .objectFit('cover')
              .width('100%')
              .height('100%');

            Badge({
              value: this.stepCounts[index].toString()
            })
            .badgeSize(24)
            .badgeColor('#FF0000')
            .textColor('#FFFFFF')
            .position({ x: '90%', y: '10%' });
          }
        })
      }
      .index(this.currentIndex)
      .onChange((index: number) => {
        this.currentIndex = index;
      })
      .width('100%')
      .height('60%');

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentIndex > 0) {
              this.currentIndex--;
              this.swiperController.showPrevious();
            }
          })
          .enabled(this.currentIndex > 0)
          .margin(10);

        Button('Next')
          .onClick(() => {
            if (this.currentIndex < this.activities.length - 1) {
              this.currentIndex++;
              this.swiperController.showNext();
            }
          })
          .enabled(this.currentIndex < this.activities.length - 1)
          .margin(10);
      }
      .justifyContent(FlexAlign.Center)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

import { Badge, List, ListItem, Column, Stack, Text, Row } from '@ohos.arkui.advanced';
import { Color, TextDecorationType, ResourceColor } from '@ohos.arkui.drawing';
import router from '@ohos.router.router';
import { BusinessError } from '@ohos.base';

interface SensorData {
  x: number;
  y: number;
  z: number;
}

interface Position {
  x: number;
  y: number;
}

interface BadgeConfig {
  color: ResourceColor;
  backgroundColor: ResourceColor;
  size: number;
  position: Position;
}

interface BadgeStyle {
  color: ResourceColor;
  backgroundColor: ResourceColor;
  fontSize: number;
}

interface ListItemType {
  id: string;
  label: string;
}

@Entry
@Component
struct MainPage {
  @State private sensorData: SensorData = { x: 0, y: 0, z: 0 };
  @State private badgeCount: number = 0;
  @State private badgeConfig: BadgeConfig = {
    color: Color.White,
    backgroundColor: Color.Red,
    size: 20,
    position: { x: 80, y: 0 }
  };
  @State private listItems: ListItemType[] = Array.from<ListItemType, ListItemType>({length: 10}, (_, i): ListItemType => ({
    id: `item_${i}`,
    label: `Item ${i + 1}`
  }));
  @State private breadcrumbs: string[] = ['Home'];
  private sensorInterval: number = 0;

  simulateSensorUpdates(): void {
    this.sensorInterval = setInterval(() => {
      this.sensorData = {
        x: Math.random() * 10 - 5,
        y: Math.random() * 10 - 5,
        z: Math.random() * 10 - 5
      };
      this.badgeCount++;
    }, 1000);
  }

  onPageShow(): void {
    this.simulateSensorUpdates();
  }

  onPageHide(): void {
    if (this.sensorInterval) {
      clearInterval(this.sensorInterval);
    }
  }

  loadMoreItems(): void {
    const newItems: ListItemType[] = Array.from<ListItemType, ListItemType>({length: 5}, (_, i): ListItemType => ({
      id: `item_${this.listItems.length + i}`,
      label: `Item ${this.listItems.length + i + 1}`
    }));
    this.listItems = [...this.listItems, ...newItems];
  }

  handleBreadcrumbClick(index: number): void {
    this.breadcrumbs = this.breadcrumbs.slice(0, index + 1);
  }

  handleListItemClick(item: ListItemType): void {
    this.breadcrumbs.push(item.label);
  }

  build() {
    Column() {
      Stack() {
        Column() {
          Text(`X: ${this.sensorData.x.toFixed(2)}`)
          Text(`Y: ${this.sensorData.y.toFixed(2)}`)
          Text(`Z: ${this.sensorData.z.toFixed(2)}`)
        }
        .padding(10)
        .backgroundColor(Color.Gray)
        .borderRadius(5)

        if (this.badgeCount > 0) {
          Badge({
            count: this.badgeCount,
            position: this.badgeConfig.position,
            style: { 
              color: this.badgeConfig.color,
              backgroundColor: this.badgeConfig.backgroundColor,
              fontSize: this.badgeConfig.size
            } as BadgeStyle
          })
        }
      }
      .width('100%')
      .height(100)
      .margin({ bottom: 10 })

      Row() {
        ForEach(this.breadcrumbs, (crumb: string, index: number) => {
          Text(crumb)
            .onClick(() => this.handleBreadcrumbClick(index))
            .margin({ right: 5 })
            .textDecoration(TextDecorationType.Underline)
        })
      }
      .width('100%')
      .padding(10)
      .backgroundColor(Color.Gray)

      List({ space: 10 }) {
        ForEach(this.listItems, (item: ListItemType) => {
          ListItem() {
            Text(item.label)
              .onClick(() => this.handleListItemClick(item))
          }
        })
      }
      .onReachEnd(() => this.loadMoreItems())
      .width('100%')
      .height('60%')
    }
    .width('100%')
    .height('100%')
    .padding(10)
  }
}

import { Entry, Component } from '@ohos.arkui.advanced';
import { Column, Text, Button, Image } from '@ohos.arkui.advanced';
import http from '@ohos.net.http';

interface MainData {
  temp: number;
}

interface WeatherItem {
  main: string;
  description: string;
}

interface WeatherData {
  main: MainData;
  weather: WeatherItem[];
  name: string;
}

interface HttpError {
  code: number;
  message: string;
}

@Entry
@Component
struct WeatherApp {
  @State temperature: string = '';
  @State condition: string = '';
  @State location: string = '';
  @State isLoading: boolean = true;
  @State weatherIcon: Resource = $r('app.media.weather_default');
  @State errorMessage: string = '';

  apiKey: string = 'YOUR_API_KEY';
  apiUrl: string = 'https://api.openweathermap.org/data/2.5/weather?q=London&appid=${this.apiKey}&units=metric';
  httpRequest = http.createHttp();

  fetchWeatherData = (): void => {
    this.isLoading = true;
    let options: http.HttpRequestOptions = { method: http.RequestMethod.GET };
    this.httpRequest.request(this.apiUrl, options)
      .then((response: http.HttpResponse) => {
        try {
          if (response.responseCode === http.ResponseCode.OK) {
            const data: WeatherData = JSON.parse(response.result.toString());
            this.temperature = `${Math.round(data.main.temp)}\u00b0C`;
            this.condition = data.weather[0].main;
            this.location = data.name;
            this.updateWeatherIcon(data.weather[0].main);
          }
        } catch (e) {
          this.errorMessage = 'Data parsing error';
        }
        this.isLoading = false;
      })
      .catch((err: HttpError) => {
        this.errorMessage = `Error: ${err.code} - ${err.message}`;
        this.isLoading = false;
      });
  };

  updateWeatherIcon = (condition: string): void => {
    switch (condition) {
      case 'Clear':
        this.weatherIcon = $r('app.media.weather_clear');
        break;
      case 'Clouds':
        this.weatherIcon = $r('app.media.weather_clouds');
        break;
      case 'Rain':
        this.weatherIcon = $r('app.media.weather_rain');
        break;
      default:
        this.weatherIcon = $r('app.media.weather_default');
    }
  };

  build() {
    Column() {
      if (this.isLoading) {
        Text('Loading...')
          .fontSize(24);
      } else {
        Text(this.location)
          .fontSize(24);
        Image(this.weatherIcon)
          .width(100)
          .height(100);
        Text(this.temperature)
          .fontSize(32);
        Button('Refresh')
          .onClick(() => this.fetchWeatherData());
      }
    }
    .width('80%')
    .height('80%')
    .margin({ top: 20, bottom: 20, left: 20, right: 20 });
  }
}

import { Column, Row, Button, Text } from '@ohos.arkui.node';
import media from '@ohos.multimedia.media';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct EventPlannerVideoPlayer {
  private avPlayer: media.AVPlayer | null = null;
  @State isPlaying: boolean = false;
  @State currentTime: number = 0;
  @State duration: number = 0;

  aboutToAppear() {
    this.avPlayer = new media.AVPlayer();
    this.avPlayer.src = 'common/video.mp4';
    this.avPlayer.prepare().then(() => {
      this.duration = this.avPlayer.duration;
    });
  }

  build() {
    Column() {
      media.Video({
        src: 'common/video.mp4',
        controller: this.avPlayer
      })
      .controls(false)
      .autoPlay(false)
      .onPrepared(() => {
        if (this.avPlayer) {
          this.duration = this.avPlayer.duration;
        }
      })
      .onUpdate(() => {
        if (this.avPlayer) {
          this.currentTime = this.avPlayer.currentTime;
        }
      })
      .onError(() => {
        promptAction.showToast({ duration: 2000, message: 'Video playback error.' });
      })
      .width('100%')
      .height(300);

      Row({ space: 10 }) {
        Button(this.isPlaying ? 'Pause' : 'Play')
          .onClick(() => {
            if (this.avPlayer) {
              if (this.isPlaying) {
                this.avPlayer.pause();
              } else {
                this.avPlayer.play();
              }
              this.isPlaying = !this.isPlaying;
            }
          })
          .padding(10);

        Button('Stop')
          .onClick(() => {
            if (this.avPlayer) {
              this.avPlayer.stop();
              this.isPlaying = false;
            }
          })
          .padding(10);
      }
      .margin({ top: 20 });

      Row({ space: 10 }) {
        Text(`Time: ${this.currentTime.toFixed(2)}`);
        Text('/');
        Text(`Duration: ${this.duration.toFixed(2)}`);
      }
      .margin({ top: 10 });
    }
    .padding(20)
    .width('100%')
    .height('100%');
  }
}

