import promptAction from '@ohos.promptAction';
import { Refresh } from '@ohos.arkui.uicontainer';
import { Toggle, ToggleType } from '@ohos.arkui.uicontainer';
import { InputType } from '@ohos.arkui.uicontainer';

@Entry
@Component
struct FormValidationApp {
  @State username: string = '';
  @State password: string = '';
  @State isToggleEnabled: boolean = false;
  @State isRefreshing: boolean = false;
  @State isUsernameValid: boolean = false;
  @State isPasswordValid: boolean = false;
  @State showSuccess: boolean = false;
  @State showError: boolean = false;

  validateUsername(username: string): boolean {
    return username.length >= 3;
  }

  validatePassword(password: string): boolean {
    return password.length >= 6;
  }

  handleRefresh(): void {
    this.isRefreshing = true;
    setTimeout(() => {
      this.isRefreshing = false;
      if (this.isUsernameValid && this.isPasswordValid && this.isToggleEnabled) {
        this.showSuccess = true;
        setTimeout(() => {
          this.showSuccess = false;
        }, 1000);
      } else {
        this.showError = true;
        setTimeout(() => {
          this.showError = false;
        }, 1000);
      }
    }, 2000);
  }

  build() {
    Column() {
      Refresh({
        refreshing: this.isRefreshing,
        onRefresh: () => this.handleRefresh()
      }) {
        Column() {
          TextInput({ placeholder: 'Enter username' })
            .width('100%')
            .height(40)
            .margin({ bottom: 20 })
            .backgroundColor('#f5f5f5')
            .padding({ left: 12 })
            .accessibilityId('usernameInput')
            .accessibilityLabel('Username input field')
            .onChange((value: string) => {
              this.username = value;
              this.isUsernameValid = this.validateUsername(value);
            });

          TextInput({ placeholder: 'Enter password' })
            .type(InputType.Password)
            .width('100%')
            .height(40)
            .margin({ bottom: 20 })
            .backgroundColor('#f5f5f5')
            .padding({ left: 12 })
            .accessibilityId('passwordInput')
            .accessibilityLabel('Password input field')
            .onChange((value: string) => {
              this.password = value;
              this.isPasswordValid = this.validatePassword(value);
            });

          Toggle({ type: ToggleType.Switch, isOn: this.isToggleEnabled })
            .width('100%')
            .height(40)
            .margin({ bottom: 20 })
            .accessibilityId('formToggle')
            .accessibilityLabel('Form agreement toggle')
            .onChange((isOn: boolean) => {
              this.isToggleEnabled = isOn;
            });

          Button('Submit')
            .width('100%')
            .height(50)
            .fontSize(18)
            .backgroundColor(this.isUsernameValid && this.isPasswordValid && this.isToggleEnabled ? '#007AFF' : '#CCCCCC')
            .enabled(this.isUsernameValid && this.isPasswordValid && this.isToggleEnabled)
            .accessibilityId('submitButton')
            .accessibilityLabel('Submit form button')
            .onClick(() => {
              promptAction.showToast({ message: 'Form submitted successfully!' });
            });

          if (this.showSuccess) {
            Text('\u2713')
              .fontSize(24)
              .fontColor('#00FF00')
              .margin({ top: 10 });
          }

          if (this.showError) {
            Text('\u2717')
              .fontSize(24)
              .fontColor('#FF0000')
              .margin({ top: 10 });
          }
        }
        .width('100%')
        .padding(20)
      }
    }
    .width('100%')
    .height('100%')
  }
}

interface Transaction {
  id: number;
  amount: string;
  status: string;
}

@Entry
@Component
struct PaymentApp {
  @State private paymentConfirmed: boolean = false;
  @State private processing: boolean = false;
  @State private progressValue: number = 0;
  @State private transactions: Array<Transaction> = [
    { id: 1, amount: "$10.00", status: "Completed" },
    { id: 2, amount: "$20.00", status: "Pending" },
    { id: 3, amount: "$15.00", status: "Failed" }
  ];

  private processPayment(): void {
    this.processing = true;
    this.progressValue = 0;
    const interval = setInterval(() => {
      this.progressValue += 10;
      if (this.progressValue >= 100) {
        clearInterval(interval);
        this.processing = false;
        this.paymentConfirmed = true;
        this.transactions.unshift({
          id: this.transactions.length + 1,
          amount: "$50.00",
          status: "Completed"
        } as Transaction);
      }
    }, 300);
  }

  build() {
    Column() {
      Text("Payment Confirmation")
        .fontSize(24)
        .margin({ bottom: 20 });

      Image($r('sys.media.ohos_app_icon'))
        .width(150)
        .height(150)
        .margin({ bottom: 20 })
        .gesture(
          SwipeGesture({ direction: SwipeDirection.Horizontal })
            .onAction(() => {
              if (!this.processing && !this.paymentConfirmed) {
                this.processPayment();
              }
            })
        );

      if (this.processing) {
        Progress({ value: this.progressValue, total: 100 })
          .width('80%')
          .margin({ bottom: 20 });
      } else if (this.paymentConfirmed) {
        Text("Payment Confirmed!")
          .fontSize(20)
          .fontColor(Color.Green)
          .margin({ bottom: 20 });
      } else {
        Text("Swipe to Confirm Payment")
          .fontSize(18)
          .margin({ bottom: 20 });
      }

      Text("Transaction History")
        .fontSize(20)
        .margin({ top: 20, bottom: 10 });

      List() {
        ForEach(this.transactions, (item: Transaction) => {
          ListItem() {
            Column() {
              Text(`Amount: ${item.amount}`)
                .fontSize(16);
              Text(`Status: ${item.status}`)
                .fontSize(14)
                .fontColor(item.status === "Completed" ? Color.Green : item.status === "Failed" ? Color.Red : Color.Gray);
            }
            .width('100%')
            .padding(10);
          }
        });
      }
      .width('100%')
      .height('40%');
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Start)
    .alignItems(HorizontalAlign.Center);
  }
}

@Entry
@Component
struct SensorApp {
  @State sensorData: string = 'No data';
  @State errorMessage: string = '';
  @State showErrorSheet: boolean = false;
  @State sensorHistory: string[] = [];
  @State currentPage: number = 1;
  @State itemsPerPage: number = 5;

  fetchSensorData() {
    try {
      this.sensorData = 'Sensor Value: 25.5°C';
      this.sensorHistory.push(this.sensorData);
    } catch (error) {
      this.errorMessage = 'Failed to fetch sensor data';
      this.showErrorSheet = true;
    }
  }

  handleError() {
    this.showErrorSheet = false;
  }

  nextPage() {
    if (this.currentPage * this.itemsPerPage < this.sensorHistory.length) {
      this.currentPage++;
    }
  }

  prevPage() {
    if (this.currentPage > 1) {
      this.currentPage--;
    }
  }

  build() {
    Column() {
      Text('Sensor Data App')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Text(this.sensorData)
        .fontSize(18)
        .margin({ bottom: 20 });

      Button('Fetch Sensor Data')
        .onClick(() => this.fetchSensorData())
        .width('80%')
        .height(40)
        .margin({ bottom: 20 });

      if (this.sensorHistory.length > 0) {
        Text('Sensor History')
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 10 });

        List() {
          ForEach(this.sensorHistory.slice(
            (this.currentPage - 1) * this.itemsPerPage,
            this.currentPage * this.itemsPerPage
          ), (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(16)
                .padding(10);
            }
            .backgroundColor('#f0f0f0')
            .borderRadius(5)
            .margin({ bottom: 10 });
          });
        }
        .width('80%')
        .height(200);

        Row() {
          Button('Previous')
            .onClick(() => this.prevPage())
            .width('40%')
            .height(40)
            .margin({ right: 10 });

          Button('Next')
            .onClick(() => this.nextPage())
            .width('40%')
            .height(40);
        }
        .justifyContent(FlexAlign.Center)
        .margin({ top: 20 });
      }

      if (this.showErrorSheet) {
        Column() {
          Text(this.errorMessage)
            .fontSize(18)
            .margin({ bottom: 20 });

          Button('OK')
            .onClick(() => this.handleError())
            .width('80%')
            .height(40);
        }
        .width('100%')
        .height('100%')
        .backgroundColor('rgba(0, 0, 0, 0.5)')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center);
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

import { Column, Text, Button, Scroll, Row } from '@ohos.arkui.advanced';
import { Badge, BadgePosition } from '@ohos.arkui.advanced.Badge';

interface Flashcard {
  id: string;
  question: string;
  answer: string;
  encrypted: boolean;
}

interface BadgeStyle {
  color: string;
  backgroundColor: string;
}

@Entry
@Component
struct FlashcardApp {
  @State flashcards: Flashcard[] = [
    { id: '1', question: 'What is the capital of France?', answer: 'Paris', encrypted: false },
    { id: '2', question: 'What is the largest planet in our solar system?', answer: 'Jupiter', encrypted: false },
    { id: '3', question: 'Who wrote \"Romeo and Juliet\"?', answer: 'William Shakespeare', encrypted: false }
  ];

  private encryptText(text: string, shift: number): string {
    return text.split('').map(char => {
      const code = char.charCodeAt(0);
      return String.fromCharCode(code + shift);
    }).join('');
  }

  private decryptText(text: string, shift: number): string {
    return text.split('').map(char => {
      const code = char.charCodeAt(0);
      return String.fromCharCode(code - shift);
    }).join('');
  }

  private toggleEncryption(index: number): void {
    const flashcard = this.flashcards[index];
    if (flashcard.encrypted) {
      flashcard.answer = this.decryptText(flashcard.answer, 1);
    } else {
      flashcard.answer = this.encryptText(flashcard.answer, 1);
    }
    flashcard.encrypted = !flashcard.encrypted;
    this.flashcards = [...this.flashcards];
  }

  build() {
    Scroll() {
      Column() {
        ForEach(this.flashcards, (flashcard: Flashcard, index: number) => {
          Column() {
            Text(flashcard.question)
              .fontSize(18)
              .margin({ bottom: 8 });
            Text(flashcard.answer)
              .fontSize(16)
              .margin({ bottom: 8 });
            Row() {
              Button(flashcard.encrypted ? 'Decrypt' : 'Encrypt')
                .onClick(() => this.toggleEncryption(index));
              Badge({
                count: flashcard.encrypted ? '!' : '',
                position: BadgePosition.Right,
                style: { color: '#FFFFFF', backgroundColor: '#FF0000' } as BadgeStyle
              });
            }
          }
          .padding(16)
          .border({ width: 1, color: '#CCCCCC' })
          .margin({ bottom: 16 });
        });
      }
      .width('100%')
      .height('100%');
    }
  }
}

