import abilityAccessCtrl from '@ohos.abilityAccessCtrl';
import sensor from '@ohos.sensor';
import { Column, Text, Button, If, RefreshContainer } from '@ohos.arkui.d.ts';
import { Color } from '@ohos.arkui.d.ts';

interface AccelerometerResponse {
  x: number;
  y: number;
  z: number;
  timestamp: number;
}

@Entry
@Component
struct DocumentViewer {
  @State isContentVisible: boolean = true;
  @State sensorData: number = 0;
  @State isRefreshing: boolean = false;
  private sensorId: number | null = null;
  private context = getContext(this) as common.UIAbilityContext;

  aboutToAppear(): void {
    const atManager = abilityAccessCtrl.createAtManager();
    try {
      atManager.requestPermissionsFromUser(this.context, ['ohos.permission.ACCELEROMETER'])
        .then((data) => {
          if (data.authResults[0] === 0) {
            this.registerSensor();
          }
        });
    } catch (error) {
      console.error('Permission error:', error);
    }
  }

  private registerSensor(): void {
    try {
      this.sensorId = sensor.on(sensor.SensorId.ACCELEROMETER, (data: AccelerometerResponse) => {
        if (data) {
          this.sensorData = data.x;
        }
      }, { interval: 20000 });
    } catch (error) {
      console.error('Sensor registration error:', error);
    }
  }

  aboutToDisappear(): void {
    if (this.sensorId !== null) {
      sensor.off(this.sensorId);
    }
  }

  toggleContent(): void {
    this.isContentVisible = !this.isContentVisible;
  }

  onRefresh(): void {
    this.isRefreshing = true;
    setTimeout(() => {
      this.isRefreshing = false;
    }, 2000);
  }

  build() {
    Column() {
      Button(this.isContentVisible ? 'Hide Content' : 'Show Content')
        .onClick(() => this.toggleContent())
        .margin(10);

      Text(`Sensor Data (X-axis): ${this.sensorData.toFixed(2)}`)
        .fontSize(16)
        .fontColor(Color.Blue)
        .margin(10);

      If(this.isContentVisible) {
        Column() {
          Text('Document Content')
            .fontSize(20)
            .fontColor(Color.Black)
            .margin(10);
        }
      }

      RefreshContainer() {
        Column() {
          Text('Pull to Refresh')
            .fontSize(16)
            .margin(10);
        }
        .width('100%')
        .height(200)
      }
      .onRefresh(() => {
        this.onRefresh();
      })
      .refreshing(this.isRefreshing)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

import { Column, Row, Text, Progress, Button } from '@ohos.arkui.advanced';
import { Drawer } from '@ohos.arkui.advanced';
import { LongPressGesture } from '@ohos.arkui.advanced';
import { FlexAlign, HorizontalAlign } from '@ohos.arkui.advanced';
import { FontWeight, TextAlign } from '@ohos.arkui.advanced';

class QuizQuestion {
  question: string;
  options: string[];
  correctAnswer: number;

  constructor(question: string, options: string[], correctAnswer: number) {
    this.question = question;
    this.options = options;
    this.correctAnswer = correctAnswer;
  }
}

@Entry
@Component
struct QuizApp {
  @State currentQuestionIndex: number = 0;
  @State selectedOption: number = -1;
  @State showFeedback: boolean = false;
  @State score: number = 0;
  @State showScore: boolean = false;
  @State drawerOpen: boolean = false;

  private questions: Array<QuizQuestion> = [
    new QuizQuestion(
      'What is the capital of France?',
      ['London', 'Berlin', 'Paris', 'Madrid'],
      2
    ),
    new QuizQuestion(
      'Which planet is closest to the Sun?',
      ['Mars', 'Venus', 'Mercury', 'Jupiter'],
      2
    ),
    new QuizQuestion(
      'What is the largest mammal?',
      ['African Elephant', 'Blue Whale', 'Giraffe', 'Hippopotamus'],
      1
    )
  ];

  checkAnswer() {
    if (this.selectedOption === -1) return;

    const correct = this.selectedOption === this.questions[this.currentQuestionIndex].correctAnswer;
    if (correct) {
      this.score++;
    }
    this.showFeedback = true;

    setTimeout(() => {
      this.showFeedback = false;
      this.selectedOption = -1;
      if (this.currentQuestionIndex < this.questions.length - 1) {
        this.currentQuestionIndex++;
      } else {
        this.showScore = true;
      }
    }, 1500);
  }

  build() {
    Column() {
      Drawer({ isOpen: this.drawerOpen, drawerWidth: '50%' }) {
        Column() {
          Button('Home')
            .onClick(() => {
              this.drawerOpen = false;
            });
          Button('Settings')
            .onClick(() => {
              this.drawerOpen = false;
            });
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center)
      }

      Column() {
        if (!this.showScore) {
          Text(`Question ${this.currentQuestionIndex + 1}/${this.questions.length}`)
            .fontSize(18)
            .margin({ bottom: 10 });

          Text(this.questions[this.currentQuestionIndex].question)
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .textAlign(TextAlign.Center)
            .margin({ bottom: 30 })
            .padding({ left: 20, right: 20 });

          ForEach(this.questions[this.currentQuestionIndex].options, (option: string, index: number) => {
            Row() {
              Text(option)
                .fontSize(18)
                .margin({ left: 10 });
            }
            .width('80%')
            .height(50)
            .borderRadius(10)
            .backgroundColor(this.selectedOption === index ? '#DDDDDD' : '#FFFFFF')
            .margin({ bottom: 10 })
            .onClick(() => {
              this.selectedOption = index;
            })
            .gesture(
              LongPressGesture()
                .onAction(() => {
                  this.selectedOption = index;
                })
            );
          });

          if (this.showFeedback) {
            Text(this.selectedOption === this.questions[this.currentQuestionIndex].correctAnswer ? 'Correct!' : 'Incorrect!')
              .fontSize(20)
              .fontColor(this.selectedOption === this.questions[this.currentQuestionIndex].correctAnswer ? 'green' : 'red')
              .margin({ top: 20 });
          }

          Button('Next')
            .onClick(() => {
              this.checkAnswer();
            })
            .margin({ top: 20 });
        } else {
          Text(`Your score: ${this.score}/${this.questions.length}`)
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .textAlign(TextAlign.Center);
        }
      }
      .width('100%')
      .height('100%')
      .justifyContent(FlexAlign.Center)
      .align

