        })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

import preferences from '@ohos.data.preferences';
import { SideBarContainer, SideBarContainerType } from '@ohos.arkui.advanced';

@Entry
@Component
struct RatingApp {
  @State currentRating: number = 0;
  @State ratingsHistory: number[] = [];
  @State showDrawer: boolean = false;

  private pref: preferences.Preferences | null = null;
  private readonly PREF_NAME: string = 'ratingPrefs';
  private readonly RATING_KEY: string = 'currentRating';
  private readonly HISTORY_KEY: string = 'ratingsHistory';

  async aboutToAppear() {
    try {
      this.pref = await preferences.getPreferences(getContext(this), this.PREF_NAME);
      const rating = await this.pref.get(this.RATING_KEY, 0);
      this.currentRating = Number(rating) || 0;
      const history = await this.pref.get(this.HISTORY_KEY, '[]');
      this.ratingsHistory = JSON.parse(history.toString()) || [];
    } catch (err) {
      console.error(`Failed to load preferences: ${err}`);
    }
  }

  async saveRating(rating: number) {
    this.currentRating = rating;
    this.ratingsHistory.push(rating);
    try {
      if (this.pref) {
        await this.pref.put(this.RATING_KEY, rating.toString());
        await this.pref.put(this.HISTORY_KEY, JSON.stringify(this.ratingsHistory));
        await this.pref.flush();
      }
    } catch (err) {
      console.error(`Failed to save rating: ${err}`);
    }
  }

  build() {
    SideBarContainer(SideBarContainerType.Embed) {
      Column() {
        Button('Toggle Menu')
          .onClick(() => {
            this.showDrawer = !this.showDrawer;
          });

        Text('Rate Us').fontSize(24).margin({ bottom: 20 });

        Row() {
          ForEach([1, 2, 3, 4, 5], (index: number) => {
            Image(this.currentRating >= index ? $r('app.media.star_filled') : $r('app.media.star_empty'))
              .width(40)
              .height(40)
              .onClick(() => {
                this.saveRating(index);
              });
          });
        }

        Text(`Current Rating: ${this.currentRating}`).margin({ top: 20 });
        Text(`History: ${this.ratingsHistory.join(', ')}`).margin({ top: 10 });
      }

      SideBar() {
        Column() {
          Text('Home').margin(10).onClick(() => { this.showDrawer = false; });
          Text('Ratings').margin(10).onClick(() => { this.showDrawer = false; });
          Text('Settings').margin(10).onClick(() => { this.showDrawer = false; });
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
      }
      .sideBarWidth(200)
      .showSideBar(this.showDrawer)
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

import { Image, Popup, Button, Column, Row, Text } from '@ohos.arkui.advanced';
import { State } from '@ohos.arkui.decorator';

@Entry
@Component
struct MapApp {
  @State currentTheme: 'light' | 'dark' = 'light';
  @State selectedLocation: string = 'Home';
  @State showSettings: boolean = false;

  private locations: string[] = ['Home', 'Work', 'Park', 'Mall'];

  build() {
