      Row() {
        ForEach(this.locations, (location: string) => {
          Text(location)
            .fontSize(16)
            .margin({ right: 10 })
            .fontColor(this.selectedLocation === location ? '#007DFF' : '#000000')
            .onClick(() => {
              this.selectedLocation = location;
            });
        });
