}

import appearance from '@ohos.system.appearance';
import { Gesture, RotateGestureEvent } from '@ohos.arkui.advanced';
import { Slider, SliderStyle, Tabs, TabContent, BarPosition, FlexAlign, Alignment } from '@ohos.arkui.advanced';

@Entry
@Component
struct DarkModeApp {
  @State currentMode: string = 'light'
  @State selectedTab: number = 0
  @State sliderValue: number = 50
  @State rotationAngle: number = 0

  aboutToAppear() {
    this.currentMode = appearance.getColorMode() === 'dark' ? 'dark' : 'light';

    appearance.on('colorModeChange', (newMode: string) => {
      this.currentMode = newMode === 'dark' ? 'dark' : 'light';
    });
  }

  build() {
    Column({ space: 20 }) {
      Text(`Current Mode: ${this.currentMode}`)
        .fontSize(18)
        .fontColor(this.currentMode === 'dark' ? '#FFFFFF' : '#000000')

      Tabs({ barPosition: BarPosition.Start, index: this.selectedTab }) {
        TabContent() {
          Text('Option 1 Content')
            .fontSize(16)
            .fontColor(this.currentMode === 'dark' ? '#FFFFFF' : '#000000')
        }.tabBar('Option 1')

        TabContent() {
          Text('Option 2 Content')
            .fontSize(16)
            .fontColor(this.currentMode === 'dark' ? '#FFFFFF' : '#000000')
        }.tabBar('Option 2')

        TabContent() {
          Text('Option 3 Content')
            .fontSize(16)
            .fontColor(this.currentMode === 'dark' ? '#FFFFFF' : '#000000')
        }.tabBar('Option 3')
      }
      .onChange((index: number) => {
        this.selectedTab = index
      })
      .width('100%')

      Text(`Slider Value: ${this.sliderValue}`)
        .fontSize(16)
        .fontColor(this.currentMode === 'dark' ? '#FFFFFF' : '#000000')

      Slider({
        value: this.sliderValue,
        min: 0,
        max: 100,
        step: 1,
        style: SliderStyle.OutSet
      })
        .onChange((value: number) => {
          this.sliderValue = value
        })
        .width('80%')

      Stack() {
        Text('Rotate Me')
          .fontSize(16)
          .fontColor(this.currentMode === 'dark' ? '#FFFFFF' : '#000000')
          .gesture(
            Gesture()
              .onRotate((event: RotateGestureEvent) => {
                this.rotationAngle = event.angle
              })
          )

        Text(`Rotation Angle: ${this.rotationAngle.toFixed(1)}\u00b0`)
          .fontSize(16)
          .fontColor(this.currentMode === 'dark' ? '#FFFFFF' : '#000000')
          .margin({ top: 50 })
      }
      .width('100%')
      .height(200)
      .align(Alignment.Center)
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.currentMode === 'dark' ? '#333333' : '#FFFFFF')
    .padding(20)
    .justifyContent(FlexAlign.Center)
  }
}

