import { Column, Row, Text } from '@ohos.arkui.advanced';
import { Toggle, ToggleType } from '@ohos.arkui.advanced';
import { Slider } from '@ohos.arkui.advanced';

@Entry
@Component
struct SettingsPage {
  @State darkMode: boolean = false;
  @State brightnessLevel: number = 50;

  build() {
    Column({ space: 20 }) {
      Row() {
        Text('Dark Mode')
          .fontSize(18)
          .margin({ right: 10 });
        Toggle({ type: ToggleType.Switch, isOn: this.darkMode })
          .onChange((isOn: boolean) => {
            this.darkMode = isOn;
          })
          .accessibilityLabel('Dark Mode Toggle');
      }

      Row() {
        Text('Brightness')
          .fontSize(18)
          .margin({ right: 10 });
        Slider({
          value: this.brightnessLevel,
          min: 0,
          max: 100,
          step: 1
        })
          .onChange((value: number) => {
            this.brightnessLevel = value;
          })
          .accessibilityLabel('Brightness Slider');
      }
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

import { Swiper, SwiperController } from '@ohos.arkui.advanced';
import { Flex, Column, Row, Stack, Button, Text, Image, ImageFit } from '@ohos.arkui.component';

enum FontWeight {
  Normal = 400,
  Bold = 700
}

interface Product {
  id: number;
  name: string;
  image: Resource;
  description: string;
  price: string;
}

@Entry
@Component
struct ECommerceDrawingTool {
  private swiperController: SwiperController = new SwiperController();
  @State selectedProduct: Product | null = null;

  private products: Product[] = [
    {
      id: 1,
      name: 'Product 1',
      image: $r('app.media.ic_default'),
      description: 'Description for Product 1',
      price: '$19.99'
    },
    {
      id: 2,
      name: 'Product 2',
      image: $r('app.media.ic_default'),
      description: 'Description for Product 2',
      price: '$29.99'
    },
    {
      id: 3,
      name: 'Product 3',
      image: $r('app.media.ic_default'),
      description: 'Description for Product 3',
      price: '$39.99'
    }
  ];

  build() {
    Column() {
      if (this.selectedProduct) {
        Column() {
          this.buildProductDetails()
        }
      } else {
        Column() {
          this.buildProductCarousel()
        }
      }
    }
    .width('100%')
    .height('100%')
    .padding(16)
  }

  @Builder
  private buildProductCarousel() {
    Swiper(this.swiperController) {
      ForEach(this.products, (product: Product) => {
        Stack() {
          Column() {
            Image(product.image)
              .width('100%')
              .height(200)
              .objectFit(ImageFit.Cover)
              .borderRadius(8)
              .alt('Product image: ' + product.name)
            Text(product.name)
              .fontSize(18)
              .fontWeight(FontWeight.Bold)
              .margin({ top: 8 })
            Text(product.description)
              .fontSize(14)
              .margin({ top: 4 })
            Text(product.price)
              .fontSize(16)
              .fontColor('#FF5722')
              .margin({ top: 8 })
            Button('View Details')
              .onClick(() => {
                this.selectedProduct = product;
              })
              .margin({ top: 12 })
              .ariaLabel('View details for ' + product.name)
          }
          .padding(16)
          .backgroundColor('#FFFFFF')
          .borderRadius(12)
          .margin({ bottom: 16 })
        }
      })
    }
    .width('100%')
    .height(400)
    .autoPlay(true)
    .interval(3000)
    .indicator(true)
    .loop(true)
  }

  @Builder
  private buildProductDetails() {
    Column() {
      Image(this.selectedProduct!.image)
        .width('100%')
        .height(300)
        .objectFit(ImageFit.Cover)
        .borderRadius(12)
        .alt('Product image: ' + this.selectedProduct!.name)
      Text(this.selectedProduct!.name)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 16 })
      Text(this.selectedProduct!.description)
        .fontSize(16)
        .margin({ top: 8 })
      Text(this.selectedProduct!.price)
        .fontSize(20)
        .fontColor('#FF5722')
        .margin({ top: 16 })
      Button('Back to Products')
        .onClick(() => {
          this.selectedProduct = null;
        })
        .margin({ top: 24 })
        .ariaLabel('Back to products list')
    }
    .padding(16)
  }
}

import { Card, Button, Image, Column, Row, Text, Badge } from '@ohos.arkui.advanced';
import { ImageFit, BadgePosition, Color, BadgeStyle } from '@ohos.arkui.advanced';

@Entry
