import promptAction from '@ohos.promptAction';
import { Tabs, TabContent, List, ListItem, Row, Column, Image, Text } from '@ohos.arkui.advanced';
import { Refresh } from '@ohos.arkui.advanced';

interface Food {
  id: number;
  title: string;
  image: Resource;
  description: string;
}

interface ActionSheetResult {
  index: number;
}

@Entry
@Component
struct FoodDeliveryApp {
  private foods: Food[] = [
    {
      id: 1,
      title: 'Pizza',
      image: $r('app.media.icon'),
      description: 'A delicious Italian dish with a thin crust, tomato sauce, and cheese.'
    },
    {
      id: 2,
      title: 'Sushi',
      image: $r('app.media.icon'),
      description: 'A traditional Japanese dish consisting of vinegared rice and seafood.'
    },
    {
      id: 3,
      title: 'Burger',
      image: $r('app.media.icon'),
      description: 'A classic American dish with a beef patty, lettuce, and cheese in a bun.'
    }
  ];

  @State selectedFood: Food | null = null;
  @State refreshing: boolean = false;
  @State currentTabIndex: number = 0;
  @State promoText: string = 'Special Offer: 50% off';

  private refreshData() {
    this.refreshing = true;
    setTimeout(() => {
      this.refreshing = false;
    }, 1000);
  }

  private showActionSheet(food: Food) {
    promptAction.showActionMenu({
      title: food.title,
      buttons: [
        {
          text: 'Add to Cart',
          color: '#007DFF'
        },
        {
          text: 'Cancel',
          color: '#999999'
        }
      ]
    }).then((result: ActionSheetResult) => {
      if (result.index === 0) {
        console.log(`Added ${food.title} to cart`);
      } else {
        console.log('Action canceled');
      }
    });
  }

  build() {
    Column() {
      Text(this.promoText)
        .height(40)
        .width('100%')
        .backgroundColor('#FFD700')
        .fontSize(16)
        .margin(5)
        .translate({ x: 0, y: 0 })
        .animation({
          duration: 2000,
          iterations: -1,
          curve: 'ease',
          onFinish: () => {
            this.promoText = this.promoText;
          }
        });

      Tabs({ index: this.currentTabIndex }) {
        TabContent() {
          Refresh({ refreshing: this.refreshing }) {
            List({ space: 10 }) {
              ForEach(this.foods, (food: Food) => {
                ListItem() {
                  Row() {
                    Image(food.image)
                      .width(80)
                      .height(80)
                      .borderRadius(8);
                    Column() {
                      Text(food.title)
                        .fontSize(18)
                        .fontWeight('bold');
                      Text(food.description)
                        .fontSize(14)
                        .lineHeight(20);
                    }
                    .margin({ left: 10 })
                  }
                  .onClick(() => {
                    this.showActionSheet(food);
                  });
                }
              });
            }
          }
          .onRefreshing(() => {
            this.refreshData();
          })
        }
        .tabBar('Home');

        TabContent() {
          Text('Orders Tab')
            .fontSize(20)
            .textAlign(TextAlign.Center);
        }
        .tabBar('Orders');

        TabContent() {
          Text('Profile Tab')
            .fontSize(20)
            .textAlign(TextAlign.Center);
        }
        .tabBar('Profile');
      }
      .width('100%')
      .height('100%');
    }
    .width('100%')
    .height('100%');
  }
}

import { Column, Row, Text, Image, Canvas, Button } from '@ohos.arkui.d.ts';
import window from '@ohos.window';
import { BusinessError } from '@ohos.base';
import { FontWeight, FlexAlign } from '@ohos.arkui.d.ts';
import { KeyEvent, KeyCode } from '@ohos.multimodalInput';

@Entry
@Component
struct EmailClient {
  private context = getContext(this);
  @State orientation: string = 'portrait';
  @State windowWidth: number = 0;
  @State windowHeight: number = 0;

  onOrientationChange() {
    let win = window.getLastWindow(this.context);
    win.then((window) => {
      window.on('windowSizeChange', () => {
        let windowRect = window.getWindowProperties().windowRect;
        this.windowWidth = windowRect.width;
        this.windowHeight = windowRect.height;
        this.orientation = this.windowWidth > this.windowHeight ? 'landscape' : 'portrait';
      });
    }).catch((err: BusinessError) => {
      console.error('Failed to get window:', err);
    });
  }

  aboutToAppear() {
    this.onOrientationChange();
  }

  build() {
    Column() {
      Row() {
        Text('Email Client')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .accessibilityDescription('Email client application header')
          .accessibilityGroup(true);
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .padding(20);

      Column() {
        Image($r('app.media.icon'))
          .width('100%')
          .height('40%')
          .accessibilityDescription('Static map for navigation')
          .accessibilityGroup(true);

        Canvas()
          .width('100%')
          .height('10%')
          .accessibilityDescription('Canvas for map annotations')
          .accessibilityGroup(true);
      }
      .width('100%')
      .padding(10);

      Column() {
        Text('Inbox')
          .fontSize(18)
          .fontWeight(FontWeight.Medium)
          .accessibilityDescription('Inbox section')
          .accessibilityGroup(true);

        Row() {
          Text('New Message')
            .fontSize(16)
            .accessibilityDescription('Email subject: New Message')
            .accessibilityGroup(true);
        }
        .width('100%')
        .padding(10)
        .backgroundColor(0xF5F5F5)
        .borderRadius(5)
        .margin({ bottom: 10 });
      }
      .width('100%')
      .padding(10);

      Button('Compose Email')
        .onClick(() => {
          console.info('Compose button clicked');
        })
        .width('50%')
        .height(50)
        .accessibilityDescription('Button to compose a new email')
        .accessibilityGroup(true)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .onKeyEvent((event: KeyEvent) => {
      if (event.code === KeyCode.KEY_TAB) {
        console.info('Tab key pressed for focus management');
      }
    });
  }
}

@Entry
@Component
struct TravelStatisticsApp {
  @State private progressValue: number = 50;
  @State private tapCount: number = 0;
  @State private tapState: string = "No Tap";

  build() {
    Column({ space: 20 }) {
      Text("Travel Statistics")
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Progress({
        value: this.progressValue,
        total: 100,
        type: ProgressType.Linear
      })
      .size({ width: "80%", height: 20 })
      .color(Color.Blue)
      .margin({ bottom: 20 });

      Text(`Progress: ${this.progressValue}%`)
        .fontSize(16)
        .fontColor(Color.Black);

      Row({ space: 10 }) {
        Button("Increase")
          .onClick(() => {
            if (this.progressValue < 100) {
              this.progressValue += 10;
            }
          })
          .width(100)
          .height(40);

        Button("Decrease")
          .onClick(() => {
            if (this.progressValue > 0) {
              this.progressValue -= 10;
            }
          })
          .width(100)
          .height(40);
      }
      .margin({ bottom: 20 });

      Text(`Tap Count: ${this.tapCount}`)
        .fontSize(16)
        .fontColor(Color.Black);

      Text(`Tap State: ${this.tapState}`)
        .fontSize(16)
        .fontColor(Color.Black);

      Button("Tap Me")
        .onClick(() => {
          this.tapCount += 1;
          this.tapState = "Tapped";
        })
        .onTouch((event: TouchEvent) => {
          if (event.type === TouchType.Down) {
            this.tapState = "Tap Down";
          } else if (event.type === TouchType.Up) {
            this.tapState = "Tap Up";
          }
        })
        .width(150)
        .height(50)
        .backgroundColor(Color.Blue)
        .fontColor(Color.White);
    }
    .width("100%")
    .height("100%")
    .padding(20)
    .backgroundColor(Color.White)
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

import { Column, Grid, GridItem, Image, Slider, Button } from '@ohos.arkui.component';
import { ImageFit, LongPressGesture, Color } from '@ohos.arkui.drawing';
import { Drawer } from '@ohos.arkui.container';

@Entry
@Component
struct FileManagerApp {
