    $r('app.media.image1'),
    $r('app.media.image2'),
    $r('app.media.image3'),
    $r('app.media.image4'),
    $r('app.media.image5'),
    $r('app.media.image6'),
    $r('app.media.image7'),
    $r('app.media.image8')
  ];
  @State private selectedImages: boolean[] = Array(this.images.length).fill(false);
  @State private isDrawerOpen: boolean = false;
  @State private imageBrightness: number = 1.0;
  @State private imageContrast: number = 1.0;
  @State private saturation: number = 1.0;

  build() {
