            Slider({
              value: this.imageContrast,
              min: 0.1,
              max: 2.0,
              step: 0.1
            })
              .onChange((value: number) => {
                this.imageContrast = value;
              })
              .margin(10);

            Slider({
              value: this.saturation,
              min: 0.1,
              max: 2.0,
              step: 0.1
            })
              .onChange((value: number) => {
                this.saturation = value;
              })
              .margin(10);

            Button('Apply')
              .onClick(() => {
                this.isDrawerOpen = false;
              })
              .margin(10);
          }
          .width('100%')
          .padding(10)
        )
    );
  }
}

import { Column, Row, Text, Button, Slider, Image, Tabs, TabContent } from '@ohos.arkui.advanced';
import { FlexAlign, FontWeight } from '@ohos.arkui.common';
import { CanvasRenderingContext2D } from '@ohos.graphics';

interface Song {
  title: string;
  artist: string;
}

@Entry
@Component
struct MusicPlayer {
  @State isPlaying: boolean = false;
  @State currentSong: string = 'Shape of You';
  @State currentArtist: string = 'Ed Sheeran';
  @State progress: number = 0;
  @State mode: string = 'online';
  @State canvasRef: CanvasRenderingContext2D | null = null;

  private songs: Array<Song> = [
    { title: 'Shape of You', artist: 'Ed Sheeran' },
    { title: 'Blinding Lights', artist: 'The Weeknd' }
  ];

  private currentSongIndex: number = 0;

  build() {
    Column() {
      Image($r('app.media.icon'))
        .width(300)
        .height(300)
        .borderRadius(10)
        .margin({ top: 20 });

      Text(this.currentSong)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20 });
      Text(this.currentArtist)
        .fontSize(18)
        .margin({ top: 5 });

      Slider({
        value: this.progress,
        min: 0,
        max: 100,
        step: 1
      })
        .width('80%')
        .margin({ top: 20 })
        .onChange((value: number) => {
          this.progress = value;
        });

      Row({ space: 20 }) {
        Button('Previous')
          .onClick(() => {
            this.currentSongIndex = (this.currentSongIndex - 1 + this.songs.length) % this.songs.length;
            this.updateSong();
          });
        Button(this.isPlaying ? 'Pause' : 'Play')
          .onClick(() => {
            this.isPlaying = !this.isPlaying;
            if (this.canvasRef) {
              this.drawVisualization(this.canvasRef);
            }
          });
        Button('Next')
          .onClick(() => {
            this.currentSongIndex = (this.currentSongIndex + 1) % this.songs.length;
            this.updateSong();
          });
      }
      .margin({ top: 20 });

      Tabs({ barPosition: 'bottom', index: 0 }) {
        TabContent() {
          Text('Online Mode')
            .fontSize(16);
        }.tabBar('Online');
        TabContent() {
          Text('Offline Mode')
            .fontSize(16);
        }.tabBar('Offline');
      }
      .onChange((index: number) => {
        this.mode = index === 0 ? 'online' : 'offline';
      });

      Canvas()
        .width('80%')
        .height(50)
        .margin({ top: 20 })
        .onReady((event: { getContext: (type: string) => CanvasRenderingContext2D }) => {
          this.canvasRef = event.getContext('2d');
          if (this.canvasRef) {
            this.drawVisualization(this.canvasRef);
          }
        });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor('#121212');
  }

  private updateSong() {
    this.currentSong = this.songs[this.currentSongIndex].title;
    this.currentArtist = this.songs[this.currentSongIndex].artist;
    this.progress = 0;
    if (this.canvasRef) {
      this.drawVisualization(this.canvasRef);
    }
  }

  private drawVisualization(canvas: CanvasRenderingContext2D | null): void {
    if (!canvas) return;
    if (this.isPlaying) {
      canvas.clearRect(0, 0, canvas.width, canvas.height);
      for (let i = 0; i < 10; i++) {
        const height = Math.random() * 50;
        canvas.fillStyle = '#4CAF50';
        canvas.fillRect(i * 15, 50 - height, 10, height);
      }
    } else {
      canvas.clearRect(0, 0, canvas.width, canvas.height);
    }
  }
}

