@Entry
@Component
struct ComicReader {
  @State currentPage: number = 0
  @State totalPages: number = 10
  @State scanHistory: string[] = []

  build() {
    Column() {
      Image($r('app.media.ic_public_filled'))
        .height('70%')
        .aspectRatio(1)
        .objectFit(ImageFit.Contain)
        .gesture(
          PanGesture()
            .onActionStart(() => {})
            .onActionUpdate((event: GestureEvent) => {
              if (event.offsetX > 50 && this.currentPage > 0) {
                this.currentPage--
              } else if (event.offsetX < -50 && this.currentPage < this.totalPages - 1) {
                this.currentPage++
              }
            })
        )

      Slider({
        value: this.currentPage,
        min: 0,
        max: this.totalPages - 1,
        step: 1,
        style: SliderStyle.OutSet
      })
      .onChange((value: number) => {
        this.currentPage = value
      })
      .width('90%')
      .margin(10)

      Button('Scan Comic')
        .onClick(() => {
          this.scanHistory.push('Comic Page ' + (this.currentPage + 1))
        })
        .width('90%')
        .margin(10)

      List() {
        ForEach(this.scanHistory, (item: string) => {
          ListItem() {
            Text(item)
              .fontSize(16)
          }
          .margin({ top: 10 })
        })
      }
      .height('20%')
      .width('100%')
      .divider({ strokeWidth: 1, color: '#f5f5f5' })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }
}

