import { ProgressStyle, FontWeight, FlexAlign } from '@ohos.arkui.advanced';
import { animateTo, Easing } from '@ohos.arkui.advanced.animate';

@Entry
@Component
struct PerformanceDashboard {
  @State cpuUsage: number = Math.floor(Math.random() * 100);
  @State memoryUsage: number = Math.floor(Math.random() * 100);
  @State rating: number = 0;
  @State hoveredStar: number = -1;
  private timerId: number = 0;

  updateMetrics(): void {
    this.timerId = setInterval(() => {
      this.cpuUsage = Math.floor(Math.random() * 100);
      this.memoryUsage = Math.floor(Math.random() * 100);
    }, 2000);
  }

  setRating(star: number): void {
    animateTo({
      duration: 300,
      curve: Easing.Out
    }, () => {
      this.rating = star;
    });
  }

  build() {
    Column({ space: 20 }) {
      Text('Performance Monitoring Dashboard')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Stack() {
        Progress({
          value: this.cpuUsage,
          total: 100,
          style: ProgressStyle.Linear
        })
          .width('90%')
          .height(20)
          .backgroundColor('#e0e0e0');

        Text(`${this.cpuUsage}%`)
          .fontSize(14)
          .fontColor('#333');
      }
      .margin({ bottom: 10 });

      Stack() {
        Progress({
          value: this.memoryUsage,
          total: 100,
          style: ProgressStyle.Linear
        })
          .width('90%')
          .height(20)
          .backgroundColor('#e0e0e0');

        Text(`${this.memoryUsage}%`)
          .fontSize(14)
          .fontColor('#333');
      }
      .margin({ bottom: 20 });

      Row({ space: 10 }) {
        ForEach([1, 2, 3, 4, 5] as Array<number>, (star: number) => {
          Button('\u2605')
            .fontSize(24)
            .fontColor(this.rating >= star || this.hoveredStar >= star ? '#FFD700' : '#ccc')
            .onClick(() => this.setRating(star))
            .onHover((isHovered: boolean) => {
              this.hoveredStar = isHovered ? star : -1;
            });
        });
      }
      .justifyContent(FlexAlign.Center)
      .margin({ bottom: 20 });

      Button('Refresh Metrics')
        .onClick(() => {
          this.cpuUsage = Math.floor(Math.random() * 100);
          this.memoryUsage = Math.floor(Math.random() * 100);
        });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .onAppear(() => this.updateMetrics())
    .onDisappear(() => clearInterval(this.timerId));
  }
}

@Entry
@Component
struct ComicReader {
  @State currentPage: number = 0;
  @State isAnimating: boolean = true;
  @State isMenuVisible: boolean = false;

  private comicPages: Resource[] = [
    $r('app.media.ic_public_picture'),
    $r('app.media.ic_public_picture'),
    $r('app.media.ic_public_picture')
  ];

  private toggleAnimation(): void {
    this.isAnimating = !this.isAnimating;
  }

  private navigate(direction: number): void {
    const newPage = this.currentPage + direction;
    if (newPage >= 0 && newPage < this.comicPages.length) {
      if (this.isAnimating) {
        animateTo({
          duration: 300,
          curve: Curve.EaseInOut
        }, () => {
          this.currentPage = newPage;
        });
      } else {
        this.currentPage = newPage;
      }
    }
  }

  private toggleMenu(): void {
    this.isMenuVisible = !this.isMenuVisible;
  }

  build() {
    Stack() {
      Column() {
        Row() {
          Text('Comic Reader')
            .fontSize(24)
            .fontWeight(500)
            .margin({ left: 16 });
          Button('Menu')
            .margin({ right: 16 })
            .onClick(() => this.toggleMenu());
        }
        .width('100%')
        .justifyContent(FlexAlign.SpaceBetween)
        .alignItems(VerticalAlign.Center)
        .height(60)
        .backgroundColor('#f0f0f0');

        Stack() {
          Image(this.comicPages[this.currentPage])
            .width('100%')
            .height('70%')
            .objectFit(ImageFit.Cover);
        }
        .width('100%')
        .height('70%');

        Row() {
          Button('Previous')
            .onClick(() => this.navigate(-1))
            .enabled(this.currentPage > 0);
          Button('Next')
            .onClick(() => this.navigate(1))
            .enabled(this.currentPage < this.comicPages.length - 1);
        }
        .width('100%')
        .justifyContent(FlexAlign.SpaceAround)
        .margin({ top: 16 });

        Row() {
          Text('Animation:');
          Button(this.isAnimating ? 'ON' : 'OFF')
            .onClick(() => this.toggleAnimation());
        }
        .width('100%')
        .justifyContent(FlexAlign.Center)
        .margin({ top: 16 });

        if (this.isMenuVisible) {
          Column() {
            ForEach(this.comicPages, (page: Resource, index: number) => {
              Button(`Page ${index + 1}`)
                .onClick(() => {
                  this.currentPage = index;
                  this.isMenuVisible = false;
                })
                .margin({ bottom: 8 });
            });
          }
          .width('80%')
          .padding(16)
          .backgroundColor('#ffffff')
          .borderRadius(8)
          .margin({ top: 16 });
        }
      }
      .width('100%')
      .height('100%');
    }
  }
}

import sensor from '@ohos.sensor';
import abilityAccessCtrl from '@ohos.abilityAccessCtrl';
import { BusinessError } from '@ohos.base';
import { Tabs, TabContent, BarPosition } from '@ohos.arkui.advanced';
import { Toggle, CheckboxToggleType } from '@ohos.arkui.advanced';
import { DatePicker } from '@ohos.arkui.advanced';

@Entry
@Component
struct SensorApp {
  @State private accelerometerData: string = 'Accelerometer Data:\nX: 0.00\nY: 0.00\nZ: 0.00';
  @State private toggleState: boolean = false;
  @State private selectedDate: Date = new Date();

  aboutToAppear() {
    let permissions: Array<string> = ['ohos.permission.ACCELEROMETER'];
    let atManager = abilityAccessCtrl.createAtManager();
    try {
      atManager.requestPermissionsFromUser(getContext(this), permissions).then((data) => {
        this.registerSensor();
      }).catch((err: BusinessError) => {
        console.error('Failed to request permissions:', err);
      });
    } catch (error) {
      console.error('Failed to request permissions:', error);
    }
  }

  aboutToDisappear() {
    this.unregisterSensor();
  }

  private registerSensor(): void {
    try {
      if (globalThis.ability) {
        sensor.on(sensor.SensorId.ACCELEROMETER, (data: sensor.AccelerometerResponse) => {
          this.accelerometerData = `Accelerometer Data:\nX: ${data.x.toFixed(2)}\nY: ${data.y.toFixed(2)}\nZ: ${data.z.toFixed(2)}`;
        }, { interval: 200000000 });
      }
    } catch (error) {
      console.error('Failed to register sensor:', (error as BusinessError).message);
    }
  }

  private unregisterSensor(): void {
    if (globalThis.ability) {
      sensor.off(sensor.SensorId.ACCELEROMETER);
    }
  }

  private handleToggleChange(newState: boolean): void {
    this.toggleState = newState;
  }

  private handleDateChange(newDate: Date): void {
    this.selectedDate = newDate;
  }

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.End }) {
        TabContent() {
          Column() {
            Text(this.accelerometerData)
              .fontSize(18)
              .textAlign(TextAlign.Start)
              .margin({ top: 20, bottom: 20 })
          }
          .width('100%')
          .height('100%')
          .padding(20)
        }.tabBar('Sensor')

        TabContent() {
          Column() {
            Toggle({ type: CheckboxToggleType, isOn: this.toggleState })
              .onChange((isOn: boolean) => this.handleToggleChange(isOn))
              .width('50%')
              .height(40)
              .margin({ top: 20, bottom: 20 })
          }
          .width('100%')
          .height('100%')
          .padding(20)
        }.tabBar('Toggle')

        TabContent() {
          Column() {
            DatePicker({ date: this.selectedDate })
              .onChange((date: Date) => this.handleDateChange(date))
              .width('80%')
              .height(50)
              .margin({ top: 20, bottom: 20 })
          }
          .width('100%')
          .height('100%')
          .padding(20)
        }.tabBar('Date')
      }
      .width('100%')
      .height('100%')
    }
    .width('100%')
    .height('100%')
  }
}

