@Entry
@Component
struct CombinedApp {
  @State timerRunning: boolean = false
  @State elapsedSeconds: number = 0
  @State travelPlans: Array<string> = []
  @State showAddPlanModal: boolean = false
  @State newPlanText: string = ''
  @State chartData: Array<number> = [10, 20, 30, 40, 50]

  private timerInterval: number = 0

  aboutToDisappear() {
    if (this.timerInterval) {
      clearInterval(this.timerInterval)
    }
  }

  toggleTimer() {
    if (this.timerRunning) {
      clearInterval(this.timerInterval)
    } else {
      this.timerInterval = setInterval(() => {
        this.elapsedSeconds += 1
      }, 1000)
    }
    this.timerRunning = !this.timerRunning
  }

  resetTimer() {
    this.elapsedSeconds = 0
    if (this.timerRunning) {
      clearInterval(this.timerInterval)
      this.timerRunning = false
    }
  }

  saveTravelPlans() {
    if (this.newPlanText.trim() === '') return
    this.travelPlans.push(this.newPlanText)
    this.newPlanText = ''
    this.showAddPlanModal = false
  }

  build() {
    Stack() {
      Column({ space: 20 }) {
        // Timer Section
        Column({ space: 10 }) {
          Text(`Elapsed: ${this.elapsedSeconds}s`)
            .fontSize(20)
          Row({ space: 10 }) {
            Button(this.timerRunning ? 'Stop' : 'Start')
              .onClick(() => this.toggleTimer())
            Button('Reset')
              .onClick(() => this.resetTimer())
          }
        }

        // Travel Planner Section
        Column({ space: 10 }) {
          Button('Add Travel Plan')
            .onClick(() => {
              this.showAddPlanModal = true
            })
          ForEach(this.travelPlans, (plan: string) => {
            Text(plan)
              .fontSize(16)
          })
        }

        // Chart Section
        Column({ space: 10 }) {
          Text('Travel Data Visualization')
            .fontSize(20)
          Row({ space: 5 }) {
            ForEach(this.chartData, (value: number) => {
              Column() {
                Text(value.toString())
                  .fontSize(12)
                Divider()
                  .height(value * 2)
                  .width(20)
                  .backgroundColor('#007AFF')
              }
            })
          }
        }
      }
      .width('100%')
      .height('100%')
      .padding(20)

      if (this.showAddPlanModal) {
        Column() {
          TextInput({ placeholder: 'Enter plan details' })
            .onChange((value: string) => {
              this.newPlanText = value
            })
          Button('Save')
            .onClick(() => this.saveTravelPlans())
        }
        .width('80%')
        .height(200)
        .backgroundColor('#FFFFFF')
        .borderRadius(10)
        .shadow({ radius: 10, color: '#000000', offsetX: 0, offsetY: 0 })
      }
    }
    .width('100%')
    .height('100%')
  }
}

import { Refresh } from '@ohos.pullToRefresh';
import { ColorPicker } from '@ohos.picker';
import { Color } from '@ohos.graphics.color';
import { HorizontalAlign, TextAlign } from '@ohos.arkui';

@Entry
@Component
struct ColorApp {
  @State colors: string[] = ['#FF5733', '#33FF57', '#3357FF', '#F3FF33', '#FF33F3'];
  @State refreshing: boolean = false;

  private generateRandomColor(): string {
    const letters = '0123456789ABCDEF';
    let color = '#';
    for (let i = 0; i < 6; i++) {
      color += letters.charAt(Math.floor(Math.random() * 16));
    }
    return color;
  }

  private onRefresh(): void {
    this.refreshing = true;
    setTimeout(() => {
      this.colors = [...this.colors, this.generateRandomColor()];
      this.refreshing = false;
    }, 1500);
  }

  private onColorSelected(color: string): void {
    this.colors = [color, ...this.colors];
  }

  build() {
    Column() {
      Column() {
        Text('Color Picker')
          .fontSize(18)
          .margin({ bottom: 10 });
        ColorPicker()
          .width('80%')
          .height(200)
          .margin({ bottom: 20 })
          .onChange((color: string) => this.onColorSelected(color));
      }
      .width('100%')
      .alignItems(HorizontalAlign.Center)

      Refresh({ refreshing: this.refreshing, onRefresh: () => this.onRefresh() }) {
        Scroll() {
          Column() {
            ForEach(this.colors, (color: string) => {
              Text(color)
                .fontSize(18)
                .padding(15)
                .borderRadius(8)
                .margin({ bottom: 10 })
                .backgroundColor(color)
                .width('100%')
                .textAlign(TextAlign.Center);
            })
          }
          .width('100%')
        }
        .height('60%')
        .width('100%')
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
  }
}

