@Entry
@Component
struct FormValidationSystem {
  @State username: string = ''
  @State email: string = ''
  @State password: string = ''
  @State usernameError: string = ''
  @State emailError: string = ''
  @State passwordError: string = ''
  @State isUsernameValid: boolean = true
  @State isEmailValid: boolean = true
  @State isPasswordValid: boolean = true

  validateUsername(username: string): string | null {
    return username.trim() ? null : 'Username is required'
  }

  validateEmail(email: string): string | null {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return emailRegex.test(email) ? null : 'Please enter a valid email'
  }

  validatePassword(password: string): string | null {
    return password.length >= 6 ? null : 'Password must be at least 6 characters'
  }

  handleSubmit() {
    const usernameValidation = this.validateUsername(this.username)
    const emailValidation = this.validateEmail(this.email)
    const passwordValidation = this.validatePassword(this.password)

    this.usernameError = usernameValidation || ''
    this.emailError = emailValidation || ''
    this.passwordError = passwordValidation || ''

    this.isUsernameValid = !usernameValidation
    this.isEmailValid = !emailValidation
    this.isPasswordValid = !passwordValidation

    if (this.isUsernameValid && this.isEmailValid && this.isPasswordValid) {
      console.info('Form submitted successfully')
    }
  }

  build() {
    Column() {
      Row() {
        Text('Welcome to the Form Validation System')
          .fontSize(16)
          .fontColor('#000000')
          .margin({ left: 20 })
      }
      .width('100%')
      .height(40)
      .backgroundColor('#f0f0f0')
      .justifyContent(FlexAlign.Start)

      Row() {
        Text('Home').onClick(() => console.info('Navigated to Home'))
        Text(' > ').margin({ left: 5, right: 5 })
        Text('Forms').onClick(() => console.info('Navigated to Forms'))
        Text(' > ').margin({ left: 5, right: 5 })
        Text('Validation').onClick(() => console.info('Navigated to Validation'))
      }
      .margin({ top: 10, bottom: 20 })
      .width('100%')
      .justifyContent(FlexAlign.Center)

      Grid() {
        GridItem() {
          Column() {
            Text('Username')
              .fontSize(16)
              .margin({ bottom: 5 })
            TextInput({ placeholder: 'Enter username' })
              .onChange((value: string) => {
                this.username = value
                const error = this.validateUsername(value)
                this.usernameError = error || ''
                this.isUsernameValid = !error
              })
              .width('100%')
              .height(40)
              .border({
                width: 1,
                color: this.isUsernameValid ? '#ddd' : '#ff0000'
              })
            if (this.usernameError) {
              Text(this.usernameError)
                .fontSize(12)
                .fontColor('#ff0000')
                .margin({ top: 5 })
            }
          }
          .width('100%')
          .margin({ bottom: 15 })
        }

        GridItem() {
          Column() {
            Text('Email')
              .fontSize(16)
              .margin({ bottom: 5 })
            TextInput({ placeholder: 'Enter email' })
              .onChange((value: string) => {
                this.email = value
                const error = this.validateEmail(value)
                this.emailError = error || ''
                this.isEmailValid = !error
              })
              .width('100%')
              .height(40)
              .border({
                width: 1,
                color: this.isEmailValid ? '#ddd' : '#ff0000'
              })
            if (this.emailError) {
              Text(this.emailError)
                .fontSize(12)
                .fontColor('#ff0000')
                .margin({ top: 5 })
            }
          }
          .width('100%')
          .margin({ bottom: 15 })
        }

        GridItem() {
          Column() {
            Text('Password')
              .fontSize(16)
              .margin({ bottom: 5 })
            TextInput({ placeholder: 'Enter password' })
              .onChange((value: string) => {
                this.password = value
                const error = this.validatePassword(value)
                this.passwordError = error || ''
                this.isPasswordValid = !error
              })
              .width('100%')
              .height(40)

@Entry
@Component
struct ImageCropperApp {
  @State private cropX: number = 0
  @State private cropWidth: number = 100
  private images: Resource[] = [
    $r('app.media.icon'),
    $r('app.media.example'),
    $r('app.media.sample')
  ]

  @Builder
  private ImageWithCrop(image: Resource) {
    Column() {
      Stack() {
        Image(image)
          .width('100%')
          .height(200)
          .objectFit(ImageFit.Cover)
          .clip(true)
          .borderRadius(10)
          .overlay(() => {
            Row()
              .width(this.cropWidth + '%')
              .height('100%')
              .backgroundColor(Color.Black)
              .opacity(0.3)
              .position({ x: this.cropX + '%', y: 0 })
          })
      }
      .gesture(
        PanGesture()
          .onActionStart(() => {})
          .onActionUpdate((event: GestureEvent) => {
            this.cropX = Math.max(0, Math.min(100 - this.cropWidth, this.cropX + event.offsetX / 3))
          })
          .onActionEnd(() => {
            animateTo({ duration: 300 }, () => {
              this.cropX = 0
            })
          })
      )
    }
    .margin(10)
  }

  build() {
    Column() {
      List() {
        ForEach(this.images, (image: Resource) => {
          ListItem() {
            this.ImageWithCrop(image)
          }
        })
      }
      .width('100%')
      .height('100%')
    }
    .backgroundColor('#F5F5F5')
    .padding(10)
  }
}

