import { Tabs, TabContent, BarPosition, Scroll, Row, Column, Image, Text, Stack } from '@ohos.arkui.advancedUI';

interface FileItem {
  name: string
  type: string
  size: string
}

@Entry
@Component
struct FileManagerApp {
  @State currentTab: number = 0
  @State swipeProgress: number = 0

  private fileData: FileItem[] = [
    { name: 'Document.pdf', type: 'pdf', size: '2.5 MB' },
    { name: 'Image.jpg', type: 'jpg', size: '1.8 MB' },
    { name: 'Spreadsheet.xlsx', type: 'xlsx', size: '3.2 MB' },
    { name: 'Presentation.pptx', type: 'pptx', size: '4.1 MB' },
    { name: 'Video.mp4', type: 'mp4', size: '15.7 MB' }
  ]

  @Builder
  FileItemBuilder(file: FileItem) {
    Row() {
      Image($r('app.media.ic_file'))
        .width(40)
        .height(40)
        .margin({ right: 10 })
      Column() {
        Text(file.name)
          .fontSize(16)
        Text(file.size)
          .fontSize(12)
          .fontColor('#666666')
      }
    }
    .padding(10)
    .margin({ bottom: 10 })
    .onClick(() => {
      console.log(`Clicked on file: ${file.name}`)
    })
  }

  @Builder
  FilesTab() {
    Scroll() {
      Column() {
        ForEach(this.fileData, (file: FileItem) => {
          this.FileItemBuilder(file)
        })
      }
    }
  }

  @Builder
  StatusTab() {
    Column() {
      Text('Status Indicator')
        .fontSize(18)
        .fontWeight(700)
      Text('Swipe left to return to Files')
        .fontSize(14)
        .margin({ top: 10 })
    }
    .width('100%')
    .height('100%')
    .justifyContent('center')
    .alignItems('center')
  }

  build() {
    Stack() {
      Column() {
        Tabs({ barPosition: BarPosition.End }) {
          TabContent() {
            this.FilesTab()
          }.tabBar('Files')

          TabContent() {
            this.StatusTab()
          }.tabBar('Status')
        }
        .onChange((index: number) => {
          this.currentTab = index
        })
      }
      .width('100%')
      .height('100%')
    }
    .width('100%')
    .height('100%')
    .gesture(
      PanGesture()
        .onActionStart(() => {
          this.swipeProgress = 0
        })
        .onActionUpdate((event: PanGestureEvent) => {
          this.swipeProgress = Math.min(Math.max(event.offsetX / 200 * 100, 0), 100)
        })
        .onActionEnd(() => {
          if (this.swipeProgress > 50) {
            this.currentTab = this.currentTab === 0 ? 1 : 0
          }
          this.swipeProgress = 0
        })
    )
  }
}

@Entry
@Component
struct LocationTrackingStatus {
  @State isTracking: boolean = false;
  @State progressValue: number = 0;
  private intervalId: number | null = null;

  private startTracking() {
    this.isTracking = true;
    this.progressValue = 0;
    this.intervalId = setInterval(() => {
      if (this.progressValue < 100) {
        this.progressValue += 10;
      } else {
        this.stopTracking();
      }
    }, 1000);
  }

  private stopTracking() {
    this.isTracking = false;
    if (this.intervalId !== null) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
    this.progressValue = 0;
  }

  private toggleTracking() {
    if (this.isTracking) {
      this.stopTracking();
    } else {
      this.startTracking();
    }
  }

  build() {
    Column() {
      Text(this.isTracking ? "Tracking in progress" : "Tracking stopped")
        .fontSize(18)
        .fontColor(this.isTracking ? "#00FF00" : "#FF0000")
        .margin({ bottom: 20 });

      Row() {
        Image($r('app.media.icon'))
          .width(24)
          .height(24)
          .margin({ right: 10 });
        Text("Location Tracking")
          .fontSize(16);
      }
      .onClick(() => this.toggleTracking())
      .margin({ bottom: 20 });

      Checkbox({ name: "Tracking Checkbox" })
        .select(this.isTracking)
        .onChange((isChecked: boolean) => {
          if (isChecked) {
            this.startTracking();
          } else {
            this.stopTracking();
          }
        })
        .margin({ bottom: 20 });

      Progress({ value: this.progressValue, total: 100 })
        .width("80%")
        .height(10)
        .margin({ bottom: 20 });
    }
    .width("100%")
    .padding(20)
    .backgroundColor("#F5F5F5");
  }
}

