  month: number;
  day: number;
}

@Entry
@Component
struct PodcastPlayer {
  @State searchText: string = '';
  @State filteredPodcasts: string[] = [];
  @State selectedDate: string = '';
  private podcasts: string[] = [
    'Tech Today',
    'Science Weekly',
    'Business Insights',
    'Health Matters',
    'History Uncovered'
  ];

  aboutToAppear() {
    this.filteredPodcasts = this.podcasts;
  }

  filteredItems(): string[] {
    if (this.searchText.trim() === '') {
      return this.podcasts;
    } else {
      return this.podcasts.filter(item =>
        item.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  build() {
    Column() {
      Search()
        .placeholder('Search podcasts...')
        .text(this.searchText)
        .width('100%')
        .onChange((value: string) => {
          this.searchText = value;
          this.filteredPodcasts = this.filteredItems();
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      if (this.filteredPodcasts.length > 0) {
        List() {
          ForEach(this.filteredPodcasts, (podcast: string) => {
            ListItem() {
              Text(podcast)
                .fontSize(18)
                .padding(12);
