import { ActionSheet, Divider, TimePicker, Button, Column, Text } from '@ohos.arkui.component';
import prompt from '@ohos.prompt';
import { BusinessError } from '@ohos.base';

interface ConfirmAction {
  value: string;
  action: () => void;
}

interface ActionSheetConfig {
  title: string;
  confirm: ConfirmAction;
  cancel: () => void;
}

interface ActionSheetProps {
  title: string;
  confirm: ConfirmAction;
  cancel: () => void;
}

interface TimePickerValue {
  hours: number;
  minutes: number;
}

@Entry
@Component
struct WorkoutPlanner {
  @State selectedTime: Date = new Date();
  @State showTimePicker: boolean = false;
  @State private actionSheetConfig: ActionSheetConfig = {
    title: 'Select Workout Duration',
    confirm: {
      value: 'Confirm',
      action: () => {
        try {
          prompt.showToast({
            message: 'Workout time set',
            duration: 2000
          });
        } catch (error) {
          console.error(`showToast args error code is ${(error as BusinessError).code}, message is ${(error as BusinessError).message}`);
        }
        this.showTimePicker = false;
      }
    },
    cancel: () => {
      this.showTimePicker = false;
    }
  };

  build() {
    Column() {
      Text('Workout Planner')
        .fontSize(20)
        .margin(10);

      Button('Select Workout Time')
        .onClick(() => {
          this.showTimePicker = true;
        })
        .accessibilityText('Select workout time button');

      if (this.showTimePicker) {
        ActionSheet({
          title: this.actionSheetConfig.title,
          confirm: {
            value: this.actionSheetConfig.confirm.value,
            action: this.actionSheetConfig.confirm.action
          },
          cancel: this.actionSheetConfig.cancel
        } as ActionSheetProps) {
          TimePicker()
            .onChange((value: TimePickerValue) => {
              this.selectedTime = new Date();
              this.selectedTime.setHours(value.hours);
              this.selectedTime.setMinutes(value.minutes);
            })
            .accessibilityText('Workout duration picker');
          Divider();
        }
      }
    }
    .width('100%')
    .height('100%');
  }
}

