  id: number;
  title: string;
  image: Resource;
  videoSrc: Resource;
}

@Entry
@Component
struct FlashcardApp {
  @State flashcards: Flashcard[] = [
    { id: 1, title: 'Card 1', image: $r('app.media.icon'), videoSrc: $rawfile('sample_video.mp4') },
    { id: 2, title: 'Card 2', image: $r('app.media.icon'), videoSrc: $rawfile('sample_video.mp4') },
    { id: 3, title: 'Card 3', image: $r('app.media.icon'), videoSrc: $rawfile('sample_video.mp4') },
    { id: 4, title: 'Card 4', image: $r('app.media.icon'), videoSrc: $rawfile('sample_video.mp4') }
  ];
  @State selectedCard: Flashcard | null = null;
  @State isPlaying: boolean = false;
  private avPlayer: media.AVPlayer | null = null;
  private videoController: VideoController = new VideoController();

  aboutToAppear(): void {
    this.avPlayer = new media.AVPlayer();
  }

  aboutToDisappear(): void {
    if (this.avPlayer) {
      this.avPlayer.release();
      this.avPlayer = null;
    }
  }

  playVideo(videoSrc: Resource): void {
    this.videoController.start();
    if (this.avPlayer) {
      this.avPlayer.reset();
      this.avPlayer.url = videoSrc;
      this.avPlayer.prepare();
      this.avPlayer.play();
      this.isPlaying = true;
    }
  }

  togglePlayPause(): void {
    if (this.avPlayer) {
      if (this.isPlaying) {
        this.avPlayer.pause();
      } else {
        this.avPlayer.play();
      }
      this.isPlaying = !this.isPlaying;
    }
  }

  nextVideo(): void {
    if (this.selectedCard) {
      const currentIndex = this.flashcards.findIndex(card => card.id === this.selectedCard!.id);
      const nextIndex = (currentIndex + 1) % this.flashcards.length;
      this.selectedCard = this.flashcards[nextIndex];
      this.playVideo(this.selectedCard.videoSrc);
    }
  }

  previousVideo(): void {
    if (this.selectedCard) {
      const currentIndex = this.flashcards.findIndex(card => card.id === this.selectedCard!.id);
      const prevIndex = (currentIndex - 1 + this.flashcards.length) % this.flashcards.length;
      this.selectedCard = this.flashcards[prevIndex];
      this.playVideo(this.selectedCard.videoSrc);
    }
  }

  build() {
    Column() {
      Grid() {
        ForEach(this.flashcards, (card: Flashcard) => {
          GridItem() {
            Column() {
              Image(card.image)
                .width(100)
                .height(100)
                .margin(5);
              Text(card.title)
                .fontSize(16)
                .margin(5);
            }
            .onClick(() => {
              this.selectedCard = card;
              this.playVideo(card.videoSrc);
            })
            .backgroundColor(this.selectedCard?.id === card.id ? '#D3D3D3' : '#F5F5F5')
            .borderRadius(8)
            .padding(10);
          };
        });
      }
      .columnsTemplate('1fr 1fr')
      .columnsGap(10)
      .rowsGap(10)
      .margin(10);

      if (this.selectedCard) {
        Video({
          src: this.selectedCard.videoSrc
        })
        .width('100%')
        .height(200)
        .margin(10);

        Row() {
          Button('Previous')
            .onClick(() => this.previousVideo())
            .margin(5);
          Button(this.isPlaying ? 'Pause' : 'Play')
            .onClick(() => this.togglePlayPause())
            .margin(5);
          Button('Next')
            .onClick(() => this.nextVideo())
            .margin(5);
        }
        .justifyContent(FlexAlign.SpaceAround);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5');
  }
}

import { Chip, Popup, Slider, Column, Text } from '@ohos.arkui.advanced';
import { ChipType } from '@ohos.arkui.advanced';
import sensor from '@ohos.sensors';
import { BusinessError } from '@ohos.base';
import abilityAccessCtrl from '@ohos.abilityAccessCtrl';
import common from '@ohos.app.ability.common';

@Entry
@Component
struct SensorDataApp {
  @State sensorData: string = 'No data';
  @State isPopupVisible: boolean = false;
  @State sensitivity: number = 50;
  private sensorId: number = -1;

  aboutToAppear() {
    let context = getContext(this) as common.UIAbilityContext;
    abilityAccessCtrl.createAtManager().requestPermissionsFromUser(context, ['ohos.permission.ACCELEROMETER']).then(() => {
      this.subscribeToSensor();
    }).catch((err: BusinessError) => {
      this.sensorData = `Permission error: ${err.message}`;
    });
  }

  aboutToDisappear() {
    if (this.sensorId !== -1) {
      sensor.off(sensor.SensorType.SENSOR_TYPE_ACCELEROMETER, this.sensorId);
    }
  }

  subscribeToSensor(): void {
    try {
      this.sensorId = sensor.on(sensor.SensorType.SENSOR_TYPE_ACCELEROMETER, 
        (data: sensor.SensorResponse) => {
          this.sensorData = `X: ${data.sensorData[0].toFixed(2)}, Y: ${data.sensorData[1].toFixed(2)}, Z: ${data.sensorData[2].toFixed(2)}`;
        }, {
          interval: this.sensitivity,
          fail: (error: BusinessError) => {
            this.sensorData = `Error: ${error.message}`;
          }
        });
    } catch (error) {
      this.sensorData = `Error: ${(error as BusinessError).message}`;
    }
  }

  onChipClick(): void {
    this.isPopupVisible = true;
  }

  onPopupClose(): void {
    this.isPopupVisible = false;
  }

  onSensitivityChange(value: number): void {
    this.sensitivity = value;
    if (this.sensorId !== -1) {
      sensor.off(sensor.SensorType.SENSOR_TYPE_ACCELEROMETER, this.sensorId);
      this.subscribeToSensor();
    }
  }

  build() {
    Column() {
      Chip({ type: ChipType.Filter }) {
        Text('Sensor Data')
      }
      .onClick(() => {
        this.onChipClick();
      })
      .margin(10);

      Popup({ isShow: this.isPopupVisible }) {
        Column() {
          Text(this.sensorData).margin(10);
          Slider({
            value: this.sensitivity,
            min: 0,
            max: 100
          })
          .onChange((value: number) => this.onSensitivityChange(value))
          .margin(10);
        }
        .width('80%')
        .height('30%')
      }
      .onClick(() => {
        this.onPopupClose();
      })
    }
  }
}

