import { Canvas, Image, Badge, BadgePosition, FlexAlign, HorizontalAlign, Column, Button } from '@ohos.arkui.dependent';
import image from '@ohos.multimedia.image';
import photoAccessHelper from '@ohos.file.photoAccessHelper';

interface ImageSource {
  id: string;
}

class BadgeStyle {
  color: string = '#FFFFFF';
  backgroundColor: string = '#FF0000';
}

@Entry
@Component
struct ImageCanvasApp {
  @State private imageSource: string = $r('app.media.icon').id.toString();
  @State private badgeCount: number = 0;

  private canvasContext?: CanvasRenderingContext2D;
  private badgeStyle: BadgeStyle = new BadgeStyle();

  aboutToAppear() {
    this.loadImageToCanvas();
  }

  private async loadImageToCanvas(): Promise<void> {
    try {
      const resourceStr = $r('app.media.icon').id.toString();
      const imageSource = image.createImageSource(resourceStr);
      const imageBitmap = await imageSource.createPixelMap();
      if (this.canvasContext && imageBitmap) {
        this.canvasContext.clearRect(0, 0, 200, 200);
        this.canvasContext.drawImage(imageBitmap, 0, 0, 200, 200);
      }
    } catch (error) {
      console.error('Error loading image:', error);
    }
  }

  private async pickImage(): Promise<void> {
    try {
      const helper = photoAccessHelper.getPhotoAccessHelper();
      const result = await helper.select();
      if (result) {
        this.imageSource = result[0].uri;
        this.badgeCount += 1;
        this.loadImageToCanvas();
      }
    } catch (error) {
      console.error('Error picking image:', error);
    }
  }

  build() {
    Column() {
      Canvas(this.canvasContext)
        .width(200)
        .height(200)
        .onReady((ctx: CanvasRenderingContext2D) => {
          this.canvasContext = ctx;
          this.loadImageToCanvas();
        });

      Badge({
        count: this.badgeCount,
        position: BadgePosition.RightTop,
        style: this.badgeStyle
      }) {
        Image(this.imageSource)
          .width(200)
          .height(200)
      }

      Button('Change Image')
        .onClick(() => {
          this.pickImage();
        });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

@Entry
@Component
struct TimerApp {
  @State isDrawerOpen: boolean = false;
  @State currentTab: number = 0;
  @State timerSeconds: number = 0;
  @State isTimerRunning: boolean = false;
  private timerInterval: number | null = null;

  build() {
    Row() {
      // Main Content Area
      Column() {
        Tabs({ barPosition: BarPosition.Start }) {
          TabContent() {
            this.TimerTab();
          }.tabBar('Timer');

          TabContent() {
            this.SettingsTab();
          }.tabBar('Settings');
        }
        .width('100%')
        .height('100%');
      }
      .layoutWeight(1);

      // Drawer Menu
      Column() {
        this.DrawerItem('Timer', 0);
        this.DrawerItem('Settings', 1);
      }
      .width('70%')
      .height('100%')
      .backgroundColor('#F5F5F5')
      .visibility(this.isDrawerOpen ? Visibility.Visible : Visibility.Hidden);
    }
    .width('100%')
    .height('100%');
  }

  @Builder DrawerItem(label: string, index: number) {
    Text(label)
      .fontSize(20)
      .padding(16)
      .onClick(() => {
        this.currentTab = index;
        this.isDrawerOpen = false;
      });
  }

  @Builder TimerTab() {
    Column() {
      Text(`Timer: ${this.timerSeconds}s`)
        .fontSize(24)
        .margin(16);

      Row() {
        Button(this.isTimerRunning ? 'Pause' : 'Start')
          .onClick(() => {
            if (this.isTimerRunning) {
              this.stopTimer();
            } else {
              this.startTimer();
            }
          })
          .margin(8);

        Button('Reset')
          .onClick(() => {
            this.resetTimer();
          })
          .margin(8);
      }
    }
    .width('100%')
    .height('100%');
  }

  @Builder SettingsTab() {
    Column() {
      Text('Settings')
        .fontSize(24)
        .margin(16);
    }
    .width('100%')
    .height('100%');
  }

  startTimer() {
    this.isTimerRunning = true;
    this.timerInterval = setInterval(() => {
      this.timerSeconds += 1;
    }, 1000);
  }

  stopTimer() {
    if (this.timerInterval) {
      clearInterval(this.timerInterval);
      this.timerInterval = null;
    }
    this.isTimerRunning = false;
  }

  resetTimer() {
    this.stopTimer();
    this.timerSeconds = 0;
  }
}

