@Entry
@Component
struct TravelPlanner {
  @State currentStep: number = 1
  @State totalSteps: number = 4
  @State stepsCompleted: number = 0
  @State breadcrumbs: string[] = ['Home', 'Itinerary', 'Review', 'Confirm']

  @Builder
  StepCircle(step: number) {
    Stack() {
      Circle()
        .width(40)
        .height(40)
        .fill(this.currentStep >= step ? '#0000FF' : '#CCCCCC')
      Text(step.toString())
        .fontSize(20)
        .fontColor(Color.White)
    }
  }

  @Builder
  BreadcrumbItem(text: string, index: number) {
    Text(text)
      .fontColor(this.breadcrumbs.length - 1 === index ? '#1698CE' : '#6B6B6B')
      .fontSize(16)
      .margin({ right: 8 })
      .onClick(() => {
        this.currentStep = index + 1
        this.breadcrumbs = this.breadcrumbs.slice(0, index + 1)
      })
  }

  build() {
    Column() {
      // Breadcrumb Navigation
      Row() {
        ForEach(this.breadcrumbs, (item: string, index: number) => {
          this.BreadcrumbItem(item, index)
          if (index < this.breadcrumbs.length - 1) {
            Text('>')
              .fontColor('#6B6B6B')
              .fontSize(16)
              .margin({ right: 8 })
          }
        })
      }
      .padding(16)
      .width('100%')
      .justifyContent(FlexAlign.Start)

      // Progress Bar
      Row() {
        ForEach([1, 2, 3, 4], (step: number) => {
          Column() {
            this.StepCircle(step)
            Text(`Step ${step}`)
              .fontSize(16)
              .margin({ top: 10 })
          }
          if (step < this.totalSteps) {
            Divider()
              .width(50)
              .strokeWidth(2)
              .color(this.currentStep > step ? '#0000FF' : '#CCCCCC')
          }
        })
      }
      .margin({ top: 50, bottom: 50 })

      // Itinerary Steps with Toggle
      Column() {
        ForEach(['Flight', 'Hotel', 'Activities', 'Payment'], (item: string, index: number) => {
          Row() {
            Text(item)
              .fontSize(18)
              .margin({ right: 20 })
            Toggle({ type: ToggleType.Checkbox })
              .onChange((isChecked: boolean) => {
                if (isChecked) {
                  this.stepsCompleted++
                } else {
                  this.stepsCompleted--
                }
              })
          }
          .margin({ bottom: 20 })
        })
      }
      .width('80%')

      // Navigation Buttons
      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentStep > 1) {
              this.currentStep--
            }
          })
          .margin({ right: 20 })
          .enabled(this.currentStep > 1)

        Button('Next')
          .onClick(() => {
            if (this.currentStep < this.totalSteps) {
              this.currentStep++
            }
          })
          .enabled(this.currentStep < this.totalSteps)
      }
      .margin({ top: 20 })

      // Completion Status
      Text(`Completion: ${(this.stepsCompleted / this.totalSteps * 100).toFixed(0)}%`)
        .fontSize(18)
        .margin({ top: 20 })
    }
    .width('100%')
    .padding(20)
  }
}

