  build() {
    Column() {
      Toggle({ type: ToggleType.Checkbox, isOn: this.currentMode === 'fast-forward' })
        .onChange((isOn: boolean) => {
          this.currentMode = isOn ? 'fast-forward' : 'normal';
        })
        .margin(10);

      Scroll() {
