                this.currentFrame--;
              }
            })
            .onActionEnd(() => {});
        }
      );

      Tabs() {
        TabContent() {
          Column() {
            Text(`Playback Mode: ${this.currentMode}`)
              .fontSize(16)
              .margin(5);
            Text(`Current Frame: ${this.frames[this.currentFrame - 1]}`)
              .fontSize(16)
              .margin(5);
          }
        }
      }
      .width('100%')
      .margin(10);
    }
    .width('100%')
    .height('100%')
    .padding(10);
  }
}

