          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 });
        Text('Question content goes here...')
          .fontSize(16)
          .margin({ bottom: 20 });
      }
      .width('100%')
      .padding(16);

      // Navigation Buttons
      Row({ space: 10 }) {
        Button('Previous')
          .onClick(() => {
