import promptAction from '@ohos.promptAction';

interface Expense {
  id: number;
  amount: number;
  category: string;
  description: string;
}

@Entry
@Component
struct ExpenseTracker {
  @State expenses: Array<Expense> = [
    { id: 1, amount: 50, category: 'Food', description: 'Lunch' },
    { id: 2, amount: 100, category: 'Transport', description: 'Bus fare' },
    { id: 3, amount: 200, category: 'Shopping', description: 'Clothes' }
  ];
  @State showAlert: boolean = false;
  @State selectedExpenseId: number = 0;

  aboutToAppear() {
  }

  showDeleteDialog() {
    promptAction.showDialog({
      title: 'Delete Expense',
      message: 'Are you sure you want to delete this expense?',
      buttons: [
        {
          text: 'Cancel',
          color: '#000000'
        },
        {
          text: 'Delete',
          color: '#FF0000'
        }
      ]
    }).then((result) => {
      if (result.index === 1) {
        this.deleteExpense(this.selectedExpenseId);
      }
    });
  }

  deleteExpense(id: number) {
    this.expenses = this.expenses.filter(expense => expense.id !== id);
    this.showAlert = false;
  }

  build() {
    Column() {
      List() {
        ForEach(this.expenses, (expense: Expense) => {
          ListItem() {
            Row() {
              Column() {
                Text(expense.category)
                  .fontSize(18)
                  .fontWeight(FontWeight.Bold);
                Text(expense.description)
                  .fontSize(14)
                  .fontColor(Color.Gray);
              }
              Text(`$${expense.amount}`)
                .fontSize(18)
                .fontColor(Color.Blue);
            }
            .justifyContent(FlexAlign.SpaceBetween)
            .width('100%')
            .padding(10)
            .gesture(
              PanGesture()
                .onActionEnd((event: GestureEvent) => {
                  if (event.offsetX < -100) {
                    this.selectedExpenseId = expense.id;
                    this.showDeleteDialog();
                  }
                })
            );
          }
        });
      }
      .width('100%')
      .height('80%');
    }
    .width('100%')
    .height('100%');
  }
}

@Entry
@Component
struct StepCounterApp {
  @State steps: number = 0
  @State isCounting: boolean = false
  @State selectedOption: string = 'Start'
  @State isAccordionExpanded: boolean = false

  private options: string[] = ['Start', 'Stop', 'Reset']

  private handleVoiceCommand(command: string) {
    switch (command) {
      case 'start':
        this.isCounting = true
        this.selectedOption = 'Stop'
        break
      case 'stop':
        this.isCounting = false
        this.selectedOption = 'Start'
        break
      case 'reset':
        this.steps = 0
        this.isCounting = false
        this.selectedOption = 'Start'
        break
    }
  }

  private toggleAccordion() {
    this.isAccordionExpanded = !this.isAccordionExpanded
  }

  build() {
    Column() {
      Text(`Steps: ${this.steps}`)
        .fontSize(24)
        .margin(10)

      Row() {
        ForEach(this.options, (option: string) => {
          Button(option)
            .onClick(() => {
              this.handleVoiceCommand(option.toLowerCase())
            })
            .margin(5)
        })
      }
      .justifyContent(FlexAlign.SpaceEvenly)

      Button('Toggle Accordion')
        .onClick(() => {
          this.toggleAccordion()
        })
        .margin(10)

      if (this.isAccordionExpanded) {
        Column() {
          Text('Voice Commands:')
            .fontSize(18)
            .margin(5)
          Text('Say "start" to begin counting')
            .margin(5)
          Text('Say "stop" to pause counting')
            .margin(5)
          Text('Say "reset" to reset steps')
            .margin(5)
        }
        .padding(10)
        .borderRadius(8)
        .backgroundColor('#f0f0f0')
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

import { Popup, Badge, Button, Column, Radio } from '@ohos.arkui.component';
import { animateTo } from '@ohos.animation';
import { Curve } from '@ohos.animation';

@Entry
@Component
struct CustomPopup {
  @State isPopupVisible: boolean = false;
  @State selectedRadio: string = 'Option 1';
  @State badgeCount: number = 5;
  @State popupOpacity: number = 0;

  build() {
    Column() {
      Button('Show Popup')
        .onClick(() => {
          this.isPopupVisible = true;
          animateTo({
            duration: 300,
            curve: Curve.EaseInOut
          }, () => {
            this.popupOpacity = 1;
          });
        })
        .margin(20)

      Popup({
        isVisible: this.isPopupVisible,
        onDismiss: () => {
          animateTo({
            duration: 300,
            curve: Curve.EaseInOut
          }, () => {
            this.popupOpacity = 0;
            this.isPopupVisible = false;
          });
        }
      }) {
        Column() {
          Radio({ group: 'radioGroup', value: 'Option 1' })
            .checked(this.selectedRadio === 'Option 1')
            .onChange((isChecked: boolean) => {
              if (isChecked) {
                this.selectedRadio = 'Option 1';
              }
            })
            .margin(10)

          Radio({ group: 'radioGroup', value: 'Option 2' })
            .checked(this.selectedRadio === 'Option 2')
            .onChange((isChecked: boolean) => {
              if (isChecked) {
                this.selectedRadio = 'Option 2';
              }
            })
            .margin(10)

          Badge({
            count: this.badgeCount,
            position: 'rightTop'
          })
          .badgeStyle({
            color: '#FFFFFF',
            backgroundColor: '#FF0000'
          })
          .margin(10)
        }
        .width('80%')
        .backgroundColor('#FFFFFF')
        .borderRadius(10)
        .padding(20)
        .opacity(this.popupOpacity)
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

