import { List, ListItem, TextInput, Button, Column, Row, Text, Scroll } from '@ohos.arkui.component';
import { PanGesture } from '@ohos.arkui.gesture';
import { Entry, Component, State, Builder } from '@ohos.arkui.advanced';
import { BarState, FontWeight, Color } from '@ohos.arkui.common';
import { AppStorage } from '@ohos.data.storage';

const CONTACTS_KEY = 'contacts';

class Contact {
  id: string;
  name: string;
  phone: string;

  constructor(id: string, name: string, phone: string) {
    this.id = id;
    this.name = name;
    this.phone = phone;
  }
}

@Entry
@Component
struct ContactManager {
  @State contacts: Contact[] = [];
  @State selectedContact: Contact | null = null;
  @State isEditing: boolean = false;
  @State tempName: string = '';
  @State tempPhone: string = '';
  @State isNameValid: boolean = true;
  @State isPhoneValid: boolean = true;

  aboutToAppear() {
    this.loadContacts();
  }

  loadContacts() {
    try {
      const storedContacts = AppStorage.Get(CONTACTS_KEY) || '[]';
      this.contacts = JSON.parse(storedContacts) as Contact[];
    } catch (error) {
      console.error('Failed to load contacts:', error.message);
    }
  }

  saveContacts() {
    try {
      AppStorage.Set(CONTACTS_KEY, JSON.stringify(this.contacts));
    } catch (error) {
      console.error('Failed to save contacts:', error.message);
    }
  }

  validateName(name: string): boolean {
    return name.trim().length > 0;
  }

  validatePhone(phone: string): boolean {
    const phoneRegex = /^\d{3}-\d{3}-\d{4}$/;
    return phoneRegex.test(phone);
  }

  handleAddContact() {
    if (this.validateName(this.tempName) && this.validatePhone(this.tempPhone)) {
      const newContact = new Contact(Date.now().toString(), this.tempName, this.tempPhone);
      this.contacts.push(newContact);
      this.saveContacts();
      this.tempName = '';
      this.tempPhone = '';
      this.isEditing = false;
    } else {
      this.isNameValid = this.validateName(this.tempName);
      this.isPhoneValid = this.validatePhone(this.tempPhone);
    }
  }

  handleEditContact(contact: Contact) {
    this.selectedContact = contact;
    this.tempName = contact.name;
    this.tempPhone = contact.phone;
    this.isEditing = true;
  }

  handleUpdateContact() {
    if (this.validateName(this.tempName) && this.validatePhone(this.tempPhone)) {
      if (this.selectedContact) {
        this.selectedContact.name = this.tempName;
        this.selectedContact.phone = this.tempPhone;
        this.saveContacts();
        this.isEditing = false;
        this.selectedContact = null;
      }
    } else {
      this.isNameValid = this.validateName(this.tempName);
      this.isPhoneValid = this.validatePhone(this.tempPhone);
    }
  }

  handleDeleteContact(contact: Contact) {
    this.contacts = this.contacts.filter(c => c.id !== contact.id);
    this.saveContacts();
  }

  @Builder
  ContactItem(contact: Contact) {
    Row() {
      Column() {
        Text(contact.name)
          .fontSize(16)
          .fontWeight(FontWeight.Medium);
        Text(contact.phone)
          .fontSize(14)
          .fontColor(Color.Gray);
      }
    }
    .width('100%')
    .padding(10)
    .backgroundColor(Color.White)
    .onClick(() => {
      this.handleEditContact(contact);
    });
  }

  @Builder
  ContactForm() {
    Column() {
      TextInput({ placeholder: 'Name', text: this.tempName })
        .onChange((value: string) => {
          this.tempName = value;
          this.isNameValid = this.validateName(value);
        })
        .backgroundColor(this.isNameValid ? Color.White : Color.Red);

      TextInput({ placeholder: 'Phone (XXX-XXX-XXXX)', text: this.tempPhone })
        .onChange((value: string) => {
          this.tempPhone = value;
          this.isPhoneValid = this.validatePhone(value);
        })
        .backgroundColor(this.isPhoneValid ? Color.White : Color.Red);

      Button(this.isEditing ? 'Update Contact' : 'Add Contact')
        .onClick(() => {
          this.isEditing ? this.handleUpdateContact() : this.handleAddContact();
        });
    }
    .width('80%')
    .padding(20);
  }

  build() {
    Column() {
      if (this.isEditing || this.selectedContact) {
        this.ContactForm();
      } else {
        Scroll() {
          List({ space: 10 }) {
            ForEach(this.contacts, (contact: Contact) => {
              ListItem() {
                this.ContactItem(contact);
              }
              .swipeAction({
                end: {
                  builder: () => {
                    Button('Delete')
                      .width(100)
                      .height('100%')
                      .backgroundColor(Color.Red)
                      .onClick(() => {
                        this.handleDeleteContact(contact);
                      });
                  },
                  background: Color.Red
                }
              });
            }, (contact: Contact) => contact.id);
          }
          .width('100%');
        }
        .scrollBar(BarState.Off);
      }
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

@Entry
@Component
struct PaymentFlow {
  @State currentStep: number = 0;
  @State showPopup: boolean = false;

  build() {
    Column() {
      Column() {
        Row() {
          ForEach([0, 1, 2], (step: number) => {
            Column() {
              Column()
                .width(30)
                .height(30)
                .borderRadius(15)
                .backgroundColor(this.currentStep >= step ? '#007DFF' : '#999999')
              Text(`Step ${step + 1}`)
                .fontSize(12)
            }
            .margin(10)
          })
        }
        .justifyContent(FlexAlign.SpaceAround)
        .width('100%')
        .margin({ top: 20, bottom: 20 })

        Column() {
          if (this.currentStep === 0) {
            Text('Enter Payment Details')
              .fontSize(20)
          } else if (this.currentStep === 1) {
            Text('Review Payment')
              .fontSize(20)
          } else {
            Text('Confirm Payment')
              .fontSize(20)
          }
        }
        .height(100)
        .justifyContent(FlexAlign.Center)

        Button('Start Payment')
          .onClick(() => {
            this.startPayment()
          })
          .margin(20)
      }
      .width('100%')
      .height('100%')
      .justifyContent(FlexAlign.Center)

      if (this.showPopup) {
        Column() {
          Text('Payment Completed!')
            .fontSize(20)
            .margin(10)
          Button('OK')
            .onClick(() => {
              this.showPopup = false
            })
            .margin(10)
        }
        .width(200)
        .height(150)
        .justifyContent(FlexAlign.Center)
        .backgroundColor('#FFFFFF')
        .borderRadius(10)
        .shadow({ radius: 10, color: '#000000', offsetX: 0, offsetY: 0 })
      }
    }
  }

  startPayment() {
    let steps = [0, 1, 2]
    steps.forEach((step, index) => {
      setTimeout(() => {
        animateTo({
          duration: 500
        }, () => {
          this.currentStep = step
          if (step === 2) {
            this.showPopup = true
          }
        })
      }, index * 1000)
    })
  }
}

import mediaquery from '@ohos.mediaquery';

@Entry
@Component
struct DocumentScanner {
  @State selectedEncryption: string = 'None';
  @State statusMessage: string = 'Ready to scan...';
  @State isLandscape: boolean = false;

  aboutToAppear() {
    let listener = mediaquery.matchMediaSync('(orientation: landscape)');
    this.isLandscape = listener.matches;
    this.updateStatusMessage();
    listener.on('change', (result: mediaquery.MediaQueryResult) => {
      this.isLandscape = result.matches;
      this.updateStatusMessage();
    });
  }

  updateStatusMessage() {
    this.statusMessage = this.isLandscape ? 'Landscape mode' : 'Portrait mode';
  }

  build() {
    Column() {
      Row() {
        Text(this.selectedEncryption)
          .fontSize(16)
          .width('80%')
          .textAlign(TextAlign.Center)
      }.width('100%').justifyContent(FlexAlign.Center)

      Row() {
        Text(this.statusMessage)
          .fontSize(16)
          .textOverflow({ overflow: TextOverflow.Ellipsis })
          .maxLines(1)
          .animation({ duration: 1000, curve: Curve.EaseInOut })
      }.width('100%').justifyContent(FlexAlign.Center).margin({ top: 20 })

      Row() {
        Image($r('sys.media.ohos_app_icon'))
          .width(200)
          .height(200)
          .backgroundColor('#FFFFFF')
          .margin(20)
      }.width('100%').justifyContent(FlexAlign.Center)
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
