@Entry
@Component
struct MapGallery {
  @State currentIndex: number = 0;
  private swiperController: SwiperController = new SwiperController();

  private mapImages: Array<string> = [
    'common/images/map_placeholder.png',
    'common/images/map_placeholder.png',
    'common/images/map_placeholder.png',
    'common/images/map_placeholder.png',
    'common/images/map_placeholder.png'
  ];

  private locationNames: Array<string> = [
    'Downtown',
    'Waterfront',
    'Park',
    'Shopping District',
    'Residential Area'
  ];

  build() {
    Column() {
      Swiper(this.swiperController) {
        ForEach(this.mapImages, (image: string, index: number) => {
          Image($rawfile(image))
            .objectFit(ImageFit.Cover)
            .width('100%')
            .height(300)
            .borderRadius(8)
            .onError(() => {
              console.error('Failed to load map image');
            });
        })
      }
      .autoPlay(true)
      .interval(3000)
      .duration(500)
      .loop(true)
      .index(this.currentIndex)
      .onChange((index: number) => {
        this.currentIndex = index;
      })
      .accessibilityLevel('Map Gallery Swiper')
      .height(300)
      .margin({ bottom: 16 });

      Row({ space: 8 }) {
        ForEach(this.locationNames, (name: string, index: number) => {
          Button(name)
            .onClick(() => {
              this.currentIndex = index;
            })
            .stateEffect(this.currentIndex === index)
            .accessibilityLevel(`Navigate to ${name}`)
            .borderRadius(4)
            .padding(8);
        })
      }
      .justifyContent(FlexAlign.Center)
      .margin({ bottom: 16 });

      Text('Use arrow keys for navigation or tab to select locations')
        .fontSize(12)
        .fontColor('#666666')
        .margin({ bottom: 16 });
    }
    .width('100%')
    .height('100%')
    .padding(16)
    .onKeyEvent((event: KeyEvent) => {
      if (event.keyCode === 21 && this.currentIndex > 0) {
        this.currentIndex--;
      } else if (event.keyCode === 22 && this.currentIndex < this.mapImages.length - 1) {
        this.currentIndex++;
      }
    });
  }
}

import { CustomDialogController, CustomDialog, DialogAlignment } from '@ohos.arkui.UIContext';
import { Column, Flex, FlexAlign, Text, Button } from '@ohos.arkui.component';
