@CustomDialog
struct ConfirmationDialog {
  controller: CustomDialogController;
  title: string = 'Confirm Action';
  cancel?: () => void;
  confirm?: () => void;

  @State rotationAngle: number = 0;

  onRotationStart(): void {
    console.log('Rotation gesture started');
  }

  onRotationUpdate(event: RotationGestureEvent): void {
    this.rotationAngle = event.angle;
    console.log(`Rotation angle: ${this.rotationAngle}`);
  }

  onRotationEnd(): void {
    console.log('Rotation gesture ended');
  }

  build() {
    Column() {
      Text(this.title)
        .fontSize(20)
        .margin(10);

      Flex({ justifyContent: FlexAlign.SpaceAround }) {
        Button('Cancel')
          .onClick(() => {
            this.controller.close();
            this.cancel?.();
          })
          .margin(10);

        Button('Confirm')
          .onClick(() => {
            this.controller.close();
            this.confirm?.();
          })
          .margin(10);
      }
    }
    .padding(20)
    .gesture(
      RotationGesture()
        .onStart(() => this.onRotationStart())
        .onUpdate((event: RotationGestureEvent) => this.onRotationUpdate(event))
        .onEnd(() => this.onRotationEnd())
    );
  }
}

