import picker from '@ohos.file.picker';
import { Video, VideoController } from '@ohos.multimedia.media';

@Entry
@Component
struct RecipeVideoApp {
  @State videoSrc: string = 'common/video_frame.png';
  @State isPlaying: boolean = false;
  @State selectedFile: string = '';
  @State showMarquee: boolean = false;

  private videoController: VideoController = new VideoController();

  build() {
    Column() {
      Video({
        src: this.videoSrc,
        controller: this.videoController
      })
        .width('100%')
        .height(300)
        .onClick(() => {
          this.isPlaying = !this.isPlaying;
          if (this.isPlaying) {
            this.videoController.start();
          } else {
            this.videoController.pause();
          }
        });

      if (this.showMarquee) {
        Text(this.selectedFile)
          .margin(10)
          .fontColor('#000000')
          .textOverflow({ overflow: TextOverflow.Ellipsis });
      }

      Row() {
        Button('Select File')
          .onClick(() => {
            let documentPicker = new picker.DocumentViewPicker();
            documentPicker.select()
              .then((fileList: Array<string>) => {
                if (fileList.length > 0) {
                  this.selectedFile = fileList[0];
                  this.showMarquee = true;
                }
              })
              .catch((err: Error) => {
                console.error('File selection failed:', err);
              });
          })
          .margin(10);

        Button('Share')
          .onClick(() => {
            console.log('Sharing file:', this.selectedFile);
          })
          .margin(10);
      }
      .justifyContent(FlexAlign.Center)
      .margin(10);
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

