@Entry
@Component
struct PerformanceMonitorApp {
  @State currentStep: number = 0
  private totalSteps: number = 3
  private metrics: string[] = ["Transport", "Music", "Performance"]

  @Builder
  StepIndicator(step: number) {
    Stack() {
      Circle()
        .width(40)
        .height(40)
        .fill(this.currentStep >= step ? '#0000FF' : '#CCCCCC')
      Text(step.toString())
        .fontSize(20)
        .fontColor(Color.White)
    }
  }

  @Builder
  StepContent(step: number) {
    Column() {
      Text(`Metric: ${this.metrics[step]}`)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      Text(`Details for ${this.metrics[step]}`)
        .fontSize(18)
        .fontColor(Color.Gray)
        .margin({ bottom: 20 })

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ bottom: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }

  build() {
    Column() {
      Row() {
        ForEach([0, 1, 2], (step: number) => {
          Column() {
            this.StepIndicator(step + 1)
            Text(`Step ${step + 1}`)
              .fontSize(16)
              .margin({ top: 10 })
          }

          if (step < this.totalSteps - 1) {
            Divider()
              .width(50)
              .strokeWidth(2)
              .color(this.currentStep > step ? '#0000FF' : '#CCCCCC')
          }
        })
      }
      .margin({ top: 50, bottom: 50 })

      this.StepContent(this.currentStep)

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentStep > 0) {
              this.currentStep--
            }
          })
          .margin({ right: 20 })
          .enabled(this.currentStep > 0)

        Button('Next')
          .onClick(() => {
            if (this.currentStep < this.totalSteps - 1) {
              this.currentStep++
            }
          })
          .enabled(this.currentStep < this.totalSteps - 1)
      }
      .margin({ top: 50 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .onTouch((event: TouchEvent) => {
      if (event.type === TouchType.Up && event.touches.length > 0) {
        const touchX = event.touches[0].windowX
        const componentWidth = 360
        if (touchX > componentWidth / 2 && this.currentStep < this.totalSteps - 1) {
          this.currentStep++
        } else if (touchX < componentWidth / 2 && this.currentStep > 0) {
          this.currentStep--
        }
      }
    })
  }
}

