import { Tabs, TabContent, Column, Row, Text, Image, Button, PanGesture, PanGestureEvent, FontWeight, Color, FlexAlign } from '@ohos.arkui.advanced';

@Entry
@Component
struct FitnessTracker {
  @State currentTabIndex: number = 0;
  @State progress: number = 0;

  private workouts: string[] = ["Warm-Up", "Cardio", "Strength Training", "Cooldown"];

  private onTabChange(index: number): void {
    this.currentTabIndex = index;
    this.progress = (index + 1) * 25;
  }

  private onSwipe(event: PanGestureEvent): void {
    if (event.offsetX < -50 && this.currentTabIndex < this.workouts.length - 1) {
      this.currentTabIndex++;
      this.progress = (this.currentTabIndex + 1) * 25;
    } else if (event.offsetX > 50 && this.currentTabIndex > 0) {
      this.currentTabIndex--;
      this.progress = (this.currentTabIndex + 1) * 25;
    }
  }

  build() {
    Column() {
      Tabs({ index: this.currentTabIndex }) {
        ForEach(this.workouts, (workout: string, index: number) => {
          TabContent() {
            Column({ space: 20 }) {
              Text(workout)
                .fontSize(24)
                .fontWeight(FontWeight.Bold);
              Text(`Progress: ${this.progress}%`)
                .fontSize(18);
              Image()
                .width(150)
                .height(150)
                .border({ width: 1, color: Color.Gray });
            }
            .width('100%')
            .height('100%')
            .justifyContent(FlexAlign.Center)
            .padding(20);
          }
          .onPanGesture((event: PanGestureEvent) => this.onSwipe(event));
        })
      }
      .onChange((index: number) => this.onTabChange(index))
      .barWidth(0);

      Row({ space: 20 }) {
        ForEach(this.workouts, (workout: string, index: number) => {
          Button(workout)
            .onClick(() => {
              this.currentTabIndex = index;
              this.progress = (index + 1) * 25;
            });
        })
      }
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

