import { Button, Column, PanGesture, GestureEvent, FlexAlign } from '@ohos.arkui.node';

@Entry
@Component
struct SwipeOrderButton {
  @State buttonText: string = 'Swipe to Order';
  @State buttonColor: string = '#007AFF';
  @State isSwiping: boolean = false;

  build() {
    Column() {
      Button(this.buttonText)
        .width(200)
        .height(80)
        .backgroundColor(this.buttonColor)
        .gesture(
          PanGesture()
            .onActionStart(() => {
              this.isSwiping = true;
              this.buttonText = 'Swiping...';
              this.buttonColor = '#4CD964';
            })
            .onActionUpdate((event: GestureEvent) => {
              if (event.offsetX > 0) {
                this.buttonColor = '#4CD964';
              } else if (event.offsetX < 0) {
                this.buttonColor = '#FF3B30';
              }
            })
            .onActionEnd((event: GestureEvent) => {
              this.isSwiping = false;
              if (event.offsetX > 0) {
                this.buttonText = 'Order Placed!';
                this.buttonColor = '#4CD964';
              } else if (event.offsetX < 0) {
                this.buttonText = 'Order Cancelled';
                this.buttonColor = '#FF3B30';
              } else {
                this.buttonText = 'Swipe to Order';
                this.buttonColor = '#007AFF';
              }
            })
        )
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

import hilog from '@ohos.hilog';
import promptAction from '@ohos.promptAction';
import { Toggle, List, ListItem } from '@ohos.arkui.advanced';

interface ActionSheetItem {
  title: string;
  action: () => void;
}

interface Task {
  id: number;
  name: string;
  completed: boolean;
}

@Entry
@Component
struct TaskManager {
  @State tasks: Task[] = [
    { id: 1, name: 'Complete project', completed: false },
    { id: 2, name: 'Review code', completed: false },
    { id: 3, name: 'Test application', completed: false }
  ];

  showFileOperations() {
    let actionSheetItems: Array<ActionSheetItem> = [
      { title: 'Save tasks to file', action: () => { hilog.info(0x0000, 'TaskManager', 'Save tasks to file selected'); } },
      { title: 'Load tasks from file', action: () => { hilog.info(0x0000, 'TaskManager', 'Load tasks from file selected'); } },
      { title: 'Delete task file', action: () => { hilog.info(0x0000, 'TaskManager', 'Delete task file selected'); } }
    ];

    let actionSheetOptions: promptAction.ActionMenuOptions = {
      title: 'File Operations',
      confirm: {
        value: 'Cancel',
        action: () => { hilog.info(0x0000, 'TaskManager', 'ActionSheet canceled'); }
      },
      sheets: actionSheetItems
    };

    promptAction.showActionMenu(actionSheetOptions);
  }

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.tasks, (task: Task) => {
          ListItem() {
            Row() {
              Toggle({ type: 'switch' })
                .isOn(task.completed)
                .onChange((isOn: boolean) => {
                  this.tasks = this.tasks.map(t => {
                    if (t.id === task.id) {
                      return {...t, completed: isOn};
                    }
                    return t;
                  });
                });
              Text(task.name)
                .margin({ left: 10 });
            }
            .width('100%')
            .padding(10)
          }
        })
      }
      .width('100%')
      .height('70%')

      Button('File Operations')
        .onClick(() => {
          this.showFileOperations();
        })
        .width('50%')
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

@Entry
@Component
struct NoteTakingApp {
  @State noteContent: string = '';
  @State isNoteValid: boolean = false;
  @State savedNotes: string[] = [];
  @State showFeedback: boolean = false;
  @State feedbackMessage: string = '';
  @State feedbackColor: string = '';

  build() {
    SideBarContainer(SideBarContainerType.Embed) {
      Column() {
        TextInput({ placeholder: 'Enter your note here' })
          .width('100%')
          .height(100)
          .onChange((value: string) => {
            this.noteContent = value;
            this.validateNote();
          });

        Button('Save Note', { type: ButtonType.Capsule })
          .width('100%')
          .margin(10)
          .onClick(() => {
            if (this.isNoteValid) {
              this.savedNotes.push(this.noteContent);
              this.showFeedback = true;
              this.feedbackMessage = 'Note saved successfully!';
              this.feedbackColor = 'green';
              this.noteContent = '';
              setTimeout(() => {
                this.showFeedback = false;
              }, 2000);
            } else {
              this.showFeedback = true;
              this.feedbackMessage = 'Note cannot be empty!';
              this.feedbackColor = 'red';
              setTimeout(() => {
                this.showFeedback = false;
              }, 2000);
            }
          });

        if (this.showFeedback) {
          Text(this.feedbackMessage)
            .fontColor(this.feedbackColor)
            .fontSize(16)
            .margin(10)
            .animation({ duration: 500, curve: Curve.EaseInOut });
        }
      }
      .width('100%')
      .padding(20);

      Column() {
        Text('Saved Notes')
          .fontSize(20)
          .margin(10);
        ForEach(this.savedNotes, (note: string) => {
          Text(note)
            .fontSize(16)
            .margin(5);
        });
      }
      .width('30%')
      .padding(10);
    }
  }

  private validateNote() {
    this.isNoteValid = this.noteContent.trim().length > 0;
  }
}

@Entry
@Component
struct PinchToZoomImage {
  @State scaleValue: number = 1.0
  @State lastScale: number = 1.0
  @State rotationAngle: number = 0
  @State offsetX: number = 0
  @State offsetY: number = 0
  @State initialDistance: number = 0

  build() {
    Column() {
      Stack() {
        Image($r('app.media.icon'))
          .objectFit(ImageFit.Contain)
          .width('100%')
          .height('100%')
          .scale({ x: this.scaleValue, y: this.scaleValue })
          .translate({ x: this.offsetX, y: this.offsetY })
          .rotate({ x: 0, y: 0, z: 1, angle: this.rotationAngle })
          .gesture(
            GestureGroup(
              GestureMode.Parallel,
              PinchGesture()
                .onActionStart(() => {
                  this.lastScale = this.scaleValue
                })
                .onActionUpdate((event: PinchGestureEvent) => {
                  this.scaleValue = this.lastScale * event.scale
                })
                .onActionEnd(() => {
                  this.lastScale = this.scaleValue
                }),
              RotationGesture()
                .onActionUpdate((event: RotationGestureEvent) => {
                  this.rotationAngle += event.angle
                })
            )
          )
          .clip(true)

        Button('Reset')
          .onClick(() => {
            this.scaleValue = 1.0
            this.rotationAngle = 0
            this.offsetX = 0
            this.offsetY = 0
          })
          .position({ x: 20, y: 20 })
          .backgroundColor('#FFFFFF')
          .padding({ left: 10, right: 10, top: 5, bottom: 5 })
          .borderRadius(5)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

interface TimeValue {
  hour: number;
  minute: number;
}

@Entry
@Component
struct RideSharingApp {
  @State name: string = '';
  @State phone: string = '';
  @State selectedTime: TimeValue = { hour: 0, minute: 0 };
  @State time: string = '';
  @State progress: number = 0;
  @State isProgressActive: boolean = false;
  @State nameError: string = '';
  @State phoneError: string = '';
  @State timeError: string = '';

  validateName(): boolean {
    if (this.name.trim() === '') {
      this.nameError = 'Name is required';
      return false;
    }
    this.nameError = '';
    return true;
  }

  validatePhone(): boolean {
    const phoneRegex = /^\d{10}$/;
    if (!phoneRegex.test(this.phone)) {
      this.phoneError = 'Phone must be 10 digits';
      return false;
    }
    this.phoneError = '';
    return true;
  }

  validateTime(): boolean {
    if (this.selectedTime.hour === 0 && this.selectedTime.minute === 0) {
      this.timeError = 'Time is required';
      return false;
    }
    this.timeError = '';
    return true;
  }

  validateForm(): boolean {
    return this.validateName() && this.validatePhone() && this.validateTime();
  }

  startRide() {
    if (!this.validateForm()) return;
    this.isProgressActive = true;
    const interval = setInterval(() => {
      if (this.progress >= 100) {
        clearInterval(interval);
        this.isProgressActive = false;
        return;
      }
      this.progress += 10;
    }, 1000);
  }

  build() {
    Column() {
      Text('Ride Sharing App')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      TextInput({ placeholder: 'Enter your name' })
        .width('80%')
        .height(40)
        .margin({ bottom: 10 })
        .onChange((value: string) => {
          this.name = value;
          this.validateName();
        });

      if (this.nameError) {
        Text(this.nameError)
          .fontSize(12)
          .fontColor(Color.Red)
          .margin({ bottom: 10 });
      }

      TextInput({ placeholder: 'Enter your phone number' })
        .width('80%')
        .height(40)
        .margin({ bottom: 10 })
        .onChange((value: string) => {
          this.phone = value;
          this.validatePhone();
        });

      if (this.phoneError) {
        Text(this.phoneError)
          .fontSize(12)
          .fontColor(Color.Red)
          .margin({ bottom: 10 });
      }

      TimePicker()
        .width('80%')
        .height(40)
        .margin({ bottom: 10 })
        .onChange((value: TimeValue) => {
          this.selectedTime = value;
          this.time = `${value.hour}:${value.minute}`;
          this.validateTime();
        });

      if (this.timeError) {
        Text(this.timeError)
          .fontSize(12)
          .fontColor(Color.Red)
          .margin({ bottom: 10 });
      }

      Progress({ value: this.progress, total: 100 })
        .width('80%')
        .height(10)
        .margin({ bottom: 20 });

      Button('Start Ride', { type: ButtonType.Normal })
        .width('80%')
        .height(40)
        .enabled(this.validateForm() && !this.isProgressActive)
        .onClick(() => {
          this.startRide();
        });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center);
  }
}

