interface Product {
  id: number;
  name: string;
  price: number;
  image: string;
  audioSrc: string;
}

@Entry
@Component
struct ECommerceApp {
  @StorageLink('products') products: Array<Product> = [];

  @State refreshing: boolean = false;

  aboutToAppear() {
    AppStorage.setOrCreate('products', [
      { id: 1, name: 'Product 1', price: 19.99, image: 'https://example.com/product1.jpg', audioSrc: 'audio_placeholder' },
      { id: 2, name: 'Product 2', price: 29.99, image: 'https://example.com/product2.jpg', audioSrc: 'audio_placeholder' },
      { id: 3, name: 'Product 3', price: 39.99, image: 'https://example.com/product3.jpg', audioSrc: 'audio_placeholder' }
    ]);
  }

  onRefresh() {
    this.refreshing = true;
    setTimeout(() => {
      this.products.push({ 
        id: this.products.length + 1, 
        name: `Product ${this.products.length + 1}`, 
        price: 49.99, 
        image: 'https://example.com/product4.jpg', 
        audioSrc: 'audio_placeholder' 
      });
      this.refreshing = false;
    }, 1000);
  }

  playAudio(audioSrc: string) {
    console.log(`Playing audio: ${audioSrc}`);
  }

  build() {
    Column() {
      List() {
        ForEach(this.products, (product: Product) => {
          ListItem() {
            Row() {
              Image(product.image)
                .width(100)
                .height(100)
                .margin(10);
              Column() {
                Text(product.name)
                  .fontSize(18)
                  .fontWeight(FontWeight.Bold);
                Text(`$${product.price.toFixed(2)}`)
                  .fontSize(16)
                  .margin({ top: 5 });
              }
              .margin({ left: 10 });
              Button('Play')
                .width(40)
                .height(40)
                .onClick(() => this.playAudio(product.audioSrc));
            }
            .width('100%')
            .justifyContent(FlexAlign.SpaceBetween)
            .padding(10);
          }
        });
      }
      .width('100%')
      .height('100%');
    }
    .width('100%')
    .height('100%');
  }
}

