@Entry
@Component
struct WaterIntakeTracker {
  @State waterIntake: number = 0;
  @State dailyGoal: number = 2000;
  @State progress: number = 0;
  @State inputValue: string = '';
  @State validationError: string = '';

  updateProgress() {
    this.progress = (this.waterIntake / this.dailyGoal) * 100;
  }

  validateInput(value: string): boolean {
    const numValue = Number(value);
    if (isNaN(numValue)) {
      this.validationError = 'Please enter a valid number';
      return false;
    }
    if (numValue <= 0) {
      this.validationError = 'Value must be greater than 0';
      return false;
    }
    this.validationError = '';
    return true;
  }

  handleSubmit() {
    if (this.validateInput(this.inputValue)) {
      this.waterIntake += Number(this.inputValue);
      this.updateProgress();
      this.inputValue = '';
    }
  }

  build() {
    Column({ space: 20 }) {
      Text('Daily Water Intake Tracker')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Text(`Goal: ${this.dailyGoal} ml`)
        .fontSize(18)
        .margin({ bottom: 10 });

      Text(`Consumed: ${this.waterIntake} ml`)
        .fontSize(18)
        .margin({ bottom: 10 });

      Progress({ value: this.progress, total: 100, style: ProgressStyle.Linear })
        .width('80%')
        .height(20)
        .margin({ bottom: 20 });

      TextInput({ placeholder: 'Enter amount in ml', text: this.waterIntake.toString() })
        .onChange((value: string) => {
          if (/^\d*$/.test(value)) {
            this.waterIntake = Number(value);
            this.updateProgress();
          }
        })
        .width('80%')
        .height(50)
        .margin({ bottom: 20 });

      TextInput({ placeholder: 'Enter water intake in ml', text: this.inputValue })
        .onChange((value: string) => {
          this.inputValue = value;
        })
        .width('80%')
        .height(50)
        .margin({ bottom: 10 });

      if (this.validationError) {
        Text(this.validationError)
          .fontSize(14)
          .fontColor('#FF0000')
          .margin({ bottom: 10 });
      }

      Button('Submit', { type: ButtonType.Capsule })
        .onClick(() => {
          this.handleSubmit();
        })
        .width('80%')
        .height(50)
        .margin({ bottom: 20 });

      Button('Reset', { type: ButtonType.Capsule })
        .onClick(() => {
          this.waterIntake = 0;
          this.updateProgress();
        })
        .width('80%')
        .height(50);
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center);
  }
}

