import { Column, Row, Grid, GridItem, Text, TextInput, Button, Slider, HorizontalAlign, SliderStyle } from '@ohos/arkui';
import promptAction from '@ohos/promptAction';

interface Message {
  content: string;
  isUser: boolean;
}

@Entry
@Component
struct MessagingInterface {
  @State messages: Array<Message> = [];
  @State newMessage: string = '';
  @State isOnline: boolean = true;
  @State fontSize: number = 16;

  build() {
    Column() {
      Row() {
        Text(this.isOnline ? 'Online' : 'Offline')
          .fontSize(16)
          .fontColor(this.isOnline ? '#00FF00' : '#FF0000')
          .margin({ top: 10, bottom: 10 });
      }

      Grid() {
        ForEach(this.messages, (message: Message, index: number) => {
          GridItem() {
            Column() {
              Text(message.content)
                .fontSize(this.fontSize)
                .padding(10)
                .backgroundColor(message.isUser ? '#DCF8C6' : '#ECECEC')
                .borderRadius(8)
                .width('80%')
                .align(message.isUser ? HorizontalAlign.End : HorizontalAlign.Start);
            }
            .width('100%')
            .margin({ top: 5, bottom: 5 });
          }
        })
      }
      .columnsTemplate('1fr')
      .rowsGap(10)
      .columnsGap(10)
      .padding(10)
      .layoutWeight(1);

      Row() {
        Slider({
          min: 12,
          max: 24,
          value: this.fontSize,
          step: 1,
          style: SliderStyle.OutSet
        })
          .width('70%')
          .onChange((value: number) => {
            this.fontSize = value;
          });

        Button('Toggle Status')
          .width('30%')
          .onClick(() => {
            this.isOnline = !this.isOnline;
          });
      }
      .width('100%')
      .padding(10);

      Row() {
        TextInput({ placeholder: 'Type a message...' })
          .width('80%')
          .height(40)
          .backgroundColor('#F5F5F5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.newMessage = value;
          });

        Button('Send')
          .width('20%')
          .height(40)
          .onClick(() => {
            if (this.newMessage.trim()) {
              this.messages.push({ content: this.newMessage, isUser: true });
              this.newMessage = '';
            } else {
              promptAction.showToast({
                message: 'Message cannot be empty',
                duration: 2000
              });
            }
          });
      }
      .width('100%')
      .padding(10);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

@Entry
@Component
struct Stopwatch {
  @State elapsedTime: number = 0
  @State isRunning: boolean = false
  private timerId: number = -1

  build() {
    Column() {
      Text(this.formatTime(this.elapsedTime))
        .fontSize(40)
        .margin(20)

      Row() {
        Button(this.isRunning ? 'Stop' : 'Start')
          .onClick(() => {
            if (this.isRunning) {
              clearInterval(this.timerId)
            } else {
              this.timerId = setInterval(() => {
                this.elapsedTime += 1
              }, 10)
            }
            this.isRunning = !this.isRunning
          })
          .margin(10)

        Button('Reset')
          .onClick(() => {
            clearInterval(this.timerId)
            this.elapsedTime = 0
            this.isRunning = false
          })
          .margin(10)
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }

  private formatTime(time: number): string {
    const minutes = Math.floor(time / 6000)
    const seconds = Math.floor((time % 6000) / 100)
    const centiseconds = time % 100
    return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}.${centiseconds.toString().padStart(2, '0')}`
  }
}

