                .fontSize(16)
                .padding(16)
            }
            .width('100%')
            .backgroundColor(Color.White)
            .borderRadius(8)
            .margin({ bottom: 10 })
          }
        })
      }
      .width('100%')
      .padding({ left: 16, right: 16 })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }

  @Builder FormTab() {
    Column() {
      Text('Form')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      TextInput({ placeholder: 'Enter your name' })
        .width('90%')
        .height(40)
        .margin({ bottom: 16 })
        .backgroundColor(Color.White)
        .borderRadius(8)

      TextInput({ placeholder: 'Enter your email' })
        .width('90%')
        .height(40)
        .margin({ bottom: 16 })
        .backgroundColor(Color.White)
        .borderRadius(8)

      Button('Submit')
        .width('90%')
        .height(40)
        .backgroundColor('#1698CE')
        .fontColor(Color.White)
        .borderRadius(8)
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }

  @Builder CanvasTab() {
    Column() {
      Text('Canvas')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      Canvas(this.context)
        .width('100%')
        .height(300)
        .backgroundColor('#ffffff')
        .onReady(() => {
          this.context = this.context
          this.draw()
        })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }

  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D()

  draw() {
    this.context.beginPath()
    this.context.arc(150, 150, 100, 0, 2 * Math.PI)
    this.context.strokeStyle = '#1698CE'
    this.context.lineWidth = 5
    this.context.stroke()
  }
}

@Entry
@Component
struct RecipeFormApp {
  @State recipeName: string = '';
  @State ingredients: string = '';
  @State steps: string[] = [];
  @State currentStep: string = '';
  @State isFormValid: boolean = false;

  validateForm() {
    this.isFormValid = this.recipeName.trim() !== '' && this.ingredients.trim() !== '' && this.steps.length > 0;
  }

  addStep() {
    if (this.currentStep.trim() !== '') {
      this.steps.push(this.currentStep);
      this.currentStep = '';
      this.validateForm();
    }
  }

  removeStep(index: number) {
    this.steps.splice(index, 1);
    this.validateForm();
  }

  submitForm() {
    if (this.isFormValid) {
      console.log('Recipe submitted:', {
        name: this.recipeName,
        ingredients: this.ingredients,
        steps: this.steps
      });
    }
  }

  build() {
    Column() {
      Stack() {
        Column() {
          Text('Recipe Name')
            .fontSize(18)
            .margin({ bottom: 8 });

          TextInput({ placeholder: 'Enter recipe name', text: this.recipeName })
            .width('100%')
            .onChange((value: string) => {
              this.recipeName = value;
              this.validateForm();
            })
            .margin({ bottom: 16 });

          Text('Ingredients')
            .fontSize(18)
            .margin({ bottom: 8 });

          TextInput({ placeholder: 'Enter ingredients (comma-separated)', text: this.ingredients })
            .width('100%')
            .onChange((value: string) => {
              this.ingredients = value;
              this.validateForm();
            })
            .margin({ bottom: 16 });

          Text('Steps')
            .fontSize(18)
            .margin({ bottom: 8 });

          TextInput({ placeholder: 'Enter a step', text: this.currentStep })
            .width('100%')
            .onChange((value: string) => {
              this.currentStep = value;
            })
            .margin({ bottom: 8 });

          Button('Add Step')
            .onClick(() => {
              this.addStep();
            })
            .margin({ bottom: 16 });

          if (this.steps.length > 0) {
            List() {
              ForEach(this.steps, (step: string, index: number) => {
                ListItem() {
                  Column() {
                    Text(step)
                      .fontSize(16)
                      .margin({ bottom: 8 });

                    Button('Remove')
                      .onClick(() => {
                        this.removeStep(index);
                      })
                      .margin({ bottom: 16 });
                  }
                }
              });
            }
          }

          Button('Submit Recipe', { type: ButtonType.Capsule })
            .onClick(() => {
              this.submitForm();
            })
            .enabled(this.isFormValid)
            .margin({ top: 16 });
        }
        .width('100%')
        .padding(16);
      }
      .width('100%')
      .height('100%');
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }
}

