import router from '@ohos.router';
import { Text, Button, Column, ScrollView } from '@ohos.arkui.node';

@Entry
@Component
struct CountdownTimer {
  @State private timeLeft: number = 60;
  @State private isRunning: boolean = false;
  private timerId: number = 0;

  aboutToDisappear() {
    if (this.timerId) {
      clearInterval(this.timerId);
    }
  }

  private startPauseTimer(): void {
    if (this.isRunning) {
      clearInterval(this.timerId);
      this.isRunning = false;
    } else {
      this.isRunning = true;
      this.timerId = setInterval(() => {
        if (this.timeLeft > 0) {
          this.timeLeft -= 1;
        } else {
          clearInterval(this.timerId);
          this.isRunning = false;
        }
      }, 1000);
    }
  }

  private resetTimer(): void {
    clearInterval(this.timerId);
    this.timeLeft = 60;
    this.isRunning = false;
  }

  private navigateToHome(): void {
    router.pushUrl({ url: 'pages/Home' });
  }

  build() {
    Column() {
      ScrollView() {
        Column() {
          Text(`${this.timeLeft}`)
            .fontSize(24)
            .margin({ bottom: 20 });

          Button(this.isRunning ? 'Pause' : 'Start')
            .onClick(() => this.startPauseTimer())
            .margin({ bottom: 10 });

          Button('Reset')
            .onClick(() => this.resetTimer())
            .margin({ bottom: 10 });

          Button('Navigate Home')
            .onClick(() => this.navigateToHome());
        }
        .width('100%')
        .justifyContent(FlexAlign.Center)
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

