import { Badge, Text, Column, Row } from '@ohos.arkui.advanced';
import { PanGesture } from '@ohos.arkui.advanced';

@Entry
@Component
struct SwipeTracker {
  @State swipeDirection: string = 'Swipe here';
  @State location: string = 'Location: Unknown';

  build() {
    Column() {
      Badge({
        count: 1,
        position: 'right'
      })
      .textColor('#FFFFFF')
      .backgroundColor('#FF0000')
      .fontSize(20)
      .fontWeight(700)
      {
        Text('Track Swipes')
      }

      Text(this.swipeDirection)
        .margin({ top: 20 })

      Text(this.location)
        .margin({ top: 10 })

      Row()
        .width('80%')
        .height(200)
        .backgroundColor('#CCCCCC')
        .margin({ top: 30 })
        .gesture(
          PanGesture()
            .onActionStart(() => {
            })
            .onActionUpdate(() => {
            })
            .onActionEnd((event: { offsetX: number, offsetY: number }) => {
              const xOffset = event.offsetX;
              const yOffset = event.offsetY;

              if (Math.abs(xOffset) > Math.abs(yOffset)) {
                this.swipeDirection = xOffset > 0 ? 'Swiped Right' : 'Swiped Left';
              } else {
                this.swipeDirection = yOffset > 0 ? 'Swiped Down' : 'Swiped Up';
              }

              const latitude = (Math.random() * 180 - 90).toFixed(4);
              const longitude = (Math.random() * 360 - 180).toFixed(4);
              this.location = `Location: ${latitude}, ${longitude}`;
            })
        )
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .alignItems('center')
  }
}

