@Entry
@Component
struct EventPlanner {
  @State sliderValue: number = 50;
  @State scaleValue: number = 1.0;
  @State minScale: number = 0.5;
  @State maxScale: number = 2.0;
  @State showMenu: boolean = false;

  build() {
    Column() {
      Text("Event Planner")
        .fontSize(24)
        .margin(20);

      Slider({
        value: this.sliderValue,
        min: 0,
        max: 100,
        style: SliderStyle.OutSet
      })
        .width('90%')
        .blockColor(0x009688)
        .trackColor(0xD8D8D8)
        .selectedColor(0x009688)
        .showSteps(true)
        .onChange((value: number) => {
          this.sliderValue = value;
        })
        .accessibilityDescription("Event time slider")
        .focusable(true);

      Image($r('app.media.icon'))
        .width(200)
        .height(200)
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .gesture(
          PinchGesture()
            .onActionStart(() => {
              console.info("Pinch gesture started");
            })
            .onActionUpdate((event: GestureEvent) => {
              let newScale = this.scaleValue * event.scale;
              if (newScale < this.minScale) {
                newScale = this.minScale;
              } else if (newScale > this.maxScale) {
                newScale = this.maxScale;
              }
              this.scaleValue = newScale;
            })
            .onActionEnd(() => {
              console.info("Pinch gesture ended");
            })
        );

      Button("Settings")
        .onClick(() => {
          this.showMenu = !this.showMenu;
        })
        .margin(20);

      if (this.showMenu) {
        Menu() {
          MenuItem({ content: "Option 1" })
            .onClick(() => {
              console.info("Option 1 selected");
            });
          MenuItem({ content: "Option 2" })
            .onClick(() => {
              console.info("Option 2 selected");
            });
        }
        .width(150)
        .height(100)
        .margin(10);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .padding(20);
  }
}

import { TextInput, Stack, Column, Text } from '@ohos.arkui.component';
import { Alignment } from '@ohos.arkui.directional';
import { 
  PanGesture, 
  TapGesture, 
  GestureGroup, 
  GestureMode, 
  PanDirection,
  PanGestureEvent 
} from '@ohos.arkui.directional';

@Entry
@Component
struct TVGestureInput {
  @State private tapCount: number = 0;
  @State private swipeDirection: string = 'Swipe here';
  @State private inputText: string = '';

  build() {
    Stack({ alignContent: Alignment.Center }) {
      Column() {
        TextInput({ placeholder: 'Enter text here' })
          .width('80%')
          .height(80)
          .onChange((value: string) => {
            this.inputText = value;
          });

        Text(`Tap Count: ${this.tapCount}`)
          .fontSize(30)
          .margin({ top: 20 });

        Text(`Swipe Direction: ${this.swipeDirection}`)
          .fontSize(30)
          .margin({ top: 10 });
      }
      .gesture(
        GestureGroup(GestureMode.Exclusive)
          .gesture(
            TapGesture()
              .onAction(() => {
                this.tapCount++;
              })
          )
          .gesture(
            PanGesture({ direction: PanDirection.Horizontal })
              .onActionUpdate((event: PanGestureEvent) => {
                if (event.offsetX > 50) {
                  this.swipeDirection = 'Right Swipe';
                } else if (event.offsetX < -50) {
                  this.swipeDirection = 'Left Swipe';
                }
              })
              .onActionEnd(() => {
                this.swipeDirection = 'Swipe here';
              })
          )
      )
      .focusable(true)
      .focusOnTouch(true)
      .focusStyle({
        borderWidth: 4,
        borderColor: '#FF0000'
      });
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5');
  }
}

import { Column, Row, Text, Button, List, ListItem, TextInput } from '@ohos.arkui';
import { Edge, HorizontalAlign, FlexAlign, FontWeight, Color } from '@ohos.arkui';

interface Exercise {
  name: string;
  sets: number;
  reps: number;
}

@Entry
@Component
struct WorkoutPlanner {
  @State exercises: Exercise[] = [];
  @State exerciseName: string = '';
  @State sets: string = '';
  @State reps: string = '';

  addExercise(): void {
    if (this.exerciseName.trim() === '') {
      return;
    }
    const setsNum = parseInt(this.sets);
    const repsNum = parseInt(this.reps);
    if (isNaN(setsNum) || isNaN(repsNum)) {
      return;
    }
    const newExercise: Exercise = {
      name: this.exerciseName,
      sets: setsNum,
      reps: repsNum,
    };
    this.exercises = [...this.exercises, newExercise];
    this.exerciseName = '';
    this.sets = '';
    this.reps = '';
  }

  deleteExercise(index: number): void {
    this.exercises.splice(index, 1);
    this.exercises = [...this.exercises];
  }

  build(): void {
    Column() {
      Text('Workout Planner')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Column() {
        TextInput({ placeholder: 'Exercise Name' })
          .width('90%')
          .height(40)
          .margin({ bottom: 10 })
          .onChange((value: string) => {
            this.exerciseName = value;
          });

        Row() {
          TextInput({ placeholder: 'Sets' })
            .width('45%')
            .height(40)
            .margin({ right: 10 })
            .onChange((value: string) => {
              this.sets = value;
            });

          TextInput({ placeholder: 'Reps' })
            .width('45%')
            .height(40)
            .onChange((value: string) => {
              this.reps = value;
            });
        }
        .width('90%')
        .margin({ bottom: 20 });

        Button('Add Exercise')
          .width('90%')
          .height(40)
          .onClick(() => {
            this.addExercise();
          });
      }
      .width('100%')
      .alignItems(HorizontalAlign.Center);

      List({ space: 10 }) {
        ForEach(this.exercises, (exercise: Exercise, index: number) => {
          ListItem() {
            Row() {
              Column() {
                Text(exercise.name)
                  .fontSize(18)
                  .fontWeight(FontWeight.Bold);
                Text(`Sets: ${exercise.sets}, Reps: ${exercise.reps}`)
                  .fontSize(14);
              }
              .width('80%');

              Button('Delete')
                .width('20%')
                .onClick(() => {
                  this.deleteExercise(index);
                });
            }
            .width('100%')
            .justifyContent(FlexAlign.SpaceBetween);
          }
          .swipeAction({
            edge: Edge.End,
            builder: (): Button => {
              return Button('Delete')
                .width(80)
                .height('100%')
                .backgroundColor('#FF0000')
                .fontColor('#FFFFFF')
                .onClick(() => {
                  this.deleteExercise(index);
                });
            },
          });
        });
      }
      .width('100%')
      .layoutWeight(1);
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

@Entry
@Component
struct FileManagerForm {
  @State fileName: string = '';
  @State fileSize: string = '';
  @State isFileValid: boolean = false;
  @State uploadProgress: number = 0;
  @State isUploading: boolean = false;
  @State errorMessage: string = '';

  validateFile(): boolean {
    if (!this.fileName) {
      this.errorMessage = 'File name is required';
      return false;
    }
    if (!this.fileSize || isNaN(Number(this.fileSize))) {
      this.errorMessage = 'File size must be a number';
      return false;
    }
    this.errorMessage = '';
    return true;
  }

  startUpload() {
    if (!this.validateFile()) return;
    this.isUploading = true;
    this.uploadProgress = 0;
    const interval = setInterval(() => {
      if (this.uploadProgress < 100) {
        this.uploadProgress += 10;
      } else {
        clearInterval(interval);
        this.isUploading = false;
      }
    }, 500);
  }

  build() {
    Column({ space: 20 }) {
      TextInput({ placeholder: 'File Name' })
        .width('100%')
        .onChange((value: string) => {
          this.fileName = value;
        });

      TextInput({ placeholder: 'File Size (KB)' })
        .width('100%')
        .onChange((value: string) => {
          this.fileSize = value;
        });

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(12)
          .fontColor(Color.Red)
          .margin({ top: 5 });
      }

      if (this.isUploading) {
        Progress({
          value: this.uploadProgress,
          total: 100,
          type: ProgressType.Linear
        })
          .width('80%')
          .height(20)
          .color(Color.Blue);
      }

      Button('Upload File')
        .enabled(!this.isUploading)
        .onClick(() => this.startUpload())
        .width('50%')
        .margin({ top: 20 });
    }
    .padding(20)
    .width('100%');
  }
}

import Progress from '@ohos.arkui.advanced.Progress';
import Canvas, { CanvasRenderingContext2D } from '@ohos.graphics.canvas';
import { AppStorage } from '@ohos.data.appStorage';

@Entry
@Component
struct MovieTicketBooking {
  @State private seats: boolean[][] = Array(5).fill(false).map(() => Array(5).fill(false));
  @State private progress: number = 0;
  private context: CanvasRenderingContext2D | null = null;

  aboutToAppear(): void {
    const storedSeats: boolean[][] | undefined = AppStorage.get<boolean[][]>('selectedSeats');
    if (storedSeats) {
      this.seats = storedSeats;
      this.updateProgress();
    }
  }

  build() {
    Column() {
      Progress({ value: this.progress, total: 100 })
        .strokeWidth(10)
        .color('#0000ff')
        .margin(20);

      Canvas()
        .width(300)
        .height(300)
        .onReady((canvas: CanvasRenderingContext2D) => {
          this.context = canvas;
          this.drawSeats();
        })
        .onTouch((event: TouchEvent) => {
          this.handleSeatSelection(event);
        });

      Button('Confirm Booking')
        .onClick(() => {
          AppStorage.set('selectedSeats', this.seats);
        })
        .margin(20);
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }

  private drawSeats() {
    if (!this.context) return;

    this.context.clearRect(0, 0, 300, 300);
    for (let row = 0; row < 5; row++) {
      for (let col = 0; col < 5; col++) {
        this.context.fillStyle = this.seats[row][col] ? '#0000ff' : '#333';
        this.context.fillRect(col * 40 + 10, row * 40 + 10, 30, 30);
      }
    }
  }

  private handleSeatSelection(event: TouchEvent) {
    const touch = event.touches[0];
    const x = touch.x;
    const y = touch.y;

    for (let row = 0; row < 5; row++) {
      for (let col = 0; col < 5; col++) {
        const seatX = col * 40 + 10;
        const seatY = row * 40 + 10;
        if (x >= seatX && x <= seatX + 30 && y >= seatY && y <= seatY + 30) {
          this.seats[row][col] = !this.seats[row][col];
          this.updateProgress();
          this.drawSeats();
          return;
        }
      }
    }
  }

  private updateProgress() {
    let selected = 0;
    for (let row = 0; row < 5; row++) {
      for (let col = 0; col < 5; col++) {
        if (this.seats[row][col]) selected++;
      }
    }
    this.progress = selected * 4;
  }
}

