@Entry
@Component
struct CountdownTimer {
  @State timeLeft: number = 0;
  @State inputTime: string = '';
  @State isRunning: boolean = false;
  @State isValidInput: boolean = true;
  private timerId: number = -1;

  private validateInput(input: string): boolean {
    const num = parseInt(input, 10);
    return !isNaN(num) && num > 0;
  }

  private startTimer() {
    if (!this.isRunning && this.validateInput(this.inputTime)) {
      this.timeLeft = parseInt(this.inputTime, 10);
      this.isRunning = true;
      this.timerId = setInterval(() => {
        if (this.timeLeft > 0) {
          this.timeLeft--;
        } else {
          this.stopTimer();
        }
      }, 1000);
    } else {
      this.isValidInput = false;
    }
  }

  private stopTimer() {
    this.isRunning = false;
    clearInterval(this.timerId);
  }

  private resetTimer() {
    this.stopTimer();
    this.timeLeft = 0;
    this.inputTime = '';
    this.isValidInput = true;
  }

  build() {
    Column({ space: 10 }) {
      TextInput({ placeholder: 'Enter time in seconds' })
        .width('80%')
        .height(40)
        .margin(10)
        .onChange((value: string) => {
          this.inputTime = value;
          this.isValidInput = this.validateInput(value);
        });

      if (!this.isValidInput) {
        Text('Please enter a valid positive number')
          .fontSize(14)
          .fontColor(Color.Red)
          .margin(5);
      }

      Text(`Time Left: ${this.timeLeft}s`)
        .fontSize(24)
        .margin(10);

      Row({ space: 20 }) {
        Button('Start')
          .onClick(() => {
            this.startTimer();
          })
          .backgroundColor(Color.Green)
          .fontColor(Color.White)
          .padding(10)
          .margin(5);

        Button('Stop')
          .onClick(() => {
            this.stopTimer();
          })
          .backgroundColor(Color.Red)
          .fontColor(Color.White)
          .padding(10)
          .margin(5);

        Button('Reset')
          .onClick(() => {
            this.resetTimer();
          })
          .backgroundColor(Color.Blue)
          .fontColor(Color.White)
          .padding(10)
          .margin(5);
      }
      .justifyContent(FlexAlign.Center)
      .width('80%');
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }
}

