@Entry
@Component
struct FileManagerApp {
  @State private files: string[] = ["Document.pdf", "Image.jpg", "Video.mp4", "Music.mp3", "Archive.zip"]
  @State private currentIndex: number = 0
  @State private showActionSheet: boolean = false
  @State private actionSheetTitle: string = ""

  private showFileActions(file: string) {
    this.actionSheetTitle = `Actions for ${file}`
    this.showActionSheet = true
  }

  private handleSwipe(direction: string) {
    if (direction === "left" && this.currentIndex < this.files.length - 1) {
      this.currentIndex++
    } else if (direction === "right" && this.currentIndex > 0) {
      this.currentIndex--
    }
  }

  build() {
    Column() {
      // File list with swipe gestures
      Stack() {
        ForEach(this.files, (file: string) => {
          Row() {
            Image($r('app.media.app_icon'))
              .width(40)
              .height(40)
              .margin({ right: 10 })
            Text(file)
              .fontSize(16)
          }
          .width('100%')
          .padding(10)
          .backgroundColor('#FFFFFF')
          .borderRadius(5)
          .margin({ bottom: 5 })
          .gesture(
            GestureGroup(
              GestureMode.Parallel,
              PanGesture({ direction: PanDirection.Horizontal })
                .onActionEnd((event: GestureEvent) => {
                  if (event.offsetX > 0) {
                    this.handleSwipe("right")
                  } else {
                    this.handleSwipe("left")
                  }
                }),
              LongPressGesture()
                .onAction(() => {
                  this.showFileActions(file)
                })
            )
          )
        })
      }
      .width('100%')
      .height('70%')

      // Stepper for navigation
      Row() {
        Button("Previous")
          .onClick(() => {
            if (this.currentIndex > 0) {
              this.currentIndex--
            }
          })
          .enabled(this.currentIndex > 0)
          .margin({ right: 10 })

        Text(`File ${this.currentIndex + 1} of ${this.files.length}`)
          .fontSize(14)

        Button("Next")
          .onClick(() => {
            if (this.currentIndex < this.files.length - 1) {
              this.currentIndex++
            }
          })
          .enabled(this.currentIndex < this.files.length - 1)
          .margin({ left: 10 })
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .margin({ top: 20 })

      // ActionSheet
      if (this.showActionSheet) {
        Column() {
          Text(this.actionSheetTitle)
            .fontSize(18)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 })

          Button("Delete")
            .onClick(() => {
              this.files.splice(this.currentIndex, 1)
              this.showActionSheet = false
            })
            .width('100%')
            .margin({ bottom: 10 })

          Button("Rename")
            .onClick(() => {
              this.showActionSheet = false
            })
            .width('100%')
            .margin({ bottom: 10 })

          Button("Cancel")
            .onClick(() => {
              this.showActionSheet = false
            })
            .width('100%')
        }
        .width('80%')
        .padding(20)
        .backgroundColor('#FFFFFF')
        .borderRadius(10)
        .position({ x: '10%', y: '20%' })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5')
  }
}

