import AppStorage from '@ohos.data.storage'
import window from '@ohos.window'

@Entry
@Component
struct Calculator {
  @State result: string = '0'
  @State currentInput: string = ''
  @State operator: string = ''
  @State selectedOperation: string = '+'
  @State refreshKey: number = 0

  aboutToAppear() {
    let context = getContext(this)
    window.getLastWindow(context, (err, windowObj) => {
      if (err) {
        console.error('Failed to get window object')
        return
      }
      windowObj.setPreferredOrientation(window.Orientation.LANDSCAPE)
    })
  }

  build() {
    Row() {
      Column() {
        Text(this.result)
          .fontSize(40)
          .width('100%')
          .textAlign(TextAlign.End)
          .margin({ bottom: 20 })
          .accessibilityDescription('Result: ' + this.result)

        Row() {
          Radio({ group: 'operation', value: '+' })
            .checked(this.selectedOperation === '+')
            .onChange((isChecked: boolean) => {
              if (isChecked) this.selectedOperation = '+'
            })
            .accessibilityDescription('Addition operation')
          Radio({ group: 'operation', value: '-' })
            .checked(this.selectedOperation === '-')
            .onChange((isChecked: boolean) => {
              if (isChecked) this.selectedOperation = '-'
            })
            .accessibilityDescription('Subtraction operation')
          Radio({ group: 'operation', value: '*' })
            .checked(this.selectedOperation === '*')
            .onChange((isChecked: boolean) => {
              if (isChecked) this.selectedOperation = '*'
            })
            .accessibilityDescription('Multiplication operation')
          Radio({ group: 'operation', value: '/' })
            .checked(this.selectedOperation === '/')
            .onChange((isChecked: boolean) => {
              if (isChecked) this.selectedOperation = '/'
            })
            .accessibilityDescription('Division operation')
        }
        .margin({ bottom: 20 })

        Grid() {
          ForEach(['7', '8', '9', '4', '5', '6', '1', '2', '3', 'C', '0', '='], (button: string) => {
            GridItem() {
              Button(button)
                .width('100%')
                .height(60)
                .onClick(() => this.handleButtonPress(button))
                .accessibilityDescription('Button: ' + button)
            }
          })
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsTemplate('1fr 1fr 1fr 1fr')
        .width('100%')
        .height(300)
      }
      .width('100%')
      .padding(20)
    }
    .width('100%')
    .height('100%')
  }

  handleButtonPress(button: string) {
    if (button >= '0' && button <= '9') {
      this.currentInput += button
      this.result = this.currentInput
    } else if (button === 'C') {
      this.result = '0'
      this.currentInput = ''
      this.operator = ''
    } else if (button === '=') {
      this.calculateResult()
    }
  }

  calculateResult() {
    const num1 = parseFloat(this.result)
    const num2 = parseFloat(this.currentInput)
    let calculatedResult = 0

    switch (this.selectedOperation) {
      case '+':
        calculatedResult = num1 + num2
        break
      case '-':
        calculatedResult = num1 - num2
        break
      case '*':
        calculatedResult = num1 * num2
        break
      case '/':
        calculatedResult = num1 / num2
        break
    }

    this.result = calculatedResult.toString()
    this.currentInput = ''
    this.operator = ''
  }
}

