@Entry
@Component
struct CustomToggle {
  @State isOn: boolean = false;
  @State offsetX: number = 0;
  @State selectedTime: Date = new Date();

  build() {
    Column() {
      // Custom Toggle Component
      Row() {
        Text(this.isOn ? 'ON' : 'OFF')
          .fontSize(20)
          .fontColor(this.isOn ? Color.Green : Color.Red)
          .margin({ right: 10 })

        Row()
          .width(60)
          .height(30)
          .backgroundColor(this.isOn ? Color.Green : Color.Red)
          .borderRadius(15)
          .gesture(
            PanGesture({ direction: PanDirection.Horizontal })
              .onActionUpdate((event: GestureEvent) => {
                this.offsetX = event.offsetX;
              })
              .onActionEnd(() => {
                if (this.offsetX > 20) {
                  this.isOn = true;
                } else if (this.offsetX < -20) {
                  this.isOn = false;
                }
                animateTo({ duration: 300 }, () => {
                  this.offsetX = 0;
                });
              })
          )
          .transform({ translate: { x: this.offsetX } })
          .animation({ duration: 300 })
      }
      .justifyContent(FlexAlign.Center)
      .alignItems(VerticalAlign.Center)
      .margin({ bottom: 20 })

      // TimePicker Component
      TimePicker({ selected: this.selectedTime })
        .onChange((value: TimePickerResult) => {
          this.selectedTime = new Date(0, 0, 0, value.hour, value.minute);
        })
        .margin({ bottom: 20 })

      // Display Selected Time
      Text(`Selected Time: ${this.selectedTime.getHours()}:${this.selectedTime.getMinutes()}`)
        .fontSize(18)
        .fontColor(Color.Black)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

