interface Message {
  text: string;
  sender: string;
  timestamp: string;
}

@Entry
@Component
struct MessagingApp {
  @State messages: Array<Message> = [
    { text: 'Hello!', sender: 'User', timestamp: '10:00 AM' },
    { text: 'Hi there!', sender: 'Other', timestamp: '10:01 AM' },
    { text: 'How are you?', sender: 'User', timestamp: '10:02 AM' },
    { text: 'I am good, thanks!', sender: 'Other', timestamp: '10:03 AM' }
  ];
  @State newMessage: string = '';
  @State filter: string = 'All';

  build() {
    Column() {
      Row() {
        Button('All')
          .width('33%')
          .height(40)
          .backgroundColor(this.filter === 'All' ? '#007AFF' : '#ECECEC')
          .onClick(() => {
            this.filter = 'All';
          });
        Button('User')
          .width('33%')
          .height(40)
          .backgroundColor(this.filter === 'User' ? '#007AFF' : '#ECECEC')
          .onClick(() => {
            this.filter = 'User';
          });
        Button('Other')
          .width('33%')
          .height(40)
          .backgroundColor(this.filter === 'Other' ? '#007AFF' : '#ECECEC')
          .onClick(() => {
            this.filter = 'Other';
          });
      }
      .width('100%')
      .margin({ bottom: 10 });

      List({ space: 10 }) {
        ForEach(
          this.messages.filter((msg) => this.filter === 'All' || msg.sender === this.filter),
          (message: Message) => {
            ListItem() {
              Stack() {
                Column() {
                  Text(message.text)
                    .fontSize(16)
                    .padding(10)
                    .backgroundColor(message.sender === 'User' ? '#DCF8C6' : '#ECECEC')
                    .borderRadius(10);
                  Text(message.timestamp)
                    .fontSize(12)
                    .fontColor('#666666')
                    .margin({ top: 5 });
                }
                .alignItems(message.sender === 'User' ? HorizontalAlign.End : HorizontalAlign.Start);
              }
            }
          }
        );
      }
      .layoutWeight(1)
      .width('100%')
      .padding(10);

      Row() {
        TextInput({ placeholder: 'Type a message...' })
          .width('80%')
          .height(40)
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.newMessage = value;
          });

        Button('Send')
          .width('20%')
          .height(40)
          .fontSize(16)
          .backgroundColor('#007AFF')
          .onClick(() => {
            if (this.newMessage.trim()) {
              const timestamp = new Date().toLocaleTimeString();
              this.messages.push({ text: this.newMessage, sender: 'User', timestamp: timestamp });
              this.newMessage = '';
            } else {
              promptAction.showToast({
                message: 'Message cannot be empty',
              });
            }
          });
      }
      .width('100%')
      .padding(10);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

