import { Text, Row, Column, Button, Progress } from '@ohos.arkui.UIContext';
import { State, Color, BorderStyle, FlexAlign } from '@ohos.arkui.base';
import { Animator } from '@ohos.arkui.animation';

@Entry
@Component
struct MarqueeComponent {
  @State private marqueePos: number = 0;
  @State private isPlaying: boolean = false;
  @State private speed: number = 50;
  private text: string = "Your scrolling text here";
  private animator: Animator | null = null;

  private startAnimation() {
    if (this.animator) {
      this.animator.stop();
    }

    this.isPlaying = true;
    this.animator = new Animator({
      duration: 10000 / this.speed,
      iterations: Infinity,
      onUpdate: (progress: number) => {
        this.marqueePos = -progress * 500;
        if (this.marqueePos <= -500) {
          this.marqueePos = 0;
        }
      }
    });
    this.animator.start();
  }

  private stopAnimation() {
    if (this.animator) {
      this.animator.stop();
    }
    this.isPlaying = false;
  }

  private updateSpeed(newSpeed: number) {
    this.speed = newSpeed;
    if (this.isPlaying) {
      this.stopAnimation();
      this.startAnimation();
    }
  }

  build() {
    Column() {
      Row() {
        Text(this.text)
          .fontSize(24)
          .fontColor(Color.Black)
          .translate({ x: this.marqueePos })
          .width('80%')
          .height(50)
          .backgroundColor(Color.White)
          .border({
            width: 1,
            color: Color.Gray,
            style: BorderStyle.Solid
          })
          .margin(10)
          .padding(10)
      }
      .width('100%')
      .height(100)
      .justifyContent(FlexAlign.Center)

      Row() {
        Button(this.isPlaying ? 'Stop' : 'Start')
          .onClick(() => {
            if (this.isPlaying) {
              this.stopAnimation();
            } else {
              this.startAnimation();
            }
          })
          .margin(10)

        Progress({
          value: this.speed,
          total: 100
          })
          .onChange((value: number) => {
            this.updateSpeed(value);
          })
          .width('60%')
          .margin(10)
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
    }
    .width('100%')
    .height('100%')
    .padding(10)
  }
}

