interface Document {
  id: number;
  title: string;
  content: string;
}

@Entry
@Component
struct ExpenseTracker {
  @State transactions: Transaction[] = [];
  @State newAmount: string = '';
  @State newCategory: string = '';
  @State newDescription: string = '';
  @State transactionType: 'income' | 'expense' = 'expense';
  @State currentDocumentIndex: number = 0;
  @State documents: Document[] = [
    { id: 1, title: 'Document 1', content: 'Sample content for Document 1' },
    { id: 2, title: 'Document 2', content: 'Sample content for Document 2' },
    { id: 3, title: 'Document 3', content: 'Sample content for Document 3' }
  ];

  calculateBalance(): number {
    return this.transactions.reduce((total, t) => {
      return total + (t.type === 'income' ? t.amount : -t.amount);
    }, 0);
  }

  addTransaction() {
    if (this.newAmount && this.newCategory) {
      this.transactions.push({
        type: this.transactionType,
        amount: parseFloat(this.newAmount),
        category: this.newCategory,
        description: this.newDescription,
        date: new Date().toISOString()
      });
      this.newAmount = '';
      this.newCategory = '';
      this.newDescription = '';
    }
  }

  nextDocument() {
    if (this.currentDocumentIndex < this.documents.length - 1) {
      this.currentDocumentIndex++;
    }
  }

  prevDocument() {
    if (this.currentDocumentIndex > 0) {
      this.currentDocumentIndex--;
    }
  }

  build() {
    Row() {
      Column({ space: 20 }) {
        Text(`Balance: $${this.calculateBalance().toFixed(2)}`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 });

        Row() {
          Radio({ value: 'expense', group: 'type' })
            .checked(this.transactionType === 'expense')
            .onChange((isChecked: boolean) => {
              if (isChecked) this.transactionType = 'expense';
            });
          Text('Expense');

          Radio({ value: 'income', group: 'type' })
            .checked(this.transactionType === 'income')
            .onChange((isChecked: boolean) => {
              if (isChecked) this.transactionType = 'income';
            });
          Text('Income');
        }
        .margin({ bottom: 10 });

        TextInput({ placeholder: 'Amount', text: this.newAmount })
          .type(InputType.Number)
          .onChange((value: string) => {
            this.newAmount = value;
          });

        TextInput({ placeholder: 'Category', text: this.newCategory })
          .onChange((value: string) => {
            this.newCategory = value;
          });

        TextInput({ placeholder: 'Description', text: this.newDescription })
          .onChange((value: string) => {
            this.newDescription = value;
          });

        Button('Add Transaction')
          .onClick(() => {
            this.addTransaction();
          });

        List() {
          ForEach(this.transactions, (transaction: Transaction) => {
            ListItem() {
              Row() {
                Column() {
                  Text(transaction.category)
                    .fontSize(18)
                    .fontWeight(FontWeight.Bold);
                  Text(transaction.description)
                    .fontSize(14)
                    .fontColor(Color.Gray);
                }
                Text(`${transaction.type === 'income' ? '+' : '-'}$${transaction.amount.toFixed(2)}`)
                  .fontSize(18)
                  .fontColor(transaction.type === 'income' ? '#4CAF50' : '#F44336');
              }
              .justifyContent(FlexAlign.SpaceBetween)
              .width('100%')
              .padding(10);
            }
          });
        }
        .width('100%');
      }
      .width('50%')
      .padding(20);

      Column({ space: 20 }) {
        Swiper() {
          ForEach(this.documents, (document: Document) => {
            Column() {
              Text(document.content)
                .fontSize(16)
                .margin(10);
            }
            .width('100%')
            .height(300)
            .backgroundColor('#f0f0f0')
            .borderRadius(5);
          });
        }
        .indicator(false)
        .loop(false)
        .width('100%')
        .height(300);

        Row() {
          Button('Previous')
            .onClick(() => {
              this.prevDocument();
            });
          Text(this.documents[this.currentDocumentIndex].title)
            .fontSize(18)
            .margin({ left: 10, right: 10 });
          Button('Next')
            .onClick(() => {
              this.nextDocument();
            });
        }
        .justifyContent(FlexAlign.Center)
        .width('100%');
      }
      .width('50%')
      .padding(20);
    }
    .width('100%')
    .height('100%');
  }
}

