@Entry
@Component
struct BottomSheetApp {
  @State isBottomSheetVisible: boolean = false;
  @State selectedDate: Date = new Date();
  @State searchText: string = '';
  @State items: string[] = ['Apple', 'Banana', 'Orange', 'Grapes', 'Mango'];

  filteredItems(): string[] {
