@Entry
@Component
struct RatingAuthApp {
  @State rating: number = 0;
  @State authMessage: string = '';

  build() {
    Column() {
      Text('Rate Us')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row() {
        ForEach([1, 2, 3, 4, 5], (index: number) => {
          Image(this.rating >= index ? $r('app.media.star_filled') : $r('app.media.star_empty'))
            .width(40)
            .height(40)
            .margin(8)
            .onClick(() => {
              this.rating = index;
            });
        });
