@Entry
@Component
struct DocumentScannerApp {
  @State selectedMode: string = 'Scan'
  @State zoomLevel: number = 1.0
  @State documentImage: Resource = $r('app.media.app_icon')
  @State rotationAngle: number = 0

  private modes: string[] = ['Scan', 'Edit', 'Save']

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.End }) {
        ForEach(this.modes, (mode: string) => {
          TabContent() {
            Column() {
              Image(this.documentImage)
                .width('90%')
                .height(400)
                .rotate({ x: 0, y: 0, z: 1, angle: this.rotationAngle })
                .scale({ x: this.zoomLevel, y: this.zoomLevel })
                .gesture(
                  RotationGesture()
                    .onActionStart(() => {
                      console.info('Pinch-to-zoom started')
                    })
                    .onActionUpdate((event: RotationGestureEvent) => {
                      this.zoomLevel += event.angle * 0.01
                      if (this.zoomLevel < 0.5) this.zoomLevel = 0.5
                      if (this.zoomLevel > 3.0) this.zoomLevel = 3.0
                      console.info(`Zoom level updated to: ${this.zoomLevel}`)
                    })
                    .onActionEnd(() => {
                      console.info('Pinch-to-zoom ended')
                    })
                )

              Text(`Mode: ${this.selectedMode}`)
                .fontSize(18)
                .margin(10)

              Text(`Zoom: ${this.zoomLevel.toFixed(2)}x`)
                .fontSize(18)
                .margin(10)
            }
          }.tabBar(mode)
        })
      }
      .onChange((index: number) => {
        this.selectedMode = this.modes[index]
      })
      .margin(20)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

