  }

  @Builder TimerScreen() {
    Column() {
      Text(`Traveling to: ${this.selectedDestination}`)
        .fontSize(24)
        .margin(16);
      Text(`Time Elapsed: ${this.timerCount} seconds`)
        .fontSize(20)
        .margin(16);
      Button(this.timerRunning ? 'Stop Timer' : 'Start Timer')
        .onClick(() => {
          if (this.timerRunning) {
            this.stopTimer();
          } else {
            this.startTimer();
          }
        })
        .width(200)
        .margin(16);
      Button('Back to Destinations')
        .onClick(() => {
          this.selectedDestination = '';
          this.stopTimer();
          this.timerCount = 0;
        })
        .width(200)
        .margin(16);
    }
    .width('100%')
    .height('100%');
  }

  private startTimer() {
    this.timerRunning = true;
    this.timerId = setInterval(() => {
      this.timerCount++;
    }, 1000);
  }

  private stopTimer() {
    if (this.timerId !== null) {
      clearInterval(this.timerId);
      this.timerId = null;
    }
    this.timerRunning = false;
  }
}

import fs from '@ohos.file.fs';
import cryptoFramework from '@ohos.security.cryptoFramework';
import { Divider, Stepper, Text, TextInput, Button, Row, Column } from '@ohos.arkui.js';

@Entry
@Component
struct FitnessTracker {
  @State fitnessData: string = '';
  @State encryptedData: string = '';
  @State decryptedData: string = '';
  @State encryptionLevel: number = 1;
  @State filePath: string = 'fitness_data.txt';

  private stringToUint8Array(str: string): Uint8Array {
    const array = new Uint8Array(str.length);
    for (let i = 0; i < str.length; i++) {
      array[i] = str.charCodeAt(i);
    }
    return array;
  }

  private uint8ArrayToString(array: Uint8Array): string {
    let str = '';
    for (let i = 0; i < array.length; i++) {
      str += String.fromCharCode(array[i]);
    }
    return str;
  }

  private async generateKey(level: number): Promise<cryptoFramework.SymKey> {
    const key = `secret_key_${level}`;
    const symKeyGenerator = cryptoFramework.createSymKeyGenerator('AES256');
    const keyBlob: cryptoFramework.DataBlob = { 
      data: this.stringToUint8Array(key) 
    };
    return await symKeyGenerator.convertKey(keyBlob);
  }

  private async encryptData(data: string): Promise<string> {
    try {
      const symKey = await this.generateKey(this.encryptionLevel);
      const cipher = cryptoFramework.createCipher('AES256|ECB|PKCS7');
      await cipher.init(cryptoFramework.CryptoMode.ENCRYPT_MODE, symKey, null);
      const input: cryptoFramework.DataBlob = { data: this.stringToUint8Array(data) };
      const output = await cipher.doFinal(input);
      return this.uint8ArrayToString(output.data);
    } catch (error) {
      console.error('Encryption failed:', error);
      return '';
    }
  }

  private async decryptData(data: string): Promise<string> {
    try {
      const symKey = await this.generateKey(this.encryptionLevel);
      const cipher = cryptoFramework.createCipher('AES256|ECB|PKCS7');
      await cipher.init(cryptoFramework.CryptoMode.DECRYPT_MODE, symKey, null);
      const input: cryptoFramework.DataBlob = { data: this.stringToUint8Array(data) };
      const output = await cipher.doFinal(input);
      return this.uint8ArrayToString(output.data);
    } catch (error) {
      console.error('Decryption failed:', error);
      return '';
    }
  }

  private async saveToFile(data: string): Promise<void> {
    try {
      const context = getContext(this);
      const fileDir = context.filesDir;
      const fullPath = `${fileDir}/${this.filePath}`;
      const file = await fs.open(fullPath, fs.OpenMode.READ_WRITE | fs.OpenMode.CREATE);
      await fs.write(file.fd, this.stringToUint8Array(data));
      await fs.close(file.fd);
    } catch (error) {
      console.error('File write failed:', error);
    }
  }

  private async readFromFile(): Promise<string> {
    try {
      const context = getContext(this);
      const fileDir = context.filesDir;
      const fullPath = `${fileDir}/${this.filePath}`;
      const file = await fs.open(fullPath, fs.OpenMode.READ_ONLY);
      const stat = await fs.stat(fullPath);
      const arrayBuffer = new ArrayBuffer(stat.size);
      await fs.read(file.fd, arrayBuffer);
      await fs.close(file.fd);
      return this.uint8ArrayToString(new Uint8Array(arrayBuffer));
    } catch (error) {
      console.error('File read failed:', error);
      return '';
    }
  }

  build() {
    Column() {
      Divider()
      Text('Fitness Data Input')
      TextInput({ placeholder: 'Enter fitness data' })
        .onChange((value: string) => {
          this.fitnessData = value;
        })

      Divider()
      Text('Encryption Level')
      Stepper({
        index: this.encryptionLevel
      })
      .min(1)
      .max(3)
      .step(1)
      .onChange((value: number) => {
        this.encryptionLevel = value;
      })

      Divider()
      Row() {
        Button('Encrypt & Save')
          .onClick(async () => {
            this.encryptedData = await this.encryptData(this.fitnessData);
            await this.saveToFile(this.encryptedData);
          })
        Button('Decrypt & Display')
          .onClick(async () => {
            const data = await this.readFromFile();
            this.decryptedData = await this.decryptData(data);
          })
      }

      Divider()
      Text('Encrypted Data:')
      Text(this.encryptedData)
      Divider()
      Text('Decrypted Data:')
      Text(this.decryptedData)
    }
    .padding(16)
  }
}

interface Email {
