import { Tabs, TabContent, TabsController } from '@ohos.arkui.component';
import { List, ListItem, SwipeAction } from '@ohos.arkui.component';
import { Column, Row, Stack, Text, Button, Blank } from '@ohos.arkui.component';
import { Alignment, BarPosition, BarMode, TextAlign } from '@ohos.arkui.component';
import { Circle, Line } from '@ohos.arkui.component';
import { Toggle, ToggleType } from '@ohos.arkui.component';
import { Color } from '@ohos.arkui.component';
import systemDateTime from '@ohos.systemDateTime';

interface Alarm {
  id: number;
  time: string;
  active: boolean;
}

@Entry
@Component
struct AlarmClockApp {
  @State currentTime: Date = new Date(systemDateTime.getTime());
  @State alarms: Alarm[] = [
    { id: 1, time: "08:00", active: true },
    { id: 2, time: "12:30", active: false },
    { id: 3, time: "18:45", active: true }
  ];
  private timerId: number = 0;
  private tabsController: TabsController = new TabsController();

  aboutToAppear() {
    this.timerId = setInterval(() => {
      this.currentTime = new Date(systemDateTime.getTime());
    }, 1000);
  }

  aboutToDisappear() {
    if (this.timerId !== 0) {
      clearInterval(this.timerId);
    }
  }

  @Builder
  ClockHand(rotation: number, length: number, width: number, color: Color) {
    Line()
      .startPoint([150, 150])
      .endPoint([150 + length * Math.sin(rotation), 150 - length * Math.cos(rotation)])
      .stroke(color)
      .strokeWidth(width);
  }

  @Builder
  AlarmItem(alarm: Alarm) {
    ListItem() {
      Row() {
        Text(alarm.time)
          .fontSize(18);
        Blank();
        Toggle({ type: ToggleType.Checkbox, isOn: alarm.active })
          .onChange((isOn: boolean) => {
            this.alarms = this.alarms.map(item => 
              item.id === alarm.id ? {...item, active: isOn} : item
            );
          });
      }
      .width('100%')
      .padding(16);
    }
    .swipeAction({ end: this.DeleteAction(alarm.id) });
  }

  @Builder
  DeleteAction(id: number) {
    Button('Delete')
      .backgroundColor(Color.Red)
      .onClick(() => {
        this.alarms = this.alarms.filter(alarm => alarm.id !== id);
      });
  }

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.Start, controller: this.tabsController }) {
        TabContent() {
          Column() {
            Stack({ alignContent: Alignment.Center }) {
              Circle()
                .width(350)
                .height(350)
                .fill(Color.White)
                .stroke(Color.Black)
                .strokeWidth(10);

              ForEach(
                Array.from<number, number>({ length: 12 }, (_, index: number) => index),
                (index: number) => {
                  Line()
                    .startPoint([150 + 140 * Math.sin(index * Math.PI / 6), 150 - 140 * Math.cos(index * Math.PI / 6)])
                    .endPoint([150 + 130 * Math.sin(index * Math.PI / 6), 150 - 130 * Math.cos(index * Math.PI / 6)])
                    .stroke(Color.Black)
                    .strokeWidth(3);
                },
                (index: number) => index.toString()
              );

              this.ClockHand(this.currentTime.getHours() * Math.PI / 6 + this.currentTime.getMinutes() * Math.PI / 360, 80, 6, Color.Black);
              this.ClockHand(this.currentTime.getMinutes() * Math.PI / 30, 110, 4, Color.Black);
              this.ClockHand(this.currentTime.getSeconds() * Math.PI / 30, 130, 2, Color.Gray);
            }
            .width(300)
            .height(300);

            Text(`${this.currentTime.toTimeString().split(' ')[0]}`)
              .fontSize(24)
              .fontColor(Color.Black)
              .margin({ top: 20 })
              .textAlign(TextAlign.Center);
          }
        }
        .tabBar('Clock');

        TabContent() {
          List() {
            ForEach(this.alarms, (alarm: Alarm) => {
              this.AlarmItem(alarm);
            });
          }
          .height('100%');
        }
        .tabBar('Alarms');
      }
      .barMode(BarMode.Fixed)
      .barWidth('100%')
      .barHeight(50)
      .animationDuration(400);
    }
    .width('100%')
    .height('100%');
  }
}

@Entry
@Component
struct ComicReaderApp {
  @State private encryptedPages: string[] = ["comic_page_1", "comic_page_2", "comic_page_3"];
  @State private decryptedPages: string[] = [];
  @State private currentPage: number = 0;

  decryptPage(pageIndex: number): void {
    if (this.decryptedPages[pageIndex]) return;

    const encryptedPage = this.encryptedPages[pageIndex];
    const decryptedPage = this.simpleDecrypt(encryptedPage);
    this.decryptedPages[pageIndex] = decryptedPage;
  }

  simpleDecrypt(data: string): string {
    return data.split("").reverse().join("");
  }

  build() {
    Column() {
      Scroll() {
        Column() {
          ForEach(this.encryptedPages, (page: string, index: number) => {
            Column() {
              Canvas()
                .width('100%')
                .height(500)
                .backgroundColor('#f0f0f0')
                .onReady(() => {
                  // Add drawing logic here based on page content
                });

              Button(this.decryptedPages[index] ? 'Decrypted' : 'Decrypt')
                .onClick(() => this.decryptPage(index))
                .margin(10)
                .width('80%');
            }
            .margin({ bottom: 20 });
          });
        }
        .width('100%');
      }
      .width('100%')
      .height('80%');

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentPage > 0) this.currentPage--;
          })
          .width('40%')
          .margin(10);

        Button('Next')
          .onClick(() => {
            if (this.currentPage < this.encryptedPages.length - 1) this.currentPage++;
          })
          .width('40%')
          .margin(10);
      }
      .width('100%')
      .justifyContent(FlexAlign.Center);
    }
    .width('100%')
    .height('100%')
    .padding(10);
  }
}

