import prompt from '@ohos.promptAction';
import { Column, Row, Text, Button, List, ListItem } from '@ohos.arkui.advanced';
import { State } from '@ohos.arkui.state';

@Entry
@Component
struct WatchApp {
  @State isAuthenticated: boolean = false;
  @State counterValue: number = 0;
  @State messages: string[] = ['Welcome to your journal!'];
  @State isMenuVisible: boolean = false;

  private showAuthDialog(): void {
    prompt.showDialog({
      title: 'Authentication',
      message: 'Enter your credentials',
      buttons: [
        {
          text: 'Cancel',
          color: '#000000',
          action: () => {
            prompt.showToast({ message: 'Authentication canceled' });
          }
        },
        {
          text: 'Login',
          color: '#000000',
          action: () => {
            this.isAuthenticated = true;
            prompt.showToast({ message: 'Login successful' });
          }
        }
      ]
    });
  }

  private addMessage(newMessage: string): void {
    this.messages = [...this.messages, newMessage];
  }

  private toggleMenu(): void {
    this.isMenuVisible = !this.isMenuVisible;
  }

  build() {
    Column() {
      if (!this.isAuthenticated) {
        Button('Authenticate')
          .onClick(() => this.showAuthDialog())
          .margin(20)
          .width('60%')
          .height(50);
      } else {
        Column() {
          Row() {
            Button('-')
              .onClick(() => this.counterValue--)
              .margin(10)
              .width('30%');
            Text(this.counterValue.toString())
              .fontSize(20)
              .margin(10);
            Button('+')
              .onClick(() => this.counterValue++)
              .margin(10)
              .width('30%');
          }
          .justifyContent(FlexAlign.Center);

          List({ space: 10 }) {
            ForEach(this.messages, (message: string, index?: number) => {
              ListItem() {
                Text(message)
                  .fontSize(18)
                  .margin({ top: 8, bottom: 8 });
              }
            });
          }
          .height('50%')
          .margin({ top: 10, bottom: 10 });

          Button('Add Message')
            .onClick(() => this.addMessage('New journal entry'))
            .margin(10)
            .width('50%');

          Button('Toggle Menu')
            .onClick(() => this.toggleMenu())
            .margin(10)
            .width('50%');

          if (this.isMenuVisible) {
            Column() {
              Button('Home').width('100%').margin(5);
              Button('Profile').width('100%').margin(5);
              Button('Settings').width('100%').margin(5);
            }
            .width('70%')
            .margin(10);
          }
        }
        .width('100%')
        .height('100%');
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

