@Entry
@Component
struct ProjectManagementStats {
  @State private stats: MeditationStat[] = [
    { date: '2023-10-01', completed: true, duration: 30 } as MeditationStat,
    { date: '2023-10-02', completed: false, duration: 45 } as MeditationStat,
    { date: '2023-10-03', completed: true, duration: 20 } as MeditationStat,
    { date: '2023-10-04', completed: false, duration: 60 } as MeditationStat,
    { date: '2023-10-05', completed: true, duration: 15 } as MeditationStat
  ];

  @State private selectedDates: string[] = [];

  build() {
