import { TimePicker, Column, Text, TextInput, TextArea, Button, List, ListItem, Row } from '@ohos.arkui.advanced';
import { Toast } from '@ohos.arkui.notify';
import { FontWeight, Color } from '@ohos.arkui.common';
import abilityAccessCtrl from '@ohos.abilityAccessCtrl';
import vibrator from '@ohos.vibrator';
import { BusinessError } from '@ohos.base';
import common from '@ohos.app.ability.common';

interface Note {
  id: number;
  title: string;
  content: string;
  time: string;
}

interface TimeChangeValue {
  hour: number;
  minute: number;
}

@Entry
@Component
struct NoteApp {
  @State notes: Note[] = [];
  @State newNoteTitle: string = '';
  @State newNoteContent: string = '';
  @State selectedHours: number = new Date().getHours();
  @State selectedMinutes: number = new Date().getMinutes();
  @State editNoteId: number | null = null;

  aboutToAppear() {
    let context = getContext(this) as common.UIAbilityContext;
    let atManager = abilityAccessCtrl.createAtManager();
    atManager.requestPermissionsFromUser(context, ['ohos.permission.VIBRATE'], (err: BusinessError, data) => {
      if (err) {
        console.error('Failed to request permissions');
      }
    });
  }

  async vibrate() {
    try {
      await vibrator.startVibration({
        type: 'time',
        duration: 50
      }, {
        usage: 'alarm'
      }, (error: BusinessError) => {
        if (error) {
          console.error('Vibration failed:', error);
        }
      });
    } catch (error) {
      console.error('Vibration failed:', error);
    }
  }

  build() {
    Column({ space: 10 }) {
      TextInput({ placeholder: 'Enter note title...', text: this.newNoteTitle })
        .height(50)
        .width('90%')
        .onChange((value: string) => {
          this.newNoteTitle = value;
        })
        .margin(10);

      TextArea({ placeholder: 'Enter note content...', text: this.newNoteContent })
        .height(100)
        .width('90%')
        .onChange((value: string) => {
          this.newNoteContent = value;
        })
        .margin(10);

      TimePicker({
        hours: this.selectedHours,
        minutes: this.selectedMinutes,
        onDateChange: (value: TimeChangeValue) => {
          this.selectedHours = value.hour;
          this.selectedMinutes = value.minute;
          this.vibrate();
        }
      })
      .width('90%')
      .margin(10);

      Button(this.editNoteId !== null ? 'Update Note' : 'Add Note')
        .onClick(() => {
          if (this.newNoteTitle.trim() && this.newNoteContent.trim()) {
            const formattedTime = `${this.selectedHours.toString().padStart(2, '0')}:${this.selectedMinutes.toString().padStart(2, '0')}`;
            if (this.editNoteId !== null) {
              const index = this.notes.findIndex(note => note.id === this.editNoteId);
              this.notes[index] = {
                id: this.editNoteId,
                title: this.newNoteTitle,
                content: this.newNoteContent,
                time: formattedTime
              };
              this.editNoteId = null;
            } else {
              this.notes.push({
                id: Date.now(),
                title: this.newNoteTitle,
                content: this.newNoteContent,
                time: formattedTime
              });
            }
            this.newNoteTitle = '';
            this.newNoteContent = '';
            Toast.show({ message: 'Note saved successfully!', duration: 2000 });
          }
        })
        .margin(10);

      List() {
        ForEach(this.notes, (note: Note) => {
          ListItem() {
            Row() {
              Column() {
                Text(note.title)
                  .fontSize(18)
                  .fontWeight(FontWeight.Bold)
                  .width('80%');
                Text(note.content)
                  .fontSize(14)
                  .width('80%');
                Text(note.time)
                  .fontSize(12)
                  .fontColor(Color.Gray)
                  .width('80%');
              }
              .width('80%');

              Button('Edit')
                .onClick(() => {
                  this.newNoteTitle = note.title;
                  this.newNoteContent = note.content;
                  const timeParts = note.time.split(':');
                  const hours = Number(timeParts[0]);
                  const minutes = Number(timeParts[1]);
                  this.selectedHours = hours;
                  this.selectedMinutes = minutes;
                  this.editNoteId = note.id;
                })
                .margin(5);

              Button('Delete')
                .onClick(() => {
                  this.notes = this.notes.filter(n => n.id !== note.id);
                  Toast.show({ message: 'Note deleted successfully!', duration: 2000 });
                })
                .margin(5);
            }
            .padding(10);
          }
        });
      }
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

