@Entry
@Component
struct StepCounterApp {
  @State stepCount: number = 0;
  @State selectedDate: Date = new Date();
  @State validationErrors: string[] = [];

  incrementStepCount() {
    this.stepCount++;
  }

  validateForm(): boolean {
    this.validationErrors = [];
    if (this.stepCount <= 0) {
      this.validationErrors.push('Step count must be greater than 0');
    }
    if (!this.selectedDate) {
      this.validationErrors.push('Please select a date');
    }
    return this.validationErrors.length === 0;
  }

  build() {
    Column() {
      Text('Step Counter')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Text(`Steps: ${this.stepCount}`)
        .fontSize(18)
        .margin({ bottom: 10 });

      Button('Increment Steps')
        .width(200)
        .height(50)
        .margin({ bottom: 20 })
        .onClick(() => {
          this.incrementStepCount();
        });

      DatePicker({
        start: new Date('2000-01-01'),
        end: new Date('2030-12-31'),
        selected: this.selectedDate
      })
        .onDateChange((value: Date) => {
          this.selectedDate = value;
        })
        .margin({ bottom: 20 });

      Text(`Selected Date: ${this.selectedDate.toLocaleDateString()}`)
        .fontSize(16)
        .margin({ bottom: 20 });

      ForEach(this.validationErrors, (error: string) => {
        Text(error)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ bottom: 5 });
      });

      Button('Submit')
        .width(200)
        .height(50)
        .onClick(() => {
          if (this.validateForm()) {
            console.info('Form submitted successfully');
          }
        });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center);
  }
}

