@Entry
@Component
struct ExpenseTracker {
  @State transactions: Array<Transaction> = []
  @State newAmount: string = ''
  @State newCategory: string = ''
  @State newDescription: string = ''
  @State transactionType: string = 'expense'
  @State showTooltip: boolean = false
  @State selectedTransaction: number = -1

  calculateBalance(): number {
    return this.transactions.reduce((total, t) => {
      return total + (t.type === 'income' ? t.amount : -t.amount)
    }, 0)
  }

  build() {
    Column() {
      Text(`Balance: $${this.calculateBalance().toFixed(2)}`)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      Column() {
        Row() {
          Radio({ value: 'expense', group: 'type' })
            .checked(this.transactionType === 'expense')
            .onChange((isChecked) => {
              if (isChecked) this.transactionType = 'expense'
            })
          Text('Expense')
          Radio({ value: 'income', group: 'type' })
            .checked(this.transactionType === 'income')
            .onChange((isChecked) => {
              if (isChecked) this.transactionType = 'income'
            })
          Text('Income')
        }
        .margin({ bottom: 10 })

        TextInput({ placeholder: 'Amount', text: this.newAmount })
          .type(InputType.Number)
          .onChange((value: string) => {
            this.newAmount = value
          })

        TextInput({ placeholder: 'Category', text: this.newCategory })
          .onChange((value: string) => {
            this.newCategory = value
          })

        TextInput({ placeholder: 'Description', text: this.newDescription })
          .onChange((value: string) => {
            this.newDescription = value
          })

        Button('Add Transaction')
          .onClick(() => {
            if (this.newAmount && this.newCategory) {
              this.transactions.push({
                type: this.transactionType,
                amount: parseFloat(this.newAmount),
                category: this.newCategory,
                description: this.newDescription,
                date: new Date().toISOString()
              } as Transaction)
              this.newAmount = ''
              this.newCategory = ''
              this.newDescription = ''
            }
          })
      }
      .padding(20)

      List() {
        ForEach(this.transactions, (transaction: Transaction, index: number) => {
          ListItem() {
            Row() {
              Column() {
                Text(transaction.category)
                  .fontSize(18)
                  .fontWeight(FontWeight.Bold)
                Text(transaction.description)
                  .fontSize(14)
                  .fontColor(Color.Gray)
              }
              Text(`${transaction.type === 'income' ? '+' : '-'}$${transaction.amount.toFixed(2)}`)
                .fontSize(18)
                .fontColor(transaction.type === 'income' ? '#4CAF50' : '#F44336')
            }
            .justifyContent(FlexAlign.SpaceBetween)
            .width('100%')
            .padding(10)
            .onClick(() => {
              this.selectedTransaction = index
              this.showTooltip = true
            })
          }
        })
      }
      .width('100%')

      Flex({ justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
        Column()
          .width(200)
          .height(150)
          .backgroundColor('#CCCCCC')
      }
      .width('100%')
      .height(200)
      .margin({ top: 20 })

      if (this.showTooltip && this.selectedTransaction >= 0) {
        Column() {
          Text(`Category: ${this.transactions[this.selectedTransaction].category}`)
          Text(`Amount: ${this.transactions[this.selectedTransaction].amount}`)
          Text(`Description: ${this.transactions[this.selectedTransaction].description}`)
          Text(`Date: ${this.transactions[this.selectedTransaction].date}`)
          Button('Close')
            .onClick(() => {
              this.showTooltip = false
            })
        }
        .padding(20)
        .backgroundColor('#ffffff')
        .borderRadius(10)
        .shadow(10)
      }
    }
    .padding(20)
  }
}

interface Item {
  id: number;
  title: string;
  description: string;
}

@Entry
@Component
struct ItemPaginationApp {
  @State private items: Item[] = [];
  @State private isLoading: boolean = true;
  @State private currentPage: number = 1;
  @State private searchText: string = '';
  private totalPages: number = 5;

  aboutToAppear() {
    this.fetchData();
  }

  fetchData() {
    this.isLoading = true;
    setTimeout(() => {
      const newItems: Item[] = [];
      for (let i = 1; i <= 10; i++) {
        newItems.push({
          id: i,
          title: `Item ${i + (this.currentPage - 1) * 10}`,
          description: `Description for Item ${i + (this.currentPage - 1) * 10}`
        });
      }
      this.items = newItems;
      this.isLoading = false;
    }, 1000);
  }

  handleSearch() {
    this.currentPage = 1;
    this.fetchData();
  }

  handlePageChange(newPage: number) {
    if (newPage >= 1 && newPage <= this.totalPages) {
      this.currentPage = newPage;
      this.fetchData();
    }
  }

  handleShare(platform: string) {
    console.log(`Sharing to ${platform}`);
  }

  build() {
    Column() {
      Search({ placeholder: 'Search items', value: this.searchText })
        .searchButton('Search')
        .onChange((value: string) => {
          this.searchText = value;
        })
        .onSubmit(() => {
          this.handleSearch();
        })
        .margin(16)
        .width('90%');

      Scroll() {
        Column() {
          if (this.isLoading) {
            Text('Loading...')
              .fontSize(18)
              .margin({ top: 20 });
          } else {
            ForEach(this.items, (item: Item) => {
              Row() {
                Image($r('app.media.icon'))
                  .width(80)
                  .height(80)
                  .borderRadius(8)
                  .objectFit(ImageFit.Cover);
                Column() {
                  Text(item.title)
                    .fontSize(16)
                    .fontWeight(FontWeight.Medium);
                  Text(item.description)
                    .fontSize(14)
                    .fontColor('#666666');
                }
                .margin({ left: 16 });
              }
              .padding(16)
              .backgroundColor(Color.White)
              .borderRadius(12)
              .margin({ bottom: 12 });
            });
          }
        }
        .width('100%');
      }
      .layoutWeight(1);

      Row() {
        Button('Previous')
          .enabled(this.currentPage > 1)
          .onClick(() => {
            this.handlePageChange(this.currentPage - 1);
          });
        Text(`${this.currentPage} / ${this.totalPages}`)
          .margin({ left: 16, right: 16 });
        Button('Next')
          .enabled(this.currentPage < this.totalPages)
          .onClick(() => {
            this.handlePageChange(this.currentPage + 1);
          });
      }
      .justifyContent(FlexAlign.Center)
      .margin({ top: 16, bottom: 16 });

      Row() {
        Button('Facebook')
          .onClick(() => {
            this.handleShare('Facebook');
          });
        Button('Twitter')
          .margin({ left: 16 })
          .onClick(() => {
            this.handleShare('Twitter');
          });
      }
      .justifyContent(FlexAlign.Center)
      .margin({ bottom: 16 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }
}

