import { CustomDialog } from '@ohos.arkui.advanced.CustomDialog';
import { CustomDialogController } from '@ohos.arkui.advanced';
import audio from '@ohos.multimedia.audio';

interface FormData {
  name: string;
  email: string;
}

@CustomDialog
struct CustomPopupDialog {
  controller: CustomDialogController;
  @State private formData: FormData = { name: '', email: '' };
  @State private isPlaying: boolean = false;
  private audioRenderer: audio.AudioRenderer | null = null;

  aboutToAppear(): void {
    this.initializeAudioRenderer().catch((error: Error) => {
      console.error('Audio initialization error:', error);
    });
  }

  aboutToDisappear(): void {
    if (this.audioRenderer) {
      this.audioRenderer.release();
      this.audioRenderer = null;
    }
  }

  private async initializeAudioRenderer(): Promise<void> {
    try {
      const audioRendererOptions: audio.AudioRendererOptions = {
        streamInfo: {
          samplingRate: audio.AudioSamplingRate.SAMPLE_RATE_44100,
          channels: audio.AudioChannel.CHANNEL_2,
          sampleFormat: audio.AudioSampleFormat.SAMPLE_FORMAT_S16LE,
          encodingType: audio.AudioEncodingType.ENCODING_TYPE_RAW
        },
        rendererInfo: {
          usage: audio.StreamUsage.STREAM_USAGE_MUSIC,
          rendererFlags: 0
        }
      };
      this.audioRenderer = await audio.createAudioRenderer(audioRendererOptions);
    } catch (error) {
      console.error('Failed to initialize audio renderer:', error);
    }
  }

  private async toggleAudio(): Promise<void> {
    if (this.audioRenderer) {
      try {
        if (this.isPlaying) {
          await this.audioRenderer.stop();
        } else {
          await this.audioRenderer.start();
        }
        this.isPlaying = !this.isPlaying;
      } catch (error) {
        console.error('Audio operation failed:', error);
      }
    }
  }

  private submitForm(): void {
    console.info('Form submitted:', this.formData);
    this.controller.close();
  }

  build() {
    Column() {
      Text('Enter your details')
        .fontSize(20)
        .margin({ top: 10, bottom: 20 });

      TextInput({ placeholder: 'Name', text: this.formData.name })
        .height(50)
        .width('90%')
        .onChange((value: string) => {
          this.formData.name = value;
        })
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Email', text: this.formData.email })
        .height(50)
        .width('90%')
        .onChange((value: string) => {
          this.formData.email = value;
        })
        .margin({ bottom: 20 });

      Flex({ justifyContent: FlexAlign.SpaceAround }) {
        Button(this.isPlaying ? 'Stop Audio' : 'Play Audio')
          .onClick(() => this.toggleAudio())
          .backgroundColor(0xffffff)
          .fontColor(Color.Black)
          .borderRadius(5)
          .padding(10);

        Button('Submit')
          .onClick(() => this.submitForm())
          .backgroundColor(0xffffff)
          .fontColor(Color.Red)
          .borderRadius(5)
          .padding(10);
      }
      .margin({ bottom: 10 });
    }
    .width('80%')
    .padding(20)
    .backgroundColor(0xffffff)
    .borderRadius(10)
    .shadow({ radius: 10, color: 0x000000, offsetX: 0, offsetY: 0 });
  }
}

