@Entry
@Component
struct TimePickerWithEncryption {
  @State selectedTime: Date = new Date(2023, 9, 15, 12, 0, 0);
  @State encryptedData: string = '';
  @State showEncryptedData: boolean = false;
  @State stepperValue: number = 0;

  encryptData(data: string): string {
    return data.split('').map(char => String.fromCharCode(char.charCodeAt(0) + 1)).join('');
  }

  build() {
    Column({ space: 20 }) {
      TimePicker({
        selected: this.selectedTime
      })
      .onChange((value: TimePickerResult) => {
        this.selectedTime = new Date(
          this.selectedTime.getFullYear(),
          this.selectedTime.getMonth(),
          this.selectedTime.getDate(),
          value.hour,
          value.minute,
          value.second
        );
      })

      Stepper({
        index: this.stepperValue
      })
      .onChange((index: number) => {
        this.stepperValue = index;
      })

      Button('Encrypt Time')
        .onClick(() => {
          this.encryptedData = this.encryptData(this.selectedTime.toLocaleTimeString());
          this.showEncryptedData = true;
        })

      if (this.showEncryptedData) {
        Text(`Encrypted Data: ${this.encryptedData}`)
          .fontSize(20)
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

