import { Swiper } from '@ohos.arkui.component';
import { Image, ImageFit } from '@ohos.arkui.component';
import { Text } from '@ohos.arkui.component';
import { Button } from '@ohos.arkui.component';
import { Row, Column, FlexAlign } from '@ohos.arkui.component';
import { State } from '@ohos.arkui.component';

@Entry
@Component
struct BookReader {
  @State currentFrame: number = 0;
  @State isPlaying: boolean = false;
  private frames: string[] = ['media_1', 'media_2', 'media_3'];
  private timerId: number | null = null;

  build() {
    Column() {
      Swiper({
        index: this.currentFrame,
        onChange: (index: number) => {
          this.currentFrame = index;
        }
      }) {
        ForEach(this.frames, (frame: string) => {
          Image($r(`app.media.${frame}`))
            .width('100%')
            .height('100%')
            .objectFit(ImageFit.Cover)
            .onError(() => {
              console.error(`Failed to load image: ${frame}`);
            });
        });
      }
      .width('100%')
      .height('60%')
      .indicator(true)
      .loop(false);

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentFrame > 0) {
              this.currentFrame--;
            }
          })
          .enabled(this.currentFrame > 0);

        Button(this.isPlaying ? 'Pause' : 'Play')
          .onClick(() => {
            this.isPlaying = !this.isPlaying;
            if (this.isPlaying) {
              this.startAutoAdvance();
            } else {
              this.stopAutoAdvance();
            }
          });

        Button('Next')
          .onClick(() => {
            if (this.currentFrame < this.frames.length - 1) {
              this.currentFrame++;
            }
          })
          .enabled(this.currentFrame < this.frames.length - 1);
      }
      .justifyContent(FlexAlign.SpaceAround)
      .width('100%')
      .margin({ top: 20 });

      Row() {
        ForEach(this.frames, (frame: string, index: number) => {
          Button('')
            .width(20)
            .height(20)
            .borderRadius(10)
            .backgroundColor(index === this.currentFrame ? '#007AFF' : '#E0E0E0')
            .onClick(() => {
              this.currentFrame = index;
            })
            .margin(5);
        });
      }
      .justifyContent(FlexAlign.Center)
      .width('100%')
      .margin({ top: 10 });
    }
    .width('100%')
    .height('100%')
    .padding(16);
  }

  private startAutoAdvance() {
    this.timerId = setInterval(() => {
      if (this.currentFrame < this.frames.length - 1) {
        this.currentFrame++;
      } else {
        this.stopAutoAdvance();
        this.isPlaying = false;
      }
    }, 1000);
  }

  private stopAutoAdvance() {
    if (this.timerId !== null) {
      clearInterval(this.timerId);
      this.timerId = null;
    }
  }

  onPageHide() {
    this.stopAutoAdvance();
  }
}

@Entry
@Component
struct EventPlanner {
  @State offsetX: number = 0;
  @State offsetY: number = 0;
  @State initialX: number = 0;
  @State initialY: number = 0;
  @State isDragging: boolean = false;
  @State dragStatus: string = "Drag not started";

  private handleDragStart(event: TouchEvent) {
    this.initialX = this.offsetX;
    this.initialY = this.offsetY;
    this.isDragging = true;
    this.dragStatus = "Dragging started";
  }

  private handleDragMove(event: TouchEvent) {
    if (this.isDragging) {
      this.offsetX = this.initialX + event.touches[0].x;
      this.offsetY = this.initialY + event.touches[0].y;
      this.dragStatus = `Dragging: X=${this.offsetX.toFixed(0)}, Y=${this.offsetY.toFixed(0)}`;
    }
  }

  private handleDragEnd() {
    this.isDragging = false;
    this.dragStatus = "Drag ended";
  }

  build() {
    Stack() {
      Column() {
        Text(this.dragStatus)
          .fontSize(16)
          .margin(10);

        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
          .position({ x: this.offsetX, y: this.offsetY })
          .onTouch((event: TouchEvent) => {
            if (event.type === TouchType.Down) {
              this.handleDragStart(event);
            } else if (event.type === TouchType.Move) {
              this.handleDragMove(event);
            } else if (event.type === TouchType.Up) {
              this.handleDragEnd();
            }
          });
      }
      .width('100%')
      .height('100%')
      .backgroundColor('#f0f0f0');
    }
  }
}

import router from '@ohos.router';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct LoginScreen {
  @State email: string = '';
  @State password: string = '';
  @State message: string = '';
  @State isSuccess: boolean = false;

  validateInputs(): boolean {
    if (!this.email || !this.password) {
      promptAction.showToast({
        message: 'Please fill in all fields',
        duration: 2000
      });
      return false;
    }
    return true;
  }

  navigateToHome() {
    router.pushUrl({
      url: 'pages/HomePage'
    })
    .then(() => {
      console.log('Navigation to HomePage successful');
    })
    .catch((err: Error) => {
      console.error('Navigation failed: ', err);
    });
  }

  build() {
    Column() {
      Text('Login')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 30 });

      Text('Email:')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your email' })
        .width('80%')
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.email = value;
        });

      Text('Password:')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .width('80%')
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.password = value;
        });

      Button('Login')
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)
        .onClick(() => {
          if (this.validateInputs()) {
            this.navigateToHome();
          }
        });

      if (this.message) {
        Text(this.message)
          .fontSize(14)
          .fontColor(this.isSuccess ? '#4CAF50' : '#F44336')
          .margin({ top: 20 });
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

