  minute: number;
  second: number;
}

@Entry
@Component
struct MealPlannerApp {
  @State marqueeOffset: number = 0;
  @State selectedTime: string = '12:00 PM';
  @State mealItems: string[] = ['Breakfast', 'Lunch', 'Dinner', 'Snacks'];
  @State draggedItemIndex: number = -1;

  build() {
    Column() {
      Row() {
        Text('Weekly Meal Planner')
          .fontSize(24)
          .fontWeight(700)
          .margin({ left: this.marqueeOffset })
          .onAppear(() => {
            animateTo({ duration: 10000, iterations: -1 }, () => {
              this.marqueeOffset = -1000;
            });
          });
      }
      .width('100%')
      .height(60)
      .backgroundColor('#f0f0f0')
      .clip(true);

      Row() {
        TimePicker()
          .onChange((time: TimePickerResult) => {
            this.selectedTime = `${time.hour % 12 || 12}:${time.minute.toString().padStart(2, '0')} ${time.hour >= 12 ? 'PM' : 'AM'}`;
          });
        Text(this.selectedTime)
          .fontSize(18)
          .margin({ left: 10 });
