const seats: Seat[] = Array.from({length: 20}, (_, index): Seat => ({
  id: index + 1,
  isBooked: Math.random() < 0.3,
  isSelected: false
}));

@Entry
@Component
struct MovieBookingApp {
  @State selectedMovie: Movie | null = null;
  @State selectedSeats: Seat[] = [];
  @State isDarkMode: boolean = false;

  build() {
    Column() {
      if (this.selectedMovie == null) {
        Column() {
          Text('Movie List')
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .padding(16);

          List() {
            ForEach<Movie, ListItem>(movies, (movie: Movie, index: number) => {
              ListItem() {
                Row() {
                  Image(movie.poster)
                    .width(100)
                    .height(150)
                    .objectFit(ImageFit.Cover)
                    .padding(10);
                  Column() {
                    Text(movie.title)
                      .fontSize(20)
                      .fontWeight(FontWeight.Medium)
                      .padding({ bottom: 4 });
                    Text(`Release Date: ${movie.releaseDate}`)
                      .fontSize(16)
                      .padding({ bottom: 8 });
                  }
                  .padding(16);
                }
                .onClick(() => {
                  this.selectedMovie = movie;
                });
              }
            });
          }
        }
      } else {
        Column() {
          Row() {
            Text(this.selectedMovie.title)
              .fontSize(24)
              .fontWeight(FontWeight.Bold)
              .padding(16);
            Button('Back')
              .onClick(() => {
                this.selectedMovie = null;
                this.selectedSeats = [];
              })
              .padding(16);
          }

          Scroll() {
            Column() {
              Text('Seat Selection')
                .fontSize(20)
                .fontWeight(FontWeight.Bold)
                .padding(16);

              Grid() {
                ForEach<Seat, GridItem>(seats, (seat: Seat) => {
                  GridItem() {
                    Column() {
                      Column()
                        .width(40)
                        .height(40)
                        .backgroundColor(seat.isBooked ? Color.Red : seat.isSelected ? Color.Green : Color.Gray)
                        .onClick(() => {
                          if (!seat.isBooked) {
                            seat.isSelected = !seat.isSelected;
                            this.selectedSeats = seats.filter((s: Seat) => s.isSelected);
                          }
                        });
                      Text(`Seat ${seat.id}`)
                        .fontSize(12);
                    }
                  }
                });
              }
              .columnsTemplate('1fr 1fr 1fr 1fr 1fr')
              .columnsGap(10)
              .rowsGap(10)
              .padding(16);

              Button('Book Selected Seats')
                .onClick(() => {
                  this.selectedSeats.forEach((seat: Seat) => seat.isBooked = true);
                  this.selectedSeats = [];
                })
                .padding(16);
            }
          }
        }
      }

      Toggle({ type: ToggleType.Switch, isOn: this.isDarkMode })
        .onChange((isOn: boolean) => {
          this.isDarkMode = isOn;
        })
        .margin(16);
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.isDarkMode ? Color.Black : Color.White);
