@Entry
@Component
struct Stopwatch {
    @State elapsedTime: number = 0
    @State isRunning: boolean = false
    @State selectedDate: string = ''
    @State selectedMode: string = 'stopwatch'
    private timerId: number = -1

    build() {
        Column() {
            Row() {
                Radio({ value: 'stopwatch', group: 'mode' })
                    .onChange((isChecked: boolean) => {
                        if (isChecked) this.selectedMode = 'stopwatch'
                    })
                Text('Stopwatch')
                    .margin({ left: 5 })

                Radio({ value: 'timer', group: 'mode' })
                    .onChange((isChecked: boolean) => {
                        if (isChecked) this.selectedMode = 'timer'
                    })
                Text('Timer')
                    .margin({ left: 5 })
            }
            .margin(10)

            if (this.selectedMode === 'timer') {
                TextInput({ placeholder: 'Select date' })
                    .onChange((value: string) => {
                        this.selectedDate = value
                    })
            }

            Text(this.formatTime(this.elapsedTime))
                .fontSize(40)
                .margin(20)
                .animation({
                    duration: 1000,
                    curve: Curve.EaseInOut,
                    iterations: 1,
                    playMode: PlayMode.Normal
                })

            Row() {
                Button(this.isRunning ? 'Stop' : 'Start')
                    .onClick(() => {
                        if (this.isRunning) {
                            clearInterval(this.timerId)
                        } else {
                            this.timerId = setInterval(() => {
                                this.elapsedTime += 1
                            }, 10)
                        }
                        this.isRunning = !this.isRunning
                    })
                    .margin(10)

                Button('Reset')
                    .onClick(() => {
                        clearInterval(this.timerId)
                        this.elapsedTime = 0
                        this.isRunning = false
                    })
                    .margin(10)
            }
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
    }

    private formatTime(time: number): string {
        const minutes = Math.floor(time / 6000).toString().padStart(2, '0');
        const seconds = Math.floor((time % 6000) / 100).toString().padStart(2, '0');
        const centiseconds = (time % 100).toString().padStart(2, '0');
        return `${minutes}:${seconds}.${centiseconds}`;
    }
}

