          ListItem() {
            Row() {
              Column() {
                Text(note.title)
                  .fontSize(18)
                  .fontWeight(FontWeight.Bold)
                  .fontColor(this.isDarkMode ? '#FFFFFF' : '#000000');
                Text(note.content)
                  .fontSize(14)
                  .fontColor(this.isDarkMode ? '#FFFFFF' : '#000000');
              }
              .width('80%');
              Button('Delete')
                .onClick(() => {
                  this.notes = this.notes.filter(n => n.id !== note.id);
