import promptAction from '@ohos.promptAction';

@Entry
@Component
struct FilePickerSimulation {
  @State selectedImage: Resource = $r('app.media.icon');
  @State showFeedback: boolean = false;
  @State feedbackMessage: string = '';

  build() {
    Column({ space: 20 }) {
      Image(this.selectedImage)
        .width(200)
        .height(200)
        .margin({ top: 20 })

      Button('Select Image')
        .onClick(() => {
          this.showImageSourceOptions();
        })
        .width(200)
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .onAppear(() => {
      if (this.showFeedback) {
        this.showAlertDialog();
      }
    })
  }

  private showAlertDialog() {
    AlertDialog.show({
      title: 'Feedback',
      message: this.feedbackMessage,
      confirm: {
        value: 'OK',
        action: () => {
          this.showFeedback = false;
        }
      }
    });
  }

  private showImageSourceOptions() {
    promptAction.showActionMenu({
      title: 'Select Image Source',
      buttons: [
        { text: 'Camera', color: '#000000' },
        { text: 'Gallery', color: '#000000' },
        { text: 'Cancel', color: '#FF0000' }
      ]
    }).then((result: promptAction.ActionMenuSuccessResponse) => {
      if (result.index === 0) {
        this.simulateCameraCapture();
      } else if (result.index === 1) {
        this.simulateGallerySelection();
      }
    });
  }

  private simulateCameraCapture() {
    this.selectedImage = $r('app.media.icon');
    this.feedbackMessage = 'Image captured from camera';
    this.showFeedback = true;
  }

  private simulateGallerySelection() {
    this.selectedImage = $r('app.media.icon');
    this.feedbackMessage = 'Image selected from gallery';
    this.showFeedback = true;
  }
}

