import { Column, Text, Button, Row, Divider, ContextMenu, MenuItem, FlexAlign, Slider } from '@ohos.arkui.component';

@Entry
@Component
struct Stopwatch {
    @State elapsedTime: number = 0
    @State isRunning: boolean = false
    @State dividerWidth: number = 2
    @State dividerColor: string = '#000000'
    @State dividerOpacity: number = 1
    private timerId: number | null = null

    build() {
        Column() {
            Text(this.formatTime(this.elapsedTime))
                .fontSize(40)
                .margin(20)

            Divider()
                .strokeWidth(this.dividerWidth)
                .color(this.dividerColor)
                .opacity(this.dividerOpacity)
                .margin(20)
                .animation({ duration: 300 })

            Slider({
                value: this.dividerWidth,
                min: 1,
                max: 10,
                step: 1
            })
                .onChange((value: number) => {
                    this.dividerWidth = value
                })
                .margin(20)

            Row() {
                Button(this.isRunning ? 'Stop' : 'Start')
                    .onClick(() => {
                        if (this.isRunning) {
                            if (this.timerId !== null) {
                                clearInterval(this.timerId)
                                this.timerId = null
                            }
                        } else {
                            this.timerId = setInterval(() => {
                                this.elapsedTime += 1
                            }, 10)
                        }
                        this.isRunning = !this.isRunning
                    })
                    .margin(10)

                Button('Reset')
                    .onClick(() => {
                        if (this.timerId !== null) {
                            clearInterval(this.timerId)
                            this.timerId = null
                        }
                        this.elapsedTime = 0
                        this.isRunning = false
                    })
                    .margin(10)
            }

            ContextMenu() {
                MenuItem('Increase Opacity')
                    .onClick(() => {
                        this.dividerOpacity = Math.min(1, this.dividerOpacity + 0.1)
                    })

                MenuItem('Decrease Opacity')
                    .onClick(() => {
                        this.dividerOpacity = Math.max(0, this.dividerOpacity - 0.1)
                    })
            }
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
    }

    private formatTime(time: number): string {
        const minutes = Math.floor(time / 6000)
        const seconds = Math.floor((time % 6000) / 100)
        const centiseconds = time % 100
        return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}.${centiseconds.toString().padStart(2, '0')}`
    }
}

