import { Column, Grid, GridItem, Image, ImageFit, Color } from '@ohos.arkui.advanced';
import { Refresh, RefreshController } from '@ohos.arkui.component.refresh';
import { Gesture } from '@ohos.arkui.component.gesture';

@Entry
@Component
struct PhotoEditor {
  @State photos: string[] = [
    'https://placehold.co/600x400',
    'https://placehold.co/600x400',
    'https://placehold.co/600x400',
    'https://placehold.co/600x400',
    'https://placehold.co/600x400',
    'https://placehold.co/600x400',
    'https://placehold.co/600x400',
    'https://placehold.co/600x400',
    'https://placehold.co/600x400',
    'https://placehold.co/600x400'
  ];
  @State selectedPhotos: string[] = [];
  @State refreshing: boolean = false;
  private refreshController: RefreshController = new RefreshController();

  build() {
    Column() {
      Refresh({
        controller: this.refreshController,
        onRefresh: () => {
          this.refreshing = true;
          setTimeout(() => {
            this.photos = [...this.photos, 'https://placehold.co/600x400', 'https://placehold.co/600x400'];
            this.refreshing = false;
            this.refreshController.finishRefresh();
          }, 1000);
        }
      }) {
        Grid() {
          ForEach(this.photos, (photo: string, index: number) => {
            GridItem() {
              Gesture({
                onLongPress: () => {
                  if (this.selectedPhotos.includes(photo)) {
                    this.selectedPhotos = this.selectedPhotos.filter(item => item !== photo);
                  } else {
                    this.selectedPhotos = [...this.selectedPhotos, photo];
                  }
                }
              }) {
                Image(photo)
                  .width('100%')
                  .height(150)
                  .margin(5)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(5)
                  .border({
                    width: this.selectedPhotos.includes(photo) ? 2 : 0,
                    color: Color.Blue
                  });
              }
            }
          });
        }
        .columnsTemplate('1fr 1fr')
        .columnsGap(5)
        .rowsGap(5)
        .padding(5);
      }
      .width('100%')
      .height('100%');
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5');
  }
}

import promptAction from '@ohos.promptAction';

@Entry
@Component
struct NewsReader {
  @State refreshing: boolean = false;
  @State newsData: string[] = ['News 1', 'News 2', 'News 3'];
  @State timerId: number = -1;

  aboutToAppear() {
    this.timerId = setInterval(() => {
      this.newsData.push("Breaking News " + (this.newsData.length + 1).toString());
      if (this.newsData.length > 10) {
        this.newsData.shift();
      }
    }, 5000);
  }

  aboutToDisappear() {
    if (this.timerId !== -1) {
      clearInterval(this.timerId);
    }
  }

  refreshNews() {
    this.refreshing = true;
    promptAction.showToast({message: 'Refreshing news...'});
    setTimeout(() => {
      this.newsData = ['Latest News 1', 'Latest News 2', 'Latest News 3'];
      this.refreshing = false;
      promptAction.showToast({message: 'Refresh complete'});
    }, 2000);
  }

  build() {
    Column() {
      List() {
        ForEach(this.newsData, (item: string) => {
          ListItem() {
            Text(item)
              .fontSize(16)
              .padding(16)
              .backgroundColor('#f0f0f0')
              .width('100%')
          }
        })
      }
      .width('100%')
      .margin({ top: 10 })
      .divider({ strokeWidth: 1, color: '#F1F3F5' })
      .edgeEffect(EdgeEffect.Spring)
      .onScrollIndex((first: number) => {
        if (first === 0 && !this.refreshing) {
          this.refreshNews();
        }
      })

      Slider({
        value: 0,
        min: 0,
        max: 100,
        style: SliderStyle.OutSet
      })
      .onChange((value: number) => {
        if (value > 80 && !this.refreshing) {
          this.refreshNews();
        }
      })

      Column()
        .gesture(
          RotationGesture()
            .onActionStart(() => {})
            .onActionUpdate((event: GestureEvent) => {
              if (Math.abs(event.angle) > 45 && !this.refreshing) {
                this.refreshNews();
              }
            })
        )
    }
    .width('100%')
    .height('100%')
  }
}

import { Tabs, TabContent, Text, Image, Button, Column, Row } from '@ohos.arkui.advanced';
import media from '@ohos.multimedia.media';
import vibrator from '@ohos.vibrator';
import abilityAccessCtrl from '@ohos.abilityAccessCtrl';
import common from '@ohos.app.ability.common';
import AppStorage from '@ohos.data.storage';

@Entry
@Component
struct FitnessTracker {
  private workoutPhases: string[] = ['Warm-Up', 'Cardio', 'Strength Training', 'Cooldown'];
  private workoutDescriptions: string[] = [
    'Prepare your body for exercise with light movements.',
    'Get your heart pumping with high-intensity exercises.',
    'Build muscle with resistance training.',
    'Cool down and stretch to relax your muscles.'
  ];
  private workoutImages: Resource[] = [
    $r('app.media.ic_public_warmup'),
    $r('app.media.ic_public_cardio'),
    $r('app.media.ic_public_strength'),
    $r('app.media.ic_public_cooldown')
  ];
  private audioFiles: Resource[] = [
    $rawfile('warmup.mp3'),
    $rawfile('cardio.mp3'),
    $rawfile('strength.mp3'),
    $rawfile('cooldown.mp3')
  ];
  private avPlayers: media.AVPlayer[] = [];
  @State currentTabIndex: number = 0;

  async aboutToAppear() {
    let context = getContext(this) as common.UIAbilityContext;
    let atManager = abilityAccessCtrl.createAtManager();
    await atManager.requestPermissionsFromUser(context, ['ohos.permission.VIBRATE']);
    this.initializeAVPlayers();
  }

  async initializeAVPlayers(): Promise<void> {
    for (let audioFile of this.audioFiles) {
      try {
        const avPlayer = media.createAVPlayer();
        avPlayer.url = audioFile.toString();
        await avPlayer.prepare();
        avPlayer.on('stateChange', (state: string) => {
          if (state === 'error') {
            console.error('Error playing audio');
          }
        });
        this.avPlayers.push(avPlayer);
      } catch (error) {
        console.error('Failed to initialize AVPlayer: ' + error.message);
      }
    }
  }

  playAudio(index: number): void {
    this.vibrate();
    this.avPlayers[index].play();
  }

  onTabChange(index: number): void {
    this.vibrate();
    this.currentTabIndex = index;
  }

  vibrate(): void {
    try {
      vibrator.startVibration({ duration: 100 });
    } catch (error) {
      console.error('Failed to vibrate: ' + error.message);
    }
  }

  build() {
    Column() {
      Tabs({ index: this.currentTabIndex }) {
        ForEach(this.workoutPhases, (phase: string, index: number) => {
          TabContent() {
            Column({ space: 16 }) {
              Text(phase)
                .fontSize(24)
                .fontWeight(FontWeight.Bold);
              Text(this.workoutDescriptions[index])
                .fontSize(16);
              Image(this.workoutImages[index])
                .width(200)
                .height(200);
              Button('Play Audio')
                .onClick(() => this.playAudio(index));
            }
            .width('100%')
            .height('100%')
            .justifyContent(FlexAlign.Center)
            .padding(16);
          }
        });
      }
      .onChange((index: number) => this.onTabChange(index))
      .width('100%')
      .height('80%');
    }
    .width('100%')
    .height('100%');
  }
}

