import { Image, Column, Text, FlexAlign, HorizontalAlign, Rating } from '@ohos.arkui.advanced';
import { animateTo, Curve } from '@ohos.animator';

@Entry
@Component
struct InteractiveImageComponent {
  @State scaleValue: number = 1.0;
  @State opacityValue: number = 1.0;
  @State rotationValue: number = 0;
  @State ratingValue: number = 0;

  build() {
    Column({ space: 20 }) {
      Image($r('app.media.img'))
        .width(200)
        .height(200)
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .opacity(this.opacityValue)
        .rotate({ angle: this.rotationValue })
        .onClick(() => {
          animateTo({
            duration: 1000,
            curve: Curve.EaseInOut
          }, () => {
            this.scaleValue = this.scaleValue === 1.0 ? 1.5 : 1.0;
            this.opacityValue = this.opacityValue === 1.0 ? 0.5 : 1.0;
            this.rotationValue = this.rotationValue === 0 ? 45 : 0;
          });
        })

      Text('Rate the animation:')
        .margin({ top: 20 })

      Rating()
        .rating(this.ratingValue)
        .onChange((value: number) => {
          this.ratingValue = value;
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

import router from '@ohos.router';
import { TextInput, InputType } from '@ohos.arkui.component';
import { FlexAlign, HorizontalAlign } from '@ohos.arkui.common';

@Entry
@Component
struct AuthFlow {
  @State currentStep: number = 0;
  @State username: string = '';
  @State password: string = '';
  @State email: string = '';
  @State isEmailValid: boolean = false;

  validateEmail(email: string): boolean {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return re.test(email);
  }

  nextStep() {
    if (this.currentStep < 2) {
      this.currentStep++;
    }
  }

  prevStep() {
    if (this.currentStep > 0) {
      this.currentStep--;
    }
  }

  submit() {
    if (this.username && this.password && this.isEmailValid) {
      router.pushUrl({
        url: 'pages/ComicReader'
      });
    }
  }

  build() {
    Column() {
      Stepper() {
        StepperItem() {
          Text('Username')
        }
        StepperItem() {
          Text('Password')
        }
        StepperItem() {
          Text('Email')
        }
      }
      .index(this.currentStep)
      .onChange((index: number) => {
        this.currentStep = index;
      })

      Swiper() {
        Column() {
          TextInput({ placeholder: 'Enter username', text: this.username })
            .onChange((value: string) => {
              this.username = value;
            })
            .width('80%');
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center);

        Column() {
          TextInput({ placeholder: 'Enter password', text: this.password })
            .type(InputType.Password)
            .onChange((value: string) => {
              this.password = value;
            })
            .width('80%');
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center);

        Column() {
          TextInput({ placeholder: 'Enter email', text: this.email })
            .onChange((value: string) => {
              this.email = value;
              this.isEmailValid = this.validateEmail(value);
            })
            .width('80%');
          if (this.email && !this.isEmailValid) {
            Text('Invalid email format')
              .fontColor('#ff0000');
          }
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center);
      }
      .index(this.currentStep)
      .onChange((index: number) => {
        this.currentStep = index;
      })

      if (this.currentStep === 2) {
        Column() {
          Text('Summary')
            .fontSize(20)
            .fontWeight('bold');
          Text(`Username: ${this.username}`);
          Text(`Password: ${'*'.repeat(this.password.length)}`);
          Text(`Email: ${this.email}`);
          Button('Submit')
            .onClick(() => this.submit())
            .width('60%');
        }
        .width('100%')
        .padding(20);
      }

      Row() {
        Button('Back')
          .onClick(() => this.prevStep())
          .opacity(this.currentStep === 0 ? 0.5 : 1)
          .enabled(this.currentStep !== 0);
        Button('Next')
          .onClick(() => this.nextStep())
          .opacity(this.currentStep === 2 ? 0.5 : 1)
          .enabled(this.currentStep !== 2);
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceBetween)
      .padding(20);
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

