@Entry
@Component
struct AudioPlayerWithGesture {
  @State angle: number = 0
  @State isPlaying: boolean = false
  @State volume: number = 50
  @State analyticsData: string = "Gesture data will appear here"

  build() {
    Column() {
      Image($r('app.media.icon'))
        .width(200)
        .height(200)
        .rotate({ x: 0, y: 0, z: 1, angle: this.angle })
        .gesture(
          RotationGesture()
            .onActionStart(() => {
              this.analyticsData = "Rotation gesture started"
            })
            .onActionUpdate((event: RotationGestureEvent) => {
              this.angle = event.angle
              this.volume = Math.min(100, Math.max(0, this.volume + event.angle / 10))
              this.analyticsData = `Rotating: ${this.angle.toFixed(2)}° | Volume: ${this.volume}`
            })
            .onActionEnd(() => {
              this.analyticsData = "Rotation gesture ended"
            })
            .onActionCancel(() => {
              this.analyticsData = "Rotation gesture cancelled"
            })
        )

      Flex({ direction: FlexDirection.Row, justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
        Button("Play/Pause")
          .onClick(() => {
            this.isPlaying = !this.isPlaying
            this.analyticsData = `Playback ${this.isPlaying ? "started" : "paused"}`
          })

        Slider({
          value: this.volume,
          min: 0,
          max: 100,
          step: 1,
          style: SliderStyle.OutSet
        })
          .onChange((value: number) => {
            this.volume = value
            this.analyticsData = `Volume adjusted to ${value}`
          })
      }
      .width('100%')
      .margin({ top: 20 })

      Text(this.analyticsData)
        .fontSize(16)
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

import { Refresh, Toggle, ToggleType, FlexAlign, animateTo } from '@ohos.arkui.advanced';
import media from '@ohos.multimedia.media';
import common from '@ohos.app.ability.common';

interface Habit {
  name: string;
  completed: boolean;
}

@Entry
@Component
struct HabitTracker {
  @State habits: Array<Habit> = [
    { name: 'Drink Water', completed: false },
    { name: 'Exercise', completed: false },
    { name: 'Read', completed: false }
  ];
  @State refreshing: boolean = false;
  private avPlayer: media.AVPlayer | null = null;

  async aboutToAppear(): Promise<void> {
    try {
      this.avPlayer = await media.createAVPlayer();
      const context = getContext(this) as common.UIAbilityContext;
      const resourceMgr = context.resourceManager;
      const fdSrc: media.AVFileDescriptor = {
        fd: (await resourceMgr.getRawFd('sound.mp3')).fd,
        offset: 0,
        length: -1
      } as media.AVFileDescriptor;
      this.avPlayer.fdSrc = fdSrc;
    } catch (err) {
      console.error('AVPlayer creation failed: ' + JSON.stringify(err));
    }
  }

  aboutToDisappear(): void {
    if (this.avPlayer) {
      this.avPlayer.release();
      this.avPlayer = null;
    }
  }

  toggleHabit(index: number): void {
    animateTo({ duration: 300 }, () => {
      this.habits[index].completed = !this.habits[index].completed;
    });
    if (this.habits[index].completed && this.avPlayer !== null) {
      this.avPlayer.play().catch((err: Error) => {
        console.error('Audio play failed: ' + JSON.stringify(err));
      });
    }
  }

  refreshHabits(): void {
    this.refreshing = true;
    setTimeout((): void => {
      this.habits = this.habits.map((habit: Habit) => {
        return { name: habit.name, completed: false };
      });
      this.refreshing = false;
    }, 1000);
  }

  build() {
    Column() {
      Refresh({ refreshing: this.refreshing, onRefresh: () => this.refreshHabits() }) {
        List() {
          ForEach(this.habits, (habit: Habit, index: number) => {
            ListItem() {
              Row() {
                Text(habit.name)
                  .fontSize(18)
                  .margin({ right: 10 });
                Toggle({ type: ToggleType.Switch, isOn: habit.completed })
                  .onChange(() => this.toggleHabit(index));
              }
              .justifyContent(FlexAlign.SpaceBetween)
              .width('100%')
              .padding(10);
            }
          });
        }
        .width('100%')
        .height('100%');
      }
    }
    .width('100%')
    .height('100%')
    .padding(10);
  }
}

import { TextInput, Image, Column, Row, Text, Button, LoadingProgress } from '@ohos.arkui.advanced';
import image from '@ohos.multimedia.image';
import type { PixelMap } from '@ohos.multimedia.image';

@Entry
@Component
struct ImageCropper {
  @State widthInput: string = '';
  @State heightInput: string = '';
  @State originalImage: PixelMap | null = null;
  @State croppedImage: PixelMap | null = null;
  @State isLoading: boolean = false;
  @State errorMessage: string = '';

  build() {
    Column() {
      Row() {
        TextInput({ placeholder: 'Width' })
          .width('40%')
          .height(40)
          .onChange((value: string) => {
            this.widthInput = value;
          });
        TextInput({ placeholder: 'Height' })
          .width('40%')
          .height(40)
          .onChange((value: string) => {
            this.heightInput = value;
          });
      }
      .margin({ top: 20, bottom: 20 })

      Row() {
        if (this.originalImage) {
          Image(this.originalImage)
            .width(150)
            .height(150)
            .margin({ right: 20 });
        } else {
          Rectangle()
            .width(150)
            .height(150)
            .backgroundColor('#cccccc')
            .margin({ right: 20 });
        }

        if (this.croppedImage) {
          Image(this.croppedImage)
            .width(150)
            .height(150);
        }
      }
      .justifyContent(FlexAlign.Center)

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 10 });
      }

      Button('Crop Image')
        .width('80%')
        .height(40)
        .margin({ top: 20 })
        .onClick(() => {
          this.handleCrop();
        });

      if (this.isLoading) {
        LoadingProgress()
          .width(50)
          .height(50)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Start)
  }

  private async handleCrop(): Promise<void> {
    const width = parseInt(this.widthInput);
    const height = parseInt(this.heightInput);

    if (isNaN(width) || isNaN(height) || width <= 0 || height <= 0) {
      this.errorMessage = 'Invalid dimensions';
      return;
    }

    this.isLoading = true;
    this.errorMessage = '';

    try {
      await new Promise<void>(resolve => setTimeout(resolve, 1000));
      this.croppedImage = this.originalImage;
    } catch (error) {
      this.errorMessage = 'Failed to crop image';
    } finally {
      this.isLoading = false;
    }
  }
}

