@Entry
@Component
struct VideoStreamingApp {
  @State selectedVideo: VideoItem | null = null;
  @State abTestingEnabled: boolean = false;
  @State currentStep: number = 1;
  private videoController: media.VideoController = new media.VideoController();

  build() {
    Column() {
      if (this.selectedVideo == null) {
        Text('Video Streaming App')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .padding(16);

        Row() {
          Text('A/B Testing Mode')
            .fontSize(18)
