            .onChange((isOn: boolean) => {
              this.abTestingEnabled = isOn;
            });
        }
        .padding(16);

        Stepper({ current: this.currentStep, total: 3 })
          .onChange((current: number) => {
            this.currentStep = current;
          })
          .padding(16);

        Grid() {
          ForEach(videos, (video: VideoItem) => {
            GridItem() {
              Column() {
                Image($r('app.media.placeholder'))
                  .width(100)
                  .height(150)
                  .objectFit(ImageFit.Cover)
                  .margin({ bottom: 8 });

                Text(video.title)
                  .fontSize(18)
                  .fontWeight(FontWeight.Medium)
                  .padding({ bottom: 4 });

                Button('Play')
                  .onClick(() => {
                    this.selectedVideo = video;
                  })
                  .padding(10);
              }
              .padding(16);
            }
          });
        }
        .columnsTemplate('1fr 1fr')
        .rowsGap(16)
        .columnsGap(16)
        .padding(16);
      } else {
        media.Video({
          src: this.selectedVideo.url,
          controller: this.videoController
