import { Swiper } from '@ohos.arkui.advanced.Swiper';
import { LongPressGesture } from '@ohos.arkui.advanced.Gesture';
import { Tooltip } from '@ohos.arkui.advanced.Tooltip';
import { Color, FlexAlign, HorizontalAlign } from '@ohos.arkui.advanced.Drawing';
import { InputType } from '@ohos.arkui.advanced.Text';

interface Flashcard {
  question: string;
  answer: string;
}

@Entry
@Component
struct FlashcardApp {
  @State isAuthenticated: boolean = false;
  @State username: string = '';
  @State password: string = '';
  @State currentCardIndex: number = 0;
  @State showAnswer: boolean = false;

  private flashcards: Array<Flashcard> = [
    { question: "What is the capital of France?", answer: "Paris" },
    { question: "What is 2 + 2?", answer: "4" },
    { question: "What is the largest planet?", answer: "Jupiter" }
  ];

  private validateForm(): boolean {
    return this.username.trim() !== '' && this.password.trim() !== '';
  }

  private handleLogin() {
    if (this.validateForm()) {
      this.isAuthenticated = true;
    }
  }

  private handleLogout() {
    this.isAuthenticated = false;
    this.username = '';
    this.password = '';
  }

  private handleLongPress() {
    this.showAnswer = true;
  }

  private handleSwipe(direction: 'left' | 'right') {
    if (direction === 'left' && this.currentCardIndex < this.flashcards.length - 1) {
      this.currentCardIndex++;
    } else if (direction === 'right' && this.currentCardIndex > 0) {
      this.currentCardIndex--;
    }
    this.showAnswer = false;
  }

  build() {
    Column() {
      if (!this.isAuthenticated) {
        Column() {
          TextInput({ placeholder: "Username" })
            .onChange((value: string) => {
              this.username = value;
            })
            .margin({ bottom: 10 });

          TextInput({ placeholder: "Password", type: InputType.Password })
            .onChange((value: string) => {
              this.password = value;
            })
            .margin({ bottom: 10 });

          Button("Login")
            .onClick(() => {
              this.handleLogin();
            })
            .enabled(this.validateForm());
        }
        .padding(20)
        .width('80%');
      } else {
        Column() {
          Swiper({
            index: this.currentCardIndex,
            autoPlay: false,
            loop: false
          }) {
            ForEach(this.flashcards, (card: Flashcard, index: number) => {
              Column() {
                Tooltip({ content: "Long press to reveal answer" }) {
                  Text(card.question)
                    .fontSize(20)
                    .margin({ bottom: 20 });
                }

                if (this.showAnswer && index === this.currentCardIndex) {
                  Text(card.answer)
                    .fontSize(18)
                    .fontColor(Color.Blue);
                }
              }
              .width('90%')
              .height(200)
              .backgroundColor(Color.White)
              .shadow({ radius: 5, color: Color.Gray })
              .justifyContent(FlexAlign.Center)
              .alignItems(HorizontalAlign.Center)
              .gesture(
                LongPressGesture()
                  .onAction(() => {
                    this.handleLongPress();
                  })
                  .duration(1000)
              );
            });
          }
          .indicator(true)
          .onChange((index: number) => {
            this.currentCardIndex = index;
            this.showAnswer = false;
          });

          Button("Logout")
            .onClick(() => {
              this.handleLogout();
            })
            .margin({ top: 20 });
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

import { Gesture, DatePicker } from '@ohos.arkui.advancedUI';
import promptAction from '@ohos.promptAction';
import mediaquery from '@ohos.mediaquery';

interface DatePickerResult {
  year: number;
  month: number;
  day: number;
}

@Entry
@Component
struct TVPortraitApp {
  @State isPortrait: boolean = false;
  @State scaleValue: number = 1.0;
  @State selectedDate: string = '';
  private mediaQueryListener: mediaquery.MediaQueryListener = mediaquery.matchMediaSync('(orientation: portrait)');

  aboutToAppear() {
    const callback = (result: mediaquery.MediaQueryResult) => {
      this.isPortrait = result.matches;
    };
    this.mediaQueryListener.on('change', callback);
  }

  aboutToDisappear() {
    this.mediaQueryListener.off('change');
  }

  build() {
    Column() {
      if (this.isPortrait) {
        Column() {
          Gesture({
            onPinchUpdate: (event: GestureEvent) => {
              this.scaleValue = Math.max(0.5, Math.min(3.0, this.scaleValue * event.scale));
            }
          }) {
            Image($r('app.media.tv_portrait_placeholder'))
              .width(300)
              .height(300)
              .scale({ x: this.scaleValue, y: this.scaleValue });
          }

          DatePicker({
            start: new Date('1970-01-01'),
            end: new Date('2100-12-31'),
            selected: new Date()
          })
            .onChange((date: DatePickerResult) => {
              this.selectedDate = `${date.year}-${date.month}-${date.day}`;
              promptAction.showToast({ message: 'Date changed to: ' + this.selectedDate, duration: 2000 });
            });

          Text('Selected Date: ' + this.selectedDate)
            .fontSize(20)
            .margin({ top: 20 });
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center);
      } else {
        Column() {
          Text('Please switch to portrait mode for the best experience')
            .fontSize(24)
            .textAlign(TextAlign.Center)
            .width('100%')
            .height('100%');
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center);
      }
    }
    .width('100%')
    .height('100%');
  }
}

interface Note {
  id: number;
  content: string;
  priority: number;
}

@Entry
@Component
struct NoteApp {
  @State notes: Note[] = [];
  @State newNoteContent: string = '';
  @State newNotePriority: number = 1;

  build() {
    Column() {
      TextArea({ placeholder: 'Enter note content...', text: this.newNoteContent })
        .height(100)
        .width('90%')
        .onChange((value: string) => {
          this.newNoteContent = value;
        })
        .margin(10);

      Row() {
        Text('Priority:')
          .fontSize(16)
          .margin({ right: 10 });

        Stepper({
          index: this.newNotePriority - 1
        })
          .onChange((index: number) => {
            this.newNotePriority = index + 1;
          });
      }
      .margin(10);

      Button('Add Note')
        .onClick(() => {
          if (this.newNoteContent.trim()) {
            this.notes.push({
              id: Date.now(),
              content: this.newNoteContent,
              priority: this.newNotePriority
            });
            this.newNoteContent = '';
            this.newNotePriority = 1;
          }
        })
        .margin(10);

      Grid() {
        ForEach(this.notes, (note: Note) => {
          GridItem() {
            Column() {
              Text(note.content)
                .fontSize(16)
                .margin(5);
              Text(`Priority: ${note.priority}`)
                .fontSize(14)
                .fontColor(Color.Gray)
                .margin(5);
              Button('Delete')
                .onClick(() => {
                  this.notes = this.notes.filter(n => n.id !== note.id);
                })
                .margin(5);
            }
            .padding(10)
            .border({ width: 1, color: Color.Gray })
            .borderRadius(5)
            .width('100%');
          }
        });
      }
      .columnsTemplate('1fr 1fr')
      .rowsTemplate('1fr 1fr')
      .width('100%')
      .height('60%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

