import prompt from '@ohos.promptAction';

@Entry
@Component
struct CountdownTimer {
  @State private timeLeft: number = 60;
  @State private isRunning: boolean = false;
  private timerId: number | undefined = undefined;

  private startTimer() {
    if (!this.isRunning) {
      this.isRunning = true;
      this.timerId = setInterval(() => {
        if (this.timeLeft > 0) {
          this.timeLeft -= 1;
        } else {
          this.stopTimer();
        }
      }, 1000);
    }
  }

  private stopTimer() {
    this.isRunning = false;
    if (this.timerId !== undefined) {
      clearInterval(this.timerId);
      this.timerId = undefined;
    }
  }

  private resetTimer() {
    this.stopTimer();
    this.timeLeft = 60;
  }

  build() {
    Column({ space: 10 }) {
      Row({ space: 20 }) {
        Button('Start')
          .onClick(() => this.startTimer())
          .backgroundColor('#4caf50')
          .fontColor(Color.White)
          .padding(10)
          .margin(5)
          .borderRadius(5);

        Button('Stop')
          .onClick(() => this.stopTimer())
          .backgroundColor('#ff5722')
          .fontColor(Color.White)
          .padding(10)
          .margin(5)
          .borderRadius(5);

        Button('Reset')
          .onClick(() => this.resetTimer())
          .backgroundColor('#2196f3')
          .fontColor(Color.White)
          .padding(10)
          .margin(5)
          .borderRadius(5);
      }
      .justifyContent(FlexAlign.Center)
      .width('80%')
      .margin(10);

      Column() {
        Text(`${this.timeLeft} seconds`)
          .fontSize(24)
          .fontColor(Color.Black)
          .textAlign(TextAlign.Center)
          .padding(20);
      }
      .width('80%')
      .margin(10)
      .borderRadius(8)
      .backgroundColor('#f5f5f5')
      .padding(10);

      Progress({
        value: (60 - this.timeLeft) / 60 * 100
      })
      .width('80%')
      .height(10)
      .margin(10);

      Row({ space: 20 }) {
        Button('Mock')
          .onClick(() => {})
          .backgroundColor('#9c27b0')
          .fontColor(Color.White)
          .padding(10)
          .margin(5)
          .borderRadius(5);

        Button('Record')
          .onClick(() => {})
          .backgroundColor('#607d8b')
          .fontColor(Color.White)
          .padding(10)
          .margin(5)
          .borderRadius(5);
      }
      .justifyContent(FlexAlign.Center)
      .width('80%')
      .margin(10);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor('#ffffff');
  }
}

