import { Badge, Stepper, Button, Divider } from '@ohos.arkui.component';

@Entry
@Component
struct ProgressTracker {
  @State currentStep: number = 1
  private totalSteps: number = 4

  @Builder
  StepBadge(step: number) {
    Badge({
      count: step,
      position: 'rightTop'
    })
    .badgeStyle({ 
      color: this.currentStep >= step ? '#0000FF' : '#CCCCCC',
      fontSize: 16,
      size: 20
    }) {
      Image($r('app.media.step_placeholder'))
        .width(40)
        .height(40)
    }
  }

  build() {
    Column() {
      Row() {
        ForEach([1, 2, 3, 4], (step: number) => {
          Column() {
            this.StepBadge(step)
            Text(`Step ${step}`)
              .fontSize(16)
              .margin({ top: 10 })
              .accessibilityDescription(`Step ${step} of ${this.totalSteps}`)
          }

          if (step < this.totalSteps) {
            Divider()
              .width(50)
              .strokeWidth(2)
              .color(this.currentStep > step ? '#0000FF' : '#CCCCCC')
          }
        })
      }
      .margin({ top: 50, bottom: 50 })

      Stepper({
        index: this.currentStep,
        onValueChange: (newValue: number) => {
          this.currentStep = newValue
        }
      })
      .margin({ top: 20, bottom: 20 })

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentStep > 1) {
              this.currentStep--
            }
          })
          .margin({ right: 20 })
          .enabled(this.currentStep > 1)
          .accessibilityDescription('Go to previous step')

        Button('Next')
          .onClick(() => {
            if (this.currentStep < this.totalSteps) {
              this.currentStep++
            }
          })
          .enabled(this.currentStep < this.totalSteps)
          .accessibilityDescription('Go to next step')
      }
    }
    .width('100%')
    .padding(20)
    .margin({ top: 20, bottom: 20 })
  }
}

