import { Text, Button, Column, Row, List, ListItem, ForEach } from '@ohos.arkui.advanced';
import { TouchEvent } from '@ohos.multimodalinput.event';

@Entry
@Component
struct SocialMediaApp {
  @State currentLanguage: string = 'en';
  @State showLanguagePopup: boolean = false;
  @State swipeDirection: string = '';
  @State private touchStartX: number = 0;

  private translations: Record<string, Record<'greeting'|'settings'|'close'|'swipe_left'|'swipe_right', string>> = {
    'en': { 'greeting': 'Hello', 'settings': 'Settings', 'close': 'Close', 'swipe_left': 'Swiped Left', 'swipe_right': 'Swiped Right' },
    'es': { 'greeting': 'Hola', 'settings': 'Configuración', 'close': 'Cerrar', 'swipe_left': 'Deslizado a la Izquierda', 'swipe_right': 'Deslizado a la Derecha' }
  };

  private languages: string[] = ['en', 'es'];

  updateLanguage(language: string) {
    this.currentLanguage = language;
    this.showLanguagePopup = false;
  }

  detectSwipe(direction: string) {
    this.swipeDirection = this.translations[this.currentLanguage][direction];
  }

  build() {
    Column() {
      Row({ space: 10 }) {
        Text(this.translations[this.currentLanguage]['greeting'])
          .fontSize(24)
          .fontWeight('700');
        Button(this.translations[this.currentLanguage]['settings'])
          .onClick(() => {
            this.showLanguagePopup = true;
          });
      }
      .width('100%')
      .justifyContent('space-between')
      .padding(20);

      Column()
        .width('100%')
        .height(200)
        .backgroundColor('#f0f0f0')
        .onTouch((event: TouchEvent) => {
          if (event.type === 'down') {
            this.touchStartX = event.touches[0].x;
          }
          if (event.type === 'move') {
            const currentX = event.touches[0].x;
            if (currentX > this.touchStartX + 50) {
              this.detectSwipe('swipe_right');
            } else if (currentX < this.touchStartX - 50) {
              this.detectSwipe('swipe_left');
            }
          }
        });

      Text(this.swipeDirection)
        .fontSize(18)
        .margin({ top: 20 });

      if (this.showLanguagePopup) {
        Column() {
          List({ space: 10 }) {
            ForEach(this.languages, (language: string) => {
              ListItem() {
                Text(this.translations[language]['greeting'])
                  .onClick(() => {
                    this.updateLanguage(language);
                  });
              }
            });
          }
          .width('80%')
          .height(200);

          Button(this.translations[this.currentLanguage]['close'])
            .onClick(() => {
              this.showLanguagePopup = false;
            });
        }
        .width('100%')
        .height('100%')
        .backgroundColor('rgba(0, 0, 0, 0.5)')
        .justifyContent('center');
      }
    }
    .width('100%')
    .height('100%');
  }
}

