import { TimePicker, Column, Row, Text } from '@ohos.arkui.advanced';
import { RefreshContainer } from '@ohos.arkui.advanced';
import sensor from '@ohos.sensor';
import { BusinessError } from '@ohos.base';
import abilityAccessCtrl from '@ohos.abilityAccessCtrl';

interface TimePickerValue {
  hour: number
  minute: number
}

@Entry
@Component
struct TimePickerApp {
  @State selectedTime: Date = new Date()
  @State displayTime: string = ''
  @State validationMessage: string = ''
  @State isRefreshing: boolean = false
  private sensorId: number = 0
  private context = getContext(this)
  private sensorManager = sensor.getSensorManager()
  private accelerometer = this.sensorManager.getDefaultSensor(sensor.SensorType.SENSOR_TYPE_ACCELEROMETER)

  async aboutToAppear() {
    try {
      let atManager = abilityAccessCtrl.createAtManager()
      await atManager.requestPermissionsFromUser(this.context, ['ohos.permission.ACCELEROMETER'])
    } catch (err) {
      console.error('Failed to request permissions:', err.message)
    }
    this.updateDisplayTime()
    this.sensorId = this.setupSensor()
  }

  aboutToDisappear() {
    if (this.sensorId !== 0) {
      this.sensorManager.off(this.sensorId)
    }
  }

  private setupSensor(): number {
    try {
      return this.sensorManager.on(this.accelerometer, (data) => {
        if (data) {
          this.validateTime()
        }
      })
    } catch (error) {
      console.error('Sensor setup failed:', error.message)
      return 0
    }
  }

  validateTime() {
    const currentTime = new Date()
    if (this.selectedTime.getTime() < currentTime.getTime()) {
      this.validationMessage = 'Selected time is in the past!'
    } else {
      this.validationMessage = 'Time is valid!'
    }
  }

  updateDisplayTime() {
    this.displayTime = this.selectedTime.toLocaleTimeString()
  }

  onRefresh(): void {
    this.isRefreshing = true
    setTimeout(() => {
      this.isRefreshing = false
      this.validateTime()
    }, 1000)
  }

  build() {
    Column() {
      RefreshContainer({
        refreshing: this.isRefreshing,
        onRefresh: () => this.onRefresh()
      }) {
        Column() {
          Text('Time Picker')
            .fontSize(28)
            .fontWeight(FontWeight.Bold)
            .margin({ top: 20, bottom: 20 })

          Row() {
            TimePicker({
              selected: this.selectedTime
            })
              .onChange((value: TimePickerValue) => {
                const newTime = new Date(this.selectedTime)
                newTime.setHours(value.hour, value.minute)
                this.selectedTime = newTime
                this.updateDisplayTime()
                this.validateTime()
              })
              .margin({ bottom: 40 })
          }

          Column() {
            Text('Selected Time:')
              .fontSize(20)
              .fontWeight(FontWeight.Medium)
              .margin({ bottom: 8 })

            Text(this.displayTime)
              .fontSize(24)
              .fontWeight(FontWeight.Bold)
              .fontColor('#007AFF')

            Text(this.validationMessage)
              .fontSize(18)
              .margin({ top: 10 })
              .fontColor(this.validationMessage.includes('past') ? '#FF3B30' : '#34C759')
          }
          .padding(16)
          .borderRadius(12)
          .backgroundColor('#F0F0F0')
        }
        .width('100%')
        .height('100%')
        .padding(20)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

