import { Switch, Button, Progress, Text, Column, Row, Stack } from '@ohos.arkui.advanced';

@Entry
@Component
struct PDFViewer {
  @State isViewerEnabled: boolean = false
  @State currentPage: number = 1
  private totalPages: number = 10
  @State progressValue: number = 0.1

  build() {
    Column() {
      Row() {
        Text('Enable PDF Viewer')
          .fontSize(18)
          .margin({ right: 10 })
        Switch()
          .onChange((isOn: boolean) => {
            this.isViewerEnabled = isOn
          })
      }
      .margin({ top: 20, bottom: 20 })

      if (this.isViewerEnabled) {
        Column() {
          Text(`Page ${this.currentPage} of ${this.totalPages}`)
            .fontSize(16)
            .margin({ bottom: 10 })

          Progress({ value: this.progressValue })
            .width('80%')
            .height(8)
            .margin({ bottom: 20 })

          Row() {
            Button('Previous')
              .enabled(this.currentPage > 1)
              .onClick(() => {
                if (this.currentPage > 1) {
                  this.currentPage--
                  this.updateProgress()
                }
              })
              .margin({ right: 10 })

            Button('Next')
              .enabled(this.currentPage < this.totalPages)
              .onClick(() => {
                if (this.currentPage < this.totalPages) {
                  this.currentPage++
                  this.updateProgress()
                }
              })
          }
          .justifyContent('center')
          .margin({ bottom: 20 })

          Column() {
            Text('PDF Content Here')
              .fontSize(20)
              .textAlign('center')
          }
          .width('100%')
          .height(300)
          .backgroundColor('#f0f0f0')
        }
        .width('100%')
        .alignItems('center')
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }

  private updateProgress() {
    this.progressValue = this.currentPage / this.totalPages
  }
}

