@Entry
@Component
struct PerformanceMonitoringList {
  @State private perfStartTime: number = 0;
  @State private perfEndTime: number = 0;
  @State private perfDuration: number = 0;
  @State private perfLogs: string[] = [];
  @State private offsetX: number = 0;
  @State private isSwiped: boolean = false;

  private items: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4', 'Item 5'];

  private logPerformance(message: string) {
    this.perfLogs.push(`${new Date().toLocaleTimeString()}: ${message}`);
    if (this.perfLogs.length > 5) {
      this.perfLogs.shift();
    }
  }

  private startPerformanceTimer() {
    this.perfStartTime = Date.now();
    this.logPerformance('Performance timer started');
  }

  private endPerformanceTimer() {
    this.perfEndTime = Date.now();
    this.perfDuration = this.perfEndTime - this.perfStartTime;
    this.logPerformance(`Performance timer ended. Duration: ${this.perfDuration}ms`);
  }

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.items, (item: string) => {
          ListItem() {
            Stack({ alignContent: Alignment.Center }) {
              Column() {
                Text(item)
                  .fontSize(18)
                  .fontColor(Color.White)
                  .padding(10)
                  .backgroundColor(Color.Blue)
                  .borderRadius(5)
                  .width('100%')
                  .height(50)
              }
              .gesture(
                PanGesture({ direction: PanDirection.Horizontal })
                  .onActionStart(() => {
                    this.startPerformanceTimer();
                    this.isSwiped = false;
                  })
                  .onActionUpdate((event: GestureEvent) => {
                    this.offsetX = event.offsetX;
                  })
                  .onActionEnd(() => {
                    this.endPerformanceTimer();
                    if (this.offsetX > 50) {
                      this.isSwiped = true;
                      this.logPerformance('Swiped Right');
                    } else if (this.offsetX < -50) {
                      this.isSwiped = true;
                      this.logPerformance('Swiped Left');
                    }
                    animateTo({ duration: 300 }, () => {
                      this.offsetX = 0;
                    });
                  })
              )
              .transform({ translate: { x: this.offsetX } })
              .animation({ duration: 300 })
            }
          }
          .width('100%')
          .height(50)
        })
      }
      .width('100%')
      .height('60%')

      Column() {
        ForEach(this.perfLogs, (log: string) => {
          Text(log)
            .fontSize(12)
            .margin(5)
        })
      }
      .width('100%')
      .height('30%')
      .padding(10)
      .backgroundColor(Color.Gray)
    }
    .width('100%')
    .height('100%')
    .padding(10)
  }
}

