import { Column, Text, Button, Row, Slider, FontWeight, FlexAlign } from '@ohos.arkui.component';

@Entry
@Component
struct EncryptedDataVisualization {
  @State private currentPage: number = 0;
  private totalPages: number = 3;
  private encryptedData: number[][] = [
    [10, 20, 30, 40, 50],
    [15, 25, 35, 45, 55],
    [5, 15, 25, 35, 45]
  ];

  build() {
    Column() {
      Text('Encrypted Device Data Visualization')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Column() {
        ForEach(this.encryptedData[this.currentPage], (item: number, index: number) => {
          Row() {
            Text(`Value ${index + 1}: ${item}`)
              .fontSize(16)
              .margin({ right: 10 });
            Slider({ value: item, min: 0, max: 100, step: 1 })
              .width('80%')
              .height(20);
          }
          .width('100%')
          .margin({ bottom: 10 });
        });
      }
      .width('90%')
      .height(300)
      .border({ width: 1, color: '#cccccc' })
      .margin({ bottom: 20 });

      Row() {
        Button('Previous')
          .width('30%')
          .height(50)
          .fontSize(18)
          .enabled(this.currentPage > 0)
          .onClick(() => {
            if (this.currentPage > 0) {
              this.currentPage--;
            }
          });

        ForEach(Array.from({ length: this.totalPages }), (item: undefined, index: number) => {
          Button(index === this.currentPage ? '\\u25cf' : '\\u25cb')
            .width(30)
            .height(30)
            .fontSize(16)
            .backgroundColor(index === this.currentPage ? '#4CAF50' : '#cccccc')
            .onClick(() => {
              this.currentPage = index;
            });
        });

        Button('Next')
          .width('30%')
          .height(50)
          .fontSize(18)
          .enabled(this.currentPage < this.totalPages - 1)
          .onClick(() => {
            if (this.currentPage < this.totalPages - 1) {
              this.currentPage++;
            }
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceBetween)
      .margin({ bottom: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }
}

import { Image, Select, Grid, Button, Column, GridItem, ImageFit } from '@ohos.arkui.advanced';
import Resource from '@ohos.resourceManager';

@Entry
@Component
struct TravelPlanningApp {
  @State images: Resource[] = [
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon')
  ];

  @State selectedImage: Resource | null = null;
  @State filterOption: 'All' | 'Even' = 'All';

  get filteredImages(): Resource[] {
    if (this.filterOption === 'Even') {
      return this.images.filter((_, index) => index % 2 === 0);
    }
    return this.images;
  }

  build() {
    Column() {
      Select([
        { value: 'All', label: 'All' },
        { value: 'Even', label: 'Even' }
      ])
      .onSelect((value: string) => {
        this.filterOption = value as 'All' | 'Even';
      });

      Grid() {
        ForEach(this.filteredImages, (image: Resource, index: number) => {
          GridItem() {
            Image(image)
              .width('100%')
              .height('100%')
              .objectFit(ImageFit.Cover)
              .onClick(() => {
                this.selectedImage = image;
              });
          }
        }, (image: Resource, index: number) => index.toString());
      }
      .columnsTemplate('repeat(4, 1fr)')
      .columnsGap(10)
      .rowsGap(10);

      if (this.selectedImage) {
        Column() {
          Image(this.selectedImage)
            .width('100%')
            .height('100%')
            .objectFit(ImageFit.Cover);
          Button('Close')
            .margin(10)
            .backgroundColor('#FFFFFF')
            .onClick(() => {
              this.selectedImage = null;
            });
        }
        .width('100%')
        .height('100%')
        .position({ x: 0, y: 0 })
        .backgroundColor('#000000');
      }
    }
    .width('100%')
    .height('100%')
    .padding(10);
  }
}

import { Row, Column, Text, Image, Picker } from '@ohos.arkui.component';
import { PanGesture, GestureEvent } from '@ohos.arkui.gesture';

@Entry
@Component
struct PerformanceDashboard {
  @State renderTime: number = 0;
  @State memoryUsage: number = 0;
  @State fps: number = 0;
  @State selectedSensor: string = 'CPU';
  @State panelColor: string = '#4CAF50';
  @State panelPosition: number = 0;
  @State sensorOptions: string[] = ['CPU', 'GPU', 'Memory'];

  private timer: number = 0;

  aboutToAppear() {
    this.startMockDataUpdates();
  }

  aboutToDisappear() {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = 0;
    }
  }

  private startMockDataUpdates() {
    this.timer = setInterval(() => {
      this.renderTime = Math.floor(Math.random() * 100);
      this.memoryUsage = Math.floor(Math.random() * 1000);
      this.fps = Math.floor(Math.random() * 60) + 30;
    }, 1000);
  }

  private onPanStart(): void {
    this.panelColor = '#FF5722';
  }

  private onPanEnd(): void {
    this.panelColor = '#4CAF50';
  }

  private onPanMove(event: GestureEvent): void {
    this.panelPosition = event.offsetX;
  }

  build() {
    Column() {
      Text('Performance Monitoring Dashboard')
        .fontSize(24)
        .margin({ bottom: 20 });

      Row() {
        Text('Sensor:')
          .fontSize(18)
          .margin({ right: 10 });

        Picker({ options: this.sensorOptions })
          .selected(this.selectedSensor)
          .onChange((value: string) => {
            this.selectedSensor = value;
          })
          .margin({ bottom: 20 })
          .width(150)
          .height(40);
      }

      Column() {
        Text(`Render Time: ${this.renderTime} ms`)
          .fontSize(16)
          .padding(10)
          .borderRadius(20)
          .backgroundColor('#E1F5FE')
          .margin({ bottom: 10 });

        Text(`Memory Usage: ${this.memoryUsage} MB`)
          .fontSize(16)
          .padding(10)
          .borderRadius(20)
          .backgroundColor('#E8F5E9')
          .margin({ bottom: 10 });

        Text(`FPS: ${this.fps}`)
          .fontSize(16)
          .padding(10)
          .borderRadius(20)
          .backgroundColor('#FFF3E0')
          .margin({ bottom: 10 });
      }

      Column()
        .width('80%')
        .height(100)
        .backgroundColor(this.panelColor)
        .margin({ top: 20 })
        .gesture(
          PanGesture()
            .onActionStart(() => this.onPanStart())
            .onActionUpdate((event: GestureEvent) => this.onPanMove(event))
            .onActionEnd(() => this.onPanEnd())
        )
        .position({ x: this.panelPosition });
    }
    .padding(20)
    .width('100%')
    .height('100%');
  }
}

