import { Column, Row, Text, Image, List, ListItem, ForEach, TextInput, Button } from '@ohos.arkui.advanced';
import { State } from '@ohos.arkui.advanced';
import { FontWeight, FlexAlign, HorizontalAlign } from '@ohos.arkui.advanced';

@Entry
@Component
struct PodcastPlayer {
  @State currentTab: number = 0;
  @State isPlaying: boolean = false;
  @State progress: number = 0;
  @State messages: string[] = [];
  @State newMessage: string = '';

  simulatePlayback(): void {
    let interval = setInterval(() => {
      if (this.progress >= 100 || !this.isPlaying) {
        clearInterval(interval);
        return;
      }
      this.progress += 1;
    }, 100);
  }

  build() {
    Column() {
      Column() {
        if (this.currentTab === 0) {
          this.PodcastTab();
        } else if (this.currentTab === 1) {
          this.MessagesTab();
        } else {
          this.SettingsTab();
        }
      }
      .width('100%')
      .layoutWeight(1);

      Row() {
        Column() {
          Image($r('app.media.ic_podcast'))
            .width(30)
            .height(30);
          Text('Podcast')
            .fontSize(16)
            .fontColor(this.currentTab === 0 ? '#1698CE' : '#666666');
        }
        .width('33.33%')
        .onClick(() => this.currentTab = 0);

        Column() {
          Image($r('app.media.ic_message'))
            .width(30)
            .height(30);
          Text('Messages')
            .fontSize(16)
            .fontColor(this.currentTab === 1 ? '#1698CE' : '#666666');
        }
        .width('33.33%')
        .onClick(() => this.currentTab = 1);

        Column() {
          Image($r('app.media.ic_settings'))
            .width(30)
            .height(30);
          Text('Settings')
            .fontSize(16)
            .fontColor(this.currentTab === 2 ? '#1698CE' : '#666666');
        }
        .width('33.33%')
        .onClick(() => this.currentTab = 2);
      }
      .width('100%')
      .height(60)
      .backgroundColor('#FFFFFF')
      .border({ width: { top: 0.5 }, color: '#CCCCCC' });
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
    .focusable(true)
    .focusOnTouch(true)
    .defaultFocus(true);
  }

  @Builder PodcastTab() {
    Column() {
      Text('Current Podcast')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20 });

      Row() {
        Row()
          .width(`${this.progress}%`)
          .height(5)
          .backgroundColor('#1698CE');
      }
      .width('80%')
      .height(5)
      .backgroundColor('#CCCCCC')
      .margin({ top: 20, bottom: 20 });

      Button(this.isPlaying ? 'Pause' : 'Play')
        .width(100)
        .height(40)
        .onClick(() => {
          this.isPlaying = !this.isPlaying;
          if (this.isPlaying) {
            this.simulatePlayback();
          }
        });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }

  @Builder MessagesTab() {
    Column() {
      List() {
        ForEach(this.messages, (message: string) => {
          ListItem() {
            Text(message)
              .fontSize(18)
              .margin({ top: 10, bottom: 10 });
          };
        });
      }
      .width('100%')
      .layoutWeight(1);

      Row() {
        TextInput({ placeholder: 'Type a message', text: this.newMessage })
          .width('80%')
          .onChange((value: string) => {
            this.newMessage = value;
          });
        Button('Send')
          .width('20%')
          .onClick(() => {
            if (this.newMessage.trim() !== '') {
              this.messages.push(this.newMessage);
              this.newMessage = '';
            }
          });
      }
      .width('100%')
      .height(60);
    }
    .

import { Column, Text, Button, Row, Stack, Progress } from '@ohos.arkui.advanced.Components';
import { Gesture, PanGestureEvent } from '@ohos.arkui.advanced.Gesture';
import { FlexAlign, FontWeight, TextAlign } from '@ohos.arkui.advanced.Common';

@Entry
@Component
struct QuizApp {
  @State currentQuestionIndex: number = 0;
  @State selectedAnswer: string = '';
  @State showCompletion: boolean = false;
  @State filePickerVisible: boolean = false;
  @State fileSelected: boolean = false;

  private questions: Array<string> = ['Q1', 'Q2', 'Q3'];
  private answers: Array<Array<string>> = [['A1', 'A2'], ['B1', 'B2'], ['C1', 'C2']];
  private correctAnswers: Array<string> = ['A1', 'B2', 'C1'];

  onAnswerSelect(answer: string): void {
    this.selectedAnswer = answer;
  }

  onSubmit(): void {
    if (this.currentQuestionIndex < this.questions.length - 1) {
      this.currentQuestionIndex++;
      this.selectedAnswer = '';
    } else {
      this.showCompletion = true;
    }
  }

  onRestart(): void {
    this.currentQuestionIndex = 0;
    this.selectedAnswer = '';
    this.showCompletion = false;
  }

  onSwipe(event: PanGestureEvent): void {
    if (event.offsetX > 50) {
      this.filePickerVisible = true;
    }
  }

  onFileSelect(): void {
    this.fileSelected = true;
    setTimeout(() => {
      this.filePickerVisible = false;
      this.fileSelected = false;
    }, 1000);
  }

  build() {
    Stack() {
      Column() {
        if (!this.showCompletion) {
          Progress({ value: this.currentQuestionIndex + 1, total: this.questions.length })
            .width('90%')
            .height(10)
            .margin({ top: 20, bottom: 20 });

          Text(`Question ${this.currentQuestionIndex + 1}/${this.questions.length}`)
            .fontSize(16)
            .margin({ bottom: 10 });

          Text(this.questions[this.currentQuestionIndex])
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .textAlign(TextAlign.Center)
            .margin({ bottom: 40 })
            .padding({ left: 20, right: 20 });

          ForEach(this.answers[this.currentQuestionIndex], (answer: string) => {
            Row() {
              Button(answer)
                .width('80%')
                .height(50)
                .onClick(() => this.onAnswerSelect(answer))
                .backgroundColor(this.selectedAnswer === answer ? '#DDDDDD' : '#FFFFFF');
            }
            .width('100%')
            .justifyContent(FlexAlign.Center)
            .margin({ bottom: 10 });
          });

          Button('Submit')
            .width('80%')
            .height(50)
            .onClick(() => this.onSubmit())
            .enabled(this.selectedAnswer !== '');

          if (this.filePickerVisible) {
            Column() {
              Text('File Picker')
                .fontSize(20)
                .margin({ bottom: 20 });
              Button('Select File')
                .width('80%')
                .height(50)
                .onClick(() => this.onFileSelect());
            }
            .width('100%')
            .justifyContent(FlexAlign.Center)
            .backgroundColor(this.fileSelected ? '#DDDDDD' : '#FFFFFF');
          }
        } else {
          Text('Quiz Completed!')
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });
          Button('Restart')
            .width('80%')
            .height(50)
            .onClick(() => this.onRestart());
        }
      }
      .width('100%')
      .height('100%')
      .justifyContent(FlexAlign.Center)
      .gesture(
        Gesture.Pan()
          .onStart(() => {})
          .onUpdate((event: PanGestureEvent) => {
            if (event.offsetX > 50) {
              this.filePickerVisible = true;
            }
          })
          .onEnd(() => {})
      );
    }
  }
}

import { Tabs, TabContent, Swiper } from '@ohos.arkui.advanced';
import { Column, Row, Button, Text, Image } from '@ohos.arkui.advanced';
import { BarPosition, FlexAlign, FontWeight } from '@ohos.arkui.advanced';

@Entry
@Component
struct MapViewer {
  @State currentTab: number = 0
  @State currentMapIndex: number[] = [0, 0, 0]
  @State autoPlay: boolean = true

  private categories: string[] = ['Cities', 'Nature', 'Landmarks']
  private maps: string[][] = [
    ['city1', 'city2', 'city3'],
    ['nature1', 'nature2', 'nature3'],
    ['landmark1', 'landmark2', 'landmark3']
  ]
  private captions: string[][] = [
    ['City 1', 'City 2', 'City 3'],
    ['Nature 1', 'Nature 2', 'Nature 3'],
    ['Landmark 1', 'Landmark 2', 'Landmark 3']
  ]

  build() {
    Column() {
      Text('Map Viewer')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      Tabs({ barPosition: BarPosition.Start }) {
        ForEach(this.categories, (category: string, index: number) => {
          TabContent() {
            Column() {
              Swiper() {
                ForEach(this.maps[index], (map: string, mapIndex: number) => {
                  Image($r(`app.media.${map}`))
                    .borderRadius(16)
                    .width('100%')
                    .height(300)
                })
              }
              .index(this.currentMapIndex[index])
              .autoPlay(this.autoPlay)
              .interval(3000)
              .duration(500)
              .loop(true)
              .indicator(true)
              .onChange((index: number) => {
                this.currentMapIndex[index] = index
              })

              Text(this.captions[index][this.currentMapIndex[index]])
                .fontSize(18)
                .margin({ top: 10, bottom: 10 })

              Row() {
                Button('Previous')
                  .onClick(() => {
                    if (this.currentMapIndex[index] > 0) {
                      this.currentMapIndex[index]--
                    } else {
                      this.currentMapIndex[index] = this.maps[index].length - 1
                    }
                  })
                  .margin({ right: 10 })

                Button('Next')
                  .onClick(() => {
                    if (this.currentMapIndex[index] < this.maps[index].length - 1) {
                      this.currentMapIndex[index]++
                    } else {
                      this.currentMapIndex[index] = 0
                    }
                  })
              }
              .justifyContent(FlexAlign.Center)
              .margin({ top: 10, bottom: 20 })
            }
            .width('100%')
            .padding(16)
          }
          .tabBar(category)
        })
      }
      .width('100%')
      .height('100%')
    }
    .width('100%')
    .height('100%')
  }
}

interface Preferences {
  accessibility: boolean;
  fastestRoute: boolean;
  avoidTransfers: boolean;
}

interface Route {
  id: number;
  name: string;
  stops: Array<string>;
  duration: number;
}

@Entry
@Component
struct PublicTransportPlanner {
  @State preferences: Preferences = {
    accessibility: false,
    fastestRoute: true,
    avoidTransfers: false
  };

  @State routes: Array<Route> = [
    { id: 1, name: "Route A", stops: ["Stop 1", "Stop 2", "Stop 3"], duration: 15 },
    { id: 2, name: "Route B", stops: ["Stop 4", "Stop 5", "Stop 6"], duration: 20 },
    { id: 3, name: "Route C", stops: ["Stop 7", "Stop 8", "Stop 9"], duration: 25 }
  ];

  @State selectedRoute: number | null = null;

  togglePreference(key: string) {
    let updatedPrefs: Preferences = {
      accessibility: this.preferences.accessibility,
      fastestRoute: this.preferences.fastestRoute,
      avoidTransfers: this.preferences.avoidTransfers
    };
    if (key === "accessibility") updatedPrefs.accessibility = !updatedPrefs.accessibility;
    else if (key === "fastestRoute") updatedPrefs.fastestRoute = !updatedPrefs.fastestRoute;
    else if (key === "avoidTransfers") updatedPrefs.avoidTransfers = !updatedPrefs.avoidTransfers;
    this.preferences = updatedPrefs;
  }

  selectRoute(id: number) {
    this.selectedRoute = id;
  }

  build() {
    Column() {
      Text("Public Transport Planner")
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Text("Preferences:")
        .fontSize(18)
        .margin({ bottom: 10 });

      Row() {
        Text("Accessibility")
          .fontSize(16);
        Toggle({ type: ToggleType.Switch, isOn: this.preferences.accessibility })
          .onChange(() => this.togglePreference("accessibility"))
          .margin({ left: 10 });
      }
      .margin({ bottom: 10 });

      Row() {
        Text("Fastest Route")
          .fontSize(16);
        Toggle({ type: ToggleType.Switch, isOn: this.preferences.fastestRoute })
          .onChange(() => this.togglePreference("fastestRoute"))
          .margin({ left: 10 });
      }
      .margin({ bottom: 10 });

      Row() {
        Text("Avoid Transfers")
          .fontSize(16);
        Toggle({ type: ToggleType.Switch, isOn: this.preferences.avoidTransfers })
          .onChange(() => this.togglePreference("avoidTransfers"))
          .margin({ left: 10 });
      }
      .margin({ bottom: 20 });

      Text("Available Routes:")
        .fontSize(18)
        .margin({ bottom: 10 });

      List() {
        ForEach(this.routes, (route: Route) => {
          ListItem() {
            Column() {
              Text(route.name)
                .fontSize(16)
                .fontWeight(FontWeight.Bold);
              Text(`Duration: ${route.duration} mins`)
                .fontSize(14)
                .margin({ top: 5 });
              Text(`Stops: ${route.stops.join(", ")}`)
                .fontSize(14)
                .margin({ top: 5 });
            }
            .width('100%')
            .padding(10)
            .onClick(() => this.selectRoute(route.id));
          }
          .borderRadius(8)
          .backgroundColor(this.selectedRoute === route.id ? "#E3F2FD" : "#FFFFFF")
          .margin({ bottom: 10 });
        });
      }
      .width('100%')
      .height('40%')
