@Entry
@Component
struct SocialMediaFeedApp {
  @State private feedData: string[] = ['Post 1', 'Post 2', 'Post 3'];
  @State private showOnboarding: boolean = true;
  @State private currentSlide: number = 0;
  @State private timerId: number = -1;

  aboutToAppear() {
    this.timerId = setInterval(() => {
      this.feedData.push(`New Post ${this.feedData.length + 1}`);
      if (this.feedData.length > 10) {
        this.feedData.shift();
      }
    }, 5000);
  }

  aboutToDisappear() {
    if (this.timerId !== -1) {
      clearInterval(this.timerId);
    }
  }

  skipOnboarding() {
    this.showOnboarding = false;
  }

  nextSlide() {
    if (this.currentSlide < 2) {
      this.currentSlide++;
    } else {
      this.skipOnboarding();
    }
  }

  build() {
    Column() {
      if (this.showOnboarding) {
        Column() {
          Text(`Onboarding Slide ${this.currentSlide + 1}`)
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ top: 20 });

          Button('Next')
            .onClick(() => {
              this.nextSlide();
            })
            .margin({ top: 20 });
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center);
      } else {
        List() {
          ForEach(this.feedData, (post: string) => {
            ListItem() {
              Text(post)
                .fontSize(16)
                .padding(16)
                .backgroundColor('#f0f0f0')
                .width('100%');
            }
          });
        }
        .width('100%');
      }
    }
    .width('100%')
    .height('100%');
  }
}

import sensor from '@ohos.sensor.service';
import promptAction from '@ohos.promptAction';
import abilityAccessCtrl from '@ohos.abilityAccessCtrl';
import common from '@ohos.app.ability.common';

interface AccelerometerData {
  x: number;
  y: number;
  z: number;
}

@Entry
@Component
struct SensorDataMonitor {
  @State accelerometerData: AccelerometerData = { x: 0, y: 0, z: 0 };
  @State isLoading: boolean = false;

  aboutToAppear() {
    let context = getContext(this) as common.Context;
    let atManager = abilityAccessCtrl.createAtManager();
    atManager.requestPermissionsFromUser(context, ['ohos.permission.ACCELEROMETER'])
      .then(() => this.startSensor())
      .catch((err: Error) => console.error('Permission denied:', err));
  }

  onPageHide() {
    sensor.off(sensor.SensorId.ACCELEROMETER);
  }

  private startSensor(): void {
    try {
      sensor.on(sensor.SensorId.ACCELEROMETER,
        (data: sensor.AccelerometerResponse) => {
          this.accelerometerData = {
            x: data.x,
            y: data.y,
            z: data.z
          };
        }, { interval: 1000 });
    } catch (error) {
      console.error('Failed to start sensor:', error);
    }
  }

  private refreshData(): void {
    this.isLoading = true;
    setTimeout(() => {
      this.isLoading = false;
      promptAction.showToast({ message: 'Data refreshed', duration: 2000 });
    }, 1000);
  }

  build() {
    Column() {
      Text('Sensor Data Monitor')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row() {
        Text('X: ' + this.accelerometerData.x.toFixed(2))
          .fontSize(18)
          .margin({ right: 10 });
        Progress({ value: Math.abs(this.accelerometerData.x), total: 20 })
          .width(100)
          .height(10);
      }
      .margin({ bottom: 10 });

      Row() {
        Text('Y: ' + this.accelerometerData.y.toFixed(2))
          .fontSize(18)
          .margin({ right: 10 });
        Progress({ value: Math.abs(this.accelerometerData.y), total: 20 })
          .width(100)
          .height(10);
      }
      .margin({ bottom: 10 });

      Row() {
        Text('Z: ' + this.accelerometerData.z.toFixed(2))
          .fontSize(18)
          .margin({ right: 10 });
        Progress({ value: Math.abs(this.accelerometerData.z), total: 20 })
          .width(100)
          .height(10);
      }
      .margin({ bottom: 20 });

      Refresh({ refreshing: $$this.isLoading })
        .onRefreshing(() => {
          this.refreshData();
        }) {
        Column() {
          if (this.isLoading) {
            Stack() {
              Progress({ value: 50, total: 100 })
                .width(30)
                .height(30);
            }
            .width('100%')
            .height(100)
            .align(Alignment.Center);
          }
        }
        .width('100%')
        .height('100%');
      }
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

import promptAction from '@ohos.promptAction';
import { AlertDialog } from '@ohos.promptAction';

interface MoodEntry {
  date: string;
  mood: string;
}

@Entry
@Component
struct MoodTracker {
  @State currentMood: string = '';
  @State moodHistory: MoodEntry[] = [];
  @State refreshing: boolean = false;

  private moods: string[] = ['Happy', 'Excited', 'Neutral', 'Angry', 'Frustrated'];

  private showMoodSelection(): void {
    promptAction.showActionMenu({
      title: 'Select Your Mood',
      buttons: this.moods.map(mood => ({
        text: mood,
        color: '#000000'
      })),
      success: (index: number) => {
        this.currentMood = this.moods[index];
        AlertDialog.show({
          title: 'Mood Selected',
          message: `You selected: ${this.currentMood}`,
          buttons: [
            {
              text: 'Cancel',
              color: '#000000'
            },
            {
              text: 'Confirm',
              color: '#000000'
            }
          ],
          success: (buttonIndex: number) => {
            if (buttonIndex === 1) {
              this.moodHistory.push({
                date: new Date().toLocaleDateString(),
                mood: this.currentMood
              });
            }
          }
        });
      }
    });
  }

  private onRefresh(): void {
    this.refreshing = true;
    setTimeout(() => {
      this.refreshing = false;
    }, 1000);
  }

  build() {
    Column() {
      Text('Mood Tracker')
        .fontSize(24)
        .margin(20);

      Button('Select Mood')
        .onClick(() => this.showMoodSelection())
        .margin(20);

      if (this.currentMood) {
        Text(`Current Mood: ${this.currentMood}`)
          .fontSize(20)
          .margin(10);
      }

      Refresh({ refreshing: this.refreshing }) {
        List() {
          ForEach(this.moodHistory, (entry: MoodEntry) => {
            ListItem() {
              Row() {
                Text(entry.date)
                  .width('50%');
                Text(entry.mood)
                  .width('50%');
              }
              .padding(10);
            }
          });
        }
        .width('100%');
      }
      .onRefreshing(() => this.onRefresh())
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

