          .columnsGap(10)
          .padding(10)
        } else {
          Column() {
            ForEach(this.images, (image: Resource) => {
              Image(image)
                .width('100%')
                .aspectRatio(1)
                .objectFit(ImageFit.Cover)
                .borderRadius(5)
                .margin(5)
                .gesture(
