                    .onAction(() => {
                      this.selectedImage = image
                      this.showFullScreen = true
                    })
                )
            })
          }
          .padding(10)
        }
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

@Entry
@Component
struct JournalNewsReader {
  @State refreshing: boolean = false
  @State listData: string[] = ['News Item 1', 'News Item 2', 'News Item 3']
  @State selectedSegment: number = 0
  @State segments: string[] = ['Latest', 'Popular', 'Saved']

  build() {
    Column() {
      // SegmentedControl for navigation
      Row() {
        ForEach(this.segments, (segment: string, index: number) => {
          Button(segment)
            .width('33%')
            .height(50)
            .backgroundColor(this.selectedSegment === index ? '#007AFF' : '#F0F0F0')
            .fontColor(this.selectedSegment === index ? '#FFFFFF' : '#000000')
            .onClick(() => {
              this.selectedSegment = index
              // Simulate loading new data based on segment
              this.refreshing = true
              setTimeout(() => {
                this.listData = [`${segment} News 1`, `${segment} News 2`, `${segment} News 3`]
                this.refreshing = false
              }, 1000)
            })
        })
      }
      .width('100%')
      .margin({ top: 10 })

      // Refreshable List
      Column() {
        if (this.refreshing) {
          LoadingProgress()
            .width(50)
            .height(50)
            .margin({ top: 20 })
        } else {
          List() {
            ForEach(this.listData, (item: string) => {
              ListItem() {
                Text(item)
                  .fontSize(16)
                  .padding(16)
                  .backgroundColor('#FFFFFF')
                  .width('100%')
              }
            }, (item: string) => item)
          }
          .width('100%')
          .height('100%')
          .onScrollIndex((start: number) => {
            if (start === 0 && !this.refreshing) {
              this.refreshing = true
              setTimeout(() => {
                this.listData = [...this.listData, `New ${this.segments[this.selectedSegment]} News`]
                this.refreshing = false
              }, 1000)
            }
          })
        }
      }
      .width('100%')
      .height('100%')
    }
    .width('100%')
    .height('100%')
  }
}

