  @State count: number = 0
  @State refreshing: boolean = false
  @State refreshEnabled: boolean = true

  build() {
    Column() {
      // Toggle switch for refresh control
      Row() {
        Text('Enable Refresh:')
          .fontSize(16)
          .margin({ right: 10 })
        Toggle({ type: ToggleType.Switch, isOn: this.refreshEnabled })
          .onChange((isOn: boolean) => {
            this.refreshEnabled = isOn
          })
      }
      .margin({ top: 20, bottom: 20 })

      // Badge on a button
      Stack() {
        Button('Click Me')
          .width(150)
          .height(40)
          .fontSize(16)
          .onClick(() => {
            this.count++
          })

        if (this.count > 0) {
          Text(this.count.toString())
            .fontSize(12)
            .fontColor(Color.White)
            .backgroundColor(Color.Red)
            .borderRadius(10)
            .padding({ left: 6, right: 6, top: 2, bottom: 2 })
            .position({ x: '80%', y: '-20%' })
        }
      }
      .margin({ bottom: 20 })

      // Scrollable list with pull-to-refresh
      List() {
        ForEach([1, 2, 3, 4, 5], (item: number) => {
          ListItem() {
            Text('Item ' + item)
              .fontSize(16)
              .margin(10)
          }
        })
      }
      .onScrollIndex((start: number, end: number) => {
        if (this.refreshEnabled && start === 0 && this.refreshing === false) {
          this.refreshing = true
          setTimeout(() => {
            this.count++
            this.refreshing = false
          }, 2000)
        }
      })
      .scrollBar(BarState.Off)
      .edgeEffect(EdgeEffect.Spring)
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

@Entry
@Component
struct StopwatchApp {
  @State elapsedTime: number = 0
  @State isRunning: boolean = false
  private timerId: number = -1
  @State messages: string[] = ['Message 1', 'Message 2', 'Message 3']
  @State videoPlaceholders: string[] = ['video_placeholder1', 'video_placeholder2', 'video_placeholder3', 'video_placeholder4']

  build() {
    Column() {
      Text(this.formatTime(this.elapsedTime))
        .fontSize(40)
        .margin(20)

      Row() {
        Button(this.isRunning ? 'Stop' : 'Start')
          .onClick(() => {
            if (this.isRunning) {
              clearInterval(this.timerId)
            } else {
              this.timerId = setInterval(() => {
                this.elapsedTime += 1
              }, 10)
            }
            this.isRunning = !this.isRunning
          })
          .margin(10)

        Button('Reset')
          .onClick(() => {
            clearInterval(this.timerId)
            this.elapsedTime = 0
            this.isRunning = false
          })
          .margin(10)
      }

      Grid() {
        ForEach(this.videoPlaceholders, (video: string) => {
          GridItem() {
            Image($r(`app.media.${video}`))
              .width('100%')
              .aspectRatio(1)
              .objectFit(ImageFit.Cover)
          }
        })
      }
      .columnsTemplate('1fr 1fr')
      .rowsGap(10)
      .columnsGap(10)
      .padding(10)
      .width('100%')

      Column() {
        ForEach(this.messages, (message: string) => {
          Text(message)
            .fontSize(18)
            .margin(10)
        })
      }
      .width('100%')
      .margin(20)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }

  private formatTime(time: number): string {
    const minutes = Math.floor(time / 6000)
    const seconds = Math.floor((time % 6000) / 100)
    const centiseconds = time % 100
    return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}.${centiseconds.toString().padStart(2, '0')}`
  }
}

