import { Radio, Badge, BadgePosition } from '@ohos.arkui.component';
import Curve from '@ohos.animator';
import fs from '@ohos.file.fs';
import { BusinessError } from '@ohos.base';

@Entry
@Component
struct CurrencyConverter {
  @State selectedCurrency: string = 'USD';
  @State showBadge: boolean = false;
  @State saveStatus: string = '';

  private currencies: string[] = ['USD', 'EUR', 'GBP', 'JPY'];
  private filePath: string = 'currency_data.json';

  private async saveCurrencyToFile() {
    try {
      const file = await fs.open(this.filePath, fs.OpenMode.READ_WRITE | fs.OpenMode.CREATE);
      await fs.write(file.fd, JSON.stringify({ currency: this.selectedCurrency }));
      await fs.close(file.fd);
      this.saveStatus = 'Saved successfully!';
    } catch (error) {
      this.saveStatus = 'Error saving data!';
    }
  }

  private showConfirmationBadge() {
    this.showBadge = true;
    setTimeout(() => {
      this.showBadge = false;
    }, 1000);
  }

  build() {
    Column() {
      Text('Select Currency')
        .fontSize(24)
        .margin(20);

      Column() {
        ForEach(this.currencies, (currency: string) => {
          Radio({ value: currency, group: 'currencyGroup' })
            .checked(this.selectedCurrency === currency)
            .onChange((isChecked: boolean) => {
              if (isChecked) {
                this.selectedCurrency = currency;
                this.showConfirmationBadge();
              }
            })
            .margin(10);
        });
      }

      if (this.showBadge) {
        Badge({ count: 1, position: BadgePosition.RightTop })
          .value('Updated!')
          .animation({ duration: 300, curve: Curve.EaseInOut });
      }

      Button('Save')
        .onClick(() => {
          this.saveCurrencyToFile();
        })
        .margin(20)
        .width('50%');

      Text(this.saveStatus)
        .fontSize(16)
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }
}

