@CustomDialog
struct NoteTakingDialog {
  controller?: CustomDialogController;
  @State private noteText: string = '';
  @State private selectedDate: Date = new Date();

  private getLocalizedString(key: string): string {
    let result: string = key;
    try {
      const resourceManager = getContext().resourceManager;
      result = resourceManager.getStringSync($r('app.string.' + key).id);
    } catch (error) {
      console.error('Failed to get localized string for key: ' + key);
    }
    return result;
  }

  build() {
    Column() {
      Text(this.getLocalizedString('note_dialog_title'))
        .fontSize(20)
        .margin({ top: 10, bottom: 10 });

      TextInput({ placeholder: this.getLocalizedString('note_input_placeholder'), text: this.noteText })
        .height(60)
        .width('90%')
        .onChange((value: string) => {
          this.noteText = value;
        });

      DatePicker({
        start: new Date(1970, 0, 1),
        end: new Date(2100, 11, 31),
        selected: this.selectedDate,
      })
        .onDateChange((value: Date) => {
          this.selectedDate = value;
        })
        .margin({ top: 10, bottom: 10 });

      Row() {
        Button(this.getLocalizedString('cancel_button'))
          .onClick(() => {
            if (this.controller) {
              this.controller.close();
            }
          })
          .backgroundColor(0xffffff)
          .fontColor(Color.Black);

        Button(this.getLocalizedString('confirm_button'))
          .onClick(() => {
            if (this.controller) {
              promptAction.showToast({
                message: this.getLocalizedString('toast_success'),
                duration: 2000
              });
              this.controller.close();
            }
