@Entry
@Component
struct InventoryManager {
  @State private dataItems: string[] = Array.from<number, string>({length: 20}, (_, i) => `Item ${i + 1}`);
  @State private refreshing: boolean = false;
  @State private loading: boolean = false;

  private loadMoreItems(): void {
    if (this.loading) return;
    this.loading = true;
    setTimeout((): void => {
      const newItems = Array.from<number, string>({length: 10}, (_, i) => `Item ${this.dataItems.length + i + 1}`);
      this.dataItems = [...this.dataItems, ...newItems];
      this.loading = false;
    }, 1000);
  }

  private refreshItems(): void {
    if (this.refreshing) return;
    this.refreshing = true;
    setTimeout((): void => {
      this.dataItems = Array.from<number, string>({length: 20}, (_, i) => `Item ${i + 1}`);
      this.refreshing = false;
    }, 1000);
  }

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.dataItems, (item: string) => {
          ListItem() {
            Row() {
              Text('📦')
                .fontSize(20)
                .margin(10);
              Text(item)
                .fontSize(16)
                .margin(10);
            }
            .width('100%')
            .justifyContent(FlexAlign.Start);
          }
        }, (item: string) => item);
      }
      .onReachEnd(() => {
        this.loadMoreItems();
      })
      .width('100%')
      .height('100%');

      if (this.loading) {
        Row() {
          Text('Loading more items...')
            .fontSize(14)
            .margin(10);
        }
        .justifyContent(FlexAlign.Center);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F1F3F5');
  }
}

@Entry
@Component
struct MeditationTimer {
  @State currentStep: number = 0;
  private steps: string[] = ["Breathe In", "Hold", "Breathe Out", "Relax"];
  @State progress: number = 0;
  private timerId: number = -1;
  @State isRunning: boolean = false;
  @State errorMessage: string = "";

  aboutToDisappear() {
    if (this.timerId !== -1) {
      clearTimeout(this.timerId);
      this.timerId = -1;
    }
  }

  private startTimer() {
    if (this.timerId !== -1) {
      clearTimeout(this.timerId);
    }
    this.timerId = setTimeout(() => {
      if (this.currentStep < this.steps.length - 1) {
        this.currentStep++;
        this.progress = (this.currentStep / (this.steps.length - 1)) * 100;
        this.startTimer();
      } else {
        this.isRunning = false;
      }
    }, 5000);
  }

  private handleError() {
    this.errorMessage = "Meditation session paused due to an error. Please try again.";
    this.isRunning = false;
    if (this.timerId !== -1) {
      clearTimeout(this.timerId);
      this.timerId = -1;
    }
  }

  build() {
    Column({ space: 20 }) {
      Text("Meditation Timer")
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(16)
          .fontColor(Color.Red)
          .margin({ bottom: 20 });
      }

      Progress({ value: this.progress, total: 100 })
        .style({ strokeWidth: 10, scaleCount: 100, scaleWidth: 1 })
        .width('80%')
        .height(10)
        .backgroundColor(Color.Gray)
        .margin({ bottom: 20 });

      ForEach(this.steps, (step: string, index: number) => {
        Row() {
          Text(step)
            .fontSize(18)
            .fontColor(index === this.currentStep ? Color.Blue : index < this.currentStep ? Color.Green : Color.Gray)
            .margin({ right: 10 });
          if (index < this.currentStep) {
            Text("✓")
              .fontSize(18)
              .fontColor(Color.Green);
          }
        }
        .justifyContent(FlexAlign.Start)
        .width('90%')
        .margin({ bottom: 10 });
      });

      Row({ space: 20 }) {
        Button("Previous")
          .width(120)
          .height(50)
          .backgroundColor(Color.Blue)
          .onClick(() => {
            if (this.currentStep > 0) {
              this.currentStep--;
              this.progress = (this.currentStep / (this.steps.length - 1)) * 100;
            }
          })
          .enabled(this.currentStep > 0);

        Button(this.isRunning ? "Pause" : "Start")
          .width(120)
          .height(50)
          .backgroundColor(this.isRunning ? Color.Orange : Color.Green)
          .onClick(() => {
            if (this.isRunning) {
              clearTimeout(this.timerId);
              this.timerId = -1;
              this.isRunning = false;
            } else {
              this.isRunning = true;
              this.startTimer();
            }
          });

        Button("Next")
          .width(120)
          .height(50)
          .backgroundColor(Color.Blue)
          .onClick(() => {
            if (this.currentStep < this.steps.length - 1) {
              this.currentStep++;
              this.progress = (this.currentStep / (this.steps.length - 1)) * 100;
            }
          })
          .enabled(this.currentStep < this.steps.length - 1);
      }
      .justifyContent(FlexAlign.Center)
      .width('100%')
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

import { List, ListItem, Row, Column, Text, Switch } from '@ohos.arkui.advanced';
import { PinchGesture, animateTo, Curve } from '@ohos.arkui.advanced';

interface PinchEvent {
  scale: number;
  centerX: number;
  centerY: number;
  pinchStatus: number;
}

@Entry
@Component
struct TagListComponent {
  @State tags: string[] = ['Tag 1', 'Tag 2', 'Tag 3', 'Tag 4'];
  @State currentScale: number = 1.0;
  @State isZoomed: boolean = false;

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.tags, (tag: string) => {
          ListItem() {
            Row() {
              Text(tag)
                .fontSize(16)
                .fontColor('#000000')
                .margin({ right: 10 });

              Switch()
                .isOn(this.isZoomed)
                .onChange((isOn: boolean) => {
                  this.isZoomed = isOn;
                  animateTo({ duration: 300, curve: Curve.EaseInOut }, () => {
                    this.currentScale = isOn ? 1.5 : 1.0;
                  });
                });
            }
            .width('100%')
            .height(50)
            .justifyContent('space-between')
            .padding(10)
            .backgroundColor('#FFFFFF')
            .borderRadius(5)
            .gesture(
              PinchGesture()
                .onActionStart(() => {
                  console.info('Pinch gesture started');
                })
                .onActionUpdate((event: PinchEvent) => {
                  if (event.pinchStatus === 1) {
                    this.currentScale = Math.max(0.5, Math.min(2.0, event.scale));
                  }
                })
                .onActionEnd(() => {
                  animateTo({ duration: 300, curve: Curve.EaseInOut }, () => {
                    this.currentScale = this.isZoomed ? 1.5 : 1.0;
                  });
                })
            )
            .scale({ x: this.currentScale, y: this.currentScale });
          }
        });
      }
      .width('100%')
      .height('100%')
      .padding(10);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#D3D3D3');
  }
}

