                .height(50)
                .onChange((value: string) => {
                  this.title = value;
                  this.titleError = false;
                })
                .borderColor(this.titleError ? '#ff0000' : '#cccccc')
                .borderWidth(1);

              if (this.titleError) {
                Text('Title cannot be empty')
                  .fontSize(12)
                  .fontColor('#ff0000');
              }

              TextInput({ placeholder: 'Note content' })
                .width('100%')
                .height(100)
                .onChange((value: string) => {
                  this.content = value;
                  this.contentError = false;
                })
                .borderColor(this.contentError ? '#ff0000' : '#cccccc')
                .borderWidth(1);

              if (this.contentError) {
                Text('Content cannot be empty')
                  .fontSize(12)
                  .fontColor('#ff0000');
              }

              Button('Add Note')
                .width('100%')
                .height(50)
                .onClick(() => {
                  if (!this.title) {
                    this.titleError = true;
                  }
                  if (!this.content) {
                    this.contentError = true;
                  }
                  if (this.title && this.content) {
                    this.notes = [...this.notes, {
                      id: Date.now(),
                      title: this.title,
                      content: this.content,
                      expanded: false
                    }];
                    this.title = '';
                    this.content = '';
                  }
                });
            }
            .width('100%')
            .padding(10)
            .backgroundColor('#ffffff');
          }
          .width('100%')
          .height('100%')
          .backgroundColor('#f5f5f5');
        }
      }
      .width('100%')
      .height('100%');
    }
  }
}
