```typescript
import picker from '@ohos.file.picker';
import fs from '@ohos.file.fs';
import router from '@ohos.router';
import { BusinessError } from '@ohos.base';
import promptAction from '@ohos.promptAction';
import { TextDecoder, TextEncoder } from '@ohos.util';

class FileHandler {
  private fileUris: Array<string> = [];

  async openFilePicker(): Promise<void> {
    try {
      const filePicker = new picker.DocumentViewPicker();
      const result = await filePicker.select();
      this.fileUris = result;
    } catch (error: BusinessError) {
      promptAction.showToast({ message: 'Failed to open file picker' });
    }
  }

  async readFile(): Promise<string> {
    if (this.fileUris.length === 0) {
      return '';
    }

    try {
      const fileUri = this.fileUris[0];
      const file = await fs.open(fileUri, fs.OpenMode.READ_ONLY);
      const stat = await fs.stat(fileUri);
      const buf = new ArrayBuffer(stat.size);
      await fs.read(file.fd, buf);
      await fs.close(file.fd);
      const decoder = new TextDecoder();
      return decoder.decode(new Uint8Array(buf));
    } catch (error: BusinessError) {
      promptAction.showToast({ message: 'Failed to read file' });
      return '';
    }
  }

  async writeFile(content: string): Promise<void> {
    try {
      const filePicker = new picker.DocumentSavePicker();
      filePicker.save().then(async (uri) => {
        if (uri) {
          const file = await fs.open(uri, fs.OpenMode.WRITE_ONLY | fs.OpenMode.CREATE);
          const encoder = new TextEncoder();
          const data = encoder.encode(content);
          await fs.write(file.fd, data);
          await fs.close(file.fd);
          promptAction.showToast({ message: 'File saved successfully' });
        }
      });
    } catch (error: BusinessError) {
      promptAction.showToast({ message: 'Failed to save file' });
    }
  }
}

