import { SegmentedControl, Column, Row, Text, Button, Card, TextInput } from '@ohos.arkui.component';
import { FlexAlign, InputType } from '@ohos.arkui.advanced';
import { Color } from '@ohos.arkui.advanced';

@Entry
@Component
struct AuthComponent {
  @State currentTab: string = 'Login';
  @State username: string = '';
  @State password: string = '';
  @State email: string = '';
  @State usernameError: string = '';
  @State passwordError: string = '';
  @State emailError: string = '';

  clearErrors() {
    this.usernameError = '';
    this.passwordError = '';
    this.emailError = '';
  }

  build() {
    Column() {
      SegmentedControl({
        options: ['Login', 'Sign Up'],
        selected: 0
      })
        .onChange((index: number) => {
          this.currentTab = index === 0 ? 'Login' : 'Sign Up';
          this.clearErrors();
        })
        .margin({ top: 10, bottom: 20 });

      Card() {
        Column() {
          if (this.currentTab === 'Login') {
            this.buildLoginForm();
          } else {
            this.buildSignUpForm();
          }

          Button(this.currentTab === 'Login' ? 'Login' : 'Sign Up')
            .width('100%')
            .height(40)
            .margin({ top: 20 })
            .onClick(() => {
              if (this.validateForm()) {
                // Handle successful submission
              }
            });
        }
        .padding(20)
        .width('100%');
      }
      .width('90%')
      .margin({ left: 20, right: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }

  @Builder
  buildLoginForm() {
    Column() {
      Row() {
        Text('Username')
          .fontSize(16)
          .margin({ right: 10 })
          .width(80);
        TextInput()
          .placeholder('Enter username')
          .width('70%')
          .onChange((value: string) => {
            this.username = value;
          });
      }
      .margin({ bottom: 10 });

      if (this.usernameError) {
        Text(this.usernameError)
          .fontSize(12)
          .fontColor(Color.Red)
          .margin({ bottom: 10 });
      }

      Row() {
        Text('Password')
          .fontSize(16)
          .margin({ right: 10 })
          .width(80);
        TextInput()
          .placeholder('Enter password')
          .type(InputType.Password)
          .width('70%')
          .onChange((value: string) => {
            this.password = value;
          });
      }
      .margin({ bottom: 10 });

      if (this.passwordError) {
        Text(this.passwordError)
          .fontSize(12)
          .fontColor(Color.Red)
          .margin({ bottom: 10 });
      }
    };
  }

  @Builder
  buildSignUpForm() {
    Column() {
      this.buildLoginForm();

      Row() {
        Text('Email')
          .fontSize(16)
          .margin({ right: 10 })
          .width(80);
        TextInput()
          .placeholder('Enter email')
          .width('70%')
          .onChange((value: string) => {
            this.email = value;
          });
      }
      .margin({ bottom: 10 });

      if (this.emailError) {
        Text(this.emailError)
          .fontSize(12)
          .fontColor(Color.Red)
          .margin({ bottom: 10 });
      }
    };
  }

  validateForm(): boolean {
    this.clearErrors();
    let isValid = true;

    if (this.username.length < 3) {
      this.usernameError = 'Username must be at least 3 characters';
      isValid = false;
    }

    if (this.password.length < 6) {
      this.passwordError = 'Password must be at least 6 characters';
      isValid = false;
    }

    if (this.currentTab === 'Sign Up') {
      const emailRegex = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;
      if (!this.email) {
        this.emailError = 'Email is required';
        isValid = false;
      } else if (!emailRegex.test(this.email)) {
        this.emailError = 'Invalid email format';
        isValid = false;
      }
    }

    return isValid;
  }
}
