                  .height(100)
                  .margin(10)
                  .border({
                    width: this.currentVideoIndex === index ? 2 : 0,
                    color: Color.Red
                  })
              }
            })
          }
        }
      }
    }
    .width('100%')
    .height('100%')
  }
