@Entry
@Component
struct WaterTracker {
  @State totalGlasses: number = 8;
  @State completedGlasses: number = 0;
  @State glassStates: boolean[] = Array(this.totalGlasses).fill(false);
  @State startX: number = 0;

  private handleGlassToggle(index: number, checked: boolean): void {
    this.glassStates[index] = checked;
    this.completedGlasses = this.glassStates.filter(val => val).length;
  }

  build() {
    Column() {
      Progress({
        value: (this.completedGlasses / this.totalGlasses) * 100,
        type: ProgressType.Circular
      })
        .width(150)
        .height(150)
        .margin(20)

      Text(`Drink your water! ${this.completedGlasses}/${this.totalGlasses} glasses`)
        .fontSize(20)
        .margin(10)

      Scroll() {
        Column() {
          ForEach(this.glassStates, (isChecked: boolean, index: number) => {
            Row() {
              Checkbox()
                .selected(isChecked)
                .onChange((checked: boolean) => {
                  this.handleGlassToggle(index, checked);
                })
                .margin(10)

              Text(`Glass ${index + 1}`)
                .fontSize(18)
            }
            .justifyContent(FlexAlign.SpaceBetween)
            .width('100%')
            .padding(10)
            .gesture(
              PanGesture()
                .onActionStart((event: GestureEvent) => {
                  this.startX = event.offsetX;
                })
                .onActionUpdate((event: GestureEvent) => {
                  if (Math.abs(event.offsetX - this.startX) > 20) {
                    this.handleGlassToggle(index, !this.glassStates[index]);
                  }
                })
            )
          })
        }
        .width('100%')
      }
      .scrollBar(BarState.Off)
      .scrollable(ScrollDirection.Vertical)
      .width('100%')
      .height('60%')
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}
