import { SideBarContainer } from '@ohos.arkui.advanced';
import { Text, Column, Row, Button } from '@ohos.arkui.advanced';
import { Canvas } from '@ohos.arkui.graphics';
import { FontWeight } from '@ohos.arkui.common';

@Component
struct SalesAnalyticsDrawer {
  @State isDrawerOpen: boolean = false;
  @State salesData: number[] = [3500, 4500, 3000, 6000, 8000, 7500, 9000];
  @State categories: string[] = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  @State chartError: string = '';

  toggleDrawer() {
    this.isDrawerOpen = !this.isDrawerOpen;
  }

  validateChartData(): boolean {
    if (this.salesData.length !== this.categories.length) {
      this.chartError = 'Sales data and categories must have the same length';
      return false;
    }
    if (this.salesData.some(isNaN)) {
      this.chartError = 'Sales data contains invalid values';
      return false;
    }
    this.chartError = '';
    return true;
  }

  @Builder
  drawChart(ctx: CanvasRenderingContext2D) {
    const maxValue = Math.max(...this.salesData);
    const width = 300;
    const height = 200;
    const padding = 20;
    const chartWidth = width - 2 * padding;
    const chartHeight = height - 2 * padding;

    // Draw axes
    ctx.strokeStyle = '#000000';
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // Draw data points
    ctx.strokeStyle = '#007DFF';
    ctx.fillStyle = '#007DFF';
    ctx.beginPath();
    for (let i = 0; i < this.salesData.length; i++) {
      const x = padding + (i * chartWidth) / (this.salesData.length - 1);
      const y = height - padding - (this.salesData[i] / maxValue) * chartHeight;
      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
      ctx.arc(x, y, 3, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.stroke();
  }

  build() {
    Column() {
      Button('Show Analytics')
        .onClick(() => {
          this.toggleDrawer();
        })
        .margin(20);

      SideBarContainer({ isShow: this.isDrawerOpen }) {
        Column() {
          Row({ space: 10 }) {
            Text('Weekly Sales Analytics')
              .fontSize(20)
              .fontWeight(FontWeight.Bold);

            Button('\u00d7')
              .onClick(() => {
                this.toggleDrawer();
              })
              .width(40)
              .height(40);
          }
          .width('100%')
          .justifyContent('space-between')
          .padding(10);

          if (this.chartError) {
            Text(this.chartError)
              .fontColor('#FF0000')
              .margin(10);
          } else {
            Canvas(this.drawChart)
              .width('90%')
              .height(200)
              .margin({ top: 20, bottom: 20 });
          }
        }
        .width('80%')
        .height('100%')
        .backgroundColor('#F5F5F5')
        .padding(10);
      }
    }
    .width('100%')
    .height('100%');
  }
}
