import media from '@ohos.multimedia.media';
import { Refresh } from '@ohos.arkui.component';

interface AudioItem {
  id: string;
  name: string;
  duration: number;
  isPlaying: boolean;
  currentPosition: number;
}

@Entry
@Component
struct AudioPlayerComponent {
  @State audioFiles: Array<AudioItem> = [
    { id: '1', name: 'Audio 1', duration: 120, isPlaying: false, currentPosition: 0 },
    { id: '2', name: 'Audio 2', duration: 180, isPlaying: false, currentPosition: 0 },
    { id: '3', name: 'Audio 3', duration: 240, isPlaying: false, currentPosition: 0 }
  ];
  @State refreshing: boolean = false;
  private avPlayer?: media.AVPlayer;

  build() {
    Column() {
      Refresh({ refreshing: this.refreshing, onRefresh: () => { this.handleRefresh() } }) {
        List() {
          ForEach(this.audioFiles, (item: AudioItem) => {
            ListItem() {
              Row() {
                Column() {
                  Text(item.name)
                    .fontSize(16)
                    .fontWeight(FontWeight.Bold)

                  Slider({
                    value: item.currentPosition,
                    min: 0,
                    max: item.duration,
                    style: SliderStyle.OutSet
                  })
                  .onChange((value: number) => this.handleSliderChange(value, item.id))
                }
                .layoutWeight(1)

                Image(this.getPlayPauseIcon(item.isPlaying))
                  .width(30)
                  .height(30)
                  .margin(10)
                  .onClick(() => this.togglePlayPause(item))
              }
              .width('100%')
              .padding(10)
            }
          })
        }
        .width('100%')
        .height('100%')
      }
    }
    .width('100%')
    .height('100%')
  }

  private getPlayPauseIcon(isPlaying: boolean): Resource {
    return isPlaying ? $r('app.media.pause') : $r('app.media.play');
  }

  private togglePlayPause(item: AudioItem): void {
    const index = this.audioFiles.findIndex(audio => audio.id === item.id);
    if (index !== -1) {
      this.audioFiles[index].isPlaying = !this.audioFiles[index].isPlaying;
      this.audioFiles = [...this.audioFiles];
      this.handleAudioPlayback(this.audioFiles[index]);
    }
  }

  private async handleAudioPlayback(item: AudioItem): Promise<void> {
    if (!this.avPlayer) {
      this.avPlayer = await media.createAVPlayer();
      this.avPlayer.on('timeUpdate', (currentTime: number) => {
        const index = this.audioFiles.findIndex(audio => audio.id === item.id);
        if (index !== -1) {
          this.audioFiles[index].currentPosition = currentTime;
          this.audioFiles = [...this.audioFiles];
        }
      });
      this.avPlayer.on('error', (error: Error) => {
        console.error('Playback error:', error.message);
      });
    }

    if (item.isPlaying) {
      await this.avPlayer.play();
    } else {
      await this.avPlayer.pause();
    }
  }

  private handleSliderChange(value: number, id: string): void {
    const index = this.audioFiles.findIndex(item => item.id === id);
    if (index !== -1) {
      this.audioFiles[index].currentPosition = value;
      this.audioFiles = [...this.audioFiles];
      if (this.avPlayer) {
        this.avPlayer.seek(value);
      }
    }
  }

  private handleRefresh(): void {
    this.refreshing = true;
    setTimeout(() => {
      const newItem: AudioItem = {
        id: `${this.audioFiles.length + 1}`,
        name: `Audio ${this.audioFiles.length + 1}`,
        duration: Math.floor(Math.random() * 300) + 60,
        isPlaying: false,
        currentPosition: 0
      };
      this.audioFiles = [...this.audioFiles, newItem];
      this.refreshing = false;
    }, 1000);
  }
}
