import web from '@ohos.net.web';
import geolocation from '@ohos.geolocation';
import abilityAccessCtrl from '@ohos.abilityAccessCtrl';
import { Timeline, TimelineItem } from '@ohos.arkui.advanced';

interface Position {
  latitude: number;
  longitude: number;
  timestamp: number;
}

interface WebSocketMessage {
  type: string;
  data: Position | string;
}

@Entry
@Component
struct FoodDeliveryTracker {
  @State orderStatus: string = 'Order Placed';
  @State statuses: string[] = ['Order Placed', 'Preparing', 'Cooked', 'Out for Delivery', 'Delivered'];
  @State locations: Position[] = [];
  @State currentPosition: Position | null = null;
  @State socketStatus: string = 'Disconnected';
  @State showPermissionDialog: boolean = false;

  private webSocket: web.WebSocket | null = null;

  aboutToAppear(): void {
    this.requestLocationPermission();
    this.connectWebSocket();
  }

  async requestLocationPermission(): Promise<void> {
    try {
      const atManager = abilityAccessCtrl.createAtManager();
      const grantStatus = await atManager.requestPermissionsFromUser(
        globalThis.abilityContext,
        ['ohos.permission.LOCATION']
      );

      if (grantStatus.authResults[0] === 0) {
        this.startGeolocation();
      } else {
        this.showPermissionDialog = true;
      }
    } catch (err) {
      console.error('Permission request failed:', err);
      this.showPermissionDialog = true;
    }
  }

  startGeolocation(): void {
    geolocation.getCurrentLocation({
      success: (data) => {
        this.currentPosition = {
          latitude: data.latitude,
          longitude: data.longitude,
          timestamp: Date.now()
        };
        if (this.webSocket && this.webSocket.readyState === web.WebSocketReadyState.OPEN) {
          this.webSocket.send(JSON.stringify({
            type: 'locationUpdate',
            data: this.currentPosition
          }));
        }
      },
      fail: (err) => {
        console.error('Location error:', err);
      }
    });
  }

  connectWebSocket(): void {
    try {
      this.webSocket = new web.WebSocket('ws://your-delivery-service.com/tracking');
      this.socketStatus = 'Connecting';

      this.webSocket.on('open', () => {
        this.socketStatus = 'Connected';
        console.log('WebSocket connection established');
      });

      this.webSocket.on('message', (event: { data: string | ArrayBuffer }) => {
        const message: WebSocketMessage = JSON.parse(event.data.toString());
        if (message.type === 'statusUpdate') {
          this.orderStatus = message.data as string;
        } else if (message.type === 'locationUpdate') {
          this.locations.push(message.data as Position);
        }
      });

      this.webSocket.on('close', () => {
        this.socketStatus = 'Disconnected';
        console.log('WebSocket connection closed');
      });

      this.webSocket.on('error', (error: Error) => {
        this.socketStatus = 'Error';
        console.error('WebSocket error:', error);
      });
    } catch (error) {
      console.error('WebSocket initialization error:', error);
    }
  }

  onPermissionGranted(): void {
    this.showPermissionDialog = false;
    this.startGeolocation();
  }

  build() {
    Column() {
      Timeline() {
        ForEach(this.statuses, (status: string) => {
          TimelineItem() {
            Text(status)
              .fontSize(16)
              .fontColor(status === this.orderStatus ? '#FF4500' : '#666666')
              .margin({ left: 10 });
          }
        });
      }
      .width('90%')
      .margin({ top: 20 });

      Stack() {
        Column() {
          Text('Map View Placeholder')
            .fontSize(18)
            .textAlign(TextAlign.Center);
        }
        .width('100%')
        .height(200)
        .backgroundColor('#F0F0F0');
      }

      Row() {
        Text(`Status: ${this.orderStatus}`)
          .fontSize(16)
          .margin({ right: 10 });
        Text(`Socket: ${this.socketStatus}`)
          .fontSize(16);
      }
      .margin({ top: 20 });

      if (this.showPermissionDialog) {
        Button('Grant Location Permission')
          .onClick(() => this.onPermissionGranted())
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%');

