import fs from '@ohos.file.fs';
import picker from '@ohos.file.picker';
import { TextDecoder } from '@ohos.util';
import { SegmentedControl, Button, Scroll, Column, Row, Text, TextInput, ListItem } from '@ohos.arkui.component';
import { TouchEvent, TouchType } from '@ohos.multimodalInput.touchEvent';

interface Contact {
  name: string;
  phone: string;
}

@Entry
@Component
struct ContactManager {
  @State currentMode: number = 0;
  @State contacts: Array<Contact> = [];
  @State selectedFileUri: string = '';
  @State fileName: string = 'contacts.json';
  @State statusMessage: string = '';
  @State showStatus: boolean = false;
  @State isSuccess: boolean = false;

  private async importContacts(): Promise<void> {
    try {
      let filePicker = new picker.DocumentPicker();
      let result = await filePicker.select();
      if (result && result.length > 0) {
        this.selectedFileUri = result[0].uri;
        let file = fs.openSync(this.selectedFileUri, fs.OpenMode.READ_ONLY);
        let stat = fs.statSync(this.selectedFileUri);
        let buffer = new ArrayBuffer(stat.size);
        fs.readSync(file.fd, buffer);
        fs.closeSync(file);
        let decoder = new TextDecoder();
        let content = decoder.decode(new Uint8Array(buffer));
        let parsedContacts = JSON.parse(content);

        if (!Array.isArray(parsedContacts)) {
          throw new Error('Invalid contacts format');
        }

        let validContacts: Array<Contact> = [];
        for (let contact of parsedContacts) {
          if (contact.name && contact.phone) {
            validContacts.push({
              name: contact.name.toString(),
              phone: contact.phone.toString()
            });
          }
        }

        if (validContacts.length === 0) {
          throw new Error('No valid contacts found');
        }

        this.contacts = validContacts;
        this.showStatusMessage('Contacts imported successfully', true);
      }
    } catch (err) {
      this.showStatusMessage(`Import failed: ${err.message}`, false);
    }
  }

  private async exportContacts(): Promise<void> {
    try {
      if (this.contacts.length === 0) {
        throw new Error('No contacts to export');
      }

      let filePicker = new picker.DocumentPicker();
      filePicker.saveName = this.fileName;
      let result = await filePicker.save();
      if (!result) {
        return;
      }

      let jsonStr = JSON.stringify(this.contacts);
      let file = fs.openSync(result, fs.OpenMode.CREATE | fs.OpenMode.READ_WRITE);
      fs.writeSync(file.fd, jsonStr);
      fs.closeSync(file);
      this.showStatusMessage('Contacts exported successfully', true);
    } catch (err) {
      this.showStatusMessage(`Export failed: ${err.message}`, false);
    }
  }

  private showStatusMessage(message: string, success: boolean): void {
    this.statusMessage = message;
    this.isSuccess = success;
    this.showStatus = true;
    setTimeout(() => {
      this.showStatus = false;
    }, 3000);
  }

  private handleTouch(event: TouchEvent): void {
    if (event.type === TouchType.DOWN) {
      console.log('Touch event detected');
    }
  }

  build() {
    Column() {
      SegmentedControl({ selected: this.currentMode })
        .onChange((index: number) => {
          this.currentMode = index;
        })
        .options(['Import', 'Export']);

      if (this.currentMode === 0) {
        Column() {
          Button('Select JSON File')
            .onClick(() => this.importContacts())
            .margin(10)
            .fontSize(16);

          if (this.contacts.length > 0) {
            Scroll() {
              Column() {
                ForEach(this.contacts, (contact: Contact) => {
                  ListItem() {
                    Row() {
                      Text(contact.name)
                        .fontSize(16)
                        .margin({ right: 10 });
                      Text(contact.phone)
                        .fontSize(16);
                    }
                  }
                  .borderRadius(5)
                  .margin(5);
                });
              }
            }
            .height('60%')
            .onTouch((event: TouchEvent) => this.handleTouch(event));
          }
