import http from '@ohos.net.http';
import router from '@ohos.router';
import { webview } from '@ohos.web.webview';
import { Stepper, StepperItem } from '@ohos.arkui.advanced';
import { Column, Text, Image, Button } from '@ohos.arkui.advanced';
import { FontWeight, TextAlign, FlexAlign, Color, ImageFit } from '@ohos.arkui.advanced';

interface Article {
  title: string;
  description: string;
  url: string;
  urlToImage: string;
}

interface NewsApiResponse {
  articles: Article[];
}

@Component
struct NewsReader {
  @State articles: Array<Article> = [];
  @State currentIndex: number = 0;
  @State loading: boolean = false;
  @State error: string = '';
  private timer: number = 0;
  private httpRequest: http.HttpRequest = http.createHttp();

  aboutToAppear(): void {
    this.fetchNews();
    this.startAutoRefresh();
  }

  aboutToDisappear(): void {
    if (this.timer) {
      clearInterval(this.timer);
    }
    this.httpRequest.destroy();
  }

  startAutoRefresh(): void {
    this.timer = setInterval(() => {
      this.fetchNews();
    }, 30000);
  }

  async fetchNews(): Promise<void> {
    this.loading = true;
    this.error = '';
    try {
      const response = await this.httpRequest.request(
        'https://newsapi.org/v2/top-headlines',
        {
          method: http.RequestMethod.GET,
          header: {
            'Content-Type': 'application/json'
          }
        }
      );
      if (response.responseCode === 200) {
        const result = JSON.parse(response.result) as NewsApiResponse;
        this.articles = result.articles || [];
      } else {
        this.error = 'Failed to fetch news';
      }
    } catch (err) {
      this.error = 'Network error occurred';
    } finally {
      this.loading = false;
    }
  }

  navigateToArticle(url: string): void {
    router.pushUrl({
      url: 'pages/WebViewPage',
      params: { url: url }
    });
  }

  build() {
    Column() {
      if (this.loading) {
        Text('Loading...')
          .fontSize(30)
          .fontWeight(FontWeight.Bold);
      } else if (this.error) {
        Text(this.error)
          .fontSize(30)
          .fontColor(Color.Red);
      } else {
        Stepper({
          index: this.currentIndex,
          onChange: (index: number) => {
            this.currentIndex = index;
          }
        }) {
          ForEach(this.articles, (article: Article) => {
            StepperItem() {
              Column() {
                if (article.urlToImage) {
                  Image(article.urlToImage)
                    .width('100%')
                    .height(300)
                    .objectFit(ImageFit.Cover);
                }
                Text(article.title)
                  .fontSize(36)
                  .fontWeight(FontWeight.Bold)
                  .margin({ top: 20, bottom: 10 })
                  .textAlign(TextAlign.Center);
                Text(article.description)
                  .fontSize(24)
                  .margin({ bottom: 20 })
                  .textAlign(TextAlign.Center);
                Button('Read Full Article')
                  .width(300)
                  .height(60)
                  .fontSize(24)
                  .margin({ bottom: 20 })
                  .onClick(() => {
                    this.navigateToArticle(article.url);
                  });
              }
              .width('100%')
              .padding(20);
            }
          });
        }
        .responsive(false)
        .indicatorStyle({ size: 20, color: Color.Blue });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

@Component
struct WebViewPage {
  @State url: string = '';
  private controller: webview.WebviewController = new webview.WebviewController();

  onPageShow(): void {
    const params = router.getParams() as { url: string };
    this.url = params?.url || '';
  }

  build() {
    Column() {
      webview.Web({
        src: this.url,
        controller: this.controller
      })
      .width('100%')
      .height('100%');
    }
  }
}
