import { Column, Text, Button, Stack } from '@ohos.arkui.advanced';
import { Swiper } from '@ohos.arkui.advanced';
import { TimePicker } from '@ohos.arkui.advanced';
import { FlexAlign } from '@ohos.arkui.common';
import { PanGesture } from '@ohos.arkui.gesture';
import { Curve } from '@ohos.arkui.animation';
import { Color } from '@ohos.arkui.graphics';

@Entry
@Component
struct BottomSheetExample {
  @State isVisible: boolean = false;
  @State selectedTime: Date = new Date(0, 0, 0, 12, 0);
  @State offsetY: number = 1000;

  build() {
    Column() {
      Button('Toggle BottomSheet')
        .onClick(() => {
          this.isVisible = !this.isVisible;
          this.offsetY = this.isVisible ? 0 : 1000;
        })

      Stack() {
        if (this.isVisible) {
          Column() {
            Column() {
              Swiper() {
                Column() {
                  Text('Slide 1 Content')
                    .fontSize(20)
                }
                .width('100%')
                .height('100%')
                .justifyContent(FlexAlign.Center)

                Column() {
                  Text('Slide 2 Content')
                    .fontSize(20)
                }
                .width('100%')
                .height('100%')
                .justifyContent(FlexAlign.Center)

                Column() {
                  TimePicker({
                    selected: this.selectedTime
                  })
                  .onChange((value: { hour: number, minute: number }) => {
                    this.selectedTime = new Date(0, 0, 0, value.hour, value.minute);
                  })
                }
                .width('100%')
                .height('100%')
                .justifyContent(FlexAlign.Center)
              }
              .height('100%')

              Button('Close')
                .onClick(() => {
                  this.isVisible = false;
                  this.offsetY = 1000;
                })
            }
            .height('60%')
            .width('100%')
            .backgroundColor(Color.White)
            .borderRadius(16)
            .margin({ top: 20 })
            .gesture(
              PanGesture()
                .onActionUpdate((event: { offsetY: number }) => {
                  if (event.offsetY > 20) {
                    this.isVisible = false;
                    this.offsetY = 1000;
                  }
                })
            )
          }
          .position({ x: 0, y: this.offsetY })
          .animation({
            duration: 300,
            curve: Curve.EaseOut
          })
          .gesture(
            PanGesture()
              .onActionUpdate((event: { offsetY: number }) => {
                if (event.offsetY > 0) {
                  this.offsetY = event.offsetY;
                }
              })
              .onActionEnd(() => {
                if (this.offsetY > 100) {
                  this.isVisible = false;
                  this.offsetY = 1000;
                } else {
                  this.offsetY = 0;
                }
              })
          )
        }
      }
      .width('100%')
      .height('100%')
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

