import refresher from '@ohos.pullToRefresh';
import { PinchGesture } from '@ohos.multimodalinput.gesture';
import emitter from '@ohos.events.emitter';
import common from '@ohos.app.ability.common';

interface SleepData {
  day: string;
  duration: number;
  quality: number;
}

@Entry
@Component
struct SleepTracker {
  @State sleepData: Array<SleepData> = [];
  @State refreshState: refresher.RefreshState = refresher.RefreshState.Inactive;
  @State currentScale: number = 1.0;
  private eventEmitter: emitter.EventEmitter = emitter.getDefault();

  aboutToAppear(): void {
    this.generateMockData();
  }

  generateMockData(): void {
    const newData: SleepData[] = [];
    for (let i = 1; i <= 7; i++) {
      newData.push({
        day: 'Day ' + i,
        duration: Math.floor(Math.random() * 7) + 1,
        quality: Math.floor(Math.random() * 5) + 1
      });
    }
    this.sleepData = newData;
  }

  onRefresh(): void {
    this.refreshState = refresher.RefreshState.Refreshing;
    setTimeout(() => {
      this.generateMockData();
      this.eventEmitter.emit('dataUpdated', {});
      this.refreshState = refresher.RefreshState.Inactive;
    }, 1500);
  }

  build() {
    Column() {
      refresher.Refresh({ state: this.refreshState, onRefresh: () => this.onRefresh() }) {
        Stack()
          .gesture(
            PinchGesture()
              .onActionStart(() => {})
              .onActionUpdate((event: { scale: number }) => {
                let newScale = this.currentScale * event.scale;
                newScale = Math.max(0.8, Math.min(1.5, newScale));
                this.currentScale = newScale;
              })
              .onActionEnd(() => {})
          )
          .scale({ x: this.currentScale, y: this.currentScale })
          .width('100%')
          .height('100%')
        {
          Column() {
            Text('Sleep Tracker').fontSize(20).margin(10)
            Row() {
              ForEach(this.sleepData, (item: SleepData) => {
                Column() {
                  Text(item.day).fontSize(12)
                  Stack() {
                    Column()
                      .width(20)
                      .height(item.duration * 20)
                      .backgroundColor('#4CAF50')
                      .margin({ right: 5 })
                    Column()
                      .width(20)
                      .height(item.quality * 10)
                      .backgroundColor('#2196F3')
                  }
                  .width(50)
                  .height(150)
                  .align(Alignment.Bottom)
                }
                .margin(5)
              })
            }
            .justifyContent(FlexAlign.SpaceAround)
            .width('100%')
          }
        }
      }
    }
    .width('100%')
    .height('100%')
    .onAppear(() => {
      this.eventEmitter.on('dataUpdated', (event: common.CommonEvent) => {
        this.sleepData = [...this.sleepData];
      });
    })
  }
}

import { Column, Row, Button, Text, Image, Divider, Stack } from '@ohos.arkui.component';
import common from '@ohos.app.ability.common';
import { Scroller } from '@ohos.arkui.component';

interface FileItem {
  name: string;
  type: string;
}

interface FileSystemItem extends FileItem {
  children?: FileSystemItem[];
}

@Entry
@Component
struct CustomFilePicker {
  @State showPicker: boolean = false;
  @State currentPath: string[] = ['Root'];
  @State selectedFile: FileItem | null = null;

  private readonly fileSystem: FileSystemItem[] = [
    {
      name: 'Root',
      type: 'folder',
      children: [
        { 
          name: 'Documents', 
          type: 'folder', 
          children: [
            { name: 'report.pdf', type: 'file' },
            { name: 'presentation.pptx', type: 'file' }
          ]
        },
        { 
          name: 'Images', 
          type: 'folder', 
          children: [
            { name: 'vacation.jpg', type: 'file' },
            { name: 'profile.png', type: 'file' }
          ]
        },
        { 
          name: 'Music', 
          type: 'folder', 
          children: [] 
        }
      ]
    }
  ];

  private openPicker(): void {
    this.showPicker = true;
  }

  private closePicker(): void {
    this.showPicker = false;
    this.selectedFile = null;
  }

  private navigateTo(path: string[]): void {
    this.currentPath = path;
  }

  private selectFile(file: FileItem): void {
    this.selectedFile = file;
  }

  private getCurrentDirectoryItems(): FileSystemItem[] {
    let currentDir = this.fileSystem[0];
    for (let i = 1; i < this.currentPath.length; i++) {
      const nextDir = currentDir.children?.find(child => child.name === this.currentPath[i]);
      if (nextDir) {
        currentDir = nextDir;
      }
    }
    return currentDir.children || [];
  }

  build() {
    Column() {
      Button('Open File Picker')
        .onClick(() => this.openPicker());

      if (this.showPicker) {
        Stack() {
          // Overlay
          Column()
            .width('100%')
            .height('100%')
            .backgroundColor('#00000033')
            .onClick(() => this.closePicker());

          // ActionSheet Content
          Column() {
            // Breadcrumb
            Row() {
              ForEach(this.currentPath, (segment: string, index: number) => {
                Text(segment)
                  .onClick(() => {
                    this.navigateTo(this.currentPath.slice(0, index + 1));
                  });
                if (index < this.currentPath.length - 1) {
                  Text(' > ')
                    .margin({ left: 4, right: 4 });
                }
              });
            }
            .padding(12)
            .width('100%');

            Divider();

            // File List
            Scroller() {
              Column() {
                ForEach(this.getCurrentDirectoryItems(), (item: FileSystemItem) => {
                  Row()
                    .width('100%')
                    .padding(12)
                    .onClick(() => {
                      if (item.type === 'folder') {
                        this.navigateTo([...this.currentPath, item.name]);
                      } else {
                        this.selectFile(item as FileItem);
                      }
                    })
                    {
                      Image($r('app.media.icon'))
                        .width(24)
                        .height(24)
                        .margin({ right: 12 });
                      Text(item.name);
                    }
                });
              }
            }

            Divider();

            // Action Buttons
            Row() {
              Button('Cancel')
                .onClick(() => this.closePicker());
              Button('Select')
                .enabled(this.selectedFile !== null)
                .onClick(() => {
                  console.log('File selected:', this.selectedFile);
                  this.closePicker();
                });
            }
            .justifyContent('space-between')
            .width('100%')
            .padding(12);
          }
          .width('100%')
          .height('50%')
          .backgroundColor('#FFFFFF')
          .borderRadius(8);
        }
      }
    }
  }
}

