import window from '@ohos.window';
import { Tooltip } from '@ohos.arkui.Tooltip';
import { LongPressGesture } from '@ohos.arkui.Gesture';
import { Button, Column, Text } from '@ohos.arkui.BasicComponents';
import { Placement, FlexAlign } from '@ohos.arkui.Common';
import common from '@ohos.app.ability.common';

@Entry
@Component
struct TooltipDemo {
  @State isPortrait: boolean = true;
  @State showTooltip: boolean = false;
  @State tooltipContent: string = 'Loading...';
  @State showMarquee: boolean = false;

  aboutToAppear() {
    const context = getContext(this) as common.UIAbilityContext;
    window.getLastWindow(context).then((win: window.Window) => {
      const properties = win.getWindowProperties();
      this.isPortrait = properties.windowRect.width < properties.windowRect.height;
    });
  }

  loadContent() {
    setTimeout(() => {
      this.tooltipContent = 'This is the lazy loaded content...';
      this.showMarquee = true;
    }, 1000);
  }

  build() {
    Column() {
      Column() {
        Button('Show Tooltip')
          .onClick(() => {
            this.showTooltip = true;
            this.loadContent();
          })
          .gesture(
            LongPressGesture({ repeat: false })
              .onAction(() => {
                this.showTooltip = true;
                this.loadContent();
              })
          );
      }
      .width('100%')
      .height('100%')
      .justifyContent(FlexAlign.Center);

      Column() {
        Text(this.tooltipContent)
          .fontSize(this.isPortrait ? 14 : 18)
          .tooltip({
            content: this.tooltipContent,
            placement: Placement.Bottom
          })
          .tooltipShow(this.showTooltip)
          .onTooltipVisibilityChange((visible: boolean) => {
            this.showTooltip = visible;
            if (!visible) {
              this.tooltipContent = 'Loading...';
              this.showMarquee = false;
            }
          })
          .tooltipArrow(true)
          .tooltipAutoCancel(true);
      }
      .width(this.isPortrait ? '100%' : '60%')
      .height(this.isPortrait ? '30%' : '100%');
    }
  }
}
