  private restaurantData: Restaurant[] = [
    { id: 1, name: 'Dragon Palace', cuisine: 'Chinese', price: '$$', distance: 1.2 },
    { id: 2, name: 'Pasta Place', cuisine: 'Italian', price: '$$$', distance: 0.8 },
    { id: 3, name: 'Taco Fiesta', cuisine: 'Mexican', price: '$', distance: 2.5 },
    { id: 4, name: 'Sushi Heaven', cuisine: 'Japanese', price: '$$$$', distance: 3.1 },
    { id: 5, name: 'Spice Garden', cuisine: 'Indian', price: '$$', distance: 1.7 },
    { id: 6, name: 'Golden Dragon', cuisine: 'Chinese', price: '$$$', distance: 4.2 },
    { id: 7, name: 'Pizza Palace', cuisine: 'Italian', price: '$$', distance: 2.0 }
  ];

  @State filteredData: Restaurant[] = this.restaurantData;
  @State selectedCuisine: string = 'All';
  @State selectedPrice: string = 'All';
  @State selectedDistance: number = 10;
  @State refreshing: boolean = false;

  private cuisineOptions: string[] = ['All', 'Chinese', 'Italian', 'Mexican', 'Japanese', 'Indian'];
  private priceOptions: string[] = ['All', '$', '$$', '$$$', '$$$$'];
  private distanceOptions: DistanceOption[] = [
    { value: 1, label: '1km' },
    { value: 3, label: '3km' },
    { value: 5, label: '5km' },
    { value: 10, label: '10km' }
  ];

  private filterRestaurants(): void {
    this.filteredData = this.restaurantData.filter(restaurant => {
      const cuisineMatch = this.selectedCuisine === 'All' || restaurant.cuisine === this.selectedCuisine;
      const priceMatch = this.selectedPrice === 'All' || restaurant.price === this.selectedPrice;
      const distanceMatch = restaurant.distance <= this.selectedDistance;
      return cuisineMatch && priceMatch && distanceMatch;
    });
  }

  private onRefresh(): void {
    this.refreshing = true;
    setTimeout(() => {
      this.refreshing = false;
      this.filterRestaurants();
    }, 1000);
  }

  build() {
    Column() {
      Column() {
        Row() {
          Select({ options: this.cuisineOptions })
            .selected(this.selectedCuisine)
            .onSelect((index: number) => {
              this.selectedCuisine = this.cuisineOptions[index];
              this.filterRestaurants();
            })
            .margin(8)

          Select({ options: this.priceOptions })
            .selected(this.selectedPrice)
            .onSelect((index: number) => {
              this.selectedPrice = this.priceOptions[index];
              this.filterRestaurants();
            })
            .margin(8)

          Select({ options: this.distanceOptions.map(item => item.label) })
            .selected(this.distanceOptions.findIndex(item => item.value === this.selectedDistance))
            .onSelect((index: number) => {
              this.selectedDistance = this.distanceOptions[index].value;
              this.filterRestaurants();
            })
            .margin(8)
        }
        .justifyContent(FlexAlign.SpaceAround)
        .width('100%')
      }

      Refresh({ refreshing: this.refreshing, onRefresh: () => this.onRefresh() }) {
        List({ space: 10 }) {
          ForEach(this.filteredData, (item: Restaurant) => {
            ListItem() {
              Column() {
                Text(item.name)
                  .fontSize(18)
                  .fontWeight(FontWeight.Bold)
                Row() {
                  Text(`Cuisine: ${item.cuisine}`)
                    .margin({ right: 10 })
                  Text(`Price: ${item.price}`)
                    .margin({ right: 10 })
                  Text(`Distance: ${item.distance}km`)
                }
                .margin({ top: 5 })
              }
              .padding(10)
            }
          })
        }

