import { Carousel, Text, Row, Column, Stack, Blank } from '@ohos.arkui.advanced';
import { FontWeight, TextAlign, FlexAlign } from '@ohos.arkui.common';

@Entry
@Component
struct CustomTabs {
  @State currentIndex: number = 0
  @State tabIndicatorX: number = 0
  private tabWidth: number = 100
  private tabTitles: string[] = ['Tab A', 'Tab B', 'Tab C']
  private tabContents: string[] = ['Content for Tab A', 'Content for Tab B', 'Content for Tab C']

  aboutToAppear() {
    this.updateTabWidth()
  }

  updateTabWidth() {
    this.tabWidth = 100
  }

  build() {
    Column() {
      Row() {
        ForEach(this.tabTitles, (title: string, index: number) => {
          Stack() {
            Text(title)
              .fontSize(16)
              .fontWeight(this.currentIndex === index ? FontWeight.Bold : FontWeight.Normal)
              .fontColor(this.currentIndex === index ? '#0000FF' : '#808080')
              .onClick(() => {
                this.currentIndex = index
                this.tabIndicatorX = index * this.tabWidth
              })
              .width(this.tabWidth)
              .height(48)
              .textAlign(TextAlign.Center)

            if (this.currentIndex === index) {
              Blank()
                .height(2)
                .width(this.tabWidth * 0.8)
                .backgroundColor('#0000FF')
                .position({ x: this.tabWidth * 0.1, y: 46 })
            }
          }
        })
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceAround)

      Carousel() {
        ForEach(this.tabContents, (content: string) => {
          Column() {
            Text(content)
              .fontSize(24)
              .margin({ top: 20 })
          }
          .width('100%')
          .height('100%')
          .justifyContent(FlexAlign.Center)
        })
      }
      .autoPlay(false)
      .loop(false)
      .onChange((index: number) => {
        this.currentIndex = index
        this.tabIndicatorX = index * this.tabWidth
      })
      .width('100%')
      .height(200)
    }
    .onAreaChange(() => {
      this.updateTabWidth()
    })
  }
}
