import promptAction from '@ohos.promptAction';
import { SegmentedControl } from '@ohos.arkui.native';
import { Rating } from '@ohos.arkui.native';
import { PanGesture, GestureEvent } from '@ohos.multimodalInput.gesture';

@Entry
@Component
struct TravelPlanningComponent {
  @State currentIndex: number = 0;
  @State ratingValue: number = 3;
  private panX: number = 0;
  private startX: number = 0;

  @Builder
  PlanningTab() {
    Column() {
      Text('Travel Planning Content')
        .fontSize(20)
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
  }

  @Builder
  BookingTab() {
    Column() {
      Text('Booking Information')
        .fontSize(20)
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
  }

  @Builder
  SharingTab() {
    Column() {
      Rating({ rating: this.ratingValue, indicator: true })
        .stars(5)
        .stepSize(1)
        .onChange((value: number) => {
          this.ratingValue = value
        })
        .margin({ top: 20 })

      Button('Share Travel Plan')
        .onClick(() => {
          try {
            promptAction.showToast({
              message: 'Check out my travel plan!',
              duration: 2000
            })
          } catch (error) {
            console.error('Sharing failed:', error)
          }
        })
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
  }

  build() {
    Column() {
      SegmentedControl({
        selected: this.currentIndex,
        options: ['Planning', 'Booking', 'Sharing']
      })
      .onChange((index: number) => {
        this.currentIndex = index
      })
      .margin({ top: 10, bottom: 10 })

      Stack() {
        if (this.currentIndex === 0) {
          this.PlanningTab()
        }
        if (this.currentIndex === 1) {
          this.BookingTab()
        }
        if (this.currentIndex === 2) {
          this.SharingTab()
        }
      }
      .width('100%')
      .height('80%')
      .gesture(
        PanGesture()
          .onActionStart((event: GestureEvent) => {
            this.startX = event.offsetX
          })
          .onActionUpdate((event: GestureEvent) => {
            this.panX = event.offsetX - this.startX
          })
          .onActionEnd(() => {
            if (this.panX < -100 && this.currentIndex < 2) {
              this.currentIndex++
            } else if (this.panX > 100 && this.currentIndex > 0) {
              this.currentIndex--
            }
            this.panX = 0
          })
      )
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

