    .height('100%')
    .backgroundColor(this.highContrast ? Color.Black : Color.White)
  }

  startMarqueeAnimation() {
    animateTo({
      duration: 10000 / this.marqueeSpeed,
      iterations: -1
    }, () => {
      this.translateX = -1000
    })
  }
