import { AlertDialog } from '@ohos.arkui.advanced';
import common from '@ohos.app.ability.common';
import resourceManager from '@ohos.resourceManager';

interface NewsItem {
  title: string;
  content: string;
  date: string;
}

@Entry
@Component
struct NewsReader {
  @State newsItems: Array<NewsItem> = [
    {
      title: 'News Title 1',
      content: 'Detailed content for news item 1 goes here. This is a sample news article.',
      date: '2023-10-01'
    },
    {
      title: 'News Title 2',
      content: 'Detailed content for news item 2 goes here. This is another sample news article.',
      date: '2023-10-02'
    }
  ]

  @State selectedLanguage: string = 'en'
  @State showDialog: boolean = false
  @State dialogContent: string = ''

  aboutToAppear() {
    this.loadStrings()
  }

  loadStrings() {
    try {
      const context = getContext(this) as common.Context;
      resourceManager.getStringArray(context.resourceManager, 'news_items').then((result: Array<string>) => {
        if (result && result.length > 0) {
          this.newsItems = result.map((item: string) => {
            const parts = item.split('|')
            return {
              title: parts[0] || '',
              content: parts[1] || '',
              date: parts[2] || ''
            }
          })
        }
      }).catch((err: Error) => {
        console.error('Failed to load strings: ' + err.message)
      })
    } catch (err) {
      console.error('Failed to load strings: ' + (err as Error).message)
    }
  }

  changeLanguage() {
    this.selectedLanguage = this.selectedLanguage === 'en' ? 'zh' : 'en'
    this.loadStrings()
  }

  showNewsContent(content: string) {
    this.dialogContent = content
    this.showDialog = true
  }

  @Builder
  dialogBuilder() {
    AlertDialog({
      title: 'News Content',
      message: this.dialogContent,
      confirm: {
        value: 'OK',
        action: () => {
          this.showDialog = false
        }
      }
    })
  }

  build() {
    Column() {
      Button(this.selectedLanguage === 'en' ? 'Switch to Chinese' : '切换到英文')
        .onClick(() => this.changeLanguage())
        .margin(10)

      Scroll() {
        Column() {
          ForEach(this.newsItems, (item: NewsItem) => {
            Column() {
              Text(item.title)
                .fontSize(20)
                .margin({ top: 10, bottom: 5 })
              Text(item.date)
                .fontSize(14)
                .fontColor(0x999999)
                .margin({ bottom: 10 })
            }
            .width('100%')
            .padding(10)
            .borderRadius(5)
            .backgroundColor(0xF5F5F5)
            .onClick(() => this.showNewsContent(item.content))
          })
        }
        .width('100%')
      }

      if (this.showDialog) {
        this.dialogBuilder()
      }
    }
    .width('100%')
    .height('100%')
  }
}
