import { sensor } from '@ohos.sensor';
import { Stack, Text, Divider } from '@ohos.arkui.components';
import { ResourceColor, Color } from '@ohos.arkui';

@Component
struct AdaptiveDivider {
  @State orientation: string = 'Default';
  @State dividerColor: ResourceColor = Color.Black;
  @State dividerThickness: number = 2;

  aboutToAppear() {
    sensor.on(sensor.SensorId.ORIENTATION, (data: sensor.OrientationResponse) => {
      if (data.value[0] > 45 || data.value[0] < -45) {
        this.orientation = 'Landscape';
        this.dividerColor = Color.Red;
        this.dividerThickness = 4;
      } else if (Math.abs(data.value[0]) <= 45) {
        this.orientation = 'Portrait';
        this.dividerColor = Color.Blue;
        this.dividerThickness = 3;
      } else {
        this.orientation = 'Default';
        this.dividerColor = Color.Black;
        this.dividerThickness = 2;
      }
    });
  }

  aboutToDisappear() {
    sensor.off(sensor.SensorId.ORIENTATION);
  }

  build() {
    Stack() {
      Text(this.orientation)
        .fontSize(20)
        .margin({ bottom: 10 })
      Divider()
        .color(this.dividerColor)
        .strokeWidth(this.dividerThickness)
    }
    .width('100%')
    .padding(20)
    .margin({ left: 0, right: 0 })
  }
}

