import cryptoFramework from '@ohos.security.cryptoFramework';
import { Slider, Button, Column, Row, Text } from '@ohos.arkui.component';
import { PinchGesture } from '@ohos.arkui.gesture';
import { GcmParamsSpec } from '@ohos.security.cryptoFramework';
import { SliderStyle } from '@ohos.arkui.component';

@Entry
@Component
struct CountdownTimer {
  @State timerValue: number = 30;
  @State remainingTime: number = 0;
  @State isRunning: boolean = false;
  @State timerTextScale: number = 1.0;
  @State encryptedValue: string = '';
  private timerId: number = 0;
  private cryptoAlg: cryptoFramework.SymKey | null = null;
  private iv: Uint8Array = new Uint8Array(12);
  private aad: Uint8Array = new Uint8Array(16);

  async aboutToAppear() {
    await this.initCrypto();
  }

  async initCrypto() {
    try {
      let symKeyGenerator = cryptoFramework.createSymKeyGenerator('AES256');
      let keyBlob: cryptoFramework.DataBlob = {
        data: new Uint8Array(32)
      };
      this.cryptoAlg = await symKeyGenerator.convertKey(keyBlob);
      this.iv = new Uint8Array(12);
      cryptoFramework.createRandom(12).then((random) => {
        this.iv = random;
      });
      cryptoFramework.createRandom(16).then((random) => {
        this.aad = random;
      });
    } catch (err) {
      console.error('Crypto init failed: ' + err.message);
    }
  }

  encryptTimerValue(): void {
    try {
      let cipher = cryptoFramework.createCipher('AES256|GCM|PKCS7');
      let gcmParams: GcmParamsSpec = {
        iv: this.iv,
        aad: this.aad
      };
      cipher.init(cryptoFramework.CryptoMode.ENCRYPT_MODE, this.cryptoAlg as cryptoFramework.SymKey, gcmParams);
      let input: cryptoFramework.DataBlob = {
        data: new TextEncoder().encode(this.timerValue.toString())
      };
      cipher.doFinal(input).then((output: cryptoFramework.DataBlob) => {
        this.encryptedValue = Array.from(output.data, (b: number) => 
          b.toString(16).padStart(2, '0')
        ).join('');
      });
    } catch (err) {
      console.error('Encryption failed: ' + err.message);
    }
  }

  startTimer(): void {
    if (this.isRunning) return;
    this.isRunning = true;
    this.remainingTime = this.timerValue;
    this.encryptTimerValue();
    this.timerId = setInterval(() => {
      if (this.remainingTime > 0) {
        this.remainingTime--;
      } else {
        this.stopTimer();
      }
    }, 1000) as unknown as number;
  }

  pauseTimer(): void {
    if (!this.isRunning) return;
    this.isRunning = false;
    clearInterval(this.timerId);
  }

  resetTimer(): void {
    this.pauseTimer();
    this.remainingTime = this.timerValue;
    this.encryptTimerValue();
  }

  stopTimer(): void {
    this.pauseTimer();
    this.remainingTime = 0;
  }

  build() {
    Column() {
      Text('Countdown Timer')
        .fontSize(24)
        .margin({ bottom: 20 });

      Slider({
        value: this.timerValue,
        min: 0,
        max: 120,
        step: 1,
        style: SliderStyle.OutSet
      })
      .onChange((value: number) => {
        this.timerValue = value;
        this.remainingTime = value;
        this.encryptTimerValue();
      })
      .width('90%')
      .margin({ bottom: 20 });

      Text(`${this.remainingTime} seconds`)
        .fontSize(40 * this.timerTextScale)
        .margin({ bottom: 20 })
        .gesture(
          PinchGesture()
            .onActionStart(() => {})
            .onActionUpdate((event: { scale: number }) => {
              this.timerTextScale = event.scale;
            })
            .onActionEnd(() => {})
        );

      Text(`Encrypted: ${this.encryptedValue}`)
        .fontSize(16)
        .margin({ bottom: 20 });

      Row() {
        Button('Start')
          .onClick

