            }
            .onClick(() => {
              this.selectedEntry = item;
            });
          });
        }
        .layoutWeight(1);
      }

      if (this.isDrawerOpened) {
        this.DrawerBuilder();
      }
    }
    .width('100%')
    .height('100%')
  }
}

