import { Column, Row, Text, Button, TextInput, InputType, FlexAlign } from '@ohos.arkui.node';

@Entry
@Component
struct EmailClient {
  @State email: string = '';
  @State password: string = '';
  @State emailError: string = '';
  @State passwordError: string = '';
  @State isLoggedIn: boolean = false;
  @State counter: number = 0;

  validateEmail(): void {
    if (!this.email.includes('@')) {
      this.emailError = 'Invalid email address';
    } else {
      this.emailError = '';
    }
  }

  validatePassword(): void {
    if (this.password.length < 6 && this.password.length > 0) {
      this.passwordError = 'Password must be at least 6 characters';
    } else {
      this.passwordError = '';
    }
  }

  handleLogin(): void {
    if (this.emailError === '' && this.passwordError === '' && this.email !== '' && this.password !== '') {
      this.isLoggedIn = true;
    }
  }

  handleLogout(): void {
    this.isLoggedIn = false;
    this.email = '';
    this.password = '';
    this.emailError = '';
    this.passwordError = '';
    this.counter = 0;
  }

  increment(): void {
    this.counter += 1;
  }

  decrement(): void {
    this.counter -= 1;
  }

  build() {
    Column() {
      if (!this.isLoggedIn) {
        Column() {
          TextInput({ placeholder: 'Email' })
            .width('90%')
            .height(50)
            .margin({ top: 20 })
            .type(InputType.Normal)
            .onChange((value: string) => {
              this.email = value;
              this.validateEmail();
            });

          if (this.emailError) {
            Text(this.emailError)
              .width('90%')
              .fontColor('#ff0000')
              .margin({ top: 5 });
          }

          TextInput({ placeholder: 'Password' })
            .width('90%')
            .height(50)
            .margin({ top: 20 })
            .type(InputType.Password)
            .onChange((value: string) => {
              this.password = value;
              this.validatePassword();
            });

          if (this.passwordError) {
            Text(this.passwordError)
              .width('90%')
              .fontColor('#ff0000')
              .margin({ top: 5 });
          }

          Button('Login')
            .width('90%')
            .height(50)
            .margin({ top: 30 })
            .enabled(this.emailError === '' && this.passwordError === '' && this.email !== '' && this.password !== '')
            .onClick(() => {
              this.handleLogin();
            });
        }
        .width('100%')
        .justifyContent(FlexAlign.Center);
      } else {
        Column() {
          Text(`Counter: ${this.counter}`)
            .fontSize(24)
            .margin({ bottom: 20 });

          Row() {
            Button('+1')
              .width(100)
              .height(50)
              .onClick(() => {
                this.increment();
              });

            Button('-1')
              .width(100)
              .height(50)
              .margin({ left: 20 })
              .onClick(() => {
                this.decrement();
              });
          }
          .margin({ bottom: 30 });

          Button('Logout')
            .width('90%')
            .height(50)
            .onClick(() => {
              this.handleLogout();
            });
        }
        .width('100%')
        .justifyContent(FlexAlign.Center);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

