struct RestaurantFinder {
  @State restaurants: Array<Restaurant> = [
    { id: 1, name: 'Gourmet Bistro', cuisine: 'French', rating: 4.5, distance: 2.3 },
    { id: 2, name: 'Spice Garden', cuisine: 'Indian', rating: 4.2, distance: 1.5 },
    { id: 3, name: 'Pasta Palace', cuisine: 'Italian', rating: 3.8, distance: 0.8 },
    { id: 4, name: 'Dragon Wok', cuisine: 'Chinese', rating: 4.0, distance: 3.1 },
    { id: 5, name: 'Burger Barn', cuisine: 'American', rating: 3.5, distance: 1.2 }
  ];

