    this.filteredRestaurants = this.restaurants.slice();
  }

  private filterRestaurants(): void {
    switch (this.filterOption) {
      case 'Rating':
        this.filteredRestaurants = this.restaurants.slice().sort((a: Restaurant, b: Restaurant) => b.rating - a.rating);
        break;
      case 'Distance':
        this.filteredRestaurants = this.restaurants.slice().sort((a: Restaurant, b: Restaurant) => a.distance - b.distance);
        break;
      default:
        this.filteredRestaurants = this.restaurants.slice();
    }
  }

  private toggleTheme(): void {
    this.isDarkMode = !this.isDarkMode;
  }

  build() {
    Column() {
      Row() {
        Button(this.isDarkMode ? 'Light Mode' : 'Dark Mode')
          .onClick(() => {
            this.toggleTheme();
          })
      }
      .width('100%')
      .justifyContent(FlexAlign.End)
      .margin({ bottom: 20 })

      RadioGroup() {
        Radio({ value: 'All' })
          .checked(this.filterOption === 'All')
          .onChange((isChecked: boolean) => {
            if (isChecked) {
              this.filterOption = 'All';
              this.filterRestaurants();
            }
          })
        Radio({ value: 'Rating' })
          .checked(this.filterOption === 'Rating')
          .onChange((isChecked: boolean) => {
            if (isChecked) {
              this.filterOption = 'Rating';
              this.filterRestaurants();
            }
          })
        Radio({ value: 'Distance' })
          .checked(this.filterOption === 'Distance')
          .onChange((isChecked: boolean) => {
            if (isChecked) {
              this.filterOption = 'Distance';
              this.filterRestaurants();
            }
          })
