      options: ["London", "Berlin", "Paris", "Madrid"],
      correctAnswer: 2
    },
    {
      question: "Which planet is known as the Red Planet?",
      options: ["Venus", "Mars", "Jupiter", "Saturn"],
      correctAnswer: 1
    }
  ];

  private pinchHandler = new gesture.PinchGesture({
    fingers: 2,
    onActionStart: (event: gesture.PinchEvent) => {
      this.zoomScale = event.scale;
    },
    onActionUpdate: (event: gesture.PinchEvent) => {
      this.zoomScale = event.scale;
    },
    onActionEnd: () => {
      if (this.zoomScale < 0.8) {
        this.zoomScale = 0.8;
      } else if (this.zoomScale > 2.0) {
        this.zoomScale = 2.0;
      }
    }
  });

