      Column({ space: 20 }) {
        Gesture(this.pinchHandler) {
          Column() {
            Text(this.cards[this.currentCardIndex].question)
              .fontSize(24)
              .fontWeight(FontWeight.Bold)
              .margin({ bottom: 20 });

            if (this.revealAnswer) {
              Text(`Answer: ${this.cards[this.currentCardIndex].options[this.cards[this.currentCardIndex].correctAnswer]}`)
