        }

        Column({ space: 10 }) {
          ForEach(this.cards[this.currentCardIndex].options, (option: string, index: number) => {
            chip.Chip({ type: chip.ChipType.Filter }) {
              Text(option)
            }
            .selected(this.selectedOptions[index])
            .onClick(() => {
              this.selectedOptions[index] = !this.selectedOptions[index];
            })
          })
        }

        Button('Next Card')
          .onClick(() => {
            this.currentCardIndex = (this.currentCardIndex + 1) % this.cards.length;
            this.revealAnswer = false;
            this.selectedOptions = [false, false, false, false];
          })

        Button('Reveal Answer')
          .onClick(() => {
            this.revealAnswer = true;
          })
      }
      .width('100%')
      .height('100%')
      .padding(20)
    }
  }
