@Entry
@Component
struct RideShareDatePicker {
  @State isPickerVisible: boolean = false;
  @State selectedDate: Date = new Date();
  @State formattedDate: string = '';

  private formatDate(date: Date): string {
    const year = date.getFullYear();
    const month = (date.getMonth() + 1).toString().padStart(2, '0');
    const day = date.getDate().toString().padStart(2, '0');
    return `${year}-${month}-${day}`;
  }

  private showNotification() {
    let notificationRequest: notification.NotificationRequest = {
      content: {
        contentType: notification.ContentType.NOTIFICATION_CONTENT_BASIC_TEXT,
        normal: {
          title: 'Ride Scheduled',
          text: `Ride scheduled for ${this.formattedDate}`
        }
      }
    };
    notification.publish(notificationRequest);
  }

  private togglePicker() {
    this.isPickerVisible = !this.isPickerVisible;
  }

  private confirmSelection() {
    this.formattedDate = this.formatDate(this.selectedDate);
    this.showNotification();
    this.isPickerVisible = false;
  }

  private cancelSelection() {
    this.selectedDate = new Date();
    this.formattedDate = '';
    this.isPickerVisible = false;
  }

  build() {
    Column() {
      Button('Select Ride Date')
        .margin(20)
        .onClick(() => {
          this.togglePicker();
        });

      if (this.isPickerVisible) {
        DatePicker({
          start: new Date(2023, 0, 1),
          end: new Date(2025, 11, 31),
          selected: this.selectedDate
        })
        .onChange((value: DateValue) => {
          this.selectedDate = new Date(value.year, value.month - 1, value.day);
        });

        Row() {
          Button('Cancel')
            .margin(10)
            .onClick(() => {
              this.cancelSelection();
            });

          Button('Confirm')
            .margin(10)
            .onClick(() => {
              this.confirmSelection();
            });
        }
      }

      if (this.formattedDate) {
        Text(`Selected Date: ${this.formattedDate}`)
          .margin(20)
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
