  @State isMeditationMode: boolean = false;
  @State contentScale: number = 1.0;
  @State startScale: number = 1.0;

  build() {
    Column() {
      Checkbox()
        .selected(this.isMeditationMode)
        .onChange((isChecked: boolean) => {
          this.isMeditationMode = isChecked;
          if (!isChecked) {
            this.contentScale = 1.0;
          }
        })

      if (this.isMeditationMode) {
        Text('Meditation Mode')
          .fontSize(20)
          .gesture(
            PinchGesture()
              .onActionStart(() => {
                console.log('Pinch gesture started');
                this.startScale = this.contentScale;
              })
              .onActionUpdate((event: { scale: number }) => {
                this.contentScale = this.startScale * event.scale;
                console.log('Pinch scale updated: ' + this.contentScale);
              })
              .onActionEnd(() => {
                console.log('Pinch gesture ended');
              })
          )
          .scale({ x: this.contentScale, y: this.contentScale })
          .width('100%')
          .height('100%');
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(FlexAlign.Center);
  }
}

