import { PanGesture, GestureEvent } from '@ohos.arkui.gesture';
import { Checkbox, TimePicker, TextInput } from '@ohos.arkui.advancedUI';
import { animateTo, Curve } from '@ohos.arkui.animation';

@Component
struct SwipeCheckbox {
  @State isChecked: boolean = false;
  @State time: TimePickerResult = { hour: 12, minute: 0 };
  @State text: string = '';
  @State offsetY: number = 0;

  build() {
    Column() {
      Checkbox()
        .selectedColor('#007DFF')
        .onChange((isSelected: boolean) => {
          this.isChecked = isSelected;
          this.toggleComponents();
        })
        .gesture(
          PanGesture()
            .onActionStart(() => {})
            .onActionUpdate((event: GestureEvent) => {
              if (Math.abs(event.offsetX) > 20) {
                this.isChecked = !this.isChecked;
                this.toggleComponents();
              }
            })
        )

      Stack() {
        TimePicker({
          hour: this.time.hour,
          minute: this.time.minute
        })
          .onChange((value: TimePickerResult) => {
            this.time = value;
          })
          .offset({ y: this.isChecked ? 0 : 100 })
          .opacity(this.isChecked ? 1 : 0)

        TextInput({ text: this.text })
          .onChange((value: string) => {
            this.text = value;
          })
          .offset({ y: this.isChecked ? -100 : 0 })
          .opacity(this.isChecked ? 0 : 1)
      }
      .height(200)
      .margin({ top: 20 })
    }
    .width('100%')
    .padding(20)
  }

  private toggleComponents() {
    animateTo({ duration: 300, curve: Curve.EaseInOut }, () => {
      this.offsetY = this.isChecked ? 0 : 100;
    });
  }
}

interface TimePickerResult {
  hour: number;
  minute: number;
}
