  private cart: ShoppingCart;

  constructor() {
    this.user = new User(1, "John Doe", "john.doe@example.com");
    this.product1 = new Product(101, "Laptop", 999.99, 1);
    this.product2 = new Product(102, "Phone", 699.99, 2);
    this.cart = new ShoppingCart(this.user);
  }

  build() {
    Column() {
      Text(this.user.getUserInfo())
        .fontSize(18)
        .margin(10);

      Text(this.product1.getProductInfo())
        .fontSize(16)
        .margin(10);

      Text(this.product2.getProductInfo())
        .fontSize(16)
        .margin(10);

      Button("Add Laptop to Cart")
        .onClick(() => {
          this.cart.addItem(this.product1);
        })
        .margin(10);

      Button("Add Phone to Cart")
        .onClick(() => {
          this.cart.addItem(this.product2);
        })
        .margin(10);

      Button("Remove Laptop from Cart")
        .onClick(() => {
          this.cart.removeItem(this.product1.id);
        })
        .margin(10);

      Button("Remove Phone from Cart")
        .onClick(() => {
          this.cart.removeItem(this.product2.id);
        })
        .margin(10);

      Text(this.cart.getCartSummary())
        .fontSize(18)
        .margin(10);
    }
    .width('100%')
    .padding(20);
  }
}

class User {
  readonly id: number;
  name: string;
  email: string;

  constructor(id: number, name: string, email: string) {
    this.id = id;
    this.name = name;
    this.email = email;
  }

  getUserInfo(): string {
    return `User ID: ${this.id}\nName: ${this.name}\nEmail: ${this.email}`;
  }
}

class Product {
  readonly id: number;
  name: string;
  price: number;
  quantity: number;

  constructor(id: number, name: string, price: number, quantity: number) {
    this.id = id;
    this.name = name;
    this.price = price;
    this.quantity = quantity;
  }

  getProductInfo(): string {
    return `Product ID: ${this.id}\nName: ${this.name}\nPrice: $${this.price}\nQuantity: ${this.quantity}`;
  }
}

class ShoppingCart {
  user: User;
  private items: Product[] = [];

  constructor(user: User) {
    this.user = user;
  }

  addItem(product: Product): void {
    this.items.push(product);
  }

  removeItem(productId: number): void {
    this.items = this.items.filter(item => item.id !== productId);
  }

  getCartSummary(): string {
    const total = this.items.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    return `Cart Summary:\nTotal Items: ${this.items.length}\nTotal Price: $${total}`;
  }
}

