@Entry
@Component
struct QueueApp {
  @State queue: Array<string> = [];

  private enqueue(element: string) {
    this.queue.push(element);
  }

  private getFirst(): string | undefined {
    return this.queue[0];
  }

  private dequeue(): string | undefined {
    return this.queue.shift();
  }

  build() {
    Column({ space: 10 }) {
      Button('Enqueue Element')
        .onClick(() => {
          this.enqueue(`Element ${this.queue.length + 1}`);
        })
        .margin({ top: 20 })

      Button('Get First Element')
        .onClick(() => {
          const firstElement = this.getFirst();
          if (firstElement) {
            console.log(`First Element: ${firstElement}`);
          } else {
            console.log('Queue is empty');
          }
        })
        .margin({ top: 20 })

      Button('Dequeue Element')
        .onClick(() => {
          const dequeuedElement = this.dequeue();
          if (dequeuedElement) {
            console.log(`Dequeued Element: ${dequeuedElement}`);
          } else {
            console.log('Queue is empty');
          }
        })
        .margin({ top: 20 })

      List() {
        ForEach(this.queue, (item: string) => {
          ListItem() {
            Text(item)
              .fontSize(20)
              .margin({ top: 10 })
          }
        }, (item: string) => item)
      }
      .width('100%')
      .height('50%')
      .backgroundColor(0xF1F3F5)
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

