@Entry
@Component
struct ExpandablePanel {
  @State isExpanded: boolean = false;
  @State headerText: string = "Personalized Header";

  build() {
    Column() {
      // Custom Header
      Row() {
        Image($r('app.media.app_icon'))
          .width(30)
          .height(30)
          .margin({ right: 10 });

        Text(this.headerText)
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .layoutWeight(1);

        Button(this.isExpanded ? "▲" : "▼")
          .onClick(() => {
            this.isExpanded = !this.isExpanded;
          })
          .width(30)
          .height(30)
          .fontSize(16);
      }
      .width('100%')
      .padding(10)
      .backgroundColor('#f0f0f0')
      .borderRadius(5)
      .onClick(() => {
        this.isExpanded = !this.isExpanded;
      });

      // Collapsible Content
      if (this.isExpanded) {
        Column() {
          Text("This is the expanded content of the panel.")
            .fontSize(16)
            .margin(10);

          Divider()
            .strokeWidth(1)
            .color('#cccccc')
            .margin({ left: 10, right: 10 });

          Text("Additional personalized content can be added here.")
            .fontSize(14)
            .margin(10);
        }
        .width('100%')
        .backgroundColor('#ffffff')
        .border({ width: 1, color: '#f0f0f0', radius: 5 })
        .margin({ top: 5 });
      }
    }
    .width('90%')
    .margin(10);
  }
}

