@Entry
@Component
struct FlexibleComponentArchitecture {
  @State isInline: boolean = false;

  // Standard Component
  @Builder
  StandardComponent() {
    Column() {
      Text('Standard Component')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100);
    }
    .padding(20)
    .border({ width: 1, color: Color.Black });
  }

  // Inline Component
  @Builder
  InlineComponent() {
    Row() {
      Text('Inline Component')
        .fontSize(16)
        .fontWeight(FontWeight.Normal)
        .margin({ right: 10 });
      Image($r('app.media.app_icon'))
        .width(50)
        .height(50);
    }
    .padding(10)
    .border({ width: 1, color: Color.Gray });
  }

  // Toggle between standard and inline components
  toggleComponent() {
    this.isInline = !this.isInline;
  }

  build() {
    Column() {
      Button(this.isInline ? 'Switch to Standard' : 'Switch to Inline')
        .onClick(() => {
          this.toggleComponent();
        })
        .margin({ bottom: 20 });

      if (this.isInline) {
        this.InlineComponent();
      } else {
        this.StandardComponent();
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .padding(20);
  }
}

