@Entry
@Component
struct CrossAxisPositioningExample {
  @State private alignValue: ListItemAlign = ListItemAlign.Center;

  build() {
    Column() {
      // Header
      Text('Header')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .textAlign(TextAlign.Center)
        .backgroundColor('#D2B48C')
        .width('100%')
        .height(50)

      // List Items with configurable alignment
      List({ space: 10 }) {
        ForEach([1, 2, 3, 4, 5], (item: number) => {
          ListItem() {
            Text(`Item ${item}`)
              .fontSize(16)
              .textAlign(TextAlign.Center)
              .backgroundColor('#F5DEB3')
              .width('90%')
              .height(40)
              .margin({ top: 5, bottom: 5 })
          }
        })
      }
      .alignListItem(this.alignValue)
      .width('100%')
      .height('70%')

      // Footer
      Text('Footer')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .textAlign(TextAlign.Center)
        .backgroundColor('#D2B48C')
        .width('100%')
        .height(50)

      // Alignment Controls
      Row() {
        Button('Center')
          .onClick(() => {
            this.alignValue = ListItemAlign.Center;
          })
          .margin(5)

        Button('Start')
          .onClick(() => {
            this.alignValue = ListItemAlign.Start;
          })
          .margin(5)

        Button('End')
          .onClick(() => {
            this.alignValue = ListItemAlign.End;
          })
          .margin(5)
      }
      .justifyContent(FlexAlign.Center)
      .width('100%')
      .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('rgb(242,242,242)')
  }
}

