@Entry
@Component
struct DynamicPropertyModifier {
  @State text: string = "Initial Text";
  @State textColor: Color = Color.Black;
  @State textSize: number = 20;
  @State isVisible: boolean = true;
  @State bgColor: Color = Color.White;

  build() {
    Column() {
      if (this.isVisible) {
        Text(this.text)
          .fontSize(this.textSize)
          .fontColor(this.textColor)
          .width(200)
          .height(50)
          .backgroundColor(Color.Gray)
          .margin(10)
      }

      Button("Change Text")
        .width(200)
        .height(50)
        .onClick(() => {
          this.text = "Dynamic Text Updated!";
        })
        .margin(10)

      Button("Change Color")
        .width(200)
        .height(50)
        .onClick(() => {
          this.textColor = Color.Red;
        })
        .margin(10)

      Button("Change Size")
        .width(200)
        .height(50)
        .onClick(() => {
          this.textSize = 30;
        })
        .margin(10)

      Button("Toggle Visibility")
        .width(200)
        .height(50)
        .onClick(() => {
          this.isVisible = !this.isVisible;
        })
        .margin(10)

      Button("Change Background")
        .width(200)
        .height(50)
        .onClick(() => {
          this.bgColor = this.bgColor === Color.White ? Color.Blue : Color.White;
        })
        .margin(10)

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(10)
        .onClick(() => {
          console.info("Image clicked!");
        })
    }
    .width("100%")
    .height("100%")
    .backgroundColor(this.bgColor)
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

