@Entry
@Component
struct MainApp {
  @State currentIndex: number = 0

  build() {
    Column() {
      // Content Area
      Column() {
        if (this.currentIndex === 0) {
          this.HomeTab()
        } else if (this.currentIndex === 1) {
          this.ProfileTab()
        } else {
          this.SettingsTab()
        }
      }
      .width('100%')
      .layoutWeight(1)

      // Bottom Navigation Bar
      Row() {
        // Home Tab
        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Home')
            .fontSize(12)
            .fontColor(this.currentIndex === 0 ? '#1698CE' : '#666666')
        }
        .width('33.33%')
        .onClick(() => this.currentIndex = 0)

        // Profile Tab
        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Profile')
            .fontSize(12)
            .fontColor(this.currentIndex === 1 ? '#1698CE' : '#666666')
        }
        .width('33.33%')
        .onClick(() => this.currentIndex = 1)

        // Settings Tab
        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Settings')
            .fontSize(12)
            .fontColor(this.currentIndex === 2 ? '#1698CE' : '#666666')
        }
        .width('33.33%')
        .onClick(() => this.currentIndex = 2)
      }
      .width('100%')
      .height(60)
      .backgroundColor(Color.White)
      .border({ width: { top: 0.5 }, color: '#cccccc' })
    }
  }

  @Builder HomeTab() {
    Column() {
      Text('Home')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      List() {
        ForEach([1, 2, 3, 4, 5], (item:number) => {
          ListItem() {
            Column() {
              Text(`Home Content ${item}`)
                .fontSize(16)
                .padding(16)
            }
            .width('100%')
            .backgroundColor(Color.White)
            .borderRadius(8)
            .margin({ bottom: 10 })
          }
        })
      }
      .width('100%')
      .padding({ left: 16, right: 16 })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }

  @Builder ProfileTab() {
    Column() {
      Text('Profile')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .borderRadius(50)
        .margin({ bottom: 16 })

      Text('User Name')
        .fontSize(20)
        .fontWeight(FontWeight.Medium)
        .margin({ bottom: 8 })

      Text('user@email.com')
        .fontSize(16)
        .fontColor('#666666')
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }

  @Builder SettingsTab() {
    Column() {
      Text('Settings')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      List() {
        ForEach(['Account', 'Notifications', 'Privacy', 'Help', 'About'], (item:string) => {
          ListItem() {
            Row() {
              Text(item)
                .fontSize(16)
              Blank()
              Image($r('app.media.app_icon'))
                .width(20)
                .height(20)
            }
            .width('100%')
            .padding(16)
            .backgroundColor(Color.White)
          }
          .margin({ bottom: 1 })
        })
      }
      .width('100%')
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }
}

