@Entry
@Component
struct FocusControlMechanism {
  @State activeController: string = 'none';

  build() {
    Column() {
      Text('Focus Control Mechanism Demo')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Text(`Active Controller: ${this.activeController}`)
        .fontSize(18)
        .margin({ bottom: 20 });

      Column() {
        TextInput({ placeholder: 'Text Input' })
          .width('80%')
          .height(50)
          .border({ width: 1, color: this.activeController === 'input' ? Color.Blue : Color.Gray })
          .onFocus(() => {
            this.activeController = 'input';
          })
          .onBlur(() => {
            this.activeController = 'none';
          })
          .margin({ bottom: 15 });

        Button('Controller Button 1')
          .width(150)
          .height(50)
          .backgroundColor(this.activeController === 'button1' ? Color.Blue : Color.Gray)
          .onFocus(() => {
            this.activeController = 'button1';
          })
          .onBlur(() => {
            this.activeController = 'none';
          })
          .margin({ bottom: 15 });

        Button('Controller Button 2')
          .width(150)
          .height(50)
          .backgroundColor(this.activeController === 'button2' ? Color.Blue : Color.Gray)
          .onFocus(() => {
            this.activeController = 'button2';
          })
          .onBlur(() => {
            this.activeController = 'none';
          });
      }
      .width('100%')
      .alignItems(HorizontalAlign.Center)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor('#f5f5f5');
  }
}

