@Entry
@Component
struct ExpandableMenuItemGroup {
  @State expandedGroups: boolean[] = [false, false, false];
  @State selectedItem: string = "Select an item";

  build() {
    Column() {
      Text(this.selectedItem)
        .fontSize(20)
        .margin(10);

      Menu() {
        // Group 1 with expandable items
        MenuItemGroup() {
          MenuItem({
            content: "Group 1",
            startIcon: this.expandedGroups[0] ? "▼" : "▶"
          })
          .onClick(() => {
            this.expandedGroups[0] = !this.expandedGroups[0];
          })
          .enabled(false);

          if (this.expandedGroups[0]) {
            MenuItem({ startIcon: $r('app.media.app_icon'), content: "Item 1.1", labelInfo: "" })
              .onClick(() => {
                this.selectedItem = "Item 1.1 selected";
              });
            MenuItem({ startIcon: $r('app.media.app_icon'), content: "Item 1.2", labelInfo: "" })
              .onClick(() => {
                this.selectedItem = "Item 1.2 selected";
              });
          }
        }

        // Group 2 with expandable items
        MenuItemGroup() {
          MenuItem({
            content: "Group 2",
            startIcon: this.expandedGroups[1] ? "▼" : "▶"
          })
          .onClick(() => {
            this.expandedGroups[1] = !this.expandedGroups[1];
          })
          .enabled(false);

          if (this.expandedGroups[1]) {
            MenuItem({ startIcon: $r('app.media.app_icon'), content: "Item 2.1", labelInfo: "" })
              .onClick(() => {
                this.selectedItem = "Item 2.1 selected";
              });
            MenuItem({ startIcon: $r('app.media.app_icon'), content: "Item 2.2", labelInfo: "" })
              .onClick(() => {
                this.selectedItem = "Item 2.2 selected";
              });
          }
        }

        // Group 3 with expandable items
        MenuItemGroup() {
          MenuItem({
            content: "Group 3",
            startIcon: this.expandedGroups[2] ? "▼" : "▶"
          })
          .onClick(() => {
            this.expandedGroups[2] = !this.expandedGroups[2];
          })
          .enabled(false);

          if (this.expandedGroups[2]) {
            MenuItem({ startIcon: $r('app.media.app_icon'), content: "Item 3.1", labelInfo: "" })
              .onClick(() => {
                this.selectedItem = "Item 3.1 selected";
              });
            MenuItem({ startIcon: $r('app.media.app_icon'), content: "Item 3.2", labelInfo: "" })
              .onClick(() => {
                this.selectedItem = "Item 3.2 selected";
              });
          }
        }
      }
      .width('80%')
      .borderRadius(10)
      .backgroundColor('#F0F0F0')
      .shadow({ radius: 5, color: Color.Gray })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

