@Entry
@Component
struct DequeExample {
  @State deque: Array<string> = [];

  insertFront(element: string) {
    this.deque.unshift(element);
  }

  insertEnd(element: string) {
    this.deque.push(element);
  }

  accessFront(): string | undefined {
    return this.deque[0];
  }

  accessEnd(): string | undefined {
    return this.deque[this.deque.length - 1];
  }

  popFront(): string | undefined {
    return this.deque.shift();
  }

  popEnd(): string | undefined {
    return this.deque.pop();
  }

  build() {
    Column({ space: 10 }) {
      Button('Insert Front (Element A)')
        .onClick(() => {
          this.insertFront('Element A');
        })
        .margin({ top: 20 })

      Button('Insert End (Element Z)')
        .onClick(() => {
          this.insertEnd('Element Z');
        })
        .margin({ top: 20 })

      Button('Access Front')
        .onClick(() => {
          const frontElement = this.accessFront();
          if (frontElement) {
            console.log(`Front Element: ${frontElement}`);
          } else {
            console.log('Deque is empty');
          }
        })
        .margin({ top: 20 })

      Button('Access End')
        .onClick(() => {
          const endElement = this.accessEnd();
          if (endElement) {
            console.log(`End Element: ${endElement}`);
          } else {
            console.log('Deque is empty');
          }
        })
        .margin({ top: 20 })

      Button('Pop Front')
        .onClick(() => {
          const poppedElement = this.popFront();
          if (poppedElement) {
            console.log(`Popped Front Element: ${poppedElement}`);
          } else {
            console.log('Deque is empty');
          }
        })
        .margin({ top: 20 })

      Button('Pop End')
        .onClick(() => {
          const poppedElement = this.popEnd();
          if (poppedElement) {
            console.log(`Popped End Element: ${poppedElement}`);
          } else {
            console.log('Deque is empty');
          }
        })
        .margin({ top: 20 })

      List() {
        ForEach(this.deque, (item: string) => {
          ListItem() {
            Text(item)
              .fontSize(20)
              .margin({ top: 10 })
          }
        }, (item: string) => item)
      }
      .width('100%')
      .height('50%')
      .backgroundColor(0xF1F3F5)
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

