@Entry
@Component
struct AutoRefreshColumn {
  @State items: string[] = ['Initial Item 1', 'Initial Item 2', 'Initial Item 3'];
  @State refreshing: boolean = false;

  build() {
    Column({ space: 10 }) {
      Button('Add New Item')
        .onClick(() => {
          this.items.push(`New Item ${this.items.length + 1}`);
          this.refreshing = true;
          setTimeout(() => {
            this.refreshing = false;
          }, 500);
        })

      Button('Remove Last Item')
        .onClick(() => {
          if (this.items.length > 0) {
            this.items.pop();
            this.refreshing = true;
            setTimeout(() => {
              this.refreshing = false;
            }, 500);
          }
        })

      Refresh({
        refreshing: this.refreshing,
        offset: 100,
        friction: 80
      }) {
        Column() {
          ForEach(this.items, (item: string) => {
            Row() {
              Image($r('app.media.app_icon'))
                .width(40)
                .height(40)
                .margin(10)
              Text(item)
                .fontSize(18)
                .fontColor('#333333')
            }
            .width('100%')
            .padding(10)
            .backgroundColor('#ffffff')
            .borderRadius(8)
            .margin({ top: 5, bottom: 5 })
          })
        }
        .width('100%')
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
    .padding(20)
  }
}

