@Entry
@Component
struct TextProcessingController {
  @State text: string = '';
  private textInputController: TextInputController = new TextInputController();

  build() {
    Column({ space: 20 }) {
      TextInput({
        controller: this.textInputController,
        placeholder: 'Enter text to process',
        text: this.text
      })
      .onChange((value: string) => {
        this.text = value;
      })
      .width('100%')
      .height(50)
      .border({ width: 1, color: Color.Black })

      Row({ space: 10 }) {
        Button('Uppercase')
          .onClick(() => {
            this.text = this.text.toUpperCase();
          })
          .width('30%')

        Button('Lowercase')
          .onClick(() => {
            this.text = this.text.toLowerCase();
          })
          .width('30%')

        Button('Trim')
          .onClick(() => {
            this.text = this.text.trim();
          })
          .width('30%')
      }
      .width('100%')
      .margin({ top: 10 })

      Row({ space: 10 }) {
        Button('Reverse')
          .onClick(() => {
            this.text = this.text.split('').reverse().join('');
          })
          .width('30%')

        Button('Clear')
          .onClick(() => {
            this.text = '';
          })
          .width('30%')

        Button('Count Words')
          .onClick(() => {
            const wordCount = this.text.split(/\s+/).filter(word => word.length > 0).length;
            this.text = `Word count: ${wordCount}`;
          })
          .width('30%')
      }
      .width('100%')
      .margin({ top: 10 })

      Text('Processed Text:')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20 })

      Text(this.text)
        .fontSize(16)
        .margin({ top: 10 })
        .width('100%')
        .textAlign(TextAlign.Start)
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

class TextInputController {
  focus(): void {
    // Focus logic would be handled by the TextInput component
  }
}

