@Entry
@Component
struct HashMapExample {
  @State hashMap: Map<string, string> = new Map();
  @State inputKey: string = '';
  @State inputValue: string = '';
  @State result: string = '';

  build() {
    Column({ space: 10 }) {
      Text('HashMap Operations')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row({ space: 10 }) {
        TextInput({ placeholder: 'Enter key' })
          .width('40%')
          .onChange((value: string) => {
            this.inputKey = value;
          });

        TextInput({ placeholder: 'Enter value' })
          .width('40%')
          .onChange((value: string) => {
            this.inputValue = value;
          });
      }

      Button('Add Key-Value Pair')
        .onClick(() => {
          if (this.inputKey && this.inputValue) {
            this.hashMap.set(this.inputKey, this.inputValue);
            this.inputKey = '';
            this.inputValue = '';
            this.result = 'Key-Value pair added successfully';
          } else {
            this.result = 'Please enter both key and value';
          }
        })
        .width('80%')
        .margin({ top: 10, bottom: 20 });

      Button('Check Key Presence')
        .onClick(() => {
          if (this.inputKey) {
            const keyExists = this.hashMap.has(this.inputKey);
            this.result = `Key '${this.inputKey}' ${keyExists ? 'exists' : 'does not exist'}`;
          } else {
            this.result = 'Please enter a key to check';
          }
        })
        .width('80%')
        .margin({ bottom: 20 });

      Text(this.result)
        .fontSize(18)
        .margin({ bottom: 10 });

      Text('HashMap Contents:')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 10 });

      ForEach(Array.from(this.hashMap.entries()), (entry: [string, string]) => {
        Text(`${entry[0]}: ${entry[1]}`)
          .fontSize(16)
          .margin({ bottom: 5 });
      })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

