@Entry
@Component
struct EnhancedButtonApp {
  @State isExpanded: boolean = false;
  @State buttonType: string = 'Capsule';
  @State isActive: boolean = false;

  build() {
    Column() {
      // Main Button with Toggle Feature
      Button(this.isExpanded ? "Collapse" : "Expand")
        .width(200)
        .height(50)
        .backgroundColor(Color.Blue)
        .borderRadius(this.buttonType === 'Capsule' ? 25 : 0)
        .onClick(() => {
          this.isExpanded = !this.isExpanded;
        })
        .margin(10)

      // Child Component for Extended Features
      if (this.isExpanded) {
        EnhancedChildComponent({
          buttonType: this.buttonType,
          isActive: this.isActive,
          onButtonTypeChange: (newType: string) => { this.buttonType = newType; },
          onToggleActive: () => { this.isActive = !this.isActive; }
        })
      }
    }
    .width("100%")
    .height("100%")
    .backgroundColor("#ffffff")
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

@Component
struct EnhancedChildComponent {
  @Prop buttonType: string;
  @Prop isActive: boolean;
  @Prop onButtonTypeChange: (newType: string) => void;
  @Prop onToggleActive: () => void;

  build() {
    Column({ space: 10 }) {
      // Button Type Toggle
      Button(this.buttonType === 'Capsule' ? 'Switch to Normal' : 'Switch to Capsule')
        .width(200)
        .height(50)
        .backgroundColor(this.buttonType === 'Capsule' ? Color.Green : Color.Blue)
        .borderRadius(this.buttonType === 'Capsule' ? 25 : 0)
        .onClick(() => {
          this.onButtonTypeChange(this.buttonType === 'Capsule' ? 'Normal' : 'Capsule');
        })
        .margin(10)

      // Active/Inactive Toggle
      Button(this.isActive ? 'Active' : 'Inactive')
        .width(200)
        .height(50)
        .backgroundColor(this.isActive ? Color.Red : Color.Gray)
        .onClick(() => {
          this.onToggleActive();
        })
        .margin(10)

      // Image Display
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(10)
    }
    .alignItems(HorizontalAlign.Center)
  }
}

