@Entry
@Component
struct InitializeOnStartupExample {
  @State private isInitialized: boolean = false;
  @State private initializationMessage: string = "Not Initialized";

  initializeOnStartup() {
    // Simulate initialization tasks
    setTimeout(() => {
      this.isInitialized = true;
      this.initializationMessage = "Initialized Successfully";
      console.log("Initialization completed on startup");
    }, 2000);
  }

  aboutToAppear() {
    this.initializeOnStartup();
  }

  build() {
    Column() {
      Text(this.initializationMessage)
        .fontSize(30)
        .fontColor(this.isInitialized ? Color.Green : Color.Red)
        .margin(10);

      Button('Reinitialize')
        .onClick(() => {
          this.isInitialized = false;
          this.initializationMessage = "Initializing...";
          this.initializeOnStartup();
        })
        .margin(10);

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(20)
        .visibility(this.isInitialized ? Visibility.Visible : Visibility.Hidden);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

