@Component
struct ColorPickerApp {
  @State selectedColor: string = '#FF0000'
  @State isDropdownOpen: boolean = false
  private colors: string[] = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FF00FF', '#FFA500']

  build() {
    Column() {
      // Dropdown Button
      Button(this.selectedColor)
        .width(150)
        .height(40)
        .backgroundColor('#FFFFFF')
        .borderColor('#000000')
        .borderWidth(1)
        .onClick(() => {
          this.isDropdownOpen = !this.isDropdownOpen
        })

      // Dropdown Menu
      if (this.isDropdownOpen) {
        Column() {
          ForEach(this.colors, (color: string) => {
            Button(color)
              .width(150)
              .height(40)
              .backgroundColor(color)
              .onClick(() => {
                this.selectedColor = color
                this.isDropdownOpen = false
              })
              .margin({ top: 5 })
          })
        }
        .margin({ top: 10 })
      }

      // Display Selected Color Box
      Row()
        .width(100)
        .height(100)
        .backgroundColor(this.selectedColor)
        .margin({ top: 20 })
    }
    .padding(20)
    .backgroundColor('#FFFFFF')
    .width('100%')
    .height('100%')
  }
}

