@Entry
@Component
struct FullScreenLaunchComponent {
  @State private isContentLoaded: boolean = false;
  @State private showWelcome: boolean = true;
  @State private theme: string = 'light';

  private loadContent() {
    setTimeout(() => {
      this.isContentLoaded = true;
      this.showWelcome = false;
    }, 2000);
  }

  private toggleTheme() {
    this.theme = this.theme === 'light' ? 'dark' : 'light';
  }

  build() {
    Column() {
      // Header Section
      Row() {
        Column() {
          Image($r('app.media.app_icon'))
            .width(80)
            .height(80)
          Text('Full Screen Launch')
            .fontSize(24)
            .fontColor(this.theme === 'light' ? Color.Black : Color.White)
        }
        .margin({ left: 20 })
        .alignItems(HorizontalAlign.Center)

        Button(`Switch to ${this.theme === 'light' ? 'Dark' : 'Light'}`)
          .onClick(() => this.toggleTheme())
          .width(120)
          .margin({ right: 20 })
      }
      .width('100%')
      .height(100)
      .justifyContent(FlexAlign.SpaceBetween)
      .backgroundColor(this.theme === 'light' ? '#EEEEEE' : '#333333')

      // Main Content Section
      Column() {
        if (this.showWelcome) {
          Text('Welcome to the Application')
            .fontSize(20)
            .fontColor(this.theme === 'light' ? Color.Black : Color.White)
            .margin({ bottom: 20 })
          Progress({ value: 50 })
            .width('80%')
            .height(4)
            .color(Color.Blue)
        } else if (this.isContentLoaded) {
          Image($r('app.media.app_icon'))
            .width(150)
            .height(150)
            .borderRadius(10)
            .margin({ bottom: 20 })
          Text('Content Loaded Successfully')
            .fontSize(20)
            .fontColor(this.theme === 'light' ? Color.Black : Color.White)
        } else {
          Text('Loading Content...')
            .fontSize(20)
            .fontColor(this.theme === 'light' ? Color.Black : Color.White)
        }
      }
      .layoutWeight(1)
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .alignItems(HorizontalAlign.Center)

      // Footer Section
      Row() {
        Text('© 2023 MyApp')
          .fontSize(14)
          .fontColor(this.theme === 'light' ? Color.Black : Color.White)
          .textAlign(TextAlign.Center)
          .width('100%')
      }
      .width('100%')
      .height(60)
      .justifyContent(FlexAlign.Center)
      .backgroundColor(this.theme === 'light' ? '#EEEEEE' : '#333333')
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.theme === 'light' ? Color.White : Color.Black)
    .onAppear(() => {
      this.loadContent();
    })
  }
}

