@Entry
@Component
struct TreeMapExample {
  @State treeMap: Map<string, number> = new Map();
  @State firstKey: string = '';
  @State lastKey: string = '';
  @State inputKey: string = '';
  @State inputValue: string = '';

  build() {
    Column({ space: 10 }) {
      Text('TreeMap Operations')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row({ space: 10 }) {
        TextInput({ placeholder: 'Enter key' })
          .width('40%')
          .onChange((value: string) => {
            this.inputKey = value;
          });

        TextInput({ placeholder: 'Enter value' })
          .width('40%')
          .type(InputType.Number)
          .onChange((value: string) => {
            this.inputValue = value;
          });
      }

      Button('Add to TreeMap')
        .onClick(() => {
          if (this.inputKey && this.inputValue) {
            this.treeMap.set(this.inputKey, parseInt(this.inputValue));
            this.inputKey = '';
            this.inputValue = '';
            this.updateFirstLastKeys();
          }
        })
        .width('80%')
        .margin({ top: 10, bottom: 20 });

      Button('Get First Key')
        .onClick(() => {
          this.firstKey = this.getFirstKey();
        })
        .width('80%')
        .margin({ bottom: 10 });

      Button('Get Last Key')
        .onClick(() => {
          this.lastKey = this.getLastKey();
        })
        .width('80%')
        .margin({ bottom: 20 });

      Text(`First Key: ${this.firstKey}`)
        .fontSize(18)
        .margin({ bottom: 10 });

      Text(`Last Key: ${this.lastKey}`)
        .fontSize(18)
        .margin({ bottom: 10 });

      Text('TreeMap Contents:')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 10 });

      ForEach(Array.from(this.treeMap.entries()), (entry: [string, number]) => {
        Text(`${entry[0]}: ${entry[1]}`)
          .fontSize(16)
          .margin({ bottom: 5 });
      })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }

  private updateFirstLastKeys() {
    const keys = Array.from(this.treeMap.keys()).sort();
    if (keys.length > 0) {
      this.firstKey = keys[0];
      this.lastKey = keys[keys.length - 1];
    } else {
      this.firstKey = '';
      this.lastKey = '';
    }
  }

  private getFirstKey(): string {
    const keys = Array.from(this.treeMap.keys()).sort();
    return keys.length > 0 ? keys[0] : 'No keys';
  }

  private getLastKey(): string {
    const keys = Array.from(this.treeMap.keys()).sort();
    return keys.length > 0 ? keys[keys.length - 1] : 'No keys';
  }
}

