import promptAction from '@ohos.promptAction';

@Entry
@Component
struct ContactForm {
  @State name: string = '';
  @State email: string = '';
  @State message: string = '';
  @State showDialog: boolean = false;

  build() {
    Column() {
      // Form Title
      Text('Contact Us')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      // Name Input
      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value;
          });
      }

      // Email Input
      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value;
          });
      }

      // Message Input
      Column() {
        Text('Message:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your message' })
          .width('100%')
          .height(100)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.message = value;
          });
      }

      // Submit Button
      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.name && this.email && this.message) {
            this.showDialog = true;
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields'
            });
          }
        });

      // Alert Dialog
      if (this.showDialog) {
        Column() {
          Text('Submitted Information')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Name: ${this.name}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Message: ${this.message}`)
            .fontSize(16)
            .margin({ bottom: 20 });

