@Entry
@Component
struct LightWeightSetExample {
  @State private elements: string[] = [];
  @State private currentIndex: number = -1;
  @State private inputValue: string = '';

  build() {
    Column({ space: 10 }) {
      Text('LightWeightSet Example')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      TextInput({ placeholder: 'Enter element to add' })
        .onChange((value: string) => {
          this.inputValue = value;
        })
        .width('80%')
        .height(40)
        .margin({ bottom: 10 });

      Button('Add Element')
        .onClick(() => {
          if (this.inputValue) {
            this.elements.push(this.inputValue);
            this.currentIndex = this.elements.length - 1;
            this.inputValue = '';
          }
        })
        .width('80%')
        .height(40)
        .margin({ bottom: 10 });

      Button('Remove Element')
        .onClick(() => {
          if (this.elements.length > 0) {
            this.elements.pop();
            this.currentIndex = this.elements.length - 1;
          }
        })
        .width('80%')
        .height(40)
        .margin({ bottom: 10 });

      Text(`Current Index: ${this.currentIndex}`)
        .fontSize(16)
        .margin({ bottom: 10 });

      Button('Verify Index')
        .onClick(() => {
          if (this.currentIndex >= 0 && this.currentIndex < this.elements.length) {
            console.info(`Element at index ${this.currentIndex}: ${this.elements[this.currentIndex]}`);
          } else {
            console.info('Invalid index');
          }
        })
        .width('80%')
        .height(40)
        .margin({ bottom: 10 });

      List({ space: 10 }) {
        ForEach(this.elements, (item: string, index: number) => {
          ListItem() {
            Text(`${index}: ${item}`)
              .fontSize(16)
              .textAlign(TextAlign.Center)
              .width('100%')
              .height(40)
              .backgroundColor(index === this.currentIndex ? '#CCCCCC' : '#FFFFFF')
          }
        }, (item: string) => item)
      }
      .width('100%')
      .height('60%')
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

