@Entry
@Component
struct ColorDropdownApp {
  @State selectedColor: string = '#FF0000'
  @State isDropdownOpen: boolean = false
  private colors: string[] = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FF00FF', '#FFA500']

  build() {
    Column() {
      // Display Selected Color
      Row() {
        Text('Selected Color:')
          .fontSize(20)
          .margin({ bottom: 10 })

        Row()
          .width(50)
          .height(50)
          .backgroundColor(this.selectedColor)
          .borderRadius(25)
      }
      .margin({ bottom: 20 })

      // Dropdown Button
      Button('Select Color')
        .width(150)
        .height(40)
        .backgroundColor('#FFFFFF')
        .borderColor('#000000')
        .borderWidth(1)
        .onClick(() => {
          this.isDropdownOpen = !this.isDropdownOpen
        })
        .margin({ bottom: 20 })

      // Dropdown Menu
      if (this.isDropdownOpen) {
        Column() {
          ForEach(this.colors, (color: string) => {
            Button()
              .width(100)
              .height(40)
              .backgroundColor(color)
              .onClick(() => {
                this.selectedColor = color
                this.isDropdownOpen = false
              })
              .margin(5)
          })
        }
        .border({ width: 1, color: '#CCCCCC' })
        .borderRadius(5)
        .padding(10)
        .backgroundColor('#FFFFFF')
      }
    }
    .padding(20)
    .backgroundColor('#FFFFFF')
    .width('100%')
    .height('100%')
  }
}

