@Entry
@Component
struct FormValidationExample {
  @State username: string = ''
  @State email: string = ''
  @State password: string = ''
  @State confirmPassword: string = ''

  @State usernameError: string = ''
  @State emailError: string = ''
  @State passwordError: string = ''
  @State confirmPasswordError: string = ''

  @State isFormValid: boolean = false

  validateUsername(username: string): string | null {
    if (username.length < 3) return 'Username must be at least 3 characters'
    if (username.length > 20) return 'Username must be less than 20 characters'
    return null
  }

  validateEmail(email: string): string | null {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    if (!emailRegex.test(email)) return 'Please enter a valid email'
    return null
  }

  validatePassword(password: string): string | null {
    if (password.length < 6) return 'Password must be at least 6 characters'
    return null
  }

  validateConfirmPassword(password: string, confirmPassword: string): string | null {
    return password === confirmPassword ? null : 'Passwords do not match'
  }

  validateForm() {
    this.usernameError = this.validateUsername(this.username) || ''
    this.emailError = this.validateEmail(this.email) || ''
    this.passwordError = this.validatePassword(this.password) || ''
    this.confirmPasswordError = this.validateConfirmPassword(this.password, this.confirmPassword) || ''
    this.isFormValid = !this.usernameError && !this.emailError && !this.passwordError && !this.confirmPasswordError
  }

  build() {
    Column({ space: 20 }) {
      TextInput({ placeholder: 'Username' })
        .width('100%')
        .onChange((value: string) => {
          this.username = value
          this.validateForm()
        })
        .border({
          width: 1,
          color: this.usernameError ? '#ff0000' : '#ddd'
        })

      if (this.usernameError) {
        Text(this.usernameError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      TextInput({ placeholder: 'Email' })
        .width('100%')
        .onChange((value: string) => {
          this.email = value
          this.validateForm()
        })
        .border({
          width: 1,
          color: this.emailError ? '#ff0000' : '#ddd'
        })

      if (this.emailError) {
        Text(this.emailError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      TextInput({ placeholder: 'Password' })
        .width('100%')
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
          this.validateForm()
        })
        .border({
          width: 1,
          color: this.passwordError ? '#ff0000' : '#ddd'
        })

      if (this.passwordError) {
        Text(this.passwordError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      TextInput({ placeholder: 'Confirm Password' })
        .width('100%')
        .type(InputType.Password)
        .onChange((value: string) => {
          this.confirmPassword = value
          this.validateForm()
        })
        .border({
          width: 1,
          color: this.confirmPasswordError ? '#ff0000' : '#ddd'
        })

      if (this.confirmPasswordError) {
        Text(this.confirmPasswordError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      Button('Submit')
        .enabled(this.isFormValid)
        .onClick(() => {
          console.info('Form submitted successfully')
        })
        .width('100%')
    }
    .padding(20)
    .width('100%')
  }
}

