          this.validateForm()
        })
        .border({
          width: 1,
          color: this.emailError ? '#ff0000' : '#ddd'
        })

      if (this.emailError) {
        Text(this.emailError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      TextInput({ placeholder: 'Password' })
        .width('100%')
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
          this.validateForm()
        })
        .border({
          width: 1,
          color: this.passwordError ? '#ff0000' : '#ddd'
        })

      if (this.passwordError) {
        Text(this.passwordError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      TextInput({ placeholder: 'Confirm Password' })
        .width('100%')
        .type(InputType.Password)
        .onChange((value: string) => {
          this.confirmPassword = value
          this.validateForm()
        })
        .border({
          width: 1,
          color: this.confirmPasswordError ? '#ff0000' : '#ddd'
        })

      if (this.confirmPasswordError) {
        Text(this.confirmPasswordError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      Button('Submit')
        .enabled(this.isFormValid)
        .onClick(() => {
          console.info('Form submitted successfully')
        })
        .width('100%')
    }
    .padding(20)
    .width('100%')
  }
}

@Entry
@Component
struct ControllerInputValidationExample {
  @State inputValue: string = ''
  @State errorMessage: string = ''
  @State isValid: boolean = true
  controller: TextInputController = new TextInputController()

  validateInput(value: string): boolean {
    if (value.length < 5) {
      this.errorMessage = 'Input must be at least 5 characters long'
      this.isValid = false
      return false
    }
    if (!/^[a-zA-Z0-9]+$/.test(value)) {
      this.errorMessage = 'Input must contain only alphanumeric characters'
      this.isValid = false
      return false
    }
    this.errorMessage = ''
    this.isValid = true
    return true
  }

  build() {
    Column({ space: 20 }) {
      TextInput({ placeholder: 'Enter your input', controller: this.controller })
        .onChange((value: string) => {
          this.inputValue = value
          this.validateInput(value)
        })
        .border({
          width: 1,
          color: this.isValid ? '#ddd' : '#ff0000'
        })
        .width('100%')

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      Button('Submit')
        .enabled(this.isValid)
        .onClick(() => {
          console.info('Input submitted successfully')
        })
    }
    .padding(20)
    .width('100%')
  }
}

