@Entry
@Component
struct MainApp {
  @State currentIndex: number = 0

  build() {
    Column() {
      // Content Area
      Column() {
        if (this.currentIndex === 0) {
          this.HomeTab()
        } else if (this.currentIndex === 1) {
          this.ExploreTab()
        } else {
          this.ProfileTab()
        }
      }
      .width('100%')
      .layoutWeight(1)

      // Bottom Navigation Bar
      Row() {
        // Home Tab
        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Home')
            .fontSize(12)
            .fontColor(this.currentIndex === 0 ? '#1698CE' : '#666666')
        }
        .width('33.33%')
        .onClick(() => this.currentIndex = 0)

        // Explore Tab
        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Explore')
            .fontSize(12)
            .fontColor(this.currentIndex === 1 ? '#1698CE' : '#666666')
        }
        .width('33.33%')
        .onClick(() => this.currentIndex = 1)

        // Profile Tab
        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Profile')
            .fontSize(12)
            .fontColor(this.currentIndex === 2 ? '#1698CE' : '#666666')
        }
        .width('33.33%')
        .onClick(() => this.currentIndex = 2)
      }
      .width('100%')
      .height(60)
      .backgroundColor(Color.White)
      .border({ width: { top: 0.5 }, color: '#cccccc' })
    }
  }

  @Builder HomeTab() {
    Column() {
      Text('Home Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }

  @Builder ExploreTab() {
    Column() {
      Text('Explore Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }

  @Builder ProfileTab() {
    Column() {
      Text('Profile Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }
}

