import router from '@ohos.router';

interface Movie {
  id: number;
  title: string;
  poster: string;
  releaseYear: string;
  description: string;
}

const movies: Movie[] = [
  {
    id: 1,
    title: 'Inception',
    poster: 'app.media.app_icon',
    releaseYear: '2010',
    description: 'A skilled thief who steals corporate secrets through the use of dream-sharing technology is given the inverse task of planting an idea into the mind of a CEO.',
  },
  {
    id: 2,
    title: 'The Matrix',
    poster: 'app.media.app_icon',
    releaseYear: '1999',
    description: 'A computer hacker learns from mysterious rebels about the true nature of his reality and his role in the war against its controllers.',
  },
  {
    id: 3,
    title: 'Interstellar',
    poster: 'app.media.app_icon',
    releaseYear: '2014',
    description: 'A team of explorers travel through a wormhole in space in an attempt to ensure humanity’s survival.',
  },
];

@Entry
@Component
struct Index {
  @State selectedMovie: Movie | null = null;

  build() {
    if (this.selectedMovie == null) {
      Column() {
        Text('Movie List')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .padding(16);

        List() {
          ForEach(movies, (movie: Movie) => {
            ListItem() {
              Row() {
                Image(movie.poster)
                  .width(100)
                  .height(150)
                  .objectFit(ImageFit.Cover)
                  .margin({ right: 10 });
                Column() {
                  Text(movie.title)
                    .fontSize(20)
                    .fontWeight(FontWeight.Medium)
                    .padding({ bottom: 4 });
                  Text(`Release Year: ${movie.releaseYear}`)
                    .fontSize(16)
                    .padding({ bottom: 8 });
                }
                .layoutWeight(1)
                .margin({ left: 10 });
              }
              .padding(16)
              .onClick(() => {
                this.selectedMovie = movie;
              });
            }
          });
        }
      }
    } else {
      Scroll() {
        Column() {
          Image(this.selectedMovie.poster)
            .width('100%')
            .height(300)
            .objectFit(ImageFit.Cover)
            .margin({ bottom: 16 });

          Text(this.selectedMovie.title)
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .padding(16);

          Text(`Release Year: ${this.selectedMovie.releaseYear}`)
            .fontSize(18)
            .padding({ left: 16, right: 16, bottom: 8 });

          Text('Description:')
            .fontSize(20)
            .fontWeight(FontWeight.Medium)
            .padding({ left: 16, right: 16, top: 16, bottom: 4 });

          Text(this.selectedMovie.description)
            .fontSize(16)
            .padding({ left: 16, right: 16, bottom: 16 });

          Button('Back')
            .onClick(() => {
              this.selectedMovie = null;
            })
            .padding(16);
        }
      }
    }
  }
}

