@Entry
@Component
struct DynamicFormWithConditionalFields {
  @State firstName: string = '';
  @State lastName: string = '';
  @State email: string = '';
  @State phone: string = '';
  @State address: string = '';
  @State showAddressFields: boolean = false;
  @State showPhoneFields: boolean = false;
  @State formSubmitted: boolean = false;

  validateForm(): boolean {
    return this.firstName.length > 0 && this.lastName.length > 0 && this.email.length > 0;
  }

  build() {
    Column({ space: 20 }) {
      TextInput({ placeholder: 'First Name' })
        .onChange((value: string) => {
          this.firstName = value;
        });

      TextInput({ placeholder: 'Last Name' })
        .onChange((value: string) => {
          this.lastName = value;
        });

      TextInput({ placeholder: 'Email' })
        .onChange((value: string) => {
          this.email = value;
        });

      Toggle({ type: ToggleType.Checkbox, isOn: this.showPhoneFields })
        .onChange((value: boolean) => {
          this.showPhoneFields = value;
        })
        .margin({ top: 20 });

      if (this.showPhoneFields) {
        TextInput({ placeholder: 'Phone' })
          .onChange((value: string) => {
            this.phone = value;
          });
      }

      Toggle({ type: ToggleType.Checkbox, isOn: this.showAddressFields })
        .onChange((value: boolean) => {
          this.showAddressFields = value;
        })
        .margin({ top: 20 });

      if (this.showAddressFields) {
        TextInput({ placeholder: 'Address' })
          .onChange((value: string) => {
            this.address = value;
          });
      }

      Button('Submit')
        .onClick(() => {
          if (this.validateForm()) {
            this.formSubmitted = true;
            console.info('Form submitted with:', {
              firstName: this.firstName,
              lastName: this.lastName,
              email: this.email,
              phone: this.phone,
              address: this.address
            });
          }
        })
        .margin({ top: 20 })
        .enabled(this.validateForm());

      if (this.formSubmitted) {
        Text('Form submitted successfully!')
          .fontColor('#008000')
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .padding(20);
  }
}

