@Entry
@Component
struct KeyboardControllerExample {
  controller: TextInputController = new TextInputController()
  @State inputValue: string = ''
  @State isKeyboardVisible: boolean = false

  @Builder
  CustomKeyboardBuilder() {
    Column() {
      Row() {
        Button('Hide Keyboard')
          .onClick(() => {
            this.controller.stopEditing()
            this.isKeyboardVisible = false
          })
          .margin(10)
      }
      Grid() {
        ForEach(['1', '2', '3', '4', '5', '6', '7', '8', '9', '*', '0', '#'], (item: string) => {
          GridItem() {
            Button(item)
              .width(80)
              .height(80)
              .backgroundColor('#007BFF')
              .fontColor(Color.White)
              .onClick(() => {
                this.inputValue += item
              })
          }
        })
        GridItem() {
          Button('Backspace')
            .width(80)
            .height(80)
            .backgroundColor('#FF0000')
            .fontColor(Color.White)
            .onClick(() => {
              if (this.inputValue.length > 0) {
                this.inputValue = this.inputValue.slice(0, -1)
              }
            })
        }
      }
      .columnsTemplate('1fr 1fr 1fr')
      .rowsGap(10)
      .columnsGap(10)
      .padding(10)
    }
    .backgroundColor('#F5F5F5')
  }

  build() {
    Column() {
      TextInput({ placeholder: 'Enter text here', controller: this.controller, text: this.inputValue })
        .onChange((value: string) => {
          this.inputValue = value
        })
        .customKeyboard(this.CustomKeyboardBuilder())
        .width('80%')
        .height(50)
        .margin({ top: 20 })
        .onFocus(() => {
          this.isKeyboardVisible = true
        })
        .onBlur(() => {
          this.isKeyboardVisible = false
        })

      Text('Current Text: ' + this.inputValue)
        .fontSize(16)
        .margin(10)

      Button('Clear Text')
        .width(100)
        .height(40)
        .margin(10)
        .onClick(() => {
          this.inputValue = ''
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(Color.White)
  }
}

