@Entry
@Component
struct FormComponentWithFileUpload {
  @State name: string = ''
  @State email: string = ''
  @State isEmailValid: boolean = true
  @State emailError: string = ''
  @State selectedFiles: Resource[] = []
  @State maxFiles: number = 3
  @State uploadStatus: string = ''

  validateEmail(email: string): string | null {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return emailRegex.test(email) ? null : 'Please enter a valid email'
  }

  selectFile() {
    if (this.selectedFiles.length < this.maxFiles) {
      this.selectedFiles.push($r('app.media.app_icon'))
    }
  }

  removeFile(index: number) {
    this.selectedFiles.splice(index, 1)
  }

  submitForm() {
    if (this.isEmailValid && this.name.length > 0 && this.selectedFiles.length > 0) {
      this.uploadStatus = 'Uploading files...'
      setTimeout(() => {
        this.uploadStatus = 'Files uploaded successfully!'
        console.info('Form submitted with:', {
          name: this.name,
          email: this.email,
          files: this.selectedFiles.length
        })
      }, 1500)
    } else {
      this.uploadStatus = 'Please fill all fields and upload at least one file'
    }
  }

  build() {
    Column({ space: 20 }) {
      Text('Form with File Upload')
        .fontSize(24)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Name' })
        .width('100%')
        .onChange((value: string) => {
          this.name = value
        })

      TextInput({ placeholder: 'Email' })
        .width('100%')
        .onChange((value: string) => {
          this.email = value
          const error = this.validateEmail(value)
          this.emailError = error || ''
          this.isEmailValid = !error
        })
        .border({
          width: 1,
          color: this.isEmailValid ? '#ddd' : '#ff0000'
        })

      if (this.emailError) {
        Text(this.emailError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      Text('Upload Files (Max ' + this.maxFiles + ')')
        .fontSize(16)
        .margin({ top: 20 })

      Button('Select File')
        .onClick(() => this.selectFile())
        .margin({ bottom: 10 })

      if (this.selectedFiles.length > 0) {
        ForEach(this.selectedFiles, (file: Resource, index: number) => {
          Row() {
            Image(file)
              .width(60)
              .height(60)
              .margin({ right: 10 })

            Button('Remove')
              .onClick(() => this.removeFile(index))
          }
          .margin({ bottom: 10 })
        })
      }

      Button('Submit')
        .onClick(() => this.submitForm())
        .margin({ top: 20 })

      if (this.uploadStatus) {
        Text(this.uploadStatus)
          .fontSize(14)
          .fontColor(this.uploadStatus.includes('success') ? '#008000' : '#ff0000')
          .margin({ top: 10 })
      }
    }
    .padding(20)
    .width('100%')
  }
}

