@Entry
@Component
struct RatingApp {
  @State items: Array<Item> = [
    new Item('Item 1'),
    new Item('Item 2'),
    new Item('Item 3')
  ];

  private rateItem(index: number, rating: number): void {
    let item = this.items[index];
    item.ratings.push(rating);
    item.averageRating = this.calculateAverage(item.ratings);
    this.items[index] = item;
  }

  private calculateAverage(ratings: number[]): number {
    if (ratings.length === 0) return 0;
    const sum = ratings.reduce((acc, curr) => acc + curr, 0);
    return sum / ratings.length;
  }

  build() {
    Column({ space: 20 }) {
      Text('Rate the Items')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      ForEach(this.items, (item: Item, index: number) => {
        Column({ space: 10 }) {
          Text(item.name)
            .fontSize(18)
            .fontWeight(FontWeight.Medium);

          Text(`Average Rating: ${item.averageRating.toFixed(1)}`)
            .fontSize(16)
            .fontColor(Color.Gray);

          Row({ space: 5 }) {
            ForEach([1, 2, 3, 4, 5], (star: number) => {
              Image($r('app.media.app_icon'))
                .width(24)
                .height(24)
                .opacity(star <= item.currentRating ? 1 : 0.3)
                .onClick(() => {
                  item.currentRating = star;
                  this.rateItem(index, star);
                });
            });
          }
        }
        .padding(15)
        .backgroundColor('#f0f0f0')
        .borderRadius(10)
        .width('100%');
      });
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

