@Entry
@Component
struct CustomStateApp {
  @State title: string = "Custom State App";
  @State counter: number = 0;
  @State isHighlighted: boolean = false;

  build() {
    Column({ space: 20 }) {
      // Custom component showing state
      CustomStateDisplay({
        title: this.title,
        count: this.counter,
        highlighted: this.isHighlighted
      })

      // Controls to modify state
      Button("Increment Counter")
        .width(200)
        .height(50)
        .onClick(() => {
          this.counter += 1;
        })
        .margin(10)

      Button("Toggle Highlight")
        .width(200)
        .height(50)
        .onClick(() => {
          this.isHighlighted = !this.isHighlighted;
        })
        .margin(10)

      Button("Reset All")
        .width(200)
        .height(50)
        .onClick(() => {
          this.title = "Custom State App";
          this.counter = 0;
          this.isHighlighted = false;
        })
        .margin(10)
