@Entry
@Component
struct CustomLoadingAnimation {
  @State private progressValue: number = 0;
  @State private rotation: number = 0;
  private intervalID: number = -1;

  aboutToAppear() {
    this.intervalID = setInterval(() => {
      this.rotation = (this.rotation + 10) % 360;
      if (this.progressValue < 100) {
        this.progressValue += 5;
      } else {
        clearInterval(this.intervalID);
      }
    }, 200);
  }

  aboutToDisappear() {
    if (this.intervalID !== -1) {
      clearInterval(this.intervalID);
    }
  }

  build() {
    Column({ space: 20 }) {
      Text('Custom Loading Animation')
        .fontSize(20)
        .fontColor(Color.Black)

      // Custom Progress Bar
      Stack() {
        Progress({
          value: this.progressValue,
          total: 100,
          style: ProgressStyle.Linear
        })
          .width('80%')
          .height(20)
          .backgroundColor(Color.Gray)
          .foregroundColor(Color.Blue)

        Text(`${this.progressValue}%`)
          .fontSize(14)
          .fontColor(Color.White)
          .textAlign(TextAlign.Center)
          .width('80%')
          .height(20)
      }

      // Custom Spinner
      Row() {
        Image($r('app.media.app_icon'))
          .width(50)
          .height(50)
          .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })
          .animation({ duration: 1000, iterations: Infinity, curve: Curve.Linear })
      }
      .justifyContent(FlexAlign.Center)
      .width('100%')
      .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20)
  }
}

