@Entry
@Component
struct MultiStageProgressBar {
    @State currentStage: number = 1
    private totalStages: number = 5
    @State progressValues: number[] = [0, 0, 0, 0, 0]
    private intervalIds: number[] = []

    aboutToDisappear() {
        this.intervalIds.forEach(id => clearInterval(id))
    }

    startProgress(stageIndex: number) {
        if (this.intervalIds[stageIndex]) {
            clearInterval(this.intervalIds[stageIndex])
        }
        this.progressValues[stageIndex] = 0
        this.intervalIds[stageIndex] = setInterval(() => {
            if (this.progressValues[stageIndex] < 100) {
                this.progressValues[stageIndex] += 1
            } else {
                clearInterval(this.intervalIds[stageIndex])
                if (stageIndex < this.totalStages - 1) {
                    this.currentStage = stageIndex + 2
                }
            }
        }, 30)
    }

    build() {
        Column({ space: 20 }) {
            // Stage indicators
            Row({ space: 10 }) {
                ForEach(Array.from({ length: this.totalStages }), (item: undefined, stageIndex: number) => {
                    Column() {
                        Circle()
                            .width(30)
                            .height(30)
                            .fill(this.currentStage >= stageIndex + 1 ? '#4CAF50' : '#CCCCCC')
                        Text(`Stage ${stageIndex + 1}`)
                            .fontSize(12)
                            .fontColor(this.currentStage >= stageIndex + 1 ? '#4CAF50' : '#999999')
                    }
                    .onClick(() => {
                        if (stageIndex + 1 <= this.currentStage) {
                            this.startProgress(stageIndex)
                        }
                    })
                })
            }
            .width('100%')
            .justifyContent(FlexAlign.SpaceBetween)
            .padding(10)

            // Current stage progress bar
            Text(`Stage ${this.currentStage} Progress`)
                .fontSize(16)
                .fontColor('#333333')

            Progress({
                value: this.progressValues[this.currentStage - 1],
                total: 100,
                type: ProgressType.Linear
            })
                .width('90%')
                .height(20)
                .color('#4CAF50')

            Text(`${this.progressValues[this.currentStage - 1]}%`)
                .fontSize(14)

            // Control buttons
            Row({ space: 20 }) {
                Button('Previous Stage')
                    .onClick(() => {
                        if (this.currentStage > 1) {
                            this.currentStage--
                        }
                    })
                    .enabled(this.currentStage > 1)

                Button('Next Stage')
                    .onClick(() => {
                        if (this.currentStage < this.totalStages) {
                            this.currentStage++
                        }
                    })
                    .enabled(this.currentStage < this.totalStages)
            }
            .margin({ top: 20 })
        }
        .width('100%')
        .height('100%')
        .padding(20)
        .justifyContent(FlexAlign.Center)
    }
}

