@Entry
@Component
struct ComplexNestedUI {
  @State private headerText: string = 'Complex Nested UI';
  @State private subtitle: string = 'Optimized with Builder Pattern';
  @State private isExpanded: boolean = false;
  @State private counter: number = 0;
  @State private selectedItem: string = 'Item 1';

  // Builder for header section
  @Builder
  HeaderBuilder() {
    Column() {
      Text(this.headerText)
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 5 });

      Text(this.subtitle)
        .fontSize(16)
        .fontColor(Color.Gray)
        .margin({ bottom: 20 });

      Divider()
        .strokeWidth(1)
        .color(Color.Gray);
    }
    .width('100%')
    .padding(20);
  }

  // Builder for expandable content
  @Builder
  ExpandableContentBuilder() {
    Column() {
      if (this.isExpanded) {
        Row() {
          Column() {
            Text('Expanded Content')
              .fontSize(18)
              .fontWeight(FontWeight.Bold)
              .margin({ bottom: 10 });

            Text(`Counter: ${this.counter}`)
              .fontSize(16)
              .margin({ bottom: 10 });

            Image($r('app.media.app_icon'))
              .width(80)
              .height(80)
              .margin({ bottom: 10 });
          }
          .padding(10)
          .backgroundColor('#F5F5F5')
          .borderRadius(8);
        }
        .width('100%');
      }
    }
    .width('100%');
  }

  // Builder for control buttons
  @Builder
  ControlButtonsBuilder() {
    Row() {
      Button(this.isExpanded ? 'Collapse' : 'Expand')
        .onClick(() => {
          this.isExpanded = !this.isExpanded;
        })
        .width(120)
        .margin({ right: 10 });

      Button('Increment')
        .onClick(() => {
          this.counter++;
        })
        .width(120);
    }
    .margin({ top: 10, bottom: 20 });
  }

  // Builder for item selection
  @Builder
  ItemSelectorBuilder() {
    Column() {
      Text('Select Item:')
        .fontSize(16)
        .margin({ bottom: 5 });

      Row() {
        ForEach(['Item 1', 'Item 2', 'Item 3', 'Item 4'], (item: string) => {
          Button(item)
            .backgroundColor(this.selectedItem === item ? Color.Blue : Color.White)
            .fontColor(this.selectedItem === item ? Color.White : Color.Black)
            .onClick(() => {
              this.selectedItem = item;
            })
            .margin({ right: 5 });
        });
      }
    }
    .margin({ top: 10 });
  }

  // Main build
  build() {
    Column() {
      this.HeaderBuilder();
      this.ExpandableContentBuilder();
      this.ControlButtonsBuilder();
      this.ItemSelectorBuilder();

      Text(`Selected: ${this.selectedItem}`)
        .fontSize(16)
        .fontWeight(FontWeight.Medium)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White);
  }
}

