@Component
struct ColorMetricsApplication {
  @State overlayColor: Color = Color.Red
  @State overlayOpacity: number = 0.5
  @State imageSource: Resource = $r('app.media.app_icon')

  build() {
    Column({ space: 20 }) {
      Text('Original Image')
        .fontSize(16)
      Image(this.imageSource)
        .width(200)
        .height(200)
        .margin({ bottom: 20 })

      Text('Image with Dynamic Color Overlay')
        .fontSize(16)
      Stack() {
        Image(this.imageSource)
          .width(200)
          .height(200)

        Row()
          .width(200)
          .height(200)
          .backgroundColor(this.overlayColor)
          .opacity(this.overlayOpacity)
      }
      .margin({ bottom: 20 })

      Column({ space: 10 }) {
        Text('Select Overlay Color:')
        Row() {
          Button('Red')
            .onClick(() => { this.overlayColor = Color.Red })
          Button('Blue')
            .onClick(() => { this.overlayColor = Color.Blue })
          Button('Green')
            .onClick(() => { this.overlayColor = Color.Green })
        }

        Text(`Opacity: ${this.overlayOpacity.toFixed(1)}`)
        Slider({
          value: this.overlayOpacity,
          min: 0,
          max: 1,
