@Entry
@Component
struct TextSelectionMenuExample {
  @State text: string = 'Select some text from this paragraph to see the selection menu.';
  @State start: number = 0;
  @State end: number = 0;
  @State selectedText: string = '';
  @State isMenuVisible: boolean = false;

  build() {
    Column() {
      // Text component with selection capability
      Text(this.text)
        .fontSize(16)
        .lineHeight(24)
        .margin(20)
        .selection(this.start, this.end)
        .onTextSelectionChange((start: number, end: number) => {
          this.start = start;
          this.end = end;
          this.selectedText = this.text.substring(start, end);
          this.isMenuVisible = (start !== end); // Show menu only when text is selected
        })

      // Selection menu that appears when text is selected
      if (this.isMenuVisible) {
        Column() {
          Button('Copy')
            .width('80%')
            .height(40)
            .margin(5)
            .onClick(() => {
              console.info('Copied:', this.selectedText);
              this.isMenuVisible = false;
            })

          Button('Share')
            .width('80%')
            .height(40)
            .margin(5)
            .onClick(() => {
              console.info('Shared:', this.selectedText);
              this.isMenuVisible = false;
            })

          Button('Search')
            .width('80%')
            .height(40)
            .margin(5)
            .onClick(() => {
              console.info('Search:', this.selectedText);
              this.isMenuVisible = false;
            })
        }
        .border({ width: 1, color: Color.Gray })
        .borderRadius(5)
        .backgroundColor(Color.White)
        .shadow({ radius: 5, color: Color.Gray })
        .margin({ top: 10 })
      }

      // Display selected text
      Text(`Selected: ${this.selectedText}`)
        .fontSize(14)
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

