@Entry
@Component
struct TouchEventHandler {
  @State private touchStatus: string = 'No touch detected';
  @State private touchPosition: string = 'Position: (0, 0)';

  build() {
    Column({ space: 20 }) {
      Text('Touch Event Handler')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Text(this.touchStatus)
        .fontSize(18);

      Text(this.touchPosition)
        .fontSize(16)
        .margin({ top: 10 });

      // Touchable area
      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .margin(20)
        .onTouch((event: TouchEvent) => {
          if (event.touches.length > 0) {
            const touch = event.touches[0];
            this.touchPosition = `Position: (${touch.x.toFixed(1)}, ${touch.y.toFixed(1)})`;

            switch (touch.type) {
              case TouchType.Down:
                this.touchStatus = 'Touch Down';
                console.log('Touch Down detected');
                break;
              case TouchType.Move:
                this.touchStatus = 'Touch Move';
                console.log('Touch Move detected');
                break;
              case TouchType.Up:
                this.touchStatus = 'Touch Up';
                console.log('Touch Up detected');
                break;
              case TouchType.Cancel:
                this.touchStatus = 'Touch Canceled';
                console.log('Touch Canceled detected');
                break;
              default:
                this.touchStatus = 'Unknown Touch Type';
            }
          }
        })
        .backgroundColor(Color.Gray)
        .borderRadius(10);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(Color.White);
  }
}

@Entry
@Component
struct LongPressTapEffect {
  @State isPressed: boolean = false
  @State pressDuration: number = 0
  @State tapEffect: boolean = false
  private timer: number = 0

  build() {
    Column() {
      Text(this.isPressed ? 'Long Pressing...' : 'Press and Hold')
        .fontSize(20)
        .margin({ bottom: 20 })

      Text(`Press Duration: ${this.pressDuration}ms`)
        .fontSize(16)
        .margin({ bottom: 20 })

      if (this.tapEffect) {
        Text('Tap Effect!')
          .fontSize(18)
          .fontColor(Color.Red)
          .margin({ bottom: 20 })
      }

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .backgroundColor(this.isPressed ? Color.Gray : Color.White)
        .opacity(this.isPressed ? 0.7 : 1.0)
        .gesture(
          LongPressGesture({ repeat: true })
            .onAction(() => {
              this.isPressed = true
              this.timer = setInterval(() => {
                this.pressDuration += 100
                // Trigger tap effect every 500ms during long press
                if (this.pressDuration % 500 === 0) {
                  this.tapEffect = true
                  setTimeout(() => {
                    this.tapEffect = false
                  }, 100)
                }
              }, 100)
            })
            .onActionEnd(() => {
              this.isPressed = false
              clearInterval(this.timer)
              this.pressDuration = 0
            })
        )
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

