@Entry
@Component
struct ConditionalTabDisplay {
  @State currentIndex: number = 0
  @State showTabs: boolean = true
  private tabsController: TabsController = new TabsController()

  @Builder TabBuilder(title: string, index: number) {
    Column() {
      Image($r('app.media.app_icon'))
        .width(24)
        .height(24)
        .objectFit(ImageFit.Contain)
        .opacity(this.currentIndex === index ? 1 : 0.5)
      Text(title)
        .fontSize(12)
        .fontColor(this.currentIndex === index ? '#1698CE' : '#6B6B6B')
        .margin({ top: 4 })
    }
    .width('100%')
    .height(60)
    .justifyContent(FlexAlign.Center)
  }

  build() {
    Column() {
      if (this.showTabs) {
        Tabs({ barPosition: BarPosition.Start, controller: this.tabsController }) {
          TabContent() {
            Column() {
              Text('Tab 1 Content')
                .fontSize(20)
                .margin(20)
            }
            .width('100%')
            .height('100%')
          }.tabBar(this.TabBuilder('Tab 1', 0))

          TabContent() {
            Column() {
              Text('Tab 2 Content')
                .fontSize(20)
                .margin(20)
            }
            .width('100%')
            .height('100%')
          }.tabBar(this.TabBuilder('Tab 2', 1))

          TabContent() {
            Column() {
              Text('Tab 3 Content')
                .fontSize(20)
                .margin(20)
            }
            .width('100%')
            .height('100%')
          }.tabBar(this.TabBuilder('Tab 3', 2))
        }
        .barWidth('100%')
        .barHeight(60)
