@Entry
@Component
struct TextPatternValidationExample {
  @State inputText: string = '';
  @State validationMessage: string = 'Please enter text to validate.';
  @State isValid: boolean = false;

  build() {
    Column() {
      TextInput({ placeholder: 'Enter text to validate' })
        .width('80%')
        .height(40)
        .margin(20)
        .onChange((value: string) => {
          this.inputText = value;
          this.validatePattern(value);
        });

      Text(this.validationMessage)
        .fontSize(16)
        .margin(10)
        .fontColor(this.isValid ? '#228B22' : '#FF0000');

      Button('Validate')
        .width('50%')
        .margin(20)
        .onClick(() => {
          this.validatePattern(this.inputText);
        });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }

  private validatePattern(text: string) {
    // Example pattern: Validate if the text contains only alphanumeric characters
    const alphanumericPattern = /^[a-zA-Z0-9]+$/;
    if (alphanumericPattern.test(text)) {
      this.validationMessage = 'Valid text pattern!';
      this.isValid = true;
    } else {
      this.validationMessage = 'Invalid text pattern. Only alphanumeric characters are allowed.';
      this.isValid = false;
    }
  }
}

