@Entry
@Component
struct ResponsiveForm {
  @State firstName: string = ''
  @State lastName: string = ''
  @State email: string = ''
  @State phone: string = ''
  @State showAdditionalFields: boolean = false
  @State errorMessage: string = ''
  @State successMessage: string = ''

  validateForm(): boolean {
    if (!this.firstName || !this.lastName || !this.email) {
      this.errorMessage = 'First Name, Last Name, and Email are required'
      this.successMessage = ''
      return false
    }
    if (this.showAdditionalFields && !this.phone) {
      this.errorMessage = 'Phone is required when additional fields are shown'
      this.successMessage = ''
      return false
    }
    this.errorMessage = ''
    this.successMessage = 'Form submitted successfully!'
    return true
  }

  build() {
    Column({ space: 20 }) {
      Text('User Registration Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'First Name' })
        .onChange((value: string) => {
          this.firstName = value
        })

      TextInput({ placeholder: 'Last Name' })
        .onChange((value: string) => {
          this.lastName = value
        })

      TextInput({ placeholder: 'Email' })
        .onChange((value: string) => {
          this.email = value
        })

      Toggle({ type: ToggleType.Checkbox, isOn: this.showAdditionalFields })
        .onChange((value: boolean) => {
          this.showAdditionalFields = value
        })
        .margin({ top: 20 })
        Text('Show Additional Fields')
          .fontSize(14)
          .margin({ left: 10 })

      if (this.showAdditionalFields) {
        TextInput({ placeholder: 'Phone' })
          .onChange((value: string) => {
            this.phone = value
          })
          .margin({ top: 10 })
      }

      Button('Submit')
        .onClick(() => {
          if (this.validateForm()) {
            console.info('Form submitted:', {
              firstName: this.firstName,
              lastName: this.lastName,
              email: this.email,
              phone: this.phone
            })
          }
        })
        .margin({ top: 20 })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 10 })
      }

      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(14)
          .fontColor(Color.Green)
          .margin({ top: 10 })
      }
    }
    .width('100%')
    .padding(20)
  }
}

