@Entry
@Component
struct ContactForm {
  @State name: string = '';
  @State email: string = '';
  @State phone: string = '';
  @State showDialog: boolean = false;

  validateEmail(email: string): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }

  build() {
    Column() {
      // Form Title
      Text('Contact Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      // Name Input
      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value;
          });
      }

      // Email Input
      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value;
          });
      }

      // Phone Input
      Column() {
        Text('Phone:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your phone number' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.phone = value;
          });
      }

      // Submit Button
      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.name && this.email && this.phone && this.validateEmail(this.email)) {
            this.showDialog = true;
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields correctly'
            });
          }
        });

      // Alert Dialog
      if (this.showDialog) {
        Column() {
          Text('Submitted Data')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Name: ${this.name}`)
