          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Phone: ${this.phone}`)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.showDialog = false;
              this.name = '';
              this.email = '';
              this.phone = '';
            });
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

