@Entry
@Component
struct TouchEventProcessor {
  @State private touchHistory: Array<string> = [];
  @State private currentPosition: string = 'Position: (0, 0)';
  @State private touchType: string = 'No touch detected';

  private recordTouchAction(type: string, x: number, y: number) {
    this.currentPosition = `Position: (${x.toFixed(1)}, ${y.toFixed(1)})`;
    this.touchType = `Touch Type: ${type}`;
    const action = `${type} at (${x.toFixed(1)}, ${y.toFixed(1)})`;
    this.touchHistory = [action, ...this.touchHistory].slice(0, 10);
  }

  build() {
    Column({ space: 20 }) {
      Text('Touch Event Processor')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Text(this.touchType)
        .fontSize(18);

      Text(this.currentPosition)
        .fontSize(16)
        .margin({ top: 10 });

      List() {
        ForEach(this.touchHistory, (item: string, index: number) => {
          ListItem() {
            Text(`${index + 1}. ${item}`)
              .fontSize(14)
              .margin(5);
          }
        });
      }
      .height(200)
      .width('90%')
      .backgroundColor('#f0f0f0')
      .margin(10);

      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .margin(20)
        .onTouch((event: TouchEvent) => {
          if (event.touches.length > 0) {
            const touch = event.touches[0];
            switch (touch.type) {
              case TouchType.Down:
                this.recordTouchAction('Down', touch.x, touch.y);
                break;
              case TouchType.Move:
                this.recordTouchAction('Move', touch.x, touch.y);
                break;
              case TouchType.Up:
                this.recordTouchAction('Up', touch.x, touch.y);
                break;
              case TouchType.Cancel:
                this.recordTouchAction('Cancel', touch.x, touch.y);
                break;
            }
          }
        })
        .backgroundColor(Color.Gray)
        .borderRadius(10);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(Color.White);
  }
}

@Entry
@Component
struct TapEffectDuringLongPress {
  @State isPressed: boolean = false
  @State pressDuration: number = 0
  @State tapEffect: boolean = false
  @State tapEffectOpacity: number = 0
  private timer: number = 0

  build() {
    Column() {
      Text(this.isPressed ? 'Long Pressing...' : 'Press and Hold')
        .fontSize(20)
        .margin({ bottom: 20 })

      Text(`Press Duration: ${this.pressDuration}ms`)
        .fontSize(16)
        .margin({ bottom: 20 })

      Stack() {
        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
          .backgroundColor(this.isPressed ? Color.Gray : Color.White)
          .opacity(this.isPressed ? 0.7 : 1.0)

        if (this.tapEffect) {
          Circle()
            .width(120)
            .height(120)
            .fill(Color.Red)
            .opacity(this.tapEffectOpacity)
            .onClick(() => {})
        }
      }

      Column()
        .width(200)
        .height(200)
        .gesture(
          LongPressGesture({ repeat: true })
            .onAction(() => {
              this.isPressed = true
              this.timer = setInterval(() => {
                this.pressDuration += 100
                if (this.pressDuration % 500 === 0) {
                  this.tapEffect = true
                  animateTo({ duration: 100 }, () => {
                    this.tapEffectOpacity = 0.3
                  })
                  setTimeout(() => {
                    animateTo({ duration: 200 }, () => {
                      this.tapEffectOpacity = 0
                      this.tapEffect = false
                    })
                  }, 100)
                }
              }, 100)
            })
            .onActionEnd(() => {
              this.isPressed = false
              clearInterval(this.timer)
              this.pressDuration = 0
              this.tapEffect = false
              this.tapEffectOpacity = 0
            })
        )
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

