@Entry
@Component
struct DragAndDropTextApp {
  @State sourceTexts: string[] = ['Text 1', 'Text 2', 'Text 3'];
  @State targetTexts: string[] = [];
  @State draggedItem: string = '';
  @State isDragging: boolean = false;

  build() {
    Column() {
      Text('Drag and Drop Text Data')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })
        .width('100%')
        .textAlign(TextAlign.Center);

      Row() {
        Column() {
          Text('Source Texts')
            .fontSize(18)
            .margin({ bottom: 10 });

          ForEach(this.sourceTexts, (text: string) => {
            Text(text)
              .fontSize(16)
              .padding(10)
              .backgroundColor(this.isDragging && this.draggedItem === text ? '#D1C4E9' : '#E0F7FA')
              .borderRadius(8)
              .margin({ bottom: 5 })
              .onTouch((event: TouchEvent) => {
                if (event.type === TouchType.Down) {
                  this.draggedItem = text;
                  this.isDragging = true;
                } else if (event.type === TouchType.Up) {
                  this.isDragging = false;
                }
              });
          });
        }
        .width('50%')
        .padding(10)

        Column() {
          Text('Target Area')
            .fontSize(18)
            .margin({ bottom: 10 });

          Column() {
            ForEach(this.targetTexts, (text: string) => {
              Text(text)
                .fontSize(16)
                .padding(10)
                .backgroundColor('#B2DFDB')
                .borderRadius(8)
                .margin({ bottom: 5 });
            });

            if (this.isDragging && this.draggedItem) {
              Text('Drop Here')
                .fontSize(16)
                .padding(10)
                .backgroundColor('#80CBC4')
                .borderRadius(8)
                .margin({ bottom: 5 })
                .onTouch((event: TouchEvent) => {
                  if (event.type === TouchType.Up) {
                    this.targetTexts.push(this.draggedItem);
                    this.sourceTexts = this.sourceTexts.filter(item => item !== this.draggedItem);
                    this.draggedItem = '';
                    this.isDragging = false;
                  }
                });
            }
          }
          .width('100%')
          .height('100%')
          .border({ width: 1, color: '#cccccc' })
          .borderRadius(8)
        }
        .width('50%')
        .padding(10)
      }
      .width('100%')
      .height('80%')
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

