import { ExceptionPrompt, PromptOptions, MarginType } from '@kit.ArkUI';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct ErrorCallbackManagement {
  @State options: PromptOptions = {
    icon: $r('app.media.app_icon'),
    tip: 'Error Occurred',
    marginType: MarginType.DEFAULT_MARGIN,
    actionText: 'Retry',
    marginTop: 80,
    isShown: false
  };

  @State private errorMessage: string = '';
  @State private showError: boolean = false;

  private handleError(error: Error, context: string = '') {
    this.errorMessage = `${context} Error: ${error.message}`;
    this.showError = true;
    this.options.isShown = true;
    console.error(this.errorMessage);

    promptAction.showToast({
      message: this.errorMessage,
      duration: 2000
    });
  }

  private retryOperation() {
    console.log('Retrying operation...');
    this.showError = false;
    this.options.isShown = false;
  }

  private simulateError() {
    try {
      if (Math.random() > 0.5) {
        throw new Error('Simulated error occurred');
      }
      this.showError = false;
      this.options.isShown = false;
    } catch (error) {
      this.handleError(error, 'Simulation');
    }
  }

  build() {
    Column() {
      if (this.showError) {
        ExceptionPrompt({
          options: this.options,
          onTipClick: () => {
            console.info("Error tip clicked.");
          },
          onActionTextClick: () => {
            console.info("Retry action clicked.");
            this.retryOperation();
          },
        });
      }

      Button('Simulate Error')
        .width(200)
        .height(50)
        .margin(10)
        .onClick(() => {
          this.simulateError();
        });

      Button('Clear Errors')
        .width(200)
        .height(50)
        .margin(10)
        .onClick(() => {
          this.showError = false;
          this.options.isShown = false;
          this.errorMessage = '';
        });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

