@Entry
@Component
struct FullScreenLaunchComponent {
  @State keyEventLog: string = 'No key events yet';
  @State pressedKey: string = 'No key pressed';
  @State isKeyDown: boolean = false;
  @State keyHistory: string[] = [];

  handleKeyEvent(event: KeyEvent) {
    switch (event.type) {
      case KeyType.Down:
        this.isKeyDown = true;
        this.keyEventLog = `Key Down: ${event.keyCode}`;
        this.pressedKey = `Pressed: ${event.keyCode}`;
        this.keyHistory.unshift(`Down: ${event.keyCode}`);
        break;
      case KeyType.Up:
        this.isKeyDown = false;
        this.keyEventLog = `Key Up: ${event.keyCode}`;
        this.keyHistory.unshift(`Up: ${event.keyCode}`);
        break;
    }

    if (this.keyHistory.length > 5) {
      this.keyHistory = this.keyHistory.slice(0, 5);
    }
  }

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(20)
        .opacity(this.isKeyDown ? 0.7 : 1.0);

      Text('Synchronous Key Event Handling')
        .fontSize(24)
        .fontColor(Color.Black)
        .margin(10);

      Text(this.pressedKey)
        .fontSize(20)
        .fontColor(this.isKeyDown ? Color.Red : Color.Black);

      Text(this.keyEventLog)
        .fontSize(18)
        .fontColor(Color.Blue)
        .margin(10);

      Column() {
        Text('Recent Events:')
          .fontSize(14)
          .fontColor(Color.Gray);

        ForEach(this.keyHistory, (item: string) => {
          Text(item)
            .fontSize(12)
            .fontColor('#A9A9A9')
            .margin({ bottom: 2 });
        });
      }
      .width('80%')
      .padding(10)
      .border({ width: 1, color: '#D3D3D3' })
      .borderRadius(5);

      Button('Clear History')
        .width(150)
        .height(40)
        .margin(20)
        .onClick(() => {
          this.keyHistory = [];
          this.keyEventLog = 'History cleared';
        });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#F5F5F5')
    .onKeyEvent((event: KeyEvent) => this.handleKeyEvent(event));
  }
}

import taskpool from '@ohos.taskpool';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct FullScreenLaunchComponent {
  @State isLoading: boolean = false;
  @State touchFeedback: string = 'Touch the screen to start';
  @State touchCount: number = 0;

  private async handleTouchEvent() {
    this.isLoading = true;
    this.touchFeedback = 'Processing touch...';

    try {
      const task = new taskpool.Task(() => {
        // Simulate async processing
        for (let i = 0; i < 500000000; i++) {}
        return 'Touch processed successfully';
      });

      const result = await taskpool.execute(task);
      this.touchCount++;
      this.touchFeedback = `${result} (Total touches: ${this.touchCount})`;
    } catch (error) {
      console.error('Touch Error:', error);
      promptAction.showToast({
        message: 'Touch processing failed',
        duration: 2000,
      });
      this.touchFeedback = 'Error occurred';
    } finally {
      this.isLoading = false;
    }
  }

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .margin(20)
        .onTouch((event: TouchEvent) => {
          if (event.type === TouchType.Down) {
            this.handleTouchEvent();
          }
        });

      if (this.isLoading) {
        Progress({ value: 50 })
          .width(100)
          .height(100)
          .color(Color.Blue);
      }

      Text(this.touchFeedback)
        .fontSize(20)
        .fontColor(Color.Black)
        .margin(10);

      Text(`Total touches: ${this.touchCount}`)
        .fontSize(16)
        .fontColor(Color.Gray)
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor(Color.White);
  }
}

@Entry
@Component
struct FullScreenLaunchComponent {
  @State sharedData: string = 'Initial Data';
  @State isConnected: boolean = false;
  @State isLoading: boolean = false;
  @State peerAppName: string = '';

  // Simulate capability sharing with another application
  private shareCapability() {
    this.isLoading = true;
    setTimeout(() => {
      this.isConnected = true;
      this.sharedData = 'Shared Data from Provider';
      this.peerAppName = 'ConsumerApp';
      this.isLoading = false;
      console.log('Capability shared with ' + this.peerAppName);
    }, 1500);
  }

  // Simulate receiving capability from another application
  private receiveCapability() {
    this.isLoading = true;
    setTimeout(() => {
      this.isConnected = true;
      this.sharedData = 'Received Data from Host';
      this.peerAppName = 'ProviderApp';
      this.isLoading = false;
      console.log('Capability received from ' + this.peerAppName);
    }, 1500);
  }

  build() {
    Column({ space: 20 }) {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 50 });

      Text(this.isConnected ? `Connected to ${this.peerAppName}` : 'Disconnected')
        .fontSize(20)
        .fontColor(this.isConnected ? Color.Green : Color.Red);

      Text('Shared Data: ' + this.sharedData)
        .fontSize(18)
        .margin({ top: 20 });

      if (this.isLoading) {
        Progress({ value: 0 })
          .width(100)
          .height(100)
          .color(Color.Blue)
          .margin({ top: 20 });
      } else {
        Column() {
          Button('Share Capability')
            .width(200)
            .height(50)
            .onClick(() => this.shareCapability())
            .margin({ top: 20 });

          Button('Receive Capability')
            .width(200)
            .height(50)
            .onClick(() => this.receiveCapability())
            .margin({ top: 10 });

          Button('Reset Connection')
            .width(200)
            .height(50)
            .onClick(() => {
              this.isConnected = false;
              this.sharedData = 'Initial Data';
              this.peerAppName = '';
            })
            .margin({ top: 10 });
        }
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(Color.White);
  }
}

@Entry
@Component
struct DragAndDropText {
  @State offsetX: number = 0;
  @State offsetY: number = 0;
  @State isDragging: boolean = false;
  @State droppedText: string = 'Drop text here';

  build() {
    Stack() {
      // Draggable Text Component
      Text('Drag Me!')
        .width(150)
        .height(50)
        .fontSize(16)
        .textAlign(TextAlign.Center)
        .backgroundColor(Color.Pink)
        .borderRadius(10)
        .position({ x: this.offsetX, y: this.offsetY })
        .opacity(this.isDragging ? 0.7 : 1)
        .onTouch((event: TouchEvent) => {
          if (event.type === TouchType.Down) {
            this.isDragging = true;
          } else if (event.type === TouchType.Move) {
            this.offsetX = event.touches[0].x;
            this.offsetY = event.touches[0].y;
          } else if (event.type === TouchType.Up) {
            this.isDragging = false;
          }
        });

      // Drop Zone Component
      Column() {
        Text(this.droppedText)
          .width(200)
          .height(80)
          .fontSize(16)
          .textAlign(TextAlign.Center)
          .backgroundColor(Color.Gray)
          .borderRadius(10)
          .margin({ top: 200 });
      }
      .width('100%')
      .height('100%')
      .justifyContent(FlexAlign.Center);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f0f0f0');
  }
}

