import { UIContext } from '@kit.ArkUI';

@Entry
@Component
struct AnimationControlMechanism {
  @State myScale: number = 1.0;
  @State rotationAngle: number = 0;
  @State textStyle: FontStyle = FontStyle.Normal;
  @State fontWeight: FontWeight = FontWeight.Normal;
  @State isAnimated: boolean = false;
  uiContext: UIContext | undefined = undefined;

  aboutToAppear() {
    this.uiContext = this.getUIContext?.();
  }

  build() {
    Column() {
      // Image with scaling and rotation animation
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(100)
        .scale({ x: this.myScale, y: this.myScale })
        .rotate({ x: 0, y: 0, z: 1, angle: this.rotationAngle })
        .onClick(() => {
          if (!this.uiContext) {
            console.info("no uiContext, animation failed");
            return;
          }
          this.myScale = 1;
          this.rotationAngle = 0;
          this.uiContext.keyframeAnimateTo({ iterations: 3 }, [
            {
              duration: 800,
              event: () => {
                this.myScale = 1.5;
                this.rotationAngle = 90;
              }
            },
            {
              duration: 500,
              event: () => {
                this.myScale = 1;
                this.rotationAngle = 0;
              }
            }
          ]);
        })

      // Text with style animation
      Text("Animated Text")
        .fontSize(24)
        .fontStyle(this.textStyle)
        .fontWeight(this.fontWeight)
        .fontColor(Color.Black)
        .margin({ top: 20 })
        .onClick(() => {
          this.isAnimated = !this.isAnimated;
          this.textStyle = this.isAnimated ? FontStyle.Italic : FontStyle.Normal;
          this.fontWeight = this.isAnimated ? FontWeight.Bold : FontWeight.Normal;
        })

      // Button to trigger animations
      Button("Toggle All Animations")
        .onClick(() => {
          this.isAnimated = !this.isAnimated;
          this.textStyle = this.isAnimated ? FontStyle.Italic : FontStyle.Normal;
          this.fontWeight = this.isAnimated ? FontWeight.Bold : FontWeight.Normal;
          if (this.uiContext) {
            this.myScale = 1;
            this.rotationAngle = 0;
            this.uiContext.keyframeAnimateTo({ iterations: 1 }, [
              {
                duration: 800,
                event: () => {
                  this.myScale = 1.5;
                  this.rotationAngle = 90;
                }
              },
              {
                duration: 500,
                event: () => {
                  this.myScale = 1;
                  this.rotationAngle = 0;
                }
              }
            ]);
          }
        })
        .margin({ top: 20 })
        .backgroundColor(Color.Blue)
        .fontColor(Color.White)
        .width("50%")
        .height(40)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .animation({
      duration: 500,
      curve: Curve.EaseInOut,
    })
  }
}

@Entry
@Component
struct RatingApp {
  @State items: Array<Item> = [
    new Item('Item 1'),
    new Item('Item 2'),
    new Item('Item 3')
  ];

  private rateItem(index: number, rating: number): void {
    if (rating < 1 || rating > 5) {
      console.error('Invalid rating. Must be between 1 and 5.');
      return;
    }

    let item = this.items[index];
    item.totalRatings += 1;
    item.totalScore += rating;
    item.averageRating = item.totalScore / item.totalRatings;

    this.items[index] = item;
  }

  build() {
    Column({ space: 20 }) {
      Text('Rate the Items')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      ForEach(this.items, (item: Item, index: number) => {
        Column({ space: 10 }) {
          Text(item.name)
            .fontSize(18)
            .fontWeight(FontWeight.Medium);

          Text(`Average Rating: ${item.averageRating.toFixed(1)}`)
            .fontSize(16)
            .fontColor(Color.Gray);

          Row({ space: 5 }) {
            ForEach([1, 2, 3, 4, 5], (starIndex: number) => {
              Image($r('app.media.app_icon'))
                .width(30)
                .height(30)
                .opacity(starIndex <= Math.round(item.averageRating) ? 1 : 0.3)
                .onClick(() => {
                  this.rateItem(index, starIndex);
                });
            });
          }
        }
        .padding(10)
        .backgroundColor('#f0f0f0')
        .borderRadius(10)
        .margin({ bottom: 10 });
      });
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

class Item {
  name: string;
  totalRatings: number = 0;
  totalScore: number = 0;
  averageRating: number = 0;

  constructor(name: string) {
    this.name = name;
  }
}

