@Entry
@Component
struct SelectionMechanismExample {
  @State selectedIndex: number = -1
  @State options: string[] = ['Option 1', 'Option 2', 'Option 3', 'Option 4']
  @State selectedValue: string = 'Select an option'

  build() {
    Column() {
      // Dropdown-style selection
      Select([
        { value: 'Option 1', icon: $r("app.media.app_icon") },
        { value: 'Option 2', icon: $r("app.media.app_icon") },
        { value: 'Option 3', icon: $r("app.media.app_icon") },
        { value: 'Option 4', icon: $r("app.media.app_icon") }
      ])
        .selected(this.selectedIndex)
        .value(this.selectedValue)
        .font({ size: 16, weight: 500 })
        .fontColor('#182431')
        .selectedOptionFont({ size: 16, weight: 400 })
        .optionFont({ size: 16, weight: 400 })
        .space(8)
        .arrowPosition(ArrowPosition.END)
        .menuAlign(MenuAlignType.START, { dx: 0, dy: 0 })
        .optionWidth(200)
        .optionHeight(300)
        .onSelect((index: number, value: string) => {
          this.selectedIndex = index
          this.selectedValue = value
        })
        .width('80%')
        .margin(20)

      // List-style selection with indicators
      List({ space: 10 }) {
        ForEach(this.options, (option: string, index: number) => {
          ListItem() {
            Row() {
              Image(this.selectedIndex === index ? $r("app.media.app_icon") : $r("app.media.app_icon"))
                .width(20)
                .height(20)
                .opacity(this.selectedIndex === index ? 1 : 0.3)

              Text(option)
                .fontSize(18)
                .fontColor(this.selectedIndex === index ? '#1890FF' : '#000000')
                .margin({ left: 10 })
            }
            .width('100%')
            .padding(10)
            .backgroundColor(this.selectedIndex === index ? '#F5F5F5' : '#FFFFFF')
            .borderRadius(4)
          }
          .onClick(() => {
            this.selectedIndex = index
            this.selectedValue = option
          })
        })
      }
      .width('90%')
      .height('60%')
      .divider({ strokeWidth: 1, color: '#F0F0F0' })

      // Current selection display
      Text(`Selected: ${this.selectedValue}`)
        .fontSize(20)
        .margin(20)
        .fontColor('#1890FF')
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

@Entry
@Component
struct TextSelectionMenuExample {
  @State text: string = 'Select some text from this paragraph to see the selection menu.';
  @State start: number = 0;
  @State end: number = 0;
  @State selectedText: string = '';
  @State isMenuVisible: boolean = false;
  @State menuOptions: string[] = ['Copy', 'Share', 'Search'];

  build() {
    Column() {
      // Text component with selection capability
      Text(this.text)
        .fontSize(16)
        .lineHeight(24)
        .margin(20)
        .selection(this.start, this.end)
        .onTextSelectionChange((start: number, end: number) => {
          this.start = start;
          this.end = end;
          this.selectedText = this.text.substring(start, end);
          this.isMenuVisible = (start !== end); // Show menu only when text is selected
        })

      // Selection menu that appears when text is selected
      if (this.isMenuVisible) {
        Column() {
          ForEach(this.menuOptions, (option: string) => {
            Button(option)
              .width('80%')
              .height(40)
              .margin(5)
              .onClick(() => {
                console.info(`${option}: ${this.selectedText}`);
                this.isMenuVisible = false;
              })
          })
        }
        .border({ width: 1, color: Color.Gray })
        .borderRadius(5)
        .backgroundColor(Color.White)
        .shadow({ radius: 5, color: Color.Gray })
        .margin({ top: 10 })
      }

      // Display selected text
      Text(`Selected: ${this.selectedText}`)
        .fontSize(14)
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

