@Entry
@Component
struct FullScreenAtomicService {
  build() {
    Column({ space: 20 }) {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
      Text('Atomic Service in Full Screen Mode')
        .fontSize(20)
        .fontColor(Color.Black)
      Button('Launch Service')
        .width(200)
        .height(50)
        .onClick(() => {
          this.launchFullScreenService();
        })
    }
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .width('100%')
    .height('100%')
  }

  private launchFullScreenService() {
    let want: Want = {
      bundleName: 'com.example.atomicService',
      abilityName: 'MainAbility',
      parameters: {
        launchMode: 'fullScreen'
      }
    };

    let context: common.UIAbilityContext = getContext() as common.UIAbilityContext;
    try {
      context.startAbility(want, (err) => {
        if (err) {
          console.error('Failed to launch atomic service:', err);
        } else {
          console.log('Atomic service launched successfully in full screen mode');
        }
      });
    } catch (error) {
      console.error('StartAbility error:', error);
    }
  }
}

