@Entry
@Component
struct TextPatternValidation {
  @State inputText: string = '';
  @State validationMessage: string = 'Enter text to validate against the pattern.';
  @State isValid: boolean = false;

  private validatePattern(text: string) {
    // Example pattern: Validate if the text is a valid email address
    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (emailPattern.test(text)) {
      this.validationMessage = 'Valid pattern!';
      this.isValid = true;
    } else {
      this.validationMessage = 'Invalid pattern. Please try again.';
      this.isValid = false;
    }
  }

  build() {
    Column() {
      TextInput({ placeholder: 'Enter text to validate' })
        .width('80%')
        .height(40)
        .margin(20)
        .onChange((value: string) => {
          this.inputText = value;
          this.validatePattern(value);
        });

      Text(this.validationMessage)
        .fontSize(16)
        .margin(10)
        .fontColor(this.isValid ? '#228B22' : '#FF0000');

      Button('Validate')
        .width('50%')
        .margin(20)
        .onClick(() => {
          this.validatePattern(this.inputText);
        });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

