@Component
struct ToolbarListExample {
  @State toolbarItems: Array<string> = ['Home', 'Profile', 'Settings', 'Logout']
  @State isEditing: boolean = false

  build() {
    Column() {
      Button(this.isEditing ? 'Done' : 'Edit')
        .onClick(() => {
          this.isEditing = !this.isEditing
        })
        .margin(10)
        .width(100)

      if (this.isEditing) {
        TextInput({ placeholder: 'Add new item' })
          .onSubmit((enterKey: EnterKeyType, event: SubmitEvent) => {
            const value = event.text as string;
            if (value) {
              this.toolbarItems.push(value)
              this.toolbarItems = [...this.toolbarItems]
            }
          })
          .margin(10)
          .width('80%')
      }

      List({ space: 10 }) {
        ForEach(this.toolbarItems, (item: string, index: number) => {
          ListItem() {
            Row() {
              Text(item)
                .fontSize(20)
                .fontColor(Color.White)
                .backgroundColor(Color.Blue)
                .padding(10)
                .borderRadius(5)

              if (this.isEditing) {
                Button('Delete')
                  .onClick(() => {
                    this.toolbarItems.splice(index, 1)
                    this.toolbarItems = [...this.toolbarItems]
                  })
                  .margin({ left: 10 })
                  .backgroundColor(Color.Red)
              }
            }
          }
        })
      }
      .width('100%')
      .height('80%')
      .layoutWeight(1)
      .margin(10)
    }
    .width('100%')
    .height('100%')
    .padding(10)
  }
}

