@Entry
@Component
struct MultiLineTextProcessor {
  @State inputText: string = "";
  @State fontSize: number = 16;
  @State isBold: boolean = false;
  @State textColor: Color = Color.Black;
  @State words: string[] = [];

  extractWords() {
    const wordPattern = /\w+/g;
    this.words = this.inputText.match(wordPattern) || [];
  }

  build() {
    Column() {
      TextArea({ placeholder: "Enter multi-line text here", text: this.inputText })
        .width("90%")
        .height(150)
        .fontSize(this.fontSize)
        .fontWeight(this.isBold ? FontWeight.Bold : FontWeight.Normal)
        .fontColor(this.textColor)
        .border({ width: 1, color: Color.Gray })
        .onChange((value: string) => {
          this.inputText = value;
          this.extractWords();
        })
        .margin({ top: 20, bottom: 20 })

      Row() {
        Button("Bold")
          .width(80)
          .height(40)
          .onClick(() => {
            this.isBold = !this.isBold;
          })

        Button("Size+")
          .width(80)
          .height(40)
          .margin({ left: 10 })
          .onClick(() => {
            this.fontSize = Math.min(24, this.fontSize + 2);
          })

        Button("Size-")
          .width(80)
          .height(40)
          .margin({ left: 10 })
          .onClick(() => {
            this.fontSize = Math.max(12, this.fontSize - 2);
          })

        Button("Color")
          .width(80)
          .height(40)
          .margin({ left: 10 })
          .onClick(() => {
            this.textColor = this.textColor === Color.Black ? Color.Blue : Color.Black;
          })
      }
      .justifyContent(FlexAlign.Center)
      .margin({ bottom: 20 })

      Text("Preview:")
        .fontSize(16)
        .margin({ bottom: 10 })

      Text(this.inputText)
        .width("90%")
        .fontSize(this.fontSize)
        .fontWeight(this.isBold ? FontWeight.Bold : FontWeight.Normal)
        .fontColor(this.textColor)
        .border({ width: 1, color: '#D3D3D3' })
        .padding(10)
        .margin({ bottom: 20 })

      Text("Extracted Words:")
        .fontSize(16)
        .margin({ bottom: 10 })

      if (this.words.length > 0) {
        ForEach(this.words, (word: string) => {
          Text(word)
            .fontSize(14)
            .margin({ bottom: 5 })
        })
      } else {
        Text("No words extracted.")
          .fontSize(14)
          .margin({ bottom: 5 })
      }
    }
    .width("100%")
    .height("100%")
    .backgroundColor("#f5f5f5")
    .alignItems(HorizontalAlign.Center)
  }
}

@Entry
@Component
struct FullScreenLaunchComponent {
  @State private isEmbeddedMode: boolean = true;
  @State private isSubWindowAllowed: boolean = false;

  build() {
    Column() {
      // Main content area
      Column() {
        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
          .margin({ bottom: 20 });

        Text('Full Screen Launch Component')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .textAlign(TextAlign.Center);

        // Embedded mode control
        Row() {
          Text('Embedded Mode:')
            .fontSize(18)
            .margin({ right: 10 });

          Toggle({ type: ToggleType.Switch, isOn: this.isEmbeddedMode })
            .onChange((isOn: boolean) => {
              this.isEmbeddedMode = isOn;
              this.isSubWindowAllowed = !isOn;
              console.log(`Embedded Mode: ${isOn}, Sub-window Creation: ${!isOn}`);
            });
        }
        .margin({ top: 30 });

        // Sub-window status indicator
        Text(this.isSubWindowAllowed ? 'Sub-window creation enabled' : 'Sub-window creation disabled')
          .fontSize(16)
          .fontColor(this.isSubWindowAllowed ? Color.Green : Color.Red)
          .margin({ top: 20 });
      }
      .width('100%')
      .height('100%')
      .justifyContent(FlexAlign.Center)
      .alignItems(HorizontalAlign.Center)
    }
    .width('100%')
    .height('100%')
  }

  aboutToAppear() {
    this.isEmbeddedMode = true;
    this.isSubWindowAllowed = false;
    console.log('Initialized in embedded mode - Sub-window creation disabled');
  }
}

