@Component
struct TextTransformationApp {
  @State text: string = "Transform me!";
  @State scaleX: number = 1.0;
  @State scaleY: number = 1.0;
  @State rotation: number = 0;
  @State textCase: TextCase = TextCase.Normal;

  build() {
    Column({ space: 20 }) {
      Text('Text Transformation Demo')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 30 });

      TextInput({ placeholder: 'Enter text', text: this.text })
        .onChange((value: string) => { this.text = value; })
        .width('80%');

      Row() {
        Text('Scale X:')
        Slider({
          value: this.scaleX,
          min: 0.5,
          max: 2.0,
          step: 0.1
        })
        .onChange((value: number) => { this.scaleX = value; })
        .width('60%')
      }

      Row() {
        Text('Scale Y:')
        Slider({
          value: this.scaleY,
          min: 0.5,
          max: 2.0,
          step: 0.1
        })
        .onChange((value: number) => { this.scaleY = value; })
        .width('60%')
      }

      Row() {
        Text('Rotation:')
        Slider({
          value: this.rotation,
          min: 0,
          max: 360,
          step: 1
        })
        .onChange((value: number) => { this.rotation = value; })
        .width('60%')
      }

      Row() {
        Button('UPPERCASE')
          .onClick(() => { this.textCase = TextCase.UpperCase; })
        Button('lowercase')
          .onClick(() => { this.textCase = TextCase.LowerCase; })
        Button('Normal')
          .onClick(() => { this.textCase = TextCase.Normal; })
      }

      Text(this.text)
        .fontSize(20)
        .fontColor(Color.Black)
        .textCase(this.textCase)
        .scale({ x: this.scaleX, y: this.scaleY })
        .rotate({ angle: this.rotation })
        .border({ width: 1, color: Color.Gray })
        .padding(10)
        .width('80%');
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

