@Component
struct LongPressGestureCustomTiming {
  @State message: string = "Long press me (custom duration: 1500ms)"
  @State color: ResourceColor = Color.Blue

  build() {
    Column() {
      Text(this.message)
        .fontSize(20)
        .padding(20)
        .backgroundColor(this.color)
        .borderRadius(10)
        .gesture(
          LongPressGesture({ repeat: false, duration: 1500 })
            .onAction(() => {
              this.message = "Long press action started"
              this.color = Color.Green
              console.log("LongPressGesture onAction triggered")
            })
            .onActionEnd(() => {
              this.message = "Long press action ended"
              this.color = Color.Blue
              console.log("LongPressGesture onActionEnd triggered")
            })
            .onActionCancel(() => {
              this.message = "Long press action canceled"
              this.color = Color.Red
              console.log("LongPressGesture onActionCancel triggered")
            })
        )
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

