@Component
struct SophisticatedTextStyling {
  @State isBold: boolean = false;
  @State isItalic: boolean = false;
  @State textColor: string = '#000000';
  @State decorationType: TextDecorationType = TextDecorationType.None;
  @State decorationColor: string = '#FF0000';
  @State decorationStyle: TextDecorationStyle = TextDecorationStyle.SOLID;
  @State shadowEnabled: boolean = false;
  @State gradientEnabled: boolean = false;

  build() {
    Column({ space: 20 }) {
      Text('Sophisticated Text Styling Demo')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
