        .fontWeight(this.isBold ? FontWeight.Bold : FontWeight.Normal)
        .fontStyle(this.isItalic ? FontStyle.Italic : FontStyle.Normal)
        .fontColor(this.textColor)
        .decoration({
          type: this.decorationType,
          color: this.decorationColor,
          style: this.decorationStyle
        })
        .shadow(this.shadowEnabled ? {
          offsetX: 5,
          offsetY: 5,
          radius: 10,
          color: '#000000'
        } : null)
        .linearGradient(this.gradientEnabled ? {
          angle: 90,
          colors: [['#ff4c8f', 0], ['#8933ff', 1]]
