          .onClick(() => { this.isItalic = !this.isItalic; })
          .width('30%');
      }
      .width('100%')
      .justifyContent(FlexAlign.Center);

      Row({ space: 10 }) {
        Button('Red')
          .onClick(() => { this.textColor = '#FF0000'; })
          .width('20%');

        Button('Blue')
          .onClick(() => { this.textColor = '#0000FF'; })
          .width('20%');

        Button('Green')
          .onClick(() => { this.textColor = '#00FF00'; })
          .width('20%');
      }
      .width('100%')
      .justifyContent(FlexAlign.Center);

      Row({ space: 10 }) {
        Button('Underline')
          .onClick(() => {
            this.decorationType = this.decorationType === TextDecorationType.Underline ?
              TextDecorationType.None : TextDecorationType.Underline;
          })
          .width('30%');

        Button('LineThrough')
          .onClick(() => {
            this.decorationType = this.decorationType === TextDecorationType.LineThrough ?
              TextDecorationType.None : TextDecorationType.LineThrough;
          })
          .width('30%');

        Button('Overline')
          .onClick(() => {
            this.decorationType = this.decorationType === TextDecorationType.Overline ?
              TextDecorationType.None : TextDecorationType.Overline;
          })
          .width('30%');
      }
      .width('100%')
      .justifyContent(FlexAlign.Center);

      Row({ space: 10 }) {
        Button('Solid')
          .onClick(() => { this.decorationStyle = TextDecorationStyle.SOLID; })
          .width('20%');

        Button('Dotted')
          .onClick(() => { this.decorationStyle = TextDecorationStyle.DOTTED; })
          .width('20%');

        Button('Dashed')
          .onClick(() => { this.decorationStyle = TextDecorationStyle.DASHED; })
