      Button() {
        Image($r('app.media.app_icon'))
          .width(40)
          .height(40)
      }
      .width(this.buttonSize)
      .height(this.buttonSize)
      .backgroundColor(this.buttonColor)
      .borderRadius(this.buttonSize / 2)
      .opacity(this.opacityValue)
      .onClick(() => {
        this.isPressed = !this.isPressed;
        this.buttonColor = this.isPressed ? Color.Red : Color.Blue;
        this.opacityValue = this.isPressed ? 0.7 : 1.0;
        animateTo({ duration: 300 }, () => {
          this.buttonSize = this.isPressed ? 80 : 60;
        });
      })
      .position({ x: '50%', y: '80%' })
      .margin(20)
      .animation({
        duration: 300,
        curve: Curve.EaseInOut
      })
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
  }
}

@Entry
@Component
struct AdaptiveSearchLayout {
  @State searchText: string = '';
  @State isExpanded: boolean = false;
  @State isError: boolean = false;
  @State items: string[] = [
    'Apple', 'Banana', 'Orange', 'Grapes', 'Mango',
    'Pineapple', 'Strawberry', 'Watermelon', 'Cherry'
  ];

  filteredItems(): string[] {
    if (this.searchText.trim() === '') {
      return this.items;
    }
    return this.items.filter(item =>
      item.toLowerCase().includes(this.searchText.toLowerCase())
    );
  }

  validateInput(text: string): void {
    this.isError = text.length > 50;
  }

  build() {
    Column() {
      // Adaptive search bar
      Row() {
        Image($r('app.media.app_icon'))
          .width(24)
          .height(24)
          .margin({ right: 8 })

        TextInput({ placeholder: 'Search...', text: this.searchText })
          .width(this.isExpanded ? '80%' : '60%')
          .height(40)
          .onChange((value: string) => {
            this.searchText = value;
            this.validateInput(value);
          })
          .onFocus(() => {
            this.isExpanded = true;
          })
          .onBlur(() => {
            this.isExpanded = false;
          })
          .border({
            width: 1,
            color: this.isError ? Color.Red : Color.Gray
          })
          .maxLength(50)
          .transition({ type: TransitionType.All })
          .animation({ duration: 200 })

        if (this.isExpanded) {
          Button('Cancel')
            .margin({ left: 8 })
            .onClick(() => {
              this.searchText = '';
              this.isExpanded = false;
              this.isError = false;
            })
        }
      }
      .padding(16)
      .backgroundColor('#f0f0f0')
      .borderRadius(8)
      .width('100%')

      // Error message
      if (this.isError) {
        Text('Error: Input must not exceed 50 characters')
          .fontSize(12)
          .fontColor(Color.Red)
          .margin({ top: 5 })
      }

      // Adaptive results layout
      if (this.filteredItems().length > 0) {
        Grid() {
          ForEach(this.filteredItems(), (item: string) => {
            GridItem() {
              Column() {
                Text(item)
                  .fontSize(16)
                  .margin({ bottom: 4 })
                Divider()
                  .strokeWidth(1)
                  .color('#e0e0e0')
              }
              .padding(12)
              .backgroundColor(Color.White)
              .borderRadius(8)
              .shadow({ radius: 2, color: '#10000000', offsetX: 1, offsetY: 1 })
            }
            .aspectRatio(1)
          })
        }
        .columnsTemplate('1fr 1fr 1fr')
        .columnsGap(12)
        .rowsGap(12)
        .padding(16)
        .width('100%')
        .layoutWeight(1)
      } else if (this.searchText) {
        Text('No results found')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#fafafa')
  }
}

@Entry
@Component
struct CameraGalleryApp {
  @State imagePaths: string[] = [];
  @State hasImage: boolean = false;
  @State selectedImage: string = '';
  @State showFullScreen: boolean = false;
  @State cameraPermissionGranted: boolean = false;
  @State storagePermissionGranted: boolean = false;

  build() {
    Column() {
      if (!this.cameraPermissionGranted || !this.storagePermissionGranted) {
        Text('Please grant camera and storage permissions to proceed.')
          .fontSize(18)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 });
      }

      Button('Take Picture')
        .onClick(async () => {
          if (!this.cameraPermissionGranted) {
            await this.requestCameraPermission();
          }
          if (this.cameraPermissionGranted) {
            const result = await this.takePicture();
            if (result) {
              this.imagePaths.push(result);
              this.hasImage = true;
            }
          }
        })
        .margin({ top: 20, bottom: 20 });

      if (this.hasImage) {
        Grid() {
          ForEach(this.imagePaths, (imagePath: string) => {
            GridItem() {
              Image(imagePath)
                .width('100%')
                .aspectRatio(1)
                .objectFit(ImageFit.Cover)
                .borderRadius(5)
                .onClick(() => {
                  this.selectedImage = imagePath;
                  this.showFullScreen = true;
                });
            }
          })
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsGap(10)
        .columnsGap(10)
        .padding(10);
      }

      if (this.showFullScreen) {
        Stack() {
          Image(this.selectedImage)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%');

          Button('Close')
            .onClick(() => {
              this.showFullScreen = false;
            })
            .position({ x: 20, y: 20 })
            .backgroundColor('#FFFFFF')
            .padding({ left: 10, right: 10, top: 5, bottom: 5 })
            .borderRadius(5);
        }
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5');
  }

  async requestCameraPermission(): Promise<void> {
    this.cameraPermissionGranted = true;
  }

  async requestStoragePermission(): Promise<void> {
    this.storagePermissionGranted = true;
  }

  async takePicture(): Promise<string> {
    return 'app.media.app_icon';
  }

  async saveImage(imagePath: string): Promise<void> {
    console.log(`Image saved at: ${imagePath}`);
  }
}

