@Entry
@Component
struct CustomComponentPresentation {
  @State selectedOption: string = "Select an option";
  @State showComponent: boolean = false;
  @State componentToShow: string = "";

  build() {
    Column() {
      Select([
        { value: 'Component A', icon: $r('app.media.app_icon') },
        { value: 'Component B', icon: $r('app.media.app_icon') },
        { value: 'Component C', icon: $r('app.media.app_icon') }
      ])
      .value(this.selectedOption)
      .onSelect((index: number, value: string) => {
        this.selectedOption = value;
        this.componentToShow = value;
        this.showComponent = true;
        console.info(`Selected: ${value}`);
      })
      .width('80%')
      .margin(20);

      if (this.showComponent) {
        this.getCustomComponent(this.componentToShow);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Start)
  }

  @Builder
  getCustomComponent(componentName: string) {
    Column() {
      if (componentName === 'Component A') {
        ComponentA()
      } else if (componentName === 'Component B') {
        ComponentB()
      } else if (componentName === 'Component C') {
        ComponentC()
      }
    }
    .width('100%')
    .margin({ top: 20 })
  }
}

