    this.apiVersion = this.getSystemApiVersion();
    this.isCompatible = this.checkApiCompatibility();
  }

  private getSystemApiVersion(): number {
    // Simulate getting the actual system API version
    return 9; // Example value, replace with actual logic
  }

  private checkApiCompatibility(): boolean {
    // Check if the system API version meets the minimum requirement
    const minRequiredVersion = 9;
    return this.apiVersion >= minRequiredVersion;
  }

