@Component
struct ImageGridApp {
  @State selectedImage: Resource = $r('app.media.app_icon');
  @State showDetail: boolean = false;
  @State description: string = '';

  private images: Array<ImageItem> = [
    new ImageItem(1, 'Mountain View', $r('app.media.app_icon'), 'A breathtaking view of a mountain range during sunset.'),
    new ImageItem(2, 'Ocean Waves', $r('app.media.app_icon'), 'Waves crashing against the shore on a sunny day.'),
    new ImageItem(3, 'Forest Trail', $r('app.media.app_icon'), 'A serene path winding through a lush green forest.'),
    new ImageItem(4, 'Desert Dunes', $r('app.media.app_icon'), 'Golden sand dunes under a clear blue sky.')
  ];

  build() {
    Column() {
      if (this.showDetail) {
        Stack() {
          Image(this.selectedImage)
            .width('100%')
            .height('100%')
            .objectFit(ImageFit.Cover);

          Column() {
            Text(this.description)
              .fontSize(18)
              .fontColor(Color.White)
              .backgroundColor('#00000080')
              .padding(10)
              .width('100%')
              .textAlign(TextAlign.Center);

            Button('Back')
              .onClick(() => {
                this.showDetail = false;
              })
              .margin({ top: 20 })
              .width('100%')
              .height(40);
          }
          .position({ x: 0, y: 0 });
        }
      } else {
        Grid() {
          ForEach(this.images, (item: ImageItem) => {
            GridItem() {
              Column() {
                Image(item.image)
                  .width('100%')
                  .aspectRatio(1)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(5)
                  .onClick(() => {
                    this.selectedImage = item.image;
                    this.description = item.description;
                    this.showDetail = true;
