@Entry
@Component
struct LoginScreen {
  @State username: string = ''
  @State password: string = ''
  @State loginMessage: string = ''
  @State isSuccess: boolean = false

  validateInput(): boolean {
    if (this.username && this.password) {
      this.loginMessage = 'Login successful!'
      this.isSuccess = true
      return true
    } else {
      this.loginMessage = 'Please enter both username and password.'
      this.isSuccess = false
      return false
    }
  }

  build() {
    Column() {
      // Username Label and Input
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your username', text: this.username })
        .onChange((value: string) => {
          this.username = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Password Label and Input
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Login Button
      Button('Login')
        .onClick(() => {
          this.validateInput()
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      // Login Message
      if (this.loginMessage) {
        Text(this.loginMessage)
          .fontSize(16)
          .margin({ top: 20 })
          .fontColor(this.isSuccess ? Color.Green : Color.Red)
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

@Entry
@Component
struct LoginScreen {
  @State email: string = ''
  @State password: string = ''
  @State message: string = ''
  @State isSuccess: boolean = false
  @State showMessage: boolean = false

  build() {
    Column() {
      // App Logo/Header
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ bottom: 30 })

      // Email Input Section
      Text('Email Address')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })
        .width('80%')
        .textAlign(TextAlign.Start)

      TextInput({ placeholder: 'Enter your email' })
        .width('80%')
        .height(40)
        .margin({ bottom: 20 })
        .borderRadius(5)
        .borderWidth(1)
        .borderColor('#CCCCCC')
        .onChange((value: string) => {
          this.email = value
        })

      // Password Input Section
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })
        .width('80%')
        .textAlign(TextAlign.Start)

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .width('80%')
        .height(40)
        .margin({ bottom: 30 })
        .borderRadius(5)
        .borderWidth(1)
        .borderColor('#CCCCCC')
        .onChange((value: string) => {
          this.password = value
        })

      // Login Button
      Button('Login', { type: ButtonType.Capsule })
        .width('80%')
        .height(45)
        .backgroundColor('#4CAF50')
        .fontColor(Color.White)
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .onClick(() => {
          if (this.validateCredentials()) {
            this.message = 'Welcome! Login successful!'
            this.isSuccess = true
          } else {
            this.message = 'Invalid email or password'
            this.isSuccess = false
          }
          this.showMessage = true
        })

      // Status Message
      if (this.showMessage) {
        Text(this.message)
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
          .fontColor(this.isSuccess ? Color.Green : Color.Red)
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#F5F5F5')
  }

  validateCredentials(): boolean {
    const emailValid = this.validateEmail(this.email)
    const passwordValid = this.password.length >= 6

    return emailValid && passwordValid &&
           this.email === 'test@example.com' &&
           this.password === 'password123'
  }

  validateEmail(email: string): boolean {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return re.test(email)
  }
}

