@Component
struct RelativeContainerLayout {
  build() {
    RelativeContainer() {
      // Header positioned at top with full width
      Text("Header")
        .width("100%")
        .height(80)
        .backgroundColor("#409EFF")
        .fontSize(24)
        .textAlign(TextAlign.Center)
        .alignRules({
          top: { anchor: "__container__", align: VerticalAlign.Top },
          left: { anchor: "__container__", align: HorizontalAlign.Start },
          right: { anchor: "__container__", align: HorizontalAlign.End }
        })
        .id("header")

      // Side navigation positioned left
      Text("Navigation")
        .width(120)
        .height("100%")
        .backgroundColor("#67C23A")
        .fontSize(18)
        .textAlign(TextAlign.Center)
        .alignRules({
          top: { anchor: "header", align: VerticalAlign.Bottom },
          left: { anchor: "__container__", align: HorizontalAlign.Start },
          bottom: { anchor: "footer", align: VerticalAlign.Top }
        })
        .id("nav")

      // Main content area
      Text("Main Content")
        .width("100%")
        .height("100%")
        .backgroundColor("#E6A23C")
        .fontSize(18)
        .textAlign(TextAlign.Center)
        .alignRules({
          top: { anchor: "header", align: VerticalAlign.Bottom },
          left: { anchor: "nav", align: HorizontalAlign.End },
          right: { anchor: "__container__", align: HorizontalAlign.End },
          bottom: { anchor: "footer", align: VerticalAlign.Top }
        })
        .id("content")

      // Footer positioned at bottom with full width
      Text("Footer")
        .width("100%")
        .height(80)
        .backgroundColor("#F56C6C")
        .fontSize(24)
        .textAlign(TextAlign.Center)
        .alignRules({
          bottom: { anchor: "__container__", align: VerticalAlign.Bottom },
          left: { anchor: "__container__", align: HorizontalAlign.Start },
          right: { anchor: "__container__", align: HorizontalAlign.End }
        })
        .id("footer")

      // Floating button positioned relative to content
      Button("+")
        .width(60)
        .height(60)
        .borderRadius(30)
        .backgroundColor("#909399")
        .fontSize(24)
        .alignRules({
          right: { anchor: "content", align: HorizontalAlign.End },
          bottom: { anchor: "content", align: VerticalAlign.Bottom }
        })
    }
    .width("100%")
    .height("100%")
    .backgroundColor("#ffffff")
  }
}

