@Entry
@Component
struct CustomSpinnerAnimation {
    @State private rotation: number = 0;
    private intervalID: number = -1;

    aboutToAppear() {
        this.intervalID = setInterval(() => {
            this.rotation = (this.rotation + 10) % 360;
        }, 50);
    }

    aboutToDisappear() {
        if (this.intervalID !== -1) {
            clearInterval(this.intervalID);
        }
    }

    build() {
        Column() {
            Stack() {
                Circle()
                    .width(100)
                    .height(100)
                    .stroke(Color.Blue)
                    .strokeWidth(10)
                    .strokeDashArray([10, 20])
                    .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })
            }
            .width(100)
            .height(100)
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .backgroundColor(Color.White)
    }
}

@Entry
@Component
struct PinchGestureApp {
  @State scaleValue: number = 1.0;
  @State fingerCount: number = 2;
  @State minDistance: number = 50;
  @State callbackLog: string = '';

  build() {
    Column() {
      Text("Pinch Gesture Demo")
        .fontSize(20)
        .margin(10);

      Text(`Current Scale: ${this.scaleValue.toFixed(2)}`)
        .fontSize(16)
        .margin(5);

      Text(`Finger Count: ${this.fingerCount}`)
        .fontSize(16)
        .margin(5);

      Text(`Min Distance: ${this.minDistance}px`)
        .fontSize(16)
        .margin(5);

      Image($r("app.media.app_icon"))
        .width(200)
        .height(200)
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .gesture(
          PinchGesture({ fingers: this.fingerCount, distance: this.minDistance })
            .onActionStart((event: PinchGestureEvent) => {
              this.callbackLog += `Action Start: Fingers=${this.fingerCount}
`;
            })
            .onActionUpdate((event: PinchGestureEvent) => {
              this.scaleValue *= event.scale;
              this.callbackLog += `Action Update: Scale=${event.scale.toFixed(2)}
`;
            })
            .onActionEnd(() => {
              this.callbackLog += `Action End: Pinch gesture completed
`;
            })
            .onActionCancel(() => {
              this.callbackLog += `Action Cancel: Pinch gesture cancelled
`;
            })
        );

      Text(this.callbackLog)
        .fontSize(14)
        .margin(10)
        .border({ width: 1, color: Color.Gray })
        .width('90%')
        .height(200);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

