@Entry
@Component
struct ReusableUIAbstraction {
  @State private title: string = 'Reusable UI Abstraction';
  @State private description: string = 'Using Builder Decorator in ArkTS';
  @State private isActive: boolean = false;

  // Reusable Title Builder
  @Builder
  TitleBuilder(title: string) {
    Text(title)
      .fontSize(28)
      .fontWeight(FontWeight.Bold)
      .fontColor(Color.Black)
      .margin({ bottom: 10 });
  }

  // Reusable Description Builder
  @Builder
  DescriptionBuilder(description: string) {
    Text(description)
      .fontSize(18)
      .fontColor(Color.Gray)
      .margin({ bottom: 20 });
  }

  // Reusable Button Builder
  @Builder
  ButtonBuilder(label: string, onClick: () => void) {
    Button(label)
      .onClick(onClick)
      .width(200)
      .height(50)
      .backgroundColor(Color.Blue)
      .fontColor(Color.White)
      .margin(10);
  }

  // Reusable Toggle Builder
  @Builder
  ToggleBuilder() {
    Button(this.isActive ? 'Active' : 'Inactive')
      .backgroundColor(this.isActive ? Color.Green : Color.Red)
      .fontColor(Color.White)
      .onClick(() => {
        this.isActive = !this.isActive;
      })
      .margin({ top: 20 });
  }

  // Reusable Image Builder
  @Builder
  ImageBuilder(icon: Resource) {
    Image(icon)
      .width(100)
      .height(100)
      .margin(10);
  }

  build() {
    Column() {
      this.TitleBuilder(this.title);
      this.DescriptionBuilder(this.description);
      this.ButtonBuilder('Click Me', () => {
        console.log('Button clicked!');
      });
      this.ToggleBuilder();
      this.ImageBuilder($r('app.media.app_icon'));
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

