@Entry
@Component
struct FullScreenLaunchComponent {
  @State isHostActive: boolean = false
  @State isProviderActive: boolean = false
  @State sharedData: string = 'No data shared'
  @State connectionStatus: string = 'Disconnected'

  // Simulate host initiating interaction
  private hostInitiate() {
    this.isHostActive = true
    this.sharedData = 'Host shared data'
    this.updateConnectionStatus()
    console.log('Host initiated interaction')
  }

  // Simulate provider responding
  private providerRespond() {
    this.isProviderActive = true
    this.sharedData = 'Provider response data'
    this.updateConnectionStatus()
    console.log('Provider responded')
  }

  // Update connection status based on states
  private updateConnectionStatus() {
    if (this.isHostActive && this.isProviderActive) {
      this.connectionStatus = 'Fully Connected'
    } else if (this.isHostActive || this.isProviderActive) {
      this.connectionStatus = 'Partial Connection'
    } else {
      this.connectionStatus = 'Disconnected'
    }
  }

  // Reset the interaction
  private resetInteraction() {
    this.isHostActive = false
    this.isProviderActive = false
    this.sharedData = 'No data shared'
    this.connectionStatus = 'Disconnected'
    console.log('Interaction reset')
  }

  build() {
    Column({ space: 20 }) {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 50 })

      Text('Connection Status: ' + this.connectionStatus)
        .fontSize(20)
        .fontColor(this.connectionStatus === 'Fully Connected' ? Color.Green :
                  this.connectionStatus === 'Partial Connection' ? Color.Blue : Color.Red)

      Text('Shared Data: ' + this.sharedData)
        .fontSize(18)
        .margin({ top: 20 })

      Row({ space: 20 }) {
        Button('Host Initiate')
          .width(150)
          .height(50)
          .onClick(() => this.hostInitiate())

        Button('Provider Respond')
          .width(150)
          .height(50)
          .onClick(() => this.providerRespond())
      }
      .margin({ top: 20 })

      Button('Reset')
        .width(200)
        .height(50)
        .onClick(() => this.resetInteraction())
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(Color.White)
  }
}

