@Entry
@Component
struct FullScreenLaunchComponent {
  @State private isFocused: boolean = false;
  @State private keyboardInput: string = '';
  @State private accessibilityEnabled: boolean = true;
  @State private buttonClicked: boolean = false;

  private handleButtonClick(): void {
    this.buttonClicked = true;
    console.log('Button clicked synchronously');
  }

  private handleTextInputChange(value: string): void {
    this.keyboardInput = value;
    console.log('Text input changed synchronously:', value);
  }

  private handleToggleChange(isOn: boolean): void {
    this.accessibilityEnabled = isOn;
    console.log('Accessibility ' + (isOn ? 'enabled' : 'disabled') + ' synchronously');
  }

  build() {
    Column() {
      // Accessibility toggle
      Toggle({ type: ToggleType.Switch, isOn: this.accessibilityEnabled })
        .onChange((isOn: boolean) => {
          this.handleToggleChange(isOn);
        })
        .margin({ bottom: 20 });

      // Accessible button with synchronous event handling
      Button('Accessible Button')
        .fontSize(20)
        .backgroundColor(this.isFocused ? Color.Blue : Color.Gray)
        .onClick(() => {
          this.handleButtonClick();
        })
        .onFocus(() => {
          this.isFocused = true;
          console.log('Button focused synchronously');
        })
        .onBlur(() => {
          this.isFocused = false;
          console.log('Button blurred synchronously');
        })
        .accessibilityText(this.accessibilityEnabled ? 'Primary Button' : '')
        .accessibilityDescription('Tap to perform action');

      // Accessible text input
      TextInput({ placeholder: 'Enter text' })
        .fontSize(20)
        .margin({ top: 20 })
        .onChange((value: string) => {
          this.handleTextInputChange(value);
        })
        .accessibilityText(this.accessibilityEnabled ? 'Text Input Field' : '')
        .accessibilityDescription('Enter your text here');

      // Accessible image
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 20 })
        .accessibilityText(this.accessibilityEnabled ? 'Application Icon' : '')
        .accessibilityDescription('Company logo image');

      // Status indicators
      Text(this.accessibilityEnabled ? 'Accessibility Enabled' : 'Accessibility Disabled')
        .fontSize(16)
        .fontColor(this.accessibilityEnabled ? Color.Green : Color.Red)
        .margin({ top: 20 });

      Text(this.buttonClicked ? 'Button was clicked!' : 'Button not clicked yet')
        .fontSize(16)
        .fontColor(Color.Black)
        .margin({ top: 10 });
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

