@Entry
@Component
struct ImageKnife {
  @State private imageUrl: string = 'https://example.com/image.jpg';
  @State private showPlaceholder: boolean = true;
  @State private showError: boolean = false;
  @State private isLoading: boolean = false;

  build() {
    Column() {
      if (this.showPlaceholder && !this.isLoading) {
        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
          .onAppear(() => {
            this.loadImage();
          });
      } else if (this.isLoading) {
        Progress({ value: 50, total: 100 })
          .width(100)
          .height(100)
          .color(Color.Blue);
      } else if (this.showError) {
        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
          .onClick(() => {
            this.resetAndLoad();
          });
      } else {
        Image(this.imageUrl)
          .width(100)
          .height(100)
          .onError(() => {
            this.handleError();
          });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }

  private loadImage() {
    this.isLoading = true;
    setTimeout(() => {
      this.isLoading = false;
      this.showPlaceholder = false;
      this.showError = false;
    }, 2000);
  }

  private handleError() {
    this.showError = true;
    this.showPlaceholder = false;
    this.isLoading = false;
  }

  private resetAndLoad() {
    this.showPlaceholder = true;
    this.showError = false;
    this.isLoading = false;
    this.loadImage();
  }
}

