@Component
struct TextSelectionMenuApp {
  @State selectedText: string = '';
  @State isMenuVisible: boolean = false;
  private menuOptions: string[] = ["Copy", "Share", "Search", "Highlight", "Translate"];

  private handleMenuAction(action: string): void {
    switch (action) {
      case 'Copy':
        console.info(`Copied: ${this.selectedText}`);
        break;
      case 'Share':
        console.info(`Shared: ${this.selectedText}`);
        break;
      case 'Search':
        console.info(`Searching: ${this.selectedText}`);
        break;
      case 'Highlight':
        console.info(`Highlighted: ${this.selectedText}`);
        break;
      case 'Translate':
        console.info(`Translated: ${this.selectedText}`);
        break;
      default:
        console.info('No action matched');
    }
    this.isMenuVisible = false;
  }

  build() {
    Column() {
      Text('Select text below to see custom actions menu')
        .fontSize(18)
        .margin(20)
        .onTextSelectionChange((start: number, end: number) => {
          this.selectedText = 'Sample selected text';
          this.isMenuVisible = true;
        });

      if (this.isMenuVisible) {
        Column() {
          ForEach(this.menuOptions, (option: string) => {
            Text(option)
              .fontSize(16)
              .padding(10)
              .backgroundColor(Color.Gray)
              .onClick(() => {
                this.handleMenuAction(option);
              });
          })
        }
        .border({ width: 1, color: Color.Black })
        .margin(10);
      }

      Text(`Selected: ${this.selectedText}`)
        .fontSize(16)
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F0F0F0');
  }
}

