@Entry
@Component
struct FullScreenLaunchComponent {
  @State errorType: string = '';
  @State showErrorDialog: boolean = false;
  @State errorMessage: string = '';
  @State isLoading: boolean = false;
  @State testResult: string = '';

  private simulateError(type: string) {
    try {
      switch (type) {
        case 'launch':
          throw new Error('Failed to launch FullScreen component: Permission denied');
        case 'render':
          throw new Error('Render process failed: Component tree corrupted');
        case 'network':
          throw new Error('Network request failed: Connection timeout');
        case 'data':
          throw new Error('Data parsing failed: Invalid format');
        case 'test':
          throw new Error('Test operation failed: Unexpected error');
        default:
          throw new Error('Unknown error occurred');
      }
    } catch (error) {
      this.errorType = type;
      this.errorMessage = (error as Error).message;
      this.showErrorDialog = true;
      console.error(`[${type.toUpperCase()}_ERROR]`, error);
      this.showAlertDialog();
    }
  }

  private showAlertDialog() {
    console.info('Showing error dialog:', this.errorMessage);
    this.showErrorDialog = true;
  }

  private startTest() {
    this.isLoading = true;
    setTimeout(() => {
      try {
        if (Math.random() > 0.5) {
          this.simulateError('test');
        } else {
          this.testResult = 'Test Passed!';
        }
      } finally {
        this.isLoading = false;
      }
    }, 2000);
  }

  private retryAction() {
    this.showErrorDialog = false;
    this.errorMessage = '';
    this.testResult = '';
  }

  build() {
    Column({ space: 20 }) {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ bottom: 30 });

      Text('FullScreen Launch Component')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 40 });

      Button('Simulate Launch Error')
        .width('80%')
        .onClick(() => this.simulateError('launch'));

      Button('Simulate Render Error')
        .width('80%')
        .onClick(() => this.simulateError('render'));

      Button('Simulate Network Error')
        .width('80%')
        .onClick(() => this.simulateError('network'));

      Button('Simulate Data Error')
        .width('80%')
        .onClick(() => this.simulateError('data'));

      Button('Start Test')
        .width('80%')
        .onClick(() => this.startTest())
        .margin({ top: 20 });

      if (this.isLoading) {
        Progress({ value: 50 })
          .width(200)
          .height(20)
          .margin({ top: 20 });
      } else if (this.testResult) {
        Text(this.testResult)
          .fontSize(24)
          .fontColor(Color.Green)
          .margin({ top: 20 });
      }

      if (this.showErrorDialog) {
        Text(this.errorMessage)
          .fontSize(16)
          .fontColor(Color.Red)
          .margin(10);

        Button('Retry')
          .width('80%')
          .onClick(() => this.retryAction());
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }
}

@Entry
@Component
struct RemoteWindowAnimation {
  @State isWindowVisible: boolean = false
  @State windowScale: number = 0.1
  @State windowOpacity: number = 0
  @State windowPosition: number = -300

  build() {
    Column() {
      Button('Toggle Remote Window')
        .onClick(() => {
          this.isWindowVisible = !this.isWindowVisible
          animateTo({
            duration: 500,
            curve: Curve.EaseInOut
          }, () => {
            this.windowScale = this.isWindowVisible ? 1 : 0.1
            this.windowOpacity = this.isWindowVisible ? 1 : 0
            this.windowPosition = this.isWindowVisible ? 0 : -300
          })
        })
        .margin(20)

      if (this.isWindowVisible) {
        Stack() {
          Column() {
            Text('Remote Window')
              .fontSize(24)
              .fontWeight(FontWeight.Bold)
              .margin(10)
              .fontColor(Color.White)

            Text('This window features animation capabilities')
              .fontSize(16)
              .margin(10)
              .fontColor(Color.White)

            Image($r('app.media.app_icon'))
              .width(100)
              .height(100)
              .margin(10)
          }
          .width('80%')
          .height('60%')
          .backgroundColor(Color.Black)
          .borderRadius(10)
          .scale({ x: this.windowScale, y: this.windowScale })
          .opacity(this.windowOpacity)
          .translate({ x: this.windowPosition, y: 0 })
          .animation({
            duration: 500,
            curve: Curve.EaseInOut
          })
        }
        .align(Alignment.Center)
      }
    }
    .width('100%')
    .height('100%')
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
  }
}

@Entry
@Component
struct ProgressIndicatorsExample {
  @State linearProgress: number = 0
  @State capsuleProgress: number = 0
  @State ringProgress: number = 0
  @State scaleRingProgress: number = 0
  @State angle: number = 0
  private intervalId: number = -1

  aboutToAppear() {
    this.intervalId = setInterval(() => {
      if (this.linearProgress < 100) {
        this.linearProgress += 1
        this.capsuleProgress += 1
        this.ringProgress += 1
        this.scaleRingProgress += 1
        this.angle += 3.6
      } else {
        this.linearProgress = 0
        this.capsuleProgress = 0
        this.ringProgress = 0
        this.scaleRingProgress = 0
        this.angle = 0
      }
    }, 50)
  }

  aboutToDisappear() {
    if (this.intervalId !== -1) {
      clearInterval(this.intervalId)
    }
  }

  build() {
    Column({ space: 20 }) {
      // Linear Progress with custom styling
      Text('Linear Progress').fontSize(18)
      Progress({
        value: this.linearProgress,
        total: 100,
        type: ProgressType.Linear
      })
        .width('80%')
        .height(20)
        .color('#4CAF50')
        .backgroundColor('#E0E0E0')

      // Capsule Progress with custom styling
      Text('Capsule Progress').fontSize(18)
      Row() {
        Progress({
          value: this.capsuleProgress,
          total: 100,
          type: ProgressType.Linear
        })
          .width('70%')
          .height(30)
          .borderRadius(15)
          .color('#2196F3')
          .backgroundColor('#E0E0E0')

        Text(`${this.capsuleProgress}%`)
          .fontSize(14)
          .margin({ left: 10 })
      }
      .width('80%')
      .justifyContent(FlexAlign.Center)

      // Ring Progress with custom styling
      Text('Ring Progress').fontSize(18)
      Stack() {
        Circle()
          .width(150)
          .height(150)
          .stroke('#E0E0E0')
          .strokeWidth(10)
          .fill('transparent')

        Circle()
          .width(150)
          .height(150)
          .stroke('#FF5722')
          .strokeWidth(10)
          .fill('transparent')
          .strokeDashArray([Math.PI * 150, Math.PI * 150])
          .strokeDashOffset(Math.PI * 150 * (1 - this.ringProgress / 100))
          .rotate({ x: 0, y: 0, z: 1, angle: -90 })

        Text(`${this.ringProgress}%`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
      }
      .width(150)
      .height(150)

      // ScaleRing Progress with scan effect and custom styling
      Text('ScaleRing Progress').fontSize(18)
      Stack() {
        Circle()
          .width(150)
          .height(150)
          .stroke('#E0E0E0')
          .strokeWidth(10)
          .fill('transparent')

        Circle()
          .width(150)
          .height(150)
          .stroke('#9C27B0')
          .strokeWidth(10)
          .fill('transparent')
          .strokeDashArray([Math.PI * 150, Math.PI * 150])
          .strokeDashOffset(Math.PI * 150 * (1 - this.scaleRingProgress / 100))
          .rotate({ x: 0, y: 0, z: 1, angle: -90 })

        Image($r('app.media.app_icon'))
          .width(20)
          .height(20)
          .rotate({ x: 0, y: 0, z: 1, angle: this.angle })
          .position({ x: 75, y: 0 })

        Text(`${this.scaleRingProgress}%`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
      }
      .width(150)
      .height(150)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20)
  }
}

