@Component
struct NavigationDrawerApp {
  @State isDrawerOpen: boolean = false;
  @State selectedScreenIndex: number = 0;
  @State dynamicContent: string = 'Default Content';

  build() {
    Row() {
      // Main Content Area
      Column() {
        this.ScreenContent()
        this.DrawerButton()
      }
      .layoutWeight(1)

      // Drawer Panel
      Panel(this.isDrawerOpen) {
        Column() {
          this.NavItem('Home', 0)
          this.NavItem('Profile', 1)
          this.NavItem('Settings', 2)
        }
        .width('80%')
        .height('100%')
        .backgroundColor(Color.White)
      }
      .mode(PanelMode.Mini)
      .type(PanelType.Temporary)
      .dragBar(false)
    }
    .width('100%')
    .height('100%')
  }

  @Builder DrawerButton() {
    Button('Toggle Drawer')
      .onClick(() => {
        this.isDrawerOpen = !this.isDrawerOpen
      })
  }

  @Builder NavItem(label: string, index: number) {
    Text(label)
      .fontSize(20)
      .margin(10)
      .onClick(() => {
        this.selectedScreenIndex = index
        this.isDrawerOpen = false
        this.loadDynamicContent(index)
      })
  }

  @Builder ScreenContent() {
    if (this.selectedScreenIndex === 0) {
      this.HomeScreen()
    } else if (this.selectedScreenIndex === 1) {
      this.ProfileScreen()
    } else {
      this.SettingsScreen()
    }
  }

  @Builder HomeScreen() {
    Column() {
      Text('Home Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin(16)
      Text(this.dynamicContent)
        .fontSize(16)
        .margin(16)
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(16)
    }
    .width('100%')
    .height('100%')
  }

  @Builder ProfileScreen() {
    Column() {
      Text('Profile Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin(16)
      Text(this.dynamicContent)
        .fontSize(16)
        .margin(16)
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(16)
    }
    .width('100%')
    .height('100%')
  }

  @Builder SettingsScreen() {
    Column() {
      Text('Settings Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin(16)
      Text(this.dynamicContent)
        .fontSize(16)
        .margin(16)
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(16)
    }
    .width('100%')
    .height('100%')
  }

  loadDynamicContent(index: number) {
    if (index === 0) {
      this.dynamicContent = 'Dynamic Content for Home Screen';
    } else if (index === 1) {
      this.dynamicContent = 'Dynamic Content for Profile Screen';
    } else {
      this.dynamicContent = 'Dynamic Content for Settings Screen';
    }
