struct LunarDatePicker {
  @State isLunar: boolean = true
  @State selectedDate: Date = new Date('2023-01-01')
  @State minDate: Date = new Date('2000-01-01')
  @State maxDate: Date = new Date('2030-12-31')

  updateDisplayDate() {
    return this.selectedDate.toLocaleDateString()
  }

