        .margin({ bottom: 20 })
        .onClick(() => {
          this.isLunar = !this.isLunar
        })

      DatePicker({
        start: this.minDate,
        end: this.maxDate,
        selected: this.selectedDate
      })
        .lunar(this.isLunar)
        .onDateChange((value: Date) => {
          this.selectedDate = value
        })
        .margin({ bottom: 20 })

      Column() {
        Text('Selected Date:')
          .fontSize(20)
          .margin({ bottom: 5 })

