    .padding(20)
    .backgroundColor(Color.White)
  }
}

@Entry
@Component
struct LifecyclePerformanceExample {
  @State private count: number = 0;
  @State private isVisible: boolean = true;

  // Lifecycle callback when the component is created
  aboutToAppear() {
    console.log('[Lifecycle] Component is about to appear');
  }

  // Lifecycle callback when the component is updated
  aboutToUpdate() {
    console.log('[Lifecycle] Component is about to update');
  }

  // Lifecycle callback when the component is destroyed
  aboutToDisappear() {
    console.log('[Lifecycle] Component is about to disappear');
  }

  build() {
    Column() {
      if (this.isVisible) {
        Text(`Count: ${this.count}`)
          .fontSize(20)
          .margin(10);

        Button('Increment Count')
          .onClick(() => {
            this.count += 1;
          })
          .margin(10);

        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
          .margin(10);
      }

      Button(this.isVisible ? 'Hide Component' : 'Show Component')
        .onClick(() => {
          this.isVisible = !this.isVisible;
        })
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

