@Entry
@Component
struct ParentComponent {
  @State componentType: 'typeA' | 'typeB' = 'typeA';
  @State textColor: Color = Color.Black;
  @State fontSize: number = 20;
  @State isActive: boolean = false;

  build() {
    Column() {
      Text("Parent Component")
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin(10);

      Row() {
        Button('Toggle Type')
          .onClick(() => {
            this.componentType = this.componentType === 'typeA' ? 'typeB' : 'typeA';
          })
          .margin(5);

        Button('Toggle Color')
          .onClick(() => {
            this.textColor = this.textColor === Color.Black ? Color.Red : Color.Black;
          })
          .margin(5);

        Button('Toggle Size')
          .onClick(() => {
            this.fontSize = this.fontSize === 20 ? 30 : 20;
          })
          .margin(5);

        Button('Toggle Active')
          .onClick(() => {
            this.isActive = !this.isActive;
          })
          .margin(5);
      }

      AdaptiveComponent({
        type: this.componentType,
        textColor: this.textColor,
        fontSize: this.fontSize,
        isActive: this.isActive,
        onAction: () => {
          console.log("Action triggered in adaptive component");
        }
      })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

@Component
struct AdaptiveComponent {
  @Prop type: 'typeA' | 'typeB';
  @Prop textColor: Color;
  @Prop fontSize: number;
  @Prop isActive: boolean;
  @Prop onAction: () => void;

  build() {
    Column() {
      if (this.type === 'typeA') {
        Text("Type A Display")
          .fontSize(this.fontSize)
          .fontColor(this.textColor)
          .margin(10);

        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
          .margin(10);
      } else {
        Text("Type B Display")
          .fontSize(this.fontSize + 5)
          .fontColor(this.textColor)
          .fontWeight(FontWeight.Bold)
          .margin(10);

        Row() {
          Image($r('app.media.app_icon'))
            .width(80)
            .height(80)
            .margin(5);

          Image($r('app.media.app_icon'))
            .width(80)
            .height(80)
            .margin(5);
        }
      }

      Button(this.isActive ? 'Active' : 'Inactive')
        .onClick(() => {
          this.onAction();
        })
        .backgroundColor(this.isActive ? Color.Green : Color.Gray)
        .margin(10);
    }
    .borderWidth(1)
    .borderColor(Color.Gray)
    .padding(10)
  }
}

