import promptAction from '@ohos.promptAction';

@Entry
@Component
struct UserRegistrationForm {
  @State name: string = '';
  @State email: string = '';
  @State password: string = '';
  @State showDialog: boolean = false;

  validateForm(): boolean {
    if (!this.name || !this.email || !this.password) {
      promptAction.showToast({
        message: 'Please fill in all fields'
      });
      return false;
    }
    return true;
  }

  build() {
    Column({ space: 20 }) {
      Text('Registration Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      // Name Input
      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value;
          });
      }

      // Email Input
      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value;
          });
      }

      // Password Input
      Column() {
        Text('Password:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your password' })
          .type(InputType.Password)
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.password = value;
          });
      }

      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.validateForm()) {
            this.showDialog = true;
          }
        });

      if (this.showDialog) {
        Column() {
          Text('Submitted Information')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

