@Entry
@Component
struct ReusableUIElement {
  @State private isActive: boolean = false;
  @State private counter: number = 0;
  @State private selectedItem: string = 'Option 1';

  // Reusable toggle button with dynamic styling
  @Builder
  ToggleButtonBuilder() {
    Button(this.isActive ? 'Active' : 'Inactive')
      .backgroundColor(this.isActive ? Color.Green : Color.Red)
      .fontColor(Color.White)
      .onClick(() => {
        this.isActive = !this.isActive;
      })
      .margin({ top: 20 });
  }

  // Reusable counter component
  @Builder
  CounterBuilder() {
    Row() {
      Button('Decrement')
        .onClick(() => {
          this.counter--;
        })
        .width(100);
      Text(`Count: ${this.counter}`)
        .fontSize(18)
        .margin({ left: 20, right: 20 });
      Button('Increment')
        .onClick(() => {
          this.counter++;
        })
        .width(100);
    }
    .margin({ top: 20 });
  }

  // Reusable dropdown selector
  @Builder
  DropdownBuilder() {
    Column() {
      Text('Select Item:')
        .fontSize(16)
        .margin({ bottom: 5 });
      Row() {
        ForEach(['Option 1', 'Option 2', 'Option 3'], (item: string) => {
          Button(item)
            .backgroundColor(this.selectedItem === item ? Color.Blue : Color.White)
            .fontColor(this.selectedItem === item ? Color.White : Color.Black)
            .onClick(() => {
              this.selectedItem = item;
            })
            .margin({ right: 5 });
        })
      }
    }
    .margin({ top: 20 });
  }

  // Reusable informational panel
  @Builder
  InfoPanelBuilder() {
    Column() {
      Text('Current Status:')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });
      Text(`Active: ${this.isActive}`)
        .fontSize(14)
        .margin({ bottom: 5 });
      Text(`Counter: ${this.counter}`)
        .fontSize(14)
        .margin({ bottom: 5 });
      Text(`Selected: ${this.selectedItem}`)
        .fontSize(14);
    }
    .padding(15)
    .backgroundColor('#F5F5F5')
    .borderRadius(8)
    .margin({ top: 20 });
  }

  build() {
    Column() {
      this.ToggleButtonBuilder();
      this.CounterBuilder();
      this.DropdownBuilder();
      this.InfoPanelBuilder();
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

