@Component
struct TextInputApp {
  @State userInput: string = ''
  @State formattedText: string = ''
  @State showFormattedText: boolean = false

  build() {
    Column() {
      TextInput({ placeholder: 'Enter your text here' })
        .width('100%')
        .height(40)
        .margin({ bottom: 20 })
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .onChange((value: string) => {
          this.userInput = value
        })

      Button('Format Text')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.userInput) {
            this.formattedText = this.formatText(this.userInput)
            this.showFormattedText = true
          }
        })

      if (this.showFormattedText) {
        Text(this.formattedText)
          .fontSize(24)
          .margin({ top: 20 })
          .fontColor('#333333')
          .textAlign(TextAlign.Center)
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
  }

  private formatText(input: string): string {
    return `Formatted: ${input.toUpperCase()}`
  }
}

@Entry
@Component
struct DisabledStateStyling {
  @State isDisabled: boolean = false;

  build() {
    Column({ space: 20 }) {
      // Method 1: Direct property styling
      Button('Toggle Disabled State')
        .backgroundColor(this.isDisabled ? Color.Gray : Color.Blue)
        .fontColor(Color.White)
        .enabled(!this.isDisabled)
        .onClick(() => {
          this.isDisabled = !this.isDisabled;
        })
        .width('80%')
        .height(50)

      // Method 2: Using StateStyles for more comprehensive control
      Button(this.isDisabled ? 'Disabled' : 'Enabled')
        .stateStyles({
          normal: {
            .backgroundColor(Color.Blue)
            .fontColor(Color.White)
            .borderRadius(5)
          },
          disabled: {
            .backgroundColor(Color.Gray)
            .fontColor('#CCCCCC')
            .borderRadius(5)
          }
        })
        .enabled(!this.isDisabled)
        .onClick(() => {
          this.isDisabled = !this.isDisabled;
        })
        .width('80%')
        .height(50)

      // Demonstrating disabled state for non-interactive components
      Text('Sample Text')
        .fontSize(20)
        .fontColor(this.isDisabled ? '#999999' : Color.Black)
        .margin({ top: 20 })

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .opacity(this.isDisabled ? 0.5 : 1.0)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20)
  }
}

