@Entry
@Component
struct FactorialCalculator {
  @State inputNumber: string = ''
  @State result: string = ''

  build() {
    Column() {
      Text('Factorial Calculator')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter a number' })
        .type(InputType.Number)
        .onChange((value: string) => {
          this.inputNumber = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      Button('Calculate Factorial')
        .onClick(() => {
          const num = parseInt(this.inputNumber)
          if (!isNaN(num) && num >= 0) {
            this.result = this.calculateFactorial(num).toString()
          } else {
            this.result = 'Invalid input'
          }
        })
        .width('80%')
        .margin({ bottom: 20 })

      Text(`Result: ${this.result}`)
        .fontSize(24)
        .fontColor('#4CAF50')
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }

  calculateFactorial(n: number): number {
    if (n === 0 || n === 1) return 1
    return n * this.calculateFactorial(n - 1)
  }
}

