    Column() {
      if (this.selectedMovie == null) {
        Text('Movie Catalog')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .padding(16);

        Grid() {
          ForEach(movies, (movie: Movie) => {
            GridItem() {
              Column() {
                Image(movie.poster)
                  .width(100)
                  .height(150)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(8)
                  .padding(10);
                Text(movie.title)
                  .fontSize(18)
                  .fontWeight(FontWeight.Medium)
                  .padding({ bottom: 4 });
                Text(movie.description)
                  .fontSize(14)
                  .maxLines(2)
                  .textOverflow({ overflow: TextOverflow.Ellipsis })
                  .padding({ bottom: 8 });
              }
              .onClick(() => {
                this.selectedMovie = movie;
              });
            }
          });
        }
        .columnsTemplate('1fr 1fr')
        .columnsGap(10)
        .rowsGap(10)
        .padding(16);
      } else {
        Scroll() {
          Column() {
            Image(this.selectedMovie.poster)
              .width('100%')
              .height(300)
              .objectFit(ImageFit.Cover);

            Text(this.selectedMovie.title)
              .fontSize(24)
              .fontWeight(FontWeight.Bold)
              .padding(16);

            Text(`Release Date: ${this.selectedMovie.releaseDate}`)
              .fontSize(18)
              .padding({ left: 16, right: 16, bottom: 8 });

            Text(`Director: ${this.selectedMovie.director}`)
              .fontSize(18)
              .padding({ left: 16, right: 16, bottom: 8 });

            Text('Description:')
              .fontSize(20)
              .fontWeight(FontWeight.Medium)
              .padding({ left: 16, right: 16, top: 16, bottom: 4 });

            Text(this.selectedMovie.description)
              .fontSize(16)
              .padding({ left: 16, right: 16, bottom: 16 });

            Button('Back')
              .onClick(() => {
                this.selectedMovie = null;
              })
              .padding(16);
          }
        }
      }
    }
    .width('100%')
    .height('100%');
  }
}

