@Entry
@Component
struct TaskManagerApp {
  @State tasks: Array<Task> = []
  @State newTask: string = ''
  @State taskIdCounter: number = 0

  build() {
    Column() {
      TextInput({ placeholder: 'Enter a new task' })
        .onChange((value: string) => {
          this.newTask = value
        })
        .margin({ bottom: 20 })

      Button('Add Task')
        .onClick(() => {
          if (this.newTask.trim()) {
            this.tasks.push({
              id: this.taskIdCounter++,
              content: this.newTask,
              completed: false
            })
            this.newTask = ''
          }
        })
        .margin({ bottom: 20 })

      List() {
        ForEach(this.tasks, (task: Task, index: number) => {
          ListItem() {
            Row() {
              Checkbox()
                .select(task.completed)
                .onChange((checked: boolean) => {
                  this.tasks[index].completed = checked
                })
                .margin({ right: 10 })

              Text(task.content)
                .fontSize(18)
                .decoration({
                  type: task.completed ? TextDecorationType.LineThrough : TextDecorationType.None
                })
                .layoutWeight(1)

              Button() {
                Image($r('app.media.app_icon'))
                  .width(20)
              }
              .type(ButtonType.Circle)
              .onClick(() => {
                this.tasks.splice(index, 1)
              })
            }
            .justifyContent(FlexAlign.SpaceBetween)
            .width('100%')
          }
        })
      }
      .layoutWeight(1)
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

interface Task {
  id: number
  content: string
  completed: boolean
}

