@Entry
@Component
struct ConditionalRenderingApp {
  @State isLoggedIn: boolean = false;
  @State userName: string = "Guest";
  @State toggle: boolean = true;
  @State count: number = 0;
  @State items: Array<Item> = [
    { id: 1, name: 'Item 1', isActive: true },
    { id: 2, name: 'Item 2', isActive: false },
    { id: 3, name: 'Item 3', isActive: true }
  ];

  build() {
    Column() {
      // Conditional greeting based on login status
      if (this.isLoggedIn) {
        Text(`Welcome back, ${this.userName}!`)
          .fontSize(20)
          .fontColor(Color.Blue)
          .margin(10);
      } else {
        Text('Please log in to continue.')
          .fontSize(20)
          .fontColor(Color.Red)
          .margin(10);
      }

      Button(this.isLoggedIn ? 'Log Out' : 'Log In')
        .onClick(() => {
          this.isLoggedIn = !this.isLoggedIn;
          this.userName = this.isLoggedIn ? "JohnDoe" : "Guest";
        })
        .margin(10);

      // Toggle visibility example
      if (this.toggle) {
        Text('Toggle is ON')
          .fontSize(20)
          .fontColor(Color.Green)
          .margin(10);
      } else {
        Text('Toggle is OFF')
          .fontSize(20)
          .fontColor(Color.Red)
          .margin(10);
      }

      Button(`Toggle State: ${this.toggle ? 'ON' : 'OFF'}`)
        .onClick(() => {
          this.toggle = !this.toggle;
        })
        .margin(10);

      // Count-based conditional rendering
      Text(`count=${this.count}`)
        .fontSize(20)
        .margin(10);

      if (this.count > 0) {
        Text('count is positive')
          .fontColor(Color.Green)
          .margin(10);
      }

      Row() {
        Button('increase count')
          .onClick(() => { this.count++; })
          .margin(5);

        Button('decrease count')
          .onClick(() => { this.count--; })
          .margin(5);
      }

      // List with conditional item rendering
      ForEach(this.items, (item: Item) => {
        if (item.isActive) {
          Text(`${item.name} is active`)
            .fontColor(Color.Green)
            .fontSize(20)
            .margin(10);
        } else {
          Text(`${item.name} is inactive`)
            .fontColor(Color.Red)
            .fontSize(20)
            .margin(10);
        }
      })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }
}

interface Item {
  id: number;
  name: string;
  isActive: boolean;
}

