@Entry
@Component
struct ChatApp {
  private messageItem: MessageItem = { text: '', isSender: false };

  @State messages: MessageItem[] = [];
  @State newMessage: string = '';

  build() {
    Column() {
      List() {
        ForEach(this.messages, (message: MessageItem) => {
          ListItem() {
            Column() {
              Text(message.text)
                .fontSize(16)
                .padding(10)
                .backgroundColor(message.isSender ? '#DCF8C6' : '#ECECEC')
                .borderRadius(8)
                .align(message.isSender ? Alignment.End : Alignment.Start);
            }
            .width('100%')
            .margin({ top: 5, bottom: 5 });
          };
        });
      }
      .layoutWeight(1)
      .width('100%')
      .padding(10);

      Row() {
        TextInput({ placeholder: 'Type a message...', text: this.newMessage })
          .width('80%')
          .height(40)
          .backgroundColor('#F5F5F5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.newMessage = value;
          });

        Button('Send')
          .width('20%')
          .height(40)
          .fontSize(16)
          .backgroundColor('#007AFF')
          .onClick(() => {
            if (this.newMessage.trim()) {
              this.messages = [...this.messages, { text: this.newMessage, isSender: true }];
              this.newMessage = '';
            }
          });
      }
      .width('100%')
      .padding(10);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

interface MessageItem {
  text: string;
  isSender: boolean;
}

