@Entry
@Component
struct GracefulImageLoader {
  @State imageUrl: string = 'app.media.app_icon'
  @State isLoading: boolean = true
  @State hasError: boolean = false
  @State errorMessage: string = ''

  build() {
    Column() {
      if (this.isLoading) {
        Column() {
          LoadingProgress()
            .width(50)
            .height(50)
          Text('Loading image...')
            .margin({ top: 10 })
        }
        .onAppear(() => {
          setTimeout(() => {
            this.isLoading = false
          }, 2000)
        })
      }

      if (!this.isLoading && !this.hasError) {
        Image(this.imageUrl)
          .width(200)
          .height(200)
          .onError(() => {
            this.hasError = true
            this.errorMessage = 'Failed to load image'
          })
      }

      if (this.hasError) {
        Column() {
          Image($r('app.media.app_icon'))
            .width(100)
            .height(100)
          Text(this.errorMessage)
            .fontColor(Color.Red)
            .margin({ top: 10 })
          Button('Retry')
            .onClick(() => {
              this.hasError = false
              this.isLoading = true
              this.imageUrl = 'app.media.app_icon'
            })
            .margin({ top: 20 })
        }
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

