@Entry
@Component
struct UserForm {
  @State username: string = '';
  @State password: string = '';
  @State selectedRole: string = 'user';
  @State showDialog: boolean = false;

  build() {
    Column() {
      // Form Title
      Text('User Registration')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      // Username Input
      Column() {
        Text('Username:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your username' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.username = value;
          });
      }

      // Password Input
      Column() {
        Text('Password:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your password' })
          .type(InputType.Password)
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.password = value;
          });
      }

      // Role Selection
      Column() {
        Text('Role:')
          .fontSize(16)
          .margin({ bottom: 8 });

        Row() {
          Radio({ value: 'user', group: 'roleGroup' })
            .checked(this.selectedRole === 'user')
            .onChange((isChecked: boolean) => {
              if (isChecked) {
                this.selectedRole = 'user';
              }
            });
          Text('User')
            .margin({ left: 8 });

          Radio({ value: 'admin', group: 'roleGroup' })
            .checked(this.selectedRole === 'admin')
            .margin({ left: 20 })
            .onChange((isChecked: boolean) => {
              if (isChecked) {
                this.selectedRole = 'admin';
              }
            });
          Text('Admin')
            .margin({ left: 8 });
        }
        .margin({ bottom: 30 });
      }

      // Submit Button
      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.username && this.password) {
            this.showDialog = true;
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields'
            });
          }
        });

      // Dialog
      if (this.showDialog) {
        Column() {
          Text('Submitted Information')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Username: ${this.username}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Password: ${this.password}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Role: ${this.selectedRole}`)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.showDialog = false;
              // Clear form fields after submission
              this.username = '';
              this.password = '';
              this.selectedRole = 'user';
            });
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

