import promptAction from '@ohos.promptAction';

interface Message {
  text: string;
  sender: string;
  timestamp: string;
  isSender: boolean;
}

@Entry
@Component
struct ChatApp {
  @State messages: Array<Message> = [];
  @State newMessage: string = '';

  build() {
    Column() {
      // Chat Messages List
      List({ space: 10 }) {
        ForEach(this.messages, (message: Message) => {
          ListItem() {
            Column() {
              Text(message.text)
                .fontSize(16)
                .padding(10)
                .backgroundColor(message.isSender ? '#DCF8C6' : '#ECECEC')
                .borderRadius(10)
              Text(`${message.sender} - ${message.timestamp}`)
                .fontSize(12)
                .fontColor('#666666')
                .margin({ top: 5 })
            }
            .alignItems(message.isSender ? HorizontalAlign.End : HorizontalAlign.Start)
          }
        })
      }
      .layoutWeight(1)
      .width('100%')
      .padding(10)

      // Message Input and Send Button
      Row() {
        TextInput({ placeholder: 'Type a message...' })
          .width('80%')
          .height(40)
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.newMessage = value;
          })

        Button('Send')
          .width('20%')
          .height(40)
          .fontSize(16)
          .backgroundColor('#007AFF')
          .onClick(() => {
            if (this.newMessage.trim()) {
              const timestamp = new Date().toLocaleTimeString();
              this.messages.push({
                text: this.newMessage,
                sender: 'User',
                timestamp: timestamp,
                isSender: true
              });
              this.newMessage = '';
            } else {
              promptAction.showToast({
                message: 'Message cannot be empty'
              });
            }
          })
      }
      .width('100%')
      .padding(10)
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

@Entry
@Component
struct SearchableListView {
  @State items: string[] = [
    'Apple',
    'Banana',
    'Orange',
    'Grapes',
    'Mango',
    'Pineapple',
    'Strawberry',
    'Watermelon',
    'Cherry',
    'Blueberry',
    'Lemon',
    'Peach'
  ];

  @State searchText: string = '';

  filteredItems(): string[] {
    if (this.searchText.trim() === '') {
      return this.items;
    } else {
      return this.items.filter(item =>
        item.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  build() {
    Column() {
      // Search Bar
      TextInput({
        placeholder: 'Search items...',
        text: this.searchText
      })
        .width('100%')
        .onChange((value: string) => {
          this.searchText = value;
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      // List of Items
      if (this.filteredItems().length > 0) {
        List() {
          ForEach(this.filteredItems(), (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(18)
                .padding(12);
            }
          }, (item: string) => item);
        }
      } else {
        // Display a message when no items match the search
        Text('No items found')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

@Entry
@Component
struct TaskManager {
  @State tasks: Array<Task> = []
  @State newTask: string = ''
  @State editIndex: number = -1
  @State editTask: string = ''

  build() {
    Column() {
      // Input for new task
      TextInput({ placeholder: 'Enter a new task' })
        .onChange((value: string) => {
          this.newTask = value
        })
        .margin({ bottom: 20 })

      // Button to add task
      Button('Add Task')
        .onClick(() => {
          if (this.newTask.trim()) {
            this.tasks.push({
              id: Date.now(),
              content: this.newTask,
              completed: false
            })
            this.newTask = ''
          }
        })
        .margin({ bottom: 20 })

      // List of tasks
      ForEach(this.tasks, (task: Task, index: number) => {
        Row() {
          if (this.editIndex === index) {
            TextInput({ text: this.editTask })
              .onChange((value: string) => {
                this.editTask = value
              })
              .width('60%')
              .margin({ right: 10 })

            Button('Save')
              .onClick(() => {
                if (this.editTask.trim()) {
                  this.tasks[index].content = this.editTask
                  this.editIndex = -1
                  this.editTask = ''
                }
              })
              .margin({ right: 10 })
          } else {
            // Checkbox for completion status
            Checkbox()
              .select(task.completed)
              .onChange((value: boolean) => {
                this.tasks[index].completed = value
              })
              .margin({ right: 10 })

            // Task text with strike-through if completed
            Text(task.content)
              .fontSize(18)
              .decoration({
                type: task.completed ? TextDecorationType.LineThrough : TextDecorationType.None
              })
              .layoutWeight(1)

            // Edit button
            Button('Edit')
              .onClick(() => {
                this.editIndex = index
                this.editTask = task.content
              })
              .margin({ right: 10 })
          }

          // Delete button
          Button('Delete')
            .onClick(() => {
              this.tasks.splice(index, 1)
            })
            .margin({ left: 10 })
        }
        .margin({ top: 10 })
        .width('100%')
        .justifyContent(FlexAlign.SpaceBetween)
      })
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

interface Task {
  id: number
  content: string
  completed: boolean
}

