      Text(`Cart Items: ${this.cartItems}`)
        .fontSize(20)
        .margin(10);

      Text(this.notificationMessage)
        .fontSize(16)
        .margin(10)
        .fontColor(Color.Red);

      Button('Add Item')
        .onClick(() => {
          this.cartItems += 1;
          this.showNotification('Item added to cart');
        })
        .margin(10);

      Button('Remove Item')
        .onClick(() => {
          if (this.cartItems > 0) {
            this.cartItems -= 1;
            this.showNotification('Item removed from cart');
          }
        })
        .margin(10);
