import promptAction from '@ohos.promptAction';

interface Position {
  x: number;
  y: number;
}

@Entry
@Component
struct CustomTextSelectionMenu {
  @State text: string = 'Select some text to see the custom copy menu options.'
  @State selectedText: string = ''
  @State start: number = 0
  @State end: number = 0
  @State showCustomMenu: boolean = false
  @State menuPosition: Position = { x: 0, y: 0 }

  // Custom copy handlers
  handleCopyWithPrefix() {
    this.selectedText = 'PREFIX: ' + this.selectedText
    promptAction.showToast({ message: `Copied with prefix: ${this.selectedText}` })
    this.showCustomMenu = false
  }

  handleCopyUppercase() {
    this.selectedText = this.selectedText.toUpperCase()
    promptAction.showToast({ message: `Copied uppercase: ${this.selectedText}` })
    this.showCustomMenu = false
  }

  handleCopyFormatted() {
    this.selectedText = `**${this.selectedText}**`
    promptAction.showToast({ message: `Copied formatted: ${this.selectedText}` })
    this.showCustomMenu = false
  }

  build() {
    Column() {
      Text(this.text)
        .fontSize(18)
        .margin(20)
        .padding(10)
        .border({ width: 1, color: Color.Gray })
        .selection(this.start, this.end)
        .onTextSelectionChange((start: number, end: number) => {
          this.start = start
          this.end = end
          this.selectedText = this.text.substring(start, end)
          this.showCustomMenu = (start !== end)
        })
        .onTouch((event: TouchEvent) => {
          if (event.type === TouchType.Down) {
            this.menuPosition = { x: event.touches[0].x, y: event.touches[0].y }
          }
        })

      if (this.showCustomMenu) {
        Column() {
          Text('Custom Copy Options')
            .fontSize(16)
            .fontWeight(FontWeight.Bold)
            .padding(10)
            .backgroundColor(Color.White)

          Divider().color(Color.Gray)

          Text('Copy with Prefix')
            .fontSize(14)
            .padding(10)
            .backgroundColor(Color.White)
            .onClick(() => {
              this.handleCopyWithPrefix()
            })

          Text('Copy Uppercase')
            .fontSize(14)
            .padding(10)
            .backgroundColor(Color.White)
            .onClick(() => {
              this.handleCopyUppercase()
            })

          Text('Copy with Formatting')
            .fontSize(14)
            .padding(10)
            .backgroundColor(Color.White)
            .onClick(() => {
              this.handleCopyFormatted()
            })
        }
        .position({ x: this.menuPosition.x, y: this.menuPosition.y })
        .border({ width: 1, color: Color.Gray })
        .borderRadius(5)
        .shadow({ radius: 5, color: Color.Gray })
      }

      Text('Selected Text: ' + this.selectedText)
        .fontSize(14)
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .onClick(() => {
      this.showCustomMenu = false
    })
  }
}

