          text: 'Red Action',
          color: '#FF0000'
        },
        {
          text: 'Green Action',
          color: '#00FF00'
        },
        {
          text: 'Blue Action',
          color: '#0000FF'
        },
        {
          text: 'Cancel',
          color: '#888888'
        }
      ]
    }).then((value: promptAction.ActionMenuSuccessResponse) => {
      switch(value.index) {
        case 0:
          this.handleAction('Red Action');
          break;
        case 1:
          this.handleAction('Green Action');
          break;
        case 2:
          this.handleAction('Blue Action');
          break;
        case 3:
          this.handleAction('Cancel');
          break;
      }
    }).catch((error: Error) => {
      console.error(`showActionMenu error: ${error}`);
