@Entry
@Component
struct AccessibilityStylingApp {
  @State fontSize: number = 16;
  @State isHighContrast: boolean = false;
  @State isScreenReaderEnabled: boolean = false;

  build() {
    Column({ space: 20 }) {
      Text("Accessibility Styling Demo")
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .accessibilityLevel('1')
        .accessibilityTextHint('Application title')
        .accessibilityGroup(true)
        .margin({ top: 20 });

      Text('High Contrast Example')
        .fontSize(18)
        .fontColor(this.isHighContrast ? Color.White : Color.Black)
        .backgroundColor(this.isHighContrast ? Color.Black : Color.White)
        .padding(10)
        .accessibilityTextHint('Example of high contrast text')
        .margin({ top: 20 });

      Text('Adjustable Font Size Example')
        .fontSize(this.fontSize)
        .fontColor(Color.Black)
        .accessibilityTextHint('Text with adjustable font size')
        .margin({ top: 20 });

      Slider({
        value: this.fontSize,
        min: 12,
        max: 24,
        step: 1,
        style: SliderStyle.OutSet
      })
        .onChange((value: number) => {
          this.fontSize = value;
        })
        .width('80%')
        .accessibilityTextHint('Slider to adjust font size')
        .margin({ top: 10 });

      Row({ space: 20 }) {
        Toggle({ type: ToggleType.Switch, isOn: this.isHighContrast })
          .onChange((value: boolean) => {
            this.isHighContrast = value;
          })
          .accessibilityTextHint('Toggle high contrast mode');

        Text("High Contrast")
          .fontSize(16)
          .accessibilityTextHint('High contrast mode status');
      }
      .margin({ top: 20 });

      Row({ space: 20 }) {
        Toggle({ type: ToggleType.Switch, isOn: this.isScreenReaderEnabled })
          .onChange((value: boolean) => {
            this.isScreenReaderEnabled = value;
          })
          .accessibilityTextHint('Toggle screen reader');

        Text("Screen Reader")
          .fontSize(16)
          .accessibilityTextHint('Screen reader status');
      }
      .margin({ top: 20 });

      Button("More Options")
        .onClick(() => {
          console.info('More options clicked');
        })
        .width('80%')
        .accessibilityTextHint('Button for more accessibility options')
        .margin({ top: 30 });

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .accessibilityTextHint('Application icon')
        .margin({ top: 30 });
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor(this.isHighContrast ? Color.Black : Color.White)
    .accessibilityLevel('1')
    .accessibilityTextHint('Main application container');
  }
}

