@Entry
@Component
struct UnifiedImageDragDrop {
  @State leftImages: Resource[] = [$r('app.media.app_icon'), $r('app.media.app_icon')];
  @State rightImages: Resource[] = [$r('app.media.app_icon'), $r('app.media.app_icon')];
  @State draggingIndex: number = -1;
  @State draggingSource: string = '';
  @State dragOffsetX: number = 0;
  @State dragOffsetY: number = 0;
  @State initialX: number = 0;
  @State initialY: number = 0;

  build() {
    Column() {
      Text('Unified Image Drag & Drop')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row() {
        // Left Container
        Column() {
          Text('Left Container')
            .fontSize(18)
            .margin({ bottom: 10 });

          Stack() {
            ForEach(this.leftImages, (image: Resource, index: number) => {
              Image(image)
                .width(100)
                .height(100)
                .position({
                  x: this.draggingIndex === index && this.draggingSource === 'left' ?
                     this.dragOffsetX : 0,
                  y: this.draggingIndex === index && this.draggingSource === 'left' ?
                     this.dragOffsetY : 0
                })
                .opacity(this.draggingIndex === index && this.draggingSource === 'left' ? 0.7 : 1)
                .onTouch((event: TouchEvent) => {
                  this.handleImageTouch(event, index, 'left');
                });
            });
          }
          .width(150)
          .height(300)
          .border({ width: 1, color: Color.Gray })
          .padding(10);
        }
        .margin({ right: 20 });

        // Right Container
        Column() {
          Text('Right Container')
            .fontSize(18)
            .margin({ bottom: 10 });

          Stack() {
            ForEach(this.rightImages, (image: Resource, index: number) => {
              Image(image)
                .width(100)
                .height(100)
                .position({
                  x: this.draggingIndex === index && this.draggingSource === 'right' ?
                     this.dragOffsetX : 0,
                  y: this.draggingIndex === index && this.draggingSource === 'right' ?
                     this.dragOffsetY : 0
                })
                .opacity(this.draggingIndex === index && this.draggingSource === 'right' ? 0.7 : 1)
                .onTouch((event: TouchEvent) => {
                  this.handleImageTouch(event, index, 'right');
                });
            });
          }
          .width(150)
          .height(300)
          .border({ width: 1, color: Color.Gray })
          .padding(10);
        }
      }
      .justifyContent(FlexAlign.Center)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }

  handleImageTouch(event: TouchEvent, index: number, source: string) {
    const touch = event.touches[0];
    if (!touch) return;

    switch (event.type) {
      case TouchType.Down:
        this.draggingIndex = index;
        this.draggingSource = source;
        this.initialX = touch.x;
        this.initialY = touch.y;
        break;

      case TouchType.Move:
        if (this.draggingIndex !== -1) {
          this.dragOffsetX = touch.x - this.initialX;
          this.dragOffsetY = touch.y - this.initialY;
        }
        break;

      case TouchType.Up:
        if (this.draggingIndex !== -1) {
          // Check if dropped
          this.draggingIndex = -1;
          this.draggingSource = '';
        }
        break;
    }
  }
}

