@Entry
@Component
struct ComplexAsyncDataHandling {
  @State dataItems: ComplexDataModel[] = [];
  @State isLoading: boolean = true;
  @State errorMessage: string = '';
  @State isRefreshing: boolean = false;

  // Load initial data
  async loadData(): Promise<void> {
    try {
      this.isLoading = true;
      this.dataItems = await DataService.fetchData();
      this.errorMessage = '';
    } catch (error) {
      this.errorMessage = 'Failed to load data';
    } finally {
      this.isLoading = false;
      this.isRefreshing = false;
    }
  }

  // Handle refresh
  async handleRefresh(): Promise<void> {
    this.isRefreshing = true;
    await this.loadData();
  }

  // Update single item
  async updateItem(item: ComplexDataModel): Promise<void> {
    const updatedItem = await DataService.updateItem(item);
    this.dataItems = this.dataItems.map(i => i.id === updatedItem.id ? updatedItem : i);
  }

  aboutToAppear(): void {
    this.loadData();
  }

  build() {
    Column() {
      // Header section
      Row() {
        Text('Complex Async Data Handling')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)

        Image($r('app.media.app_icon'))
          .width(40)
          .height(40)
          .margin({ left: 10 })
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .padding(10)

      // Status indicators
      if (this.isLoading && !this.isRefreshing) {
        Column() {
          Progress({ value: 0 })
            .width(50)
            .height(50)
          Text('Loading data...')
            .margin({ top: 10 })
        }
        .width('100%')
        .height(200)
        .justifyContent(FlexAlign.Center)
      }

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(18)
          .fontColor(Color.Red)
          .margin(10)
      }

      // Data list
      List({ space: 10 }) {
        ForEach(this.dataItems, (item: ComplexDataModel) => {
          ListItem() {
            Column() {
              Row() {
                Text(item.name)
                  .fontSize(20)
                  .fontWeight(FontWeight.Bold)
                  .layoutWeight(1)

                Text(`Value: ${item.value}`)
                  .fontSize(16)
              }

              Row() {
                Text(`Last updated: ${item.lastUpdated}`)
                  .fontSize(14)
                  .fontColor(Color.Gray)
                  .layoutWeight(1)

                Button('Update')
                  .type(ButtonType.Normal)
                  .size({ width: 100, height: 30 })
                  .onClick(() => {
                    this.updateItem(item);
                  })
              }
              .margin({ top: 5 })
            }
            .width('100%')
            .padding(10)
            .backgroundColor(Color.White)
            .borderRadius(8)
          }
        }, (item: ComplexDataModel) => item.id.toString())
      }
      .width('100%')
      .layoutWeight(1)
      .margin(10)

      // Refresh control
      Refresh({ refreshing: $$this.isRefreshing }) {
        Column() {
          if (this.isRefreshing) {
            Progress({ value: 0 })
              .width(30)
              .height(30)
          }
        }
      }
    }
  }
}

interface ComplexDataModel {
  id: string;
  name: string;
  value: number;
  lastUpdated: string;
}

class DataService {
  static async fetchData(): Promise<ComplexDataModel[]> {
    // Implementation for fetching data
    return [];
  }

  static async updateItem(item: ComplexDataModel): Promise<ComplexDataModel> {
    // Implementation for updating item
    return item;
  }
}

