@Component
struct FrameNodeEffectsExample {
  @State private frameNodeCount: number = 1;
  @State private layoutTime: number = 0;
  @State private renderTime: number = 0;
  @State private showEffects: boolean = false;
  @State private effectIntensity: number = 0.5;

  build() {
    Column() {
      Text('FrameNode Effects in Layout')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row() {
        Button('Add FrameNode')
          .onClick(() => {
            this.frameNodeCount = Math.min(10, this.frameNodeCount + 1);
          })
          .margin({ right: 10 });

        Button('Remove FrameNode')
          .onClick(() => {
            this.frameNodeCount = Math.max(1, this.frameNodeCount - 1);
          });
      }
      .margin({ bottom: 20 });

      Slider({
        value: this.effectIntensity,
        min: 0,
        max: 1,
        step: 0.1
      })
      .onChange((value: number) => {
        this.effectIntensity = value;
      })
      .margin({ bottom: 20 });

      Button(this.showEffects ? 'Hide Effects' : 'Show Effects')
        .onClick(() => {
          this.showEffects = !this.showEffects;
        })
        .margin({ bottom: 20 });

      if (this.showEffects) {
        Column() {
          Text(`Layout Calculation Time: ${this.layoutTime}ms`)
            .fontSize(16)
            .margin({ bottom: 10 });
          Text(`Rendering Time: ${this.renderTime}ms`)
            .fontSize(16);
          Text(`Effect Intensity: ${this.effectIntensity.toFixed(1)}`)
            .fontSize(16);
        }
        .margin({ bottom: 20 });
      }

      Stack() {
        ForEach(Array(this.frameNodeCount).fill(0), (item: number, index: number) => {
          this.createFrameNode(index);
        })
      }
      .width('100%')
      .height(300)
      .border({ width: 1, color: Color.Gray })
      .onAreaChange((oldValue: Area, newValue: Area) => {
        this.calculatePerformance();
      });
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }

  @Builder
  createFrameNode(index: number) {
    Column() {
      Text(`FrameNode ${index + 1}`)
        .fontSize(14)
        .margin({ bottom: 5 });
      Image($r('app.media.app_icon'))
        .width(50)
        .height(50);
    }
    .width(100)
    .height(100)
    .backgroundColor(index % 2 === 0 ? '#FFD306' : '#D2B48C')
    .opacity(this.effectIntensity)
    .margin(5)
    .border({ width: 1, color: Color.Black })
  }

  calculatePerformance() {
    const startTime = Date.now();

    // Simulate layout calculation with effect intensity
    for (let i = 0; i < this.frameNodeCount * 1000 * this.effectIntensity; i++) {
      // Empty loop to simulate calculation
    }
    this.layoutTime = Date.now() - startTime;

    // Simulate rendering time with effect intensity
    const renderStart = Date.now();
    for (let i = 0; i < this.frameNodeCount * 500 * this.effectIntensity; i++) {
      // Empty loop to simulate rendering
    }
    this.renderTime = Date.now() - renderStart;
  }
}

