@Entry
@Component
struct AnimatedCounter {
  @State count: number = 0
  @State scaleValue: number = 1
  @State rotateValue: number = 0
  @State colorValue: Color = Color.Black
  @State opacityValue: number = 1.0

  build() {
    Column() {
      Text(`Count: ${this.count}`)
        .fontSize(36)
        .fontWeight(FontWeight.Bold)
        .fontColor(this.colorValue)
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .rotate({ angle: this.rotateValue })
        .opacity(this.opacityValue)
        .animation({
          duration: 300,
          curve: Curve.EaseInOut
        })
        .margin(20)

      Row() {
        Button('Increment')
          .onClick(() => {
            this.count++
            this.scaleValue = 1.2
            this.rotateValue = 5
            this.colorValue = Color.Green
            this.opacityValue = 0.8
            setTimeout(() => {
              this.scaleValue = 1
              this.rotateValue = 0
              this.colorValue = Color.Black
              this.opacityValue = 1.0
            }, 300)
          })
          .width(120)
          .height(50)
          .margin(10)

        Button('Decrement')
          .onClick(() => {
            if (this.count > 0) {
              this.count--
              this.scaleValue = 1.2
              this.rotateValue = -5
              this.colorValue = Color.Red
              this.opacityValue = 0.8
              setTimeout(() => {
                this.scaleValue = 1
                this.rotateValue = 0
                this.colorValue = Color.Black
                this.opacityValue = 1.0
              }, 300)
            }
          })
          .width(120)
          .height(50)
          .margin(10)
      }
      .justifyContent(FlexAlign.SpaceEvenly)
      .width('100%')

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(20)
        .opacity(this.count % 2 === 0 ? 1 : 0.5)
        .animation({
          duration: 500,
          curve: Curve.EaseInOut
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

@Entry
@Component
struct CustomCircularProgressIndicator {
  @State progress: number = 0;
  @State color: string = '#FF0000';
  private intervalId: number = -1;

  aboutToAppear() {
    this.intervalId = setInterval(() => {
      if (this.progress < 100) {
        this.progress += 1;
        // Change color based on progress
        if (this.progress < 25) {
          this.color = '#FF0000';
        } else if (this.progress < 50) {
          this.color = '#FFA500';
        } else if (this.progress < 75) {
          this.color = '#FFFF00';
        } else {
          this.color = '#4CAF50';
        }
      } else {
        clearInterval(this.intervalId);
      }
    }, 50);
  }

  aboutToDisappear() {
    if (this.intervalId !== -1) {
      clearInterval(this.intervalId);
    }
  }

  build() {
    Column() {
      Stack() {
        // Background circle
        Circle()
          .width(200)
          .height(200)
          .stroke('#E0E0E0')
          .strokeWidth(15)
          .fill('transparent');

        // Progress circle
        Circle()
          .width(200)
          .height(200)
          .stroke(this.color)
          .strokeWidth(15)
          .fill('transparent')
          .strokeDashArray([Math.PI * 200, Math.PI * 200])
          .strokeDashOffset(Math.PI * 200 * (1 - this.progress / 100))
          .rotate({ x: 0, y: 0, z: 1, angle: -90 });

        // Percentage text
        Text(`${Math.round(this.progress)}%`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold);
      }
      .width(200)
      .height(200);

      Button('Reset')
        .onClick(() => {
          this.progress = 0;
          this.color = '#FF0000';
          this.aboutToAppear();
        })
        .margin({ top: 40 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

@Entry
@Component
struct LoginScreen {
  @State email: string = ''
  @State password: string = ''
  @State message: string = ''
  @State isSuccess: boolean = false
  @State showMessage: boolean = false

  build() {
    Column() {
      // App Logo/Header
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ bottom: 30 })

      // Email Input
      Text('Email Address')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })
        .width('80%')
        .textAlign(TextAlign.Start)

      TextInput({ placeholder: 'Enter your email' })
        .width('80%')
        .height(40)
        .margin({ bottom: 20 })
        .borderRadius(5)
        .borderWidth(1)
        .borderColor('#CCCCCC')
        .onChange((value: string) => {
          this.email = value
        })

      // Password Input
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })
        .width('80%')
        .textAlign(TextAlign.Start)

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .width('80%')
        .height(40)
        .margin({ bottom: 30 })
        .borderRadius(5)
        .borderWidth(1)
        .borderColor('#CCCCCC')
        .onChange((value: string) => {
          this.password = value
        })

      // Login Button
      Button('Login', { type: ButtonType.Capsule })
        .width('80%')
        .height(45)
        .backgroundColor('#4CAF50')
        .fontColor(Color.White)
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .onClick(() => {
          if (this.validateCredentials()) {
            this.message = 'Login successful!'
            this.isSuccess = true
          } else {
            this.message = 'Invalid email or password'
            this.isSuccess = false
          }
          this.showMessage = true
        })

      // Status Message
      if (this.showMessage) {
        Text(this.message)
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
          .fontColor(this.isSuccess ? Color.Green : Color.Red)
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#F5F5F5')
  }

  validateCredentials(): boolean {
    const emailValid = this.validateEmail(this.email)
    const passwordValid = this.password.length >= 6
    return emailValid && passwordValid
  }

  validateEmail(email: string): boolean {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return re.test(email)
  }
}

