    Column() {
      // Example 1: Static custom color using hex code
      Text('Custom Color (Hex)')
        .fontSize(20)
        .fontColor('#FF5733')
        .margin(10);

      // Example 2: Predefined color constant
      Text('Predefined Color')
        .fontSize(20)
        .fontColor(Color.Green)
        .margin(10);

      // Example 3: Dynamic color change
      Text(this.message)
        .fontSize(20)
        .fontColor(this.dynamicColor)
        .margin(10);

      Button('Toggle Color')
        .onClick(() => {
          this.dynamicColor = this.dynamicColor === Color.Blue ? Color.Red : Color.Blue;
          this.message = this.dynamicColor === Color.Blue ? 'Blue Text' : 'Red Text';
        })
        .margin(20);

      // Example 4: Background and border styling
      Text('Styled Text with Background')
        .fontSize(20)
        .fontColor(Color.White)
        .backgroundColor('#333333')
        .border({ width: 2, color: Color.Yellow, style: BorderStyle.Solid })
        .padding(10)
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

