@Entry
@Component
struct RichEditorWithImageUpload {
  controller: RichEditorController = new RichEditorController();
  options: RichEditorOptions = { controller: this.controller };
  @State selectedImages: Resource[] = [];
  @State editorContent: string = "Editor Content";

  build() {
    Column({ space: 10 }) {
      // Image upload section
      Row({ space: 10 }) {
        Button("Upload Image")
          .onClick(() => {
            this.uploadImage();
          })
          .width(150)
          .height(40)

        Button("Clear All")
          .onClick(() => {
            this.clearImages();
          })
          .width(150)
          .height(40)
      }

      // Preview selected images
      Scroll() {
        Row({ space: 5 }) {
          ForEach(this.selectedImages, (image: Resource) => {
            Image(image)
              .width(80)
              .height(80)
              .onClick(() => {
                this.insertImageToEditor(image);
              })
          })
        }
        .margin(5)
      }
      .height(100)
      .width("100%")

      // RichEditor section
      RichEditor(this.options)
        .onReady(() => {
          this.controller.addTextSpan("Start editing here...\n", {
            style: {
              fontSize: 16,
              fontColor: Color.Black
            }
          });
        })
        .borderWidth(1)
        .borderColor(Color.Gray)
        .width("100%")
        .height("60%")

      Text(this.editorContent)
        .fontSize(16)
        .margin({ top: 10 })
    }
    .padding(20)
    .width("100%")
    .height("100%")
  }

  private uploadImage() {
    // Simulate image upload
    const newImage = $r("app.media.app_icon");
    this.selectedImages.push(newImage);
  }

  private clearImages() {
    this.selectedImages = [];
  }

  private insertImageToEditor(image: Resource) {
    this.controller.addImageSpan(image, {
      imageStyle: {
        size: ["100px", "100px"],
        layoutStyle: {
          margin: 5,
          borderRadius: 10
        }
      },
      gesture: {
        onClick: () => {
          this.editorContent = "Image clicked in editor";
        }
      }
    });
  }
}

@Entry
@Component
struct WeightConverter {
    @State weightInPounds: string = "";
    @State weightInKilograms: string = "";
    @State errorMessage: string = "";

    build() {
        Column({ space: 20 }) {
            Text("Enter Weight in Pounds:")
                .fontSize(18)
                .fontColor(Color.Black);

            TextInput({ placeholder: "Pounds" })
                .onChange((value: string) => {
                    this.weightInPounds = value;
                    this.errorMessage = "";
                })
                .width('80%')
                .type(InputType.Number)
                .margin({ bottom: 10 });

            Button("Convert to Kilograms")
                .onClick(() => {
                    const pounds = parseFloat(this.weightInPounds);
                    if (isNaN(pounds)) {
                        this.errorMessage = "Please enter a valid number.";
                        return;
                    }
                    if (pounds <= 0) {
                        this.errorMessage = "Weight must be greater than zero.";
                        return;
                    }
                    this.weightInKilograms = (pounds * 0.453592).toFixed(2);
                    this.errorMessage = "";
                })
                .width('80%')
                .margin({ bottom: 10 });

            if (this.errorMessage) {
                Text(this.errorMessage)
                    .fontSize(14)
                    .fontColor(Color.Red)
                    .margin({ bottom: 10 });
            }

            Text(`Weight in Pounds: ${this.weightInPounds}`)
                .fontSize(18)
                .fontColor(Color.Blue)
                .margin({ bottom: 10 });

            Text(`Weight in Kilograms: ${this.weightInKilograms}`)
                .fontSize(18)
                .fontColor(Color.Green)
                .margin({ bottom: 10 });
        }
        .width('100%')
        .height('100%')
        .padding(20)
        .justifyContent(FlexAlign.Center);
    }
}

