import { hilog } from '@kit.PerformanceAnalysisKit';
import { promptAction } from '@kit.ArkUI';

@Entry
@Component
struct PerformanceDebuggingApp {
  @State isNested: boolean = false;
  @State performanceData: string = 'Performance data will appear here';
  @State nestedLevel: number = 1;

  aboutToAppear() {
    hilog.info(0x0000, 'PerformanceDebugging', 'Main component initialized');
  }

  toggleNesting() {
    this.isNested = !this.isNested;
    hilog.info(0x0000, 'PerformanceDebugging', `Nesting ${this.isNested ? 'enabled' : 'disabled'}`);
    this.performanceData = `Nesting level changed to ${this.nestedLevel}`;
  }

  analyzePerformance() {
    hilog.info(0x0000, 'PerformanceDebugging', 'Starting performance analysis...');
    promptAction.showToast({ message: 'Analyzing...' });

    setTimeout(() => {
      this.performanceData = `Analysis completed: ${this.nestedLevel} nested levels detected`;
      hilog.info(0x0000, 'PerformanceDebugging', 'Performance analysis completed');
    }, 1500);
  }

  increaseNesting() {
    this.nestedLevel = Math.min(this.nestedLevel + 1, 5);
    this.performanceData = `Nesting level increased to ${this.nestedLevel}`;
  }

  decreaseNesting() {
    this.nestedLevel = Math.max(this.nestedLevel - 1, 1);
    this.performanceData = `Nesting level decreased to ${this.nestedLevel}`;
  }

  build() {
    Column() {
      Text('Performance Debugger')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row({ space: 10 }) {
        Button('Toggle Nesting')
          .onClick(() => this.toggleNesting())
          .width('40%');

        Button('Analyze')
          .onClick(() => this.analyzePerformance())
          .width('40%');
      }
      .margin({ bottom: 20 });

      Row({ space: 10 }) {
        Button('+ Level')
          .onClick(() => this.increaseNesting())
          .width('30%');

        Button('- Level')
          .onClick(() => this.decreaseNesting())
          .width('30%');
      }
      .margin({ bottom: 20 });

      Text(this.performanceData)
        .fontSize(16)
        .margin({ bottom: 20 });

      if (this.isNested) {
        NestedComponent({ level: this.nestedLevel });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White);
  }
}

