import promptAction from '@ohos.promptAction';

@Entry
@Component
struct TaskManagementApp {
    @State tasks: Array<TaskModel> = [];
    @State newTaskTitle: string = '';
    @State newTaskDescription: string = '';
    @State isEditing: boolean = false;
    @State editIndex: number = -1;

    build() {
        Column({ space: 20 }) {
            TextInput({ placeholder: 'Enter task title' })
                .onChange((value: string) => {
                    this.newTaskTitle = value;
                })
                .margin({ bottom: 10 });

            TextInput({ placeholder: 'Enter task description' })
                .onChange((value: string) => {
                    this.newTaskDescription = value;
                })
                .margin({ bottom: 10 });

            Button(this.isEditing ? 'Update Task' : 'Add Task')
                .onClick(() => {
                    if (this.newTaskTitle && this.newTaskDescription) {
                        if (this.isEditing) {
                            this.tasks[this.editIndex] = new TaskModel(
                                this.tasks[this.editIndex].id,
                                this.newTaskTitle,
                                this.newTaskDescription,
                                this.tasks[this.editIndex].isCompleted
                            );
                            this.isEditing = false;
                            this.editIndex = -1;
                        } else {
                            this.tasks.push(new TaskModel(
                                Date.now(),
                                this.newTaskTitle,
                                this.newTaskDescription,
                                false
                            ));
                        }
                        this.newTaskTitle = '';
                        this.newTaskDescription = '';
                        promptAction.showToast({ message: 'Task saved successfully' });
                    }
                })
                .margin({ bottom: 20 });

            List({ space: 10 }) {
                ForEach(this.tasks, (task: TaskModel, index: number) => {
                    ListItem() {
                        Row({ space: 10 }) {
                            Checkbox()
                                .select(task.isCompleted)
                                .onChange((value: boolean) => {
                                    task.isCompleted = value;
                                });

                            Column({ space: 5 }) {
                                Text(task.title)
                                    .fontSize(18)
                                    .fontWeight(FontWeight.Bold)
                                    .decoration({
                                        type: task.isCompleted ? TextDecorationType.LineThrough : TextDecorationType.None
                                    });

                                Text(task.description)
                                    .fontSize(14)
                                    .fontColor(Color.Gray);
                            }

                            Button('Edit')
                                .onClick(() => {
                                    this.newTaskTitle = task.title;
                                    this.newTaskDescription = task.description;
                                    this.isEditing = true;
                                    this.editIndex = index;
                                });

                            Button('Delete')
                                .onClick(() => {
                                    this.tasks.splice(index, 1);
                                    promptAction.showToast({ message: 'Task deleted' });
                                });
                        }
                        .padding(10)
                        .backgroundColor(Color.White)
                        .borderRadius(10)
                        .shadow({ radius: 2, color: '#1F000000', offsetX: 1, offsetY: 1 });
                    }
                });
            }
            .layoutWeight(1);
        }
        .padding(20)
        .backgroundColor('#F5F5F5');
    }
}

class TaskModel {
    id: number;
    title: string;
    description: string;
    isCompleted: boolean;

    constructor(id: number, title: string, description: string, isCompleted: boolean) {
        this.id = id;
        this.title = title;
        this.description = description;
        this.isCompleted = isCompleted;
    }
}

@Entry
@Component
struct AnimatedApp {
  @State currentScreen: number = 0
  @State buttonScale: number = 1
  @State buttonColor: Color = Color.Blue
  @State rotationAngle: number = 0
  @State scaleValue: number = 1
  @State opacityValue: number = 1

  build() {
    Stack() {
      // Screen 1 with transition animation
      if (this.currentScreen === 0) {
        Column() {
          Text('Welcome Screen')
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 30 })
            .transition({ type: TransitionType.Insert, opacity: 0, translate: { x: 0, y: -100 } })
            .transition({ type: TransitionType.Delete, opacity: 0, translate: { x: 0, y: 100 } })

          Image($r('app.media.app_icon'))
            .width(100)
            .height(100)
            .rotate({ x: 0, y: 0, z: 1, angle: this.rotationAngle })
            .scale({ x: this.scaleValue, y: this.scaleValue })
            .opacity(this.opacityValue)
            .margin({ bottom: 20 })

          Button('Go to Next Screen')
            .width(200)
            .height(50)
            .backgroundColor(this.buttonColor)
            .scale({ x: this.buttonScale, y: this.buttonScale })
            .onClick(() => {
              animateTo({
                duration: 200,
                curve: Curve.EaseInOut
              }, () => {
                this.buttonScale = 0.9
                this.buttonColor = Color.Green
                this.rotationAngle = 45
                this.scaleValue = 0.8
                this.opacityValue = 0.7
              })

              setTimeout(() => {
                animateTo({
                  duration: 300,
                  curve: Curve.EaseInOut
                }, () => {
                  this.buttonScale = 1
                  this.buttonColor = Color.Blue
                  this.currentScreen = 1
                  this.rotationAngle = 0
                  this.scaleValue = 1
                  this.opacityValue = 1
                })
              }, 200)
            })
            .margin({ top: 20 })
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center)
      }

      // Screen 2 with different transition
      if (this.currentScreen === 1) {
        Column() {
          Text('Second Screen')
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 30 })
            .transition({ type: TransitionType.Insert, opacity: 0, translate: { x: 100, y: 0 } })
            .transition({ type: TransitionType.Delete, opacity: 0, translate: { x: -100, y: 0 } })

          Image($r('app.media.app_icon'))
            .width(150)
            .height(150)
            .rotate({ x: 0, y: 0, z: 1, angle: this.rotationAngle })
            .scale({ x: this.scaleValue, y: this.scaleValue })
            .opacity(this.opacityValue)
            .margin({ bottom: 20 })

          Button('Go Back')
            .width(200)
            .height(50)
            .backgroundColor(this.buttonColor)
            .scale({ x: this.buttonScale, y: this.buttonScale })
            .onClick(() => {
              animateTo({
                duration: 200,
                curve: Curve.EaseInOut
              }, () => {
                this.buttonScale = 0.9
                this.buttonColor = Color.Red
                this.rotationAngle = -45
                this.scaleValue = 0.8
                this.opacityValue = 0.7
              })

              setTimeout(() => {
                animateTo({
                  duration: 300,
                  curve: Curve.EaseInOut
                }, () => {
                  this.buttonScale = 1
                  this.buttonColor = Color.Blue
                  this.currentScreen = 0
                  this.rotationAngle = 0
                  this.scaleValue = 1
                  this.opacityValue = 1
                })
              }, 200)
            })
            .margin({ top: 20 })
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center)
      }
    }
  }
}

