@Entry
@Component
struct CustomCalendar {
  @State selectedDate: Date = new Date()
  @State currentMonth: number = new Date().getMonth()
  @State currentYear: number = new Date().getFullYear()
  @State daysInMonth: number = new Date(this.currentYear, this.currentMonth + 1, 0).getDate()
  @State firstDayOfMonth: number = new Date(this.currentYear, this.currentMonth, 1).getDay()

  updateCalendar() {
    this.daysInMonth = new Date(this.currentYear, this.currentMonth + 1, 0).getDate()
    this.firstDayOfMonth = new Date(this.currentYear, this.currentMonth, 1).getDay()
  }

  changeMonth(direction: number) {
    this.currentMonth += direction
    if (this.currentMonth < 0) {
      this.currentMonth = 11
      this.currentYear--
    } else if (this.currentMonth > 11) {
      this.currentMonth = 0
      this.currentYear++
    }
    this.updateCalendar()
  }

  @Builder
  DayCell(day: number) {
    Column() {
      Text(day.toString())
        .fontSize(16)
        .fontColor(this.isSelectedDay(day) ? Color.White : Color.Black)
    }
    .width(40)
    .height(40)
    .borderRadius(20)
    .backgroundColor(this.isSelectedDay(day) ? '#007AFF' : Color.White)
    .onClick(() => {
      this.selectedDate = new Date(this.currentYear, this.currentMonth, day)
    })
  }

  isSelectedDay(day: number): boolean {
    return this.selectedDate.getDate() === day &&
           this.selectedDate.getMonth() === this.currentMonth &&
           this.selectedDate.getFullYear() === this.currentYear
  }

  build() {
    Column() {
      // Month/Year Navigation
      Row() {
        Image($r('app.media.app_icon'))
          .width(24)
          .height(24)
          .onClick(() => this.changeMonth(-1))

        Text(`${new Date(this.currentYear, this.currentMonth).toLocaleString('default', { month: 'long' })} ${this.currentYear}`)
          .fontSize(20)
          .margin({ left: 20, right: 20 })

        Image($r('app.media.app_icon'))
          .width(24)
          .height(24)
          .onClick(() => this.changeMonth(1))
      }
      .justifyContent(FlexAlign.Center)
      .margin({ bottom: 20 })

      // Weekday Headers
      Grid() {
        ForEach(['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], (day: string) => {
          GridItem() {
            Text(day)
              .fontSize(14)
              .fontColor('#666666')
          }
        })
      }
      .columnsTemplate('1fr 1fr 1fr 1fr 1fr 1fr 1fr')
      .margin({ bottom: 10 })

      // Calendar Grid
      Grid() {
        // Empty cells for days before first day of month
        ForEach(Array.from(Array(this.firstDayOfMonth).keys()), (index: number) => {
          GridItem() {
            Column() {
              Text('')
            }
            .width(40)
            .height(40)
          }
        })

        // Days of month
        ForEach(Array.from(Array(this.daysInMonth).keys()), (index: number) => {
          GridItem() {
            this.DayCell(index + 1)
          }
        })
      }
      .columnsTemplate('1fr 1fr 1fr 1fr 1fr 1fr 1fr')
      .rowsGap(10)
      .columnsGap(10)

      // DatePicker for direct date selection
      DatePicker({
        start: new Date('2000-01-01'),
        end: new Date('2030-12-31'),
        selected: this.selectedDate
      })
      .onDateChange((value: Date) => {
        this.selectedDate = value
        this.currentMonth = value.getMonth()
        this.currentYear = value.getFullYear()
        this.updateCalendar()
      })
      .margin({ top: 20 })

      // Selected date display
      Text(`Selected: ${this.selectedDate.toLocaleDateString()}`)
        .fontSize(18)
        .margin({ top: 20 })
    }
    .width('100%')
    .padding(20)
  }
}

