  @State private errorType: string = '';

  // Modular error callback handler
  private handleError(error: Error, context: string = '') {
    this.errorMessage = `${context} Error: ${error.message}`;
    this.errorType = context.toLowerCase();
    this.showError = true;
    console.error(`[${this.errorType.toUpperCase()}_ERROR] ${this.errorMessage}`);

    promptAction.showToast({
      message: this.errorMessage,
      duration: 2000
    });
  }

  // Example operations with modular error handling
  private launchOperation() {
    try {
      if (Math.random() > 0.5) {
        throw new Error('Launch failed: Permission denied');
      }
      this.showError = false;
    } catch (error) {
      this.handleError(error, 'Launch');
    }
  }

  private renderOperation() {
    try {
      if (Math.random() > 0.7) {
        throw new Error('Render failed: Component tree corrupted');
      }
      this.showError = false;
    } catch (error) {
      this.handleError(error, 'Render');
    }
  }

  private clearErrors() {
    this.showError = false;
    this.errorMessage = '';
    this.errorType = '';
  }

  build() {
    Column() {
      // Main content
      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .margin(20);

      Text('Full Screen Launch Component')
        .fontSize(24)
        .fontColor(Color.Black)
        .margin(10);

      // Error display
      if (this.showError) {
        Column() {
          Text(this.errorMessage)
            .fontSize(16)
            .fontColor(Color.Red)
            .margin(10);

          Text(`Error Type: ${this.errorType}`)
            .fontSize(14)
            .fontColor(Color.Gray)
            .margin(5);
        }
      }

      // Action buttons
      Button('Launch Operation')
        .width(200)
        .height(50)
        .margin(10)
        .onClick(() => this.launchOperation());

      Button('Render Operation')
        .width(200)
        .height(50)
        .margin(10)
        .onClick(() => this.renderOperation());

      Button('Clear Errors')
        .width(200)
        .height(50)
        .margin(10)
        .onClick(() => this.clearErrors());
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

