@Entry
@Component
struct OptimizedRealTimeList {
  @State data: RealTimeDataSource = new RealTimeDataSource()
  @State loading: boolean = false
  private timer: number = 0

  aboutToAppear() {
    // Initialize with initial data
    for (let i = 0; i < 50; i++) {
      this.data.pushData(new FeedItem(`Item ${i}`, `Description ${i}`, new Date().toISOString()))
    }

    // Simulate real-time updates
    this.timer = setInterval(() => {
      const newItem = new FeedItem(
        `Item ${this.data.totalCount()}`,
        `New update ${this.data.totalCount()}`,
        new Date().toISOString()
      )
      this.data.addData(0, newItem) // Add to top
    }, 2000)
  }

  aboutToDisappear() {
    clearInterval(this.timer)
  }

  build() {
    Column() {
      if (this.loading) {
        LoadingProgress()
          .width(50)
          .height(50)
          .margin(20)
      }

      List({ space: 5 }) {
        LazyForEach(this.data, (item: FeedItem) => {
          ListItem() {
            FeedItemComponent({ item: item })
          }
          .onAppear(() => {
            console.log(`Item appeared: ${item.title}`)
          })
        }, (item: FeedItem) => item.id)
      }
      .cachedCount(15) // Pre-render 15 items
      .edgeEffect(EdgeEffect.Spring)
      .width('100%')
      .height('100%')
    }
  }
}

