class BasicDataSource implements IDataSource {
  private listeners: DataChangeListener[] = []
  protected dataArray: FeedItem[] = []

  public totalCount(): number {
    return this.dataArray.length
  }

  public getData(index: number): FeedItem {
    return this.dataArray[index]
  }

  registerDataChangeListener(listener: DataChangeListener): void {
    this.listeners.push(listener)
  }

  unregisterDataChangeListener(listener: DataChangeListener): void {
    const index = this.listeners.indexOf(listener)
    if (index >= 0) {
      this.listeners.splice(index, 1)
    }
  }

  notifyDataReload(): void {
    this.listeners.forEach(listener => listener.onDataReloaded())
  }

  notifyDataAdd(index: number): void {
    this.listeners.forEach(listener => listener.onDataAdd(index))
  }
}

class RealTimeDataSource extends BasicDataSource {
  public addData(index: number, data: FeedItem): void {
    this.dataArray.splice(index, 0, data)
    this.notifyDataAdd(index)
  }

  public pushData(data: FeedItem): void {
    this.dataArray.push(data)
    this.notifyDataAdd(this.dataArray.length - 1)
  }
}

@Observed
class FeedItem {
  id: string = Math.random().toString(36).substring(2, 9)
  title: string
  description: string
  timestamp: string

  constructor(title: string, description: string, timestamp: string) {
    this.title = title
    this.description = description
    this.timestamp = timestamp
  }
}

