@Component
struct FormApp {
  @State name: string = ''
  @State email: string = ''
  @State password: string = ''
  @State errorMessage: string = ''

  validateForm(): boolean {
    if (!this.name.trim()) {
      this.errorMessage = 'Name is required'
      return false
    }
    if (!this.email.trim()) {
      this.errorMessage = 'Email is required'
      return false
    }
    if (!this.password.trim()) {
      this.errorMessage = 'Password is required'
      return false
    }
    if (!this.email.includes('@')) {
      this.errorMessage = 'Email must be valid'
      return false
    }
    if (this.password.length < 6) {
      this.errorMessage = 'Password must be at least 6 characters'
      return false
    }
    this.errorMessage = ''
    return true
  }

  build() {
    Column({ space: 20 }) {
      Text('Registration Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)

      TextInput({ placeholder: 'Full Name' })
        .onChange((value: string) => {
          this.name = value
        })

      TextInput({ placeholder: 'Email' })
        .onChange((value: string) => {
          this.email = value
        })

      TextInput({ placeholder: 'Password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })

      Button('Submit')
        .onClick(() => {
          if (this.validateForm()) {
            AlertDialog.show({
              title: 'Submission Successful',
              message: `Name: ${this.name}\nEmail: ${this.email}\nPassword: ${this.password}`,
              confirm: {
                value: 'OK',
                action: () => {
                  this.name = ''
                  this.email = ''
                  this.password = ''
                }
              }
            })
          }
        })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct PropertyCreationExample {
  @State propertyName: string = '';
  @State propertyValue: string = '';
  @State statusMessage: string = 'Enter property details';
  @State propertyExists: boolean = false;

  private checkPropertyExistence() {
    this.propertyExists = AppStorage.has(this.propertyName);
    this.statusMessage = this.propertyExists
      ? `Property "${this.propertyName}" exists`
      : `Property "${this.propertyName}" does not exist`;
  }

  private createOrUpdateProperty() {
    if (this.propertyName.trim() === '' || this.propertyValue.trim() === '') {
      this.statusMessage = 'Both name and value are required';
      return;
    }

    AppStorage.setOrCreate(this.propertyName, this.propertyValue);
    this.propertyExists = true;
    this.statusMessage = `Property "${this.propertyName}" created/updated with value: ${this.propertyValue}`;
  }

  build() {
    Column({ space: 10 }) {
      Text(this.statusMessage)
        .fontSize(20)
        .fontColor(Color.Black)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter property name' })
        .width('80%')
        .height(50)
        .onChange((value: string) => {
          this.propertyName = value;
        })

      TextInput({ placeholder: 'Enter property value' })
        .width('80%')
        .height(50)
        .onChange((value: string) => {
          this.propertyValue = value;
        })

      Button('Check Property')
        .onClick(() => {
          this.checkPropertyExistence();
        })
        .width(200)
        .height(50)
        .backgroundColor(Color.Green)
        .fontColor(Color.White)
        .margin({ top: 10 })

      Button('Create/Update Property')
        .onClick(() => {
          this.createOrUpdateProperty();
        })
        .width(200)
        .height(50)
        .backgroundColor(Color.Blue)
        .fontColor(Color.White)
        .margin({ top: 10 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .padding(20)
  }
}

