import promptAction from '@ohos.promptAction';
import taskpool from '@ohos.taskpool';

@Entry
@Component
struct FullScreenLaunchComponent {
  @State loadingTime: number = 0;
  @State memoryUsage: string = '0 MB';
  @State cpuUsage: string = '0%';
  @State isLoading: boolean = false;
  @State isMonitoring: boolean = false;
  private startTime: number = 0;
  private intervalId: number = -1;

  aboutToAppear() {
    this.startPerformanceMonitoring();
  }

  aboutToDisappear() {
    this.stopPerformanceMonitoring();
  }

  async loadData() {
    this.isLoading = true;
    try {
      const task = new taskpool.Task((): string[] => {
        // Simulate data fetching
        const mockData: string[] = [];
        for (let i = 0; i < 10; i++) {
          mockData.push(`Data Item ${i+1}`);
        }
        return mockData;
      });

      await taskpool.execute(task);
    } catch (error) {
      promptAction.showToast({
        message: 'Data loading failed',
        duration: 2000,
      });
    } finally {
      this.isLoading = false;
    }
  }

  startPerformanceMonitoring() {
    this.isMonitoring = true;
    this.startTime = Date.now();

    this.intervalId = setInterval(() => {
      this.loadingTime = (Date.now() - this.startTime) / 1000;
      this.memoryUsage = `${(Math.random() * 100).toFixed(2)} MB`;
      this.cpuUsage = `${(Math.random() * 100).toFixed(2)}%`;
    }, 1000);
  }

  stopPerformanceMonitoring() {
    this.isMonitoring = false;
    if (this.intervalId !== -1) {
      clearInterval(this.intervalId);
      this.intervalId = -1;
    }
    promptAction.showToast({
      message: 'Performance monitoring stopped',
      duration: 2000
    });
  }

  build() {
    Column({ space: 20 }) {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(20);

      Text('Performance Metrics')
        .fontSize(24)
        .fontColor(Color.Black);

      Column({ space: 10 }) {
        Row() {
          Text('Loading Time:')
            .fontSize(18)
            .fontColor(Color.Gray);
          Text(`${this.loadingTime.toFixed(2)}s`)
            .fontSize(18)
            .fontColor(Color.Blue)
            .margin({ left: 10 });
        }

        Row() {
          Text('Memory Usage:')
            .fontSize(18)
            .fontColor(Color.Gray);
          Text(this.memoryUsage)
            .fontSize(18)
            .fontColor(Color.Blue)
            .margin({ left: 10 });
        }

        Row() {
          Text('CPU Usage:')
            .fontSize(18)
            .fontColor(Color.Gray);
          Text(this.cpuUsage)
            .fontSize(18)
            .fontColor(Color.Blue)
            .margin({ left: 10 });
        }
      }
      .width('80%')
      .padding(20)
      .borderRadius(10)
      .backgroundColor(Color.White)
      .shadow({ radius: 10, color: Color.Gray, offsetX: 2, offsetY: 2 });

      if (!this.isMonitoring) {
        Button('Start Monitoring')
          .width(200)
          .height(50)
          .backgroundColor(Color.Green)
          .fontColor(Color.White)
          .onClick(() => {
            this.startPerformanceMonitoring();
          });
      } else {
        Button('Stop Monitoring')
          .width(200)
          .height(50)
          .backgroundColor(Color.Red)
          .fontColor(Color.White)
          .onClick(() => {
            this.stopPerformanceMonitoring();
          });
      }

      if (this.isLoading) {
        Progress({ value: 50 })
          .width(100)
          .height(4)
          .color(Color.Blue);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#F5F5F5');
  }
}

