@Entry
@Component
struct FullScreenLaunchComponent {
  @State private currentStep: number = 0;
  @State private isServiceRunning: boolean = false;
  @State private serviceData: string[] = ['Initializing', 'Loading Assets', 'Configuring Services', 'Ready'];
  @State private imageSrc: Resource = $r('app.media.app_icon');

  private startService() {
    this.isServiceRunning = true;
    this.currentStep = 0;
    this.runSequence();
  }

  private async runSequence() {
    while (this.currentStep < this.serviceData.length) {
      await new Promise<void>(resolve => setTimeout(resolve, 1000));
      this.currentStep++;
    }
    this.isServiceRunning = false;
  }

  build() {
    Column() {
      Image(this.imageSrc)
        .width(100)
        .height(100)
        .margin(20);

      if (this.isServiceRunning) {
        Column() {
          Text('Service Initialization')
            .fontSize(20)
            .margin({ bottom: 10 });

          ForEach(this.serviceData.slice(0, this.currentStep + 1), (item: string, index: number) => {
            Row() {
              Image($r('app.media.app_icon'))
                .width(20)
                .height(20)
                .margin({ right: 10 });
              Text(item)
                .fontSize(16)
                .opacity(index === this.currentStep ? 1 : 0.7);
            }
            .width('100%')
            .margin({ bottom: 5 });
          });

          Progress({ value: (this.currentStep + 1) * 25 })
            .width('80%')
            .height(10)
            .color(Color.Blue)
            .margin({ top: 20 });
        }
        .width('100%')
        .alignItems(HorizontalAlign.Start)
        .padding(20);
      } else {
        Button('Start Atomic Service')
          .width(200)
          .height(50)
          .onClick(() => this.startService())
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

