@Entry
@Component
struct NavigationDrawerApp {
  @State isDrawerOpen: boolean = false
  @State selectedPageIndex: number = 0

  build() {
    Row() {
      // Main Content Area
      Column() {
        this.PageContent()
        this.DrawerButton()
      }
      .layoutWeight(1)

      // Drawer Panel
      Panel(this.isDrawerOpen) {
        Column() {
          this.NavItem('Home', 0)
          this.NavItem('Profile', 1)
          this.NavItem('Settings', 2)
          this.NavItem('Gallery', 3)
          this.NavItem('About', 4)
        }
        .width('80%')
        .height('100%')
        .backgroundColor(Color.White)
      }
      .mode(PanelMode.Mini)
      .type(PanelType.Temporary)
      .dragBar(false)
    }
    .width('100%')
    .height('100%')
  }

  @Builder DrawerButton() {
    Button('Toggle Drawer')
      .onClick(() => {
        this.isDrawerOpen = !this.isDrawerOpen
      })
  }

  @Builder NavItem(label: string, index: number) {
    Text(label)
      .fontSize(20)
      .margin(10)
      .onClick(() => {
        this.selectedPageIndex = index
        this.isDrawerOpen = false
      })
  }

  @Builder PageContent() {
    if (this.selectedPageIndex === 0) {
      this.HomePage()
    } else if (this.selectedPageIndex === 1) {
      this.ProfilePage()
    } else if (this.selectedPageIndex === 2) {
      this.SettingsPage()
    } else if (this.selectedPageIndex === 3) {
      this.GalleryPage()
    } else {
      this.AboutPage()
    }
  }

  @Builder HomePage() {
    Column() {
      Text('Home Page')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin(16)
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(16)
      Text('Welcome to the Home Page!')
        .fontSize(18)
        .margin(16)
    }
    .width('100%')
    .height('100%')
  }

