@Entry
@Component
struct UserRegistrationForm {
  @State name: string = ''
  @State email: string = ''
  @State password: string = ''
  @State phone: string = ''
  @State address: string = ''
  @State successMessage: string = ''
  @State errorMessage: string = ''

  validateForm(): boolean {
    if (!this.name.trim()) {
      this.errorMessage = 'Name is required'
      return false
    }
    if (!this.email.trim()) {
      this.errorMessage = 'Email is required'
      return false
    }
    if (!this.password.trim()) {
      this.errorMessage = 'Password is required'
      return false
    }
    if (!this.phone.trim()) {
      this.errorMessage = 'Phone is required'
      return false
    }
    if (!this.address.trim()) {
      this.errorMessage = 'Address is required'
      return false
    }
    this.errorMessage = ''
    return true
  }

  handleSubmit() {
    if (this.validateForm()) {
      this.successMessage = `Registration Successful!\n\nName: ${this.name}\nEmail: ${this.email}\nPhone: ${this.phone}\nAddress: ${this.address}`
      // Clear form
      this.name = ''
      this.email = ''
      this.password = ''
      this.phone = ''
      this.address = ''
    }
  }

  build() {
    Column({ space: 10 }) {
      // Form Title
      Text('User Registration')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      // Name Field
      TextInput({ placeholder: 'Full Name' })
        .width('100%')
        .height(40)
        .margin({ bottom: 15 })
        .onChange((value: string) => {
          this.name = value
        })

      // Email Field
      TextInput({ placeholder: 'Email Address' })
        .width('100%')
        .height(40)
        .margin({ bottom: 15 })
        .onChange((value: string) => {
          this.email = value
        })

      // Password Field
      TextInput({ placeholder: 'Password' })
        .width('100%')
        .height(40)
        .type(InputType.Password)
        .margin({ bottom: 15 })
        .onChange((value: string) => {
          this.password = value
        })

      // Phone Field
      TextInput({ placeholder: 'Phone Number' })
        .width('100%')
        .height(40)
        .margin({ bottom: 15 })
        .onChange((value: string) => {
          this.phone = value
        })

      // Address Field
      TextInput({ placeholder: 'Full Address' })
        .width('100%')
        .height(40)
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.address = value
        })

      // Submit Button
      Button('Register', { type: ButtonType.Capsule })
        .width('100%')
        .height(40)
        .backgroundColor('#007AFF')
        .onClick(() => {
          this.handleSubmit()
        })

      // Error Message
      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 10 })
      }

      // Success Message
      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(16)
          .fontColor(Color.Green)
          .margin({ top: 20 })
          .textAlign(TextAlign.Center)
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct LoginScreen {
  @State email: string = ''
  @State password: string = ''
  @State showMessage: boolean = false
  @State message: string = ''
  @State isError: boolean = false

  validateEmail(email: string): boolean {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return re.test(email)
  }

  validateCredentials(): boolean {
    if (this.validateEmail(this.email) && this.password.length >= 6) {
      this.message = 'Login successful!'
      this.isError = false
      return true
    } else {
      this.message = 'Invalid email or password'
      this.isError = true
      return false
    }
  }

  build() {
    Column() {
      Text('Email')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your email' })
        .onChange((value: string) => {
          this.email = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      Button('Login')
        .onClick(() => {
          this.validateCredentials()
          this.showMessage = true
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      if (this.showMessage) {
        Text(this.message)
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
          .fontColor(this.isError ? Color.Red : Color.Green)
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .backgroundColor('#F5F5F5')
  }
}

