@Component
struct ImageGridApp {
  private images: ImageItem[] = [
    { id: 1, title: 'Image 1', url: 'common/images/ic_image1.png' },
    { id: 2, title: 'Image 2', url: 'common/images/ic_image2.png' },
    { id: 3, title: 'Image 3', url: 'common/images/ic_image3.png' },
    { id: 4, title: 'Image 4', url: 'common/images/ic_image4.png' }
  ];

  @State selectedImage: ImageItem | null = null;
  dialogController: CustomDialogController = new CustomDialogController({
    builder: this.DialogBuilder.bind(this),
    customStyle: true,
    alignment: DialogAlignment.Center
  });

  @Builder
  DialogBuilder() {
    Column() {
      Text(this.selectedImage?.title ?? '')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 16, bottom: 8 });

      Button('OK')
        .width('80%')
        .height(40)
        .margin({ top: 24 })
        .onClick(() => {
          this.dialogController.close();
        });
    }
    .width('80%')
    .padding(16)
    .borderRadius(8)
    .backgroundColor(Color.White);
  }

  build() {
    Column() {
      Text('Image Gallery')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Grid() {
        ForEach(this.images, (imageItem: ImageItem) => {
          GridItem() {
            Column() {
              Image(imageItem.url)
                .width(100)
                .height(100)
                .borderRadius(8)
                .objectFit(ImageFit.Cover)
                .onClick(() => {
                  this.selectedImage = imageItem;
                  this.dialogController.open();
                });

              Text(imageItem.title)
                .fontSize(16)
                .margin({ top: 8 });
            }
            .margin(10);
          }
        });
      }
      .columnsTemplate('1fr 1fr 1fr')
      .rowsGap(10)
      .columnsGap(10);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }
}

