@Component
struct ColorDropdownApp {
  @State selectedColor: string = '#FFFFFF'
  @State isDropdownVisible: boolean = false
  private colors: string[] = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FF00FF', '#FFA500']

  build() {
    Column() {
      // Dropdown Button
      Button('Select Color')
        .width(150)
        .height(40)
        .backgroundColor('#DDDDDD')
        .borderRadius(8)
        .onClick(() => {
          this.isDropdownVisible = !this.isDropdownVisible
        })
        .margin({ top: 20, bottom: 20 })

      // Dropdown Menu
      if (this.isDropdownVisible) {
        Column() {
          ForEach(this.colors, (color: string) => {
            Button()
              .width(100)
              .height(40)
              .backgroundColor(color)
              .borderRadius(8)
              .onClick(() => {
                this.selectedColor = color
                this.isDropdownVisible = false
              })
              .margin({ bottom: 10 })
          })
        }
        .padding(10)
        .backgroundColor('#F5F5F5')
        .borderRadius(8)
        .margin({ bottom: 20 })
      }

      // Display Selected Color
      Text('Selected Color:')
        .fontSize(18)
        .margin({ bottom: 10 })

      Row()
        .width(50)
        .height(50)
        .backgroundColor(this.selectedColor)
        .borderRadius(25)
        .margin({ bottom: 20 })
