@Entry
@Component
struct CustomSelectWithBackground {
  @State selectedOption: string = '';
  @State isMenuOpen: boolean = false;
  private options: string[] = ['Option A', 'Option B', 'Option C', 'Option D'];

  toggleMenu() {
    this.isMenuOpen = !this.isMenuOpen;
  }

  selectOption(option: string) {
    this.selectedOption = option;
    this.isMenuOpen = false;
  }

  build() {
    Column() {
      // Dropdown trigger
      Button(this.selectedOption || 'Select an option')
        .onClick(() => this.toggleMenu())
        .width(200)
        .height(40)
        .backgroundColor('#FFFFFF')
        .border({ width: 1, color: '#CCCCCC' })
        .margin({ bottom: 10 });

      // Dropdown menu
      if (this.isMenuOpen) {
        Column() {
          ForEach(this.options, (option: string) => {
            Row() {
              Text(option)
                .fontSize(16)
                .margin({ left: 10 });
            }
            .width(200)
            .height(40)
            .backgroundColor(this.selectedOption === option ? '#39a2db' : '#FFFFFF')
            .borderRadius(5)
            .onClick(() => {
              this.selectOption(option);
            });
          });
        }
        .border({ width: 1, color: '#CCCCCC' })
        .borderRadius(5);
      }

      // Display selected option
      if (this.selectedOption) {
        Text('Selected: ' + this.selectedOption)
          .fontSize(16)
          .margin({ top: 20 });
      }
    }
    .padding(20)
    .width('100%')
    .height('100%');
  }
}

