@Entry
@Component
struct LoadingIndicator {
    @State rotation: number = 0
    private intervalID: number = -1

    aboutToAppear() {
        this.intervalID = setInterval(() => {
            this.rotation = (this.rotation + 10) % 360
        }, 50)
    }

    aboutToDisappear() {
        if (this.intervalID !== -1) {
            clearInterval(this.intervalID)
        }
    }

    build() {
        Column() {
            Stack() {
                Circle()
                    .width(100)
                    .height(100)
                    .stroke($r('sys.color.ohos_id_color_primary'))
                    .strokeWidth(10)
                    .strokeDashArray([10, 20])
                    .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })
            }
            .width(100)
            .height(100)
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .backgroundColor($r('sys.color.ohos_id_color_background'))
    }
}

@Entry
@Component
struct ImageCarousel {
  @State private currentIndex: number = 0;
  private carouselItems: Array<CarouselItem> = [
    { id: 1, image: 'placeholder1.jpg', title: 'Slide 1', description: 'Description for Slide 1' },
    { id: 2, image: 'placeholder2.jpg', title: 'Slide 2', description: 'Description for Slide 2' },
    { id: 3, image: 'placeholder3.jpg', title: 'Slide 3', description: 'Description for Slide 3' },
    { id: 4, image: 'placeholder4.jpg', title: 'Slide 4', description: 'Description for Slide 4' }
  ];

  private swiperController: SwiperController = new SwiperController();

  build() {
    Column() {
      Swiper(this.swiperController) {
        ForEach(this.carouselItems, (item: CarouselItem) => {
          Column() {
            Image(item.image)
              .height(300)
              .objectFit(ImageFit.Cover)
            Text(item.title)
            Text(item.description)
          }
        })
      }
      .indicator(true)
      .autoPlay(true)
      .interval(3000)
      .duration(500)
      .loop(true)
      .onChange((index: number) => {
        this.currentIndex = index;
      })

      Row() {
        Button('Previous')
          .onClick(() => {
            this.currentIndex = (this.currentIndex - 1 + this.carouselItems.length) % this.carouselItems.length;
          })
        Button('Next')
          .onClick(() => {
            this.currentIndex = (this.currentIndex + 1) % this.carouselItems.length;
          })
      }
    }
    .width('100%')
  }
}

interface CarouselItem {
  id: number;
  image: string;
  title: string;
  description: string;
}

