@Entry
@Component
struct FullScreenLaunchComponent {
  @State private isLoading: boolean = true;
  @State private contentReady: boolean = false;
  @State private data: string[] = [];
  @State private imageSrc: Resource = $r('app.media.app_icon');

  // Simulate async data loading
  private loadData() {
    this.isLoading = true;
    setTimeout(() => {
      this.data = ['Item 1', 'Item 2', 'Item 3']; // Mock data
      this.contentReady = true;
      this.isLoading = false;
    }, 1500);
  }

  @Builder
  HeaderSection() {
    Row() {
      Text('App Header')
        .fontSize(24)
        .fontColor(Color.White)
    }
    .width('100%')
    .height(80)
    .backgroundColor(Color.Black)
  }

  @Builder
  MainContent() {
    Column() {
      Image(this.imageSrc)
        .width(200)
        .height(200)
        .margin({ top: 20 })

      List() {
        ForEach(this.data, (item: string) => {
          ListItem() {
            Text(item)
              .fontSize(18)
              .margin(10)
          }
        })
      }
      .width('100%')
      .layoutWeight(1)
    }
    .width('100%')
    .justifyContent(FlexAlign.Center)
  }

  @Builder
  FooterSection() {
    Row() {
      Text('App Footer')
        .fontSize(18)
        .fontColor(Color.White)
    }
    .width('100%')
    .height(60)
    .backgroundColor(Color.Gray)
  }

  @Builder
  LoadingIndicator() {
    Column() {
      Progress({ value: 50 })
        .width(100)
        .height(100)
      Text('Loading...')
        .fontSize(16)
        .margin({ top: 10 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }

  build() {
    Column() {
      this.HeaderSection()

      if (this.isLoading) {
        this.LoadingIndicator()
      } else if (this.contentReady) {
        this.MainContent()
      }

      this.FooterSection()
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
  }

  aboutToAppear() {
    this.loadData();
  }
}

