@Entry
@Component
struct ComplexUIComposer {
  @State private showDetails: boolean = false;
  @State private sliderValue: number = 50;
  @State private themeColor: string = '#4A6CD1';
  @State private activeTab: number = 0;

  // Builder for a themed header section
  @Builder HeaderSection(title: string, subtitle: string) {
    Column() {
      Text(title)
        .fontSize(30)
        .fontWeight(FontWeight.Bold)
        .fontColor(this.themeColor)
        .margin({ bottom: 8 });

      Text(subtitle)
        .fontSize(16)
        .fontColor('#666666')
        .margin({ bottom: 20 });

      Divider()
        .strokeWidth(1)
        .color('#EEEEEE')
    }
    .width('100%')
    .padding(20)
  }

  // Builder for interactive content panel
  @Builder ContentPanelBuilder() {
    Column() {
      if (this.showDetails) {
        Text('Detailed information panel with dynamic content')
          .fontSize(16)
          .margin({ bottom: 15 });

        Slider({
          value: this.sliderValue,
          min: 0,
          max: 100,
          style: SliderStyle.OutSet
        })
        .onChange((value: number) => {
          this.sliderValue = value;
        })
        .width('100%');

        Text(`Current value: ${this.sliderValue}`)
          .fontSize(14)
          .margin({ top: 10 });
      }

      Image($r('app.media.app_icon'))
        .width(80)
        .height(80)
        .margin({ top: 20, bottom: 20 });
    }
    .width('100%')
    .padding(15)
    .backgroundColor('#F8F8F8')
    .borderRadius(10)
  }

  // Builder for tab navigation
  @Builder TabNavigationBuilder() {
    Row() {
      ForEach([0, 1, 2], (index: number) => {
        Button(`Tab ${index + 1}`)
          .backgroundColor(this.activeTab === index ? this.themeColor : '#DDDDDD')
          .fontColor(this.activeTab === index ? Color.White : Color.Black)
          .onClick(() => {
            this.activeTab = index;
          })
          .margin({ right: 5 })
          .borderRadius(5);
      })
    }
    .margin({ top: 15, bottom: 20 })
  }

  // Builder for main control buttons
  @Builder ControlButtonsBuilder() {
    Row() {
      Button(this.showDetails ? 'Hide Details' : 'Show Details')
        .onClick(() => {
          this.showDetails = !this.showDetails;
        })
        .width(150)
        .margin({ right: 10 });

      Button('Change Theme')
        .onClick(() => {
          this.themeColor = this.themeColor === '#4A6CD1' ? '#D14A6C' : '#4A6CD1';
        })
        .width(150);
    }
    .margin({ top: 10 })
  }

  build() {
    Column() {
      this.HeaderSection('Complex UI Builder', 'Custom Build');
      this.ContentPanelBuilder();

      this.TabNavigationBuilder();

      this.ControlButtonsBuilder();

      Text(`Active Tab: ${this.activeTab + 1} | Theme: ${this.themeColor}`)
        .fontSize(16)
        .fontWeight(FontWeight.Medium)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White)
  }
}

@Entry
@Component
struct FullScreenLaunchComponent {
  @State private isProcessing: boolean = false;
  @State private clickCount: number = 0;
  @State private lastEventTime: string = '';
  @State private imageClicked: boolean = false;
  @State private inputText: string = '';
  @State private accessibilityEnabled: boolean = true;

  private handleClick(): void {
    if (this.isProcessing) return;

    this.isProcessing = true;
    this.clickCount += 1;
    this.lastEventTime = new Date().toLocaleTimeString();

    // Simulate async operation
    setTimeout(() => {
      this.isProcessing = false;
    }, 500);
  }

  private handleLongPress(): void {
    this.clickCount = 0;
    this.lastEventTime = 'Reset at ' + new Date().toLocaleTimeString();
  }

  private handleImageClick(): void {
    this.imageClicked = !this.imageClicked;
  }

  private handleTextInputChange(value: string): void {
    this.inputText = value;
  }

  private toggleAccessibility(isOn: boolean): void {
    this.accessibilityEnabled = isOn;
  }

  build() {
    Column({ space: 20 }) {
      // Accessibility toggle
      Toggle({ type: ToggleType.Switch, isOn: this.accessibilityEnabled })
        .onChange((isOn: boolean) => {
          this.toggleAccessibility(isOn);
        });

      // Image with click and long press events
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .onClick(() => {
          this.handleImageClick();
        })
        .gesture(
          LongPressGesture({ repeat: false })
            .onAction(() => {
              this.handleLongPress();
            })
        )
        .accessibilityText(this.accessibilityEnabled ? 'Application Icon' : '')
        .accessibilityDescription('Company logo image');

      // Text input with change event
      TextInput({ placeholder: 'Enter text', text: this.inputText })
        .onChange((value: string) => {
          this.handleTextInputChange(value);
        })
        .accessibilityText(this.accessibilityEnabled ? 'Text Input Field' : '')
        .accessibilityDescription('Enter your text here');

      // Button with click event
      Button('Click Me')
        .onClick(() => {
          this.handleClick();
        })
        .accessibilityText(this.accessibilityEnabled ? 'Primary Button' : '')
        .accessibilityDescription('Tap to perform action');

      // Display status
      Text(`Clicks: ${this.clickCount}`)
        .fontSize(20);
      Text(`Last event: ${this.lastEventTime}`)
        .fontSize(16);
      Text(this.imageClicked ? 'Image clicked!' : 'Image not clicked')
        .fontSize(20);
      Text(this.accessibilityEnabled ? 'Accessibility Enabled' : 'Accessibility Disabled')
        .fontColor(this.accessibilityEnabled ? Color.Green : Color.Red);

      if (this.isProcessing) {
        Progress({ value: 50 })
          .width(100)
          .height(4)
          .color(Color.Blue);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20)
    .backgroundColor('#F5F5F5');
  }
}

