@Entry
@Component
struct SearchableList {
  @State items: string[] = [
    'Apple',
    'Banana',
    'Orange',
    'Grapes',
    'Mango',
    'Pineapple',
    'Strawberry',
    'Watermelon',
    'Cherry',
    'Blueberry',
    'Lemon',
    'Peach'
  ];

  @State searchText: string = '';

  filteredItems(): string[] {
    if (this.searchText.trim() === '') {
      return this.items;
    } else {
      return this.items.filter(item =>
        item.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  build() {
    Column() {
      // Search Bar
      TextInput({
        placeholder: 'Search items...',
        text: this.searchText
      })
        .width('100%')
        .onChange((value: string) => {
          this.searchText = value;
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      // List of Filtered Items
      if (this.filteredItems().length > 0) {
        List() {
          ForEach(this.filteredItems(), (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(18)
                .padding(12);
            }
          }, (item: string) => item);
        }
      } else {
        Text('No items found')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

@Entry
@Component
struct ImageGridApp {
  @State selectedImage: Resource = $r('app.media.app_icon')
  @State showFullScreen: boolean = false
  @State showDescription: boolean = false

  private images: Resource[] = [
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon')
  ]

  private descriptions: string[] = [
    'Description for image 1',
    'Description for image 2',
    'Description for image 3',
    'Description for image 4'
  ]

  build() {
    Column() {
      if (this.showFullScreen) {
        Stack() {
          Column() {
            Image(this.selectedImage)
              .objectFit(ImageFit.Contain)
              .width('100%')
              .height('70%')

            if (this.showDescription) {
              Text(this.descriptions[this.images.indexOf(this.selectedImage)])
                .fontSize(16)
                .margin({ top: 20, left: 20, right: 20 })
                .textAlign(TextAlign.Center)
            }
          }

          Column() {
            Button(this.showDescription ? 'Hide Description' : 'Show Description')
              .onClick(() => {
                this.showDescription = !this.showDescription
              })
              .margin({ top: 20 })
              .backgroundColor('#FFFFFF')
              .padding({ left: 10, right: 10, top: 5, bottom: 5 })
              .borderRadius(5)

            Button('Close')
              .onClick(() => {
                this.showFullScreen = false
                this.showDescription = false
              })
              .margin({ top: 10 })
              .backgroundColor('#FFFFFF')
              .padding({ left: 10, right: 10, top: 5, bottom: 5 })
              .borderRadius(5)
          }
          .position({ x: 20, y: 20 })
        }
      } else {
        Grid() {
          ForEach(this.images, (image: Resource, index: number) => {
            GridItem() {
              Column() {
                Image(image)
                  .width('100%')
                  .aspectRatio(1)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(5)
                  .onClick(() => {
                    this.selectedImage = image
                    this.showFullScreen = true
                  })

                Text(this.descriptions[index])
                  .fontSize(14)
                  .margin({ top: 5 })
              }
            }
          })
        }
        .columnsTemplate('1fr 1fr')
        .rowsGap(10)
        .columnsGap(10)
        .padding(10)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

