@Entry
@Component
struct FontColorEditor {
  private controller: RichEditorController = new RichEditorController();
  @State textColor: Color = Color.Black;

  build() {
    Column() {
      RichEditor({ controller: this.controller })
        .onReady(() => {
          this.controller.addTextSpan("Edit this text", {
            style: {
              fontColor: this.textColor,
              fontSize: 24
            }
          });
        })
        .width("90%")
        .height("40%")
        .border({ width: 1, radius: 5 })

      Row({ space: 10 }) {
        Button("Red")
          .width(80)
          .height(40)
          .onClick(() => {
            this.textColor = Color.Red;
            this.updateTextColor();
          })

        Button("Blue")
          .width(80)
          .height(40)
          .onClick(() => {
            this.textColor = Color.Blue;
            this.updateTextColor();
          })

        Button("Green")
          .width(80)
          .height(40)
          .onClick(() => {
            this.textColor = Color.Green;
            this.updateTextColor();
          })
      }
      .margin(10)
    }
    .width("100%")
    .height("100%")
    .padding(20)
  }

  private updateTextColor() {
    this.controller.updateSpanStyle({
      start: -1,
      end: -1,
      textStyle: {
        fontColor: this.textColor
      }
    });
  }
}

