      instructor: 'Dr. Ark'
    },
    {
      title: 'Distributed Systems with ArkTS',
      description: 'Build cross-device applications using ArkTS distributed capabilities.',
      instructor: 'Prof. MultiDevice'
    }
  ];

  @State selectedCourse: Course | null = null;

