    Column() {
      if (this.selectedCourse === null) {
        Text('Educational Courses')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20, bottom: 20 })
          .textAlign(TextAlign.Center);

        List() {
          ForEach(this.courses, (course: Course) => {
            ListItem() {
              Column() {
                Text(course.title)
                  .fontSize(18)
                  .fontWeight(FontWeight.Medium)
                  .margin({ bottom: 4 });

                Text(course.description)
                  .fontSize(14)
                  .fontColor('#666666')
                  .margin({ bottom: 4 });

                Text(`Instructor: ${course.instructor}`)
                  .fontSize(14)
                  .fontColor('#666666');
              }
              .padding(16)
              .backgroundColor(Color.White)
              .borderRadius(12)
              .onClick(() => {
                this.selectedCourse = course;
              });
            }
            .margin({ bottom: 12 });
          });
        }
      } else {
        Column() {
          Button('Back')
            .onClick(() => {
              this.selectedCourse = null;
            })
            .margin({ top: 20, bottom: 20 });

          Column() {
            Text(this.selectedCourse.title)
              .fontSize(20)
              .fontWeight(FontWeight.Bold)
              .margin({ bottom: 10 });

            Text(this.selectedCourse.description)
              .fontSize(16)
              .margin({ bottom: 10 });

            Text(`Instructor: ${this.selectedCourse.instructor}`)
              .fontSize(16);
          }
          .padding(16);
        }
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
    .padding({ left: 16, right: 16 });
  }
}

