@Entry
@Component
struct UserInfoForm {
  @State name: string = ''
  @State email: string = ''
  @State phoneNumber: string = ''
  @State showDialog: boolean = false
  @State emailError: string = ''

  validateEmail(email: string): boolean {
    const emailRegex = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/
    return emailRegex.test(email)
  }

  submitForm() {
    if (!this.name || !this.email || !this.phoneNumber) {
      AlertDialog.show({
        title: 'Error',
        message: 'Please fill in all fields',
        confirm: {
          value: 'OK',
          action: () => {}
        }
      })
      return
    }

    if (!this.validateEmail(this.email)) {
      this.emailError = 'Please enter a valid email'
      return
    }

    this.showDialog = true
  }

  build() {
    Column() {
      Text('User Information Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 30 })

      // Name Field
      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 })
        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value
          })
      }

      // Email Field
      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 })
        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 5 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value
            this.emailError = ''
          })
        if (this.emailError) {
          Text(this.emailError)
            .fontSize(12)
            .fontColor(Color.Red)
            .margin({ bottom: 15 })
        }
      }

      // Phone Field
      Column() {
        Text('Phone Number:')
          .fontSize(16)
          .margin({ bottom: 8 })
        TextInput({ placeholder: 'Enter your phone number' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.phoneNumber = value
          })
      }

      // Submit Button
      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          this.submitForm()
        })

      // Submission Dialog
      if (this.showDialog) {
        Column() {
          Text('Submitted Data')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 })

          Text(`Name: ${this.name}`)
            .fontSize(16)
            .margin({ bottom: 12 })

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 12 })

          Text(`Phone: ${this.phoneNumber}`)
            .fontSize(16)
            .margin({ bottom: 20 })

          Button('Close')
            .onClick(() => {
              this.showDialog = false
              this.name = ''
              this.email = ''
              this.phoneNumber = ''
            })
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '20%' })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
  }
}

