@Entry
@Component
struct LoginApp {
  @State email: string = '';
  @State password: string = '';
  @State isLoggedIn: boolean = false;
  @State welcomeMessage: string = '';

  build() {
    Column() {
      if (!this.isLoggedIn) {
        // Login Form
        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
          .margin({ bottom: 30 });

        // Email Input
        Text('Email')
          .fontSize(18)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .onChange((value: string) => {
            this.email = value;
          });

        // Password Input
        Text('Password')
          .fontSize(18)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Enter your password' })
          .type(InputType.Password)
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .onChange((value: string) => {
            this.password = value;
          });

        // Login Button
        Button('Login')
          .width('100%')
          .height(50)
          .fontSize(18)
          .backgroundColor('#007AFF')
          .onClick(() => {
            if (this.email && this.password) {
              this.isLoggedIn = true;
              this.welcomeMessage = `Welcome, ${this.email}!`;
            } else {
              promptAction.showToast({
                message: 'Please enter both email and password.'
              });
            }
          });
      } else {
        // Welcome Screen
        Text(this.welcomeMessage)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 });

        Button('Logout')
          .width('100%')
          .height(50)
          .fontSize(18)
          .backgroundColor('#FF3B30')
          .onClick(() => {
            this.isLoggedIn = false;
            this.email = '';
            this.password = '';
            this.welcomeMessage = '';
          });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
    .justifyContent(FlexAlign.Center);
  }
}

@Entry
@Component
struct RichEditorSelectionConfig {
  controller: RichEditorController = new RichEditorController();
  options: RichEditorOptions = { controller: this.controller };
  @State selectionRange: string = "[-1, -1]";
  @State selectionContent: string = "";
  @State selectedText: string = "";

  build() {
    Column({ space: 10 }) {
      RichEditor(this.options)
        .onReady(() => {
          this.controller.addTextSpan("Sample text for selection demonstration.", {
            style: {
              fontColor: Color.Black,
              fontSize: 20
            }
          });
          this.controller.addImageSpan($r("app.media.app_icon"), {
            imageStyle: {
              size: ["50px", "50px"]
            }
          });
        })
        .onSelect((value: RichEditorSelection) => {
          this.selectionRange = `[${value.selection[0]}, ${value.selection[1]}]`;
          this.selectionContent = "";
          this.selectedText = "";
          value.spans.forEach(item => {
            if (typeof (item as RichEditorTextSpanResult)['value'] !== 'undefined') {
              this.selectedText += (item as RichEditorTextSpanResult).value;
              this.selectionContent += (item as RichEditorTextSpanResult).value + "\n";
            }
          });
        })
        .borderWidth(1)
        .borderColor(Color.Green)
        .width('100%')
        .height('40%');

      Text("Selection Range: " + this.selectionRange)
        .fontSize(16)
        .margin({ top: 10 });

      Text("Selected Text: " + this.selectedText)
        .fontSize(16)
        .margin({ top: 10 });

      Text("Selection Content: " + this.selectionContent)
        .fontSize(16)
        .margin({ top: 10 });

      Button("Apply Bold")
        .width(150)
        .height(40)
        .onClick(() => {
          this.controller.updateSpanStyle({
            start: parseInt(this.selectionRange.split(",")[0].replace("[", "")),
            end: parseInt(this.selectionRange.split(",")[1].replace("]", "")),
            textStyle: {
              fontWeight: FontWeight.Bold
            }
          });
        });
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

@Entry
@Component
struct FullScreenTransitionAnimation {
  @State private isTransitioning: boolean = false;
  @State private scaleValue: number = 1.0;
  @State private opacityValue: number = 1.0;
  @State private rotationAngle: number = 0;

  build() {
    Column() {
      if (!this.isTransitioning) {
        Column() {
          Image($r('app.media.app_icon'))
            .width(100)
            .height(100)
            .margin({ bottom: 20 })
            .scale({ x: this.scaleValue, y: this.scaleValue })
            .rotate({ angle: this.rotationAngle })
            .opacity(this.opacityValue)
            .animation({ duration: 500, curve: Curve.EaseInOut });

          Text('Tap to Start Transition')
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .opacity(this.opacityValue)
            .animation({ duration: 500, curve: Curve.EaseInOut });

          Button('Begin Animation')
            .onClick(() => {
              this.isTransitioning = true;
              this.scaleValue = 0.5;
              this.opacityValue = 0.3;
              this.rotationAngle = 45;
            })
            .margin({ top: 20 });
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center)
      } else {
        Column() {
          Image($r('app.media.app_icon'))
            .width(150)
            .height(150)
            .margin({ bottom: 20 })
            .scale({ x: this.scaleValue, y: this.scaleValue })
            .rotate({ angle: this.rotationAngle })
            .opacity(this.opacityValue)
            .animation({ duration: 500, curve: Curve.EaseInOut });

          Text('Transition Complete')
            .fontSize(28)
            .fontWeight(FontWeight.Bold)
            .opacity(this.opacityValue)
            .animation({ duration: 500, curve: Curve.EaseInOut });

          Button('Reset Animation')
            .onClick(() => {
              this.isTransitioning = false;
              this.scaleValue = 1.0;
              this.opacityValue = 1.0;
              this.rotationAngle = 0;
            })
            .margin({ top: 20 });
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center)
        .onAppear(() => {
          this.scaleValue = 1.2;
          this.opacityValue = 1.0;
          this.rotationAngle = 0;
        })
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

