@Entry
@Component
struct CustomTabContent {
  @State currentIndex: number = 0
  private tabsController: TabsController = new TabsController()

  @Builder
  TabBuilder(title: string, index: number, icon: Resource) {
    Column() {
      Image(icon)
        .width(24)
        .height(24)
        .objectFit(ImageFit.Contain)
        .opacity(this.currentIndex === index ? 1 : 0.5)
      Text(title)
        .fontSize(12)
        .fontColor(this.currentIndex === index ? '#1698CE' : '#6B6B6B')
        .margin({ top: 4 })
    }
    .width('100%')
    .height(70)
    .justifyContent(FlexAlign.Center)
    .onClick(() => {
      this.currentIndex = index
      this.tabsController.changeIndex(index)
    })
  }

  build() {
    Tabs({ barPosition: BarPosition.End, controller: this.tabsController }) {
      TabContent() {
        Column() {
          Text('Home Content')
            .fontSize(20)
            .margin(20)
        }
        .width('100%')
        .height('100%')
      }.tabBar(this.TabBuilder('Home', 0, $r('app.media.app_icon')))

      TabContent() {
        Column() {
          Text('Search Content')
            .fontSize(20)
            .margin(20)
        }
        .width('100%')
        .height('100%')
      }.tabBar(this.TabBuilder('Search', 1, $r('app.media.app_icon')))

      TabContent() {
        Column() {
          Text('Profile Content')
            .fontSize(20)
            .margin(20)
        }
        .width('100%')
        .height('100%')
      }.tabBar(this.TabBuilder('Profile', 2, $r('app.media.app_icon')))
    }
    .barWidth('100%')
    .barHeight(70)
    .onChange((index: number) => {
      this.currentIndex = index
    })
    .width('100%')
    .height('100%')
  }
}

