@Component
struct CustomPopup {
  controller: CustomDialogController = new CustomDialogController({builder: CustomPopup, autoCancel: true});
  cancel?: () => void;
  confirm?: () => void;

  build() {
    Column() {
      Text('Custom Popup')
        .fontSize(24)
        .fontColor(Color.Black)
        .margin({ top: 20, bottom: 20 })

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ bottom: 20 })

      Text('This is a custom popup window within FullScreenLaunchComponent')
        .fontSize(16)
        .margin({ bottom: 20 })

      Row() {
        Button('Cancel')
          .onClick(() => {
            this.controller.close();
            this.cancel?.();
          })
          .backgroundColor(Color.Gray)
          .fontColor(Color.White)
          .padding(10)
          .margin({ right: 10 })

        Button('Confirm')
          .onClick(() => {
            this.controller.close();
            this.confirm?.();
          })
          .backgroundColor(Color.Blue)
          .fontColor(Color.White)
          .padding(10)
      }
    }
    .padding(20)
    .backgroundColor(Color.White)
    .borderRadius(10)
    .width('80%')
  }
}

