@Entry
@Component
struct ImageIntegrationComponent {
  @State localImage: Resource = $r('app.media.app_icon')
  @State remoteImage: string = 'https://example.com/remote_image.jpg'
  @State isLoading: boolean = false
  @State loadFailed: boolean = false

  build() {
    Column() {
      // Display local image
      Image(this.localImage)
        .width(150)
        .height(150)
        .objectFit(ImageFit.Cover)
        .borderRadius(10)
        .margin({ bottom: 20 })

      // Display remote image with loading state
      if (this.loadFailed) {
        Text('Failed to load remote image')
          .fontSize(16)
          .fontColor(Color.Red)
      } else if (this.isLoading) {
        Progress({ value: 50, total: 100 })
          .width(100)
          .height(100)
          .color(Color.Blue)
      } else {
        Image(this.remoteImage)
          .width(150)
          .height(150)
          .objectFit(ImageFit.Cover)
          .borderRadius(10)
          .onClick(() => {
            this.isLoading = true
            setTimeout(() => {
              this.isLoading = false
              this.loadFailed = !this.loadFailed
            }, 2000)
          })
      }

      // Button to refresh remote image
      Button('Refresh Remote Image')
        .width('70%')
        .margin({ top: 20 })
        .onClick(() => {
          this.isLoading = true
          this.loadFailed = false
          setTimeout(() => {
            this.isLoading = false
          }, 2000)
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .padding(20)
  }
}

