@Entry
@Component
struct FoodRatingApp {
  @State foodItems: FoodItem[] = [
    { name: 'Pizza', ratings: [], comments: [] },
    { name: 'Burger', ratings: [], comments: [] },
    { name: 'Sushi', ratings: [], comments: [] },
    { name: 'Pasta', ratings: [], comments: [] },
    { name: 'Salad', ratings: [], comments: [] }
  ];

  @State selectedFoodItem: FoodItem | null = null;
  @State currentComment: string = '';

  build() {
    Column() {
      Text('Food Rating App')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      ForEach(this.foodItems, (foodItem: FoodItem) => {
        Row() {
          Text(foodItem.name)
            .fontSize(20)
            .padding(10)
            .onClick(() => {
              this.selectedFoodItem = foodItem;
            });
        }
        .backgroundColor('#f0f0f0')
        .borderRadius(5)
        .margin({ bottom: 10 });
      });

      if (this.selectedFoodItem) {
        Column() {
          Text(`Rate ${this.selectedFoodItem.name}`)
            .fontSize(20)
            .fontWeight(FontWeight.Medium)
            .margin({ bottom: 20 });

          Row() {
            ForEach([1, 2, 3, 4, 5], (rating: number) => {
              Button(rating.toString())
                .onClick(() => {
                  this.selectedFoodItem!.ratings.push(rating);
                })
                .margin(5);
            });
          }

          TextInput({ placeholder: 'Add your comment...' })
            .width('100%')
            .onChange((value: string) => {
              this.currentComment = value;
            })
            .margin({ top: 20, bottom: 10 });

          Button('Submit Comment')
            .onClick(() => {
              if (this.currentComment) {
                this.selectedFoodItem!.comments.push(this.currentComment);
                this.currentComment = '';
              }
            })
            .margin({ bottom: 20 });

          if (this.selectedFoodItem.ratings.length > 0) {
            Text(`Average Rating: ${this.calculateAverage(this.selectedFoodItem.ratings).toFixed(2)}`)
              .fontSize(18)
              .margin({ bottom: 10 });

            if (this.selectedFoodItem.comments.length > 0) {
              Text('Latest Comments:')
                .fontSize(18)
                .margin({ top: 10, bottom: 5 });
              ForEach(this.selectedFoodItem.comments, (comment: string) => {
                Text(comment)
                  .fontSize(16)
                  .margin({ bottom: 5 });
              });
            }
          }
        }
        .padding(16)
        .backgroundColor('#ffffff')
        .borderRadius(10)
        .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(16)
    .backgroundColor('#ffffff');
  }

  calculateAverage(ratings: number[]): number {
    if (ratings.length === 0) return 0;
    return ratings.reduce((sum, rating) => sum + rating, 0) / ratings.length;
  }
}

interface FoodItem {
  name: string;
  ratings: number[];
  comments: string[];
}

