@Component
struct TabsImplementation {
  @State currentIndex: number = 0
  private tabsController: TabsController = new TabsController()

  @Builder TabBuilder(title: string, index: number) {
    Column() {
      Text(title)
        .fontColor(this.currentIndex === index ? '#1698CE' : '#6B6B6B')
        .fontSize(18)
        .fontWeight(this.currentIndex === index ? FontWeight.Bold : FontWeight.Normal)
    }
    .width('100%')
    .height(50)
    .justifyContent(FlexAlign.Center)
    .onClick(() => {
      this.currentIndex = index
      this.tabsController.changeIndex(index)
    })
  }

  build() {
    Column() {
      Tabs({ barPosition: BarPosition.Start, controller: this.tabsController }) {
        TabContent() {
          Text('Content for Tab 1')
            .fontSize(20)
            .textAlign(TextAlign.Center)
        }.tabBar(this.TabBuilder('Tab 1', 0))

        TabContent() {
          Text('Content for Tab 2')
            .fontSize(20)
            .textAlign(TextAlign.Center)
        }.tabBar(this.TabBuilder('Tab 2', 1))

        TabContent() {
          Text('Content for Tab 3')
            .fontSize(20)
            .textAlign(TextAlign.Center)
        }.tabBar(this.TabBuilder('Tab 3', 2))
      }
      .onChange((index: number) => {
        this.currentIndex = index
      })
      .barWidth('100%')
      .barHeight(60)
      .animationDuration(300)
      .scrollable(true)
      .height('100%')
      .backgroundColor('#FFFFFF')
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F1F3F5')
  }
}

