@Entry
@Component
struct DragEffectWithTransparencyShadow {
  @State offsetX: number = 0
  @State offsetY: number = 0
  @State initialX: number = 0
  @State initialY: number = 0
  @State isDragging: boolean = false
  @State shadowRadius: number = 5
  @State shadowColor: string = 'rgba(0,0,0,0.3)'

  build() {
    Stack() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .position({x: this.offsetX, y: this.offsetY})
        .opacity(this.isDragging ? 0.6 : 1)
        .shadow({
          radius: this.isDragging ? 10 : this.shadowRadius,
          color: this.isDragging ? 'rgba(0,0,0,0.7)' : this.shadowColor,
          offsetX: 5,
          offsetY: 5
        })
        .onTouch((event: TouchEvent) => {
          if (event.type === TouchType.Down) {
            this.initialX = this.offsetX
            this.initialY = this.offsetY
            this.isDragging = true
          } else if (event.type === TouchType.Move) {
            const touch = event.touches[0]
            if (touch) {
              this.offsetX = this.initialX + touch.x
              this.offsetY = this.initialY + touch.y
            }
          } else if (event.type === TouchType.Up) {
            this.isDragging = false
          }
        })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f0f0f0')
  }
}

import taskpool from '@ohos.taskpool';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct FullScreenLaunchComponent {
  @State isLoading: boolean = false;
  @State data: string[] = [];
  @State imageSrc: Resource = $r('app.media.app_icon');

  aboutToAppear() {
    this.loadData();
  }

  private async loadData() {
    this.isLoading = true;

    try {
      const task = new taskpool.Task((): string[] => {
        // Simulate data fetching with minimal delay
        const mockData: string[] = [];
        for (let i = 0; i < 5; i++) {
          mockData.push(`Optimized Data Item ${i+1}`);
        }
        return mockData;
      });

      const result = await taskpool.execute(task) as string[];
      this.data = result;
      console.info('Data loaded efficiently');

    } catch (error) {
      console.error('Data loading error:', error);
      promptAction.showToast({
        message: 'Data loading failed',
        duration: 2000,
      });
    } finally {
      this.isLoading = false;
    }
  }

  build() {
    Column() {
      if (this.isLoading) {
        Column() {
          Image(this.imageSrc)
            .width(100)
            .height(100)
            .margin(20);

          Progress({ value: 50 })
            .width(100)
            .height(10)
            .color(Color.Blue);
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center);
      } else {
        List() {
          ForEach(this.data, (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(18)
                .margin(10);
            }
          }, (item: string) => item);
        }
        .width('100%')
        .height('100%');
      }
    }
    .width('100%')
    .height('100%');
  }
}

