@Entry
@Component
struct BreadcrumbNavigation {
  @State breadcrumbs: string[] = ['Home', 'Products', 'Details'];
  @Prop showHomeIcon: boolean = true;

  @Builder
  BreadcrumbItem(text: string, index: number) {
    Text(text)
      .fontColor(this.breadcrumbs.length - 1 === index ? '#1698CE' : '#6B6B6B')
      .fontSize(16)
      .margin({ right: 8 })
      .onClick(() => {
        this.breadcrumbs = this.breadcrumbs.slice(0, index + 1);
      });
  }

  build() {
    Column() {
      Row() {
        if (this.showHomeIcon) {
          Image($r('app.media.app_icon'))
            .width(20)
            .height(20)
            .margin({ right: 8 })
            .onClick(() => {
              this.breadcrumbs = ['Home'];
            });
        }

        ForEach(this.breadcrumbs, (item: string, index: number) => {
          this.BreadcrumbItem(item, index);
          if (index < this.breadcrumbs.length - 1) {
            Text('>')
              .fontColor('#6B6B6B')
              .fontSize(16)
              .margin({ right: 8 });
          }
        });
      }
      .padding(16)
      .width('100%')
      .justifyContent(FlexAlign.Start);

      // Dynamic content based on current breadcrumb
      if (this.breadcrumbs[this.breadcrumbs.length - 1] === 'Home') {
        Text('Welcome to Home')
          .fontSize(20)
          .margin({ top: 20 });
      } else if (this.breadcrumbs[this.breadcrumbs.length - 1] === 'Products') {
        Text('Browse Products')
          .fontSize(20)
          .margin({ top: 20 });
      } else if (this.breadcrumbs[this.breadcrumbs.length - 1] === 'Details') {
        Text('Product Details')
          .fontSize(20)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(16);
  }
}

