class ItemData {
  id: number;
  title: string;
  description: string;
  image: Resource;

  constructor(id: number, title: string, description: string, image: Resource) {
    this.id = id;
    this.title = title;
    this.description = description;
    this.image = image;
  }
}

class OptimizedDataSource implements IDataSource {
  private data: Array<ItemData> = [];
  private listeners: DataChangeListener[] = [];

  initializeData(items: Array<ItemData>) {
    this.data = items;
  }

  totalCount(): number {
    return this.data.length;
  }

  getData(index: number): ItemData {
    return this.data[index];
  }

  registerDataChangeListener(listener: DataChangeListener): void {
    if (this.listeners.indexOf(listener) < 0) {
      this.listeners.push(listener);
    }
  }

  unregisterDataChangeListener(listener: DataChangeListener): void {
    const pos = this.listeners.indexOf(listener);
    if (pos >= 0) {
      this.listeners.splice(pos, 1);
    }
  }

  notifyDataReload(): void {
    this.listeners.forEach(listener => {
      listener.onDataReloaded();
    });
  }
}

