@Entry
@Component
struct CheckboxGroupExample {
  @State selectedValues: string[] = [];

  build() {
    Column() {
      CheckboxGroup({ group: 'checkboxGroup' }) {
        Checkbox({ name: 'checkbox1' })
          .select(false)
          .onChange((value: boolean) => {
            this.updateSelection('checkbox1', value);
          });

        Checkbox({ name: 'checkbox2' })
          .select(false)
          .onChange((value: boolean) => {
            this.updateSelection('checkbox2', value);
          });
      }

      Text(`Selected Checkboxes: ${this.selectedValues.join(', ')}`)
        .fontSize(18)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5');
  }

  private updateSelection(name: string, isSelected: boolean) {
    if (isSelected) {
      this.selectedValues = [...this.selectedValues, name];
    } else {
      this.selectedValues = this.selectedValues.filter(item => item !== name);
    }
    console.info(`Checkbox ${name} is ${isSelected ? 'selected' : 'unselected'}`);
  }
}

