@Component
struct OptimizedEventHandlingApp {
  @State private buttonState: boolean = false;
  @State private clickCount: number = 0;
  @State private componentStatus: string = "Initializing";

  // Custom component with optimized event handling
  @Builder
  CustomButton(buttonLabel: string, clickHandler: () => void) {
    Button(buttonLabel)
      .onClick(() => {
        clickHandler();
      })
      .backgroundColor(this.buttonState ? Color.Green : Color.Blue)
      .fontColor(Color.White)
      .margin(10)
      .onAppear(() => {
        console.log("CustomButton appeared");
        this.componentStatus = "Visible";
      })
      .onDisAppear(() => {
        console.log("CustomButton disappeared");
        this.componentStatus = "Hidden";
      });
  }

  // Lifecycle methods
  aboutToAppear() {
    console.log("Component about to appear");
    this.componentStatus = "About to appear";
  }

  aboutToUpdate() {
    console.log("Component about to update");
  }

  aboutToDisappear() {
    console.log("Component about to disappear");
  }

  build() {
    Column({ space: 20 }) {
      Text(`Component Status: ${this.componentStatus}`)
        .fontSize(18)
        .fontColor(Color.Black)

      this.CustomButton(this.buttonState ? "Active" : "Inactive", () => {
        this.clickCount++;
        this.buttonState = !this.buttonState;
        console.log(`Button clicked ${this.clickCount} times`);
      })

      Text(`Click Count: ${this.clickCount}`)
        .fontSize(20)
        .margin({ top: 15 })

