import { ExceptionPrompt, PromptOptions, MarginType } from '@kit.ArkUI';
import http from '@ohos.net.http';

@Entry
@Component
struct NetworkFailureHandling {
  @State options: PromptOptions = {
    icon: $r('app.media.app_icon'),
    tip: 'Network Error Occurred',
    marginType: MarginType.DEFAULT_MARGIN,
    actionText: 'Retry',
    marginTop: 80,
    isShown: false
  };
  @State isLoading: boolean = false;
  @State data: string = '';

  async fetchData() {
    this.isLoading = true;
    this.options.isShown = false;

    try {
      let httpRequest = http.createHttp();
      let response = await httpRequest.request(
        'https://api.example.com/data',
        {
          method: http.RequestMethod.GET,
          connectTimeout: 60000,
          readTimeout: 60000
        }
      );

      if (response.responseCode === 200) {
        this.data = response.result.toString();
      } else {
        this.options.tip = `Server Error: ${response.responseCode}`;
        this.options.isShown = true;
      }
    } catch (error) {
      this.options.tip = `Network Error: ${error.message}`;
      this.options.isShown = true;
    } finally {
      this.isLoading = false;
    }
  }

  build() {
    Column() {
      if (this.isLoading) {
        LoadingProgress()
          .width(50)
          .height(50);
      } else if (this.data) {
        Text(this.data)
          .fontSize(16)
          .margin(20);
      }

      ExceptionPrompt({
        options: this.options,
        onActionTextClick: () => {
          this.fetchData();
        }
      });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .onAppear(() => {
      this.fetchData();
    });
  }
}

@Entry
@Component
struct RatingApp {
  private itemList: Array<Item> = [
    new Item('Item 1', 0, 0),
    new Item('Item 2', 0, 0),
    new Item('Item 3', 0, 0)
  ];

  @State items: Array<Item> = this.itemList;

  private rateItem(index: number, rating: number): void {
    if (rating < 1 || rating > 5) {
      console.error('Invalid rating. Must be between 1 and 5.');
      return;
    }

    let item = this.items[index];
    let totalRating = item.rating * item.totalRatings + rating;
    item.totalRatings += 1;
    item.rating = totalRating / item.totalRatings;
    this.items[index] = item;
  }

  build() {
    Column({ space: 20 }) {
      Text('Rate the Items')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      ForEach(this.items, (item: Item, index: number) => {
        Column({ space: 10 }) {
          Text(item.name)
            .fontSize(18)
            .fontWeight(FontWeight.Medium);

          Text(`Average Rating: ${item.rating.toFixed(1)}`)
            .fontSize(16)
            .fontColor(Color.Gray);

          Row({ space: 5 }) {
            ForEach(new Array(5), (_: undefined, starIndex: number) => {
              Image($r('app.media.app_icon'))
                .width(30)
                .height(30)
                .onClick(() => {
                  this.rateItem(index, starIndex + 1);
                })
                .opacity(starIndex < item.rating ? 1 : 0.3);
            });
          }
        }
        .padding(10)
        .backgroundColor('#f0f0f0')
        .borderRadius(10)
        .margin({ bottom: 10 });
      });
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

class Item {
  name: string;
  rating: number;
  totalRatings: number;

  constructor(name: string, rating: number, totalRatings: number) {
    this.name = name;
    this.rating = rating;
    this.totalRatings = totalRatings;
  }
}

