@Entry
@Component
struct LoginScreen {
  @State email: string = ''
  @State password: string = ''
  @State message: string = ''
  @State isSuccess: boolean = false

  build() {
    Column() {
      // Email Input
      Text('Email:')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your email' })
        .width('80%')
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.email = value
        })

      // Password Input
      Text('Password:')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .width('80%')
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.password = value
        })

      // Login Button
      Button('Login')
        .onClick(() => {
          if (this.validateEmail(this.email) && this.password.length >= 8) {
            this.message = 'Login successful!'
            this.isSuccess = true
          } else {
            this.message = 'Invalid email or password.'
            this.isSuccess = false
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      // Message Display
      if (this.message) {
        Text(this.message)
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
          .fontColor(this.isSuccess ? Color.Green : Color.Red)
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }

  validateEmail(email: string) {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return re.test(email)
  }
}

@Entry
@Component
struct ApiDataApp {
  @State private items: ApiItem[] = [];
  @State private isLoading: boolean = true;
  @State private error: string = '';

  aboutToAppear() {
    this.fetchData();
  }

  fetchData() {
    setTimeout(() => {
      this.items = [
        {
          id: 1,
          title: 'Item 1',
          image: 'app.media.app_icon',
          description: 'Description for Item 1.'
        },
        {
          id: 2,
          title: 'Item 2',
          image: 'app.media.app_icon',
          description: 'Description for Item 2.'
        },
        {
          id: 3,
          title: 'Item 3',
          image: 'app.media.app_icon',
          description: 'Description for Item 3.'
        }
      ];
      this.isLoading = false;
    }, 2000);
  }

  build() {
    Column() {
      if (this.isLoading) {
        Text('Loading...')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20, bottom: 20 });
      } else if (this.error) {
        Text(`Error: ${this.error}`)
          .fontSize(18)
          .fontColor(Color.Red)
          .margin(10);
      } else {
        Text('Items List')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20, bottom: 20 })
          .textAlign(TextAlign.Center);

        List() {
          ForEach(this.items, (item: ApiItem) => {
            ListItem() {
              Row() {
                Image(item.image)
                  .width(80)
                  .height(80)
                  .borderRadius(8)
                  .objectFit(ImageFit.Cover);

                Column() {
                  Text(item.title)
                    .fontSize(18)
                    .fontWeight(FontWeight.Medium)
                    .margin({ bottom: 4 });

                  Text(item.description)
                    .fontSize(14)
                    .fontColor('#666666');
                }
                .layoutWeight(1)
                .alignItems(HorizontalAlign.Start)
                .margin({ left: 16 });
              }
              .padding(16)
              .backgroundColor(Color.White)
              .borderRadius(12);
            }
            .margin({ bottom: 12 });
          });
        }
        .width('100%');
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }
}

interface ApiItem {
  id: number;
  title: string;
  image: string;
  description: string;
}

