import promptAction from '@ohos.promptAction';

@Entry
@Component
struct UserRegistrationForm {
  @State username: string = '';
  @State email: string = '';
  @State password: string = '';
  @State showDialog: boolean = false;

  build() {
    Column() {
      // Form Title
      Text('User Registration')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      // Username Input
      Column() {
        Text('Username:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter username' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.username = value;
          });
      }

      // Email Input
      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value;
          });
      }

      // Password Input
      Column() {
        Text('Password:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter password' })
          .type(InputType.Password)
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.password = value;
          });
      }

      // Submit Button
      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.username && this.email && this.password) {
            this.showDialog = true;
          } else {
            promptAction.showToast({
              message: 'Please fill all fields'
            });
          }
        });

      // Information Dialog
      if (this.showDialog) {
        Column() {
          Text('Registration Details')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Username: ${this.username}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Password: ${this.password.replace(/./g, '*')}`)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.showDialog = false;
              this.username = '';
              this.email = '';
              this.password = '';
            })
            .width('100%')
            .height(50)
            .backgroundColor('#007AFF');
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

@Entry
@Component
struct CustomMenuAnimation {
  @State isMenuOpen: boolean = false
  @State menuScale: number = 0.1
  @State menuOpacity: number = 0
  @State menuRotate: number = 0

  build() {
    Column() {
      Button('Toggle Menu')
        .onClick(() => {
          this.isMenuOpen = !this.isMenuOpen
          animateTo({
            duration: 500,
            curve: Curve.EaseInOut
          }, () => {
            this.menuScale = this.isMenuOpen ? 1 : 0.1
            this.menuOpacity = this.isMenuOpen ? 1 : 0
            this.menuRotate = this.isMenuOpen ? 360 : 0
          })
        })
        .margin(20)

      Stack() {
        Image($r('app.media.app_icon'))
          .scale({ x: this.menuScale, y: this.menuScale })
          .opacity(this.menuOpacity)
          .rotate({ angle: this.menuRotate })
          .animation({
            duration: 500,
            curve: Curve.EaseInOut
          })

        Column() {
          Text('Home').fontSize(20).margin(10)
          Text('Settings').fontSize(20).margin(10)
          Text('Profile').fontSize(20).margin(10)
        }
        .scale({ x: this.menuScale, y: this.menuScale })
        .opacity(this.menuOpacity)
        .animation({
          duration: 500,
          curve: Curve.EaseInOut
        })
      }
      .width('100%')
