import promptAction from '@ohos.promptAction';

@Entry
@Component
struct LoginApp {
  @State email: string = '';
  @State password: string = '';
  @State isLoggedIn: boolean = false;
  @State welcomeMessage: string = '';

  build() {
    Column() {
      if (!this.isLoggedIn) {
        // Email Input
        Text('Email')
          .fontSize(18)
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value;
          });

        // Password Input
        Text('Password')
          .fontSize(18)
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Enter your password' })
          .type(InputType.Password)
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.password = value;
          });

        // Login Button
        Button('Login')
          .width('100%')
          .height(50)
          .fontSize(18)
          .backgroundColor('#007AFF')
          .onClick(() => {
            if (this.email && this.password) {
              this.isLoggedIn = true;
              this.welcomeMessage = `Welcome, ${this.email}!`;
            } else {
              promptAction.showToast({
                message: 'Please fill in all fields'
              });
            }
          });
      } else {
        // Welcome Message
