          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 });

        // Logout Button
        Button('Logout')
          .width('100%')
          .height(50)
          .fontSize(18)
          .backgroundColor('#FF3B30')
          .onClick(() => {
            this.isLoggedIn = false;
            this.email = '';
            this.password = '';
            this.welcomeMessage = '';
          });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

