@Entry
@Component
struct DragAndDropLists {
  @State leftList: Array<string> = ['Apple', 'Banana', 'Orange'];
  @State rightList: Array<string> = ['Carrot', 'Tomato', 'Potato'];
  @State draggingItem: string = '';
  @State targetList: string = '';

  build() {
    Column() {
      Row() {
        Column() {
          Text('Fruits').fontSize(20).margin({ bottom: 10 });
          ForEach(this.leftList, (item: string) => {
            Text(item)
              .fontSize(16)
              .padding(10)
              .border({ width: 1, color: '#cccccc' })
              .margin({ bottom: 5 })
              .backgroundColor(this.draggingItem === item ? '#e0e0e0' : '#ffffff')
              .onTouch((event: TouchEvent) => {
                if (event.type === TouchType.Down) {
                  this.draggingItem = item;
                  this.targetList = 'right';
                }
                if (event.type === TouchType.Up) {
                  if (this.draggingItem && this.targetList === 'right') {
                    this.rightList.push(this.draggingItem);
                    this.leftList = this.leftList.filter(i => i !== this.draggingItem);
                  }
                  this.draggingItem = '';
                  this.targetList = '';
                }
              });
          });
        }
        .width('50%')
        .padding(10)

        Column() {
          Text('Vegetables').fontSize(20).margin({ bottom: 10 });
          ForEach(this.rightList, (item: string) => {
            Text(item)
              .fontSize(16)
              .padding(10)
              .border({ width: 1, color: '#cccccc' })
              .margin({ bottom: 5 })
              .backgroundColor(this.draggingItem === item ? '#e0e0e0' : '#ffffff')
              .onTouch((event: TouchEvent) => {
                if (event.type === TouchType.Down) {
                  this.draggingItem = item;
                  this.targetList = 'left';
                }
                if (event.type === TouchType.Up) {
                  if (this.draggingItem && this.targetList === 'left') {
                    this.leftList.push(this.draggingItem);
                    this.rightList = this.rightList.filter(i => i !== this.draggingItem);
                  }
                  this.draggingItem = '';
                  this.targetList = '';
                }
              });
          });
        }
        .width('50%')
        .padding(10)
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

