@Entry
@Component
struct RefreshComponentWithStates {
  @State isRefreshing: boolean = false;
  @State refreshState: string = 'Idle'; // Can be: Idle, Dragging, Refreshing, Complete
  @State refreshCount: number = 0;
  @State lastRefreshTime: string = 'Never';

  build() {
    Column() {
      // State indicator
      Text(`Current State: ${this.refreshState}`)
        .fontSize(18)
        .margin(10)
        .fontColor(this.getStateColor());

      // Visual indicator based on state
      if (this.refreshState === 'Refreshing') {
        Row() {
          LoadingProgress()
            .width(30)
            .height(30);
          Text('Loading...')
            .margin({ left: 10 });
        }
        .width('100%')
        .justifyContent(FlexAlign.Center);
      } else if (this.refreshState === 'Complete') {
        Image($r('app.media.app_icon'))
          .width(30)
          .height(30)
          .margin(5);
      }

      // Refresh stats
      Text(`Refresh Count: ${this.refreshCount}`)
        .fontSize(16)
        .margin(5);
      Text(`Last Refresh: ${this.lastRefreshTime}`)
        .fontSize(16)
        .margin(5);

      // The actual Refresh component
      Refresh({ refreshing: $$this.isRefreshing }) {
        Column() {
          Text(this.getPullText())
            .fontSize(18)
            .margin(10);
        }
        .width('100%')
        .height(100);
      }
      .onStateChange((refreshStatus: RefreshStatus) => {
        switch (refreshStatus) {
          case RefreshStatus.Inactive:
            this.refreshState = 'Idle';
            break;
          case RefreshStatus.Drag:
            this.refreshState = 'Dragging';
            break;
          case RefreshStatus.OverDrag:
            this.refreshState = 'Ready to Refresh';
            break;
          case RefreshStatus.Refresh:
            this.refreshState = 'Refreshing';
            this.refreshCount += 1;
            this.lastRefreshTime = new Date().toLocaleTimeString();
            break;
          case RefreshStatus.Inactive:  // Changed from Success to Inactive
            this.refreshState = 'Complete';
            setTimeout(() => {
              this.refreshState = 'Idle';
            }, 1000);
            break;
        }
      })
      .onRefreshing(() => {
        // Simulate refresh action
        setTimeout(() => {
          this.isRefreshing = false;
        }, 2000);
      });
    }
    .width('100%')
    .height('100%');
  }

  private getStateColor(): string {
    switch (this.refreshState) {
      case 'Idle': return '#666666';
      case 'Dragging': return '#0099FF';
      case 'Ready to Refresh': return '#00CC66';
      case 'Refreshing': return '#FF9900';
      case 'Complete': return '#00CC66';
      default: return '#000000';
    }
  }

  private getPullText(): string {
    switch (this.refreshState) {
      case 'Idle': return 'Pull down to refresh';
      case 'Dragging': return 'Keep pulling...';
      case 'Ready to Refresh': return 'Release to refresh';
      case 'Refreshing': return 'Refreshing...';
      case 'Complete': return 'Refresh complete!';
      default: return 'Pull to refresh';
    }
  }
}

@Entry
@Component
struct ECommerceActivityLogger {
  @State activityLogs: Array<string> = [];
  @State criticalActions: number = 0;
  @State isTracking: boolean = true;

  private logActivity(activity: string, isCritical: boolean = false) {
    const timestamp = new Date().toLocaleString();
    const prefix = isCritical ? '[CRITICAL]' : '[REGULAR]';
    const logEntry = `${prefix} ${timestamp}: ${activity}`;
    this.activityLogs.unshift(logEntry);
    if (isCritical) this.criticalActions += 1;
    console.info(logEntry);
  }

  build() {
    Column() {
      Text('E-Commerce Activity Tracker')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      // E-commerce action buttons
      Column({ space: 15 }) {
        Button('Add to Cart')
          .onClick(() => this.logActivity('Item added to cart'))
          .width('80%')
          .fontSize(18);

        Button('View Product')
          .onClick(() => this.logActivity('Product viewed'))
          .width('80%')
          .fontSize(18);

        Button('Checkout')
          .onClick(() => {
            this.logActivity('Checkout initiated', true);
          })
          .width('80%')
          .fontSize(18)
          .backgroundColor('#FF5733')
          .fontColor(Color.White);

        Button('Apply Coupon')
          .onClick(() => this.logActivity('Coupon applied'))
          .width('80%')
          .fontSize(18);
      }
      .margin({ bottom: 20 });

      // Tracking toggle
      Row({ space: 20 }) {
        Button(this.isTracking ? 'Stop Tracking' : 'Start Tracking')
          .onClick(() => {
            this.isTracking = !this.isTracking;
            this.logActivity(`Tracking ${this.isTracking ? 'enabled' : 'disabled'}`);
          })
          .width('40%');

        Text(`Critical Actions: ${this.criticalActions}`)
          .fontSize(16)
          .fontColor(Color.Red);
      }
      .margin({ bottom: 20 });

      // Activity log display
      Text('Activity Logs')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      if (this.activityLogs.length > 0) {
        List() {
          ForEach(this.activityLogs, (log: string) => {
            ListItem() {
              Text(log)
                .fontSize(14)
                .fontColor(log.includes('[CRITICAL]') ? Color.Red : Color.Black)
                .margin(5);
            }
          });
        }
        .height(200)
        .width('100%')
        .border({ width: 1, color: Color.Gray });
      } else {
        Text('No activities logged yet')
          .fontSize(16)
          .fontColor(Color.Gray);
      }
    }
    .padding(20)
    .width('100%')
    .height('100%');
  }
}

