@Entry
@Component
struct FormValidationApp {
  @State username: string = ''
  @State password: string = ''
  @State email: string = ''
  @State usernameError: string = ''
  @State passwordError: string = ''
  @State emailError: string = ''
  @State isFormValid: boolean = false

  validateUsername(username: string): string | null {
    if (username.length < 3) {
      return 'Username must be at least 3 characters'
    }
    return null
  }

  validatePassword(password: string): string | null {
    if (password.length < 6) {
      return 'Password must be at least 6 characters'
    }
    return null
  }

  validateEmail(email: string): string | null {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return emailRegex.test(email) ? null : 'Invalid email format'
  }

  validateForm() {
    const usernameError = this.validateUsername(this.username)
    const passwordError = this.validatePassword(this.password)
    const emailError = this.validateEmail(this.email)
    this.usernameError = usernameError || ''
    this.passwordError = passwordError || ''
    this.emailError = emailError || ''
    this.isFormValid = !usernameError && !passwordError && !emailError
  }

  build() {
    Column({ space: 20 }) {
      TextInput({ placeholder: 'Username' })
        .onChange((value: string) => {
          this.username = value
          this.validateForm()
        })
        .border({
          width: 1,
          color: this.usernameError ? '#ff0000' : '#ddd'
        })
        .width('100%')

      if (this.usernameError) {
        Text(this.usernameError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      TextInput({ placeholder: 'Email' })
        .onChange((value: string) => {
          this.email = value
          this.validateForm()
        })
        .border({
          width: 1,
          color: this.emailError ? '#ff0000' : '#ddd'
        })
        .width('100%')

      if (this.emailError) {
        Text(this.emailError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      TextInput({ placeholder: 'Password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
          this.validateForm()
        })
        .border({
          width: 1,
          color: this.passwordError ? '#ff0000' : '#ddd'
        })
        .width('100%')

      if (this.passwordError) {
        Text(this.passwordError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      Button('Submit')
        .enabled(this.isFormValid)
        .onClick(() => {
          console.info('Form submitted successfully')
        })
    }
    .padding(20)
    .width('100%')
  }
}

