@Component
struct NoteApp {
  private notes: Array<Note> = [];
  private newNoteTitle: string = '';
  private newNoteContent: string = '';

  build() {
    Column() {
      TextInput({ placeholder: 'Enter note title...', text: this.newNoteTitle })
        .height(50)
        .width('90%')
        .onChange((value: string) => {
          this.newNoteTitle = value;
        })
        .margin(10);

      TextArea({ placeholder: 'Enter note content...', text: this.newNoteContent })
        .height(150)
        .width('90%')
        .onChange((value: string) => {
          this.newNoteContent = value;
        })
        .margin(10);

      Button('Add Note')
        .onClick(() => {
          if (this.newNoteTitle.trim() && this.newNoteContent.trim()) {
            this.notes.push({
              id: Date.now(),
              title: this.newNoteTitle,
              content: this.newNoteContent
            });
            this.newNoteTitle = '';
            this.newNoteContent = '';
          }
        })
        .margin(10);

      List() {
        ForEach(this.notes, (note: Note) => {
          ListItem() {
            Row() {
              Column() {
                Text(note.title)
                  .fontSize(20)
                  .fontWeight(FontWeight.Bold)
                  .margin({ bottom: 8 });

                Text(note.content)
                  .fontSize(16)
                  .margin({ bottom: 8 });
              }
              .width('80%');

              Button('Delete')
                .onClick(() => {
                  this.notes = this.notes.filter(n => n.id !== note.id);
                })
                .margin(5);
            }
            .padding(10);
          }
        });
      }
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

interface Note {
  id: number;
  title: string;
  content: string;
}

