@Entry
@Component
struct MovieSearchApp {
  @State searchKeyword: string = '';
  @State filteredMovies: Movie[] = movies;

  private filterMovies(): void {
    if (this.searchKeyword.trim() === '') {
      this.filteredMovies = movies;
    } else {
      this.filteredMovies = movies.filter(movie =>
        movie.title.toLowerCase().includes(this.searchKeyword.toLowerCase())
      );
    }
  }

  build() {
    Column() {
      // Search bar
      TextInput({ placeholder: 'Search movies...' })
        .width('90%')
        .height(40)
        .margin(16)
        .onChange((value: string) => {
          this.searchKeyword = value;
          this.filterMovies();
        });

      // Movie grid
      if (this.filteredMovies.length > 0) {
        Grid() {
          ForEach(this.filteredMovies, (movie: Movie) => {
            GridItem() {
              Column() {
                Image(movie.poster)
                  .width(120)
                  .height(180)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(8)
                  .margin({ bottom: 8 });

                Text(movie.title)
                  .fontSize(16)
                  .fontWeight(FontWeight.Medium)
                  .maxLines(1)
                  .textOverflow({ overflow: TextOverflow.Ellipsis })
                  .width(120)
                  .textAlign(TextAlign.Center);
              }
