@Entry
@Component
struct DraggableSliderApp {
  @State imageSize: number = 100
  @State sliderValue: number = 50
  @State offsetX: number = 0
  @State initialX: number = 0

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(this.imageSize)
        .height(this.imageSize)
        .objectFit(ImageFit.Contain)
        .margin({ top: 20 })

      Slider({
        value: this.sliderValue,
        min: 0,
        max: 100,
        step: 1,
        style: SliderStyle.OutSet
      })
      .onChange((value: number) => {
        this.sliderValue = value
        this.imageSize = 100 + value
      })
      .onTouch((event: TouchEvent) => {
        if (event.type === TouchType.Down) {
          this.initialX = event.touches[0].x
        } else if (event.type === TouchType.Move) {
          this.offsetX = event.touches[0].x - this.initialX
          this.sliderValue = Math.max(0, Math.min(100, this.sliderValue + this.offsetX / 10))
          this.imageSize = 100 + this.sliderValue
          this.initialX = event.touches[0].x
        }
      })
      .margin({ top: 20, left: 20, right: 20 })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

