struct MenuOpenEventConfig {
  @State isMenuOpen: boolean = false;
  @State menuItems: string[] = ['Option 1', 'Option 2', 'Option 3', 'Option 4'];
  @State selectedItem: string = '';

  private toggleMenu() {
    this.isMenuOpen = !this.isMenuOpen;
    console.log(`Menu is now ${this.isMenuOpen ? 'open' : 'closed'}`);
  }

  private handleItemClick(item: string) {
    this.selectedItem = item;
    this.isMenuOpen = false;
    console.log(`Selected menu item: ${item}`);
  }

  build() {
    Column() {
      // Main content area
      Column() {
        Text('Main Application Content')
          .fontSize(24)
          .margin({ bottom: 20 });

        Button(this.isMenuOpen ? 'Close Menu' : 'Open Menu')
          .onClick(() => {
            this.toggleMenu();
          })
          .width(200)
          .height(50)
          .backgroundColor(Color.Blue)
          .fontColor(Color.White);
      }
      .width('100%')
      .height('70%')
      .justifyContent(FlexAlign.Center)
      .alignItems(HorizontalAlign.Center)

      // Menu area (conditionally rendered)
      if (this.isMenuOpen) {
        Column() {
          ForEach(this.menuItems, (item: string) => {
            Row() {
              Image($r('app.media.app_icon'))
                .width(24)
                .height(24)
                .margin({ right: 10 });
              Text(item)
                .fontSize(18)
                .fontColor(Color.Black)
            }
