@Entry
@Component
struct EnvironmentPropertyValidation {
  @State environment: string = '';
  @State isValid: boolean = true;
  @State errorMessage: string = '';

  validateEnvironment(env: string): string | null {
    const validEnvironments = ['development', 'staging', 'production'];
    if (!validEnvironments.includes(env)) {
      return 'Environment must be one of: development, staging, production';
    }
    return null;
  }

  build() {
    Column({ space: 20 }) {
      TextInput({ placeholder: 'Enter environment (development, staging, production)' })
        .onChange((value: string) => {
          this.environment = value;
          const error = this.validateEnvironment(value);
          this.errorMessage = error || '';
          this.isValid = !error;
        })
        .border({
          width: 1,
          color: this.isValid ? '#ddd' : '#ff0000'
        })
        .width('100%');

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 });
      }

      Button('Save Environment')
        .enabled(this.isValid && this.environment.length > 0)
        .onClick(() => {
          console.info('Valid environment saved:', this.environment);
        })
        .width('100%');
    }
    .padding(20)
    .width('100%');
  }
}

