import curves from '@ohos.curves';

@Entry
@Component
struct AnimationReleaseExample {
  @State rotation: number = 0;
  private isAnimating: boolean = false;

  aboutToAppear() {
    // Start animation when page appears
    this.startAnimation();
  }

  aboutToDisappear() {
    // Clean up animation when page hides
    this.cleanupAnimation();
  }

  startAnimation() {
    this.isAnimating = true;
    this.animateRotation();
  }

  animateRotation() {
    if (!this.isAnimating) return;

    animateTo({
      duration: 2000,
      iterations: -1, // Infinite loop
      playMode: PlayMode.Normal,
      onFinish: () => {
        if (this.isAnimating) {
          this.animateRotation(); // Continue the animation loop
        }
      }
    }, () => {
      this.rotation = (this.rotation + 10) % 360;
    });
  }

  cleanupAnimation() {
    this.isAnimating = false;
    console.log('Animation resources released');
  }

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })

      Button('Clean Up Animation Now')
        .margin(20)
        .onClick(() => {
          this.cleanupAnimation();
        })

      Button('Restart Animation')
        .margin(20)
        .onClick(() => {
          this.startAnimation();
        })
    }
    .width('100%')
