@Entry
@Component
struct PromiseChainManagement {
  @State data: string = "Initial data";
  @State isLoading: boolean = false;
  @State error: string = "";
  @State imageSrc: ResourceStr = $r('app.media.app_icon');

  // First async operation - simulates API call
  private fetchUserData(): Promise<string> {
    return new Promise((resolve) => {
      setTimeout(() => {
        resolve("User data retrieved");
      }, 1500);
    });
  }

  // Second async operation - processes data
  private transformData(rawData: string): Promise<string> {
    return new Promise((resolve) => {
      setTimeout(() => {
        resolve(`Transformed: ${rawData.toUpperCase()}`);
      }, 1000);
    });
  }

  // Third async operation - loads image
  private fetchImage(): Promise<ResourceStr> {
    return new Promise((resolve) => {
      setTimeout(() => {
        resolve($r('app.media.app_icon'));
      }, 1200);
    });
  }

  // Execute the promise chain
  private runAsyncOperations() {
    this.isLoading = true;
    this.error = "";

    this.fetchUserData()
      .then((userData: string) => {
        return this.transformData(userData);
      })
      .then((processedData: string) => {
        this.data = processedData;
        return this.fetchImage();
      })
      .then((img: ResourceStr) => {
        this.imageSrc = img;
      })
      .catch((err: Error) => {
        this.error = `Operation failed: ${err.message}`;
      })
      .finally(() => {
        this.isLoading = false;
      });
  }

  build() {
    Column({ space: 15 }) {
      if (this.isLoading) {
        Progress({ value: 0, total: 100, type: ProgressType.Ring })
          .width(100)
          .height(100)
          .color(Color.Blue);
      } else {
        Image(this.imageSrc)
          .width(120)
          .height(120)
          .margin(10);

        Text(this.data)
          .fontSize(20)
          .fontColor(Color.Black)
          .margin(10);

        if (this.error) {
          Text(this.error)
            .fontSize(16)
            .fontColor(Color.Red);
        }
      }

      Button("Run Async Chain")
        .onClick(() => {
          this.runAsyncOperations();
        })
        .width(200)
        .height(50)
        .margin(20);
    }
    .width("100%")
    .height("100%")
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

@Entry
@Component
struct RegistrationForm {
  @State name: string = ''
  @State email: string = ''
  @State password: string = ''
  @State successMessage: string = ''
  @State errorMessage: string = ''

  validateEmail(email: string): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return emailRegex.test(email)
  }

  validatePassword(password: string): boolean {
    const passwordRegex = /^(?=.*[A-Za-z])(?=.*\d)[A-Za-z\d]{8,}$/
    return passwordRegex.test(password)
  }

  validateForm(): boolean {
    if (!this.name || !this.email || !this.password) {
      this.errorMessage = 'All fields are required'
      return false
    }
    if (!this.validateEmail(this.email)) {
      this.errorMessage = 'Invalid email format'
      return false
    }
    if (!this.validatePassword(this.password)) {
      this.errorMessage = 'Password must be at least 8 characters long and contain at least one letter and one number'
      return false
    }
    this.errorMessage = ''
    return true
  }

  build() {
    Column({ space: 20 }) {
      Text('Registration Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your name' })
        .onChange((value: string) => {
          this.name = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your email' })
        .onChange((value: string) => {
          this.email = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .margin({ bottom: 20 })

      Button('Submit')
        .onClick(() => {
          if (this.validateForm()) {
            this.successMessage = 'Registration successful!'
            this.name = ''
            this.email = ''
            this.password = ''
          }
        })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 20 })
      }

      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(18)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

