@Entry
@Component
struct ApiListApp {
  @State items: ApiItem[] = [];
  @State isLoading: boolean = true;
  @State selectedItem: ApiItem | null = null;

  aboutToAppear() {
    this.fetchData();
  }

  async fetchData() {
    this.isLoading = true;
    try {
      this.items = await ApiService.fetchItems();
    } catch (error) {
      console.error('Error fetching data:', error);
    } finally {
      this.isLoading = false;
    }
  }

  build() {
    Column() {
      if (this.selectedItem) {
        ItemDetail({ item: this.selectedItem });
        Button('Back')
          .onClick(() => { this.selectedItem = null; })
          .margin(20);
      } else if (this.isLoading) {
        Column() {
          Text('Loading...')
            .fontSize(18);
          Progress({ value: 50, total: 100 })
            .width('80%');
        }
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center)
      } else {
        List() {
          ForEach(this.items, (item: ApiItem) => {
            ListItem() {
              Row() {
                Image(item.thumbnailUrl)
                  .width(60)
                  .height(60)
