@Component
struct KeyboardNavigationApp {
  @State input1: string = '';
  @State input2: string = '';
  @State activeElement: number = 0;
  @State navigationMessage: string = 'Use Tab/Shift+Tab to navigate';

  build() {
    Column({ space: 20 }) {
      Text(this.navigationMessage)
        .fontSize(16)
        .margin({ top: 20 })

      TextInput({ placeholder: 'First Input', text: this.input1 })
        .width('80%')
        .height(50)
        .border({ width: this.activeElement === 0 ? 2 : 1, color: this.activeElement === 0 ? Color.Blue : Color.Gray })
        .onChange((value: string) => {
          this.input1 = value;
        })
        .onFocus(() => {
          this.activeElement = 0;
          this.navigationMessage = 'Focused on First Input';
        })

      TextInput({ placeholder: 'Second Input', text: this.input2 })
        .width('80%')
        .height(50)
        .border({ width: this.activeElement === 1 ? 2 : 1, color: this.activeElement === 1 ? Color.Blue : Color.Gray })
        .onChange((value: string) => {
          this.input2 = value;
        })
        .onFocus(() => {
          this.activeElement = 1;
          this.navigationMessage = 'Focused on Second Input';
        })

      Button('Submit')
        .width(150)
        .height(50)
        .border({ width: this.activeElement === 2 ? 2 : 1, color: this.activeElement === 2 ? Color.Blue : Color.Gray })
        .onClick(() => {
          this.navigationMessage = 'Form Submitted!';
        })
        .onFocus(() => {
          this.activeElement = 2;
          this.navigationMessage = 'Focused on Submit Button';
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor(Color.White)
  }
}

