@Entry
@Component
struct StateValidationExample {
  @State private inputValue: string = 'Default Value'; // Initialize state with default value
  @State private isValid: boolean = true; // Track validation state

  private validateInput(value: string): boolean {
    // Validation: input must be between 3-20 characters and alphanumeric
    const regex = /^[a-zA-Z0-9]{3,20}$/;
    return regex.test(value);
  }

  build() {
    Column() {
      // Display current value
      Text(`Current Value: ${this.inputValue}`)
        .fontSize(20)
        .margin(10)

      // Display validation status
      Text(this.isValid ? 'Valid' : 'Invalid')
        .fontSize(16)
        .fontColor(this.isValid ? '#00FF00' : '#FF0000')
        .margin(5)

      // Input field with validation
      TextInput({ placeholder: 'Enter 3-20 alphanumeric chars' })
        .onChange((newValue: string) => {
          this.isValid = this.validateInput(newValue);
          if (this.isValid) {
            this.inputValue = newValue;
          }
        })
        .margin(10)
        .width(250)
        .borderColor(this.isValid ? '#000000' : '#FF0000')

      // Reset button
      Button('Reset to Default')
        .onClick(() => {
          this.inputValue = 'Default Value';
          this.isValid = true;
        })
        .margin(10)
        .width(200)
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

