@Entry
@Component
struct FilteringOptionsExample {
  @State selectedFilter: string = 'All';
  @State searchText: string = '';
  @State items: string[] = ['Apple', 'Banana', 'Orange', 'Grapes', 'Mango', 'Pineapple', 'Strawberry', 'Watermelon'];
  @State filteredItems: string[] = this.items;

  private applyFilters() {
    this.filteredItems = this.items.filter(item => {
      const matchesSearch = item.toLowerCase().includes(this.searchText.toLowerCase());
      const matchesFilter = this.selectedFilter === 'All' ||
                          (this.selectedFilter === 'Fruits' && ['Apple', 'Banana', 'Orange'].includes(item)) ||
                          (this.selectedFilter === 'Berries' && ['Strawberry', 'Blueberry'].includes(item));
      return matchesSearch && matchesFilter;
    });
  }

  build() {
    Column({ space: 10 }) {
      // Search Input
      TextInput({ placeholder: 'Search items...' })
        .width('90%')
        .height(50)
        .margin(10)
        .onChange((value: string) => {
          this.searchText = value;
          this.applyFilters();
        });

      // Filter Buttons
      Row({ space: 10 }) {
        Button('All')
          .onClick(() => {
            this.selectedFilter = 'All';
            this.applyFilters();
          })
          .backgroundColor(this.selectedFilter === 'All' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1)

        Button('Fruits')
          .onClick(() => {
            this.selectedFilter = 'Fruits';
            this.applyFilters();
          })
          .backgroundColor(this.selectedFilter === 'Fruits' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1)

        Button('Berries')
          .onClick(() => {
            this.selectedFilter = 'Berries';
            this.applyFilters();
          })
          .backgroundColor(this.selectedFilter === 'Berries' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1)
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .padding(10)

      // Filtered Results
      if (this.filteredItems.length > 0) {
        List() {
          ForEach(this.filteredItems, (item: string) => {
            ListItem() {
              Row() {
                Image($r('app.media.app_icon'))
                  .width(30)
                  .height(30)
                  .margin({ right: 10 });
                Text(item)
                  .fontSize(18);
              }
              .width('100%')
              .padding(10)
            }
          })
        }
        .width('100%')
        .height('70%')
      } else {
        Column() {
          Image($r('app.media.app_icon'))
            .width(100)
            .height(100)
            .margin({ bottom: 20 });
          Text('No items match your filters')
            .fontSize(18)
            .fontColor('#666');
        }
        .width('100%')
        .height('70%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff')
    .onAppear(() => {
      this.applyFilters();
    })
  }
}

@Entry
@Component
struct LoginScreen {
  @State email: string = ''
  @State password: string = ''
  @State message: string = ''
  @State isSuccess: boolean = false

  build() {
    Column() {
      // Email Input
      Text('Email:')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your email' })
        .width('80%')
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.email = value
        })

      // Password Input
      Text('Password:')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .width('80%')
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.password = value
        })

      // Login Button
      Button('Login')
        .onClick(() => {
          if (this.validateEmail(this.email) && this.validatePassword(this.password)) {
            this.message = 'Login successful!'
            this.isSuccess = true
          } else {
            this.message = 'Invalid email or password.'
            this.isSuccess = false
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      // Message Display
      if (this.message) {
        Text(this.message)
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
          .fontColor(this.isSuccess ? Color.Green : Color.Red)
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }

  validateEmail(email: string): boolean {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return re.test(email)
  }

  validatePassword(password: string): boolean {
    return password.length >= 8
  }
}

