@Entry
@Component
struct OptionValidationApp {
  @State text: string = "Select an option"
  @State index: number = 0
  @State errorMessage: string = ''
  @State isValid: boolean = false

  validateOption(selectedIndex: number): boolean {
    if (selectedIndex === 0) {
      this.errorMessage = 'Please select a valid option'
      this.isValid = false
      return false
    }
    this.errorMessage = ''
    this.isValid = true
    return true
  }

  build() {
    Column() {
      Select([
        { value: 'Select an option', icon: $r("app.media.app_icon") },
        { value: 'Option 1', icon: $r("app.media.app_icon") },
        { value: 'Option 2', icon: $r("app.media.app_icon") },
        { value: 'Option 3', icon: $r("app.media.app_icon") }
      ])
      .selected(this.index)
      .value(this.text)
      .font({ size: 16, weight: 500 })
      .fontColor('#182431')
      .selectedOptionFont({ size: 16, weight: 400 })
      .optionFont({ size: 16, weight: 400 })
      .menuAlign(MenuAlignType.START)
      .onSelect((index: number, text?: string | undefined) => {
        this.index = index
        if (text) {
          this.text = text
        }
        this.validateOption(index)
      })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 10 })
      }

      Button('Submit')
        .enabled(this.isValid)
        .onClick(() => {
          console.info('Valid option selected:', this.text)
        })
        .margin({ top: 20 })
    }
    .width('100%')
    .padding(20)
  }
}

