            duration: 1000
          }
        ])
        .onCancel(this.handleCancel.bind(this))
        .width(100)
        .height(100)

      Text(this.isCanceled ? "Animation Canceled" : "Animation Running")
        .fontSize(20)
        .margin({ top: 20 })

