@Entry
@Component
struct ArcDrawingApp {
  private settings: RenderingContextSettings = new RenderingContextSettings(true)
  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings)

  build() {
    Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Center, justifyContent: FlexAlign.Center }) {
      Canvas(this.context)
        .width('100%')
        .height('100%')
        .backgroundColor('#ffffff')
        .onReady(() => {
          // Draw a simple arc
          this.context.beginPath()
          this.context.arc(100, 100, 50, 0, Math.PI / 2, false)
          this.context.strokeStyle = '#ff0000'
          this.context.lineWidth = 5
          this.context.stroke()

          // Draw a dashed arc
          this.context.beginPath()
          this.context.arc(200, 100, 50, Math.PI / 2, Math.PI, false)
          this.context.strokeStyle = '#00ff00'
          this.context.lineWidth = 5
          this.context.setLineDash([10, 5])
          this.context.stroke()

          // Draw a filled arc
          this.context.beginPath()
          this.context.arc(100, 200, 50, Math.PI, 3 * Math.PI / 2, false)
          this.context.fillStyle = '#0000ff'
          this.context.fill()

          // Draw a thick arc with rounded ends
          this.context.beginPath()
          this.context.arc(200, 200, 50, 3 * Math.PI / 2, 2 * Math.PI, false)
          this.context.strokeStyle = '#ff00ff'
          this.context.lineWidth = 10
          this.context.lineCap = 'round'
          this.context.stroke()
        })
    }
    .width('100%')
    .height('100%')
  }
}

