@Entry
@Component
struct FrameAnimationCombination {
  @State widthSize: number = 200
  @State heightSize: number = 200
  @State rotateAngle: number = 0
  @State frameIndex: number = 0
  @State scaleValue: number = 1.0
  private frames: Array<string> = [
    "app.media.app_icon1",
    "app.media.app_icon2",
    "app.media.app_icon3",
    "app.media.app_icon4"
  ]

  build() {
    Column() {
      Image(this.frames[this.frameIndex])
        .width(this.widthSize)
        .height(this.heightSize)
        .rotate({ angle: this.rotateAngle })
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .animation({
          duration: 1000,
          curve: Curve.EaseInOut,
          iterations: 1,
          playMode: PlayMode.Normal
        })
        .onClick(() => {
          // Frame animation
          this.frameIndex = (this.frameIndex + 1) % this.frames.length

          // Property animations
          animateTo({
            duration: 1000,
            curve: Curve.EaseInOut
          }, () => {
            if (this.scaleValue === 1.0) {
              this.widthSize = 150
              this.heightSize = 150
              this.rotateAngle = 90
              this.scaleValue = 1.5
            } else {
              this.widthSize = 200
              this.heightSize = 200
              this.rotateAngle = 0
              this.scaleValue = 1.0
            }
          })
        })
    }.width('100%').height('100%').padding(20)
  }
}

