@Entry
@Component
struct CustomFrameAnimation {
  @State private currentFrame: number = 0;
  @State private animationSpeed: number = 100; // Speed in milliseconds
  private totalFrames: number = 10; // Total number of frames in the animation
  private intervalID: number = -1;

  aboutToAppear() {
    this.startAnimation();
  }

  aboutToDisappear() {
    this.stopAnimation();
  }

  startAnimation() {
    this.intervalID = setInterval(() => {
      this.currentFrame = (this.currentFrame + 1) % this.totalFrames;
    }, this.animationSpeed) as number;
  }

  stopAnimation() {
    if (this.intervalID !== -1) {
      clearInterval(this.intervalID);
      this.intervalID = -1;
    }
  }

  onSpeedChange(speed: number) {
    this.animationSpeed = speed;
    this.stopAnimation();
    this.startAnimation();
  }

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .objectFit(ImageFit.Contain)
        .clip(new Rect({ width: 100, height: 100 })) // Updated clip usage

      Slider({
        value: this.animationSpeed,
        min: 50,
        max: 500,
        step: 10,
        style: SliderStyle.OutSet
      })
      .onChange((value: number) => {
        this.onSpeedChange(value);
      })
      .margin({ top: 20 })

      Text(`Speed: ${this.animationSpeed}ms`)
        .fontSize(16)
        .margin({ top: 10 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor($r('sys.color.ohos_id_color_background'))
  }
}

