@Component
struct ProductRatingSystem {
  @State currentRating: number = 0
  @State submitted: boolean = false
  @State productName: string = "Premium Widget"
  @State productImage: Resource = $r("app.media.app_icon")

  build() {
    Column() {
      // Product Display
      Image(this.productImage)
        .width(120)
        .height(120)
        .margin({ bottom: 20 })

      Text(this.productName)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 30 })

      // Star Rating Component
      Row() {
        ForEach([1, 2, 3, 4, 5], (index: number) => {
          Image($r('app.media.app_icon'))
            .width(32)
            .height(32)
            .margin({ right: 8 })
            .onClick(() => {
              this.currentRating = index
              this.submitted = false
            })
            .opacity(this.currentRating >= index ? 1 : 0.3)
        })
      }
      .margin({ bottom: 20 })

      // Rating Display
      if (this.currentRating > 0) {
        Text(`Your rating: ${this.currentRating} stars`)
          .fontSize(18)
          .margin({ bottom: 20 })
      }

      // Submit Button
      Button("Submit Rating")
        .onClick(() => {
          if (this.currentRating > 0) {
            this.submitted = true
            console.log(`Rating submitted: ${this.currentRating}`)
          }
        })
        .width(200)
        .height(50)
        .margin({ top: 20 })

      // Confirmation Message
      if (this.submitted) {
        Text("Thank you for your feedback!")
          .fontSize(18)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20)
  }
}

@Entry
@Component
struct ContinuousFrameAnimation {
  @State private currentFrame: number = 0;
  private frames: Resource[] = [
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon')
  ];
  private timerId: number = -1;
  private animationDuration: number = 200; // ms per frame

  aboutToAppear() {
    this.startAnimation();
  }

  aboutToDisappear() {
    if (this.timerId !== -1) {
      clearInterval(this.timerId);
    }
  }

  startAnimation() {
    this.timerId = setInterval(() => {
      this.currentFrame = (this.currentFrame + 1) % this.frames.length;
    }, this.animationDuration);
  }

  build() {
    Column() {
      Image(this.frames[this.currentFrame])
        .width(200)
        .height(200)
        .objectFit(ImageFit.Contain)
        .animation({
          duration: this.animationDuration,
          curve: Curve.Linear,
          iterations: Infinity,
          playMode: PlayMode.Normal
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

@Entry
@Component
struct ComponentDimensionMeasurer {
  @State measuredWidth: number = 0;
  @State measuredHeight: number = 0;
  @State componentClicked: boolean = false;

  build() {
    Column() {
      Text( this.componentClicked ?
        `Component Dimensions: Width - ${this.measuredWidth}, Height - ${this.measuredHeight}` :
        'Click the component to measure dimensions'
      )
      .fontSize(20)
      .margin(10);

      Stack() {
        Image($r('app.media.app_icon'))
          .width(200)
          .height(200)
          .onClick(() => {
            this.componentClicked = true;
            this.onMeasure();
          })
          .onAreaChange((oldValue, newValue) => {
            this.measuredWidth = parseInt(newValue.width.toString(), 10);
            this.measuredHeight = parseInt(newValue.height.toString(), 10);
          })
      }
      .margin(20)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }

  onMeasure() {
    // This triggers the onAreaChange callback
  }
}

