@Entry
@Component
struct StyledStringInsertion {
  @State styledString: string = "Hello, HarmonyOS!";
  @State newString: string = "ArkTS";
  @State insertPosition: number = 7;

  build() {
    Column() {
      Text(this.styledString)
        .fontSize(20)
        .fontColor(Color.Black)
        .fontWeight(FontWeight.Bold)
        .margin(10);

      TextInput({ placeholder: "Enter text to insert" })
        .onChange((value: string) => {
          this.newString = value;
        })
        .margin(10);

      TextInput({ placeholder: "Enter position (0-" + this.styledString.length + ")" })
        .onChange((value: string) => {
          let pos = parseInt(value);
          if (!isNaN(pos) && pos >= 0 && pos <= this.styledString.length) {
            this.insertPosition = pos;
          }
        })
        .margin(10);

      Button("Insert Text")
        .onClick(() => {
          this.styledString = this.insertString(this.styledString, this.newString, this.insertPosition);
        })
        .margin(10);

      Text("Result: " + this.styledString)
        .fontSize(20)
        .fontColor(Color.Blue)
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White);
  }

  insertString(original: string, newString: string, position: number): string {
    return original.slice(0, position) + newString + original.slice(position);
  }
}

