@Entry
@Component
struct PieChartAngleCalculator {
  @State centerX: number = 200
  @State centerY: number = 200
  @State touchX: number = 0
  @State touchY: number = 0
  @State angle: number = 0
  @State distance: number = 0

  build() {
    Column() {
      // Pie chart visualization
      Stack() {
        // Pie chart base
        Circle()
          .width(300)
          .height(300)
          .fill(Color.White)
          .stroke(Color.Black)
          .strokeWidth(2)

        // Center point indicator
        Circle()
          .width(10)
          .height(10)
          .fill(Color.Red)
          .position({ x: this.centerX - 5, y: this.centerY - 5 })

        // Conditional rendering for touch point indicator
        if (this.touchX > 0 && this.touchY > 0) {
          Circle()
            .width(10)
            .height(10)
            .fill(Color.Blue)
            .position({ x: this.touchX - 5, y: this.touchY - 5 })
        }

        // Conditional rendering for connecting line
        if (this.touchX > 0 && this.touchY > 0) {
          Line()
            .width(2)
            .height(this.distance)
            .startPoint([this.centerX, this.centerY])
            .endPoint([this.touchX, this.touchY])
        }
      }
      .width(400)
      .height(400)
      .onTouch((event: TouchEvent) => {
        if (event.type === TouchType.Down || event.type === TouchType.Move) {
          this.touchX = event.touches[0].x
          this.touchY = event.touches[0].y
          this.calculateAngleAndDistance()
        }
      })

      // Results display
      Text(`Touch Point: (${this.touchX.toFixed(1)}, ${this.touchY.toFixed(1)})`)
        .fontSize(18)
        .margin(10)

      Text(`Angle from center: ${this.angle.toFixed(1)}°`)
        .fontSize(18)
        .margin(10)

      Text(`Distance from center: ${this.distance.toFixed(1)}px`)
        .fontSize(18)
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }

  calculateAngleAndDistance() {
    // Calculate the difference between touch point and center
    const dx = this.touchX - this.centerX
    const dy = this.touchY - this.centerY

    // Calculate distance using Pythagorean theorem
    this.distance = Math.sqrt(dx * dx + dy * dy)

    // Calculate angle in radians then convert to degrees
    let angleRad = Math.atan2(dy, dx)
    this.angle = (angleRad * 180 / Math.PI + 360) % 360
  }
}

@Entry
@Component
struct FrameAnimationConfiguration {
  @State private currentFrame: number = 0;
  private frameImages: Resource[] = [
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon')
  ];
  private timerId: number = -1;
  private animationDuration: number = 100; // ms per frame

  aboutToAppear() {
    this.startAnimation();
  }

  aboutToDisappear() {
    if (this.timerId !== -1) {
      clearInterval(this.timerId);
    }
  }

  startAnimation() {
    this.timerId = setInterval(() => {
      this.currentFrame = (this.currentFrame + 1) % this.frameImages.length;
    }, this.animationDuration);
  }

  stopAnimation() {
    if (this.timerId !== -1) {
      clearInterval(this.timerId);
      this.timerId = -1;
    }
  }

  build() {
    Column() {
      Image(this.frameImages[this.currentFrame])
        .width(200)
        .height(200)
        .objectFit(ImageFit.Contain)
        .margin(20)
        .animation({
          duration: this.animationDuration,
          curve: Curve.Linear
        })

      Button('Start Animation')
        .onClick(() => {
          if (this.timerId === -1) {
            this.startAnimation();
          }
        })
        .margin(10)

      Button('Stop Animation')
        .onClick(() => {
          this.stopAnimation();
        })
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

@Entry
@Component
struct FormValidation {
  @State name: string = ''
  @State email: string = ''
  @State password: string = ''
  @State successMessage: string = ''
  @State errorMessage: string = ''

  validateName(): boolean {
    if (!this.name) {
      this.errorMessage = 'Name is required'
      return false
    }
    return true
  }

  validateEmail(): boolean {
    if (!this.email) {
      this.errorMessage = 'Email is required'
      return false
    }
    if (!this.email.includes('@')) {
      this.errorMessage = 'Invalid email format'
      return false
    }
    return true
  }

  validatePassword(): boolean {
    if (!this.password) {
      this.errorMessage = 'Password is required'
      return false
    }
    if (this.password.length < 6) {
      this.errorMessage = 'Password must be at least 6 characters'
      return false
    }
    return true
  }

  validateForm(): boolean {
    this.errorMessage = ''
    if (!this.validateName() || !this.validateEmail() || !this.validatePassword()) {
      return false
    }
    this.successMessage = 'Form submitted successfully!'
    return true
  }

  build() {
    Column() {
      Text('User Registration')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Full Name' })
        .onChange((value: string) => {
          this.name = value
        })
        .margin({ bottom: 10 })

      Button('Validate Name')
        .onClick(() => {
          this.validateName()
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Email Address' })
        .onChange((value: string) => {
          this.email = value
        })
        .margin({ bottom: 10 })

      Button('Validate Email')
        .onClick(() => {
          this.validateEmail()
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .margin({ bottom: 10 })

      Button('Validate Password')
        .onClick(() => {
          this.validatePassword()
        })
        .margin({ bottom: 20 })

      Button('Submit Form')
        .onClick(() => {
          this.validateForm()
        })
        .margin({ bottom: 20 })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 10 })
      }

      if (this.successMessage) {
