    Column() {
      Slider({
        value: this.iterationCount,
        min: 1,
        max: 10,
        step: 1
      })
      .width('80%')
      .margin(20)
      .onChange((value: number) => {
        this.iterationCount = value
      })

      Text(`Iterations: ${this.iterationCount}`)
        .fontSize(16)
        .margin({ bottom: 20 })

