@Entry
@Component
struct OfflineFallbackApp {
  @State isOnline: boolean = true;
  @State onlineContent: string = "Loading online content...";
  @State offlineContent: string = "Showing offline fallback content";

  build() {
    Column() {
      if (this.isOnline) {
        // Online UI
        Text(this.onlineContent)
          .fontSize(20)
          .margin({ bottom: 10 });

        Image("https://example.com/online_image.jpg")
          .width(200)
          .height(200)
          .margin({ bottom: 20 });

        Button("Refresh Content")
          .onClick(() => {
            this.checkConnectivity();
          });
      } else {
        // Offline Fallback UI
        Text(this.offlineContent)
          .fontSize(18)
          .margin({ bottom: 10 });

        Image($r('app.media.app_icon'))
          .width(200)
          .height(200)
          .margin({ bottom: 20 });

        Button("Retry Connection")
          .onClick(() => {
            this.checkConnectivity();
          });
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .onAppear(() => {
      this.checkConnectivity();
    });
  }

  checkConnectivity() {
    // Simulate connectivity check
    setTimeout(() => {
      this.isOnline = Math.random() > 0.5; // Randomly set online/offline for demo
      if (this.isOnline) {
        this.onlineContent = "Online content loaded successfully";
      } else {
        this.offlineContent = "You're offline. Showing cached content.";
      }
    }, 1000);
  }
}

