@Entry
@Component
struct ImageCarousel {
  private swiperController: SwiperController = new SwiperController();

  private carouselItems: Array<CarouselItem> = [
    { id: 1, image: $r('app.media.app_icon'), caption: 'Mountain View' },
    { id: 2, image: $r('app.media.app_icon'), caption: 'Ocean Sunset' },
    { id: 3, image: $r('app.media.app_icon'), caption: 'Forest Path' },
    { id: 4, image: $r('app.media.app_icon'), caption: 'Desert Dunes' }
  ];

  @State currentIndex: number = 0;
  @State isImageEnlarged: boolean = false;

  build() {
    Column() {
      Text('Image Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Column() {
        Swiper(this.swiperController) {
          ForEach(this.carouselItems, (item: CarouselItem) => {
            Stack() {
              Image(item.image)
                .width('100%')
                .height(300)
                .objectFit(ImageFit.Cover)
                .borderRadius(16)
                .onClick(() => {
                  this.isImageEnlarged = true;
                });
            }
          });
        }
        .width('100%')
        .height(300)
        .margin({ bottom: 16 })
        .autoPlay(true)
        .interval(3000)
        .indicator(true)
        .loop(true)
        .duration(500)
        .onChange((index: number) => {
          this.currentIndex = index;
        });

        Text(this.carouselItems[this.currentIndex].caption)
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 8 })
          .textAlign(TextAlign.Center);
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(20);

      Row() {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });

        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });

      if (this.isImageEnlarged) {
        Column() {
          Image(this.carouselItems[this.currentIndex].image)
            .width('100%')
            .height('100%')
            .objectFit(ImageFit.Cover)
            .onClick(() => {
              this.isImageEnlarged = false;
            });

          Text(this.carouselItems[this.currentIndex].caption)
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ top: 16 })
            .textAlign(TextAlign.Center);
        }
        .width('100%')
        .height('100%')
        .backgroundColor(Color.Black)
        .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

interface CarouselItem {
  id: number;
  image: Resource;
  caption: string;
}

import promptAction from '@ohos.promptAction';

@Entry
@Component
struct FormInterface {
  @State name: string = '';
  @State email: string = '';
  @State phoneNumber: string = '';
  @State showSuccessMessage: boolean = false;
  @State errorMessage: string = '';

  validateForm(): boolean {
    if (!this.name.trim()) {
      this.errorMessage = 'Name is required';
      return false;
    }
    if (!this.email.trim() || !this.email.includes('@')) {
      this.errorMessage = 'Valid email is required';
      return false;
    }
    if (!this.phoneNumber.trim() || !/^\d+$/.test(this.phoneNumber)) {
      this.errorMessage = 'Valid phone number is required';
      return false;
    }
    this.errorMessage = '';
    return true;
  }

  build() {
    Column() {
      Text('Contact Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 30 });

      // Name Field
      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 });
        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .onChange((value: string) => {
            this.name = value;
          });
      }

      // Email Field
      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 });
        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .onChange((value: string) => {
            this.email = value;
          });
      }

      // Phone Field
      Column() {
        Text('Phone Number:')
          .fontSize(16)
          .margin({ bottom: 8 });
        TextInput({ placeholder: 'Enter your phone number' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .onChange((value: string) => {
            this.phoneNumber = value;
          });
      }

      // Error Message
      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ bottom: 10 });
      }

      // Submit Button
      Button('Submit', { type: ButtonType.Normal })
        .width('100%')
        .height(50)
        .margin({ bottom: 20 })
        .onClick(() => {
          if (this.validateForm()) {
            this.showSuccessMessage = true;
          }
        });

      // Success Message
      if (this.showSuccessMessage) {
        Column() {
          Text('Form Submitted Successfully!')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });
          Text(`Name: ${this.name}`)
            .fontSize(16)
            .margin({ bottom: 8 });
          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 8 });
          Text(`Phone: ${this.phoneNumber}`)
            .fontSize(16)
            .margin({ bottom: 20 });
          Button('Close')
            .onClick(() => {
              this.showSuccessMessage = false;
              this.name = '';
              this.email = '';
              this.phoneNumber = '';
            });
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

