          this.showCustomView = !this.showCustomView;
          this.buttonLabel = this.showCustomView ?
            'Switch to Default View' : 'Switch to Custom View';
        })
        .width(200)
        .height(40);
    }
    .width('90%')
    .padding(20)
    .border({ width: 1, color: Color.Gray })
    .borderRadius(10)
  }

  build() {
    Column() {
      if (this.showCustomView) {
        this.EnhancedViewBuilder();
      } else {
        this.MinimalistViewBuilder();
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

