              .borderRadius(8)
              .margin({ bottom: 5 });
            });
          }
          .width('100%')
          .height(200);
        }
        .width('90%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 10, color: '#00000020', offsetX: 0, offsetY: 5 });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#F5F5F5');
  }
