@Entry
@Component
struct RatingApp {
  private itemList: Array<Item> = [
    new Item('Item 1', 0, 0),
    new Item('Item 2', 0, 0),
    new Item('Item 3', 0, 0)
  ];

  @State items: Array<Item> = this.itemList;

  private rateItem(index: number, rating: number): void {
    if (rating < 1 || rating > 5) {
      console.error('Invalid rating. Must be between 1 and 5.');
      return;
    }

    let item = this.items[index];
    let totalRating = item.rating * item.totalRatings + rating;
    item.totalRatings += 1;
    item.rating = totalRating / item.totalRatings;

    this.items[index] = item;
  }

  build() {
    Column({ space: 20 }) {
      Text('Rate the Items')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      ForEach(this.items, (item: Item, index: number) => {
        Column({ space: 10 }) {
          Text(item.name)
            .fontSize(18)
            .fontWeight(FontWeight.Medium);

          Text(`Average Rating: ${item.rating.toFixed(1)}`)
            .fontSize(16)
            .fontColor(Color.Gray);

          Row({ space: 5 }) {
            ForEach([1, 2, 3, 4, 5], (starIndex: number) => {
              Image($r('app.media.app_icon'))
                .width(24)
                .height(24)
                .margin({ right: 5 })
                .onClick(() => {
                  this.rateItem(index, starIndex);
                });
            });
          }
        }
        .padding(10)
        .backgroundColor('#f0f0f0')
        .borderRadius(10)
        .margin({ bottom: 10 });
      });
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

class Item {
  name: string;
  rating: number;
  totalRatings: number;

  constructor(name: string, rating: number, totalRatings: number) {
    this.name = name;
    this.rating = rating;
    this.totalRatings = totalRatings;
  }
}

@Entry
@Component
struct DevLoggerApp {
  @State logs: Array<string> = [];
  @State inputMessage: string = '';
  @State isSubscribed: boolean = false;

  private logger: Logger = new Logger();
  private listener: EventListener = new EventListener();

  onLayoutComplete() {
    this.logger.log('Layout Complete Event Triggered');
    this.logs = this.logger.getLogs();
  }

  onWillDraw() {
    this.logger.log('Will Draw Event Triggered');
    this.logs = this.logger.getLogs();
  }

  subscribeToEvents() {
    this.listener.on('layout', this.onLayoutComplete.bind(this));
    this.listener.on('draw', this.onWillDraw.bind(this));
    this.isSubscribed = true;
    this.logger.log('Subscribed to Events');
    this.logs = this.logger.getLogs();
  }

  unsubscribeFromEvents() {
    this.listener.off('layout', this.onLayoutComplete.bind(this));
    this.listener.off('draw', this.onWillDraw.bind(this));
    this.isSubscribed = false;
    this.logger.log('Unsubscribed from Events');
    this.logs = this.logger.getLogs();
  }

  build() {
    Column() {
      Text('Development Logger')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin(20);

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .id('UI_ELEMENT')
        .border({ width: 1, color: Color.Black });

      TextInput({ placeholder: 'Enter log message' })
        .onChange((value: string) => {
          this.inputMessage = value;
        })
        .margin(10);

      Button('Log Message')
        .onClick(() => {
          if (this.inputMessage.trim() !== '') {
            this.logger.log(this.inputMessage);
            this.logs = this.logger.getLogs();
            this.inputMessage = '';
          }
        })
        .margin(10);

      Button(this.isSubscribed ? 'Unsubscribe' : 'Subscribe')
        .onClick(() => {
          if (this.isSubscribed) {
            this.unsubscribeFromEvents();
          } else {
            this.subscribeToEvents();
          }
        })
        .margin(10);

      List() {
        ForEach(this.logs, (log: string) => {
          ListItem() {
            Text(log)
              .fontSize(14)
              .margin(5);
          }
        });
      }
      .layoutWeight(1)
      .margin(10);
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

class Logger {
  private logs: Array<string> = [];

  log(message: string): void {
    this.logs.push(message);
  }

  getLogs(): Array<string> {
    return [...this.logs];
  }
}

class EventListener {
  private events: Record<string, Array<() => void>> = {};

  on(event: string, callback: () => void): void {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(callback);
  }

  off(event: string, callback: () => void): void {
    if (this.events[event]) {
      this.events[event] = this.events[event].filter(cb => cb !== callback);
    }
  }

  emit(event: string): void {
    if (this.events[event]) {
      this.events[event].forEach(callback => callback());
    }
  }
}

