@Entry
@Component
struct CustomSpanMeasurement {
  @State private textWidth: number = 0;
  @State private textHeight: number = 0;
  private context: CanvasRenderingContext2D | null = null;

  build() {
    Column({ space: 10 }) {
      // Canvas for CustomSpan text measurement
      Canvas()
        .width(300)
        .height(100)
        .backgroundColor('#f0f0f0')
        .onReady(() => {
          if (this.context) {
            this.context.font = '20px Arial';
            const text = 'Custom Span Text';
            const metrics = this.context.measureText(text);
            this.textWidth = metrics.width;
            this.textHeight = parseInt(this.context.font);
            this.context.fillText(text, 10, 50);
          }
        })

      // Display measurement results
      Text(`CustomSpan Width: ${this.textWidth.toFixed(2)}px`)
        .fontSize(16)
        .margin(10)

      Text(`CustomSpan Height: ${this.textHeight}px`)
        .fontSize(16)
        .margin(10)

      // Example with CustomSpan and ImageSpan
      Flex({ direction: FlexDirection.Row, alignItems: ItemAlign.Center }) {
        Text() {
          Span('CustomSpan with ')
          ImageSpan($r('app.media.app_icon'))
            .width(30)
            .height(30)
            .verticalAlign(ImageSpanAlignment.CENTER)
          Span(' measurement')
        }
        .fontSize(18)
        .onAreaChange((oldValue, newValue) => {
          console.log(`CustomSpan area width: ${newValue.width}, height: ${newValue.height}`);
        })
      }
      .margin(20)
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
  }
}

@Entry
@Component
struct MovementMonitor {
  @State initialX: number = 0;
  @State initialY: number = 0;
  @State currentX: number = 0;
  @State currentY: number = 0;
  @State isTracking: boolean = false;

  build() {
    Column() {
      Text(`Initial Click: X=${this.initialX}, Y=${this.initialY}`)
        .fontSize(16)
        .margin(10);

      Text(`Current Position: X=${this.currentX}, Y=${this.currentY}`)
        .fontSize(16)
        .margin(10);

      Text(`Movement: X=${this.currentX - this.initialX}, Y=${this.currentY - this.initialY}`)
        .fontSize(18)
        .margin(20);

      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .gesture(
          TapGesture({ count: 1 })
            .onAction((event: GestureEvent) => {
              this.initialX = event.fingerList[0].localX;
              this.initialY = event.fingerList[0].localY;
              this.currentX = this.initialX;
              this.currentY = this.initialY;
              this.isTracking = true;
            })
        )
        .gesture(
          PanGesture()
            .onActionUpdate((event: GestureEvent) => {
              if (this.isTracking) {
                this.currentX = event.fingerList[0].localX;
                this.currentY = event.fingerList[0].localY;
              }
            })
            .onActionEnd(() => {
              this.isTracking = false;
            })
        )
        .margin(20);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

