@Component
struct AnimatorOptionsExample {
  @State startFrame: number = 0;
  @State endFrame: number = 100;
  @State duration: number = 1000;
  @State isAnimating: boolean = false;

  build() {
    Column({ space: 10 }) {
      Text(`Start Frame: ${this.startFrame}`)
        .fontSize(16)
      Slider({
        value: this.startFrame,
        min: 0,
        max: this.endFrame,
        step: 1,
        style: SliderStyle.OutSet
      })
      .onChange((value: number) => {
        this.startFrame = value;
      })
      .margin({ top: 20 })

      Text(`End Frame: ${this.endFrame}`)
        .fontSize(16)
      Slider({
        value: this.endFrame,
        min: this.startFrame,
        max: 200,
        step: 1,
        style: SliderStyle.OutSet
      })
      .onChange((value: number) => {
        this.endFrame = value;
      })
      .margin({ top: 20 })

      Text(`Duration: ${this.duration}ms`)
        .fontSize(16)
      Slider({
        value: this.duration,
        min: 500,
        max: 5000,
        step: 100,
        style: SliderStyle.OutSet
      })
      .onChange((value: number) => {
        this.duration = value;
      })
      .margin({ top: 20 })

      Button(this.isAnimating ? 'Stop Animation' : 'Start Animation')
        .onClick(() => {
          this.isAnimating = !this.isAnimating;
        })
        .margin({ top: 20 })

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 20 })
        .animation({
          duration: this.duration,
          curve: Curve.EaseInOut,
          iterations: this.isAnimating ? Infinity : 1,
          playMode: PlayMode.Normal
        })
        .rotate({ x: 0, y: 0, z: 1, angle: this.isAnimating ? 360 : 0 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

