@Entry
@Component
struct AnimationRepeatCallbackExample {
  @State repeatCount: number = 0;
  @State isPlaying: boolean = false;

  build() {
    Column() {
      ImageAnimator()
        .images([
          {
            src: $r('app.media.app_icon'),
            duration: 500
          },
          {
            src: $r('app.media.app_icon'),
            duration: 500
          }
        ])
        .state(this.isPlaying ? AnimationStatus.Running : AnimationStatus.Stopped)
        .onStart(() => {
          console.log('Animation started');
          this.isPlaying = true;
        })
        .onRepeat(() => {
          this.repeatCount++;
          console.log(`Animation repeated ${this.repeatCount} times`);
        })
        .onFinish(() => {
          console.log('Animation finished');
          this.isPlaying = false;
        })
        .width(200)
        .height(200)

      Text(`Repeat Count: ${this.repeatCount}`)
        .fontSize(20)
        .margin({top: 20})

      Button(this.isPlaying ? 'Stop Animation' : 'Start Animation')
        .onClick(() => {
          this.isPlaying = !this.isPlaying;
          if (!this.isPlaying) {
            this.repeatCount = 0;
          }
        })
        .margin({top: 20})
        .width(200)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

