@Entry
@Component
struct TemplateBasedItems {
  @State private templates: string[] = ["Default Template 1", "Default Template 2", "Default Template 3"];
  @State private newTemplateName: string = "";
  @State private selectedTemplate: string = "";

  private handleAddTemplate(): void {
    if (this.newTemplateName.trim() !== "") {
      this.templates.push(this.newTemplateName);
      this.newTemplateName = "";
    }
  }

  private handleRemoveTemplate(index: number): void {
    this.templates.splice(index, 1);
    if (this.selectedTemplate === this.templates[index]) {
      this.selectedTemplate = "";
    }
  }

  private handleSelectTemplate(template: string): void {
    this.selectedTemplate = template;
  }

  build() {
    Column({ space: 10 }) {
      Text("Template Management")
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      TextInput({ placeholder: "Enter new template name" })
        .onChange((value: string) => {
          this.newTemplateName = value;
        })
        .margin({ bottom: 10 });

      Button("Add Template")
        .onClick(() => {
          this.handleAddTemplate();
        })
        .margin({ bottom: 20 });

      List({ space: 10 }) {
        ForEach(this.templates, (template: string, index: number) => {
          ListItem() {
            Row({ space: 10 }) {
              Text(template)
                .fontSize(18)
                .onClick(() => {
                  this.handleSelectTemplate(template);
                });
              Button("Remove")
                .onClick(() => {
                  this.handleRemoveTemplate(index);
                });
            }
            .padding(10)
            .backgroundColor(this.selectedTemplate === template ? "#007DFF" : "#F5F5F5")
            .borderRadius(5)
            .margin({ bottom: 10 });
          }
        });
      }
      .width("100%")
      .height("60%");

      Text(`Selected Template: ${this.selectedTemplate}`)
        .fontSize(18)
        .margin({ top: 20 });
    }
    .padding(20)
    .width("100%")
    .height("100%")
    .backgroundColor("#f0f0f0");
  }
}

