@Entry
@Component
struct AnimatorDelayExample {
  @State widthSize: number = 200;
  @State heightSize: number = 100;
  @State rotateAngle: number = 0;
  @State isAnimating: boolean = false;

  build() {
    Column() {
      Button('Change Size with Delay')
        .onClick(() => {
          this.widthSize = this.widthSize === 200 ? 300 : 200;
          this.heightSize = this.heightSize === 100 ? 150 : 100;
        })
        .margin(30)
        .width(this.widthSize)
        .height(this.heightSize)
        .animation({
          duration: 1500,
          curve: Curve.EaseInOut,
          delay: 1000, // 1 second delay
          iterations: 1,
          playMode: PlayMode.Normal
        })

      Button('Rotate with Delay')
        .onClick(() => {
          this.rotateAngle = this.rotateAngle === 0 ? 180 : 0;
        })
        .margin(30)
        .rotate({ angle: this.rotateAngle })
        .animation({
          duration: 1000,
          curve: Curve.Ease,
          delay: 500, // 0.5 second delay
          iterations: 1,
          playMode: PlayMode.Normal
        })

      Button(this.isAnimating ? 'Stop Animation' : 'Start Animation')
        .onClick(() => {
          this.isAnimating = !this.isAnimating;
        })
        .margin(30)

      if (this.isAnimating) {
        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
          .animation({
            duration: 2000,
            curve: Curve.Linear,
            delay: 2000, // 2 second delay
            iterations: Infinity,
            playMode: PlayMode.Alternate
          })
          .opacity(this.isAnimating ? 0.5 : 1)
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

