@Entry
@Component
struct AnimationRepeatHandlerExample {
  @State private isAnimating: boolean = false
  @State private iterationCount: number = 3
  @State private rotationAngle: number = 0

  private handleAnimationEnd() {
    if (this.isAnimating) {
      this.rotationAngle = (this.rotationAngle + 360) % 720
    }
  }

  build() {
    Column() {
      Slider({
        value: this.iterationCount,
        min: 1,
        max: 10,
        step: 1
      })
      .width('80%')
      .margin(20)
      .onChange((value: number) => {
        this.iterationCount = value
      })

      Text(`Iterations: ${this.iterationCount}`)
        .fontSize(16)
        .margin({ bottom: 20 })

      Button(this.isAnimating ? 'Stop Animation' : 'Start Animation')
        .onClick(() => {
          this.isAnimating = !this.isAnimating
          if (!this.isAnimating) {
            this.rotationAngle = 0
          }
        })
        .margin(10)

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .animation({
          duration: 1000,
          curve: Curve.EaseInOut,
          iterations: this.isAnimating ? this.iterationCount : 0,
          playMode: PlayMode.Normal,
          onFinish: () => {
            this.handleAnimationEnd()
          }
        })
        .rotate({
          x: 0,
          y: 0,
          z: 1,
          angle: this.rotationAngle
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor($r('sys.color.ohos_id_color_background'))
  }
}

