@Entry
@Component
struct ScrollConflictSolution {
  @State private data: string[] = ['Item A', 'Item B', 'Item C', 'Item D', 'Item E'];
  @State private isRefreshing: boolean = false;
  @State private allowOuterScroll: boolean = true;
  private refreshThreshold: number = 100;
  private outerScroller: Scroller = new Scroller();
  private listScroller: Scroller = new Scroller();

  private handleOuterScroll(offset: number) {
    if (offset < -this.refreshThreshold && !this.isRefreshing && this.allowOuterScroll) {
      this.isRefreshing = true;
      this.refreshData();
    }
  }

  private handleListScroll(offset: number) {
    this.allowOuterScroll = (offset <= 0);
  }

  private refreshData() {
    setTimeout(() => {
      this.data = ['New Item ' + (this.data.length + 1), ...this.data];
      this.isRefreshing = false;
      this.listScroller.scrollTo({ xOffset: 0, yOffset: 0 });
    }, 1500);
  }

  build() {
    Column() {
      if (this.isRefreshing) {
        Column() {
          Progress({ value: 50, type: ProgressType.Ring })
            .width(40)
            .height(40)
          Text('Refreshing...')
            .margin({ top: 8 })
        }
        .width('100%')
        .height(100)
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center)
      }

      Scroll(this.outerScroller) {
        Column() {
          List({ space: 10, scroller: this.listScroller }) {
            ForEach(this.data, (item: string) => {
              ListItem() {
                Text(item)
                  .fontSize(18)
                  .padding(15)
                  .width('100%')
                  .backgroundColor('#f5f5f5')
                  .borderRadius(8)
              }
            }, (item: string) => item)
          }
          .width('100%')
          .height('100%')
          .onScrollIndex((start: number, end: number) => {
            this.handleListScroll(this.listScroller.currentOffset().yOffset);
          })
        }
      }
      .width('100%')
      .height('100%')
      .onScroll(() => {
        this.handleOuterScroll(this.outerScroller.currentOffset().yOffset);
      })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff')
  }
}

