@Entry
@Component
struct ContentCacheApplication {
  @State cachedData: string[] = ['Initial Cache Item 1', 'Initial Cache Item 2', 'Initial Cache Item 3'];
  @State newItem: string = '';
  @State showCache: boolean = true;
  @State refreshing: boolean = false;

  build() {
    Column({ space: 20 }) {
      // Toggle to show/hide cached content
      Button(this.showCache ? 'Hide Cache' : 'Show Cache')
        .onClick(() => {
          this.showCache = !this.showCache;
        })
        .width('80%')
        .height(40)
        .margin(10);

      // Display cached content when visible
      if (this.showCache) {
        Refresh({
          refreshing: this.refreshing,
          offset: 120,
          friction: 100
        }) {
          List({ space: 10 }) {
            ForEach(this.cachedData, (item: string) => {
              ListItem() {
                Text(item)
                  .fontSize(18)
                  .padding(10)
              }
            })
          }
          .height('50%')
          .width('100%')
          .divider({ strokeWidth: 1, color: 0xcccccc })
        }
        .onRefreshing(() => {
          // Simulated data refresh
          setTimeout(() => {
            this.cachedData = ['Refreshed Item 1', 'Refreshed Item 2', 'Refreshed Item 3'];
            this.refreshing = false;
          }, 2000);
        })
      }

      // Input for new cache items
      TextInput({ placeholder: 'Enter new cache item' })
        .onChange((value: string) => {
          this.newItem = value;
        })
        .width('80%')
        .margin(10);

      // Button to add new item to cache
      Button('Add to Cache')
        .onClick(() => {
          if (this.newItem.trim()) {
            this.cachedData.push(this.newItem);
            this.newItem = '';
          }
        })
        .width('80%')
        .height(40)
        .margin(10);

      // Button to clear cache
      Button('Clear Cache')
        .onClick(() => {
          this.cachedData = [];
        })
        .width('80%')
        .height(40)
        .margin(10)
        .backgroundColor(Color.Red)
        .fontColor(Color.White);
    }
    .width('100%')
    .height('100%')
    .padding(10)
  }
}

