import { UIContext } from '@kit.ArkUI';

@Entry
@Component
struct FrameAnimationDemo {
  @State myScale: number = 1.0;
  @State rotationAngle: number = 0;
  @State opacityValue: number = 1;
  uiContext: UIContext | undefined = undefined;

  aboutToAppear() {
    this.uiContext = this.getUIContext?.();
  }

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(100)
        .scale({ x: this.myScale, y: this.myScale })
        .rotate({ x: 0, y: 0, z: 1, angle: this.rotationAngle })
        .opacity(this.opacityValue)
        .onClick(() => {
          if (!this.uiContext) {
            console.info("no uiContext, keyframe animation failed");
            return;
          }
          this.myScale = 1;
          this.rotationAngle = 0;
          this.opacityValue = 1;

          this.uiContext.keyframeAnimateTo({ iterations: 3 }, [
            {
              duration: 800,
              event: () => {
                this.myScale = 1.5;
                this.rotationAngle = 45;
                this.opacityValue = 0.8;
              }
            },
            {
              duration: 500,
              event: () => {
                this.myScale = 0.8;
                this.rotationAngle = 90;
                this.opacityValue = 0.6;
              }
            },
            {
              duration: 500,
              event: () => {
                this.myScale = 1.2;
                this.rotationAngle = 135;
                this.opacityValue = 0.9;
              }
            },
            {
              duration: 500,
              event: () => {
                this.myScale = 1;
                this.rotationAngle = 0;
                this.opacityValue = 1;
              }
            }
          ]);
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

