@Entry
@Component
struct SquareCalculator {
  @State inputNumber: string = ''
  @State result: string = ''
  @State errorMessage: string = ''

  build() {
    Column() {
      Text('Square Calculator')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter a number', text: this.inputNumber })
        .type(InputType.Number)
        .onChange((value: string) => {
          this.inputNumber = value
          this.errorMessage = ''
        })
        .width('80%')
        .margin({ bottom: 20 })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ bottom: 10 })
      }

      Button('Calculate Square')
        .onClick(() => {
          if (this.inputNumber === '') {
            this.errorMessage = 'Please enter a number'
          } else {
            const num = parseFloat(this.inputNumber)
            if (isNaN(num)) {
              this.errorMessage = 'Invalid input. Please enter a valid number.'
            } else {
              this.result = `Square of ${num} is ${num * num}`
              this.errorMessage = ''
            }
          }
        })
        .width('80%')
        .margin({ bottom: 20 })

      if (this.result) {
        Text(this.result)
          .fontSize(16)
          .fontColor(Color.Black)
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
  }
}

