@Entry
@Component
struct ImageGridView {
  @State selectedImage: Resource = $r('app.media.app_icon')
  @State showDetailView: boolean = false
  @State imageTitle: string = ''
  @State imageDescription: string = ''

  private images: Array<ImageItem> = [
    { image: $r('app.media.app_icon'), title: 'Image 1', description: 'Description for Image 1' },
    { image: $r('app.media.app_icon'), title: 'Image 2', description: 'Description for Image 2' },
    { image: $r('app.media.app_icon'), title: 'Image 3', description: 'Description for Image 3' },
    { image: $r('app.media.app_icon'), title: 'Image 4', description: 'Description for Image 4' },
    { image: $r('app.media.app_icon'), title: 'Image 5', description: 'Description for Image 5' },
    { image: $r('app.media.app_icon'), title: 'Image 6', description: 'Description for Image 6' }
  ]

  build() {
    Column() {
      if (this.showDetailView) {
        Stack() {
          Column() {
            Image(this.selectedImage)
              .objectFit(ImageFit.Contain)
              .width('100%')
              .height('60%')
              .margin({ top: 20 })

            Text(this.imageTitle)
              .fontSize(24)
              .fontWeight(FontWeight.Bold)
              .margin({ top: 16 })

            Text(this.imageDescription)
              .fontSize(16)
              .margin({ top: 8 })

            Button('Back')
              .onClick(() => {
                this.showDetailView = false
              })
              .margin({ top: 20 })
              .width('50%')
              .height(40)
              .backgroundColor('#007AFF')
              .fontColor(Color.White)
              .borderRadius(8)
          }
          .width('100%')
          .height('100%')
          .backgroundColor('#F5F5F5')
        }
      } else {
        Grid() {
          ForEach(this.images, (item: ImageItem) => {
            GridItem() {
              Column() {
                Image(item.image)
                  .width('100%')
                  .aspectRatio(1)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(8)
                  .onClick(() => {
                    this.selectedImage = item.image
                    this.imageTitle = item.title
                    this.imageDescription = item.description
                    this.showDetailView = true
                  })

                Text(item.title)
                  .fontSize(16)
                  .fontWeight(FontWeight.Medium)
                  .margin({ top: 8 })
              }
              .backgroundColor(Color.White)
              .borderRadius(12)
              .padding(8)
            }
          })
        }
        .columnsTemplate('1fr 1fr')
        .rowsGap(16)
        .columnsGap(16)
        .padding(16)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

interface ImageItem {
  image: Resource
  title: string
  description: string
}

@Entry
@Component
struct AnimationManager {
  @State private animatorStatus: string = 'Idle';
  @State private scaleValue: number = 1.0;

  build() {
    Column({ space: 10 }) {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .animation({
          duration: 1000,
          curve: Curve.EaseInOut,
          playMode: PlayMode.Normal,
          iterations: -1
        })

      Text(`Animation Status: ${this.animatorStatus}`)
        .fontSize(20)
        .margin(10)

      Button('Start Animation')
        .onClick(() => {
          this.animatorStatus = 'Running';
          this.scaleValue = 1.5;
        })
        .width(200)
        .margin(10)

      Button('Pause Animation')
        .onClick(() => {
          this.animatorStatus = 'Paused';
        })
        .width(200)
        .margin(10)

      Button('Stop Animation')
        .onClick(() => {
          this.animatorStatus = 'Stopped';
          this.scaleValue = 1.0;
        })
        .width(200)
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

