@Entry
@Component
struct RefreshList {
  @State refreshing: boolean = false
  @State listData: string[] = ['Item 1', 'Item 2', 'Item 3']
  @State headerText: string = 'Pull to Refresh'

  // Custom item layout builder
  @Builder
  CustomItemLayout(item: string) {
    Row() {
      Image($r('app.media.app_icon'))
        .width(40)
        .height(40)
        .margin(10)
      Column() {
        Text(item)
          .fontSize(18)
          .fontColor('#333333')
        Text('Details for ' + item)
          .fontSize(12)
          .fontColor('#666666')
      }
      .margin({left: 10})
    }
    .width('100%')
    .padding(10)
    .backgroundColor('#ffffff')
    .borderRadius(8)
    .margin({top: 5, bottom: 5})
  }

  // Refresh callback handler
  private handleRefresh() {
    this.headerText = 'Refreshing...'
    setTimeout(() => {
      this.listData = ['Updated Item 1', 'Updated Item 2', 'Updated Item 3', 'New Item 4']
      this.refreshing = false
      this.headerText = 'Pull to Refresh'
    }, 2000)
  }

  build() {
    Column() {
      // Header section
      Text(this.headerText)
        .fontSize(18)
        .fontColor('#000000')
        .padding(16)
        .backgroundColor('#f0f0f0')
        .width('100%')
        .textAlign(TextAlign.Center)

      // Refreshable list with custom items
      Refresh({
        refreshing: this.refreshing,
        offset: 120,
        friction: 100
      }) {
        List() {
          ForEach(this.listData, (item: string) => {
            ListItem() {
              this.CustomItemLayout(item)
            }
          }, (item: string) => item)
        }
        .width('100%')
      }
      .onRefreshing(() => this.handleRefresh())
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }
}

@Entry
@Component
struct EnvironmentManager {
  @State currentEnv: string = 'development'
  @State envVariables: Map<string, string> = new Map([
    ['API_URL', 'https://dev.api.example.com'],
    ['DEBUG_MODE', 'true'],
    ['LOG_LEVEL', 'debug']
  ])
  @State newKey: string = ''
  @State newValue: string = ''
  @State isEditing: boolean = false
  @State editKey: string = ''

  private envConfigs: Record<string, Record<string, string>> = {
    'development': {
      'API_URL': 'https://dev.api.example.com',
      'DEBUG_MODE': 'true',
      'LOG_LEVEL': 'debug'
    },
    'staging': {
      'API_URL': 'https://stage.api.example.com',
      'DEBUG_MODE': 'true',
      'LOG_LEVEL': 'info'
    },
    'production': {
      'API_URL': 'https://api.example.com',
      'DEBUG_MODE': 'false',
      'LOG_LEVEL': 'warn'
    }
  }

  changeEnvironment(env: string) {
    this.currentEnv = env
    this.envVariables = new Map(Object.entries(this.envConfigs[env]))
  }

  addVariable() {
    if (this.newKey && this.newValue) {
      this.envVariables.set(this.newKey, this.newValue)
      this.newKey = ''
      this.newValue = ''
    }
  }

  startEdit(key: string) {
    this.isEditing = true
    this.editKey = key
    this.newValue = this.envVariables.get(key) || ''
  }

  saveEdit() {
    if (this.editKey && this.newValue) {
      this.envVariables.set(this.editKey, this.newValue)
      this.isEditing = false
      this.editKey = ''
      this.newValue = ''
    }
  }

  build() {
    Column({ space: 10 }) {
      Text('Environment Variables Manager')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      Row({ space: 10 }) {
        ForEach(['development', 'staging', 'production'], (env: string) => {
          Button(env)
            .backgroundColor(this.currentEnv === env ? '#007DFF' : '#F5F5F5')
            .fontColor(this.currentEnv === env ? Color.White : Color.Black)
            .onClick(() => this.changeEnvironment(env))
        })
      }
      .margin({ bottom: 20 })

      Text(`Current Environment: ${this.currentEnv}`)
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      List({ space: 10 }) {
        ForEach(Array.from(this.envVariables.entries()), (item: [string, string]) => {
          ListItem() {
            Row({ space: 10 }) {
              Text(`${item[0]}: ${item[1]}`)
                .fontSize(16)
                .layoutWeight(1)

              Button('Edit')
                .onClick(() => this.startEdit(item[0]))
                .width(80)
            }
          }
          .padding(10)
          .borderRadius(5)
          .backgroundColor('#F5F5F5')
        })
      }
      .layoutWeight(1)
      .width('100%')

      if (this.isEditing) {
        Column({ space: 10 }) {
          Text(`Editing: ${this.editKey}`)
            .fontSize(16)
            .fontWeight(FontWeight.Bold)

          TextInput({ placeholder: 'Enter value', text: this.newValue })
            .onChange((value: string) => {
              this.newValue = value
            })

          Button('Save')
            .onClick(() => this.saveEdit())
            .width('100%')
        }
        .padding(10)
        .borderRadius(5)
        .backgroundColor('#F5F5F5')
      }
    }
    .padding(10)
    .width('100%')
    .height('100%')
  }
}

