@Component
struct DropdownMenuApp {
  private items: Array<DropdownItem> = [
    { id: 1, label: 'Option 1', message: 'You selected Option 1' },
    { id: 2, label: 'Option 2', message: 'You selected Option 2' },
    { id: 3, label: 'Option 3', message: 'You selected Option 3' },
    { id: 4, label: 'Option 4', message: 'You selected Option 4' }
  ];

  @State isDropdownOpen: boolean = false;
  @State selectedItem: DropdownItem | null = null;

  build() {
    Column() {
      Button(this.selectedItem ? this.selectedItem.label : 'Select an option')
        .fontSize(18)
        .padding(10)
        .backgroundColor('#f0f0f0')
        .borderRadius(5)
        .onClick(() => {
          this.isDropdownOpen = !this.isDropdownOpen;
        });

      if (this.isDropdownOpen) {
        Column() {
          ForEach(this.items, (item: DropdownItem) => {
            Button(item.label)
              .fontSize(16)
              .padding(10)
              .backgroundColor('#FFFFFF')
              .borderRadius(5)
              .margin({ top: 5 })
              .onClick(() => {
                this.selectedItem = item;
                this.isDropdownOpen = false;
              });
          });
        }
        .width('100%')
        .padding(10)
        .backgroundColor('#F5F5F5')
        .borderRadius(5)
        .margin({ top: 10 });
      }

      if (this.selectedItem) {
        Text(this.selectedItem.message)
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

interface DropdownItem {
  id: number;
  label: string;
  message: string;
}

