@Component
struct PlaceholderContentExample {
  @State isLoading: boolean = true;
  @State searchQuery: string = '';
  @State showContent: boolean = false;

  build() {
    Column({ space: 20 }) {
      // Loading placeholder for content
      if (this.isLoading) {
        Column() {
          Progress({ value: 50, total: 100 })
            .width(100)
            .height(100)
          Text('Loading content...')
            .margin({ top: 10 })
        }
        .width('100%')
        .justifyContent(FlexAlign.Center)
      } else {
        Column() {
          Image($r('app.media.app_icon'))
            .width(200)
            .height(200)
          Text('Content loaded successfully!')
            .fontSize(18)
            .margin({ top: 10 })
        }
      }

      // Search input with placeholder
      TextInput({ placeholder: 'Type to search...' })
        .width('80%')
        .height(50)
        .placeholderColor(Color.Gray)
        .onChange((value: string) => {
          this.searchQuery = value;
        })

      // Content placeholder when empty
      if (this.searchQuery === '') {
        Text('No search results - try typing something')
          .fontSize(18)
          .fontColor(Color.Gray)
          .margin({ top: 20 })
      } else {
        Text(`Search results for: ${this.searchQuery}`)
          .fontSize(18)
          .margin({ top: 20 })
      }

      Button('Toggle Content')
        .width(150)
        .margin({ top: 30 })
        .onClick(() => {
          this.showContent = !this.showContent;
        })

      if (this.showContent) {
        Text('Additional content revealed!')
          .fontSize(16)
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .onAppear(() => {
      setTimeout(() => {
        this.isLoading = false;
      }, 3000);
    })
  }
}

import photoAccessHelper from '@ohos.file.photoAccessHelper';
import fs from '@ohos.file.fs';
import common from '@ohos.app.ability.common';
import dataSharePredicates from '@ohos.data.dataSharePredicates';

@Entry
@Component
struct PhotoGalleryApp {
  @State selectedImage: Resource = $r('app.media.app_icon');
  @State showFullScreen: boolean = false;
  @State images: Resource[] = [];
  private context = getContext(this) as common.UIAbilityContext;

  private async openGallery() {
    try {
      const phAccessHelper = photoAccessHelper.getPhotoAccessHelper(this.context);
      const predicates = new dataSharePredicates.DataSharePredicates();
      predicates.equalTo('media_type', 'image');

      const fetchOptions: photoAccessHelper.FetchOptions = {
        fetchColumns: ['display_name', 'uri'],
        predicates: predicates
      };

      const fetchResult = await phAccessHelper.getAssets(fetchOptions);

      if (fetchResult && fetchResult.getCount() > 0) {
        const tempImages: Resource[] = [];
        let asset = await fetchResult.getFirstObject();
        while (asset !== undefined && tempImages.length < 10) {
          tempImages.push($rawfile(asset.uri));
          asset = await fetchResult.getNextObject();
        }
        this.images = tempImages;
      }
    } catch (err) {
      console.error(`Photo selection failed: ${err.code}, ${err.message}`);
    }
  }

  build() {
    Column() {
      Button('Open Gallery')
        .onClick(() => {
          this.openGallery();
        })
        .margin(10)
        .padding(10)
        .borderRadius(5)

      if (this.showFullScreen) {
        Stack() {
          Image(this.selectedImage)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%')

          Button('Close')
            .onClick(() => {
              this.showFullScreen = false;
            })
            .position({ x: 20, y: 20 })
            .backgroundColor('#FFFFFF')
            .padding({ left: 10, right: 10, top: 5, bottom: 5 })
            .borderRadius(5)
        }
      } else {
        Grid() {
          ForEach(this.images, (image: Resource) => {
            GridItem() {
              Image(image)
                .width('100%')
                .aspectRatio(1)
                .objectFit(ImageFit.Cover)
                .borderRadius(5)
                .onClick(() => {
                  this.selectedImage = image;
                  this.showFullScreen = true;
                })
            }
          })
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsGap(10)
        .columnsGap(10)
        .padding(10)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

