    { id: 6, caption: 'Desert', description: 'Vast sandy desert', image: $r('app.media.app_icon') }
  ];

  @State selectedImage: ImageItem | null = null;
  @State showFullScreen: boolean = false;

  build() {
    Column() {
      if (this.showFullScreen && this.selectedImage) {
        Stack() {
          Image(this.selectedImage.image)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%');

          Column() {
            Text(this.selectedImage.caption)
              .fontSize(24)
              .fontWeight(FontWeight.Bold)
              .margin({ bottom: 8 });

            Text(this.selectedImage.description)
              .fontSize(18)
              .lineHeight(24);

            Button('Close')
              .onClick(() => {
                this.showFullScreen = false;
              })
              .margin({ top: 24 })
              .width('100%')
              .height(40);
          }
          .padding(24)
          .backgroundColor(Color.White)
          .borderRadius(16)
          .width('90%');
        }
        .width('100%')
        .height('100%')
        .backgroundColor('#000000');
      } else {
        Grid() {
          ForEach(this.images, (item: ImageItem) => {
            GridItem() {
              Column() {
                Image(item.image)
                  .width('100%')
                  .aspectRatio(1)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(8)
                  .onClick(() => {
                    this.selectedImage = item;
                    this.showFullScreen = true;
                  });

                Text(item.caption)
                  .fontSize(16)
                  .fontWeight(FontWeight.Medium)
                  .margin({ top: 8 });
              }
              .backgroundColor(Color.White)
              .borderRadius(12)
              .padding(16);
            }
          });
        }
        .columnsTemplate('1fr 1fr')
        .rowsGap(16)
        .columnsGap(16)
        .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }
}

