@Entry
@Component
struct AnimationSizeCalculator {
  @State widthSize: number = 100
  @State heightSize: number = 100
  @State flag: boolean = true
  @State usePercentage: boolean = false

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(this.usePercentage ? "50%" : this.widthSize)
        .height(this.usePercentage ? "30%" : this.heightSize)
        .margin(30)
        .onClick(() => {
          if (this.flag) {
            this.widthSize = 200
            this.heightSize = 200
          } else {
            this.widthSize = 100
            this.heightSize = 100
          }
          this.flag = !this.flag
        })
        .animation({
          duration: 1000,
          curve: Curve.EaseInOut,
          iterations: 1,
          playMode: PlayMode.Normal
        })

      Button("Toggle Percentage/Fixed")
        .width("60%")
        .height(50)
        .margin(20)
        .onClick(() => {
          this.usePercentage = !this.usePercentage
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

import promptAction from '@ohos.promptAction';

@Entry
@Component
struct Main {
  @State operationType: string = "BUTTON";

  build() {
    Column() {
      SubHeader({
        title: "Sample SubHeader",
        operationType: this.operationType
      })
      .margin(10)

      Button("Toggle Operation Type")
        .width(200)
        .height(40)
        .margin(10)
        .onClick(() => {
          this.operationType = this.operationType === "BUTTON" ? "TEXT" : "BUTTON";
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

@Component
struct SubHeader {
  title: string = "";
  operationType: string = "";

  build() {
    Column() {
      Row() {
        Text(this.title)
          .fontSize(18)
          .fontWeight(FontWeight.Bold)
          .layoutWeight(1)

        if (this.operationType === "BUTTON") {
          Button("Action")
            .type(ButtonType.Normal)
            .width(80)
            .height(30)
            .onClick(() => {
              promptAction.showToast({ message: 'Button clicked!' });
            })
        } else {
          Text("More")
            .fontSize(14)
            .fontColor(Color.Blue)
            .margin({ right: 10 })
        }
      }
      .width('100%')
      .padding(10)

      Divider()
        .strokeWidth(1)
        .color(Color.Gray)
    }
    .width('100%')
  }
}

