@Entry
@Component
struct CarouselSlider {
  private controller: SwiperController = new SwiperController();
  private images: string[] = [
    'image1.jpg',
    'image2.jpg',
    'image3.jpg'
  ];
  private captions: string[] = [
    'Caption 1',
    'Caption 2',
    'Caption 3'
  ];

  build() {
    Column() {
      Swiper(this.controller) {
        ForEach(this.images, (image: string, index: number) => {
          Column() {
            Image(image)
              .width('100%')
              .height(200);
            Text(this.captions[index])
              .fontSize(16)
              .margin({ top: 10 });
          }
        });
      }
      .indicator(true)
      .loop(true)
      .width('100%')
      .height(250);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

@Entry
@Component
struct DropdownApp {
  @State selectedOption: string = '';
  @State showDropdown: boolean = false;
  @State options: string[] = ['Option A', 'Option B', 'Option C'];
  @State descriptions: string[] = [
    'This is information for Option A',
    'This is information for Option B',
    'This is information for Option C'
  ];
  @State images: Resource[] = [
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon')
  ];

  build() {
    Column({ space: 20 }) {
      // Dropdown Button
      Button(this.selectedOption || 'Select an option')
        .onClick(() => {
          this.showDropdown = !this.showDropdown;
        })
        .width('80%')
        .height(40)
        .margin({ top: 20 });

      // Dropdown Menu
      if (this.showDropdown) {
        Column() {
          List() {
            ForEach(this.options, (option: string, index: number) => {
              ListItem() {
                Row() {
                  Image(this.images[index])
                    .width(30)
                    .height(30)
                    .margin({ right: 10 });
                  Text(option)
                    .fontSize(16);
                }
                .padding(10)
                .onClick(() => {
                  this.selectedOption = option;
                  this.showDropdown = false;
                });
              }
            });
          }
          .width('80%')
          .height(150)
          .border({ width: 1, color: '#cccccc' });
        }
        .width('100%')
        .alignItems(HorizontalAlign.Center);
      }

      // Display Selected Content
      if (this.selectedOption) {
        Column() {
          Text(this.descriptions[this.options.indexOf(this.selectedOption)])
            .fontSize(16)
            .margin({ top: 20 });
          Image(this.images[this.options.indexOf(this.selectedOption)])
            .width(100)
            .height(100)
            .margin({ top: 10 });
        }
        .width('100%')
        .alignItems(HorizontalAlign.Center);
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#f5f5f5');
  }
}

