import abilityAccessCtrl from '@ohos.abilityAccessCtrl';
import { Permissions } from '@ohos.abilityAccessCtrl';
import common from '@ohos.app.ability.common';
import { BusinessError } from '@ohos.base';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct MediaPermissionApp {
  private context: common.Context = getContext(this) as common.Context;
  @State permissionStatus: string = 'Checking permission...';
  @State hasPermission: boolean = false;
  @State showError: boolean = false;
  @State errorMessage: string = '';

  async checkPermission() {
    try {
      const permission: Permissions = 'ohos.permission.READ_MEDIA';
      const atManager = abilityAccessCtrl.createAtManager();
      const tokenID: number = globalThis.abilityContext?.tokenId || 0;
      const result = await atManager.checkAccessToken(tokenID, permission);

      if (result === abilityAccessCtrl.GrantStatus.PERMISSION_GRANTED) {
        this.permissionStatus = 'Permission granted';
        this.hasPermission = true;
        this.showError = false;
      } else {
        this.requestPermission();
      }
    } catch (error) {
      this.handleError(error as BusinessError);
    }
  }

  async requestPermission() {
    try {
      const permission: Permissions = 'ohos.permission.READ_MEDIA';
      const atManager = abilityAccessCtrl.createAtManager();
      const permissions: Array<Permissions> = [permission];
      const result = await atManager.requestPermissionsFromUser(
        this.context,
        permissions
      );

      if (result.authResults[0] === abilityAccessCtrl.GrantStatus.PERMISSION_GRANTED) {
        this.permissionStatus = 'Permission granted';
        this.hasPermission = true;
        this.showError = false;
        promptAction.showToast({ message: 'Permission granted' });
      } else {
        this.permissionStatus = 'Permission denied';
        this.errorMessage = 'READ_MEDIA permission is required to access media files';
        this.showError = true;
        promptAction.showToast({ message: 'Permission denied' });
      }
    } catch (error) {
      this.handleError(error as BusinessError);
    }
  }

  handleError(error: BusinessError) {
    this.errorMessage = `Error: ${error.message}`;
    this.showError = true;
    promptAction.showToast({ message: 'Permission request error' });
    console.error('Permission error:', error);
  }

  build() {
    Column({ space: 20 }) {
      Text('Media Permission Example')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ bottom: 20 })

      Text(this.permissionStatus)
        .fontSize(18)
        .fontColor(this.showError ? Color.Red : (this.hasPermission ? Color.Green : Color.Black))

      if (this.showError) {
        Text(this.errorMessage)
          .fontSize(16)
          .fontColor(Color.Red)
          .margin({ top: 10 })

        Button('Retry Permission Request')
          .onClick(() => this.checkPermission())
          .width('80%')
          .margin({ top: 20 })
      }

      Button('Check Permission')
        .onClick(() => this.checkPermission())
        .width('80%')
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .onAppear(() => {
      this.checkPermission()
    })
  }
}

