  @State secondaryIndex: number = 0
  @State secondaryOptions: Array<Option> = []

  private categories: Array<Category> = [
    {
      value: 'Category 1',
      options: [
        { value: 'Option 1.1', icon: $r("app.media.app_icon") },
        { value: 'Option 1.2', icon: $r("app.media.app_icon") }
      ]
    },
    {
      value: 'Category 2',
      options: [
        { value: 'Option 2.1', icon: $r("app.media.app_icon") },
        { value: 'Option 2.2', icon: $r("app.media.app_icon") }
      ]
    }
  ]

  build() {
    Column() {
      Select([
        { value: 'Category 1', icon: $r("app.media.app_icon") },
        { value: 'Category 2', icon: $r("app.media.app_icon") }
