@Entry
@Component
struct AnimationInterpolationExample {
  @State private isAnimating: boolean = false;
  @State private startValue: number = 0;
  @State private endValue: number = 1;
  @State private duration: number = 1000;

  build() {
    Column() {
      Text('Animation Interpolation').fontSize(20).margin(10)

      // Start value slider
      Text(`Start Value: ${this.startValue.toFixed(2)}`).fontSize(16)
      Slider({
        value: this.startValue,
        min: 0,
        max: 1,
        step: 0.1,
        style: SliderStyle.OutSet
      }).onChange((value: number) => {
        this.startValue = value;
      }).margin(10)

      // End value slider
      Text(`End Value: ${this.endValue.toFixed(2)}`).fontSize(16)
      Slider({
        value: this.endValue,
        min: 0,
        max: 1,
        step: 0.1,
        style: SliderStyle.OutSet
      }).onChange((value: number) => {
        this.endValue = value;
      }).margin(10)

      // Duration slider
      Text(`Duration: ${this.duration}ms`).fontSize(16)
      Slider({
        value: this.duration,
        min: 500,
        max: 2000,
        step: 100,
        style: SliderStyle.OutSet
      }).onChange((value: number) => {
        this.duration = value;
      }).margin(10)

      Button(this.isAnimating ? 'Stop Animation' : 'Start Animation')
        .onClick(() => {
          this.isAnimating = !this.isAnimating;
        })
        .margin(10)

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .opacity(this.isAnimating ? this.endValue : this.startValue)
        .animation({
          duration: this.duration,
          curve: Curve.EaseInOut,
          playMode: this.isAnimating ? PlayMode.Normal : PlayMode.Reverse,
          onFinish: () => {
            console.log('Animation completed');
          }
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

