import promptAction from '@ohos.promptAction';

interface DataItem {
  id: number;
  content: string;
}

class MockDatabase {
  private data: Array<DataItem> = [];

  create(content: string): void {
    const newItem: DataItem = { id: this.data.length + 1, content };
    this.data.push(newItem);
    promptAction.showToast({ message: 'Item created successfully' });
  }

  read(id: number): string | undefined {
    const item = this.data.find(item => item.id === id);
    if (item) {
      return item.content;
    } else {
      promptAction.showToast({ message: 'Item not found' });
      return undefined;
    }
  }

  update(id: number, newContent: string): void {
    const itemIndex = this.data.findIndex(item => item.id === id);
    if (itemIndex !== -1) {
      this.data[itemIndex].content = newContent;
      promptAction.showToast({ message: 'Item updated successfully' });
    } else {
      promptAction.showToast({ message: 'Item not found' });
    }
  }

  delete(id: number): void {
    const itemIndex = this.data.findIndex(item => item.id === id);
    if (itemIndex !== -1) {
      this.data.splice(itemIndex, 1);
      promptAction.showToast({ message: 'Item deleted successfully' });
    } else {
      promptAction.showToast({ message: 'Item not found' });
    }
  }

  getAll(): Array<DataItem> {
    return this.data;
  }
}

@Entry
@Component
struct CRUDApp {
  private db: MockDatabase = new MockDatabase();
  @State content: string = '';
  @State itemId: number = 1;
  @State items: Array<DataItem> = [];

  build() {
    Column({ space: 20 }) {
      TextInput({ text: this.content, placeholder: 'Enter content' })
        .onChange((value: string) => { this.content = value; })

      Button('Create')
        .onClick(() => {
          if (this.content.length === 0) {
            promptAction.showToast({ message: 'Content cannot be empty' });
            return;
          }
          this.db.create(this.content);
          this.content = '';
          this.items = this.db.getAll();
        })

      TextInput({ text: this.itemId.toString(), placeholder: 'Enter item ID' })
        .onChange((value: string) => { this.itemId = parseInt(value); })

      Button('Read')
        .onClick(() => {
          const content = this.db.read(this.itemId);
          if (content) {
            promptAction.showToast({ message: `Content: ${content}` });
          }
        })

      Button('Update')
        .onClick(() => {
          if (this.content.length === 0) {
            promptAction.showToast({ message: 'Content cannot be empty' });
            return;
          }
          this.db.update(this.itemId, this.content);
          this.content = '';
          this.items = this.db.getAll();
        })

      Button('Delete')
        .onClick(() => {
          this.db.delete(this.itemId);
          this.items = this.db.getAll();
        })

      List() {
        ForEach(this.items, (item: DataItem) => {
          ListItem() {
            Column() {
              Text(`ID: ${item.id}`).fontSize(16);
              Text(`Content: ${item.content}`).fontSize(14);
            }
            .padding(10);
          }
        }, (item: DataItem) => item.id.toString());
      }
      .width('100%')
      .height('40%');
    }
    .padding(20);
  }
}

