@Entry
@Component
struct QuizApp {
  @State currentQuestionIndex: number = 0;
  @State selectedOption: number = -1;
  @State showFeedback: boolean = false;
  @State score: number = 0;
  @State showScore: boolean = false;

  private questions: Array<QuizQuestion> = [
    {
      question: 'What is the capital of France?',
      options: ['London', 'Berlin', 'Paris', 'Madrid'],
      correctAnswer: 2
    },
    {
      question: 'Which planet is closest to the Sun?',
      options: ['Mars', 'Venus', 'Mercury', 'Jupiter'],
      correctAnswer: 2
    },
    {
      question: 'What is the largest mammal?',
      options: ['African Elephant', 'Blue Whale', 'Giraffe', 'Hippopotamus'],
      correctAnswer: 1
    }
  ];

  checkAnswer() {
    if (this.selectedOption === -1) return;

    const correct = this.selectedOption === this.questions[this.currentQuestionIndex].correctAnswer;
    if (correct) {
      this.score++;
    }
    this.showFeedback = true;

    setTimeout(() => {
      this.showFeedback = false;
      this.selectedOption = -1;
      if (this.currentQuestionIndex < this.questions.length - 1) {
        this.currentQuestionIndex++;
      } else {
        this.showScore = true;
      }
    }, 1500);
  }

  build() {
    Column() {
      if (!this.showScore) {
        Text(`Question ${this.currentQuestionIndex + 1}/${this.questions.length}`)
          .fontSize(18)
          .margin({ bottom: 10 });

        Text(this.questions[this.currentQuestionIndex].question)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .textAlign(TextAlign.Center)
          .margin({ bottom: 30 })
          .padding({ left: 20, right: 20 });

        ForEach(this.questions[this.currentQuestionIndex].options, (option: string, index: number) => {
          Row() {
            Radio({ value: index.toString(), group: 'quizOptions' })
              .checked(this.selectedOption === index)
              .onChange((isChecked: boolean) => {
                if (isChecked) {
                  this.selectedOption = index;
                }
              });
            Text(option)
              .fontSize(18)
              .margin({ left: 10 });
          }
          .width('80%')
          .margin({ bottom: 10 })
          .onClick(() => {
            this.selectedOption = index;
          });
        });

        Button('Submit Answer')
          .width('60%')
          .height(50)
          .margin({ top: 20 })
          .enabled(this.selectedOption !== -1 && !this.showFeedback)
          .onClick(() => {
            this.checkAnswer();
          });

        if (this.showFeedback) {
          Column() {
            Text(this.selectedOption === this.questions[this.currentQuestionIndex].correctAnswer ?
                 'Correct!' : 'Incorrect!')
              .fontSize(20)
              .fontColor(this.selectedOption === this.questions[this.currentQuestionIndex].correctAnswer ?
                         '#4CAF50' : '#F44336')
              .margin({ bottom: 10 });

            Text('Correct answer: ' +
                 this.questions[this.currentQuestionIndex].options[this.questions[this.currentQuestionIndex].correctAnswer])
              .fontSize(16);
          }
          .margin({ top: 20 });
        }
      } else {
        Column() {
          Text('Quiz Complete!')
            .fontSize(28)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Your Score: ${this.score}/${this.questions.length}`)
            .fontSize(24)
            .margin({ bottom: 40 });

          Button('Restart Quiz')
            .onClick(() => {
              this.currentQuestionIndex = 0;
              this.score = 0;
              this.showScore = false;
              this.selectedOption = -1;
            });
        }
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center);
  }
}

interface QuizQuestion {
  question: string;
  options: string[];
  correctAnswer: number;
}

import abilityAccessCtrl from '@ohos.abilityAccessCtrl';
import common from '@ohos.app.ability.common';
import { BusinessError } from '@ohos.base';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct GalleryPermissionApp {
  @State permissionStatus: string = 'Not Requested';
  @State hasPermission: boolean = false;
  @State showGallery: boolean = false;

  private atManager: abilityAccessCtrl.AtManager = abilityAccessCtrl.createAtManager();

  async requestGalleryPermission() {
    try {
      this.permissionStatus = 'Requesting...';
      const context = getContext(this) as common.UIAbilityContext;

      this.atManager.requestPermissionsFromUser(context, ["ohos.permission.READ_MEDIA"], (err: BusinessError, data) => {
        if (err) {
          this.permissionStatus = 'Error: ' + err.message;
          this.hasPermission = false;
          promptAction.showToast({ message: 'Permission request failed' });
          return;
        }

        if (data.authResults[0] === 0) {
          this.permissionStatus = 'Granted';
          this.hasPermission = true;
          this.showGallery = true;
          promptAction.showToast({ message: 'Permission granted' });
        } else {
          this.permissionStatus = 'Denied';
          this.hasPermission = false;
          promptAction.showToast({ message: 'Permission denied' });
        }
      });
    } catch (err) {
      this.permissionStatus = 'Error: ' + (err as BusinessError).message;
      this.hasPermission = false;
      promptAction.showToast({ message: 'Permission request error' });
    }
  }

  build() {
    Column({ space: 20 }) {
      Text('Gallery Access Permission')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 30 });

      Text(`Permission Status: ${this.permissionStatus}`)
        .fontSize(18)
        .fontColor(this.hasPermission ? Color.Green : Color.Red)
        .margin({ bottom: 20 });

      Button('Request Gallery Permission')
        .onClick(() => {
          this.requestGalleryPermission();
        })
        .width('80%')
        .height(50)
        .backgroundColor('#007BFF')
        .fontColor(Color.White);

      if (this.showGallery) {
        Column() {
          Text('Gallery Content')
            .fontSize(20)
            .margin({ bottom: 20 });

          Image($r('app.media.app_icon'))
            .width(200)
            .height(200)
            .borderRadius(10);
        }
        .margin({ top: 30 });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }
}

