@Component
struct FrameAnimationEventExample {
  @State myScale: number = 1.0;
  @State rotationAngle: number = 0;
  uiContext: UIContext | undefined = undefined;

  aboutToAppear() {
    this.uiContext = this.getUIContext?.();
  }

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(100)
        .scale({ x: this.myScale, y: this.myScale })
        .rotate({ x: 0, y: 0, z: 1, angle: this.rotationAngle })
        .onClick(() => {
          if (!this.uiContext) {
            console.info("no uiContext, keyframe failed");
            return;
          }
          this.myScale = 1;
          this.rotationAngle = 0;
          this.uiContext.keyframeAnimateTo({ iterations: 3 }, [
            {
              duration: 800,
              event: () => {
                this.myScale = 1.5;
                this.rotationAngle = 90;
              }
            },
            {
              duration: 500,
              event: () => {
                this.myScale = 1;
                this.rotationAngle = 0;
              }
            }
          ]);
        })
    }.width('100%').margin({ top: 5 })
  }
}

@Entry
@Component
struct FormWithValidation {
  @State username: string = ''
  @State email: string = ''
  @State password: string = ''
  @State confirmPassword: string = ''

  @State usernameError: string = ''
  @State emailError: string = ''
  @State passwordError: string = ''
  @State confirmPasswordError: string = ''

  @State isFormValid: boolean = false

  validateUsername(value: string): string | null {
    if (value.length < 3) return 'Must be at least 3 characters'
    if (value.length > 20) return 'Must be less than 20 characters'
    return null
  }

  validateEmail(value: string): string | null {
    if (value.length < 5) return 'Must be at least 5 characters'
    if (value.length > 50) return 'Must be less than 50 characters'
    if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(value)) return 'Invalid email format'
    return null
  }

  validatePassword(value: string): string | null {
    if (value.length < 6) return 'Must be at least 6 characters'
    if (value.length > 30) return 'Must be less than 30 characters'
    return null
  }

  validateConfirmPassword(value: string): string | null {
    return this.password === value ? null : 'Passwords do not match'
  }

  validateForm() {
    this.usernameError = this.validateUsername(this.username) || ''
    this.emailError = this.validateEmail(this.email) || ''
    this.passwordError = this.validatePassword(this.password) || ''
    this.confirmPasswordError = this.validateConfirmPassword(this.confirmPassword) || ''

    this.isFormValid = !this.usernameError && !this.emailError &&
                      !this.passwordError && !this.confirmPasswordError
  }

  build() {
    Column({ space: 20 }) {
      CustomInput({
        value: $username,
        errorMessage: $usernameError,
        placeholder: 'Username',
        onValidate: (value) => {
          this.username = value
          this.validateForm()
        }
      })

      CustomInput({
        value: $email,
        errorMessage: $emailError,
        placeholder: 'Email',
        onValidate: (value) => {
          this.email = value
          this.validateForm()
        }
      })

      CustomInput({
        value: $password,
        errorMessage: $passwordError,
        placeholder: 'Password',
        inputType: InputType.Password,
        onValidate: (value) => {
          this.password = value
          this.validateForm()
        }
      })

      CustomInput({
        value: $confirmPassword,
        errorMessage: $confirmPasswordError,
        placeholder: 'Confirm Password',
        inputType: InputType.Password,
        onValidate: (value) => {
          this.confirmPassword = value
          this.validateForm()
        }
      })

      Button('Submit', { type: ButtonType.Capsule })
        .enabled(this.isFormValid)
        .onClick(() => {
          console.info('Form submitted successfully')
        })
        .width('100%')
        .height(40)
    }
    .padding(20)
    .width('100%')
  }
}

@Component
struct CustomInput {
  @Link value: string
  @Link errorMessage: string
  placeholder: string = ''
  @Prop inputType: InputType = InputType.Normal
  @Prop onValidate: (value: string) => void

  build() {
