      }
    }
  }
}

@Entry
@Component
struct CustomAnimationExample {
  @State scaleValue: number = 1.0
  @State rotateValue: number = 0
  @State opacityValue: number = 1.0
  @State translateX: number = 0
  @State translateY: number = 0
  @State isAnimating: boolean = false
  uiContext: UIContext | undefined = undefined

  aboutToAppear() {
    this.uiContext = this.getUIContext?.()
  }

  build() {
    Column() {
      // Animated Image
      Image($r('app.media.app_icon'))
        .width(150)
        .height(150)
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .rotate({ x: 0, y: 0, z: 1, angle: this.rotateValue })
        .opacity(this.opacityValue)
        .translate({ x: this.translateX, y: this.translateY })
        .animation({
          duration: 1000,
          curve: Curve.EaseInOut,
          iterations: 1,
          playMode: PlayMode.Normal
        })
        .margin(30)

      // Animation Controls
      Button('Scale Animation')
        .onClick(() => {
          animateTo({
            duration: 800,
            curve: Curve.EaseInOut
          }, () => {
            this.scaleValue = this.scaleValue === 1.0 ? 1.5 : 1.0
          })
        })
        .margin(10)
        .width('80%')

      Button('Rotate Animation')
        .onClick(() => {
          animateTo({
            duration: 1000,
            curve: Curve.EaseInOut
          }, () => {
            this.rotateValue = this.rotateValue === 0 ? 360 : 0
          })
        })
        .margin(10)
        .width('80%')

      Button('Fade Animation')
        .onClick(() => {
          animateTo({
            duration: 600,
            curve: Curve.EaseIn
          }, () => {
            this.opacityValue = this.opacityValue === 1.0 ? 0.3 : 1.0
          })
        })
        .margin(10)
        .width('80%')

      Button('Keyframe Animation')
        .onClick(() => {
          if (!this.uiContext) {
            console.info("no uiContext, keyframe failed")
            return
          }
          this.uiContext.keyframeAnimateTo({ iterations: 2 }, [
            {
              duration: 800,
              event: () => {
                this.scaleValue = 1.5
                this.rotateValue = 90
                this.opacityValue = 0.7
                this.translateX = 50
              }
            },
            {
              duration: 500,
              event: () => {
                this.scaleValue = 1.0
                this.rotateValue = 180
                this.opacityValue = 1.0
                this.translateX = 0
              }
            }
          ])
        })
        .margin(10)
        .width('80%')

      Button('Complex Animation')
        .onClick(() => {
          this.isAnimating = !this.isAnimating
          animateTo({
            duration: 1500,
            curve: Curve.EaseInOut
          }, () => {
            this.scaleValue = this.isAnimating ? 1.8 : 1.0
            this.rotateValue = this.isAnimating ? 180 : 0
            this.opacityValue = this.isAnimating ? 0.7 : 1.0
            this.translateX = this.isAnimating ? 100 : 0
            this.translateY = this.isAnimating ? 50 : 0
          })
        })
        .margin(10)
        .width('80%')
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

