@Entry
@Component
struct SubHeaderWithLoadingAnimation {
  @State isLoading: boolean = true;
  @State rotationAngle: number = 0;
  private animationInterval: number = -1;

  aboutToAppear() {
    this.startLoadingAnimation();
  }

  aboutToDisappear() {
    if (this.animationInterval !== -1) {
      clearInterval(this.animationInterval);
    }
  }

  startLoadingAnimation() {
    this.animationInterval = setInterval(() => {
      this.rotationAngle = (this.rotationAngle + 10) % 360;
    }, 50);
  }

  toggleLoading() {
    if (this.isLoading) {
      clearInterval(this.animationInterval);
      this.animationInterval = -1;
    } else {
      this.startLoadingAnimation();
    }
    this.isLoading = !this.isLoading;
  }

  build() {
    Column() {
      // SubHeader with Loading Animation
      Column() {
        Text("SubHeader Title")
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .textAlign(TextAlign.Center)
          .backgroundColor(Color.Gray)
          .padding(10)
          .width("100%")

        if (this.isLoading) {
          Stack() {
            Image($r('app.media.app_icon'))
              .width(30)
              .height(30)
              .rotate({ x: 0, y: 0, z: 1, angle: this.rotationAngle })
          }
          .width(30)
          .height(30)
          .margin({ top: 10 })
        }
      }
      .width("100%")
      .padding(10)

      Button("Toggle Loading")
        .width(200)
        .height(50)
        .margin(10)
        .onClick(() => this.toggleLoading())
    }
    .width("100%")
    .height("100%")
    .backgroundColor("#ffffff")
  }
}

