          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your age' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.age = value;
          });
      }

      Column() {
        Text('Gender:')
          .fontSize(16)
          .margin({ bottom: 8 });

        Select(this.genders)
          .width('100%')
