@Entry
@Component
struct FileUploaderWithPermissions {
  @State selectedImage: string = ''
  @State hasPermission: boolean = false
  @State uploadStatus: string = ''
  @State showFullScreen: boolean = false

  build() {
    Column() {
      Text(this.hasPermission ? 'Permissions granted' : 'Permissions needed')
        .fontSize(16)
        .margin(10)

      Button('Request Permissions')
        .onClick(async () => {
          this.hasPermission = await this.requestPermissions()
        })
        .margin(10)
        .width('70%')

      Button('Open Gallery')
        .onClick(async () => {
          if (this.hasPermission) {
            this.selectedImage = await this.pickFile()
          } else {
            this.uploadStatus = 'Please request permissions first'
          }
        })
        .margin(10)
        .width('70%')
        .enabled(this.hasPermission)

      if (this.selectedImage) {
        Image(this.selectedImage)
          .width(200)
          .height(200)
          .margin(10)
          .onClick(() => {
            this.showFullScreen = true
          })
      }

      Button('Upload File')
        .onClick(async () => {
          if (this.selectedImage) {
            const success = await this.uploadFile(this.selectedImage)
            this.uploadStatus = success ? 'Upload successful!' : 'Upload failed'
          } else {
            this.uploadStatus = 'No file selected'
          }
        })
        .margin(10)
        .width('70%')
        .enabled(this.selectedImage !== '')

      Text(this.uploadStatus)
        .fontSize(14)
        .margin(10)
        .fontColor(this.uploadStatus.includes('success') ? Color.Green : Color.Red)

      if (this.showFullScreen && this.selectedImage) {
        Stack() {
          Image(this.selectedImage)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%')

          Button('Close')
            .onClick(() => {
              this.showFullScreen = false
            })
            .position({ x: 20, y: 20 })
            .backgroundColor('#FFFFFF')
            .padding({ left: 10, right: 10, top: 5, bottom: 5 })
            .borderRadius(5)
        }
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }

  private async requestPermissions(): Promise<boolean> {
    return new Promise((resolve) => {
      setTimeout(() => {
        resolve(true)
      }, 500)
    })
  }

  private async pickFile(): Promise<string> {
    return new Promise((resolve) => {
      setTimeout(() => {
        resolve('app.media.app_icon')
      }, 500)
    })
  }

  private async uploadFile(filePath: string): Promise<boolean> {
    return new Promise((resolve) => {
      setTimeout(() => {
        resolve(true)
      }, 1500)
    })
  }
}

