@Entry
@Component
struct MainApp {
  private pluginManager: PluginManager = new PluginManager();
  @State currentPluginId: string = '';
  @State pluginsList: string[] = [];

  aboutToAppear() {
    // Register plugins when the app starts
    this.pluginManager.registerPlugin(new ExamplePlugin());
    this.pluginManager.registerPlugin(new AnotherPlugin());
    this.pluginsList = this.pluginManager.listPlugins();
  }

  build() {
    Column() {
      Text('Plugin System Example')
        .fontSize(24)
        .margin(10);

      Column() {
        ForEach(this.pluginsList, (pluginId: string) => {
          Button(pluginId)
            .onClick(() => {
              this.currentPluginId = pluginId;
              this.pluginManager.executePlugin(pluginId);
            })
            .margin(5)
            .width('80%');
        });
      }
      .margin(10);

      Text(`Current Plugin: ${this.currentPluginId}`)
        .fontSize(18)
        .margin(10);

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

class PluginManager {
  private plugins: Map<string, Plugin> = new Map();

  registerPlugin(plugin: Plugin) {
    this.plugins.set(plugin.getId(), plugin);
  }

  listPlugins(): string[] {
    return Array.from(this.plugins.keys());
  }

  executePlugin(pluginId: string) {
    const plugin = this.plugins.get(pluginId);
    if (plugin) {
      plugin.execute();
    }
  }
}

abstract class Plugin {
  abstract getId(): string;
  abstract execute(): void;
}

class ExamplePlugin extends Plugin {
  getId(): string { return "example"; }
  execute(): void { console.log("Example plugin executed"); }
}

class AnotherPlugin extends Plugin {
  getId(): string { return "another"; }
  execute(): void { console.log("Another plugin executed"); }
}

