@Entry
@Component
struct ClickThrottleApp {
  @State lastClickTime: number = 0;
  @State clickCount: number = 0;
  @State throttleTime: number = 500; // Throttle time set to 500ms

  build() {
    Column() {
      Button('Click Me (Throttled)')
        .margin({ top: 30, bottom: 30 })
        .onClick(() => {
          const currentTime = new Date().getTime();
          if (currentTime - this.lastClickTime > this.throttleTime) {
            this.lastClickTime = currentTime;
            this.clickCount += 1;
            console.info(`Button clicked ${this.clickCount} times`);
          } else {
            console.info("Click throttled - too fast!");
          }
        })

      Text(`Click Count: ${this.clickCount}`)
        .fontSize(20)
        .margin({ top: 20 })

      Text(`Throttle Time: ${this.throttleTime}ms`)
        .fontSize(16)
        .margin({ top: 10 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

