@Entry
@Component
struct BatchInputProcessor {
  @State userInputs: string[] = [];
  @State processedBatch: string[] = [];
  @State currentInput: string = '';

  build() {
    Column() {
      TextInput({ placeholder: 'Enter input here' })
        .onChange((value: string) => {
          this.currentInput = value;
        })
        .width('80%')
        .height(50)
        .margin(10)

      Button('Add to Batch')
        .onClick(() => {
          if (this.currentInput.trim() !== '') {
            this.userInputs.push(this.currentInput);
            this.currentInput = '';
          }
        })
        .width(200)
        .height(50)
        .margin(10)

      Button('Process Batch')
        .onClick(() => {
          // Process all inputs at once
          this.processedBatch = this.userInputs.map(input => `Processed: ${input.toUpperCase()}`);
          this.userInputs = []; // Clear batch after processing
        })
        .width(200)
        .height(50)
        .margin(10)

      if (this.processedBatch.length > 0) {
        Text('Processed Items:')
          .fontSize(20)
          .margin(10)
        List({ space: 10 }) {
          ForEach(this.processedBatch, (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(16)
                .margin(5)
            }
          })
        }
        .width('90%')
        .height('40%')
        .margin(10)
      }

      if (this.userInputs.length > 0) {
        Text('Pending Batch:')
          .fontSize(20)
          .margin(10)
        List({ space: 5 }) {
          ForEach(this.userInputs, (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(14)
                .margin(5)
                .fontColor('#666666')
            }
          })
        }
        .width('90%')
        .height('30%')
        .margin(10)
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#f5f5f5')
  }
}

