@Entry
@Component
struct CustomSearchApp {
  @State items: string[] = [
    'Apple', 'Banana', 'Orange', 'Grapes', 'Mango', 'Pineapple', 'Strawberry', 'Watermelon', 'Cherry', 'Blueberry', 'Lemon', 'Peach'
  ];

  @State searchText: string = '';

  // Custom search algorithm combining prefix and substring matching
  customSearch(): string[] {
    if (this.searchText.trim() === '') {
      return this.items;
    } else {
      return this.items.filter(item =>
        item.toLowerCase().includes(this.searchText.toLowerCase()) ||
        item.toLowerCase().startsWith(this.searchText.toLowerCase())
      );
    }
  }

  build() {
    Column() {
      // Search Bar
      TextInput({
        placeholder: 'Search fruits...',
        text: this.searchText
      })
        .width('100%')
        .onChange((value: string) => {
          this.searchText = value;
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      // Results List
      if (this.customSearch().length > 0) {
        List() {
          ForEach(this.customSearch(), (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(18)
                .padding(12);
            }
          }, (item: string) => item);
        }
      } else {
        Text('No matching items found')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

