  build() {
    Column() {
      if (this.showLoader) {
        this.AnimatedLoader()
      } else {
        Column() {
          // Main Content Area
          Column() {
            if (this.currentTab === 0) {
              this.HomeContent()
            } else if (this.currentTab === 1) {
              this.ProfileContent()
            } else {
              this.SettingsContent()
            }
          }
          .layoutWeight(1)

          // Bottom Navigation Bar
          Row() {
            this.NavItem('Home', 0)
            this.NavItem('Profile', 1)
            this.NavItem('Settings', 2)
