@Entry
@Component
struct StarRatingSystem {
  @State private ratings: number[] = [3, 4, 5, 2, 4];
  @State private averageRating: number = 0;

  aboutToAppear() {
    this.calculateAverage();
  }

  calculateAverage() {
    const sum = this.ratings.reduce((acc: number, curr: number) => acc + curr, 0);
    this.averageRating = sum / this.ratings.length;
  }

  rateItem(index: number, rating: number) {
    this.ratings[index] = rating;
    this.calculateAverage();
  }

  build() {
    Column() {
      Text(`Average Rating: ${this.averageRating.toFixed(1)}`)
        .fontSize(20)
        .margin(10)

      ForEach(this.ratings, (item: number, index: number) => {
        Row() {
          ForEach([1, 2, 3, 4, 5], (star: number) => {
            Image($rawfile(star <= item ? 'star_filled.png' : 'star_empty.png'))
              .width(30)
              .height(30)
              .onClick(() => this.rateItem(index, star))
          })
        }
        .margin(5)
      })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

