import { ExceptionPrompt, PromptOptions, MarginType } from '@kit.ArkUI';

@Component
struct ErrorHandlingWrapper {
  @State hasError: boolean = false;
  @State errorMessage: string = '';
  @BuilderParam child: () => void;

  build() {
    Column() {
      if (this.hasError) {
        ExceptionPrompt({
          options: {
            icon: $r('app.media.app_icon'),
            tip: this.errorMessage,
            marginType: MarginType.DEFAULT_MARGIN,
            actionText: 'Retry',
            marginTop: 80,
            isShown: true
          },
          onTipClick: () => {
            console.error('Error displayed:', this.errorMessage);
          },
          onActionTextClick: () => {
            console.log('Retry initiated');
            this.hasError = false;
          }
        })
      } else {
        this.child()
      }
    }
  }

  componentDidCatch(error: Error) {
    this.hasError = true;
    this.errorMessage = error.message;
    console.error('Component Error:', error);
  }
}

@Entry
@Component
struct MainApp {
  @State throwError: boolean = false;

  build() {
    Column() {
      ErrorHandlingWrapper({
        child: this.renderContent
      })
    }
    .width('100%')
    .height('100%')
  }

  @Builder
  renderContent() {
    Button(this.throwError ? 'Click to throw error' : 'Click to trigger error')
      .onClick(() => {
        if (this.throwError) {
          throw new Error('Custom error triggered in component');
        } else {
          this.throwError = true;
        }
      })
      .width('80%')
      .height(50)
      .margin(20)
  }
}

@Entry
@Component
struct ParentComponent {
  @State parentData: string = 'Initial Sync Data'; // Parent's source of truth

  build() {
    Column() {
      Text(`Parent Data: ${this.parentData}`)
        .fontSize(24)
        .margin(10)

      TextInput({ text: this.parentData })
        .onChange((value: string) => {
          this.parentData = value; // Updates will sync to child
        })
        .width('80%')
        .margin(10)

      ChildComponent({ syncedData: $parentData }) // Establish two-way sync
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
  }
}

@Component
struct ChildComponent {
  @Link @Watch('onDataChange') syncedData: string; // Two-way synchronized data with parent

  onDataChange(): void {
    console.log(`Data synchronized in child: ${this.syncedData}`); // Log sync changes
  }

  build() {
    Column() {
      Text(`Child Data: ${this.syncedData}`)
        .fontSize(20)
        .margin(10)

      TextInput({ text: this.syncedData })
        .onChange((value: string) => {
          this.syncedData = value; // Updates will sync back to parent
        })
        .width('80%')
        .margin(10)
    }
    .width('100%')
    .padding(10)
  }
}

import promptAction from '@ohos.promptAction';

@Entry
@Component
struct AgeGroupApp {
  @State age: string = '';
  @State showMessage: boolean = false;
  @State message: string = '';

  build() {
    Column() {
      Text('Age Group Checker')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      Column() {
        Text('Age:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your age' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.age = value;
          });
      }

      Button('Check Age Group')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.age) {
            const ageNum = parseInt(this.age);
            if (ageNum < 13) {
              this.message = 'You are a child.';
            } else if (ageNum >= 13 && ageNum < 20) {
              this.message = 'You are a teenager.';
            } else if (ageNum >= 20 && ageNum < 60) {
              this.message = 'You are an adult.';
            } else {
              this.message = 'You are a senior.';
            }
            this.showMessage = true;
          } else {
            promptAction.showToast({
              message: 'Please enter your age'
            });
          }
        });

      if (this.showMessage) {
        Text(this.message)
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

