import promptAction from '@ohos.promptAction';

@Entry
@Component
struct FormInterface {
  @State name: string = '';
  @State email: string = '';
  @State phoneNumber: string = '';
  @State showSuccessMessage: boolean = false;
  @State errorMessage: string = '';

  validateForm(): boolean {
    if (!this.name.trim()) {
      this.errorMessage = 'Name is required';
      return false;
    }
    if (!this.email.trim()) {
      this.errorMessage = 'Email is required';
      return false;
    }
    if (!this.email.includes('@')) {
      this.errorMessage = 'Invalid email format';
      return false;
    }
    if (!this.phoneNumber.trim()) {
      this.errorMessage = 'Phone number is required';
      return false;
    }
    this.errorMessage = '';
    return true;
  }

  build() {
    Column() {
      Text('Contact Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 30 });

      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value;
          });
      }

      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value;
          });
      }

      Column() {
        Text('Phone Number:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your phone number' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.phoneNumber = value;
          });
      }

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ bottom: 20 });
      }

      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.validateForm()) {
            this.showSuccessMessage = true;
          } else {
            promptAction.showToast({
              message: this.errorMessage
            });
          }
        });

      if (this.showSuccessMessage) {
        Column() {
          Text('Success!')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Name: ${this.name}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Phone: ${this.phoneNumber}`)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.showSuccessMessage = false;
              this.name = '';
              this.email = '';
              this.phoneNumber = '';
            });
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

@Entry
@Component
struct Main {
  @State customAttribute: string = "Custom Value";
  @State isEnabled: boolean = true;
  @State headerColor: ResourceColor = "#2a58d0";
  @State fontSize: number = 18;
  @State fontWeight: FontWeight = FontWeight.Bold;
  @State paddingValue: number = 15;
  @State borderRadiusValue: number = 8;

  build() {
    Column() {
      // Custom SubHeader component with universal attributes
      SubHeader({
        title: "My SubHeader",
        customAttr: this.customAttribute,
        isEnabled: this.isEnabled,
        bgColor: this.headerColor,
        fontSize: this.fontSize,
        fontWeight: this.fontWeight,
        paddingValue: this.paddingValue,
        borderRadiusValue: this.borderRadiusValue
      })

      Divider().margin(20)

      // Controls to modify the universal attributes
      Row() {
        Button("Change Attribute")
          .onClick(() => {
            this.customAttribute = "New Value " + Math.floor(Math.random() * 100);
          })
          .margin(5)

        Button(this.isEnabled ? "Disable" : "Enable")
          .onClick(() => {
            this.isEnabled = !this.isEnabled;
          })
          .margin(5)
      }

      Row() {
        Button("Blue")
          .onClick(() => {
            this.headerColor = "#2a58d0";
          })
          .margin(5)

        Button("Green")
          .onClick(() => {
            this.headerColor = "#4CAF50";
          })
          .margin(5)
      }

      Row() {
        Button("Increase Font")
          .onClick(() => {
            this.fontSize += 1;
          })
          .margin(5)

        Button("Decrease Font")
          .onClick(() => {
            this.fontSize = Math.max(12, this.fontSize - 1);
          })
          .margin(5)
      }

      Row() {
        Button("Increase Padding")
          .onClick(() => {
            this.paddingValue += 1;
          })
          .margin(5)

        Button("Decrease Padding")
          .onClick(() => {
            this.paddingValue = Math.max(0, this.paddingValue - 1);
          })
          .margin(5)
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

@Component
struct SubHeader {
  @Prop title: string = "";
  @Prop customAttr: string = "";
  @Prop isEnabled: boolean = true;
  @Prop bgColor: ResourceColor = "#2a58d0";
  @Prop fontSize: number = 18;
  @Prop fontWeight: FontWeight = FontWeight.Bold;
  @Prop paddingValue: number = 15;
  @Prop borderRadiusValue: number = 8;

  build() {
    Row() {
      Image($r('app.media.app_icon'))
        .width(30)
        .height(30)
        .margin({ right: 10 })

      Column() {
        Text(this.title)
          .fontSize(this.fontSize)
          .fontWeight(this.fontWeight)
          .fontColor(this.isEnabled ? Color.White : Color.Gray)

        Text(this.customAttr)
          .fontSize(this.fontSize - 4)
          .fontColor(this.isEnabled ? Color.White : Color.Gray)
          .opacity(0.8)
      }
      .alignItems(HorizontalAlign.Start)
    }
    .width('100%')
    .padding(this.paddingValue)
    .backgroundColor(this.bgColor)
    .borderRadius(this.borderRadiusValue)
    .opacity(this.isEnabled ? 1 : 0.6)
  }
}

import { UIContext } from '@kit.ArkUI';
import { AnimatorOptions } from '@ohos.animator';

@Entry
@Component
struct AnimatorResultExample {
  @State myScale: number = 1.0;
  @State rotationAngle: number = 0;
  @State animatorStatus: string = 'Ready';
  uiContext: UIContext | undefined = undefined;
  animatorOptions: AnimatorOptions | undefined = undefined;

  aboutToAppear() {
    this.uiContext = this.getUIContext?.();
  }

  startAnimation() {
    if (!this.uiContext) {
      console.info("no uiContext, animation failed");
      return;
    }
    this.animatorStatus = 'Running';
    this.myScale = 1;
    this.rotationAngle = 0;

    this.animatorOptions = {
      duration: 500,
      easing: 'ease',
      delay: 0,
      fill: 'none',
      direction: 'normal',
      iterations: Infinity,
      begin: 0,
      end: 1
    };

    this.uiContext.animateTo(
      this.animatorOptions,
      () => {
        this.myScale = 1.5;
        this.rotationAngle = 90;
        this.myScale = 1;
        this.rotationAngle = 180;
        this.myScale = 1.2;
        this.rotationAngle = 270;
        this.myScale = 1;
        this.rotationAngle = 360;
        this.animatorStatus = 'Completed';
      }
    );
  }

  pauseAnimation() {
    if (this.animatorOptions) {
      this.animatorStatus = 'Paused';
    }
  }

  resumeAnimation() {
    if (this.animatorOptions) {
      this.startAnimation();
      this.animatorStatus = 'Running';
    }
  }

  stopAnimation() {
    if (this.animatorOptions) {
      this.animatorStatus = 'Stopped';
      this.myScale = 1;
      this.rotationAngle = 0;
    }
  }

  build() {
    Column() {
      Text('Animation Status: ' + this.animatorStatus)
        .fontSize(20)
        .margin(10);

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(20)
        .scale({ x: this.myScale, y: this.myScale })
        .rotate({ x: 0, y: 0, z: 1, angle: this.rotationAngle })

      Row({ space: 10 }) {
        Button('Start')
          .onClick(() => this.startAnimation())
          .width('25%')

        Button('Pause')
          .onClick(() => this.pauseAnimation())
          .width('25%')

        Button('Resume')
          .onClick(() => this.resumeAnimation())
          .width('25%')

        Button('Stop')
          .onClick(() => this.stopAnimation())
          .width('25%')
      }
      .width('100%')
      .margin(10)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

