import promptAction from '@ohos.promptAction';

@Entry
@Component
struct LoginScreen {
  @State email: string = '';
  @State password: string = '';
  @State showSnackbar: boolean = false;
  @State snackbarMessage: string = '';

  build() {
    Column() {
      // Email Label and Input
      Text('Email')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your email', text: this.email })
        .onChange((value: string) => {
          this.email = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      // Password Label and Input
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      // Login Button
      Button('Login')
        .onClick(() => {
          if (this.email && this.password) {
            this.snackbarMessage = 'Login successful!';
            this.showSnackbar = true;
            // Hide snackbar after 2 seconds
            setTimeout(() => {
              this.showSnackbar = false;
            }, 2000);
          } else {
            this.snackbarMessage = 'Please enter both email and password.';
            this.showSnackbar = true;
            setTimeout(() => {
              this.showSnackbar = false;
            }, 2000);
          }
        })
        .width('60%')
        .margin({ top: 20 })
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White);

      // Snackbar Display
      if (this.showSnackbar) {
        Text(this.snackbarMessage)
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
          .backgroundColor('#4CAF50')
          .padding(10)
          .borderRadius(5)
          .fontColor(Color.White);
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

