@Component
struct ImageGridView {
  @State selectedImage: Resource = $r('app.media.app_icon')
  @State showFullScreen: boolean = false

  private images: Resource[] = [
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon')
  ]

  build() {
    Column() {
      if (this.showFullScreen) {
        Stack() {
          Image(this.selectedImage)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%')

          Button('Back')
            .onClick(() => {
              this.showFullScreen = false
            })
            .margin(20)
            .backgroundColor('#FFFFFF')
            .padding(10)
            .borderRadius(5)
        }
      } else {
        Grid() {
          ForEach(this.images, (image: Resource) => {
            GridItem() {
              Image(image)
                .width('100%')
                .aspectRatio(1)
                .objectFit(ImageFit.Cover)
                .borderRadius(8)
                .onClick(() => {
                  this.selectedImage = image
                  this.showFullScreen = true
                })
            }
          })
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsGap(12)
        .columnsGap(12)
        .padding(12)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

@Entry
@Component
struct PerformanceOptimizationDemo {
  @State private optimized: boolean = false;
  @State private items: Array<number> = [];
  private dataSource: OptimizedDataSource = new OptimizedDataSource();

  aboutToAppear() {
    // Initialize with 100 items for demonstration
    for (let i = 0; i < 100; i++) {
      this.items.push(i);
    }
    this.dataSource.initializeData(this.items);
  }

  build() {
    Column({ space: 20 }) {
      Text('Performance Optimization Techniques')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20 });

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 20 });

      Button(this.optimized ? 'Disable Optimization' : 'Enable Optimization')
        .onClick(() => {
          this.optimized = !this.optimized;
          console.log(`Optimization ${this.optimized ? 'enabled' : 'disabled'}`);
        })
        .width('80%')
        .height(50)
        .margin({ top: 20 });

      List({ space: 10 }) {
        if (this.optimized) {
          LazyForEach(this.dataSource, (item: number) => {
            ListItem() {
              Text(`Optimized Item ${item}`)
                .fontSize(16)
                .padding(10)
            }
            .width('100%')
            .backgroundColor(Color.White)
            .borderRadius(8)
          }, (item: number) => item.toString())
        } else {
          ForEach(this.items, (item: number) => {
            ListItem() {
              Text(`Regular Item ${item}`)
                .fontSize(16)
                .padding(10)
            }
            .width('100%')
            .backgroundColor(Color.White)
            .borderRadius(8)
          })
        }
      }
      .width('100%')
