@Entry
@Component
struct AnimationClickExample {
  @State scaleValue: number = 1.0
  @State rotateAngle: number = 0
  @State opacityValue: number = 1.0
  @State translateX: number = 0
  private animateFlag: boolean = true

  build() {
    Column() {
      Button('Start Animation')
        .width(200)
        .height(60)
        .margin(30)
        .backgroundColor('#46B1E3')
        .opacity(this.opacityValue)
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .rotate({ x: 0, y: 0, z: 1, angle: this.rotateAngle })
        .translate({ x: this.translateX, y: 0 })
        .onClick(() => {
          animateTo({
            duration: 1500,
            curve: Curve.EaseInOut,
            iterations: 1,
            playMode: PlayMode.Normal,
            onFinish: () => {
              console.info('Button animation completed')
            }
          }, () => {
            if (this.animateFlag) {
              this.scaleValue = 1.5
              this.rotateAngle = 45
              this.opacityValue = 0.7
              this.translateX = 100
            } else {
              this.scaleValue = 1.0
              this.rotateAngle = 0
              this.opacityValue = 1.0
              this.translateX = 0
            }
            this.animateFlag = !this.animateFlag
          })
        })

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(50)
        .opacity(this.opacityValue)
        .onClick(() => {
          animateTo({
            duration: 1000,
            curve: Curve.EaseInOut,
            iterations: 2,
            playMode: PlayMode.Alternate,
            onFinish: () => {
              console.info('Image animation completed')
            }
          }, () => {
            this.scaleValue = 2.0
            this.opacityValue = 0.5
          })
        })
        .scale({ x: this.scaleValue, y: this.scaleValue })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

