@Entry
@Component
struct DebounceClickApp {
  @State lastClickTime: number = 0;
  @State debounceTime: number = 300; // Default debounce time in ms
  @State clickCount: number = 0;

  build() {
    Column() {
      Button('Click Me')
        .margin(30)
        .onClick(() => {
          const currentTime = new Date().getTime();
          if (currentTime - this.lastClickTime > this.debounceTime) {
            this.lastClickTime = currentTime;
            this.clickCount += 1;
            console.info(`Valid click at: ${currentTime}, total clicks: ${this.clickCount}`);
          } else {
            console.info(`Click debounced, last valid click was at: ${this.lastClickTime}`);
          }
        })

      Text(`Debounce Time: ${this.debounceTime}ms`)
        .margin({ top: 20 })
      Text(`Valid Click Count: ${this.clickCount}`)
        .margin({ top: 10 })
    }
    .width('100%')
    .margin({ top: 20 })
  }
}

