@Entry
@Component
struct ClickSequenceAnalyzer {
  @State clickTimes: number[] = [];
  @State lastClickTime: number = 0;
  @State sequenceTiming: string = '';

  build() {
    Column() {
      Button("Track Clicks")
        .onClick(() => {
          const currentTime: number = new Date().getTime();
          if (this.lastClickTime !== 0) {
            const timeDiff: number = currentTime - this.lastClickTime;
            this.clickTimes.push(timeDiff);
            this.sequenceTiming = `Click ${this.clickTimes.length}: ${timeDiff} ms`;
          }
          this.lastClickTime = currentTime;
        })
        .margin({ bottom: 20 })
        .width(200)

      Text("Click Sequence Timing Analysis")
        .fontSize(20)
        .margin({ bottom: 10 })

      ForEach(this.clickTimes, (time: number, index: number) => {
        Text(`Sequence ${index + 1}: ${time} ms`)
          .fontSize(16)
          .margin({ bottom: 5 })
      })

      Text(this.sequenceTiming)
        .fontSize(18)
        .margin({ top: 20 })
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct NetworkLagSimulator {
    @State isLoading: boolean = false
    @State data: string = ''
    @State lagDuration: number = 2000 // Default 2 seconds delay
    @State showSettings: boolean = false

    build() {
        Column() {
            Text('Network Lag Simulator')
                .fontSize(24)
                .fontWeight(FontWeight.Bold)
                .margin({ bottom: 20 })

            Button('Settings')
                .width('30%')
                .height(40)
                .onClick(() => {
                    this.showSettings = !this.showSettings
                })
                .margin({ bottom: 20 })

            if (this.showSettings) {
                Column() {
                    Slider({
                        value: this.lagDuration,
                        min: 0,
                        max: 5000,
                        step: 500,
                        style: SliderStyle.OutSet
                    })
                    .width('80%')
                    .onChange((value: number) => {
                        this.lagDuration = value
                    })
                    .margin({ bottom: 20 })

                    Text(`Simulated Lag: ${this.lagDuration}ms`)
                        .fontSize(16)
                        .margin({ bottom: 20 })
                }
            }

            Button('Fetch Data with Lag')
                .width('80%')
                .height(50)
                .onClick(() => {
                    this.simulateNetworkRequest()
                })
                .margin({ bottom: 20 })

            if (this.isLoading) {
                LoadingIndicator()
                    .width(50)
                    .height(50)
                    .margin({ bottom: 20 })
            }

            Text(this.data)
                .fontSize(18)
                .textAlign(TextAlign.Center)
        }
        .width('100%')
        .height('100%')
        .padding(20)
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center)
    }

    private simulateNetworkRequest() {
        this.isLoading = true
        this.data = ''

        // Simulate network lag using setTimeout
        setTimeout(() => {
            this.data = 'Data received after simulated lag'
            this.isLoading = false
        }, this.lagDuration)
    }
}

@Component
struct LoadingIndicator {
    @State rotation: number = 0
    private intervalID: number = -1

    aboutToAppear() {
        this.intervalID = setInterval(() => {
            this.rotation = (this.rotation + 10) % 360
        }, 50)
    }

    aboutToDisappear() {
        clearInterval(this.intervalID)
    }

    build() {
        Stack() {
            Image($r('app.media.app_icon'))
                .width(50)
                .height(50)
                .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })
        }
    }
}

