@Entry
@Component
struct TimeBasedClickPatternDetection {
  @State clickTimes: number[] = [];
  @State patternDetected: boolean = false;

  build() {
    Column() {
      Button('Click Me')
        .margin(30)
        .onClick(() => {
          const currentTime = new Date().getTime();
          this.clickTimes.push(currentTime);

          if (this.clickTimes.length >= 3) {
            const timeDiff1 = this.clickTimes[this.clickTimes.length - 1] - this.clickTimes[this.clickTimes.length - 2];
            const timeDiff2 = this.clickTimes[this.clickTimes.length - 2] - this.clickTimes[this.clickTimes.length - 3];

            if (Math.abs(timeDiff1 - timeDiff2) < 100) {
              this.patternDetected = true;
            } else {
              this.patternDetected = false;
            }
          }
        })

      if (this.patternDetected) {
        Text('Pattern Detected!')
          .fontSize(24)
          .margin({ top: 20 })
      } else {
        Text('No Pattern Detected')
          .fontSize(24)
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .padding(20)
  }
}

