@Component
struct UserRegistrationForm {
  @State name: string = ''
  @State email: string = ''
  @State password: string = ''
  @State successMessage: string = ''
  @State errorMessage: string = ''

  validateForm(): boolean {
    if (!this.name || !this.email || !this.password) {
      this.errorMessage = 'All fields are required'
      return false
    }
    this.errorMessage = ''
    return true
  }

  build() {
    Column() {
      Text('User Registration')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your name' })
        .onChange((value: string) => {
          this.name = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your email' })
        .onChange((value: string) => {
          this.email = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .margin({ bottom: 20 })

      Button('Submit')
        .onClick(() => {
          if (this.validateForm()) {
            this.successMessage = `Registration successful!\nName: ${this.name}\nEmail: ${this.email}`
            this.name = ''
            this.email = ''
            this.password = ''
          }
        })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ bottom: 20 })
      }

      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(18)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct DragDropSortList {
  @State items: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4', 'Item 5']
  @State draggingIndex: number = -1
  @State targetIndex: number = -1
  @State prevY: number = 0

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.items, (item: string, index: number) => {
          ListItem() {
            Text(item)
              .fontSize(20)
              .width('100%')
              .height(60)
              .backgroundColor(this.draggingIndex === index ? '#e0e0e0' : '#f5f5f5')
              .borderRadius(8)
              .onTouch((event: TouchEvent) => {
                if (event.type === TouchType.Down) {
                  this.draggingIndex = index
                  this.prevY = event.touches[0].y
                } else if (event.type === TouchType.Move) {
                  const currentY = event.touches[0].y
                  this.targetIndex = Math.min(Math.max(0, index + (currentY > this.prevY ? 1 : -1)), this.items.length - 1)
                  this.prevY = currentY
                } else if (event.type === TouchType.Up) {
                  if (this.draggingIndex >= 0 && this.targetIndex >= 0 && this.draggingIndex !== this.targetIndex) {
                    const newItems = [...this.items]
                    const removed = newItems[this.draggingIndex]
                    newItems.splice(this.draggingIndex, 1)
                    newItems.splice(this.targetIndex, 0, removed)
                    this.items = newItems
                  }
                  this.draggingIndex = -1
                  this.targetIndex = -1
                }
              })
          }
          .opacity(this.draggingIndex === index ? 0.5 : 1)
        })
      }
      .width('100%')
      .height('100%')
      .divider({ strokeWidth: 1, color: '#cccccc' })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

