@Entry
@Component
struct BMICalculator {
  @State heightInCm: string = ''
  @State weightInKg: string = ''
  @State bmiResult: string = ''
  @State errorMessage: string = ''

  calculateBMI() {
    const heightInM = parseFloat(this.heightInCm) / 100
    const weightKg = parseFloat(this.weightInKg)

    if (isNaN(heightInM) || isNaN(weightKg) || heightInM <= 0 || weightKg <= 0) {
      this.errorMessage = 'Please enter valid height and weight values.'
      this.bmiResult = ''
      return
    }

    const bmi = weightKg / (heightInM * heightInM)
    this.bmiResult = `Your BMI is ${bmi.toFixed(1)}`

    if (bmi < 18.5) this.bmiResult += ' (Underweight)'
    else if (bmi < 25) this.bmiResult += ' (Normal)'
    else if (bmi < 30) this.bmiResult += ' (Overweight)'
    else this.bmiResult += ' (Obese)'

    this.errorMessage = ''
  }

  build() {
    Column() {
      Text('BMI Calculator')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 })

      Text('Height (cm)')
        .fontSize(18)
        .margin({ bottom: 10 })
      TextInput({ placeholder: 'Enter height (cm)', text: this.heightInCm })
        .type(InputType.Number)
        .onChange((value: string) => {
          this.heightInCm = value
        })
        .margin({ bottom: 20 })

      Text('Weight (kg)')
        .fontSize(18)
        .margin({ bottom: 10 })
      TextInput({ placeholder: 'Enter weight (kg)', text: this.weightInKg })
        .type(InputType.Number)
        .onChange((value: string) => {
          this.weightInKg = value
        })
        .margin({ bottom: 20 })

      Button('Calculate BMI')
        .onClick(() => this.calculateBMI())
        .width('80%')
        .margin({ bottom: 20 })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(16)
          .fontColor(Color.Red)
          .margin({ bottom: 20 })
      }

      if (this.bmiResult) {
        Text(this.bmiResult)
          .fontSize(24)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

