@Entry
@Component
struct WeekDayFormatter {
  @State weekDays: string[] = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
  @State formattedDays: string[] = []
  @State formatType: string = 'short' // Options: 'short', 'full'

  aboutToAppear() {
    this.formatDays()
  }

  formatDays() {
    if (this.formatType === 'short') {
      this.formattedDays = this.weekDays.map(day => day.substring(0, 3))
    } else {
      this.formattedDays = [...this.weekDays]
    }
  }

  build() {
    Column() {
      Text('Week Day Formatter')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      Row() {
        Button('Short Format')
          .onClick(() => {
            this.formatType = 'short'
            this.formatDays()
          })
          .margin({ right: 10 })

        Button('Full Format')
          .onClick(() => {
            this.formatType = 'full'
            this.formatDays()
          })
      }
      .margin({ bottom: 20 })

      Text('Formatted Days:')
        .fontSize(18)
        .margin({ bottom: 10 })

      ForEach(this.formattedDays, (day: string) => {
        Text(day)
          .fontSize(16)
          .margin({ top: 5 })
      })
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

import promptAction from '@ohos.promptAction';

interface Message {
  user: string;
  text: string;
  color: string;
}

@Entry
@Component
struct ChatApp {
  @State messages: Message[] = [
    { user: 'Alice', text: 'Hello everyone!', color: '#FF0000' },
    { user: 'Bob', text: 'Hi Alice!', color: '#0000FF' },
    { user: 'Charlie', text: 'Hey guys!', color: '#00FF00' }
  ];

  @State newMessage: string = '';

  build() {
    Column() {
      // Chat Header
      Text('Chat Room')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      // Chat Messages
      List({ space: 10 }) {
        ForEach(this.messages, (message: Message) => {
          ListItem() {
            Column() {
              Text(message.user)
                .fontSize(16)
                .fontWeight(FontWeight.Medium)
                .fontColor(message.color)
                .margin({ bottom: 4 });

              Text(message.text)
                .fontSize(14)
                .fontColor('#333333')
                .padding(10)
                .backgroundColor('#F5F5F5')
                .borderRadius(8);
            }
            .margin({ bottom: 10 });
          };
        });
      }
      .layoutWeight(1)
      .padding(10);

      // Message Input
      Row() {
        TextInput({ placeholder: 'Type a message...' })
          .width('80%')
          .height(40)
          .backgroundColor('#FFFFFF')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.newMessage = value;
          });

        Button('Send')
          .width('20%')
          .height(40)
          .fontSize(16)
          .backgroundColor('#007AFF')
          .onClick(() => {
            if (this.newMessage.trim()) {
              this.messages.push({
                user: 'You',
                text: this.newMessage,
                color: '#FFA500'
              });
              this.newMessage = '';
            } else {
              promptAction.showToast({
                message: 'Message cannot be empty'
              });
            }
          });
      }
      .padding(10)
      .backgroundColor('#FFFFFF');
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F0F0F0');
  }
}

