@Entry
@Component
struct LoginScreen {
  @State email: string = ''
  @State password: string = ''
  @State errorMessage: string = ''
  @State showError: boolean = false
  @State isSuccess: boolean = false

  build() {
    Column() {
      // Email Label and Input
      Text('Email')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your email', text: this.email })
        .onChange((value: string) => {
          this.email = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Password Label and Input
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Login Button
      Button('Login')
        .onClick(() => {
          if (this.validateCredentials()) {
            this.errorMessage = 'Login successful!'
            this.showError = true
            this.isSuccess = true
          } else {
            this.errorMessage = 'Invalid email or password.'
            this.showError = true
            this.isSuccess = false
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      // Error Message Display
      if (this.showError) {
        Text(this.errorMessage)
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
          .fontColor(this.isSuccess ? Color.Green : Color.Red)
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }

  validateCredentials() {
    // Validate email format
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    const isEmailValid = emailRegex.test(this.email)

    // Validate password length
    const isPasswordValid = this.password.length >= 6

    return isEmailValid && isPasswordValid
  }
}

