@Entry
@Component
struct UserForm {
  @State name: string = '';
  @State email: string = '';
  @State showDialog: boolean = false;

  build() {
    Column() {
      // Form Title
      Text('Contact Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      // Name Input
      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value;
          });
      }

      // Email Input
      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value;
          });
      }

      // Submit Button
      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .fontColor(Color.White)
        .onClick(() => {
          if (this.name && this.email) {
            this.showDialog = true;
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields'
            });
          }
        });

      // Dialog
      if (this.showDialog) {
        Column() {
          Text('Submitted Information')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Name: ${this.name}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .width('100%')
            .height(50)
            .fontSize(18)
            .backgroundColor('#007AFF')
            .fontColor(Color.White)
            .onClick(() => {
              this.showDialog = false;
              // Clear form fields after submission
              this.name = '';
              this.email = '';
            });
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

@Entry
@Component
struct CountryListApp {
  @State selectedCountry: Country | null = null;

  private countries: Country[] = [
    { name: 'United States', flag: 'app.media.app_icon.us' },
    { name: 'Canada', flag: 'app.media.app_icon.ca' },
    { name: 'France', flag: 'app.media.app_icon.fr' },
    { name: 'Japan', flag: 'app.media.app_icon.jp' }
  ];

  dialogController: CustomDialogController = new CustomDialogController({
    builder: this.DialogBuilder,
    customStyle: true,
    alignment: DialogAlignment.Center
  });

  @Builder DialogBuilder() {
    if (this.selectedCountry) {
      Column() {
        Image(this.selectedCountry.flag)
          .width(150)
          .height(100)
          .objectFit(ImageFit.Cover)
          .margin({ bottom: 16 });

        Text(this.selectedCountry.name)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 16 });

        Button('Close')
          .width('100%')
          .height(40)
          .onClick(() => {
            this.dialogController.close();
          });
      }
      .padding(24)
      .width('80%')
      .backgroundColor(Color.White)
      .borderRadius(16);
    }
  }

  build() {
    Column() {
      Text('Countries List')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      List() {
        ForEach(this.countries, (country: Country) => {
          ListItem() {
            Row() {
              Image(country.flag)
                .width(50)
                .height(30)
                .objectFit(ImageFit.Cover)
                .margin({ right: 10 });

              Text(country.name)
                .fontSize(20)
                .fontWeight(FontWeight.Normal);
            }
            .padding(10)
            .onClick(() => {
              this.selectedCountry = country;
              this.dialogController.open();
            });
          }
          .backgroundColor('#FFFFFF')
          .borderRadius(5)
          .margin({ bottom: 10 });
        });
      }
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5');
  }
}

interface Country {
  name: string;
  flag: string;
}

@Entry
@Component
struct MainApp {
  @State currentIndex: number = 0

  build() {
    Column() {
      // Content Area
      Column() {
        if (this.currentIndex === 0) {
          this.HomeTab()
        } else if (this.currentIndex === 1) {
          this.ProfileTab()
        } else {
          this.SettingsTab()
        }
      }
      .width('100%')
      .layoutWeight(1)

      // Bottom Navigation Bar
      Row() {
        // Home Tab
        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Home')
            .fontSize(12)
            .fontColor(this.currentIndex === 0 ? '#1698CE' : '#666666')
        }
        .width('33.33%')
        .onClick(() => this.currentIndex = 0)

        // Profile Tab
        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Profile')
            .fontSize(12)
            .fontColor(this.currentIndex === 1 ? '#1698CE' : '#666666')
        }
        .width('33.33%')
        .onClick(() => this.currentIndex = 1)

        // Settings Tab
        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Settings')
            .fontSize(12)
            .fontColor(this.currentIndex === 2 ? '#1698CE' : '#666666')
        }
        .width('33.33%')
        .onClick(() => this.currentIndex = 2)
      }
      .width('100%')
      .height(60)
      .backgroundColor(Color.White)
      .border({ width: { top: 0.5 }, color: '#cccccc' })
    }
  }

  @Builder HomeTab() {
    Column() {
      Text('Home')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      List() {
        ForEach([1, 2, 3, 4, 5], (item:number) => {
          ListItem() {
            Column() {
              Text(`Home Content ${item}`)
                .fontSize(16)
                .padding(16)
            }
            .width('100%')
            .backgroundColor(Color.White)
            .borderRadius(8)
            .margin({ bottom: 10 })
          }
        })
      }
      .width('100%')
      .padding({ left: 16, right: 16 })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }

  @Builder ProfileTab() {
    Column() {
      Text('Profile')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .borderRadius(50)
        .margin({ bottom: 16 })

      Text('User Name')
        .fontSize(20)
        .fontWeight(FontWeight.Medium)
        .margin({ bottom: 8 })

      Text('user@email.com')
        .fontSize(16)
        .fontColor('#666666')
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }

  @Builder SettingsTab() {
    Column() {
      Text('Settings')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      List() {
        ForEach(['Account', 'Notifications', 'Privacy', 'Help', 'About'], (item:string) => {
          ListItem() {
            Row() {
              Text(item)
                .fontSize(16)
              Blank()
              Image($r('app.media.app_icon'))
                .width(20)
                .height(20)
            }
            .width('100%')
            .padding(16)
            .backgroundColor(Color.White)
          }
          .margin({ bottom: 1 })
        })
      }
      .width('100%')
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }
}

