@Entry
@Component
struct ImageFitConfiguration {
  build() {
    Column() {
      Text('ImageFit Configuration Examples')
        .fontSize(20)
        .margin({ bottom: 20 })

      Row() {
        Image($r('app.media.app_icon'))
          .width(150)
          .height(150)
          .border({ width: 2, color: Color.Black })
