        Image($r('app.media.app_icon'))
          .width(150)
          .height(150)
          .border({ width: 2, color: Color.Black })
          .objectFit(ImageFit.Cover)
          .overlay('Cover', { align: Alignment.Bottom, offset: { x: 0, y: 20 } })
      }
      .margin({ bottom: 10 })

      Row() {
        Image($r('app.media.app_icon'))
          .width(150)
          .height(150)
          .border({ width: 2, color: Color.Black })
          .objectFit(ImageFit.Fill)
          .overlay('Fill', { align: Alignment.Bottom, offset: { x: 0, y: 20 } })
      }
      .margin({ bottom: 10 })

      Row() {
        Image($r('app.media.app_icon'))
          .width(150)
          .height(150)
          .border({ width: 2, color: Color.Black })
          .objectFit(ImageFit.None)
          .overlay('None', { align: Alignment.Bottom, offset: { x: 0, y: 20 } })
      }
      .margin({ bottom: 10 })

      Row() {
        Image($r('app.media.app_icon'))
          .width(150)
          .height(150)
          .border({ width: 2, color: Color.Black })
          .objectFit(ImageFit.ScaleDown)
          .overlay('ScaleDown', { align: Alignment.Bottom, offset: { x: 0, y: 20 } })
      }
      .margin({ bottom: 10 })
    }
    .width('100%')
    .padding(20)
    .alignItems(HorizontalAlign.Center)
  }
}

@Entry
@Component
struct MainApp {
  @State currentIndex: number = 0
  @State name: string = ''
  @State email: string = ''

  build() {
    Column() {
      // Content Area
      Column() {
        if (this.currentIndex === 0) {
          this.ListTab()
        } else {
          this.FormTab()
        }
      }
      .width('100%')
      .layoutWeight(1)

      // Bottom Navigation Bar
      Row() {
        // List Tab
        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('List')
            .fontSize(12)
            .fontColor(this.currentIndex === 0 ? '#1698CE' : '#666666')
        }
        .width('50%')
        .onClick(() => {
          this.currentIndex = 0
        })

        // Form Tab
        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Form')
            .fontSize(12)
            .fontColor(this.currentIndex === 1 ? '#1698CE' : '#666666')
        }
        .width('50%')
        .onClick(() => {
          this.currentIndex = 1
        })
      }
      .width('100%')
      .height(60)
      .backgroundColor(Color.White)
      .border({ width: { top: 0.5 }, color: '#cccccc' })
    }
  }

  @Builder ListTab() {
    Column() {
      Text('List')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      List() {
        ForEach([1, 2, 3, 4, 5], (item: number) => {
          ListItem() {
            Row() {
              Image($r('app.media.app_icon'))
                .width(50)
                .height(50)
                .margin({ right: 16 })
              Text(`Item ${item}`)
                .fontSize(16)
            }
            .width('100%')
            .padding(16)
            .backgroundColor(Color.White)
            .borderRadius(8)
            .margin({ bottom: 10 })
          }
        })
      }
      .width('100%')
      .padding({ left: 16, right: 16 })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }

  @Builder FormTab() {
    Column() {
      Text('Form')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      TextInput({ placeholder: 'Name' })
        .width('80%')
        .height(40)
        .margin({ bottom: 16 })
        .onChange((value: string) => {
          this.name = value
        })

      TextInput({ placeholder: 'Email' })
        .width('80%')
        .height(40)
        .margin({ bottom: 16 })
        .onChange((value: string) => {
          this.email = value
        })

      Button('Submit')
        .width('80%')
        .height(40)
        .backgroundColor('#1698CE')
        .fontColor(Color.White)
        .onClick(() => {
          console.log(`Name: ${this.name}, Email: ${this.email}`)
        })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }
}

@Entry
@Component
struct ApiDataListApp {
  @State private items: Item[] = [];
  @State private isLoading: boolean = true;
  @State private selectedItem: Item | null = null;

  dialogController: CustomDialogController = new CustomDialogController({
    builder: this.DialogBuilder,
    customStyle: true,
    alignment: DialogAlignment.Center
  });

  aboutToAppear() {
    this.fetchData();
  }

  fetchData() {
    setTimeout(() => {
      this.items = [
        {
          id: 1,
          title: 'Mountain View',
          image: $r('app.media.app_icon'),
          description: 'A beautiful mountain landscape with snow-capped peaks and green valleys.'
        },
        {
          id: 2,
          title: 'Beach Sunset',
          image: $r('app.media.app_icon'),
          description: 'Golden sunset over a tropical beach with palm trees.'
        },
        {
          id: 3,
          title: 'City Lights',
          image: $r('app.media.app_icon'),
          description: 'Modern cityscape at night with glowing skyscrapers.'
        }
      ];
      this.isLoading = false;
    }, 2000);
  }

  @Builder DialogBuilder() {
    if (this.selectedItem) {
      Column() {
        Image(this.selectedItem.image)
          .width('100%')
          .height(200)
          .borderRadius(8)
          .objectFit(ImageFit.Cover);

        Text(this.selectedItem.title)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 16, bottom: 8 });

        Text(this.selectedItem.description)
          .fontSize(16)
          .lineHeight(24);

        Button('Close')
          .onClick(() => {
            this.dialogController.close();
          });
      }
      .padding(24)
      .width('90%')
      .backgroundColor(Color.White)
      .borderRadius(16);
    }
  }

  build() {
    Column() {
      Text('API Data List')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      if (this.isLoading) {
        Text('Loading data...')
          .fontSize(18)
          .margin({ top: 20 });
      } else {
        List() {
          ForEach(this.items, (item: Item) => {
            ListItem() {
              Row() {
                Image(item.image)
                  .width(100)
                  .height(100)
                  .borderRadius(8)
                  .objectFit(ImageFit.Cover);

                Text(item.title)
                  .fontSize(20)
                  .fontWeight(FontWeight.Medium)
                  .margin({ left: 16 });
              }
              .padding(16)
              .onClick(() => {
                this.selectedItem = item;
                this.dialogController.open();
              });
            }
            .margin({ bottom: 12 });
          });
        }
        .width('100%');
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }
}

interface Item {
  id: number;
  title: string;
  image: Resource;
  description: string;
}

import { promptAction } from '@kit.ArkUI';

interface MenuItem {
  value: Resource;
  isEnabled?: boolean;
  action?: () => void;
}

@Entry
@Component
struct Index {
  @State title: string = "Main Title";
  @State subtitle: string = "Subtitle";
  @State menuItems: MenuItem[] = [
    {
      value: $r('app.media.app_icon'),
      isEnabled: true,
      action: () => promptAction.showToast({ message: "Menu Item 1 clicked" })
    },
    {
      value: $r('app.media.app_icon'),
      isEnabled: true,
      action: () => promptAction.showToast({ message: "Menu Item 2 clicked" })
    }
  ];

  build() {
    Column() {
      // Title Bar Section
      Row() {
        Column() {
          Text(this.title)
            .fontSize(24)
            .fontWeight(FontWeight.Bold);
          Text(this.subtitle)
            .fontSize(16)
            .margin({ top: 4 });
        }
        .layoutWeight(1)

        // Menu Items
        Row() {
          ForEach(this.menuItems, (item: MenuItem) => {
            Button() {
              Image(item.value)
                .width(24)
                .height(24)
            }
            .enabled(item.isEnabled ?? true)
            .onClick(() => {
              if (item.action) {
                item.action();
              }
            })
            .margin({ left: 10 });
          });
        }
      }
      .width('100%')
      .padding(16)

      Divider()
        .strokeWidth(1)
        .color(Color.Gray)
        .margin({ left: 16, right: 16 })

      // Content Area
      Column() {
        Text("Main Content")
          .fontSize(18)
          .margin(20);
      }
      .width('100%')
      .height('100%')
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
  }
}

