@Entry
@Component
struct AuditTrailConfiguration {
  @State auditLogs: Array<string> = [];
  @State criticalActions: number = 0;

  logCriticalAction(action: string) {
    const timestamp = new Date().toLocaleString();
    const logEntry = `[${timestamp}] CRITICAL ACTION: ${action}`;
    this.auditLogs.unshift(logEntry);
    this.criticalActions += 1;
    console.info(logEntry);
  }

  logRegularAction(action: string) {
    const timestamp = new Date().toLocaleString();
    const logEntry = `[${timestamp}] REGULAR ACTION: ${action}`;
    this.auditLogs.unshift(logEntry);
    console.info(logEntry);
  }

  build() {
    Column({ space: 20 }) {
      Text('Critical Sections Audit Trail')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row({ space: 15 }) {
        Button('Admin Access')
          .onClick(() => {
            this.logCriticalAction('Admin access granted');
            promptAction.showToast({ message: 'Admin access logged', duration: 1000 });
          })
          .backgroundColor('#FF4500')
          .fontColor(Color.White);

        Button('Database Write')
          .onClick(() => {
            this.logCriticalAction('Database write operation');
            promptAction.showToast({ message: 'Database write logged', duration: 1000 });
          })
          .backgroundColor('#FF4500')
          .fontColor(Color.White);
      }

      Row({ space: 15 }) {
        Button('User Profile')
          .onClick(() => {
            this.logRegularAction('User profile accessed');
            promptAction.showToast({ message: 'Profile access logged', duration: 1000 });
          });

        Button('Settings')
          .onClick(() => {
            this.logRegularAction('Settings accessed');
            promptAction.showToast({ message: 'Settings access logged', duration: 1000 });
          });
      }

      Text(`Critical Actions Count: ${this.criticalActions}`)
        .fontSize(16)
        .margin({ top: 20 })
        .fontColor(Color.Red);

      Text('Audit Logs')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 10 });

      if (this.auditLogs.length > 0) {
        List({ space: 10 }) {
          ForEach(this.auditLogs, (log: string) => {
            ListItem() {
              Text(log)
                .fontSize(14)
                .margin(5)
                .fontColor(log.includes('CRITICAL') ? Color.Red : Color.Black);
            }
          });
        }
        .height(250)
        .width('100%')
        .border({ width: 1, color: Color.Gray });
      } else {
        Text('No audit logs available')
          .fontSize(16)
          .fontColor(Color.Gray);
      }
    }
    .padding(20)
    .width('100%')
    .height('100%');
  }
}

