@Entry
@Component
struct ComplexClickPatternRecognition {
  @State private clickPattern: number[] = [];
  @State private clickTimes: number[] = [];
  @State private message: string = 'Draw your pattern by clicking the circles in sequence.';
  @State private patternDetected: boolean = false;

  build() {
    Column() {
      Text(this.message)
        .fontSize(20)
        .margin(20)
        .textAlign(TextAlign.Center);

      Row() {
        ForEach([0, 1, 2], (index: number) => {
          Circle()
            .width(50)
            .height(50)
            .fill(Color.Gray)
            .margin(10)
            .onClick(() => {
              const currentTime = new Date().getTime();
              this.clickPattern.push(index);
              this.clickTimes.push(currentTime);
              this.message = `Pattern so far: ${this.clickPattern.join(', ')}`;

              if (this.clickPattern.length === 3) {
                this.validatePattern();
              }
            });
        });
      }
      .justifyContent(FlexAlign.Center)
      .margin(20);

      if (this.patternDetected) {
        Text('Pattern Detected!')
          .fontSize(24)
          .margin({ top: 20 });
      } else {
        Text('No Pattern Detected')
          .fontSize(24)
          .margin({ top: 20 });
      }

      Button('Reset Pattern')
        .margin(20)
        .onClick(() => {
          this.clickPattern = [];
          this.clickTimes = [];
          this.message = 'Draw your pattern by clicking the circles in sequence.';
          this.patternDetected = false;
        });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }

  private validatePattern(): void {
    const correctPattern: number[] = [0, 1, 2];
    let isSequenceCorrect = this.clickPattern.toString() === correctPattern.toString();

    let isTimePatternCorrect = true;
    for (let i = 1; i < this.clickTimes.length; i++) {
      const diff = this.clickTimes[i] - this.clickTimes[i - 1];
      if (diff > 500) {
        isTimePatternCorrect = false;
        break;
      }
    }

    if (isSequenceCorrect && isTimePatternCorrect) {
      this.message = 'Pattern recognized correctly!';
      this.patternDetected = true;
    } else {
      this.message = 'Incorrect pattern, please try again.';
      this.patternDetected = false;
    }
    this.clickPattern = [];
    this.clickTimes = [];
  }
}

