@Entry
@Component
struct AnimationCallbackExample {
  @State private isAnimationComplete: boolean = false;
  @State private scaleValue: number = 1.0;

  private onAnimationComplete() {
    this.isAnimationComplete = true;
    console.log("Animation completion callback triggered");
  }

  private startAnimation() {
    this.isAnimationComplete = false;
    animateTo({
      duration: 1000,
      curve: Curve.EaseInOut,
      onFinish: this.onAnimationComplete.bind(this)
    }, () => {
      this.scaleValue = 0.5;
    });
  }

  private resetAnimation() {
    this.scaleValue = 1.0;
    this.isAnimationComplete = false;
  }

  build() {
    Column() {
      Text(this.isAnimationComplete ? "Animation Complete!" : "Ready to Animate")
        .fontSize(20)
        .margin({ bottom: 20 });

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .opacity(this.isAnimationComplete ? 0.7 : 1.0)
        .margin({ bottom: 20 });

      Button(this.isAnimationComplete ? "Reset" : "Start Animation")
        .onClick(() => {
          if (this.isAnimationComplete) {
            this.resetAnimation();
          } else {
            this.startAnimation();
          }
        })
        .width(150)
        .height(40)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor($r('sys.color.ohos_id_color_background'));
  }
}

