            .margin({ bottom: 4 })
          Text('Form')
            .fontSize(12)
            .fontColor(this.currentIndex === 1 ? '#1698CE' : '#666666')
        }
        .width('50%')
        .onClick(() => this.currentIndex = 1)
      }
      .width('100%')
      .height(60)
      .backgroundColor(Color.White)
      .border({ width: { top: 0.5 }, color: '#cccccc' })
    }
  }

  @Builder ImageListTab() {
    Column() {
      Text('Image Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      List() {
        ForEach([1, 2, 3, 4, 5], (item: number) => {
          ListItem() {
            Column() {
              Image($r('app.media.app_icon'))
                .width(200)
                .height(200)
                .borderRadius(8)
                .margin({ bottom: 10 })
              Text(`Image ${item}`)
                .fontSize(16)
                .margin({ bottom: 10 })
            }
            .width('100%')
            .backgroundColor(Color.White)
            .borderRadius(8)
            .margin({ bottom: 10 })
            .padding(10)
          }
        })
      }
      .width('100%')
      .padding({ left: 16, right: 16 })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }

  @Builder FormTab() {
    Column() {
      Text('Contact Form')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      TextInput({ placeholder: 'Enter your name' })
        .width('80%')
        .height(40)
        .margin({ bottom: 16 })
        .onChange((value: string) => {
          this.name = value
          this.validateForm()
        })

      TextInput({ placeholder: 'Enter your email' })
        .width('80%')
        .height(40)
        .margin({ bottom: 16 })
        .onChange((value: string) => {
          this.email = value
          this.validateForm()
        })

      Button('Submit')
        .width('80%')
        .height(40)
        .backgroundColor(this.isFormValid ? '#1698CE' : '#CCCCCC')
        .fontColor(Color.White)
        .onClick(() => {
          if (this.isFormValid) {
            console.log(`Form submitted: Name=${this.name}, Email=${this.email}`)
          }
        })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }

  validateForm() {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    this.isFormValid = this.name.trim() !== '' && emailRegex.test(this.email)
  }
}

