  build() {
    Column() {
      TextInput({ text: this.text, placeholder: 'Enter text...' })
        .width('80%')
        .height(40)
        .margin(20)
        .fontSize(14)
        .fontColor(Color.Black)
        .inputFilter('[A-Za-z0-9]', (e: string) => {
          console.log('Filtered character: ' + e)
        })
        .onChange((value: string) => {
          this.text = value
        })

      Text('Filtered Text: ' + this.text)
        .fontSize(16)
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White)
  }
}

