import promptAction from '@ohos.promptAction';

@Entry
@Component
struct UserForm {
  @State name: string = '';
  @State email: string = '';
  @State phoneNumber: string = '';
  @State showSuccessMessage: boolean = false;

  build() {
    Column() {
      // Form Title
      Text('User Registration')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      // Name Input
      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value;
          });
      }

      // Email Input
      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value;
          });
      }

      // Phone Number Input
      Column() {
        Text('Phone Number:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your phone number' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.phoneNumber = value;
          });
      }

      // Submit Button
      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.name && this.email && this.phoneNumber) {
            this.showSuccessMessage = true;
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields'
            });
          }
        });

      // Success Message
      if (this.showSuccessMessage) {
        Column() {
          Text('Form Submitted Successfully!')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Name: ${this.name}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Phone Number: ${this.phoneNumber}`)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.showSuccessMessage = false;
              this.name = '';
              this.email = '';
              this.phoneNumber = '';
            });
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

@Entry
@Component
struct MonthDisplayVariation {
  @State currentMonth: number = new Date().getMonth() + 1
  @State currentYear: number = new Date().getFullYear()
  @State displayMode: string = 'numeric' // 'numeric', 'text', or 'short'

  getMonthName(month: number): string {
    const months = ['January', 'February', 'March', 'April', 'May', 'June',
                   'July', 'August', 'September', 'October', 'November', 'December']
    return months[month - 1]
  }

  getShortMonthName(month: number): string {
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
                   'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
    return months[month - 1]
  }

  build() {
    Column() {
      Text('Month Display Variations')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      // Display current month based on mode
      Column() {
        if (this.displayMode === 'numeric') {
          Text(`Current Month: ${this.currentMonth}/${this.currentYear}`)
            .fontSize(24)
        } else if (this.displayMode === 'text') {
          Text(`Current Month: ${this.getMonthName(this.currentMonth)} ${this.currentYear}`)
            .fontSize(24)
        } else {
          Text(`Current Month: ${this.getShortMonthName(this.currentMonth)} ${this.currentYear}`)
            .fontSize(24)
        }
      }
      .margin({ bottom: 20 })

      // Month navigation buttons
      Row() {
        Button('Previous Month')
          .onClick(() => {
            if (this.currentMonth === 1) {
              this.currentMonth = 12
              this.currentYear -= 1
            } else {
              this.currentMonth -= 1
            }
          })
          .margin({ right: 10 })

        Button('Next Month')
          .onClick(() => {
            if (this.currentMonth === 12) {
              this.currentMonth = 1
              this.currentYear += 1
            } else {
              this.currentMonth += 1
            }
          })
      }
      .margin({ bottom: 20 })

      // Display mode selector
      Row() {
        Button('Numeric')
          .onClick(() => { this.displayMode = 'numeric' })
          .margin({ right: 10 })

        Button('Text')
          .onClick(() => { this.displayMode = 'text' })
          .margin({ right: 10 })

        Button('Short')
          .onClick(() => { this.displayMode = 'short' })
      }
      .margin({ bottom: 20 })

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 20 })

    }.width('100%').padding(20)
  }
}

