@Entry
struct DragAndDropList {
  @State private draggedItem: number = -1;
  @State private dropPosition: number = -1;
  @State private items: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4', 'Item 5'];

  build() {
    Column() {
      List() {
        ForEach(this.items, (item: string, index: number) => {
          ListItem() {
            Text(item)
              .opacity(this.draggedItem === index ? 0.8 : 1)
              .height(60)
              .width('100%')
              .borderRadius(4)
              .backgroundColor(this.draggedItem === index ? '#f0f0f0' : '#ffffff')
              .shadow(this.draggedItem === index ? { radius: 8, color: '#000000', offsetX: 2, offsetY: 2 } : undefined)
              .onTouch((event: TouchEvent) => {
                if (event.type === TouchType.Down) {
                  this.draggedItem = index;
                } else if (event.type === TouchType.Move) {
                  this.dropPosition = index;
                } else if (event.type === TouchType.Up) {
                  if (this.draggedItem !== -1 && this.dropPosition !== -1 && this.draggedItem !== this.dropPosition) {
                    const newItems = [...this.items];
                    const removedItem = newItems[this.draggedItem];
                    newItems.splice(this.draggedItem, 1);
                    newItems.splice(this.dropPosition, 0, removedItem);
                    this.items = newItems;
                  }
                  this.draggedItem = -1;
                  this.dropPosition = -1;
                }
              });
          }
        });
      }
      .height('100%')
      .width('100%')
    }
  }
}

