import promptAction from '@ohos.promptAction';

@Entry
@Component
struct FormInterface {
  @State name: string = '';
  @State email: string = '';
  @State password: string = '';
  @State showDialog: boolean = false;
  @State errorMessage: string = '';

  validateForm(): boolean {
    this.errorMessage = '';
    if (!this.name || !this.email || !this.password) {
      this.errorMessage = 'All fields are required';
      return false;
    }
    if (!this.validateEmail(this.email)) {
      this.errorMessage = 'Please enter a valid email address';
      return false;
    }
    return true;
  }

  validateEmail(email: string): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }

  build() {
    Column({ space: 20 }) {
      Text('User Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      TextInput({ placeholder: 'Enter your name' })
        .onChange((value: string) => {
          this.name = value;
        })
        .width('100%')
        .height(40)
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .margin({ bottom: 20 });

      TextInput({ placeholder: 'Enter your email' })
        .onChange((value: string) => {
          this.email = value;
        })
        .width('100%')
        .height(40)
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .margin({ bottom: 20 });

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value;
        })
        .width('100%')
        .height(40)
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .margin({ bottom: 30 });

      Button('Submit')
        .onClick(() => {
          if (this.validateForm()) {
            this.showDialog = true;
          } else {
            promptAction.showToast({
              message: this.errorMessage
            });
          }
        })
        .width('100%')
        .height(50)
        .backgroundColor('#007AFF')
        .fontSize(18)
        .fontColor(Color.White);

      if (this.showDialog) {
        Column() {
          Text('Submitted Information')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Name: ${this.name}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Password: ${'*'.repeat(this.password.length)}`)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.showDialog = false;
              this.name = '';
              this.email = '';
              this.password = '';
            })
            .width('100%')
            .height(50)
            .backgroundColor('#007AFF')
            .fontSize(18)
            .fontColor(Color.White);
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 10 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White);
  }
}

@Entry
@Component
struct TabBarApp {
  @State currentIndex: number = 0

  build() {
    Column() {
      // Content Area
      Column() {
        if (this.currentIndex === 0) {
          this.HomeTab()
        } else if (this.currentIndex === 1) {
          this.MessagesTab()
        } else {
          this.ProfileTab()
        }
      }
      .width('100%')
      .layoutWeight(1)

      // Tab Bar
      Row() {
        // Home Tab
        Column() {
          Text('Home')
            .fontSize(16)
            .fontColor(this.currentIndex === 0 ? '#1698CE' : '#666666')
