@Entry
@Component
struct MinuteDisplayConfig {
  @State currentTime: Date = new Date()
  @State showFullFormat: boolean = true

  build() {
    Column() {
      Text(this.formatMinutes(this.currentTime))
        .fontSize(30)
        .fontColor(Color.Black)
        .margin({ top: 20 })
        .onClick(() => {
          this.currentTime = new Date()
          this.showFullFormat = !this.showFullFormat
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }

  private formatMinutes(date: Date): string {
    const minutes = date.getMinutes()
    return this.showFullFormat
      ? `${this.padZero(date.getHours())}:${this.padZero(minutes)}`
      : `${minutes} minutes`
  }

  private padZero(num: number): string {
    return num < 10 ? `0${num}` : num.toString()
  }
}

