@Entry
@Component
struct AnimationAdapterExample {
  @State scaleValue: number = 1.0;
  @State rotationValue: number = 0;
  @State opacityValue: number = 1.0;
  @State isAnimating: boolean = false;

  private animationAdapter: UIContext | undefined = undefined;

  aboutToAppear() {
    this.animationAdapter = this.getUIContext?.();
  }

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(150)
        .height(150)
        .margin(20)
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .rotate({ angle: this.rotationValue })
        .opacity(this.opacityValue)
        .onClick(() => {
          if (!this.animationAdapter) return;

          this.isAnimating = true;
          this.animationAdapter.keyframeAnimateTo({ iterations: 1 }, [
            {
              duration: 300,
              event: () => {
                this.scaleValue = 1.5;
                this.rotationValue = 30;
                this.opacityValue = 0.8;
              }
            },
            {
              duration: 300,
              event: () => {
                this.scaleValue = 1.0;
                this.rotationValue = 0;
                this.opacityValue = 1.0;
              }
            }
          ]);
          this.isAnimating = false;
        });

      Text(this.isAnimating ? 'Animating...' : 'Tap to animate')
        .fontSize(18)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

