@Entry
@Component
struct FrameAnimationConfigurator {
  @State private currentFrameIndex: number = 0;
  private frameResources: Resource[] = [
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon')
  ];
  private animationInterval: number | null = null;
  @State private isPlaying: boolean = false;
  @State private animationSpeed: number = 200;
  @State private smoothTransition: boolean = true;

  aboutToDisappear() {
    this.stopAnimation();
  }

  private startAnimation() {
    if (this.animationInterval !== null) return;
    this.isPlaying = true;
    this.animationInterval = setInterval(() => {
      this.currentFrameIndex = (this.currentFrameIndex + 1) % this.frameResources.length;
    }, this.animationSpeed);
  }

  private stopAnimation() {
    if (this.animationInterval !== null) {
      clearInterval(this.animationInterval);
      this.animationInterval = null;
      this.isPlaying = false;
    }
  }

  private toggleAnimation() {
    if (this.isPlaying) {
      this.stopAnimation();
    } else {
      this.startAnimation();
    }
  }

  private adjustSpeed(newSpeed: number) {
    this.animationSpeed = Math.max(50, Math.min(1000, newSpeed));
    if (this.isPlaying) {
      this.stopAnimation();
      this.startAnimation();
    }
  }

  private toggleSmoothTransition() {
    this.smoothTransition = !this.smoothTransition;
  }

  build() {
    Column() {
      // Animation Display Area
      Stack() {
        ForEach(this.frameResources, (frame: Resource, index: number) => {
          Image(frame)
            .width(200)
            .height(200)
            .objectFit(ImageFit.Contain)
            .opacity(this.currentFrameIndex === index ? 1 : 0)
            .animation(this.smoothTransition ? { duration: 100, curve: Curve.Linear } : {});
        })
      }
      .width('100%')
      .height(300)
      .margin({ bottom: 20 });

      // Controls
      Row() {
        Button(this.isPlaying ? 'Pause' : 'Play')
          .onClick(() => this.toggleAnimation())
          .width(120)
          .height(40)
          .margin({ right: 10 });

        Button('Next Frame')
          .onClick(() => {
            this.stopAnimation();
            this.currentFrameIndex = (this.currentFrameIndex + 1) % this.frameResources.length;
          })
          .width(120)
          .height(40);

        Toggle({ type: ToggleType.Switch })
          .onChange(() => this.toggleSmoothTransition())
          .width(120)
          .height(40)
          .margin({ left: 10 });
      }
      .margin({ bottom: 20 });

      // Speed Control
      Text('Animation Speed: ' + this.animationSpeed + 'ms')
        .fontSize(16)
        .margin({ bottom: 10 });

      Slider({
        value: this.animationSpeed,
        min: 50,
        max: 1000,
        step: 50,
        style: SliderStyle.OutSet
      })
      .onChange((value: number) => this.adjustSpeed(value))
      .width('80%')
      .margin({ bottom: 20 });

      // Status Indicators
      Row() {
        Text('Current Frame: ' + (this.currentFrameIndex + 1) + '/' + this.frameResources.length)
          .fontSize(16)
          .margin({ right: 20 });

        Text('Smooth: ' + (this.smoothTransition ? 'ON' : 'OFF'))
          .fontSize(16);
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

