class Item {
  id: number;
  title: string;
  ratings: number[] = [];
  averageRating: number = 0;

  constructor(id: number, title: string) {
    this.id = id;
    this.title = title;
  }

  calculateAverageRating() {
    if (this.ratings.length === 0) {
      this.averageRating = 0;
    } else {
      this.averageRating = this.ratings.reduce((acc, curr) => acc + curr, 0) / this.ratings.length;
    }
  }
}

@Entry
@Component
struct AnimationStatusMonitor {
  @State private animationStatus: string = 'Idle'
  @State private rotationAngle: number = 0
  private animationInterval: number = -1

  private startAnimation() {
    if (this.animationInterval !== -1) return

    this.animationStatus = 'Running'
    this.animationInterval = setInterval(() => {
      this.rotationAngle = (this.rotationAngle + 5) % 360
    }, 50)
  }

  private pauseAnimation() {
    if (this.animationInterval === -1) return

    clearInterval(this.animationInterval)
    this.animationInterval = -1
    this.animationStatus = 'Paused'
  }

  private stopAnimation() {
    if (this.animationInterval === -1) return

    clearInterval(this.animationInterval)
    this.animationInterval = -1
    this.rotationAngle = 0
    this.animationStatus = 'Stopped'
  }

  private resetAnimation() {
    this.stopAnimation()
    this.animationStatus = 'Idle'
  }

  build() {
    Column() {
      Text('Animation Status Monitor')
        .fontSize(24)
        .margin({ bottom: 20 })

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .rotate({ x: 0, y: 0, z: 1, angle: this.rotationAngle })
        .margin({ bottom: 30 })

      Text(`Current Status: ${this.animationStatus}`)
        .fontSize(18)
        .margin({ bottom: 20 })

      Button('Start Animation')
        .onClick(() => this.startAnimation())
        .margin({ bottom: 10 })
        .width('70%')

      Button('Pause Animation')
        .onClick(() => this.pauseAnimation())
        .margin({ bottom: 10 })
        .width('70%')

      Button('Stop Animation')
        .onClick(() => this.stopAnimation())
        .margin({ bottom: 10 })
        .width('70%')

      Button('Reset Animation')
        .onClick(() => this.resetAnimation())
        .margin({ bottom: 10 })
        .width('70%')
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }

  aboutToDisappear() {
    if (this.animationInterval !== -1) {
      clearInterval(this.animationInterval)
    }
  }
}

@Entry
@Component
struct SecondPrecisionClock {
  @State currentTime: string = ''
  private timerId: number = -1

  aboutToAppear() {
    this.startTimer()
  }

  aboutToDisappear() {
    this.stopTimer()
  }

  startTimer() {
    this.updateTime()
    this.timerId = setInterval(() => {
      this.updateTime()
    }, 1000)
  }

  stopTimer() {
    if (this.timerId !== -1) {
      clearInterval(this.timerId)
      this.timerId = -1
    }
  }

  updateTime() {
    const now = new Date()
    const hours = now.getHours().toString().padStart(2, '0')
    const minutes = now.getMinutes().toString().padStart(2, '0')
    const seconds = now.getSeconds().toString().padStart(2, '0')
    this.currentTime = `${hours}:${minutes}:${seconds}`
  }

  build() {
    Column({ space: 20 }) {
      Text('Second Precision Clock')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .fontColor(Color.Black)

      Text(this.currentTime)
        .fontSize(48)
        .fontWeight(FontWeight.Bold)
        .fontColor(Color.Blue)

      Row({ space: 20 }) {
        Button('Start Timer')
          .width(140)
          .height(50)
          .backgroundColor('#4CAF50')
          .fontColor(Color.White)
          .onClick(() => {
            this.startTimer()
          })

        Button('Stop Timer')
          .width(140)
          .height(50)
          .backgroundColor('#F44336')
          .fontColor(Color.White)
          .onClick(() => {
            this.stopTimer()
          })
      }

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(20)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#F5F5F5')
  }
}

