@Entry
@Component
struct TextInputErrorDisplay {
  @State inputText: string = ''
  @State isValid: boolean = true
  @State errorMessage: string = ''

  validateInput(value: string) {
    if (value.length < 5) {
      this.errorMessage = 'Input must be at least 5 characters long.'
      this.isValid = false
    } else if (!/^[a-zA-Z]+$/.test(value)) {
      this.errorMessage = 'Input must contain only letters.'
      this.isValid = false
    } else {
      this.errorMessage = ''
      this.isValid = true
    }
  }

  build() {
    Column({ space: 10 }) {
      TextInput({ placeholder: 'Enter text (letters only)' })
        .width('90%')
        .height(50)
        .border({
          width: 1,
          color: this.isValid ? '#ccc' : '#ff0000'
        })
        .onChange((value: string) => {
          this.inputText = value
          this.validateInput(value)
        })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 5 })
      }

      Button('Submit')
        .enabled(this.isValid)
        .width('50%')
        .margin({ top: 20 })
        .onClick(() => {
          console.info('Valid input submitted:', this.inputText)
        })
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

@Entry
@Component
struct ImageCarouselWithZoom {
  private swiperController: SwiperController = new SwiperController();

  private carouselItems: CarouselItem[] = [
    { id: 1, image: $r('app.media.app_icon') },
    { id: 2, image: $r('app.media.app_icon') },
    { id: 3, image: $r('app.media.app_icon') },
    { id: 4, image: $r('app.media.app_icon') }
  ];

  @State currentIndex: number = 0;
  @State isZoomed: boolean = false;
  @State zoomedImage: Resource | null = null;

  build() {
    Column() {
      Text('Image Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Column() {
        Swiper(this.swiperController) {
          ForEach(this.carouselItems, (item: CarouselItem) => {
            Stack() {
              Image(item.image)
                .width(this.isZoomed ? '150%' : '100%')
                .height(this.isZoomed ? 450 : 300)
                .objectFit(ImageFit.Cover)
                .borderRadius(16)
                .onClick(() => {
                  this.isZoomed = !this.isZoomed;
                  this.zoomedImage = item.image;
                });
            }
          });
        }
        .width('100%')
        .height(300)
        .margin({ bottom: 16 })
        .autoPlay(true)
        .interval(3000)
        .indicator(true)
        .loop(true)
        .duration(500)
        .onChange((index: number) => {
          this.currentIndex = index;
          this.isZoomed = false;
        });

        if (this.isZoomed && this.zoomedImage) {
          Image(this.zoomedImage)
            .width('100%')
            .height(400)
            .objectFit(ImageFit.Contain)
            .margin({ top: 20 })
            .onClick(() => {
              this.isZoomed = false;
            });
        }
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(20);

      Row() {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });
        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

interface CarouselItem {
  id: number;
  image: Resource;
}

