      Text('Color Selection Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      // Name Input
      TextInput({ placeholder: 'Enter your name' })
        .onChange((value: string) => {
          this.name = value
        })
        .margin({ bottom: 20 })

      // Email Input
      TextInput({ placeholder: 'Enter your email' })
        .onChange((value: string) => {
          this.email = value
        })
        .margin({ bottom: 20 })

      // Color Dropdown
      Text('Select a color:')
        .fontSize(16)
        .margin({ bottom: 8 })
      Row() {
        Text(this.selectedColor)
          .margin({ right: 10 })
        Button('\u25bc')
          .onClick(() => {
            this.showColorPicker = true
          })
      }
      .margin({ bottom: 20 })

      if (this.showColorPicker) {
        Column() {
          ForEach(this.colors, (color: string) => {
            Button(color)
              .onClick(() => {
                this.selectedColor = color
                this.showColorPicker = false
              })
              .margin({ bottom: 5 })
          })
        }
        .border({ width: 1, color: '#cccccc' })
        .margin({ bottom: 20 })
      }

      // Submit Button
      Button('Submit')
        .onClick(() => {
          if (this.validateForm()) {
            this.successMessage = `Form submitted successfully! Selected color: ${this.selectedColor}`
            this.name = ''
            this.email = ''
          }
        })

      // Error Message
      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ bottom: 20 })
      }

      // Success Message
      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(18)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct CustomDateSeparatorApp {
  @State selectedDate: Date = new Date()
  @State displayDate: string = ''
  @State separator: string = '-'

  aboutToAppear() {
    this.updateDisplayDate()
  }

  updateDisplayDate() {
    const year = this.selectedDate.getFullYear()
    const month = this.selectedDate.getMonth() + 1
    const day = this.selectedDate.getDate()
    this.displayDate = `${year}${this.separator}${month < 10 ? '0' + month : month}${this.separator}${day < 10 ? '0' + day : day}`
  }

  build() {
    Column() {
      Text('Custom Date Separator')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      DatePicker({
