import { UIContext } from '@kit.ArkUI';

@Entry
@Component
struct FrameAnimationCallbackExample {
  @State myScale: number = 1.0;
  @State rotationAngle: number = 0;
  uiContext: UIContext | undefined = undefined;

  aboutToAppear() {
    this.uiContext = this.getUIContext?.();
  }

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .scale({ x: this.myScale, y: this.myScale })
        .rotate({ angle: this.rotationAngle })
        .onClick(() => {
          if (!this.uiContext) {
            console.info("no uiContext, animation failed");
            return;
          }
          this.myScale = 1;
          this.rotationAngle = 0;
          // Set the keyframe animation to play three times.
          this.uiContext.keyframeAnimateTo({ iterations: 3 }, [
            {
              // The first keyframe animation lasts for 1000 ms, during which the scale attribute changes from 1 to 1.5.
              duration: 1000,
              event: () => {
                this.myScale = 1.5;
                this.rotationAngle = 45;
                console.info("Frame 1: Scale increased to 1.5, rotated to 45 degrees");
              }
            },
            {
              // The second keyframe animation lasts for 800 ms, during which the scale attribute changes from 1.5 to 1.
              duration: 800,
              event: () => {
                this.myScale = 1;
                this.rotationAngle = 90;
                console.info("Frame 2: Scale reset to 1, rotated to 90 degrees");
              }
            },
            {
              // The third keyframe animation lasts for 600 ms, during which the scale attribute changes from 1 to 1.2.
              duration: 600,
              event: () => {
                this.myScale = 1.2;
                this.rotationAngle = 135;
                console.info("Frame 3: Scale increased to 1.2, rotated to 135 degrees");
              }
            },
            {
              // The fourth keyframe animation lasts for 400 ms, during which the scale attribute changes from 1.2 to 1.
              duration: 400,
              event: () => {
                this.myScale = 1;
                this.rotationAngle = 180;
                console.info("Frame 4: Scale reset to 1, rotated to 180 degrees");
              }
            }
          ]);
        })
    }.width('100%').margin({ top: 5 })
  }
}

