@Entry
@Component
struct FrameAnimationPlaybackControl {
  @State myScale: number = 1.0;
  @State rotationAngle: number = 0;
  @State isPlaying: boolean = false;
  @State currentFrame: number = 0;
  private animationDuration: number = 1000;
  private frames: ImageFrameInfo[] = [
    { src: $r('app.media.app_icon'), duration: 500 },
    { src: $r('app.media.app_icon'), duration: 500 },
    { src: $r('app.media.app_icon'), duration: 500 },
    { src: $r('app.media.app_icon'), duration: 500 }
  ];

  build() {
    Column() {
      Image(this.frames[this.currentFrame].src)
        .width(100)
        .height(100)
        .scale({ x: this.myScale, y: this.myScale })
        .rotate({ angle: this.rotationAngle })
        .margin(20)
        .animation({
          duration: this.animationDuration,
          iterations: -1,
          curve: 'linear',
          playMode: PlayMode.Normal
        })

      Row({ space: 20 }) {
        Button(this.isPlaying ? 'Pause' : 'Play')
          .onClick(() => {
            this.isPlaying = !this.isPlaying;
            if (this.isPlaying) {
              this.startAnimation();
            } else {
              this.stopAnimation();
            }
          })
          .width(100)

        Button('Reset')
          .onClick(() => {
            this.resetAnimation();
          })
          .width(100)
      }
      .margin(20)

      Slider({
        value: this.animationDuration,
        min: 500,
        max: 2000,
        step: 100,
        style: SliderStyle.OutSet
      })
      .onChange((value: number) => {
        this.animationDuration = value;
      })
      .width('80%')

      Text(`Frame: ${this.currentFrame + 1}/${this.frames.length}`)
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }

  private startAnimation() {
    this.isPlaying = true;
    animateTo({
      duration: this.animationDuration,
      iterations: -1,
      curve: 'linear'
    }, () => {
      this.currentFrame = (this.currentFrame + 1) % this.frames.length;
      this.myScale = 1.0 + (this.currentFrame % 2) * 0.5;
      this.rotationAngle = this.currentFrame * 90;
    });
  }

  private stopAnimation() {
    this.isPlaying = false;
  }

  private resetAnimation() {
    this.currentFrame = 0;
    this.myScale = 1.0;
    this.rotationAngle = 0;
    this.isPlaying = false;
  }
}

