@Component
struct SharpCurveAnimation {
  @State private toggle: boolean = true;

  build() {
    Column() {
      Button('Animate')
        .margin(50)
        .onClick(() => {
          animateTo({ duration: 2000, curve: Curve.EaseInOut }, () => {
            this.toggle = !this.toggle;
          })
        })
        .width(150)
        .height(50)
        .backgroundColor(Color.Blue)
        .borderRadius(10)
        .opacity(this.toggle ? 1 : 0.5)
        .scale({ x: this.toggle ? 1 : 1.5, y: this.toggle ? 1 : 1.5 })
        .rotate({ angle: this.toggle ? 0 : 360, x: 0, y: 0, z: 0 })
        .motionPath({
          path: 'M50 50 C 100 200, 200 200, 250 50',
          from: 0.0,
          to: 1.0,
          rotatable: true
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

