@Component
struct ComposeTitleBar {
  private title: string = '';
  private subtitle?: string;
  private menuItems: Array<MenuItem> = [];
  private onBackClick?: () => void;

  build() {
    Row() {
      Image($r('app.media.app_icon'))
        .width(24)
        .height(24)
        .margin({ left: 16 })
        .onClick(() => {
          this.onBackClick?.();
        });

      Column() {
