@Entry
@Component
struct AdvancedSystemCapabilitiesDemo {
  @State private isDarkMode: boolean = false;
  @State private counter: number = 0;
  @State private sliderValue: number = 50;
  @State private isVisible: boolean = true;
  @State private content: string = "Initial Content";

  build() {
    Column({ space: 20 }) {
      // Header section with accessibility features
      Stack({ alignContent: Alignment.TopStart }) {
        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
          .margin(10)
          .accessibilityTextHint("Application icon")
          .onClick(() => {
            console.info("Image clicked");
          });

        Text('System Capabilities Demo')
          .fontSize(24)
          .fontColor(this.isDarkMode ? Color.White : Color.Black)
          .margin(10)
          .accessibilityLevel('1');
      }
      .width('100%')
      .height(150)
      .backgroundColor(this.isDarkMode ? '#333333' : '#F5F5F5')

      // Content management with state
      Button("Toggle Content Visibility")
        .width(200)
        .height(50)
        .onClick(() => {
          this.isVisible = !this.isVisible;
        })
        .stateStyles({
          normal: {
            .backgroundColor(this.isDarkMode ? '#444444' : '#EEEEEE')
          },
          pressed: {
            .backgroundColor(this.isDarkMode ? '#666666' : '#DDDDDD')
          }
        });

      if (this.isVisible) {
        Column({ space: 15 }) {
          // Dynamic content update
          Text(this.content)
            .fontSize(20)
            .fontColor(this.isDarkMode ? Color.White : Color.Black);

          Button("Update Content")
            .width(150)
            .height(40)
            .margin(10)
            .onClick(() => {
              this.content = "New Content " + Date.now();
            });

          // Counter with state management
          Row({ space: 10 }) {
            Button('-')
              .width(50)
              .height(50)
              .onClick(() => {
                this.counter--;
              });

            Text(`Count: ${this.counter}`)
              .fontSize(20);

            Button('+')
              .width(50)
              .height(50)
              .onClick(() => {
                this.counter++;
              });
          }

          // Slider with state management
          Slider({
            value: this.sliderValue,
            min: 0,
            max: 100,
            step: 1,
            style: SliderStyle.OutSet
          })
          .width('80%')
          .onChange((value: number) => {
            this.sliderValue = value;
          });

          Text(`Slider Value: ${this.sliderValue}`)
            .fontSize(16);
        }
        .width('100%')
        .padding(15)
        .borderRadius(10)
        .backgroundColor(this.isDarkMode ? '#444444' : '#EEEEEE')
      }

      // Theme toggle
      Button(this.isDarkMode ? "Light Mode" : "Dark Mode")
        .width(200)
        .height(50)
        .margin({ top: 20 })
        .onClick(() => {
          this.isDarkMode = !this.isDarkMode;
        });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(this.isDarkMode ? '#222222' : '#FFFFFF')
  }
}

