@Entry
@Component
struct CarouselSlider {
  private images: string[] = [
    'https://example.com/image1.jpg',
    'https://example.com/image2.jpg',
    'https://example.com/image3.jpg'
  ];
  private texts: string[] = [
    'Image 1 Description',
    'Image 2 Description',
    'Image 3 Description'
  ];
  private currentIndex: number = 0;

  @State
  private showLargeImage: boolean = false;
  @State
  private selectedImage: string = '';
  @State
  private selectedText: string = '';

  build() {
    Column() {
      // Carousel Slider
      Swiper() {
        ForEach(this.images, (image: string, index: number) => {
          Column() {
            Image(image)
              .width('100%')
              .height(200)
              .onClick(() => {
                this.selectedImage = image;
                this.selectedText = this.texts[index];
                this.showLargeImage = true;
              });
            Text(this.texts[index])
              .margin({ top: 10 });
          }
          .width('100%')
          .margin({ bottom: 20 });
        });
      }
      .indicator(true)
      .autoPlay(true)
      .interval(3000)
      .loop(true)
      .width('100%')
      .height(240);

      // Large Image Viewer
      if (this.showLargeImage) {
        Column() {
          Image(this.selectedImage)
            .width('100%')
            .height(400);
          Text(this.selectedText)
            .margin({ top: 10 });
          Button('Close')
            .onClick(() => {
              this.showLargeImage = false;
            })
            .margin({ top: 20 });
        }
        .width('100%')
        .padding(20)
        .backgroundColor('#f0f0f0');
      }
    }
    .width('100%')
    .height('100%');
  }
}

