@Entry
@Component
struct ImageAnimationExample {
  @State private currentFrame: number = 0;
  private frameImages: Resource[] = [
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon')
  ];
  private timerId: number = -1;
  private animationDuration: number = 100; // ms per frame

  aboutToAppear() {
    this.startAnimation();
  }

  aboutToDisappear() {
    if (this.timerId !== -1) {
      clearInterval(this.timerId);
    }
  }

  startAnimation() {
    this.timerId = setInterval(() => {
      this.currentFrame = (this.currentFrame + 1) % this.frameImages.length;
    }, this.animationDuration);
  }

  stopAnimation() {
    if (this.timerId !== -1) {
      clearInterval(this.timerId);
      this.timerId = -1;
    }
  }

  build() {
    Column() {
      Image(this.frameImages[this.currentFrame])
        .width(200)
        .height(200)
        .objectFit(ImageFit.Contain)
        .margin(20)
        .animation({
          duration: this.animationDuration,
          curve: Curve.Linear
        })

      Row() {
        Button('Start Animation')
          .onClick(() => {
            if (this.timerId === -1) {
              this.startAnimation();
            }
          })
          .margin(10)

        Button('Stop Animation')
          .onClick(() => {
            this.stopAnimation();
          })
          .margin(10)
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

