@Entry
@Component
struct TypewriterTextInputFontFeatures {
  @State inputText: string = ''
  @State currentIndex: number = 0
  private timer: number = 0
  private fullText: string = 'Demonstrating typewriter effect with font features...'

  aboutToAppear() {
    this.startTypewriter()
  }

  startTypewriter() {
    this.timer = setInterval(() => {
      if (this.currentIndex < this.fullText.length) {
        this.inputText = this.fullText.substring(0, this.currentIndex + 1)
        this.currentIndex++
      } else {
        clearInterval(this.timer)
      }
    }, 100)
  }

  build() {
    Column() {
      TextInput({ text: this.inputText })
        .width('80%')
        .height(50)
        .fontSize(16)
        .fontFeature("\"calt\" on, \"liga\" on, \"dlig\" on")
        .caretColor(Color.Black)
        .backgroundColor(Color.White)
        .border({ width: 1, color: Color.Black })
        .margin(20)
        .onChange((value: string) => {
          this.inputText = value
        })

      Button('Restart Animation')
        .onClick(() => {
          this.currentIndex = 0
          this.inputText = ''
          clearInterval(this.timer)
          this.startTypewriter()
        })
        .margin(20)
        .width('60%')
        .height(40)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }

  aboutToDisappear() {
    clearInterval(this.timer)
  }
}

