@Entry
@Component
struct SubHeaderNotificationSystem {
  @State notificationCount: number = 0;
  @State notificationTitle: string = 'System Alert';
  @State notificationMessage: string = 'New notification received';

  build() {
    Column() {
      // SubHeader Section
      Column() {
        Text('Notification System')
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 8 });

        Text('Manage your notifications here')
          .fontSize(14)
          .fontColor('#666666')
          .margin({ bottom: 16 });

        Row() {
          Button('Push Notification')
            .type(ButtonType.Normal)
            .onClick(() => {
              this.notificationCount += 1;
              promptAction.showToast({
                message: `Notification #${this.notificationCount} pushed`,
                duration: 2000
              });
            })
            .margin({ right: 10 });

          Button('Pop Notification')
            .type(ButtonType.Normal)
            .onClick(() => {
              if (this.notificationCount > 0) {
                this.notificationCount -= 1;
                promptAction.showToast({
                  message: `Notification popped (${this.notificationCount} remaining)`,
                  duration: 2000
                });
              } else {
                promptAction.showToast({
                  message: 'No notifications to pop',
                  duration: 2000
                });
              }
            });
        }
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(8)
      .margin({ bottom: 20 });

      // Notification Details Display
      Text(`Title: ${this.notificationTitle}`)
        .fontSize(16)
        .margin({ bottom: 10 });

      Text(`Message: ${this.notificationMessage}`)
        .fontSize(16)
        .margin({ bottom: 20 });

      Text(`Notifications in queue: ${this.notificationCount}`)
        .fontSize(18)
        .margin({ bottom: 20 });

      // Clear all button
      Button('Clear All Notifications')
        .width('80%')
        .onClick(() => {
          if (this.notificationCount > 0) {
            promptAction.showToast({
              message: `Cleared ${this.notificationCount} notifications`,
              duration: 2000
            });
            this.notificationCount = 0;
          } else {
            promptAction.showToast({
              message: 'No notifications to clear',
              duration: 2000
            });
          }
        });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Start);
  }
}

