@Entry
@Component
struct VisibilityHandlingDemo {
    @State isVisible: boolean = true;
    @State visibilityOption: string = "Visible";

    build() {
        Column() {
            Button('Toggle Boolean Visibility')
                .margin(20)
                .onClick(() => {
                    this.isVisible = !this.isVisible;
                })

            Button('Toggle Enum Visibility')
                .margin(20)
                .onClick(() => {
                    this.visibilityOption = this.visibilityOption === "Visible" ? "Hidden" : "Visible";
                })

            // Boolean-based visibility
            if (this.isVisible) {
                Text('Boolean Visibility: Visible')
                    .fontSize(18)
                    .fontColor(Color.Black)
                    .backgroundColor(Color.Yellow)
                    .padding(10)
            }

            // Enum-based visibility
            Text('Enum Visibility: ' + this.visibilityOption)
                .fontSize(18)
                .fontColor(Color.Black)
                .backgroundColor(Color.Yellow)
                .padding(10)
                .visibility(this.visibilityOption === "Visible" ? Visibility.Visible : Visibility.Hidden)

        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .backgroundColor('#ffffff')
    }
}

