  @State showGreeting: boolean = false;

  build() {
    Column() {
      // Name Input Section
      Column() {
        Text('Please enter your name:')
          .fontSize(18)
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Type your name here' })
          .width('100%')
          .height(45)
          .margin({ bottom: 20 })
          .backgroundColor('#f8f8f8')
          .padding({ left: 15 })
          .onChange((value: string) => {
            this.userName = value;
          });
      }

      // Greet Button
      Button('Show Greeting')
        .width('100%')
        .height(50)
        .fontSize(20)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.userName.trim()) {
            this.showGreeting = true;
          } else {
            promptAction.showToast({
              message: 'Please enter a valid name',
              duration: 2000
            });
          }
        });

      // Greeting Display
      if (this.showGreeting) {
        Text(`Welcome, ${this.userName}!`)
          .fontSize(28)
          .margin({ top: 30 })
          .fontColor('#333333');
      }
    }
    .width('100%')
    .height('100%')
    .padding(25)
    .backgroundColor('#FFFFFF');
  }
}

@Entry
@Component
struct ItemListApp {
  private items: Array<Item> = [
    {
      id: 1,
      title: 'Mountain View',
      image: $r('app.media.app_icon'),
      description: 'A beautiful mountain landscape with snow-capped peaks and green valleys.'
    },
    {
      id: 2,
      title: 'Beach Sunset',
      image: $r('app.media.app_icon'),
      description: 'Golden sunset over a tropical beach with palm trees.'
    },
    {
      id: 3,
      title: 'City Lights',
      image: $r('app.media.app_icon'),
      description: 'Modern cityscape at night with glowing skyscrapers.'
    }
  ];

  @State selectedItem: Item | null = null;

  dialogController: CustomDialogController = new CustomDialogController({
    builder: this.dialogBuilder.bind(this),
    customStyle: true,
    alignment: DialogAlignment.Center
  });

  @Builder
  dialogBuilder() {
    Column() {
      if (this.selectedItem) {
        Image(this.selectedItem.image)
          .width('100%')
          .height(200)
          .borderRadius(8)
          .objectFit(ImageFit.Cover);

        Text(this.selectedItem.title)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 16, bottom: 8 });

        Text(this.selectedItem.description)
          .fontSize(16)
          .lineHeight(24);

        Button('Close')
          .onClick(() => {
            this.dialogController.close();
          });
      }
    }
    .padding(24)
    .width('90%')
    .backgroundColor(Color.White)
    .borderRadius(16);
  }

  build() {
    Column() {
      Text('Item List')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      List() {
        ForEach(this.items, (item: Item) => {
          ListItem() {
            Row() {
              Image(item.image)
                .width(100)
                .height(100)
                .borderRadius(8)
                .objectFit(ImageFit.Cover);

              Column() {
                Text(item.title)
                  .fontSize(20)
                  .fontWeight(FontWeight.Medium);

                Text(item.description)
                  .fontSize(14)
                  .lineHeight(20)
                  .margin({ top: 8 });
              }
              .margin({ left: 16 });
            }
            .padding(16)
            .onClick(() => {
              this.selectedItem = item;
              this.dialogController.open();
            });
          }
          .margin({ bottom: 12 });
        });
      }
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }
}

