@Entry
@Component
struct FormInterface {
  @State name: string = ''
  @State email: string = ''
  @State password: string = ''
  @State successMessage: string = ''
  @State errorMessage: string = ''

  validateForm(): boolean {
    if (!this.name || !this.email || !this.password) {
      this.errorMessage = 'All fields are required'
      return false
    }
    if (!this.email.includes('@')) {
      this.errorMessage = 'Please enter a valid email address'
      return false
    }
    if (this.password.length < 6) {
      this.errorMessage = 'Password must be at least 6 characters'
      return false
    }
    this.errorMessage = ''
    return true
  }

  build() {
    Column() {
      Text('Registration Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your name' })
        .onChange((value: string) => {
          this.name = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your email' })
        .onChange((value: string) => {
          this.email = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .margin({ bottom: 20 })

      Button('Submit')
        .onClick(() => {
          if (this.validateForm()) {
            this.successMessage = 'Form submitted successfully!'
            this.name = ''
            this.email = ''
            this.password = ''
          }
        })
        .margin({ bottom: 20 })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ bottom: 20 })
      }

      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(18)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

import { ExceptionPrompt, PromptOptions, MarginType } from '@kit.ArkUI';

@Entry
@Component
struct ErrorStateManagement {
  @State options: PromptOptions = {
    icon: $r('app.media.app_icon'),
    tip: 'Network Error Occurred',
    marginType: MarginType.DEFAULT_MARGIN,
    actionText: 'Retry',
    marginTop: 80,
    isShown: false
  }

  @State errorState: string = 'idle'; // 'idle', 'loading', 'error', 'success'

  simulateNetworkRequest() {
    this.errorState = 'loading';
    setTimeout(() => {
      // Simulate random error (50% chance)
      if (Math.random() > 0.5) {
        this.errorState = 'error';
        this.options.isShown = true;
        this.options.tip = 'Network Request Failed';
      } else {
        this.errorState = 'success';
        this.options.isShown = false;
      }
    }, 1500);
  }

  build() {
    Column() {
      // Show loading state
      if (this.errorState === 'loading') {
        LoadingProgress()
          .width(50)
          .height(50)
          .margin(20)
      }

      // Show success state
      if (this.errorState === 'success') {
        Text('Request Successful!')
          .fontSize(20)
          .fontColor('#00AA00')
          .margin(20)
      }

      // Show error prompt if in error state
      if (this.errorState === 'error') {
        ExceptionPrompt({
          options: this.options,
          onTipClick: () => {
            console.log('Error details clicked');
          },
          onActionTextClick: () => {
            console.log('Retry clicked');
            this.simulateNetworkRequest();
          },
        })
      }

      // Initial/retry button
      Button(this.errorState === 'idle' ? 'Make Request' : 'Try Again')
        .onClick(() => {
          this.simulateNetworkRequest();
        })
        .margin(20)
        .width(200)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

