@Entry
@Component
struct BMICalculator {
    @State heightInCm: string = ''
    @State weightInKg: string = ''
    @State bmiResult: string = ''
    @State errorMessage: string = ''

    calculateBMI() {
        const heightInM = parseFloat(this.heightInCm) / 100
        const weightKg = parseFloat(this.weightInKg)

        if (isNaN(heightInM) || isNaN(weightKg) || heightInM <= 0 || weightKg <= 0) {
            this.errorMessage = 'Please enter valid height and weight values.'
            this.bmiResult = ''
            return
        }

        const bmi = weightKg / (heightInM * heightInM)
        this.bmiResult = `Your BMI is ${bmi.toFixed(1)}`

        if (bmi < 18.5) this.bmiResult += ' (Underweight)'
        else if (bmi < 25) this.bmiResult += ' (Normal)'
        else if (bmi < 30) this.bmiResult += ' (Overweight)'
        else this.bmiResult += ' (Obese)'

        this.errorMessage = ''
    }

    build() {
        Column() {
            Text('BMI Calculator')
                .fontSize(24)
                .fontWeight(FontWeight.Bold)
                .margin({ top: 20, bottom: 30 })

            Text('Height (cm)')
                .fontSize(18)
                .margin({ bottom: 10 })
            TextInput({ placeholder: 'Enter height (cm)', text: this.heightInCm })
                .type(InputType.Number)
                .onChange((value: string) => {
                    this.heightInCm = value
                })
                .margin({ bottom: 20 })

            Text('Weight (kg)')
                .fontSize(18)
                .margin({ bottom: 10 })
            TextInput({ placeholder: 'Enter weight (kg)', text: this.weightInKg })
                .type(InputType.Number)
                .onChange((value: string) => {
                    this.weightInKg = value
                })
                .margin({ bottom: 20 })

            Button('Calculate BMI')
                .onClick(() => this.calculateBMI())
                .width('80%')
                .margin({ bottom: 20 })

            if (this.errorMessage) {
                Text(this.errorMessage)
                    .fontSize(16)
                    .fontColor(Color.Red)
                    .margin({ bottom: 20 })
            }

            if (this.bmiResult) {
                Text(this.bmiResult)
                    .fontSize(20)
                    .fontColor(Color.Green)
                    .margin({ top: 20 })
            }
        }
        .width('100%')
        .height('100%')
        .padding(20)
        .justifyContent(FlexAlign.Center)
    }
}

@Entry
@Component
struct SubHeaderPriorityShifting {
  @State operationTypes: string[] = ["default", "text", "icon", "text_icon", "custom"];
  @State currentPriority: number = 0;

  build() {
    Column() {
      // Custom SubHeader implementation with priority shifting
      Column() {
        Text('Operation Type Priority Shifting')
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 8 });

        Text(`Current Priority: ${this.operationTypes[this.currentPriority]}`)
          .fontSize(16)
          .margin({ bottom: 16 });

        Row() {
          ForEach(this.operationTypes, (type: string, index: number) => {
            Button(type)
              .width(100)
              .height(40)
              .margin(5)
              .backgroundColor(this.currentPriority === index ? Color.Blue : Color.Gray)
              .onClick(() => {
                this.currentPriority = index;
              });
          });
        }
        .margin({ bottom: 20 });

        // Priority ordered operations display
        Column() {
          Text('Priority Operations:')
            .fontSize(16)
            .margin({ bottom: 10 });

          ForEach(this.operationTypes.slice(0, this.currentPriority + 1), (type: string) => {
            Row() {
              Text(type)
                .fontSize(14)
                .margin({ right: 10 });
              Image($r('app.media.app_icon'))
                .width(20)
                .height(20);
            }
            .padding(10)
            .borderRadius(5)
            .backgroundColor(Color.White)
            .margin({ bottom: 5 });
          });
        }
        .padding(10)
        .backgroundColor('#F5F5F5')
        .borderRadius(8);
      }
      .padding(16)
      .backgroundColor(Color.White)
      .borderRadius(8)
      .shadow({ radius: 8, color: Color.Gray, offsetX: 2, offsetY: 2 });

      Button('Shift Priority')
        .width(200)
        .height(50)
        .margin({ top: 20 })
        .onClick(() => {
          this.currentPriority = (this.currentPriority + 1) % this.operationTypes.length;
        });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(24);
  }
}

