import display from '@ohos.display';

@Entry
@Component
struct DynamicFontSizeText {
  @State fontSize: number = 20
  @State orientation: string = "portrait"

  aboutToAppear() {
    AppStorage.setOrCreate('orientation', 'portrait')
    this.orientation = AppStorage.get<string>('orientation') ?? 'portrait'
  }

  onPageShow() {
    this.updateOrientation()
  }

  updateOrientation() {
    const displayInstance = display.getDefaultDisplaySync()
    const isPortrait = displayInstance.width < displayInstance.height
    this.orientation = isPortrait ? 'portrait' : 'landscape'
    this.fontSize = isPortrait ? 20 : 30
    AppStorage.set('orientation', this.orientation)
  }

  build() {
    Column() {
      Text("Dynamic Font Size Based on Orientation")
        .fontSize(this.fontSize)
        .fontWeight(FontWeight.Bold)
        .fontColor(Color.Black)
        .textAlign(TextAlign.Center)
        .width('100%')
        .margin(20)

      Text(`Current Orientation: ${this.orientation}`)
        .fontSize(16)
        .fontColor(Color.Gray)
        .textAlign(TextAlign.Center)
        .width('100%')

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(20)
    }
    .width('100%')
    .height('100%')
    .onAreaChange((oldValue: Area, newValue: Area) => {
      const isPortrait = newValue.width < newValue.height
      this.orientation = isPortrait ? 'portrait' : 'landscape'
      this.fontSize = isPortrait ? 20 : 30
      AppStorage.set('orientation', this.orientation)
    })
  }
}

