import mediaquery from '@ohos.mediaquery';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct MediaQueryErrorHandling {
  @State private isLandscape: boolean = false;
  @State private errorMessage: string = '';
  private landscapeQuery: mediaquery.MediaQueryListener | null = null;

  aboutToAppear() {
    this.setupMediaQuery();
  }

  private setupMediaQuery() {
    try {
      this.landscapeQuery = mediaquery.matchMediaSync('(orientation: landscape)');

      this.landscapeQuery.on('change', (result: mediaquery.MediaQueryResult) => {
        this.isLandscape = result.matches;
        this.errorMessage = '';
      });
    } catch (error) {
      this.errorMessage = `Media query error: ${error.message}`;
      promptAction.showToast({
        message: this.errorMessage,
        duration: 3000
      });
    }
  }

  onPageHide() {
    if (this.landscapeQuery) {
      this.landscapeQuery.off('change');
    }
  }

  build() {
    Column() {
      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(16)
          .fontColor(Color.Red)
          .margin(10);

        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
          .margin(10);

        Button('Retry Setup')
          .onClick(() => {
            this.setupMediaQuery();
          });
      } else {
        Text(this.isLandscape ? 'Landscape Mode' : 'Portrait Mode')
          .fontSize(20)
          .margin(10);

        Image($r('app.media.app_icon'))
          .width(this.isLandscape ? 200 : 100)
          .height(this.isLandscape ? 200 : 100);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

