@Entry
@Component
struct CircularProgressApp {
    @State progress: number = 0
    private readonly maxProgress: number = 100

    build() {
        Column() {
            // Circular Progress Indicator
            Stack() {
                // Background circle
                Circle()
                    .width(200)
                    .height(200)
                    .stroke('#E0E0E0')
                    .strokeWidth(15)
                    .fill('transparent')

                // Progress circle
                Circle()
                    .width(200)
                    .height(200)
                    .stroke('#4CAF50')
                    .strokeWidth(15)
                    .fill('transparent')
                    .strokeDashArray([Math.PI * 200, Math.PI * 200])
                    .strokeDashOffset(Math.PI * 200 * (1 - this.progress / this.maxProgress))
                    .rotate({ x: 0, y: 0, z: 1, angle: -90 })

                // Percentage text
                Text(`${Math.round(this.progress)}%`)
                    .fontSize(24)
                    .fontWeight(FontWeight.Bold)
            }
            .width(200)
            .height(200)
            .margin({ top: 50 })

            // Increment Buttons
            Row() {
                Button('+10%')
                    .onClick(() => {
                        if (this.progress < this.maxProgress) {
                            this.progress += 10
                        }
                    })
                    .margin({ right: 10 })
                    .width(100)
                    .height(50)

                Button('+20%')
                    .onClick(() => {
                        if (this.progress < this.maxProgress) {
                            this.progress += 20
                        }
                    })
                    .width(100)
                    .height(50)
            }
            .margin({ top: 40 })

            // Reset Button
            Button('Reset')
                .onClick(() => {
                    this.progress = 0
                })
                .margin({ top: 20 })
                .width(200)
                .height(50)
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
    }
}

