@Component
struct LoginScreen {
  @State email: string = ''
  @State password: string = ''
  @State message: string = ''
  @State isSuccess: boolean = false

  build() {
    Column() {
      // Email Input
      Text('Email:')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your email' })
        .width('80%')
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.email = value
        })

      // Password Input
      Text('Password:')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .width('80%')
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.password = value
        })

      // Login Button
      Button('Login')
        .onClick(() => {
          if (this.validateEmail(this.email) && this.password.length >= 6) {
            this.message = 'Login successful!'
            this.isSuccess = true
          } else {
            this.message = 'Invalid email or password (must be 6+ chars)'
            this.isSuccess = false
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      // Message Display
      if (this.message) {
        Text(this.message)
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
          .fontColor(this.isSuccess ? Color.Green : Color.Red)
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }

  validateEmail(email: string) {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return re.test(email)
  }
}

@Entry
@Component
struct TimeCalculationApp {
  @State startTime: Date = new Date();
  @State endTime: Date = new Date();
  @State duration: number = 0;
  @State currentTime: string = this.getFormattedTime();
  @State isUpdating: boolean = true;
  private timerId: number = -1;

  aboutToAppear() {
    this.startTimer();
  }

  aboutToDisappear() {
    this.stopTimer();
  }

  startTimer() {
    if (this.timerId === -1) {
      this.timerId = setInterval(() => {
        this.currentTime = this.getFormattedTime();
      }, 1000);
      this.isUpdating = true;
    }
  }

  stopTimer() {
    if (this.timerId !== -1) {
      clearInterval(this.timerId);
      this.timerId = -1;
      this.isUpdating = false;
    }
  }

  getFormattedTime(): string {
    const now = new Date();
    const hours = now.getHours().toString().padStart(2, '0');
    const minutes = now.getMinutes().toString().padStart(2, '0');
    const seconds = now.getSeconds().toString().padStart(2, '0');
    return `${hours}:${minutes}:${seconds}`;
  }

  build() {
    Column({ space: 20 }) {
      Text('Current Time')
        .fontSize(24)
        .fontWeight(FontWeight.Bold);

      Text(this.currentTime)
        .fontSize(36)
        .margin({ top: 10, bottom: 30 });

      Row({ space: 20 }) {
        Button(this.isUpdating ? 'Pause Update' : 'Resume Update')
          .width(150)
          .onClick(() => {
            if (this.isUpdating) {
              this.stopTimer();
            } else {
              this.startTimer();
            }
          });

        Button('Update Now')
          .width(150)
          .onClick(() => {
            this.currentTime = this.getFormattedTime();
          });
      }

      Button('Set Start Time')
        .onClick(() => {
          TimePickerDialog.show({
            selected: this.startTime,
            onAccept: (value: TimePickerResult) => {
              this.startTime.setHours(value.hour, value.minute);
              console.info("Start Time Set: " + this.startTime.toLocaleTimeString());
            }
          });
        })
        .margin(10);

      Button('Set End Time')
        .onClick(() => {
          TimePickerDialog.show({
            selected: this.endTime,
            onAccept: (value: TimePickerResult) => {
              this.endTime.setHours(value.hour, value.minute);
              console.info("End Time Set: " + this.endTime.toLocaleTimeString());
            }
          });
        })
        .margin(10);

      Button('Calculate Duration')
        .onClick(() => {
          this.duration = this.endTime.getTime() - this.startTime.getTime();
          console.info("Duration: " + this.duration + " milliseconds");
        })
        .margin(10);

      Text('Duration: ' + this.duration + ' milliseconds')
        .fontSize(20)
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .padding(20);
  }
}

import mediaquery from '@ohos.mediaquery';

@Entry
@Component
struct MediaQueryListenerVerifier {
  @State statusMessage: string = 'Listener not checked';
  private mediaQueryListener: mediaquery.MediaQueryListener | null = null;

  // Method to verify listener availability
  verifyListenerAvailability(): boolean {
    if (this.mediaQueryListener) {
      this.statusMessage = 'Listener is available and active';
      return true;
    } else {
      this.statusMessage = 'Listener is not available';
      return false;
    }
  }

  // Register listener
  registerListener() {
    if (!this.mediaQueryListener) {
      this.mediaQueryListener = mediaquery.matchMediaSync('(max-width: 600px)');
      this.statusMessage = 'Listener registered';
    }
  }

  // Unregister listener
  unregisterListener() {
    if (this.mediaQueryListener) {
      this.mediaQueryListener = null;
      this.statusMessage = 'Listener unregistered';
    }
  }

  build() {
    Column({ space: 20 }) {
      Text('MediaQueryListener Verifier')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ bottom: 20 });

      Text(this.statusMessage)
        .fontSize(18)
        .margin({ bottom: 20 });

      Button('Register Listener')
        .width('80%')
        .onClick(() => {
          this.registerListener();
        });

      Button('Verify Availability')
        .width('80%')
        .onClick(() => {
          this.verifyListenerAvailability();
        });

      Button('Unregister Listener')
        .width('80%')
        .onClick(() => {
          this.unregisterListener();
        });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }

  aboutToDisappear() {
    this.unregisterListener();
  }
}

