@Entry
@Component
struct FormatParser {
  @State inputText: string = '';
  @State parsedText: string = '';
  @State formattedText: string = '';
  @State isBold: boolean = false;
  @State isItalic: boolean = false;

  build() {
    Column() {
      TextInput({ placeholder: 'Enter text to parse and format' })
        .width('90%')
        .height(50)
        .onChange((value: string) => {
          this.inputText = value;
        })
        .margin({ top: 20 })

      Row({ space: 10 }) {
        Button('Parse')
          .onClick(() => {
            this.parsedText = this.parseText(this.inputText);
          })

        Button('Format')
          .onClick(() => {
            this.formattedText = this.formatText(this.parsedText);
          })
      }
      .margin({ top: 20 })

      Button('Toggle Bold')
        .onClick(() => {
          this.isBold = !this.isBold;
        })
        .margin({ top: 10 })

      Button('Toggle Italic')
        .onClick(() => {
          this.isItalic = !this.isItalic;
        })
        .margin({ top: 10 })

      Text('Parsed: ' + this.parsedText)
        .fontSize(16)
        .margin({ top: 20 })

      Text('Formatted:')
        .fontSize(16)
        .margin({ top: 10 })

      Text(this.formattedText)
        .fontSize(16)
        .fontWeight(this.isBold ? FontWeight.Bold : FontWeight.Normal)
        .fontStyle(this.isItalic ? FontStyle.Italic : FontStyle.Normal)
        .margin({ top: 5 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }

  parseText(text: string): string {
    // Enhanced parsing logic for various formats
    const phoneRegex = /(\+\d{1,3}\s?)?(\(\d{1,4}\)\s?)?\d{1,4}[\s.-]?\d{1,4}[\s.-]?\d{1,9}/g;
    const urlRegex = /https?:\/\/[^\s]+/g;
    const emailRegex = /[^\s@]+@[^\s@]+\.[^\s@]+/g;
    const dateRegex = /\b\d{1,2}\/\d{1,2}\/\d{2,4}\b/g;

    let parsed = text;

    parsed = parsed.replace(phoneRegex, '[Phone: $&]');
    parsed = parsed.replace(urlRegex, '[URL: $&]');
    parsed = parsed.replace(emailRegex, '[Email: $&]');
    parsed = parsed.replace(dateRegex, '[Date: $&]');

    return parsed;
  }

  formatText(text: string): string {
    // Basic formatting examples
    let formatted = text;
    if (this.isBold) formatted = `**${formatted}**`;
    if (this.isItalic) formatted = `_${formatted}_`;
    return formatted;
  }
}

