@Entry
@Component
struct TimeConversionUtility {
  @State localTime: Date = new Date();
  @State utcTime: string = '';
  @State militaryTime: string = '';
  @State twelveHourTime: string = '';

  build() {
    Column({ space: 20 }) {
      Text('Current Local Time: ' + this.localTime.toLocaleTimeString())
        .fontSize(20)
        .margin({ top: 20 });

      Button('Convert to UTC')
        .margin(10)
        .onClick(() => {
          this.utcTime = this.convertToUTC(this.localTime);
        });

      Text('UTC Time: ' + this.utcTime)
        .fontSize(20)
        .margin({ top: 10 });

      Button('Convert to Military Time')
        .margin(10)
        .onClick(() => {
          this.militaryTime = this.convertToMilitaryTime(this.localTime);
        });

      Text('Military Time: ' + this.militaryTime)
        .fontSize(20)
        .margin({ top: 10 });

      Button('Convert to 12-Hour Format')
        .margin(10)
        .onClick(() => {
          this.twelveHourTime = this.convertToTwelveHour(this.localTime);
        });

      Text('12-Hour Format: ' + this.twelveHourTime)
        .fontSize(20)
        .margin({ top: 10 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }

  convertToUTC(date: Date): string {
    return date.toUTCString();
  }

  convertToMilitaryTime(date: Date): string {
    return date.getHours().toString().padStart(2, '0') + ':' +
           date.getMinutes().toString().padStart(2, '0');
  }

  convertToTwelveHour(date: Date): string {
    let hours = date.getHours();
    const ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12;
    hours = hours ? hours : 12;
    return hours.toString().padStart(2, '0') + ':' +
           date.getMinutes().toString().padStart(2, '0') + ' ' + ampm;
  }
}

