@Entry
@Component
struct ComplexTimeFormatter {
  @State currentTime: Date = new Date()
  @State isMilitaryTime: boolean = true
  @State customFormat: string = 'HH:mm:ss'
  @State timeSeparator: string = ':'
  private timerId: number = -1

  aboutToAppear() {
    this.timerId = setInterval(() => {
      this.currentTime = new Date()
    }, 1000)
  }

  aboutToDisappear() {
    if (this.timerId !== -1) {
      clearInterval(this.timerId)
    }
  }

  private formatTime(date: Date, format: string): string {
    const hours = date.getHours()
    const minutes = date.getMinutes()
    const seconds = date.getSeconds()
    const ampm = hours >= 12 ? 'PM' : 'AM'

    if (format === 'hh:mm:ss a') {
      const formattedHours = hours % 12 || 12
      return `${formattedHours}${this.timeSeparator}${minutes.toString().padStart(2, '0')}${this.timeSeparator}${seconds.toString().padStart(2, '0')} ${ampm}`
    } else {
      return `${hours.toString().padStart(2, '0')}${this.timeSeparator}${minutes.toString().padStart(2, '0')}${this.timeSeparator}${seconds.toString().padStart(2, '0')}`
    }
  }

  build() {
    Column() {
      Button('Toggle Time Format')
        .margin(30)
        .onClick(() => {
          this.isMilitaryTime = !this.isMilitaryTime
          this.customFormat = this.isMilitaryTime ? 'HH:mm:ss' : 'hh:mm:ss a'
        })

      Button('Change Separator')
        .margin(20)
        .onClick(() => {
          this.timeSeparator = this.timeSeparator === ':' ? '-' : ':'
        })

      Text(this.formatTime(this.currentTime, this.customFormat))
        .fontSize(40)
        .fontColor(Color.Blue)
        .margin(20)
        .textAlign(TextAlign.Center)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

@Entry
@Component
struct TimePickerApp {
  @State selectedTime: Date = new Date()
  @State displayTime: string = ''

  aboutToAppear() {
    this.updateDisplayTime()
  }

  updateDisplayTime() {
    this.displayTime = this.selectedTime.toLocaleTimeString()
  }

  build() {
    Column() {
      Text('Time Picker')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      TimePicker({
        selected: this.selectedTime
      })
        .onChange((value: TimePickerResult) => {
          if (value.hour !== undefined && value.minute !== undefined) {
            this.selectedTime.setHours(value.hour, value.minute)
            this.updateDisplayTime()
          }
        })
        .margin({ bottom: 40 })

      Column() {
        Text('Selected Time:')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ bottom: 8 })

        Text(this.displayTime)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .fontColor('#007AFF')
      }
      .padding(16)
      .borderRadius(12)
      .backgroundColor('#F0F0F0')
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White)
  }
}

@Entry
@Component
struct MultipleClockSync {
  @State timeZone1: number = -5; // UTC-5 (EST)
  @State timeZone2: number = 0;  // UTC (GMT)
  @State timeZone3: number = 9;  // UTC+9 (JST)

  controller1: TextClockController = new TextClockController();
  controller2: TextClockController = new TextClockController();
  controller3: TextClockController = new TextClockController();

  build() {
    Column({ space: 20 }) {
      // Clock for UTC-5
      Text('Eastern Time (UTC-5)')
        .fontSize(20)
        .fontColor(Color.Black);
      TextClock({ timeZoneOffset: this.timeZone1, controller: this.controller1 })
        .format('hh:mm:ss a')
        .fontSize(30)
        .margin({ bottom: 20 });

      // Clock for UTC
      Text('Greenwich Mean Time (UTC)')
        .fontSize(20)
        .fontColor(Color.Black);
      TextClock({ timeZoneOffset: this.timeZone2, controller: this.controller2 })
        .format('hh:mm:ss a')
        .fontSize(30)
        .margin({ bottom: 20 });

      // Clock for UTC+9
      Text('Japan Time (UTC+9)')
        .fontSize(20)
        .fontColor(Color.Black);
      TextClock({ timeZoneOffset: this.timeZone3, controller: this.controller3 })
        .format('hh:mm:ss a')
        .fontSize(30)
        .margin({ bottom: 20 });

      // Control buttons
      Row({ space: 20 }) {
        Button('Start All')
          .onClick(() => {
            this.controller1.start();
            this.controller2.start();
            this.controller3.start();
          })
          .width('40%');

        Button('Stop All')
          .onClick(() => {
            this.controller1.stop();
            this.controller2.stop();
            this.controller3.stop();
          })
          .width('40%');
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White);
  }
}

