@Entry
@Component
struct CustomDashboard {
  @State private dataReady: boolean = false;
  @State private chartData: Array<ChartDataPoint> = [];
  @State private selectedIndex: number = -1;

  private generateChartData() {
    const newData: ChartDataPoint[] = [];
    for (let i = 0; i < 12; i++) {
      newData.push({x: i, y: Math.random() * 100});
    }
    this.chartData = newData;
  }

  aboutToAppear() {
    setTimeout(() => {
      this.generateChartData();
      this.dataReady = true;
    }, 1000);
  }

  build() {
    Column() {
      Row() {
        Image($r('app.media.app_icon'))
          .width(40)
          .height(40)
          .margin(10);
        Text('Data Dashboard')
          .fontSize(20)
          .fontWeight(FontWeight.Bold);
      }
      .width('100%')
      .justifyContent(FlexAlign.Start)
      .padding(10)

      if (this.dataReady) {
        Column() {
          Stack() {
            ForEach(this.chartData, (item: ChartDataPoint, index: number) => {
              Rect()
                .width(30)
                .height(item.y)
                .fill(this.selectedIndex === index ? Color.Blue : Color.Grey)
                .onClick(() => {
                  this.selectedIndex = index;
                })
                .position({x: 40 * index, y: 100 - item.y})
            })

            Line()
              .width('100%')
              .height(1)
              .strokeWidth(1)
              .fill(Color.Black)
              .position({x: 0, y: 100})
          }
          .width('100%')
          .height(150)
          .margin({top: 20})

          if (this.selectedIndex >= 0) {
            Text(`Value: ${this.chartData[this.selectedIndex].y.toFixed(2)}`)
              .fontSize(16)
              .margin({top: 20})
          }

          Button('Refresh Data')
            .onClick(() => {
              this.dataReady = false;
              setTimeout(() => {
                this.generateChartData();
                this.dataReady = true;
              }, 500);
            })
            .margin({top: 20})
        }
        .width('100%')
      } else {
        LoadingProgress()
          .color(Color.Blue)
          .width(50)
          .height(50)
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

interface ChartDataPoint {
  x: number;
  y: number;
}

