      title: 'Desert Dunes',
      image: $r('app.media.app_icon'),
      description: 'Golden sand dunes under a clear blue sky.',
      date: '2023-10-04'
    }
  ];

  @State selectedImage: ImageItem | null = null;
  @State showDetailView: boolean = false;

