              .margin({ top: 24 })
              .onClick(() => {
                this.showDetailView = false;
              });
          }
          .padding(24)
          .width('90%')
          .backgroundColor(Color.White)
          .borderRadius(16);
        }
        .width('100%')
        .height('100%')
        .backgroundColor('#00000080')
        .onClick(() => {
