@Entry
@Component
struct CustomTimeSelector {
  @State selectedTime: Date = new Date()
  @State is24HourFormat: boolean = true

  build() {
    Column() {
      Text('Custom Time Selector')
        .fontSize(24)
        .fontColor(Color.Black)
        .margin({ top: 20 })

      Row() {
        Text('Hour:')
          .fontSize(18)
          .fontColor(Color.Black)
          .margin({ right: 10 })

        Slider({
          value: this.selectedTime.getHours(),
          min: 0,
          max: this.is24HourFormat ? 23 : 11,
          step: 1
        })
          .onChange((value: number) => {
            this.selectedTime.setHours(value)
            this.selectedTime = new Date(this.selectedTime)
          })
          .width('60%')
      }
      .margin({ top: 20 })

      Row() {
        Text('Minute:')
          .fontSize(18)
          .fontColor(Color.Black)
          .margin({ right: 10 })

        Slider({
          value: this.selectedTime.getMinutes(),
          min: 0,
          max: 59,
          step: 1
        })
          .onChange((value: number) => {
            this.selectedTime.setMinutes(value)
            this.selectedTime = new Date(this.selectedTime)
          })
          .width('60%')
      }
      .margin({ top: 20 })

      Row() {
        Text('Second:')
          .fontSize(18)
          .fontColor(Color.Black)
          .margin({ right: 10 })

        Slider({
          value: this.selectedTime.getSeconds(),
          min: 0,
          max: 59,
          step: 1
        })
          .onChange((value: number) => {
            this.selectedTime.setSeconds(value)
            this.selectedTime = new Date(this.selectedTime)
          })
          .width('60%')
      }
      .margin({ top: 20 })

      Toggle({ type: ToggleType.Checkbox, isOn: this.is24HourFormat })
        .onChange((isOn: boolean) => {
          this.is24HourFormat = isOn
        })
        .margin({ top: 20 })

      Text(`Selected Time: ${this.selectedTime.toTimeString().split(' ')[0]}`)
        .fontSize(18)
        .fontColor(Color.Black)
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(Color.White)
  }
}

@Entry
@Component
struct ComposeTitleBar {
  @State title: string | null = null;
  @State subtitle: string | null = null;
  @State isFalsyValue: boolean = false;

  build() {
    Column() {
      // Handling null and falsy values in the title
      if (this.title) {
        Text(this.title)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 10 });
      } else {
        Text('Default Title')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 10 });
      }

      // Handling null and falsy values in the subtitle
      if (this.subtitle) {
        Text(this.subtitle)
          .fontSize(16)
          .margin({ top: 5 });
      } else {
        Text('Default Subtitle')
          .fontSize(16)
          .margin({ top: 5 });
      }

      // Handling falsy values in a boolean state
      if (this.isFalsyValue) {
        Text('Falsy Value is True')
          .fontSize(16)
          .margin({ top: 10 });
      } else {
        Text('Falsy Value is False')
          .fontSize(16)
          .margin({ top: 10 });
      }

      // Button to toggle the falsy value
      Button('Toggle Falsy Value')
        .onClick(() => {
          this.isFalsyValue = !this.isFalsyValue;
        })
        .margin({ top: 20 });

      // Button to set title and subtitle to null
      Button('Set Title/Subtitle to Null')
        .onClick(() => {
          this.title = null;
          this.subtitle = null;
        })
        .margin({ top: 10 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(0xF1F3F5);
  }
}

@Entry
@Component
struct DynamicFormatApp {
  @State textContent: string = "Dynamic Text";
  @State fontSize: number = 16;
  @State textColor: Color = Color.Black;
  @State isBold: boolean = false;
  @State isItalic: boolean = false;

  build() {
    Column({ space: 10 }) {
      Text(this.textContent)
        .fontSize(this.fontSize)
        .fontColor(this.textColor)
        .fontWeight(this.isBold ? FontWeight.Bold : FontWeight.Normal)
        .fontStyle(this.isItalic ? FontStyle.Italic : FontStyle.Normal)
        .margin({ top: 20 })

      Row({ space: 10 }) {
        Button('Increase Size')
          .onClick(() => {
            this.fontSize += 2;
          })

        Button('Decrease Size')
          .onClick(() => {
            this.fontSize = Math.max(12, this.fontSize - 2);
          })

        Button('Toggle Bold')
          .onClick(() => {
            this.isBold = !this.isBold;
          })

        Button('Toggle Italic')
          .onClick(() => {
            this.isItalic = !this.isItalic;
          })

        Button('Change Color')
          .onClick(() => {
            this.textColor = this.textColor === Color.Black ? Color.Red : Color.Black;
          })

        Button('Update Text')
          .onClick(() => {
            this.textContent = "Updated at " + new Date().toLocaleTimeString();
          })
      }
      .justifyContent(FlexAlign.Center)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor(Color.White)
  }
}

