// Unit Test Section
class SubHeaderTests {
  static testOperationChange() {
    const testSubHeader = new SubHeader();
    testSubHeader.title = "Test Header";
    testSubHeader.operationType = "default";

    // Verify initial state
    console.assert(testSubHeader.operationType === "default", "Initial operation type should be default");

    // Simulate operation change
    testSubHeader.operationType = "custom";
    console.assert(testSubHeader.operationType === "custom", "Operation type should change to custom");

    console.log("All SubHeader operation tests passed");
  }
}

// Run tests when app loads
SubHeaderTests.testOperationChange();

@Entry
@Component
struct DynamicListWithSearch {
  @State items: string[] = [
    'Apple',
    'Banana',
    'Orange',
    'Grapes',
    'Mango',
    'Pineapple',
    'Strawberry',
    'Watermelon',
    'Cherry',
    'Blueberry',
    'Lemon',
    'Peach'
  ];

  @State searchText: string = '';

  filteredItems(): string[] {
    if (this.searchText.trim() === '') {
      return this.items;
    } else {
      return this.items.filter(item =>
        item.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  build() {
    Column() {
      // Search Bar at the top
      TextInput({
        placeholder: 'Search items...',
        text: this.searchText
      })
        .width('100%')
        .onChange((value: string) => {
          this.searchText = value;
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      // Dynamic List
      if (this.filteredItems().length > 0) {
        List() {
          ForEach(this.filteredItems(), (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(18)
                .padding(12);
            }
          }, (item: string) => item);
        }
      } else {
        Text('No items found')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

