import mediaquery from '@ohos.mediaquery';

@Entry
@Component
struct OrientationLogger {
  @State isPortrait: boolean = false;
  private portraitListener: mediaquery.MediaQueryListener = mediaquery.matchMediaSync('(orientation: portrait)');

  aboutToAppear() {
    this.isPortrait = this.portraitListener.matches;
    this.portraitListener.on('change', (result: mediaquery.MediaQueryResult) => {
      if (result.matches) {
        console.info('Orientation changed to portrait');
        this.isPortrait = true;
      } else {
        this.isPortrait = false;
      }
    });
  }

  aboutToDisappear() {
    this.portraitListener.off('change');
  }

  build() {
    Column() {
      Text(this.isPortrait ? 'Portrait Mode' : 'Landscape Mode')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .textAlign(TextAlign.Center)
        .margin(20);

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(20);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

