@Entry
@Component
struct ConsistentTextFormatting {
  @State inputText: string = ''
  @State formattedText: string = ''
  controller: TextInputController = new TextInputController()

  applyConsistentFormatting(text: string): string {
    // Example consistent formatting: Remove extra spaces and capitalize first letter
    const trimmed = text.trim()
    return trimmed.charAt(0).toUpperCase() + trimmed.slice(1).toLowerCase()
  }

  build() {
    Column() {
      TextInput({ text: this.inputText, controller: this.controller })
        .height('48vp')
        .width('80%')
        .fontSize('16vp')
        .fontColor(Color.Black)
        .placeholderColor('#999999')
        .placeholderFont({ size: '14vp', weight: FontWeight.Normal })
        .onChange((value: string) => {
          this.inputText = value
          this.formattedText = this.applyConsistentFormatting(value)
        })

      Text(this.formattedText)
        .fontSize('16vp')
        .fontColor(Color.Blue)
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .padding(20)
  }
}

