import { promptAction } from '@kit.ArkUI';

@Entry
@Component
struct ConflictResolutionApp {
  @State titleBarTitle: string = "ComposeTitleBar";
  @State subHeaderTitle: string = "SubHeader";
  @State showTitleBar: boolean = true;
  @State showSubHeader: boolean = true;
  @State conflictMessage: string = "No conflict detected";

  toggleTitleBar() {
    this.showTitleBar = !this.showTitleBar;
    this.checkConflict();
  }

  toggleSubHeader() {
    this.showSubHeader = !this.showSubHeader;
    this.checkConflict();
  }

  checkConflict() {
    if (this.showTitleBar && this.showSubHeader) {
      this.conflictMessage = "Conflict detected: Both components visible";
    } else {
      this.conflictMessage = "No conflict detected";
    }
  }

  build() {
    Column() {
      // Control buttons
      Row() {
        Button("Toggle TitleBar")
          .onClick(() => this.toggleTitleBar())
          .margin(5);
        Button("Toggle SubHeader")
          .onClick(() => this.toggleSubHeader())
          .margin(5);
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .margin({ bottom: 20 });

      // ComposeTitleBar implementation
      if (this.showTitleBar) {
        Column() {
          Text(this.titleBarTitle)
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 10 });
          Row() {
            Button($r('app.media.app_icon'))
              .onClick(() => promptAction.showToast({ message: "TitleBar Button 1" }))
              .margin(5);
            Button($r('app.media.app_icon'))
              .onClick(() => promptAction.showToast({ message: "TitleBar Button 2" }))
              .margin(5);
          }
        }
        .width('100%')
        .padding(10)
        .backgroundColor('#E6F7FF')
        .borderRadius(8)
        .margin({ bottom: 10 });
      }

      // SubHeader implementation
      if (this.showSubHeader) {
        Column() {
          Text(this.subHeaderTitle)
            .fontSize(20)
            .fontWeight(FontWeight.Medium)
            .margin({ bottom: 10 });
          Row() {
            Button("Action 1")
              .onClick(() => promptAction.showToast({ message: "SubHeader Action 1" }))
              .margin(5);
            Button("Action 2")
              .onClick(() => promptAction.showToast({ message: "SubHeader Action 2" }))
              .margin(5);
          }
        }
        .width('100%')
        .padding(10)
        .backgroundColor('#F6FFED')
        .borderRadius(8);
      }

      // Conflict resolution status
      Text(this.conflictMessage)
        .fontSize(14)
        .fontColor(this.showTitleBar && this.showSubHeader ? Color.Red : Color.Black)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

@Entry
@Component
struct AnimalSelector {
  private animals: string[] = ['Dog', 'Cat', 'Rabbit', 'Bird'];
  private selectedAnimals: string[] = [];

  build() {
    Column() {
      Text('Select your favorite animals:')
        .fontSize(20)
        .margin(10);

      List() {
        ForEach(this.animals, (animal: string) => {
          ListItem() {
            Text(animal)
              .fontSize(16)
              .margin(5);
          }
          .onClick(() => {
            if (this.selectedAnimals.includes(animal)) {
              this.selectedAnimals = this.selectedAnimals.filter(item => item !== animal);
            } else {
              this.selectedAnimals.push(animal);
            }
          });
        });
      }

      Divider()
        .margin(10);

      Text(this.selectedAnimals.length > 0 ?
        `You selected: ${this.selectedAnimals.join(', ')}` :
        'No animals selected')
        .fontSize(18)
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

