@Entry
@Component
struct NoteApp {
  @State notes: Array<Note> = [];
  @State newNoteTitle: string = '';
  @State newNoteDescription: string = '';
  @State editNoteId: number | null = null;

  build() {
    Column() {
      TextInput({ placeholder: 'Enter note title...', text: this.newNoteTitle })
        .height(50)
        .width('90%')
        .onChange((value: string) => {
          this.newNoteTitle = value;
        })
        .margin(10);

      TextArea({ placeholder: 'Enter note description...', text: this.newNoteDescription })
        .height(100)
        .width('90%')
        .onChange((value: string) => {
          this.newNoteDescription = value;
        })
        .margin(10);

      Button(this.editNoteId !== null ? 'Update Note' : 'Add Note')
        .onClick(() => {
          if (this.newNoteTitle.trim() && this.newNoteDescription.trim()) {
            if (this.editNoteId !== null) {
              const index = this.notes.findIndex(note => note.id === this.editNoteId);
              if (index !== -1) {
                this.notes[index] = new Note(
                  this.editNoteId,
                  this.newNoteTitle,
                  this.newNoteDescription
                );
              }
              this.editNoteId = null;
            } else {
              this.notes.push(new Note(
                Date.now(),
                this.newNoteTitle,
                this.newNoteDescription
              ));
            }
            this.newNoteTitle = '';
            this.newNoteDescription = '';
          }
        })
        .margin(10);

      List() {
        ForEach(this.notes, (note: Note) => {
          ListItem() {
            Row() {
              Column() {
                Text(note.title)
                  .fontSize(20)
                  .fontWeight(FontWeight.Bold)
                  .width('80%');
                Text(note.description)
                  .fontSize(16)
                  .width('80%');
              }
              .width('80%');

              Button('Edit')
                .onClick(() => {
                  this.newNoteTitle = note.title;
                  this.newNoteDescription = note.description;
                  this.editNoteId = note.id;
                })
                .margin(5);

              Button('Delete')
                .onClick(() => {
                  this.notes = this.notes.filter(n => n.id !== note.id);
                })
                .margin(5);
            }
            .padding(10);
          }
        });
      }
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

class Note {
  id: number;
  title: string;
  description: string;

  constructor(id: number, title: string, description: string) {
    this.id = id;
    this.title = title;
    this.description = description;
  }
}

