@Component
struct TextAreaCursorControl {
  @State text: string = '';
  controller: TextAreaController = new TextAreaController();

  build() {
    Column({ space: 20 }) {
      TextArea({
        text: this.text,
        placeholder: 'Type your text here...',
        controller: this.controller
      })
        .width('90%')
        .height(150)
        .fontSize(16)
        .onChange((value: string) => {
          this.text = value;
        });

      Row({ space: 10 }) {
        Button('Cursor to Start')
          .width(120)
          .height(40)
          .onClick(() => {
            this.controller.caretPosition(0);
          });

        Button('Cursor to End')
          .width(120)
          .height(40)
          .onClick(() => {
            this.controller.caretPosition(this.text.length);
          });

        Button('Cursor to Position 5')
          .width(120)
          .height(40)
          .onClick(() => {
            this.controller.caretPosition(5);
          });
      }

      Text(`Current Cursor Position: ${this.controller.caretPosition}`)
        .fontSize(14)
        .margin({ top: 10 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F1F3F5');
  }
}

