import mediaquery from '@ohos.mediaquery';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct MediaQueryAlertApp {
  private mediaQueryListener: mediaquery.MediaQueryListener | null = null;

  aboutToAppear() {
    this.mediaQueryListener = mediaquery.matchMediaSync('(max-width: 600px)');

    this.mediaQueryListener.on('change', (result: mediaquery.MediaQueryResult) => {
      if (result.matches) {
        this.showAlert('Screen width is now less than 600px');
      } else {
        this.showAlert('Screen width is now greater than 600px');
      }
    });
  }

  showAlert(message: string) {
    promptAction.showDialog({
      title: 'Media Condition Alert',
      message: message,
      buttons: [
        { text: 'OK', color: '#007AFF' }
      ]
    });
  }

  aboutToDisappear() {
    if (this.mediaQueryListener) {
      this.mediaQueryListener.off('change');
      this.mediaQueryListener = null;
    }
  }

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(20);

      Text('Change screen size to trigger media query alerts')
        .fontSize(18)
        .textAlign(TextAlign.Center)
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

