import { promptAction } from '@kit.ArkUI';

interface MenuItem {
  value: Resource;
  isEnabled?: boolean;
  action?: () => void;
}

interface AnalyticsEvent {
  event: string;
  timestamp: number;
}

@Entry
@Component
struct AnalyticsComposeTitleBar {
  @State private analyticsData: AnalyticsEvent[] = [];
  @State title: string = "App Title";
  @State subtitle: string = "Subtitle";

  private menuItems: MenuItem[] = [
    {
      value: $r('app.media.app_icon'),
      isEnabled: true,
      action: () => this.logInteraction('Left Menu Item Clicked')
    },
    {
      value: $r('app.media.app_icon'),
      isEnabled: true,
      action: () => this.logInteraction('Right Menu Item 1 Clicked')
    },
    {
      value: $r('app.media.app_icon'),
      isEnabled: true,
      action: () => this.logInteraction('Right Menu Item 2 Clicked')
    }
  ];

  logInteraction(event: string): void {
    const timestamp = new Date().getTime();
    this.analyticsData.push({ event, timestamp });
    console.log(`Analytics Event: ${event} at ${timestamp}`);
    promptAction.showToast({ message: `Logged: ${event}`, duration: 1000 });
  }

  build() {
    Column() {
      // Title Bar Section
      Row() {
        // Left menu item
        Button(this.menuItems[0].value)
          .enabled(this.menuItems[0].isEnabled)
          .onClick(() => {
            if (this.menuItems[0].action) {
              this.menuItems[0].action();
            }
          })
          .margin({ left: 10 });

        // Title and Subtitle
        Column() {
          Text(this.title)
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .onClick(() => this.logInteraction('Title Clicked'));

          Text(this.subtitle)
            .fontSize(14)
            .onClick(() => this.logInteraction('Subtitle Clicked'));
        }
        .layoutWeight(1)
        .alignItems(HorizontalAlign.Center)

        // Right menu items
        Row() {
          ForEach(this.menuItems.slice(1), (item: MenuItem) => {
            Button(item.value)
              .enabled(item.isEnabled)
              .onClick(() => {
                if (item.action) {
                  item.action();
                }
              })
              .margin({ right: 10 });
          });
        }
      }
      .width('100%')
      .padding(10)
      .backgroundColor('#F5F5F5')

      // Analytics Log Section
      Column() {
        Text('Interaction Log:')
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20, bottom: 10 });

        List() {
          ForEach(this.analyticsData, (item: AnalyticsEvent, index: number) => {
            ListItem() {
              Text(`${index + 1}. ${item.event} - ${new Date(item.timestamp).toLocaleTimeString()}`)
                .fontSize(14)
                .margin(5);
            }
          });
        }
        .height('60%')
        .width('100%')
      }
      .width('100%')
      .padding(10)
    }
    .width('100%')
    .height('100%')
  }
}

