@Entry
@Component
struct CustomToggleSwitchExample {
  @State isOn: boolean = false;

  build() {
    Column({ space: 10 }) {
      Text('Custom Toggle Switch with Point Color')
        .fontSize(16)
        .fontColor(0x333333)
        .width('90%')

      Toggle({ type: ToggleType.Switch, isOn: this.isOn })
        .selectedColor('#007DFF')
        .switchStyle({
          pointRadius: 15,
          trackBorderRadius: 10,
          pointColor: '#FFA500',
          unselectedColor: Color.Gray
        })
        .onChange((isOn: boolean) => {
          this.isOn = isOn;
          console.info('Toggle state changed to: ' + isOn);
        })

      Text(this.isOn ? 'Switch is ON' : 'Switch is OFF')
        .fontSize(18)
        .margin(10)
        .fontColor(this.isOn ? '#007DFF' : '#333333')
    }
    .width('100%')
    .padding(24)
  }
}

