          ForEach(this.carouselItems, (item: CarouselItem) => {
            Stack() {
              Image(item.image)
                .width('100%')
                .height(300)
                .objectFit(ImageFit.Cover)
                .borderRadius(16);

              Text(item.caption)
                .fontSize(20)
                .fontWeight(FontWeight.Medium)
                .textAlign(TextAlign.Center)
                .backgroundColor('rgba(0, 0, 0, 0.5)')
                .padding(10)
                .borderRadius(8)
                .position({ x: 0, y: 250 });
            }
          });
        }
        .width('100%')
        .height(300)
        .margin({ bottom: 16 })
        .autoPlay(true)
        .interval(3000)
        .indicator(true)
        .loop(true)
        .duration(500)
        .onChange((index: number) => {
          this.currentIndex = index;
        });
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(20);

      Row() {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });

        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

interface CarouselItem {
  id: number;
  image: Resource;
  caption: string;
}

