@Component
struct MovieListApp {
  @State selectedMovie: Movie | null = null;
  dialogController: CustomDialogController = new CustomDialogController({
    builder: this.DialogBuilder,
    customStyle: true,
    alignment: DialogAlignment.Center,
  });

  @Builder DialogBuilder() {
    if (this.selectedMovie) {
      Column() {
        Image(this.selectedMovie.image)
          .width('100%')
          .height(200)
          .borderRadius(8)
          .objectFit(ImageFit.Cover);

        Text(this.selectedMovie.title)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 16, bottom: 8 });

        Text(`Release Year: ${this.selectedMovie.releaseYear}`)
          .fontSize(16)
          .margin({ bottom: 8 });

        Text(`Director: ${this.selectedMovie.director}`)
          .fontSize(16)
          .margin({ bottom: 8 });

        Text(`Genre: ${this.selectedMovie.genre}`)
          .fontSize(16)
          .margin({ bottom: 16 });

        Button('Close')
          .width('100%')
          .height(40)
          .margin({ top: 24 })
          .onClick(() => {
            this.dialogController.close();
          });
      }
      .padding(24)
      .width('90%')
      .backgroundColor(Color.White)
      .borderRadius(16);
    }
  }

  build() {
    Column() {
      Text('Movie List')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      List() {
        ForEach(movies, (movie: Movie) => {
          ListItem() {
            Row() {
              Image(movie.image)
                .width(80)
                .height(120)
                .borderRadius(8)
                .objectFit(ImageFit.Cover);

              Column() {
                Text(movie.title)
                  .fontSize(20)
                  .fontWeight(FontWeight.Medium)
                  .margin({ left: 10 });

                Text(`Release Year: ${movie.releaseYear}`)
                  .fontSize(16)
                  .margin({ left: 10 });
              }
              .layoutWeight(1)
              .margin({ left: 10 });
            }
            .onClick(() => {
              this.selectedMovie = movie;
              this.dialogController.open();
            });
          }
        });
      }
      .width('100%')
      .layoutWeight(1);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
    .padding(20);
  }
}

