@Component
struct MediaQueryApp {
  @State isLargeScreen: boolean = false;
  @State currentLayout: string = 'mobile';

  aboutToAppear() {
    this.checkScreenSize();
  }

  checkScreenSize() {
    const screenWidth = 800; // Example width, replace with actual API call
    this.isLargeScreen = screenWidth > 600;
    this.currentLayout = this.isLargeScreen ? 'desktop' : 'mobile';
  }

  build() {
    Column() {
      Text(`Current Layout: ${this.currentLayout}`)
        .fontSize(20)
        .fontColor(Color.Black)
        .margin(10);

      if (this.isLargeScreen) {
        Row() {
          Image($r('app.media.app_icon'))
            .width(150)
            .height(150)
            .margin(10);

          Column() {
            Text('Desktop View')
              .fontSize(24)
              .fontWeight(FontWeight.Bold)
              .margin({ bottom: 20 });

            Text('This content is optimized for large screens')
              .fontSize(18);
          }
          .margin(20);
        }
      } else {
        Column() {
          Image($r('app.media.app_icon'))
            .width(100)
            .height(100)
            .margin(10);

          Text('Mobile View')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 10 });

          Text('This content is optimized for small screens')
            .fontSize(16);
        }
      }

      Button('Toggle Screen Size')
        .onClick(() => {
          this.isLargeScreen = !this.isLargeScreen;
          this.currentLayout = this.isLargeScreen ? 'desktop' : 'mobile';
        })
        .margin(20)
        .width(200);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
