      value: $r('app.media.app_icon'),
      isEnabled: true,
      action: () => this.logAction("Left Menu Clicked")
    },
    {
      value: $r('app.media.app_icon'),
      isEnabled: true,
      action: () => this.logAction("Right Menu Item 1 Clicked")
    },
    {
      value: $r('app.media.app_icon'),
      isEnabled: true,
      action: () => this.logAction("Right Menu Item 2 Clicked")
    }
  ];

  logAction(event: string, details?: string): void {
    const timestamp = new Date().getTime();
    this.logs.push({ event, timestamp, details });
    console.log(`Logged Event: ${event} at ${timestamp}`);
    promptAction.showToast({ message: `Logged: ${event}`, duration: 1000 });
  }

  build() {
    Column() {
      // Title Bar Section
      Row() {
        // Left menu item
        Button(this.menuItems[0].value, { type: ButtonType.Normal })
          .onClick(() => {
            if (this.menuItems[0].action) {
              this.menuItems[0].action();
            }
          })
          .margin({ left: 10 });

        // Title and Subtitle
        Column() {
          Text(this.title)
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .onClick(() => {
              this.logAction("Title Clicked", "Title changed to New Title");
              this.title = "New Title";
            });

          Text(this.subtitle)
            .fontSize(14)
            .onClick(() => {
              this.logAction("Subtitle Clicked", "Subtitle changed to New Subtitle");
              this.subtitle = "New Subtitle";
            });
        }
        .layoutWeight(1)
        .alignItems(HorizontalAlign.Center)

        // Right menu items
        Row() {
          ForEach(this.menuItems.slice(1), (item: MenuItem) => {
            Button(item.value, { type: ButtonType.Normal })
              .onClick(() => {
                if (item.action) {
                  item.action();
                }
              })
              .margin({ right: 10 });
          });
        }
      }
      .width('100%')
      .padding(10)
      .backgroundColor('#F5F5F5')

      // Log Display Section
      Column() {
        Text("Event Logs:")
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20, bottom: 10 });

        List() {
          ForEach(this.logs, (log: LogEvent, index: number) => {
            ListItem() {
              Column() {
                Text(`${index + 1}. ${log.event}`)
                  .fontSize(14);
                Text(`Time: ${new Date(log.timestamp).toLocaleTimeString()}`)
                  .fontSize(12)
                  .opacity(0.7);
                if (log.details) {
                  Text(`Details: ${log.details}`)
                    .fontSize(12)
                    .opacity(0.7);
                }
              }
              .margin(5);
            }
          });
        }
        .height('60%')
        .width('100%')
      }
      .width('100%')
      .padding(10)
    }
    .width('100%')
    .height('100%')
  }
}

