@Entry
@Component
struct ProductRatingApp {
  @State ratings: number[] = [];
  @State currentRating: number = 0;
  @State averageRating: number = 0;

  private calculateAverage(): void {
    if (this.ratings.length === 0) {
      this.averageRating = 0;
      return;
    }
    const sum = this.ratings.reduce((acc, rating) => acc + rating, 0);
    this.averageRating = sum / this.ratings.length;
  }

  private handleRating(rating: number): void {
    this.currentRating = rating;
    this.ratings.push(rating);
    this.calculateAverage();
  }

  private resetRatings(): void {
    this.ratings = [];
    this.currentRating = 0;
    this.averageRating = 0;
  }

  build() {
    Column() {
      Text("Rate the Product")
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row({ space: 10 }) {
        ForEach([1, 2, 3, 4, 5], (index: number) => {
          Image($r('app.media.app_icon'))
            .width(30)
            .height(30)
            .opacity(this.currentRating >= index ? 1 : 0.3)
            .onClick(() => {
              this.handleRating(index);
            });
        })
      }
      .margin({ bottom: 20 });

      Text(`Average Rating: ${this.averageRating.toFixed(1)}`)
        .fontSize(18)
        .fontWeight(FontWeight.Medium);

      Text(`Your Rating: ${this.currentRating > 0 ? this.currentRating : 'Not rated yet'}`)
        .fontSize(16)
        .margin({ top: 10 });

      Button("Reset Ratings")
        .onClick(() => {
          this.resetRatings();
        })
        .margin({ top: 20 })
        .width(150);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }
}

@Entry
@Component
struct CustomLoadingScreen {
    @State rotation: number = 0
    @State progress: number = 0
    private intervalID: number = -1

    aboutToAppear() {
        this.intervalID = setInterval(() => {
            this.rotation = (this.rotation + 10) % 360
            this.progress = (this.progress + 1) % 101
        }, 50)
    }

    aboutToDisappear() {
        if (this.intervalID !== -1) {
            clearInterval(this.intervalID)
        }
    }

    build() {
        Column() {
            Stack() {
                Image($r('app.media.app_icon'))
                    .width(100)
                    .height(100)
                    .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })
                Circle()
                    .width(120)
                    .height(120)
                    .stroke($r('sys.color.ohos_id_color_primary'))
                    .strokeWidth(10)
                    .strokeDashArray([10, 20])
                    .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })
            }
            .width(120)
            .height(120)

            Progress({ value: this.progress, total: 100 })
                .width('80%')
                .height(10)
                .backgroundColor($r('sys.color.ohos_id_color_background'))
                .color($r('sys.color.ohos_id_color_primary'))

            Text(`Loading... ${this.progress}%`)
                .fontSize(20)
                .margin({ top: 20 })
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .backgroundColor($r('sys.color.ohos_id_color_background'))
    }
}

