import mediaquery from '@ohos.mediaquery';

@Entry
@Component
struct MultiMediaFeatureApp {
  @State isWideScreen: boolean = false;
  @State isDarkMode: boolean = false;
  @State isLandscape: boolean = false;
  @State currentBreakpoint: string = 'unknown';

  aboutToAppear() {
    const wideScreenQuery = mediaquery.matchMediaSync('(min-width: 600px)');
    const darkModeQuery = mediaquery.matchMediaSync('(prefers-color-scheme: dark)');
    const landscapeQuery = mediaquery.matchMediaSync('(orientation: landscape)');
    const breakpointQuery = mediaquery.matchMediaSync('(min-width: 320px) and (max-width: 480px)');

    wideScreenQuery.on('change', (result: mediaquery.MediaQueryResult) => {
      this.isWideScreen = result.matches;
    });

    darkModeQuery.on('change', (result: mediaquery.MediaQueryResult) => {
      this.isDarkMode = result.matches;
    });

    landscapeQuery.on('change', (result: mediaquery.MediaQueryResult) => {
      this.isLandscape = result.matches;
    });

    breakpointQuery.on('change', (result: mediaquery.MediaQueryResult) => {
      this.currentBreakpoint = result.matches ? 'mobile' : 'tablet/desktop';
    });
  }

  build() {
    Column({ space: 20 }) {
      Text('Media Feature Status:')
        .fontSize(24)
        .fontWeight(FontWeight.Bold);

      Text(`Wide Screen: ${this.isWideScreen}`)
        .fontSize(18);
      Text(`Dark Mode: ${this.isDarkMode}`)
        .fontSize(18);
      Text(`Landscape: ${this.isLandscape}`)
        .fontSize(18);
      Text(`Breakpoint: ${this.currentBreakpoint}`)
        .fontSize(18);

      if (this.isWideScreen && this.isDarkMode) {
        Column() {
          Text('Wide Screen & Dark Mode')
            .fontSize(20)
            .fontColor(Color.White);
          Image($r('app.media.app_icon'))
            .width(100)
            .height(100);
        }
        .width('100%')
        .backgroundColor('#333333')
        .padding(20);
      } else if (this.isLandscape || this.isWideScreen) {
        Column() {
          Text('Landscape or Wide Screen')
            .fontSize(20)
            .fontColor(Color.Black);
          Image($r('app.media.app_icon'))
            .width(80)
            .height(80);
        }
        .width('100%')
        .backgroundColor('#EEEEEE')
        .padding(20);
      } else {
        Column() {
          Text('Default View')
            .fontSize(20)
            .fontColor(Color.Black);
          Image($r('app.media.app_icon'))
            .width(60)
            .height(60);
        }
        .width('100%')
        .backgroundColor('#FFFFFF')
        .padding(20);
      }

      if (this.isWideScreen && this.isDarkMode && this.isLandscape) {
        Text('Premium Experience Mode')
          .fontSize(22)
          .fontColor(Color.Yellow)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(16)
    .backgroundColor(this.isDarkMode ? '#222222' : '#F5F5F5');
  }
}

