import promptAction from '@ohos.promptAction';

interface Message {
  sender: string;
  receiver: string;
  content: string;
  isOutgoing: boolean;
}

@Entry
@Component
struct ChatApp {
  @State messages: Array<Message> = [];
  @State newMessage: string = '';

  build() {
    Column() {
      // Chat Header
      Text('Chat Interface')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      // Chat Messages List
      List({ space: 10 }) {
        ForEach(this.messages, (message: Message) => {
          ListItem() {
            Column() {
              Text(`${message.isOutgoing ? 'You' : message.sender} to ${message.receiver}:`)
                .fontSize(14)
                .fontColor(message.isOutgoing ? '#007AFF' : '#333333')
                .margin({ bottom: 4 });

              Text(message.content)
                .fontSize(16)
                .fontColor('#000000')
                .padding(10)
                .backgroundColor(message.isOutgoing ? '#DCF8C6' : '#ECECEC')
                .borderRadius(8);
            }
            .alignItems(message.isOutgoing ? HorizontalAlign.End : HorizontalAlign.Start)
            .width('100%')
            .margin({ bottom: 10 });
          }
        })
      }
      .layoutWeight(1)
      .width('100%')
      .padding(10);

      // Message Input
      Row() {
        TextInput({ placeholder: 'Type a message...' })
          .width('80%')
          .height(40)
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.newMessage = value;
          });

        Button('Send')
          .width('20%')
          .height(40)
          .fontSize(16)
          .backgroundColor('#007AFF')
          .onClick(() => {
            if (this.newMessage.trim()) {
              const newMessage: Message = {
                sender: 'User1',
                receiver: 'User2',
                content: this.newMessage,
                isOutgoing: true
              };
              this.messages.push(newMessage);
              this.newMessage = '';
            } else {
              promptAction.showToast({
                message: 'Message cannot be empty'
              });
            }
          });
      }
      .width('100%')
      .padding(10);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

