import mediaquery from '@ohos.mediaquery';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct MediaQueryDebugger {
  @State private queryInfo: string = '';
  @State private currentOrientation: string = 'portrait';
  @State private currentWidth: string = '';
  @State private currentHeight: string = '';

  aboutToAppear() {
    const orientationQuery = mediaquery.matchMediaSync('(orientation: portrait)');
    orientationQuery.on('change', (result: mediaquery.MediaQueryResult) => {
      this.currentOrientation = result.matches ? 'portrait' : 'landscape';
      this.updateDebugInfo(result);
    });

    const widthQuery = mediaquery.matchMediaSync('(max-width: 600px)');
    widthQuery.on('change', (result: mediaquery.MediaQueryResult) => {
      this.currentWidth = result.matches ? '<= 600px' : '> 600px';
      this.updateDebugInfo(result);
    });

    const heightQuery = mediaquery.matchMediaSync('(max-height: 800px)');
    heightQuery.on('change', (result: mediaquery.MediaQueryResult) => {
      this.currentHeight = result.matches ? '<= 800px' : '> 800px';
      this.updateDebugInfo(result);
    });
  }

  updateDebugInfo(result: mediaquery.MediaQueryResult) {
    this.queryInfo = `MediaQuery Debug Info:
- Orientation: ${this.currentOrientation}
- Width: ${this.currentWidth}
- Height: ${this.currentHeight}
- Media: ${result.media}
- Matches: ${result.matches}`;
  }

  showDebugToast() {
    promptAction.showToast({
      message: this.queryInfo,
      duration: 3000
    });
  }

  build() {
    Column({ space: 20 }) {
      Text('MediaQuery Debugger')
        .fontSize(24)
        .fontWeight(FontWeight.Bold);

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 20, bottom: 20 });

      Text(this.currentOrientation === 'portrait' ? 'Portrait Mode' : 'Landscape Mode')
        .fontSize(20)
        .fontColor(Color.Black);

      Text(`Width: ${this.currentWidth}`)
        .fontSize(16);

      Text(`Height: ${this.currentHeight}`)
        .fontSize(16);

      Button('Show Debug Info')
        .onClick(() => this.showDebugToast())
        .width('60%')
        .margin({ top: 30 });

      Scroll() {
        Text(this.queryInfo)
          .fontSize(14)
          .textAlign(TextAlign.Start)
          .padding(10);
      }
      .height('30%')
      .width('90%')
      .border({ width: 1, color: Color.Gray })
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(this.currentOrientation === 'portrait' ? Color.White : '#D3D3D3');
  }
}

