@Component
struct ComposeTitleBar {
  private title: string = '';
  private subtitle?: string;
  private menuItems: Array<MenuItem> = [];
  private onBackClick?: () => void;

  build() {
    Row() {
      Image($r('app.media.app_icon'))
        .width(24)
        .height(24)
        .margin({ left: 16 })
        .onClick(() => {
          this.onBackClick?.();
        });

      Column() {
        Text(this.title)
          .fontSize(20)
          .fontWeight(FontWeight.Bold);

        if (this.subtitle) {
          Text(this.subtitle)
            .fontSize(14)
            .margin({ top: 4 });
        }
      }
      .layoutWeight(1)
      .margin({ left: 16 });

      Row() {
        ForEach(this.menuItems, (item: MenuItem) => {
          Button(item.value)
            .enabled(item.isEnabled)
            .onClick(() => {
              if (item.isEnabled && item.action) {
                item.action();
              }
            })
            .margin({ left: 8 });
        });
      }
      .margin({ right: 16 });
    }
    .width('100%')
    .height(56)
    .backgroundColor('#F5F5F5');
  }
}

