  @State selectedItem: Item | null = null;

  build() {
    Column() {
      List() {
        ForEach(this.items, (item: Item) => {
          ListItem() {
            Row() {
              Image(item.image)
                .width(80)
                .height(80)
                .borderRadius(8)
                .margin({ right: 16 });

              Column() {
                Text(item.title)
                  .fontSize(20)
                  .fontWeight(FontWeight.Medium);

                Text(item.description)
                  .fontSize(14)
                  .margin({ top: 4 });
              }
            }
            .padding(16)
            .onClick(() => {
              this.selectedItem = item;
            });
          }
          .margin({ bottom: 12 });
        });
      }
      .layoutWeight(1);

      if (this.selectedItem) {
        Column() {
          Text(`Selected: ${this.selectedItem.title}`)
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 8 });

          Text(this.selectedItem.description)
            .fontSize(16)
            .lineHeight(24);
        }
        .padding(16)
        .margin({ top: 20 })
        .backgroundColor('#FFFFFF')
        .borderRadius(8);
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5');
  }
}

interface Item {
  id: number;
  title: string;
  image: Resource;
  description: string;
}

