@Entry
@Component
struct CustomImageRatingSystem {
  @State selectedRating: number = 0;
  @State maxRating: number = 5;

  private selectedImage: Resource = $r('app.media.app_icon');
  private unselectedImage: Resource = $r('app.media.app_icon');

  build() {
    Column({ space: 20 }) {
      Text('Rate the Item')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row({ space: 5 }) {
        ForEach(new Array(this.maxRating).fill(0), (item: number, index: number) => {
          Image(index < this.selectedRating ? this.selectedImage : this.unselectedImage)
            .width(24)
            .height(24)
            .onClick(() => {
              this.selectedRating = index + 1;
            })
            .margin({ right: 5 });
        });
      }

      Text(`Current Rating: ${this.selectedRating}`)
        .fontSize(18)
        .fontColor(Color.Gray)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }
}

