struct CustomDialogExample {
  cancel: () => void = () => {};
  confirm: () => void = () => {};
  controller: CustomDialogController;

  build() {
    Column() {
      Text("Custom Popup Dialog")
        .fontSize(20)
        .margin({ top: 20 })
      Row() {
        Button("Cancel")
          .onClick(() => {
            this.cancel();
            if (this.controller) {
              this.controller.close();
            }
          })
        Button("Confirm")
          .onClick(() => {
            this.confirm();
            if (this.controller) {
              this.controller.close();
            }
          })
      }
      .margin({ top: 20 })
    }
    .padding(20)
  }
}

