@Entry
@Component
struct UserProfileInterface {
  @State name: string = 'Jane Smith'
  @State email: string = 'jane@example.com'
  @State isEditing: boolean = false
  @State newName: string = ''
  @State newEmail: string = ''

  build() {
    Column() {
      // Display profile picture
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ bottom: 20 })

      if (this.isEditing) {
        // Edit mode: Display input fields for name and email
        Row() {
          Text('Name: ').fontSize(18)
          TextInput({ placeholder: 'Enter name', text: this.newName })
            .onChange((value: string) => {
              this.newName = value
            })
        }
        .margin({ bottom: 20 })

        Row() {
          Text('Email: ').fontSize(18)
          TextInput({ placeholder: 'Enter email', text: this.newEmail })
            .onChange((value: string) => {
              this.newEmail = value
            })
        }
        .margin({ bottom: 20 })

        // Save button to update profile information
        Button('Save')
          .onClick(() => {
            if (this.newName && this.newEmail) {
              this.name = this.newName
              this.email = this.newEmail
              this.isEditing = false
            }
          })
          .margin({ top: 30 })
      } else {
        // Display mode: Show user's name and email
        Text(`Name: ${this.name}`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 10 })

        Text(`Email: ${this.email}`)
          .fontSize(18)
          .margin({ bottom: 20 })

        // Edit button to switch to edit mode
        Button('Edit')
          .onClick(() => {
            this.newName = this.name
            this.newEmail = this.email
            this.isEditing = true
          })
          .margin({ top: 30 })
      }
    }
    .padding(20)
  }
}

