@Component
struct MultiSelectSegmentButtonExample {
  @State selectedItems: string[] = [];
  @State options: string[] = ['Option 1', 'Option 2', 'Option 3', 'Option 4'];

  build() {
    Column() {
      Row() {
        ForEach(this.options, (option: string, index: number) => {
          Button(option)
            .type(ButtonType.Capsule)
            .stateEffect(true)
            .backgroundColor(this.selectedItems.includes(option) ? Color.Blue : Color.Gray)
            .onClick(() => {
              if (this.selectedItems.includes(option)) {
                this.selectedItems = this.selectedItems.filter(item => item !== option);
