import mediaquery from '@ohos.mediaquery';
import { UIContext } from '@kit.ArkUI';

@Entry
@Component
struct ConditionBasedAnimation {
  @State isLandscape: boolean = false;
  @State scaleValue: number = 1.0;
  @State rotationValue: number = 0;
  uiContext: UIContext | undefined = undefined;

  aboutToAppear() {
    this.uiContext = this.getUIContext?.();

    const landscapeListener = mediaquery.matchMediaSync('(orientation: landscape)');

    this.isLandscape = landscapeListener.matches;

    landscapeListener.on('change', (result) => {
      this.isLandscape = result.matches;
      if (this.isLandscape && this.uiContext) {
        this.triggerLandscapeAnimation();
      }
    });
  }

  triggerLandscapeAnimation() {
    if (!this.uiContext) return;

    this.uiContext.keyframeAnimateTo({ iterations: 1 }, [
      {
        duration: 500,
        event: () => {
          this.scaleValue = 1.5;
          this.rotationValue = 180;
        }
      },
      {
        duration: 500,
        event: () => {
          this.scaleValue = 1.0;
          this.rotationValue = 360;
        }
      }
    ]);
  }

  build() {
    Column() {
      Text(this.isLandscape ? 'Landscape Mode Activated' : 'Portrait Mode')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin(20);

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .rotate({ angle: this.rotationValue })
        .margin(20);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(this.isLandscape ? Color.Gray : Color.White)
  }
}

