@Entry
@Component
struct TextInputValidationApp {
  @State inputValue: string = ''
  @State isValid: boolean = true
  @State errorMessage: string = ''

  validateInput(value: string): string | null {
    if (value.length < 5) {
      return 'Input must be at least 5 characters long.'
    }
    return null
  }

  build() {
    Column({ space: 20 }) {
      TextInput({ placeholder: 'Enter text' })
        .width('100%')
        .height(50)
        .border({
          width: 1,
          color: this.isValid ? '#ddd' : '#ff0000'
        })
        .onChange((value: string) => {
          this.inputValue = value
          const error = this.validateInput(value)
          this.errorMessage = error || ''
          this.isValid = !error
        })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      Button('Submit')
        .enabled(this.isValid)
        .onClick(() => {
          console.info('Form submitted with value:', this.inputValue)
        })
    }
    .padding(20)
    .width('100%')
  }
}

