@Entry
@Component
struct MovieListApp {
  @State selectedMovie: Movie | null = null;
  dialogController: CustomDialogController = new CustomDialogController({
    builder: this.DialogBuilder,
    customStyle: true,
    alignment: DialogAlignment.Center,
  });

  @Builder DialogBuilder() {
    if (this.selectedMovie) {
      Column() {
        Image(this.selectedMovie.poster)
          .width('100%')
          .height(200)
          .borderRadius(8)
          .objectFit(ImageFit.Cover);

        Text(this.selectedMovie.title)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 16, bottom: 8 });

        Text(`Release Date: ${this.selectedMovie.releaseDate}`)
          .fontSize(16)
          .margin({ bottom: 8 });

        Text(`Genre: ${this.selectedMovie.genre}`)
          .fontSize(16)
          .margin({ bottom: 8 });

        Text('Plot:')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ bottom: 4 });

        Text(this.selectedMovie.plot)
          .fontSize(16)
          .lineHeight(24)
          .margin({ bottom: 16 });

        Button('Close')
          .onClick(() => {
            this.dialogController.close();
            this.selectedMovie = null;
          })
          .width('100%');
      }
      .padding(24)
      .width('90%')
      .backgroundColor(Color.White)
      .borderRadius(16);
    }
  }

  build() {
    Column() {
      Text('Movie List')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .padding(16);

      List() {
        ForEach(movies, (movie: Movie) => {
          ListItem() {
            Row() {
              Image(movie.poster)
                .width(100)
                .height(150)
                .borderRadius(8)
                .objectFit(ImageFit.Cover)
                .margin({ right: 10 });

              Column() {
                Text(movie.title)
                  .fontSize(20)
                  .fontWeight(FontWeight.Medium)
                  .margin({ bottom: 4 });

                Text(`Release Date: ${movie.releaseDate}`)
                  .fontSize(16);
              }
            }
            .onClick(() => {
              this.selectedMovie = movie;
              this.dialogController.open();
            });
          }
        });
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5');
  }
}

