@Entry
@Component
struct LoginScreen {
  @State email: string = ''
  @State password: string = ''
  @State message: string = ''
  @State isSuccess: boolean = false

  build() {
    Column() {
      // Email Input
      Text('Email:')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your email' })
        .width('80%')
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.email = value
        })

      // Password Input
      Text('Password:')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .width('80%')
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.password = value
        })

      // Login Button
      Button('Login')
        .onClick(() => {
          if (this.validateEmail(this.email) && this.password.length > 0) {
            this.message = 'Login successful!'
            this.isSuccess = true
          } else {
            this.message = 'Invalid email or password.'
            this.isSuccess = false
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      // Message Display
      if (this.message) {
        Text(this.message)
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
          .fontColor(this.isSuccess ? Color.Green : Color.Red)
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }

  validateEmail(email: string) {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return re.test(email)
  }
}

import mediaQuery from '@ohos.mediaquery';

@Entry
@Component
struct ScreenOrientationDetector {
  @State isPortrait: boolean = false;
  @State isNarrowWidth: boolean = false;
  private portraitListener: mediaQuery.MediaQueryListener = mediaQuery.matchMediaSync('(orientation: portrait)');
  private widthListener: mediaQuery.MediaQueryListener = mediaQuery.matchMediaSync('(max-width: 500vp)');

  aboutToAppear() {
    this.isPortrait = this.portraitListener.matches;
    this.portraitListener.on('change', (result: mediaQuery.MediaQueryResult) => {
      this.isPortrait = result.matches;
    });

    this.isNarrowWidth = this.widthListener.matches;
    this.widthListener.on('change', (result: mediaQuery.MediaQueryResult) => {
      this.isNarrowWidth = result.matches;
    });
  }

  aboutToDisappear() {
    this.portraitListener.off('change');
    this.widthListener.off('change');
  }

  build() {
    Column() {
      Text(`Orientation: ${this.isPortrait ? 'Portrait' : 'Landscape'}`)
        .fontSize(20)
        .margin(10);

      Text(`Viewport Width: ${this.isNarrowWidth ? 'Narrow (<500vp)' : 'Wide (≥500vp)'}`)
        .fontSize(20)
        .margin(10);

      if (this.isPortrait && this.isNarrowWidth) {
        Image($r("app.media.app_icon"))
          .width(200)
          .height(200)
          .objectFit(ImageFit.Contain)
          .borderRadius(10)
          .backgroundColor(Color.Blue);
      } else if (this.isPortrait) {
        Image($r("app.media.app_icon"))
          .width(300)
          .height(300)
          .objectFit(ImageFit.Contain)
          .borderRadius(10)
          .backgroundColor(Color.Green);
      } else {
        Image($r("app.media.app_icon"))
          .width('80%')
          .height('60%')
          .objectFit(ImageFit.Cover)
          .borderRadius(20)
          .backgroundColor(Color.Orange);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

