@Component
struct TitledImageCarousel {
  private swiperController: SwiperController = new SwiperController();

  private carouselItems: Array<CarouselItem> = [
    {
      id: 1,
      image: $r('app.media.app_icon'),
      title: 'Mountain View',
      description: 'A breathtaking view of the mountains.',
      additionalInfo: 'Elevation: 3000m, Location: Alps'
    },
    {
      id: 2,
      image: $r('app.media.app_icon'),
      title: 'Ocean Sunset',
      description: 'A serene sunset over the ocean.',
      additionalInfo: 'Location: Pacific Ocean, Best Time: Evening'
    },
    {
      id: 3,
      image: $r('app.media.app_icon'),
      title: 'Forest Path',
      description: 'A peaceful path through the forest.',
      additionalInfo: 'Trail Length: 5km, Difficulty: Easy'
    },
    {
      id: 4,
      image: $r('app.media.app_icon'),
      title: 'Desert Dunes',
      description: 'The vast expanse of desert dunes.',
      additionalInfo: 'Location: Sahara, Temperature: 40°C'
    }
  ];

  @State currentIndex: number = 0;
  @State showDetails: boolean = false;

  build() {
    Column() {
      Text('Image Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Column() {
        Swiper(this.swiperController) {
          ForEach(this.carouselItems, (item: CarouselItem) => {
            Stack() {
              Image(item.image)
                .width('100%')
                .height(300)
                .objectFit(ImageFit.Cover)
                .borderRadius(16)
                .onClick(() => {
                  this.showDetails = true;
                });
            }
          });
        }
        .width('100%')
        .height(300)
        .margin({ bottom: 16 })
        .autoPlay(true)
        .interval(3000)
        .indicator(true)
        .loop(true)
        .duration(500)
        .onChange((index: number) => {
          this.currentIndex = index;
        });

        if (this.showDetails) {
          Column() {
            Text(this.carouselItems[this.currentIndex].title)
              .fontSize(24)
              .fontWeight(FontWeight.Bold)
              .margin({ top: 8 })
              .textAlign(TextAlign.Center);

            Text(this.carouselItems[this.currentIndex].description)
              .fontSize(16)
              .margin({ top: 8 })
              .textAlign(TextAlign.Center);

            Text(this.carouselItems[this.currentIndex].additionalInfo)
              .fontSize(14)
              .margin({ top: 8 })
              .textAlign(TextAlign.Center)
              .onClick(() => {
                this.showDetails = false;
              });
          }
          .width('100%')
          .padding(16)
          .backgroundColor('#f5f5f5')
          .borderRadius(20);
        }
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(20);

      Row() {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });

        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

