@Component
struct ImageGalleryApp {
  @State selectedImage: string = ''
  @State showFullScreen: boolean = false
  @State imageDetails: string = ''

  private images: ImageItem[] = [
    { title: 'Image 1', image: 'app.media.app_icon', description: 'This is the first image with detailed information.' },
    { title: 'Image 2', image: 'app.media.app_icon', description: 'This is the second image with detailed information.' },
    { title: 'Image 3', image: 'app.media.app_icon', description: 'This is the third image with detailed information.' },
    { title: 'Image 4', image: 'app.media.app_icon', description: 'This is the fourth image with detailed information.' }
  ]

  build() {
    Column() {
      if (this.showFullScreen) {
        Stack() {
          Image(this.selectedImage)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%')

          Column() {
            Text(this.imageDetails)
              .fontSize(16)
              .fontColor('#000000')
              .margin({ top: 20, bottom: 10 })

            Button('Close')
              .onClick(() => {
                this.showFullScreen = false
              })
              .backgroundColor('#FFFFFF')
              .padding({ left: 10, right: 10, top: 5, bottom: 5 })
              .borderRadius(5)
          }
          .alignItems(HorizontalAlign.Center)
          .width('100%')
          .margin({ top: 20 })
        }
      } else {
        Grid() {
          ForEach(this.images, (item: ImageItem) => {
            GridItem() {
              Column() {
                Image(item.image)
                  .width('100%')
                  .aspectRatio(1)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(5)
                  .onClick(() => {
                    this.selectedImage = item.image
