@Entry
@Component
struct Index {
  @State selectedMovie: Movie | null = null;
  @State rating: number = 0;

  build() {
    if (this.selectedMovie == null) {
      Column() {
        Text('Movie List')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .padding(16);

        List() {
          ForEach(movies, (movie: Movie) => {
            ListItem() {
              Row() {
                Image(movie.image)
                  .width(100)
                  .height(150)
                  .objectFit(ImageFit.Cover)
                  .margin({ right: 10 });
                Column() {
                  Text(movie.title)
                    .fontSize(20)
                    .fontWeight(FontWeight.Medium)
                    .padding({ bottom: 4 });
                  Text(`Release Date: ${movie.releaseDate}`)
                    .fontSize(16)
                    .padding({ bottom: 8 });
                  Text(`Average Rating: ${movie.averageRating.toFixed(1)}`)
                    .fontSize(16)
                    .padding({ bottom: 8 });
                }
                .padding(16);
              }
              .onClick(() => {
                this.selectedMovie = movie;
                this.rating = 0;
              });
            }
          });
        }
      }
    } else {
      Scroll() {
        Column() {
          Image(this.selectedMovie.image)
            .width('100%')
            .height(300)
            .objectFit(ImageFit.Cover);

          Text(this.selectedMovie.title)
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .padding(16);

          Text(`Release Date: ${this.selectedMovie.releaseDate}`)
            .fontSize(18)
            .padding({ left: 16, right: 16, bottom: 8 });

          Text(`Director: ${this.selectedMovie.director}`)
            .fontSize(18)
            .padding({ left: 16, right: 16, bottom: 8 });

          Text('Description:')
            .fontSize(20)
            .fontWeight(FontWeight.Medium)
            .padding({ left: 16, right: 16, top: 16, bottom: 4 });

          Text(this.selectedMovie.description)
            .fontSize(16)
            .padding({ left: 16, right: 16, bottom: 16 });

          Text('Rate this movie:')
            .fontSize(20)
            .fontWeight(FontWeight.Medium)
            .padding({ left: 16, right: 16, top: 16, bottom: 4 });

          Row() {
            ForEach([1, 2, 3, 4, 5], (star: number) => {
              Image(this.rating >= star ? 'common/star_filled.png' : 'common/star_empty.png')
                .width(30)
                .height(30)
                .margin({ right: 5 })
                .onClick(() => {
                  this.rating = star;
                });
            });
          }
          .padding({ left: 16, right: 16, bottom: 16 });

          Button('Submit')
            .width('80%')
            .height(50)
            .margin({ top: 16, bottom: 16 })
            .onClick(() => {
              this.selectedMovie = null;
            });
        }
      }
    }
  }
}

class Movie {
  title: string;
  image: string;
  releaseDate: string;
  director: string;
  description: string;
  averageRating: number;

  constructor(title: string, image: string, releaseDate: string, director: string, description: string, averageRating: number) {
    this.title = title;
    this.image = image;
    this.releaseDate = releaseDate;
    this.director = director;
    this.description = description;
    this.averageRating = averageRating;
  }
}

