@Entry
@Component
struct SignUpForm {
  @State name: string = ''
  @State email: string = ''
  @State password: string = ''
  @State nameError: string = ''
  @State emailError: string = ''
  @State passwordError: string = ''
  @State successMessage: string = ''

  validateName(name: string): boolean {
    return name.trim().length > 0
  }

  validateEmail(email: string): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return emailRegex.test(email)
  }

  validatePassword(password: string): boolean {
    return password.length >= 6
  }

  handleSignUp() {
    this.nameError = this.validateName(this.name) ? '' : 'Name is required'
    this.emailError = this.validateEmail(this.email) ? '' : 'Please enter a valid email'
    this.passwordError = this.validatePassword(this.password) ? '' : 'Password must be at least 6 characters'

    if (!this.nameError && !this.emailError && !this.passwordError) {
      this.successMessage = 'Sign up successful!'
      this.name = ''
      this.email = ''
      this.password = ''
    }
  }

  build() {
    Column({ space: 20 }) {
      // Form Title
      Text('Sign Up')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      // Name Input
      TextInput({ placeholder: 'Enter your name' })
        .width('100%')
        .onChange((value: string) => {
          this.name = value
          if (this.validateName(value)) {
            this.nameError = ''
          }
        })
        .border({
          width: 1,
          color: this.nameError ? '#ff0000' : '#ddd'
        })

      if (this.nameError) {
        Text(this.nameError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      // Email Input
      TextInput({ placeholder: 'Enter your email' })
        .width('100%')
        .onChange((value: string) => {
          this.email = value
          if (this.validateEmail(value)) {
            this.emailError = ''
          }
        })
        .border({
          width: 1,
          color: this.emailError ? '#ff0000' : '#ddd'
        })

      if (this.emailError) {
        Text(this.emailError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      // Password Input
      TextInput({ placeholder: 'Enter your password' })
        .width('100%')
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
          if (this.validatePassword(value)) {
            this.passwordError = ''
          }
        })
        .border({
          width: 1,
          color: this.passwordError ? '#ff0000' : '#ddd'
        })

      if (this.passwordError) {
        Text(this.passwordError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      // Sign Up Button
      Button('Sign Up')
        .width('100%')
        .onClick(() => {
          this.handleSignUp()
        })

      // Success Message
      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(18)
          .fontColor('#00ff00')
          .margin({ top: 20 })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

