@Entry
@Component
struct SectionSplicingOperations {
  @State sections: Array<string> = ['Part 1', 'Part 2', 'Part 3', 'Part 4']
  @State splicedText: string = ''

  build() {
    Column({ space: 10 }) {
      Text('Section Splicing Operations')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      ForEach(this.sections, (section: string, index: number) => {
        Row() {
          Text(section)
            .fontSize(16)
            .margin({ right: 10 })
          Button('Modify')
            .onClick(() => {
              this.modifySection(index)
            })
        }
        .margin({ bottom: 10 })
      })

      Row({ space: 20 }) {
        Button('Add Section')
          .onClick(() => {
            this.addSection()
          })
        Button('Splice Sections')
          .onClick(() => {
            this.spliceSections()
          })
      }
      .margin({ top: 20 })

      Text('Spliced Text: ' + this.splicedText)
        .fontSize(16)
        .margin({ top: 20 })
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }

  private addSection() {
    this.sections.push(`Part ${this.sections.length + 1}`)
  }

  private modifySection(index: number) {
    this.sections[index] = `Edited Part ${index + 1}`
  }

  private spliceSections() {
    this.splicedText = this.sections.join(' + ')
  }
}

