@Entry
@Component
struct StateManagementExample {
  @State sharedCount: number = 0;
  @State isDarkMode: boolean = false;
  @State items: string[] = ['Apple', 'Banana', 'Cherry'];

  build() {
    Column() {
      HeaderComponent({ count: this.sharedCount, isDark: this.isDarkMode });

      CounterComponent({
        count: this.sharedCount,
        onIncrement: () => { this.sharedCount += 1 },
        onDecrement: () => { this.sharedCount -= 1 }
      });

      ThemeToggleComponent({
        isDark: this.isDarkMode,
        onToggle: () => { this.isDarkMode = !this.isDarkMode }
      });

      StatusDisplayComponent({ count: this.sharedCount, isDark: this.isDarkMode });

      ItemListComponent({
        items: this.items,
        onAdd: () => { this.items = [...this.items, `Item ${this.items.length + 1}`] },
        onRemove: () => { this.items = this.items.slice(0, -1) }
      });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.isDarkMode ? Color.Black : Color.White)
    .padding(20);
  }
}

