@Entry
@Component
struct MultiSelectSegmentButton {
  @State selectedIndices: number[] = [];
  private options: string[] = ["Option 1", "Option 2", "Option 3", "Option 4", "Option 5"];

  build() {
    Column() {
      Row() {
        ForEach(this.options, (option: string, index: number) => {
          Button(option)
            .margin(5)
            .padding(10)
            .backgroundColor(this.selectedIndices.includes(index) ? Color.Blue : Color.Gray)
            .fontColor(Color.White)
            .borderRadius(5)
            .onClick(() => {
              if (this.selectedIndices.includes(index)) {
                this.selectedIndices = this.selectedIndices.filter(i => i !== index);
              } else {
                this.selectedIndices = [...this.selectedIndices, index];
              }
            });
        })
      }
      .justifyContent(FlexAlign.Center)
      .padding(10)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

@Entry
@Component
struct ImageSlideshow {
  private swiperController: SwiperController = new SwiperController();

  private slideshowItems: Array<SlideshowItem> = [
    {
      id: 1,
      image: $r('app.media.app_icon')
    },
    {
      id: 2,
      image: $r('app.media.app_icon')
    },
    {
      id: 3,
      image: $r('app.media.app_icon')
    },
    {
      id: 4,
      image: $r('app.media.app_icon')
    }
  ];

  @State currentIndex: number = 0;

  build() {
    Column() {
      Text('Image Slideshow')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Column() {
        Swiper(this.swiperController) {
          ForEach(this.slideshowItems, (item: SlideshowItem) => {
            Stack() {
              Image(item.image)
                .width('100%')
                .height(300)
                .objectFit(ImageFit.Cover)
                .borderRadius(16);
            }
          });
        }
        .width('100%')
        .height(300)
        .margin({ bottom: 16 })
        .autoPlay(true)
        .interval(3000)
        .indicator(true)
        .loop(true)
        .duration(500)
        .onChange((index: number) => {
          this.currentIndex = index;
        });
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(20);

      Row() {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });

        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
