@Entry
@Component
struct SectionValueRetrieval {
  private sections: string[] = ['Section A', 'Section B', 'Section C', 'Section D']
  @State private selectedSection: string = ''

  build() {
    Column() {
      Text('Select a Section to Retrieve Values')
        .fontSize(20)
        .margin(10)

      List({ space: 10 }) {
        ForEach(this.sections, (section: string) => {
          ListItem() {
            Row() {
              Image($r('app.media.app_icon'))
                .width(30)
                .height(30)
                .margin({ right: 10 })

              Text(section)
                .fontSize(16)
                .textAlign(TextAlign.Center)
                .width('80%')
            }
            .width('100%')
            .height(60)
            .backgroundColor(this.selectedSection === section ? '#CCCCCC' : '#FFFFFF')
            .borderRadius(8)
            .onClick(() => {
              this.selectedSection = section
            })
          }
        }, (section: string) => section)
      }
      .width('100%')
      .height('60%')

      Text(this.selectedSection ? `Values for ${this.selectedSection}: ${this.retrieveSectionValues(this.selectedSection)}` : 'No section selected')
        .fontSize(16)
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .padding(10)
  }

  private retrieveSectionValues(section: string): string {
    switch (section) {
      case 'Section A':
        return 'Value 1, Value 2, Value 3'
      case 'Section B':
        return 'Value 4, Value 5, Value 6'
      case 'Section C':
        return 'Value 7, Value 8, Value 9'
      case 'Section D':
        return 'Value 10, Value 11, Value 12'
      default:
        return 'No values found'
    }
  }
}

