@Component
struct SectionLengthConfiguration {
  @State sectionLengths: number[] = [100, 150, 200];
  @State totalLength: number = 0;

  build() {
    Column() {
      ForEach(this.sectionLengths, (length: number, index: number) => {
        Row() {
          Text(`Section ${index + 1}:`)
            .fontSize(18)
            .margin(5)
          TextInput({ text: `${length}` })
            .width(100)
            .height(40)
            .onChange((value: string) => {
              this.sectionLengths[index] = parseInt(value) || 0;
            })
        }
        .margin(5)
      })

      Button('Calculate Total Length')
        .onClick(() => {
          this.totalLength = this.sectionLengths.reduce((acc, curr) => acc + curr, 0);
        })
        .margin(15)
        .width('80%')
        .height(50)
        .backgroundColor('#007DFF')
        .fontColor('#FFFFFF')

      Text(`Total Length: ${this.totalLength}px`)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .padding(10)
  }
}

