@Component
struct FoldStatusDetection {
    @State isFolded: boolean = false;
    @State foldPercentage: number = 0;

    build() {
        Column({ space: 10 }) {
            // Fold status display
            Row() {
                Text('Status:')
                    .fontSize(18)
                    .fontColor(Color.Black)

                Text(this.isFolded ? 'Folded' : 'Unfolded')
                    .fontSize(18)
                    .fontColor(this.isFolded ? Color.Red : Color.Green)
                    .margin({ left: 10 })
            }
            .margin({ bottom: 20 })

            // Visual representation of fold state
            Image($r('app.media.app_icon'))
                .width(150)
                .height(150)
                .rotate({ x: 1, y: 0, z: 0, angle: this.isFolded ? 180 : 0 })
                .opacity(this.isFolded ? 0.6 : 1)
                .onClick(() => {
                    this.isFolded = !this.isFolded;
                })

            // Fold percentage control
            Text(`Fold Percentage: ${this.foldPercentage}%`)
                .fontSize(16)
                .margin({ top: 20 })

            Slider({
                value: this.foldPercentage,
                min: 0,
                max: 100,
                step: 1,
                style: SliderStyle.OutSet
            })
            .width('80%')
            .onChange((value: number) => {
                this.foldPercentage = value;
                this.isFolded = value > 50;
            })

            // Fold/Unfold action buttons
            Row({ space: 20 }) {
                Button('Fold')
                    .onClick(() => {
                        this.isFolded = true;
                        this.foldPercentage = 100;
                    })

                Button('Unfold')
                    .onClick(() => {
                        this.isFolded = false;
                        this.foldPercentage = 0;
                    })
            }
            .margin({ top: 20 })
        }
        .width('100%')
        .height('100%')
        .padding(20)
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center)
    }
}

