@Entry
@Component
struct EmailInputApp {
  @State email: string = '';
  @State isValidEmail: boolean = true;
  @State validationMessage: string = '';

  validateEmail(email: string): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }

  build() {
    Column({ space: 10 }) {
      TextInput({ placeholder: 'Enter your email' })
        .type(InputType.Email)
        .onChange((value: string) => {
          this.email = value;
          this.isValidEmail = this.validateEmail(value);
          this.validationMessage = this.isValidEmail ? '' : 'Please enter a valid email address';
        })
        .width('100%')
        .padding(10)
        .border({
          width: 1,
          color: this.isValidEmail ? '#ddd' : '#ff0000'
        })

      Text(`Entered Email: ${this.email}`)
        .fontSize(16)
        .margin({ top: 10 })

      if (this.validationMessage) {
        Text(this.validationMessage)
          .fontSize(14)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }
    }
    .padding(20)
    .width('100%')
  }
}

