struct GridViewFavoritesApp {
  private items: Array<Item> = [
    { id: 1, title: 'Item A', image: 'common/icons/icon1.png' },
    { id: 2, title: 'Item B', image: 'common/icons/icon2.png' },
    { id: 3, title: 'Item C', image: 'common/icons/icon3.png' },
    { id: 4, title: 'Item D', image: 'common/icons/icon4.png' },
    { id: 5, title: 'Item E', image: 'common/icons/icon5.png' },
    { id: 6, title: 'Item F', image: 'common/icons/icon6.png' }
  ];

  @State selectedItems: Array<Item> = [];

  build() {
    Column() {
      Text('Select Items to Add to Favorites')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Grid() {
        ForEach(this.items, (item: Item) => {
          GridItem() {
            Column() {
              Image(item.image)
                .width(80)
                .height(80)
                .objectFit(ImageFit.Cover)
                .margin({ bottom: 10 });

              Text(item.title)
                .fontSize(16)
                .fontWeight(FontWeight.Medium);
            }
            .padding(10)
            .backgroundColor(this.selectedItems.some(selectedItem => selectedItem.id === item.id) ? '#D3D3D3' : '#F0F0F0')
            .borderRadius(5)
            .onClick(() => {
              if (this.selectedItems.some(selectedItem => selectedItem.id === item.id)) {
                this.selectedItems = this.selectedItems.filter(selectedItem => selectedItem.id !== item.id);
              } else {
                this.selectedItems = [...this.selectedItems, item];
              }
            });
          }
          .margin({ bottom: 10 });
        });
      }
      .columnsTemplate('1fr 1fr 1fr')
      .columnsGap(10)
      .rowsGap(10)
      .width('100%')
      .height('60%');

      Text('Favorites List')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 10 });

      List() {
        ForEach(this.selectedItems, (item: Item) => {
          ListItem() {
            Row() {
              Image(item.image)
                .width(40)
                .height(40)
                .objectFit(ImageFit.Cover)
                .margin({ right: 10 });

              Text(item.title)
                .fontSize(18)
                .fontWeight(FontWeight.Medium);
            }
            .padding(10)
            .backgroundColor('#FFFFFF')
            .borderRadius(5);
          }
          .margin({ bottom: 10 });
        });
      }
      .width('100%')
      .height('30%');
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

