import display from '@ohos.display';
import mediaquery from '@ohos.mediaquery';

@Entry
@Component
struct TabletMediaQueryApp {
  @State isTablet: boolean = false;
  private tabletListener: mediaquery.MediaQueryListener = mediaquery.matchMediaSync('(min-width: 600px) and (max-width: 1024px)');

  aboutToAppear() {
    const displayClass = display.getDefaultDisplaySync();
    this.checkIfTablet(displayClass.width);

    this.tabletListener.on('change', (result: mediaquery.MediaQueryResult) => {
      this.isTablet = result.matches;
    });
  }

  checkIfTablet(width: number) {
    this.isTablet = width >= 600 && width <= 1024;
  }

  build() {
    Column() {
      if (this.isTablet) {
        Flex({ direction: FlexDirection.Row, justifyContent: FlexAlign.SpaceBetween, alignItems: ItemAlign.Center }) {
          Image($r('app.media.app_icon'))
            .width(150)
            .height(150)
            .margin(20);

          Column() {
            Text('Tablet Layout')
              .fontSize(24)
              .fontColor(Color.Black);

            Text('Optimized for tablet devices')
              .fontSize(16)
              .fontColor(Color.Gray);
          }
        }
        .width('100%')
        .height('100%')
        .backgroundColor('#F5F5F5');
      } else {
        Flex({ direction: FlexDirection.Column, justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
          Text('Standard Layout')
            .fontSize(24)
            .fontColor(Color.Black);

          Image($r('app.media.app_icon'))
            .width(100)
            .height(100)
            .margin(20);

          Text('Default layout for non-tablet devices')
            .fontSize(16)
            .fontColor(Color.Gray);
        }
        .width('100%')
        .height('100%')
        .backgroundColor('#FFFFFF');
      }
    }
    .width('100%')
    .height('100%');
  }

  onDestroy() {
    if (this.tabletListener) {
      this.tabletListener.off('change');
    }
  }
}

