@Entry
@Component
struct SectionModificationApp {
  @State sections: string[] = ['Section 1', 'Section 2', 'Section 3'];

  build() {
    Column() {
      List({ space: 20 }) {
        ForEach(this.sections, (section: string, index: number) => {
          ListItem() {
            Text(section)
              .fontSize(20)
              .fontWeight(FontWeight.Bold)
              .textAlign(TextAlign.Center)
              .backgroundColor('#95efd2')
              .width('100%')
              .height(80)
              .borderRadius(10)
              .margin({ top: 5, bottom: 5 })
              .onClick(() => {
                this.modifySection(index);
              });
          }
        })
      }
      .width('100%')
      .height('80%')
      .backgroundColor('#eeeeee')
      .divider({ strokeWidth: 1, color: 0x222222 })

      Button('Add Section')
        .onClick(() => {
          this.addSection();
        })
        .width('90%')
        .height(50)
        .margin(10)
        .backgroundColor('#007DFF')
        .fontColor(Color.White)
        .fontSize(16)
        .fontWeight(FontWeight.Bold)
        .borderRadius(10)
    }
    .width('100%')
    .height('100%')
    .padding(10)
  }

  private addSection() {
    this.sections.push(`Section ${this.sections.length + 1}`);
  }

  private modifySection(index: number) {
    this.sections[index] = `Modified Section ${index + 1}`;
  }
}

