import promptAction from '@ohos.promptAction';

@Entry
@Component
struct UserForm {
  @State name: string = '';
  @State email: string = '';
  @State password: string = '';
  @State showDialog: boolean = false;

  build() {
    Column() {
      Text('User Registration')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value;
          });
      }

      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value;
          });
      }

      Column() {
        Text('Password:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your password' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .type(InputType.Password)
          .onChange((value: string) => {
            this.password = value;
          });
      }

      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.name && this.email && this.password) {
            this.showDialog = true;
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields'
            });
          }
        });

      if (this.showDialog) {
        Column() {
          Text('Submitted Information')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Name: ${this.name}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Password: ${this.password}`)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.showDialog = false;
              this.name = '';
              this.email = '';
              this.password = '';
            });
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

@Entry
@Component
struct CountryListApp {
  private countries: Array<Country> = [
    {
      name: 'United States',
      flag: 'app.media.us',
      capital: 'Washington, D.C.',
      population: 331000000,
      region: 'Americas'
    },
    {
      name: 'Canada',
      flag: 'app.media.ca',
      capital: 'Ottawa',
      population: 37700000,
      region: 'Americas'
    },
    {
      name: 'France',
      flag: 'app.media.fr',
      capital: 'Paris',
      population: 65200000,
      region: 'Europe'
    },
    {
      name: 'Japan',
      flag: 'app.media.jp',
      capital: 'Tokyo',
      population: 126000000,
      region: 'Asia'
    }
  ];

  @State selectedCountry: Country | null = null;
  dialogController: CustomDialogController = new CustomDialogController({
    builder: this.DialogBuilder,
    customStyle: true,
    alignment: DialogAlignment.Center
  });

  @Builder DialogBuilder() {
    if (this.selectedCountry) {
      Column() {
        Image(this.selectedCountry.flag)
          .width('100%')
          .height(100)
          .objectFit(ImageFit.Cover)
          .margin({ bottom: 16 });

        Text(this.selectedCountry.name)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 8 });

        Text(`Capital: ${this.selectedCountry.capital}`)
          .fontSize(16)
          .margin({ bottom: 4 });

        Text(`Population: ${this.selectedCountry.population.toLocaleString()}`)
          .fontSize(16)
          .margin({ bottom: 4 });

        Text(`Region: ${this.selectedCountry.region}`)
          .fontSize(16)
          .margin({ bottom: 16 });

        Button('Close')
          .width('100%')
          .height(40)
          .onClick(() => {
            this.dialogController.close();
          });
      }
      .padding(24)
      .width('90%')
      .backgroundColor(Color.White)
      .borderRadius(16);
    }
  }

  build() {
    Column() {
      Text('Countries List')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      List() {
        ForEach(this.countries, (country: Country) => {
          ListItem() {
            Row() {
              Image(country.flag)
                .width(50)
                .height(30)
                .objectFit(ImageFit.Cover)
                .margin({ right: 10 });

              Text(country.name)
                .fontSize(20)
                .fontWeight(FontWeight.Normal);
            }
            .padding(10)
            .onClick(() => {
              this.selectedCountry = country;
              this.dialogController.open();
            });
          }
          .backgroundColor('#FFFFFF')
          .borderRadius(5)
          .margin({ bottom: 10 });
        });
      }
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5');
  }
}

interface Country {
  name: string;
  flag: string;
  capital: string;
  population: number;
  region: string;
}

@Entry
@Component
struct CustomButtonWithRadius {
  @State buttonRadius: number = 0;

  build() {
    Column({ space: 10 }) {
      Button("Change Radius")
        .width(200)
        .height(50)
        .backgroundColor(Color.Blue)
        .borderRadius(this.buttonRadius)
        .fontColor(Color.White)
        .fontSize(16)
        .onClick(() => {
          this.buttonRadius = this.buttonRadius === 0 ? 25 : 0;
        })
        .margin(10)

      Text(`Current Border Radius: ${this.buttonRadius}`)
        .fontSize(18)
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

