              .textAlign(TextAlign.Center)
              .width('100%')
              .height(60)
              .backgroundColor('#F1F3F5')
              .borderRadius(8)
              .onClick(() => {
                this.reorderSection(index);
              });
          }
        }, (section: string) => section)
      }
      .width('100%')
      .height('80%')
      .padding(16)

      Button('Add New Section')
        .onClick(() => {
          this.addNewSection();
        })
        .margin(10)
        .width('90%')
        .height(50)
        .backgroundColor('#007DFF')
        .fontColor(Color.White)
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
  }

  private reorderSection(index: number) {
    if (index > 0) {
      const temp = this.sections[index];
      this.sections[index] = this.sections[index - 1];
      this.sections[index - 1] = temp;
      this.sections = [...this.sections];
    }
  }

  private addNewSection() {
    this.sections.push(`Section ${this.sections.length + 1}`);
  }
}

