@Entry
@Component
struct SegmentButtonExample {
  @State options: string[] = ['Option 1', 'Option 2', 'Option 3'];
  @State selectedIndex: number = 0;

  build() {
    Column() {
      Row() {
        ForEach(this.options, (option: string, index: number) => {
          Button(option)
            .onClick(() => {
              this.selectedIndex = index;
            })
            .backgroundColor(this.selectedIndex === index ? Color.Blue : Color.Gray)
            .fontColor(this.selectedIndex === index ? Color.White : Color.Black)
            .margin(5)
            .padding(10)
            .borderRadius(5)
        })
      }
      .width('80%')
      .justifyContent(FlexAlign.Center)
      .margin({ top: 20 })

      Row() {
        Button('Add Option')
          .onClick(() => {
            this.options.push(`Option ${this.options.length + 1}`);
            this.options = [...this.options];
          })
          .margin(5)
          .padding(10)
          .borderRadius(5)

        Button('Remove Option')
          .onClick(() => {
            if (this.options.length > 1) {
              this.options.pop();
              this.selectedIndex = Math.min(this.selectedIndex, this.options.length - 1);
              this.options = [...this.options];
            }
          })
          .margin(5)
          .padding(10)
          .borderRadius(5)
      }
      .width('80%')
      .justifyContent(FlexAlign.Center)
      .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor('#ffffff')
  }
}

