@Component
struct LoginScreen {
  @State username: string = ''
  @State password: string = ''
  @State errorMessage: string = ''
  @State isSuccess: boolean = false

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ bottom: 20 })

      Text('Welcome')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 30 })

      TextInput({ placeholder: 'Enter your username' })
        .width('80%')
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.username = value
        })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .width('80%')
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.password = value
        })

      Button('Login')
        .onClick(() => {
          if (this.validateCredentials()) {
            this.errorMessage = ''
            this.isSuccess = true
          } else {
            this.errorMessage = 'Invalid username or password.'
            this.isSuccess = false
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)
        .margin({ bottom: 20 })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .fontColor(Color.Red)
          .margin({ top: 10 })
      }

      if (this.isSuccess) {
        Text('Login successful!')
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .fontColor(Color.Green)
          .margin({ top: 10 })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }

  validateCredentials(): boolean {
    return this.username === 'admin' && this.password === 'password123'
  }
}

@Entry
@Component
struct SectionStyleCustomization {
  @State sections: Array<string> = ['Section A', 'Section B', 'Section C', 'Section D', 'Section E'];
  @State currentStyle: number = 0;

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.sections, (section: string, index: number) => {
          ListItem() {
            Column() {
              Text(section)
                .fontSize(20)
                .fontWeight(FontWeight.Bold)
                .textAlign(TextAlign.Center)
                .margin({ bottom: 5 })

              Text(this.getStyleDescription())
                .fontSize(14)
                .fontColor(Color.Gray)
            }
            .width('100%')
            .padding(15)
            .borderRadius(12)
            .border({
              width: this.currentStyle >= 1 ? 2 : 0,
              color: this.currentStyle >= 1 ? Color.Blue : Color.Transparent,
              style: BorderStyle.Solid
            })
            .backgroundColor(this.getBackgroundColor(index))
            .shadow(this.currentStyle >= 3 ? {
              radius: 6,
              color: Color.Gray,
              offsetX: 3,
              offsetY: 3
            } : null)
          }
          .opacity(this.currentStyle >= 4 ? 0.8 : 1)
          .margin({ top: 8, bottom: 8 })
        })
      }
      .width('100%')
      .height('75%')
      .divider({ strokeWidth: 1, color: Color.Gray })

      Row({ space: 15 }) {
        Button('Style 1')
          .onClick(() => { this.currentStyle = 1 })
          .backgroundColor(this.currentStyle === 1 ? '#007DFF' : '#EEEEEE')
          .fontColor(this.currentStyle === 1 ? Color.White : Color.Black)

        Button('Style 2')
          .onClick(() => { this.currentStyle = 2 })
          .backgroundColor(this.currentStyle === 2 ? '#007DFF' : '#EEEEEE')
          .fontColor(this.currentStyle === 2 ? Color.White : Color.Black)

        Button('Style 3')
          .onClick(() => { this.currentStyle = 3 })
          .backgroundColor(this.currentStyle === 3 ? '#007DFF' : '#EEEEEE')
          .fontColor(this.currentStyle === 3 ? Color.White : Color.Black)
      }
      .width('100%')
      .margin({ top: 15 })
      .justifyContent(FlexAlign.Center)
    }
    .width('100%')
    .height('100%')
    .padding(15)
    .backgroundColor('#F5F5F5')
  }

  private getBackgroundColor(index: number): ResourceColor {
    const colors = [
      ['#95efd2', '#ffb6c1', '#ffd700', '#98fb98', '#add8e6'],
      ['#e6f7ff', '#f0fff0', '#fff0f5', '#f0f8ff', '#fffaf0'],
      ['#ff6347', '#4682b4', '#9acd32', '#da70d6', '#ffa500'],
      ['#d8bfd8', '#ffdead', '#b0e0e6', '#f5deb3', '#d3d3d3'],
      ['#800000', '#006400', '#000080', '#4b0082', '#8b4513']
    ];
    return colors[this.currentStyle]?.[index % 5] || '#FFFFFF';
  }

  private getStyleDescription(): string {
    const descriptions = [
      'Basic styling with solid colors',
      'Light colors with borders',
      'Vibrant colors with borders',
      'Vibrant colors with shadow effects',
      'Semi-transparent with shadow effects'
    ];
    return descriptions[this.currentStyle] || 'Custom styling';
  }
}

