@Entry
@Component
struct TextInputErrorDisplay {
  @State text: string = ''
  @State showError: boolean = false
  @State errorMessage: string = ''

  validateInput(input: string): string | null {
    if (input.length === 0) {
      return 'Input cannot be empty'
    }
    if (!/^[a-zA-Z0-9]+$/.test(input)) {
      return 'Input must be alphanumeric'
    }
    return null
  }

  build() {
    Column({ space: 20 }) {
      TextInput({ placeholder: 'Enter text', text: this.text })
        .width('100%')
        .height(50)
        .showError(this.showError ? this.errorMessage : '')
        .onChange((value: string) => {
          this.text = value
          const validationError = this.validateInput(value)
          this.showError = validationError !== null
          this.errorMessage = validationError || ''
        })

      Button('Submit')
        .enabled(!this.showError && this.text.length > 0)
        .onClick(() => {
          console.info('Form submitted with value:', this.text)
        })
    }
    .padding(20)
    .width('100%')
  }
}

