@Entry
@Component
struct SegmentButtonMaxLimit {
  @State selectedIndex: number = 0;
  @State buttonCount: number = 3;
  private maxButtons: number = 5;

  build() {
    Column({ space: 20 }) {
      // Segment Buttons
      Row({ space: 10 }) {
        ForEach(Array.from<number, number>({ length: this.buttonCount }, (_, i: number) => i),
          (item: number) => {
            Button(`Option ${item + 1}`)
              .backgroundColor(this.selectedIndex === item ? Color.Blue : Color.Gray)
              .fontColor(Color.White)
              .onClick(() => {
                this.selectedIndex = item;
              })
              .margin(5)
              .padding(10)
              .borderRadius(5);
          },
          (item: number) => item.toString()
        )
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)

      // Button Controls
      Row({ space: 10 }) {
        Button('Add Button')
          .onClick(() => {
            if (this.buttonCount < this.maxButtons) {
              this.buttonCount++;
            }
          })
          .enabled(this.buttonCount < this.maxButtons)
          .margin(5);

        Button('Remove Button')
          .onClick(() => {
            if (this.buttonCount > 1) {
              this.buttonCount--;
              if (this.selectedIndex >= this.buttonCount) {
                this.selectedIndex = this.buttonCount - 1;
              }
            }
          })
          .enabled(this.buttonCount > 1)
          .margin(5);
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)

      // Status Display
      Text(`Selected: Option ${this.selectedIndex + 1}`)
        .fontSize(20)
        .margin({ top: 20 });

      Text(`Buttons: ${this.buttonCount}/${this.maxButtons}`)
        .fontSize(16)
        .margin({ top: 10 });

      // Visual indicator when max is reached
      if (this.buttonCount >= this.maxButtons) {
        Text('Maximum buttons reached!')
          .fontColor(Color.Red)
          .fontSize(14)
          .margin({ top: 10 });
      }

      // Image display based on selected option
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 20 })
        .visibility(this.selectedIndex === 0 ? Visibility.Visible : Visibility.None);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20)
  }
}

