@Component
struct MultiStateManagement {
  @State counter: number = 0;
  @State isLoggedIn: boolean = false;
  @State userProfile: UserProfile = new UserProfile("Anonymous", 0);
  @State todoList: Array<string> = ["Task 1", "Task 2"];

  build() {
    Column() {
      // Counter display and increment
      Text(`Counter: ${this.counter}`)
        .margin(10)
        .fontSize(20)

      Button('Increment Counter')
        .onClick(() => {
          this.counter += 1;
        })
        .margin(10)
        .width(200)

      // Login status display and toggle
      Text(`Logged In: ${this.isLoggedIn ? "Yes" : "No"}`)
        .margin(10)
        .fontSize(20)

      Button('Toggle Login Status')
        .onClick(() => {
          this.isLoggedIn = !this.isLoggedIn;
        })
        .margin(10)
        .width(200)

      // User profile display and update
      Text(`User: ${this.userProfile.name}, Age: ${this.userProfile.age}`)
        .margin(10)
        .fontSize(20)

      Button('Update Profile')
        .onClick(() => {
          this.userProfile = new UserProfile("John Smith", 30);
        })
        .margin(10)
        .width(200)

      // Todo list display and actions
      ForEach(this.todoList, (task: string) => {
        Text(`Task: ${task}`)
          .margin(10)
      })

      Button('Add Task')
        .onClick(() => {
          this.todoList = [...this.todoList, `Task ${this.todoList.length + 1}`];
        })
        .margin(10)
        .width(200)

      Button('Remove Task')
        .onClick(() => {
          this.todoList = this.todoList.slice(0, -1);
        })
        .margin(10)
        .width(200)
    }
    .padding(20)
  }
}

