@Entry
@Component
struct LoginForm {
  @State username: string = ''
  @State password: string = ''
  @State errorMessage: string = ''
  @State successMessage: string = ''

  validateForm(): boolean {
    if (this.username.length < 6) {
      this.errorMessage = 'Username must be at least 6 characters'
      return false
    }
    if (this.password.length < 8) {
      this.errorMessage = 'Password must be at least 8 characters'
      return false
    }
    this.errorMessage = ''
    return true
  }

  build() {
    Column() {
      Text('Login')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 30 })

      Text('Username')
        .fontSize(16)
        .fontWeight(FontWeight.Medium)
        .alignSelf(ItemAlign.Start)
        .margin({ bottom: 8 })

      TextInput({ placeholder: 'Enter username (min 6 chars)' })
        .width('100%')
        .height(40)
        .borderRadius(4)
        .borderWidth(1)
        .borderColor('#CCCCCC')
        .padding(8)
        .onChange((value: string) => {
          this.username = value
        })
        .margin({ bottom: 20 })

      Text('Password')
        .fontSize(16)
        .fontWeight(FontWeight.Medium)
        .alignSelf(ItemAlign.Start)
        .margin({ bottom: 8 })

      TextInput({ placeholder: 'Enter password (min 8 chars)' })
        .width('100%')
        .height(40)
        .borderRadius(4)
        .borderWidth(1)
        .borderColor('#CCCCCC')
        .padding(8)
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .margin({ bottom: 30 })

      Button('Login')
        .width('100%')
        .height(40)
        .backgroundColor('#007AFF')
        .fontColor(Color.White)
        .fontSize(16)
        .borderRadius(4)
        .onClick(() => {
          if (this.validateForm()) {
            this.successMessage = 'Login successful!'
          }
        })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 20 })
      }

      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(16)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

