  private carouselItems: Array<CarouselItem> = [
    {
      id: 1,
      image: $r('app.media.app_icon'),
      caption: 'Mountain View'
    },
    {
      id: 2,
      image: $r('app.media.app_icon'),
      caption: 'Ocean Sunset'
    },
    {
      id: 3,
      image: $r('app.media.app_icon'),
      caption: 'Forest Path'
    },
    {
      id: 4,
      image: $r('app.media.app_icon'),
      caption: 'Desert Dunes'
    }
  ];

  @State currentIndex: number = 0;

  build() {
    Column() {
      Text('Image Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Column() {
        Swiper(this.swiperController) {
          ForEach(this.carouselItems, (item: CarouselItem) => {
            Stack() {
              Image(item.image)
                .width('100%')
                .height(300)
                .objectFit(ImageFit.Cover)
                .borderRadius(16);
            }
          });
        }
        .width('100%')
        .height(300)
        .margin({ bottom: 16 })
        .autoPlay(true)
        .interval(3000)
        .indicator(true)
        .loop(true)
        .duration(500)
        .onChange((index: number) => {
          this.currentIndex = index;
        });

        Text(this.carouselItems[this.currentIndex].caption)
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 8 })
          .textAlign(TextAlign.Center);
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(20);

      Row() {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });

        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

interface CarouselItem {
  id: number;
  image: Resource;
  caption: string;
}

@Entry
@Component
struct UserForm {
  @State name: string = ''
  @State email: string = ''
  @State gender: string = 'Select Gender'
  @State showDialog: boolean = false
  @State genderOptions: SelectOption[] = [
    { value: 'Male' },
    { value: 'Female' },
    { value: 'Other' },
    { value: 'Prefer not to say' }
  ]

  build() {
    Column() {
      Text('User Information')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 })

      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value
          })
      }

      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value
          })
      }

      Column() {
        Text('Gender:')
          .fontSize(16)
          .margin({ bottom: 8 })

        Select(this.genderOptions)
          .selected(0)
          .value(this.gender)
          .onSelect((index: number, value: string) => {
            this.gender = value
          })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
      }

      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.name && this.email && this.gender !== 'Select Gender') {
            this.showDialog = true
          }
        })

      if (this.showDialog) {
        Column() {
          Text('Submitted Information')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 })

          Text(`Name: ${this.name}`)
            .fontSize(16)
            .margin({ bottom: 12 })

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 12 })

          Text(`Gender: ${this.gender}`)
            .fontSize(16)
            .margin({ bottom: 20 })

          Button('Close')
            .onClick(() => {
              this.showDialog = false
              this.name = ''
              this.email = ''
              this.gender = 'Select Gender'
            })
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
  }
}

