@Component
struct UserRegistrationForm {
  @State name: string = ''
  @State email: string = ''
  @State password: string = ''
  @State confirmationMessage: string = ''

  build() {
    Column() {
      // Form Title
      Text('User Registration')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      // Name Input
      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value
          })
      }

      // Email Input
      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value
          })
      }

      // Password Input
      Column() {
        Text('Password:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your password' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .type(InputType.Password)
          .onChange((value: string) => {
            this.password = value
          })
      }

      // Submit Button
      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.name && this.email && this.password) {
            this.confirmationMessage = `Name: ${this.name}\nEmail: ${this.email}\nPassword: ${this.password}`
          } else {
            this.confirmationMessage = 'Please fill all fields.'
          }
        })

      // Confirmation Message
      if (this.confirmationMessage) {
        Text(this.confirmationMessage)
          .fontSize(16)
          .fontColor(Color.Black)
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
  }
}

