@Component
struct ImageGalleryApp {
  private images: Array<ImageItem> = [
    new ImageItem(1, 'Mountain View', $r('app.media.app_icon'), 'A breathtaking view of a mountain range during sunset.'),
    new ImageItem(2, 'Ocean Waves', $r('app.media.app_icon'), 'Waves crashing against the shore on a sunny day.'),
    new ImageItem(3, 'Forest Trail', $r('app.media.app_icon'), 'A serene path winding through a lush green forest.'),
    new ImageItem(4, 'Desert Dunes', $r('app.media.app_icon'), 'Golden sand dunes under a clear blue sky.')
  ];

  @State selectedImage: ImageItem | null = null;
  dialogController: CustomDialogController = new CustomDialogController({
    builder: this.DialogBuilder,
    customStyle: true,
    alignment: DialogAlignment.Center
  });

  @Builder DialogBuilder() {
    if (this.selectedImage) {
      Column() {
        Image(this.selectedImage.image)
          .width('100%')
          .height(200)
          .borderRadius(8)
          .objectFit(ImageFit.Cover);

        Text(this.selectedImage.title)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 16, bottom: 8 });

        Text(this.selectedImage.description)
          .fontSize(16)
          .lineHeight(24);

        Button('Close')
          .width('100%')
          .height(40)
          .margin({ top: 24 })
          .onClick(() => {
            this.dialogController.close();
          });
      }
      .padding(24)
      .width('90%')
      .backgroundColor(Color.White)
      .borderRadius(16);
    }
  }

  build() {
    Column() {
      Text('Image Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Grid() {
        ForEach(this.images, (imageItem: ImageItem) => {
          GridItem() {
            Column() {
              Image(imageItem.image)
                .width('100%')
                .height(160)
                .borderRadius(8)
                .objectFit(ImageFit.Cover);

              Text(imageItem.title)
                .fontSize(16)
                .fontWeight(FontWeight.Medium)
                .margin({ top: 8 });

              Button('View Details')
                .onClick(() => {
                  this.selectedImage = imageItem;
                  this.dialogController.open();
                })
                .margin({ top: 4 });
            }
            .backgroundColor(Color.White)
            .borderRadius(12)
            .padding(16);
          }
        });
      }
      .columnsTemplate('1fr 1fr')
      .rowsGap(16)
      .columnsGap(16)
      .padding(16);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }
}

class ImageItem {
  id: number;
  title: string;
  image: Resource;
  description: string;

  constructor(id: number, title: string, image: Resource, description: string) {
    this.id = id;
    this.title = title;
    this.image = image;
    this.description = description;
  }
}

