@Entry
@Component
struct Index {
  @State selectedMovie: Movie | null = null;

  build() {
    if (this.selectedMovie == null) {
      Column() {
        Text('Movie List')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .padding(16);

        List() {
          ForEach(movies, (movie: Movie) => {
            ListItem() {
              Row() {
                Image(movie.poster)
                  .width(100)
                  .height(150)
                  .objectFit(ImageFit.Cover)
                  .margin({ right: 10 });
                Column() {
                  Text(movie.title)
                    .fontSize(20)
                    .fontWeight(FontWeight.Medium)
                    .padding({ bottom: 4 });
                  Text(`Release Date: ${movie.releaseDate}`)
                    .fontSize(16)
                    .padding({ bottom: 8 });
                }
              }
              .padding(16)
              .onClick(() => {
                this.selectedMovie = movie;
              });
            }
          });
        }
      }
    } else {
      Scroll() {
        Column() {
