import promptAction from '@ohos.promptAction';

@Entry
@Component
struct ContactForm {
  @State name: string = '';
  @State email: string = '';
  @State message: string = '';
  @State showDialog: boolean = false;

  build() {
    Column() {
      Text('Contact Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value;
          });
      }

      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value;
          });
      }

      Column() {
        Text('Message:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your message' })
          .width('100%')
          .height(100)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.message = value;
          });
      }

      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .fontColor(Color.White)
        .onClick(() => {
          if (this.name && this.email && this.message) {
            this.showDialog = true;
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields'
            });
          }
        });

      if (this.showDialog) {
        Column() {
          Text('Submitted Information')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Name: ${this.name}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Message: ${this.message}`)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .width('100%')
            .height(50)
            .fontSize(18)
            .backgroundColor('#007AFF')
            .fontColor(Color.White)
            .onClick(() => {
              this.showDialog = false;
              this.name = '';
              this.email = '';
              this.message = '';
            });
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

@Entry
@Component
struct MediaConditionResetHandler {
  @State mediaMatch: boolean = false;
  @State showContent: boolean = false;
  @State message: string = 'Waiting for media check...';

  build() {
    Column() {
      if (this.showContent) {
        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
      } else {
        Text(this.message)
          .fontSize(16)
          .fontColor(Color.Red)
      }

      Button('Check Media Conditions')
        .onClick(() => {
          this.checkAndResetMediaState();
        })
        .margin(20)

      Button('Reset State')
        .onClick(() => {
          this.resetMediaState();
        })
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }

  private checkAndResetMediaState() {
    this.mediaMatch = this.checkMediaConditions();

    if (!this.mediaMatch) {
      this.resetMediaState();
      this.message = 'Media conditions not met - state reset';
    } else {
      this.showContent = true;
      this.message = 'Media conditions met - content shown';
    }
  }

  private resetMediaState() {
    this.showContent = false;
    this.mediaMatch = false;
  }

  private checkMediaConditions(): boolean {
    return Math.random() > 0.5;
  }
}

