                .height(150)
                .borderRadius(8)
                .objectFit(ImageFit.Cover);

              Text(imageItem.category)
                .fontSize(16)
                .fontWeight(FontWeight.Medium)
                .margin({ top: 8 });
            }
            .backgroundColor(Color.White)
            .borderRadius(12)
            .padding(16);
          }
        });
      }
      .columnsTemplate('1fr 1fr')
      .rowsGap(16)
      .columnsGap(16)
      .padding(16)
      .layoutWeight(1);

      Row() {
        ForEach(this.categories, (category: string) => {
          Button(category)
            .onClick(() => {
              this.selectedCategory = category;
