import display from '@ohos.display';

@Entry
@Component
struct MediaQueryCardExample {
  @State screenWidth: number = 600; // Default screen width
  @State currentLayout: string = 'desktop';

  onPageShow() {
    const displayClass = display.getDefaultDisplaySync();
    this.screenWidth = displayClass.width;
    this.updateLayout();
  }

  updateLayout() {
    if (this.screenWidth <= 480) {
      this.currentLayout = 'mobile';
    } else if (this.screenWidth > 480 && this.screenWidth <= 1024) {
      this.currentLayout = 'tablet';
    } else {
      this.currentLayout = 'desktop';
    }
  }

  build() {
    Column() {
      Column() {
        Row() {
          Text('Media Query Card')
            .fontSize(this.currentLayout === 'mobile' ? 18 : 24)
            .fontWeight(FontWeight.Bold)
            .layoutWeight(1);

          Text(this.currentLayout.toUpperCase())
            .fontSize(14)
            .fontColor(Color.Gray);
        }
        .width('100%')
        .padding(12);

        if (this.currentLayout === 'mobile') {
          Column() {
            Image($r('app.media.app_icon'))
              .width(120)
              .height(120)
              .margin({ bottom: 12 });

            Text('Mobile Layout Content')
              .fontSize(16)
              .textAlign(TextAlign.Center);
          }
          .width('100%')
          .alignItems(HorizontalAlign.Center);
        } else if (this.currentLayout === 'tablet') {
          Row() {
            Image($r('app.media.app_icon'))
              .width(160)
              .height(160)
              .margin({ right: 16 });

            Column() {
              Text('Tablet Layout Content')
                .fontSize(18)
                .margin({ bottom: 8 });

              Text('This layout adapts to medium screen sizes')
                .fontSize(14)
                .fontColor(Color.Gray);
            }
            .layoutWeight(1);
          }
          .width('100%');
        } else {
          Column() {
            Image($r('app.media.app_icon'))
              .width(200)
              .height(200)
              .margin({ bottom: 16 });

            Column() {
              Text('Desktop Layout Content')
                .fontSize(20)
                .margin({ bottom: 8 });

              Text('This layout is optimized for large screens')
                .fontSize(16)
                .fontColor(Color.Gray);

              Text('Media queries help adapt to different screen sizes')
                .fontSize(14)
                .fontColor(Color.Gray)
                .margin({ top: 8 });
            }
            .width('100%');
          }
          .width('100%')
          .alignItems(HorizontalAlign.Center);
        }

        Row() {
          Button('Action 1')
            .width(this.currentLayout === 'mobile' ? '100%' : '48%')
            .height(40)
            .margin({ right: this.currentLayout === 'mobile' ? 0 : 8 });

          if (this.currentLayout !== 'mobile') {
            Button('Action 2')
              .width('48%')
              .height(40);
          }
        }
        .width('100%')
        .margin({ top: 16 });
      }
      .width(this.currentLayout === 'mobile' ? '90%' : '70%')
      .padding(16)
      .backgroundColor(Color.White)
      .borderRadius(12)
      .shadow({ radius: 8, color: Color.Gray, offsetX: 2, offsetY: 2 });

      Text(`Screen Width: ${this.screenWidth}px`)
        .fontSize(14)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#f5f5f5')
    .onAreaChange(() => {
      const displayClass = display.getDefaultDisplaySync();
      this.screenWidth = displayClass.width;
      this.updateLayout();
    });
  }
}

