@Entry
@Component
struct NoteApp {
  private noteItem: Note = {
    id: 0,
    title: '',
    content: '',
    timestamp: ''
  };

  @State notes: Array<Note> = [];
  @State newTitle: string = '';
  @State newContent: string = '';
  @State editNoteId: number | null = null;

  build() {
    Column() {
      TextInput({ placeholder: 'Enter title...', text: this.newTitle })
        .height(50)
        .width('90%')
        .onChange((value: string) => {
          this.newTitle = value;
        })
        .margin(10);

      TextArea({ placeholder: 'Enter content...', text: this.newContent })
        .height(100)
        .width('90%')
        .onChange((value: string) => {
          this.newContent = value;
        })
        .margin(10);

      Button(this.editNoteId !== null ? 'Update Note' : 'Add Note')
        .onClick(() => {
          if (this.newTitle.trim() && this.newContent.trim()) {
            const timestamp = new Date().toLocaleString();
            if (this.editNoteId !== null) {
              const index = this.notes.findIndex(note => note.id === this.editNoteId);
              this.notes[index] = {
                id: this.editNoteId,
                title: this.newTitle,
                content: this.newContent,
                timestamp: timestamp
              };
              this.editNoteId = null;
            } else {
              this.notes.push({
                id: Date.now(),
                title: this.newTitle,
                content: this.newContent,
                timestamp: timestamp
              });
            }
            this.newTitle = '';
            this.newContent = '';
          }
        })
        .margin(10);

      List() {
        ForEach(this.notes, (note: Note) => {
          ListItem() {
            Row() {
              Column() {
                Text(note.title)
                  .fontSize(18)
                  .fontWeight(FontWeight.Bold);
                Text(note.content)
                  .fontSize(14)
                  .margin({ top: 5 });
                Text(note.timestamp)
                  .fontSize(12)
                  .fontColor(Color.Gray)
                  .margin({ top: 5 });
              }
              .width('80%');

              Button('Edit')
                .onClick(() => {
                  this.newTitle = note.title;
                  this.newContent = note.content;
                  this.editNoteId = note.id;
                })
                .margin(5);

              Button('Delete')
                .onClick(() => {
                  this.notes = this.notes.filter(n => n.id !== note.id);
                })
                .margin(5);
            }
            .padding(10);
          }
        });
      }
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

interface Note {
  id: number;
  title: string;
  content: string;
  timestamp: string;
}

