@Entry
@Component
struct WeightConverter {
  @State weightInPounds: number = 0
  @State weightInKilograms: number = 0

  build() {
    Column() {
      TextInput({ placeholder: 'Enter weight in pounds' })
        .onChange((value: string) => {
          this.weightInPounds = parseFloat(value)
        })
        .margin({ bottom: 20 })

      Button('Convert to Kilograms')
        .onClick(() => {
          this.weightInKilograms = this.weightInPounds * 0.453592
        })
        .margin({ bottom: 20 })

      Text(`Weight in Kilograms: ${this.weightInKilograms.toFixed(2)}`)
        .fontSize(24)
        .margin({ top: 20 })
    }
    .padding(20)
  }
}

