        .width(100)
        .height(100)
        .margin(16)
    }
    .width('100%')
    .height('100%')
  }

  @Builder ProfileScreen() {
    Column() {
      Text('Profile Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin(16)
      Text(this.dynamicContent)
        .fontSize(16)
        .margin(16)
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(16)
    }
    .width('100%')
    .height('100%')
  }

  @Builder SettingsScreen() {
    Column() {
      Text('Settings Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin(16)
      Text(this.dynamicContent)
        .fontSize(16)
        .margin(16)
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(16)
    }
    .width('100%')
    .height('100%')
  }

  loadDynamicContent(index: number) {
    if (index === 0) {
      this.dynamicContent = 'Dynamic Content for Home Screen'
    } else if (index === 1) {
      this.dynamicContent = 'Dynamic Content for Profile Screen'
    } else {
      this.dynamicContent = 'Dynamic Content for Settings Screen'
    }
  }
