@Entry
@Component
struct ImageCarousel {
  private swiperController: SwiperController = new SwiperController();

  private carouselItems: Array<CarouselItem> = [
    {
      id: 1,
      image: $r('app.media.app_icon'),
      caption: 'Mountain View'
    },
    {
      id: 2,
      image: $r('app.media.app_icon'),
      caption: 'Ocean Sunset'
    },
    {
      id: 3,
      image: $r('app.media.app_icon'),
      caption: 'Forest Path'
    },
    {
      id: 4,
      image: $r('app.media.app_icon'),
      caption: 'Desert Dunes'
    }
  ];

  @State currentIndex: number = 0;
  @State isImageEnlarged: boolean = false;

  build() {
    Column() {
      Text('Image Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Column() {
        Swiper(this.swiperController) {
          ForEach(this.carouselItems, (item: CarouselItem) => {
            Stack() {
              Image(item.image)
                .width('100%')
                .height(300)
                .objectFit(ImageFit.Cover)
                .borderRadius(16)
                .onClick(() => {
                  this.isImageEnlarged = true;
                });
            }
          });
        }
        .width('100%')
        .height(300)
        .margin({ bottom: 16 })
        .autoPlay(true)
        .interval(3000)
        .indicator(true)
        .loop(true)
        .duration(500)
        .onChange((index: number) => {
          this.currentIndex = index;
        });

        Text(this.carouselItems[this.currentIndex].caption)
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 8 })
          .textAlign(TextAlign.Center);
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(20);

      Row() {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });

        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });

      if (this.isImageEnlarged) {
        Column() {
          Image(this.carouselItems[this.currentIndex].image)
            .width('100%')
            .height('100%')
            .objectFit(ImageFit.Cover)
            .onClick(() => {
              this.isImageEnlarged = false;
            });

          Text(this.carouselItems[this.currentIndex].caption)
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ top: 16 })
            .textAlign(TextAlign.Center);
        }
        .width('100%')
        .height('100%')
        .backgroundColor(Color.Black)
        .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

interface CarouselItem {
  id: number;
  image: Resource;
  caption: string;
}

