@Entry
@Component
struct ProfileScreen {
  @State userName: string = 'John Doe'
  @State userEmail: string = 'john@example.com'
  @State userBio: string = 'Software Developer with 5 years of experience in HarmonyOS and ArkTS development.'
  @State isEditing: boolean = false
  @State newName: string = ''
  @State newEmail: string = ''
  @State newBio: string = ''

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ bottom: 20 })

      if (this.isEditing) {
        TextInput({ placeholder: 'Enter new name', text: this.newName })
          .onChange((value: string) => {
            this.newName = value
          })
          .margin({ bottom: 10 })

        TextInput({ placeholder: 'Enter new email', text: this.newEmail })
          .onChange((value: string) => {
            this.newEmail = value
          })
          .margin({ bottom: 10 })

        TextInput({ placeholder: 'Enter new bio', text: this.newBio })
          .onChange((value: string) => {
            this.newBio = value
          })
          .margin({ bottom: 10 })

        Button('Save')
          .onClick(() => {
            if (this.newName) {
              this.userName = this.newName
            }
            if (this.newEmail) {
              this.userEmail = this.newEmail
            }
            if (this.newBio) {
              this.userBio = this.newBio
            }
            this.isEditing = false
          })
      } else {
        Text(this.userName)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 10 })

        Text(this.userEmail)
          .fontSize(18)
          .margin({ bottom: 10 })

        Text(this.userBio)
          .fontSize(16)
          .margin({ bottom: 20 })

        Button('Edit Profile')
          .onClick(() => {
            this.isEditing = true
            this.newName = this.userName
            this.newEmail = this.userEmail
            this.newBio = this.userBio
          })
      }
    }
    .padding(20)
  }
}

