struct ClearAllTextExample {
  @State inputText: string = '';
  @State areaText: string = '';
  inputController: TextInputController = new TextInputController();
  areaController: TextAreaController = new TextAreaController();

  build() {
    Column({ space: 20 }) {
      TextInput({
        placeholder: 'Enter text here',
        text: this.inputText,
        controller: this.inputController
      })
      .width('90%')
      .height(50)
      .onChange((value: string) => {
        this.inputText = value;
      })

      TextArea({
        placeholder: 'Enter multi-line text here',
        text: this.areaText,
        controller: this.areaController
      })
      .width('90%')
      .height(150)
      .onChange((value: string) => {
        this.areaText = value;
      })

      Button('Clear All')
      .width(150)
      .height(40)
      .onClick(() => {
        this.inputText = '';
        this.areaText = '';
        this.inputController.caretPosition(0);
        this.areaController.caretPosition(0);
      })

