      Text('TextArea Content:')
      .fontSize(16)
      .margin({ top: 20 })

      Text(this.areaText)
      .fontSize(18)
      .fontColor(Color.Green)
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#ffffff')
  }
}

