            this.updateExternalState('Option 1 selected');
          })
          .margin(5)
          .padding(10)
          .borderRadius(5);

        Button('Option 2')
          .backgroundColor(this.selectedIndex === 1 ? '#007DFF' : '#D2B48C')
          .onClick(() => {
            this.selectedIndex = 1;
            this.updateExternalState('Option 2 selected');
          })
          .margin(5)
          .padding(10)
          .borderRadius(5);

        Button('Option 3')
          .backgroundColor(this.selectedIndex === 2 ? '#007DFF' : '#D2B48C')
          .onClick(() => {
            this.selectedIndex = 2;
            this.updateExternalState('Option 3 selected');
          })
          .margin(5)
          .padding(10)
          .borderRadius(5);
      }
      .justifyContent(FlexAlign.Center)
      .width('100%')
      .padding(10);

      Text(this.externalState)
        .fontSize(20)
        .margin({ top: 20 });

      Text(`Selected Option: ${this.selectedIndex + 1}`)
        .fontSize(20)
        .margin({ top: 20 });

