@Entry
@Component
struct ItemRestrictionExample {
  @State options: string[] = ['Option A', 'Option B', 'Option C', 'Option D', 'Option E'];
  @State selectedOptions: string[] = [];
  @State maxSelections: number = 3; // Maximum number of options that can be selected

  build() {
    Column() {
      Text('Select up to ' + this.maxSelections + ' options:')
        .fontSize(18)
        .margin({ bottom: 20 });

      ForEach(this.options, (option: string) => {
        Row() {
          Text(option)
            .fontSize(16)
            .layoutWeight(1);

          Checkbox()
            .select(this.selectedOptions.includes(option))
            .onChange((isChecked: boolean) => {
              if (isChecked) {
                if (this.selectedOptions.length < this.maxSelections) {
                  this.selectedOptions.push(option);
                }
              } else {
                this.selectedOptions = this.selectedOptions.filter(item => item !== option);
              }
            });
        }
        .width('100%')
        .padding(10)
        .margin({ bottom: 5 });
      })

      Text('Selected options: ' + this.selectedOptions.join(', '))
        .fontSize(16)
        .margin({ top: 20 });

      Button('Reset Selection')
        .onClick(() => {
          this.selectedOptions = [];
        })
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

@Entry
@Component
struct LoginScreen {
  @State username: string = ''
  @State password: string = ''
  @State loginMessage: string = ''

  validateInput(): boolean {
    if (this.username && this.password) {
      this.loginMessage = 'Login successful!'
      return true
    } else {
      this.loginMessage = 'Please enter both username and password.'
      return false
    }
  }

  build() {
    Column() {
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your username', text: this.username })
        .onChange((value: string) => {
          this.username = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      Button('Login')
        .onClick(() => {
          this.validateInput()
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      if (this.loginMessage) {
        Text(this.loginMessage)
          .fontSize(16)
          .margin({ top: 20 })
          .fontColor(this.loginMessage === 'Login successful!' ? Color.Green : Color.Red)
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

