@Entry
@Component
struct TodoList {
  @State tasks: Array<Task> = []
  @State newTask: string = ''

  build() {
    Column() {
      TextInput({ placeholder: 'Enter a new task' })
        .onChange((value: string) => {
          this.newTask = value
        })
        .margin({ bottom: 20 })

      Button('Add Task')
        .onClick(() => {
          if (this.newTask.trim()) {
            this.tasks.push({
              id: Date.now(),
              content: this.newTask,
              completed: false
            })
            this.newTask = ''
          }
        })
        .margin({ bottom: 20 })

      List() {
        ForEach(this.tasks, (task: Task, index: number) => {
          ListItem() {
            Row() {
              Checkbox()
                .select(task.completed)
                .onChange((value: boolean) => {
                  this.tasks[index].completed = value
                })
                .margin({ right: 10 })

              Text(task.content)
                .fontSize(18)
                .decoration({
                  type: task.completed ? TextDecorationType.LineThrough : TextDecorationType.None
                })
                .layoutWeight(1)

              Button() {
                Image($r('app.media.app_icon'))
                  .width(20)
                  .height(20)
              }
              .onClick(() => {
                this.tasks.splice(index, 1)
              })
              .margin({ left: 10 })
            }
            .width('100%')
            .justifyContent(FlexAlign.SpaceBetween)
          }
        })
      }
      .layoutWeight(1)
      .divider({ strokeWidth: 1, color: '#F1F1F1' })
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

interface Task {
  id: number
  content: string
  completed: boolean
}

