@Entry
@Component
struct EventHandlingApp {
  @State buttonText: string = 'Click Me';
  @State inputText: string = '';
  @State toggleState: boolean = false;
  @State imageClickCount: number = 0;
  @State sliderValue: number = 50;

  private handleButtonClick() {
    this.buttonText = 'Button Clicked!';
    console.log('Button click event handled');
  }

  private handleInputChange(value: string) {
    this.inputText = value;
    console.log('Input changed:', value);
  }

  private handleToggle() {
    this.toggleState = !this.toggleState;
    console.log('Toggle state:', this.toggleState);
  }

  private handleImageClick() {
    this.imageClickCount++;
    console.log('Image clicked', this.imageClickCount, 'times');
  }

  private handleSliderChange(value: number) {
    this.sliderValue = value;
    console.log('Slider value changed to:', value);
  }

  build() {
    Column({ space: 20 }) {
      Button(this.buttonText)
        .onClick(() => {
          this.handleButtonClick();
        })
        .width(200)
        .height(50)
        .backgroundColor(Color.Blue)
        .fontColor(Color.White)

      TextInput({ placeholder: 'Type something' })
        .onChange((value: string) => {
          this.handleInputChange(value);
        })
        .width('80%')
        .height(50)
        .border({ width: 1, color: Color.Gray })

      Text(`You typed: ${this.inputText}`)
        .fontSize(16)

      Toggle({ type: ToggleType.Switch, isOn: this.toggleState })
        .onChange((isOn: boolean) => {
          this.handleToggle();
        })
        .width(100)

      Text(this.toggleState ? 'Toggle ON' : 'Toggle OFF')
        .fontSize(16)

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .onClick(() => {
          this.handleImageClick();
        })

      Text(`Image clicked ${this.imageClickCount} times`)
        .fontSize(16)

      Slider({
        value: this.sliderValue,
        min: 0,
        max: 100,
        step: 1,
        style: SliderStyle.OutSet
      })
        .onChange((value: number) => {
          this.handleSliderChange(value);
        })
        .width('80%')

      Text(`Slider value: ${this.sliderValue}`)
        .fontSize(16)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .padding(20)
  }
}

@Entry
@Component
struct TextInputWithLetterSpacing {
  @State text: string = 'Configure character spacing'
  @State letterSpacing: number = 2.0

  build() {
    Column() {
      TextInput({ text: this.text })
        .width('90%')
        .height(50)
        .fontSize(16)
        .letterSpacing(this.letterSpacing)
        .onChange((value: string) => {
          this.text = value
        })

      Slider({
        value: this.letterSpacing,
        min: 0,
        max: 10,
        step: 0.5
      })
        .width('90%')
        .onChange((value: number) => {
          this.letterSpacing = value
        })

      Text(`Current Letter Spacing: ${this.letterSpacing}`)
        .fontSize(14)
        .margin({ top: 10 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

@Entry
@Component
struct ImageGallery {
  @State selectedImage: Resource = $r('app.media.app_icon')
  @State showFullScreen: boolean = false

  private images: Resource[] = [
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon')
  ]

  build() {
    Column() {
      if (this.showFullScreen) {
        Stack() {
          Image(this.selectedImage)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%')

          Button('Close')
            .onClick(() => {
              this.showFullScreen = false
            })
            .position({ x: 20, y: 20 })
            .backgroundColor('#FFFFFF')
            .padding({ left: 10, right: 10, top: 5, bottom: 5 })
            .borderRadius(5)
        }
      } else {
        Grid() {
          ForEach(this.images, (image: Resource) => {
            GridItem() {
              Image(image)
                .width('100%')
                .aspectRatio(1)
                .objectFit(ImageFit.Cover)
                .borderRadius(5)
                .onClick(() => {
                  this.selectedImage = image
                  this.showFullScreen = true
                })
            }
          })
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsGap(10)
        .columnsGap(10)
        .padding(10)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

