import router from '@ohos.router';

interface Movie {
  id: number;
  title: string;
  image: Resource;
  releaseDate: string;
  director: string;
  description: string;
}

const movies: Movie[] = [
  {
    id: 1,
    title: 'Inception',
    image: $r('app.media.app_icon'),
    releaseDate: '2010-07-16',
    director: 'Christopher Nolan',
    description: 'A skilled thief who steals corporate secrets through dream-sharing technology is given the task of planting an idea into a CEO\'s mind.',
  },
  {
    id: 2,
    title: 'The Matrix',
    image: $r('app.media.app_icon'),
    releaseDate: '1999-03-31',
    director: 'Lana Wachowski, Lilly Wachowski',
    description: 'A computer hacker learns about the true nature of his reality and his role in the war against its controllers.',
  },
  {
    id: 3,
    title: 'Interstellar',
    image: $r('app.media.app_icon'),
    releaseDate: '2014-11-07',
    director: 'Christopher Nolan',
    description: 'A team of explorers travel through a wormhole in space in an attempt to ensure humanity\'s survival.',
  },
];

@Entry
@Component
struct MovieListApp {
  @State selectedMovie: Movie | null = null;
  dialogController: CustomDialogController = new CustomDialogController({
    builder: this.DialogBuilder,
    customStyle: true,
    alignment: DialogAlignment.Center
  });

  @Builder DialogBuilder() {
    if (this.selectedMovie) {
      Column() {
        Image(this.selectedMovie.image)
          .width('100%')
          .height(200)
          .borderRadius(8)
          .objectFit(ImageFit.Cover);

        Text(this.selectedMovie.title)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 16, bottom: 8 });

        Text(`Released on: ${this.selectedMovie.releaseDate}`)
          .fontSize(16)
          .fontColor('#666666')
          .margin({ bottom: 8 });

        Text(`Director: ${this.selectedMovie.director}`)
          .fontSize(16)
          .fontColor('#666666')
          .margin({ bottom: 16 });

        Text('Description:')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ bottom: 4 });

        Text(this.selectedMovie.description)
          .fontSize(16)
          .lineHeight(24);

        Button('Close')
          .onClick(() => {
            this.dialogController.close();
          })
          .margin({ top: 24 });
      }
      .padding(24)
      .width('90%')
      .backgroundColor(Color.White)
      .borderRadius(16);
    }
  }

  build() {
    Column() {
      Text('Movie List')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .padding(16);

      List() {
        ForEach(movies, (movie: Movie) => {
          ListItem() {
            Row() {
              Image(movie.image)
                .width(100)
                .height(150)
                .borderRadius(8)
                .objectFit(ImageFit.Cover);

              Column() {
                Text(movie.title)
                  .fontSize(20)
                  .fontWeight(FontWeight.Medium)
                  .margin({ bottom: 4 });

                Text(movie.description)
                  .fontSize(14)
                  .maxLines(2)
                  .textOverflow({ overflow: TextOverflow.Ellipsis });
              }
              .padding(8);
            }
            .onClick(() => {
              this.selectedMovie = movie;
              this.dialogController.open();
            });
          }
        });
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5');
  }
}

