    .backgroundColor('#F5F5F5')
  }
}

@Entry
@Component
struct TabBarWithSearch {
  @State currentTab: number = 0;
  @State searchText: string = '';

  @State tab1Items: string[] = ['Apple', 'Banana', 'Orange', 'Grapes', 'Mango'];
  @State tab2Items: string[] = ['Pineapple', 'Strawberry', 'Watermelon', 'Cherry', 'Blueberry'];
  @State tab3Items: string[] = ['Lemon', 'Peach', 'Pear', 'Kiwi', 'Plum'];

  filteredItems(): string[] {
    let items: string[];
    switch (this.currentTab) {
      case 0:
        items = this.tab1Items;
        break;
      case 1:
        items = this.tab2Items;
        break;
      case 2:
        items = this.tab3Items;
        break;
      default:
        items = [];
    }

    if (this.searchText.trim() === '') {
      return items;
    } else {
      return items.filter(item =>
        item.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  build() {
    Column() {
      // Tab Bar
      Row() {
        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Tab 1')
            .fontSize(12)
            .fontColor(this.currentTab === 0 ? '#007AFF' : '#666666')
        }
        .width('33%')
        .onClick(() => {
          this.currentTab = 0;
          this.searchText = '';
        })

        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Tab 2')
            .fontSize(12)
            .fontColor(this.currentTab === 1 ? '#007AFF' : '#666666')
        }
        .width('33%')
        .onClick(() => {
          this.currentTab = 1;
          this.searchText = '';
        })

        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Tab 3')
            .fontSize(12)
            .fontColor(this.currentTab === 2 ? '#007AFF' : '#666666')
        }
        .width('33%')
        .onClick(() => {
          this.currentTab = 2;
          this.searchText = '';
        })
      }
      .width('100%')
      .height(60)
      .backgroundColor(Color.White)
      .border({ width: { top: 0.5 }, color: '#cccccc' })

      // Search Bar
      TextInput({
        placeholder: 'Search items...',
        text: this.searchText
      })
        .width('100%')
        .onChange((value: string) => {
          this.searchText = value;
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 })

      // List of Items
      if (this.filteredItems().length > 0) {
        List() {
          ForEach(this.filteredItems(), (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(18)
                .padding(12)
            }
          }, (item: string) => item)
        }
      } else {
        Text('No items found')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
  }
}

@Entry
@Component
struct RatingWithMinimumValidation {
  @State rating: number = 3.0;
  @State minRating: number = 1.0;

  build() {
    Column() {
      Rating({ rating: this.rating, indicator: false })
        .stars(5)
        .stepSize(0.5)
        .margin({ top: 20 })
        .onChange((value: number) => {
          this.rating = Math.max(value, this.minRating);
        })

      Text(`Current Rating: ${this.rating}`)
        .fontSize(18)
        .margin({ top: 10 })

      Text(`Minimum Allowed Rating: ${this.minRating}`)
        .fontSize(16)
        .fontColor(Color.Gray)
        .margin({ top: 5 })

      TextInput({ placeholder: 'Set minimum rating (0-5)' })
        .width('80%')
        .margin({ top: 20 })
        .onChange((value: string) => {
          const newMin = parseFloat(value);
          if (!isNaN(newMin) && newMin >= 0 && newMin <= 5) {
            this.minRating = newMin;
            this.rating = Math.max(this.rating, this.minRating);
          }
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20)
  }
}

