@Entry
@Component
struct TaskSubmissionApp {
  @State tasks: Array<Task> = []
  @State newTaskDescription: string = ''
  @State selectedDate: Date = new Date()
  @State showSubmitted: boolean = false
  @State submittedTask: Task | null = null

  build() {
    Column() {
      // Input for task description
      TextInput({ placeholder: 'Enter task description', text: this.newTaskDescription })
        .onChange((value: string) => {
          this.newTaskDescription = value
        })
        .width('100%')
        .margin({ bottom: 20 })

      // Date picker for deadline
      DatePicker({
        start: new Date(),
        end: new Date('2030-12-31'),
        selected: this.selectedDate
      })
        .onDateChange((value: Date) => {
          this.selectedDate = value
        })
        .margin({ bottom: 20 })

      // Submit button
      Button('Submit Task')
        .onClick(() => {
          if (this.newTaskDescription) {
            const newTask: Task = {
              id: Date.now(),
              description: this.newTaskDescription,
              deadline: this.selectedDate.toLocaleDateString()
            }
            this.tasks.push(newTask)
            this.submittedTask = newTask
            this.showSubmitted = true
            this.newTaskDescription = ''
          }
        })
        .width('100%')
        .margin({ bottom: 20 })

      // Display submitted task
      if (this.showSubmitted && this.submittedTask) {
        Column() {
          Text('Task Submitted:')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 10 })

          Text(`Description: ${this.submittedTask.description}`)
            .fontSize(16)
            .margin({ bottom: 8 })

          Text(`Deadline: ${this.submittedTask.deadline}`)
            .fontSize(16)
            .margin({ bottom: 8 })

          Button('OK')
            .onClick(() => {
              this.showSubmitted = false
            })
            .margin({ top: 20 })
        }
        .padding(20)
        .backgroundColor('#F0F0F0')
        .borderRadius(12)
        .width('90%')
      }

      // List of all tasks
      List() {
        ForEach(this.tasks, (task: Task) => {
          ListItem() {
            Row() {
              Column() {
                Text(task.description)
                  .fontSize(18)
                  .fontWeight(FontWeight.Bold)
                Text(`Due: ${task.deadline}`)
                  .fontSize(14)
                  .fontColor(Color.Gray)
              }
              .margin({ right: 10 })

              Button() {
                Image($r('app.media.app_icon'))
                  .width(20)
                  .fillColor(Color.Red)
              }
              .onClick(() => {
                this.tasks.splice(this.tasks.indexOf(task), 1)
              })
            }
            .padding(10)
            .borderRadius(5)
            .backgroundColor(Color.White)
            .margin({ top: 10 })
          }
        })
      }
      .layoutWeight(1)
      .width('100%')
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

interface Task {
  id: number;
  description: string;
  deadline: string;
}

