import mediaquery from '@ohos.mediaquery';

@Entry
@Component
struct MediaQueryDetachExample {
  @State private screenSize: string = 'Unknown';
  @State private showComponent: boolean = true;
  private mediaQueryListener: mediaquery.MediaQueryListener | null = null;

  aboutToAppear() {
    this.mediaQueryListener = mediaquery.matchMediaSync('(max-width: 600px)');
    this.mediaQueryListener.on('change', (result: mediaquery.MediaQueryResult) => {
      this.screenSize = result.matches ? 'Small Screen' : 'Large Screen';
    });
  }

  aboutToDisappear() {
    if (this.mediaQueryListener) {
      this.mediaQueryListener.off('change');
      this.mediaQueryListener = null;
      console.info('Media query listener successfully detached');
    }
  }

  build() {
    Column() {
      if (this.showComponent) {
        Column() {
          Text('Current Screen Size:')
            .fontSize(20)
            .margin(10);

          Text(this.screenSize)
            .fontSize(24)
            .fontColor(Color.Blue)
            .margin(10);

          Image($r('app.media.app_icon'))
            .width(100)
            .height(100)
            .margin(20);
        }
      }

      Button('Toggle Component')
        .onClick(() => {
          this.showComponent = !this.showComponent;
        })
        .margin(20);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

