@Entry
@Component
struct DynamicButtonStyling {
  @State buttonState: string = 'normal'
  @State clickCount: number = 0

  build() {
    Column({ space: 20 }) {
      Button(this.getButtonText())
        .width(200)
        .height(50)
        .backgroundColor(this.getButtonColor())
        .fontColor(this.getTextColor())
        .fontSize(this.getFontSize())
        .borderRadius(this.getBorderRadius())
        .onClick(() => {
          this.clickCount++
          this.updateButtonState()
        })
        .margin(20)

      Button('Reset Styles')
        .width(200)
        .height(40)
        .backgroundColor('#CCCCCC')
        .onClick(() => {
          this.clickCount = 0
          this.buttonState = 'normal'
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }

  private updateButtonState() {
    if (this.clickCount < 3) {
      this.buttonState = 'normal'
    } else if (this.clickCount < 6) {
      this.buttonState = 'hover'
    } else if (this.clickCount < 9) {
      this.buttonState = 'active'
    } else {
      this.buttonState = 'disabled'
    }
  }

  private getButtonText(): string {
    switch (this.buttonState) {
      case 'normal': return 'Click Me'
      case 'hover': return 'Hover State'
      case 'active': return 'Active!'
      case 'disabled': return 'Disabled'
      default: return 'Button'
    }
  }

  private getButtonColor(): Color | string {
    switch (this.buttonState) {
      case 'normal': return '#317aff'
      case 'hover': return '#1a5fcc'
      case 'active': return '#0a4eb8'
      case 'disabled': return '#cccccc'
      default: return '#317aff'
    }
  }

  private getTextColor(): Color | string {
    switch (this.buttonState) {
      case 'disabled': return '#666666'
      default: return '#ffffff'
    }
  }

  private getFontSize(): number {
    switch (this.buttonState) {
      case 'active': return 18
      default: return 16
    }
  }

  private getBorderRadius(): number {
    switch (this.buttonState) {
      case 'normal': return 8
      case 'hover': return 12
      case 'active': return 16
      default: return 8
    }
  }
}

