@Component
struct FlowItemStateManagement {
  @State items: string[] = ['Item 1', 'Item 2', 'Item 3'];
  @State selectedIndex: number = -1;

  build() {
    Column() {
      Flex({ direction: FlexDirection.Row, wrap: FlexWrap.Wrap }) {
        ForEach(this.items, (item: string, index: number) => {
          Column() {
            Image($r('app.media.app_icon'))
              .width(40)
              .height(40)
              .margin(5)
            Text(item)
              .fontSize(16)
              .textAlign(TextAlign.Center)
          }
          .width(100)
          .height(120)
          .backgroundColor(this.selectedIndex === index ? '#DDDDDD' : '#F5F5F5')
          .border({ width: 1, color: '#AAAAAA', radius: 5 })
          .margin(5)
          .onClick(() => {
            this.selectedIndex = index;
          })
        })
      }
      .width('100%')
      .height('70%')
      .padding(10)

      Row() {
        Button('Add Item')
          .onClick(() => {
            this.items = [...this.items, `Item ${this.items.length + 1}`];
          })
          .margin(5)
          .width(120)

        Button('Remove Selected')
          .onClick(() => {
            if (this.selectedIndex >= 0) {
              this.items.splice(this.selectedIndex, 1);
              this.items = [...this.items];
              this.selectedIndex = -1;
            }
          })
          .margin(5)
          .width(120)
      }
      .justifyContent(FlexAlign.SpaceAround)
      .width('100%')
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

