@Entry
@Component
struct GestureButtonExample {
  @State buttonPressed: boolean = false;
  @State tapCount: number = 0;
  @State message: string = "Tap or Swipe the Button";

  build() {
    Column({ space: 20 }) {
      Button('Gesture Button')
        .width(200)
        .height(60)
        .backgroundColor(this.buttonPressed ? Color.Red : Color.Blue)
        .gesture(
          TapGesture({ count: 1 })
            .onAction(() => {
              this.buttonPressed = !this.buttonPressed;
              this.tapCount += 1;
              this.message = "Single Tap Detected";
            })
        )
        .gesture(
          SwipeGesture({ direction: SwipeDirection.Horizontal })
            .onAction(() => {
              this.message = "Swipe Detected";
            })
        );

      Text(`Tap Count: ${this.tapCount}`)
        .fontSize(20)
        .fontColor(Color.Black);

      Text(this.message)
        .fontSize(20)
        .fontColor(Color.Black);

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .gesture(
          TapGesture({ count: 2 })
            .onAction(() => {
              this.message = "Double Tap Detected on Image";
            })
        );
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(0xf5f5f5);
  }
}

