      .margin(20)

      Text(this.isOn ? 'Switch is ON' : 'Switch is OFF')
        .fontSize(20)
        .fontColor(this.isOn ? '#4CAF50' : '#F44336')
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor('#F5F5F5')
  }
}

