import promptAction from '@ohos.promptAction'

@Entry
@Component
struct VotingEligibilityApp {
  @State age: string = ''
  @State showMessage: boolean = false
  @State eligibilityMessage: string = ''

  build() {
    Column() {
      Text('Voting Eligibility Check')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 })

      Column() {
        Text('Age:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your age' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.age = value
          })
      }

      Button('Check Eligibility')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.age) {
            const ageNumber = parseInt(this.age)
            if (ageNumber >= 18) {
              this.eligibilityMessage = 'You are eligible to vote!'
            } else {
              this.eligibilityMessage = 'You are not eligible to vote yet.'
            }
            this.showMessage = true
          } else {
            promptAction.showToast({
              message: 'Please enter your age'
            })
          }
        })

      if (this.showMessage) {
        Text(this.eligibilityMessage)
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
  }
}

@Entry
@Component
struct NumberParityChecker {
    @State inputNumber: string = '';
    @State isEven: boolean = false;
    @State resultMessage: string = '';

    checkParity() {
        const number = parseFloat(this.inputNumber);
        if (isNaN(number)) {
            this.resultMessage = 'Please enter a valid number.';
            this.isEven = false;
        } else {
            this.isEven = number % 2 === 0;
            this.resultMessage = this.isEven ? 'Even Number' : 'Odd Number';
        }
    }

    build() {
        Column({ space: 20 }) {
            TextInput({ placeholder: 'Enter a number' })
                .type(InputType.Number)
                .onChange((value: string) => {
                    this.inputNumber = value;
                })
                .margin({ bottom: 20 })

            Button('Check Parity', { type: ButtonType.Capsule })
                .onClick(() => {
                    this.checkParity();
                })
                .backgroundColor('#0D9FFB')
                .fontColor(Color.White)
                .padding(10)
                .margin({ bottom: 20 })

            Text(this.resultMessage)
                .fontSize(20)
                .fontColor(this.isEven ? Color.Green : Color.Red)
                .margin({ bottom: 20 })
        }
        .padding(20)
        .width('100%')
        .height('100%')
    }
}

