@Entry
@Component
struct SearchableListApp {
  @State items: string[] = [
    'Apple',
    'Banana',
    'Orange',
    'Grapes',
    'Mango',
    'Pineapple',
    'Strawberry',
    'Watermelon',
    'Cherry',
    'Blueberry',
    'Lemon',
    'Peach'
  ];

  @State searchText: string = '';

  filteredItems(): string[] {
    if (this.searchText.trim() === '') {
      return this.items;
    } else {
      return this.items.filter(item =>
        item.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  build() {
    Column() {
      // Search Bar
      TextInput({
        placeholder: 'Search items...',
        text: this.searchText
      })
        .width('100%')
        .onChange((value: string) => {
          this.searchText = value;
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      // List of Filtered Items
      if (this.filteredItems().length > 0) {
        List() {
          ForEach(this.filteredItems(), (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(18)
                .padding(12);
            }
          }, (item: string) => item);
        }
      } else {
        // Display a message when no items match the search
        Text('No items found')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

import mediaquery from '@ohos.mediaquery';

@Entry
@Component
struct ParentComponent {
  @State isLargeScreen: boolean = false;
  @State isDarkMode: boolean = false;

  aboutToAppear() {
    const screenSizeListener = mediaquery.matchMediaSync('(min-width: 600vp)');
    const colorSchemeListener = mediaquery.matchMediaSync('(prefers-color-scheme: dark)');

    screenSizeListener.on('change', (result: mediaquery.MediaQueryResult) => {
      this.isLargeScreen = result.matches;
    });

    colorSchemeListener.on('change', (result: mediaquery.MediaQueryResult) => {
      this.isDarkMode = result.matches;
    });
  }

  build() {
    Column() {
      Text('Parent Component')
        .fontSize(24)
        .fontColor(this.isDarkMode ? Color.White : Color.Black);

      ChildComponent({
        isLargeScreen: this.isLargeScreen,
        isDarkMode: this.isDarkMode
      })
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.isDarkMode ? '#333333' : '#FFFFFF')
  }
}

@Component
struct ChildComponent {
  @Prop isLargeScreen: boolean;
  @Prop isDarkMode: boolean;

  build() {
    Column() {
      Text('Child Component')
        .fontSize(this.isLargeScreen ? 20 : 16)
        .fontColor(this.isDarkMode ? Color.White : Color.Black);

      Image($r('app.media.app_icon'))
        .width(this.isLargeScreen ? 200 : 100)
        .height(this.isLargeScreen ? 200 : 100)
        .margin(10);

      GrandchildComponent({
        isLargeScreen: this.isLargeScreen,
        isDarkMode: this.isDarkMode
      })
    }
    .padding(10)
  }
}

