    new ImageItem($r('app.media.app_icon'), 'Image 1'),
    new ImageItem($r('app.media.app_icon'), 'Image 2'),
    new ImageItem($r('app.media.app_icon'), 'Image 3'),
    new ImageItem($r('app.media.app_icon'), 'Image 4'),
    new ImageItem($r('app.media.app_icon'), 'Image 5'),
    new ImageItem($r('app.media.app_icon'), 'Image 6'),
    new ImageItem($r('app.media.app_icon'), 'Image 7'),
    new ImageItem($r('app.media.app_icon'), 'Image 8'),
    new ImageItem($r('app.media.app_icon'), 'Image 9'),
    new ImageItem($r('app.media.app_icon'), 'Image 10')
  ]

  build() {
    Column() {
      if (this.showFullScreen) {
        Stack() {
          Image(this.selectedImage)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%')

          Button('Close')
            .onClick(() => {
              this.showFullScreen = false
            })
            .position({ x: 20, y: 20 })
            .backgroundColor('#FFFFFF')
            .padding({ left: 10, right: 10, top: 5, bottom: 5 })
            .borderRadius(5)
        }
      } else {
        Grid() {
          ForEach(this.images, (item: ImageItem) => {
            GridItem() {
              Column() {
                Image(item.image)
                  .width('100%')
                  .aspectRatio(1)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(5)
                  .onClick(() => {
                    this.selectedImage = item.image
                    this.showFullScreen = true
                  })

                Text(item.caption)
                  .fontSize(14)
                  .textAlign(TextAlign.Center)
                  .margin({ top: 5 })
              }
            }
          })
