import mediaquery from '@ohos.mediaquery';

@Entry
@Component
struct MediaConditionHandler {
  @StorageLink('isDarkMode') isDarkMode: boolean = false;
  @StorageLink('isLandscape') isLandscape: boolean = false;

  aboutToAppear() {
    mediaquery.matchMediaSync('(prefers-color-scheme: dark)').on('change', (result: mediaquery.MediaQueryResult) => {
      AppStorage.set('isDarkMode', result.matches);
    });

    mediaquery.matchMediaSync('(orientation: landscape)').on('change', (result: mediaquery.MediaQueryResult) => {
      AppStorage.set('isLandscape', result.matches);
    });
  }

  build() {
    Column() {
      Text('Media Conditions')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row() {
        Text('Color Scheme:')
          .fontSize(18);
        Text(this.isDarkMode ? 'Dark Mode' : 'Light Mode')
          .fontSize(18)
          .fontColor(this.isDarkMode ? Color.White : Color.Black);
      }
      .margin({ bottom: 10 });

      Row() {
        Text('Orientation:')
          .fontSize(18);
        Text(this.isLandscape ? 'Landscape' : 'Portrait')
          .fontSize(18);
      }
      .margin({ bottom: 20 });

      Image($r('app.media.app_icon'))
        .width(this.isLandscape ? 200 : 100)
        .height(this.isLandscape ? 200 : 100)
        .margin({ bottom: 20 });

      Button('Toggle Dark Mode')
        .onClick(() => {
          AppStorage.set('isDarkMode', !this.isDarkMode);
        })
        .width(200)
        .margin({ bottom: 10 });

      Button('Simulate Orientation Change')
        .onClick(() => {
          AppStorage.set('isLandscape', !this.isLandscape);
        })
        .width(200);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(this.isDarkMode ? Color.Black : Color.White);
  }
}

