import mediaquery from '@ohos.mediaquery';
import promptAction from '@ohos.promptAction';
import logger from '@ohos.hilog';

@Entry
@Component
struct MediaQueryAnalytics {
  @State private currentOrientation: string = 'portrait';
  @State private currentWidth: string = '';
  @State private queryLogs: Array<string> = [];
  private orientationListener: mediaquery.MediaQueryListener | null = null;
  private widthListener: mediaquery.MediaQueryListener | null = null;

  aboutToAppear() {
    this.orientationListener = mediaquery.matchMediaSync('(orientation: portrait)');
    this.orientationListener.on('change', (result: mediaquery.MediaQueryResult) => {
      const newOrientation = result.matches ? 'portrait' : 'landscape';
      this.logMediaChange(`Orientation changed to: ${newOrientation}`);
      this.currentOrientation = newOrientation;
    });

    this.widthListener = mediaquery.matchMediaSync('(min-width: 600px)');
    this.widthListener.on('change', (result: mediaquery.MediaQueryResult) => {
      const widthStatus = result.matches ? 'wide' : 'narrow';
      this.logMediaChange(`Width threshold changed: ${widthStatus}`);
      this.currentWidth = widthStatus;
    });
  }

  aboutToDisappear() {
    if (this.orientationListener) {
      this.orientationListener.off('change');
    }
    if (this.widthListener) {
      this.widthListener.off('change');
    }
  }

  logMediaChange(message: string) {
    console.log(`[MediaQuery] ${message}`);
    logger.info(0x0000, 'MediaQueryAnalytics', `Media Query Change: ${message}`);
    this.queryLogs.unshift(`${new Date().toLocaleTimeString()}: ${message}`);
    if (this.queryLogs.length > 10) {
      this.queryLogs.pop();
    }
    promptAction.showToast({ message: message, duration: 2000 });
  }

  build() {
    Column() {
      Text('Media Query Analytics')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ bottom: 20 });

      Text(`Current State:`)
        .fontSize(18)
        .margin({ bottom: 10 });

      Text(`Orientation: ${this.currentOrientation}`)
        .fontSize(16)
        .margin({ bottom: 5 });

      Text(`Width: ${this.currentWidth}`)
        .fontSize(16)
        .margin({ bottom: 20 });

      Divider()
        .strokeWidth(1)
        .color(Color.Gray)
        .margin({ bottom: 20 });

      Text('Query Change Log:')
        .fontSize(18)
        .margin({ bottom: 10 });

      List() {
        ForEach(this.queryLogs, (log: string) => {
          ListItem() {
            Text(log)
              .fontSize(14)
              .padding(8);
          }
        }, (log: string) => log);
      }
      .height('40%')
      .width('100%')
      .divider({ strokeWidth: 1, color: Color.Gray });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

