@Component
struct UsernameAutoComplete {
  @State userName: string = '';
  @State suggestions: string[] = ['Alice', 'Bob', 'Charlie', 'David', 'Eve'];
  @State showSuggestions: boolean = false;
  @State filteredSuggestions: string[] = [];

  build() {
    Column() {
      TextInput({ placeholder: 'Enter username' })
        .width('90%')
        .height(50)
        .margin({ top: 20 })
        .backgroundColor(Color.White)
        .borderRadius(8)
        .padding(10)
        .onChange((value: string) => {
          this.userName = value;
          if (value.length > 0) {
            this.filteredSuggestions = this.suggestions.filter(name =>
              name.toLowerCase().includes(value.toLowerCase())
            );
            this.showSuggestions = this.filteredSuggestions.length > 0;
          } else {
            this.showSuggestions = false;
          }
        });

      if (this.showSuggestions) {
        Column() {
          ForEach(this.filteredSuggestions, (item: string) => {
            Text(item)
