@Entry
@Component
struct MediaQueryVerificationSuite {
  @State mediaQueryResult: string = '';
  @State testResults: Array<string> = [];

  build() {
    Column({ space: 20 }) {
      Text('Media Query Verification Suite')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      TextInput({ placeholder: 'Enter media query to test' })
        .width('80%')
        .height(50)
        .onChange((value: string) => {
          this.mediaQueryResult = this.verifyMediaQuery(value);
        });

      Text(`Test Result: ${this.mediaQueryResult}`)
        .fontSize(18)
        .margin({ top: 20 });

      Button('Run Full Test Suite', { type: ButtonType.Normal })
        .width('50%')
        .height(50)
        .onClick(() => {
          this.executeTestSuite();
        });

      ForEach(this.testResults, (result: string) => {
        Text(result)
          .fontSize(14)
          .margin({ top: 10 });
      });
    }
    .width('100%')
    .padding(20);
  }

  verifyMediaQuery(query: string): string {
    if (query.includes('max-width')) {
      return 'Valid media query: max-width condition';
    } else if (query.includes('min-width')) {
      return 'Valid media query: min-width condition';
    } else if (query.includes('orientation')) {
      return 'Valid media query: orientation condition';
    } else {
      return 'Invalid media query format';
    }
  }

  executeTestSuite() {
    const testCases = [
      '(max-width: 600px)',
      '(min-width: 768px)',
      '(orientation: landscape)',
      '(invalid-query)'
    ];

    this.testResults = [];
    testCases.forEach(query => {
      const result = this.verifyMediaQuery(query);
      this.testResults.push(`Test Case: ${query} - ${result}`);
    });
  }
}

