@Entry
@Component
struct VisualScoringSystem {
  @State score: number = 0
  @State feedback: string = ''
  @State isGameActive: boolean = false

  increaseScore() {
    this.score += 10
    this.feedback = 'Great job! +10 points'
  }

  decreaseScore() {
    if (this.score >= 5) {
      this.score -= 5
      this.feedback = 'Oops! -5 points'
    } else {
      this.feedback = 'Score cannot go below 0'
    }
  }

  resetScore() {
    this.score = 0
    this.feedback = 'Score reset to 0'
  }

  startGame() {
    this.isGameActive = true
    this.score = 0
    this.feedback = 'Game started! Score is 0'
  }

  endGame() {
    this.isGameActive = false
    this.feedback = `Game ended! Final score: ${this.score}`
  }

  build() {
    Column() {
      Text('Visual Scoring System')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      if (!this.isGameActive) {
        Button('Start Game')
          .onClick(() => this.startGame())
          .width('80%')
          .margin({ bottom: 20 })
      } else {
        Row() {
          ForEach([1, 2, 3, 4, 5], (index: number) => {
            Image($r('app.media.app_icon'))
              .width(30)
              .height(30)
              .margin({ right: 5 })
              .opacity(index <= this.score / 20 ? 1 : 0.3)
          })
        }

        Text(`Score: ${this.score}`)
          .fontSize(24)
          .margin({ bottom: 10 })

        Text(this.feedback)
          .fontSize(18)
          .fontColor(this.feedback.includes('Great') ? '#4CAF50' : '#F44336')
          .margin({ bottom: 20 })

        Button('Increase Score')
          .onClick(() => this.increaseScore())
          .width('80%')
          .margin({ bottom: 10 })

        Button('Decrease Score')
          .onClick(() => this.decreaseScore())
          .width('80%')
          .margin({ bottom: 10 })

        Button('End Game')
          .onClick(() => this.endGame())
          .width('80%')
          .margin({ bottom: 20 })
      }

      if (!this.isGameActive && this.score > 0) {
        Button('Reset Score')
          .onClick(() => this.resetScore())
          .width('80%')
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
  }
}

