@Entry
@Component
struct SearchApp {
  private item: Item = { id: 0, title: '', description: '' };

  @State items: Array<Item> = [
    { id: 1, title: 'Apple', description: 'This is the detailed description of Apple.' },
    { id: 2, title: 'Banana', description: 'This is the detailed description of Banana.' },
    { id: 3, title: 'Orange', description: 'This is the detailed description of Orange.' },
    { id: 4, title: 'Grapes', description: 'This is the detailed description of Grapes.' },
    { id: 5, title: 'Mango', description: 'This is the detailed description of Mango.' },
    { id: 6, title: 'Pineapple', description: 'This is the detailed description of Pineapple.' },
    { id: 7, title: 'Strawberry', description: 'This is the detailed description of Strawberry.' },
    { id: 8, title: 'Watermelon', description: 'This is the detailed description of Watermelon.' },
    { id: 9, title: 'Cherry', description: 'This is the detailed description of Cherry.' },
    { id: 10, title: 'Blueberry', description: 'This is the detailed description of Blueberry.' }
  ];

  @State searchText: string = '';
  @State selectedItem: Item | null = null;

  filteredItems(): Array<Item> {
    if (this.searchText.trim() === '') {
      return this.items;
    } else {
      return this.items.filter(item =>
        item.title.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  build() {
    if (this.selectedItem == null) {
      Column() {
        TextInput({
          placeholder: 'Search items...',
          text: this.searchText
        })
          .width('100%')
          .onChange((value: string) => {
            this.searchText = value;
          })
          .margin(16)
          .backgroundColor('#f0f0f0')
          .borderRadius(8)
          .padding({ left: 12, right: 12, top: 8, bottom: 8 });

        if (this.filteredItems().length > 0) {
          List() {
            ForEach(this.filteredItems(), (item: Item) => {
              ListItem() {
                Text(item.title)
                  .fontSize(18)
                  .padding(12)
                  .onClick(() => {
                    this.selectedItem = item;
                  });
              }
              .backgroundColor('#FFFFFF')
              .borderRadius(5)
              .margin({ bottom: 10 });
            }, (item: Item) => item.id.toString());
          }
        } else {
          Text('No items found')
            .fontSize(16)
            .fontColor(Color.Gray)
            .padding(16);
        }
      }
      .width('100%')
      .height('100%')
      .backgroundColor(Color.White);
    } else {
      Column() {
        Button('Back')
          .onClick(() => {
            this.selectedItem = null;
          })
          .margin({ top: 20, bottom: 20 });

        Scroll() {
          Column() {
            Text(this.selectedItem.title)
              .fontSize(24)
              .fontWeight(FontWeight.Bold)
              .margin({ bottom: 10 });

            Text(this.selectedItem.description)
              .fontSize(18)
              .lineHeight(24)
              .margin({ bottom: 20 });
          }
        }
        .width('100%')
        .height('100%');
      }
      .padding(20)
      .backgroundColor('#FFFFFF');
    }
  }
}

