@Entry
@Component
struct RotationGestureExample {
  @State angle: number = 0;
  @State minAngle: number = 15; // Custom minimum angle for rotation

  build() {
    Column() {
      Image($r("app.media.app_icon"))
        .width(100)
        .height(100)
        .rotate({ x: 0, y: 0, z: 1, angle: this.angle })
        .gesture(
          RotationGesture()
            .onActionStart(() => {
              console.info("Rotation started");
            })
            .onActionUpdate((event: RotationGestureEvent) => {
              const newAngle = this.angle + event.angle;
              if (Math.abs(newAngle) >= this.minAngle) {
                this.angle = newAngle;
              }
            })
            .onActionEnd(() => {
              console.info("Rotation ended");
            })
        )
      Text(`Current Angle: ${this.angle.toFixed(2)}°`)
        .fontSize(20)
        .margin(20)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

