@Entry
@Component
struct ProductRatingSystem {
  @State ratings: number[] = [];
  @State averageRating: number = 0;
  @State currentRating: number = 0;

  private calculateAverage(): void {
    if (this.ratings.length === 0) {
      this.averageRating = 0;
      return;
    }
    const sum = this.ratings.reduce((acc, curr) => acc + curr, 0);
    this.averageRating = sum / this.ratings.length;
  }

  private handleRating(rating: number): void {
    this.currentRating = rating;
    this.ratings.push(rating);
    this.calculateAverage();
  }

  build() {
    Column({ space: 20 }) {
      Text('Product Rating')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row({ space: 5 }) {
        ForEach([1, 2, 3, 4, 5], (index: number) => {
          Image($r('app.media.app_icon'))
            .width(40)
            .height(40)
            .onClick(() => {
              this.handleRating(index);
            })
            .opacity(this.currentRating >= index ? 1 : 0.3);
        })
      }

      if (this.ratings.length > 0) {
        Column() {
          Text('Average Rating:')
            .fontSize(18)
            .margin({ bottom: 5 });
          Text(this.averageRating.toFixed(1))
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .fontColor('#FFA500');
        }
        .margin({ top: 20 });
      }

      Text(`Based on ${this.ratings.length} ratings`)
        .fontSize(14)
        .fontColor('#666666')
        .margin({ top: 10 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

