                .margin(10)
              Text(item)
                .fontSize(16)
            }
            .width('100%')
            .onAppear(() => {
              console.info(`Item ${item} appeared`);
            })
            .onDisAppear(() => {
              console.info(`Item ${item} disappeared and recycled`);
              this.recycledItems.push(item);
            })
          }
        }, (item: string) => item)
      }
      .cachedCount(5)
      .height('80%')

      Button('Show Recycled Items')
        .onClick(() => {
          console.info(`Recycled Items: ${this.recycledItems.join(', ')}`);
        })
        .margin(10)
    }
    .width('100%')
    .height('100%')
  }
}

