@Entry
@Component
struct RotationGestureTrackingApp {
  @State angle: number = 0
  @State rotationState: string = "Rotation not started"

  build() {
    Column() {
      Text(`Rotation Angle: ${this.angle.toFixed(2)}°`)
        .fontSize(20)
        .margin({ bottom: 10 })

      Text(`State: ${this.rotationState}`)
        .fontSize(20)
        .margin({ bottom: 20 })

      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .rotate({ x: 0, y: 0, z: 1, angle: this.angle })
        .gesture(
          RotationGesture()
            .onActionStart(() => {
              this.rotationState = "Rotation started"
              console.info('Rotation gesture started')
            })
            .onActionUpdate((event: RotationGestureEvent) => {
              this.angle = event.angle
              this.rotationState = "Rotating"
              console.info(`Rotation angle updated: ${this.angle}`)
            })
            .onActionEnd(() => {
              this.rotationState = "Rotation ended"
              console.info('Rotation gesture ended')
            })
            .onActionCancel(() => {
              this.rotationState = "Rotation cancelled"
              console.info('Rotation gesture cancelled')
            })
        )
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

