@Entry
@Component
struct UserForm {
  @State name: string = '';
  @State email: string = '';
  @State phoneNumber: string = '';
  @State showDialog: boolean = false;
  @State emailErrorMessage: string = '';

  validateEmail(email: string): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }

  build() {
    Column() {
      Text('User Information')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value;
          });
      }

      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value;
            if (!this.validateEmail(value)) {
              this.emailErrorMessage = 'Please enter a valid email';
            } else {
              this.emailErrorMessage = '';
            }
          });

        if (this.emailErrorMessage) {
          Text(this.emailErrorMessage)
            .fontSize(12)
            .fontColor(Color.Red)
            .margin({ top: 5 });
        }
      }

      Column() {
        Text('Phone Number:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your phone number' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.phoneNumber = value;
          });
      }

      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.name && this.email && this.phoneNumber && this.validateEmail(this.email)) {
            this.showDialog = true;
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields correctly'
            });
          }
        });

      if (this.showDialog) {
        Column() {
          Text('Submitted Information')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Name: ${this.name}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Phone Number: ${this.phoneNumber}`)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.showDialog = false;
              this.name = '';
              this.email = '';
              this.phoneNumber = '';
            });
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

@Entry
@Component
struct StopwatchApp {
    @State elapsedTime: number = 0
    @State isRunning: boolean = false
    private timerId: number = -1

    build() {
        Column() {
            Text(this.formatTime(this.elapsedTime))
                .fontSize(40)
                .margin(20)

            Row() {
                Button(this.isRunning ? 'Stop' : 'Start')
                    .onClick(() => {
                        if (this.isRunning) {
                            clearInterval(this.timerId)
                        } else {
                            this.timerId = setInterval(() => {
                                this.elapsedTime += 1
                            }, 1000)
                        }
                        this.isRunning = !this.isRunning
                    })
                    .margin(10)

                Button('Reset')
                    .onClick(() => {
                        clearInterval(this.timerId)
                        this.elapsedTime = 0
                        this.isRunning = false
                    })
                    .margin(10)
            }
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
    }

    private formatTime(time: number): string {
        const hours = Math.floor(time / 3600)
        const minutes = Math.floor((time % 3600) / 60)
        const seconds = time % 60
        return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`
    }
}

