@Entry
@Component
struct ChatApp {
  @State messages: Array<Message> = [];
  @State newMessage: string = '';

  build() {
    Column() {
      // Chat Messages Display
      List() {
        ForEach(this.messages, (message: Message, index: number) => {
          ListItem() {
            Column() {
              Text(message.text)
                .fontSize(16)
                .padding(10)
                .backgroundColor(message.isSender ? '#DCF8C6' : '#ECECEC')
                .borderRadius(8)
                .align(message.isSender ? Alignment.End : Alignment.Start)
            }
            .width('100%')
            .margin({ top: 5, bottom: 5 })
          }
        })
      }
      .layoutWeight(1)
      .width('100%')
      .padding(10)

      // Input Area
      Row() {
        TextInput({ placeholder: 'Type a message...' })
          .width('80%')
          .height(40)
          .backgroundColor('#F5F5F5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.newMessage = value;
          })

        Button('Send')
          .width('20%')
          .height(40)
          .fontSize(16)
          .backgroundColor('#007AFF')
          .onClick(() => {
            if (this.newMessage.trim()) {
              this.messages.push({ text: this.newMessage, isSender: true });
              this.newMessage = '';
              // Simulate receiver response
              setTimeout(() => {
                this.messages.push({ text: 'Received: ' + this.newMessage, isSender: false });
              }, 1000);
            }
          })
      }
      .width('100%')
      .padding(10)
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
  }
}

interface Message {
  text: string;
  isSender: boolean;
}

