@Entry
@Component
struct RotationGestureWithConstraints {
  @State rotateAngle: number = 0
  @State isRotating: boolean = false
  private minAngle: number = -45
  private maxAngle: number = 45

  build() {
    Column() {
      Image($r("app.media.app_icon"))
        .width(100)
        .height(100)
        .rotate({ x: 0, y: 0, z: 1, angle: this.rotateAngle })
        .gesture(
          RotationGesture()
            .onActionStart(() => {
              this.isRotating = true
            })
            .onActionUpdate((event: RotationGestureEvent) => {
              let newAngle = this.rotateAngle + event.angle
              if (newAngle >= this.minAngle && newAngle <= this.maxAngle) {
                this.rotateAngle = newAngle
              }
            })
            .onActionEnd(() => {
              this.isRotating = false
            })
        )
      Text(`Current Angle: ${this.rotateAngle.toFixed(2)}°`)
        .fontSize(20)
        .margin(20)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

@Entry
@Component
struct LoginApp {
  @State username: string = ''
  @State password: string = ''
  @State loginMessage: string = ''

  validateCredentials(): boolean {
    if (this.username === 'admin' && this.password === 'password123') {
      this.loginMessage = 'Login successful!'
      return true
    } else {
      this.loginMessage = 'Invalid username or password'
      return false
    }
  }

  build() {
    Column() {
      // Username Label and Input
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your username', text: this.username })
        .onChange((value: string) => {
          this.username = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Password Label and Input
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Login Button
      Button('Login')
        .onClick(() => {
          this.validateCredentials()
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      // Login Message
      if (this.loginMessage) {
        Text(this.loginMessage)
          .fontSize(16)
          .margin({ top: 20 })
          .fontColor(this.loginMessage === 'Login successful!' ? Color.Green : Color.Red)
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

