@Entry
@Component
struct TodoList {
  @State tasks: Array<string> = []
  @State newTask: string = ''
  @State editIndex: number = -1
  @State editTask: string = ''

  build() {
    Column() {
      TextInput({ placeholder: 'Enter a new task' })
        .onChange((value: string) => {
          this.newTask = value
        })
        .margin({ bottom: 20 })

      Button('Add Task')
        .onClick(() => {
          if (this.newTask) {
            this.tasks.push(this.newTask)
            this.newTask = ''
          }
        })
        .margin({ bottom: 20 })

      ForEach(this.tasks, (task: string, index: number) => {
        Row() {
          if (this.editIndex === index) {
            TextInput({ text: this.editTask })
              .onChange((value: string) => {
                this.editTask = value
              })
              .margin({ right: 10 })

            Button('Save')
              .onClick(() => {
                if (this.editTask) {
                  this.tasks[index] = this.editTask
                  this.editIndex = -1
                  this.editTask = ''
                }
              })
          } else {
            Text(task)
              .margin({ right: 10 })

            Button('Edit')
              .onClick(() => {
                this.editIndex = index
                this.editTask = task
              })
              .margin({ right: 10 })
          }

          Button() {
            Image($r('app.media.app_icon'))
              .width(20)
              .height(20)
          }
          .onClick(() => {
            this.tasks.splice(index, 1)
          })
        }
        .margin({ top: 10 })
      })
    }
    .padding(20)
  }
}

