@Entry
@Component
struct RotationGestureFeedback {
  @State angle: number = 0
  @State rotationText: string = "Rotation Angle: 0°"

  build() {
    Column({ space: 20 }) {
      Text(this.rotationText)
        .fontSize(20)
        .fontColor(Color.Black)

      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .rotate({ x: 0, y: 0, z: 1, angle: this.angle })
        .gesture(
          RotationGesture()
            .onActionStart(() => {
              console.info('Rotation started')
            })
            .onActionUpdate((event: RotationGestureEvent) => {
              this.angle = event.angle
              this.rotationText = `Rotation Angle: ${Math.round(this.angle)}°`
              console.info(`Rotation angle: ${this.angle}`)
            })
            .onActionEnd(() => {
              console.info('Rotation ended')
            })
        )
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor(Color.White)
  }
}

