@Entry
@Component
struct SegmentButtonComponent {
  private segmentItem: Array<SegmentItem> = [
    new SegmentItem("Home", "app_icon_home"),
    new SegmentItem("Search", "app_icon_search"),
    new SegmentItem("Profile", "app_icon_profile")
  ];

  @State selectedIndex: number = 0;

  build() {
    Column() {
      Row() {
        ForEach(this.segmentItem, (item: SegmentItem, index: number) => {
          Button(item.label)
            .onClick(() => {
              this.selectedIndex = index;
            })
            .margin(5)
            .backgroundColor(this.selectedIndex === index ? '#007AFF' : '#E0E0E0')
            .width(100)
            .height(40)
        })
      }

      Text(`Selected: ${this.segmentItem[this.selectedIndex].label}`)
        .fontSize(20)
        .margin(10)

      Button('Add New Segment')
        .onClick(() => {
          const newLabel = `Segment ${this.segmentItem.length + 1}`;
          const newIcon = "app_icon_default";
          this.segmentItem = [...this.segmentItem, new SegmentItem(newLabel, newIcon)];
        })
        .margin(10)
        .width(200)

      Button('Remove Last Segment')
        .onClick(() => {
          if (this.segmentItem.length > 0) {
            this.segmentItem = this.segmentItem.slice(0, -1);
            if (this.selectedIndex >= this.segmentItem.length) {
              this.selectedIndex = Math.max(0, this.segmentItem.length - 1);
            }
          }
        })
        .margin(10)
        .width(200)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

class SegmentItem {
  label: string;
  icon: string;

  constructor(label: string, icon: string) {
    this.label = label;
    this.icon = icon;
  }
}

