@Entry
@Component
struct BasicSwipeRefresher {
  @State refreshing: boolean = false
  @State data: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4', 'Item 5']

  build() {
    Column() {
      Refresh({ refreshing: this.refreshing }) {
        List() {
          ForEach(this.data, (item: string) => {
            ListItem() {
              Row() {
                Image($r('app.media.app_icon'))
                  .width(40)
                  .height(40)
                  .margin(10)

                Text(item)
                  .fontSize(18)
              }
              .width('100%')
              .justifyContent(FlexAlign.Start)
            }
            .borderRadius(8)
            .margin({ top: 5, bottom: 5 })
            .backgroundColor('#f5f5f5')
          }, (item: string) => item)
        }
        .width('100%')
        .height('100%')
      }
      .onRefreshing(() => {
        this.refreshing = true
        setTimeout(() => {
          this.data = [...this.data, `Item ${this.data.length + 1}`]
          this.refreshing = false
        }, 1500)
      })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff')
  }
}

