@Component
struct ImageCarousel {
  private swiperController: SwiperController = new SwiperController();

  private items: Array<ImageItem> = [
    { id: 1, image: $r('app.media.app_icon'), message: 'Message for Image 1' },
    { id: 2, image: $r('app.media.app_icon'), message: 'Message for Image 2' },
    { id: 3, image: $r('app.media.app_icon'), message: 'Message for Image 3' },
    { id: 4, image: $r('app.media.app_icon'), message: 'Message for Image 4' },
  ];

  @State currentIndex: number = 0;
  @State selectedMessage: string = '';

  build() {
    Column() {
      Text('Image Carousel')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Swiper(this.swiperController) {
        ForEach(this.items, (item: ImageItem) => {
          Image(item.image)
            .width('100%')
            .height(300)
            .objectFit(ImageFit.Cover)
            .borderRadius(16)
            .onClick(() => {
              this.selectedMessage = item.message;
            });
        });
      }
      .width('100%')
      .height(300)
      .margin({ bottom: 16 })
      .autoPlay(true)
      .interval(3000)
      .indicator(true)
      .loop(true)
      .duration(500)
      .onChange((index: number) => {
        this.currentIndex = index;
      });

      if (this.selectedMessage !== '') {
        Text(`Selected: ${this.selectedMessage}`)
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 8 })
          .textAlign(TextAlign.Center);
      }

      Row() {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });

        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

