@Component
struct RefreshControlExample {
  @State isRefreshing: boolean = true; // Initial state of the refreshing indicator

  build() {
    Column() {
      // Display the current refreshing state
      Text('Refreshing Status: ' + this.isRefreshing)
        .fontSize(18)
        .margin(5)

      // Use the `refreshing` attribute to control the refreshing indicator
      Refresh({ refreshing: this.isRefreshing }) {
        Text('Pull down to refresh')
          .fontSize(18)
          .margin(5)
      }
      .onStateChange(() => {
        // Simulate a network request or data loading
        setTimeout(() => {
          // Stop the refreshing indicator by setting isRefreshing to false
          this.isRefreshing = false;
        }, 2500); // Simulate a 2.5-second delay
      })

      // Button to manually stop the refreshing indicator
      Button('Stop Refreshing')
        .onClick(() => {
          this.isRefreshing = false;
        })
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

