@Entry
@Component
struct DataReloadMechanism {
  @State refreshing: boolean = false;
  @State isLoading: boolean = true;
  @State listData: string[] = [];

  aboutToAppear() {
    this.loadData();
  }

  private loadData() {
    setTimeout(() => {
      this.listData = ['Item A', 'Item B', 'Item C', 'Item D'];
      this.isLoading = false;
    }, 2000);
  }

  build() {
    Column() {
      if (this.isLoading) {
        LoadingProgress()
          .color(Color.Blue)
          .width(100)
          .height(100)
          .margin({ top: 20 });
      } else {
        Refresh({
          refreshing: this.refreshing,
          offset: 120,
          friction: 100
        }) {
          List() {
            ForEach(this.listData, (item: string) => {
              ListItem() {
                Text(item)
                  .fontSize(18)
                  .padding(10)
                  .width('100%');
              }
            }, (item: string) => item);
          }
          .width('100%')
          .height('80%');
        }
        .onRefreshing(() => {
          this.refreshing = true;
          setTimeout(() => {
            this.listData = ['New Item X', 'New Item Y', 'New Item Z'];
            this.refreshing = false;
          }, 2000);
        })
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

@Entry
@Component
struct RefreshApp {
  @State isRefreshing: boolean = false
  @State data: string[] = ['Default Item 1', 'Default Item 2', 'Default Item 3']
  @State refreshCount: number = 0

  private fetchNewData() {
    setTimeout(() => {
      this.data = ['Updated Item 1', 'Updated Item 2', 'Updated Item 3']
      this.refreshCount += 1
      this.isRefreshing = false
    }, 1000)
  }

  build() {
    Column() {
      Text(`Refreshing: ${this.isRefreshing}`)
        .fontSize(16)
        .margin(10)
      Text(`Refresh count: ${this.refreshCount}`)
        .fontSize(16)
        .margin(10)

      Refresh({ refreshing: $$this.isRefreshing }) {
        List() {
          ForEach(this.data, (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(18)
                .padding(10)
                .width('100%')
            }
          })
        }
        .width('100%')
        .height('80%')
      }
      .onRefreshing(() => {
        this.isRefreshing = true
        this.fetchNewData()
      })

      if (this.isRefreshing) {
        LoadingProgress()
          .width(50)
          .height(50)
          .margin(10)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }
}

