@Entry
@Component
struct CustomRefreshInterface {
  @State isRefreshing: boolean = false;
  @State refreshOffset: number = 120; // Custom offset value
  @State refreshCount: number = 0;
  @State data: string[] = ['Item A', 'Item B', 'Item C'];

  build() {
    Column() {
      // Display refresh information
      Text(`Refresh Offset: ${this.refreshOffset}`)
        .fontSize(18)
        .margin(10);

      Text(`Refresh Count: ${this.refreshCount}`)
        .fontSize(18)
        .margin(10);

      // Custom refresh component with offset
      Refresh({
        refreshing: $$this.isRefreshing,
        offset: this.refreshOffset // Applying custom offset value
      }) {
        List() {
          ForEach(this.data, (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(16)
                .padding(16)
                .width('100%')
            }
          })
        }
        .width('100%')
      }
      .onStateChange((offset: number) => {
        console.log(`Current offset: ${offset}`);
      })
      .onRefreshing(() => {
        // Simulate data refresh
        setTimeout(() => {
          this.data = ['New Item A', 'New Item B', 'New Item C'];
          this.isRefreshing = false;
          this.refreshCount += 1;
        }, 2000);
      });

      // Control panel for offset adjustment
      Row() {
        Button('Increase Offset')
          .onClick(() => {
            this.refreshOffset += 10;
          })
          .margin(5);

        Button('Decrease Offset')
          .onClick(() => {
            if (this.refreshOffset > 50) {
              this.refreshOffset -= 10;
            }
          })
          .margin(5);
      }
      .margin(10)
    }
    .width('100%')
    .height('100%')
  }
}

