@Entry
@Component
struct RotationGestureVelocityTracking {
  @State angle: number = 0
  @State velocity: number = 0
  @State rotationState: string = "Rotation not started"
  private lastTime: number = 0
  private lastAngle: number = 0

  build() {
    Column() {
      Text(`Rotation Angle: ${this.angle.toFixed(2)}°`)
        .fontSize(20)
        .margin({ bottom: 10 })

      Text(`Rotation Velocity: ${this.velocity.toFixed(2)}°/s`)
        .fontSize(20)
        .margin({ bottom: 10 })

      Text(`State: ${this.rotationState}`)
        .fontSize(20)
        .margin({ bottom: 20 })

      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .rotate({ x: 0, y: 0, z: 1, angle: this.angle })
        .gesture(
          RotationGesture()
            .onActionStart((event: RotationGestureEvent) => {
              this.lastTime = event.timestamp
              this.lastAngle = this.angle
              this.rotationState = "Rotation started"
              console.info('Rotation gesture started')
            })
            .onActionUpdate((event: RotationGestureEvent) => {
              const currentTime = event.timestamp
              const deltaTime = (currentTime - this.lastTime) / 1000
              const deltaAngle = event.angle - this.lastAngle

              this.angle += deltaAngle
              this.velocity = deltaAngle / deltaTime
              this.rotationState = "Rotating"
              console.info(`Rotation angle updated: ${this.angle}`)

              this.lastTime = currentTime
              this.lastAngle = this.angle
            })
            .onActionEnd(() => {
              this.velocity = 0
              this.rotationState = "Rotation ended"
              console.info('Rotation gesture ended')
            })
            .onActionCancel(() => {
              this.velocity = 0
              this.rotationState = "Rotation cancelled"
              console.info('Rotation gesture cancelled')
            })
        )
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

