@Entry
@Component
struct TodoList {
  @State tasks: Array<Task> = []
  @State newTask: string = ''
  @State taskIdCounter: number = 0

  build() {
    Column() {
      TextInput({ placeholder: 'Enter a new task' })
        .onChange((value: string) => {
          this.newTask = value
        })
        .margin({ bottom: 20 })

      Button('Add Task')
        .onClick(() => {
          if (this.newTask) {
            this.tasks.push({ id: this.taskIdCounter++, content: this.newTask, isCompleted: false })
            this.newTask = ''
          }
        })
        .margin({ bottom: 20 })

      ForEach(this.tasks, (task: Task, index: number) => {
        Row() {
          Checkbox()
            .select(task.isCompleted)
            .onChange((value: boolean) => {
              this.tasks[index].isCompleted = value
            })
            .margin({ right: 10 })

          Text(task.content)
            .fontSize(20)
            .decoration({ type: task.isCompleted ? TextDecorationType.LineThrough : TextDecorationType.None })

          Button() {
            Image($r('app.media.app_icon'))
              .width(20)
              .height(20)
          }
          .onClick(() => {
            this.tasks.splice(index, 1)
          })
          .margin({ left: 10 })
        }
        .margin({ top: 10 })
      })
    }
    .padding(20)
  }
}

interface Task {
  id: number
  content: string
  isCompleted: boolean
}

