@Entry
@Component
struct ProductListRefresh {
  @State refreshing: boolean = false
  @State listData: string[] = ['Product A', 'Product B', 'Product C']

  refreshData() {
    this.refreshing = true
    setTimeout(() => {
      this.listData = ['Updated Product A', 'Updated Product B', 'Updated Product C']
      this.refreshing = false
    }, 2000)
  }

  build() {
    Column() {
      Refresh({
        refreshing: this.refreshing,
        offset: 120,
        friction: 100
      }) {
        List() {
          ForEach(this.listData, (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(16)
                .padding(16)
                .backgroundColor('#f0f0f0')
                .width('100%')
            }
          })
        }
        .width('100%')
      }
      .onRefreshing(() => {
        this.refreshData()
      })
    }
    .width('100%')
    .height('100%')
  }
}

