import http from '@ohos.net.http';

@Entry
@Component
struct ApiDataList {
  @State items: Array<Item> = [];
  @State isLoading: boolean = false;
  @State error: string = '';

  aboutToAppear() {
    this.fetchData();
  }

  fetchData() {
    this.isLoading = true;
    this.error = '';

    const apiUrl = 'https://api.example.com/items';

    let httpRequest = http.createHttp();
    httpRequest.request(apiUrl, {
      method: http.RequestMethod.GET
    }).then((response: http.HttpResponse) => {
      if (response.responseCode !== 200) {
        throw new Error('Network response was not ok');
      }
      return response.result as Array<ItemResponse>;
    }).then((data: Array<ItemResponse>) => {
      if (Array.isArray(data)) {
        this.items = data.map((item: ItemResponse) => new Item(item));
      } else {
        throw new Error('Invalid data format');
      }
    }).catch((error: Error) => {
      this.error = error.message || 'Failed to fetch data';
    }).finally(() => {
      this.isLoading = false;
    });
  }

  build() {
    Column() {
      if (this.isLoading) {
        Text('Loading...')
          .fontSize(18)
          .margin(10);
      } else if (this.error) {
        Text(`Error: ${this.error}`)
          .fontSize(18)
          .fontColor(Color.Red)
          .margin(10);
      } else {
        List() {
          ForEach(this.items, (item: Item) => {
            ListItem() {
              Row() {
                Image(item.imageUrl || $r('app.media.app_icon'))
                  .width(50)
                  .height(50)
                  .margin(10);

                Column() {
                  Text(item.title)
                    .fontSize(18)
                    .fontWeight(FontWeight.Bold);

                  Text(item.description)
                    .fontSize(14)
                    .margin({ top: 5 });
                }
              }
            }
          })
        }
        .width('100%')
        .height('100%');
      }
    }
    .width('100%')
    .height('100%')
    .padding(10);
  }
}

class Item {
  id: string;
  title: string;
  description: string;
  imageUrl: string;

  constructor(itemResponse: ItemResponse) {
    this.id = itemResponse.id || '';
    this.title = itemResponse.title || '';
    this.description = itemResponse.description || '';
    this.imageUrl = itemResponse.imageUrl || '';
  }
}

interface ItemResponse {
  id: string;
  title: string;
  description: string;
  imageUrl: string;
}

