@Entry
@Component
struct RotationGestureMomentum {
  @State rotateAngle: number = 0
  @State velocity: number = 0
  private lastTime: number = 0
  private lastAngle: number = 0

  build() {
    Column() {
      Text(`Current Angle: ${this.rotateAngle.toFixed(2)}°`)
        .fontSize(20)
        .margin({ bottom: 10 })

      Text(`Rotation Velocity: ${this.velocity.toFixed(2)}°/s`)
        .fontSize(20)
        .margin({ bottom: 20 })

      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .rotate({ x: 0, y: 0, z: 1, angle: this.rotateAngle })
        .gesture(
          RotationGesture()
            .onActionStart((event: RotationGestureEvent) => {
              this.lastTime = event.timestamp
              this.lastAngle = this.rotateAngle
            })
            .onActionUpdate((event: RotationGestureEvent) => {
              const currentTime = event.timestamp
              const deltaTime = (currentTime - this.lastTime) / 1000 // Convert to seconds
              const deltaAngle = event.angle - this.lastAngle

              this.rotateAngle += deltaAngle
              this.velocity = deltaAngle / deltaTime

              this.lastTime = currentTime
              this.lastAngle = this.rotateAngle
            })
            .onActionEnd(() => {
              this.velocity = 0
            })
        )
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

@Entry
@Component
struct AdvancedAnimationDemo {
  @State widthSize: number = 200
  @State heightSize: number = 200
  @State rotateAngle: number = 0
  @State scaleSize: number = 1
  @State opacityValue: number = 1
  @State translateX: number = 0
  @State translateY: number = 0
  @State isAnimating: boolean = false

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(this.widthSize)
        .height(this.heightSize)
        .rotate({ angle: this.rotateAngle })
        .scale({ x: this.scaleSize, y: this.scaleSize })
        .opacity(this.opacityValue)
        .translate({ x: this.translateX, y: this.translateY })
        .animation({
          duration: 1500,
          curve: Curve.EaseInOut,
          iterations: -1,
          playMode: PlayMode.Alternate
        })
        .margin(50)

      Button('Toggle Animation')
        .onClick(() => {
          this.isAnimating = !this.isAnimating
          animateTo({
            duration: 1500,
            curve: Curve.EaseInOut
          }, () => {
            this.widthSize = this.isAnimating ? 300 : 200
            this.heightSize = this.isAnimating ? 300 : 200
            this.rotateAngle = this.isAnimating ? 180 : 0
            this.scaleSize = this.isAnimating ? 1.5 : 1
            this.opacityValue = this.isAnimating ? 0.5 : 1
            this.translateX = this.isAnimating ? 100 : 0
            this.translateY = this.isAnimating ? 100 : 0
          })
        })
        .margin(10)
        .width('80%')

      Button('Reset Animation')
        .onClick(() => {
          animateTo({
            duration: 1000,
            curve: Curve.EaseInOut
          }, () => {
            this.widthSize = 200
            this.heightSize = 200
            this.rotateAngle = 0
            this.scaleSize = 1
            this.opacityValue = 1
            this.translateX = 0
            this.translateY = 0
            this.isAnimating = false
          })
        })
        .margin(10)
        .width('80%')
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

