@Entry
@Component
struct NoteApp {
  private noteItem: Note = { id: 0, title: '', description: '', date: '' };

  @State notes: Array<Note> = [];
  @State newTitle: string = '';
  @State newDescription: string = '';
  @State editNoteId: number | null = null;

  build() {
    Column() {
      TextInput({ placeholder: 'Enter title...', text: this.newTitle })
        .height(50)
        .width('90%')
        .onChange((value: string) => {
          this.newTitle = value;
        })
        .margin(10);

      TextArea({ placeholder: 'Enter description...', text: this.newDescription })
        .height(100)
        .width('90%')
        .onChange((value: string) => {
          this.newDescription = value;
        })
        .margin(10);

      Button(this.editNoteId !== null ? 'Update Note' : 'Add Note')
        .onClick(() => {
          if (this.newTitle.trim() && this.newDescription.trim()) {
            const currentDate = new Date().toLocaleDateString();
            if (this.editNoteId !== null) {
              const index = this.notes.findIndex(note => note.id === this.editNoteId);
              this.notes[index] = {
                id: this.editNoteId,
                title: this.newTitle,
                description: this.newDescription,
                date: currentDate
              };
              this.editNoteId = null;
            } else {
              this.notes.push({
                id: Date.now(),
                title: this.newTitle,
                description: this.newDescription,
                date: currentDate
              });
            }
            this.newTitle = '';
            this.newDescription = '';
          }
        })
        .margin(10);

      List() {
        ForEach(this.notes, (note: Note) => {
          ListItem() {
            Row() {
              Column() {
                Text(note.title)
                  .fontSize(20)
                  .fontWeight(FontWeight.Bold);
                Text(note.description)
                  .fontSize(16)
                  .margin({ top: 5 });
                Text(note.date)
                  .fontSize(14)
                  .fontColor(Color.Gray)
                  .margin({ top: 5 });
              }
              .width('80%');

              Button('Edit')
                .onClick(() => {
                  this.newTitle = note.title;
                  this.newDescription = note.description;
                  this.editNoteId = note.id;
                })
                .margin(5);

              Button('Delete')
                .onClick(() => {
                  this.notes = this.notes.filter(n => n.id !== note.id);
                })
                .margin(5);
            }
            .padding(10);
          }
        });
      }
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

interface Note {
  id: number;
  title: string;
  description: string;
  date: string;
}

@Entry
@Component
struct RotationGestureWithTransformation {
  @State rotationAngle: number = 0
  @State scaleFactor: number = 1
  @State transitionActive: boolean = false

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .rotate({ x: 0, y: 0, z: 1, angle: this.rotationAngle })
        .scale({ x: this.scaleFactor, y: this.scaleFactor })
        .gesture(
          GestureGroup(GestureMode.Sequence,
            RotationGesture()
              .onActionStart(() => {
                this.transitionActive = true
                console.info('Rotation gesture started')
              })
              .onActionUpdate((event: RotationGestureEvent) => {
                this.rotationAngle += event.angle
                console.info(`Rotation angle updated to: ${this.rotationAngle}`)
              })
              .onActionEnd(() => {
                this.transitionActive = false
                console.info('Rotation gesture ended')
              }),
            PinchGesture()
              .onActionStart(() => {
                console.info('Pinch gesture started')
              })
              .onActionUpdate((event: PinchGestureEvent) => {
                this.scaleFactor *= event.scale
                console.info(`Scale factor updated to: ${this.scaleFactor}`)
              })
              .onActionEnd(() => {
                console.info('Pinch gesture ended')
              })
          )
        )
        .backgroundColor(this.transitionActive ? Color.Green : Color.White)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor(Color.Gray)
  }
}

