@Entry
@Component
struct AlertDialogWithSecondaryActions {
  private showAlertDialog() {
    promptAction.showDialog({
      title: 'Action Required',
      message: 'Please choose an action to proceed.',
      buttons: [
        {
          text: 'Primary',
          color: '#FF0000',
          primary: true
        },
        {
          text: 'Secondary',
          color: '#0000FF'
        },
        {
          text: 'Cancel',
          color: '#808080'
        }
      ]
    }).then((result) => {
      if (result.index === 0) {
        console.info('Primary button clicked');
        // Perform primary action here
      } else if (result.index === 1) {
        console.info('Secondary button clicked');
        // Perform secondary action here
      } else if (result.index === 2) {
        console.info('Cancel button clicked');
        // Perform cancel action here
      }
    }).catch((error: Error) => {
      console.error('Failed to show AlertDialog:', error);
    });
  }

  build() {
    Column() {
      Button('Show AlertDialog')
        .onClick(() => {
          this.showAlertDialog();
        })
        .margin(20)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

