@Entry
@Component
struct RotationGestureDirectionDetection {
  @State angle: number = 0
  @State rotationDirection: string = "No rotation detected"

  build() {
    Column() {
      Text(`Rotation Angle: ${this.angle.toFixed(2)}°`)
        .fontSize(20)
        .margin({ bottom: 10 })

      Text(`Direction: ${this.rotationDirection}`)
        .fontSize(20)
        .margin({ bottom: 20 })

      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .rotate({ x: 0, y: 0, z: 1, angle: this.angle })
        .gesture(
          RotationGesture()
            .onActionStart(() => {
              this.rotationDirection = "Rotation started"
              console.info('Rotation gesture started')
            })
            .onActionUpdate((event: RotationGestureEvent) => {
              this.angle = event.angle
              if (event.angle > 0) {
                this.rotationDirection = "Clockwise"
              } else if (event.angle < 0) {
                this.rotationDirection = "Counter-clockwise"
              }
              console.info(`Rotation angle updated: ${this.angle}, Direction: ${this.rotationDirection}`)
            })
            .onActionEnd(() => {
              this.rotationDirection = "Rotation ended"
              console.info('Rotation gesture ended')
            })
            .onActionCancel(() => {
              this.rotationDirection = "Rotation cancelled"
              console.info('Rotation gesture cancelled')
            })
        )
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

