    { label: "Option 3", selectedIcon: $r('app.media.app_icon'), unselectedIcon: $r('app.media.app_icon') }
  ];

  build() {
    Column() {
      Text('Extreme Icon Size Configurations in SegmentButton')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row() {
        ForEach(this.options, (option: Option, index: number) => {
          Button() {
            Image(this.selectedIndex === index ? option.selectedIcon : option.unselectedIcon)
              .width(this.iconSize)
              .height(this.iconSize)
          }
          .onClick(() => {
            this.selectedIndex = index;
          })
          .backgroundColor(this.selectedIndex === index ? Color.Blue : Color.Gray)
          .borderRadius(5)
          .margin(5)
        })
      }
      .justifyContent(FlexAlign.Center)
      .width('100%')
      .padding(10)

      Slider({
        value: this.iconSize,
        min: 10,
        max: 100,
        step: 1,
        style: SliderStyle.OutSet
      })
        .onChange((value: number) => {
          this.iconSize = value;
        })
        .margin({ bottom: 20 })

      Button({ type: ButtonType.Normal }) {
        Row() {
          Image($r('app.media.app_icon'))
            .width(this.iconSize)
            .height(this.iconSize)
          Text('Dynamic Icon Size')
        }
      }
      .margin({ bottom: 10 })
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor(Color.White)
  }
}

