@Entry
@Component
struct PolygonWithOpacity {
  private settings: RenderingContextSettings = new RenderingContextSettings(true)
  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings)

  build() {
    Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Center, justifyContent: FlexAlign.Center }) {
      Canvas(this.context)
        .width('100%')
        .height('100%')
        .backgroundColor('#ffffff')
        .onReady(() => {
          let region = new Path2D()
          region.moveTo(50, 50)
          region.lineTo(150, 50)
          region.lineTo(200, 150)
          region.lineTo(100, 200)
          region.lineTo(50, 150)
          region.closePath()
          this.context.fillStyle = 'rgba(0, 0, 255, 0.5)' // Blue color with 50% opacity
          this.context.fill(region, "evenodd")
        })
    }
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct BasicSwipeGestureDetection {
  @State private swipeMessage: string = "Swipe here to see the result";
  @State private offsetX: number = 0;

  build() {
    Column() {
      Text(this.swipeMessage)
        .fontSize(20)
        .margin({ bottom: 20 });

      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .margin({ bottom: 20 })
        .gesture(
          PanGesture({ direction: PanDirection.Horizontal })
            .onActionStart(() => {
              console.info('Swipe gesture started');
            })
            .onActionUpdate((event: GestureEvent) => {
              this.offsetX = event.offsetX;
            })
            .onActionEnd(() => {
              if (this.offsetX > 100) {
                this.swipeMessage = "Right Swipe Detected";
              } else if (this.offsetX < -100) {
                this.swipeMessage = "Left Swipe Detected";
              } else {
                this.swipeMessage = "Swipe here to see the result";
              }
              this.offsetX = 0;
            })
        )
        .transform({ translate: { x: this.offsetX } })
        .animation({ duration: 300 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(Color.White);
  }
}

