@Component
struct VerticalSwipeGestureApp {
  @State offsetY: number = 0;
  @State swipeMessage: string = "Swipe vertically";

  build() {
    Column() {
      Text(this.swipeMessage)
        .fontSize(20)
        .margin({ bottom: 20 });

      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .gesture(
          PanGesture({ direction: PanDirection.Vertical })
            .onActionStart(() => {
              console.info('Vertical swipe start');
            })
            .onActionUpdate((event: PanGestureEvent) => {
              this.offsetY = event.offsetY;
              if (this.offsetY > 50) {
                this.swipeMessage = 'Swiped Down';
              } else if (this.offsetY < -50) {
                this.swipeMessage = 'Swiped Up';
              }
            })
            .onActionEnd(() => {
              animateTo({ duration: 300 }, () => {
                this.offsetY = 0;
              });
              this.swipeMessage = 'Swipe vertically';
            })
        )
        .transform({ translate: { y: this.offsetY } })
        .animation({ duration: 300 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor(Color.White);
  }
}

