@Entry
@Component
struct DashArrayPolygonBorder {
  private settings: RenderingContextSettings = new RenderingContextSettings(true)
  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings)

  build() {
    Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Center, justifyContent: FlexAlign.Center }) {
      Canvas(this.context)
        .width('100%')
        .height('100%')
        .backgroundColor('#ffffff')
        .onReady(() => {
          // Configure dash array pattern for the polygon border
          this.context.setLineDash([15, 5]) // 15px dash, 5px gap
          this.context.lineWidth = 4
          this.context.strokeStyle = '#ff0000'

          // Draw a polygon with dashed border
          this.context.beginPath()
          this.context.moveTo(100, 100)
          this.context.lineTo(200, 100)
          this.context.lineTo(250, 200)
          this.context.lineTo(150, 250)
          this.context.lineTo(100, 200)
          this.context.closePath()
          this.context.stroke()
        })
    }
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct FailSafeSegmentButton {
  @State selectedIndex: number = 0;
  @State errorMessage: string = '';

  build() {
    Column() {
      Row() {
        ForEach(['Option 1', 'Option 2', 'Option 3'], (item: string, index: number) => {
          Button(item)
            .stateEffect(true)
            .backgroundColor(this.selectedIndex === index ? '#007DFF' : '#FFFFFF')
            .onClick(() => {
              if (index >= 0 && index < 3) {
                this.selectedIndex = index;
                this.errorMessage = '';
              } else {
                this.errorMessage = 'Invalid segment button selection detected.';
              }
            })
            .margin(5)
        })
      }

      Text(`Selected Option: ${this.selectedIndex + 1}`)
        .margin({ top: 20 })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor('#FF0000')
          .margin({ top: 10 })
      }

      Button('Reset Selection')
        .onClick(() => {
          this.selectedIndex = 0;
          this.errorMessage = '';
        })
        .margin({ top: 20 })
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

