    builder: this.dialogBuilder(),
    autoCancel: true
  });

  @Builder
  dialogBuilder() {
    Column() {
      Text('Dialog Content')
        .fontSize(20)
        .margin(10)
      Row() {
        Button('Cancel')
          .onClick(() => {
            this.onCancel();
            this.dialogController.close();
          })
        Button('Confirm')
          .onClick(() => {
            this.onConfirm();
            this.dialogController.close();
          })
      }
      .justifyContent(FlexAlign.SpaceEvenly)
      .width('100%')
      .margin(10)
    }
  }

  onCancel(): void {
    console.info('Canceled');
  }

  onConfirm(): void {
    console.info('Confirmed');
  }

  build() {
    Column() {
      Button('Show Dialog')
        .onClick(() => {
          this.dialogController.open();
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

