@Component
struct PolygonStrokeLineCapExample {
  private settings: RenderingContextSettings = new RenderingContextSettings(true)
  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings)
  @State private lineCapStyle: CanvasLineCap = 'round'

  build() {
    Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Center, justifyContent: FlexAlign.Center }) {
      Canvas(this.context)
        .width('100%')
        .height('100%')
        .backgroundColor('#ffff00')
        .onReady(() => {
          this.context.lineWidth = 8
          this.context.beginPath()
          this.context.lineCap = this.lineCapStyle
          this.context.moveTo(30, 50)
          this.context.lineTo(220, 50)
          this.context.lineTo(220, 150)
          this.context.lineTo(30, 150)
          this.context.closePath()
          this.context.stroke()
        })

      Row({ space: 10 }) {
        Text('Line Cap Style:')
        Button('Butt')
          .onClick(() => {
            this.lineCapStyle = 'butt'
          })
        Button('Round')
          .onClick(() => {
            this.lineCapStyle = 'round'
          })
        Button('Square')
          .onClick(() => {
            this.lineCapStyle = 'square'
          })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

