@Entry
@Component
struct CalculatorApp {
  @State num1: number = 0;
  @State num2: number = 0;
  @State result: number = 0;

  build() {
    Column() {
      TextInput({ placeholder: 'Enter first number' })
        .onChange((value: string) => {
          this.num1 = parseFloat(value);
        })
        .margin({ bottom: 20 });

      TextInput({ placeholder: 'Enter second number' })
        .onChange((value: string) => {
          this.num2 = parseFloat(value);
        })
        .margin({ bottom: 20 });

      Row() {
        Button('Add')
          .onClick(() => {
            this.result = this.num1 + this.num2;
          })
          .margin({ right: 10 });

        Button('Subtract')
          .onClick(() => {
            this.result = this.num1 - this.num2;
          })
          .margin({ right: 10 });

        Button('Multiply')
          .onClick(() => {
            this.result = this.num1 * this.num2;
          })
          .margin({ right: 10 });

        Button('Divide')
          .onClick(() => {
            if (this.num2 !== 0) {
              this.result = this.num1 / this.num2;
            } else {
              this.result = NaN;
            }
          })
          .margin({ right: 10 });
      }
      .margin({ bottom: 20 });

      Text(`Result: ${this.result}`)
        .fontSize(24)
        .margin({ top: 20 });
    }
    .padding(20);
  }
}

@Entry
@Component
struct DatePickerDialogBehaviorUpdate {
  @State selectedDate: Date = new Date()
  @State displayMessage: string = 'Select a date to see the message.'

  updateDisplayMessage() {
    if (this.selectedDate.getFullYear() > 2020) {
      this.displayMessage = 'Selected date is after 2020.'
    } else {
      this.displayMessage = 'Selected date is before or in 2020.'
    }
  }

  build() {
    Column() {
      Button("Show DatePicker Dialog")
        .margin(20)
        .onClick(() => {
          DatePickerDialog.show({
            start: new Date("2000-01-01"),
            end: new Date("2030-12-31"),
            selected: this.selectedDate,
            onDateAccept: (value: Date) => {
              this.selectedDate = value
              this.updateDisplayMessage()
              console.info("DatePickerDialog:onDateAccept()" + value.toString())
            },
            onCancel: () => {
              console.info("DatePickerDialog:onCancel()")
            },
            onDateChange: (value: Date) => {
              this.selectedDate = value
              this.updateDisplayMessage()
              console.info("DatePickerDialog:onDateChange()" + value.toString())
            }
          })
        })

      Text(this.displayMessage)
        .fontSize(20)
        .fontWeight(FontWeight.Medium)
        .margin({ top: 20 })
    }
    .width('100%')
    .padding(20)
  }
}

