@Entry
@Component
struct SwipeRefreshWithTranslation {
  @State refreshing: boolean = false
  @State listData: string[] = ['Apple', 'Banana', 'Orange']
  @State currentLanguage: string = 'en'
  @State content: string = 'Pull to Refresh'

  private translations: Record<string, Record<string, string>> = {
    'en': { 'Apple': 'Apple', 'Banana': 'Banana', 'Orange': 'Orange', 'Pull to Refresh': 'Pull to Refresh', 'Refreshing...': 'Refreshing...', 'Refresh Complete!': 'Refresh Complete!' },
    'es': { 'Apple': 'Manzana', 'Banana': 'Plátano', 'Orange': 'Naranja', 'Pull to Refresh': 'Tirar para actualizar', 'Refreshing...': 'Actualizando...', 'Refresh Complete!': '¡Actualización completa!' },
    'fr': { 'Apple': 'Pomme', 'Banana': 'Banane', 'Orange': 'Orange', 'Pull to Refresh': 'Tirer pour rafraîchir', 'Refreshing...': 'Rafraîchissement...', 'Refresh Complete!': 'Rafraîchissement terminé!' }
  }

  translateText(text: string): string {
    return this.translations[this.currentLanguage][text] || text
  }

  build() {
    Column() {
      Row() {
        Button('English').onClick(() => { this.currentLanguage = 'en' })
        Button('Español').onClick(() => { this.currentLanguage = 'es' })
        Button('Français').onClick(() => { this.currentLanguage = 'fr' })
      }

      Refresh({
        refreshing: this.refreshing,
        offset: 120,
        friction: 100
      }) {
        Column() {
          Image($r('app.media.app_icon'))
            .width(100)
            .height(100)
            .margin(20)

          Text(this.translateText(this.content))
            .fontSize(18)
            .margin(10)

          List() {
            ForEach(this.listData, (item: string) => {
              ListItem() {
                Text(this.translateText(item))
                  .fontSize(16)
                  .padding(16)
                  .backgroundColor('#f0f0f0')
                  .width('100%')
              }
            })
          }
          .width('100%')
        }
      }
      .onRefreshing(() => {
        this.refreshing = true
        this.content = 'Refreshing...'
        setTimeout(() => {
          this.listData = ['Apple', 'Banana', 'Orange', 'Mango']
          this.content = 'Refresh Complete!'
          this.refreshing = false
        }, 2000)
      })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

