@Entry
@Component
struct CustomLoadingScreen {
    @State rotation: number = 0
    @State isLoading: boolean = true
    private intervalID: number = -1

    aboutToAppear() {
        this.intervalID = setInterval(() => {
            this.rotation = (this.rotation + 10) % 360
        }, 50)

        setTimeout(() => {
            this.isLoading = false
        }, 3000)
    }

    aboutToDisappear() {
        if (this.intervalID !== -1) {
            clearInterval(this.intervalID)
        }
    }

    build() {
        Column() {
            if (this.isLoading) {
                Stack() {
                    Image($r('app.media.app_icon'))
                        .width(100)
                        .height(100)
                        .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })
                }
                .width(100)
                .height(100)

                Text('Loading... Please wait')
                    .fontSize(20)
                    .margin({ top: 20 })
            } else {
                Text('Welcome to the App!')
                    .fontSize(30)
                    .fontWeight(FontWeight.Bold)
                    .margin({ top: 20 })
            }
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .backgroundColor($r('sys.color.ohos_id_color_background'))
    }
}

import promptAction from '@ohos.promptAction';

@Entry
@Component
struct SignInPage {
  @State email: string = '';
  @State password: string = '';
  @State errorMessage: string = '';

  validateEmail(email: string): boolean {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return re.test(email);
  }

  validatePassword(password: string): boolean {
    return password.length >= 6;
  }

  handleSignIn() {
    if (!this.email || !this.password) {
      this.errorMessage = 'Please fill in all fields.';
      return;
    }

    if (!this.validateEmail(this.email)) {
      this.errorMessage = 'Invalid email format.';
      return;
    }

    if (!this.validatePassword(this.password)) {
      this.errorMessage = 'Password must be at least 6 characters.';
      return;
    }

    promptAction.showToast({
      message: 'Sign in successful!'
    });
    this.errorMessage = '';
  }

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ bottom: 30 });

      Text('Email')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your email' })
        .width('100%')
        .height(40)
        .margin({ bottom: 20 })
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .onChange((value: string) => {
          this.email = value;
        });

      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .width('100%')
        .height(40)
        .margin({ bottom: 30 })
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .onChange((value: string) => {
          this.password = value;
        });

      Button('Sign In')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          this.handleSignIn();
        });

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

@Entry
@Component
struct ResponsiveDesignThreshold {
  @State thresholdValue: number = 50; // Default threshold value (percentage)

  build() {
    Column() {
      Row() {
        Text('Threshold Value: ' + this.thresholdValue + '%')
          .fontSize(18)
          .textAlign(TextAlign.Center)
          .width('100%')
      }
      .height('15%')
      .backgroundColor('#f0f0f0')

      Row() {
        Button('Decrease (-10%)')
          .onClick(() => {
            if (this.thresholdValue > 10) {
              this.thresholdValue -= 10;
            }
          })
          .width('40%')
          .height('100%')

        Button('Increase (+10%)')
          .onClick(() => {
            if (this.thresholdValue < 90) {
              this.thresholdValue += 10;
            }
          })
          .width('40%')
          .height('100%')
      }
      .height('15%')
      .justifyContent(FlexAlign.SpaceAround)

      Column() {
        Text('Responsive Section')
          .fontSize(20)
          .textAlign(TextAlign.Center)
          .width('100%')
          .height('20%')

        Column() {
          Text('This section adjusts based on the threshold value.')
            .fontSize(16)
            .textAlign(TextAlign.Center)
            .width('100%')
            .height('60%')
        }
        .width(this.thresholdValue + '%')
        .backgroundColor('#ADD8E6')
        .height('80%')
      }
      .width('100%')
      .height('70%')
      .backgroundColor('#ffffff')
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }
}

