        .width(200)
        .height(200)
        .margin({ bottom: 20 })
        .gesture(
          PanGesture({ direction: PanDirection.Horizontal })
            .onActionStart(() => {
              this.lastTime = Date.now()
              this.lastOffsetX = this.offsetX
            })
            .onActionUpdate((event: PanGestureEvent) => {
              const currentTime = Date.now()
              const deltaTime = (currentTime - this.lastTime) / 1000 // Convert to seconds
              const deltaOffsetX = event.offsetX - this.lastOffsetX

              this.offsetX = event.offsetX
              this.swipeSpeed = Math.abs(deltaOffsetX / deltaTime)

              this.lastTime = currentTime
              this.lastOffsetX = this.offsetX
            })
            .onActionEnd(() => {
              this.swipeSpeed = 0
            })
        )
        .transform({ translate: { x: this.offsetX } })
        .animation({ duration: 300 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

@Entry
@Component
struct RatingApp {
  @State ratings: number[] = [];
  @State averageRating: number = 0;

  build() {
    Column() {
      Text('Rate the Item')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })
        .width('100%')
        .textAlign(TextAlign.Center);

      Row() {
        ForEach([1, 2, 3, 4, 5], (index: number) => {
          Image($r('app.media.app_icon'))
            .width(30)
            .height(30)
            .margin({ right: 5 })
            .onClick(() => {
              this.ratings.push(index);
              this.calculateAverageRating();
            });
        });
      }
      .margin({ bottom: 20 });

      Text(`Average Rating: ${this.averageRating.toFixed(2)}`)
        .fontSize(18)
        .fontWeight(FontWeight.Medium)
        .margin({ bottom: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5');
  }

  calculateAverageRating() {
    if (this.ratings.length > 0) {
      const sum = this.ratings.reduce((acc, curr) => acc + curr, 0);
      this.averageRating = sum / this.ratings.length;
    } else {
      this.averageRating = 0;
    }
  }
}

