@Entry
@Component
struct DirectionalSwipeConstraints {
  @State offsetX: number = 0
  @State offsetY: number = 0
  @State swipeDirection: string = "No Swipe Detected"
  @State maxOffset: number = 200 // Maximum allowed swipe distance

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .gesture(
          PanGesture({ direction: PanDirection.All })
            .onActionStart(() => {
              console.info('Pan gesture started')
            })
            .onActionUpdate((event: PanGestureEvent) => {
              // Apply bounds checking for X and Y directions
              if (Math.abs(event.offsetX) <= this.maxOffset) {
                this.offsetX = event.offsetX
              }
              if (Math.abs(event.offsetY) <= this.maxOffset) {
                this.offsetY = event.offsetY
              }

              // Determine swipe direction
              if (Math.abs(this.offsetX) > Math.abs(this.offsetY)) {
                if (this.offsetX > 100) {
                  this.swipeDirection = "Right Swipe Detected"
                } else if (this.offsetX < -100) {
                  this.swipeDirection = "Left Swipe Detected"
                }
              } else {
                if (this.offsetY > 100) {
                  this.swipeDirection = "Down Swipe Detected"
                } else if (this.offsetY < -100) {
                  this.swipeDirection = "Up Swipe Detected"
                }
              }
            })
            .onActionEnd(() => {
              animateTo({ duration: 300 }, () => {
                this.offsetX = 0
                this.offsetY = 0
              })
              this.swipeDirection = "No Swipe Detected"
            })
        )
        .transform({ translate: { x: this.offsetX, y: this.offsetY } })
        .animation({ duration: 300 })

      Text(this.swipeDirection)
        .fontSize(20)
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor(Color.White)
  }
}

