  build() {
    Column() {
      Text('Refreshing Status: ' + this.isRefreshing)
        .fontSize(18)
        .margin(5)

      Text('Data Loaded: ' + this.dataLoaded)
        .fontSize(18)
        .margin(5)

      Text('Refresh Count: ' + this.refreshCount)
        .fontSize(16)
        .margin(5)

      Text('Last Refresh: ' + this.lastRefreshTime)
        .fontSize(16)
        .margin(5)

      Refresh({ refreshing: $$this.isRefreshing }) {
        Column() {
          if (this.isRefreshing) {
            LoadingProgress()
              .width(30)
              .height(30)
            Text('Loading...')
              .margin({ left: 10 })
          } else {
            Text('Pull down to refresh')
              .fontSize(18)
              .margin(10)
          }
        }
        .width('100%')
        .height(100)
      }
      .onStateChange(() => {
        this.refreshCount += 1
        this.lastRefreshTime = new Date().toLocaleTimeString()

        setTimeout(() => {
          this.dataLoaded = true
          this.isRefreshing = false
        }, 2000)
      })
    }
    .width('100%')
    .height('100%')
  }
}

