@Entry
@Component
struct SwipeGestureDistanceTracking {
  @State offsetX: number = 0
  @State swipeDistance: number = 0
  @State swipeDirection: string = ''

  build() {
    Column() {
      Text('Swipe to track distance')
        .fontSize(20)
        .margin({ bottom: 20 })

      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .gesture(
          PanGesture({ direction: PanDirection.Horizontal })
            .onActionStart(() => {
              console.info('Pan start')
            })
            .onActionUpdate((event: GestureEvent) => {
              this.offsetX = event.offsetX
              this.swipeDistance = Math.abs(this.offsetX)
              if (this.offsetX > 0) {
                this.swipeDirection = 'Right'
              } else if (this.offsetX < 0) {
                this.swipeDirection = 'Left'
              }
            })
            .onActionEnd(() => {
              animateTo({ duration: 300 }, () => {
                this.offsetX = 0
              })
              this.swipeDistance = 0
              this.swipeDirection = ''
            })
        )
        .transform({ translate: { x: this.offsetX } })
        .animation({ duration: 300 })

      Text(`Swipe Distance: ${this.swipeDistance.toFixed(2)}`)
        .fontSize(16)
        .margin({ top: 20 })

