@Entry
@Component
struct CustomSwipeGestureThresholds {
  @State offsetX: number = 0
  @State swipeSpeed: number = 0
  @State swipeDirection: string = 'None'
  @State swipeMessage: string = 'Swipe to detect speed and direction'
  private lastTime: number = 0
  private lastOffsetX: number = 0

  build() {
    Column() {
      Text(this.swipeMessage)
        .fontSize(20)
        .margin({ bottom: 20 })

      Text(`Swipe Speed: ${this.swipeSpeed.toFixed(2)} px/s`)
        .fontSize(16)
        .margin({ bottom: 20 })

      Text(`Direction: ${this.swipeDirection}`)
        .fontSize(16)
        .margin({ bottom: 20 })

      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .margin({ bottom: 20 })
        .gesture(
          PanGesture({ direction: PanDirection.Horizontal })
            .onActionStart(() => {
              this.lastTime = Date.now()
              this.lastOffsetX = this.offsetX
            })
            .onActionUpdate((event: PanGestureEvent) => {
              const currentTime = Date.now()
              const deltaTime = (currentTime - this.lastTime) / 1000
              const deltaOffsetX = event.offsetX - this.lastOffsetX

              this.offsetX = event.offsetX
              this.swipeSpeed = Math.abs(deltaOffsetX / deltaTime)

              if (this.swipeSpeed > 1000) {
                this.swipeDirection = 'Very Fast Swipe'
                this.swipeMessage = `Very Fast Swipe Detected at speed: ${this.swipeSpeed.toFixed(2)} px/s`
              } else if (this.swipeSpeed > 500) {
                this.swipeDirection = 'Fast Swipe'
                this.swipeMessage = `Fast Swipe Detected at speed: ${this.swipeSpeed.toFixed(2)} px/s`
              } else if (this.swipeSpeed > 200) {
                this.swipeDirection = 'Moderate Swipe'
                this.swipeMessage = `Moderate Swipe Detected at speed: ${this.swipeSpeed.toFixed(2)} px/s`
              } else {
                this.swipeDirection = 'Slow Swipe'
                this.swipeMessage = `Slow Swipe Detected at speed: ${this.swipeSpeed.toFixed(2)} px/s`
              }

              this.lastTime = currentTime
              this.lastOffsetX = this.offsetX
            })
            .onActionEnd(() => {
              this.swipeSpeed = 0
              this.swipeDirection = 'None'
              this.swipeMessage = 'Swipe to detect speed and direction'
            })
        )
        .transform({ translate: { x: this.offsetX } })
        .animation({ duration: 300 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

