@Entry
@Component
struct RefreshChainStateChanges {
  @State isRefreshing: boolean = false;
  @State step1: string = "Step 1: Initial";
  @State step2: string = "Step 2: Initial";
  @State step3: string = "Step 3: Initial";

  build() {
    Column() {
      Text(this.isRefreshing ? "Refreshing..." : "Pull to Refresh")
        .fontSize(20)
        .margin(10);

      Text(this.step1)
        .fontSize(18)
        .margin(5);

      Text(this.step2)
        .fontSize(18)
        .margin(5);

      Text(this.step3)
        .fontSize(18)
        .margin(5);

      Refresh({ refreshing: $$this.isRefreshing }) {
        Text("Pull down to refresh")
          .fontSize(18)
          .margin(5);
      }
      .onStateChange(() => {
        this.isRefreshing = true;
      })
      .onRefreshing(() => {
        setTimeout(() => {
          this.step1 = "Step 1: Updated";
          setTimeout(() => {
            this.step2 = "Step 2: Updated";
            setTimeout(() => {
              this.step3 = "Step 3: Updated";
              this.isRefreshing = false;
            }, 500);
          }, 500);
        }, 500);
      })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

