@Entry
@Component
struct ImageGallery {
  @State selectedImage: Resource = $r('app.media.app_icon');
  @State showFullScreen: boolean = false;

  private images: Resource[] = [
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon')
  ];

  build() {
    Column() {
      if (this.showFullScreen) {
        Stack() {
          Image(this.selectedImage)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%');

          Button('Close')
            .onClick(() => {
              this.showFullScreen = false;
            })
            .position({ x: 20, y: 20 })
            .borderRadius(5)
            .padding({ left: 10, right: 10, top: 5, bottom: 5 })
            .backgroundColor('#FFFFFF')
            .borderColor('#000000')
            .borderWidth(1);
        }
      } else {
        Grid() {
          ForEach(this.images, (image: Resource) => {
            GridItem() {
              Image(image)
                .width('100%')
                .aspectRatio(1)
                .objectFit(ImageFit.Cover)
                .borderRadius(5)
                .onClick(() => {
                  this.selectedImage = image;
                  this.showFullScreen = true;
                });
            }
          });
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsGap(10)
        .columnsGap(10)
        .padding(10);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5');
  }
}

@Entry
@Component
struct SwipeNavigationApp {
  private swiperController: SwiperController = new SwiperController()
  private pages: string[] = ["Home", "Profile", "Settings"]

  build() {
    Column() {
      Swiper(this.swiperController) {
        ForEach(this.pages, (page: string) => {
          Column() {
            Text(page)
              .fontSize(30)
              .fontWeight(FontWeight.Bold)
              .textAlign(TextAlign.Center)
              .margin({ top: 20 })
            Image($r('app.media.app_icon'))
              .width(100)
              .height(100)
              .margin({ top: 20 })
          }
          .width('100%')
          .height('100%')
          .backgroundColor(Color.Gray)
          .justifyContent(FlexAlign.Center)
        })
      }
      .cachedCount(2)
      .index(0)
      .autoPlay(false)
      .indicator(Indicator.dot()
        .itemWidth(15)
        .itemHeight(15)
        .selectedItemWidth(15)
        .selectedItemHeight(15)
        .color(Color.Gray)
        .selectedColor(Color.Blue))
      .loop(false)
      .duration(1000)
      .itemSpace(0)
      .displayArrow(true, true)
      .height('70%')

      Row({ space: 12 }) {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious()
          })
        Button('Next')
          .onClick(() => {
            this.swiperController.showNext()
          })
      }
      .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
  }
}

