@Entry
@Component
struct FastSwipeRefreshExample {
  @State refreshing: boolean = false
  @State data: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4', 'Item 5']
  @State refreshState: string = 'idle'

  build() {
    Column() {
      Text(`Current State: ${this.refreshState}`)
        .fontSize(16)
        .margin(10)
        .fontColor(Color.Blue)

      Refresh({ refreshing: $$this.refreshing }) {
        List() {
          ForEach(this.data, (item: string) => {
            ListItem() {
              Row() {
                Image($r('app.media.app_icon'))
                  .width(40)
                  .height(40)
                  .margin(10)

                Text(item)
                  .fontSize(18)
              }
              .width('100%')
              .justifyContent(FlexAlign.Start)
            }
            .borderRadius(8)
            .margin({ top: 5, bottom: 5 })
            .backgroundColor('#f5f5f5')
          }, (item: string) => item)
        }
        .width('100%')
        .height('70%')
      }
      .onStateChange((newState: RefreshStatus) => {
        switch(newState) {
          case RefreshStatus.Inactive:
            this.refreshState = 'inactive'
            break
          case RefreshStatus.Drag:
            this.refreshState = 'dragging'
            break
          case RefreshStatus.OverDrag:
            this.refreshState = 'overdrag'
            break
          case RefreshStatus.Refresh:
            this.refreshState = 'refreshing'
            break
          case RefreshStatus.Done:
            this.refreshState = 'completed'
            break
        }
      })
      .onRefreshing(() => {
        if (this.refreshState === 'overdrag') {
          this.refreshing = true
          setTimeout(() => {
            this.data = [...this.data, `Item ${this.data.length + 1}`]
            this.refreshing = false
          }, 1500)
        }
      })

      if (this.refreshState === 'refreshing') {
        Image($r('app.media.app_icon'))
          .width(50)
          .height(50)
          .margin(10)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff')
  }
}

