@Entry
@Component
struct LoginScreen {
  @State email: string = ''
  @State password: string = ''
  @State message: string = ''
  @State isSuccess: boolean = false

  build() {
    Column() {
      // Email Label and Input
      Text('Email')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your email', text: this.email })
        .onChange((value: string) => {
          this.email = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Password Label and Input
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Login Button
      Button('Login')
        .onClick(() => {
          if (this.validateEmail(this.email) && this.password.length >= 6) {
            this.message = 'Login successful!'
            this.isSuccess = true
          } else {
            this.message = 'Invalid email or password.'
            this.isSuccess = false
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      // Login Message
      if (this.message) {
        Text(this.message)
          .fontSize(16)
          .margin({ top: 20 })
          .fontColor(this.isSuccess ? Color.Green : Color.Red)
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }

  validateEmail(email: string): boolean {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return re.test(email)
  }
}

