@Entry
@Component
struct SegmentButtonExample {
  @State selectedIndex: number = 0;
  @State items: string[] = ['Option 1', 'Option 2', 'Option 3'];

  build() {
    Column() {
      // Segment Buttons
      Row() {
        ForEach(this.items, (item: string, index: number) => {
          Button(item)
            .backgroundColor(this.selectedIndex === index ? '#007AFF' : '#E0E0E0')
            .fontColor(this.selectedIndex === index ? '#FFFFFF' : '#000000')
            .onClick(() => {
              this.selectedIndex = index;
            })
            .margin(5)
            .borderRadius(8)
            .width('30%')
            .height(40)
        })
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceBetween)

      // Display selected option
      Text(`Selected: ${this.items[this.selectedIndex]}`)
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin(20)

      // Button to add a new option
      Button('Add Option')
        .onClick(() => {
          this.items = [...this.items, `Option ${this.items.length + 1}`];
          this.selectedIndex = this.items.length - 1;
        })
        .margin(10)
        .width(200)
        .height(40)

      // Button to remove an option
      Button('Remove Option')
        .onClick(() => {
          if (this.items.length > 1) {
            this.items = this.items.slice(0, -1);
            if (this.selectedIndex >= this.items.length) {
              this.selectedIndex = this.items.length - 1;
            }
          }
        })
        .margin(10)
        .width(200)
        .height(40)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

