@Entry
@Component
struct SegmentButtonFailureAnalysis {
  @State selectedIndex: number = 0;
  @State errorMessage: string = '';
  @State isInvalidSelection: boolean = false;

  build() {
    Column() {
      Row() {
        ForEach(['Option 1', 'Option 2', 'Option 3'], (item: string, index: number) => {
          Button(item)
            .backgroundColor(this.selectedIndex === index ? '#007DFF' : '#F1F3F5')
            .fontColor(this.selectedIndex === index ? '#FFFFFF' : '#000000')
            .onClick(() => {
              if (this.selectedIndex === index) {
                this.errorMessage = `${item} already selected!`;
                this.isInvalidSelection = true;
              } else {
                this.selectedIndex = index;
                this.errorMessage = '';
                this.isInvalidSelection = false;
              }
            })
            .margin(5)
            .borderRadius(8)
        })
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .padding(10)

      Text(`Selected Option: ${this.selectedIndex + 1}`)
        .margin({ top: 20 })
        .fontSize(18)
        .fontColor(Color.Black)

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 10 })
      }

      if (this.isInvalidSelection) {
        Text('Invalid selection detected. Please choose a different option.')
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 10 })
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor('#FFFFFF')
  }
}

