@Component
struct RatingApp {
  private items: Array<Item> = [
    new Item(1, 'Item 1'),
    new Item(2, 'Item 2'),
    new Item(3, 'Item 3')
  ];

  build() {
    Column() {
      Text('Rate Items')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })
        .width('100%')
        .textAlign(TextAlign.Center);

      List() {
        ForEach(this.items, (item: Item) => {
          ListItem() {
            Column() {
              Text(item.title)
                .fontSize(20)
                .fontWeight(FontWeight.Medium)
                .margin({ bottom: 10 });

              Row() {
                ForEach([1, 2, 3, 4, 5], (index: number) => {
                  Image($r('app.media.star'))
                    .width(30)
                    .height(30)
                    .onClick(() => {
                      item.ratings.push(index);
                      item.calculateAverageRating();
                    })
                    .opacity(index <= item.averageRating ? 1 : 0.3);
                });
              }

              Text(`Average Rating: ${item.averageRating.toFixed(2)}`)
                .fontSize(16)
                .margin({ top: 10 });
            }
            .padding(10)
            .backgroundColor('#FFFFFF')
            .borderRadius(5)
            .margin({ bottom: 10 });
          }
        });
      }
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5');
  }
}

class Item {
  id: number;
  title: string;
  ratings: number[] = [];
  averageRating: number = 0;

  constructor(id: number, title: string) {
    this.id = id;
    this.title = title;
  }

  calculateAverageRating(): void {
    if (this.ratings.length > 0) {
      this.averageRating = this.ratings.reduce((sum, rating) => sum + rating, 0) / this.ratings.length;
    }
  }
}

