@Entry
@Component
struct MultipleSwipeRefreshersHandling {
  @State isRefreshing1: boolean = false;
  @State isRefreshing2: boolean = false;
  @State refreshState1: string = 'idle';
  @State refreshState2: string = 'idle';
  @State items1: string[] = ['Item 1.1', 'Item 1.2', 'Item 1.3'];
  @State items2: string[] = ['Item 2.1', 'Item 2.2', 'Item 2.3'];

  build() {
    Column() {
      // First SwipeRefresher with state handling
      Text(`First List State: ${this.refreshState1}`)
        .fontSize(16)
        .margin(10)
        .fontColor(Color.Blue)

      Refresh({ refreshing: $$this.isRefreshing1 }) {
        List() {
          ForEach(this.items1, (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(16)
                .padding(10)
            }
          })
        }
        .width('100%')
        .height('40%')
      }
      .onStateChange((newState: RefreshStatus) => {
        switch(newState) {
          case RefreshStatus.Inactive:
            this.refreshState1 = 'inactive';
            break;
          case RefreshStatus.Drag:
            this.refreshState1 = 'dragging';
            break;
          case RefreshStatus.OverDrag:
            this.refreshState1 = 'overdrag';
            break;
          case RefreshStatus.Refresh:
            this.refreshState1 = 'refreshing';
            break;
          case RefreshStatus.Done:
            this.refreshState1 = 'completed';
            break;
        }
      })
      .onRefreshing(() => {
        this.isRefreshing1 = true;
        setTimeout(() => {
          this.items1.push(`Item 1.${this.items1.length + 1}`);
          this.isRefreshing1 = false;
        }, 2000);
      })

      // Second SwipeRefresher with state handling
      Text(`Second List State: ${this.refreshState2}`)
        .fontSize(16)
        .margin(10)
        .fontColor(Color.Blue)

      Refresh({ refreshing: $$this.isRefreshing2 }) {
        List() {
          ForEach(this.items2, (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(16)
                .padding(10)
            }
          })
        }
        .width('100%')
        .height('40%')
      }
      .onStateChange((newState: RefreshStatus) => {
        switch(newState) {
          case RefreshStatus.Inactive:
            this.refreshState2 = 'inactive';
            break;
          case RefreshStatus.Drag:
            this.refreshState2 = 'dragging';
            break;
          case RefreshStatus.OverDrag:
            this.refreshState2 = 'overdrag';
            break;
          case RefreshStatus.Refresh:
            this.refreshState2 = 'refreshing';
            break;
          case RefreshStatus.Done:
            this.refreshState2 = 'completed';
            break;
        }
      })
      .onRefreshing(() => {
        this.isRefreshing2 = true;
        setTimeout(() => {
          this.items2.push(`Item 2.${this.items2.length + 1}`);
          this.isRefreshing2 = false;
        }, 2000);
      })

      // Visual indicators based on state
      if (this.refreshState1 === 'refreshing') {
        Image($r('app.media.app_icon'))
          .width(50)
          .height(50)
          .margin(10)
      }
      if (this.refreshState2 === 'refreshing') {
        Image($r('app.media.app_icon'))
          .width(50)
          .height(50)
          .margin(10)
      }
    }
    .width('100%')
    .height('100%')
    .padding(10)
  }
}

