@Entry
@Component
struct MultipleStrokeStyles {
  private settings: RenderingContextSettings = new RenderingContextSettings(true)
  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings)

  build() {
    Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Center, justifyContent: FlexAlign.Center }) {
      Canvas(this.context)
        .width('100%')
        .height('100%')
        .backgroundColor('#ffffff')
        .onReady(() => {
          // First stroke style: solid red line
          this.context.lineWidth = 5
          this.context.strokeStyle = '#ff0000'
          this.context.beginPath()
          this.context.moveTo(50, 50)
          this.context.lineTo(250, 50)
          this.context.stroke()

          // Second stroke style: dashed blue line
          this.context.lineWidth = 8
          this.context.strokeStyle = '#0000ff'
          this.context.setLineDash([10, 5])
          this.context.beginPath()
          this.context.moveTo(50, 100)
          this.context.lineTo(250, 100)
          this.context.stroke()

          // Third stroke style: dotted green line with round caps
          this.context.lineWidth = 6
          this.context.strokeStyle = '#00ff00'
          this.context.setLineDash([3, 3])
          this.context.lineCap = 'round'
          this.context.beginPath()
          this.context.moveTo(50, 150)
          this.context.lineTo(250, 150)
          this.context.stroke()

          // Fourth stroke style: thick black line with opacity
          this.context.lineWidth = 10
          this.context.strokeStyle = 'rgba(0, 0, 0, 0.5)'
          this.context.beginPath()
          this.context.moveTo(50, 200)
          this.context.lineTo(250, 200)
          this.context.stroke()
        })
    }
    .width('100%')
    .height('100%')
  }
}

