@Entry
@Component
struct AutoToastDuration {
  @State toastMessage: string = "";
  @State toastVisible: boolean = false;
  @State toastDuration: number = 2000;

  private showAutoToast(message: string): void {
    this.toastMessage = message;
    this.toastVisible = true;

    // Automatically adjust duration based on message length
    this.toastDuration = Math.min(Math.max(message.length * 100, 1000), 5000);

    setTimeout(() => {
      this.toastVisible = false;
    }, this.toastDuration);
  }

  build() {
    Column({ space: 20 }) {
      Button("Show Auto Duration Toast")
        .onClick(() => {
          this.showAutoToast("This toast's duration is automatically set based on its length.");
        })
        .width('50%')
        .height('10%');

      if (this.toastVisible) {
        Text(this.toastMessage)
          .fontSize(20)
          .backgroundColor('#CCCCCC')
          .padding(10)
          .borderRadius(5)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

