@Entry
@Component
struct SwipeGestureCancellation {
  @State offsetX: number = 0
  @State isSwipeCancelled: boolean = false

  build() {
    Column() {
      Text('Swipe to move the box')
        .fontSize(20)
        .margin({ bottom: 20 })

      Row()
        .width(300)
        .height(200)
        .backgroundColor(Color.Blue)
        .borderRadius(10)
        .gesture(
          PanGesture({ direction: PanDirection.Horizontal })
            .onActionStart(() => {
              this.isSwipeCancelled = false
            })
            .onActionUpdate((event: PanGestureEvent) => {
              if (!this.isSwipeCancelled) {
                this.offsetX = event.offsetX
              }
            })
            .onActionEnd(() => {
              if (this.isSwipeCancelled) {
                animateTo({ duration: 300 }, () => {
                  this.offsetX = 0
                })
              }
            })
        )
        .transform({ translate: { x: this.offsetX } })
        .animation({ duration: 300 })

      Button('Cancel Swipe')
        .onClick(() => {
          this.isSwipeCancelled = true
        })
        .width('80%')
        .height(50)
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20)
  }
}

