  @State buttonStates: boolean[] = [true, false, false];
  @State globalState: string = 'Global State: Initial';

  build() {
    Column({ space: 20 }) {
      Row({ space: 10 }) {
        Button('Option 1')
          .stateEffect(this.buttonStates[0])
          .onClick(() => {
            this.updateButtonState(0);
            this.updateGlobalState('Option 1 selected');
          })
          .margin(5)
          .padding(10)
          .borderRadius(5);

        Button('Option 2')
          .stateEffect(this.buttonStates[1])
          .onClick(() => {
            this.updateButtonState(1);
            this.updateGlobalState('Option 2 selected');
          })
          .margin(5)
          .padding(10)
          .borderRadius(5);

        Button('Option 3')
          .stateEffect(this.buttonStates[2])
          .onClick(() => {
            this.updateButtonState(2);
            this.updateGlobalState('Option 3 selected');
          })
          .margin(5)
          .padding(10)
          .borderRadius(5);
      }
      .justifyContent(FlexAlign.Center)
      .width('100%')
      .padding(10);

      Text(this.globalState)
        .fontSize(20)
        .margin({ top: 20 });

      Text(`Selected Option: ${this.selectedIndex + 1}`)
        .fontSize(20)
        .margin({ top: 20 });

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 20 })
        .visibility(this.selectedIndex === 0 ? Visibility.Visible : Visibility.None);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#ffffff');
  }

  updateButtonState(index: number) {
    this.buttonStates = this.buttonStates.map((_, i) => i === index);
    this.selectedIndex = index;
  }

  updateGlobalState(newState: string) {
    this.globalState = `Global State: ${newState}`;
  }
}

