@Entry
@Component
struct SwipeGestureVelocityTracking {
  @State offsetX: number = 0
  @State velocity: number = 0
  private lastTime: number = 0
  private lastOffsetX: number = 0

  build() {
    Column() {
      Text(`Swipe Offset: ${this.offsetX.toFixed(2)}`)
        .fontSize(20)
        .margin({ bottom: 10 })

      Text(`Swipe Velocity: ${this.velocity.toFixed(2)}px/s`)
        .fontSize(20)
        .margin({ bottom: 20 })

      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .gesture(
          PanGesture({ direction: PanDirection.Horizontal })
            .onActionStart((event: PanGestureEvent) => {
              this.lastTime = event.timestamp
              this.lastOffsetX = this.offsetX
            })
            .onActionUpdate((event: PanGestureEvent) => {
              const currentTime = event.timestamp
              const deltaTime = (currentTime - this.lastTime) / 1000
              const deltaOffsetX = event.offsetX - this.lastOffsetX

              this.offsetX += deltaOffsetX
              this.velocity = deltaOffsetX / deltaTime

              this.lastTime = currentTime
              this.lastOffsetX = this.offsetX
            })
            .onActionEnd(() => {
              this.velocity = 0
            })
        )
        .transform({ translate: { x: this.offsetX } })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

