@Component
struct ShakeTextInputEffect {
  @State text: string = ''
  @State shake: boolean = false
  controller: TextInputController = new TextInputController()

  build() {
    Column() {
      TextInput({ placeholder: 'Enter text...', controller: this.controller })
        .width(300)
        .height(50)
        .borderColor(this.shake ? Color.Red : Color.Gray)
        .borderWidth(2)
        .animation({
          duration: 100,
          iterations: 3,
          curve: Curve.EaseInOut,
          onFinish: () => {
            this.shake = false
          }
        })
        .onChange((value: string) => {
          this.text = value
          if (!this.validateInput(value)) {
            this.shake = true
          }
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(Color.White)
  }

  validateInput(input: string): boolean {
    return input.trim() !== ''
  }
}

@Entry
@Component
struct SwipeGestureWithCustomTags {
  @State offsetX: number = 0
  @State currentIndex: number = 0
  @State tags: string[] = ['Custom Tag 1', 'Custom Tag 2', 'Custom Tag 3', 'Custom Tag 4']

  build() {
    Column() {
      Text('Swipe to change custom tags')
        .fontSize(20)
        .margin({ bottom: 20 })

      Row() {
        Text(this.tags[this.currentIndex])
          .fontSize(18)
          .fontColor(Color.White)
          .padding(10)
          .backgroundColor(Color.Blue)
          .borderRadius(5)
      }
      .width(300)
      .height(100)
      .justifyContent(FlexAlign.Center)
      .gesture(
        PanGesture({ direction: PanDirection.Horizontal })
          .onActionStart(() => {
            console.info('Pan start')
          })
          .onActionUpdate((event: GestureEvent) => {
            this.offsetX = event.offsetX
          })
          .onActionEnd(() => {
            if (this.offsetX > 50) {
              this.currentIndex = (this.currentIndex - 1 + this.tags.length) % this.tags.length
            } else if (this.offsetX < -50) {
              this.currentIndex = (this.currentIndex + 1) % this.tags.length
            }
            animateTo({ duration: 300 }, () => {
              this.offsetX = 0
            })
          })
      )
      .transform({ translate: { x: this.offsetX } })
      .animation({ duration: 300 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

