@Entry
@Component
struct RatingApp {
  @State ratings: number[] = [];
  @State averageRating: number = 0;
  @State currentRating: number = 0;

  private calculateAverage(): void {
    if (this.ratings.length === 0) {
      this.averageRating = 0;
      return;
    }
    const sum = this.ratings.reduce((acc, curr) => acc + curr, 0);
    this.averageRating = sum / this.ratings.length;
  }

  private handleRating(rating: number): void {
    this.currentRating = rating;
    this.ratings.push(rating);
    this.calculateAverage();
  }

  build() {
    Column() {
      Text('Rate the Item')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Text(`Average Rating: ${this.averageRating.toFixed(1)}`)
        .fontSize(18)
        .margin({ bottom: 20 });

      Row({ space: 5 }) {
        ForEach([1, 2, 3, 4, 5], (index: number) => {
          Image($r('app.media.app_icon'))
            .width(30)
            .height(30)
            .opacity(index <= this.currentRating ? 1 : 0.3)
            .onClick(() => {
              this.handleRating(index);
            });
        })
      }
      .margin({ bottom: 20 });

      if (this.ratings.length > 0) {
        Text(`Total Ratings: ${this.ratings.length}`)
          .fontSize(16)
          .margin({ bottom: 20 });
      }

      Button("Submit Rating")
        .onClick(() => {
          console.log("Rating submitted:", this.ratings);
        })
        .width(200)
        .height(50)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }
}

