@Component
struct NavigationDrawerApp {
  @State isDrawerOpen: boolean = false;
  @State selectedItem: string = 'Home';

  build() {
    Column() {
      // Main Content Area
      this.ContentArea();

      // Toggle Drawer Button
      Button('Toggle Drawer')
        .onClick(() => {
          this.isDrawerOpen = !this.isDrawerOpen;
        })
        .margin(10);

      // Navigation Drawer
      Panel(this.isDrawerOpen) {
        Column() {
          this.DrawerItem('Home');
          this.DrawerItem('Settings');
        }
        .width('250px')
        .height('100%')
        .backgroundColor(Color.White);
      }
      .mode(PanelMode.Mini)
      .type(PanelType.Temporary)
      .dragBar(false);
    }
    .width('100%')
    .height('100%');
  }

  @Builder ContentArea() {
    Column() {
      if (this.selectedItem === 'Home') {
        Text('Welcome to the Home Screen')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .padding(16);
      } else if (this.selectedItem === 'Settings') {
        Text('This is the Settings Screen')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%');
  }

  @Builder DrawerItem(label: string) {
    Text(label)
      .fontSize(20)
      .padding(16)
      .onClick(() => {
        this.selectedItem = label;
        this.isDrawerOpen = false;
      })
      .backgroundColor(this.selectedItem === label ? '#D3D3D3' : Color.Transparent)
      .margin({ bottom: 1 });
  }
}

@Entry
@Component
struct LoginForm {
  @State username: string = ''
  @State password: string = ''
  @State snackbarMessage: string = ''
  @State showSnackbar: boolean = false

  validateCredentials(): boolean {
    if (this.username && this.password) {
      this.snackbarMessage = 'Login successful!'
      return true
    } else {
      this.snackbarMessage = 'Please enter both username and password.'
      return false
    }
  }

  build() {
    Column() {
      // Username Label and Input
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your username', text: this.username })
        .onChange((value: string) => {
          this.username = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Password Label and Input
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Login Button
      Button('Login')
        .onClick(() => {
          if (this.validateCredentials()) {
            this.showSnackbar = true
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
