@Entry
@Component
struct JokeApp {
  @State jokes: Array<Joke> = [];
  @State isLoading: boolean = true;

  aboutToAppear() {
    this.fetchJokes();
  }

  fetchJokes() {
    setTimeout(() => {
      this.jokes = [
        new Joke("Why don't scientists trust atoms? Because they make up everything!", 0),
        new Joke("Why did the scarecrow win an award? Because he was outstanding in his field!", 0),
        new Joke("Why don't skeletons fight each other? They don't have the guts.", 0),
        new Joke("What do you call fake spaghetti? An impasta!", 0),
        new Joke("Why did the bicycle fall over? Because it was two-tired!", 0),
        new Joke("What do you call cheese that isn't yours? Nacho cheese!", 0),
        new Joke("Why can't you give Elsa a balloon? Because she will let it go!", 0),
        new Joke("What do you get when you cross a snowman and a vampire? Frostbite!", 0),
        new Joke("Why did the math book look sad? Because it had too many problems.", 0),
        new Joke("What do you call a bear with no teeth? A gummy bear!", 0)
      ];
      this.isLoading = false;
    }, 2000);
  }

  likeJoke(index: number) {
    this.jokes[index].likes += 1;
  }

  build() {
    Column() {
      if (this.isLoading) {
        Text('Loading jokes...')
          .fontSize(20)
          .fontColor(Color.Gray)
          .margin({ top: 20 });
      } else {
        List() {
          ForEach(this.jokes, (joke: Joke, index: number) => {
            ListItem() {
              Row() {
                Column() {
                  Text(joke.text)
                    .fontSize(18)
                    .margin({ bottom: 8 });

                  Row() {
                    Text(`Likes: ${joke.likes}`)
                      .fontSize(14)
                      .fontColor(Color.Gray);

                    Button('Like')
                      .margin({ left: 10 })
                      .onClick(() => {
                        this.likeJoke(index);
                      });
                  }
                }
              }
              .padding(16)
              .backgroundColor('#f0f0f0')
              .borderRadius(8)
              .margin({ bottom: 10 });
            }
          }, (joke: Joke) => joke.text);
        }
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

class Joke {
  text: string;
  likes: number;

  constructor(text: string, likes: number) {
    this.text = text;
    this.likes = likes;
  }
}

