@Entry
@Component
struct LoginScreen {
  @State username: string = ''
  @State password: string = ''
  @State successMessage: string = ''
  @State errorMessage: string = ''

  validateCredentials(): boolean {
    if (this.username && this.password) {
      this.successMessage = 'Login successful!'
      this.errorMessage = ''
      return true
    } else {
      this.errorMessage = 'Please fill in both fields'
      this.successMessage = ''
      return false
    }
  }

  build() {
    Column() {
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your username' })
        .onChange((value: string) => {
          this.username = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      Button('Login')
        .onClick(() => {
          if (this.validateCredentials()) {
            console.info(this.successMessage)
          } else {
            console.error(this.errorMessage)
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(16)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(16)
          .fontColor(Color.Red)
          .margin({ top: 20 })
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
  }
}

@Entry
@Component
struct AnimatedCircularProgress {
  @State progress: number = 0
  @State isAnimating: boolean = true
  private intervalId: number = -1

  aboutToAppear() {
    this.startAnimation()
  }

  startAnimation() {
    this.intervalId = setInterval(() => {
      if (this.progress < 100) {
        this.progress += 1
      } else {
        this.progress = 0
      }
    }, 50)
  }

  stopAnimation() {
    if (this.intervalId !== -1) {
      clearInterval(this.intervalId)
      this.isAnimating = false
    }
  }

  build() {
    Column() {
      Stack() {
        Circle()
          .width(200)
          .height(200)
          .stroke('#E0E0E0')
          .strokeWidth(15)
          .fill('transparent')

        Circle()
          .width(200)
          .height(200)
          .stroke('#4CAF50')
          .strokeWidth(15)
          .fill('transparent')
          .strokeDashArray([Math.PI * 2 * 100, Math.PI * 2 * 100])
          .strokeDashOffset(Math.PI * 2 * 100 * (1 - this.progress / 100))
          .rotate({ x: 0, y: 0, z: 1, angle: -90 })

        Text(`${Math.round(this.progress)}%`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
      }
      .width(200)
      .height(200)

      Button(this.isAnimating ? 'Stop Animation' : 'Start Animation')
        .onClick(() => {
          if (this.isAnimating) {
            this.stopAnimation()
          } else {
            this.startAnimation()
            this.isAnimating = true
          }
        })
        .margin({ top: 40 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

