@Entry
@Component
struct SwipeGestureWithMomentum {
  @State offsetX: number = 0
  @State velocity: number = 0
  private lastTime: number = 0
  private lastOffsetX: number = 0

  build() {
    Column() {
      Text('Swipe with momentum effect')
        .fontSize(20)
        .margin({ bottom: 20 })

      Row()
        .width(300)
        .height(200)
        .backgroundColor(Color.Blue)
        .borderRadius(10)
        .gesture(
          PanGesture({ direction: PanDirection.Horizontal })
            .onActionStart(() => {
              this.lastTime = Date.now()
              this.lastOffsetX = this.offsetX
            })
            .onActionUpdate((event: GestureEvent) => {
              const currentTime = Date.now()
              const deltaTime = (currentTime - this.lastTime) / 1000
              const deltaX = event.offsetX - this.lastOffsetX

              this.velocity = deltaX / deltaTime
              this.offsetX = event.offsetX
              this.lastTime = currentTime
              this.lastOffsetX = this.offsetX
            })
            .onActionEnd(() => {
              const momentum = this.velocity * 100
              animateTo({ duration: Math.abs(momentum) / 100 }, () => {
                this.offsetX += momentum
              })
            })
        )
        .transform({ translate: { x: this.offsetX } })
        .animation({ duration: 300 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

