@Entry
@Component
struct PolygonStateManagement {
  @State private polygonPoints: Array<[number, number]> = [[50, 0], [100, 100], [0, 100]];
  @State private fillColor: string = '#00ff00';
  @State private isActive: boolean = false;

  private settings: RenderingContextSettings = new RenderingContextSettings(true);
  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings);

  build() {
    Column({ space: 10 }) {
      Canvas(this.context)
        .width(200)
        .height(200)
        .backgroundColor('#ffff00')
        .onReady(() => {
          let region = new Path2D();
          this.polygonPoints.forEach((point, index) => {
            if (index === 0) {
              region.moveTo(point[0], point[1]);
            } else {
              region.lineTo(point[0], point[1]);
            }
          });
          region.closePath();
          this.context.fillStyle = this.fillColor;
          this.context.fill(region, "evenodd");
        });

      Button('Toggle Polygon State')
        .onClick(() => {
          this.isActive = !this.isActive;
          console.log(`Polygon state toggled to: ${this.isActive}`);
        });

      Button('Change Color')
        .onClick(() => {
          this.fillColor = this.isActive ? '#ff0000' : '#00ff00';
        });

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 20 })
        .clip(new Path().commands('M50 0 L100 100 L0 100 Z'));
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

