@Entry
@Component
struct TodoList {
  @State tasks: Array<Task> = []
  @State newTask: string = ''

  build() {
    Column() {
      TextInput({ placeholder: 'Enter a new task' })
        .onChange((value: string) => {
          this.newTask = value
        })
        .margin({ bottom: 20 })

      Button('Add Task')
        .onClick(() => {
          if (this.newTask) {
            this.tasks.push({ id: Date.now(), content: this.newTask, completed: false })
            this.newTask = ''
          }
        })
        .margin({ bottom: 20 })

      ForEach(this.tasks, (task: Task, index: number) => {
        Row() {
          Checkbox()
            .select(task.completed)
            .onChange((value: boolean) => {
              this.tasks[index].completed = value
            })
            .margin({ right: 10 })

          Text(task.content)
            .fontSize(20)
            .decoration({ type: task.completed ? TextDecorationType.LineThrough : TextDecorationType.None })

          Button() {
            Image($r('app.media.app_icon'))
              .width(20)
              .height(20)
          }
          .onClick(() => {
            this.tasks.splice(index, 1)
          })
          .margin({ left: 10 })
        }
        .margin({ top: 10 })
      })
    }
    .padding(20)
  }
}

interface Task {
  id: number
  content: string
  completed: boolean
}

