@Entry
@Component
struct PullToRefreshCustomAnimation {
  @State refreshing: boolean = false
  @State items: string[] = ['Item 1', 'Item 2', 'Item 3']
  @State scaleValue: number = 1.0
  @State rotateValue: number = 0
  @State opacityValue: number = 1.0
  private timerId: number = -1

  build() {
    Column() {
      // Custom loading animation
      if (this.refreshing) {
        Row() {
          Image($r('app.media.app_icon'))
            .width(30)
            .height(30)
            .scale({ x: this.scaleValue, y: this.scaleValue })
            .rotate({ angle: this.rotateValue })
            .opacity(this.opacityValue)
            .animation({
              duration: 1000,
              curve: Curve.EaseInOut,
              iterations: -1,
              playMode: PlayMode.Normal
            })
          Text('Refreshing...')
            .margin({ left: 10 })
        }
        .width('100%')
        .justifyContent(FlexAlign.Center)
        .padding(10)
        .onAppear(() => {
          animateTo({
            duration: 1000,
            curve: Curve.EaseInOut,
            iterations: -1,
            playMode: PlayMode.Normal
          }, () => {
            this.scaleValue = 1.5
            this.rotateValue = 360
            this.opacityValue = 0.7
          })
        })
      }

      // List with pull-to-refresh
      Refresh({ refreshing: $$this.refreshing, friction: 100 }) {
        List() {
          ForEach(this.items, (item: string) => {
            ListItem() {
              Text(item)
                .width('100%')
                .height(50)
                .fontSize(16)
                .textAlign(TextAlign.Center)
                .backgroundColor('#f5f5f5')
                .margin({ top: 10 })
            }
          })
        }
        .width('100%')
        .height('100%')
      }
      .onStateChange((refreshStatus: RefreshStatus) => {
        console.info('Refresh status changed to: ' + refreshStatus)
      })
      .onRefreshing(() => {
        // Simulate data fetching
        this.timerId = setTimeout(() => {
          // Add new items
          this.items = ['New Item ' + (this.items.length + 1), ...this.items]
          this.refreshing = false
        }, 2000)
      })
    }
    .width('100%')
    .height('100%')
  }

  aboutToDisappear() {
    if (this.timerId !== -1) {
      clearTimeout(this.timerId)
    }
  }
}

