      // Success or Error Message
      if (this.showMessage) {
        Text(this.message)
          .fontSize(18)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
          .fontColor(this.message === 'Login successful!' ? Color.Green : Color.Red)
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5')
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
  }
}

