@Entry
@Component
struct FavoriteFoodApp {
  @State foodList: FoodItem[] = []
  @State newFood: string = ''

  private nextId: number = 1

  build() {
    Column() {
      Text('Add Your Favorite Foods')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      TextInput({ placeholder: 'Enter your favorite food' })
        .width('90%')
        .height(40)
        .fontSize(16)
        .padding(10)
        .borderRadius(5)
        .borderWidth(1)
        .borderColor('#CCCCCC')
        .onChange((value: string) => {
          this.newFood = value
        })

      Button('Add Food')
        .width('90%')
        .height(40)
        .margin({ top: 10, bottom: 20 })
        .onClick(() => {
          if (this.newFood.trim() !== '') {
            this.foodList.push({ id: this.nextId++, name: this.newFood })
            this.newFood = ''
          }
        })

      List({ space: 10 }) {
        ForEach(this.foodList, (food: FoodItem) => {
          ListItem() {
            Text(food.name)
              .fontSize(18)
              .padding(10)
              .onClick(() => {
                this.foodList = this.foodList.filter((item) => item.id !== food.id)
              })
          }
          .backgroundColor('#F5F5F5')
          .borderRadius(5)
          .margin({ bottom: 10 })
        })
      }
      .width('100%')
      .layoutWeight(1)
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16)
  }
}

interface FoodItem {
  id: number
  name: string
}

