@Entry
@Component
struct SwipeGestureWithCustomTriggers {
  @State offsetX: number = 0
  @State triggerAction: string = 'No Action'

  build() {
    Column() {
      Text('Swipe to trigger custom actions')
        .fontSize(20)
        .margin({ bottom: 20 })

      Row()
        .width(300)
        .height(200)
        .backgroundColor(Color.Green)
        .borderRadius(10)
        .gesture(
          PanGesture({ direction: PanDirection.Horizontal })
            .onActionStart(() => {
              console.info('Pan start')
            })
            .onActionUpdate((event: GestureEvent) => {
              this.offsetX = event.offsetX
              if (this.offsetX > 100) {
                this.triggerAction = 'Right Swipe Triggered'
              } else if (this.offsetX < -100) {
                this.triggerAction = 'Left Swipe Triggered'
              }
            })
            .onActionEnd(() => {
              animateTo({ duration: 300 }, () => {
                this.offsetX = 0
              })
              this.triggerAction = 'No Action'
            })
        )
        .transform({ translate: { x: this.offsetX } })
        .animation({ duration: 300 })

      Text(this.triggerAction)
        .fontSize(16)
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

