struct CustomPopupArchitecture {
  @State isPopupVisible: boolean = false;
  @State popupPlacement: string = "center";

  build() {
    Column({ space: 20 }) {
      Button('Show Custom Popup')
        .onClick(() => {
          this.isPopupVisible = true;
        })
        .padding(10)
        .backgroundColor(Color.Blue)
        .fontColor(Color.White)
        .shadow({ radius: 5 })

      if (this.isPopupVisible) {
        Column() {
          Text('Popup Placement Options')
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .fontColor(Color.Black)
            .margin({ bottom: 20 })

          Image($r('app.media.app_icon'))
            .width(100)
            .height(100)
            .margin({ bottom: 20 })

          Row({ space: 10 }) {
            Button('Top')
              .onClick(() => {
                this.popupPlacement = "top";
              })
              .backgroundColor(Color.Gray)
              .fontColor(Color.White)

            Button('Center')
              .onClick(() => {
                this.popupPlacement = "center";
              })
              .backgroundColor(Color.Gray)
              .fontColor(Color.White)

            Button('Bottom')
              .onClick(() => {
                this.popupPlacement = "bottom";
              })
              .backgroundColor(Color.Gray)
              .fontColor(Color.White)
          }
          .margin({ bottom: 20 })

          Row({ space: 10 }) {
            Button('Cancel')
              .onClick(() => {
                this.isPopupVisible = false;
              })
              .backgroundColor(Color.Gray)
              .fontColor(Color.White)

            Button('Confirm')
              .onClick(() => {
                console.log('Confirm button clicked');
                this.isPopupVisible = false;
              })
              .backgroundColor(Color.Blue)
              .fontColor(Color.White)
          }
        }
        .backgroundColor(Color.White)
        .borderRadius(10)
        .shadow({ radius: 10 })
        .padding(20)
        .position(this.popupPlacement === "top" ? { x: 0, y: 0 } :
                  this.popupPlacement === "bottom" ? { x: 0, y: '60%' } :
                  { x: '10%', y: '30%' })
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

