@Entry
@Component
struct SearchApp {
  private item: Item = {
    id: 0,
    name: '',
    description: '',
    image: $r('app.media.icon')
  };

  @State items: Array<Item> = [
    { id: 1, name: 'Apple', description: 'A sweet and crunchy fruit.', image: $r('app.media.icon') },
    { id: 2, name: 'Banana', description: 'A long and yellow fruit.', image: $r('app.media.icon') },
    { id: 3, name: 'Orange', description: 'A citrus fruit with a bright color.', image: $r('app.media.icon') },
    { id: 4, name: 'Grapes', description: 'Small and juicy fruits in clusters.', image: $r('app.media.icon') },
    { id: 5, name: 'Mango', description: 'A tropical fruit with a rich flavor.', image: $r('app.media.icon') },
    { id: 6, name: 'Pineapple', description: 'A spiky and sweet tropical fruit.', image: $r('app.media.icon') },
    { id: 7, name: 'Strawberry', description: 'A red and juicy berry.', image: $r('app.media.icon') },
    { id: 8, name: 'Watermelon', description: 'A large and refreshing fruit.', image: $r('app.media.icon') },
    { id: 9, name: 'Cherry', description: 'Small and sweet red fruits.', image: $r('app.media.icon') },
    { id: 10, name: 'Blueberry', description: 'Tiny blue berries packed with flavor.', image: $r('app.media.icon') }
  ];

  @State searchText: string = '';

  filteredItems(): Array<Item> {
    if (this.searchText.trim() === '') {
      return this.items;
    } else {
      return this.items.filter(item =>
        item.name.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  build() {
    Column() {
      TextInput({
        placeholder: 'Search items...',
        text: this.searchText
      })
        .width('100%')
        .onChange((value: string) => {
          this.searchText = value;
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      if (this.filteredItems().length > 0) {
        List() {
          ForEach(this.filteredItems(), (item: Item) => {
            ListItem() {
              Row() {
                Image(item.image)
                  .width(50)
                  .height(50)
                  .margin({ right: 12 });
                Column() {
                  Text(item.name)
                    .fontSize(18);
                  Text(item.description)
                    .fontSize(14)
                    .fontColor(Color.Gray);
                }
              }
              .padding(12);
            }
          }, (item: Item) => item.id.toString());
        }
      } else {
        Text('No items found')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

