@Component
struct ImageGalleryApp {
  @State selectedImage: Resource | null = null
  @State showFullScreen: boolean = false
  @State imageDescription: string = ''

  private images: Resource[] = [
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon')
  ]

  private descriptions: string[] = [
    'Description for Image 1',
    'Description for Image 2',
    'Description for Image 3',
    'Description for Image 4',
    'Description for Image 5',
    'Description for Image 6',
    'Description for Image 7',
    'Description for Image 8',
    'Description for Image 9'
  ]

  build() {
    Column() {
      if (this.showFullScreen && this.selectedImage) {
        Stack({ alignContent: Alignment.Bottom }) {
          Image(this.selectedImage)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('80%')
            .onClick(() => {
              this.showFullScreen = false
            })

          Text(this.imageDescription)
            .fontSize(18)
            .fontColor(Color.White)
            .backgroundColor(Color.Black)
            .padding(10)
            .width('100%')
            .textAlign(TextAlign.Center)
        }
        .backgroundColor(Color.Black)
      } else {
        Grid() {
          ForEach(this.images, (image: Resource, index: number) => {
            GridItem() {
              Column() {
                Image(image)
                  .width(100)
                  .height(100)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(10)
                  .onClick(() => {
                    this.selectedImage = image
                    this.imageDescription = this.descriptions[index]
                    this.showFullScreen = true
                  })

                Text(this.descriptions[index])
                  .fontSize(12)
                  .textAlign(TextAlign.Center)
              }
            }
          })
        }
        .columnsTemplate('1fr 1fr 1fr')
        .columnsGap(10)
        .rowsGap(10)
        .padding(10)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

