              .justifyContent(FlexAlign.Start)
              .padding(12)
              .backgroundColor('#f0f0f0')
              .borderRadius(12)
              .margin({ top: 8, bottom: 8 });
            }
          }, (item: string) => item);
        }
        .width('100%');
      }
      .onRefreshing(() => {
        this.refreshing = true;
        setTimeout(() => {
          this.dashboardData = [...this.dashboardData, `Dashboard Item ${this.dashboardData.length + 1}`];
