@Entry
@Component
struct WaterIntakeTracker {
  @State waterIntake: number = 0;
  @State dailyGoal: number = 2000; // Default daily goal in milliliters
  @State progress: number = 0;

  updateProgress() {
    this.progress = (this.waterIntake / this.dailyGoal) * 100;
  }

  build() {
    Column() {
      Text('Daily Water Intake Tracker')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin(20);

      Text(`Goal: ${this.dailyGoal} ml`)
        .fontSize(18)
        .margin(10);

      Text(`Consumed: ${this.waterIntake} ml`)
        .fontSize(18)
        .margin(10);

      Stack() {
        Circle()
          .width(200)
          .height(200)
          .stroke('#E0E0E0')
          .strokeWidth(15)
          .fill('transparent');

        Circle()
          .width(200)
          .height(200)
          .stroke('#4CAF50')
          .strokeWidth(15)
          .fill('transparent')
          .strokeDashArray([Math.PI * 200, Math.PI * 200])
          .strokeDashOffset(Math.PI * 200 * (1 - this.progress / 100))
          .rotate({ x: 0, y: 0, z: 1, angle: -90 });

        Text(`${Math.round(this.progress)}%`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold);
      }
      .width(200)
      .height(200)
      .margin({ top: 50 });

      Row() {
        Button('+250 ml')
          .onClick(() => {
            this.waterIntake += 250;
            this.updateProgress();
          })
          .margin(10);

        Button('+500 ml')
          .onClick(() => {
            this.waterIntake += 500;
            this.updateProgress();
          })
          .margin(10);
      }

      Button('Reset')
        .onClick(() => {
          this.waterIntake = 0;
          this.updateProgress();
        })
        .margin(20);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

