      .dragBar(false);
    }
    .width('100%')
    .height('100%');
  }

  getSelectedContent() {
    switch (this.selectedItem) {
      case 'Home':
        return 'Welcome Home';
      case 'Settings':
        return 'Adjust Settings';
      default:
        return '';
    }
  }
}

@Entry
@Component
struct TextInputVerification {
  @State inputText: string = ''
  @State isValid: boolean = true
  @State errorMessage: string = ''

  validateInput(value: string): boolean {
    return value.length >= 3 && /^[A-Za-z0-9]+$/.test(value)
  }

  build() {
    Column() {
      TextInput({ placeholder: 'Enter username' })
        .width('90%')
        .height(40)
        .margin(10)
        .onChange((value: string) => {
          this.inputText = value
          this.isValid = this.validateInput(value)
          this.errorMessage = this.isValid ? '' : 'Username must be at least 3 characters and alphanumeric'
        })
        .borderColor(this.isValid ? Color.Green : Color.Red)
        .borderWidth(1)

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 10 })
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

