@Entry
@Component
struct FloatingActionButtonInteraction {
  @State isFabClicked: boolean = false;
  @State isExpanded: boolean = false;
  @State opacityValue: number = 1.0;

  build() {
    Column() {
      if (this.isFabClicked) {
        Text("FAB Clicked!")
          .fontSize(20)
          .fontColor(Color.Black)
          .margin({ bottom: 20 });
      }

      // Main Floating Action Button
      Button() {
        Image($r('app.media.app_icon'))
          .width(40)
          .height(40)
      }
      .width(60)
      .height(60)
      .backgroundColor(Color.Blue)
      .borderRadius(30)
      .align(Alignment.BottomEnd)
      .margin({ bottom: 20, right: 20 })
      .onClick(() => {
        this.isFabClicked = !this.isFabClicked;
        this.isExpanded = !this.isExpanded;
        this.opacityValue = this.isExpanded ? 0.7 : 1.0;
      })
      .animation({ duration: 300, curve: Curve.EaseInOut })

      // Additional Buttons
      Stack() {
        if (this.isExpanded) {
          Button() {
            Image($r('app.media.app_icon'))
              .width(30)
              .height(30)
          }
          .width(50)
          .height(50)
          .backgroundColor(Color.Green)
          .borderRadius(25)
          .align(Alignment.BottomEnd)
          .margin({ bottom: 90, right: 20 })
          .opacity(this.opacityValue)
          .animation({ duration: 300, curve: Curve.EaseInOut })

          Button() {
            Image($r('app.media.app_icon'))
              .width(30)
              .height(30)
          }
          .width(50)
          .height(50)
          .backgroundColor(Color.Red)
          .borderRadius(25)
          .align(Alignment.BottomEnd)
          .margin({ bottom: 150, right: 20 })
          .opacity(this.opacityValue)
          .animation({ duration: 300, curve: Curve.EaseInOut })

          Button() {
            Image($r('app.media.app_icon'))
              .width(30)
              .height(30)
          }
          .width(50)
          .height(50)
          .backgroundColor(Color.Blue)
          .borderRadius(25)
          .align(Alignment.BottomEnd)
          .margin({ bottom: 210, right: 20 })
          .opacity(this.opacityValue)
          .animation({ duration: 300, curve: Curve.EaseInOut })
        }
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
  }
}

import promptAction from '@ohos.promptAction';

@Entry
@Component
struct UserForm {
  @State name: string = '';
  @State email: string = '';
  @State showDialog: boolean = false;

  build() {
    Column() {
      Text('User Information')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value;
          });
      }

      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value;
          });
      }

      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.name && this.email) {
            this.showDialog = true;
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields'
            });
          }
        });

      if (this.showDialog) {
        Column() {
          Text('Submitted Information')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Name: ${this.name}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.showDialog = false;
              this.name = '';
              this.email = '';
            });
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

@Entry
@Component
struct PopupInteractionTracker {
  @State isPopupVisible: boolean = false;
  @State selectedOption: string = 'None';

  private logInteraction(action: string, details: string) {
    console.log(`User Interaction: ${action} - ${details}`);
  }

  build() {
    Column({ space: 20 }) {
      Button('Show Popup')
        .margin(20)
        .onClick(() => {
          this.isPopupVisible = !this.isPopupVisible;
          this.logInteraction('Popup Toggle', `Visibility: ${this.isPopupVisible}`);
        });

      if (this.isPopupVisible) {
        Column() {
          Text('Option A')
            .fontSize(18)
            .padding(10)
            .onClick(() => {
              this.selectedOption = 'Option A';
              this.logInteraction('Option Selected', this.selectedOption);
              this.isPopupVisible = false;
            });

          Text('Option B')
            .fontSize(18)
            .padding(10)
            .onClick(() => {
              this.selectedOption = 'Option B';
              this.logInteraction('Option Selected', this.selectedOption);
              this.isPopupVisible = false;
            });

          Text('Option C')
            .fontSize(18)
            .padding(10)
            .onClick(() => {
              this.selectedOption = 'Option C';
              this.logInteraction('Option Selected', this.selectedOption);
              this.isPopupVisible = false;
            });
        }
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(10)
        .shadow({ radius: 5 })
        .margin({ top: 10 });
      }

      Text(`Selected Option: ${this.selectedOption}`)
        .fontSize(16)
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

