@Entry
@Component
struct MultiComponentRefreshExample {
  @State private isRefreshing: boolean = false;
  @State private data1: string = "Initial Data 1";
  @State private data2: string = "Initial Data 2";
  @State private data3: string = "Initial Data 3";
  @State private refreshCount: number = 0;

  onRefresh() {
    this.isRefreshing = true;
    setTimeout(() => {
      this.data1 = "Updated Data 1";
      this.data2 = "Updated Data 2";
      this.data3 = "Updated Data 3";
      this.refreshCount += 1;
      this.isRefreshing = false;
    }, 2000);
  }

  build() {
    Column() {
      // Component 1
      Text(this.data1)
        .fontSize(20)
        .margin(10)
        .onClick(() => {
          this.data1 = "Clicked Data 1";
        });

      // Component 2
      Text(this.data2)
        .fontSize(20)
        .margin(10)
        .onClick(() => {
          this.data2 = "Clicked Data 2";
        });

      // Component 3
      Text(this.data3)
        .fontSize(20)
        .margin(10)
        .onClick(() => {
          this.data3 = "Clicked Data 3";
        });

      // Refresh Button
      Button('Refresh All')
        .onClick(() => {
          this.onRefresh();
        })
        .margin(20)
        .width(200)
        .height(50);

      // Refresh Status
      Text('Refreshing Status: ' + this.isRefreshing)
        .fontSize(18)
        .margin(5);

      // Refresh Count
      Text('Number of Refreshes: ' + this.refreshCount)
        .fontSize(18)
        .margin(5);

      // Loading Indicator
      if (this.isRefreshing) {
        LoadingProgress()
          .width(50)
          .height(50)
          .margin(10);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

