@Entry
@Component
struct NoteApp {
  @State notes: Array<Note> = [];
  @State newNoteTitle: string = '';
  @State newNoteDescription: string = '';
  @State editNoteId: number | null = null;

  build() {
    Column() {
      TextInput({ placeholder: 'Enter note title...', text: this.newNoteTitle })
        .height(50)
        .width('90%')
        .onChange((value: string) => {
          this.newNoteTitle = value;
        })
        .margin(10);

      TextArea({ placeholder: 'Enter note description...', text: this.newNoteDescription })
        .height(100)
        .width('90%')
        .onChange((value: string) => {
          this.newNoteDescription = value;
        })
        .margin(10);

      Button(this.editNoteId !== null ? 'Update Note' : 'Add Note')
        .onClick(() => {
          if (this.newNoteTitle.trim() && this.newNoteDescription.trim()) {
            if (this.editNoteId !== null) {
              const index = this.notes.findIndex(note => note.id === this.editNoteId);
              if (index !== -1) {
                this.notes[index] = new Note(this.editNoteId, this.newNoteTitle, this.newNoteDescription);
              }
              this.editNoteId = null;
            } else {
              this.notes.push(new Note(Date.now(), this.newNoteTitle, this.newNoteDescription));
            }
            this.newNoteTitle = '';
            this.newNoteDescription = '';
          }
        })
        .margin(10);

      List() {
        ForEach(this.notes, (note: Note) => {
          ListItem() {
            Row() {
              Column() {
                Text(note.title)
                  .fontSize(20)
                  .fontWeight(FontWeight.Bold)
                  .width('80%');
                Text(note.description)
                  .fontSize(16)
                  .width('80%');
              }
              .width('80%');

              Button('Edit')
                .onClick(() => {
                  this.newNoteTitle = note.title;
                  this.newNoteDescription = note.description;
                  this.editNoteId = note.id;
                })
                .margin(5);

              Button('Delete')
                .onClick(() => {
                  this.notes = this.notes.filter(n => n.id !== note.id);
                })
                .margin(5);
            }
            .padding(10);
          }
        });
      }
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

class Note {
  id: number;
  title: string;
  description: string;

  constructor(id: number, title: string, description: string) {
    this.id = id;
    this.title = title;
    this.description = description;
  }
}

@Entry
@Component
struct RegistrationForm {
  @State name: string = ''
  @State email: string = ''
  @State password: string = ''
  @State successMessage: string = ''
  @State errorMessage: string = ''

  validateForm(): boolean {
    if (!this.name || !this.email || !this.password) {
      this.errorMessage = 'All fields are required'
      return false
    }
    this.errorMessage = ''
    return true
  }

  build() {
    Column() {
      Text('Registration')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your name' })
        .onChange((value: string) => {
          this.name = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your email' })
        .onChange((value: string) => {
          this.email = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .margin({ bottom: 20 })

      Button('Submit')
        .onClick(() => {
          if (this.validateForm()) {
            this.successMessage = 'Registration successful!'
            this.name = ''
            this.email = ''
            this.password = ''
          }
        })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ bottom: 20 })
      }

      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(18)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct Component3DAnimationOnAppear {
  @State private scaleValue: number = 1.0;
  @State private rotation: number = 0;
  uiContext: UIContext | undefined = undefined;

  aboutToAppear() {
    this.uiContext = this.getUIContext?.();
    if (!this.uiContext) {
      console.info("no uiContext, animation failed");
      return;
    }
    this.uiContext.keyframeAnimateTo({ iterations: 1 }, [
      {
        duration: 800,
        event: () => {
          this.scaleValue = 1.5;
          this.rotation = 90;
        }
      },
      {
        duration: 500,
        event: () => {
          this.scaleValue = 1;
          this.rotation = 0;
        }
      }
    ]);
    console.log('Component3D has appeared and animation started');
  }

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(100)
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

