@Entry
@Component
struct LoginForm {
  @State username: string = ''
  @State password: string = ''
  @State showDialog: boolean = false

  validateCredentials(): boolean {
    return this.username === 'admin' && this.password === 'password123'
  }

  build() {
    Column() {
      // Username Label and Input
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your username' })
        .onChange((value: string) => {
          this.username = value
        })
        .width('80%')
        .height(40)
        .margin({ bottom: 20 })
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })

      // Password Label and Input
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .height(40)
        .margin({ bottom: 20 })
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })

      // Login Button
      Button('Login')
        .onClick(() => {
          if (this.username && this.password) {
            this.showDialog = true
          } else {
            AlertDialog.show({
              title: 'Error',
              message: 'Please fill in all fields',
              confirm: {
                value: 'OK',
                action: () => {}
              }
            })
          }
        })
        .width('80%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#4CAF50')
        .fontColor(Color.White)

      // Dialog
      if (this.showDialog) {
        Column() {
          Text(this.validateCredentials() ? 'Login Successful' : 'Login Failed')
            .fontSize(20)
            .margin({ bottom: 20 })
            .fontColor(this.validateCredentials() ? Color.Green : Color.Red)

          Text(`Username: ${this.username}`)
            .fontSize(16)
            .margin({ bottom: 12 })

          Text(`Password: ${this.password}`)
            .fontSize(16)
            .margin({ bottom: 20 })

          Button('Close')
            .onClick(() => {
              this.showDialog = false
            })
            .width('60%')
            .height(40)
            .fontSize(16)
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
  }
}

