import { AnimatorOptions } from '@ohos.animator';

@Entry
@Component
struct GesturePriorityManagement {
  @State private message: string = "Gesture Priority Management";
  @State private offsetX: number = 0;
  @State private offsetY: number = 0;
  @State private tapCount: number = 0;
  @State private priorityMessage: string = "Tap or Pan the box";

  build() {
    Column() {
      Text(this.message)
        .fontSize(20)
        .margin({ bottom: 20 });

      Text(`Tap Count: ${this.tapCount}`)
        .fontSize(18)
        .margin({ bottom: 10 });

      Text(`Message: ${this.priorityMessage}`)
        .fontSize(18)
        .margin({ bottom: 20 });

      Row()
        .width(150)
        .height(150)
        .backgroundColor(Color.Green)
        .borderRadius(10)
        .gesture(
          GestureGroup(
            GestureMode.Exclusive,
            TapGesture()
              .onAction(() => {
                this.tapCount += 1;
                this.priorityMessage = "Tap Gesture Detected";
              }),
            PanGesture({ direction: PanDirection.All })
              .onActionUpdate((event: GestureEvent) => {
                this.offsetX = event.offsetX;
                this.offsetY = event.offsetY;
                this.priorityMessage = `Pan Gesture Update: X: ${this.offsetX}, Y: ${this.offsetY}`;
              })
              .onActionEnd(() => {
                this.priorityMessage = "Pan Gesture Ended";
                const animationOptions: AnimatorOptions = {
                  duration: 300,
                  easing: 'ease-in-out',
                  delay: 0,
                  fill: 'forwards',
                  direction: 'normal',
                  iterations: 1,
                  begin: 0,
                  end: 1
                };
                animateTo(animationOptions, () => {
                  this.offsetX = 0;
                  this.offsetY = 0;
                });
              })
          )
        )
        .transform({ translate: { x: this.offsetX, y: this.offsetY } })
        .animation({ duration: 300 });

      Flex({ justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
        Text('High Priority Tap')
          .fontSize(18)
          .padding(20)
          .backgroundColor(Color.Blue)
          .borderRadius(10)
          .gesture(
            TapGesture()
              .onAction(() => {
                this.tapCount += 1;
                this.priorityMessage = "High Priority Tap Detected";
              })
          );
      }
      .width('80%')
      .height(150)
      .backgroundColor(Color.Gray)
      .borderRadius(10)
      .margin(10);

      Flex({ justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
        Text('Low Priority Tap')
          .fontSize(18)
          .padding(20)
          .backgroundColor(Color.Green)
          .borderRadius(10)
          .gesture(
            TapGesture()
              .onAction(() => {
                this.tapCount += 1;
                this.priorityMessage = "Low Priority Tap Detected";
              })
          );
      }
      .width('80%')
      .height(150)
      .backgroundColor(Color.Gray)
      .borderRadius(10)
      .margin(10);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(Color.White);
  }
}

import { image } from '@kit.ImageKit';
import { AnimatedDrawableDescriptor, AnimationOptions } from '@ohos.arkui.drawableDescriptor';

@Entry
@Component
struct SheetAnimationExample {
  pixelmaps: Array<image.PixelMap> = [];
  options: AnimationOptions = { duration: 2000, iterations: 1 };
  @State animated: AnimatedDrawableDescriptor | undefined = undefined;

  async aboutToAppear() {
    this.pixelmaps = await this.getPixelMaps();
    this.animated = new AnimatedDrawableDescriptor(this.pixelmaps, this.options);
  }

  build() {
    Column() {
      Row() {
        Image(this.animated)
          .width('500px')
          .height('500px')
          .onFinish(() => {
            console.info("Animation finished");
          })
      }.height('50%')
      Row() {
        Button('Play Once')
          .width(100)
          .padding(5)
          .onClick(() => {
            this.options = { duration: 2000, iterations: 1 };
            this.animated = new AnimatedDrawableDescriptor(this.pixelmaps, this.options);
          })
          .margin(5)
        Button('Play Infinite')
          .width(100)
          .padding(5)
          .onClick(() => {
            this.options = { duration: 2000, iterations: -1 };
            this.animated = new AnimatedDrawableDescriptor(this.pixelmaps, this.options);
          })
          .margin(5)
      }
    }.width('50%')
  }

  private async getPixmapListFromMedia(resource: Resource) {
    let unit8Array = await getContext(this)?.resourceManager?.getMediaContent({
      bundleName: resource.bundleName,
      moduleName: resource.moduleName,
      id: resource.id
    });
    let imageSource = image.createImageSource(unit8Array.buffer.slice(0, unit8Array.buffer.byteLength));
    let createPixelMap: Array<image.PixelMap> = await imageSource.createPixelMapList({
      desiredPixelFormat: image.PixelMapFormat.RGBA_8888
    });
    await imageSource.release();
    return createPixelMap;
  }

  private async getPixmapFromMedia(resource: Resource) {
    let unit8Array = await getContext(this)?.resourceManager?.getMediaContent({
      bundleName: resource.bundleName,
      moduleName: resource.moduleName,
      id: resource.id
    });
    let imageSource = image.createImageSource(unit8Array.buffer.slice(0, unit8Array.buffer.byteLength));
    let createPixelMap: image.PixelMap = await imageSource.createPixelMap({
      desiredPixelFormat: image.PixelMapFormat.RGBA_8888
    });
    await imageSource.release();
    return createPixelMap;
  }

  private async getPixelMaps() {
    let Mypixelmaps: Array<image.PixelMap> = await this.getPixmapListFromMedia($r('app.media.app_icon'));
    Mypixelmaps.push(await this.getPixmapFromMedia($r('app.media.app_icon')));
    return Mypixelmaps;
  }
}

