struct NavigationDrawerApp {
  @State isDrawerOpen: boolean = false;
  @State currentPage: number = 0;

  build() {
    Column() {
      // Main Content Area
      Column() {
        if (this.currentPage === 0) {
          this.HomeScreen();
        } else if (this.currentPage === 1) {
          this.AboutScreen();
        } else {
          this.ContactScreen();
        }
      }
      .layoutWeight(1);

      // Drawer Toggle Button
      Button('Toggle Drawer')
        .onClick(() => {
          this.isDrawerOpen = !this.isDrawerOpen;
        })
        .padding(10);

      // Navigation Drawer
      if (this.isDrawerOpen) {
        Column() {
          this.NavOption('Home', 0);
          this.NavOption('About', 1);
          this.NavOption('Contact', 2);
        }
        .backgroundColor('#FFFFFF')
        .padding(10)
        .width(200)
        .height('100%')
        .position({ x: 0, y: 0 });
      }
    }
    .height('100%');
  }

  @Builder NavOption(label: string, page: number) {
    Button(label)
      .onClick(() => {
        this.currentPage = page;
        this.isDrawerOpen = false;
      })
      .padding(10)
      .width('100%')
      .backgroundColor(this.currentPage === page ? '#D3D3D3' : Color.Transparent);
  }

  @Builder HomeScreen() {
    Column() {
      Text('Home Screen')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .padding(16);
    }
    .width('100%')
    .height('100%');
  }

  @Builder AboutScreen() {
    Column() {
      Text('About Screen')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .padding(16);
    }
    .width('100%')
    .height('100%');
  }

  @Builder ContactScreen() {
    Column() {
      Text('Contact Screen')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .padding(16);
    }
    .width('100%')
    .height('100%');
  }
}

