@Entry
@Component
struct CityDropdownApp {
  private cities: Array<City> = [
    { id: 1, name: 'New York' },
    { id: 2, name: 'Los Angeles' },
    { id: 3, name: 'Chicago' },
    { id: 4, name: 'Houston' }
  ];

  @State selectedCity: City | null = null;
  @State isDropdownOpen: boolean = false;

  build() {
    Column() {
      Button(this.selectedCity ? this.selectedCity.name : 'Select a City')
        .onClick(() => {
          this.isDropdownOpen = !this.isDropdownOpen;
        })
        .width('80%')
        .height(50)
        .backgroundColor('#f0f0f0')
        .borderRadius(5)
        .margin({ top: 20, bottom: 10 });

      if (this.isDropdownOpen) {
        List() {
          ForEach(this.cities, (city: City) => {
            ListItem() {
              Row() {
                Image($r('app.media.app_icon'))
                  .width(24)
                  .height(24)
                  .margin({ right: 10 });
                Text(city.name)
                  .fontSize(18);
              }
              .onClick(() => {
                this.selectedCity = city;
                this.isDropdownOpen = false;
              });
            }
            .backgroundColor('#FFFFFF')
            .borderRadius(5)
            .margin({ bottom: 5 });
          });
        }
        .width('80%')
        .backgroundColor('#FFFFFF')
        .borderRadius(5)
        .margin({ bottom: 20 });
      }

      if (this.selectedCity) {
        Text(`Selected City: ${this.selectedCity.name}`)
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

interface City {
  id: number;
  name: string;
}

