@Entry
@Component
struct ImageGridGallery {
  @State selectedImage: Resource = $r('app.media.app_icon')
  @State showFullScreen: boolean = false

  private images: Resource[] = [
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon')
  ]

  build() {
    Column() {
      if (this.showFullScreen) {
        Stack() {
          Image(this.selectedImage)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%')

          Button('Close')
            .onClick(() => {
              this.showFullScreen = false
            })
            .position({ x: 20, y: 20 })
            .backgroundColor('#FFFFFF')
            .padding({ left: 10, right: 10, top: 5, bottom: 5 })
            .borderRadius(5)
        }
      } else {
        Scroll() {
          Grid() {
            ForEach(this.images, (image: Resource) => {
              GridItem() {
                Image(image)
                  .width('100%')
                  .aspectRatio(1)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(5)
                  .onClick(() => {
                    this.selectedImage = image
                    this.showFullScreen = true
                  })
              }
            })
          }
          .columnsTemplate('1fr 1fr 1fr')
          .rowsGap(10)
          .columnsGap(10)
          .padding(10)
        }
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

@Entry
@Component
struct EventHandlingDemo {
  @State private buttonText: string = "Click Me";
  @State private tapText: string = "Tap Me";
  @State private swipeText: string = "Swipe Me";
  @State private inputValue: string = '';

  private handleButtonClick() {
    this.buttonText = "Button Clicked!";
    console.log("Button click event handled");
  }

  private handleTap() {
    this.tapText = "Tap Detected!";
    console.log("Tap event handled");
  }

  private handleSwipe() {
    this.swipeText = "Swipe Detected!";
    console.log("Swipe event handled");
  }

  private handleInputChange(value: string) {
    this.inputValue = value;
    console.log("Input changed:", value);
  }

  build() {
    Column({ space: 20 }) {
      Button(this.buttonText)
        .onClick(() => {
          this.handleButtonClick();
        })
        .width(200)
        .height(50)
        .backgroundColor(Color.Blue)
        .fontColor(Color.White)
        .margin({ top: 20 });

      Text(this.tapText)
        .fontSize(18)
        .padding(20)
        .backgroundColor(0xeeeeee)
        .borderRadius(10)
        .gesture(
          TapGesture({ count: 1 })
            .onAction(() => {
              this.handleTap();
            })
        )
        .margin({ top: 20 });

      Text(this.swipeText)
        .fontSize(18)
        .padding(20)
        .backgroundColor(0xeeeeee)
        .borderRadius(10)
        .gesture(
          SwipeGesture({ direction: SwipeDirection.Horizontal })
            .onAction(() => {
              this.handleSwipe();
            })
        )
        .margin({ top: 20 });

      TextInput({ placeholder: 'Type here', text: this.inputValue })
        .onChange((value: string) => {
          this.handleInputChange(value);
        })
        .width('80%')
        .height(50)
        .margin({ top: 20 });

      Text('Input Text: ' + this.inputValue)
        .fontSize(16)
        .margin({ top: 10 });

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 20 })
        .onClick(() => {
          console.log("Image clicked");
        });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(0xf5f5f5)
  }
}

@Entry
@Component
struct GraphSwipeRefreshExample {
  @State isRefreshing: boolean = false
  @State graphData: number[] = [30, 50, 70, 90, 110]

  build() {
    Column() {
      // Graph component (simulated with a bar chart)
      Row({ space: 10 }) {
        ForEach(this.graphData, (value: number, index: number) => {
          Column() {
            Text(value.toString())
              .fontSize(14)
              .margin(2)
            Column()
              .width(20)
              .height(value)
              .backgroundColor(Color.Blue)
          }
          .margin(5)
        })
      }
      .width('100%')
      .height(200)
      .justifyContent(FlexAlign.Center)

      // Refresh component
      Refresh({ refreshing: this.isRefreshing }) {
        Text('Pull down to refresh graph data')
          .fontSize(18)
          .margin(10)
      }
      .onRefreshing(() => {
        this.isRefreshing = true
        // Simulate data refresh with a 2-second delay
        setTimeout(() => {
          this.graphData = this.generateRandomGraphData()
          this.isRefreshing = false
        }, 2000)
      })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }

  private generateRandomGraphData(): number[] {
    const data: number[] = []
    for (let i = 0; i < 5; i++) {
      data.push(Math.floor(Math.random() * 150) + 10)
    }
    return data
  }
}

