        this.ScreenContent();
        this.DrawerButton();
      }
      .layoutWeight(1);

      // Drawer Panel
      Panel(this.isDrawerOpen) {
        Column() {
          this.NavItem('Home', 0);
          this.NavItem('Profile', 1);
          this.NavItem('Settings', 2);
        }
        .width('80%')
        .height('100%')
        .backgroundColor(Color.White);
