@Entry
@Component
struct CalculatorApp {
  @State input1: number = 0
  @State input2: number = 0
  @State sumResult: number = 0

  build() {
    Column() {
      TextInput({ placeholder: 'Enter first number' })
        .onChange((value: string) => {
          this.input1 = parseFloat(value)
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter second number' })
        .onChange((value: string) => {
          this.input2 = parseFloat(value)
        })
        .margin({ bottom: 20 })

      Button('Calculate Sum')
        .onClick(() => {
          this.sumResult = this.input1 + this.input2
        })
        .margin({ bottom: 20 })

      Text(`Sum: ${this.sumResult}`)
        .fontSize(24)
        .margin({ top: 20 })
    }
    .padding(20)
