@Entry
@Component
struct TaskManagerApp {
    @State tasks: Array<Task> = []
    @State newTaskName: string = ''
    @State newTaskDueDate: string = ''

    build() {
        Column() {
            // Input for task name
            TextInput({ placeholder: 'Enter task name', text: this.newTaskName })
                .onChange((value: string) => {
                    this.newTaskName = value
                })
                .margin({ bottom: 10 })

            // Input for task due date
            TextInput({ placeholder: 'Enter due date (YYYY-MM-DD)', text: this.newTaskDueDate })
                .onChange((value: string) => {
                    this.newTaskDueDate = value
                })
                .margin({ bottom: 20 })

            // Button to add a new task
            Button('Add Task')
                .onClick(() => {
                    if (this.newTaskName && this.newTaskDueDate) {
                        const newTask: Task = {
                            id: Date.now(),
                            name: this.newTaskName,
                            dueDate: this.newTaskDueDate
                        }
                        this.tasks.push(newTask)
                        this.newTaskName = ''
                        this.newTaskDueDate = ''
                    }
                })
                .margin({ bottom: 20 })

            // List of tasks
            List() {
                ForEach(this.tasks, (task: Task) => {
                    ListItem() {
                        Row() {
                            Column() {
                                Text(task.name)
                                    .fontSize(18)
                                    .fontWeight(FontWeight.Bold)
                                Text(`Due: ${task.dueDate}`)
                                    .fontSize(14)
                                    .fontColor(Color.Gray)
                            }
                            .margin({ right: 10 })

                            Button() {
                                Image($r('app.media.app_icon'))
                                    .width(20)
                                    .fillColor(Color.Red)
                            }
                            .onClick(() => {
                                this.tasks.splice(this.tasks.indexOf(task), 1)
                            })
                        }
                        .padding(10)
                        .borderRadius(5)
                        .backgroundColor(Color.White)
                        .margin({ top: 10 })
                    }
                })
            }
            .layoutWeight(1)
        }
        .padding(20)
        .backgroundColor('#F5F5F5')
    }
}

interface Task {
    id: number;
    name: string;
    dueDate: string;
}

@Entry
@Component
struct TodoList {
  @State tasks: Array<Task> = []
  @State newTask: string = ''

  build() {
    Column() {
      TextInput({ placeholder: 'Enter task title', text: this.newTask })
        .onChange((value: string) => {
          this.newTask = value
        })
        .margin({ bottom: 20 })

      Button('Add Task')
        .onClick(() => {
          if (this.newTask) {
            this.tasks.push({ id: Date.now(), title: this.newTask, isCompleted: false })
            this.newTask = ''
          }
        })
        .margin({ bottom: 20 })

      ForEach(this.tasks, (task: Task, index: number) => {
        Row() {
          Checkbox()
            .select(task.isCompleted)
            .onChange((value: boolean) => {
              this.tasks[index].isCompleted = value
            })
            .margin({ right: 10 })

          Text(task.title)
            .fontSize(18)
            .decoration({ type: task.isCompleted ? TextDecorationType.LineThrough : TextDecorationType.None })

          Button() {
            Image($r('app.media.app_icon'))
              .width(20)
              .height(20)
          }
          .onClick(() => {
            this.tasks.splice(index, 1)
          })
          .margin({ left: 10 })
        }
        .padding(10)
        .borderRadius(5)
        .backgroundColor(Color.White)
        .margin({ top: 10 })
      })
    }
    .padding(20)
    .backgroundColor('#F5F5F5')
  }
}

interface Task {
  id: number
  title: string
  isCompleted: boolean
}

