    Stack() {
      Text()
        .width(300)
        .height(300)
        .backgroundColor(Color.Black)
      Particle({
        particles: [
          {
            emitter: {
              particle: {
                type: ParticleType.POINT,
                config: {
                  radius: 5
                },
                count: 200,
                lifetime: 5000,
                lifetimeRange: 500
              },
              emitRate: 5,
              position: [0, 0],
              shape: ParticleEmitterShape.CIRCLE
            },
            color: {
              range: [Color.Red, Color.Blue],
              updater: {
                type: ParticleUpdater.CURVE,
                config: [
                  {
                    from: Color.Red,
                    to: Color.Blue,
                    startMillis: 0,
                    endMillis: 2500,
                    curve: Curve.EaseIn
                  },
                  {
                    from: Color.Blue,
                    to: Color.Green,
                    startMillis: 2500,
                    endMillis: 5000,
                    curve: Curve.EaseIn
                  }
                ]
              }
            },
            opacity: {
              range: [0.0, 1.0],
              updater: {
                type: ParticleUpdater.CURVE,
                config: [
                  {
                    from: 0.0,
                    to: 1.0,
                    startMillis: 0,
                    endMillis: 1000,
                    curve: Curve.EaseIn
                  },
                  {
                    from: 1.0,
                    to: 0.0,
                    startMillis: 4000,
                    endMillis: 5000,
                    curve: Curve.EaseIn
                  }
                ]
              }
            },
            scale: {
              range: [0.0, 0.0],
              updater: {
                type: ParticleUpdater.CURVE,
                config: [
                  {
                    from: 0.0,
                    to: 0.3,
                    startMillis: 0,
                    endMillis: 2000,
                    curve: Curve.EaseIn
                  }
                ]
              }
            },
            acceleration: {
              speed: {
                range: [2, 6],
                updater: {
                  type: ParticleUpdater.RANDOM,
                  config: [1, 10]
                }
              },
              angle: {
                range: [0, 360]
              }
            }
          }
        ]
      })
        .width(300)
        .height(300)
    }
    .width("100%")
    .height("100%")
    .align(Alignment.Center)
  }
