@Entry
@Component
struct SearchFilterApp {
  @State items: string[] = [
    'Apple',
    'Banana',
    'Orange',
    'Grapes',
    'Mango',
    'Pineapple',
    'Strawberry',
    'Watermelon',
    'Cherry',
    'Blueberry',
    'Lemon',
    'Peach'
  ];

  @State searchText: string = '';

  filteredItems(): string[] {
    if (this.searchText.trim() === '') {
      return this.items;
    } else {
      return this.items.filter(item =>
        item.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  build() {
    Column() {
      TextInput({
        placeholder: 'Search items...',
        text: this.searchText
      })
        .width('100%')
        .onChange((value: string) => {
          this.searchText = value;
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      if (this.filteredItems().length > 0) {
        List() {
          ForEach(this.filteredItems(), (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(18)
                .padding(12);
            }
          }, (item: string) => item);
        }
      } else {
        Text('No items found')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

@Entry
@Component
struct ThemeBasedTextInput {
  @State private inputState: string = "normal";
  @State private textValue: string = "";

  build() {
    Column() {
      Row() {
        Column() {
          TextInput({ text: this.textValue, placeholder: "Enter text" })
            .onChange((value: string) => {
              this.textValue = value;
              this.inputState = value.length > 0 ? "typing" : "normal";
            })
            .underlineColor({
              normal: Color.Blue,
              typing: Color.Green,
              error: Color.Red
            })
            .width("80%")
            .padding(10)
            .enabled(this.inputState !== "disabled")
            .onAppear(() => {
              this.inputState = "normal";
            })
        }
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center)
        .width("100%")
        .height("100%")
      }
    }
    .width("100%")
    .height("100%")
  }
}

