  build() {
    Column() {
      // Content Area
      Column() {
        if (this.currentIndex === 0) {
          this.HomeTab()
        } else if (this.currentIndex === 1) {
          this.CategoriesTab()
        } else if (this.currentIndex === 2) {
          this.SearchTab()
        } else {
          this.ProfileTab()
        }
      }
      .width('100%')
      .layoutWeight(1)

      // Bottom Navigation Bar
      Row() {
        // Home Tab
        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Home')
            .fontSize(12)
            .fontColor(this.currentIndex === 0 ? '#1698CE' : '#666666')
        }
        .width('25%')
        .onClick(() => {
          this.currentIndex = 0
        })

        // Categories Tab
        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Categories')
            .fontSize(12)
            .fontColor(this.currentIndex === 1 ? '#1698CE' : '#666666')
        }
        .width('25%')
        .onClick(() => {
          this.currentIndex = 1
        })

        // Search Tab
        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Search')
            .fontSize(12)
            .fontColor(this.currentIndex === 2 ? '#1698CE' : '#666666')
        }
        .width('25%')
        .onClick(() => {
          this.currentIndex = 2
        })

        // Profile Tab
        Column() {
          Image($r('app.media.app_icon'))
            .width(24)
            .height(24)
            .margin({ bottom: 4 })
          Text('Profile')
            .fontSize(12)
            .fontColor(this.currentIndex === 3 ? '#1698CE' : '#666666')
        }
        .width('25%')
        .onClick(() => {
          this.currentIndex = 3
        })
      }
      .width('100%')
      .height(60)
      .backgroundColor(Color.White)
      .border({ width: { top: 0.5 }, color: '#cccccc' })
    }
  }

  @Builder HomeTab() {
    Column() {
      Text('Home Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }

  @Builder CategoriesTab() {
    Column() {
      Text('Categories Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }

  @Builder SearchTab() {
    Column() {
      Text('Search Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }

  @Builder ProfileTab() {
    Column() {
      Text('Profile Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }
}

@Entry
@Component
struct UserForm {
  @State username: string = '';
  @State selectedCountry: string = '';
  @State showMessage: boolean = false;

  private countries: string[] = ['USA', 'Canada', 'UK', 'Australia', 'Germany', 'France', 'India'];

  build() {
    Column() {
      // Username Input
      TextInput({ placeholder: 'Enter your username' })
        .width('100%')
        .height(40)
        .margin({ bottom: 20 })
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .onChange((value: string) => {
          this.username = value;
        });

      // Country Select Dropdown
      Text('Select your country:')
        .fontSize(16)
        .margin({ bottom: 10 });

      Flex({ direction: FlexDirection.Column, justifyContent: FlexAlign.Start }) {
        ForEach(this.countries, (country: string, index: number) => {
          Button(country)
            .width('100%')
            .height(40)
            .margin({ bottom: 10 })
            .backgroundColor('#f5f5f5')
            .onClick(() => {
              this.selectedCountry = country;
            });
        });
      }
      .width('100%')
      .margin({ bottom: 20 });

      // Submit Button
      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.username && this.selectedCountry) {
            this.showMessage = true;
          }
        });

      // Display Message
      if (this.showMessage) {
        Column() {
          Text(`Hello, ${this.username}!`)
            .fontSize(24)
            .margin({ bottom: 10 });

          Text(`Your selected country is: ${this.selectedCountry}`)
            .fontSize(18)
            .margin({ bottom: 10 });
        }
        .padding(20)
        .backgroundColor('#F5F5F5')
        .borderRadius(12)
        .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

