@Entry
@Component
struct Component3DRenderingControl {
  @State shouldRender: boolean = true;
  @State conditionMet: boolean = false;

  build() {
    Column() {
      if (this.shouldRender && !this.conditionMet) {
        Custom3DComponent()
          .onAppear(() => {
            if (this.checkCondition()) {
              this.conditionMet = true;
              this.shouldRender = false;
            }
          })
      }

      Button('Reset Condition')
        .onClick(() => {
          this.conditionMet = false;
          this.shouldRender = true;
        })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }

  checkCondition(): boolean {
    return Math.random() > 0.5;
  }
}

