@Entry
@Component
struct ParticleEmitterConfig {
  @State private emitRate: number = 10;
  @State private particleCount: number = 500;
  @State private lifetime: number = 10000;
  @State private shape: string = "RECTANGLE";

  build() {
    Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Center, justifyContent: FlexAlign.Center }) {
      Text('Particle Emitter Configuration').fontSize(20).fontColor(0x000000).margin({ bottom: 20 })

      Slider({
        value: this.emitRate,
        min: 1,
        max: 50,
        style: SliderStyle.OutSet
      })
      .width('80%')
      .blockColor(0x009688)
      .trackColor(0xD8D8D8)
      .selectedColor(0x009688)
      .showSteps(true)
      .onChange((value: number) => {
        this.emitRate = value;
      })
      Text(`Emit Rate: ${this.emitRate.toFixed(0)} particles/sec`).fontSize(16).margin({ top: 10 })

      Slider({
        value: this.particleCount,
        min: 100,
        max: 1000,
        style: SliderStyle.OutSet
      })
      .width('80%')
      .blockColor(0x009688)
      .trackColor(0xD8D8D8)
      .selectedColor(0x009688)
      .showSteps(true)
      .onChange((value: number) => {
        this.particleCount = value;
      })
      Text(`Particle Count: ${this.particleCount.toFixed(0)}`).fontSize(16).margin({ top: 10 })

      Slider({
        value: this.lifetime,
        min: 1000,
        max: 20000,
        style: SliderStyle.OutSet
      })
      .width('80%')
      .blockColor(0x009688)
      .trackColor(0xD8D8D8)
      .selectedColor(0x009688)
      .showSteps(true)
      .onChange((value: number) => {
        this.lifetime = value;
      })
      Text(`Lifetime: ${this.lifetime.toFixed(0)} ms`).fontSize(16).margin({ top: 10 })

      Toggle({
        type: ToggleType.Checkbox,
        isOn: this.shape === "CIRCLE"
      })
      .onChange((isOn: boolean) => {
        this.shape = isOn ? "CIRCLE" : "RECTANGLE";
      })
      Text(`Shape: ${this.shape === "RECTANGLE" ? 'Rectangle' : 'Circle'}`).fontSize(16).margin({ top: 10 })

      Button('Apply Configuration', { type: ButtonType.Normal, stateEffect: true })
      .backgroundColor(0x4F4F4F)
      .borderRadius(4)
      .width(200)
      .margin({ top: 20 })
      .onClick(() => {
        console.log(`Emit Rate: ${this.emitRate}`);
        console.log(`Particle Count: ${this.particleCount}`);
        console.log(`Lifetime: ${this.lifetime}`);
        console.log(`Shape: ${this.shape === "RECTANGLE" ? 'Rectangle' : 'Circle'}`);
      })
    }
  }
}

