  @State password: string = ''
  @State loginMessage: string = ''
  @State navigateToHome: boolean = false

  build() {
    Column() {
      Text('Email')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your email', text: this.email })
        .onChange((value: string) => {
          this.email = value
        })
        .width('80%')
