@Entry
@Component
struct MultiLevelSwipeRefresher {
  @State isRefreshingParent: boolean = false;
  @State isRefreshingChild: boolean = false;
  @State parentData: string[] = ['Parent Item 1', 'Parent Item 2', 'Parent Item 3'];
  @State childData: string[] = ['Child Item 1', 'Child Item 2', 'Child Item 3'];

  build() {
    Column() {
      Refresh({
        refreshing: this.isRefreshingParent,
        offset: 120,
        friction: 100
      }) {
        Column() {
          List() {
            ForEach(this.parentData, (item: string) => {
              ListItem() {
                Text(item)
                  .fontSize(18)
                  .padding(16)
                  .backgroundColor('#f0f0f0')
                  .width('100%')
              }
            })
          }
          .width('100%')

          Refresh({
            refreshing: this.isRefreshingChild,
            offset: 80,
            friction: 80
          }) {
            List() {
              ForEach(this.childData, (item: string) => {
                ListItem() {
                  Text(item)
                    .fontSize(16)
                    .padding(12)
                    .backgroundColor('#ffffff')
                    .width('100%')
                }
              })
            }
            .width('100%')
          }
          .onRefreshing(() => {
            this.isRefreshingChild = true;
            setTimeout(() => {
              this.childData = ['New Child Item 1', 'New Child Item 2', 'New Child Item 3'];
              this.isRefreshingChild = false;
            }, 2000);
          })
        }
        .width('100%')
      }
      .onRefreshing(() => {
        this.isRefreshingParent = true;
        setTimeout(() => {
          this.parentData = ['New Parent Item 1', 'New Parent Item 2', 'New Parent Item 3'];
          this.isRefreshingParent = false;
        }, 2000);
      })
    }
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct ParticleColorTransitionConfig {
  @State color1: string = '#FF0000'; // Red
  @State color2: string = '#00FF00'; // Green
  @State color3: string = '#0000FF'; // Blue

  build() {
    Stack() {
      Text()
        .width(300).height(300).backgroundColor(Color.Black)
      Particle({particles:[
        {
          emitter:{
            particle:{
              type:ParticleType.POINT,
              config:{
                radius:10
              },
              count: 500,
              lifetime:10000,
              lifetimeRange:100
            },
            emitRate:10,
            position:[0,0],
            shape:ParticleEmitterShape.RECTANGLE
          },
          color:{
            range:[Color.Red,Color.Yellow],
            updater:{
              type:ParticleUpdater.CURVE,
              config:[
                {
                  from:Color.White,
                  to:Color.Pink,
                  startMillis:0,
                  endMillis:3000,
                  curve:Curve.EaseIn
                },
                {
                  from:Color.Pink,
                  to:Color.Orange,
                  startMillis:3000,
                  endMillis:5000,
                  curve:Curve.EaseIn
                },
                {
                  from:Color.Orange,
                  to:Color.Pink,
                  startMillis:5000,
                  endMillis:8000,
                  curve:Curve.EaseIn
                },
              ]
            }
          },
          opacity:{
            range:[0.0,1.0],
            updater:{
              type:ParticleUpdater.CURVE,
              config:[
                {
                  from:0.0,
                  to:1.0,
                  startMillis:0,
                  endMillis:3000,
                  curve:Curve.EaseIn
                },
                {
                  from:1.0,
                  to:0.0,
                  startMillis:5000,
                  endMillis:10000,
                  curve:Curve.EaseIn
                }
              ]
            }
          },
          scale:{
            range:[0.0,0.0],
            updater:{
              type:ParticleUpdater.CURVE,
              config:[
                {
                  from:0.0,
                  to:0.5,
                  startMillis:0,
                  endMillis:3000,
                  curve: Curve.EaseIn
                }
              ]
            }
          },
          acceleration:{
            speed:{
              range:[3,9],
              updater:{
                type:ParticleUpdater.RANDOM,
                config:[1,20]
              }
            },
            angle:{
              range:[90,90]
            }
          }
        }
      ]}).width(300).height(300)
    }.width("100%").height("100%").align(Alignment.Center)
  }
}

