      cancel: () => this.onCancel(),
      confirm: () => this.onConfirm(),
      controller: undefined
    }),
    alignment: DialogAlignment.Center,
    autoCancel: true,
    onWillDismiss: (dismissDialogAction: DismissDialogAction) => {
      if (dismissDialogAction.reason === DismissReason.PRESS_BACK) {
        console.info('Dialog dismissed by back press');
      } else if (dismissDialogAction.reason === DismissReason.TOUCH_OUTSIDE) {
        console.info('Dialog dismissed by touch outside');
      }
    },
    cornerRadius: 10,
  });

  onCancel(): void {
    console.info('Dialog was canceled');
  }

  onConfirm(): void {
    console.info('Dialog was confirmed');
  }

  build() {
    Column({ space: 20 }) {
      Button('Show Dialog')
        .onClick(() => {
          this.dialogController.open();
        })
        .width('50%')
        .height('10%')
