@Entry
@Component
struct TaskManagementApp {
  @State tasks: Array<Task> = []
  @State newTaskName: string = ''
  @State newTaskDeadline: string = ''

  private generateTaskId(): number {
    return Date.now()
  }

  private addTask() {
    if (this.newTaskName.trim() && this.newTaskDeadline.trim()) {
      this.tasks.push({
        id: this.generateTaskId(),
        name: this.newTaskName,
        deadline: this.newTaskDeadline,
        completed: false
      })
      this.newTaskName = ''
      this.newTaskDeadline = ''
    }
  }

  private toggleTaskCompletion(taskId: number) {
    const taskIndex = this.tasks.findIndex(task => task.id === taskId)
    if (taskIndex !== -1) {
      this.tasks[taskIndex].completed = !this.tasks[taskIndex].completed
    }
  }

  build() {
    Column() {
      Text('Task Management')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Task Name', text: this.newTaskName })
        .onChange((value: string) => { this.newTaskName = value })
        .width('90%')
        .height(50)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Deadline (YYYY-MM-DD)', text: this.newTaskDeadline })
        .onChange((value: string) => { this.newTaskDeadline = value })
        .width('90%')
        .height(50)
        .margin({ bottom: 20 })

      Button('Add Task')
        .onClick(() => { this.addTask() })
        .width('90%')
        .height(50)
        .margin({ bottom: 20 })

      List() {
        ForEach(this.tasks, (task: Task) => {
          ListItem() {
            Row() {
              Column() {
                Text(task.name)
                  .fontSize(18)
                  .fontWeight(FontWeight.Bold)
                  .decoration({ type: task.completed ? TextDecorationType.LineThrough : TextDecorationType.None })
                Text(`Deadline: ${task.deadline}`)
                  .fontSize(14)
                  .fontColor(Color.Gray)
              }
              .layoutWeight(1)
              .padding(10)

              Checkbox()
                .select(task.completed)
                .onChange((checked: boolean) => { this.toggleTaskCompletion(task.id) })
                .margin({ right: 10 })
            }
            .padding(10)
            .backgroundColor('#F5F5F5')
            .borderRadius(5)
            .margin({ bottom: 10 })
          }
        })
      }
      .width('90%')
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
  }
}

interface Task {
  id: number
  name: string
  deadline: string
  completed: boolean
}

