@Entry
@Component
struct GestureConflictResolution {
  @State private message: string = "Perform Gestures Here"
  @State private tapDetected: boolean = false
  @State private swipeDetected: boolean = false

  build() {
    Column({ space: 20 }) {
      Text(this.message)
        .fontSize(20)
        .textAlign(TextAlign.Center)
        .margin({ top: 20 })

      Flex({ justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
        Text("Interact Here")
          .fontSize(18)
          .padding(20)
          .backgroundColor(0xeeeeee)
          .borderRadius(10)
          .gesture(
            GestureGroup(
              GestureMode.Exclusive,
              TapGesture({ count: 1 })
                .onAction(() => {
                  this.tapDetected = true
                  this.swipeDetected = false
                  this.message = "Tap Detected"
                }),
              SwipeGesture({ direction: SwipeDirection.Horizontal })
                .onAction(() => {
                  this.swipeDetected = true
                  this.tapDetected = false
                  this.message = "Swipe Detected"
                })
            )
          )
      }

      if (this.tapDetected) {
        Image($r("app.media.app_icon"))
          .width(100)
          .height(100)
          .margin({ top: 20 })
      }

      if (this.swipeDetected) {
        Row()
          .width(200)
          .height(100)
          .backgroundColor(Color.Blue)
          .borderRadius(10)
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(0xf5f5f5)
  }
}

