        .width("80%")
        .height(50)
        .margin({ top: 20 })
        .onClick(() => {
          this.handleAction();
        })
        .enabled(this.isActionEnabled);

      // Display the input dynamically
      Text(`Current Input: ${this.inputText}`)
        .fontSize(16)
        .margin({ top: 20 })
        .width("80%")
        .textAlign(TextAlign.Center);
    }
