@Entry
@Component
struct ApiDataListApp {
  private items: Array<Item> = [];
  @State private isLoading: boolean = true;
  @State private error: string = '';

  aboutToAppear() {
    this.fetchData();
  }

  fetchData() {
    this.isLoading = true;
    this.error = '';

    setTimeout(() => {
      try {
        this.items = [
          new Item(1, 'Item 1', 'app.media.app_icon', 'Description for Item 1.'),
          new Item(2, 'Item 2', 'app.media.app_icon', 'Description for Item 2.'),
          new Item(3, 'Item 3', 'app.media.app_icon', 'Description for Item 3.')
        ];
      } catch (error) {
        this.error = 'Failed to fetch data';
      } finally {
        this.isLoading = false;
      }
    }, 2000);
  }

  build() {
    Column() {
      if (this.isLoading) {
        Text('Loading...')
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 });
      } else if (this.error) {
        Text(`Error: ${this.error}`)
          .fontSize(20)
          .fontColor(Color.Red)
          .margin({ top: 20 });
      } else {
        List() {
          ForEach(this.items, (item: Item) => {
            ListItem() {
              Row() {
                Image(item.image)
                  .width(80)
                  .height(80)
                  .borderRadius(8)
                  .objectFit(ImageFit.Cover)
                  .margin({ right: 16 });

                Column() {
                  Text(item.title)
                    .fontSize(18)
                    .fontWeight(FontWeight.Medium)
                    .margin({ bottom: 4 });

                  Text(item.description)
                    .fontSize(14)
                    .fontColor('#666666');
                }
                .layoutWeight(1)
                .alignItems(HorizontalAlign.Start);
              }
              .padding(16)
              .backgroundColor(Color.White)
              .borderRadius(12);
