@Entry
@Component
struct ConditionalPostRefresh {
  @State isRefreshing: boolean = false;
  @State contentLoaded: boolean = false;

  build() {
    Column() {
      if (this.isRefreshing) {
        LoadingProgress()
          .color('#106836')
          .size({ width: '100%' })
          .margin({ top: 20 });
      } else {
        if (this.contentLoaded) {
          Text('Content Loaded Successfully!')
            .fontSize(20)
            .fontColor(Color.Black)
            .margin({ top: 20 });
        } else {
          Text('Pull to Refresh to Load Content')
            .fontSize(20)
            .fontColor(Color.Gray)
            .margin({ top: 20 });
        }
      }

      Button(this.isRefreshing ? 'Refreshing...' : 'Refresh')
        .onClick(() => {
          this.isRefreshing = true;
          setTimeout(() => {
            this.isRefreshing = false;
            this.contentLoaded = true;
          }, 2000); // Simulate a 2-second refresh delay
        })
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

