@Entry
@Component
struct ConfigureAcceleration {
  @State private speed: number = 0;
  @State private acceleration: number = 0;
  @State private isAccelerating: boolean = false;
  private timerId: number = -1;

  startAcceleration() {
    this.isAccelerating = true;
    this.timerId = setInterval(() => {
      this.acceleration += 0.1;
      this.speed += this.acceleration;
      if (this.speed >= 100) {
        clearInterval(this.timerId);
        this.isAccelerating = false;
        this.speed = 100;
        this.acceleration = 0;
      }
    }, 100);
  }

  stopAcceleration() {
    clearInterval(this.timerId);
    this.isAccelerating = false;
    this.speed = 0;
    this.acceleration = 0;
  }

  build() {
    Column() {
      Text(`Speed: ${this.speed.toFixed(2)} km/h`)
        .fontSize(30)
        .margin(20);

      Text(`Acceleration: ${this.acceleration.toFixed(2)} m/s²`)
        .fontSize(20)
        .margin(10);

      Button(this.isAccelerating ? 'Stop' : 'Start')
        .onClick(() => {
          if (this.isAccelerating) {
            this.stopAcceleration();
          } else {
            this.startAcceleration();
          }
        })
        .margin(20);

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(20);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

