@Component
struct SpinAnimationEffect {
  @State rotation: number = 0

  aboutToAppear() {
    setInterval(() => {
      this.rotation = (this.rotation + 10) % 360
    }, 50)
  }

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })
