import promptAction from '@ohos.promptAction';

@Entry
@Component
struct RegistrationForm {
  @State userName: string = '';
  @State userEmail: string = '';
  @State showGreeting: boolean = false;

  build() {
    Column() {
      // Name Input
      Column() {
        Text('Enter your name:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Your Name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.userName = value.trim();
          });
      }

      // Email Input
      Column() {
        Text('Enter your email:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Your Email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.userEmail = value.trim();
          });
      }

      // Register Button
      Button('Register')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.userName && this.userEmail) {
            this.showGreeting = true;
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields'
            });
          }
        });

      // Personalized Greeting
      if (this.showGreeting) {
        Text(`Welcome, ${this.userName}! Your email is ${this.userEmail}.`)
          .fontSize(24)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

import promptAction from '@ohos.promptAction'

@Entry
@Component
struct VotingEligibilityApp {
  @State age: string = ''
  @State showMessage: boolean = false
  @State eligibilityMessage: string = ''

  build() {
    Column() {
      Text('Voting Eligibility Check')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 })

      Column() {
        Text('Age:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your age' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.age = value
          })
      }

      Button('Check Eligibility')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.age) {
            const ageNumber = parseInt(this.age)
            if (ageNumber >= 18) {
              this.eligibilityMessage = 'You are eligible to vote!'
            } else {
              this.eligibilityMessage = 'You are not eligible to vote yet.'
            }
            this.showMessage = true
          } else {
            promptAction.showToast({
              message: 'Please enter your age'
            })
          }
        })

      if (this.showMessage) {
        Text(this.eligibilityMessage)
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
  }
}

