@Entry
@Component
struct ProgressBarApp {
  @State linearProgress: number = 0;
  @State circularProgress: number = 0;

  build() {
    Column() {
      // Linear Progress Bar
      Progress({
        value: this.linearProgress,
        total: 100,
        type: ProgressType.Linear
      })
      .size({ width: "80%", height: 20 })
      .color(Color.Blue)
      .margin({ bottom: 40 })

      Button("Increase Linear Progress")
      .onClick(() => {
        if (this.linearProgress < 100) {
          this.linearProgress += 10;
        }
      })
      .margin({ bottom: 20 })

      Button("Reset Linear Progress")
      .onClick(() => {
        this.linearProgress = 0;
      })
      .margin({ bottom: 40 })

      // Circular Progress Bar
      Stack() {
        // Background circle
        Circle()
          .width(200)
          .height(200)
          .stroke('#E0E0E0')
          .strokeWidth(10)
          .fill('transparent')

        // Progress circle
        Circle()
          .width(200)
          .height(200)
          .stroke('#4CAF50')
          .strokeWidth(10)
          .fill('transparent')
          .strokeDashArray([Math.PI * 200, Math.PI * 200])
          .strokeDashOffset(Math.PI * 200 * (1 - this.circularProgress / 100))
          .rotate({ x: 0, y: 0, z: 1, angle: -90 })

        // Percentage text
        Text(`${Math.round(this.circularProgress)}%`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
      }
      .width(200)
      .height(200)
      .margin({ bottom: 40 })

      Button("Increase Circular Progress")
      .onClick(() => {
        if (this.circularProgress < 100) {
          this.circularProgress += 10;
        }
      })
      .margin({ bottom: 20 })

      Button("Reset Circular Progress")
      .onClick(() => {
        this.circularProgress = 0;
      })
    }
    .width("100%")
    .height("100%")
    .padding(20)
    .justifyContent(FlexAlign.Center)
    .backgroundColor("#ffffff")
  }
}

@Entry
@Component
struct QuoteCarousel {
  private swiperController: SwiperController = new SwiperController();

  private carouselItems: Array<CarouselItem> = [
    {
      id: 1,
      image: $r('app.media.app_icon'),
      title: 'Inspiration',
      quote: 'The only way to do great work is to love what you do.'
    },
    {
      id: 2,
      image: $r('app.media.app_icon'),
      title: 'Motivation',
      quote: 'Believe you can and you’re halfway there.'
    },
    {
      id: 3,
      image: $r('app.media.app_icon'),
      title: 'Wisdom',
      quote: 'The journey of a thousand miles begins with one step.'
    },
    {
      id: 4,
      image: $r('app.media.app_icon'),
      title: 'Success',
      quote: 'Success is not final, failure is not fatal: It is the courage to continue that counts.'
    }
  ];

  @State currentIndex: number = 0;

  build() {
    Column() {
      Text('Quote Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Column() {
        Swiper(this.swiperController) {
          ForEach(this.carouselItems, (item: CarouselItem) => {
            Stack() {
              Image(item.image)
                .width('100%')
                .height(300)
                .objectFit(ImageFit.Cover)
                .borderRadius(16);
            }
          });
        }
        .width('100%')
        .height(300)
        .margin({ bottom: 16 })
        .autoPlay(true)
        .interval(3000)
        .indicator(true)
        .loop(true)
        .duration(500)
        .onChange((index: number) => {
          this.currentIndex = index;
        });

