@Entry
@Component
struct ImageGalleryApp {
  @State selectedImage: string = '';
  @State showFullScreen: boolean = false;
  @State images: string[] = [];

  private uploadImage() {
    const newImage = 'app.media.app_icon';
    this.images.push(newImage);
  }

  private validateImage(image: string): boolean {
    return image.startsWith('app.media.app_icon');
  }

  build() {
    Column() {
      Button('Upload Image')
        .onClick(() => {
          this.uploadImage();
        })
        .margin(10)
        .padding(10)
        .backgroundColor('#007BFF')
        .fontColor(Color.White);

      if (this.showFullScreen) {
        Stack() {
          Image(this.selectedImage)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%');

          Button('Close')
            .onClick(() => {
              this.showFullScreen = false;
            })
            .position({ x: 20, y: 20 })
            .backgroundColor('#FFFFFF')
            .padding({ left: 10, right: 10, top: 5, bottom: 5 })
            .borderRadius(5);
        }
      } else {
        Grid() {
          ForEach(this.images, (image: string) => {
            if (this.validateImage(image)) {
              GridItem() {
                Image(image)
                  .width('100%')
                  .aspectRatio(1)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(5)
