@Component
struct GestureDependencyManagement {
  @State private tapCount: number = 0;
  @State private swipeCount: number = 0;
  @State private panX: number = 0;
  @State private panY: number = 0;
  @State private message: string = "Interact with the elements below";

  build() {
    Column({ space: 20 }) {
      Text(this.message)
        .fontSize(20)
        .textAlign(TextAlign.Center)
        .margin({ top: 20 });

      // TapGesture example
      Flex({ justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
        Text("Tap Me")
          .fontSize(18)
          .padding(20)
          .backgroundColor(0xeeeeee)
          .borderRadius(10)
          .gesture(
            TapGesture({ count: 1 })
              .onAction(() => {
                this.tapCount += 1;
                this.message = `Tap Count: ${this.tapCount}`;
              })
          );
      }

      // SwipeGesture example
      Flex({ justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
        Text("Swipe Me")
          .fontSize(18)
          .padding(20)
          .backgroundColor(0xeeeeee)
          .borderRadius(10)
          .gesture(
            SwipeGesture({ direction: SwipeDirection.Horizontal })
              .onAction(() => {
                this.swipeCount += 1;
                this.message = `Swipe Count: ${this.swipeCount}`;
              })
          );
      }

      // PanGesture example
      Flex({ justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
        Text("Pan Me")
          .fontSize(18)
          .padding(20)
          .backgroundColor(0xeeeeee)
          .borderRadius(10)
          .gesture(
            PanGesture({ direction: PanDirection.All })
              .onActionUpdate((event: GestureEvent) => {
                this.panX = event.offsetX;
                this.panY = event.offsetY;
                this.message = `Panning: X: ${this.panX}, Y: ${this.panY}`;
              })
              .onActionEnd(() => {
                animateTo({ duration: 300 }, () => {
                  this.panX = 0;
                  this.panY = 0;
                });
                this.message = "Interact with the elements below";
              })
          )
          .transform({ translate: { x: this.panX, y: this.panY } });
      }

      // Combined Gesture Dependency
      Flex({ justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
        Image($r("app.media.app_icon"))
          .width(100)
          .height(100)
          .gesture(
            GestureGroup(
              GestureMode.Parallel,
              TapGesture({ count: 1 })
                .onAction(() => {
                  this.tapCount += 1;
                  this.message = `Tap Count: ${this.tapCount}`;
                }),
              SwipeGesture({ direction: SwipeDirection.Horizontal })
                .onAction(() => {
                  this.swipeCount += 1;
                  this.message = `Swipe Count: ${this.swipeCount}`;
                }),
              PanGesture({ direction: PanDirection.All })
                .onActionUpdate((event: GestureEvent) => {
                  this.panX = event.offsetX;
                  this.panY = event.offsetY;
                  this.message = `Panning: X: ${this.panX}, Y: ${this.panY}`;
                })
                .onActionEnd(() => {
                  animateTo({ duration: 300 }, () => {
                    this.panX = 0;
                    this.panY = 0;
                  });
                  this.message = "Interact with the elements below";
                })
            )
          )
          .transform({ translate: { x: this.panX, y: this.panY } });
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(0xf5f5f5);
  }
}

