@Entry
@Component
struct AutoCancelConfigComponent {
  dialogController: CustomDialogController = new CustomDialogController({
    builder: AutoCancelConfigDialog({
      cancel: () => this.onCancel(),
      confirm: () => this.onConfirm()
    }),
    autoCancel: true
  });

  onCancel(): void {
    console.info('Configuration Canceled');
  }

  onConfirm(): void {
    console.info('Configuration Confirmed');
  }

  build() {
    Column() {
      Button('Configure Auto-Cancel')
        .onClick(() => {
          this.dialogController.open();
        })
    }
  }
}

@Component
struct AutoCancelConfigDialog {
  @Prop cancel: () => void;
  @Prop confirm: () => void;
  controller: CustomDialogController = new CustomDialogController({
    builder: this,
    autoCancel: true
  });

  build() {
    Column() {
      Text('Auto-Cancel Configuration')
      Row() {
        Button('Cancel')
          .onClick(() => {
            this.cancel();
            this.controller.close();
          })
        Button('Confirm')
          .onClick(() => {
            this.confirm();
            this.controller.close();
          })
      }
    }
    .padding(20)
  }
}

