@Component
struct RatingSystem {
  @State selectedRating: number = 0;
  @State showMessage: boolean = false;

  build() {
    Column() {
      // Header
      Text('Rate Your Experience')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      // Star Rating
      Row() {
        ForEach([1, 2, 3, 4, 5], (star: number) => {
          Image($r('app.media.app_icon'))
            .width(40)
            .height(40)
            .margin(5)
            .onClick(() => {
              this.selectedRating = star;
              this.showMessage = true;
            })
            .opacity(this.selectedRating >= star ? 1 : 0.3);
        });
      }

      // Selected Rating Message
      if (this.showMessage && this.selectedRating > 0) {
        Text(`You rated: ${this.selectedRating} stars`)
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 40 });
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

