struct CalculatorApp {
  @State num1: number = 0
  @State num2: number = 0
  @State result: number = 0

  build() {
    Column() {
      TextInput({ placeholder: 'Enter first number' })
        .onChange((value: string) => {
          this.num1 = parseFloat(value)
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter second number' })
        .onChange((value: string) => {
          this.num2 = parseFloat(value)
