        .margin({ bottom: 20 })

      Button('Calculate Sum')
        .onClick(() => {
          this.result = this.num1 + this.num2
        })
        .margin({ bottom: 20 })

      Text(`Sum: ${this.result}`)
        .fontSize(24)
        .margin({ top: 20 })
    }
    .padding(20)
  }
}

