@Entry
@Component
struct PopupPositioningExample {
  @State popupOffsetX: number = 100;
  @State popupOffsetY: number = 100;
  @State showPopup: boolean = false;
  @State locale: string = 'en';

  build() {
    Stack() {
      Column() {
        Button('Show Popup')
          .onClick(() => {
            this.showPopup = !this.showPopup;
          })
          .width(150)
          .height(50)
          .backgroundColor(Color.Blue)
          .fontColor(Color.White)
          .margin(20);

        Flex({ justifyContent: FlexAlign.SpaceAround }) {
          Button('English (EN)')
            .onClick(() => {
              this.locale = 'en';
              this.popupOffsetX = 100;
              this.popupOffsetY = 100;
            })
            .backgroundColor(Color.Green)
            .fontColor(Color.White)
            .padding(10);

          Button('Arabic (AR)')
            .onClick(() => {
              this.locale = 'ar';
              this.popupOffsetX = -100;
              this.popupOffsetY = 100;
            })
            .backgroundColor(Color.Green)
            .fontColor(Color.White)
            .padding(10);

          Button('Chinese (ZH)')
            .onClick(() => {
              this.locale = 'zh';
              this.popupOffsetX = 100;
              this.popupOffsetY = -100;
            })
            .backgroundColor(Color.Green)
            .fontColor(Color.White)
            .padding(10);
        }
        .margin({ bottom: 20 });

        if (this.showPopup) {
          Column() {
            Text('Popup Content')
              .fontSize(18)
              .fontColor(Color.Black)
              .textAlign(TextAlign.Center)
              .margin(10);

            Image($r('app.media.app_icon'))
              .width(50)
              .height(50)
              .margin(10);
          }
          .width(200)
          .height(150)
          .backgroundColor(Color.White)
          .borderRadius(10)
          .position({ x: this.popupOffsetX, y: this.popupOffsetY })
          .shadow({ radius: 10, color: Color.Gray, offsetX: 5, offsetY: 5 });
        }
      }
      .width('100%')
      .height('100%')
      .backgroundColor('#D3D3D3');
    }
  }
}

