@Entry
@Component
struct TaskListApp {
  private tasks: Task[] = [
    { id: 1, title: 'Task 1', completed: false },
    { id: 2, title: 'Task 2', completed: false },
    { id: 3, title: 'Task 3', completed: false }
  ];

  private newTaskTitle: string = '';

  build() {
    Column() {
      Row() {
        TextInput({ placeholder: 'Enter a new task' })
          .width('70%')
          .height(40)
          .onChange((value: string) => {
            this.newTaskTitle = value;
          });

        Button('Add')
          .width('30%')
          .height(40)
          .onClick(() => {
            if (this.newTaskTitle.trim() !== '') {
              this.tasks.push({
                id: this.tasks.length + 1,
                title: this.newTaskTitle,
                completed: false
              });
              this.newTaskTitle = '';
            }
          });
      }
      .padding(10);

      ForEach(this.tasks, (task: Task, index: number) => {
        Row() {
          Checkbox()
            .select(task.completed)
            .onChange((value: boolean) => {
              this.tasks[index].completed = value;
            });

          Text(task.title)
            .fontSize(18)
            .margin({ left: 10 })
            .decoration({ type: task.completed ? TextDecorationType.LineThrough : TextDecorationType.None });
        }
        .padding(10);
      });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5');
  }
}

interface Task {
  id: number;
  title: string;
  completed: boolean;
}

