@Entry
@Component
struct SwipeRefresherWithRealTimeData {
  @State refreshing: boolean = false;
  @State listData: string[] = ['Initial Data 1', 'Initial Data 2', 'Initial Data 3'];
  @State timerId: number = -1;

  aboutToAppear() {
    this.timerId = setInterval(() => {
      this.listData.push(`Real-Time Update ${this.listData.length + 1}`);
      if (this.listData.length > 10) {
        this.listData.shift();
      }
    }, 3000);
  }

  aboutToDisappear() {
    if (this.timerId !== -1) {
      clearInterval(this.timerId);
    }
  }

  refreshData() {
    this.refreshing = true;
    setTimeout(() => {
      this.listData = ['Refreshed Data 1', 'Refreshed Data 2', 'Refreshed Data 3'];
      this.refreshing = false;
    }, 1500);
  }

  build() {
    Column() {
      Refresh({
        refreshing: this.refreshing,
        offset: 120,
        friction: 100
      }) {
        List() {
          ForEach(this.listData, (item: string) => {
            ListItem() {
              Row() {
                Image($r('app.media.app_icon'))
                  .width(40)
                  .height(40)
                  .margin(10);
                Text(item)
                  .fontSize(18);
              }
              .width('100%')
              .justifyContent(FlexAlign.Start);
            }
            .borderRadius(8)
            .margin({ top: 5, bottom: 5 })
            .backgroundColor('#f5f5f5');
          }, (item: string) => item);
        }
        .width('100%')
        .height('100%');
      }
      .onRefreshing(() => {
        this.refreshData();
      });
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff');
  }
}

