@Component
struct TodoListApp {
  @State tasks: Array<string> = []
  @State newTask: string = ''

  build() {
    Column() {
      TextInput({ placeholder: 'Enter a new task', text: this.newTask })
        .onChange((value: string) => {
          this.newTask = value
        })
        .margin({ bottom: 20 })

      Button('Add Task')
        .onClick(() => {
          if (this.newTask.trim() !== '') {
            this.tasks.push(this.newTask)
            this.newTask = ''
          }
        })
        .margin({ bottom: 20 })

      List() {
        ForEach(this.tasks, (task: string, index: number) => {
          ListItem() {
            Row() {
              Text(task)
                .fontSize(20)
                .margin({ left: 10 })
              Button('Remove')
                .onClick(() => {
                  this.tasks.splice(index, 1)
                })
                .margin({ left: 10 })
            }
            .justifyContent(FlexAlign.SpaceBetween)
          }
          .margin({ top: 10 })
        })
      }
      .width('100%')
      .height('70%')
    }
    .padding(20)
  }
}

