@Entry
@Component
struct GestureSequenceTiming {
  @State private tapCount: number = 0;
  @State private tapSequence: string = '';
  @State private lastTapTime: number = 0;

  private handleTap() {
    const currentTime = new Date().getTime();
    if (currentTime - this.lastTapTime < 800) { // 800ms timing constraint
      this.tapCount++;
      this.tapSequence += 'Tap, ';
    } else {
      this.tapCount = 1;
      this.tapSequence = 'Tap, ';
    }
    this.lastTapTime = currentTime;
  }

  build() {
    Column() {
      Text('Gesture Sequence Timing')
        .fontSize(24)
        .margin(20);
      Text(`Tap Count: ${this.tapCount}`)
        .fontSize(18)
        .margin(10);
      Text(`Tap Sequence: ${this.tapSequence}`)
        .fontSize(18)
        .margin(10);
      Button('Tap Me')
        .onClick(() => {
          this.handleTap();
        })
        .width(150)
        .height(50)
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor('#F5F5F5');
  }
}

