@Entry
@Component
struct GestureGroupErrorHandling {
  @State private message: string = "Perform a gesture";
  @State private errorMessage: string = "";
  @State private panOffsetX: number = 0;
  @State private panOffsetY: number = 0;

  private handleGestureError(error: string): void {
    this.errorMessage = error;
  }

  build() {
    Column({ space: 20 }) {
      Text(this.message)
        .fontSize(20)
        .textAlign(TextAlign.Center)
        .margin({ top: 20 });

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(16)
          .fontColor(Color.Red)
          .margin({ top: 10 });
      }

      Flex({ justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
          .gesture(
            GestureGroup(
              GestureMode.Parallel,
              TapGesture({ count: 1 })
                .onAction(() => {
                  this.message = "Tap Detected";
                  this.errorMessage = "";
                }),
              PanGesture({ direction: PanDirection.All })
                .onActionStart(() => {
                  this.message = "Pan Started";
                  this.errorMessage = "";
                })
                .onActionUpdate((event: PanGestureEvent) => {
                  this.panOffsetX = event.offsetX;
                  this.panOffsetY = event.offsetY;
                  this.message = "Pan Update";
                  this.errorMessage = "";
                })
                .onActionEnd(() => {
                  this.message = "Pan Ended";
                  this.handleGestureError("Pan Gesture Error Occurred");
                })
            )
          )
          .transform({ translate: { x: this.panOffsetX, y: this.panOffsetY } })
          .animation({ duration: 300 })
      }
      .width('100%')
      .height(200)
      .backgroundColor(Color.Gray)
      .borderRadius(10)
      .margin(20);
    }
    .width('100%')
    .height('100%')
    .backgroundColor(0xf5f5f5)
  }
}

@Entry
@Component
struct LoginScreen {
  @State username: string = ''
  @State password: string = ''
  @State loginMessage: string = ''

  validateInput(): boolean {
    if (this.username && this.password) {
      this.loginMessage = 'Login successful!'
      return true
    } else {
      this.loginMessage = 'Please enter both username and password.'
      return false
    }
  }

  build() {
    Column() {
      // Username Label and Input
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your username', text: this.username })
        .onChange((value: string) => {
          this.username = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Password Label and Input
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Login Button
      Button('Login')
        .onClick(() => {
          this.validateInput()
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      // Login Message
      if (this.loginMessage) {
        Text(this.loginMessage)
          .fontSize(16)
          .margin({ top: 20 })
          .fontColor(this.loginMessage === 'Login successful!' ? Color.Green : Color.Red)
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

