@Entry
@Component
struct GestureGroupStateMachine {
  @State private panOffsetX: number = 0;
  @State private panOffsetY: number = 0;
  @State private scaleValue: number = 1;
  @State private rotationAngle: number = 0;
  @State private tapCount: number = 0;

  build() {
    Column() {
      Text('Perform complex gestures on the box')
        .fontSize(20)
        .margin({ bottom: 20 });

      Row()
        .width(200)
        .height(200)
        .backgroundColor(Color.Green)
        .borderRadius(10)
        .gesture(
          GestureGroup(
            GestureMode.Parallel,
            PanGesture({ direction: PanDirection.All })
              .onActionStart(() => {
                console.info('Pan gesture started');
              })
              .onActionUpdate((event: PanGestureEvent) => {
                this.panOffsetX = event.offsetX;
                this.panOffsetY = event.offsetY;
              })
              .onActionEnd(() => {
                console.info('Pan gesture ended');
              }),
            PinchGesture()
              .onActionStart(() => {
                console.info('Pinch gesture started');
              })
              .onActionUpdate((event: PinchGestureEvent) => {
                this.scaleValue = event.scale;
              })
              .onActionEnd(() => {
                console.info('Pinch gesture ended');
              }),
            RotationGesture()
              .onActionStart(() => {
                console.info('Rotation gesture started');
              })
              .onActionUpdate((event: RotationGestureEvent) => {
                this.rotationAngle = event.angle;
              })
              .onActionEnd(() => {
                console.info('Rotation gesture ended');
              }),
            TapGesture()
              .onAction(() => {
                this.tapCount += 1;
              })
          )
        )
        .transform({ translate: { x: this.panOffsetX, y: this.panOffsetY }, scale: { x: this.scaleValue, y: this.scaleValue }, rotate: { angle: this.rotationAngle } })
        .animation({ duration: 300 });

      Text(`Tap Count: ${this.tapCount}`)
        .fontSize(24)
        .fontColor(Color.Black)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

import { inspector } from '@kit.ArkUI';

@Entry
@Component
struct Component3DEventDetection {
  private eventDispatcher: EventDispatcher = new EventDispatcher();
  listener: inspector.ComponentObserver = inspector.createComponentObserver('COMPONENT_3D_ID');

  build() {
    Column() {
      Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Start }) {
        Row({ space: 5 }) {
          Image($r('app.media.app_icon'))
            .width(110)
            .height(110)
            .border({ width: 1 })
            .id('COMPONENT_3D_ID')
        }
      }
    }.height(320).width(360).padding({ right: 10, top: 10 })
  }

  aboutToAppear() {
    let onLayoutComplete: () => void = (): void => {
      console.log('Component3D layout completed');
      this.eventDispatcher.dispatchEvent({ type: 'LayoutComplete', data: 'Layout completion event fired' });
    };
    let onDrawComplete: () => void = (): void => {
      console.log('Component3D draw completed');
      this.eventDispatcher.dispatchEvent({ type: 'DrawComplete', data: 'Draw completion event fired' });
    };

    let FuncLayout = onLayoutComplete;
    let FuncDraw = onDrawComplete;

    this.listener.on('layout', FuncLayout);
    this.listener.on('draw', FuncDraw);

    this.eventDispatcher.addEventListener('LayoutComplete', this.handleEvent.bind(this));
    this.eventDispatcher.addEventListener('DrawComplete', this.handleEvent.bind(this));
  }

  private handleEvent(event: EventType): void {
    console.log(`Universal event detected: ${event.type}`, event.data);
  }
}

interface EventType {
  type: string;
  data: string;
}

class EventDispatcher {
  private listeners: Map<string, (event: EventType) => void> = new Map();

  dispatchEvent(event: EventType): void {
    const listener = this.listeners.get(event.type);
    if (listener) {
      listener(event);
    }
  }

  addEventListener(eventType: string, callback: (event: EventType) => void): void {
    this.listeners.set(eventType, callback);
  }
}

