@Entry
@Component
struct SwipeRefresherThrottlingHandling {
  @State isRefreshing: boolean = false;
  @State items: string[] = ['Item 1', 'Item 2', 'Item 3'];
  private lastRefreshTime: number = 0;
  private throttleTime: number = 3000; // 3 seconds throttle time

  build() {
    Column() {
      Refresh({ refreshing: this.isRefreshing }) {
        List() {
          ForEach(this.items, (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(16)
                .padding(10)
            }
          })
        }
        .height('80%')
      }
      .onRefreshing(() => {
        const currentTime = new Date().getTime();
        if (currentTime - this.lastRefreshTime > this.throttleTime) {
          this.lastRefreshTime = currentTime;
          this.isRefreshing = true;
          setTimeout(() => {
            if (Math.random() < 0.5) { // Simulate a 50% chance of server throttling
              this.isRefreshing = false;
              console.log('Server throttling detected. Please try again later.');
            } else {
              this.items = [...this.items, `Item ${this.items.length + 1}`];
              this.isRefreshing = false;
            }
          }, 2000); // Simulate a 2-second delay for the server response
        } else {
          this.isRefreshing = false;
          console.log('Throttling: Please wait before refreshing again.');
        }
      })

      if (this.isRefreshing) {
        Image($r('app.media.app_icon'))
          .width(50)
          .height(50)
          .margin(10)
      }
    }
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct TapGestureTimeoutHandling {
  @State private tapCount: number = 0;
  @State private timeoutId: number = -1;
  @State private tapMessage: string = "Tap the screen";

  private handleTap() {
    this.tapCount++;
    if (this.timeoutId !== -1) {
      clearTimeout(this.timeoutId);
    }
    this.timeoutId = setTimeout(() => {
      this.tapMessage = `Tap gesture timeout reached. Total taps: ${this.tapCount}`;
      this.tapCount = 0;
      this.timeoutId = -1;
    }, 1000); // 1 second timeout
  }

  build() {
    Column() {
      Text(this.tapMessage)
        .fontSize(20)
        .margin(10)
      Button('Tap Me')
        .onClick(() => {
          this.handleTap();
        })
        .width(150)
        .height(50)
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

