@Entry
@Component
struct TapPositionValidation {
  @State tapX: number = 0
  @State tapY: number = 0
  @State isValidTap: boolean = false

  build() {
    Column() {
      Text('Tap anywhere on the screen to validate the position')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .onTouch((event: TouchEvent) => {
          const touch = event.touches[0]
          this.tapX = touch.x
          this.tapY = touch.y
          this.isValidTap = this.validateTapPosition(touch.x, touch.y)
        })

      if (this.isValidTap) {
        Text(`Valid tap at (${this.tapX}, ${this.tapY})`)
          .fontSize(16)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 20 })
      } else {
        Text(`Invalid tap at (${this.tapX}, ${this.tapY})`)
          .fontSize(16)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#F5F5F5')
  }

  private validateTapPosition(x: number, y: number): boolean {
    // Define the valid tap area (e.g., within the image bounds)
    const imageX = 100 // X position of the image
    const imageY = 100 // Y position of the image
    const imageWidth = 200
    const imageHeight = 200

    return x >= imageX && x <= imageX + imageWidth && y >= imageY && y <= imageY + imageHeight
  }
}

