  @State private message: string = 'Tap the rectangle below';

  build() {
    Column() {
      Text(this.message)
        .fontSize(20)
        .margin({ bottom: 20 });

      Text(`Total Tap Count: ${this.tapCount}`)
        .fontSize(18)
        .margin({ bottom: 20 });

      Rect()
        .width(200)
        .height(200)
        .backgroundColor(Color.Orange)
        .borderRadius(10)
        .gesture(
          TapGesture({ count: 1 })
            .onAction(() => {
              this.message = 'Single tap detected';
              this.tapCount += 1;
            })
        )
        .gesture(
          TapGesture({ count: 2 })
            .onAction(() => {
              this.message = 'Double tap detected';
              this.tapCount += 2;
            })
        )
        .gesture(
          TapGesture({ count: 3 })
            .onAction(() => {
              this.message = 'Triple tap detected';
              this.tapCount += 3;
            })
        )
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

