                    .borderRadius(4)
                    .backgroundColor('#f0f0f0')
                    .padding(5)
                  }
                }
                .width('100%')
                .justifyContent(FlexAlign.Start)
              }
              .width('100%')
              .padding(10)
              .borderRadius(8)
              .backgroundColor('#ffffff')
              .margin({ top: 5, bottom: 5 })
            }
          })
        }
        .width('100%')
        .height('100%')
      }
      .onRefreshing(() => {
        this.isRefreshing = true;
        setTimeout(() => {
          this.isRefreshing = false;
          this.showNestedContent = true;
          this.listData = [...this.listData, `New Item ${this.listData.length + 1}`];
        }, 1500);
      })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
    .padding(10)
  }
}

