@Entry
@Component
struct ChainedPopups {
  @State isFirstPopupVisible: boolean = false;
  @State isSecondPopupVisible: boolean = false;
  @State isThirdPopupVisible: boolean = false;
  @State selectedOption: string = '';
  @State confirmationMessage: string = '';

  build() {
    Column({ space: 20 }) {
      Button('Start Chained Popups')
        .onClick(() => {
          this.isFirstPopupVisible = true;
        })
        .padding(10)
        .backgroundColor(Color.Blue)
        .fontColor(Color.White)
        .borderRadius(5);

      if (this.isFirstPopupVisible) {
        Column() {
          Text('First Popup: Select an Option')
            .fontSize(20)
            .fontColor(Color.Black)
            .padding(10);

          Button('Option A')
            .onClick(() => {
              this.selectedOption = 'Option A';
              this.isFirstPopupVisible = false;
              this.isSecondPopupVisible = true;
            })
            .margin(10)
            .width(200);

          Button('Option B')
            .onClick(() => {
              this.selectedOption = 'Option B';
              this.isFirstPopupVisible = false;
              this.isSecondPopupVisible = true;
            })
            .margin(10)
            .width(200);
        }
        .backgroundColor(Color.White)
        .borderRadius(10)
        .shadow({ radius: 5 })
        .padding(20);
      }

      if (this.isSecondPopupVisible) {
        Column() {
          Text(`Selected Option: ${this.selectedOption}`)
            .fontSize(18)
            .fontColor(Color.Black)
            .padding(10);

          Text('Second Popup: Confirm Selection')
            .fontSize(20)
            .fontColor(Color.Black)
            .padding(10);

          Button('Confirm')
            .onClick(() => {
              this.confirmationMessage = 'Selection confirmed successfully!';
              this.isSecondPopupVisible = false;
              this.isThirdPopupVisible = true;
            })
            .margin(10)
            .width(200);

          Button('Cancel')
            .onClick(() => {
              this.isSecondPopupVisible = false;
            })
            .margin(10)
            .width(200);
        }
        .backgroundColor(Color.White)
        .borderRadius(10)
        .shadow({ radius: 5 })
        .padding(20);
      }

      if (this.isThirdPopupVisible) {
        Column() {
          Text('Third Popup: Confirmation')
            .fontSize(20)
            .fontColor(Color.Black)
            .padding(10);

          Text(this.confirmationMessage)
            .fontSize(16)
            .padding(10);

          Button('Close')
            .onClick(() => {
              this.isThirdPopupVisible = false;
            })
            .margin(10)
            .width(200);
        }
        .backgroundColor(Color.White)
        .borderRadius(10)
        .shadow({ radius: 5 })
        .padding(20);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#f5f5f5');
  }
}

