@Component
struct TapGestureFilteringExample {
  @State private tapCount: number = 0;
  @State private tapMessage: string = "Tap the box";
  @State private lastTapTime: number = 0;

  build() {
    Column() {
      Text(this.tapMessage)
        .fontSize(24)
        .margin({ bottom: 20 });

      Image($r('app.media.app_icon'))
        .width(150)
        .height(150)
        .backgroundColor(Color.Gray)
        .borderRadius(10)
        .gesture(
          TapGesture()
            .onAction(() => {
              const currentTime = new Date().getTime();
              if (currentTime - this.lastTapTime > 500) {
                this.tapCount++;
                this.tapMessage = `Tap Count: ${this.tapCount}`;
                this.lastTapTime = currentTime;
              } else {
                this.tapMessage = "Tap too fast! Slow down.";
              }
            })
        )
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

