@Entry
@Component
struct RefreshRollbackMechanism {
  @State isRefreshing: boolean = false;
  @State refreshCount: number = 0;
  @State refreshSuccess: boolean = true;
  @State data: string[] = ['Initial Data 1', 'Initial Data 2', 'Initial Data 3'];

  build() {
    Column() {
      Text('Refreshing Status: ' + this.isRefreshing)
        .fontSize(24)
        .margin(10);

      Text('Refresh Count: ' + this.refreshCount)
        .fontSize(24)
        .margin(10);

      Text('Last Refresh: ' + (this.refreshSuccess ? 'Success' : 'Failure'))
        .fontSize(24)
        .margin(10);

      List() {
        ForEach(this.data, (item: string) => {
          ListItem() {
            Text(item)
              .fontSize(16)
              .padding(16)
              .backgroundColor('#f0f0f0')
              .width('100%');
          }
        });
      }
      .width('100%');

      Refresh({ refreshing: $$this.isRefreshing }) {
        Text('Pull down to refresh')
          .fontSize(24)
          .margin(10);
      }
      .onStateChange(() => {
        const currentData = [...this.data];
        setTimeout(() => {
          const success = Math.random() > 0.5;
          if (success) {
            this.refreshCount += 1;
            this.refreshSuccess = true;
            this.data = ['Updated Data 1', 'Updated Data 2', 'Updated Data 3'];
          } else {
            this.refreshSuccess = false;
            this.data = currentData; // Rollback to previous data on failure
          }
          this.isRefreshing = false;
        }, 2000);
      });
    }
    .width('100%')
    .height('100%');
  }
}

