@Entry
@Component
struct CustomSwipeRefresherAnimation {
  @State refreshing: boolean = false
  @State items: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4']
  @State scaleValue: number = 1
  @State opacityValue: number = 0.5
  private timerId: number = -1

  build() {
    Column() {
      // Custom loading animation
      if (this.refreshing) {
        Row() {
          Image($r('app.media.app_icon'))
            .width(40)
            .height(40)
            .scale({ x: this.scaleValue, y: this.scaleValue })
            .opacity(this.opacityValue)
          Text('Loading...')
            .margin({ left: 10 })
            .fontSize(16)
        }
        .width('100%')
        .justifyContent(FlexAlign.Center)
        .padding(10)
        .onAppear(() => {
          animateTo({
            duration: 1000,
            curve: Curve.EaseInOut,
            iterations: -1,
            playMode: PlayMode.Normal
          }, () => {
            this.scaleValue = 1.5
            this.opacityValue = 1
          })
          animateTo({
            duration: 1000,
            curve: Curve.EaseInOut,
            iterations: -1,
            playMode: PlayMode.Normal
          }, () => {
            this.scaleValue = 1
            this.opacityValue = 0.5
          })
        })
      }

      // List with pull-to-refresh
      Refresh({ refreshing: $$this.refreshing, friction: 100 }) {
        List() {
          ForEach(this.items, (item: string) => {
            ListItem() {
              Text(item)
                .width('100%')
                .height(60)
                .fontSize(18)
                .textAlign(TextAlign.Center)
                .backgroundColor('#f5f5f5')
                .margin({ top: 5, bottom: 5 })
                .borderRadius(8)
            }
          })
        }
        .width('100%')
        .height('100%')
      }
      .onStateChange((refreshStatus: RefreshStatus) => {
        console.info('Refresh status changed to: ' + refreshStatus)
      })
      .onRefreshing(() => {
        this.refreshing = true
        // Simulate data fetching
        this.timerId = setTimeout(() => {
          this.items = ['New Item ' + (this.items.length + 1), ...this.items]
          this.refreshing = false
        }, 2000)
      })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff')
  }

  aboutToDisappear() {
    if (this.timerId !== -1) {
      clearTimeout(this.timerId)
    }
  }
}

