@Entry
@Component
struct TapGestureWithCustomTriggers {
  @State message: string = 'Tap the box to trigger custom actions'
  @State triggerCount: number = 0

  build() {
    Column() {
      Text(this.message)
        .fontSize(20)
        .margin({ bottom: 20 })

      Row()
        .width(200)
        .height(200)
        .backgroundColor(Color.Green)
        .borderRadius(10)
        .gesture(
          TapGesture({ count: 1 })
            .onAction(() => {
              this.triggerCount += 1
              if (this.triggerCount === 1) {
                this.message = 'Single tap triggered'
              } else if (this.triggerCount === 2) {
                this.message = 'Double tap triggered'
              } else if (this.triggerCount >= 3) {
                this.message = 'Triple tap triggered'
              }
              setTimeout(() => {
                this.triggerCount = 0
                this.message = 'Tap the box to trigger custom actions'
              }, 1000)
            })
        )
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

