import { UIContext } from '@kit.ArkUI';

interface ScaleValue {
  x: number;
  y: number;
}

@Entry
@Component
struct Component3DAnimation {
  @State private scaleValue: number = 1.0;
  @State private rotation: number = 0;
  @State private opacityValue: number = 1.0;
  uiContext: UIContext | undefined = undefined;

  aboutToAppear() {
    this.uiContext = this.getUIContext?.();
  }

  scale(value: ScaleValue): CommonAttribute {
    this.scaleValue = value.x;
    return new CommonAttribute();
  }

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(100)
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })
        .opacity(this.opacityValue)
        .onClick(() => {
          if (!this.uiContext) {
            console.info("no uiContext, animation failed");
            return;
          }
          this.scaleValue = 1.0;
          this.rotation = 0;
          this.opacityValue = 1.0;
          this.uiContext.keyframeAnimateTo({ iterations: 2 }, [
            {
              duration: 800,
              event: () => {
                this.scaleValue = 1.5;
                this.rotation = 90;
                this.opacityValue = 0.7;
              }
            },
            {
              duration: 500,
              event: () => {
                this.scaleValue = 1.0;
                this.rotation = 0;
                this.opacityValue = 1.0;
              }
            }
          ]);
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

