          .onClick(() => {
            this.selectedStyle = 'OUTLINE';
          })

        Button('Colored')
          .width('80px')
          .height('30px')
          .backgroundColor(this.selectedStyle === 'COLORED' ? '#3498db' : '#95a5a6')
          .onClick(() => {
            this.selectedStyle = 'COLORED';
          })
      }.justifyContent(FlexAlign.Center)
    }.width('100%').height('100%').justifyContent(FlexAlign.Center).alignItems(HorizontalAlign.Center)
  }

  private getIcon(): Resource {
    switch (this.selectedStyle) {
      case 'FILLED':
        return $r('app.media.icon');
      case 'OUTLINE':
        return $r('app.media.icon');
      case 'COLORED':
        return $r('app.media.icon');
      default:
        return $r('app.media.icon');
    }
  }
}

