@Component
struct ImageGallery {
  @State selectedImage: Resource = $r('app.media.app_icon')
  @State showFullScreen: boolean = false
  @State private currentScale: number = 1.0

  private images: Resource[] = [
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
  ]

  build() {
    Column() {
      if (this.showFullScreen) {
        Stack() {
          Image(this.selectedImage)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%')
            .scale({ x: this.currentScale, y: this.currentScale })
            .gesture(
              PinchGesture()
                .onActionStart(() => {})
                .onActionUpdate((event: PinchGestureEvent) => {
                  this.currentScale = event.scale
                })
                .onActionEnd(() => {})
            )

          Button('Close')
            .onClick(() => {
              this.showFullScreen = false
              this.currentScale = 1.0
            })
            .position({ x: 20, y: 20 })
            .backgroundColor('#FFFFFF')
            .padding({ left: 10, right: 10, top: 5, bottom: 5 })
            .borderRadius(5)
        }
      } else {
        Grid() {
          ForEach(this.images, (image: Resource) => {
            GridItem() {
              Image(image)
                .width('100%')
                .aspectRatio(1)
                .objectFit(ImageFit.Cover)
                .borderRadius(5)
                .onClick(() => {
                  this.selectedImage = image
                  this.showFullScreen = true
                })
            }
          })
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsGap(10)
        .columnsGap(10)
        .padding(10)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

