@Entry
@Component
struct MultiSelectionListView {
  private items: Array<string> = [
    'Item 1',
    'Item 2',
    'Item 3',
    'Item 4',
    'Item 5'
  ];

  @State selectedItems: Array<string> = [];

  build() {
    Column() {
      Text('Multi-Selection ListView')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      List() {
        ForEach(this.items, (item: string) => {
          ListItem() {
            Row() {
              Image($r('app.media.app_icon'))
                .width(30)
                .height(30)
                .margin({ right: 10 });
              Text(item)
                .fontSize(18)
                .padding(10)
                .onClick(() => {
                  if (this.selectedItems.includes(item)) {
                    this.selectedItems = this.selectedItems.filter(selectedItem => selectedItem !== item);
                  } else {
                    this.selectedItems = [...this.selectedItems, item];
                  }
                });
            }
            .backgroundColor(this.selectedItems.includes(item) ? '#d3d3d3' : '#f0f0f0')
            .borderRadius(5)
            .padding(10)
            .margin({ bottom: 10 });
          }
        }, (item: string) => item);
      }
      .width('100%');

      if (this.selectedItems.length > 0) {
        Text('Summary of Selected Items:')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 20 });

        ForEach(this.selectedItems, (selectedItem: string) => {
          Text(selectedItem)
            .fontSize(18)
            .margin({ top: 10 });
        }, (selectedItem: string) => selectedItem);
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

