@Entry
@Component
struct EfficientArrayManager {
  @State private dataArray: number[] = [];
  @State private isLoading: boolean = false;
  @State private refreshCount: number = 0;
  @State private processingTime: string = "";

  private simulateDataLoad() {
    this.isLoading = true;
    const startTime = Date.now();

    setTimeout(() => {
      this.dataArray = Array.from<number, number>({ length: 5000 }, (_, i) => i + 1);
      this.isLoading = false;
      this.refreshCount++;
      const endTime = Date.now();
      this.processingTime = `Processed in ${(endTime - startTime).toFixed(2)} ms`;
    }, 800); // Simulate a delay for loading
  }

  private refreshData() {
    this.dataArray = [];
    this.simulateDataLoad();
  }

  private clearData() {
    this.dataArray = [];
    this.processingTime = "";
  }

  build() {
    Column() {
      Text('Efficient Array Management')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Button(this.isLoading ? 'Loading Data...' : 'Load Data')
        .onClick(() => this.simulateDataLoad())
        .width('80%')
        .margin({ bottom: 10 })
        .enabled(!this.isLoading);

      Button('Refresh Data')
        .onClick(() => this.refreshData())
        .width('80%')
        .margin({ bottom: 10 })
        .enabled(!this.isLoading);

      Button('Clear Data')
        .onClick(() => this.clearData())
        .width('80%')
        .margin({ bottom: 20 })
        .enabled(!this.isLoading && this.dataArray.length > 0);

      Text(`Refresh Count: ${this.refreshCount}`)
        .fontSize(18)
        .margin({ bottom: 10 });

      Text(`Array Length: ${this.dataArray.length}`)
        .fontSize(18)
        .margin({ bottom: 10 });

      if (this.processingTime) {
        Text(this.processingTime)
          .fontSize(16)
          .fontColor('#666666')
          .margin({ bottom: 10 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
    .backgroundColor('#ffffff');
  }
}

