@Entry
@Component
struct WizardLayoutWithProgress {
  @State currentStep: number = 1
  private totalSteps: number = 5

  @Builder
  StepCircle(step: number) {
    Stack() {
      Circle()
        .width(50)
        .height(50)
        .fill(this.currentStep >= step ? '#007AFF' : '#E0E0E0')
      Text(step.toString())
        .fontSize(24)
        .fontColor(Color.White)
    }
  }

  build() {
    Column() {
      Row() {
        ForEach([1, 2, 3, 4, 5], (step: number) => {
          Column() {
            this.StepCircle(step)
            Text(`Step ${step}`)
              .fontSize(16)
              .margin({ top: 10 })
          }

          if (step < this.totalSteps) {
            Divider()
              .width(40)
              .strokeWidth(2)
              .color(this.currentStep > step ? '#007AFF' : '#E0E0E0')
          }
        })
      }
      .margin({ top: 50, bottom: 50 })

      Column() {
        Progress({ value: (this.currentStep / this.totalSteps) * 100, style: ProgressStyle.Linear })
          .width('80%')
          .height(10)
          .color('#007AFF')
          .backgroundColor('#E0E0E0')
      }
      .width('100%')
      .alignItems(HorizontalAlign.Center)
      .margin({ bottom: 20 })

      Row() {
        Button('Back')
          .onClick(() => {
            if (this.currentStep > 1) {
              this.currentStep--
            }
          })
          .margin({ right: 20 })
          .enabled(this.currentStep > 1)

        Button('Next')
          .onClick(() => {
            if (this.currentStep < this.totalSteps) {
              this.currentStep++
            }
          })
          .enabled(this.currentStep < this.totalSteps)
      }

      Text(`Step ${this.currentStep} of ${this.totalSteps}`)
        .fontSize(18)
        .margin({ top: 30 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

