@Entry
@Component
struct Texture3DRenderingQuality {
  @State private textureQuality: number = 1.0;
  @State private isHighQuality: boolean = true;

  build() {
    Column() {
      Text("3D Texture Rendering Quality")
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin(10);

      Slider({
        value: this.textureQuality,
        min: 0.1,
        max: 2.0,
        step: 0.1,
        style: SliderStyle.OutSet
      })
      .onChange((value: number) => {
        this.textureQuality = value;
      })
      .margin(10);

      Text(`Current Texture Quality: ${this.textureQuality.toFixed(1)}`)
        .fontSize(18)
        .margin(10);

      Toggle({ type: ToggleType.Switch, isOn: this.isHighQuality })
        .onChange((isOn: boolean) => {
          this.isHighQuality = isOn;
        })
        .margin(10);

      Text(this.isHighQuality ? "High Quality Enabled" : "High Quality Disabled")
        .fontSize(16)
        .margin(10);

      Stack() {
        Image($r('app.media.app_icon'))
          .width(300)
          .height(300)
          .objectFit(ImageFit.Cover)
          .opacity(this.textureQuality)
          .borderRadius(10)
          .border({ width: 2, color: Color.Black });

        if (this.isHighQuality) {
          Image($r('app.media.app_icon'))
            .width(300)
            .height(300)
            .objectFit(ImageFit.Cover)
            .opacity(this.textureQuality * 0.5)
            .blur(2)
            .borderRadius(10);
        }
      }
      .margin(10);
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5');
  }
}

@Entry
@Component
struct EditableTitleBar {
  @State title: string = 'Editable Title';
  @State isEditable: boolean = true;
  @State isEditing: boolean = false;
  @State tempTitle: string = this.title;

  @LocalStorageProp('contentMargin')
  contentMargin: ContentMargin = { left: 20, top: 20, right: 20, bottom: 20 };

  build() {
    Flex({ direction: FlexDirection.Row, alignItems: ItemAlign.Center, justifyContent: FlexAlign.SpaceBetween }) {
      // Back Button
      Image($r("app.media.app_icon"))
        .width(40)
        .height(40)
        .margin(this.contentMargin)
        .onClick(() => {
          this.isEditing = false;
        });

      // Title or Editable Text
      if (this.isEditing) {
        TextInput({ text: this.tempTitle })
          .onChange((value: string) => {
            this.tempTitle = value;
          })
          .onSubmit(() => {
            this.isEditing = false;
            this.title = this.tempTitle;
          })
          .margin(this.contentMargin);
      } else {
        Text(this.title)
          .fontSize(20)
          .onClick(() => {
            if (this.isEditable) {
              this.isEditing = true;
            }
          })
          .margin(this.contentMargin);
      }

      // Right Action
      Image($r("app.media.app_icon"))
        .width(40)
        .height(40)
        .margin(this.contentMargin);
    }
    .width('100%')
    .height(80)
    .backgroundColor(Color.Gray);
  }
}

interface ContentMargin {
  left: number;
  top: number;
  right: number;
  bottom: number;
}

