@Entry
@Component
struct StateManagementApp {
  @State private items: string[] = ['Item 1', 'Item 2']; // State array for items
  @State private counter: number = 0; // State variable for counter

  // Method to add an item
  private addItem() {
    this.items = [...this.items, `Item ${this.items.length + 1}`];
  }

  // Method to remove an item
  private removeItem() {
    this.items = this.items.slice(0, -1);
  }

  // Method to increment counter
  private incrementCounter() {
    this.counter += 1;
  }

  // Method to decrement counter
  private decrementCounter() {
    this.counter -= 1;
  }

  build() {
    Column() {
      // Display items
      ForEach(this.items, (item: string) => {
        Text(`Item: ${item}`)
          .margin(10)
      })

      // Buttons for item management
      Button('Add Item')
        .onClick(() => {
          this.addItem();
        })
        .margin(10)
        .width(200)

      Button('Remove Item')
        .onClick(() => {
          this.removeItem();
        })
        .margin(10)
        .width(200)

      // Display counter
      Text(`Counter: ${this.counter}`)
        .fontSize(24)
        .margin(20)

      // Buttons for counter management
      Button('Increment')
        .onClick(() => {
          this.incrementCounter();
        })
        .margin(10)
        .width(150)

      Button('Decrement')
        .onClick(() => {
          this.decrementCounter();
        })
        .margin(10)
        .width(150)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

