@Component
struct ComplexTapGestureExample {
  @State tapCount: number = 0;
  @State tapPosition: string = 'Tap position will appear here';

  build() {
    Column({ space: 20 }) {
      Text(`Tap Count: ${this.tapCount}`)
        .fontSize(24)
        .fontColor(Color.Black)
        .margin({ top: 20 });

      Text(this.tapPosition)
        .fontSize(18)
        .fontColor(Color.Black)
        .margin({ top: 10 });

      Flex({ justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
        Text('Tap here for complex gestures')
          .fontSize(18)
          .fontColor(Color.White)
          .padding(20)
          .backgroundColor(Color.Blue)
          .borderRadius(10)
          .gesture(
            TapGesture()
              .onAction((event: GestureEvent) => {
                this.tapCount += 1;
                this.tapPosition = `Tap at X: ${event.offsetX}, Y: ${event.offsetY}`;
              })
          );
      }
      .width('100%')
      .height(200)
      .backgroundColor(Color.Gray)
      .borderRadius(10)
      .margin(20);

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 20 })
        .gesture(
          TapGesture()
            .onAction(() => {
              this.tapCount += 1;
            })
        );
    }
    .width('100%')
    .height('100%')
  }
}

import { ExceptionPrompt, PromptOptions, MarginType } from '@kit.ArkUI';

@Entry
@Component
struct ComponentSnapshotErrorHandling {
  @State options: PromptOptions = {
    icon: $r('app.media.app_icon'),
    tip: 'Unauthorized Access (Error Code: 401)',
    marginType: MarginType.DEFAULT_MARGIN,
    actionText: 'Retry',
    marginTop: 80,
    isShown: true
  };

  @State private errorMessage: string = '';

  handleError(error: Error) {
    if (error.message.includes('401')) {
      this.options.tip = 'Unauthorized Access (Error Code: 401)';
      this.options.isShown = true;
    } else {
      this.errorMessage = `Error occurred: ${error.message}`;
    }
  }

  build() {
    Column() {
      Button('Create Snapshot')
        .onClick(() => {
          try {
            // Placeholder for componentSnapshot logic
            this.createSnapshot();
          } catch (error) {
            if (error instanceof Error) {
              this.handleError(error);
            } else {
              this.handleError(new Error('An unknown error occurred'));
            }
          }
        })
        .margin({ bottom: 20 });

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(16)
          .fontColor(Color.Red)
          .margin({ top: 10 });
      }

      ExceptionPrompt({
        options: this.options,
        onTipClick: () => {
          // Handle tip click
        },
        onActionTextClick: () => {
          // Handle retry action
        },
      });
    }
    .width('100%')
    .padding(20);
  }

  private createSnapshot(): void {
    // Placeholder for actual snapshot creation logic
    throw new Error('Unauthorized access (Error Code: 401)');
  }
}

