@Entry
@Component
struct MultiLineFilterWithCollapsibleOptions {
  @State isCollapsed: boolean = true;
  @State filterOptions: string[] = ['Option 1', 'Option 2', 'Option 3', 'Option 4'];
  @State selectedOptions: string[] = [];

  toggleCollapse() {
    this.isCollapsed = !this.isCollapsed;
  }

  updateSelection(option: string) {
    if (this.selectedOptions.includes(option)) {
      this.selectedOptions = this.selectedOptions.filter(item => item !== option);
    } else {
      this.selectedOptions.push(option);
    }
  }

  build() {
    Column({ space: 10 }) {
      // Collapsible Header
      Row({ space: 10 }) {
        Text('Filter Options')
          .fontSize(18)
          .fontWeight(FontWeight.Bold)
        Button(this.isCollapsed ? 'Expand' : 'Collapse')
          .onClick(() => this.toggleCollapse())
          .backgroundColor('#39a2db')
          .fontColor(Color.White)
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceBetween)
      .padding(10)

      // Filter Options List
      if (!this.isCollapsed) {
        Column() {
          ForEach(this.filterOptions, (option: string) => {
            Row({ space: 10 }) {
              Checkbox({ name: option, group: 'filterOptions' })
                .select(this.selectedOptions.includes(option))
                .onChange((value: boolean) => this.updateSelection(option))
              Text(option)
                .fontSize(16)
            }
            .width('100%')
            .padding(10)
          })
        }
        .width('100%')
        .padding(10)
      }

      // Selected Options Display
      if (this.selectedOptions.length > 0) {
        Column() {
          Text('Selected Options:')
            .fontSize(16)
            .fontWeight(FontWeight.Bold)
            .padding(10)
          ForEach(this.selectedOptions, (option: string) => {
            Row() {
              Image($r('app.media.app_icon'))
                .width(20)
                .height(20)
                .margin({ right: 10 })
              Text(option)
                .fontSize(14)
            }
            .width('100%')
            .padding(5)
          })
        }
        .width('100%')
        .padding(10)
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White)
  }
}

