@Entry
@Component
struct VibrancyShaderCorrection {
  @State private vibrancy: number = 1.0;
  @State private shaderIntensity: number = 0.5;
  @State private shaderColor: string = '#FF0000';
  @State private shaderOpacity: number = 0.8;

  build() {
    Column({ space: 20 }) {
      Text('Vibrancy Correction with Shader')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20 })

      // Image with Vibrancy and Shader Effects
      Stack() {
        Image($r('app.media.app_icon'))
          .width(300)
          .height(300)
          .opacity(this.vibrancy)
          .backgroundColor(this.shaderColor)
          .borderRadius(20)
          .overlay('rgba(0,0,0,' + (1 - this.shaderIntensity) + ')')
      }
      .width('100%')
      .height(300)
      .margin({ bottom: 20 })

      // Vibrancy Slider
      Row() {
        Text('Vibrancy:')
        Slider({
          value: this.vibrancy,
          min: 0.5,
          max: 2.0,
          step: 0.1
        })
        .onChange((value: number) => {
          this.vibrancy = value;
        })
        .layoutWeight(1)
      }

      // Shader Intensity Slider
      Row() {
        Text('Shader Intensity:')
        Slider({
          value: this.shaderIntensity,
          min: 0,
          max: 1,
          step: 0.1
        })
        .onChange((value: number) => {
          this.shaderIntensity = value;
        })
        .layoutWeight(1)
      }

      // Shader Color Toggle
      Row() {
        Text('Shader Color:')
        Button(this.shaderColor)
          .onClick(() => {
            this.shaderColor = this.shaderColor === '#FF0000' ? '#00FF00' : '#FF0000';
          })
          .backgroundColor(this.shaderColor)
          .width(100)
      }

      // Shader Opacity Slider
      Row() {
        Text('Shader Opacity:')
        Slider({
          value: this.shaderOpacity,
          min: 0.1,
          max: 1,
          step: 0.1
        })
        .onChange((value: number) => {
          this.shaderOpacity = value;
        })
        .layoutWeight(1)
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5')
  }
}

