@Entry
@Component
struct CustomFilterParameters {
  @State filter1: string = '';
  @State filter2: string = '';
  @State filter3: string = '';
  @State items: string[] = ['Apple', 'Banana', 'Orange', 'Grapes', 'Mango', 'Pineapple', 'Strawberry', 'Watermelon', 'Cherry', 'Blueberry'];

  private filterItems(): string[] {
    return this.items.filter(item => {
      const matchesFilter1 = this.filter1 ? item.toLowerCase().includes(this.filter1.toLowerCase()) : true;
      const matchesFilter2 = this.filter2 ? item.toLowerCase().includes(this.filter2.toLowerCase()) : true;
      const matchesFilter3 = this.filter3 ? item.toLowerCase().includes(this.filter3.toLowerCase()) : true;
      return matchesFilter1 && matchesFilter2 && matchesFilter3;
    });
  }

  build() {
    Column({ space: 10 }) {
      TextInput({ placeholder: 'Filter 1' })
        .onChange((value: string) => {
          this.filter1 = value;
        })
        .width('100%')
        .margin({ top: 10 });

      TextInput({ placeholder: 'Filter 2' })
        .onChange((value: string) => {
          this.filter2 = value;
        })
        .width('100%')
        .margin({ top: 10 });

      TextInput({ placeholder: 'Filter 3' })
        .onChange((value: string) => {
          this.filter3 = value;
        })
        .width('100%')
        .margin({ top: 10 });

      if (this.filterItems().length > 0) {
        List() {
          ForEach(this.filterItems(), (item: string) => {
            ListItem() {
              Row() {
                Image($r('app.media.app_icon'))
                  .width(30)
                  .height(30)
                  .margin({ right: 10 });
                Text(item)
                  .fontSize(18);
              }
              .width('100%')
              .padding(10);
            }
          });
        }
        .width('100%')
        .height('70%');
      } else {
        Column() {
          Image($r('app.media.app_icon'))
            .width(100)
            .height(100)
            .margin({ bottom: 20 });
          Text('No items match your filters')
            .fontSize(18)
            .fontColor('#666');
        }
        .width('100%')
        .height('70%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff');
  }
}

