      .padding(24)
      .width('90%')
      .backgroundColor(Color.White)
      .borderRadius(16);
    }
  }

  build() {
    Column() {
      Text('Product Grid')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Grid() {
        ForEach(this.products, (product: Product) => {
          GridItem() {
            Column() {
              Image(product.image)
                .width('100%')
                .height(160)
                .borderRadius(8)
