@Entry
@Component
struct Component3DEventHandling {
  private eventDispatcher: EventDispatcher = new EventDispatcher();

  build() {
    Column({ space: 10 }) {
      // Placeholder for Component3D with proactive event dispatch
      Text('3D Component Placeholder')
        .width('100%')
        .height('100%')
        .onAppear(() => {
          this.eventDispatcher.dispatchEvent({ type: 'Component3DAppeared', data: '3D Component has appeared' });
        })

      Button('Trigger Event')
        .onClick(() => {
          this.eventDispatcher.dispatchEvent({ type: 'CustomEvent', data: 'Custom event triggered' });
        })
        .margin({ top: 20 })

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }

  aboutToAppear(): void {
    this.eventDispatcher.addEventListener('Component3DAppeared', this.handle3DEvent.bind(this));
    this.eventDispatcher.addEventListener('CustomEvent', this.handleCustomEvent.bind(this));
  }

  private handle3DEvent(event: EventType): void {
    console.log(`Received event: ${event.type}`, event.data);
    if (event.type === 'Component3DAppeared') {
      console.log('Proactive event handled for 3D Component');
    }
  }

  private handleCustomEvent(event: EventType): void {
    console.log(`Received custom event: ${event.type}`, event.data);
  }
}

interface EventType {
  type: string;
  data: string;
}

class EventDispatcher {
  private listeners: Map<string, (event: EventType) => void> = new Map();

  dispatchEvent(event: EventType): void {
    const listener = this.listeners.get(event.type);
    if (listener) {
      listener(event);
    }
  }

  addEventListener(eventType: string, callback: (event: EventType) => void): void {
    this.listeners.set(eventType, callback);
  }
}

