@Entry
@Component
struct FilterResultTrackingApp {
  @State filterResults: Array<FilterResult> = [];
  @State items: string[] = ['Apple', 'Banana', 'Orange', 'Grapes', 'Mango', 'Pineapple', 'Strawberry', 'Watermelon', 'Cherry', 'Blueberry', 'Lemon', 'Peach'];
  @State searchText: string = '';

  private filteredItems(): string[] {
    if (this.searchText.trim() === '') {
      return this.items;
    } else {
      return this.items.filter(item =>
        item.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  build() {
    Column() {
      // Search Bar
      TextInput({
        placeholder: 'Search items...',
        text: this.searchText
      })
        .width('100%')
        .onChange((value: string) => {
          this.searchText = value;
          this.filterResults = [{ name: 'Search', value: value }];
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      // Display Filter Results
      if (this.filterResults.length > 0) {
        Text('Filter Results:')
          .fontSize(16)
          .fontColor(Color.Black)
          .margin({ top: 16, bottom: 8 });
        ForEach(this.filterResults, (result: FilterResult) => {
          Text(`${result.name}: ${result.value}`)
            .fontSize(14)
            .fontColor(Color.Gray)
            .margin({ bottom: 4 });
        });
      }

      // List of Items
      if (this.filteredItems().length > 0) {
        List() {
          ForEach(this.filteredItems(), (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(18)
                .padding(12);
            }
          }, (item: string) => item); // Use the item as the key
        }
      } else {
        // Display a message when no items match the search
        Text('No items found')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

interface FilterResult {
  name: string;
  value: string;
}

import { ExceptionPrompt, PromptOptions, MarginType } from '@kit.ArkUI';
import image from '@ohos.multimedia.image';

@Entry
@Component
struct ScreenshotErrorHandling {
  @State options: PromptOptions = {
    icon: $r('app.media.app_icon'),
    tip: 'Image not ready for screenshot',
    marginType: MarginType.DEFAULT_MARGIN,
    actionText: 'Retry',
    marginTop: 80,
    isShown: false
  };

  @State imageReady: boolean = false;

  build() {
    Column() {
      if (this.imageReady) {
        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
          .onClick(() => {
            this.takeScreenshot();
          });
      } else {
        ExceptionPrompt({
          options: this.options,
          onTipClick: () => {
            // Handle tip click
          },
          onActionTextClick: () => {
            this.checkImageReady();
          }
        });
      }
    }
    .width('100%')
    .height('100%')
    .onAppear(() => {
      this.checkImageReady();
    });
  }

  private checkImageReady() {
    setTimeout(() => {
      this.imageReady = true;
      this.options.isShown = false;
    }, 2000);
  }

  private takeScreenshot() {
    try {
      if (!this.imageReady) {
        throw new Error('Image is not ready for screenshot');
      }
      console.log('Screenshot captured successfully');
    } catch (error) {
      this.options.isShown = true;
      console.error('Screenshot error:', error.message);
    }
  }
}

