@Entry
@Component
struct FilterSwitchingApp {
  @State selectedFilter: string = 'All';
  @State items: string[] = ['Apple', 'Banana', 'Orange', 'Grapes', 'Mango', 'Pineapple', 'Strawberry', 'Watermelon', 'Cherry', 'Blueberry'];
  @State filteredItems: string[] = [];

  private applyFilter() {
    if (this.selectedFilter === 'All') {
      this.filteredItems = [...this.items];
    } else if (this.selectedFilter === 'Fruits') {
      this.filteredItems = this.items.filter(item => ['Apple', 'Banana', 'Orange', 'Grapes', 'Mango'].includes(item));
    } else if (this.selectedFilter === 'Berries') {
      this.filteredItems = this.items.filter(item => ['Strawberry', 'Watermelon', 'Cherry', 'Blueberry'].includes(item));
    }
  }

  build() {
    Column({ space: 10 }) {
      // Filter Selection UI
      Row({ space: 10 }) {
        Button('All')
          .onClick(() => {
            this.selectedFilter = 'All';
            this.applyFilter();
          })
          .backgroundColor(this.selectedFilter === 'All' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1)
          .margin(5)

        Button('Fruits')
          .onClick(() => {
            this.selectedFilter = 'Fruits';
            this.applyFilter();
          })
          .backgroundColor(this.selectedFilter === 'Fruits' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1)
          .margin(5)

        Button('Berries')
          .onClick(() => {
            this.selectedFilter = 'Berries';
            this.applyFilter();
          })
          .backgroundColor(this.selectedFilter === 'Berries' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1)
          .margin(5)
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .padding(10)

      // Display Filtered Items
      if (this.filteredItems.length > 0) {
        List() {
          ForEach(this.filteredItems, (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(18)
                .padding(12);
            }
          }, (item: string) => item);
        }
      } else {
        Text('No items match the filter')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .onAppear(() => {
      this.applyFilter();
    });
  }
}

