struct ColorChangingTextApp {
  @State text: string = ''
  @State textColor: Color = Color.Black

  build() {
    Column() {
      // Text Input Field
      TextInput({ placeholder: 'Type something...' })
        .width('100%')
        .height(50)
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .fontColor(this.textColor)
        .onChange((value: string) => {
          this.text = value
          // Change text color based on input length
          if (value.length > 0) {
            this.textColor = Color.Red
          } else {
            this.textColor = Color.Black
          }
        })

      // Display the current text color
      if (this.text.length > 0) {
        Text(`Current Text Color: ${this.textColor}`)
          .fontSize(16)
          .margin({ top: 20 })
          .fontColor(this.textColor)
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White)
  }
}

