@Entry
@Component
struct FilterOptionSelection {
  @State selectedFilter: string = 'All';
  @State searchText: string = '';
  @State items: string[] = ['Apple', 'Banana', 'Cherry', 'Date', 'Fig', 'Grape', 'Kiwi'];
  @State filteredItems: string[] = this.items;

  private applyFilters() {
    this.filteredItems = this.items.filter(item => {
      const matchesSearch = item.toLowerCase().includes(this.searchText.toLowerCase());
      const matchesFilter = this.selectedFilter === 'All' ||
                          (this.selectedFilter === 'A-C' && ['Apple', 'Banana', 'Cherry'].includes(item)) ||
                          (this.selectedFilter === 'D-G' && ['Date', 'Fig', 'Grape'].includes(item)) ||
                          (this.selectedFilter === 'H-K' && ['Kiwi'].includes(item));
      return matchesSearch && matchesFilter;
    });
  }

  build() {
    Column({ space: 10 }) {
      // Search Input
      TextInput({ placeholder: 'Search items...' })
        .width('90%')
        .height(50)
        .margin(10)
        .onChange((value: string) => {
          this.searchText = value;
          this.applyFilters();
        });

      // Filter Buttons
      Row({ space: 10 }) {
        Button('All')
          .onClick(() => {
            this.selectedFilter = 'All';
            this.applyFilters();
          })
          .backgroundColor(this.selectedFilter === 'All' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1)

        Button('A-C')
          .onClick(() => {
            this.selectedFilter = 'A-C';
            this.applyFilters();
          })
          .backgroundColor(this.selectedFilter === 'A-C' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1)

        Button('D-G')
          .onClick(() => {
            this.selectedFilter = 'D-G';
            this.applyFilters();
          })
          .backgroundColor(this.selectedFilter === 'D-G' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1)

        Button('H-K')
          .onClick(() => {
            this.selectedFilter = 'H-K';
            this.applyFilters();
          })
          .backgroundColor(this.selectedFilter === 'H-K' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1)
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .padding(10)

      // Filtered Results
      if (this.filteredItems.length > 0) {
        List() {
          ForEach(this.filteredItems, (item: string) => {
            ListItem() {
              Row() {
                Image($r('app.media.app_icon'))
                  .width(30)
                  .height(30)
                  .margin({ right: 10 });
                Text(item)
                  .fontSize(18);
              }
              .width('100%')
              .padding(10)
            }
          })
        }
        .width('100%')
        .height('70%')
      } else {
        Column() {
          Image($r('app.media.app_icon'))
            .width(100)
            .height(100)
            .margin({ bottom: 20 });
          Text('No items match your filters')
            .fontSize(18)
            .fontColor('#666');
        }
        .width('100%')
        .height('70%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff')
    .onAppear(() => {
      this.applyFilters();
    })
  }
}

