    this.fetchData();
  }

  fetchData() {
    setTimeout(() => {
      this.items = [
        new Item(1, 'Item 1', 'app_icon', 'Description for Item 1.'),
        new Item(2, 'Item 2', 'app_icon', 'Description for Item 2.'),
        new Item(3, 'Item 3', 'app_icon', 'Description for Item 3.')
      ];
      this.isLoading = false;
    }, 2000);
  }

  build() {
