      if (this.selectedOption) {
        Text(this.selectedOption.message)
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
          .width('80%')
          .textAlign(TextAlign.Center);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
    .padding(20);
  }
}

