import { matrix4 } from '@kit.ArkUI';

@Entry
@Component
struct AdvancedZoomControls {
  @State zoomLevel: number = 1.0;
  @State rotationAngle: number = 0;
  @State translateX: number = 0;
  @State translateY: number = 0;

  private getTransformMatrix() {
    return matrix4.identity()
      .translate({ x: this.translateX, y: this.translateY, z: 0 })
      .rotate({ angle: this.rotationAngle, x: 0, y: 0, z: 1 })
      .scale({ x: this.zoomLevel, y: this.zoomLevel, z: 1 });
  }

  build() {
    Column({ space: 20 }) {
      Text('Advanced Zoom Controls')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Stack() {
        Image($r('app.media.app_icon'))
          .width(200)
          .height(200)
          .transform(this.getTransformMatrix());
      }
      .width('100%')
      .height(300)
      .border({ width: 1, color: Color.Gray });

      Slider({
        value: this.zoomLevel,
        min: 0.5,
        max: 3.0,
        step: 0.1,
        style: SliderStyle.OutSet
      })
        .onChange((value: number) => {
          this.zoomLevel = value;
        })
        .margin({ top: 20 });

      Row({ space: 10 }) {
        Button('Rotate +')
          .onClick(() => {
            this.rotationAngle += 15;
          });
        Button('Rotate -')
          .onClick(() => {
            this.rotationAngle -= 15;
          });
      }

      Row({ space: 10 }) {
        Button('Left')
          .onClick(() => {
            this.translateX -= 10;
          });
        Button('Right')
          .onClick(() => {
            this.translateX += 10;
          });
        Button('Up')
          .onClick(() => {
            this.translateY -= 10;
          });
        Button('Down')
          .onClick(() => {
            this.translateY += 10;
          });
      }

      Button('Reset')
        .onClick(() => {
          this.zoomLevel = 1.0;
          this.rotationAngle = 0;
          this.translateX = 0;
          this.translateY = 0;
        })
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White);
  }
}

@Entry
@Component
struct FilterDataBindingApp {
  @State items: string[] = ['Apple', 'Banana', 'Orange', 'Grapes', 'Mango', 'Pineapple', 'Strawberry', 'Watermelon', 'Cherry', 'Blueberry'];
  @State filteredItems: string[] = [];
  @State searchText: string = '';
  @State selectedFilter: string = 'All';

  private applyFilters(): void {
    this.filteredItems = this.items.filter(item => {
      const matchesSearch = item.toLowerCase().includes(this.searchText.toLowerCase());
      const matchesFilter = this.selectedFilter === 'All' ||
                          (this.selectedFilter === 'Fruits' && ['Apple', 'Banana', 'Orange', 'Grapes', 'Mango', 'Pineapple'].includes(item)) ||
                          (this.selectedFilter === 'Berries' && ['Strawberry', 'Cherry', 'Blueberry'].includes(item));
      return matchesSearch && matchesFilter;
    });
  }

  build() {
    Column({ space: 10 }) {
      // Search Input
      TextInput({ placeholder: 'Search items...', text: this.searchText })
        .width('90%')
        .height(50)
        .margin(10)
        .onChange((value: string) => {
          this.searchText = value;
          this.applyFilters();
        });

      // Filter Buttons
      Row({ space: 10 }) {
        Button('All')
          .onClick(() => {
            this.selectedFilter = 'All';
            this.applyFilters();
          })
          .backgroundColor(this.selectedFilter === 'All' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1);

        Button('Fruits')
          .onClick(() => {
            this.selectedFilter = 'Fruits';
            this.applyFilters();
          })
          .backgroundColor(this.selectedFilter === 'Fruits' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1);

        Button('Berries')
          .onClick(() => {
            this.selectedFilter = 'Berries';
            this.applyFilters();
          })
          .backgroundColor(this.selectedFilter === 'Berries' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1);
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .padding(10);

      // Filtered Results
      if (this.filteredItems.length > 0) {
        List() {
          ForEach(this.filteredItems, (item: string) => {
            ListItem() {
              Row() {
                Image($r('app.media.app_icon'))
                  .width(30)
                  .height(30)
                  .margin({ right: 10 });
                Text(item)
                  .fontSize(18);
              }
              .width('100%')
              .padding(10);
            }
          });
        }
        .width('100%')
        .height('70%');
      } else {
        Column() {
          Image($r('app.media.app_icon'))
            .width(100)
            .height(100)
            .margin({ bottom: 20 });
          Text('No items match your filters')
            .fontSize(18)
            .fontColor('#666');
        }
        .width('100%')
        .height('70%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff')
    .onAppear(() => {
      this.applyFilters();
    });
  }
}

