@Entry
@Component
struct ColorSelectionApp {
  @State selectedColors: string[] = []
  @State favoriteColors: string[] = []
  private colors: string[] = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FF00FF', '#FFA500']

  build() {
    Column() {
      // Display selected colors
      Text('Selected Colors:')
        .fontSize(20)
        .margin({ bottom: 10 })

      Flex({ wrap: FlexWrap.Wrap, justifyContent: FlexAlign.SpaceAround }) {
        ForEach(this.selectedColors, (color: string) => {
          Row()
            .width(50)
            .height(50)
            .backgroundColor(color)
            .borderRadius(25)
            .margin(5)
        })
      }
      .margin({ bottom: 20 })

      // Display favorite colors
      Text('Favorite Colors:')
        .fontSize(20)
        .margin({ bottom: 10 })

      Flex({ wrap: FlexWrap.Wrap, justifyContent: FlexAlign.SpaceAround }) {
        ForEach(this.favoriteColors, (color: string) => {
          Row()
            .width(50)
            .height(50)
            .backgroundColor(color)
            .borderRadius(25)
            .margin(5)
        })
      }
      .margin({ bottom: 20 })

      // Color options
      Flex({ wrap: FlexWrap.Wrap, justifyContent: FlexAlign.SpaceAround }) {
        ForEach(this.colors, (color: string) => {
          Button() {
            Row()
              .width(50)
              .height(50)
              .backgroundColor(color)
              .borderRadius(25)
          }
          .width(50)
          .height(50)
          .onClick(() => {
            if (this.selectedColors.includes(color)) {
              this.selectedColors = this.selectedColors.filter(c => c !== color)
            } else {
              this.selectedColors = [...this.selectedColors, color]
            }
          })
          .onTouch((event: TouchEvent) => {
            if (event.timestamp > 1000) {
              if (this.favoriteColors.includes(color)) {
                this.favoriteColors = this.favoriteColors.filter(c => c !== color)
              } else {
                this.favoriteColors = [...this.favoriteColors, color]
              }
            }
          })
          .margin(5)
        })
      }
    }
    .padding(20)
    .backgroundColor('#FFFFFF')
    .width('100%')
    .height('100%')
  }
}

