  @State tasks: Array<Task> = []
  @State newTitle: string = ''
  @State newDescription: string = ''

  build() {
    Column() {
      TextInput({ placeholder: 'Enter task title' })
        .onChange((value: string) => {
          this.newTitle = value
        })
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter task description' })
        .onChange((value: string) => {
          this.newDescription = value
        })
        .margin({ bottom: 20 })

      Button('Add Task')
        .onClick(() => {
          if (this.newTitle && this.newDescription) {
            this.tasks.push(new Task(this.newTitle, this.newDescription, false))
            this.newTitle = ''
            this.newDescription = ''
          }
        })
        .margin({ bottom: 20 })

      ForEach(this.tasks, (task: Task, index: number) => {
        Row() {
          Column() {
            Text(task.title)
              .fontSize(16)
              .fontWeight(FontWeight.Bold)
              .margin({ bottom: 5 })

            Text(task.description)
              .fontSize(14)
              .opacity(0.7)
          }
          .margin({ right: 10 })

          Button() {
            Image($r('app.media.app_icon'))
              .width(20)
              .height(20)
          }
          .onClick(() => {
            this.tasks[index].completed = !this.tasks[index].completed
          })
          .margin({ right: 10 })

          Button() {
            Image($r('app.media.app_icon'))
              .width(20)
              .height(20)
          }
          .onClick(() => {
            this.tasks.splice(index, 1)
          })
        }
        .margin({ top: 10 })
        .padding(10)
        .borderRadius(5)
        .backgroundColor(task.completed ? '#e0e0e0' : '#ffffff')
      })
    }
    .padding(20)
  }
}

class Task {
  title: string
  description: string
  completed: boolean

  constructor(title: string, description: string, completed: boolean) {
    this.title = title
    this.description = description
    this.completed = completed
  }
}

@Entry
@Component
struct ColorSelectionApp {
  private colors: ColorOption[] = [
    { name: 'Red', value: '#FF0000' },
    { name: 'Blue', value: '#0000FF' },
    { name: 'Green', value: '#00FF00' },
    { name: 'Yellow', value: '#FFFF00' },
    { name: 'Purple', value: '#800080' },
    { name: 'Orange', value: '#FFA500' }
  ]

  @State selectedColor: string = ''
  @State showMessage: boolean = false

  build() {
    Column() {
      Text('Select Your Color')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 })

      Grid() {
        ForEach(this.colors, (color: ColorOption) => {
          GridItem() {
            Column() {
              Row()
                .width(80)
                .height(80)
                .backgroundColor(color.value)
                .borderRadius(40)
                .border({
                  width: this.selectedColor === color.value ? 4 : 0,
                  color: '#000000'
                })
                .margin({ bottom: 8 })

              Text(color.name)
                .fontSize(16)
                .fontColor(this.selectedColor === color.value ? color.value : '#000000')
            }
            .onClick(() => {
              this.selectedColor = color.value
            })
          }
        })
      }
      .columnsTemplate('1fr 1fr 1fr')
      .rowsGap(20)
      .columnsGap(20)
      .padding(20)

      Button('Confirm')
        .width(200)
        .height(50)
        .backgroundColor('#007BFF')
        .borderRadius(8)
        .onClick(() => {
          if (this.selectedColor) {
            this.showMessage = true
          }
        })
        .margin({ top: 20 })

      if (this.showMessage && this.selectedColor) {
        Row() {
          Column() {
            Text('Selected Color:')
              .fontSize(18)
              .margin({ bottom: 8 })

            Row()
              .width(40)
              .height(40)
              .backgroundColor(this.selectedColor)
              .borderRadius(20)
              .margin({ bottom: 8 })

            Text(this.colors.find((c: ColorOption) => c.value === this.selectedColor)?.name || '')
              .fontSize(20)
              .fontWeight(FontWeight.Medium)
              .fontColor(this.selectedColor)
          }
          .padding(20)
          .backgroundColor('#F5F5F5')
          .borderRadius(12)
        }
        .margin({ top: 40 })
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16)
  }
}

