@Entry
@Component
struct TodoList {
  @State tasks: Array<TaskModel> = []
  @State newTask: string = ''

  build() {
    Column() {
      TextInput({ placeholder: 'Enter a new task' })
        .onChange((value: string) => this.newTask = value)
        .margin({ bottom: 20 })

      Button('Add Task')
        .onClick(() => {
          if (this.newTask) {
            this.tasks.push(new TaskModel(Date.now(), this.newTask, false))
            this.newTask = ''
          }
        })
        .margin({ bottom: 20 })

      Button('Clear Completed')
        .onClick(() => {
          this.tasks = this.tasks.filter(task => !task.isCompleted)
        })
        .margin({ bottom: 20 })

      List({ space: 10 }) {
        ForEach(this.tasks, (task: TaskModel, index: number) => {
          ListItem() {
            Row() {
              Checkbox()
                .select(task.isCompleted)
                .onChange((value) => {
                  task.isCompleted = value
                })

              Text(task.taskContent)
                .fontSize(20)
                .margin({ left: 10 })
                .decoration({
                  type: task.isCompleted ? TextDecorationType.LineThrough : TextDecorationType.None
                })

              Blank()

              Button() {
                Image($r('app.media.app_icon'))
                  .fillColor(Color.White)
                  .width(20)
              }
              .width(40)
              .height(40)
              .type(ButtonType.Circle)
              .backgroundColor(Color.Red)
              .margin(5)
              .onClick(() => {
                this.tasks.splice(index, 1)
              })
            }
            .justifyContent(FlexAlign.SpaceBetween)
            .width('95%')
            .padding(20)
            .borderRadius(15)
            .shadow({ radius: 6, color: '#1F000000', offsetX: 2, offsetY: 4 })
          }
          .swipeAction({ end: this.deleteButton(index) })
        })
      }
      .width('100%')
      .height('70%')
      .alignListItem(ListItemAlign.Center)
      .scrollBarColor(Color.Transparent)
    }
    .padding(20)
  }

  @Builder
  deleteButton(index: number) {
    Button() {
      Image($r('app.media.app_icon'))
        .fillColor(Color.White)
        .width(20)
    }
    .width(40)
    .height(40)
    .type(ButtonType.Circle)
    .backgroundColor(Color.Red)
    .margin(5)
    .onClick(() => {
      this.tasks.splice(index, 1)
    })
  }
}

class TaskModel {
  taskId: number
  taskContent: string
  isCompleted: boolean

  constructor(taskId: number, taskContent: string, isCompleted: boolean) {
    this.taskId = taskId
    this.taskContent = taskContent
    this.isCompleted = isCompleted
  }
}

@Entry
@Component
struct MultiRenderLoopConfig {
  @State private renderCount: number = 0;
  @State private isRendering: boolean = false;
  @State private loopSpeed: number = 100; // Default speed in milliseconds

  private startRenderLoop() {
    if (this.isRendering) return;

    this.isRendering = true;
    this.renderCount = 0;

    const renderLoop = () => {
      if (this.renderCount < 10) {
        this.renderCount++;
        setTimeout(() => {
          renderLoop();
        }, this.loopSpeed); // Use the configured loop speed
      } else {
        this.isRendering = false;
      }
    };

    renderLoop();
  }

  private updateLoopSpeed(speed: number) {
    this.loopSpeed = speed;
  }

  build() {
    Column({ space: 10 }) {
      Text(`Render Count: ${this.renderCount}`)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .textAlign(TextAlign.Center)
        .margin({ top: 20 });

      Slider({
        value: this.loopSpeed,
        min: 50,
        max: 500,
        step: 50,
        style: SliderStyle.OutSet
      })
        .onChange((value: number) => {
          this.updateLoopSpeed(value);
        })
        .width('80%')
        .margin({ top: 20 });

      Text(`Loop Speed: ${this.loopSpeed}ms`)
        .fontSize(16)
        .margin({ top: 10 });

      Button('Start Render Loop')
        .onClick(() => {
          this.startRenderLoop();
        })
        .width('80%')
        .height(50)
        .backgroundColor(Color.Blue)
        .fontColor(Color.White)
        .margin({ top: 20 });

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

