@Entry
@Component
struct FloatingActionButton {
  @State isBackgroundChanged: boolean = false;
  @State buttonColor: Color = Color.Blue;

  build() {
    Column() {
      Button()
        .width(60)
        .height(60)
        .backgroundColor(this.buttonColor)
        .borderRadius(30)
        .onClick(() => {
          this.isBackgroundChanged = !this.isBackgroundChanged;
          this.buttonColor = this.isBackgroundChanged ? Color.Red : Color.Blue;
        })
        .position({ x: '50%', y: '80%' })
        .margin(20)
        .animation({
          duration: 300,
          curve: Curve.EaseInOut
        })
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.isBackgroundChanged ? Color.Green : Color.White)
  }
}

@Entry
@Component
struct ChainAnimationList {
  private scroller: Scroller = new Scroller();
  @State items: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4', 'Item 5', 'Item 6', 'Item 7', 'Item 8', 'Item 9', 'Item 10'];

  build() {
    Column() {
      List({ space: 20, scroller: this.scroller }) {
        ForEach(this.items, (item: string, index: number) => {
          ListItem() {
            Text(item)
              .fontSize(20)
              .textAlign(TextAlign.Center)
              .backgroundColor('#95efd2')
              .width('100%')
              .height(100)
              .borderRadius(10)
              .animation({
                duration: 300,
                curve: Curve.EaseInOut,
                delay: index * 100
              })
          }
        })
      }
      .width('100%')
      .height('100%')
      .onScrollIndex((start: number, end: number) => {
        console.info(`Visible items range: ${start} to ${end}`);
      })
      .edgeEffect(EdgeEffect.Spring)

      Button('Scroll to Item 5')
        .onClick(() => {
          this.scroller.scrollToIndex(4, true);
        })
        .margin(20)

      Button('Scroll to Item 5 (No Animation)')
        .onClick(() => {
          this.scroller.scrollToIndex(4, false);
        })
        .margin(20)
    }
    .width('100%')
    .height('100%')
