@Entry
@Component
struct Component3DShaderConfig {
  @State selectedShader: string = 'default';
  @State shaderIntensity: number = 0.5;
  @State shaderColor: string = '#FF0000';
  @State shaderOpacity: number = 0.8;

  build() {
    Column({ space: 20 }) {
      // 3D Component Simulation with Shader Effects
      Stack() {
        Image($r('app.media.app_icon'))
          .width(300)
          .height(300)
          .opacity(this.shaderOpacity)
          .backgroundColor(this.shaderColor)
          .borderRadius(20)
          .overlay('rgba(0,0,0,' + (1 - this.shaderIntensity) + ')')
          .blur(this.selectedShader === 'blur' ? 10 : 0)
          .grayscale(this.selectedShader === 'edgeDetection' ? 1 : 0)
          .sepia(this.selectedShader === 'emboss' ? 0.8 : 0)
          .opacity(this.selectedShader === 'sharpen' ? 1.5 : this.shaderOpacity)
      }
      .width('100%')
      .height(300)
      .margin({ bottom: 20 })

      // Shader Selection Dropdown
      Select([
        { value: 'default' },
        { value: 'blur' },
        { value: 'sharpen' },
        { value: 'edgeDetection' },
        { value: 'emboss' }
      ])
        .selected(0)
        .onSelect((index: number, value: string) => {
          this.selectedShader = value;
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Shader Parameter Controls
      Text('Shader Parameters')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)

      Row() {
        Text('Intensity:')
        Slider({
          value: this.shaderIntensity,
          min: 0,
          max: 1,
          step: 0.1
        })
        .onChange((value: number) => {
          this.shaderIntensity = value;
        })
        .layoutWeight(1)
      }

      Row() {
        Text('Color:')
        Button(this.shaderColor)
          .onClick(() => {
            this.shaderColor = this.shaderColor === '#FF0000' ? '#00FF00' : '#FF0000';
          })
          .backgroundColor(this.shaderColor)
          .width(100)
      }

      Row() {
        Text('Opacity:')
        Slider({
          value: this.shaderOpacity,
          min: 0.1,
          max: 1,
          step: 0.1
        })
        .onChange((value: number) => {
          this.shaderOpacity = value;
        })
        .layoutWeight(1)
      }

      // Display Selected Shader
      Text(`Selected Shader: ${this.selectedShader}`)
        .fontSize(18)
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5')
  }
}

