@Entry
@Component
struct ImageGalleryApp {
  @State private selectedImage: string = '';
  @State private images: string[] = [];
  @State private errorMessage: string = '';

  async pickImage() {
    try {
      const image = await this.simulateImageSelection();
      if (image) {
        this.selectedImage = image;
        this.errorMessage = '';
      } else {
        this.errorMessage = 'No image selected.';
      }
    } catch (error) {
      this.errorMessage = 'Failed to select image. Please try again.';
    }
  }

  simulateImageSelection(): Promise<string> {
    return new Promise((resolve) => {
      setTimeout(() => {
        resolve($r('app.media.app_icon').id.toString());
      }, 1000);
    });
  }

  build() {
    Column() {
      if (this.selectedImage) {
        Image($r('app.media.app_icon'))
          .width(200)
          .height(200)
          .objectFit(ImageFit.Cover)
          .borderRadius(10)
          .margin({ bottom: 20 });

        Button('Share Image')
          .onClick(() => {
            console.log('Sharing image:', this.selectedImage);
          })
          .padding(10)
          .backgroundColor(Color.Blue)
          .fontColor(Color.White)
          .borderRadius(5)
          .margin({ bottom: 20 });
      } else {
        Text('No image selected')
          .fontSize(18)
          .fontColor('#666666')
          .margin({ bottom: 20 });
      }

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(16)
          .fontColor(Color.Red)
          .margin({ bottom: 20 });
      }

      Button('Select Image')
        .onClick(() => this.pickImage())
        .padding(10)
        .backgroundColor(Color.Blue)
        .fontColor(Color.White)
        .borderRadius(5);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }
}

@Entry
@Component
struct DataFetchingApp {
    @State isLoading: boolean = false
    @State data: string[] = []

    aboutToAppear() {
        this.fetchData()
    }

    private fetchData() {
        this.isLoading = true
        setTimeout(() => {
            this.data = ['Data Item 1', 'Data Item 2', 'Data Item 3']
            this.isLoading = false
        }, 2500)
    }

    build() {
        Column() {
            if (this.isLoading) {
                AnimatedSpinner()
            } else {
                List() {
                    ForEach(this.data, (item: string) => {
                        ListItem() {
                            Text(item).fontSize(30)
                        }
                    }, (item: string) => item)
                }
            }
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .backgroundColor(Color.White)
    }
}

@Component
struct AnimatedSpinner {
    @State rotation: number = 0
    private intervalID: number = -1

    aboutToAppear() {
        this.intervalID = setInterval(() => {
            this.rotation = (this.rotation + 10) % 360
        }, 50)
    }

    aboutToDisappear() {
        if (this.intervalID !== -1) {
            clearInterval(this.intervalID)
        }
    }

    build() {
        Column() {
            Stack() {
                Circle()
                    .width(100)
                    .height(100)
                    .stroke(Color.Blue)
                    .strokeWidth(10)
                    .strokeDashArray([10, 20])
                    .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })
            }
            .width(100)
            .height(100)
        }
        .justifyContent(FlexAlign.Center)
        .backgroundColor(Color.White)
        .width('100%')
        .height('100%')
    }
}

@Entry
@Component
struct NavigationDrawerApp {
  @State isDrawerOpen: boolean = false;
  @State selectedScreenIndex: number = 0;
  @State dynamicContent: string = 'Default Content';
  @State formInput: string = '';

  build() {
    Row() {
      // Main Content Area
      Column() {
        this.ScreenContent();
        this.DrawerButton();
      }
      .layoutWeight(1);

      // Drawer Panel
      Panel(this.isDrawerOpen) {
        Column() {
          this.NavItem('Home', 0);
          this.NavItem('Profile', 1);
          this.NavItem('Form', 2);
        }
        .width('80%')
        .height('100%')
        .backgroundColor(Color.White);
      }
      .mode(PanelMode.Mini)
      .type(PanelType.Temporary)
      .dragBar(false);
    }
    .width('100%')
    .height('100%');
  }

  @Builder DrawerButton() {
    Button('Toggle Drawer')
      .onClick(() => {
        this.isDrawerOpen = !this.isDrawerOpen;
      });
  }

  @Builder NavItem(label: string, index: number) {
    Text(label)
      .fontSize(20)
      .margin(10)
      .onClick(() => {
        this.selectedScreenIndex = index;
        this.isDrawerOpen = false;
        this.loadDynamicContent(index);
      });
  }

  @Builder ScreenContent() {
    if (this.selectedScreenIndex === 0) {
      this.HomeScreen();
    } else if (this.selectedScreenIndex === 1) {
      this.ProfileScreen();
    } else {
      this.FormScreen();
    }
  }

  @Builder HomeScreen() {
    Column() {
      Text('Home Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin(16);
      Text(this.dynamicContent)
        .fontSize(16)
        .margin(16);
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(16);
    }
    .width('100%')
    .height('100%');
  }

  @Builder ProfileScreen() {
    Column() {
      Text('Profile Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin(16);
      Text(this.dynamicContent)
        .fontSize(16)
        .margin(16);
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(16);
    }
    .width('100%')
    .height('100%');
  }

  @Builder FormScreen() {
    Column() {
      Text('Form Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin(16);
      TextInput({ placeholder: 'Enter text here' })
        .width('80%')
        .height(40)
        .margin(16)
        .onChange((value: string) => {
          this.formInput = value;
        });
      Text(`Input: ${this.formInput}`)
        .fontSize(16)
        .margin(16);
      Button('Submit')
        .margin(16)
        .onClick(() => {
          this.dynamicContent = `Submitted: ${this.formInput}`;
          this.formInput = '';
        });
    }
    .width('100%')
    .height('100%');
  }

  loadDynamicContent(index: number) {
    if (index === 0) {
      this.dynamicContent = 'Dynamic Content for Home Screen';
    } else if (index === 1) {
      this.dynamicContent = 'Dynamic Content for Profile Screen';
    } else {
      this.dynamicContent = 'Dynamic Content for Form Screen';
    }
  }
}

@Entry
@Component
struct LoginScreen {
  @State username: string = ''
  @State password: string = ''
  @State loginMessage: string = ''

  validateInput(): boolean {
    if (this.username && this.password) {
      this.loginMessage = 'Login successful!'
      return true
    } else {
      this.loginMessage = 'Please enter both username and password.'
      return false
    }
  }

  build() {
    Column() {
      // Username Label and Input
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your username', text: this.username })
        .onChange((value: string) => {
          this.username = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Password Label and Input
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Login Button
      Button('Login')
        .onClick(() => {
          this.validateInput()
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      // Login Message
      if (this.loginMessage) {
        Text(this.loginMessage)
          .fontSize(16)
          .margin({ top: 20 })
          .fontColor(this.loginMessage === 'Login successful!' ? Color.Green : Color.Red)
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

