@Entry
@Component
struct DynamicFilterApp {
  @State selectedFilter: string = 'All';
  @State filterText: string = '';
  @State items: string[] = ['Apple', 'Banana', 'Orange', 'Grapes', 'Mango', 'Pineapple', 'Strawberry', 'Watermelon', 'Cherry', 'Blueberry'];
  @State filteredItems: string[] = [];

  private applyFilter() {
    if (this.selectedFilter === 'All' && this.filterText.trim() === '') {
      this.filteredItems = [...this.items];
    } else {
      this.filteredItems = this.items.filter(item =>
        (this.selectedFilter === 'All' || item.toLowerCase().includes(this.selectedFilter.toLowerCase())) &&
        (this.filterText.trim() === '' || item.toLowerCase().includes(this.filterText.toLowerCase()))
      );
    }
  }

  build() {
    Column({ space: 10 }) {
      // Filter Selection UI
      Row({ space: 10 }) {
        Button('All')
          .onClick(() => {
            this.selectedFilter = 'All';
            this.applyFilter();
          })
          .backgroundColor(this.selectedFilter === 'All' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1)

        Button('Fruit')
          .onClick(() => {
            this.selectedFilter = 'Fruit';
            this.applyFilter();
          })
          .backgroundColor(this.selectedFilter === 'Fruit' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1)

        Button('Berry')
          .onClick(() => {
            this.selectedFilter = 'Berry';
            this.applyFilter();
          })
          .backgroundColor(this.selectedFilter === 'Berry' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1)
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .padding(10)

      // Search Bar
      TextInput({ placeholder: 'Search items...', text: this.filterText })
        .width('90%')
        .onChange((value: string) => {
          this.filterText = value;
          this.applyFilter();
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      // Display Filtered Items
      if (this.filteredItems.length > 0) {
        List() {
          ForEach(this.filteredItems, (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(18)
                .padding(12);
            }
          }, (item: string) => item);
        }
      } else {
        Text('No items match the filter')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .onAppear(() => {
      this.applyFilter();
    });
  }
}

