@Entry
@Component
struct Main {
  @State sliderValue: number = 50;

  build() {
    Column() {
      Slider({
        min: 0,
        max: 100,
        value: this.sliderValue
      })
      .width("80%")
      .onChange((value: number) => {
        this.sliderValue = value;
      })

      Row({ space: 20 }) {
        Button('Decrease')
          .onClick(() => {
            if (this.sliderValue > 0) {
              this.sliderValue -= 10;
            }
          })
          .backgroundColor('#FF0000')
          .fontColor('#FFFFFF')

        Button('Increase')
          .onClick(() => {
            if (this.sliderValue < 100) {
              this.sliderValue += 10;
            }
          })
          .backgroundColor('#00FF00')
          .fontColor('#FFFFFF')
      }
      .margin(20)

      Text(`Slider Value: ${this.sliderValue}`)
        .fontSize(18)
        .padding(10)
    }
    .width("100%")
    .height("100%")
    .padding(20)
    .backgroundColor("#ffffff")
  }
}

