import componentSnapshot from '@ohos.arkui.componentSnapshot';

@Entry
@Component
struct SnapshotOptionsExample {
  @State private imageSrc: string = '';
  @State private isSnapshotTaken: boolean = false;

  build() {
    Column() {
      Text('Snapshot Options Example')
        .fontSize(20)
        .margin(10);

      Button('Take Snapshot')
        .onClick(() => {
          this.takeSnapshot();
        })
        .margin(10);

      if (this.isSnapshotTaken) {
        Image(this.imageSrc)
          .width(200)
          .height(200)
          .margin(10)
          .border({ width: 1, color: Color.Black });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }

  private takeSnapshot() {
    const snapshotOptions: componentSnapshot.SnapshotOptions = {
      waitUntilRenderFinished: true
    };

    setTimeout(() => {
      this.imageSrc = 'app.media.app_icon';
      this.isSnapshotTaken = true;
    }, 1000);
  }
}

@Entry
@Component
struct FilterOptionPersistenceApp {
  @State selectedFilter: string = 'All';
  @State items: string[] = ['Apple', 'Banana', 'Orange', 'Grapes', 'Mango', 'Pineapple', 'Strawberry', 'Watermelon', 'Cherry', 'Blueberry'];

  saveFilter(filter: string) {
    // Simulate saving the filter option to persistent storage
    console.log(`Filter saved: ${filter}`);
  }

  loadFilter() {
    // Simulate loading the filter option from persistent storage
    const savedFilter = 'All'; // This could be retrieved from storage
    this.selectedFilter = savedFilter;
  }

  build() {
    Column() {
      // Filter Selection UI
      Row({ space: 10 }) {
        Button('All')
          .onClick(() => {
            this.selectedFilter = 'All';
            this.saveFilter('All');
          })
          .backgroundColor(this.selectedFilter === 'All' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1)

        Button('Fruits')
          .onClick(() => {
            this.selectedFilter = 'Fruits';
            this.saveFilter('Fruits');
          })
          .backgroundColor(this.selectedFilter === 'Fruits' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1)

        Button('Berries')
          .onClick(() => {
            this.selectedFilter = 'Berries';
            this.saveFilter('Berries');
          })
          .backgroundColor(this.selectedFilter === 'Berries' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1)
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .padding(10)

      // Displayed Content Based on Selected Filter
      List() {
        ForEach(this.items, (item: string) => {
          if (this.selectedFilter === 'All' ||
              (this.selectedFilter === 'Fruits' && (item === 'Apple' || item === 'Banana' || item === 'Orange' || item === 'Grapes' || item === 'Mango' || item === 'Pineapple')) ||
              (this.selectedFilter === 'Berries' && (item === 'Strawberry' || item === 'Watermelon' || item === 'Cherry' || item === 'Blueberry'))) {
            ListItem() {
              Row() {
                Image($r('app.media.app_icon'))
                  .width(30)
                  .height(30)
                  .margin({ right: 10 });
                Text(item)
                  .fontSize(18);
              }
              .width('100%')
              .padding(10)
            }
          }
        })
      }
      .width('100%')
      .height('70%')
      .backgroundColor('#f5f5f5')
    }
    .width('100%')
    .height('100%')
    .onAppear(() => {
      this.loadFilter();
    })
  }
}

