            this.isButton2Active = false;
            this.isButton3Active = false;
          }
        })
        .margin(10);

      Button('Button 2')
        .backgroundColor(this.isButton2Active ? Color.Green : Color.Blue)
        .onClick(() => {
          this.isButton2Active = !this.isButton2Active;
          if (this.isButton2Active) {
            this.isButton1Active = false;
            this.isButton3Active = false;
          }
        })
        .margin(10);

      Button('Button 3')
        .backgroundColor(this.isButton3Active ? Color.Green : Color.Blue)
        .onClick(() => {
          this.isButton3Active = !this.isButton3Active;
          if (this.isButton3Active) {
            this.isButton1Active = false;
            this.isButton2Active = false;
          }
        })
        .margin(10);
    }
