import promptAction from '@ohos.promptAction'

@Entry
@Component
struct AgeCategoryApp {
  @State age: string = ''
  @State category: string = ''
  @State showCategory: boolean = false

  build() {
    Column() {
      Text('Age Categorizer')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 })

      Column() {
        Text('Enter your age:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your age' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.age = value
          })
      }

      Button('Categorize')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.age) {
            const ageNum = parseInt(this.age)
            if (ageNum < 13) {
              this.category = 'Child'
            } else if (ageNum >= 13 && ageNum < 20) {
              this.category = 'Teenager'
            } else {
              this.category = 'Adult'
            }
            this.showCategory = true
          } else {
            promptAction.showToast({
              message: 'Please enter your age'
            })
          }
        })

      if (this.showCategory) {
        Text(`Category: ${this.category}`)
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
  }
}

