@Entry
@Component
struct LoginScreen {
  @State email: string = '';
  @State password: string = '';
  @State loginMessage: string = '';
  @State isSuccess: boolean = false;

  validateCredentials(): boolean {
    if (this.email && this.password) {
      this.loginMessage = 'Login successful!';
      this.isSuccess = true;
      return true;
    } else {
      this.loginMessage = 'Please fill in all fields';
      this.isSuccess = false;
      return false;
    }
  }

  build() {
    Column() {
      // Email Input
      Text('Email')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your email', text: this.email })
        .onChange((value: string) => {
          this.email = value;
        })
        .width('80%')
        .height(40)
        .margin({ bottom: 20 })
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 });

      // Password Input
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value;
        })
        .width('80%')
        .height(40)
        .margin({ bottom: 20 })
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 });

      // Login Button
      Button('Login')
        .onClick(() => {
          if (this.validateCredentials()) {
            console.info('Login successful!');
          } else {
            console.error('Login failed!');
          }
        })
        .width('60%')
        .height(50)
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White);

      // Login Message
      if (this.loginMessage) {
        Text(this.loginMessage)
          .fontSize(16)
          .fontColor(this.isSuccess ? Color.Green : Color.Red)
          .margin({ top: 20 });
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .backgroundColor('#FFFFFF');
  }
}

