interface Message {
  user: string;
  text: string;
  timestamp: string;
  avatar: Resource;
}

@Entry
@Component
struct ChatApp {
  @State messages: Array<Message> = [
    {
      user: 'Alice',
      text: 'Hello everyone!',
      timestamp: '10:00 AM',
      avatar: $r('app.media.app_icon')
    },
    {
      user: 'Bob',
      text: 'Hi Alice!',
      timestamp: '10:02 AM',
      avatar: $r('app.media.app_icon')
    },
    {
      user: 'Charlie',
      text: 'Hey guys!',
      timestamp: '10:05 AM',
      avatar: $r('app.media.app_icon')
    }
  ];

  @State newMessage: string = '';

  build() {
    Column() {
      // Chat Messages List
      List({ space: 10 }) {
        ForEach(this.messages, (message: Message) => {
          ListItem() {
            Row({ space: 10 }) {
              Image(message.avatar)
                .width(40)
                .height(40)
                .borderRadius(20)
              Column() {
                Row({ space: 5 }) {
                  Text(message.user)
                    .fontSize(16)
                    .fontWeight(FontWeight.Medium)
                  Text(message.timestamp)
                    .fontSize(12)
                    .fontColor('#666666')
                }
                Text(message.text)
                  .fontSize(14)
                  .padding(10)
                  .backgroundColor(message.user === 'You' ? '#DCF8C6' : '#ECECEC')
                  .borderRadius(10)
              }
            }
            .width('100%')
            .padding(10)
          }
        })
      }
      .layoutWeight(1)
      .width('100%')

      // Message Input and Send Button
      Row() {
        TextInput({ placeholder: 'Type a message...' })
          .width('80%')
          .height(40)
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.newMessage = value;
          })

        Button('Send')
          .width('20%')
          .height(40)
          .fontSize(16)
          .backgroundColor('#007AFF')
          .onClick(() => {
            if (this.newMessage.trim()) {
              const timestamp = new Date().toLocaleTimeString();
              this.messages.push({
                user: 'You',
                text: this.newMessage,
                timestamp: timestamp,
                avatar: $r('app.media.app_icon')
              });
              this.newMessage = '';
            } else {
              promptAction.showToast({
                message: 'Message cannot be empty'
              });
            }
          })
      }
      .width('100%')
      .padding(10)
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

