@Entry
@Component
struct LoginForm {
  @State username: string = ''
  @State password: string = ''
  @State successMessage: string = ''
  @State errorMessage: string = ''

  validateCredentials(): boolean {
    if (this.username === 'admin' && this.password === 'password123') {
      this.successMessage = 'Login successful!'
      this.errorMessage = ''
      return true
    } else {
      this.errorMessage = 'Invalid username or password'
      this.successMessage = ''
      return false
    }
  }

  build() {
    Column() {
      // Username Label and Input
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your username' })
        .onChange((value: string) => {
          this.username = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Password Label and Input
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Login Button
      Button('Login')
        .onClick(() => {
          if (this.validateCredentials()) {
            console.info(this.successMessage)
          } else {
            console.error(this.errorMessage)
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      // Success and Error Messages
      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(16)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(16)
          .fontColor(Color.Red)
          .margin({ top: 20 })
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
  }
}

@Entry
@Component
struct TodoListApp {
  @State tasks: Array<Task> = []
  @State newTask: string = ''

  build() {
    Column() {
      Text('Todo List')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter a new task', text: this.newTask })
        .onChange((value: string) => {
          this.newTask = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      Button('Add Task')
        .onClick(() => {
          if (this.newTask.trim() !== '') {
            this.tasks.push({ id: Date.now(), content: this.newTask.trim(), isCompleted: false })
            this.newTask = ''
          }
        })
        .margin({ bottom: 20 })

      ForEach(this.tasks, (task: Task, index: number) => {
        Row() {
          Checkbox()
            .select(task.isCompleted)
            .onChange((value: boolean) => {
              this.tasks[index].isCompleted = value
            })
          Text(task.content)
            .fontSize(18)
            .margin({ left: 10 })
            .decoration({ type: task.isCompleted ? TextDecorationType.LineThrough : TextDecorationType.None })
          Button('Delete')
            .onClick(() => {
              this.tasks.splice(index, 1)
            })
        }
        .width('80%')
        .margin({ bottom: 10 })
      })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

interface Task {
  id: number
  content: string
  isCompleted: boolean
}

