@Entry
@Component
struct MultiSelectList {
  @State items: Array<string> = ["Item 1", "Item 2", "Item 3", "Item 4", "Item 5"];
  @State selectedItems: Array<string> = [];
  @State multiSelectable: boolean = true;

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.items, (item: string) => {
          ListItem() {
            Row() {
              Image($r('app.media.app_icon'))
                .width(30)
                .height(30)
                .margin({ right: 10 });
              Text(item)
                .fontSize(18)
                .margin({ right: 20 });
              Checkbox({ name: item, group: 'itemGroup' })
                .select(this.selectedItems.includes(item))
                .onChange((selected: boolean) => {
                  if (selected) {
                    this.selectedItems.push(item);
                  } else {
                    this.selectedItems = this.selectedItems.filter(selectedItem => selectedItem !== item);
                  }
                });
            }
            .padding(10)
          }
        })
      }
      .width("100%")
      .height("80%")
      .multiSelectable(this.multiSelectable);

      Text(`Selected Items: ${this.selectedItems.join(", ")}`)
        .fontSize(18)
        .padding(10);
    }
    .width("100%")
    .height("100%")
    .padding(20)
    .backgroundColor("#ffffff");
  }
}

