@Entry
@Component
struct RegistrationForm {
  @State username: string = ''
  @State email: string = ''
  @State password: string = ''
  @State successMessage: string = ''
  @State errorMessage: string = ''

  validateForm(): boolean {
    if (!this.username || !this.email || !this.password) {
      this.errorMessage = 'All fields are required'
      return false
    }
    this.errorMessage = ''
    return true
  }

  build() {
    Column() {
      // Form Title
      Text('Registration')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      // Username Input
      TextInput({ placeholder: 'Enter your username' })
        .onChange((value: string) => {
          this.username = value
        })
        .margin({ bottom: 20 })

      // Email Input
      TextInput({ placeholder: 'Enter your email' })
        .onChange((value: string) => {
          this.email = value
        })
        .margin({ bottom: 20 })

      // Password Input
      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .margin({ bottom: 20 })

      // Submit Button
      Button('Submit')
        .onClick(() => {
          if (this.validateForm()) {
            this.successMessage = 'Registration successful!'
            this.username = ''
            this.email = ''
            this.password = ''
          }
        })

      // Error Message
      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ bottom: 20 })
      }

      // Success Message
      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(18)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct SnapshotErrorHandling {
  @State private errorMessage: string = '';
  @State private showError: boolean = false;

  @Builder
  CustomBuilder() {
    Column() {
      Text('Custom Builder Content')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });
    }
  }

  private handleSnapshotError(error: Error): void {
    this.errorMessage = `Snapshot Error: ${error.message}`;
    this.showError = true;
  }

  private createSnapshotFromBuilder(builder: () => void, onError: (error: Error) => void): void {
    try {
      builder();
    } catch (error) {
      if (error instanceof Error) {
        onError(error);
      } else {
        onError(new Error('An unknown error occurred'));
      }
    }
  }

  build() {
    Column() {
      Button('Create Snapshot')
        .onClick(() => {
          this.createSnapshotFromBuilder(
            this.CustomBuilder,
            (error) => this.handleSnapshotError(error)
          );
        })
        .margin({ bottom: 20 });

      if (this.showError) {
        Text(this.errorMessage)
          .fontSize(16)
          .fontColor(Color.Red)
          .margin({ top: 10 });
      }
    }
    .width('100%')
    .padding(20);
  }
}

