@Entry
@Component
struct ImageGallery {
  @State selectedImage: string = ''
  @State showDetails: boolean = false
  @State imageData: string[] = []

  async aboutToAppear() {
    this.imageData = await this.fetchImages();
  }

  async fetchImages(): Promise<string[]> {
    return new Promise((resolve) => {
      setTimeout(() => {
        resolve([
          'app.media.app_icon',
          'app.media.app_icon',
          'app.media.app_icon',
          'app.media.app_icon',
          'app.media.app_icon',
          'app.media.app_icon',
          'app.media.app_icon',
          'app.media.app_icon',
          'app.media.app_icon',
          'app.media.app_icon'
        ]);
      }, 1000);
    });
  }

  build() {
    Column() {
      if (this.showDetails) {
        Stack() {
          Image(this.selectedImage)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%')

          Button('Close')
            .onClick(() => {
              this.showDetails = false
            })
            .position({ x: 20, y: 20 })
            .backgroundColor('#FFFFFF')
            .padding({ left: 10, right: 10, top: 5, bottom: 5 })
            .borderRadius(5)
        }
      } else {
        Grid() {
          ForEach(this.imageData, (image: string) => {
            GridItem() {
              Image(image)
                .width('100%')
                .aspectRatio(1)
                .objectFit(ImageFit.Cover)
                .borderRadius(5)
                .onClick(() => {
                  this.selectedImage = image
                  this.showDetails = true
                })
            }
          })
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsGap(10)
        .columnsGap(10)
        .padding(10)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

