@Entry
@Component
struct ListItemRearrange {
  @State items: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4', 'Item 5']
  @State draggingIndex: number = -1
  @State targetIndex: number = -1

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.items, (item: string, index: number) => {
          ListItem() {
            Text(item)
              .fontSize(20)
              .width('100%')
              .height(60)
              .backgroundColor(this.draggingIndex === index ? '#e0e0e0' : '#f5f5f5')
              .borderRadius(8)
          }
          .opacity(this.draggingIndex === index ? 0.5 : 1)
        })
      }
      .onItemMove((from: number, to: number) => {
        if (from !== to) {
          const newItems = [...this.items]
          const removed = newItems[from]
          newItems.splice(from, 1)
          newItems.splice(to, 0, removed)
          this.items = newItems
        }
        return true
      })
      .width('100%')
      .height('100%')
      .divider({ strokeWidth: 1, color: '#cccccc' })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

