@Component
struct NodeTreeManipulation {
  @State private rootNode: Node = new Node("Root");
  @State private childNode1: Node = new Node("Child 1");
  @State private childNode2: Node = new Node("Child 2");

  build() {
    Column() {
      Text('Node Tree Manipulation')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Button('Add Child Node 1')
        .onClick(() => {
          this.rootNode.addChild(this.childNode1);
          console.info('Child Node 1 added to Root Node');
        })
        .margin({ bottom: 10 });

      Button('Add Child Node 2')
        .onClick(() => {
          this.rootNode.addChild(this.childNode2);
          console.info('Child Node 2 added to Root Node');
        })
        .margin({ bottom: 10 });

      Button('Remove Child Node 1')
        .onClick(() => {
          this.rootNode.removeChild(this.childNode1);
          console.info('Child Node 1 removed from Root Node');
        })
        .margin({ bottom: 10 });

      Button('Remove Child Node 2')
        .onClick(() => {
          this.rootNode.removeChild(this.childNode2);
          console.info('Child Node 2 removed from Root Node');
        })
        .margin({ bottom: 10 });

      Button('Clear All Children')
        .onClick(() => {
          this.rootNode.clearChildren();
          console.info('All children removed from Root Node');
        })
        .margin({ bottom: 10 });

      Button('Print Node Tree')
        .onClick(() => {
          this.printNodeTree(this.rootNode);
        });
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }

  private printNodeTree(node: Node, level: number = 0) {
    let indent = ' '.repeat(level * 2);
    console.info(`${indent}Node: ${node.name}`);
    node.children.forEach(child => {
      this.printNodeTree(child, level + 1);
    });
  }
}

class Node {
  name: string;
  children: Node[] = [];

  constructor(name: string) {
    this.name = name;
  }

  addChild(child: Node) {
    this.children.push(child);
  }

  removeChild(child: Node) {
    const index = this.children.indexOf(child);
    if (index !== -1) {
      this.children.splice(index, 1);
    }
  }

  clearChildren() {
    this.children = [];
  }
}

