  @State message: string = "Initial Message";

  aboutToAppear() {
    this.message = "Component is about to appear";
    console.info("Component is about to appear");
  }

  aboutToDisappear() {
    this.message = "Component is about to disappear";
    console.info("Component is about to disappear");
  }

  onPageShow() {
    this.message = "Page is now visible";
    console.info("Page is now visible");
  }

  onPageHide() {
    this.message = "Page is now hidden";
    console.info("Page is now hidden");
  }

  aboutToReuse(params: Record<string, ESObject>) {
    this.message = "Component is about to be reused";
    console.info("Component is about to be reused");
  }

  build() {
    Column() {
