@Entry
@Component
struct FieldEvaluationsWithComponent3D {
  @State private evaluationResult: string = '';
  @State private isEvaluationComplete: boolean = false;

  build() {
    Column({ space: 20 }) {
      Text('Field Evaluations with Component3D')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Flex({ direction: FlexDirection.Column, justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
        Text('3D Component for Evaluation')
          .fontSize(16)
          .fontColor('#FFFFFF')
          .backgroundColor('#000000')
          .padding(10)
          .borderRadius(5);

        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
          .margin({ top: 10 });
      }
      .width('80%')
      .height('40%')
      .backgroundColor('#333333')
      .borderRadius(10)
      .margin({ bottom: 20 });

      if (this.isEvaluationComplete) {
        Text(`Result: ${this.evaluationResult}`)
          .fontSize(18)
          .margin({ bottom: 20 });
      } else {
        Text('Running Evaluation...')
          .fontSize(18)
          .margin({ bottom: 20 });
      }

      Button('Run Evaluation')
        .width('50%')
        .height(50)
        .onClick(() => {
          this.runEvaluation();
        });
    }
    .width('100%')
    .padding(20);
  }

  runEvaluation() {
    this.isEvaluationComplete = false;
    setTimeout(() => {
      this.evaluationResult = 'Evaluation Complete: Success';
      this.isEvaluationComplete = true;
    }, 2000);
  }
}

@Entry
@Component
struct ProfileInterface {
  @State userName: string = 'John Doe'
  @State userEmail: string = 'john.doe@example.com'
  @State isEditing: boolean = false
  @State newName: string = ''
  @State newEmail: string = ''

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .borderRadius(50)
        .margin({ bottom: 20 })

      if (this.isEditing) {
        TextInput({ placeholder: 'Enter new name' })
          .onChange((value: string) => {
            this.newName = value
          })
          .margin({ bottom: 10 })

        TextInput({ placeholder: 'Enter new email' })
          .onChange((value: string) => {
            this.newEmail = value
          })
          .margin({ bottom: 10 })

        Button('Save')
          .onClick(() => {
            if (this.newName) {
              this.userName = this.newName
            }
            if (this.newEmail) {
              this.userEmail = this.newEmail
            }
            this.isEditing = false
          })
      } else {
        Text(this.userName)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 10 })

        Text(this.userEmail)
          .fontSize(16)
          .margin({ bottom: 20 })

        Button('Edit Profile')
          .onClick(() => {
            this.isEditing = true
          })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

