@Entry
@Component
struct DropdownSelectionApp {
  @State selectedItem: Item | null = null;
  @State isDropdownOpen: boolean = false;

  private items: Item[] = [
    { id: 1, name: 'Apple', details: 'A sweet, red fruit.' },
    { id: 2, name: 'Banana', details: 'A yellow, curved fruit.' },
    { id: 3, name: 'Orange', details: 'A juicy, citrus fruit.' },
    { id: 4, name: 'Grapes', details: 'Small, sweet fruits in clusters.' }
  ];

  build() {
    Column() {
      Text('Select an Item')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Button(this.selectedItem ? this.selectedItem.name : 'Choose an Item')
        .onClick(() => {
          this.isDropdownOpen = !this.isDropdownOpen;
        })
        .width('80%')
        .height(50)
        .backgroundColor('#f0f0f0')
        .borderRadius(5)
        .margin({ bottom: 10 });

      if (this.isDropdownOpen) {
        List() {
          ForEach(this.items, (item: Item) => {
            ListItem() {
              Text(item.name)
                .fontSize(18)
                .padding(10)
                .onClick(() => {
                  this.selectedItem = item;
                  this.isDropdownOpen = false;
                });
            }
            .margin({ bottom: 5 })
            .backgroundColor('#e0e0e0')
            .borderRadius(5);
          });
        }
        .width('80%')
        .height(200)
        .backgroundColor('#FFFFFF')
        .borderRadius(5)
        .margin({ bottom: 20 });
      }

      if (this.selectedItem) {
        Column() {
          Text(`Selected: ${this.selectedItem.name}`)
            .fontSize(20)
            .fontWeight(FontWeight.Medium)
            .margin({ bottom: 10 });

          Text(this.selectedItem.details)
            .fontSize(16)
            .lineHeight(20)
            .margin({ bottom: 20 });
        }
        .width('80%')
        .padding(15)
        .backgroundColor('#FFFFFF')
        .borderRadius(10);
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5');
  }
}

interface Item {
  id: number;
  name: string;
  details: string;
}

