                Text(card.subtitle)
                  .fontSize(14)
                  .fontColor('#666666');
              }
              .width('100%')
              .padding(12);
            }
            .backgroundColor(Color.White)
            .borderRadius(12)
            .onClick(() => {
              this.selectedCard = card;
              this.dialogController.open();
            });
          }
        });
      }
      .columnsTemplate('1fr 1fr')
      .rowsGap(16)
      .columnsGap(16)
      .padding(16)
      .layoutWeight(1);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }
