@Component
struct Index {
  @State selectedMovie: Movie | null = null;

  build() {
    if (this.selectedMovie == null) {
      Column() {
        Text('Movie List')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .padding(16);

        List() {
          ForEach(movies, (movie: Movie) => {
            ListItem() {
              Row() {
                Image(movie.poster)
                  .width(100)
                  .height(150)
                  .objectFit(ImageFit.Cover)
                  .margin({ right: 10 });
                Column() {
                  Text(movie.title)
                    .fontSize(20)
                    .fontWeight(FontWeight.Medium)
                    .padding({ bottom: 4 });
                  Text(`Genre: ${movie.genre}`)
                    .fontSize(16)
                    .padding({ bottom: 4 });
                  Text(`Rating: ${movie.rating}`)
                    .fontSize(16)
                    .padding({ bottom: 8 });
                }
                .layoutWeight(1)
                .margin({ left: 10 });
              }
              .padding(16)
              .onClick(() => {
                this.selectedMovie = movie;
              });
            }
          });
        }
      }
    } else {
      Scroll() {
        Column() {
          Image(this.selectedMovie.poster)
            .width('100%')
            .height(300)
            .objectFit(ImageFit.Cover)
            .margin({ bottom: 16 });

          Text(this.selectedMovie.title)
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .padding(16);

          Text(`Genre: ${this.selectedMovie.genre}`)
            .fontSize(18)
            .padding({ left: 16, right: 16, bottom: 8 });

          Text(`Rating: ${this.selectedMovie.rating}`)
            .fontSize(18)
            .padding({ left: 16, right: 16, bottom: 8 });

          Text('Description:')
            .fontSize(20)
            .fontWeight(FontWeight.Medium)
            .padding({ left: 16, right: 16, top: 16, bottom: 4 });

          Text(this.selectedMovie.description)
            .fontSize(16)
            .padding({ left: 16, right: 16, bottom: 16 });

          Button('Back')
            .onClick(() => {
              this.selectedMovie = null;
            })
            .padding(16);
        }
      }
    }
  }
}

