@Component
struct DataFetchingApp {
    @State isLoading: boolean = false
    @State data: string[] = []

    aboutToAppear() {
        this.fetchData()
    }

    private fetchData() {
        this.isLoading = true
        setTimeout(() => {
            this.data = ['Data 1', 'Data 2', 'Data 3']
            this.isLoading = false
        }, 2000)
    }

    build() {
        Column() {
            if (this.isLoading) {
                AnimatedSpinner()
            } else {
                List() {
                    ForEach(this.data, (item: string) => {
                        ListItem() {
                            Text(item).fontSize(30)
                        }
                    }, (item: string) => item)
                }
            }
        }
        .width('100%')
        .height('100%')
    }
}

@Component
struct AnimatedSpinner {
    @State rotation: number = 0
    private intervalID: number = -1

    aboutToAppear() {
        this.intervalID = setInterval(() => {
            this.rotation = (this.rotation + 10) % 360
        }, 50)
    }

    aboutToDisappear() {
        clearInterval(this.intervalID)
    }

    build() {
        Column() {
            Stack() {
                Circle()
                    .width(100)
                    .height(100)
                    .stroke($r('sys.color.ohos_id_color_primary'))
                    .strokeWidth(10)
                    .strokeDashArray([10, 20])
                    .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })
            }
            .width(100)
            .height(100)
        }
        .justifyContent(FlexAlign.Center)
        .backgroundColor($r('sys.color.ohos_id_color_background'))
        .width('100%')
        .height('100%')
    }
}

