import promptAction from '@ohos.promptAction';

@Entry
@Component
struct UserForm {
  @State name: string = '';
  @State email: string = '';
  @State phoneNumber: string = '';
  @State showSuccessMessage: boolean = false;

  build() {
    Column() {
      Text('User Information')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value;
          });
      }

      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value;
          });
      }

      Column() {
        Text('Phone Number:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your phone number' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.phoneNumber = value;
          });
      }

      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.name && this.email && this.phoneNumber) {
            this.showSuccessMessage = true;
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields'
            });
          }
        });

      if (this.showSuccessMessage) {
        Column() {
          Text('Form Submitted Successfully!')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Name: ${this.name}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Phone Number: ${this.phoneNumber}`)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.showSuccessMessage = false;
              this.name = '';
              this.email = '';
              this.phoneNumber = '';
            });
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

@Entry
@Component
struct MultipleResponseRegions {
  @State private response1: string = "";
  @State private response2: string = "";
  @State private response3: string = "";
  @State private showAlert: boolean = false;

  validateInputs(): boolean {
    if (this.response1.trim() === "" || this.response2.trim() === "" || this.response3.trim() === "") {
      return false;
    }
    return true;
  }

  handleSubmit() {
    if (this.validateInputs()) {
      this.showAlert = true;
    }
  }

  build() {
    Column({ space: 10 }) {
      TextInput({ placeholder: "Enter response for region 1" })
        .onChange((value: string) => {
          this.response1 = value;
        })
        .margin({ top: 10 });

      TextInput({ placeholder: "Enter response for region 2" })
        .onChange((value: string) => {
          this.response2 = value;
        })
        .margin({ top: 10 });

      TextInput({ placeholder: "Enter response for region 3" })
        .onChange((value: string) => {
          this.response3 = value;
        })
        .margin({ top: 10 });

      Button("Submit Responses")
        .onClick(() => {
          this.handleSubmit();
        })
        .margin({ top: 20 })
        .backgroundColor(0x317aff);

      if (this.showAlert) {
        Column() {
          Text("Submitted Responses")
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text("Response 1: " + this.response1)
            .fontSize(16)
            .margin({ bottom: 10 });

          Text("Response 2: " + this.response2)
            .fontSize(16)
            .margin({ bottom: 10 });

          Text("Response 3: " + this.response3)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button("Close")
            .onClick(() => {
              this.showAlert = false;
              this.response1 = "";
              this.response2 = "";
              this.response3 = "";
            })
            .width('100%')
            .height(50)
            .backgroundColor(0x317aff)
            .fontSize(18);
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .padding(20);
  }
}

