@Entry
@Component
struct MapSearchApp {
  @State searchText: string = '';
  @State markers: Array<Marker> = [];

  private addMarker(latitude: number, longitude: number, name: string): void {
    const newMarker: Marker = { id: this.markers.length + 1, latitude, longitude, name };
    this.markers = [...this.markers, newMarker];
  }

  private searchLocation(): void {
    if (this.searchText.trim() === '') return;

    const mockLatitude: number = 37.7749 + Math.random() * 0.01;
    const mockLongitude: number = -122.4194 + Math.random() * 0.01;
    this.addMarker(mockLatitude, mockLongitude, this.searchText);
    this.searchText = '';
  }

  build() {
    Column() {
      TextInput({ placeholder: 'Enter Location', text: this.searchText })
        .onChange((value: string) => {
          this.searchText = value;
        })
        .width('80%')
        .margin(10)
        .border({ width: 1, color: '#cccccc', radius: 5 });

      Button('Search')
        .onClick(() => {
          this.searchLocation();
        })
        .width('80%')
        .margin(10)
        .backgroundColor('#1698CE')
        .fontColor(Color.White);

      Text('Map View: Displaying Markers')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 10 });

      List() {
        ForEach(this.markers, (marker: Marker, index: number) => {
          ListItem() {
            Column() {
              Text(`Marker ${index + 1}: ${marker.name}`)
                .fontSize(14)
                .fontWeight(FontWeight.Bold);
              Text(`(${marker.latitude}, ${marker.longitude})`)
                .fontSize(12)
                .fontWeight(FontWeight.Normal);
            }
            .padding(10)
            .backgroundColor('#FFFFFF')
            .borderRadius(5)
            .margin({ bottom: 10 });
          }
        });
      }
      .width('100%')
      .height('100%');
    }
    .width('100%')
    .height('100%')
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#F5F5F5');
  }
}

interface Marker {
  id: number;
  name: string;
  latitude: number;
  longitude: number;
}

