@Component
struct WaterIntakeMonitor {
  @State waterIntake: number = 0
  @State dailyGoal: number = 2000 // Default daily goal in milliliters
  @State progress: number = 0

  updateProgress() {
    this.progress = (this.waterIntake / this.dailyGoal) * 100
  }

  build() {
    Column() {
      Text('Daily Water Intake Monitor')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin(20)

      Text(`Goal: ${this.dailyGoal} ml`)
        .fontSize(18)
        .margin(10)

      Text(`Consumed: ${this.waterIntake} ml`)
        .fontSize(18)
        .margin(10)

      Progress({ value: this.progress, total: 100 })
        .width('80%')
        .height(20)
        .margin(20)

      Row() {
        Button('+250 ml')
          .onClick(() => {
            this.waterIntake += 250
            this.updateProgress()
          })
          .margin(10)

        Button('+500 ml')
          .onClick(() => {
            this.waterIntake += 500
            this.updateProgress()
          })
          .margin(10)
      }

      Button('Reset')
        .onClick(() => {
          this.waterIntake = 0
          this.updateProgress()
        })
        .margin(20)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

