struct NodePerformanceOptimization {
  @State private isOptimized: boolean = false;
  @State private items: Array<number> = [];
  private dataSource: OptimizedDataSource = new OptimizedDataSource();

  aboutToAppear() {
    for (let i = 0; i < 100; i++) {
      this.items.push(i);
    }
    this.dataSource.initializeData(this.items);
  }

  build() {
    Column({ space: 20 }) {
      Text('Node Performance Optimization')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .textAlign(TextAlign.Center)
        .margin({ top: 20 });

      Image($r("app.media.app_icon"))
        .width(100)
        .height(100)
        .margin({ top: 20 });

      Button(this.isOptimized ? 'Disable Optimization' : 'Enable Optimization')
        .onClick(() => {
          this.isOptimized = !this.isOptimized;
          console.log(`Optimization ${this.isOptimized ? 'enabled' : 'disabled'}`);
        })
        .width('80%')
        .height(50)
        .margin({ top: 20 });

      List({ space: 10 }) {
        if (this.isOptimized) {
          LazyForEach(this.dataSource, (item: number) => {
            ListItem() {
              Text(`Optimized Item ${item}`)
                .fontSize(16)
                .padding(10)
            }
            .width('100%')
            .backgroundColor(Color.White)
            .borderRadius(8)
          }, (item: number) => item.toString())
        } else {
          ForEach(this.items, (item: number) => {
            ListItem() {
              Text(`Regular Item ${item}`)
                .fontSize(16)
                .padding(10)
            }
            .width('100%')
            .backgroundColor(Color.White)
            .borderRadius(8)
          })
        }
      }
      .width('100%')
      .height('60%')
      .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .padding(10)
  }
}

class OptimizedDataSource implements IDataSource {
  private data: Array<number> = [];
  private listeners: DataChangeListener[] = [];

  initializeData(items: Array<number>) {
    this.data = items;
  }

  totalCount(): number {
    return this.data.length;
  }

  getData(index: number): number {
    return this.data[index];
  }

  registerDataChangeListener(listener: DataChangeListener): void {
    if (this.listeners.indexOf(listener) < 0) {
      this.listeners.push(listener);
    }
  }

  unregisterDataChangeListener(listener: DataChangeListener): void {
    const pos = this.listeners.indexOf(listener);
    if (pos >= 0) {
      this.listeners.splice(pos, 1);
    }
  }

  notifyDataReload(): void {
    this.listeners.forEach(listener => {
      listener.onDataReloaded();
    });
  }
}

