@Entry
@Component
struct NavigationDrawerApp {
  @State isDrawerOpen: boolean = false;
  @State selectedScreenIndex: number = 0;

  build() {
    Row() {
      Column() {
        this.ScreenContent();
        this.DrawerButton();
      }
      .layoutWeight(1);

      Panel(this.isDrawerOpen) {
        Column() {
          this.NavItem('Home', 0);
          this.NavItem('Profile', 1);
          this.NavItem('Settings', 2);
          this.NavItem('Messages', 3);
          this.NavItem('Notifications', 4);
        }
        .width('80%')
        .height('100%')
        .backgroundColor(Color.White);
      }
      .mode(PanelMode.Mini)
      .type(PanelType.Temporary)
      .dragBar(false);
    }
    .width('100%')
    .height('100%');
  }

  @Builder DrawerButton() {
    Button('Toggle Drawer')
      .onClick(() => {
        this.isDrawerOpen = !this.isDrawerOpen;
      });
  }

  @Builder NavItem(label: string, index: number) {
    Row() {
      Text(label)
        .fontSize(20)
        .margin(10);
      Blank();
      Image($r('app.media.app_icon'))
        .width(20)
        .height(20);
    }
    .onClick(() => {
      this.selectedScreenIndex = index;
      this.isDrawerOpen = false;
    })
    .width('100%')
    .backgroundColor(Color.White)
    .border({ width: { bottom: 1 }, color: '#cccccc' });
  }

  @Builder ScreenContent() {
    if (this.selectedScreenIndex === 0) {
      this.HomeScreen();
    } else if (this.selectedScreenIndex === 1) {
      this.ProfileScreen();
    } else if (this.selectedScreenIndex === 2) {
      this.SettingsScreen();
    } else if (this.selectedScreenIndex === 3) {
      this.MessagesScreen();
    } else {
      this.NotificationsScreen();
