        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin(16);
    }
    .width('100%')
    .height('100%');
  }

  @Builder SettingsScreen() {
    Column() {
      Text('Settings Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin(16);
    }
    .width('100%')
    .height('100%');
  }

  @Builder MessagesScreen() {
