@Entry
@Component
struct AsyncCallbackHandler {
  @State result: string = 'Waiting for computation...';

  build() {
    Column() {
      Text(this.result)
        .fontSize(20)
        .margin(10)

      Button('Start Async Computation')
        .onClick(() => {
          this.performAsyncComputation((computedValue: string) => {
            this.result = computedValue;
          });
        })
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }

  performAsyncComputation(callback: (value: string) => void) {
    setTimeout(() => {
      const computedValue = 'Computed Value: 100'; // Simulated computation result
      callback(computedValue);
    }, 2000); // Simulate a 2-second delay
  }
}

