@Entry
@Component
struct InsertItemAtIndex {
  @State items: string[] = ['Apple', 'Banana', 'Cherry']
  @State newItem: string = ''
  @State index: number = 0

  build() {
    Column() {
      TextInput({ placeholder: 'Enter a new item' })
        .onChange((value: string) => {
          this.newItem = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter index to add item' })
        .onChange((value: string) => {
          this.index = parseInt(value)
        })
        .margin({ bottom: 20 })

      Button('Insert Item at Index')
        .onClick(() => {
          if (this.newItem && this.index >= 0 && this.index <= this.items.length) {
            this.items.splice(this.index, 0, this.newItem)
            this.newItem = ''
          }
        })
        .margin({ bottom: 20 })

      ForEach(this.items, (item: string, idx: number) => {
        Text(`${idx + 1}. ${item}`)
          .margin({ top: 10 })
      })
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff')
  }
}

