@Entry
@Component
struct ImageGridApp {
  @State selectedImage: Resource = $r('app.media.icon')
  @State showFullScreen: boolean = false

  private images: Resource[] = [
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon'),
    $r('app.media.icon')
  ]

  build() {
    Column() {
      if (this.showFullScreen) {
        Stack() {
          Image(this.selectedImage)
