      // Bottom Navigation Bar
      Row() {
        this.BottomNavItem('Home', 0);
        this.BottomNavItem('Profile', 1);
        this.BottomNavItem('Settings', 2);
      }
      .width('100%')
      .height(60)
      .backgroundColor(Color.Gray)
      .justifyContent(FlexAlign.SpaceAround);

      // Drawer Panel
      Panel(this.isDrawerOpen) {
