import promptAction from '@ohos.promptAction';

@Entry
@Component
struct UserForm {
  @State username: string = '';
  @State email: string = '';
  @State password: string = '';
  @State showDialog: boolean = false;

  build() {
    Column() {
      Text('User Registration')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      Column() {
        Text('Username:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your username' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.username = value;
          });
      }

      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value;
          });
      }

      Column() {
        Text('Password:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your password' })
          .type(InputType.Password)
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.password = value;
          });
      }

      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.username && this.email && this.password) {
            this.showDialog = true;
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields'
            });
          }
        });

      if (this.showDialog) {
        Column() {
          Text('Submitted Information')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Username: ${this.username}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Password: ${this.password}`)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.showDialog = false;
              this.username = '';
              this.email = '';
              this.password = '';
            });
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

@Entry
@Component
struct PaginatedListWithLoadMore {
  @State listData: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4', 'Item 5'];
  @State isLoading: boolean = false;
  private scroller: Scroller = new Scroller();

  build() {
    Column() {
      List({ scroller: this.scroller }) {
        ForEach(this.listData, (item: string) => {
          ListItem() {
            Row() {
              Image($r('app.media.app_icon'))
                .width(40)
                .height(40)
                .margin(10)
              Text(item)
                .fontSize(18)
                .fontWeight(FontWeight.Bold)
            }
            .width('100%')
            .justifyContent(FlexAlign.Start)
            .padding(10)
            .backgroundColor('#f0f0f0')
            .borderRadius(10)
          }
        })
      }
      .width('100%')
      .height('90%')
      .onReachEnd(() => {
        if (!this.isLoading) {
          this.loadMoreData();
        }
      })

      if (this.isLoading) {
        Text('Loading more...')
          .fontSize(16)
          .padding(16)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff')
    .padding(10)
  }

  loadMoreData() {
    this.isLoading = true;
    setTimeout(() => {
      const newItems = ['Item 6', 'Item 7', 'Item 8', 'Item 9', 'Item 10'];
      this.listData = [...this.listData, ...newItems];
      this.isLoading = false;
    }, 2000);
  }
}

