      Text('Select Multiple Items')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      List() {
        ForEach(this.items, (item: Item) => {
          ListItem() {
            Row() {
              Image($r('app.media.icon'))
                .width(30)
                .height(30)
                .margin({ right: 10 });
              Text(item.title)
                .fontSize(18)
                .padding(10);
              Checkbox()
                .onChange((isChecked: boolean) => {
                  if (isChecked) {
                    this.selectedItems.push(item);
                  } else {
                    this.selectedItems = this.selectedItems.filter(selectedItem => selectedItem.id !== item.id);
                  }
                });
            }
            .justifyContent(FlexAlign.SpaceBetween)
            .backgroundColor(this.selectedItems.includes(item) ? '#d3d3d3' : '#f0f0f0')
            .borderRadius(5)
            .padding(10)
            .margin({ bottom: 10 });
          }
        });
      }
      .width('100%');

      if (this.selectedItems.length > 0) {
        Text('Selected Items:')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 20 });

        List() {
          ForEach(this.selectedItems, (item: Item) => {
            ListItem() {
              Text(item.title)
                .fontSize(18)
                .padding(10);
            }
            .backgroundColor('#e0e0e0')
            .borderRadius(5)
            .margin({ bottom: 10 });
          });
        }
        .width('100%');
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

