@Entry
@Component
struct ChatApp {
  @State messages: Array<Message> = []
  @State newMessage: string = ''

  build() {
    Column() {
      // Chat Messages Display
      List({ space: 10 }) {
        ForEach(this.messages, (message: Message) => {
          ListItem() {
            Column() {
              Text(`${message.sender} - ${message.timestamp}`)
                .fontSize(14)
                .fontColor('#666666')
                .margin({ bottom: 4 })
              Text(message.content)
                .fontSize(16)
                .fontColor('#000000')
                .padding(10)
                .backgroundColor(message.sender === 'User' ? '#DCF8C6' : '#ECECEC')
                .borderRadius(10)
            }
            .alignItems(message.sender === 'User' ? HorizontalAlign.End : HorizontalAlign.Start)
            .width('100%')
          }
        })
      }
      .layoutWeight(1)
      .width('100%')
      .padding(10)

      // Text Input for New Messages
      Row() {
        TextInput({ placeholder: 'Type a message...', text: this.newMessage })
          .onChange((value: string) => {
            this.newMessage = value
          })
          .layoutWeight(1)
          .height(40)
          .backgroundColor('#ffffff')
          .padding({ left: 12, right: 12 })
          .borderRadius(8)

        Button('Send')
          .width(80)
          .height(40)
          .fontSize(16)
          .backgroundColor('#007AFF')
          .onClick(() => {
            if (this.newMessage.trim()) {
              const newMsg: Message = {
                sender: 'User',
                timestamp: new Date().toLocaleTimeString(),
                content: this.newMessage
              }
              this.messages = [...this.messages, newMsg]
              this.newMessage = ''
            }
          })
      }
      .padding(10)
      .backgroundColor('#ffffff')
      .width('100%')
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f0f0f0')
  }
}

interface Message {
  sender: string
  timestamp: string
  content: string
}

