@Entry
@Component
struct AsyncSnapshotRendering {
  @State private imageSrc: string = '';
  @State private isProcessing: boolean = false;

  build() {
    Column() {
      Text('Asynchronous Snapshot Rendering')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Button('Capture Snapshot')
        .onClick(() => {
          this.captureSnapshot();
        })
        .width(200)
        .height(40)
        .margin({ bottom: 20 })
        .backgroundColor(Color.Blue)
        .borderRadius(8);

      if (this.isProcessing) {
        Progress({ value: 0 })
          .width(200)
          .height(4)
          .margin({ bottom: 20 });
      }

      Image(this.imageSrc ? $r(this.imageSrc) : $r('app.media.app_icon'))
        .width(200)
        .height(200)
        .margin({ bottom: 20 })
        .visibility(this.imageSrc ? Visibility.Visible : Visibility.None);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }

  private captureSnapshot() {
    this.isProcessing = true;
    setTimeout(() => {
      this.imageSrc = 'app.media.app_icon';
      this.isProcessing = false;
    }, 1500);
  }
}

@Entry
@Component
struct SignInApp {
  @State email: string = '';
  @State password: string = '';
  @State isSignedIn: boolean = false;
  @State errorMessage: string = '';

  validateInputs(): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(this.email)) {
      this.errorMessage = 'Please enter a valid email address';
      return false;
    }
    if (this.password.length < 6) {
      this.errorMessage = 'Password must be at least 6 characters';
      return false;
    }
    this.errorMessage = '';
    return true;
  }

  navigateToWelcome() {
    // Note: You'll need to replace the router     // For now, this is a placeholder
    console.log('Navigating to welcome page with email:', this.email);
  }

  build() {
    Column() {
      if (!this.isSignedIn) {
        TextInput({ placeholder: 'Email' })
          .onChange((value: string) => {
            this.email = value;
          })
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Password' })
          .type(InputType.Password)
          .onChange((value: string) => {
            this.password = value;
          })
          .margin({ bottom: 10 });

        if (this.errorMessage) {
          Text(this.errorMessage)
            .fontColor(Color.Red)
            .margin({ bottom: 10 });
        }

        Button('Sign In')
          .onClick(() => {
            if (this.validateInputs()) {
              this.isSignedIn = true;
              this.navigateToWelcome();
            }
          })
          .width('60%')
          .margin({ bottom: 10 });

        Text('New Account?')
          .onClick(() => {
            // Note: Replace with appropriate navigation logic or toast implementation
            console.log('Navigate to sign-up page');
          })
          .fontColor(Color.Blue);
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%');
  }
}

