@Component
struct StickyHeaderList {
  private sections: string[] = ['Section 1', 'Section 2', 'Section 3', 'Section 4'];
  private items: string[][] = [
    ['Item 1.1', 'Item 1.2', 'Item 1.3'],
    ['Item 2.1', 'Item 2.2', 'Item 2.3'],
    ['Item 3.1', 'Item 3.2', 'Item 3.3'],
    ['Item 4.1', 'Item 4.2', 'Item 4.3']
  ];

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.sections, (section: string, sectionIndex: number) => {
          ListItemGroup({ header: this.HeaderBuilder(section) }) {
            ForEach(this.items[sectionIndex], (item: string) => {
              ListItem() {
                Row() {
                  Image($r('app.media.app_icon'))
                    .width(50)
                    .height(50)
                    .margin(10);
                  Text(item)
                    .fontSize(16)
                    .margin(10);
                }
                .width('100%')
                .justifyContent(FlexAlign.Start)
                .padding(10)
                .backgroundColor('#f0f0f0')
                .borderRadius(10);
              }
            });
          }
        });
      }
      .scrollBar(BarState.On)
      .scrollBarColor(Color.Gray)
      .scrollBarWidth(10)
      .edgeEffect(EdgeEffect.Spring)
      .width('100%')
      .height('100%')
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }

  @Builder
  HeaderBuilder(title: string) {
    Text(title)
      .fontSize(20)
      .fontWeight(FontWeight.Bold)
      .backgroundColor(Color.White)
      .width('100%')
      .padding(10)
      .zIndex(1);
  }
}

@Entry
@Component
struct TextPickerMultiSelectExample {
  private selectedIndices: number[] = [0, 2] // Default selected indices
  private options: string[] = ['Option A', 'Option B', 'Option C', 'Option D', 'Option E']

  build() {
    Column() {
      TextPicker({ range: this.options, selected: this.selectedIndices })
        .onChange((value: string | string[], index: number | number[]) => {
          if (Array.isArray(index)) {
            this.selectedIndices = index;
            console.info('Selected indices: ' + this.selectedIndices.join(', '));
          }
        })
        .disappearTextStyle({ color: Color.Red, font: { size: 15, weight: FontWeight.Lighter } })
        .textStyle({ color: Color.Black, font: { size: 20, weight: FontWeight.Normal } })
        .selectedTextStyle({ color: Color.Blue, font: { size: 30, weight: FontWeight.Bolder } })
        .divider(null)

      Text(`Selected Options: ${this.selectedIndices.map(i => this.options[i]).join(', ')}`)
        .fontSize(20)
        .margin({ top: 20 })
        .fontColor(Color.Blue)
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White)
  }
}

