import promptAction from '@ohos.promptAction';

@Entry
@Component
struct InteractionFeedbackDemo {
  @State private buttonText: string = "Click Me";
  @State private inputText: string = "";
  @State private toggleState: boolean = false;
  @State private imageClickCount: number = 0;
  @State private sliderValue: number = 50;
  @State private showFeedback: boolean = false;

  private handleButtonClick() {
    this.buttonText = "Button Clicked!";
    this.showFeedback = true;
    promptAction.showToast({
      message: 'Button Interaction Feedback',
      duration: 1500,
    });
  }

  private handleInputChange(value: string) {
    this.inputText = value;
    promptAction.showToast({
      message: 'Input Changed',
      duration: 1500,
    });
  }

  private handleToggle() {
    this.toggleState = !this.toggleState;
    promptAction.showToast({
      message: `Toggle ${this.toggleState ? 'ON' : 'OFF'}`,
      duration: 1500,
    });
  }

  private handleImageClick() {
    this.imageClickCount++;
    promptAction.showToast({
      message: `Image Clicked ${this.imageClickCount} times`,
      duration: 1500,
    });
  }

  private handleSliderChange(value: number) {
    this.sliderValue = value;
    promptAction.showToast({
      message: `Slider Value: ${value}`,
      duration: 1500,
    });
  }

  build() {
    Column({ space: 20 }) {
      Button(this.buttonText)
        .onClick(() => {
          this.handleButtonClick();
        })
        .width(200)
        .height(50)
        .backgroundColor(Color.Blue)
        .fontColor(Color.White)
        .fontSize(16);

      TextInput({ placeholder: 'Type something' })
        .onChange((value: string) => {
          this.handleInputChange(value);
        })
        .width('80%')
        .height(50)
        .border({ width: 1, color: Color.Gray });

      Text(`You typed: ${this.inputText}`)
        .fontSize(16);

      Toggle({ type: ToggleType.Switch, isOn: this.toggleState })
        .onChange((isOn: boolean) => {
          this.handleToggle();
        })
        .width(100);

      Text(this.toggleState ? 'Toggle ON' : 'Toggle OFF')
        .fontSize(16);

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .onClick(() => {
          this.handleImageClick();
        });

      Text(`Image clicked ${this.imageClickCount} times`)
        .fontSize(16);

      Slider({
        value: this.sliderValue,
        min: 0,
        max: 100,
        step: 1,
        style: SliderStyle.OutSet
      })
        .onChange((value: number) => {
          this.handleSliderChange(value);
        })
        .width('80%');

      Text(`Slider value: ${this.sliderValue}`)
        .fontSize(16);

      if (this.showFeedback) {
        Text('Feedback: Interaction Detected')
          .fontSize(18)
          .fontColor(Color.Green)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
