@Component
struct ImageUploaderApp {
  @State images: Resource[] = []
  @State selectedImage: Resource = $r('app.media.app_icon')
  @State showFullScreen: boolean = false

  build() {
    Column() {
      if (this.showFullScreen) {
        Stack() {
          Image(this.selectedImage)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%')

          Button('Close')
            .onClick(() => {
              this.showFullScreen = false
            })
            .position({ x: 20, y: 20 })
            .backgroundColor('#FFFFFF')
            .padding({ left: 10, right: 10, top: 5, bottom: 5 })
            .borderRadius(5)
        }
      } else {
        Grid() {
          ForEach(this.images, (image: Resource) => {
            GridItem() {
              Image(image)
                .width('100%')
                .aspectRatio(1)
                .objectFit(ImageFit.Cover)
                .borderRadius(5)
                .onClick(() => {
                  this.selectedImage = image
                  this.showFullScreen = true
                })
            }
          })
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsGap(10)
        .columnsGap(10)
        .padding(10)

        Button('Upload Image')
          .onClick(() => {
            this.images.push($r('app.media.app_icon'))
          })
          .margin(10)
          .backgroundColor('#007AFF')
          .padding({ left: 20, right: 20, top: 10, bottom: 10 })
          .borderRadius(5)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

@Entry
@Component
struct ScreenshotWithDelay {
  @State private imageSrc: string = '';
  @State private status: string = 'Waiting for network image...';
  @State private isProcessing: boolean = false;

  build() {
    Column() {
      Text(this.status)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Image('https://example.com/image.jpg')
        .width(200)
        .height(200)
        .onClick(() => {
          if (!this.isProcessing) {
            this.isProcessing = true;
            this.status = 'Preparing screenshot...';
            this.takeScreenshotWithDelay(2000); // 2 seconds delay
          }
        });

      if (this.imageSrc) {
        Image($r('app.media.app_icon'))
          .width(200)
          .height(200)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }

  private takeScreenshotWithDelay(delay: number): void {
    setTimeout(() => {
      this.status = 'Screenshot taken successfully!';
      this.imageSrc = 'app.media.app_icon'; // Placeholder for screenshot result
      this.isProcessing = false;
      console.log('Screenshot saved:', this.imageSrc);
    }, delay);
  }
}

