@Entry
@Component
struct WaterIntakeTracker {
  @State waterIntake: number = 0;
  @State totalGlasses: number = 0;
  @State dailyGoal: number = 2000; // Default daily goal in milliliters
  @State progress: number = 0;

  updateProgress() {
    this.progress = (this.totalGlasses * 250 / this.dailyGoal) * 100;
  }

  build() {
    Column({ space: 20 }) {
      Text('Daily Water Intake Tracker')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Text(`Goal: ${this.dailyGoal} ml`)
        .fontSize(18)
        .margin(10);

      Text(`Total Glasses Consumed: ${this.totalGlasses}`)
        .fontSize(18)
        .margin(10);

      Stack() {
        Circle()
          .width(200)
          .height(200)
          .stroke('#E0E0E0')
          .strokeWidth(15)
          .fill('transparent');

        Circle()
          .width(200)
          .height(200)
          .stroke('#4CAF50')
          .strokeWidth(15)
          .fill('transparent')
          .strokeDashArray([Math.PI * 200, Math.PI * 200])
          .strokeDashOffset(Math.PI * 200 * (1 - this.progress / 100))
          .rotate({ x: 0, y: 0, z: 1, angle: -90 });

        Text(`${Math.round(this.progress)}%`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold);
      }
      .width(200)
      .height(200)
      .margin({ top: 20 });

      Row({ space: 10 }) {
        Button('-')
          .width(60)
          .height(60)
          .fontSize(24)
          .backgroundColor('#FF5722')
          .onClick(() => {
            if (this.waterIntake > 0) {
              this.waterIntake--;
            }
          });

        Text(`${this.waterIntake}`)
          .fontSize(24)
          .margin({ left: 10, right: 10 });

        Button('+')
          .width(60)
          .height(60)
          .fontSize(24)
          .backgroundColor('#4CAF50')
          .onClick(() => {
            this.waterIntake++;
          });
      }

      Button('Add to Total')
        .width(200)
        .height(50)
        .fontSize(18)
        .backgroundColor('#2196F3')
        .onClick(() => {
          this.totalGlasses += this.waterIntake;
          this.waterIntake = 0;
          this.updateProgress();
        })
        .margin({ top: 20 });

      Button('Reset')
        .width(200)
        .height(50)
        .fontSize(18)
        .backgroundColor('#F44336')
        .onClick(() => {
          this.totalGlasses = 0;
          this.waterIntake = 0;
          this.updateProgress();
        })
        .margin({ top: 10 });

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FAFAFA');
  }
}

