@Entry
@Component
struct LoginScreen {
  @State email: string = ''
  @State password: string = ''
  @State message: string = ''
  @State isSuccess: boolean = false

  build() {
    Column() {
      // Email Input
      Text('Email:')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your email' })
        .width('80%')
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.email = value
        })

      // Password Input
      Text('Password:')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .width('80%')
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.password = value
        })

      // Login Button
      Button('Login')
        .onClick(() => {
          if (this.validateEmail(this.email) && this.password.length >= 8) {
            this.message = 'Login successful!'
            this.isSuccess = true
          } else {
            if (!this.validateEmail(this.email)) {
              this.message = 'Invalid email format.'
            } else {
              this.message = 'Password must be at least 8 characters long.'
            }
            this.isSuccess = false
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      // Message Display
      if (this.message) {
        Text(this.message)
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
          .fontColor(this.isSuccess ? Color.Green : Color.Red)
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }

  validateEmail(email: string): boolean {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return re.test(email)
  }
}

import promptAction from '@ohos.promptAction';

@Entry
@Component
struct CustomVideoPlayer {
  private videoController: VideoController = new VideoController();
  @State isPlaying: boolean = false;
  @State currentTime: number = 0;
  @State duration: number = 0;
  @State isMuted: boolean = false;

  build() {
    Column() {
      Video({
        src: $r("app.media.app_icon"),
        controller: this.videoController
      })
      .controls(false)
      .autoPlay(false)
      .loop(false)
      .muted(this.isMuted)
      .onPrepared((event) => {
        this.duration = event.duration;
        console.info("Video prepared. Duration: " + event.duration);
      })
      .onUpdate((event) => {
        this.currentTime = event.time;
        console.info("Video progress updated. Current time: " + event.time);
      })
      .onError(() => {
        promptAction.showToast({ duration: 2000, message: "Video playback error." });
      })
      .width("100%")
      .height(300);

      Row({ space: 10 }) {
        Button(this.isPlaying ? "Pause" : "Play")
          .onClick(() => {
            if (this.isPlaying) {
              this.videoController.pause();
            } else {
              this.videoController.start();
            }
            this.isPlaying = !this.isPlaying;
          })
          .padding(10);

        Button("Stop")
          .onClick(() => {
            this.videoController.stop();
            this.isPlaying = false;
          })
          .padding(10);

        Button(this.isMuted ? "Unmute" : "Mute")
          .onClick(() => {
            this.isMuted = !this.isMuted;
          })
          .padding(10);
      }
      .margin({ top: 20 });

      Row({ space: 10 }) {
        Text("Time: " + this.currentTime.toFixed(2));
        Text("/");
        Text("Duration: " + this.duration.toFixed(2));
      }
      .margin({ top: 10 });
    }
    .padding(20)
    .width("100%")
    .height("100%");
  }
}

