@Entry
@Component
struct DevelopmentIterationSetup {
  @State private iterationStep: number = 1;
  @State private isProcessComplete: boolean = false;
  @State private processImage: Resource = $r('app.media.app_icon');

  build() {
    Column() {
      Text("Development Iteration Process")
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      if (this.isProcessComplete) {
        Image(this.processImage)
          .width(100)
          .height(100)
          .margin({ bottom: 20 });
        Text("Iteration Complete!")
          .fontSize(18)
          .margin({ bottom: 20 });
      } else {
        Text(`Iteration Step: ${this.iterationStep}`)
          .fontSize(18)
          .margin({ bottom: 20 });
      }

      Button("Next Step")
        .onClick(() => {
          this.nextStep();
        })
        .margin({ bottom: 20 });

      Button("Complete Iteration")
        .onClick(() => {
          this.completeIteration();
        })
        .margin({ bottom: 20 });
    }
    .padding(20)
    .width("100%")
    .height("100%")
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }

  private nextStep() {
    if (this.iterationStep < 3) {
      this.iterationStep++;
    }
  }

  private completeIteration() {
    this.isProcessComplete = true;
    setTimeout(() => {
      this.processImage = $r('app.media.app_icon');
    }, 1000);
  }
}

