        })
        .width('80%')
        .height(50)
        .margin({ top: 20 });

      Grid() {
        ForEach(['1', '2', '3', '4', '5', '6', '7', '8', '9', '*', '0', '#'], (item: string) => {
          GridItem() {
            Button(item)
              .width(80)
              .height(80)
              .backgroundColor('#007BFF')
              .fontColor(Color.White)
              .onClick(() => {
                this.inputValue += item;
              });
          }
        });

        GridItem() {
          Button('Backspace')
            .width(80)
            .height(80)
            .backgroundColor('#FF0000')
            .fontColor(Color.White)
