@Entry
@Component
struct CompositeTouchAreaApp {
  @State private isExpanded: boolean = false;
  @State private selectedColor: string = '#FF0000';
  private colors: string[] = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FF00FF', '#FFA500'];

  build() {
    Column() {
      // Display selected color
      Row() {
        Text('Selected Color:')
          .fontSize(20)
          .margin({ bottom: 10 });

        Row()
          .width(50)
          .height(50)
          .backgroundColor(this.selectedColor)
          .borderRadius(25);
      }
      .margin({ bottom: 20 });

      // Color options with touch area expansion
      Flex({ wrap: FlexWrap.Wrap, justifyContent: FlexAlign.SpaceAround }) {
        ForEach(this.colors, (color: string) => {
          Stack() {
            Button() {
              Text('');
            }
            .width(50)
            .height(50)
            .backgroundColor(color)
            .borderRadius(25)
            .onClick(() => {
              this.selectedColor = color;
              this.isExpanded = !this.isExpanded;
            });

            if (this.isExpanded && this.selectedColor === color) {
              Button()
                .width(100)
                .height(100)
                .backgroundColor(color)
                .opacity(0.3)
                .onClick(() => {
                  this.isExpanded = false;
                });
            }
          }
          .margin(5);
        });
      }

      // Touch area expansion example
      Stack() {
        Button('Tap to Expand')
          .width(100)
          .height(50)
          .backgroundColor(this.isExpanded ? '#4CAF50' : '#2196F3')
          .onClick(() => {
            this.isExpanded = !this.isExpanded;
          });

        if (this.isExpanded) {
          Button()
            .width(200)
            .height(100)
            .backgroundColor('#4CAF50')
            .opacity(0.3)
            .onClick(() => {
              this.isExpanded = false;
            });
        }
      }
      .width('100%')
      .height(150)
      .align(Alignment.Center);
    }
    .padding(20)
    .backgroundColor('#FFFFFF')
    .width('100%')
    .height('100%');
  }
}

