@Entry
@Component
struct RegistrationForm {
  @State name: string = ''
  @State email: string = ''
  @State password: string = ''
  @State errorMessage: string = ''

  validateForm(): boolean {
    if (!this.name || !this.email || !this.password) {
      this.errorMessage = 'All fields are required'
      return false
    }
    this.errorMessage = ''
    return true
  }

  build() {
    Column() {
      Text('Registration Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your name' })
        .onChange((value: string) => {
          this.name = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your email' })
        .onChange((value: string) => {
          this.email = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .margin({ bottom: 20 })

      Button('Submit')
        .onClick(() => {
          if (this.validateForm()) {
            AlertDialog.show({
              title: 'Form Submitted',
              message: `Name: ${this.name}\nEmail: ${this.email}\nPassword: ${this.password}`,
              confirm: {
                value: 'OK',
                action: () => {
                  this.name = ''
                  this.email = ''
                  this.password = ''
                }
              }
            })
          }
        })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ bottom: 20 })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct LoginScreen {
  @State username: string = ''
  @State password: string = ''
  @State loginMessage: string = ''
  @State showMessage: boolean = false

  build() {
    Column() {
      // Username Label and Input
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your username', text: this.username })
        .onChange((value: string) => {
          this.username = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Password Label and Input
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Login Button
      Button('Login')
        .onClick(() => {
          if (this.username === 'admin' && this.password === 'password123') {
            this.loginMessage = 'Login successful!'
          } else {
            this.loginMessage = 'Invalid username or password.'
          }
          this.showMessage = true
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      // Login Message
      if (this.showMessage) {
        Text(this.loginMessage)
          .fontSize(16)
          .margin({ top: 20 })
          .fontColor(this.loginMessage === 'Login successful!' ? Color.Green : Color.Red)
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

