@Component
struct ImageGalleryApp {
  private images: Array<ImageItem> = [
    { id: 1, title: 'Mountain View', image: $r('app.media.app_icon'), caption: 'A beautiful mountain landscape.' },
    { id: 2, title: 'Beach Sunset', image: $r('app.media.app_icon'), caption: 'Golden sunset over a tropical beach.' },
    { id: 3, title: 'City Lights', image: $r('app.media.app_icon'), caption: 'Modern cityscape at night.' }
  ];

  @State selectedImage: ImageItem | null = null;

  build() {
    if (this.selectedImage === null) {
      Column() {
        Text('Image Gallery')
          .fontSize(28)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20, bottom: 20 })
          .width('100%')
          .textAlign(TextAlign.Center);

        List() {
          ForEach(this.images, (imageItem: ImageItem) => {
            ListItem() {
              Row() {
                Image(imageItem.image)
                  .width(80)
                  .height(80)
                  .borderRadius(8)
                  .objectFit(ImageFit.Cover);

                Column() {
                  Text(imageItem.title)
                    .fontSize(18)
                    .fontWeight(FontWeight.Medium)
                    .margin({ bottom: 4 });

                  Text(imageItem.caption)
                    .fontSize(14)
                    .fontColor('#666666');
                }
                .layoutWeight(1)
                .alignItems(HorizontalAlign.Start)
                .margin({ left: 16 });
              }
              .width('100%')
              .padding(16)
              .backgroundColor(Color.White)
              .borderRadius(12)
              .onClick(() => {
                this.selectedImage = imageItem;
              });
            }
            .margin({ bottom: 12 });
          });
        }
        .width('100%');
      }
      .width('100%')
      .height('100%')
      .backgroundColor('#f5f5f5');
    } else {
      Stack() {
        Image(this.selectedImage.image)
          .objectFit(ImageFit.Cover)
          .width('100%')
          .height('100%');

        Column() {
          Button('Back')
            .onClick(() => {
              this.selectedImage = null;
            })
            .margin({ top: 20, left: 20 })
            .backgroundColor('#FFFFFF')
            .padding(10)
            .borderRadius(5);

          Text(this.selectedImage.caption)
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .position({ x: '50%', y: '90%' })
            .textAlign(TextAlign.Center)
            .backgroundColor('#FFFFFF')
            .padding(10)
            .borderRadius(5);
        }
      }
      .width('100%')
      .height('100%');
    }
  }
}

