@Entry
@Component
struct ArrayListExample {
  @State private arrayList: string[] = ['Apple', 'Banana', 'Cherry'];
  @State private inputValue: string = '';
  @State private indexToModify: string = '';
  @State private newValue: string = '';

  build() {
    Column({ space: 10 }) {
      Text('ArrayList Elements:')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      ForEach(this.arrayList, (item: string, index: number) => {
        Text(`${index}: ${item}`)
          .fontSize(16)
          .margin({ bottom: 5 });
      }, (item: string) => item);

      TextInput({ placeholder: 'Enter value to add' })
        .onChange((value: string) => {
          this.inputValue = value;
        })
        .margin(10)
        .width('80%');

      Button('Add Element')
        .onClick(() => {
          if (this.inputValue) {
            this.arrayList.push(this.inputValue);
            this.arrayList = [...this.arrayList];
            this.inputValue = '';
          }
        })
        .margin(10)
        .width('80%');

      TextInput({ placeholder: 'Enter index to modify' })
        .onChange((value: string) => {
          this.indexToModify = value;
        })
        .margin(10)
        .width('80%');

      TextInput({ placeholder: 'Enter new value' })
        .onChange((value: string) => {
          this.newValue = value;
        })
        .margin(10)
        .width('80%');

      Button('Modify Element')
        .onClick(() => {
          if (this.indexToModify && this.newValue) {
            const index = Number(this.indexToModify);
            if (index >= 0 && index < this.arrayList.length) {
              this.arrayList[index] = this.newValue;
              this.arrayList = [...this.arrayList];
              this.indexToModify = '';
              this.newValue = '';
            }
          }
        })
        .margin(10)
        .width('80%');

      Button('Remove Last Element')
        .onClick(() => {
          if (this.arrayList.length > 0) {
            this.arrayList.pop();
            this.arrayList = [...this.arrayList];
          }
        })
        .margin(10)
        .width('80%');
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor(0xF1F3F5)
  }
}

