  @State linkedList: LinkedList = new LinkedList();
  @State inputValue: string = '';
  @State indexToModify: string = '';
  @State newValue: string = '';

  build() {
    Column({ space: 10 }) {
      TextInput({ placeholder: 'Enter value to add' })
        .onChange((value: string) => {
          this.inputValue = value;
        })
        .margin(10)
        .width('80%')

      Button('Add to LinkedList')
        .onClick(() => {
          if (this.inputValue) {
            this.linkedList.add(Number(this.inputValue));
            this.inputValue = '';
          }
        })
        .margin(10)
        .width('80%')

      TextInput({ placeholder: 'Enter index to modify' })
        .onChange((value: string) => {
          this.indexToModify = value;
        })
        .margin(10)
        .width('80%')

      TextInput({ placeholder: 'Enter new value' })
        .onChange((value: string) => {
          this.newValue = value;
        })
        .margin(10)
        .width('80%')

      Button('Modify LinkedList')
        .onClick(() => {
          if (this.indexToModify && this.newValue) {
            this.linkedList.set(Number(this.indexToModify), Number(this.newValue));
            this.indexToModify = '';
            this.newValue = '';
          }
        })
        .margin(10)
        .width('80%')

      ForEach(this.linkedList.toArray(), (item: number, index: number) => {
        Text(`Index ${index}: ${item}`)
          .fontSize(18)
          .margin(10)
      })
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(0xF1F3F5)
  }
}

class LinkedList {
  private head: Node | null = null;
  private tail: Node | null = null;
  private length: number = 0;

  add(value: number): void {
    const newNode = new Node(value);
    if (!this.head) {
      this.head = newNode;
      this.tail = newNode;
    } else {
      this.tail!.next = newNode;
      this.tail = newNode;
    }
    this.length++;
  }

  set(index: number, value: number): void {
    if (index < 0 || index >= this.length) return;
    let current = this.head;
    for (let i = 0; i < index; i++) {
      current = current!.next;
    }
    current!.value = value;
  }

  toArray(): number[] {
    const result: number[] = [];
    let current = this.head;
    while (current) {
      result.push(current.value);
      current = current.next;
    }
    return result;
  }
}

class Node {
  value: number;
  next: Node | null;

  constructor(value: number) {
    this.value = value;
    this.next = null;
  }
}

