@Entry
@Component
struct SearchWithAdaptiveFont {
  @State private searchText: string = '';

  build() {
    Column() {
      TextInput({ placeholder: 'Search...', text: this.searchText })
        .onChange((value: string) => {
          this.searchText = value;
        })
        .width('80%')
        .height(50)
        .fontSize(this.calculateFontSize(this.searchText.length))
        .borderRadius(10)
        .padding(10)
        .backgroundColor(Color.White)
        .margin(20)

      if (this.searchText) {
        Text(`Searching for: ${this.searchText}`)
          .fontSize(16)
          .fontColor(Color.Black)
          .margin(10)
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(0xFFD3D3D3)
  }

  private calculateFontSize(textLength: number): number {
    const baseSize = 16;
    const maxSize = 24;
    const minSize = 12;

    if (textLength <= 10) {
      return maxSize;
    } else if (textLength > 10 && textLength <= 20) {
      return baseSize;
    } else {
      return minSize;
    }
  }
}

