@Entry
@Component
struct BasicShapesCanvas {
  private settings: RenderingContextSettings = new RenderingContextSettings(true)
  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings)

  build() {
    Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Center, justifyContent: FlexAlign.Center }) {
      Canvas(this.context)
        .width('100%')
        .height('100%')
        .backgroundColor('#ffffff')
        .onReady(() => {
          // Draw a rectangle
          this.context.fillStyle = '#ff0000'
          this.context.fillRect(50, 50, 150, 100)

          // Draw a circle
          this.context.beginPath()
          this.context.arc(250, 150, 50, 0, 2 * Math.PI)
          this.context.fillStyle = '#00ff00'
          this.context.fill()

          // Draw a triangle
          this.context.beginPath()
          this.context.moveTo(350, 50)
          this.context.lineTo(300, 150)
          this.context.lineTo(400, 150)
          this.context.closePath()
          this.context.fillStyle = '#0000ff'
          this.context.fill()

          // Draw a line
          this.context.beginPath()
          this.context.moveTo(50, 200)
          this.context.lineTo(200, 200)
          this.context.lineWidth = 5
          this.context.strokeStyle = '#ff00ff'
          this.context.stroke()
        })
    }
    .width('100%')
    .height('100%')
  }
}

