      }, 1000);
    });
  }
}

@Entry
@Component
struct MultiSelectList {
  private items: Array<IListItem> = [
    { id: 1, name: 'Item 1', selected: false },
    { id: 2, name: 'Item 2', selected: false },
    { id: 3, name: 'Item 3', selected: false },
    { id: 4, name: 'Item 4', selected: false }
  ];

  @State private selectedCount: number = 0;

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.items, (item: IListItem) => {
          ListItem() {
            Row() {
              Image($r('app.media.app_icon'))
                .width(50)
                .height(50)
                .margin({ right: 10 });

              Text(item.name)
                .fontSize(18)
                .fontWeight(FontWeight.Medium);

              Checkbox({ name: `item${item.id}`, group: 'itemGroup' })
                .select(item.selected)
                .selectedColor(Color.Blue)
                .shape(CheckBoxShape.CIRCLE)
                .onChange((selected: boolean) => {
                  const updatedItems = [...this.items];
                  const index = updatedItems.findIndex(i => i.id === item.id);
                  updatedItems[index].selected = selected;
                  this.items = updatedItems;
                  this.selectedCount = updatedItems.filter(i => i.selected).length;
                });
            }
            .padding(10)
            .backgroundColor(item.selected ? '#e0f7fa' : '#ffffff')
            .borderRadius(5)
            .onClick(() => {
              const updatedItems = [...this.items];
              const index = updatedItems.findIndex(i => i.id === item.id);
              updatedItems[index].selected = !item.selected;
              this.items = updatedItems;
              this.selectedCount = updatedItems.filter(i => i.selected).length;
            });
          }
          .margin({ bottom: 10 });
        });
      }
      .layoutWeight(1)
      .width('100%');

      Button('Show Selected Count')
        .onClick(() => {
          AlertDialog.show({
            title: 'Selected Items',
            message: `Selected Items: ${this.selectedCount}`,
            confirm: {
              value: 'OK',
              action: () => {}
            }
          });
        })
        .margin(20);
    }
    .padding(20)
    .backgroundColor('#f5f5f5');
  }
}

interface IListItem {
  id: number;
  name: string;
  selected: boolean;
}

