@Entry
@Component
struct DynamicIndexSpanList {
  @State items: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4', 'Item 5'];
  @State indexSpan: number = 1;
  @State newItem: string = '';

  build() {
    Column() {
      Text('Dynamic Index Span List')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      TextInput({ placeholder: 'Add new item' })
        .onChange((value: string) => {
          this.newItem = value;
        })
        .margin({ bottom: 20 });

      Button('Add Item')
        .onClick(() => {
          if (this.newItem) {
            this.items.push(this.newItem);
            this.newItem = '';
          }
        })
        .margin({ bottom: 20 });

      List() {
        ForEach(this.items, (item: string, index: number) => {
          ListItem() {
            Row() {
              Text(item)
                .fontSize(18)
                .margin({ left: 10 });
              Image($r('app.media.app_icon'))
                .width(30)
                .height(30)
                .margin({ left: 10 });
              Button('Remove')
                .onClick(() => {
                  this.items.splice(index, 1);
                });
            }
            .padding(10)
          }
          .backgroundColor('#f0f0f0')
          .borderRadius(5)
          .margin({ bottom: 10 });
        })
      }
      .lanes({ minLength: this.indexSpan, maxLength: this.indexSpan })
      .width('100%');

      Row() {
        Button('Increase Span')
          .onClick(() => {
            if (this.indexSpan < 3) {
              this.indexSpan += 1;
            }
          })
          .margin({ right: 10 });

        Button('Decrease Span')
          .onClick(() => {
            if (this.indexSpan > 1) {
              this.indexSpan -= 1;
            }
          });
      }
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

