@Entry
@Component
struct BookSearchApp {
  private books: Array<Book> = [
    {
      id: 1,
      title: 'Book 1',
      author: 'Author 1',
      coverImage: $r('app.media.app_icon')
    },
    {
      id: 2,
      title: 'Book 2',
      author: 'Author 2',
      coverImage: $r('app.media.app_icon')
    },
    {
      id: 3,
      title: 'Book 3',
      author: 'Author 3',
      coverImage: $r('app.media.app_icon')
    },
    {
      id: 4,
      title: 'Book 4',
      author: 'Author 4',
      coverImage: $r('app.media.app_icon')
    }
  ];

  @State searchText: string = '';

  filteredBooks(): Array<Book> {
    if (this.searchText.trim() === '') {
      return this.books;
    } else {
      return this.books.filter(book =>
        book.title.toLowerCase().includes(this.searchText.toLowerCase()) ||
        book.author.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  build() {
    Column() {
      TextInput({
        placeholder: 'Search books...',
        text: this.searchText
      })
        .width('100%')
        .onChange((value: string) => {
          this.searchText = value;
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      if (this.filteredBooks().length > 0) {
        List() {
          ForEach(this.filteredBooks(), (book: Book) => {
            ListItem() {
              Row() {
                Image(book.coverImage)
                  .width(60)
                  .height(60)
                  .borderRadius(8)
                  .objectFit(ImageFit.Cover);

                Column() {
                  Text(book.title)
                    .fontSize(18)
                    .fontWeight(FontWeight.Medium)
                    .margin({ left: 16 });

                  Text(book.author)
                    .fontSize(14)
                    .fontColor(Color.Gray)
                    .margin({ left: 16, top: 4 });
                }
                .layoutWeight(1)
                .alignItems(HorizontalAlign.Start);
              }
              .padding(12);
            }
          }, (book: Book) => book.id.toString());
        }
      } else {
        Text('No books found')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

interface Book {
  id: number;
  title: string;
  author: string;
  coverImage: Resource;
}

@Entry
@Component
struct EditableTitleBar {
  @State private isEditing: boolean = false;
  @State private tempTitle: string = "Editable Title";
  @State private title: string = "Editable Title";

  build() {
    Flex({ direction: FlexDirection.Row, alignItems: ItemAlign.Center, justifyContent: FlexAlign.Center }) {
      // Back Button
      Flex({ direction: FlexDirection.Row, alignItems: ItemAlign.Start, justifyContent: FlexAlign.Start }) {
        Column() {
          Image($r("app.media.app_icon")).width(40).height(40)
            .margin({ left: 20 })
        }
        .padding(10)
      }
      .width('20%')

      // Title or Editable Text
      Flex({ direction: FlexDirection.Row, alignItems: ItemAlign.Center, justifyContent: FlexAlign.Center }) {
        if (this.isEditing) {
          TextInput({ text: this.tempTitle })
            .onChange((value: string) => {
              this.tempTitle = value;
            })
            .onSubmit(() => {
              this.isEditing = false;
              this.title = this.tempTitle;
            })
        } else {
          Text(this.title)
            .fontSize(20)
            .fontColor(Color.White)
            .onClick(() => {
              this.isEditing = true;
            })
        }
      }
      .width('60%')

      // Right Action
      Flex({ direction: FlexDirection.Row, alignItems: ItemAlign.End, justifyContent: FlexAlign.End }) {
        Stack() {
          Text('').visibility(Visibility.Hidden)
          Image($r("app.media.app_icon")).width(40).height(40)
            .margin({ right: 20 })
        }
        .padding(10)
      }
      .width('20%')
    }
    .width('100%')
    .height(60)
    .linearGradient({
      angle: 180,
      colors: [['#ff56ae97', 0], ['#56ae97', 1]]
    })
    .zIndex(99)
  }
}

@Entry
@Component
struct LoginScreen {
  @State email: string = ''
  @State password: string = ''
  @State loginMessage: string = ''
  @State shouldNavigateToHome: boolean = false

  validateInputs(): boolean {
    if (!this.email || !this.password) {
      this.loginMessage = 'Please fill in all fields'
      return false
    }
    return true
  }

  navigateToHomeScreen() {
    this.shouldNavigateToHome = true
  }

  build() {
    Column() {
      Text('Email')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your email', text: this.email })
        .onChange((value: string) => {
          this.email = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      Button('Login')
        .onClick(() => {
          if (this.validateInputs()) {
            this.loginMessage = 'Login successful!'
            this.navigateToHomeScreen()
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      if (this.loginMessage) {
        Text(this.loginMessage)
          .fontSize(16)
          .margin({ top: 20 })
          .fontColor(this.shouldNavigateToHome ? Color.Green : Color.Red)
      }

      if (this.shouldNavigateToHome) {
        Navigator({ target: 'pages/HomePage' })
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

