@Entry
@Component
struct MultiStepWorkflow {
  @State currentStep: number = 1
  private totalSteps: number = 4

  @Builder
  StepCircle(step: number) {
    Stack() {
      Circle()
        .width(40)
        .height(40)
        .fill(this.currentStep >= step ? '#0000FF' : '#CCCCCC')
      Text(step.toString())
        .fontSize(20)
        .fontColor(Color.White)
    }
  }

  build() {
    Column() {
      Row() {
        ForEach([1, 2, 3, 4], (step: number) => {
          Column() {
            this.StepCircle(step)
            Text(`Step ${step}`)
              .fontSize(16)
              .margin({ top: 10 })
          }

          if (step < this.totalSteps) {
            Divider()
              .width(50)
              .strokeWidth(2)
              .color(this.currentStep > step ? '#0000FF' : '#CCCCCC')
          }
        })
      }
      .margin({ top: 50, bottom: 50 })

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.currentStep > 1) {
              this.currentStep--
            }
          })
          .margin({ right: 20 })
          .enabled(this.currentStep > 1)

        Button('Next')
          .onClick(() => {
            if (this.currentStep < this.totalSteps) {
              this.currentStep++
            }
          })
          .enabled(this.currentStep < this.totalSteps)
      }
    }
    .width('100%')
    .padding(20)
  }
}

