@Component
struct ChainAnimationList {
  private scroller: Scroller = new Scroller();
  @State items: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4', 'Item 5', 'Item 6', 'Item 7', 'Item 8', 'Item 9', 'Item 10'];
  @State isAnimating: boolean = false;

  build() {
    Column() {
      Button(this.isAnimating ? 'Stop Animation' : 'Start Animation')
        .onClick(() => {
          this.isAnimating = !this.isAnimating;
        })
        .margin(20)

      List({ space: 20, scroller: this.scroller }) {
        ForEach(this.items, (item: string, index: number) => {
          ListItem() {
            Text(item)
              .fontSize(20)
              .textAlign(TextAlign.Center)
              .backgroundColor('#95efd2')
              .width('100%')
              .height(100)
              .borderRadius(10)
              .animation({
                duration: 300,
                curve: Curve.EaseInOut,
                delay: index * 100,
                playMode: this.isAnimating ? PlayMode.Normal : PlayMode.Reverse
              })
          }
        })
      }
      .width('100%')
      .height('80%')
      .onScrollIndex((start: number, end: number) => {
        console.info(`Visible items range: ${start} to ${end}`);
      })
      .edgeEffect(EdgeEffect.Spring)
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }
}

