  @State private blurRadius: number = 5;

  build() {
    Column({ space: 10 }) {
      TextInput({ placeholder: 'Enter text here' })
        .width('80%')
        .height(40)
        .backgroundColor(this.isBlurred ? '#f0f0f0' : '#ffffff')
        .onBlur(() => {
          this.isBlurred = true;
          console.log('TextInput blurred');
        })
        .onFocus(() => {
          this.isBlurred = false;
          console.log('TextInput focused');
        })

      Image($r('app.media.app_icon'))
        .width(120)
        .height(120)
        .blur(this.blurRadius)
        .onBlur(() => {
          console.log('Image blurred');
        })

      Slider({
        value: this.blurRadius,
        min: 0,
        max: 10,
        step: 1
      })
      .onChange((value: number) => {
        this.blurRadius = value;
      })
      .width('80%')

      Text(`Current Blur Radius: ${this.blurRadius}`)
        .fontSize(16)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

