@Component
struct ImageGallery {
  @State selectedImage: Resource = $r('app.media.app_icon')
  @State selectedDescription: string = ''
  @State showFullScreen: boolean = false

  private images: Array<ImageItem> = [
    { image: $r('app.media.app_icon'), description: 'Description for image 1' },
    { image: $r('app.media.app_icon'), description: 'Description for image 2' },
    { image: $r('app.media.app_icon'), description: 'Description for image 3' },
    { image: $r('app.media.app_icon'), description: 'Description for image 4' },
    { image: $r('app.media.app_icon'), description: 'Description for image 5' },
    { image: $r('app.media.app_icon'), description: 'Description for image 6' },
    { image: $r('app.media.app_icon'), description: 'Description for image 7' },
    { image: $r('app.media.app_icon'), description: 'Description for image 8' },
    { image: $r('app.media.app_icon'), description: 'Description for image 9' },
    { image: $r('app.media.app_icon'), description: 'Description for image 10' }
  ]

  build() {
    Column() {
      if (this.showFullScreen) {
        Stack() {
          Column() {
            Image(this.selectedImage)
              .objectFit(ImageFit.Contain)
              .width('100%')
              .height('80%')

            Text(this.selectedDescription)
              .fontSize(16)
              .textAlign(TextAlign.Center)
              .margin({ top: 10 })
          }

          Button('Close')
            .onClick(() => {
              this.showFullScreen = false
            })
            .position({ x: 20, y: 20 })
            .backgroundColor('#FFFFFF')
            .padding({ left: 10, right: 10, top: 5, bottom: 5 })
            .borderRadius(5)
        }
      } else {
        Grid() {
          ForEach(this.images, (item: ImageItem) => {
            GridItem() {
              Image(item.image)
                .width('100%')
                .aspectRatio(1)
                .objectFit(ImageFit.Cover)
                .borderRadius(5)
                .onClick(() => {
                  this.selectedImage = item.image
                  this.selectedDescription = item.description
                  this.showFullScreen = true
                })
            }
          })
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsGap(10)
        .columnsGap(10)
        .padding(10)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

