@Entry
@Component
struct InputValidationApp {
  @State inputValue: string = ''
  @State errorMessage: string = ''
  @State isValid: boolean = false
  controller: TextInputController = new TextInputController()

  validateInput(text: string): boolean {
    // Example validation: Check if the input is a valid phone number
    const phonePattern = /^[0-9]{10}$/
    return phonePattern.test(text)
  }

  handleInputChange(value: string) {
    this.inputValue = value
    this.isValid = this.validateInput(value)
    this.errorMessage = this.isValid ? '' : 'Invalid phone number format (10 digits required)'
  }

  build() {
    Column() {
      TextInput({ placeholder: 'Enter your phone number', controller: this.controller })
        .width(380)
        .height(60)
        .margin(10)
        .onChange((value: string) => {
          this.handleInputChange(value)
        })
        .border({
          width: 1,
          color: this.errorMessage ? Color.Red : Color.Gray
        })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin(10)
      }

      Button('Submit')
        .width(200)
        .height(50)
        .margin(10)
        .enabled(this.isValid)
        .onClick(() => {
          console.log('Valid input:', this.inputValue)
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

