@Component
struct SplashScreenApp {
  @State private isSplashVisible: boolean = true;
  @State private rotation: number = 0;
  private intervalID: number = -1;

  aboutToAppear() {
    this.intervalID = setInterval(() => {
      this.rotation = (this.rotation + 10) % 360;
    }, 50);

    setTimeout(() => {
      this.isSplashVisible = false;
      clearInterval(this.intervalID);
    }, 3000);
  }

  build() {
    Stack() {
      if (this.isSplashVisible) {
        Column() {
          Image($r('app.media.app_icon'))
            .width(200)
            .height(200)
            .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })
            .margin({ bottom: 20 });
          Text('Welcome to My App')
            .fontSize(24)
            .fontWeight(FontWeight.Bold);
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center)
        .backgroundColor('#FFFFFF');
      } else {
        this.MainScreen();
      }
    }
    .width('100%')
    .height('100%');
  }

  @Builder MainScreen() {
    Column() {
      Column() {
        if (this.currentIndex === 0) {
          this.HomeScreen();
        } else if (this.currentIndex === 1) {
          this.ProfileScreen();
        } else {
          this.SettingsScreen();
        }
      }
      .layoutWeight(1);

      Row() {
        this.NavButton('Home', 0);
        this.NavButton('Profile', 1);
        this.NavButton('Settings', 2);
      }
      .width('100%')
      .height(60)
      .backgroundColor(Color.White);
    }
    .height('100%');
  }

  @State private currentIndex: number = 0;

  @Builder NavButton(label: string, index: number) {
    Column() {
      Text(label)
        .fontSize(16)
        .fontColor(this.currentIndex === index ? '#1698CE' : '#666666');
    }
    .onClick(() => {
      this.currentIndex = index;
    })
    .width('33.33%')
    .padding(10)
    .alignItems(HorizontalAlign.Center);
  }

  @Builder HomeScreen() {
    Column() {
      Text('Home Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }

  @Builder ProfileScreen() {
    Column() {
      Text('Profile Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }

