@Component
struct AnimatedPageTransitionApp {
  @State private currentPage: number = 0;

  build() {
    Column() {
      if (this.currentPage === 0) {
        PageOne()
          .transition({ type: TransitionType.Insert, opacity: 0, translate: { x: -100, y: 0 } })
          .transition({ type: TransitionType.Delete, opacity: 0, translate: { x: 100, y: 0 } })
      } else {
        PageTwo()
          .transition({ type: TransitionType.Insert, opacity: 0, translate: { x: 100, y: 0 } })
          .transition({ type: TransitionType.Delete, opacity: 0, translate: { x: -100, y: 0 } })
      }

      Row() {
        Button('Go to Page 1')
          .onClick(() => {
            animateTo({
              duration: 300,
              curve: Curve.EaseInOut
            }, () => {
              this.currentPage = 0;
            })
          })
          .margin(10)
        Button('Go to Page 2')
          .onClick(() => {
            animateTo({
              duration: 300,
              curve: Curve.EaseInOut
            }, () => {
              this.currentPage = 1;
            })
          })
          .margin(10)
      }
      .justifyContent(FlexAlign.Center)
      .width('100%')
      .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .backgroundColor($r('sys.color.ohos_id_color_background'))
  }
}

