@Entry
@Component
struct GestureEventHandling {
  @State private message: string = "Perform a Gesture"
  @State private isTapped: boolean = false

  build() {
    Column({ space: 20 }) {
      Text(this.message)
        .fontSize(20)
        .textAlign(TextAlign.Center)
        .margin({ top: 20 })

      // TapGesture example
      Flex({ justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
        Text("Tap Here")
          .fontSize(18)
          .padding(20)
          .backgroundColor(0xeeeeee)
          .borderRadius(10)
          .gesture(
            TapGesture({ count: 1 })
              .onAction(() => {
                this.message = "Tap Detected"
                this.isTapped = !this.isTapped
              })
          )
      }

      // SwipeGesture example
      Flex({ justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
        Text("Swipe Here")
          .fontSize(18)
          .padding(20)
          .backgroundColor(0xeeeeee)
          .borderRadius(10)
          .gesture(
            SwipeGesture({ direction: SwipeDirection.Horizontal })
              .onAction(() => {
                this.message = "Swipe Detected"
              })
          )
      }

      // Image with TapGesture
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .gesture(
          TapGesture()
            .onAction(() => {
              this.isTapped = !this.isTapped
              console.log('Image tapped!')
            })
        )
        .backgroundColor(this.isTapped ? Color.Red : Color.Green)
    }
    .width('100%')
    .height('100%')
    .backgroundColor(0xf5f5f5)
  }
}

@Entry
@Component
struct SearchHistoryTracker {
  @State searchText: string = '';
  @State searchHistory: string[] = [];

  addToHistory(searchTerm: string) {
    if (searchTerm.trim() !== '' && !this.searchHistory.includes(searchTerm)) {
      this.searchHistory.unshift(searchTerm);
      if (this.searchHistory.length > 10) {
        this.searchHistory.pop();
      }
    }
  }

  build() {
    Column() {
      TextInput({
        placeholder: 'Search...',
        text: this.searchText
      })
        .width('100%')
        .onChange((value: string) => {
          this.searchText = value;
        })
        .onSubmit(() => {
          this.addToHistory(this.searchText);
          this.searchText = '';
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      if (this.searchHistory.length > 0) {
        Text('Search History')
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 16, bottom: 8 });

        List() {
          ForEach(this.searchHistory, (historyItem: string) => {
            ListItem() {
              Text(historyItem)
                .fontSize(18)
                .padding(12);
            }
          }, (historyItem: string) => historyItem);
        }
      } else {
        Text('No search history available')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

