@Entry
@Component
struct ItemListApp {
  private items: Array<Item> = [
    {
      id: 1,
      title: 'Mountain View',
      image: $r('app.media.app_icon'),
      description: 'A beautiful mountain landscape with snow-capped peaks and green valleys.'
    },
    {
      id: 2,
      title: 'Beach Sunset',
      image: $r('app.media.app_icon'),
      description: 'Golden sunset over a tropical beach with palm trees.'
    },
    {
      id: 3,
      title: 'City Lights',
      image: $r('app.media.app_icon'),
      description: 'Modern cityscape at night with glowing skyscrapers.'
    }
  ];

  @State selectedItem: Item | null = null;

  dialogController: CustomDialogController = new CustomDialogController({
    builder: () => this.DialogBuilder(),
    customStyle: true,
    alignment: DialogAlignment.Center
  });

  @Builder
  DialogBuilder(): void {
    if (this.selectedItem) {
      Column() {
        Image(this.selectedItem.image)
          .width('100%')
          .height(200)
          .borderRadius(8)
          .objectFit(ImageFit.Cover);

        Text(this.selectedItem.title)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 16, bottom: 8 });

        Text(this.selectedItem.description)
          .fontSize(16)
          .lineHeight(24);

        Button('Close')
          .onClick(() => {
            this.dialogController.close();
          });
      }
      .padding(24)
      .width('90%')
      .backgroundColor(Color.White)
      .borderRadius(16);
    }
  }

  build() {
    Column() {
      Text('Item List')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      List() {
        ForEach(this.items, (item: Item) => {
          ListItem() {
            Row() {
              Image(item.image)
                .width(100)
                .height(100)
                .borderRadius(8)
                .objectFit(ImageFit.Cover);

              Text(item.title)
                .fontSize(20)
                .fontWeight(FontWeight.Medium)
                .margin({ left: 16 });
            }
            .padding(16)
            .onClick(() => {
              this.selectedItem = item;
              this.dialogController.open();
            });
          }
          .margin({ bottom: 12 });
        });
      }
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }
}

