import promptAction from '@ohos.promptAction';

@Entry
@Component
struct ContactForm {
  @State name: string = '';
  @State email: string = '';
  @State message: string = '';

  build() {
    Column() {
      Text('Contact Us')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value;
          });
      }

      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value;
          });
      }

      Column() {
        Text('Message:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your message' })
          .width('100%')
          .height(100)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.message = value;
          });
      }

      Button('Send')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.name && this.email && this.message) {
            this.sendEmail();
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields'
            });
          }
        });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }

  sendEmail() {
    setTimeout(() => {
      promptAction.showToast({
        message: 'Email sent successfully'
      });
    }, 1000);
  }
}

