@Entry
@Component
struct ListSettingsConfig {
  @State listItems: Array<string> = ["Option 1", "Option 2", "Option 3", "Option 4", "Option 5"];
  @State selectedItems: Array<string> = [];
  @State isSettingsVisible: boolean = false;

  build() {
    Column() {
      // Main Content Area
      Column() {
        Text('List Settings Configuration').fontSize(28).fontWeight(FontWeight.Bold).margin(10);
        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
          .margin(16);

        List({ space: 10 }) {
          ForEach(this.listItems, (item: string) => {
            ListItem() {
              Row() {
                Text(item)
                  .fontSize(18)
                  .margin({ right: 20 });

                Checkbox({ name: item, group: 'itemGroup' })
                  .select(this.selectedItems.includes(item))
                  .onChange((selected: boolean) => {
                    if (selected) {
                      this.selectedItems.push(item);
                    } else {
                      this.selectedItems = this.selectedItems.filter(selectedItem => selectedItem !== item);
                    }
                  });
              }
              .padding(10);
            }
          });
        }
        .width("100%")
        .height("60%");

        Text(`Selected Items: ${this.selectedItems.join(", ")}`)
          .fontSize(18)
          .padding(10);
      }
      .layoutWeight(1);

      // Settings Toggle Button
      Button('Configure Settings')
        .onClick(() => {
          this.isSettingsVisible = !this.isSettingsVisible;
        })
        .width('100%');

      // Settings Panel
      if (this.isSettingsVisible) {
        this.SettingsPanel();
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor("#ffffff");
  }

  @Builder SettingsPanel() {
    Column() {
      Text('Settings Panel').fontSize(24).margin(10);

      // Add New Item Option
      Button('Add New Item')
        .onClick(() => {
          this.listItems.push(`Option ${this.listItems.length + 1}`);
        })
        .width('100%');

      // Remove Selected Items Option
      Button('Remove Selected Items')
        .onClick(() => {
          this.listItems = this.listItems.filter(item => !this.selectedItems.includes(item));
          this.selectedItems = [];
        })
        .width('100%');

      // Clear All Items Option
      Button('Clear All Items')
        .onClick(() => {
          this.listItems = [];
          this.selectedItems = [];
        })
        .width('100%');
    }
    .width('80%')
    .height('40%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

