@Entry
@Component
struct NavigationDrawerApp {
  @State isDrawerOpen: boolean = false;
  @State selectedScreenIndex: number = 0;
  @State dynamicContent: string = 'Default Content';

  build() {
    Row() {
      // Main Content Area
      Column() {
        this.ScreenContent()
        this.DrawerButton()
      }
      .layoutWeight(1)

      // Drawer Panel
      Panel(this.isDrawerOpen) {
        Column() {
          this.NavItem('Home', 0)
          this.NavItem('Profile', 1)
          this.NavItem('Settings', 2)
        }
        .width('80%')
        .height('100%')
        .backgroundColor(Color.White)
      }
      .mode(PanelMode.Mini)
      .type(PanelType.Temporary)
      .dragBar(false)
    }
    .width('100%')
    .height('100%')
  }

  @Builder DrawerButton() {
    Button('Toggle Drawer')
      .onClick(() => {
        this.isDrawerOpen = !this.isDrawerOpen;
      })
  }

  @Builder NavItem(label: string, index: number) {
    Text(label)
      .fontSize(20)
      .margin(10)
      .onClick(() => {
        this.selectedScreenIndex = index;
        this.isDrawerOpen = false;
        this.loadDynamicContent(index);
      })
  }

  @Builder ScreenContent() {
    if (this.selectedScreenIndex === 0) {
      this.HomeScreen();
    } else if (this.selectedScreenIndex === 1) {
      this.ProfileScreen();
    } else {
      this.SettingsScreen();
    }
  }

  @Builder HomeScreen() {
    Column() {
      Text('Home Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin(16);
      Text(this.dynamicContent)
        .fontSize(16)
        .margin(16);
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(16);
    }
    .width('100%')
    .height('100%');
  }

  @Builder ProfileScreen() {
    Column() {
      Text('Profile Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin(16);
      Text(this.dynamicContent)
        .fontSize(16)
        .margin(16);
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(16);
    }
    .width('100%')
    .height('100%');
  }

  @Builder SettingsScreen() {
    Column() {
      Text('Settings Screen')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin(16);
      Text(this.dynamicContent)
        .fontSize(16)
        .margin(16);
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(16);
    }
    .width('100%')
    .height('100%');
  }

  loadDynamicContent(index: number) {
    if (index === 0) {
      this.dynamicContent = 'Dynamic Content for Home Screen';
    } else if (index === 1) {
      this.dynamicContent = 'Dynamic Content for Profile Screen';
    } else {
      this.dynamicContent = 'Dynamic Content for Settings Screen';
    }
  }
}

@Entry
@Component
struct TitledImageGridApp {
  @State selectedImage: string = ''
  @State showFullScreen: boolean = false
  @State imageDetails: string = ''

  private images: ImageItem[] = [
    { title: 'Image 1', image: 'app.media.app_icon', description: 'Detailed information about Image 1.' },
    { title: 'Image 2', image: 'app.media.app_icon', description: 'Detailed information about Image 2.' },
    { title: 'Image 3', image: 'app.media.app_icon', description: 'Detailed information about Image 3.' },
    { title: 'Image 4', image: 'app.media.app_icon', description: 'Detailed information about Image 4.' },
    { title: 'Image 5', image: 'app.media.app_icon', description: 'Detailed information about Image 5.' },
    { title: 'Image 6', image: 'app.media.app_icon', description: 'Detailed information about Image 6.' }
  ]

  build() {
    Column() {
      if (this.showFullScreen) {
        Stack() {
          Image(this.selectedImage)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%')

          Column() {
            Text(this.imageDetails)
              .fontSize(16)
              .fontColor('#000000')
              .margin({ top: 20, bottom: 10 })

            Button('Close')
              .onClick(() => {
                this.showFullScreen = false
              })
              .backgroundColor('#FFFFFF')
              .padding({ left: 10, right: 10, top: 5, bottom: 5 })
              .borderRadius(5)
          }
          .alignItems(HorizontalAlign.Center)
          .width('100%')
          .margin({ top: 20 })
        }
      } else {
        Grid() {
          ForEach(this.images, (item: ImageItem) => {
            GridItem() {
              Column() {
                Image(item.image)
                  .width('100%')
                  .aspectRatio(1)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(5)
                  .onClick(() => {
                    this.selectedImage = item.image
                    this.imageDetails = item.description
                    this.showFullScreen = true
                  })

                Text(item.title)
                  .fontSize(16)
                  .fontWeight(FontWeight.Medium)
                  .margin({ top: 8 })
              }
            }
          })
        }
        .columnsTemplate('1fr 1fr')
        .rowsGap(10)
        .columnsGap(10)
        .padding(10)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

