@Entry
@Component
struct ImageCarousel {
  private swiperController: SwiperController = new SwiperController();

  private carouselItems: Array<CarouselItem> = [
    {
      id: 1,
      image: $r('app.media.app_icon'),
      caption: 'Mountain View'
    },
    {
      id: 2,
      image: $r('app.media.app_icon'),
      caption: 'Ocean Sunset'
    },
    {
      id: 3,
      image: $r('app.media.app_icon'),
      caption: 'Forest Path'
    },
    {
      id: 4,
      image: $r('app.media.app_icon'),
      caption: 'Desert Dunes'
    }
  ];

  @State currentIndex: number = 0;

  build() {
    Column() {
      Text('Image Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Column() {
        Swiper(this.swiperController) {
          ForEach(this.carouselItems, (item: CarouselItem) => {
            Stack() {
              Image(item.image)
                .width('100%')
                .height(300)
                .objectFit(ImageFit.Cover)
                .borderRadius(16);
            }
          });
        }
        .width('100%')
        .height(300)
        .margin({ bottom: 16 })
        .autoPlay(true)
        .interval(3000)
        .indicator(true)
        .loop(true)
        .duration(500)
        .onChange((index: number) => {
          this.currentIndex = index;
          globalThis.ohos.prompt.showToast({
            message: this.carouselItems[index].caption,
            duration: 2000
          });
        });

        Text(this.carouselItems[this.currentIndex].caption)
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 8 })
          .textAlign(TextAlign.Center);
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(20);

      Row() {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });

        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

interface CarouselItem {
  id: number;
  image: Resource;
  caption: string;
}

@Entry
@Component
struct MusicPlayer {
  @State isPlaying: boolean = false
  @State currentSong: string = 'Awesome Song'
  @State currentArtist: string = 'Cool Artist'
  @State progress: number = 0

  build() {
    Column() {
      // Album art placeholder
      Image($r('app.media.app_icon'))
        .width(300)
        .height(300)
        .borderRadius(10)
        .margin({ top: 20 })

      // Song info
      Text(this.currentSong)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20 })
      Text(this.currentArtist)
        .fontSize(18)
        .margin({ top: 5 })

      // Progress bar
      Slider({
        value: this.progress,
        min: 0,
        max: 100,
        step: 1
      })
        .width('80%')
        .margin({ top: 20 })

      // Playback controls
      Row({ space: 20 }) {
        Button('Previous')
          .onClick(() => {
            console.info('Previous song')
          })
          .width(100)
          .height(40)

        Button(this.isPlaying ? 'Pause' : 'Play')
          .onClick(() => {
            this.isPlaying = !this.isPlaying
          })
          .width(100)
          .height(40)

        Button('Next')
          .onClick(() => {
            console.info('Next song')
          })
          .width(100)
          .height(40)

        Button('Stop')
          .onClick(() => {
            this.isPlaying = false
            this.progress = 0
          })
          .width(100)
          .height(40)
      }
      .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor($r('sys.color.ohos_id_color_background'))
  }
}

