@Entry
@Component
struct DataLoadingApp {
    @State isLoading: boolean = false
    @State progressValue: number = 0
    @State data: string[] = []

    aboutToAppear() {
        this.fetchData()
    }

    private fetchData() {
        this.isLoading = true
        this.progressValue = 0
        let interval = setInterval(() => {
            if (this.progressValue < 100) {
                this.progressValue += 5
            } else {
                clearInterval(interval)
                this.isLoading = false
                this.data = ['Fetched Data A', 'Fetched Data B', 'Fetched Data C']
            }
        }, 300)
    }

    build() {
        Column() {
            if (this.isLoading) {
                Progress({
                    value: this.progressValue,
                    total: 100,
                    type: ProgressType.Linear
                })
                .size({ width: '80%', height: 20 })
                .color(Color.Blue)
                Text('Fetching Data...').fontSize(20).margin(10)
            } else {
                List() {
                    ForEach(this.data, (item: string) => {
                        ListItem() {
                            Text(item).fontSize(30)
                        }
                    }, (item: string) => item)
                }
            }
        }
        .width('100%')
        .height('100%')
        .padding(20)
        .backgroundColor(Color.White)
    }
}

