    if (!this.email.includes('@')) {
      this.errorMessage = 'Please enter a valid email address';
      return false;
    }
    this.errorMessage = '';
    return true;
  }

  build() {
    Column() {
      // Form Title
      Text('User Information')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      // Name Input
      Text('Name:')
        .fontSize(16)
        .margin({ bottom: 8 });

      TextInput({ placeholder: 'Enter your name' })
        .width('100%')
        .height(40)
        .margin({ bottom: 20 })
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .onChange((value: string) => {
          this.name = value;
        });

      // Email Input
      Text('Email:')
        .fontSize(16)
        .margin({ bottom: 8 });

      TextInput({ placeholder: 'Enter your email' })
        .width('100%')
        .height(40)
        .margin({ bottom: 20 })
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .onChange((value: string) => {
          this.email = value;
        });

      // Phone Number Input
      Text('Phone Number:')
        .fontSize(16)
        .margin({ bottom: 8 });

      TextInput({ placeholder: 'Enter your phone number' })
        .width('100%')
        .height(40)
        .margin({ bottom: 20 })
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .onChange((value: string) => {
          this.phoneNumber = value;
        });

      // Error Message
      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ bottom: 20 });
      }

      // Submit Button
      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.validateForm()) {
            promptAction.showToast({
              message: `Name: ${this.name}\nEmail: ${this.email}\nPhone: ${this.phoneNumber}`
            });
          }
        });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

