@Entry
@Component
struct AuthApp {
  @State email: string = ''
  @State password: string = ''
  @State message: string = ''
  @State isSuccess: boolean = false
  @State showMessage: boolean = false

  build() {
    Column() {
      // App Logo/Header
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ bottom: 30 })

      // Email Input Section
      Text('Email')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })
        .width('80%')
        .textAlign(TextAlign.Start)

      TextInput({ placeholder: 'Enter your email', text: this.email })
        .width('80%')
        .height(40)
        .margin({ bottom: 20 })
        .borderRadius(5)
        .borderWidth(1)
        .borderColor('#CCCCCC')
        .onChange((value: string) => {
          this.email = value
        })

      // Password Input Section
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })
        .width('80%')
        .textAlign(TextAlign.Start)

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .width('80%')
        .height(40)
        .margin({ bottom: 30 })
        .borderRadius(5)
        .borderWidth(1)
        .borderColor('#CCCCCC')
        .onChange((value: string) => {
          this.password = value
        })

      // Login Button
      Button('Login', { type: ButtonType.Capsule })
        .width('80%')
        .height(45)
        .backgroundColor('#4CAF50')
        .fontColor(Color.White)
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .onClick(() => {
          if (this.validateCredentials()) {
            this.message = 'Authentication successful!'
            this.isSuccess = true
          } else {
            this.message = 'Invalid email or password'
            this.isSuccess = false
          }
          this.showMessage = true
        })

      // Status Message
      if (this.showMessage) {
        Text(this.message)
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
          .fontColor(this.isSuccess ? Color.Green : Color.Red)
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#F5F5F5')
  }

  validateCredentials(): boolean {
    const emailValid = this.validateEmail(this.email)
    const passwordValid = this.password.length >= 6
    return emailValid && passwordValid && this.email === 'test@example.com' && this.password === 'password123'
  }

  validateEmail(email: string): boolean {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return re.test(email)
  }
}

