struct TextSelectionControl {
  @State text: string = 'This is a sample text for text selection control.';
  @State start: number = 0;
  @State end: number = 10;
  @State selectedText: string = '';

  build() {
    Column() {
      Text(this.text)
        .fontSize(16)
        .border({ width: 1, color: Color.Black })
        .margin(20)
        .selection(this.start, this.end)
        .onTextSelectionChange((start: number, end: number) => {
          this.start = start;
          this.end = end;
          this.selectedText = this.text.substring(start, end);
        })

      Text('Selected Text: ' + this.selectedText)
        .fontSize(14)
        .margin(10)

      Button('Change Selection Range')
        .margin(20)
        .onClick(() => {
          this.start = 5;
          this.end = 15;
        })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

@Entry
@Component
struct Calculator {
  @State result: string = '0'
  @State currentInput: string = ''
  @State operator: string = ''

  build() {
    Column() {
      Text(this.result)
        .fontSize(40)
        .width('100%')
        .textAlign(TextAlign.End)
        .margin({ bottom: 20 })

      Grid() {
        ForEach(['7', '8', '9', '/', '4', '5', '6', '*', '1', '2', '3', '-', 'C', '0', '=', '+'], (button: string) => {
          GridItem() {
            Button(button)
              .width('100%')
              .height(60)
              .onClick(() => this.handleButtonPress(button))
          }
        })
      }
      .columnsTemplate('1fr 1fr 1fr 1fr')
      .rowsTemplate('1fr 1fr 1fr 1fr')
      .width('100%')
      .height(300)
    }
    .width('100%')
    .padding(20)
  }

  handleButtonPress(button: string) {
    if (button >= '0' && button <= '9') {
      this.currentInput += button
      this.result = this.currentInput
    } else if (button === 'C') {
      this.result = '0'
      this.currentInput = ''
      this.operator = ''
    } else if (button === '=') {
      this.calculateResult()
    } else {
      this.operator = button
      this.result = this.currentInput
      this.currentInput = ''
    }
  }

  calculateResult() {
    const num1 = parseFloat(this.result)
    const num2 = parseFloat(this.currentInput)
    let calculatedResult = 0

    switch (this.operator) {
      case '+':
        calculatedResult = num1 + num2
        break
      case '-':
        calculatedResult = num1 - num2
        break
      case '*':
        calculatedResult = num1 * num2
        break
      case '/':
        calculatedResult = num1 / num2
        break
    }

    this.result = calculatedResult.toString()
    this.currentInput = ''
    this.operator = ''
  }
}

