        .loop(true)
        .duration(500)
        .onChange((index: number) => {
          this.currentIndex = index;
        });

        Column() {
          Text(this.carouselItems[this.currentIndex].title)
            .fontSize(20)
            .fontWeight(FontWeight.Medium)
            .margin({ top: 8 })
            .textAlign(TextAlign.Center);

          Text(this.carouselItems[this.currentIndex].description)
            .fontSize(16)
            .lineHeight(24)
            .textAlign(TextAlign.Center)
            .margin({ top: 8 });
        }
        .width('100%')
        .padding(16);
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(20);

      Row() {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });

        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

interface CarouselItem {
  id: number;
  image: Resource;
  title: string;
  description: string;
}

@Entry
@Component
struct ImageGridApp {
  @State selectedImage: Resource = $r('app.media.app_icon')
  @State showFullScreen: boolean = false
  @State showDetails: boolean = false

  private images: Resource[] = [
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon')
  ]

  private details: string[] = [
    'Details for image 1',
    'Details for image 2',
    'Details for image 3',
    'Details for image 4',
    'Details for image 5',
    'Details for image 6',
    'Details for image 7',
    'Details for image 8',
    'Details for image 9',
    'Details for image 10'
  ]

  build() {
    Column() {
      if (this.showFullScreen) {
        Stack() {
          Column() {
            Image(this.selectedImage)
              .objectFit(ImageFit.Contain)
              .width('100%')
              .height('70%')

            if (this.showDetails) {
              Text(this.details[this.images.indexOf(this.selectedImage)])
                .fontSize(16)
                .margin({ top: 20, left: 20, right: 20 })
                .textAlign(TextAlign.Center)
            }
          }

          Column() {
            Button(this.showDetails ? 'Hide Details' : 'Show Details')
              .onClick(() => {
                this.showDetails = !this.showDetails
              })
              .margin({ top: 20 })
              .backgroundColor('#FFFFFF')
              .padding({ left: 10, right: 10, top: 5, bottom: 5 })
              .borderRadius(5)

            Button('Close')
              .onClick(() => {
                this.showFullScreen = false
                this.showDetails = false
              })
              .margin({ top: 10 })
              .backgroundColor('#FFFFFF')
              .padding({ left: 10, right: 10, top: 5, bottom: 5 })
              .borderRadius(5)
          }
          .position({ x: 20, y: 20 })
        }
      } else {
        Grid() {
          ForEach(this.images, (image: Resource, index: number) => {
            GridItem() {
              Image(image)
                .width('100%')
                .aspectRatio(1)
                .objectFit(ImageFit.Cover)
                .borderRadius(5)
                .onClick(() => {
                  this.selectedImage = image
                  this.showFullScreen = true
                })
            }
          })
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsGap(10)
        .columnsGap(10)
        .padding(10)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

