  id: number;
  image: Resource;
  title: string;
  description: string;
}

@Entry
@Component
struct Index {
  @State selectedMovie: Movie | null = null;
  @State rating: number = 0;
  @State comment: string = '';

  @State movies: Movie[] = [
    {
      id: '1',
      title: 'Movie 1',
      releaseDate: '2023-01-01',
      director: 'Director 1',
      description: 'Description of Movie 1',
      image: 'app.media.movie1',
      rating: 0,
      comment: ''
    }
  ];

  build() {
    if (this.selectedMovie == null) {
      Column() {
        Text('Movie List')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .padding(16);

        List() {
          ForEach(this.movies, (movie: Movie) => {
            ListItem() {
              Row() {
                Image(movie.image)
                  .width(100)
                  .height(150)
                  .objectFit(ImageFit.Cover)
                  .margin({ right: 10 });
                Column() {
                  Text(movie.title)
                    .fontSize(20)
                    .fontWeight(FontWeight.Medium)
                    .padding({ bottom: 4 });
                  Text(`Release Date: ${movie.releaseDate}`)
                    .fontSize(16)
                    .padding({ bottom: 8 });
                }
                .padding(16);
              }
              .onClick(() => {
                this.selectedMovie = movie;
                this.rating = movie.rating;
                this.comment = movie.comment;
              });
            }
          });
        }
      }
    } else {
      Scroll() {
        Column() {
          Image(this.selectedMovie.image)
            .width('100%')
            .height(300)
            .objectFit(ImageFit.Cover);

          Text(this.selectedMovie.title)
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .padding(16);

          Text(`Release Date: ${this.selectedMovie.releaseDate}`)
            .fontSize(18)
            .padding({ left: 16, right: 16, bottom: 8 });

          Text(`Director: ${this.selectedMovie.director}`)
            .fontSize(18)
            .padding({ left: 16, right: 16, bottom: 8 });

          Text('Description:')
            .fontSize(20)
            .fontWeight(FontWeight.Medium)
            .padding({ left: 16, right: 16, top: 16, bottom: 4 });

          Text(this.selectedMovie.description)
            .fontSize(16)
            .padding({ left: 16, right: 16, bottom: 16 });

          Text('Rate this movie:')
            .fontSize(20)
            .fontWeight(FontWeight.Medium)
            .padding({ left: 16, right: 16, top: 16, bottom: 4 });

          Row() {
            ForEach([1, 2, 3, 4, 5], (star: number) => {
              Image(this.rating >= star ? 'app.media.star_filled' : 'app.media.star_empty')
                .width(30)
                .height(30)
                .margin({ right: 5 })
                .onClick(() => {
                  this.rating = star;
                });
            });
          }
          .padding({ left: 16, right: 16, bottom: 16 });

          Text('Leave a comment:')
            .fontSize(20)
            .fontWeight(FontWeight.Medium)
            .padding({ left: 16, right: 16, bottom: 8 });

          TextInput({ placeholder: 'Enter your comment here' })
            .height(100)
            .width('90%')
            .onChange((value: string) => {
              this.comment = value;
            })
            .padding({ left: 16, right: 16, bottom: 16 });

          Button('Submit', { type: ButtonType.Capsule })
            .onClick(() => {
              if (this.selectedMovie) {
                this.selectedMovie.rating = this.rating;
                this.selectedMovie.comment = this.comment;
                this.selectedMovie = null;
              }
            })
            .padding({ left: 16, right: 16, bottom: 16 });
        }
      }
    }
  }
}

interface Movie {
  id: string;
  title: string;
  releaseDate: string;
  director: string;
  description: string;
  image: string;
  rating: number;
  comment: string;
}

