@Entry
@Component
struct LoginScreen {
  @State email: string = ''
  @State password: string = ''
  @State emailError: string = ''
  @State passwordError: string = ''
  @State loginMessage: string = ''
  @State isSuccess: boolean = false

  build() {
    Column({ space: 10 }) {
      Text('Email')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)

      TextInput({ placeholder: 'Enter your email' })
        .width('80%')
        .height(40)
        .borderRadius(8)
        .backgroundColor('#F5F5F5')
        .padding({ left: 12 })
        .onChange((value: string) => {
          this.email = value
          this.emailError = ''
        })

      if (this.emailError) {
        Text(this.emailError)
          .fontSize(14)
          .fontColor(Color.Red)
      }

      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)

      TextInput({ placeholder: 'Enter your password' })
        .width('80%')
        .height(40)
        .borderRadius(8)
        .backgroundColor('#F5F5F5')
        .padding({ left: 12 })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
          this.passwordError = ''
        })

      if (this.passwordError) {
        Text(this.passwordError)
          .fontSize(14)
          .fontColor(Color.Red)
      }

      Button('Login')
        .width('60%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#4CAF50')
        .borderRadius(8)
        .onClick(() => {
          this.validateEmail()
          this.validatePassword()
          if (!this.emailError && !this.passwordError) {
            this.loginMessage = 'Login successful!'
            this.isSuccess = true
          } else {
            this.loginMessage = 'Validation failed. Please check the fields.'
            this.isSuccess = false
          }
        })

      if (this.loginMessage) {
        Text(this.loginMessage)
          .fontSize(16)
          .fontColor(this.isSuccess ? Color.Green : Color.Red)
          .margin({ top: 20 })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }

  validateEmail() {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    if (!this.email || !emailRegex.test(this.email)) {
      this.emailError = 'Please enter a valid email address.'
    }
  }

  validatePassword() {
    const passwordRegex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d).{8,}$/
    if (!this.password || !passwordRegex.test(this.password)) {
      this.passwordError = 'Password must be at least 8 characters with one uppercase, one lowercase, and one number.'
    }
  }
}

