@Entry
@Component
struct CustomLoadingSpinner {
    @State rotation: number = 0
    @State colorIndex: number = 0
    private intervalID: number = -1
    private colors: string[] = [$r('sys.color.ohos_id_color_primary').toString(), $r('sys.color.ohos_id_color_secondary').toString(), $r('sys.color.ohos_id_color_tertiary').toString()]

    aboutToAppear() {
        this.intervalID = setInterval(() => {
            this.rotation = (this.rotation + 10) % 360
            this.colorIndex = (this.colorIndex + 1) % this.colors.length
        }, 50)
    }

    aboutToDisappear() {
        if (this.intervalID !== -1) {
            clearInterval(this.intervalID)
        }
    }

    build() {
        Column() {
            Stack() {
                Circle()
                    .width(100)
                    .height(100)
                    .stroke(this.colors[this.colorIndex])
                    .strokeWidth(10)
                    .strokeDashArray([10, 20])
                    .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })
            }
            .width(100)
            .height(100)
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .backgroundColor($r('sys.color.ohos_id_color_background'))
    }
}

