@Entry
@Component
struct WeatherApp {
  @State cityName: string = '';
  @State weatherData: WeatherData | null = null;
  @State isLoading: boolean = false;
  @State errorMessage: string = '';

  async fetchWeatherData(city: string): Promise<void> {
    this.isLoading = true;
    this.errorMessage = '';
    try {
      await new Promise<void>(resolve => setTimeout(resolve, 1000));
      this.weatherData = {
        city: city,
        temperature: '25°C',
        condition: 'Sunny',
        humidity: '60%',
        windSpeed: '10 km/h'
      };
    } catch (error) {
      this.errorMessage = 'Failed to fetch weather data. Please try again.';
    } finally {
      this.isLoading = false;
    }
  }

  build() {
    Column() {
      TextInput({ placeholder: 'Enter city name' })
        .width('80%')
        .height(40)
        .margin({ top: 20, bottom: 10 })
        .onChange((value: string) => {
          this.cityName = value;
        });

      Button('Get Weather')
        .width('50%')
        .height(40)
        .margin({ bottom: 20 })
        .onClick(() => {
          if (this.cityName.trim() !== '') {
            this.fetchWeatherData(this.cityName);
          }
        });

      if (this.isLoading) {
        LoadingProgress()
          .width(50)
          .height(50)
          .margin({ top: 20 });
      }

      if (this.errorMessage !== '') {
        Text(this.errorMessage)
          .fontSize(16)
          .fontColor(Color.Red)
          .margin({ top: 20 });
      }

      if (this.weatherData !== null) {
        Column() {
          Text(`City: ${this.weatherData.city}`)
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 10 });

          Text(`Temperature: ${this.weatherData.temperature}`)
            .fontSize(20)
            .margin({ bottom: 5 });

          Text(`Condition: ${this.weatherData.condition}`)
            .fontSize(20)
            .margin({ bottom: 5 });

          Text(`Humidity: ${this.weatherData.humidity}`)
            .fontSize(20)
            .margin({ bottom: 5 });

          Text(`Wind Speed: ${this.weatherData.windSpeed}`)
            .fontSize(20)
            .margin({ bottom: 20 });
        }
        .padding(20);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

interface WeatherData {
  city: string;
  temperature: string;
  condition: string;
  humidity: string;
  windSpeed: string;
}

@Entry
@Component
struct FullScreenImageViewer {
  @State showFullScreen: boolean = false
  @State scaleValue: number = 1.0
  @State lastScale: number = 1.0
  @State offsetX: number = 0
  @State offsetY: number = 0
  @State initialDistance: number = 0

  private images: Resource[] = [
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon')
  ]

  private captions: string[] = [
    'Image 1',
    'Image 2',
    'Image 3'
  ]

  build() {
    Column() {
      if (this.showFullScreen) {
        Stack() {
          Image($r('app.media.app_icon'))
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%')
            .scale({ x: this.scaleValue, y: this.scaleValue })
            .translate({ x: this.offsetX, y: this.offsetY })
            .onTouch((event: TouchEvent) => {
              if (event.touches.length === 2) {
                const touch1 = event.touches[0]
                const touch2 = event.touches[1]
                const currentDistance = Math.sqrt(
                  Math.pow(touch2.x - touch1.x, 2) +
                  Math.pow(touch2.y - touch1.y, 2)
                )

                if (this.initialDistance === 0) {
                  this.initialDistance = currentDistance
                } else {
                  const scaleFactor = currentDistance / this.initialDistance
                  this.scaleValue = this.lastScale * scaleFactor
                }
              } else if (event.type === TouchType.Up) {
                this.lastScale = this.scaleValue
                this.initialDistance = 0
              }
            })

          Button('Close')
            .onClick(() => {
              this.showFullScreen = false
              this.scaleValue = 1.0
              this.offsetX = 0
              this.offsetY = 0
            })
            .position({ x: 20, y: 20 })
            .backgroundColor('#FFFFFF')
            .padding({ left: 10, right: 10, top: 5, bottom: 5 })
            .borderRadius(5)
        }
      } else {
        Grid() {
          ForEach(this.images, (image: Resource, index: number) => {
            GridItem() {
              Column() {
                Image(image)
                  .width('100%')
                  .height(160)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(5)
                  .onClick(() => {
                    this.showFullScreen = true
                  })

                Text(this.captions[index])
                  .fontSize(14)
                  .textAlign(TextAlign.Center)
                  .margin({ top: 8 })
              }
            }
          })
        }
        .columnsTemplate('1fr 1fr')
        .columnsGap(16)
        .rowsGap(16)
        .padding(16)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

