@Component
struct TodoListApp {
  @State tasks: Array<Task> = []
  @State newTask: string = ''

  build() {
    Column() {
      Text('Todo List')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter a new task', text: this.newTask })
        .onChange((value: string) => {
          this.newTask = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      Button('Add Task')
        .onClick(() => {
          if (this.newTask.trim() !== '') {
            this.tasks.push({ id: Date.now(), content: this.newTask.trim(), isCompleted: false })
            this.newTask = ''
          }
        })
        .margin({ bottom: 20 })

      ForEach(this.tasks, (task: Task, index: number) => {
        Row() {
          Checkbox()
            .select(task.isCompleted)
            .onChange((value: boolean) => {
              this.tasks[index].isCompleted = value
            })
          Text(task.content)
            .fontSize(18)
            .margin({ left: 10 })
            .decoration({ type: task.isCompleted ? TextDecorationType.LineThrough : TextDecorationType.None })
          Button('Delete')
            .onClick(() => {
              this.tasks.splice(index, 1)
            })
        }
        .width('80%')
        .margin({ bottom: 10 })
      })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

