import promptAction from '@ohos.promptAction';

@Entry
@Component
struct UserForm {
  @State name: string = '';
  @State email: string = '';
  @State phoneNumber: string = '';
  @State showDialog: boolean = false;

  build() {
    Column() {
      // Form Title
      Text('User Information')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      // Name Input
      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value;
          });
      }

      // Email Input
      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value;
          });
      }

      // Phone Number Input
      Column() {
        Text('Phone Number:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your phone number' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.phoneNumber = value;
          });
      }

      // Submit Button
      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.name && this.email && this.phoneNumber) {
            this.showDialog = true;
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields'
            });
          }
        });

      // Dialog
      if (this.showDialog) {
        Column() {
          Text('Submitted Information')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Name: ${this.name}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Phone Number: ${this.phoneNumber}`)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.showDialog = false;
              // Clear form fields after submission
              this.name = '';
              this.email = '';
              this.phoneNumber = '';
            });
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

@Entry
@Component
struct ImageGridApp {
  private images: ImageItem[] = [
    {
      id: 1,
      title: 'Image 1',
      image: $r('app.media.app_icon')
    },
    {
      id: 2,
      title: 'Image 2',
      image: $r('app.media.app_icon')
    },
    {
      id: 3,
      title: 'Image 3',
      image: $r('app.media.app_icon')
    },
    {
      id: 4,
      title: 'Image 4',
      image: $r('app.media.app_icon')
    }
  ];

  @State selectedImage: ImageItem | null = null;
  dialogController: CustomDialogController = new CustomDialogController({
    builder: this.DialogBuilder.bind(this),
    customStyle: true,
    alignment: DialogAlignment.Center
  });

  @Builder DialogBuilder() {
    if (this.selectedImage) {
      Column() {
        Image(this.selectedImage.image)
          .width('100%')
          .height(200)
          .borderRadius(8)
          .objectFit(ImageFit.Cover);

        Text(this.selectedImage.title)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 16, bottom: 8 });

        Button('Close')
          .width('100%')
          .height(40)
          .margin({ top: 24 })
          .onClick(() => {
            this.dialogController.close();
          });
      }
      .padding(24)
      .width('90%')
      .backgroundColor(Color.White)
      .borderRadius(16);
    }
  }

  build() {
    Column() {
      Text('Image Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Grid() {
        ForEach(this.images, (imageItem: ImageItem) => {
          GridItem() {
            Column() {
              Image(imageItem.image)
                .width('100%')
                .height(160)
                .borderRadius(8)
                .objectFit(ImageFit.Cover)
                .onClick(() => {
                  this.selectedImage = imageItem;
                  this.dialogController.open();
                });

              Text(imageItem.title)
                .fontSize(16)
                .fontWeight(FontWeight.Medium)
                .margin({ top: 8 });
            }
            .backgroundColor(Color.White)
            .borderRadius(12)
            .padding(16);
          }
        });
      }
      .columnsTemplate('1fr 1fr')
      .rowsGap(16)
      .columnsGap(16)
      .padding(16);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }
}

