@Entry
@Component
struct NavigationDrawerApp {
  @State currentScreen: string = 'Home';
  @State isDrawerOpen: boolean = false;

  build() {
    Row() {
      // Navigation Drawer
      Panel(this.isDrawerOpen) {
        Column() {
          Text('Menu')
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .padding(16);

          this.NavItem('Home');
          this.NavItem('Profile');
          this.NavItem('Settings');
        }
        .width('250px')
        .backgroundColor('#F5F5F5');
      }
      .mode(PanelMode.Mini)
      .type(PanelType.Temporary)
      .dragBar(false);

      // Main Content Area
      Column() {
        if (this.currentScreen === 'Home') {
          this.HomeScreen();
        } else if (this.currentScreen === 'Profile') {
          this.ProfileScreen();
        } else if (this.currentScreen === 'Settings') {
          this.SettingsScreen();
        }
      }
      .layoutWeight(1);
    }
    .height('100%');
  }

  @Builder NavItem(label: string) {
    Text(label)
      .fontSize(18)
      .padding(16)
      .onClick(() => {
        this.currentScreen = label;
        this.isDrawerOpen = false;
      })
      .backgroundColor('#FFFFFF')
      .margin({ bottom: 1 });
  }

  @Builder HomeScreen() {
    Column() {
      Text('Welcome to the Home Screen')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .padding(16);
      Button('Toggle Drawer')
        .onClick(() => {
          this.isDrawerOpen = !this.isDrawerOpen;
        });
    }
    .width('100%')
    .height('100%');
  }

  @Builder ProfileScreen() {
    Column() {
      Text('This is the Profile Screen')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .padding(16);
      Button('Toggle Drawer')
        .onClick(() => {
          this.isDrawerOpen = !this.isDrawerOpen;
        });
    }
    .width('100%')
    .height('100%');
  }

  @Builder SettingsScreen() {
    Column() {
      Text('This is the Settings Screen')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .padding(16);
      Button('Toggle Drawer')
        .onClick(() => {
          this.isDrawerOpen = !this.isDrawerOpen;
        });
    }
    .width('100%')
    .height('100%');
  }
}

@Entry
@Component
struct ImageGallery {
  @State selectedImage: string = ''
  @State showFullScreen: boolean = false

  private images: Resource[] = [
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
  ]

  build() {
    Column() {
      if (this.showFullScreen) {
        Stack() {
          Image(this.selectedImage)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%')

          Button('Close')
            .onClick(() => {
              this.showFullScreen = false
            })
            .position({ x: 20, y: 20 })
            .backgroundColor('#FFFFFF')
            .padding({ left: 10, right: 10, top: 5, bottom: 5 })
            .borderRadius(5)
        }
      } else {
        Grid() {
          ForEach(this.images, (image: string) => {
            GridItem() {
              Image(image)
                .width('100%')
                .aspectRatio(1)
                .objectFit(ImageFit.Cover)
                .borderRadius(5)
                .onClick(() => {
                  this.selectedImage = image
                  this.showFullScreen = true
                })
            }
          })
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsGap(10)
        .columnsGap(10)
        .padding(10)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

