@Component
struct ImageGridApp {
  @State selectedImage: Resource = $r('app.media.app_icon')
  @State showFullScreen: boolean = false
  @State showDetails: boolean = false

  private images: Resource[] = [
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon')
  ]

  private details: string[] = [
    'Details for image 1',
    'Details for image 2',
    'Details for image 3',
    'Details for image 4',
    'Details for image 5',
    'Details for image 6',
    'Details for image 7',
    'Details for image 8',
    'Details for image 9',
    'Details for image 10'
  ]

  build() {
    Column() {
      if (this.showFullScreen) {
        Stack() {
          Column() {
            Image(this.selectedImage)
              .objectFit(ImageFit.Contain)
              .width('100%')
              .height('70%')

            if (this.showDetails) {
              Text(this.details[this.images.indexOf(this.selectedImage)])
                .fontSize(16)
                .margin({ top: 20, left: 20, right: 20 })
                .textAlign(TextAlign.Center)
            }
          }

          Column() {
            Button(this.showDetails ? 'Hide Details' : 'Show Details')
              .onClick(() => {
                this.showDetails = !this.showDetails
              })
              .margin({ top: 20 })
              .backgroundColor('#FFFFFF')
              .padding({ left: 10, right: 10, top: 5, bottom: 5 })
              .borderRadius(5)

            Button('Close')
              .onClick(() => {
                this.showFullScreen = false
                this.showDetails = false
              })
              .margin({ top: 10 })
              .backgroundColor('#FFFFFF')
              .padding({ left: 10, right: 10, top: 5, bottom: 5 })
              .borderRadius(5)
          }
          .position({ x: 20, y: 20 })
        }
      } else {
        Grid() {
          ForEach(this.images, (image: Resource, index: number) => {
            GridItem() {
              Image(image)
                .width('100%')
                .aspectRatio(1)
                .objectFit(ImageFit.Cover)
                .borderRadius(5)
                .onClick(() => {
                  this.selectedImage = image
                  this.showFullScreen = true
                })
            }
          })
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsGap(10)
        .columnsGap(10)
        .padding(10)
      }
    }
