@Entry
@Component
struct Index {
  @State selectedMovie: Movie | null = null;

  build() {
    if (this.selectedMovie == null) {
      Column() {
        Text('Movie List')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .padding(16);

        List() {
          ForEach(movies, (movie: Movie) => {
            ListItem() {
              Column() {
                Column() {
                  Text(movie.title)
                    .fontSize(20)
                    .fontWeight(FontWeight.Medium)
                    .padding({ bottom: 4 });
                  Text(`Release Date: ${movie.releaseDate}`)
                    .fontSize(16)
                    .padding({ bottom: 4 });
                  Text(`Rating: ${movie.rating}`)
                    .fontSize(16)
                    .padding({ bottom: 8 });
                }
                .padding(16);

                Divider()
                  .height(1)
                  .backgroundColor(Color.Gray);
              }
            }
            .onClick(() => {
              this.selectedMovie = movie;
            });
          });
        }
      }
    } else {
      Scroll() {
        Column() {
          Text(this.selectedMovie.title)
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .padding(16);

          Text(`Release Date: ${this.selectedMovie.releaseDate}`)
            .fontSize(18)
            .padding({ left: 16, right: 16, bottom: 8 });

          Text(`Rating: ${this.selectedMovie.rating}`)
            .fontSize(18)
            .padding({ left: 16, right: 16, bottom: 8 });

          Text(`Director: ${this.selectedMovie.director}`)
            .fontSize(18)
            .padding({ left: 16, right: 16, bottom: 8 });

          Text('Description:')
            .fontSize(20)
            .fontWeight(FontWeight.Medium)
            .padding({ left: 16, right: 16, top: 16, bottom: 4 });

          Text(this.selectedMovie.description)
