@Component
struct ApiDataApp {
  @State private data: Array<ApiItem> = [];
  @State private isLoading: boolean = true;
  @State private error: string = '';

  aboutToAppear() {
    this.fetchData();
  }

  fetchData() {
    // Simulate fetching data from an API endpoint
    setTimeout(() => {
      const apiResponse: Array<ApiItem> = [
        {
          id: 1,
          title: 'Item 1',
          description: 'Description for Item 1',
          image: $r('app.media.app_icon')
        },
        {
          id: 2,
          title: 'Item 2',
          description: 'Description for Item 2',
          image: $r('app.media.app_icon')
        },
        {
          id: 3,
          title: 'Item 3',
          description: 'Description for Item 3',
          image: $r('app.media.app_icon')
        }
      ];
      this.data = apiResponse;
      this.isLoading = false;
    }, 2000);
  }

  build() {
    Column() {
      if (this.isLoading) {
        Text('Loading...')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .textAlign(TextAlign.Center)
          .margin({ top: 20, bottom: 20 });
      } else if (this.error) {
        Text(this.error)
          .fontSize(18)
          .fontColor(Color.Red)
          .textAlign(TextAlign.Center)
          .margin({ top: 20, bottom: 20 });
      } else {
        List() {
          ForEach(this.data, (item: ApiItem) => {
            ListItem() {
              Row() {
                Image(item.image)
                  .width(50)
                  .height(50)
                  .objectFit(ImageFit.Cover)
                  .margin({ right: 10 });
                Column() {
                  Text(item.title)
                    .fontSize(20)
                    .fontWeight(FontWeight.Medium);
                  Text(item.description)
                    .fontSize(16)
                    .margin({ top: 5 });
                }
              }
              .padding(10);
            }
            .backgroundColor('#FFFFFF')
            .borderRadius(5)
            .margin({ bottom: 10 });
          });
        }
        .width('100%');
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5');
  }
}

