@Component
struct ApiDataGridView {
  @State data: Array<ApiItem> = []
  @State isLoading: boolean = true
  @State error: string = ''

  aboutToAppear() {
    this.fetchData()
  }

  fetchData() {
    setTimeout(() => {
      const apiResponse: Array<ApiItem> = [
        new ApiItem(1, 'Item 1', 'Description for Item 1', $r('app.media.app_icon')),
        new ApiItem(2, 'Item 2', 'Description for Item 2', $r('app.media.app_icon')),
        new ApiItem(3, 'Item 3', 'Description for Item 3', $r('app.media.app_icon')),
        new ApiItem(4, 'Item 4', 'Description for Item 4', $r('app.media.app_icon')),
        new ApiItem(5, 'Item 5', 'Description for Item 5', $r('app.media.app_icon')),
        new ApiItem(6, 'Item 6', 'Description for Item 6', $r('app.media.app_icon')),
        new ApiItem(7, 'Item 7', 'Description for Item 7', $r('app.media.app_icon')),
        new ApiItem(8, 'Item 8', 'Description for Item 8', $r('app.media.app_icon')),
        new ApiItem(9, 'Item 9', 'Description for Item 9', $r('app.media.app_icon')),
        new ApiItem(10, 'Item 10', 'Description for Item 10', $r('app.media.app_icon'))
      ]
      this.data = apiResponse
      this.isLoading = false
    }, 2000)
  }

  build() {
    Column() {
      if (this.isLoading) {
        Text('Loading...')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .textAlign(TextAlign.Center)
          .margin({ top: 20, bottom: 20 })
      } else if (this.error) {
        Text(this.error)
          .fontSize(18)
          .fontColor(Color.Red)
          .textAlign(TextAlign.Center)
          .margin({ top: 20, bottom: 20 })
      } else {
        Grid() {
          ForEach(this.data, (item: ApiItem) => {
            GridItem() {
              Column() {
                Image(item.image)
                  .width('100%')
                  .aspectRatio(1)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(5)
                Text(item.title)
                  .fontSize(16)
                  .textAlign(TextAlign.Center)
                  .margin({ top: 5 })
                Text(item.description)
                  .fontSize(14)
                  .textAlign(TextAlign.Center)
                  .margin({ top: 5 })
              }
            }
          })
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsGap(10)
        .columnsGap(10)
        .padding(10)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

class ApiItem {
  id: number
  title: string
  description: string
  image: Resource

  constructor(id: number, title: string, description: string, image: Resource) {
    this.id = id
    this.title = title
    this.description = description
    this.image = image
  }
}

