@Entry
@Component
struct CircularProgressApp {
  @State progress: number = 0
  private readonly maxProgress: number = 100
  private canvasRef: CanvasRenderingContext2D | null = null

  build() {
    Column() {
      Canvas()
        .width(240)
        .height(240)
        .onReady(() => {
          this.drawProgress(this.canvasRef!)
        })
        .id('canvas')

      Button('Increase Progress')
        .onClick(() => {
          if (this.progress < this.maxProgress) {
            this.progress += 10
          }
        })
        .margin({ top: 40 })
        .width(200)
        .height(50)

      Button('Reset Progress')
        .onClick(() => {
          this.progress = 0
        })
        .margin({ top: 20 })
        .width(200)
        .height(50)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }

  private drawProgress(ctx: CanvasRenderingContext2D) {
    const centerX = 120
    const centerY = 120
    const radius = 105
    const startAngle = -Math.PI / 2
    const endAngle = startAngle + (2 * Math.PI * this.progress / this.maxProgress)

    // Background circle
    ctx.beginPath()
    ctx.arc(centerX, centerY, radius, 0, 2 * Math.PI)
    ctx.strokeStyle = '#E0E0E0'
    ctx.lineWidth = 15
    ctx.stroke()

    // Progress arc
    ctx.beginPath()
    ctx.arc(centerX, centerY, radius, startAngle, endAngle)
    ctx.strokeStyle = '#4CAF50'
    ctx.lineWidth = 15
    ctx.stroke()
  }
}

