@Entry
@Component
struct MovieListApp {
  @State selectedMovie: Movie | null = null;
  dialogController: CustomDialogController = new CustomDialogController({
    builder: this.DialogBuilder,
    customStyle: true,
    alignment: DialogAlignment.Center
  });

  @Builder DialogBuilder() {
    if (this.selectedMovie) {
      Column() {
        Image(this.selectedMovie.image)
          .width('100%')
          .height(200)
          .borderRadius(8)
          .objectFit(ImageFit.Cover);

        Text(this.selectedMovie.title)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 16, bottom: 8 });

        Text(`Released on: ${this.selectedMovie.releaseDate}`)
          .fontSize(16)
          .fontColor('#666666')
          .margin({ bottom: 8 });

        Text(`Director: ${this.selectedMovie.director}`)
          .fontSize(16)
          .fontColor('#666666')
          .margin({ bottom: 16 });

        Text('Description:')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ bottom: 4 });

        Text(this.selectedMovie.description)
          .fontSize(16)
          .lineHeight(24);

        Button('Close')
          .onClick(() => {
            this.dialogController.close();
          })
          .margin({ top: 24 });
      }
      .padding(24)
      .width('90%')
      .backgroundColor(Color.White)
      .borderRadius(16);
    }
  }

  build() {
    Column() {
      Text('Movie List')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .padding(16);

      List() {
        ForEach(movies, (movie: Movie) => {
          ListItem() {
            Row() {
              Image(movie.image)
                .width(100)
                .height(150)
                .borderRadius(8)
                .objectFit(ImageFit.Cover);

              Column() {
                Text(movie.title)
                  .fontSize(20)
                  .fontWeight(FontWeight.Medium)
                  .margin({ bottom: 4 });

                Text(movie.description)
                  .fontSize(14)
                  .maxLines(2)
                  .textOverflow({ overflow: TextOverflow.Ellipsis });
              }
              .padding(8);
            }
            .onClick(() => {
              this.selectedMovie = movie;
              this.dialogController.open();
            });
          }
        });
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5');
  }
}

