@Entry
@Component
struct FavoriteBooksApp {
  @State favoriteBooks: Array<Book> = [];
  @State newBookTitle: string = '';
  @State newBookAuthor: string = '';

  build() {
    Column() {
      Text('Favorite Books List')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      TextInput({ placeholder: 'Enter book title' })
        .width('80%')
        .height(40)
        .margin({ bottom: 10 })
        .onChange((value: string) => {
          this.newBookTitle = value;
        });

      TextInput({ placeholder: 'Enter book author' })
        .width('80%')
        .height(40)
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.newBookAuthor = value;
        });

      Button('Add Book')
        .width('80%')
        .height(40)
        .margin({ bottom: 20 })
        .onClick(() => {
          if (this.newBookTitle.trim() !== '' && this.newBookAuthor.trim() !== '') {
            const newBook: Book = {
              id: this.favoriteBooks.length + 1,
              title: this.newBookTitle.trim(),
              author: this.newBookAuthor.trim(),
              cover: 'app.media.app_icon'
            };
            this.favoriteBooks = [...this.favoriteBooks, newBook];
            this.newBookTitle = '';
            this.newBookAuthor = '';
          }
        });

      List() {
        ForEach(this.favoriteBooks, (book: Book) => {
          ListItem() {
            Row() {
              Image(book.cover)
                .width(60)
                .height(60)
                .borderRadius(8)
                .objectFit(ImageFit.Cover);

              Column() {
                Text(book.title)
                  .fontSize(18)
                  .fontWeight(FontWeight.Medium)
                  .margin({ bottom: 4 });

                Text(book.author)
                  .fontSize(14)
                  .fontColor('#666666');
              }
              .layoutWeight(1)
              .alignItems(HorizontalAlign.Start)
              .margin({ left: 16 });

              Button('Remove')
                .width(80)
                .height(30)
                .onClick(() => {
                  this.favoriteBooks = this.favoriteBooks.filter(b => b.id !== book.id);
                });
            }
            .justifyContent(FlexAlign.SpaceBetween)
            .width('100%')
            .padding(10)
            .backgroundColor('#f0f0f0')
            .borderRadius(5);
          }
          .margin({ bottom: 10 });
        });
      }
      .width('100%')
      .height('60%');
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

interface Book {
  id: number;
  title: string;
  author: string;
  cover: string;
}

@Entry
@Component
struct SplashToLoginApp {
  @State showSplash: boolean = true;
  @State rotation: number = 0;
  private intervalID: number = -1;

  aboutToAppear() {
    this.intervalID = setInterval(() => {
      this.rotation = (this.rotation + 10) % 360;
    }, 50);

    setTimeout(() => {
      this.showSplash = false;
    }, 3000);
  }

  aboutToDisappear() {
    clearInterval(this.intervalID);
  }

  build() {
    Stack() {
      if (this.showSplash) {
        Column() {
          Image($r('app.media.app_icon'))
            .width(150)
            .height(150)
            .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })
            .margin({ bottom: 20 });
          Text('Welcome to My App')
            .fontSize(24)
            .fontWeight(FontWeight.Bold);
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center)
        .backgroundColor('#FFFFFF');
      } else {
        LoginPage();
      }
    }
    .width('100%')
    .height('100%');
  }
}

@Component
struct LoginPage {
  @State email: string = '';
  @State password: string = '';
  @State loginMessage: string = '';

  build() {
    Column() {
      Text('Email')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your email', text: this.email })
        .onChange((value: string) => {
          this.email = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Button('Login')
        .onClick(() => {
          if (this.email && this.password) {
            this.loginMessage = 'Login successful!';
          } else {
            this.loginMessage = 'Please fill in all fields';
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White);

      if (this.loginMessage) {
        Text(this.loginMessage)
          .fontSize(16)
          .margin({ top: 20 })
          .fontColor(Color.Red);
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

