import promptAction from '@ohos.promptAction';

@Entry
@Component
struct GreetingApp {
  @State name: string = '';
  @State age: string = '';
  @State showGreeting: boolean = false;

  build() {
    Column() {
      Text('Personal Greeting App')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value;
          });
      }

      Column() {
        Text('Age:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your age' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.age = value;
          });
      }

      Button('Generate Greeting')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.name && this.age) {
            this.showGreeting = true;
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields',
              duration: 2000
            });
          }
        });

      if (this.showGreeting) {
        Text(`Hello, ${this.name}! You are ${this.age} years young.`)
          .fontSize(20)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

