@Entry
@Component
struct LoginScreen {
  @State username: string = ''
  @State password: string = ''
  @State loginMessage: string = ''
  @State showRegistration: boolean = false

  build() {
    Column() {
      // App Icon
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ bottom: 20 })

      // Username Label and Input
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your username', text: this.username })
        .onChange((value: string) => {
          this.username = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Password Label and Input
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Login Button
      Button('Login')
        .onClick(() => {
          if (this.username && this.password) {
            this.loginMessage = 'Login successful!'
          } else {
            this.loginMessage = 'Please enter both username and password.'
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)
        .margin({ bottom: 20 })

      // Registration Option
      Text('Don\'t have an account? Register here')
        .fontSize(16)
        .fontColor('#007AFF')
        .onClick(() => {
          this.showRegistration = true
        })
        .margin({ bottom: 20 })

      // Login Message
      if (this.loginMessage) {
        Text(this.loginMessage)
          .fontSize(16)
          .margin({ top: 20 })
          .fontColor(Color.Red)
      }

      // Registration Dialog
      if (this.showRegistration) {
        Column() {
          Text('Registration')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 })

          TextInput({ placeholder: 'Enter your email' })
            .width('80%')
            .margin({ bottom: 20 })

          TextInput({ placeholder: 'Enter your password' })
            .type(InputType.Password)
            .width('80%')
            .margin({ bottom: 20 })

          Button('Register')
            .width('60%')
            .backgroundColor('#007AFF')
            .fontSize(18)
            .fontColor(Color.White)
            .onClick(() => {
              this.showRegistration = false
            })
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
