@Entry
@Component
struct TextInputDialogApp {
  @State inputText: string = '';
  @State showDialog: boolean = false;

  build() {
    Column() {
      TextInput({ placeholder: 'Enter text here' })
        .width('100%')
        .height(40)
        .margin({ bottom: 20 })
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .onChange((value: string) => {
          this.inputText = value;
        });

      Button('Save')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.inputText) {
            this.showDialog = true;
          } else {
            promptAction.showToast({
              message: 'Please enter some text'
            });
          }
        });

      if (this.showDialog) {
        Column() {
          Text('Entered Text')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(this.inputText)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.showDialog = false;
              this.inputText = '';
            });
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

