@Entry
@Component
struct LocationTrackerApp {
  @State private latitude: number = 37.7749;
  @State private longitude: number = -122.4194;
  @State private customMarkerIcon: Resource = $r('app.media.app_icon');
  @State private markers: Array<Marker> = [];

  addMarker(latitude: number, longitude: number): void {
    const newMarker: Marker = { latitude: latitude, longitude: longitude };
    this.markers = [...this.markers, newMarker];
  }

  updateLocation(): void {
    this.latitude = 37.7849;
    this.longitude = -122.4294;
    this.addMarker(this.latitude, this.longitude);
  }

  build() {
    Column() {
      Text('Map View: Displaying User Location with Custom Marker')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      Image(this.customMarkerIcon)
        .width(50)
        .height(50)
        .margin({ bottom: 10 });

      Text(`Latitude: ${this.latitude}`)
        .fontSize(16)
        .margin({ bottom: 5 });

      Text(`Longitude: ${this.longitude}`)
        .fontSize(16)
        .margin({ bottom: 20 });

      Button('Update Location')
        .onClick(() => {
          this.updateLocation();
        })
        .margin({ top: 20 });

      List() {
        ForEach(this.markers, (marker: Marker, index: number) => {
          ListItem() {
            Column() {
              Text(`Marker ${index + 1}: (${marker.latitude}, ${marker.longitude})`)
                .fontSize(14)
                .fontWeight(FontWeight.Normal);
            }
            .padding(10)
            .backgroundColor('#FFFFFF')
            .borderRadius(5)
            .margin({ bottom: 10 });
          }
        });
      }
      .width('100%')
      .height('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#ffffff');
  }
}

interface Marker {
  latitude: number;
  longitude: number;
}

