@Entry
@Component
struct NoteApp {
  @State notes: Array<Note> = [];
  @State newTitle: string = '';
  @State newContent: string = '';

  build() {
    Column({ space: 10 }) {
      TextInput({ placeholder: 'Enter title...', text: this.newTitle })
        .height(50)
        .width('90%')
        .onChange((value: string) => {
          this.newTitle = value;
        })
        .margin(10);

      TextArea({ placeholder: 'Enter content...', text: this.newContent })
        .height(100)
        .width('90%')
        .onChange((value: string) => {
          this.newContent = value;
        })
        .margin(10);

      Button('Add Note')
        .onClick(() => {
          if (this.newTitle.trim() && this.newContent.trim()) {
            this.notes.push(new Note(Date.now(), this.newTitle, this.newContent));
            this.newTitle = '';
            this.newContent = '';
          }
        })
        .margin(10);

      List({ space: 10 }) {
        ForEach(this.notes, (note: Note) => {
          ListItem() {
            Column({ space: 5 }) {
              Text(note.title)
                .fontSize(18)
                .fontWeight(FontWeight.Bold)
                .margin({ bottom: 5 });

              Text(note.content)
                .fontSize(14)
                .margin({ bottom: 10 });

              Button('Delete')
                .onClick(() => {
                  this.notes = this.notes.filter(n => n.id !== note.id);
                })
                .width('100%')
                .margin({ top: 10 });
            }
            .padding(10)
            .width('100%')
          }
        })
      }
      .width('100%')
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

class Note {
  id: number;
  title: string;
  content: string;

  constructor(id: number, title: string, content: string) {
    this.id = id;
    this.title = title;
    this.content = content;
  }
}

