@Entry
@Component
struct RotatingCubeAnimation {
  @State rotationAngle: number = 0;
  @State cubeColor: Color = Color.Blue;
  uiContext: UIContext | undefined = undefined;

  aboutToAppear() {
    this.uiContext = this.getUIContext?.();
  }

  build() {
    Column() {
      Stack() {
        Column()
          .width(100)
          .height(100)
          .backgroundColor(this.cubeColor)
          .rotate({ x: 1, y: 1, z: 1, angle: this.rotationAngle })
          .onClick(() => {
            if (!this.uiContext) {
              console.info("no uiContext, keyframe failed");
              return;
            }
            this.rotationAngle = 0;
            this.cubeColor = Color.Blue;
            this.uiContext.keyframeAnimateTo({ iterations: -1 }, [
              {
                duration: 1000,
                event: () => {
                  this.rotationAngle = 90;
                  this.cubeColor = Color.Green;
                }
              },
              {
                duration: 1000,
                event: () => {
                  this.rotationAngle = 180;
                  this.cubeColor = Color.Red;
                }
              },
              {
                duration: 1000,
                event: () => {
                  this.rotationAngle = 270;
                  this.cubeColor = Color.Yellow;
                }
              },
              {
                duration: 1000,
                event: () => {
                  this.rotationAngle = 360;
                  this.cubeColor = Color.Blue;
                }
              }
            ]);
          })
      }
      .width('100%')
      .height('100%')
      .align(Alignment.Center)
    }
    .width('100%')
    .height('100%')
  }
}

