import promptAction from '@ohos.promptAction'

@Entry
@Component
struct AgeGroupChecker {
  @State age: string = ''
  @State message: string = ''
  @State showMessage: boolean = false

  build() {
    Column() {
      Text('Age Group Checker')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 })

      Column() {
        Text('Enter your age:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your age' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.age = value
          })
      }

      Button('Check Age Group')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.age) {
            const ageNum = parseInt(this.age)
            if (ageNum < 13) {
              this.message = 'You are a child.'
            } else if (ageNum >= 13 && ageNum < 20) {
              this.message = 'You are a teenager.'
            } else if (ageNum >= 20 && ageNum < 60) {
              this.message = 'You are an adult.'
            } else {
              this.message = 'You are a senior.'
            }
            this.showMessage = true
          } else {
            promptAction.showToast({
              message: 'Please enter your age'
            })
          }
        })

      if (this.showMessage) {
        Text(this.message)
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
  }
}

