@Entry
@Component
struct MultiFieldForm {
  @State name: string = ''
  @State email: string = ''
  @State phone: string = ''
  @State address: string = ''
  @State successMessage: string = ''
  @State errorMessage: string = ''

  validateForm(): boolean {
    if (!this.name || !this.email || !this.phone || !this.address) {
      this.errorMessage = 'All fields are required'
      return false
    }
    if (!this.email.includes('@')) {
      this.errorMessage = 'Please enter a valid email address'
      return false
    }
    this.errorMessage = ''
    return true
  }

  build() {
    Column({ space: 20 }) {
      // Form Title
      Text('Multi-Field Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      // Name Input
      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value
          })
      }

      // Email Input
      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value
          })
      }

      // Phone Input
      Column() {
        Text('Phone:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your phone number' })
          .width('100%')
          .height(40)
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.phone = value
          })
      }

      // Address Input
      Column() {
        Text('Address:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your address' })
          .width('100%')
          .height(40)
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.address = value
          })
      }

      // Submit Button
      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.validateForm()) {
            this.successMessage = 'Form submitted successfully!'
            this.name = ''
            this.email = ''
            this.phone = ''
            this.address = ''
          }
        })

      // Error Message
      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 10 })
      }

      // Success Message
      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(18)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
  }
}

@Entry
@Component
struct LoginScreen {
  @State username: string = ''
  @State password: string = ''
  @State loginMessage: string = ''
  @State isSuccess: boolean = false

  validateCredentials(): boolean {
    const validUsername = 'user123'
    const validPassword = 'securePass123'
    return this.username === validUsername && this.password === validPassword
  }

  build() {
    Column() {
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your username', text: this.username })
        .onChange((value: string) => {
          this.username = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      Button('Login')
        .onClick(() => {
          if (this.validateCredentials()) {
            this.loginMessage = 'Login successful!'
            this.isSuccess = true
          } else {
            this.loginMessage = 'Invalid username or password.'
            this.isSuccess = false
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      if (this.loginMessage) {
        Text(this.loginMessage)
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
          .fontColor(this.isSuccess ? Color.Green : Color.Red)
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

