@Entry
@Component
struct HorizontalDatePickerApp {
  @State selectedDate: Date = new Date()
  @State displayDate: string = ''

  aboutToAppear() {
    this.updateDisplayDate()
  }

  updateDisplayDate() {
    this.displayDate = this.selectedDate.toLocaleDateString()
  }

  build() {
    Column() {
      Text('Horizontal Date Picker')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      Scroll() {
        Row() {
          ForEach(this.generateDateRange(), (date: Date) => {
            Button(date.toLocaleDateString())
              .onClick(() => {
                this.selectedDate = date
                this.updateDisplayDate()
              })
              .margin({ right: 10 })
              .backgroundColor(this.selectedDate.toDateString() === date.toDateString() ? '#007AFF' : '#F0F0F0')
              .fontColor(this.selectedDate.toDateString() === date.toDateString() ? Color.White : Color.Black)
          })
        }
        .padding(10)
      }
      .height(100)
      .margin({ bottom: 40 })

      Column() {
        Text('Selected Date:')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ bottom: 8 })

        Text(this.displayDate)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .fontColor('#007AFF')
      }
      .padding(16)
      .borderRadius(12)
      .backgroundColor('#F0F0F0')
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White)
  }

  generateDateRange(): Date[] {
    const dates: Date[] = []
    const startDate = new Date('2000-01-01')
    const endDate = new Date('2030-12-31')
    for (let d = startDate; d <= endDate; d.setDate(d.getDate() + 1)) {
      dates.push(new Date(d))
    }
    return dates
  }
}

