@Entry
@Component
struct RegistrationForm {
  @State name: string = ''
  @State email: string = ''
  @State password: string = ''
  @State confirmationMessage: string = ''
  @State errorMessage: string = ''

  validateForm(): boolean {
    if (!this.name || !this.email || !this.password) {
      this.errorMessage = 'All fields are required'
      return false
    }
    this.errorMessage = ''
    return true
  }

  build() {
    Column() {
      Text('Registration Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 30 })

      TextInput({ placeholder: 'Enter your name' })
        .width('90%')
        .height(40)
        .margin({ bottom: 20 })
        .backgroundColor('#f5f5f5')
        .padding(10)
        .borderRadius(8)
        .onChange((value: string) => {
          this.name = value
        })

      TextInput({ placeholder: 'Enter your email' })
        .width('90%')
        .height(40)
        .margin({ bottom: 20 })
        .backgroundColor('#f5f5f5')
        .padding(10)
        .borderRadius(8)
        .onChange((value: string) => {
          this.email = value
        })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .width('90%')
        .height(40)
        .margin({ bottom: 30 })
        .backgroundColor('#f5f5f5')
        .padding(10)
        .borderRadius(8)
        .onChange((value: string) => {
          this.password = value
        })

      Button('Submit', { type: ButtonType.Capsule })
        .width('50%')
        .height(45)
        .fontSize(18)
        .fontColor(Color.White)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.validateForm()) {
            this.confirmationMessage = `Registration Details:\n\nName: ${this.name}\nEmail: ${this.email}\nPassword: ${this.password}`
          }
        })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 20 })
      }

      if (this.confirmationMessage) {
        Text(this.confirmationMessage)
          .fontSize(16)
          .fontColor(Color.Black)
          .margin({ top: 30 })
          .padding(20)
          .backgroundColor('#f0f0f0')
          .borderRadius(12)
          .width('90%')
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

@Entry
@Component
struct ChatApp {
  @State messages: Array<Message> = []
  @State currentMessage: string = ''
  @State currentUser: string = 'User1'

  build() {
    Column() {
      // Chat Window
      List({ space: 10 }) {
        ForEach(this.messages, (item: Message) => {
          ListItem() {
            Column() {
              Text(`${item.user} - ${item.timestamp}`)
                .fontSize(14)
                .fontColor('#666666')
                .margin({ bottom: 4 })
              Text(item.message)
                .fontSize(16)
                .fontColor('#000000')
            }
            .padding(10)
            .backgroundColor(item.user === this.currentUser ? '#DCF8C6' : '#ECECEC')
            .borderRadius(8)
            .width('80%')
            .alignItems(item.user === this.currentUser ? HorizontalAlign.End : HorizontalAlign.Start)
          }
        })
      }
      .layoutWeight(1)
      .width('100%')
      .padding(10)

      // Message Input
      Row() {
        TextInput({ placeholder: 'Type a message...' })
          .onChange((value: string) => {
            this.currentMessage = value
          })
          .width('80%')
          .height(40)
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })

        Button('Send')
          .width('20%')
          .height(40)
          .fontSize(16)
          .backgroundColor('#007AFF')
          .onClick(() => {
            if (this.currentMessage) {
              const timestamp = new Date().toLocaleTimeString()
              this.messages.push({ user: this.currentUser, message: this.currentMessage, timestamp: timestamp })
              this.currentMessage = ''
            }
          })
      }
      .width('100%')
      .padding(10)
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

interface Message {
  user: string
  message: string
  timestamp: string
}

