  @State userName: string = 'Jane Smith';
  @State userEmail: string = 'jane.smith@example.com';
  @State userBio: string = 'Product Designer with a passion for creating intuitive user experiences.';
  @State isEditing: boolean = false;
  @State newName: string = '';
  @State newEmail: string = '';
  @State newBio: string = '';

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .borderRadius(50)
        .margin({ bottom: 20 });

      if (this.isEditing) {
        TextInput({ placeholder: 'Enter new name' })
          .onChange((value: string) => this.newName = value)
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Enter new email' })
          .onChange((value: string) => this.newEmail = value)
          .margin({ bottom: 10 });

        TextInput({ placeholder: 'Enter new bio' })
          .onChange((value: string) => this.newBio = value)
          .margin({ bottom: 10 });

        Button('Save')
          .onClick(() => {
            if (this.newName) this.userName = this.newName;
            if (this.newEmail) this.userEmail = this.newEmail;
            if (this.newBio) this.userBio = this.newBio;
            this.isEditing = false;
          })
          .margin({ bottom: 10 });
      } else {
        Text(this.userName)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 10 });

        Text(this.userEmail)
          .fontSize(16)
          .margin({ bottom: 10 });

        Text(this.userBio)
          .fontSize(16)
          .margin({ bottom: 20 });

        Button('Edit Profile')
          .onClick(() => {
            this.isEditing = true;
            this.newName = this.userName;
            this.newEmail = this.userEmail;
            this.newBio = this.userBio;
          })
          .margin({ bottom: 10 });
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

