@Entry
@Component
struct DrawerMenuApp {
  @State currentPage: string = 'Home';
  @State isDrawerOpen: boolean = false;

  build() {
    Column() {
      // Main Content Area
      Column() {
        if (this.currentPage === 'Home') {
          this.HomePage();
        } else if (this.currentPage === 'About') {
          this.AboutPage();
        } else if (this.currentPage === 'Contact') {
          this.ContactPage();
        }
      }
      .width('100%')
      .height('100%');

      // Navigation Drawer
      if (this.isDrawerOpen) {
        Column() {
          Button('Home')
            .onClick(() => {
              this.currentPage = 'Home';
              this.isDrawerOpen = false;
            })
            .padding(10)
            .width('100%')
            .backgroundColor(this.currentPage === 'Home' ? '#D3D3D3' : Color.Transparent);

          Button('About')
            .onClick(() => {
              this.currentPage = 'About';
              this.isDrawerOpen = false;
            })
            .padding(10)
            .width('100%')
            .backgroundColor(this.currentPage === 'About' ? '#D3D3D3' : Color.Transparent);

          Button('Contact')
            .onClick(() => {
              this.currentPage = 'Contact';
              this.isDrawerOpen = false;
            })
            .padding(10)
            .width('100%')
            .backgroundColor(this.currentPage === 'Contact' ? '#D3D3D3' : Color.Transparent);
        }
        .backgroundColor('#FFFFFF')
        .padding(10)
        .width(200)
        .height('100%')
        .position({ x: 0, y: 0 });
      }

      // Toggle Drawer Button
      Button('☰')
        .onClick(() => {
          this.isDrawerOpen = !this.isDrawerOpen;
        })
        .padding(10);
    }
    .height('100%');
