@Entry
@Component
struct ColorChangingContainer {
  @State containerColor: string = '#FFFFFF'
  private colors: string[] = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FF00FF', '#FFA500', '#00FFFF', '#800080', '#FF4500', '#8A2BE2']

  build() {
    Column() {
      Text('Tap the container to change color')
        .fontSize(18)
        .margin({ bottom: 20 })

      // Container with dynamic color change
      Row()
        .width(200)
        .height(200)
        .backgroundColor(this.containerColor)
        .borderRadius(10)
        .onClick(() => {
          this.containerColor = this.colors[Math.floor(Math.random() * this.colors.length)]
        })
        .margin({ bottom: 20 })

      // Display current color
      Text('Current Color: ' + this.containerColor)
        .fontSize(16)
        .margin({ bottom: 20 })
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

