@Entry
@Component
struct ImageGridApp {
  @State message: string = ''

  private items: Array<ImageItem> = [
    { image: $r('app.media.app_icon'), message: 'Message for Image 1' },
    { image: $r('app.media.app_icon'), message: 'Message for Image 2' },
    { image: $r('app.media.app_icon'), message: 'Message for Image 3' },
    { image: $r('app.media.app_icon'), message: 'Message for Image 4' },
    { image: $r('app.media.app_icon'), message: 'Message for Image 5' },
    { image: $r('app.media.app_icon'), message: 'Message for Image 6' }
  ]

  build() {
    Column() {
      Grid() {
        ForEach(this.items, (item: ImageItem) => {
          GridItem() {
            Column() {
              Image(item.image)
                .width('100%')
                .aspectRatio(1)
                .objectFit(ImageFit.Cover)
                .borderRadius(8)
                .onClick(() => {
                  this.message = item.message
                })
            }
            .width('100%')
          }
        })
      }
      .columnsTemplate('1fr 1fr')
      .rowsGap(12)
      .columnsGap(12)
      .padding(12)

      if (this.message !== '') {
        Text(`Message: ${this.message}`)
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 24 })
          .textAlign(TextAlign.Center)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

interface ImageItem {
  image: Resource
  message: string
}

