@Component
struct DropdownMenuApp {
  private items: DropdownItem[] = [
    { id: 1, label: 'Apple', value: 'apple' },
    { id: 2, label: 'Banana', value: 'banana' },
    { id: 3, label: 'Cherry', value: 'cherry' },
    { id: 4, label: 'Date', value: 'date' }
  ];

  @State selectedItem: DropdownItem | null = null;
  @State isDropdownOpen: boolean = false;

  build() {
    Column() {
      // Title
      Text('Select an Item')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      // Dropdown Button
      Button(this.selectedItem ? this.selectedItem.label : 'Select an Item')
        .onClick(() => {
          this.isDropdownOpen = !this.isDropdownOpen;
        })
        .width('80%')
        .height(50)
        .backgroundColor('#f0f0f0')
        .borderRadius(5)
        .margin({ bottom: 10 });

      // Dropdown List
      if (this.isDropdownOpen) {
        List() {
          ForEach(this.items, (item: DropdownItem) => {
            ListItem() {
              Text(item.label)
                .fontSize(18)
                .padding(10)
                .onClick(() => {
                  this.selectedItem = item;
                  this.isDropdownOpen = false;
                });
            }
            .backgroundColor('#FFFFFF')
            .borderRadius(5)
            .margin({ bottom: 5 });
          });
        }
        .width('80%')
        .height(200)
        .backgroundColor('#FFFFFF')
        .borderRadius(5)
        .margin({ bottom: 20 });
      }

      // Display Selected Item
      if (this.selectedItem) {
        Text(`Selected Item: ${this.selectedItem.label}`)
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

interface DropdownItem {
  id: number;
  label: string;
  value: string;
}

@Entry
@Component
struct LoginForm {
  @State username: string = ''
  @State email: string = ''
  @State password: string = ''
  @State successMessage: string = ''
  @State errorMessage: string = ''

  validateForm(): boolean {
    if (!this.username || !this.email || !this.password) {
      this.errorMessage = 'All fields are required'
      return false
    }
    this.errorMessage = ''
    return true
  }

  build() {
    Column() {
      // Form Title
      Text('Login')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      // Username Input
      TextInput({ placeholder: 'Enter your username' })
        .onChange((value: string) => {
          this.username = value
        })
        .margin({ bottom: 20 })

      // Email Input
      TextInput({ placeholder: 'Enter your email' })
        .onChange((value: string) => {
          this.email = value
        })
        .margin({ bottom: 20 })

      // Password Input
      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .margin({ bottom: 20 })

      // Submit Button
      Button('Submit')
        .onClick(() => {
          if (this.validateForm()) {
            this.successMessage = 'Login successful!'
            this.username = ''
            this.email = ''
            this.password = ''
          }
        })

      // Error Message
      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ bottom: 20 })
      }

      // Success Message
      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(18)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

