  private images: string[] = [
    'app.media.app_icon1',
    'app.media.app_icon2',
    'app.media.app_icon3',
    'app.media.app_icon4',
    'app.media.app_icon5',
    'app.media.app_icon6',
    'app.media.app_icon7',
    'app.media.app_icon8',
    'app.media.app_icon9'
  ]

  build() {
