    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

@Entry
@Component
struct ColorfulBoxGridApp {
  @State boxColors: Color[] = Array(12).fill(Color.Blue);
  private colors: Color[] = [Color.Red, Color.Green, Color.Blue, Color.Yellow, Color.Pink, Color.Orange, Color.Gray];

  getRandomColor(): Color {
    const randomIndex: number = Math.floor(Math.random() * this.colors.length);
    return this.colors[randomIndex];
  }

  build() {
    Column() {
      Text('Tap Boxes to Change Color')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Grid() {
        ForEach(this.boxColors, (color: Color, index: number) => {
          GridItem() {
            Row()
              .width(100)
              .height(100)
              .backgroundColor(color)
              .onClick(() => {
                this.boxColors[index] = this.getRandomColor();
              })
              .borderRadius(10)
              .margin(10);
          }
        })
      }
      .columnsTemplate('1fr 1fr 1fr 1fr')
      .rowsTemplate('1fr 1fr 1fr')
      .height('100%')
      .width('100%')
    }
    .padding(20)
    .backgroundColor('#F5F5F5')
    .width('100%')
    .height('100%')
  }
}

