    $r('app.media.app_icon')
  ];

  @State imageRatings: Map<string, number> = new Map();
  @State selectedImage: string = '';
  @State showRating: boolean = false;

  build() {
    Column() {
      if (this.showRating) {
        Stack() {
          Image(this.selectedImage)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%');

          Column() {
            Text('Rate this image:')
              .fontSize(20)
              .margin({ bottom: 10 });

            Row() {
              ForEach([1, 2, 3, 4, 5], (star: number) => {
                Button(star.toString())
                  .onClick(() => {
                    this.imageRatings.set(this.selectedImage, star);
                    this.showRating = false;
                  })
                  .margin({ right: 5 });
              })
            }
            .justifyContent(FlexAlign.Center)
            .margin({ bottom: 20 });

            Button('Close')
              .onClick(() => {
                this.showRating = false;
              })
              .backgroundColor('#FFFFFF')
