      image: 'app.media.app_icon',
      rating: 0,
      description: 'A premium product with advanced features.'
    },
    {
      id: 2,
      name: 'Product Y',
      image: 'app.media.app_icon',
      rating: 0,
      description: 'A budget-friendly product with essential features.'
    }
  ];

  @State selectedProduct: Product | null = null;

  private updateRating(productId: number, newRating: number): void {
    const productIndex = this.products.findIndex((p: Product) => p.id === productId);
    if (productIndex !== -1) {
      this.products[productIndex].rating = newRating;
    }
  }

  build() {
    if (this.selectedProduct === null) {
      Column() {
        Text('Rate Our Products')
          .fontSize(28)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20, bottom: 20 })
          .width('100%')
          .textAlign(TextAlign.Center);

        Scroll() {
          Column() {
            ForEach(this.products, (product: Product) => {
              Column() {
                Image(product.image)
                  .width(100)
                  .height(100)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(8);

                Text(product.name)
                  .fontSize(18)
                  .fontWeight(FontWeight.Medium)
                  .margin({ top: 8 });

                Row() {
                  ForEach([1, 2, 3, 4, 5], (index: number) => {
                    Image('app.media.app_icon')
                      .width(24)
                      .height(24)
                      .margin({ right: 2 })
                      .onClick(() => {
                        this.updateRating(product.id, index);
                      })
                      .opacity(product.rating >= index ? 1 : 0.3);
                  });
                }
                .margin({ top: 8 });
              }
              .padding(16)
              .backgroundColor(Color.White)
              .borderRadius(12)
              .onClick(() => {
                this.selectedProduct = product;
              })
              .margin({ bottom: 12 });
            });
          }
        }
        .layoutWeight(1);
      }
      .width('100%')
      .height('100%')
      .backgroundColor('#f5f5f5')
      .padding({ left: 16, right: 16 });
    } else {
      Column() {
        Row() {
          Button() {
            Image('app.media.app_icon')
              .width(24)
              .height(24);
          }
          .backgroundColor('transparent')
          .onClick(() => {
            this.selectedProduct = null;
          });

          Text(this.selectedProduct!.name)
            .fontSize(20)
            .fontWeight(FontWeight.Medium)
            .margin({ left: 16 });
        }
        .width('100%')
        .height(56)
        .padding({ left: 16, right: 16 })
        .backgroundColor(Color.White);

        Scroll() {
          Column() {
            Image(this.selectedProduct!.image)
              .width('100%')
              .height(200)
              .objectFit(ImageFit.Cover);

            Column() {
              Text(this.selectedProduct!.name)
                .fontSize(24)
                .fontWeight(FontWeight.Bold)
                .margin({ bottom: 8 });

              Row() {
                ForEach([1, 2, 3, 4, 5], (index: number) => {
                  Image('app.media.app_icon')
                    .width(24)
                    .height(24)
                    .margin({ right: 2 })
                    .onClick(() => {
                      this.updateRating(this.selectedProduct!.id, index);
                    })
                    .opacity(this.selectedProduct!.rating >= index ? 1 : 0.3);
                });
              }
              .margin({ bottom: 16 });

              Text(this.selectedProduct!.description)
                .fontSize(16)
                .lineHeight(24);
            }
            .width('100%')
            .padding(16);
          }
        }
        .layoutWeight(1);
      }
      .width('100%')
      .height('100%')
      .backgroundColor('#f5f5f5');
    }
  }
}

interface Product {
  id: number;
  name: string;
  image: string;
  rating: number;
  description: string;
}

@Entry
@Component
struct ChatApp {
  @State messages: Array<Message> = [
    { text: "Hello there!", isSender: false, timestamp: "10:00 AM" },
    { text: "Hi! How are you?", isSender: true, timestamp: "10:02 AM" },
    { text: "I'm good, thanks!", isSender: false, timestamp: "10:05 AM" }
  ];
  @State newMessage: string = '';

  build() {
    Column() {
      // Chat Header
      Text('Chat')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .textAlign(TextAlign.Center)
        .padding(15)
        .backgroundColor('#007AFF')
        .fontColor(Color.White)

      // Chat Messages Display
      List() {
        ForEach(this.messages, (message: Message) => {
          ListItem() {
            Column() {
              Row() {
                if (message.isSender) {
                  Text('You')
                    .fontSize(14)
                    .fontWeight(FontWeight.Medium)
                    .margin({ right: 5 })
                } else {
                  Text('Friend')
                    .fontSize(14)
                    .fontWeight(FontWeight.Medium)
                    .margin({ right: 5 })
                }
                Text(message.timestamp)
                  .fontSize(12)
                  .fontColor('#888888')
              }
              .justifyContent(FlexAlign.Start)
              .width('100%')

              Text(message.text)
                .fontSize(16)
                .padding(10)
                .backgroundColor(message.isSender ? '#DCF8C6' : '#ECECEC')
                .borderRadius(8)
                .width('80%')
                .align(message.isSender ? Alignment.End : Alignment.Start)
            }
            .width('100%')
            .margin({ top: 5, bottom: 15 })
          }
        })
      }
      .layoutWeight(1)
      .width('100%')
      .padding(10)

      // Input Area
      Row() {
        TextInput({ placeholder: 'Type a message...', text: this.newMessage })
          .width('80%')
          .height(40)
          .backgroundColor('#F5F5F5')
          .padding({ left: 12 })
          .onChange((newText: string) => {
            this.newMessage = newText;
          })

        Button('Send')
          .width('20%')
          .height(40)
          .fontSize(16)
          .backgroundColor('#007AFF')
          .fontColor(Color.White)
          .onClick(() => {
            if (this.newMessage.trim()) {
              const now = new Date();
              const timeString = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
              this.messages = [...this.messages, { text: this.newMessage, isSender: true, timestamp: timeString }];
              this.newMessage = '';
            }
          })
      }
      .width('100%')
      .padding(10)
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
  }
}

interface Message {
  text: string;
  isSender: boolean;
  timestamp: string;
}

