@Entry
@Component
struct ProfilePage {
  @State userName: string = 'Jane Smith'
  @State userEmail: string = 'janesmith@example.com'
  @State isEditing: boolean = false
  @State newName: string = ''
  @State newEmail: string = ''

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ bottom: 20 })

      if (this.isEditing) {
        TextInput({ placeholder: 'Enter new name', text: this.newName })
          .onChange((value: string) => {
            this.newName = value
          })
          .margin({ bottom: 10 })

        TextInput({ placeholder: 'Enter new email', text: this.newEmail })
          .onChange((value: string) => {
            this.newEmail = value
          })
          .margin({ bottom: 10 })

        Button('Save')
          .onClick(() => {
            if (this.newName && this.newEmail) {
              this.userName = this.newName
              this.userEmail = this.newEmail
              this.isEditing = false
            }
          })
      } else {
        Text(`Name: ${this.userName}`)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 10 })

        Text(`Email: ${this.userEmail}`)
          .fontSize(16)
          .margin({ bottom: 20 })

        Button('Edit')
          .onClick(() => {
            this.newName = this.userName
            this.newEmail = this.userEmail
            this.isEditing = true
          })
      }
    }
    .padding(20)
  }
}

