@Entry
@Component
struct RatingApp {
  private itemList: Array<Item> = [
    new Item('Item 1', []),
    new Item('Item 2', []),
    new Item('Item 3', [])
  ];

  @State items: Array<Item> = this.itemList;

  private rateItem(index: number, rating: number): void {
    let item = this.items[index];
    item.ratings.push(rating);
    this.items[index] = item;
  }

  private calculateAverageRating(ratings: number[]): number {
    if (ratings.length === 0) return 0;
    const sum = ratings.reduce((acc, curr) => acc + curr, 0);
    return sum / ratings.length;
  }

  build() {
    Column({ space: 20 }) {
      Text('Rate the Items')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      ForEach(this.items, (item: Item, index: number) => {
        Column({ space: 10 }) {
          Text(item.name)
            .fontSize(18)
            .fontWeight(FontWeight.Medium);

          Text(`Average Rating: ${this.calculateAverageRating(item.ratings).toFixed(1)}`)
            .fontSize(16)
            .fontColor(Color.Gray);

          Row({ space: 5 }) {
            ForEach(new Array(5), (_: undefined, starIndex: number) => {
              Text(starIndex < this.calculateAverageRating(item.ratings) ? '★' : '☆')
                .fontSize(24)
                .fontColor(starIndex < this.calculateAverageRating(item.ratings) ? Color.Yellow : Color.Gray)
                .onClick(() => {
                  this.rateItem(index, starIndex + 1);
                });
            });
          }
        }
        .padding(10)
        .backgroundColor('#f0f0f0')
        .borderRadius(10)
        .margin({ bottom: 10 });
      });
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

class Item {
  name: string;
  ratings: number[];

  constructor(name: string, ratings: number[]) {
    this.name = name;
    this.ratings = ratings;
  }
}

