@Entry
@Component
struct TodoList {
  @State tasks: Array<Task> = []
  @State newTask: string = ''

  build() {
    Column() {
      TextInput({ placeholder: 'Enter a new task' })
        .onChange((value: string) => {
          this.newTask = value
        })
        .margin({ bottom: 20 })

      Button('Add Task')
        .onClick(() => {
          if (this.newTask.trim()) {
            this.tasks.push({
              id: Date.now(),
              content: this.newTask,
              isCompleted: false
            })
            this.newTask = ''
          }
        })
        .margin({ bottom: 20 })

      List() {
        ForEach(this.tasks, (task: Task, index: number) => {
          ListItem() {
            Row() {
              Checkbox()
                .select(task.isCompleted)
                .onChange((value: boolean) => {
                  this.tasks[index].isCompleted = value
                })
                .margin({ right: 10 })

              Text(task.content)
                .fontSize(18)
                .decoration({
                  type: task.isCompleted ? TextDecorationType.LineThrough : TextDecorationType.None
                })
                .layoutWeight(1)

              Button() {
                Image($r('app.media.app_icon'))
                  .width(20)
                  .height(20)
              }
              .onClick(() => {
                this.tasks.splice(index, 1)
              })
              .margin({ left: 10 })
            }
            .width('100%')
            .justifyContent(FlexAlign.SpaceBetween)
          }
        })
      }
      .layoutWeight(1)
      .divider({ strokeWidth: 1, color: '#F1F1F1' })
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

interface Task {
  id: number
  content: string
  isCompleted: boolean
}

@Entry
@Component
struct RecipeSearchApp {
  @State recipes: string[] = [
    'Pasta with Tomato Sauce',
    'Vegetable Stir Fry',
    'Chicken Curry',
    'Beef Stew',
    'Vegetable Soup',
    'Grilled Salmon',
    'Vegetable Lasagna',
    'Chicken Alfredo',
    'Beef Tacos',
    'Vegetable Pizza'
  ];

  @State ingredients: string[] = [
    'Tomato',
    'Onion',
    'Garlic',
    'Chicken',
    'Beef',
    'Vegetables',
    'Pasta',
    'Rice',
    'Cheese',
    'Salmon'
  ];

  @State searchText: string = '';

  filteredRecipes(): string[] {
    if (this.searchText.trim() === '') {
      return this.recipes;
    } else {
      return this.recipes.filter(recipe =>
        recipe.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  build() {
    Column() {
      TextInput({
        placeholder: 'Enter ingredients...',
        text: this.searchText
      })
        .width('100%')
        .onChange((value: string) => {
          this.searchText = value;
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      if (this.filteredRecipes().length > 0) {
        List() {
          ForEach(this.filteredRecipes(), (recipe: string) => {
            ListItem() {
              Row() {
                Image($r('app.media.app_icon'))
                  .width(50)
                  .height(50)
                  .objectFit(ImageFit.Cover)
                  .margin({ right: 10 });
                Text(recipe)
                  .fontSize(18)
                  .padding(12);
              }
            }
          });
        }
      } else {
        Text('No recipes found')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

