        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.userName) {
            this.showGreeting = true;
          } else {
            promptAction.showToast({
              message: 'Please enter your name'
            });
          }
        });

      if (this.showGreeting) {
        Text(`Hello, ${this.userName}!`)
          .fontSize(24)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

@Entry
@Component
struct RegistrationForm {
  @State username: string = ''
  @State email: string = ''
  @State password: string = ''
  @State successMessage: string = ''
  @State errorMessage: string = ''

  validateForm(): boolean {
    if (!this.username || !this.email || !this.password) {
      this.errorMessage = 'All fields are required'
      return false
    }
    this.errorMessage = ''
    return true
  }

  build() {
    Column() {
      Text('User Registration')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your username' })
        .onChange((value: string) => {
          this.username = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your email' })
        .onChange((value: string) => {
          this.email = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .margin({ bottom: 20 })

      Button('Submit')
        .onClick(() => {
          if (this.validateForm()) {
            this.successMessage = `Registration successful!\nUsername: ${this.username}\nEmail: ${this.email}`
            this.username = ''
            this.email = ''
            this.password = ''
          }
        })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ bottom: 20 })
      }

      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(18)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct NoteApp {
  private noteId: number = 0;
  @State notes: Array<Note> = [];
  @State newTitle: string = '';
  @State newDescription: string = '';
  @State editNoteId: number | null = null;

  build() {
    Column() {
      TextInput({ placeholder: 'Enter note title...', text: this.newTitle })
        .height(50)
        .width('90%')
        .onChange((value: string) => {
          this.newTitle = value;
        })
        .margin(10);

      TextArea({ placeholder: 'Enter note description...', text: this.newDescription })
        .height(100)
        .width('90%')
        .onChange((value: string) => {
          this.newDescription = value;
        })
        .margin(10);

      Button(this.editNoteId !== null ? 'Update Note' : 'Add Note')
        .onClick(() => {
          if (this.newTitle.trim() && this.newDescription.trim()) {
            const currentDate = new Date().toLocaleDateString();
            if (this.editNoteId !== null) {
              const index = this.notes.findIndex(note => note.id === this.editNoteId);
              this.notes[index] = {
                id: this.editNoteId,
                title: this.newTitle,
                description: this.newDescription,
                date: currentDate
              };
              this.editNoteId = null;
            } else {
              this.notes.push({
                id: Date.now(),
                title: this.newTitle,
                description: this.newDescription,
                date: currentDate
              });
            }
            this.newTitle = '';
            this.newDescription = '';
          }
        })
        .margin(10);

      List() {
        ForEach(this.notes, (note: Note) => {
          ListItem() {
            Row() {
              Column() {
                Text(note.title)
                  .fontSize(20)
                  .fontWeight(500);
                Text(note.description)
                  .fontSize(16)
                  .margin({ top: 5 });
                Text(note.date)
                  .fontSize(14)
                  .fontColor(0x808080)
                  .margin({ top: 5 });
              }
              .width('80%');

              Button('Edit')
                .onClick(() => {
                  this.newTitle = note.title;
                  this.newDescription = note.description;
                  this.editNoteId = note.id;
                })
                .margin(5);

              Button('Delete')
                .onClick(() => {
                  this.notes = this.notes.filter(n => n.id !== note.id);
                })
                .margin(5);
            }
            .padding(10);
          }
        });
      }
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

interface Note {
  id: number;
  title: string;
  description: string;
  date: string;
}

