@Component
struct SportsTeamSelectorApp {
  private teams: Team[] = [
    { id: 1, name: 'Team A', image: $r('app.media.app_icon') },
    { id: 2, name: 'Team B', image: $r('app.media.app_icon') },
    { id: 3, name: 'Team C', image: $r('app.media.app_icon') },
    { id: 4, name: 'Team D', image: $r('app.media.app_icon') }
  ];

  @State selectedTeams: Team[] = [];

  build() {
    Column() {
      Text('Select Your Favorite Teams')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      List() {
        ForEach(this.teams, (team: Team, index?: number) => {
          ListItem() {
            Row() {
              Image(team.image)
                .width(50)
                .height(50)
                .margin({ right: 10 });
              Text(team.name)
                .fontSize(18)
                .padding(10)
                .onClick(() => {
                  if (this.selectedTeams.includes(team)) {
                    this.selectedTeams = this.selectedTeams.filter(selectedTeam => selectedTeam.id !== team.id);
                  } else {
                    this.selectedTeams = [...this.selectedTeams, team];
                  }
                });
            }
            .backgroundColor(this.selectedTeams.includes(team) ? '#d3d3d3' : '#f0f0f0')
            .borderRadius(5)
            .padding(10)
            .margin({ bottom: 10 });
          }
        }, (team: Team) => team.id.toString());
      }
      .width('100%');

      if (this.selectedTeams.length > 0) {
        Text('Selected Teams:')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 20 });

        ForEach(this.selectedTeams, (selectedTeam: Team) => {
          Row() {
            Image(selectedTeam.image)
              .width(30)
              .height(30)
              .margin({ right: 10 });
            Text(selectedTeam.name)
              .fontSize(18)
              .margin({ top: 10 });
          }
        }, (selectedTeam: Team) => selectedTeam.id.toString());
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

interface Team {
  id: number;
  name: string;
  image: Resource;
}

