          .width('100%')
          .height(240)
          .objectFit(ImageFit.Cover);

        Text(this.selectedRecipe.title)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 8 });

        Text('Ingredients:')
          .fontSize(18)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 16, bottom: 8 });

        Column() {
          ForEach(this.selectedRecipe.ingredients, (ingredient: string) => {
            Text(ingredient)
              .fontSize(16)
              .margin({ bottom: 4 });
          });
        }
        .margin({ bottom: 16 });

        Text('Instructions:')
          .fontSize(18)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 16, bottom: 8 });

        Column() {
          ForEach(this.selectedRecipe.instructions, (instruction: string) => {
            Text(instruction)
              .fontSize(16)
              .margin({ bottom: 4 });
          });
        }
        .margin({ bottom: 16 });
      }
      .width('100%');
    }
  }
