@Entry
@Component
struct DynamicMenuAtStartup {
  @State menuItems: Array<string> = ['Home', 'Profile', 'Settings']
  @State newMenuItem: string = ''
  @State isMenuOpen: boolean = false
  @State selectedItem: string = ''

  private handleMenuToggle() {
    this.isMenuOpen = !this.isMenuOpen
  }

  private handleMenuItemClick(item: string) {
    this.selectedItem = item
    this.isMenuOpen = false
  }

  private addMenuItem() {
    if (this.newMenuItem) {
      this.menuItems.push(this.newMenuItem)
      this.newMenuItem = ''
    }
  }

  private removeMenuItem(index: number) {
    this.menuItems.splice(index, 1)
  }

  build() {
    Column() {
      // Main content area
      Column() {
        Text('Main Content')
          .fontSize(24)
          .margin({ bottom: 20 })

        Button(this.isMenuOpen ? 'Close Menu' : 'Open Menu')
          .onClick(() => {
            this.handleMenuToggle()
          })
          .width(200)
          .height(50)
          .backgroundColor(Color.Blue)
          .fontColor(Color.White)
      }
      .width('100%')
      .height('70%')
      .justifyContent(FlexAlign.Center)
      .alignItems(HorizontalAlign.Center)

      // Menu area (conditionally rendered)
      if (this.isMenuOpen) {
        Column() {
          TextInput({ placeholder: 'Add new menu item' })
            .onChange((value: string) => {
              this.newMenuItem = value
            })
            .margin({ bottom: 20 })

          Button('Add Menu Item')
            .onClick(() => {
              this.addMenuItem()
            })
            .margin({ bottom: 20 })

          ForEach(this.menuItems, (item: string, index: number) => {
            Row() {
              Image($r('app.media.app_icon'))
                .width(24)
                .height(24)
                .margin({ right: 10 })
              Text(item)
                .fontSize(18)
                .fontColor(Color.Black)
              Button('Remove')
                .onClick(() => {
                  this.removeMenuItem(index)
                })
            }
            .width('100%')
            .padding(15)
            .backgroundColor(item === this.selectedItem ? Color.Gray : Color.White)
            .borderRadius(8)
            .onClick(() => {
              this.handleMenuItemClick(item)
            })
          })
        }
        .width('100%')
        .height('30%')
        .padding(10)
        .backgroundColor('#f5f5f5')
        .border({ width: 1, color: Color.Gray })
        .animation({ duration: 300, curve: Curve.Ease })
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
  }
}

