@Entry
@Component
struct DynamicSearchApp {
  @State items: string[] = [
    'Apple',
    'Banana',
    'Orange',
    'Grapes',
    'Mango',
    'Pineapple',
    'Strawberry',
    'Watermelon',
    'Cherry',
    'Blueberry',
    'Lemon',
    'Peach'
  ];

  @State searchText: string = '';

  filteredItems(): string[] {
    if (this.searchText.trim() === '') {
      return this.items;
    } else {
      return this.items.filter((item: string) =>
        item.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  build() {
    Column() {
      TextInput({
        placeholder: 'Search items...',
        text: this.searchText
      })
        .width('100%')
        .onChange((value: string) => {
          this.searchText = value;
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      if (this.filteredItems().length > 0) {
        List() {
          ForEach(this.filteredItems(), (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(18)
                .padding(12);
            }
          }, (item: string) => item);
        }
      } else {
        Text('No items found')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

@Entry
@Component
struct QuizApp {
  @State currentQuestionIndex: number = 0;
  @State score: number = 0;
  @State showScore: boolean = false;
  @State showFeedback: boolean = false;
  @State isCorrect: boolean = false;

  private questions: Array<Question> = [
    {
      question: 'What is the capital of France?',
      options: ['London', 'Berlin', 'Paris', 'Madrid'],
      correctAnswer: 2
    },
    {
      question: 'Which planet is closest to the Sun?',
      options: ['Mars', 'Venus', 'Mercury', 'Jupiter'],
      correctAnswer: 2
    },
    {
      question: 'What is the largest mammal?',
      options: ['African Elephant', 'Blue Whale', 'Giraffe', 'Hippopotamus'],
      correctAnswer: 1
    }
  ];

  checkAnswer(selectedIndex: number) {
    const correct = selectedIndex === this.questions[this.currentQuestionIndex].correctAnswer;
    this.isCorrect = correct;
    if (correct) {
      this.score++;
    }
    this.showFeedback = true;

    setTimeout(() => {
      this.showFeedback = false;
      if (this.currentQuestionIndex < this.questions.length - 1) {
        this.currentQuestionIndex++;
      } else {
        this.showScore = true;
      }
    }, 1000);
  }

  build() {
    Column() {
      if (!this.showScore) {
        Progress({
          value: ((this.currentQuestionIndex + 1) / this.questions.length) * 100,
          total: 100
        })
          .width('90%')
          .height(10)
          .margin({ top: 20, bottom: 20 });

        Text(`Question ${this.currentQuestionIndex + 1}/${this.questions.length}`)
          .fontSize(16)
          .margin({ bottom: 10 });

        Text(this.questions[this.currentQuestionIndex].question)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .textAlign(TextAlign.Center)
          .margin({ bottom: 40 })
          .padding({ left: 20, right: 20 });

        ForEach(this.questions[this.currentQuestionIndex].options, (option: string, index: number) => {
          Button(option)
            .width('80%')
            .height(50)
            .margin({ bottom: 10 })
            .backgroundColor(this.showFeedback && index === this.questions[this.currentQuestionIndex].correctAnswer ? '#4CAF50' : '#007AFF')
            .onClick(() => {
              if (!this.showFeedback) {
                this.checkAnswer(index);
              }
            });
        });

        if (this.showFeedback) {
          Text(this.isCorrect ? 'Correct!' : 'Incorrect!')
            .fontSize(20)
            .fontColor(this.isCorrect ? '#4CAF50' : '#F44336')
            .margin({ top: 20 });
        }
      } else {
        Column() {
          Text('Quiz Complete!')
            .fontSize(28)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Your Score: ${this.score}/${this.questions.length}`)
            .fontSize(24)
            .margin({ bottom: 40 });

          Button('Try Again')
            .onClick(() => {
              this.currentQuestionIndex = 0;
              this.score = 0;
              this.showScore = false;
            });
        }
        .justifyContent(FlexAlign.Center);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

interface Question {
  question: string;
  options: string[];
  correctAnswer: number;
}

