@Entry
@Component
struct FullScreenLaunchComponent {
  @State themeMode: 'light' | 'dark' = 'light';
  @State isLoading: boolean = true;
  @State progressValue: number = 0;
  @State isFocused: boolean = false;
  @State isPermissionGranted: boolean = false;

  private simulateDataLoading() {
    this.isLoading = true;
    this.progressValue = 0;
    const interval = setInterval(() => {
      if (this.progressValue < 100) {
        this.progressValue += 10;
      } else {
        clearInterval(interval);
        this.isLoading = false;
      }
    }, 300);
  }

  private setTheme(theme: 'light' | 'dark') {
    this.themeMode = theme;
  }

  build() {
    Column() {
      // Header Section with theme toggle
      Row() {
        Text('Full Screen Launch')
          .fontSize(24)
          .fontColor(this.themeMode === 'light' ? Color.Black : Color.White)
          .layoutWeight(1)
          .textAlign(TextAlign.Center)

        Button(`Switch to ${this.themeMode === 'light' ? 'Dark' : 'Light'}`)
          .onClick(() => this.setTheme(this.themeMode === 'light' ? 'dark' : 'light'))
          .type(ButtonType.Normal)
          .width(120)
      }
      .width('100%')
      .padding(10)
      .backgroundColor(this.themeMode === 'light' ? '#EEEEEE' : '#333333')

      // Main Content Section
      Column() {
        if (this.isPermissionGranted) {
          this.ImageDisplayView()
        } else {
          this.PermissionRequestView()
        }

        // Loading Indicator
        if (this.isLoading) {
          Progress({
            value: this.progressValue,
            style: ProgressStyle.Linear
          })
          .width('80%')
          .height(20)
          .margin({ top: 20 })
        }

        // Accessible Button Example
        Button('Reload Content')
          .onClick(() => {
            this.simulateDataLoading()
          })
          .margin({ top: 20 })
          .width(200)
          .height(50)
          .backgroundColor(this.isFocused ? Color.Blue : Color.Gray)
          .onFocus(() => this.isFocused = true)
          .onBlur(() => this.isFocused = false)
          .accessibilityLevel('1')
          .accessibilityTextHint('Button to reload content')
      }
      .layoutWeight(1)
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .alignItems(HorizontalAlign.Center)

      // Footer Section
      Row() {
        Text('© 2023 My App')
          .fontSize(14)
          .fontColor(this.themeMode === 'light' ? Color.Black : Color.White)
          .textAlign(TextAlign.Center)
          .width('100%')
      }
      .width('100%')
      .padding(10)
      .backgroundColor(this.themeMode === 'light' ? '#EEEEEE' : '#333333')
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.themeMode === 'light' ? Color.White : Color.Black)
  }

  @Builder
  ImageDisplayView() {
    Column({ space: 20 }) {
      Image($r('app.media.app_icon'))
        .width(150)
        .height(150)
        .borderRadius(10)
        .shadow({
          radius: 10,
          color: this.themeMode === 'light' ? '#888888' : '#222222',
          offsetX: 5,
          offsetY: 5
        })
        .objectFit(ImageFit.Contain)

      Text('Application Content')
        .fontSize(20)
        .fontColor(this.themeMode === 'light' ? Color.Black : Color.White)
    }
  }

  @Builder
  PermissionRequestView() {
    Column({ space: 20 }) {
      Text('Permission Required')
        .fontSize(20)
        .fontColor(Color.Red)

      Button('Grant Permission')
        .onClick(() => {
          this.isPermissionGranted = true
          this.simulateDataLoading()
        })
        .width(200)
        .height(50)
    }
  }

  aboutToAppear() {
    this.simulateDataLoading();
  }
}

