@Entry
@Component
struct Index {
  @State selectedMovie: Movie | null = null;
  @State rating: number = 0;

  private movies: Movie[] = [
    {
      title: "Movie 1",
      releaseDate: "2023-01-01",
      director: "Director 1",
      description: "Description for Movie 1",
      averageRating: 3.5,
      image: "app.media.movie1"
    },
    {
      title: "Movie 2",
      releaseDate: "2023-02-01",
      director: "Director 2",
      description: "Description for Movie 2",
      averageRating: 4.0,
      image: "app.media.movie2"
    }
  ];

  build() {
    if (this.selectedMovie == null) {
      Column() {
        Text('Movie List')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .padding(16);

        List() {
          ForEach(this.movies, (movie: Movie) => {
            ListItem() {
              Row() {
                Image(movie.image)
                  .width(100)
                  .height(150)
                  .objectFit(ImageFit.Cover)
                  .margin({ right: 10 });
                Column() {
                  Text(movie.title)
                    .fontSize(20)
                    .fontWeight(FontWeight.Medium)
                    .padding({ bottom: 4 });
                  Text(`Release Date: ${movie.releaseDate}`)
                    .fontSize(16)
                    .padding({ bottom: 8 });
                  Text(`Average Rating: ${movie.averageRating.toFixed(1)}`)
                    .fontSize(16)
                    .padding({ bottom: 8 });
                }
                .padding(16);
              }
              .onClick(() => {
                this.selectedMovie = movie;
                this.rating = 0;
              });
            }
          });
        }
      }
    } else {
      Scroll() {
        Column() {
          Image(this.selectedMovie.image)
            .width('100%')
            .height(300)
            .objectFit(ImageFit.Cover);

          Text(this.selectedMovie.title)
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .padding(16);

          Text(`Release Date: ${this.selectedMovie.releaseDate}`)
            .fontSize(18)
            .padding({ left: 16, right: 16, bottom: 8 });

          Text(`Director: ${this.selectedMovie.director}`)
            .fontSize(18)
            .padding({ left: 16, right: 16, bottom: 8 });

          Text('Description:')
            .fontSize(20)
            .fontWeight(FontWeight.Medium)
            .padding({ left: 16, right: 16, top: 16, bottom: 4 });

          Text(this.selectedMovie.description)
            .fontSize(16)
            .padding({ left: 16, right: 16, bottom: 16 });

          Text('Rate this movie:')
            .fontSize(20)
            .fontWeight(FontWeight.Medium)
            .padding({ left: 16, right: 16, top: 16, bottom: 4 });

          Row() {
            ForEach([1, 2, 3, 4, 5], (star: number) => {
              Image(this.rating >= star ? 'app.media.star_filled' : 'app.media.star_empty')
                .width(30)
                .height(30)
                .margin({ right: 5 })
                .onClick(() => {
                  this.rating = star;
                });
            });
          }
          .padding({ left: 16, right: 16, bottom: 16 });

          Button('Submit Rating')
            .onClick(() => {
              if (this.selectedMovie) {
                const index = this.movies.findIndex(m => m.title === this.selectedMovie?.title);
                if (index !== -1) {
                  this.movies[index].averageRating = (this.movies[index].averageRating + this.rating) / 2;
                }
                this.selectedMovie = null;
                this.rating = 0;
              }
            });
        }
      }
    }
  }
}

class Movie {
  title: string = "";
  releaseDate: string = "";
  director: string = "";
  description: string = "";
  averageRating: number = 0;
  image: string = "";
}

