@Component
struct ResponsiveSearchComponent {
  @State searchText: string = '';
  @State isExpanded: boolean = false;
  @State isLoading: boolean = false;
  @State items: string[] = ['Apple', 'Banana', 'Orange', 'Grapes', 'Mango', 'Pineapple', 'Strawberry', 'Watermelon', 'Cherry'];

  private filteredItems(): string[] {
    if (this.searchText.trim() === '') {
      return this.items;
    }
    return this.items.filter((item: string) =>
      item.toLowerCase().includes(this.searchText.toLowerCase())
    );
  }

  private async simulateSearch(): Promise<void> {
    this.isLoading = true;
    await new Promise<void>(resolve => setTimeout(resolve, 1000));
    this.isLoading = false;
  }

  build() {
    Column() {
      // Search bar with expandable behavior
      Row() {
        Image($r('app.media.app_icon'))
          .width(24)
          .height(24)
          .margin({ right: 8 });

        TextInput({ placeholder: 'Search...', text: this.searchText })
          .width(this.isExpanded ? '80%' : '60%')
          .height(40)
          .onChange((value: string) => {
            this.searchText = value;
          })
          .onFocus(() => {
            this.isExpanded = true;
          })
          .onBlur(() => {
            this.isExpanded = false;
          })
          .transition({ type: TransitionType.All })
          .animation({ duration: 200 });

        if (this.isExpanded) {
          Button('Cancel')
            .margin({ left: 8 })
            .onClick(() => {
              this.searchText = '';
              this.isExpanded = false;
            });
        }
      }
      .padding(16)
      .backgroundColor('#f0f0f0')
      .borderRadius(8)
      .width('100%');

      // Loading indicator
      if (this.isLoading) {
        Progress({ value: 50, total: 100, type: ProgressType.Linear })
          .size({ width: '80%', height: 20 })
          .color(Color.Blue)
          .margin({ top: 16 });
      } else {
        // Results layout
        if (this.filteredItems().length > 0) {
          List({ space: 10 }) {
            ForEach(this.filteredItems(), (item: string) => {
              ListItem() {
                Text(item)
                  .fontSize(16)
                  .margin({ top: 8, bottom: 8 });
              }
            });
          }
          .width('100%')
          .height('80%')
          .backgroundColor('#eeeeee');
        } else if (this.searchText) {
          Text('No results found')
            .fontSize(16)
            .fontColor(Color.Gray)
            .padding(16);
        }
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#fafafa');
  }
}

