@Entry
@Component
struct LazyDataFetchComponent {
  @State data: string[] = [];
  @State isLoading: boolean = false;

  private async fetchData(): Promise<string[]> {
    return new Promise((resolve) => {
      setTimeout(() => {
        resolve(["Lazy Item 1", "Lazy Item 2", "Lazy Item 3", "Lazy Item 4", "Lazy Item 5"]);
      }, 2000);
    });
  }

  private loadData() {
    this.isLoading = true;
    this.fetchData().then((result) => {
      this.data = result;
      this.isLoading = false;
    });
  }

  build() {
    Column() {
      if (this.isLoading) {
        Progress({ value: 50, total: 100, type: ProgressType.Linear })
          .size({ width: "80%", height: 20 })
          .color(Color.Blue);
      } else {
        Grid() {
          ForEach(this.data, (item: string) => {
            GridItem() {
              Text(item)
                .fontSize(18)
                .margin(10)
                .textAlign(TextAlign.Center)
                .backgroundColor(Color.White)
                .borderRadius(10)
                .padding(10);
            }
          }, (item: string) => item);
        }
        .columnsTemplate('1fr 1fr')
        .rowsGap(10)
        .columnsGap(10)
        .padding(10);
      }

      Button("Fetch Data")
        .onClick(() => {
          this.loadData();
        })
        .margin({ top: 20 });
    }
    .width("100%")
    .height("100%")
    .padding(20)
    .backgroundColor("#ffffff");
  }
}

