@Entry
@Component
struct FormExample {
  @State email: string = ''
  @State isEmailValid: boolean = true
  @State emailError: string = ''

  @State password: string = ''
  @State isPasswordValid: boolean = true
  @State passwordError: string = ''

  validateEmail(email: string): string | null {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return emailRegex.test(email) ? null : 'Please enter a valid email'
  }

  validatePassword(password: string): string | null {
    return password.length >= 6 ? null : 'Password must be at least 6 characters'
  }

  build() {
    Column({ space: 20 }) {
      TextInput({ placeholder: 'Email', text: this.email })
        .onChange((value: string) => {
          this.email = value
          const error = this.validateEmail(value)
          this.isEmailValid = error === null
          this.emailError = error || ''
        })
      if (!this.isEmailValid) {
        Text(this.emailError)
          .fontColor('#FF0000')
      }

      TextInput({ placeholder: 'Password', text: this.password })
        .onChange((value: string) => {
          this.password = value
          const error = this.validatePassword(value)
          this.isPasswordValid = error === null
          this.passwordError = error || ''
        })
      if (!this.isPasswordValid) {
        Text(this.passwordError)
          .fontColor('#FF0000')
      }

      Button('Submit')
        .enabled(this.isEmailValid && this.isPasswordValid)
        .onClick(() => {
          console.info('Form submitted')
        })
    }
    .padding(20)
    .width('100%')
  }
}

