@Entry
@Component
struct DragDropList {
  @State items: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4', 'Item 5']
  @State draggingIndex: number = -1
  @State targetIndex: number = -1
  @State prevY: number = 0

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.items, (item: string, index: number) => {
          ListItem() {
            Text(item)
              .fontSize(20)
              .width('100%')
              .height(60)
              .backgroundColor(this.draggingIndex === index ? '#e0e0e0' : '#f5f5f5')
              .borderRadius(8)
              .onTouch((event: TouchEvent) => {
                if (event.type === TouchType.Down) {
                  this.draggingIndex = index
                  this.prevY = event.touches[0].y
                } else if (event.type === TouchType.Move) {
                  const currentY = event.touches[0].y
                  this.targetIndex = Math.min(Math.max(0, index + (currentY > this.prevY ? 1 : -1)), this.items.length - 1)
                  this.prevY = currentY
                } else if (event.type === TouchType.Up) {
                  if (this.draggingIndex >= 0 && this.targetIndex >= 0 && this.draggingIndex !== this.targetIndex) {
                    const newItems = [...this.items]
                    const removed = newItems[this.draggingIndex]
                    newItems.splice(this.draggingIndex, 1)
                    newItems.splice(this.targetIndex, 0, removed)
                    this.items = newItems
                  }
                  this.draggingIndex = -1
                  this.targetIndex = -1
                }
              })
          }
          .opacity(this.draggingIndex === index ? 0.5 : 1)
        })
      }
      .width('100%')
      .height('100%')
      .divider({ strokeWidth: 1, color: '#cccccc' })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

