@Entry
@Component
struct BatchPersistenceExample {
  @State data: Array<string> = ['Item 1', 'Item 2', 'Item 3'];
  @State selectedItems: Array<number> = [];
  @StorageProp('persistedData') persistedData: Array<string> = [];

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.data, (item: string, index: number) => {
          ListItem() {
            Row() {
              Text(item)
                .fontSize(20)
                .margin({ left: 10 })
              Checkbox()
                .onChange((checked: boolean) => {
                  if (checked) {
                    this.selectedItems.push(index);
                  } else {
                    const pos = this.selectedItems.indexOf(index);
                    if (pos >= 0) {
                      this.selectedItems.splice(pos, 1);
                    }
                  }
                })
            }
            .justifyContent(FlexAlign.SpaceBetween)
            .padding(10)
          }
        })
      }
      .layoutWeight(1)

      Button('Persist Selected')
        .onClick(() => {
          this.selectedItems.forEach((index: number) => {
            this.persistedData.push(this.data[index]);
          });
          this.selectedItems = [];
        })
        .margin(20)

      Button('Clear Persisted Data')
        .onClick(() => {
          this.persistedData = [];
        })
        .margin(20)

      Text('Persisted Data:')
        .fontSize(20)
        .margin(10)

      List({ space: 5 }) {
        ForEach(this.persistedData, (item: string) => {
          ListItem() {
            Text(item)
              .fontSize(16)
              .margin(10)
          }
        })
      }
      .layoutWeight(1)
    }
    .padding(20)
  }
}

