@Entry
@Component
struct NoteApp {
  @State notes: Array<Note> = [];
  @State newNoteTitle: string = '';
  @State newNoteContent: string = '';
  @State editNoteId: number | null = null;

  build() {
    Column() {
      TextInput({ placeholder: 'Enter note title...', text: this.newNoteTitle })
        .height(50)
        .width('90%')
        .onChange((value: string) => {
          this.newNoteTitle = value;
        })
        .margin(10);

      TextArea({ placeholder: 'Enter note content...', text: this.newNoteContent })
        .height(100)
        .width('90%')
        .onChange((value: string) => {
          this.newNoteContent = value;
        })
        .margin(10);

      Button(this.editNoteId !== null ? 'Update Note' : 'Add Note')
        .onClick(() => {
          if (this.newNoteTitle.trim() && this.newNoteContent.trim()) {
            const timestamp = new Date().toLocaleString();
            if (this.editNoteId !== null) {
              const index = this.notes.findIndex(note => note.id === this.editNoteId);
              this.notes[index] = new Note(
                this.editNoteId,
                this.newNoteTitle,
                this.newNoteContent,
                timestamp
              );
              this.editNoteId = null;
            } else {
              this.notes.push(new Note(
                Date.now(),
                this.newNoteTitle,
                this.newNoteContent,
                timestamp
              ));
            }
            this.newNoteTitle = '';
            this.newNoteContent = '';
          }
        })
        .margin(10);

      List() {
        ForEach(this.notes, (note: Note) => {
          ListItem() {
            Column() {
              Text(note.title)
                .fontSize(20)
                .fontWeight(FontWeight.Bold)
                .margin({ bottom: 5 });

              Text(note.content)
                .fontSize(16)
                .margin({ bottom: 5 });

              Text(note.timestamp)
                .fontSize(12)
                .fontColor(Color.Gray);

              Row() {
                Button('Edit')
                  .onClick(() => {
                    this.newNoteTitle = note.title;
                    this.newNoteContent = note.content;
                    this.editNoteId = note.id;
                  })
                  .margin(5);

                Button('Delete')
                  .onClick(() => {
                    this.notes = this.notes.filter(n => n.id !== note.id);
                  })
                  .margin(5);
              }
            }
            .padding(10)
            .width('100%')
            .backgroundColor('#f0f0f0')
            .borderRadius(8)
            .margin({ bottom: 10 });
          }
        });
      }
      .width('100%')
      .height('70%');
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#ffffff');
  }
}

class Note {
  id: number;
  title: string;
  content: string;
  timestamp: string;

  constructor(id: number, title: string, content: string, timestamp: string) {
    this.id = id;
    this.title = title;
    this.content = content;
    this.timestamp = timestamp;
  }
}

