          .width('100%')
          .height(40)
          .margin({ top: 24 })
          .onClick(() => {
            this.dialogController.close();
          });
      }
      .padding(24)
      .width('90%')
      .backgroundColor(Color.White)
      .borderRadius(16);
    }
  }

  build() {
    Column() {
      Text('Image Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Column() {
        Swiper(this.swiperController) {
          ForEach(this.carouselItems, (item: CarouselItem) => {
            Stack() {
              Image(item.image)
                .width('100%')
                .height(300)
                .objectFit(ImageFit.Cover)
                .borderRadius(16)
                .onClick(() => {
                  this.selectedItem = item;
                  this.dialogController.open();
                });
            }
          });
        }
        .width('100%')
        .height(300)
        .margin({ bottom: 16 })
        .autoPlay(true)
        .interval(3000)
        .indicator(true)
        .loop(true)
        .duration(500)
        .onChange((index: number) => {
          this.currentIndex = index;
        });

        Text(this.carouselItems[this.currentIndex].caption)
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 8 })
          .textAlign(TextAlign.Center);
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(20);

      Row() {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });

        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

interface CarouselItem {
  id: number;
  image: Resource;
  caption: string;
  description: string;
}

@Entry
@Component
struct FullScreenLaunchComponent {
  @State private isFocused: boolean = false;
  @State private textInput: string = '';
  @State private imageClicked: boolean = false;
  @State private clickCount: number = 0;
  @State private lastEventTime: string = '';
  @State private isProcessing: boolean = false;

  private handleButtonClick(): void {
    console.log('Button clicked');
  }

  private handleTextInputChange(value: string): void {
    this.textInput = value;
    console.log('Text input changed:', value);
  }

  private handleImageClick(): void {
    this.imageClicked = !this.imageClicked;
    console.log('Image clicked');
  }

  private handleClick(): void {
    if (this.isProcessing) return;

    this.isProcessing = true;
    this.clickCount += 1;
    this.lastEventTime = new Date().toLocaleTimeString();

    setTimeout(() => {
      this.isProcessing = false;
    }, 500);
  }

  private handleLongPress(): void {
    this.clickCount = 0;
    this.lastEventTime = 'Reset at ' + new Date().toLocaleTimeString();
  }

  build() {
    Column({ space: 20 }) {
      Button('Click Me')
        .fontSize(20)
        .backgroundColor(this.isFocused ? Color.Blue : Color.Gray)
        .onClick(() => this.handleButtonClick())
        .onFocus(() => {
          this.isFocused = true;
          console.log('Button focused');
        })
        .onBlur(() => {
          this.isFocused = false;
          console.log('Button blurred');
        });

      TextInput({ placeholder: 'Enter text' })
        .fontSize(20)
        .margin({ top: 20 })
        .onChange((value: string) => this.handleTextInputChange(value));

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 20 })
        .onClick(() => this.handleImageClick())
        .gesture(
          LongPressGesture({ repeat: false })
            .onAction(() => {
              this.handleLongPress();
            })
        );

      Text(this.imageClicked ? 'Image clicked!' : 'Image not clicked')
        .fontSize(20)
        .margin({ top: 20 });

      Text(`Clicks: ${this.clickCount}`)
        .fontSize(20)
        .fontColor(Color.Black);

      Text(`Last event: ${this.lastEventTime}`)
        .fontSize(16)
        .fontColor(Color.Gray);

      if (this.isProcessing) {
        Progress({ value: 50 })
          .width(100)
          .height(4)
          .color(Color.Blue);
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

