@Entry
@Component
struct TimePicker24HourExample {
  @State selectedTime: Date = new Date(2023, 9, 15, 14, 30, 0); // Initialize with a default time in 24-hour format

  build() {
    Column({ space: 20 }) {
      // Display the current time
      Text(`Selected Time: ${this.selectedTime.toLocaleTimeString()}`)
        .fontSize(20)
        .margin({ bottom: 20 })

      // TimePicker element with 24-hour format
      TimePicker({
        selected: this.selectedTime
      })
        .useMilitaryTime(true) // Set to 24-hour format
        .onChange((value: TimePickerResult) => {
          this.selectedTime = new Date(
            this.selectedTime.getFullYear(),
            this.selectedTime.getMonth(),
            this.selectedTime.getDate(),
            value.hour,
            value.minute,
            value.second
          );
          console.info('Selected time in 24-hour format: ' + this.selectedTime.toLocaleTimeString());
        })
        .margin({ bottom: 40 })

      // Display the selected time details
      Text(`Hour: ${this.selectedTime.getHours()}`)
        .fontSize(18)
        .margin({ top: 10 })

      Text(`Minute: ${this.selectedTime.getMinutes()}`)
        .fontSize(18)
        .margin({ top: 10 })

      Text(`Second: ${this.selectedTime.getSeconds()}`)
        .fontSize(18)
        .margin({ top: 10 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

