@Entry
@Component
struct DeepNestedOptimizedUI {
  @State private data: Array<Item> = [];
  @State private isOptimized: boolean = false;
  @State private renderCount: number = 0;

  aboutToAppear() {
    for (let i = 0; i < 100; i++) {
      this.data.push({ id: i, text: `Item ${i}` });
    }
  }

  build() {
    Column() {
      Text(this.isOptimized ? "Optimized Rendering" : "Deep Nesting Rendering")
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin(10);

      Text(`Render Count: ${this.renderCount}`)
        .fontSize(16)
        .margin({ bottom: 10 });

      Button(this.isOptimized ? "Show Deep Nesting" : "Show Optimized Rendering")
        .onClick(() => {
          this.isOptimized = !this.isOptimized;
          this.renderCount++;
        })
        .margin(10);

      if (this.isOptimized) {
        this.OptimizedView();
      } else {
        this.DeepNestedView();
      }
    }
    .width('100%')
    .height('100%')
    .padding(10)
  }

  @Builder
  DeepNestedView() {
    Scroll() {
      Column() {
        ForEach(this.data, (item: Item) => {
          Column() {
            Row() {
              Image($r('app.media.app_icon'))
                .width(50)
                .height(50)
                .margin(5);
              Text(item.text)
                .fontSize(18)
                .margin(5);
            }
            .padding(10)
            .backgroundColor(Color.White)
            .borderRadius(10)
            .margin(5);
          }
        })
      }
    }
    .height('80%')
    .width('100%')
    .onScroll((scrollOffset: number) => {
      console.info(`Scroll offset: ${scrollOffset}`);
    });
  }

  @Builder
  OptimizedView() {
    List({ space: 10 }) {
      ForEach(this.data, (item: Item) => {
        ListItem() {
          Row() {
            Image($r('app.media.app_icon'))
              .width(50)
              .height(50)
              .margin(5);
            Text(item.text)
              .fontSize(18)
              .margin(5);
          }
          .padding(10)
          .backgroundColor(Color.White)
          .borderRadius(10)
          .margin(5);
        }
      })
    }
    .width('100%')
    .height('80%')
    .onScrollIndex((start: number, end: number) => {
      console.info(`Visible items: ${start} to ${end}`);
    });
  }
}

interface Item {
  id: number;
  text: string;
}

@Entry
@Component
struct NavigationDrawerApp {
  @State currentScreen: string = 'Home';
  @State isDrawerOpen: boolean = false;

  build() {
    Row() {
      // Main Content Area
      Column() {
        Text(this.getScreenMessage())
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20, bottom: 20 })
          .textAlign(TextAlign.Center);

        Button('Toggle Drawer')
          .onClick(() => {
            this.isDrawerOpen = !this.isDrawerOpen;
          });
      }
      .layoutWeight(1);

      // Drawer Menu
      Panel(this.isDrawerOpen) {
        Column() {
          Text('Navigation Drawer')
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ top: 20, bottom: 20 });

          this.NavItem('Home');
          this.NavItem('Profile');
          this.NavItem('Settings');
          this.NavItem('About');

          Button('Close Drawer')
            .onClick(() => {
              this.isDrawerOpen = false;
            });
        }
        .padding(20)
        .backgroundColor(Color.White);
      }
      .mode(PanelMode.Mini)
      .type(PanelType.Temporary)
      .dragBar(false);
    }
    .width('100%')
    .height('100%');
  }

  @Builder NavItem(label: string) {
    Button(label)
      .onClick(() => {
        this.currentScreen = label;
        this.isDrawerOpen = false;
      })
      .margin({ bottom: 10 })
      .width('100%');
  }

  getScreenMessage() {
    switch (this.currentScreen) {
      case 'Home':
        return 'Welcome to the Home Screen!';
      case 'Profile':
        return 'This is your Profile Screen.';
      case 'Settings':
        return 'Adjust your settings here.';
      case 'About':
        return 'Learn more about us here.';
      default:
        return '';
    }
  }
}

