@Entry
@Component
struct DragAnimationOptions {
  @State offsetX: number = 0;
  @State offsetY: number = 0;
  @State initialX: number = 0;
  @State initialY: number = 0;
  @State isDragging: boolean = false;
  @State boundaryWidth: number = 300;
  @State boundaryHeight: number = 300;

  build() {
    Stack() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .position({ x: this.offsetX, y: this.offsetY })
        .opacity(this.isDragging ? 0.5 : 1)
        .onTouch((event: TouchEvent) => {
          if (event.type === TouchType.Down) {
            this.initialX = this.offsetX;
            this.initialY = this.offsetY;
            this.isDragging = true;
          } else if (event.type === TouchType.Move) {
            const touch = event.touches[0];
            if (touch) {
              let newX = this.initialX + touch.x;
              let newY = this.initialY + touch.y;

              if (newX >= 0 && newX <= this.boundaryWidth - 100) {
                this.offsetX = newX;
              }
              if (newY >= 0 && newY <= this.boundaryHeight - 100) {
                this.offsetY = newY;
              }
            }
          } else if (event.type === TouchType.Up) {
            this.isDragging = false;
          }
        })
        .animation({ duration: 300, curve: Curve.EaseInOut });

      Stack()
        .width(this.boundaryWidth)
        .height(this.boundaryHeight)
        .backgroundColor('#f0f0f0')
        .border({ width: 1, color: '#000000' });
    }
    .width('100%')
    .height('100%');
  }
}

