@Component
struct ChatApp {
  @State messages: Array<Message> = [];
  @State inputText: string = '';

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.messages, (message: Message) => {
          ListItem() {
            Column() {
              Text(message.text)
                .fontSize(16)
                .padding(10)
                .backgroundColor(message.isUser ? '#007AFF' : '#f5f5f5')
                .borderRadius(10)
                .align(Alignment.Start)
                .margin({ left: message.isUser ? '50%' : '0%', right: message.isUser ? '0%' : '50%' })
            }
          }
        })
      }
      .layoutWeight(1)
      .width('100%')
      .padding(10)

      Row() {
        TextInput({ placeholder: 'Type a message...' })
          .width('80%')
          .height(40)
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.inputText = value;
          })

        Button('Send')
          .width('20%')
          .height(40)
          .fontSize(16)
          .backgroundColor('#007AFF')
          .onClick(() => {
            if (this.inputText.trim()) {
              this.messages.push(new Message(this.inputText, true));
              this.inputText = '';
              setTimeout(() => {
                this.messages.push(new Message('This is a response.', false));
              }, 1000);
            }
          })
      }
      .width('100%')
      .padding(10)
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

