@Entry
@Component
struct RichEditorEventExample {
  controller: RichEditorController = new RichEditorController();
  options: RichEditorOptions = { controller: this.controller };
  @State textFlag: string = "No event triggered yet.";
  @State selectedText: string = "";
  @State selectionRange: string = "[-1, -1]";

  build() {
    Column({ space: 10 }) {
      RichEditor(this.options)
        .onReady(() => {
          this.controller.addTextSpan("Click or long press this text.", {
            style: {
              fontColor: Color.Black,
              fontSize: 20
            },
            gesture: {
              onClick: () => {
                this.textFlag = "Text clicked.";
              },
              onLongPress: () => {
                this.textFlag = "Text long pressed.";
              }
            }
          });

          this.controller.addTextSpan("\nSelect this text to modify attributes.", {
            style: {
              fontColor: Color.Blue,
              fontSize: 20
            }
          });

          this.controller.addImageSpan($r("app.media.app_icon"), {
            imageStyle: {
              size: ["50px", "50px"]
            },
            gesture: {
              onClick: () => {
                this.textFlag = "Image clicked.";
              },
              onLongPress: () => {
                this.textFlag = "Image long pressed.";
              }
            }
          });
        })
        .onSelect((value: RichEditorSelection) => {
          this.selectionRange = `[${value.selection[0]}, ${value.selection[1]}]`;
          this.selectedText = "";
          value.spans.forEach(item => {
            if (typeof (item as RichEditorTextSpanResult)['value'] !== 'undefined') {
              this.selectedText += (item as RichEditorTextSpanResult).value;
            }
          });
        })
        .borderWidth(1)
        .borderColor(Color.Gray)
        .width('100%')
        .height('40%');

      Text("Event Status: " + this.textFlag)
        .fontSize(16)
        .margin({ top: 10 });

      Text("Selection Range: " + this.selectionRange)
        .fontSize(16)
        .margin({ top: 10 });

      Text("Selected Text: " + this.selectedText)
        .fontSize(16)
        .margin({ top: 10 });

      Button("Make Selection Bold")
        .width(200)
        .height(40)
        .onClick(() => {
          this.controller.updateSpanStyle({
            start: parseInt(this.selectionRange.split(",")[0].replace("[", "")),
            end: parseInt(this.selectionRange.split(",")[1].replace("]", "")),
            textStyle: {
              fontWeight: FontWeight.Bold
            }
          });
        });

      Button("Make Selection Italic")
        .width(200)
        .height(40)
        .onClick(() => {
          this.controller.updateSpanStyle({
            start: parseInt(this.selectionRange.split(",")[0].replace("[", "")),
            end: parseInt(this.selectionRange.split(",")[1].replace("]", "")),
            textStyle: {
              fontStyle: FontStyle.Italic
            }
          });
        });
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

