import { ExceptionPrompt, PromptOptions, MarginType } from '@kit.ArkUI';
import http from '@ohos.net.http';

@Entry
@Component
struct TimeoutHandling {
  @State options: PromptOptions = {
    icon: $r('app.media.app_icon'),
    tip: 'Network Error Occurred',
    marginType: MarginType.DEFAULT_MARGIN,
    actionText: 'Retry',
    marginTop: 80,
    isShown: false
  };
  @State isLoading: boolean = false;
  @State data: string = '';
  @State timeoutConfig: http.HttpRequestOptions = {
    connectTimeout: 30000,
    readTimeout: 30000
  };

  async fetchData() {
    this.isLoading = true;
    this.options.isShown = false;

    try {
      let httpRequest = http.createHttp();
      let response = await httpRequest.request(
        'https://api.example.com/data',
        {
          method: http.RequestMethod.GET,
          connectTimeout: this.timeoutConfig.connectTimeout,
          readTimeout: this.timeoutConfig.readTimeout
        }
      );

      if (response.responseCode === 200) {
        this.data = response.result.toString();
      } else {
        this.options.tip = `Server Error: ${response.responseCode}`;
        this.options.isShown = true;
      }
    } catch (error) {
      this.options.tip = `Network Error: ${error.message}`;
      this.options.isShown = true;
    } finally {
      this.isLoading = false;
    }
  }

  updateTimeoutConfig(connectTimeout: number, readTimeout: number) {
    this.timeoutConfig.connectTimeout = connectTimeout;
    this.timeoutConfig.readTimeout = readTimeout;
  }

  build() {
    Column() {
      if (this.isLoading) {
        LoadingProgress()
          .width(50)
          .height(50);
      } else if (this.data) {
        Text(this.data)
          .fontSize(16)
          .margin(20);
      }

      Button('Update Timeout (10s)')
        .onClick(() => {
          this.updateTimeoutConfig(10000, 10000);
        })
        .margin(10);

      Button('Update Timeout (30s)')
        .onClick(() => {
          this.updateTimeoutConfig(30000, 30000);
        })
        .margin(10);

      ExceptionPrompt({
        options: this.options,
        onActionTextClick: () => {
          this.fetchData();
        }
      });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .onAppear(() => {
      this.fetchData();
    });
  }
}

