@Component
struct ClickEventDebugging {
  @State private clickCount: number = 0;

  private logClickEvent(event: ClickEvent, buttonName: string): void {
    this.clickCount++;
    console.info(`Button "${buttonName}" clicked! Event details: ${event}`);
    console.info(`Total clicks: ${this.clickCount}`);
  }

  build() {
    Column() {
      Button('Button 1')
        .margin(20)
        .onClick((event: ClickEvent) => {
          this.logClickEvent(event, 'Button 1');
        })
      Button('Button 2')
        .margin(20)
        .onClick((event: ClickEvent) => {
          this.logClickEvent(event, 'Button 2');
        })
      Text(`Total Clicks: ${this.clickCount}`)
        .fontSize(20)
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

