import promptAction from '@ohos.promptAction';

class AnalyticsEvent {
  public eventType: string;
  public timestamp: number;

  constructor(eventType: string) {
    this.eventType = eventType;
    this.timestamp = Date.now();
  }
}

@Entry
@Component
struct AnalyticsApp {
  @State events: AnalyticsEvent[] = [];

  logAnalytics(eventType: string): void {
    const newEvent = new AnalyticsEvent(eventType);
    this.events.push(newEvent);
    console.log(`Analytics Event: ${eventType} at ${newEvent.timestamp}`);
    promptAction.showToast({ message: `Event: ${eventType} logged`, duration: 2000 });
  }

  build() {
    Column() {
      Button('Log Button Click')
        .onClick(() => {
          this.logAnalytics('Button Clicked');
        })
        .width(200)
        .height(50)
        .backgroundColor(Color.Blue)
        .fontColor(Color.White)
        .margin(10)
        .fontSize(18);

      Button('Log Page View')
        .onClick(() => {
          this.logAnalytics('Page Viewed');
        })
        .width(200)
        .height(50)
        .backgroundColor(Color.Green)
        .fontColor(Color.White)
        .margin(10)
        .fontSize(18);

      ForEach(this.events, (event: AnalyticsEvent) => {
        Row() {
          Text(`Event: ${event.eventType} at ${new Date(event.timestamp).toLocaleTimeString()}`)
            .fontSize(14)
