@Entry
@Component
struct ImageCarousel {
  private swiperController: SwiperController = new SwiperController();

  private carouselItems: Array<CarouselItem> = [
    {
      id: 1,
      image: $r('app.media.app_icon'),
      title: 'Mountain View'
    },
    {
      id: 2,
      image: $r('app.media.app_icon'),
      title: 'Ocean Sunset'
    },
    {
      id: 3,
      image: $r('app.media.app_icon'),
      title: 'Forest Path'
    },
    {
      id: 4,
      image: $r('app.media.app_icon'),
      title: 'Desert Dunes'
    }
  ];

  @State currentIndex: number = 0;

  build() {
    Column() {
      Text('Image Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Column() {
        Swiper(this.swiperController) {
          ForEach(this.carouselItems, (item: CarouselItem) => {
            Stack() {
              Image(item.image)
                .width('100%')
                .height(300)
                .objectFit(ImageFit.Cover)
                .borderRadius(16);
            }
          });
        }
        .width('100%')
        .height(300)
        .margin({ bottom: 16 })
        .autoPlay(true)
        .interval(3000)
        .indicator(true)
        .loop(true)
        .duration(500)
        .onChange((index: number) => {
          this.currentIndex = index;
        });

        Text(this.carouselItems[this.currentIndex].title)
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 8 })
          .textAlign(TextAlign.Center);
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(20);

      Row() {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });

        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

interface CarouselItem {
  id: number;
  image: Resource;
  title: string;
}

@Entry
@Component
struct ReusableUIComponents {
  @State title: string = 'Reusable UI Components';
  @State description: string = 'Efficient Build';
  @State isExpanded: boolean = false;
  @State counter: number = 0;
  @State selectedTheme: string = 'Light';

  // Reusable Header Builder
  @Builder
  HeaderBuilder(headerTitle: string, headerSubtitle: string) {
    Column() {
      Text(headerTitle)
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .fontColor(Color.Black)
        .margin({ bottom: 5 });

      Text(headerSubtitle)
        .fontSize(16)
        .fontColor(Color.Gray)
        .margin({ bottom: 20 });

      Divider()
        .strokeWidth(1)
        .color(Color.Gray);
    }
    .width('100%')
    .padding(20);
  }

  // Reusable Expandable Content Builder
  @Builder
  ExpandableContentBuilder() {
    Column() {
      if (this.isExpanded) {
        Text('This is the expanded content area with detailed information.')
          .fontSize(14)
          .margin({ bottom: 10 });

        Image($r('app.media.app_icon'))
          .width(80)
          .height(80)
          .margin({ bottom: 10 });

        Text(`Counter: ${this.counter}`)
          .fontSize(16)
          .fontWeight(FontWeight.Medium);
      }
    }
    .width('100%')
    .padding(10)
    .backgroundColor('#F5F5F5')
    .borderRadius(8);
  }

  // Reusable Control Panel Builder
  @Builder
  ControlPanelBuilder() {
    Row() {
      Button(this.isExpanded ? 'Collapse' : 'Expand')
        .onClick(() => {
          this.isExpanded = !this.isExpanded;
        })
        .width(120)
        .margin({ right: 10 });

      Button('Increment')
        .onClick(() => {
          this.counter++;
        })
        .width(120);
    }
    .margin({ top: 10, bottom: 20 });
  }

  // Reusable Theme Selector Builder
  @Builder
  ThemeSelectorBuilder() {
    Column() {
      Text('Select Theme:')
        .fontSize(16)
        .margin({ bottom: 5 });

      Row() {
        ForEach(['Light', 'Dark', 'Blue', 'Green'], (theme: string) => {
          Button(theme)
            .backgroundColor(this.selectedTheme === theme ? Color.Black : Color.White)
            .fontColor(this.selectedTheme === theme ? Color.White : Color.Black)
            .onClick(() => {
              this.selectedTheme = theme;
            })
            .margin({ right: 5 });
        })
      }
    }
    .margin({ top: 10 });
  }

  build() {
    Column() {
      this.HeaderBuilder(this.title, this.description);

      this.ExpandableContentBuilder();

      this.ControlPanelBuilder();

      this.ThemeSelectorBuilder();

      Text(`Current Theme: ${this.selectedTheme}`)
        .fontSize(16)
        .fontWeight(FontWeight.Medium)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White);
  }
}

