@Entry
@Component
struct CheckboxGroupOptions {
  @State private checkboxStates: boolean[] = [false, false, false];
  @State private selectedOptions: string[] = [];

  build() {
    Column({ space: 20 }) {
      Text('Select your options:')
        .fontSize(20)
        .margin({ bottom: 10 });

      CheckboxGroup() {
        ForEach(this.checkboxStates, (state: boolean, index: number) => {
          Column() {
            Checkbox({ name: `option${index + 1}` })
              .select(state)
              .selectedColor(Color.Blue)
              .shape(CheckBoxShape.ROUNDED_SQUARE)
              .onChange((value: boolean) => {
                this.checkboxStates[index] = value;
                this.updateSelection(`option${index + 1}`, value);
              })
              .width('100%')
              .height(50);

            Text(`Option ${index + 1}`)
              .fontSize(16)
              .margin({ left: 10 });
          }
          .margin({ bottom: 10 });
        })
      }
      .width('80%')
      .padding(20)
      .backgroundColor(Color.White)
      .borderRadius(10);

      Text('Selected Options: ' + this.selectedOptions.join(', '))
        .fontSize(16)
        .margin({ top: 10 });
    }
    .width('100%')
    .height('100%')
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .backgroundColor('#D3D3D3')
    .padding(20);
  }

  updateSelection(option: string, isSelected: boolean) {
    if (isSelected) {
      this.selectedOptions = [...this.selectedOptions, option];
    } else {
      this.selectedOptions = this.selectedOptions.filter(item => item !== option);
    }
  }
}

