@Component
struct MusicPlayer {
  @State isPlaying: boolean = false
  @State currentSong: string = 'Awesome Song'
  @State currentArtist: string = 'Cool Artist'
  @State progress: number = 0

  build() {
    Column() {
      // Album art placeholder
      Image($r('app.media.app_icon'))
        .width(300)
        .height(300)
        .borderRadius(10)

      // Song info
      Text(this.currentSong)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20 })
      Text(this.currentArtist)
        .fontSize(18)
        .margin({ top: 5 })

      // Progress bar
      Slider({
        value: this.progress,
        min: 0,
        max: 100,
        step: 1
      })
        .width('80%')
        .margin({ top: 20 })

      // Play/Pause/Stop buttons
      Row({ space: 20 }) {
        Button(this.isPlaying ? 'Pause' : 'Play')
          .onClick(() => {
            this.isPlaying = !this.isPlaying
          })
        Button('Stop')
          .onClick(() => {
            this.isPlaying = false
            this.progress = 0
          })
      }
      .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor($r('sys.color.ohos_id_color_background'))
  }
}

