        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Button('Login')
        .onClick(() => {
          if (this.validateInput()) {
            this.navigateToHome();
            promptAction.showToast({
              message: 'Login successful!',
