@Entry
@Component
struct CustomSortingApp {
  @State items: string[] = ['Banana', 'Apple', 'Cherry', 'Date'];
  @State inputText: string = '';
  @State sortedItems: string[] = [];

  private sortAlphabetically(): void {
    this.sortedItems = [...this.items.sort((a, b) => a.localeCompare(b))];
  }

  private sortByLength(): void {
    this.sortedItems = [...this.items.sort((a, b) => a.length - b.length)];
  }

  private addItem(): void {
    if (this.inputText.trim() !== '') {
      this.items = [...this.items, this.inputText.trim()];
      this.inputText = '';
    }
  }

  build() {
    Column() {
      Text('Original List').fontSize(20).margin(10);
      ForEach(this.items, (item: string) => {
        Text(item).fontSize(18).margin(5);
      });

      TextInput({ placeholder: 'Add a new item' })
        .width('80%')
        .height(40)
        .margin(10)
        .onChange((value: string) => {
          this.inputText = value;
        });

      Button('Add Item')
        .onClick(() => {
          this.addItem();
        })
        .margin(10);

      Button('Sort Alphabetically')
        .onClick(() => {
          this.sortAlphabetically();
        })
        .margin(10);

      Button('Sort by Length')
        .onClick(() => {
          this.sortByLength();
        })
        .margin(10);

      Text('Sorted List').fontSize(20).margin(10);
      ForEach(this.sortedItems, (item: string) => {
        Text(item).fontSize(18).margin(5);
      });
    }
    .width('100%')
    .padding(20)
  }
}

