@Component
struct TextClockTimeZoneConfig {
  @State timeZones: string[] = ['UTC', 'America/New_York', 'Europe/London', 'Asia/Tokyo'];
  @State currentDates: number[] = this.timeZones.map(() => Date.now());

  aboutToAppear() {
    setInterval(() => {
      this.currentDates = this.timeZones.map(() => Date.now());
    }, 1000);
  }

  build() {
    Column({ space: 20 }) {
      ForEach(this.timeZones, (timeZone: string, index: number) => {
        TextClock({
          timeZoneOffset: this.getTimeZoneOffset(timeZone),
          controller: new TextClockController()
        })
          .format('hh:mm:ss a')
          .onDateChange((value: number) => {
            console.log(`Current time in ${timeZone}: ${new Date(value).toLocaleTimeString()}`);
          })
          .fontSize(24)
          .width('80%')
      })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }

  private getTimeZoneOffset(timeZone: string): number {
    // Placeholder for actual timezone offset logic
    switch (timeZone) {
      case 'UTC':
        return 0;
      case 'America/New_York':
        return -5;
      case 'Europe/London':
        return 0;
      case 'Asia/Tokyo':
        return 9;
      default:
        return 0;
    }
  }
}

