@Entry
@Component
struct YearFormatCustomization {
  @State private selectedYear: string = '2023';
  @State private customFormat: string = 'YYYY';

  build() {
    Column() {
      Text('Year Format Customization')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      TextInput({ placeholder: 'Enter Year' })
        .width('80%')
        .height(40)
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.selectedYear = value;
        });

      TextInput({ placeholder: 'Enter Custom Format (e.g., YYYY)' })
        .width('80%')
        .height(40)
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.customFormat = value;
        });

      Text(`Formatted Year: ${this.formatYear(this.selectedYear, this.customFormat)}`)
        .fontSize(18)
        .margin({ top: 20 });

    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }

  private formatYear(year: string, format: string): string {
    if (format === 'YYYY') {
      return year;
    } else if (format === 'YY') {
      return year.slice(-2);
    } else if (format === 'YYYY-MM-DD') {
      return `${year}-01-01`;
    } else {
      return year;
    }
  }
}

@Entry
@Component
struct ClickHandlerWithTimeout {
  @State message: string = 'Click the button';
  @State isProcessing: boolean = false;

  handleClickWithTimeout() {
    if (this.isProcessing) return;

    this.isProcessing = true;
    this.message = 'Button clicked, waiting for timeout...';

    setTimeout(() => {
      this.message = 'Timeout completed!';
      this.isProcessing = false;
    }, 3000); // 3 seconds timeout
  }

  build() {
    Column() {
      Text(this.message)
        .fontSize(20)
        .margin(20)
      Button('Click Me')
        .onClick(() => {
          this.handleClickWithTimeout();
        })
        .width(150)
        .height(50)
        .margin(10)
        .enabled(!this.isProcessing)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

