struct BirthYearApp {
  @State age: string = '';
  @State birthYear: number = 0;
  @State showResult: boolean = false;

  build() {
    Column() {
      Text('Calculate Birth Year')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      Column() {
        Text('Age:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your age' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.age = value;
          });
      }

      Button('Calculate')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.age) {
            const currentYear = new Date().getFullYear();
            this.birthYear = currentYear - parseInt(this.age);
            this.showResult = true;
          } else {
            promptAction.showToast({
              message: 'Please enter your age'
            });
          }
        });

      if (this.showResult) {
        Text(`You were born in ${this.birthYear}`)
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 });
      }
    }
