@Entry
@Component
struct CustomTextModifications {
  @State text: string = "Sample Text";
  @State fontWeight: FontWeight = FontWeight.Normal;
  @State fontStyle: FontStyle = FontStyle.Normal;
  @State textDecoration: TextDecorationType = TextDecorationType.None;
  @State fontColor: ResourceColor = Color.Black;
  @State fontSize: number = 16;

  build() {
    Column({ space: 10 }) {
      Text(this.text)
        .fontSize(this.fontSize)
        .fontWeight(this.fontWeight)
        .fontStyle(this.fontStyle)
        .decoration({
          type: this.textDecoration
        })
        .fontColor(this.fontColor)
        .margin({ bottom: 20 });

      Button("Toggle Bold")
        .onClick(() => {
          this.fontWeight = this.fontWeight === FontWeight.Normal ? FontWeight.Bolder : FontWeight.Normal;
        })
        .margin({ bottom: 10 });

      Button("Toggle Italic")
        .onClick(() => {
          this.fontStyle = this.fontStyle === FontStyle.Normal ? FontStyle.Italic : FontStyle.Normal;
        })
        .margin({ bottom: 10 });

      Button("Toggle Underline")
        .onClick(() => {
          this.textDecoration = this.textDecoration === TextDecorationType.None ? TextDecorationType.Underline : TextDecorationType.None;
        })
        .margin({ bottom: 10 });

      Button("Change Color")
        .onClick(() => {
          if (this.fontColor === Color.Black) {
            this.fontColor = Color.Red;
          } else if (this.fontColor === Color.Red) {
            this.fontColor = Color.Blue;
          } else {
            this.fontColor = Color.Black;
          }
        })
        .margin({ bottom: 10 });

      Button("Increase Font Size")
        .onClick(() => {
          this.fontSize += 2;
        })
        .margin({ bottom: 10 });

      Button("Decrease Font Size")
        .onClick(() => {
          this.fontSize = Math.max(10, this.fontSize - 2);
        })
        .margin({ bottom: 10 });
    }
    .width('100%')
    .padding(20)
  }
}

