@Entry
@Component
struct CaptionedImageCarousel {
  private swiperController: SwiperController = new SwiperController();

  private carouselItems: Array<CarouselItem> = [
    {
      id: 1,
      image: $r('app.media.app_icon'),
      caption: 'Mountain View',
      description: 'A breathtaking view of a mountain range during sunset.'
    },
    {
      id: 2,
      image: $r('app.media.app_icon'),
      caption: 'Ocean Sunset',
      description: 'Waves crashing against the shore on a sunny day.'
    },
    {
      id: 3,
      image: $r('app.media.app_icon'),
      caption: 'Forest Path',
      description: 'A serene path winding through a lush green forest.'
    },
    {
      id: 4,
      image: $r('app.media.app_icon'),
      caption: 'Desert Dunes',
      description: 'Golden sand dunes under a clear blue sky.'
    }
  ];

  @State currentIndex: number = 0;
  @State selectedItem: CarouselItem | null = null;
  dialogController: CustomDialogController = new CustomDialogController({
    builder: this.DialogBuilder,
    customStyle: true,
    alignment: DialogAlignment.Center
  });

  @Builder DialogBuilder() {
    if (this.selectedItem) {
      Column() {
        Image(this.selectedItem.image)
          .width('100%')
          .height(200)
          .borderRadius(8)
          .objectFit(ImageFit.Cover);

        Text(this.selectedItem.caption)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 16, bottom: 8 });

        Text(this.selectedItem.description)
          .fontSize(16)
          .lineHeight(24);

        Button('Close')
          .width('100%')
          .height(40)
          .margin({ top: 24 })
          .onClick(() => {
            this.dialogController.close();
          });
      }
      .padding(24)
      .width('90%')
      .backgroundColor(Color.White)
      .borderRadius(16);
    }
  }

  build() {
    Column() {
      Text('Image Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Column() {
        Swiper(this.swiperController) {
          ForEach(this.carouselItems, (item: CarouselItem) => {
            Stack() {
              Image(item.image)
                .width('100%')
                .height(300)
                .objectFit(ImageFit.Cover)
                .borderRadius(16)
                .onClick(() => {
                  this.selectedItem = item;
                  this.dialogController.open();
                });
            }
          });
        }
        .width('100%')
        .height(300)
        .margin({ bottom: 16 })
        .autoPlay(true)
        .interval(3000)
        .indicator(true)
        .loop(true)
        .duration(500)
        .onChange((index: number) => {
          this.currentIndex = index;
        });

        Text(this.carouselItems[this.currentIndex].caption)
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 8 })
          .textAlign(TextAlign.Center);
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(20);

      Row() {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });

        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

