@Component
struct MultiItemSelectorApp {
  private items: Array<Item> = [
    { id: 1, title: 'Item A' },
    { id: 2, title: 'Item B' },
    { id: 3, title: 'Item C' },
    { id: 4, title: 'Item D' }
  ];

  @State selectedItems: Array<Item> = [];

  build() {
    Column() {
      Text('Select Multiple Items')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      List() {
        ForEach(this.items, (item: Item) => {
          ListItem() {
            Row() {
              Image($r('app.media.app_icon'))
                .width(30)
                .height(30)
                .margin({ right: 10 });
              Text(item.title)
                .fontSize(18)
                .padding(10)
                .onClick(() => {
                  if (this.selectedItems.some(selectedItem => selectedItem.id === item.id)) {
                    this.selectedItems = this.selectedItems.filter(selectedItem => selectedItem.id !== item.id);
                  } else {
                    this.selectedItems = [...this.selectedItems, item];
                  }
                });
            }
            .backgroundColor(this.selectedItems.some(selectedItem => selectedItem.id === item.id) ? '#d3d3d3' : '#f0f0f0')
            .borderRadius(5)
            .padding(10)
            .margin({ bottom: 10 });
          }
        }, (item: Item) => item.id.toString());
      }
      .width('100%');

      if (this.selectedItems.length > 0) {
        Text('Selected Items:')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 20 });

        ForEach(this.selectedItems, (selectedItem: Item) => {
          Text(selectedItem.title)
            .fontSize(18)
            .margin({ top: 10 });
        }, (selectedItem: Item) => selectedItem.id.toString());
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

