@Entry
@Component
struct CustomRefreshList {
  @State refreshing: boolean = false
  @State listData: string[] = ['Item 1', 'Item 2', 'Item 3']
  @State headerText: string = 'Pull to Refresh'

  @Builder
  CustomListItem(item: string) {
    Row() {
      Image($r('app.media.app_icon'))
        .width(40)
        .height(40)
        .margin(10)
      Column() {
        Text(item)
          .fontSize(18)
          .fontColor('#333333')
        Text('Description for ' + item)
          .fontSize(12)
          .fontColor('#666666')
      }
      .margin({ left: 10 })
    }
    .width('100%')
    .padding(10)
    .backgroundColor('#ffffff')
    .borderRadius(8)
    .margin({ top: 5, bottom: 5 })
  }

  build() {
    Column() {
      Text(this.headerText)
        .fontSize(18)
        .fontColor('#000000')
        .padding(16)
        .backgroundColor('#f0f0f0')
        .width('100%')
        .textAlign(TextAlign.Center)

      Refresh({
        refreshing: this.refreshing,
        offset: 120,
        friction: 100
      }) {
        List() {
          ForEach(this.listData, (item: string) => {
            ListItem() {
              this.CustomListItem(item)
            }
          }, (item: string) => item)
        }
        .width('100%')
      }
      .onRefreshing(() => {
        this.headerText = 'Refreshing...'
        setTimeout(() => {
          this.listData = ['New Item 1', 'New Item 2', 'New Item 3', 'New Item 4']
          this.refreshing = false
          this.headerText = 'Pull to Refresh'
        }, 2000)
      })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }
}

