    { name: 'Canada', flag: 'app.media.ca_flag' },
    { name: 'Mexico', flag: 'app.media.mx_flag' },
    { name: 'Germany', flag: 'app.media.de_flag' },
    { name: 'France', flag: 'app.media.fr_flag' },
    { name: 'Japan', flag: 'app.media.jp_flag' },
    { name: 'Australia', flag: 'app.media.au_flag' }
  ];

  @State selectedCountry: Country | null = null;
  dialogController: CustomDialogController = new CustomDialogController({
    builder: this.DialogBuilder,
    customStyle: true,
    alignment: DialogAlignment.Center
  });

  @Builder DialogBuilder() {
    if (this.selectedCountry) {
      Column() {
        Text(this.selectedCountry.name)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 16, bottom: 16 });

        Button('Close')
          .onClick(() => {
            this.dialogController.close();
          });
      }
      .padding(24)
      .backgroundColor(Color.White)
      .borderRadius(16);
    }
  }

  build() {
    Column() {
      Text('Country Flags')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      List() {
        ForEach(this.countries, (country: Country) => {
          ListItem() {
            Row() {
              Image(country.flag)
                .width(50)
                .height(30)
                .objectFit(ImageFit.Cover)
                .margin({ right: 10 });
              Text(country.name)
                .fontSize(20)
                .fontWeight(FontWeight.Medium);
            }
            .padding(10)
            .onClick(() => {
              this.selectedCountry = country;
              this.dialogController.open();
            });
          }
          .backgroundColor('#FFFFFF')
          .borderRadius(5)
          .margin({ bottom: 10 });
        });
      }
      .width('100%')
      .layoutWeight(1)
      .padding(16);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5');
  }
}

