@Entry
@Component
struct TextInputAlertApp {
  @State inputText: string = '';
  @State showDialog: boolean = false;

  build() {
    Column() {
      // Text Input Field
      TextInput({ placeholder: 'Enter your text here' })
        .width('100%')
        .height(50)
        .margin({ top: 20, bottom: 20 })
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .onChange((value: string) => {
          this.inputText = value;
        });

      // Button to Show Alert
      Button('Show Alert')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.inputText) {
            this.showDialog = true;
          } else {
            promptAction.showToast({
              message: 'Please enter some text'
            });
          }
        });

      // Alert Dialog
      if (this.showDialog) {
        Column() {
          Text('Your Input')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(this.inputText)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.showDialog = false;
              this.inputText = '';
            });
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

