@Entry
@Component
struct LoginForm {
  @State username: string = ''
  @State password: string = ''
  @State loginMessage: string = ''

  validateInput(): boolean {
    if (this.username.trim() && this.password.trim()) {
      this.loginMessage = 'Login successful!'
      return true
    } else {
      this.loginMessage = 'Please enter both username and password.'
      return false
    }
  }

  build() {
    Column() {
      // Title
      Text('Login')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 30 })

      // Username Input
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })
        .alignSelf(ItemAlign.Start)
        .width('80%')

      TextInput({ placeholder: 'Enter username' })
        .width('80%')
        .height(40)
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.username = value
        })

      // Password Input
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })
        .alignSelf(ItemAlign.Start)
        .width('80%')

      TextInput({ placeholder: 'Enter password' })
        .type(InputType.Password)
        .width('80%')
        .height(40)
        .margin({ bottom: 30 })
        .onChange((value: string) => {
          this.password = value
        })

      // Login Button
      Button('Login', { type: ButtonType.Capsule })
        .width('80%')
        .height(40)
        .backgroundColor('#007DFF')
        .fontColor(Color.White)
        .onClick(() => {
          this.validateInput()
        })

      // Status Message
      if (this.loginMessage) {
        Text(this.loginMessage)
          .fontSize(16)
          .margin({ top: 20 })
          .fontColor(this.loginMessage === 'Login successful!' ? Color.Green : Color.Red)
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .padding(20)
  }
}

