    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

@Entry
@Component
struct AnimatedGestureResponse {
  @State private offsetX: number = 0;
  @State private offsetY: number = 0;
  @State private scaleValue: number = 1;
  @State private rotationAngle: number = 0;
  @State private buttonScale: number = 1;
  @State private buttonColor: Color = Color.Blue;

  build() {
    Column({ space: 20 }) {
      Text('Perform gestures on the image to see animated responses')
        .fontSize(20)
        .fontColor(Color.Black)
        .margin({ bottom: 20 });

      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .gesture(
          GestureGroup(
            GestureMode.Parallel,
            PanGesture({ direction: PanDirection.All })
              .onActionUpdate((event: GestureEvent) => {
                this.offsetX = event.offsetX;
                this.offsetY = event.offsetY;
              }),
            PinchGesture()
              .onActionUpdate((event: PinchGestureEvent) => {
                this.scaleValue = event.scale;
              }),
            RotationGesture()
              .onActionUpdate((event: RotationGestureEvent) => {
                this.rotationAngle = event.angle;
              })
          )
        )
        .transform({
          translate: { x: this.offsetX, y: this.offsetY },
          scale: { x: this.scaleValue, y: this.scaleValue },
          rotate: { angle: this.rotationAngle }
        })
        .animation({ duration: 300, curve: Curve.EaseInOut });

      Button('Reset Animation')
        .width(200)
        .height(50)
        .backgroundColor(this.buttonColor)
        .scale({ x: this.buttonScale, y: this.buttonScale })
        .onClick(() => {
          animateTo({
            duration: 200,
            curve: Curve.EaseInOut
          }, () => {
            this.buttonScale = 0.9;
            this.buttonColor = Color.Green;
          });

          setTimeout(() => {
            animateTo({
              duration: 200,
              curve: Curve.EaseInOut
            }, () => {
              this.buttonScale = 1;
              this.buttonColor = Color.Blue;
              this.offsetX = 0;
              this.offsetY = 0;
              this.scaleValue = 1;
              this.rotationAngle = 0;
            });
          }, 200);
        })
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor(Color.White);
  }
}

