import { AnimatorOptions } from '@ohos.animator';
import router from '@ohos.router';
import promptAction from '@ohos.promptAction';
import hilog from '@ohos.hilog';
import { UIContext } from '@kit.ArkUI';

@Entry
@Component
struct ReleaseCommandPostAnimation {
  private enterAnimatorParam: AnimatorOptions = {
    duration: 600,
    easing: 'friction',
    delay: 0,
    fill: 'forwards',
    direction: 'normal',
    iterations: 1,
    begin: 0.0,
    end: 1.0
  };

  private exitAnimatorParam: AnimatorOptions = {
    duration: 600,
    easing: 'friction',
    delay: 0,
    fill: 'forwards',
    direction: 'normal',
    iterations: 1,
    begin: 1.0,
    end: 0.0
  };

  @State myScale: number = 1.0;
  @State rotationAngle: number = 0;
  uiContext: UIContext | undefined = undefined;

  aboutToAppear() {
    this.uiContext = this.getUIContext?.();
    hilog.info(0x0000, 'ReleaseCommand', '%{public}s', 'Release command setup complete');
  }

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(100)
        .scale({ x: this.myScale, y: this.myScale })
        .rotate({ x: 0, y: 0, z: 1, angle: this.rotationAngle })
        .onClick(() => {
          if (!this.uiContext) {
            console.info("no uiContext, keyframe failed");
            return;
          }
          this.myScale = 1;
          this.rotationAngle = 0;
          this.uiContext.keyframeAnimateTo({ iterations: 1 }, [
            {
              duration: 800,
              event: () => {
                this.myScale = 1.5;
                this.rotationAngle = 90;
              }
            },
            {
              duration: 500,
              event: () => {
                this.myScale = 1;
                this.rotationAngle = 0;
                this.executeReleaseCommand();
              }
            }
          ]);
        });

      Button('Trigger Release Command')
        .fontColor(Color.Black)
        .backgroundColor('#cccccc')
        .width('100%')
        .margin({ top: 40 })
        .onClick(() => {
          this.executeReleaseCommand();
        });

      Text('Release Command Post-Animation')
        .fontSize(20)
        .alignSelf(ItemAlign.Center)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center);
  }

  private executeReleaseCommand() {
    hilog.info(0x0000, 'ReleaseCommand', '%{public}s', 'Release command executed');
    promptAction.showToast({ message: 'Release command executed successfully' });
    router.back();
  }
}

