@Entry
@Component
struct QuizApp {
  @State currentQuestionIndex: number = 0;
  @State selectedOption: number = -1;
  @State showFeedback: boolean = false;
  @State score: number = 0;
  @State showScore: boolean = false;

  private questions: Array<Question> = [
    new Question(
      'What is the capital of France?',
      ['London', 'Berlin', 'Paris', 'Madrid'],
      2
    ),
    new Question(
      'Which planet is closest to the Sun?',
      ['Mars', 'Venus', 'Mercury', 'Jupiter'],
      2
    ),
    new Question(
      'What is the largest mammal?',
      ['African Elephant', 'Blue Whale', 'Giraffe', 'Hippopotamus'],
      1
    )
  ];

  checkAnswer() {
    if (this.selectedOption === -1) return;

    const correct = this.selectedOption === this.questions[this.currentQuestionIndex].correctAnswer;
    if (correct) {
      this.score++;
    }
    this.showFeedback = true;

    setTimeout(() => {
      this.showFeedback = false;
      this.selectedOption = -1;
      if (this.currentQuestionIndex < this.questions.length - 1) {
        this.currentQuestionIndex++;
      } else {
        this.showScore = true;
      }
    }, 1500);
  }

  build() {
    Column() {
      if (!this.showScore) {
        Text(`Question ${this.currentQuestionIndex + 1}/${this.questions.length}`)
          .fontSize(18)
          .margin({ bottom: 10 });

        Text(this.questions[this.currentQuestionIndex].question)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .textAlign(TextAlign.Center)
          .margin({ bottom: 30 })
          .padding({ left: 20, right: 20 });

        ForEach(this.questions[this.currentQuestionIndex].options, (option: string, index: number) => {
          Row() {
            Radio({ value: index.toString(), group: 'quizOptions' })
              .checked(this.selectedOption === index)
              .onChange((isChecked: boolean) => {
                if (isChecked) {
                  this.selectedOption = index;
                }
              });
            Text(option)
              .fontSize(18)
              .margin({ left: 10 });
          }
          .width('80%')
          .margin({ bottom: 10 })
          .onClick(() => {
            this.selectedOption = index;
          });
        });

        Button('Submit Answer')
          .width('60%')
          .height(50)
          .margin({ top: 20 })
          .enabled(this.selectedOption !== -1 && !this.showFeedback)
          .onClick(() => {
            this.checkAnswer();
          });

        if (this.showFeedback) {
          Column() {
            Text(this.selectedOption === this.questions[this.currentQuestionIndex].correctAnswer ? 'Correct!' : 'Incorrect!')
              .fontSize(20)
              .fontColor(this.selectedOption === this.questions[this.currentQuestionIndex].correctAnswer ? '#4CAF50' : '#F44336')
              .margin({ bottom: 10 });

            Text('Correct answer: ' + this.questions[this.currentQuestionIndex].options[this.questions[this.currentQuestionIndex].correctAnswer])
              .fontSize(16);
          }
          .margin({ top: 20 });
        }
      } else {
        Column() {
          Text('Quiz Complete!')
            .fontSize(28)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Your Score: ${this.score}/${this.questions.length}`)
            .fontSize(24)
            .margin({ bottom: 40 });

          Button('Restart Quiz')
            .onClick(() => {
              this.currentQuestionIndex = 0;
              this.score = 0;
              this.showScore = false;
              this.selectedOption = -1;
            });
        }
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center);
  }
}

class Question {
  question: string;
  options: string[];
  correctAnswer: number;

  constructor(question: string, options: string[], correctAnswer: number) {
    this.question = question;
    this.options = options;
    this.correctAnswer = correctAnswer;
  }
}

