@Entry
@Component
struct StyledStringGestureConfig {
  @State private isTapped: boolean = false;
  @State private gestureText: string = "Tap or Swipe Me!";
  @State private swipeDirection: string = "";

  build() {
    Column() {
      Text() {
        Span(this.gestureText)
          .fontSize(24)
          .fontColor(this.isTapped ? Color.Red : Color.Blue)
          .fontWeight(FontWeight.Bold)
          .fontStyle(FontStyle.Italic)
      }
      .gesture(
        TapGesture()
          .onAction(() => {
            this.isTapped = !this.isTapped;
          })
      )
      .gesture(
        SwipeGesture({ direction: SwipeDirection.Horizontal })
          .onAction((event: GestureEvent) => {
            if (event.offsetX < 0) {
              this.swipeDirection = "Left";
            } else if (event.offsetX > 0) {
              this.swipeDirection = "Right";
            }
            this.gestureText = `Swiped ${this.swipeDirection}`;
          })
      )
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

