@Component
struct RecipeSearchApp {
  @State recipes: string[] = [
    'Pasta with Tomato Sauce',
    'Vegetable Stir Fry',
    'Chicken Curry',
    'Beef Stew',
    'Vegetable Soup',
    'Grilled Salmon',
    'Vegetable Lasagna',
    'Chicken Alfredo',
    'Beef Tacos',
    'Vegetable Pizza'
  ];

  @State ingredients: string[] = [
    'Tomato',
    'Onion',
    'Garlic',
    'Chicken',
    'Beef',
    'Vegetables',
    'Pasta',
    'Rice',
    'Cheese',
    'Salmon'
  ];

  @State searchText: string = '';

  filteredRecipes(): string[] {
    if (this.searchText.trim() === '') {
      return this.recipes;
    } else {
      return this.recipes.filter(recipe =>
        recipe.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  build() {
    Column() {
      // Search Bar
      TextInput({
        placeholder: 'Enter ingredients...',
        text: this.searchText
      })
        .width('100%')
        .onChange((value: string) => {
          this.searchText = value;
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      // List of Recipes
      if (this.filteredRecipes().length > 0) {
        List() {
          ForEach(this.filteredRecipes(), (recipe: string) => {
            ListItem() {
              Row() {
                Image($r('app.media.app_icon'))
                  .width(50)
                  .height(50)
                  .objectFit(ImageFit.Cover)
                  .margin({ right: 10 });
                Text(recipe)
                  .fontSize(18)
                  .padding(12);
              }
            }
          }, (recipe: string) => recipe);
        }
      } else {
        // Display a message when no recipes match the search
        Text('No recipes found')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

@Entry
@Component
struct FrameAnimationApp {
  @State currentFrame: number = 0;
  @State isPlaying: boolean = false;
  private frames: Resource[] = [
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon')
  ];
  private timerId: number | null = null;

  playAnimation() {
    if (this.isPlaying) return;
    this.isPlaying = true;
    this.timerId = setInterval(() => {
      this.currentFrame = (this.currentFrame + 1) % this.frames.length;
    }, 200);
  }

  stopAnimation() {
    if (!this.isPlaying || !this.timerId) return;
    clearInterval(this.timerId);
    this.timerId = null;
    this.isPlaying = false;
  }

  resetAnimation() {
    this.stopAnimation();
    this.currentFrame = 0;
  }

  build() {
    Column() {
      Image(this.frames[this.currentFrame])
        .width(200)
        .height(200)
        .margin({ top: 20 });

      Row() {
        Button('Play')
          .onClick(() => this.playAnimation())
          .margin(8);

        Button('Stop')
          .onClick(() => this.stopAnimation())
          .margin(8);

        Button('Reset')
          .onClick(() => this.resetAnimation())
          .margin(8);
      }
      .justifyContent(FlexAlign.Center)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

