@Entry
@Component
struct CustomUnderlineTextInput {
  @State text: string = '';
  @State underlineColor: Color = Color.Blue;
  @State inputState: string = 'normal';

  build() {
    Column() {
      TextInput({ placeholder: 'Enter text here', text: this.text })
        .width('90%')
        .height(50)
        .margin(20)
        .border({
          width: 1,
          color: this.getUnderlineColor()
        })
        .onChange((value: string) => {
          this.text = value;
          this.inputState = value.length > 0 ? 'typing' : 'normal';
        })

      Button('Change Underline Color')
        .onClick(() => {
          this.underlineColor = this.underlineColor === Color.Blue ? Color.Pink : Color.Blue;
        })
        .width('90%')
        .height(50)
        .margin(20)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }

  private getUnderlineColor(): Color {
    switch (this.inputState) {
      case 'normal':
        return this.underlineColor;
      case 'typing':
        return Color.Green;
      case 'error':
        return Color.Red;
      case 'disabled':
        return Color.Gray;
      default:
        return this.underlineColor;
    }
  }
}

