      .onScroll((scrollOffset: number) => {
        this.currentIndex = Math.floor(scrollOffset / 200)
      })
    }
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct TodoList {
  @State tasks: Array<Task> = []
  @State newTask: string = ''

  build() {
    Column() {
      TextInput({ placeholder: 'Enter a new task' })
        .onChange((value: string) => {
          this.newTask = value
        })
        .margin({ bottom: 20 })

      Button('Add Task')
        .onClick(() => {
          if (this.newTask) {
            this.tasks.push({ id: Date.now(), content: this.newTask, isCompleted: false })
            this.newTask = ''
          }
        })
        .margin({ bottom: 20 })

      ForEach(this.tasks, (task: Task, index: number) => {
        Row() {
          Checkbox()
            .select(task.isCompleted)
            .onChange((value: boolean) => {
              this.tasks[index].isCompleted = value
            })
          Text(task.content)
            .fontSize(20)
            .margin({ left: 10 })
            .decoration({ type: task.isCompleted ? TextDecorationType.LineThrough : TextDecorationType.None })
        }
        .margin({ top: 10 })
      })
    }
    .padding(20)
  }
}

interface Task {
  id: number
  content: string
  isCompleted: boolean
}

@Entry
@Component
struct RegistrationForm {
  @State name: string = ''
  @State email: string = ''
  @State password: string = ''
  @State successMessage: string = ''
  @State errorMessage: string = ''

  validateForm(): boolean {
    if (!this.name || !this.email || !this.password) {
      this.errorMessage = 'All fields are required'
      return false
    }
    this.errorMessage = ''
    return true
  }

  build() {
    Column() {
      Text('Registration')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your name' })
        .onChange((value: string) => {
          this.name = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your email' })
        .onChange((value: string) => {
          this.email = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .margin({ bottom: 20 })

      Button('Submit')
        .onClick(() => {
          if (this.validateForm()) {
            this.successMessage = 'Registration successful!'
            this.name = ''
            this.email = ''
            this.password = ''
          }
        })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ bottom: 20 })
      }

      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(18)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

