@Entry
@Component
struct PasswordRulesConfigurator {
  @State password: string = ''
  @State passwordState: boolean = false
  @State errorMessage: string = ''
  @State passwordRules: string[] = [
    'At least 8 characters',
    'At least one uppercase letter',
    'At least one lowercase letter',
    'At least one number',
    'At least one special character'
  ]
  controller: TextInputController = new TextInputController()

  validatePassword(password: string): boolean {
    const minLength = 8
    const hasUpperCase = /[A-Z]/.test(password)
    const hasLowerCase = /[a-z]/.test(password)
    const hasNumber = /[0-9]/.test(password)
    const hasSpecialChar = /[!@#$%^&*(),.?":{}|<>]/.test(password)

    if (password.length < minLength) {
      this.errorMessage = 'Password must be at least 8 characters long.'
      return false
    }
    if (!hasUpperCase) {
      this.errorMessage = 'Password must contain at least one uppercase letter.'
      return false
    }
    if (!hasLowerCase) {
      this.errorMessage = 'Password must contain at least one lowercase letter.'
      return false
    }
    if (!hasNumber) {
      this.errorMessage = 'Password must contain at least one number.'
      return false
    }
    if (!hasSpecialChar) {
      this.errorMessage = 'Password must contain at least one special character.'
      return false
    }
    this.errorMessage = ''
    return true
  }

  generatePassword(): string {
    const length = 12
    const charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()'
    let password = ''
    for (let i = 0; i < length; i++) {
      password += charset.charAt(Math.floor(Math.random() * charset.length))
    }
    return password
  }

  updatePasswordRules(password: string) {
    const rules = [
      password.length >= 8,
      /[A-Z]/.test(password),
      /[a-z]/.test(password),
      /[0-9]/.test(password),
      /[!@#$%^&*(),.?":{}|<>]/.test(password)
    ]

    this.passwordRules = [
      rules[0] ? '✓ At least 8 characters' : '✗ At least 8 characters',
      rules[1] ? '✓ At least one uppercase letter' : '✗ At least one uppercase letter',
      rules[2] ? '✓ At least one lowercase letter' : '✗ At least one lowercase letter',
      rules[3] ? '✓ At least one number' : '✗ At least one number',
      rules[4] ? '✓ At least one special character' : '✗ At least one special character'
    ]
  }

  build() {
    Column({ space: 20 }) {
      TextInput({ placeholder: 'Enter your password...', controller: this.controller })
        .width('95%')
        .height(40)
        .margin(20)
        .type(InputType.Password)
        .maxLength(20)
        .showPasswordIcon(true)
        .showPassword(this.passwordState)
        .onChange((value: string) => {
          this.password = value
          this.validatePassword(value)
          this.updatePasswordRules(value)
        })
        .onSecurityStateChange((isShowPassword: boolean) => {
          this.passwordState = isShowPassword
        })

      Text(this.errorMessage)
        .fontSize(12)
        .fontColor(Color.Red)
        .margin(10)

      Text('Password Rules:')
        .fontSize(16)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 10, bottom: 10 })

      ForEach(this.passwordRules, (rule: string) => {
        Text(rule)
          .fontSize(14)
          .margin({ bottom: 5 })
      })

      Button('Generate Password')
        .margin(15)
        .onClick(() => {
          this.password = this.generatePassword()
          this.validatePassword(this.password)
          this.updatePasswordRules(this.password)
        })

      Button('Submit')
        .margin(15)
        .onClick(() => {
          if (this.validatePassword(this.password)) {
            console.log('Password is valid and submitted.')
          } else {
            console.log('Password is invalid. Please correct it.')
          }
        })
    }
    .width('100%')
  }
}

