@Component
struct CustomizableTextDecoration {
  @State underlineActive: boolean = false;
  @State overlineActive: boolean = false;
  @State lineThroughActive: boolean = false;
  @State decorationColor: ResourceColor = Color.Blue;
  @State decorationStyle: TextDecorationStyle = TextDecorationStyle.SOLID;

  build() {
    Column({ space: 20 }) {
      Text('Customizable Text Decoration')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 30 });

      Text('Sample text with customizable decorations')
        .fontSize(18)
        .decoration({
          type: this.underlineActive ? TextDecorationType.Underline : TextDecorationType.None,
          color: this.decorationColor,
          style: this.decorationStyle
        })
        .decoration({
          type: this.overlineActive ? TextDecorationType.Overline : TextDecorationType.None,
          color: this.decorationColor,
          style: this.decorationStyle
        })
        .decoration({
          type: this.lineThroughActive ? TextDecorationType.LineThrough : TextDecorationType.None,
          color: this.decorationColor,
          style: this.decorationStyle
        })
        .padding(15)
        .backgroundColor('#f0f0f0')
        .width('90%');

      Row({ space: 10 }) {
        Button('Underline')
          .onClick(() => {
            this.underlineActive = !this.underlineActive;
          })
          .stateEffect(this.underlineActive);

        Button('Overline')
          .onClick(() => {
            this.overlineActive = !this.overlineActive;
          })
          .stateEffect(this.overlineActive);

        Button('LineThrough')
          .onClick(() => {
            this.lineThroughActive = !this.lineThroughActive;
          })
          .stateEffect(this.lineThroughActive);
      }
      .width('90%')
      .justifyContent(FlexAlign.SpaceBetween)
      .margin({ top: 20 });

      Row({ space: 10 }) {
        Button('Red')
          .onClick(() => {
            this.decorationColor = Color.Red;
          });

        Button('Blue')
          .onClick(() => {
            this.decorationColor = Color.Blue;
          });

        Button('Green')
          .onClick(() => {
            this.decorationColor = Color.Green;
          });
      }
      .width('90%')
      .justifyContent(FlexAlign.SpaceBetween)
      .margin({ top: 10 });

      Row({ space: 10 }) {
        Button('Solid')
          .onClick(() => {
            this.decorationStyle = TextDecorationStyle.SOLID;
          });

        Button('Dotted')
          .onClick(() => {
            this.decorationStyle = TextDecorationStyle.DOTTED;
          });

        Button('Dashed')
          .onClick(() => {
            this.decorationStyle = TextDecorationStyle.DASHED;
          });
      }
      .width('90%')
      .justifyContent(FlexAlign.SpaceBetween)
      .margin({ top: 10 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

