@Entry
@Component
struct LoginForm {
  @State username: string = ''
  @State password: string = ''
  @State loginMessage: string = ''
  @State isSuccess: boolean = false

  validateCredentials(): boolean {
    const validUsername = 'user123'
    const validPassword = 'securePass123'
    return this.username === validUsername && this.password === validPassword
  }

  build() {
    Column() {
      // Username Input Field
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your username', text: this.username })
        .onChange((value: string) => {
          this.username = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Password Input Field
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Login Button
      Button('Login')
        .onClick(() => {
          if (this.validateCredentials()) {
            this.loginMessage = 'Login successful!'
            this.isSuccess = true
          } else {
            this.loginMessage = 'Invalid username or password'
            this.isSuccess = false
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      // Login Message
      if (this.loginMessage) {
        Text(this.loginMessage)
          .fontSize(16)
          .margin({ top: 20 })
          .fontColor(this.isSuccess ? Color.Green : Color.Red)
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

import promptAction from '@ohos.promptAction';

@Entry
@Component
struct CustomEditMenu {
  @State inputText: string = "";
  @State isMenuVisible: boolean = false;
  @State menuOptions: string[] = ["Cut", "Copy", "Paste", "Select All"];

  build() {
    Column() {
      TextInput({ placeholder: "Type here...", text: this.inputText })
        .width("80%")
        .height(50)
        .onChange((value: string) => {
          this.inputText = value;
        })
        .onClick(() => {
          this.isMenuVisible = true;
        })
        .margin({ top: 20 });

      if (this.isMenuVisible) {
        Column() {
          ForEach(this.menuOptions, (option: string) => {
            Button(option)
              .width("100%")
              .height(40)
              .backgroundColor(Color.White)
              .borderRadius(5)
              .onClick(() => {
                this.handleMenuAction(option);
                this.isMenuVisible = false;
              });
          })
        }
        .border({ width: 1, color: Color.Gray })
        .borderRadius(5)
        .width("80%")
        .margin({ top: 10 });
      }
    }
    .width("100%")
    .height("100%")
    .padding(20)
    .backgroundColor("#f5f5f5")
    .onClick(() => {
      this.isMenuVisible = false;
    });
  }

  private handleMenuAction(action: string): void {
    switch (action) {
      case "Cut":
        promptAction.showToast({ message: "Text cut!" });
        break;
      case "Copy":
        promptAction.showToast({ message: "Text copied!" });
        break;
      case "Paste":
        promptAction.showToast({ message: "Text pasted!" });
        break;
      case "Select All":
        promptAction.showToast({ message: "All text selected!" });
        break;
    }
  }
}

