  @State offsetX: number = 0;
  @State offsetY: number = 0;
  @State initialX: number = 0;
  @State initialY: number = 0;
  @State copiedText: string = '';

  build() {
    Stack() {
      Text('Drag & Copy Me!')
        .width(150)
        .height(50)
        .fontSize(18)
        .fontStyle(FontStyle.Italic)
        .fontWeight(FontWeight.Bold)
        .fontColor('#2a58d0')
        .textAlign(TextAlign.Center)
        .backgroundColor(Color.Pink)
        .borderRadius(10)
        .position({ x: this.offsetX, y: this.offsetY })
        .onTouch((event: TouchEvent) => {
          if (event.type === TouchType.Down) {
            this.initialX = event.touches[0].x;
            this.initialY = event.touches[0].y;
          } else if (event.type === TouchType.Move) {
            this.offsetX = event.touches[0].x - this.initialX;
            this.offsetY = event.touches[0].y - this.initialY;
          }
        })
        .onClick(() => {
          this.copiedText = 'Drag & Copy Me!';
        });

      Text('Copied Text: ' + this.copiedText)
        .fontSize(16)
        .margin({ top: 100 })
        .fontColor('#000000');
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f0f0f0');
  }
}

