@Entry
@Component
struct PortraitOrientationListener {
  @State isPortrait: boolean = false;

  aboutToAppear() {
    const mediaQueryListener = mediaquery.matchMediaSync('(orientation: portrait)');
    this.isPortrait = mediaQueryListener.matches;
    mediaQueryListener.on('change', (result) => {
      this.isPortrait = result.matches;
    });
  }

  build() {
    Column() {
      Text(this.isPortrait ? 'Portrait Mode' : 'Landscape Mode')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .textAlign(TextAlign.Center)
        .margin(20);

      Image($r('app.media.app_icon'))
        .width(100)
