import mediaquery from '@ohos.mediaquery';

@Entry
@Component
struct OrientationBackground {
  @State isPortrait: boolean = true;

  aboutToAppear() {
    const portraitQuery = mediaquery.matchMediaSync('(orientation: portrait)');
    this.isPortrait = portraitQuery.matches;

    portraitQuery.on('change', (result: mediaquery.MediaQueryResult) => {
      this.isPortrait = result.matches;
    });
  }

  build() {
    Column() {
      Text(this.isPortrait ? 'Portrait Mode' : 'Landscape Mode')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .textAlign(TextAlign.Center)
        .margin(20);

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(20);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(this.isPortrait ? '#87CEEB' : '#90EE90');
  }
}

