          .onChange((value: string) => {
            this.newName = value
          })
          .margin({ bottom: 10 })

        TextInput({ placeholder: 'Enter new bio' })
          .onChange((value: string) => {
            this.newBio = value
          })
          .margin({ bottom: 10 })

        Button('Save')
          .onClick(() => {
            if (this.newName) {
              this.userName = this.newName
            }
            if (this.newBio) {
              this.userBio = this.newBio
            }
            this.isEditing = false
          })
      } else {
        Text(this.userName)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
