    { id: 1, title: 'Mountain View', image: $r('app.media.app_icon') },
    { id: 2, title: 'Ocean Waves', image: $r('app.media.app_icon') },
    { id: 3, title: 'Forest Trail', image: $r('app.media.app_icon') },
    { id: 4, title: 'Desert Dunes', image: $r('app.media.app_icon') }
  ];

  build() {
    Column() {
      if (this.showFullScreen) {
        Stack() {
          Image(this.selectedImage)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%');

          Button('Back')
            .onClick(() => {
              this.showFullScreen = false;
            })
            .position({ x: 20, y: 20 })
            .backgroundColor('#FFFFFF')
            .padding({ left: 10, right: 10, top: 5, bottom: 5 })
            .borderRadius(5);
        }
      } else {
        Grid() {
          ForEach(this.images, (item: ImageItem) => {
            GridItem() {
              Column() {
                Image(item.image)
                  .width('100%')
                  .aspectRatio(1)
                  .objectFit(ImageFit.Cover)
