    Column() {
      Toggle({ type: ToggleType.Switch, isOn: this.isOn })
        .onChange((isOn: boolean) => {
          this.isOn = isOn;
          this.feedbackMessage = isOn ? 'Switch is ON' : 'Switch is OFF';
        })
        .selectedColor('#007DFF')
        .switchStyle({
          pointRadius: 15,
          trackBorderRadius: 10,
          pointColor: '#D2B48C',
          unselectedColor: Color.Pink
        })

      Text(this.feedbackMessage)
        .fontSize(20)
        .margin(10)
        .fontColor(this.isOn ? '#007DFF' : '#FF0000')
    }
    .width('100%')
    .padding(24)
  }
}

