@Entry
@Component
struct SearchApp {
  @State items: Array<Item> = [
    { id: 1, title: 'Apple', description: 'A sweet and crunchy fruit.' },
    { id: 2, title: 'Banana', description: 'A tropical fruit with a soft texture.' },
    { id: 3, title: 'Orange', description: 'A citrus fruit rich in vitamin C.' },
    { id: 4, title: 'Grapes', description: 'Small, sweet fruits often used in winemaking.' },
    { id: 5, title: 'Mango', description: 'A juicy fruit with a unique flavor.' },
    { id: 6, title: 'Pineapple', description: 'A tropical fruit with a spiky exterior.' },
    { id: 7, title: 'Strawberry', description: 'A red, juicy fruit with a sweet taste.' },
    { id: 8, title: 'Watermelon', description: 'A large, refreshing fruit with high water content.' },
    { id: 9, title: 'Cherry', description: 'A small, sweet fruit with a pit.' },
    { id: 10, title: 'Blueberry', description: 'A small, blue fruit rich in antioxidants.' }
  ];

  @State searchText: string = '';
  @State selectedItem: Item | null = null;
  dialogController: CustomDialogController = new CustomDialogController({
    builder: this.DialogBuilder,
    customStyle: true,
    alignment: DialogAlignment.Center
  });

  filteredItems(): Array<Item> {
    if (this.searchText.trim() === '') {
      return this.items;
    } else {
      return this.items.filter(item =>
        item.title.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  @Builder DialogBuilder() {
    if (this.selectedItem) {
      Column() {
        Text(this.selectedItem.title)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 16, bottom: 8 });

        Text(this.selectedItem.description)
          .fontSize(16)
          .lineHeight(24);

        Button('Close')
          .onClick(() => {
            this.dialogController.close();
          })
          .margin({ top: 16 });
      }
      .padding(24)
      .width('90%')
      .backgroundColor(Color.White)
      .borderRadius(16);
    }
  }

  build() {
    Column() {
      TextInput({
        placeholder: 'Search items...',
        text: this.searchText
      })
        .width('100%')
        .onChange((value: string) => {
          this.searchText = value;
        })
        .margin(16)
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      if (this.filteredItems().length > 0) {
        List() {
          ForEach(this.filteredItems(), (item: Item) => {
            ListItem() {
              Text(item.title)
                .fontSize(18)
                .padding(12);
            }
            .onClick(() => {
              this.selectedItem = item;
              this.dialogController.open();
            });
          }, (item: Item) => item.id.toString());
        }
      } else {
        Text('No items found')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

interface Item {
  id: number;
  title: string;
  description: string;
}

@Entry
@Component
struct ModularStyles {
  // Define style configurations
  private readonly STYLE_A: StyleConfig = {
    backgroundColor: Color.White,
    textColor: Color.Black,
    buttonColor: Color.Red,
    fontSize: 18,
    padding: 16
  };

  private readonly STYLE_B: StyleConfig = {
    backgroundColor: Color.Gray,
    textColor: Color.Blue,
    buttonColor: Color.Green,
    fontSize: 20,
    padding: 20
  };

  @State currentStyle: StyleConfig = this.STYLE_A;

  build() {
    Column() {
      // Style toggle button
      Button("Toggle Style")
        .fontSize(this.currentStyle.fontSize)
        .fontColor(Color.White)
        .backgroundColor(this.currentStyle.buttonColor)
        .padding(this.currentStyle.padding)
        .borderRadius(5)
        .onClick(() => {
          this.currentStyle = this.currentStyle === this.STYLE_A ? this.STYLE_B : this.STYLE_A;
        });

      // Modular component with current style
      this.ModularComponent("Sample Text", this.currentStyle)
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.currentStyle.backgroundColor)
    .padding(this.currentStyle.padding);
  }

  @Builder
  ModularComponent(text: string, style: StyleConfig) {
    Column() {
      Text(text)
        .fontSize(style.fontSize)
        .fontColor(style.textColor)
        .padding(style.padding);

      Button("Action")
        .fontSize(style.fontSize)
        .fontColor(Color.White)
        .backgroundColor(style.buttonColor)
        .padding(style.padding)
        .borderRadius(5)
        .onClick(() => {
          console.info("Button clicked!");
        });

      Image($r('app.media.app_icon'))
        .width(50)
        .height(50)
        .margin({ top: 20 });
    }
    .width('100%')
    .alignItems(HorizontalAlign.Center);
  }
}

interface StyleConfig {
  backgroundColor: ResourceColor;
  textColor: ResourceColor;
  buttonColor: ResourceColor;
  fontSize: number;
  padding: number;
}

