import mediaquery from '@ohos.mediaquery';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct MediaConditionFallback {
  @State private mediaMatch: boolean = false;
  @State private errorMessage: string = '';
  private mediaQueryListener: mediaquery.MediaQueryListener | null = null;

  aboutToAppear() {
    try {
      this.mediaQueryListener = mediaquery.matchMediaSync('(min-width: 600px)');
      this.mediaQueryListener.on('change', (result: mediaquery.MediaQueryResult) => {
        this.mediaMatch = result.matches;
        this.errorMessage = '';
      });
    } catch (error) {
      this.errorMessage = `Media query setup failed: ${error.message}`;
      promptAction.showToast({
        message: this.errorMessage,
        duration: 3000
      });
    }
  }

  onPageHide() {
    if (this.mediaQueryListener) {
      this.mediaQueryListener.off('change');
    }
  }

  build() {
    Column() {
      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(16)
          .fontColor(Color.Red)
          .margin(10);

        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
          .margin(10);

        Button('Retry Setup')
          .onClick(() => {
            this.aboutToAppear();
          });
      } else if (this.mediaMatch) {
        Text('Media conditions match')
          .fontSize(20)
          .margin(10);

        Image($r('app.media.app_icon'))
          .width(200)
          .height(200);
      } else {
        Text('Media conditions do not match. Displaying fallback content.')
          .fontSize(16)
          .fontColor(Color.Red)
          .margin(10);

        Image($r('app.media.app_icon'))
          .width(100)
          .height(100);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

