@Entry
@Component
struct BatchDataOperationsExample {
  @State data: Array<string> = ['Item 1', 'Item 2', 'Item 3', 'Item 4'];
  @State selectedIndices: Array<number> = [];

  build() {
    Column() {
      List({ space: 10 }) {
        ForEach(this.data, (item: string, index: number) => {
          ListItem() {
            Row() {
              Text(item)
                .fontSize(20)
                .margin({ left: 10 })
              Checkbox()
                .onChange((checked: boolean) => {
                  if (checked) {
                    this.selectedIndices.push(index);
                  } else {
                    const pos = this.selectedIndices.indexOf(index);
                    if (pos >= 0) {
                      this.selectedIndices.splice(pos, 1);
                    }
                  }
                })
            }
            .justifyContent(FlexAlign.SpaceBetween)
            .padding(10)
          }
        })
      }
      .layoutWeight(1)

      Row({ space: 20 }) {
        Button('Delete Selected')
          .onClick(() => {
            this.selectedIndices.sort((a, b) => b - a);
            this.selectedIndices.forEach((index: number) => {
              this.data.splice(index, 1);
            });
            this.selectedIndices = [];
          })
          .width(150)
          .height(50)

        Button('Clear All')
          .onClick(() => {
            this.data = [];
            this.selectedIndices = [];
          })
          .width(150)
          .height(50)
      }
      .margin(20)
    }
    .padding(20)
    .width("100%")
    .height("100%")
    .backgroundColor("#ffffff")
  }
}

