          .margin({ top: 20, bottom: 20 })
          .textAlign(TextAlign.Center);
      }
      .layoutWeight(1);

      // Drawer Toggle Button
      Button('Toggle Drawer')
        .onClick(() => {
          this.isDrawerOpen = !this.isDrawerOpen;
        })
        .margin(20);

      // Custom Drawer
      Panel(this.isDrawerOpen) {
        Column() {
          Text('Menu')
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ top: 20, bottom: 20 });

          this.DrawerItem('Home', 'app.media.app_icon_home');
          this.DrawerItem('Profile', 'app.media.app_icon_profile');
          this.DrawerItem('Settings', 'app.media.app_icon_settings');
          this.DrawerItem('About', 'app.media.app_icon_about');
        }
        .width('70%')
        .height('100%')
        .backgroundColor('#F5F5F5')
        .padding(20);
      }
      .mode(PanelMode.Mini)
      .type(PanelType.Temporary)
      .dragBar(false);
    }
    .width('100%')
    .height('100%');
  }

  @Builder DrawerItem(label: string, icon: string) {
    Row() {
      Image(icon)
        .width(24)
        .height(24)
        .margin({ right: 10 });
      Text(label)
        .fontSize(18);
    }
    .width('100%')
    .padding(16)
    .onClick(() => {
      this.selectedItem = label;
      this.isDrawerOpen = false;
      this.updateMessage(label);
    })
    .backgroundColor('#FFFFFF')
    .margin({ bottom: 8 })
    .borderRadius(8);
  }

  updateMessage(label: string) {
    switch (label) {
      case 'Home':
        this.message = 'Welcome to the Home Screen';
        break;
      case 'Profile':
        this.message = 'Viewing your Profile';
        break;
      case 'Settings':
        this.message = 'Adjust your Settings here';
        break;
      case 'About':
        this.message = 'About this Application';
        break;
      default:
        this.message = '';
    }
  }
}

