@Entry
@Component
struct MiterLimitConfigurator {
  @State miterLimit: number = 5; // Default miter limit
  private settings: RenderingContextSettings = new RenderingContextSettings(true)
  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings)

  build() {
    Column() {
      Text('Configure Miter Limit for Polygon Strokes:')
        .fontSize(20)
        .margin({ bottom: 20 })

      Row() {
        Text('Miter Limit:')
          .fontSize(16)
          .margin({ right: 10 })

        TextInput({ placeholder: 'Enter miter limit (1-10)' })
          .layoutWeight(1)
          .type(InputType.Number)
          .onChange((value: string) => {
            let newLimit = Number(value);
            if (newLimit >= 1 && newLimit <= 10) {
              this.miterLimit = newLimit;
            } else {
              console.error('Miter limit must be between 1 and 10.');
            }
          })
      }
      .margin({ bottom: 20 })

      Text(`Current Miter Limit: ${this.miterLimit}`)
        .fontSize(16)
        .margin({ bottom: 20 })

      Button('Apply Miter Limit')
        .onClick(() => {
          console.log(`Miter limit set to: ${this.miterLimit}`);
        })
        .width(200)
        .height(40)
        .margin({ bottom: 20 })

      Canvas(this.context)
        .width('100%')
        .height(300)
        .backgroundColor('#ffff00')
        .onReady(() => {
          this.context.lineWidth = 8
          this.context.lineJoin = 'miter'
          this.context.miterLimit = this.miterLimit
          this.context.beginPath()
          this.context.moveTo(50, 50)
          this.context.lineTo(150, 50)
          this.context.lineTo(100, 150)
          this.context.lineTo(50, 50)
          this.context.closePath()
          this.context.stroke()
        })

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 20 })
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
  }
}

@Entry
@Component
struct SwipeGestureStateTransition {
  @State private isSwipeActive: boolean = false;
  @State private swipeDirection: string = 'None';

  build() {
    Column() {
      Text('Swipe Gesture State Transition')
        .fontSize(20)
        .margin({ bottom: 20 });

      Row()
        .width(300)
        .height(200)
        .backgroundColor('#ADD8E6')
        .borderRadius(10)
        .gesture(
          PanGesture({ direction: PanDirection.Horizontal })
            .onActionStart(() => {
              this.swipeDirection = 'None';
            })
            .onActionUpdate((event: PanGestureEvent) => {
              if (event.offsetX > 50) {
                this.swipeDirection = 'Right';
                this.isSwipeActive = true;
              } else if (event.offsetX < -50) {
                this.swipeDirection = 'Left';
                this.isSwipeActive = true;
              }
            })
            .onActionEnd(() => {
              this.isSwipeActive = false;
              animateTo({ duration: 300 }, () => {
                this.swipeDirection = 'None';
              });
            })
        );

      if (this.isSwipeActive) {
        Text(`Swipe Direction: ${this.swipeDirection}`)
          .fontSize(16)
          .margin({ top: 20 });
      } else {
        Text('Swipe to see direction')
          .fontSize(16)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(Color.White);
  }
}

