@Entry
@Component
struct SequentialGestureRecognition {
  @State private sequence: string = '';
  @State private recognized: boolean = false;

  private expectedSequence: string[] = ['Tap', 'Swipe', 'Pinch'];
  private currentStep: number = 0;

  private checkGesture(gesture: string): void {
    if (gesture === this.expectedSequence[this.currentStep]) {
      this.sequence += gesture + ' ';
      this.currentStep++;
      if (this.currentStep === this.expectedSequence.length) {
        this.recognized = true;
      }
    } else {
      this.sequence = '';
      this.currentStep = 0;
      this.recognized = false;
    }
  }

  build() {
    Column() {
      Text(this.recognized ? 'Sequence Recognized!' : 'Perform Tap, Swipe, Pinch')
        .fontSize(24)
        .margin(20);

      Text(`Current Sequence: ${this.sequence}`)
        .fontSize(18)
        .margin(10);

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(20)
        .gesture(
          TapGesture({ count: 1 })
            .onAction(() => this.checkGesture('Tap'))
        );

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(20)
        .gesture(
          SwipeGesture({ direction: SwipeDirection.Horizontal })
            .onAction(() => this.checkGesture('Swipe'))
        );

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(20)
        .gesture(
          PinchGesture()
            .onActionEnd(() => this.checkGesture('Pinch'))
        );
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

