@Entry
@Component
struct ComplexGestureCombination {
  @State offsetX: number = 0
  @State offsetY: number = 0
  @State scaleValue: number = 1
  @State rotationAngle: number = 0
  @State message: string = 'Perform gestures on the box'

  build() {
    Column() {
      Text(this.message)
        .fontSize(20)
        .margin({ bottom: 20 })

      Row()
        .width(200)
        .height(200)
        .backgroundColor(Color.Blue)
        .borderRadius(10)
        .gesture(
          GestureGroup(
            GestureMode.Parallel,
            PanGesture({ direction: PanDirection.All })
              .onActionStart(() => {
                this.message = 'Pan gesture started'
              })
              .onActionUpdate((event: GestureEvent) => {
                this.offsetX = event.offsetX
                this.offsetY = event.offsetY
                this.message = `Panning: X: ${this.offsetX}, Y: ${this.offsetY}`
              })
              .onActionEnd(() => {
                animateTo({ duration: 300 }, () => {
                  this.offsetX = 0
                  this.offsetY = 0
                })
                this.message = 'Perform gestures on the box'
              }),
            PinchGesture()
              .onActionUpdate((event: PinchGestureEvent) => {
                this.scaleValue = event.scale
                this.message = `Scaling: ${this.scaleValue.toFixed(2)}`
              }),
            RotationGesture()
              .onActionUpdate((event: RotationGestureEvent) => {
                this.rotationAngle = event.angle
                this.message = `Rotating: ${this.rotationAngle.toFixed(2)}°`
              }),
            TapGesture({ count: 2 })
              .onAction(() => {
                this.message = 'Double tap detected'
              })
          )
        )
        .transform({ translate: { x: this.offsetX, y: this.offsetY }, scale: { x: this.scaleValue, y: this.scaleValue }, rotate: { angle: this.rotationAngle } })
        .animation({ duration: 300 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

