@Entry
@Component
struct ShaderBufferModifier {
  @State bufferData: ArrayBuffer = new ArrayBuffer(1024);
  @State shaderEnabled: boolean = false;
  @State shaderIntensity: number = 0.5;
  @State shaderColor: string = '#FF0000';

  aboutToAppear() {
    this.bufferData = this.generateBufferData();
  }

  generateBufferData(): ArrayBuffer {
    const buffer = new ArrayBuffer(1024);
    const view = new Uint8Array(buffer);
    for (let i = 0; i < view.length; i++) {
      view[i] = Math.floor(Math.random() * 256);
    }
    return buffer;
  }

  toggleShader() {
    this.shaderEnabled = !this.shaderEnabled;
  }

  updateShaderIntensity(value: number) {
    this.shaderIntensity = value;
  }

  toggleShaderColor() {
    this.shaderColor = this.shaderColor === '#FF0000' ? '#00FF00' : '#FF0000';
  }

  build() {
    Column({ space: 20 }) {
      Text('Shader Buffer Modifier')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Stack() {
        Image($r('app.media.app_icon'))
          .width(300)
          .height(300)
          .backgroundColor(this.shaderColor)
          .opacity(this.shaderIntensity)
          .overlay(this.shaderEnabled ? 'rgba(0,0,0,0.3)' : 'rgba(0,0,0,0)')
          .onClick(() => {
            this.toggleShader();
          });
      }
      .width('100%')
      .height(300)
      .margin({ bottom: 20 });

      Row() {
        Text('Intensity:');
        Slider({
          value: this.shaderIntensity,
          min: 0,
          max: 1,
          step: 0.1
        })
        .onChange((value: number) => {
          this.updateShaderIntensity(value);
        })
        .layoutWeight(1);
      }

      Row() {
        Text('Color:');
        Button(this.shaderColor)
          .onClick(() => {
            this.toggleShaderColor();
          })
          .backgroundColor(this.shaderColor)
          .width(100);
      }

      Button(this.shaderEnabled ? 'Disable Shader' : 'Enable Shader')
        .onClick(() => {
          this.toggleShader();
        })
        .margin({ top: 20 });

      Text('Buffer Data Loaded')
        .fontSize(16)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor($r('sys.color.ohos_id_color_background'));
  }
}

