struct DynamicMediaLayoutExample {
  @State private paddingValue: number = 20;
  @State private marginValue: number = 10;
  @State private isWideScreen: boolean = false;

  build() {
    Column() {
      Text('Dynamic Media Layout Example')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Text(this.isWideScreen ? 'Wide Screen' : 'Narrow Screen')
        .fontSize(18)
        .margin({ bottom: 20 });

      Column() {
        Text('Content with Dynamic Padding and Margin')
          .fontSize(18)
          .textAlign(TextAlign.Center)
          .backgroundColor(Color.Gray)
          .padding(this.paddingValue)
          .margin(this.marginValue)
          .border({ width: 1, color: Color.Black });
      }
      .width('100%')
      .alignItems(HorizontalAlign.Center)
      .onAreaChange((oldValue, newValue) => {
        this.isWideScreen = newValue.width > 600;
        this.paddingValue = this.isWideScreen ? 40 : 20;
        this.marginValue = this.isWideScreen ? 20 : 10;
      });
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

