import { UIContext, matrix4 } from '@kit.ArkUI';

@Entry
@Component
struct OptimizedComponent3DAnimation {
  private matrix = matrix4.identity()
    .rotate({ angle: 45, x: 1, y: 0, z: 0 })
    .rotate({ angle: 30, x: 0, y: 1, z: 0 })
    .rotate({ angle: 60, x: 0, y: 0, z: 1 })
    .scale({ x: 1.5, y: 1.5, z: 1.5 })
    .translate({ x: 100, y: 50, z: 0 });

  @State myScale: number = 1.0;
  @State rotationAngle: number = 0;
  @State translateZ: number = 0;
  uiContext: UIContext | undefined = undefined;

  aboutToAppear() {
    this.uiContext = this.getUIContext?.();
  }

  build() {
    Stack() {
      Image($r('app.media.app_icon'))
        .transform(this.matrix)
        .width(300)
        .height(300)
        .scale({ x: this.myScale, y: this.myScale })
        .rotate({ angle: this.rotationAngle })
        .translate({ z: this.translateZ })
        .backgroundColor(Color.Gray)
        .onClick(() => {
          if (!this.uiContext) {
            console.info("no uiContext, animation failed");
            return;
          }
          this.myScale = 1;
          this.rotationAngle = 0;
          this.translateZ = 0;
          this.uiContext.keyframeAnimateTo({ iterations: 3 }, [
            {
              duration: 800,
              event: () => {
                this.myScale = 1.5;
                this.rotationAngle = 45;
                this.translateZ = 50;
              }
            },
            {
              duration: 500,
              event: () => {
                this.myScale = 1;
                this.rotationAngle = 90;
                this.translateZ = 0;
              }
            },
            {
              duration: 500,
              event: () => {
                this.myScale = 1.2;
                this.rotationAngle = 135;
                this.translateZ = -50;
              }
            },
            {
              duration: 500,
              event: () => {
                this.myScale = 1;
                this.rotationAngle = 180;
                this.translateZ = 0;
              }
            }
          ]);
        })
    }
    .width('100%')
    .height('100%')
    .align(Alignment.Center)
  }
}

@Entry
@Component
struct TextInputErrorIndicator {
  @State text: string = ''
  @State isError: boolean = false
  @State errorMessage: string = ''
  controller: TextInputController = new TextInputController()

  build() {
    Column() {
      TextInput({ placeholder: 'Enter text...', controller: this.controller })
        .width(380)
        .height(60)
        .onChange((value: string) => {
          this.text = value
          this.validateInput(value)
        })
        .borderColor(this.isError ? Color.Red : Color.Gray)
        .borderWidth(2)

      if (this.isError) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 10 })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }

  validateInput(value: string) {
    if (value.length === 0) {
      this.isError = true
      this.errorMessage = 'Input cannot be empty.'
    } else if (!/^[a-zA-Z0-9]+$/.test(value)) {
      this.isError = true
      this.errorMessage = 'Input must contain only letters and numbers.'
    } else {
      this.isError = false
      this.errorMessage = ''
    }
  }
}

