@Entry
@Component
struct LoginScreen {
  @State email: string = ''
  @State password: string = ''
  @State loginMessage: string = ''
  @State isSuccess: boolean = false

  validateInput(): boolean {
    if (this.email && this.password) {
      this.loginMessage = `Login successful! Email: ${this.email}, Password: ${this.password}`
      this.isSuccess = true
      return true
    } else {
      this.loginMessage = 'Please enter both email and password.'
      this.isSuccess = false
      return false
    }
  }

  build() {
    Column() {
      // Email Label and Input
      Text('Email')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your email', text: this.email })
        .onChange((value: string) => {
          this.email = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Password Label and Input
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      // Login Button
      Button('Login')
        .onClick(() => {
          this.validateInput()
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      // Login Message
      if (this.loginMessage) {
        Text(this.loginMessage)
          .fontSize(16)
          .margin({ top: 20 })
          .fontColor(this.isSuccess ? Color.Green : Color.Red)
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

@Entry
@Component
struct CustomParticleBehavior {
  build() {
    Stack() {
      Text()
        .width(300)
        .height(300)
        .backgroundColor(Color.Black)
      Particle({
        particles: [
          {
            emitter: {
              particle: {
                type: ParticleType.POINT,
                config: {
                  radius: 10
                },
                count: 500,
                lifetime: 10000,
                lifetimeRange: 100
              },
              emitRate: 10,
              position: [0, 0],
              shape: ParticleEmitterShape.RECTANGLE
            },
            color: {
              range: [Color.Red, Color.Yellow],
              updater: {
                type: ParticleUpdater.CURVE,
                config: [
                  {
                    from: Color.White,
                    to: Color.Pink,
                    startMillis: 0,
                    endMillis: 3000,
                    curve: Curve.EaseIn
                  },
                  {
                    from: Color.Pink,
                    to: Color.Orange,
                    startMillis: 3000,
                    endMillis: 5000,
                    curve: Curve.EaseIn
                  },
                  {
                    from: Color.Orange,
                    to: Color.Pink,
                    startMillis: 5000,
                    endMillis: 8000,
                    curve: Curve.EaseIn
                  }
                ]
              }
            },
            opacity: {
              range: [0.0, 1.0],
              updater: {
                type: ParticleUpdater.CURVE,
                config: [
                  {
                    from: 0.0,
                    to: 1.0,
                    startMillis: 0,
                    endMillis: 3000,
                    curve: Curve.EaseIn
                  },
                  {
                    from: 1.0,
                    to: 0.0,
                    startMillis: 5000,
                    endMillis: 10000,
                    curve: Curve.EaseIn
                  }
                ]
              }
            },
            scale: {
              range: [0.0, 0.0],
              updater: {
                type: ParticleUpdater.CURVE,
                config: [
                  {
                    from: 0.0,
                    to: 0.5,
                    startMillis: 0,
                    endMillis: 3000,
                    curve: Curve.EaseIn
                  }
                ]
              }
            },
            acceleration: {
              speed: {
                range: [3, 9],
                updater: {
                  type: ParticleUpdater.RANDOM,
                  config: [1, 20]
                }
              },
              angle: {
                range: [90, 90]
              }
            }
          }
        ]
      })
        .width(300)
        .height(300)
    }
    .width("100%")
    .height("100%")
    .align(Alignment.Center)
  }
}

