@Entry
@Component
struct TapGestureTimingConstraints {
  @State private tapCount: number = 0;
  @State private lastTapTime: number = 0;
  @State private tapMessage: string = "Tap the screen";

  private handleTap() {
    const currentTime = new Date().getTime();
    if (currentTime - this.lastTapTime < 300) { // 300ms timing constraint
      this.tapCount++;
      this.tapMessage = `Double Tap Detected! Count: ${this.tapCount}`;
    } else {
      this.tapCount = 1;
      this.tapMessage = "Single Tap Detected!";
    }
    this.lastTapTime = currentTime;
  }

  build() {
    Column() {
      Text(this.tapMessage)
        .fontSize(20)
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .gesture(
      TapGesture()
        .onAction(() => {
          this.handleTap();
        })
    )
  }
}

