@Entry
@Component
struct PullUpToLoadMoreWithSwipeRefresher {
  @State refreshing: boolean = false;
  @State loadingMore: boolean = false;
  @State listData: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4', 'Item 5'];

  private loadMoreData() {
    this.loadingMore = true;
    setTimeout(() => {
      const newData = ['New Item 1', 'New Item 2', 'New Item 3'];
      this.listData = [...this.listData, ...newData];
      this.loadingMore = false;
    }, 2000);
  }

  private refreshData() {
    this.refreshing = true;
    setTimeout(() => {
      this.listData = ['Refreshed Item 1', 'Refreshed Item 2', 'Refreshed Item 3'];
      this.refreshing = false;
    }, 2000);
  }

  build() {
    Column() {
      Refresh({
        refreshing: this.refreshing,
        offset: 120,
        friction: 100
      }) {
        List() {
          ForEach(this.listData, (item: string) => {
            ListItem() {
              Row() {
                Image($r('app.media.app_icon'))
                  .width(40)
                  .height(40)
                  .margin(10)

                Text(item)
                  .fontSize(18)
              }
              .width('100%')
              .justifyContent(FlexAlign.Start)
            }
            .borderRadius(8)
            .margin({ top: 5, bottom: 5 })
            .backgroundColor('#f5f5f5')
          }, (item: string) => item)

          if (this.loadingMore) {
            ListItem() {
              Text('Loading more...')
                .fontSize(16)
                .padding(16)
                .textAlign(TextAlign.Center)
                .width('100%')
            }
          }
        }
        .onReachEnd(() => {
          if (!this.loadingMore) {
            this.loadMoreData();
          }
        })
        .width('100%')
      }
      .onRefreshing(() => {
        this.refreshData();
      })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff')
  }
}

import router from '@ohos.router';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct LoginScreen {
  @State email: string = '';
  @State password: string = '';
  @State errorMessage: string = '';

  validateInput(): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(this.email)) {
      this.errorMessage = 'Invalid email format';
      return false;
    }
    if (this.password.length < 6) {
      this.errorMessage = 'Password must be at least 6 characters';
      return false;
    }
    this.errorMessage = '';
    return true;
  }

  navigateToHome() {
    router.pushUrl({ url: 'pages/HomeScreen' });
  }

  build() {
    Column() {
      Text('Email')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your email', text: this.email })
        .onChange((value: string) => {
          this.email = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Button('Login')
        .onClick(() => {
          if (this.validateInput()) {
            promptAction.showToast({ message: 'Login successful!' });
            this.navigateToHome();
          } else {
            promptAction.showToast({ message: this.errorMessage });
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White);

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 10 });
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

