@Component
struct ContactForm {
  @State name: string = ''
  @State email: string = ''
  @State phoneNumber: string = ''
  @State successMessage: string = ''
  @State errorMessage: string = ''

  validateForm(): boolean {
    if (!this.name || !this.email || !this.phoneNumber) {
      this.errorMessage = 'All fields are required'
      return false
    }
    if (!this.email.includes('@')) {
      this.errorMessage = 'Invalid email format'
      return false
    }
    if (!/^\d{10}$/.test(this.phoneNumber)) {
      this.errorMessage = 'Phone number must be 10 digits'
      return false
    }
    this.errorMessage = ''
    return true
  }

  build() {
    Column() {
      Text('Contact Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value
          })
      }

      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value
          })
