@Entry
@Component
struct EventDetectionWithCarefulAveraging {
  @State clickTimes: number[] = [];
  @State averageInterval: number = 0;
  @State detectionMessage: string = 'Click to calculate careful average event interval';

  build() {
    Column() {
      Button('Click Me')
        .margin(30)
        .onClick(() => {
          const currentTime = new Date().getTime();
          this.clickTimes.push(currentTime);

          if (this.clickTimes.length >= 2) {
            const intervals: number[] = [];
            for (let i = 1; i < this.clickTimes.length; i++) {
              intervals.push(this.clickTimes[i] - this.clickTimes[i - 1]);
            }
            const sum = intervals.reduce((acc, curr) => acc + curr, 0);
            this.averageInterval = sum / intervals.length;

            const deviation = intervals.reduce((acc, curr) => acc + Math.abs(curr - this.averageInterval), 0) / intervals.length;
            if (deviation < 50) { // 50ms tolerance for careful averaging
              this.detectionMessage = `Careful Average: ${this.averageInterval.toFixed(2)}ms (Consistent)`;
            } else {
              this.detectionMessage = `Average: ${this.averageInterval.toFixed(2)}ms (Inconsistent)`;
            }
          }
        });

      Text(this.detectionMessage)
        .fontSize(20)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }
}

