@Component
struct AnimatedLoader {
    @State rotation: number = 0
    @State scaleValue: number = 1
    private intervalID: number = -1

    aboutToAppear() {
        this.intervalID = setInterval(() => {
            this.rotation = (this.rotation + 15) % 360
            this.scaleValue = this.scaleValue === 1 ? 1.2 : 1
        }, 100)
    }

    aboutToDisappear() {
        if (this.intervalID !== -1) {
            clearInterval(this.intervalID)
        }
    }

    build() {
        Column() {
            Stack() {
                Image($r('app.media.app_icon'))
                    .width(100)
                    .height(100)
                    .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })
                    .scale({ x: this.scaleValue, y: this.scaleValue })
                Circle()
                    .width(120)
                    .height(120)
                    .stroke($r('sys.color.ohos_id_color_primary'))
                    .strokeWidth(5)
                    .strokeDashArray([5, 15])
                    .rotate({ x: 0, y: 0, z: 1, angle: -this.rotation })
            }
            .width(120)
            .height(120)

            Text('Loading...')
                .fontSize(20)
                .margin({ top: 20 })
        }
        .justifyContent(FlexAlign.Center)
        .width('100%')
        .height('100%')
    }
}

