        }
        .width('100%');
      }
      .onRefreshing(() => {
        this.isRefreshing = true;
        setTimeout(() => {
          this.listData = ['New Item 1', 'New Item 2', 'New Item 3'];
          this.isRefreshing = false;
        }, 2000);
      });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

