@Entry
@Component
struct NestedFilterApp {
  @State selectedCategory: string = 'All';
  @State selectedSubCategory: string = 'All';
  @State items: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4', 'Item 5'];

  build() {
    Column({ space: 10 }) {
      // Category Filter
      Row({ space: 10 }) {
        Button('All')
          .onClick(() => {
            this.selectedCategory = 'All';
            this.selectedSubCategory = 'All';
          })
          .backgroundColor(this.selectedCategory === 'All' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1)

        Button('Electronics')
          .onClick(() => {
            this.selectedCategory = 'Electronics';
            this.selectedSubCategory = 'All';
          })
          .backgroundColor(this.selectedCategory === 'Electronics' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1)

        Button('Clothing')
          .onClick(() => {
            this.selectedCategory = 'Clothing';
            this.selectedSubCategory = 'All';
          })
          .backgroundColor(this.selectedCategory === 'Clothing' ? '#39a2db' : '#e0e0e0')
          .flexGrow(1)
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .padding(10)

      // Sub-Category Filter
      if (this.selectedCategory !== 'All') {
        Row({ space: 10 }) {
          Button('All')
            .onClick(() => {
              this.selectedSubCategory = 'All';
            })
            .backgroundColor(this.selectedSubCategory === 'All' ? '#39a2db' : '#e0e0e0')
            .flexGrow(1)

          Button(this.selectedCategory === 'Electronics' ? 'Mobiles' : 'Shirts')
            .onClick(() => {
              this.selectedSubCategory = this.selectedCategory === 'Electronics' ? 'Mobiles' : 'Shirts';
            })
            .backgroundColor(this.selectedSubCategory === (this.selectedCategory === 'Electronics' ? 'Mobiles' : 'Shirts') ? '#39a2db' : '#e0e0e0')
            .flexGrow(1)

          Button(this.selectedCategory === 'Electronics' ? 'Laptops' : 'Pants')
            .onClick(() => {
              this.selectedSubCategory = this.selectedCategory === 'Electronics' ? 'Laptops' : 'Pants';
            })
            .backgroundColor(this.selectedSubCategory === (this.selectedCategory === 'Electronics' ? 'Laptops' : 'Pants') ? '#39a2db' : '#e0e0e0')
            .flexGrow(1)
        }
        .width('100%')
        .justifyContent(FlexAlign.SpaceEvenly)
        .padding(10)
      }

      // Displayed Content Based on Selected Filters
      List() {
        ForEach(this.items, (item: string) => {
          if ((this.selectedCategory === 'All' || this.selectedCategory === 'Electronics' || this.selectedCategory === 'Clothing') &&
              (this.selectedSubCategory === 'All' || this.selectedSubCategory === 'Mobiles' || this.selectedSubCategory === 'Laptops' || this.selectedSubCategory === 'Shirts' || this.selectedSubCategory === 'Pants')) {
            ListItem() {
              Column() {
                Text(item)
                  .fontSize(18)
                  .padding(10)
              }
              .width('100%')
              .alignItems(HorizontalAlign.Start)
              .padding(10)
            }
          }
        })
      }
      .width('100%')
      .height('70%')
      .backgroundColor('#f5f5f5')
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff')
  }
}

