@Entry
@Component
struct CustomRotationAxisVectors {
  @State private angle: number = 0;
  @State private axisX: number = 0;
  @State private axisY: number = 1;
  @State private axisZ: number = 0;

  private degreesToRadians(degrees: number): number {
    return degrees * (Math.PI / 180);
  }

  build() {
    Column({ space: 20 }) {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .rotate({ x: this.axisX, y: this.axisY, z: this.axisZ, angle: this.degreesToRadians(this.angle) })
        .margin(10)
        .align(Alignment.Center)

      Slider({
        min: 0,
        max: 360,
        value: this.angle
      })
      .width('80%')
      .onChange((value: number) => {
        this.angle = value;
      })

      Text('Axis X: ' + this.axisX.toFixed(2))
        .fontSize(16)
      Slider({
        min: -1,
        max: 1,
        value: this.axisX
      })
      .width('80%')
      .onChange((value: number) => {
        this.axisX = value;
      })

      Text('Axis Y: ' + this.axisY.toFixed(2))
        .fontSize(16)
      Slider({
        min: -1,
        max: 1,
        value: this.axisY
      })
      .width('80%')
      .onChange((value: number) => {
        this.axisY = value;
      })

      Text('Axis Z: ' + this.axisZ.toFixed(2))
        .fontSize(16)
      Slider({
        min: -1,
        max: 1,
        value: this.axisZ
      })
      .width('80%')
      .onChange((value: number) => {
        this.axisZ = value;
      })
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

