@Component
struct SplashScreen {
  @State logoVisible: boolean = true;
  @State rotation: number = 0;
  private onTransition: () => void = () => {};

  aboutToAppear() {
    const intervalID = setInterval(() => {
      this.rotation = (this.rotation + 10) % 360;
    }, 50);

    setTimeout(() => {
      clearInterval(intervalID);
      this.logoVisible = false;
      this.onTransition();
    }, 3000);
  }

  build() {
    Column() {
      if (this.logoVisible) {
        Image($r('app.media.app_icon'))
          .width(150)
          .height(150)
          .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })
          .margin({ bottom: 20 });

        Text('Welcome to My App')
          .fontSize(24)
          .fontWeight(FontWeight.Bold);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#FFFFFF')
  }
}

@Component
struct LoginScreen {
  @State username: string = '';
  @State password: string = '';
  @State loginMessage: string = '';

  build() {
    Column() {
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your username', text: this.username })
        .onChange((value: string) => {
          this.username = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

