@Entry
@Component
struct SwipeRefresherPerformanceProfiling {
  @State isRefreshing: boolean = false
  @State refreshStartTime: number = 0
  @State refreshEndTime: number = 0
  @State refreshDuration: number = 0
  @State data: string[] = ['Item 1', 'Item 2', 'Item 3']

  startProfiling() {
    this.refreshStartTime = Date.now()
    this.isRefreshing = true
  }

  stopProfiling() {
    this.refreshEndTime = Date.now()
    this.refreshDuration = this.refreshEndTime - this.refreshStartTime
    this.isRefreshing = false
  }

  updateData() {
    this.data = ['New Item A', 'New Item B', 'New Item C']
  }

  build() {
    Column() {
      Text(`Refresh Duration: ${this.refreshDuration} ms`)
        .fontSize(18)
        .margin(10)

      Refresh({
        refreshing: this.isRefreshing,
        offset: 120,
        friction: 100
      }) {
        List() {
          ForEach(this.data, (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(16)
                .padding(10)
            }
          })
        }
        .width('100%')
      }
      .onRefreshing(() => {
        this.startProfiling()
        setTimeout(() => {
          this.updateData()
          this.stopProfiling()
        }, 2000)
      })

      if (this.isRefreshing) {
        Image($r('app.media.app_icon'))
          .width(50)
          .height(50)
          .margin(10)
      }
    }
    .width('100%')
    .height('100%')
    .padding(10)
  }
}

