@Entry
@Component
struct ModularPopupApp {
  @State isSimplePopupVisible: boolean = false;
  @State isDecoratedPopupVisible: boolean = false;
  @State isAnimatedPopupVisible: boolean = false;

  build() {
    Column({ space: 20 }) {
      Button('Show Simple Popup')
        .onClick(() => {
          this.isSimplePopupVisible = true;
        })
        .margin(10)
        .backgroundColor(Color.Blue)
        .fontColor(Color.White);

      Button('Show Decorated Popup')
        .onClick(() => {
          this.isDecoratedPopupVisible = true;
        })
        .margin(10)
        .backgroundColor(Color.Green)
        .fontColor(Color.White);

      Button('Show Animated Popup')
        .onClick(() => {
          this.isAnimatedPopupVisible = true;
        })
        .margin(10)
        .backgroundColor(Color.Orange)
        .fontColor(Color.White);

      if (this.isSimplePopupVisible) {
        SimplePopup({
          onClose: () => {
            this.isSimplePopupVisible = false;
          }
        });
      }

      if (this.isDecoratedPopupVisible) {
        DecoratedPopup({
          onClose: () => {
            this.isDecoratedPopupVisible = false;
          }
        });
      }

      if (this.isAnimatedPopupVisible) {
        AnimatedPopup({
          onClose: () => {
            this.isAnimatedPopupVisible = false;
          }
        });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

