import promptAction from '@ohos.promptAction';

@Entry
@Component
struct LoginForm {
  @State username: string = '';
  @State password: string = '';

  validateCredentials(): boolean {
    if (this.username === 'admin' && this.password === 'password123') {
      promptAction.showToast({
        message: 'Login successful!'
      });
      return true;
    } else {
      promptAction.showToast({
        message: 'Invalid username or password'
      });
      return false;
    }
  }

  build() {
    Column() {
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your username' })
        .onChange((value: string) => {
          this.username = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Button('Login')
        .onClick(() => {
          this.validateCredentials();
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White);
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

@Entry
@Component
struct TransformationStateManagement {
  @State transformations: Array<Transformation> = [
    { id: 1, description: "Initial Transformation 1" },
    { id: 2, description: "Initial Transformation 2" }
  ];

  build() {
    Column() {
      ForEach(this.transformations, (transformation: Transformation) => {
        Column() {
          Text(`ID: ${transformation.id}`)
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin(10);
          Text(`Description: ${transformation.description}`)
            .fontSize(16)
            .margin(10);
        }
        .padding(10)
        .border({ width: 1, color: Color.Gray })
        .margin(10);
      }, (transformation: Transformation) => transformation.id.toString());

      Button('Add Transformation')
        .onClick(() => {
          const newTransformation: Transformation = {
            id: this.transformations.length + 1,
            description: `Transformation ${this.transformations.length + 1}`
          };
          this.transformations = [...this.transformations, newTransformation];
        })
        .margin(10)
        .width(200);

      Button('Remove Transformation')
        .onClick(() => {
          if (this.transformations.length > 0) {
            this.transformations = this.transformations.slice(0, -1);
          }
        })
        .margin(10)
        .width(200);
    }
    .padding(20)
    .width('100%')
    .height('100%');
  }
}

interface Transformation {
  id: number;
  description: string;
}

