@Entry
@Component
struct FirebaseLoginApp {
  @State email: string = '';
  @State password: string = '';
  @State welcomeMessage: string = '';
  @State errorMessage: string = '';
  @State isLoading: boolean = false;

  async handleLogin() {
    if (!this.email || !this.password) {
      this.errorMessage = 'Please fill in all fields';
      return;
    }
    if (!this.validateEmail(this.email)) {
      this.errorMessage = 'Please enter a valid email';
      return;
    }
    this.isLoading = true;
    try {
      const user: User = await this.mockFirebaseLogin(this.email, this.password);
      this.welcomeMessage = `Welcome, ${user.email}!`;
      this.errorMessage = '';
    } catch (error) {
      this.errorMessage = 'Login failed. Please check your credentials.';
    } finally {
      this.isLoading = false;
    }
  }

  async mockFirebaseLogin(email: string, password: string): Promise<User> {
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        if (email === 'test@example.com' && password === 'password123') {
          resolve({ email });
        } else {
          reject(new Error('Invalid credentials'));
        }
      }, 2000);
    });
  }

  validateEmail(email: string): boolean {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return re.test(email);
  }

  build() {
    Column() {
      Text('Login with Firebase')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 40 });

      TextInput({ placeholder: 'Enter your email' })
        .onChange((value: string) => {
          this.email = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Button(this.isLoading ? 'Logging in...' : 'Login')
        .onClick(() => {
          this.handleLogin();
        })
        .width('60%')
        .margin({ bottom: 20 });

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontColor(Color.Red)
          .fontSize(14)
          .margin({ bottom: 20 });
      }

      if (this.welcomeMessage) {
        Text(this.welcomeMessage)
          .fontColor(Color.Green)
          .fontSize(18);
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

interface User {
  email: string;
}

