@Entry
@Component
struct EditableTitleBarWithRightMenu {
  @State title: string = "Editable Title";
  @State isEditable: boolean = false;
  @State menuItems: MenuItem[] = [
    {
      value: $r('app.media.app_icon'),
      isEnabled: true,
      action: () => {
        promptAction.showToast({ message: "Menu Item 1 Clicked" });
      }
    },
    {
      value: $r('app.media.app_icon'),
      isEnabled: true,
      action: () => {
        promptAction.showToast({ message: "Menu Item 2 Clicked" });
      }
    }
  ];

  build() {
    Flex({ direction: FlexDirection.Row, alignItems: ItemAlign.Center, justifyContent: FlexAlign.SpaceBetween }) {
      // Title or TextInput for editable title
      if (this.isEditable) {
        TextInput({ text: this.title })
          .onChange((value: string) => {
            this.title = value;
          })
          .width('60%')
          .height(40)
          .padding(10)
          .backgroundColor(Color.White)
          .border({ width: 1, color: Color.Black })
          .onBlur(() => {
            this.isEditable = false;
          });
      } else {
        Text(this.title)
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .textOverflow({ overflow: TextOverflow.Ellipsis })
          .maxLines(1)
          .onClick(() => {
            this.isEditable = true;
          });
      }

      // Menu items on the right
      Row() {
        Blank()
          .layoutWeight(1);

        ForEach(this.menuItems, (item: MenuItem, index: number) => {
          Button() {
            Image(item.value)
              .width(30)
              .height(30)
          }
          .enabled(item.isEnabled ?? true)
          .onClick(() => {
            if (item.action) {
              item.action();
            }
          })
          .margin({ left: 10 });
        });
      }
    }
    .width('100%')
    .padding(10)
    .backgroundColor('#f0f0f0');
  }
}

