  build() {
    Column() {
      if (this.selectedVideo == null) {
        Text('Video Grid')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .padding(16);

        Grid() {
          ForEach(videos, (video: Video) => {
            GridItem() {
              Column() {
                Image($r('app.media.app_icon'))
                  .width(100)
                  .height(150)
                  .objectFit(ImageFit.Cover)
                  .margin({ bottom: 8 });

                Text(video.title)
                  .fontSize(18)
                  .fontWeight(FontWeight.Medium)
                  .padding({ bottom: 4 });

                Button('Play')
                  .onClick(() => {
                    this.selectedVideo = video;
                  })
                  .padding(10);
              }
              .padding(16);
            }
          });
        }
        .columnsTemplate('1fr 1fr')
        .rowsGap(16)
        .columnsGap(16)
        .padding(16);
      } else {
        Video({
          src: this.selectedVideo.url,
          controller: this.videoController
        })
        .controls(true)
        .autoPlay(true)
        .loop(false)
        .objectFit(ImageFit.Contain)
        .onPrepared((event) => {
          console.info("Video prepared. Duration: " + event.duration);
        })
        .onUpdate((event) => {
          console.info("Video progress updated. Current time: " + event.time);
        })
        .onError(() => {
          promptAction.showToast({ duration: 2000, message: "Video playback error." });
        })
        .width('100%')
        .height('100%');

        Button('Back')
          .onClick(() => {
            this.videoController.stop();
            this.selectedVideo = null;
          })
          .padding(16);
      }
    }
    .width('100%')
    .height('100%');
  }
}

