@Component
struct EditableTitleBar {
  @State title: string = "Default Title";
  @State isEditable: boolean = false;
  @State isSaveRequired: boolean = false;

  build() {
    Column() {
      if (this.isEditable) {
        TextInput({ text: this.title })
          .onChange((value: string) => {
            this.title = value;
          })
          .width('80%')
          .height(40)
          .padding(10)
          .backgroundColor(Color.White)
          .border({ width: 1, color: Color.Black })
          .onBlur(() => {
            this.isEditable = false;
          });

        if (this.isSaveRequired) {
          Image($r("app.media.app_icon"))
            .width(30)
            .height(30)
            .onClick(() => {
              this.isEditable = false;
              console.log("Title saved:", this.title);
            })
            .margin({ top: 10 });
        }
      } else {
        Text(this.title)
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .textOverflow({ overflow: TextOverflow.Ellipsis })
          .maxLines(1)
          .onClick(() => {
            this.isEditable = true;
          });
      }
    }
    .width('100%')
    .padding(10)
    .backgroundColor('#f0f0f0')
  }
}

