@Entry
@Component
struct BoundaryConfigurationExample {
  @State private inputValue: string = '';
  @State private isValid: boolean = true;

  build() {
    Column({ space: 10 }) {
      TextInput({ placeholder: 'Enter a value within bounds (1-100)' })
        .width('80%')
        .height(40)
        .onChange((value: string) => {
          this.inputValue = value;
          this.isValid = this.validateBoundary(value);
        })
        .borderColor(this.isValid ? Color.Black : Color.Red)
        .borderWidth(2)

      if (!this.isValid) {
        Text('Value out of bounds! Must be between 1 and 100.')
          .fontSize(14)
          .fontColor(Color.Red)
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }

  private validateBoundary(value: string): boolean {
    const num = Number(value);
    return !isNaN(num) && num >= 1 && num <= 100;
  }
}

import router from '@ohos.router';
import promptAction from '@ohos.promptAction';

@Entry
@Component
struct LoginScreen {
  @State email: string = '';
  @State password: string = '';
  @State errorMessage: string = '';

  validateInput(): boolean {
    const emailRegex = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;
    if (!emailRegex.test(this.email)) {
      this.errorMessage = 'Invalid email format';
      return false;
    }
    if (this.password.length < 6) {
      this.errorMessage = 'Password must be at least 6 characters';
      return false;
    }
    this.errorMessage = '';
    return true;
  }

  navigateToHome() {
    router.pushUrl({ url: 'pages/HomeScreen' });
  }

  build() {
    Column() {
      Text('Email')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your email', text: this.email })
        .onChange((value: string) => {
          this.email = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Button('Login')
        .onClick(() => {
          if (this.validateInput()) {
            promptAction.showToast({ message: 'Login successful!' });
            this.navigateToHome();
          } else {
            promptAction.showToast({ message: this.errorMessage });
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White);

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 10 });
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

