@Component
struct PreserveScrollPositionList {
  @State data: Array<string> = ['Item 1', 'Item 2', 'Item 3', 'Item 4', 'Item 5'];
  private scroller: Scroller = new Scroller();
  private lastVisibleIndex: number = 0;

  build() {
    Column() {
      List({ space: 10, scroller: this.scroller }) {
        ForEach(this.data, (item: string, index: number) => {
          ListItem() {
            Text(item)
              .fontSize(20)
              .width('100%')
              .height(100)
              .textAlign(TextAlign.Center)
              .backgroundColor(0xF0F0F0)
              .borderRadius(10)
              .margin({ top: 5, bottom: 5 })
          }
        }, (item: string) => item)
      }
      .onScrollIndex((startIndex: number, endIndex: number) => {
        this.lastVisibleIndex = startIndex;
        console.info(`Visible items: ${startIndex} to ${endIndex}`);
      })
      .backgroundColor('#eeeeee')
      .divider({ strokeWidth: 1, color: 0x222222 })

      Button('Add Item')
        .onClick(() => {
          const newItem = `Item ${this.data.length + 1}`;
          this.data.push(newItem);
          this.data = [...this.data];
          this.scroller.scrollToIndex(this.lastVisibleIndex);
        })
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .backgroundColor(0xF1F3F5)
  }
}

