    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

import { inspector } from '@kit.ArkUI';

@Entry
@Component
struct SnapshotCaptureExample {
  @State snapshotCaptured: boolean = false;
  @State snapshotData: string = '';

  listener: inspector.ComponentObserver = inspector.createComponentObserver('TARGET_COMPONENT');

  aboutToAppear() {
    let onLayoutComplete: () => void = (): void => {
      this.captureSnapshot();
    };

    let onDrawComplete: () => void = (): void => {
      this.finalizeSnapshot();
    };

    let FuncLayout = onLayoutComplete;
    let FuncDraw = onDrawComplete;

    this.listener.on('layout', FuncLayout);
    this.listener.on('draw', FuncDraw);
  }

  captureSnapshot() {
    this.snapshotData = 'Snapshot initiated';
  }

  finalizeSnapshot() {
    this.snapshotCaptured = true;
    this.snapshotData = 'Snapshot completed';
  }

  build() {
    Column() {
      Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Start }) {
        Row({ space: 5 }) {
          Image($r('app.media.app_icon'))
            .width(110)
            .height(110)
            .border({ width: 1 })
            .id('TARGET_COMPONENT')
        }
      }
      Text(this.snapshotData)
        .fontSize(18)
        .margin(10)
    }
    .height(320)
    .width(360)
    .padding({ right: 10, top: 10 })
  }
}

