          .backgroundColor('#f0f0f0')
          .borderRadius(10)
        }
      }, (item: string) => item)
    }
    .width('100%')
    .height('100%')
    .scrollBar(BarState.On)
    .scrollBarColor(Color.Gray)
    .scrollBarWidth(10)
    .edgeEffect(EdgeEffect.Spring)
    .onScrollIndex((startIndex: number, endIndex: number) => {
      console.log(`Visible items from index ${startIndex} to ${endIndex}`);
    })
    .onReachEnd(() => {
      const newData: string[] = Array.from({ length: 10 }, (_: undefined, i: number) => `Item ${this.data.length + i + 1}`);
      this.data = [...this.data, ...newData];
    })
    .padding(10)
  }
}

@Entry
@Component
struct TodoListApp {
  @State tasks: Array<Task> = []
  @State newTask: string = ''
  @State taskIdCounter: number = 0

  build() {
    Column() {
      TextInput({ placeholder: 'Enter a new task' })
        .onChange((value: string) => {
          this.newTask = value
        })
        .margin({ bottom: 20 })

      Button('Add Task')
        .onClick(() => {
          if (this.newTask) {
            this.tasks.push({ id: this.taskIdCounter++, content: this.newTask, isCompleted: false, createdAt: new Date().toLocaleString() })
            this.newTask = ''
          }
        })
        .margin({ bottom: 20 })

      ForEach(this.tasks, (task: Task, index: number) => {
        Row() {
          Checkbox()
            .select(task.isCompleted)
            .onChange((value: boolean) => {
              this.tasks[index].isCompleted = value
            })
            .margin({ right: 10 })

          Text(task.content)
            .fontSize(20)
            .decoration({ type: task.isCompleted ? TextDecorationType.LineThrough : TextDecorationType.None })

          Button() {
            Image($r('app.media.app_icon'))
              .fillColor(Color.White)
              .width(20)
          }
          .width(40)
          .height(40)
          .type(ButtonType.Circle)
          .backgroundColor(Color.Red)
          .margin({ left: 10 })
          .onClick(() => {
            this.tasks.splice(index, 1)
          })
        }
        .margin({ top: 10 })
      })
    }
    .padding(20)
  }
}

interface Task {
  id: number
  content: string
  isCompleted: boolean
  createdAt: string
}

