@Entry
@Component
struct ProductRatingSystem {
  @State ratings: number[] = [];
  @State averageRating: number = 0;
  @State currentRating: number = 0;

  private calculateAverageRating(): void {
    if (this.ratings.length === 0) {
      this.averageRating = 0;
      return;
    }
    const sum = this.ratings.reduce((acc: number, rating: number) => acc + rating, 0);
    this.averageRating = sum / this.ratings.length;
  }

  private handleRating(rating: number): void {
    this.currentRating = rating;
  }

  private submitRating(): void {
    if (this.currentRating > 0) {
      this.ratings.push(this.currentRating);
      this.calculateAverageRating();
      this.currentRating = 0;
    }
  }

  build() {
    Column() {
      Text("Rate the Product")
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row() {
        ForEach([1, 2, 3, 4, 5], (index: number) => {
          Image($r('app.media.app_icon'))
            .width(30)
            .height(30)
            .margin({ right: 5 })
            .opacity(index <= this.currentRating ? 1 : 0.3)
            .onClick(() => {
              this.handleRating(index);
            });
        })
      }
      .margin({ bottom: 20 });

      Text(`Average Rating: ${this.averageRating.toFixed(1)}`)
        .fontSize(18)
        .margin({ bottom: 20 });

      Button("Submit Rating")
        .onClick(() => {
          this.submitRating();
        })
        .width(200)
        .height(50);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }
}

