      Button('Trigger Notification')
        .width('80%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          promptAction.showToast({
            message: `${this.notificationMessage} ${this.displayDate}`,
            duration: 3000
          });
        });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White);
  }
}

@Entry
@Component
struct TextInputValidation {
  @State text: string = ''
  @State errorMessage: string = ''
  private controller: TextInputController = new TextInputController()

  private validateInput(value: string): boolean {
    return value.length >= 5 // Example validation: input must be at least 5 characters
  }

  build() {
    Column() {
      TextInput({ placeholder: 'Enter a word (min 5 characters)', controller: this.controller })
        .width(380)
        .height(60)
        .onChange((value: string) => {
          this.text = value
          if (this.validateInput(value)) {
            this.errorMessage = ''
          } else {
            this.errorMessage = 'Input must be at least 5 characters long'
          }
        })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 10 })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

