import image from '@ohos.multimedia.image';

@Entry
@Component
struct ScreenshotOptimization {
  @State private optimized: boolean = false;
  @State private imageSrc: Resource = $r('app.media.app_icon');
  @State private imageWidth: number = 200;
  @State private imageHeight: number = 200;

  private async optimizeScreenshotDecoding(): Promise<void> {
    if (this.optimized) {
      const resource = $r('app.media.app_icon');
      const unit8Array: Uint8Array | undefined = await getContext(this)?.resourceManager?.getMediaContent({
        bundleName: resource.bundleName,
        moduleName: resource.moduleName,
        id: resource.id
      });
      if (unit8Array) {
        const imageSource = image.createImageSource(unit8Array.buffer);
        const pixelMap = await imageSource.createPixelMap({
          desiredPixelFormat: image.PixelMapFormat.RGBA_8888
        });
        await imageSource.release();
        this.imageSrc = {
          bundleName: resource.bundleName,
          moduleName: resource.moduleName,
          id: resource.id,
          pixelMap: pixelMap
        } as Resource;
      }
    } else {
      this.imageSrc = $r('app.media.app_icon');
    }
  }

  build() {
    Column() {
      Text('Screenshot Decoding Optimization')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Image(this.imageSrc)
        .width(this.imageWidth)
        .height(this.imageHeight)
        .margin({ bottom: 20 });

      Text(this.optimized ? 'Optimization Enabled' : 'Optimization Disabled')
        .fontSize(18)
        .fontColor(this.optimized ? Color.Green : Color.Red)
        .margin({ bottom: 20 });

      Button(this.optimized ? 'Disable Optimization' : 'Enable Optimization')
        .onClick(() => {
          this.optimized = !this.optimized;
          this.optimizeScreenshotDecoding();
        })
        .width(200)
        .height(40)
        .backgroundColor(this.optimized ? Color.Red : Color.Green)
        .borderRadius(8);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

@Entry
@Component
struct SearchableItemList {
  @State items: string[] = [
    'Laptop',
    'Smartphone',
    'Tablet',
    'Headphones',
    'Keyboard',
    'Mouse',
    'Monitor',
    'Camera',
    'Printer',
    'Router',
    'Speaker',
    'Microphone'
  ];

  @State searchText: string = '';

  filteredItems(): string[] {
    if (this.searchText.trim() === '') {
      return this.items;
    } else {
      return this.items.filter(item =>
        item.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
  }

  build() {
    Column() {
      // Search Bar
      TextInput({
        placeholder: 'Search items...',
        text: this.searchText
      })
        .width('90%')
        .height(40)
        .margin({ top: 16, bottom: 16 })
        .onChange((value: string) => {
          this.searchText = value;
        })
        .backgroundColor('#f0f0f0')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      // List of Items
      if (this.filteredItems().length > 0) {
        List() {
          ForEach(this.filteredItems(), (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(18)
                .padding(12);
            }
          }, (item: string) => item);
        }
      } else {
        // Display a message when no items match the search
        Text('No items found')
          .fontSize(16)
          .fontColor(Color.Gray)
          .padding(16);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#ffffff');
  }
}

