import { image } from '@kit.ImageKit';

@Entry
@Component
struct ScreenshotCaptureExample {
  @State pixelMap: image.PixelMap | null = null;
  @State captureStatus: string = "Ready to Capture";

  async captureScreenshot() {
    try {
      const resource = $r('app.media.app_icon');
      const unit8Array = await getContext(this)?.resourceManager?.getMediaContent({
        bundleName: resource.bundleName,
        moduleName: resource.moduleName,
        id: resource.id
      });
      const imageSource = image.createImageSource(unit8Array.buffer.slice(0, unit8Array.buffer.byteLength));
      this.pixelMap = await imageSource.createPixelMap({
        desiredPixelFormat: image.PixelMapFormat.RGBA_8888
      });
      await imageSource.release();
      this.captureStatus = "Screenshot Captured Successfully!";
    } catch (error) {
      this.captureStatus = "Failed to Capture Screenshot";
      console.error('Screenshot capture error:', error.message);
    }
  }

  build() {
    Column() {
      Text(this.captureStatus)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Button('Capture Screenshot')
        .onClick(() => {
          this.captureScreenshot();
        })
        .margin({ top: 20, bottom: 20 });

      if (this.pixelMap) {
        Image(this.pixelMap)
          .width(200)
          .height(200)
          .margin(10);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

