@Entry
@Component
struct LoginScreen {
  @State email: string = ''
  @State password: string = ''
  @State message: string = ''
  @State isError: boolean = false

  build() {
    Column() {
      // Email Input
      Text('Email:')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your email' })
        .width('80%')
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.email = value
        })

      // Password Input
      Text('Password:')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .width('80%')
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.password = value
        })

      // Login Button
      Button('Login')
        .onClick(() => {
          if (this.email.trim() === '' || this.password.trim() === '') {
            this.message = 'Email and password cannot be empty.'
            this.isError = true
          } else {
            this.message = 'Login successful!'
            this.isError = false
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      // Message Display
      if (this.message) {
        Text(this.message)
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
          .fontColor(this.isError ? Color.Red : Color.Green)
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

