@Entry
@Component
struct GaugeAnimation {
  @State progress: number = 0
  private intervalId: number = -1

  aboutToAppear() {
    this.intervalId = setInterval(() => {
      if (this.progress < 80) {
        this.progress += 1
      } else {
        clearInterval(this.intervalId)
      }
    }, 100)
  }

  aboutToDisappear() {
    if (this.intervalId !== -1) {
      clearInterval(this.intervalId)
    }
  }

  build() {
    Column() {
      Gauge({
        value: this.progress,
        min: 0,
        max: 100
      })
        .width(240)
        .height(240)
        .colors([[new LinearGradient([{ color: Color.Red, offset: 0.0 }, { color: Color.Blue, offset: 1.0 }]), 1]])

      Button('Restart Animation')
        .onClick(() => {
          if (this.intervalId !== -1) {
            clearInterval(this.intervalId)
          }
          this.progress = 0
          this.aboutToAppear()
        })
        .margin({ top: 40 })
        .backgroundColor('#4CAF50')
        .fontColor(Color.White)
        .borderRadius(5)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

