        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      // TextInput for User Input
      TextInput({ placeholder: 'Enter text here' })
        .width('100%')
        .height(40)
        .margin({ bottom: 20 })
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .onChange((value: string) => {
          this.userInput = value;
        });

      // Button to Add Input to List
      Button('Add Input')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.userInput.trim() !== '') {
            this.inputList.push(this.userInput);
            this.userInput = ''; // Clear the input after adding
          }
        });

      // ListView to Display Inputs
      List() {
        ForEach(this.inputList, (input: string, index: number) => {
          ListItem() {
            Text(input)
              .fontSize(16)
              .padding(10)
              .backgroundColor('#f0f0f0')
              .borderRadius(5);
          }
          .margin({ bottom: 10 });
        });
      }
      .width('100%')
      .height('60%')
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

