@Component
struct ImageCarouselWithIndicators {
  private swiperController: SwiperController = new SwiperController();

  @State carouselItems: Array<CarouselItem> = [
    new CarouselItem(1, $r('app.media.app_icon')),
    new CarouselItem(2, $r('app.media.app_icon')),
    new CarouselItem(3, $r('app.media.app_icon')),
    new CarouselItem(4, $r('app.media.app_icon'))
  ];

  @State currentIndex: number = 0;

  build() {
    Column() {
      Text('Image Carousel with Indicators')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Column() {
        Swiper(this.swiperController) {
          ForEach(this.carouselItems, (item: CarouselItem) => {
            Stack() {
              Image(item.image)
                .width('100%')
                .height(300)
                .objectFit(ImageFit.Cover)
                .borderRadius(16);
            }
          });
        }
        .width('100%')
        .height(300)
        .margin({ bottom: 16 })
        .autoPlay(true)
        .interval(3000)
        .indicator(false)
        .loop(true)
        .duration(500)
        .onChange((index: number) => {
          this.currentIndex = index;
        });

        Row() {
          ForEach(this.carouselItems, (item: CarouselItem, index: number) => {
            Circle()
              .width(10)
              .height(10)
              .backgroundColor(index === this.currentIndex ? Color.Blue : Color.Gray)
              .margin(5);
          });
        }
        .justifyContent(FlexAlign.Center)
        .margin({ top: 8 });
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(20);

      Row() {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });

        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

