@Entry
@Component
struct CustomLoadingScreen {
    @State rotation: number = 0
    @State progress: number = 0
    private intervalID: number = -1

    aboutToAppear() {
        this.intervalID = setInterval(() => {
            this.rotation = (this.rotation + 10) % 360
            this.progress = (this.progress + 1) % 101
        }, 50)
    }

    aboutToDisappear() {
        if (this.intervalID !== -1) {
            clearInterval(this.intervalID)
        }
    }

    build() {
        Column() {
            Stack() {
                Image($r('app.media.app_icon'))
                    .width(100)
                    .height(100)
                    .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })
                Circle()
                    .width(120)
                    .height(120)
                    .stroke($r('sys.color.ohos_id_color_primary'))
                    .strokeWidth(10)
                    .strokeDashArray([10, 20])
                    .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })
            }
            .width(120)
            .height(120)

            Progress({ value: this.progress, total: 100 })
                .width('80%')
                .height(10)
                .backgroundColor($r('sys.color.ohos_id_color_background'))
                .color($r('sys.color.ohos_id_color_primary'))

            Text(`Loading... ${this.progress}%`)
                .fontSize(20)
                .margin({ top: 20 })
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .backgroundColor($r('sys.color.ohos_id_color_background'))
    }
}

@Entry
@Component
struct RegistrationForm {
  @State username: string = ''
  @State password: string = ''
  @State confirmPassword: string = ''
  @State errorMessage: string = ''
  @State successMessage: string = ''

  validateForm(): boolean {
    if (!this.username || !this.password || !this.confirmPassword) {
      this.errorMessage = 'All fields are required'
      return false
    }
    if (this.password !== this.confirmPassword) {
      this.errorMessage = 'Passwords do not match'
      return false
    }
    this.errorMessage = ''
    return true
  }

  build() {
    Column() {
      Text('Registration')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your username' })
        .onChange((value: string) => {
          this.username = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Confirm your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.confirmPassword = value
        })
        .margin({ bottom: 20 })

      Button('Submit')
        .onClick(() => {
          if (this.validateForm()) {
            this.successMessage = 'Registration successful!'
            this.username = ''
            this.password = ''
            this.confirmPassword = ''
          }
        })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ bottom: 20 })
      }

      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(18)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

