@Entry
@Component
struct NonReadyImageHandler {
  @State isImageReady: boolean = false;
  @State errorMessage: string = '';
  @State showPlaceholder: boolean = true;

  build() {
    Column() {
      // Display placeholder while loading
      if (this.showPlaceholder) {
        Column() {
          LoadingProgress()
            .color(Color.Blue)
            .width(50)
            .height(50);
          Text('Loading image...')
            .margin({ top: 10 });
        }
        .onAppear(() => {
          // Simulate network delay
          setTimeout(() => {
            this.isImageReady = true;
            this.showPlaceholder = false;
          }, 2000);
        });
      }

      // Display the image when loaded
      if (this.isImageReady && !this.errorMessage) {
        Image($r('app.media.app_icon'))
          .width(200)
          .height(200)
          .onError(() => {
            this.errorMessage = 'Failed to load image';
            this.isImageReady = false;
          });
      }

      // Display error message if any
      if (this.errorMessage) {
        Column() {
          Image($r('app.media.app_icon')) // Fallback image
            .width(100)
            .height(100);
          Text(this.errorMessage)
            .fontColor(Color.Red)
            .margin({ top: 10 });
          Button('Retry')
            .onClick(() => {
              this.errorMessage = '';
              this.showPlaceholder = true;
            })
            .margin({ top: 20 });
        }
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

