@Entry
@Component
struct CustomFloatingActionButton {
  @State isPressed: boolean = false;
  @State buttonColor: Color = Color.Blue;
  @State buttonSize: number = 60;

  build() {
    Column() {
      Button() {
        Image($r('app.media.app_icon'))
          .width(40)
          .height(40)
      }
      .width(this.buttonSize)
      .height(this.buttonSize)
      .backgroundColor(this.buttonColor)
      .borderRadius(this.buttonSize / 2)
      .onClick(() => {
        this.isPressed = !this.isPressed;
        this.buttonColor = this.isPressed ? Color.Red : Color.Blue;
        this.buttonSize = this.isPressed ? 80 : 60;
      })
      .animation({
        duration: 300,
        curve: Curve.EaseInOut
      })
      .margin({ bottom: 20 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.End)
    .padding(20)
    .backgroundColor(Color.White)
  }
}

import promptAction from '@ohos.promptAction';

@Entry
@Component
struct UserRegistrationForm {
  @State name: string = '';
  @State email: string = '';
  @State password: string = '';
  @State showDialog: boolean = false;

  build() {
    Column() {
      // Form Title
      Text('User Registration')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      // Name Input
      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value;
          });
      }

      // Email Input
      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value;
          });
      }

      // Password Input
      Column() {
        Text('Password:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your password' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .type(InputType.Password)
          .onChange((value: string) => {
            this.password = value;
          });
      }

      // Submit Button
      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.name && this.email && this.password) {
            this.showDialog = true;
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields'
            });
          }
        });

      // Dialog
      if (this.showDialog) {
        Column() {
          Text('Registration Successful')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Name: ${this.name}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text('Password: ********')
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.showDialog = false;
              // Clear form fields after submission
              this.name = '';
              this.email = '';
              this.password = '';
            });
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

