@Entry
@Component
struct ImageCarousel {
  private swiperController: SwiperController = new SwiperController();

  private carouselItems: CarouselItem[] = [
    {
      id: 1,
      image: $r('app.media.app_icon'),
      caption: 'Mountain View'
    },
    {
      id: 2,
      image: $r('app.media.app_icon'),
      caption: 'Ocean Sunset'
    },
    {
      id: 3,
      image: $r('app.media.app_icon'),
      caption: 'Forest Path'
    },
    {
      id: 4,
      image: $r('app.media.app_icon'),
      caption: 'Desert Dunes'
    }
  ];

  @State currentIndex: number = 0;

  build() {
    Column() {
      Text('Image Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Column() {
        Swiper(this.swiperController) {
          ForEach(this.carouselItems, (item: CarouselItem) => {
            Stack() {
              Image(item.image)
                .width('100%')
                .height(300)
                .objectFit(ImageFit.Cover)
                .borderRadius(16);
            }
          });
        }
        .width('100%')
        .height(300)
        .margin({ bottom: 16 })
        .autoPlay(true)
        .interval(3000)
        .indicator(true)
        .loop(true)
        .duration(500)
        .onChange((index: number) => {
          this.currentIndex = index;
        });

        Text(this.carouselItems[this.currentIndex].caption)
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 8 })
          .textAlign(TextAlign.Center);
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(20);

      Row() {
        Button('Previous')
          .onClick(() => {
            if (this.swiperController) {
              this.swiperController.showPrevious();
            }
          });

        Button('Next')
          .onClick(() => {
            if (this.swiperController) {
              this.swiperController.showNext();
            }
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

interface CarouselItem {
  id: number;
  image: Resource;
  caption: string;
}

@Entry
@Component
struct RegistrationForm {
  @State name: string = ''
  @State email: string = ''
  @State password: string = ''
  @State errorMessage: string = ''
  @State successMessage: string = ''

  validateEmail(email: string): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return emailRegex.test(email)
  }

  validatePassword(password: string): boolean {
    return password.length >= 8
  }

  validateForm(): boolean {
    if (!this.name || !this.email || !this.password) {
      this.errorMessage = 'All fields are required'
      return false
    }
    if (!this.validateEmail(this.email)) {
      this.errorMessage = 'Invalid email format'
      return false
    }
    if (!this.validatePassword(this.password)) {
      this.errorMessage = 'Password must be at least 8 characters long'
      return false
    }
    this.errorMessage = ''
    return true
  }

  build() {
    Column({ space: 20 }) {
      Text('Registration Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your name' })
        .onChange((value: string) => {
          this.name = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your email' })
        .onChange((value: string) => {
          this.email = value
        })
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .margin({ bottom: 20 })

      Button('Submit')
        .onClick(() => {
          if (this.validateForm()) {
            this.successMessage = 'Registration successful!'
            this.name = ''
            this.email = ''
            this.password = ''
          }
        })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ bottom: 20 })
      }

      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(18)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct LoginPage {
  @State email: string = ''
  @State password: string = ''
  @State loginMessage: string = ''
  @State isSuccess: boolean = false

  build() {
    Column() {
      // Email Input
      Text('Email')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your email', text: this.email })
        .onChange((value: string) => {
          this.email = value
        })
        .width('100%')
        .height(40)
        .margin({ bottom: 20 })
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })

      // Password Input
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('100%')
        .height(40)
        .margin({ bottom: 30 })
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })

      // Login Button
      Button('Login')
        .onClick(() => {
          if (this.validateEmail(this.email) && this.password.length > 0) {
            this.loginMessage = 'Login successful!'
            this.isSuccess = true
          } else {
            this.loginMessage = 'Invalid email or password'
            this.isSuccess = false
          }
        })
        .width('100%')
        .height(50)
        .backgroundColor('#007AFF')
        .fontSize(18)
        .fontColor(Color.White)

      // Login Message
      if (this.loginMessage) {
        Text(this.loginMessage)
          .fontSize(16)
          .margin({ top: 20 })
          .fontColor(this.isSuccess ? Color.Green : Color.Red)
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }

  validateEmail(email: string) {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return re.test(email)
  }
}

@Entry
@Component
struct ImageSelectionGallery {
  @State selectedImages: string[] = [];
  dialogController: CustomDialogController = new CustomDialogController({
    builder: this.DialogBuilder,
    customStyle: true,
    alignment: DialogAlignment.Center
  });

  private images: string[] = [
    'app.media.app_icon1',
    'app.media.app_icon2',
    'app.media.app_icon3',
    'app.media.app_icon4',
    'app.media.app_icon5',
    'app.media.app_icon6',
    'app.media.app_icon7',
    'app.media.app_icon8',
    'app.media.app_icon9',
    'app.media.app_icon10'
  ];

  @Builder DialogBuilder() {
    Column() {
      Text(`You have selected ${this.selectedImages.length} images`)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 16, bottom: 8 });

      Button('OK')
        .width('100%')
        .height(40)
        .margin({ top: 24 })
        .onClick(() => {
          this.dialogController.close();
        });
    }
    .padding(24)
    .width('90%')
    .backgroundColor(Color.White)
    .borderRadius(16);
  }

  build() {
    Column() {
      Text('Image Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Grid() {
        ForEach(this.images, (image: string) => {
          GridItem() {
            Image(image)
              .width('100%')
              .aspectRatio(1)
              .objectFit(ImageFit.Cover)
              .borderRadius(5)
              .onClick(() => {
                if (this.selectedImages.includes(image)) {
                  this.selectedImages = this.selectedImages.filter(img => img !== image);
                } else {
                  this.selectedImages.push(image);
                }
              })
              .border({ width: this.selectedImages.includes(image) ? 2 : 0, color: Color.Blue });
          }
        });
      }
      .columnsTemplate('1fr 1fr 1fr')
      .rowsGap(10)
      .columnsGap(10)
      .padding(10);

      Button('Show Selected Count')
        .onClick(() => {
          this.dialogController.open();
        })
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5');
  }
}

