    { image: $r('app.media.app_icon'), title: 'Image 6', description: 'This is the sixth image.' }
  ]

  build() {
    Column() {
      if (this.showDetailView) {
        Stack() {
          Column() {
            Image(this.selectedImage)
              .objectFit(ImageFit.Contain)
              .width('100%')
              .height('60%')
              .margin({ top: 20 })

            Text(this.imageTitle)
              .fontSize(24)
              .fontWeight(FontWeight.Bold)
              .margin({ top: 16 })

            Text(this.imageDescription)
              .fontSize(16)
              .margin({ top: 8 })

            Button('Back')
              .onClick(() => {
                this.showDetailView = false
              })
              .margin({ top: 20 })
              .width('50%')
              .height(40)
              .backgroundColor('#007AFF')
              .fontColor(Color.White)
              .borderRadius(8)
          }
          .width('100%')
          .height('100%')
          .backgroundColor('#F5F5F5')
        }
      } else {
        Grid() {
          ForEach(this.images, (item: ImageItem) => {
            GridItem() {
              Column() {
                Image(item.image)
                  .width('100%')
                  .aspectRatio(1)
                  .objectFit(ImageFit.Cover)
                  .borderRadius(8)
                  .onClick(() => {
                    this.selectedImage = item.image
                    this.imageTitle = item.title
                    this.imageDescription = item.description
                    this.showDetailView = true
                  })

                Text(item.title)
                  .fontSize(16)
                  .fontWeight(FontWeight.Medium)
                  .margin({ top: 8 })
              }
              .backgroundColor(Color.White)
              .borderRadius(12)
              .padding(8)
            }
          })
        }
        .columnsTemplate('1fr 1fr')
        .rowsGap(16)
        .columnsGap(16)
        .padding(16)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

