import promptAction from '@ohos.promptAction'

@Entry
@Component
struct GreetingApp {
  @State name: string = ''
  @State age: string = ''
  @State showGreeting: boolean = false
  @State birthYear: number = 0

  build() {
    Column() {
      Text('User Greeting Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 })

      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value
          })
      }

      Column() {
        Text('Age:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your age' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.age = value
          })
      }

      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.name && this.age) {
            this.showGreeting = true
            const currentYear = new Date().getFullYear()
            this.birthYear = currentYear - parseInt(this.age)
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields'
            })
          }
        })

      if (this.showGreeting) {
        Text(`Hello, ${this.name}! You were born in ${this.birthYear}.`)
          .fontSize(20)
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
  }
}

@Entry
@Component
struct LoginScreen {
  @State email: string = ''
  @State password: string = ''
  @State message: string = ''
  @State isSuccess: boolean = false

  build() {
    Column() {
      // Email Input
      Text('Email:')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your email' })
        .width('80%')
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.email = value
        })

      // Password Input
      Text('Password:')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .width('80%')
        .margin({ bottom: 20 })
        .onChange((value: string) => {
          this.password = value
        })

      // Login Button
      Button('Login')
        .onClick(() => {
          if (this.validateEmail(this.email) && this.password.length > 0) {
            this.message = 'Login successful!'
            this.isSuccess = true
          } else {
            this.message = 'Invalid email or password.'
            this.isSuccess = false
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      // Message Display
      if (this.message) {
        Text(this.message)
          .fontSize(16)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20 })
          .fontColor(this.isSuccess ? Color.Green : Color.Red)
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }

  validateEmail(email: string): boolean {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return re.test(email)
  }
}

