@Entry
@Component
struct ErrorBoundaryComponent {
  @State hasError: boolean = false;
  @State error: Error | null = null;

  build() {
    Column() {
      if (this.hasError && this.error) {
        this.fallbackUI();
      } else {
        this.childComponents();
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }

  @Builder
  fallbackUI() {
    Column() {
      Text('Something went wrong').fontSize(20).margin(10);
      Text(`Error: ${this.error?.message}`).fontSize(16).margin(5);
      Button('Retry').onClick(() => {
        this.hasError = false;
        this.error = null;
      }).margin(10);
    }
  }

  @Builder
  childComponents() {
    Column() {
      Button('Trigger Error').onClick(() => {
        throw new Error('Test error');
      }).margin(10);
    }
  }
}

import promptAction from '@ohos.promptAction';

interface Theme {
  name: string;
  bgColor: string;
  textColor: string;
  buttonColor: string;
}

@Entry
@Component
export struct ThemePresetsWithCustomization {
  @State selectedTheme: string = 'Default';
  @State bgColor: string = '#FFFFFF';
  @State textColor: string = '#000000';
  @State buttonColor: string = '#007BFF';
  @State showCustomization: boolean = false;
  @State customBgColor: string = '#FFFFFF';
  @State customTextColor: string = '#000000';
  @State customButtonColor: string = '#007BFF';

  private themes: Theme[] = [
    { name: 'Default', bgColor: '#FFFFFF', textColor: '#000000', buttonColor: '#007BFF' },
    { name: 'Dark', bgColor: '#121212', textColor: '#FFFFFF', buttonColor: '#BB86FC' },
    { name: 'Light', bgColor: '#F5F5F5', textColor: '#333333', buttonColor: '#6200EE' },
    { name: 'Ocean', bgColor: '#E0F7FA', textColor: '#00695C', buttonColor: '#00BCD4' },
    { name: 'Sunset', bgColor: '#FFF3E0', textColor: '#E65100', buttonColor: '#FF9800' }
  ];

  applyTheme(theme: Theme) {
    this.selectedTheme = theme.name;
    this.bgColor = theme.bgColor;
    this.textColor = theme.textColor;
    this.buttonColor = theme.buttonColor;
    promptAction.showToast({ message: `Theme ${theme.name} applied` });
    if (this.showCustomization) {
      this.showCustomization = false;
    }
  }

  applyCustomTheme() {
    this.bgColor = this.customBgColor;
    this.textColor = this.customTextColor;
    this.buttonColor = this.customButtonColor;
    this.selectedTheme = 'Custom';
    promptAction.showToast({ message: 'Custom Theme Applied' });
    this.showCustomization = false;
  }

  build() {
    Column({ space: 20 }) {
      if (!this.showCustomization) {
        Text('Select a Theme')
          .fontSize(24)
          .fontColor(this.textColor)
          .margin({ bottom: 20 });

        ForEach(this.themes, (theme: Theme) => {
          Button(theme.name)
            .backgroundColor(this.buttonColor)
            .fontColor(this.textColor)
            .onClick(() => this.applyTheme(theme))
            .margin({ bottom: 10 });
        });

        Button('Customize Theme')
          .backgroundColor(this.buttonColor)
          .fontColor(this.textColor)
          .onClick(() => {
            this.showCustomization = true;
          });
      } else {
        Text('Customize Theme')
          .fontSize(24)
          .fontColor(this.textColor)
          .margin({ bottom: 20 });

        TextInput({ placeholder: 'Background Color (e.g., #FFFFFF)' })
          .width('80%')
          .height(50)
          .backgroundColor('#FFFFFF')
          .margin({ bottom: 10 })
          .onChange((value: string) => {
            this.customBgColor = value;
          });

        TextInput({ placeholder: 'Text Color (e.g., #000000)' })
          .width('80%')
          .height(50)
          .backgroundColor('#FFFFFF')
          .margin({ bottom: 10 })
          .onChange((value: string) => {
            this.customTextColor = value;
          });

        TextInput({ placeholder: 'Button Color (e.g., #007BFF)' })
          .width('80%')
          .height(50)
          .backgroundColor('#FFFFFF')
          .margin({ bottom: 10 })
          .onChange((value: string) => {
            this.customButtonColor = value;
          });

        Button('Apply Custom Theme')
          .backgroundColor(this.buttonColor)
          .fontColor(this.textColor)
          .onClick(() => this.applyCustomTheme())
          .margin({ bottom: 20 });

        Button('Back to Themes')
          .backgroundColor(this.buttonColor)
          .fontColor(this.textColor)
          .onClick(() => {
            this.showCustomization = false;
          });
      }

      Text(`Current Theme: ${this.selectedTheme}`)
        .fontSize(18)
        .fontColor(this.textColor);
    }
    .width('100%')
    .height('100%')
    .backgroundColor(this.bgColor)
    .padding(20);
  }
}

