              .margin({ top: 5, bottom: 5 })
              .onAppear(() => {
                console.info(`Item ${index} has become visible.`);
              })
              .onDisAppear(() => {
                console.info(`Item ${index} is no longer visible.`);
              })
          }
        })
      }
      .onScrollIndex((startIndex: number, endIndex: number) => {
        this.visibleItems = this.allItems.slice(startIndex, endIndex + 1);
