      .onScrollVisibleContentChange((start: VisibleListContentInfo, end: VisibleListContentInfo) => {
        console.info(`Visible content changed from index ${start.index} to ${end.index}.`);
      })
      .width('100%')
      .height('100%')
      .backgroundColor(0xFFFFFF)
    }
    .width('100%')
    .height('100%')
