@Entry
@Component
struct SwipeRefreshStateToggle {
  @State isRefreshing: boolean = false;
  @State refreshState: string = 'idle';
  @State showAction: boolean = false;

  build() {
    Column() {
      Text(`Current State: ${this.refreshState}`)
        .fontSize(16)
        .margin(10)
        .fontColor(Color.Blue)

      Refresh({ refreshing: $$this.isRefreshing }) {
        List() {
          ForEach(['Item 1', 'Item 2', 'Item 3'], (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(16)
                .padding(10)
            }
          })
        }
        .height('70%')
      }
      .onStateChange((newState: RefreshStatus) => {
        switch(newState) {
          case RefreshStatus.Inactive:
            this.refreshState = 'inactive';
            break;
          case RefreshStatus.Drag:
            this.refreshState = 'dragging';
            break;
          case RefreshStatus.OverDrag:
            this.refreshState = 'overdrag';
            break;
          case RefreshStatus.Refresh:
            this.refreshState = 'refreshing';
            this.showAction = true;
            break;
          case RefreshStatus.Done:
            this.refreshState = 'completed';
            this.showAction = false;
            break;
        }
        console.log(`Refresh state changed to: ${this.refreshState}`);
      })
      .onRefreshing(() => {
        this.isRefreshing = true;
        setTimeout(() => {
          this.isRefreshing = false;
        }, 2000);
      })

      if (this.showAction) {
        Image($r('app.media.app_icon'))
          .width(50)
          .height(50)
          .margin(10)
      }
    }
    .width('100%')
    .height('100%')
  }
}

