      Text(`Last Refresh: ${this.lastRefreshTime}`)
        .fontSize(16)
        .margin(5);

      Refresh({ refreshing: $$this.isRefreshing }) {
        Column() {
          Text(this.getPullText())
            .fontSize(18)
            .margin(10);
        }
        .width('100%')
        .height(100);
      }
      .onStateChange((refreshStatus: RefreshStatus) => {
        switch (refreshStatus) {
          case RefreshStatus.Inactive:
            this.refreshState = 'Idle';
            break;
          case RefreshStatus.Drag:
            this.refreshState = 'Dragging';
            break;
          case RefreshStatus.OverDrag:
            this.refreshState = 'Ready to Refresh';
            break;
          case RefreshStatus.Refresh:
            this.refreshState = 'Refreshing';
            this.refreshCount += 1;
            this.lastRefreshTime = new Date().toLocaleTimeString();
            break;
          default:
            this.refreshState = 'Complete';
            setTimeout(() => {
              this.refreshState = 'Idle';
            }, 1000);
        }
      })
      .onRefreshing(() => {
        setTimeout(() => {
          this.isRefreshing = false;
        }, 2000);
      });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }

  private getStateColor(): string {
    switch (this.refreshState) {
      case 'Idle': return '#666666';
      case 'Dragging': return '#0099FF';
      case 'Ready to Refresh': return '#00CC66';
      case 'Refreshing': return '#FF9900';
      case 'Complete': return '#00CC66';
      default: return '#000000';
    }
  }

  private getPullText(): string {
    switch (this.refreshState) {
      case 'Idle': return 'Pull down to refresh';
      case 'Dragging': return 'Keep pulling...';
      case 'Ready to Refresh': return 'Release to refresh';
      case 'Refreshing': return 'Refreshing...';
      case 'Complete': return 'Refresh complete!';
      default: return 'Pull to refresh';
    }
  }
}

@Entry
@Component
struct DebounceRefreshExample {
    @State private data: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4', 'Item 5'];
    private lastRefreshTime: number = 0;
    private debounceTime: number = 1000; // 1 second debounce time
    @State private isRefreshing: boolean = false;

    build() {
        Column() {
            Refresh({ refreshing: this.isRefreshing }) {
                List({ space: 20 }) {
                    ForEach(this.data, (item: string) => {
                        ListItem() {
                            Text(item)
                                .width('100%')
                                .height(150)
                                .fontSize(20)
                                .textAlign(TextAlign.Center)
                                .backgroundColor('#95efd2')
                        }
                    })
                }
                .backgroundColor('#eeeeee')
                .divider({ strokeWidth: 1, color: 0x222222 })
                .edgeEffect(EdgeEffect.Spring)
            }
            .onStateChange(() => {
                this.handleRefresh();
            })

            Button('Manual Refresh')
                .onClick(() => {
                    this.handleRefresh();
                })
                .margin({ top: 20 })
        }
        .width('100%')
        .height('100%')
        .padding(20)
    }

    private handleRefresh() {
        const currentTime = new Date().getTime();
        if (currentTime - this.lastRefreshTime > this.debounceTime) {
            this.lastRefreshTime = currentTime;
            this.isRefreshing = true;
            setTimeout(() => {
                this.data = [...this.data, `Item ${this.data.length + 1}`];
                this.isRefreshing = false;
            }, 1000); // Simulate network delay
        }
    }
}

@Entry
@Component
struct SnapshotApp {
  @State private imageSrc: string = 'app.media.app_icon';
  @State private snapshotData: string = '';

  private async captureSnapshot(): Promise<void> {
    try {
      const media = new Media();
      const snapshot: ImagePixelMap = await media.createPixelMap(this.imageSrc);
      this.snapshotData = snapshot.toDataURL();
    } catch (error) {
      console.error('Failed to capture snapshot:', error.message);
    }
  }

  build() {
    Column() {
      Image(this.imageSrc)
        .width(100)
        .height(100)
        .onClick(async () => {
          await this.captureSnapshot();
        });

      if (this.snapshotData) {
        Image(this.snapshotData)
          .width(100)
          .height(100);
      } else {
        Text('No snapshot available')
          .fontSize(16)
          .margin(10);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

class Media {
  async createPixelMap(imageSrc: string): Promise<ImagePixelMap> {
    return new ImagePixelMap();
  }
}

class ImagePixelMap {
  toDataURL(): string {
    return 'data:image/png;base64,...';
  }
}

