@Component
struct BackwardCompatibilityDemo {
  @State private currentVersion: string = "1.0.0";
  @State private supportedVersions: string[] = ["1.0.0", "1.1.0", "1.2.0"];
  @State private isLegacyMode: boolean = false;

  build() {
    Column() {
      Text(`Current Version: ${this.currentVersion}`)
        .fontSize(20)
        .margin(10);

      Text("Supported Versions:")
        .fontSize(18)
        .margin(10);

      List({ space: 10 }) {
        ForEach(this.supportedVersions, (version: string) => {
          ListItem() {
            Text(version)
              .fontSize(16)
              .margin(5);
          }
        });
      }

      Toggle({ type: ToggleType.Switch, isOn: this.isLegacyMode })
        .onChange((isOn: boolean) => {
          this.isLegacyMode = isOn;
          console.log(`Legacy Mode ${isOn ? "enabled" : "disabled"}`);
        })
        .margin(20);

      Button("Check Compatibility")
        .onClick(() => {
          this.checkCompatibility();
        })
        .margin(20);

      if (this.isLegacyMode) {
        Text("Running in Legacy Mode - Backward Compatibility Enabled")
          .fontSize(16)
          .margin(10)
          .fontColor('#FF0000');
      } else {
        Text("Running in Latest Mode - Using New Features")
          .fontSize(16)
          .margin(10)
          .fontColor('#00AA00');
      }
    }
    .padding(20)
    .width('100%')
    .height('100%');
  }

  private checkCompatibility() {
    const latestVersion = "1.2.0";
    if (this.currentVersion !== latestVersion) {
      AlertDialog.show({
        title: "Compatibility Check",
        message: `Your current version (${this.currentVersion}) is outdated. Enable Legacy Mode for backward compatibility?`,
        confirm: {
          value: "Enable",
          action: () => {
            this.isLegacyMode = true;
            console.log("Legacy Mode enabled for backward compatibility.");
          }
        },
        cancel: () => {
          console.log("Legacy Mode disabled.");
        }
      });
    } else {
      console.log("Your app is up to date. No compatibility issues detected.");
    }
  }
}

