    this.selectedIndex = index;
  }

  build() {
    Column() {
      Row({ space: 5 }) {
        ForEach(this.tabLabels, (label: string, index: number) => {
          Button(label)
            .backgroundColor(this.selectedIndex === index ? '#007DFF' : '#F1F3F5')
            .fontColor(this.selectedIndex === index ? '#FFFFFF' : '#182431')
            .borderRadius(5)
            .padding(10)
            .onClick(() => this.handleTabChange(index));
        })
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .margin({ top: 20 });

      if (this.selectedIndex === 0) {
        Text('Content for Tab 1')
          .fontSize(20)
          .margin({ top: 20 });
      } else if (this.selectedIndex === 1) {
        Text('Content for Tab 2')
          .fontSize(20)
          .margin({ top: 20 });
      } else {
        Text('Content for Tab 3')
          .fontSize(20)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#FFFFFF');
  }
}

@Entry
@Component
struct PopMethodAndDisplayExample {
  @State options: string[] = ['Option A', 'Option B', 'Option C', 'Option D', 'Option E'];
  @State selectedOption: string = '';
  @State isPopupVisible: boolean = false;

  build() {
    Column() {
      // Display the remaining options as a list
      ForEach(this.options, (option: string, index: number) => {
        Text(option)
          .fontSize(16)
          .fontColor(Color.Black)
          .margin(10)
          .onClick(() => {
            this.selectedOption = option;
            this.options.splice(index, 1); // Remove the selected option
          });
      });

      // Button to toggle the popup for additional options
      Button('Show Remaining Options')
        .onClick(() => {
          this.isPopupVisible = true;
        })
        .margin(20);

      // Display the selected option
      Text('Selected: ' + this.selectedOption)
        .fontSize(20)
        .fontColor(Color.Blue)
        .margin(20);

      // Button to reset all options
      Button('Reset Options')
        .onClick(() => {
          this.options = ['Option A', 'Option B', 'Option C', 'Option D', 'Option E'];
          this.selectedOption = '';
        })
        .margin(20);

      // Popup to display remaining options
      if (this.isPopupVisible) {
        Column() {
          ForEach(this.options, (option: string) => {
            Text(option)
              .fontSize(18)
              .padding(10)
              .onClick(() => {
                this.selectedOption = option;
                this.isPopupVisible = false;
              });
          });
          Button('Close')
            .onClick(() => {
              this.isPopupVisible = false;
            })
            .margin(10);
        }
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(10)
        .shadow({ radius: 5 })
        .margin({ top: 10 });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

