@Entry
@Component
struct InteractionStateVisualization {
  @State isActive: boolean = false;
  @State scaleValue: number = 1;
  @State rotationAngle: number = 0;
  @State timerId: number = -1;

  aboutToAppear() {
    this.startTimer();
  }

  aboutToDisappear() {
    this.stopTimer();
  }

  startTimer() {
    this.timerId = setInterval(() => {
      this.isActive = !this.isActive;
      if (!this.isActive) {
        this.scaleValue = 1;
        this.rotationAngle = 0;
      }
    }, 2000);
  }

  stopTimer() {
    if (this.timerId !== -1) {
      clearInterval(this.timerId);
      this.timerId = -1;
    }
  }

  build() {
    Column() {
      Text('Interaction States Fixation & Transition Visualization')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Row()
        .width(200)
        .height(200)
        .backgroundColor(Color.Blue)
        .borderRadius(10)
        .gesture(
          GestureGroup(
            GestureMode.Parallel,
            PanGesture({ direction: PanDirection.All })
              .onActionUpdate((event: GestureEvent) => {
                this.isActive = true;
              }),
            PinchGesture()
              .onActionUpdate((event: PinchGestureEvent) => {
                this.scaleValue = event.scale;
              }),
            RotationGesture()
              .onActionUpdate((event: RotationGestureEvent) => {
                this.rotationAngle = event.angle;
              })
          )
        )
        .transform({ scale: { x: this.scaleValue, y: this.scaleValue }, rotate: { angle: this.rotationAngle } })
        .animation({ duration: 300, curve: Curve.EaseInOut });

      Button(this.isActive ? 'Reset' : 'Activate')
        .onClick(() => {
          this.isActive = !this.isActive;
          if (!this.isActive) {
            this.scaleValue = 1;
            this.rotationAngle = 0;
          }
        })
        .margin(20)
        .width(200);

      Button(this.timerId === -1 ? 'Start Timer' : 'Stop Timer')
        .onClick(() => {
          if (this.timerId === -1) {
            this.startTimer();
          } else {
            this.stopTimer();
          }
        })
        .margin(20)
        .width(200);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

