@Entry
@Component
struct ImageGallery {
  @State images: string[] = ['image1', 'image2', 'image3'];
  @State searchText: string = '';
  @State selectedImage: string = '';
  @State showDialog: boolean = false;

  controller: CustomDialogController = new CustomDialogController({
    builder: this.imageDetailDialog,
    alignment: DialogAlignment.Center,
    cancel: () => {
      this.showDialog = false;
    }
  });

  @Builder
  imageDetailDialog() {
    Image(this.selectedImage)
      .objectFit(ImageFit.Contain)
      .width('100%')
      .height('100%');
  }

  build() {
    Column() {
      TextInput({ placeholder: 'Search images' })
        .onChange((value: string) => {
          this.searchText = value;
        })
        .width('80%')
        .margin(10);

      Grid() {
        ForEach(this.images, (image: string) => {
          GridItem() {
            Image(image)
              .width(100)
              .height(100)
              .onClick(() => {
                this.selectedImage = image;
                this.showDialog = true;
                this.controller.open();
              });
          }
        });
      }
      .columnsGap(10)
      .rowsGap(10)
      .columnsTemplate('1fr 1fr 1fr');
    }
    .width('100%')
    .height('100%');
  }
}

import promptAction from '@ohos.promptAction';

@Entry
@Component
struct LoginForm {
  @State username: string = '';
  @State password: string = '';
  @State showDialog: boolean = false;

  build() {
    Column() {
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your username' })
        .onChange((value: string) => {
          this.username = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value;
        })
        .width('80%')
        .margin({ bottom: 20 });

      Button('Submit')
        .onClick(() => {
          if (this.username && this.password) {
            this.showDialog = true;
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields'
            });
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White);

      if (this.showDialog) {
        Column() {
          Text('Submitted Information')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Username: ${this.username}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Password: ${this.password}`)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.showDialog = false;
              this.username = '';
              this.password = '';
            });
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center);
  }
}

