@Entry
@Component
struct ModelTypeEnhancement {
  @State private modelType: string = "DefaultModel";
  @State private dependencies: Array<string> = ["Dep1", "Dep2", "Dep3"];
  @State private enhancedDependencies: Array<string> = [];
  @State private serviceData: string = "";

  private appContext = AppContext.getInstance();

  build() {
    Column() {
      Text(`Current Model Type: ${this.modelType}`)
        .fontSize(20)
        .margin(10);

      Text("Dependencies:")
        .fontSize(18)
        .margin(10);

      List({ space: 10 }) {
        ForEach(this.dependencies, (dep: string) => {
          ListItem() {
            Text(dep)
              .fontSize(16)
              .margin(5);
          }
        });
      }

      Button("Enhance Dependencies")
        .onClick(() => {
          this.enhanceDependencies();
        })
        .margin(20);

      Text("Enhanced Dependencies:")
        .fontSize(18)
        .margin(10);

      List({ space: 10 }) {
        ForEach(this.enhancedDependencies, (enhancedDep: string) => {
          ListItem() {
            Text(enhancedDep)
              .fontSize(16)
              .margin(5);
          }
        });
      }

      Button("Fetch Service Data")
        .onClick(() => {
          const myService = this.appContext.getService('myService');
          if (myService) {
            this.serviceData = myService.getData();
          }
        })
        .margin(20);

      Text(this.serviceData)
        .fontSize(18)
        .margin(10);
    }
    .padding(20)
    .width('100%')
    .height('100%');
  }

  private enhanceDependencies() {
    this.enhancedDependencies = this.dependencies.map(dep => `Enhanced_${dep}`);
  }
}

interface MyService {
  getData(): string;
}

class MyServiceImpl implements MyService {
  getData(): string {
    return "Data from MyService";
  }
}

class AppContext {
  private static instance: AppContext;
  private services: Map<string, MyService> = new Map();

  private constructor() {}

  static getInstance(): AppContext {
    if (!AppContext.instance) {
      AppContext.instance = new AppContext();
    }
    return AppContext.instance;
  }

  registerService(key: string, service: MyService): void {
    this.services.set(key, service);
  }

  getService(key: string): MyService | undefined {
    return this.services.get(key);
  }
}

const appContext = AppContext.getInstance();
appContext.registerService('myService', new MyServiceImpl());

@Entry
@Component
struct CalendarApp {
  @State events: Array<CalendarEvent> = []
  @State newEventDate: string = ''
  @State newEventTime: string = ''
  @State newEventTitle: string = ''

  build() {
    Column() {
      // Header
      Text('Calendar App')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      // Event List
      List() {
        ForEach(this.events, (event: CalendarEvent, index: number) => {
          ListItem() {
            Column() {
              Text(`Date: ${event.date}`)
                .fontSize(18)
                .fontWeight(FontWeight.Medium)
              Text(`Time: ${event.time}`)
                .fontSize(16)
              Text(`Title: ${event.title}`)
                .fontSize(16)
                .fontWeight(FontWeight.Bold)
            }
            .padding(16)
            .borderRadius(12)
            .backgroundColor('#F0F0F0')
            .margin({ bottom: 10 })
          }
        })
      }
      .layoutWeight(1)
      .width('100%')

      // Add Event Form
      Column() {
        Text('Add New Event')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ bottom: 10 })

        TextInput({ placeholder: 'Date (YYYY-MM-DD)' })
          .onChange((value: string) => {
            this.newEventDate = value
          })
          .margin({ bottom: 10 })

        TextInput({ placeholder: 'Time (HH:MM)' })
          .onChange((value: string) => {
            this.newEventTime = value
          })
          .margin({ bottom: 10 })

        TextInput({ placeholder: 'Title' })
          .onChange((value: string) => {
            this.newEventTitle = value
          })
          .margin({ bottom: 10 })

        Button('Add Event')
          .onClick(() => {
            if (this.newEventDate && this.newEventTime && this.newEventTitle) {
              this.events.push({
                date: this.newEventDate,
                time: this.newEventTime,
                title: this.newEventTitle
              })
              this.newEventDate = ''
              this.newEventTime = ''
              this.newEventTitle = ''
            }
          })
          .backgroundColor('#007AFF')
          .fontColor(Color.White)
          .padding(10)
          .borderRadius(8)
      }
      .padding(16)
      .backgroundColor(Color.White)
      .borderRadius(12)
      .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White)
  }
}

interface CalendarEvent {
  date: string
  time: string
  title: string
}

