@Entry
@Component
struct ImageGallery {
  @State imageItems: Array<ImageItem> = [
    new ImageItem(1, 'Image 1', $r('app.media.icon'), 'Description for Image 1'),
    new ImageItem(2, 'Image 2', $r('app.media.icon'), 'Description for Image 2'),
    new ImageItem(3, 'Image 3', $r('app.media.icon'), 'Description for Image 3'),
    new ImageItem(4, 'Image 4', $r('app.media.icon'), 'Description for Image 4'),
  ];

  @State selectedImage: ImageItem | null = null;

  private dialogController: CustomDialogController = new CustomDialogController({
    builder: this.DialogBuilder.bind(this),
    cancel: this.onDialogCancel.bind(this),
    autoCancel: true,
  });

  build() {
    Column() {
      Text('Image Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 24 });

      Grid() {
        ForEach(this.imageItems, (item: ImageItem) => {
          GridItem() {
            Column() {
              Image(item.image)
                .objectFit(ImageFit.Cover)
                .width('100%')
                .height(150)
                .borderRadius(12);
              Text(item.title)
                .fontSize(16)
                .margin({ top: 8 });
            }
            .padding(16)
            .backgroundColor(Color.White)
            .borderRadius(12)
            .onClick(() => {
              this.selectedImage = item;
              this.dialogController.open();
            });
          }
        }, (item: ImageItem) => item.id.toString());
      }
      .columnsTemplate('1fr 1fr')
      .columnsGap(16)
      .rowsGap(16)
      .width('100%');
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
    .padding(16);
  }

  @Builder
  DialogBuilder() {
    if (this.selectedImage) {
      Column() {
        Image(this.selectedImage.image)
          .width('100%')
          .height(300)
          .objectFit(ImageFit.Cover);
        Text(this.selectedImage.title)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 16 });
        Text(this.selectedImage.description)
          .fontSize(16)
          .lineHeight(24)
          .margin({ top: 8 });
        Button('Close')
          .margin({ top: 24 })
          .onClick(() => {
            this.dialogController.close();
          });
      }
      .padding(24)
      .backgroundColor(Color.White)
      .borderRadius(16);
    }
  }

  onDialogCancel() {
    this.selectedImage = null;
  }
}

class ImageItem {
