@Entry
@Component
struct SlideInPanel {
  @State isPanelVisible: boolean = false
  @State panelOffset: number = 300

  build() {
    Column() {
      Button('Toggle Panel')
        .onClick(() => {
          this.isPanelVisible = !this.isPanelVisible
          animateTo({
            duration: 500,
            curve: Curve.EaseInOut
          }, () => {
            this.panelOffset = this.isPanelVisible ? 0 : 300
          })
        })
        .margin(20)

      Stack() {
        Column() {
          Text('Slide-In Panel Content')
            .fontSize(20)
            .padding(10)
            .backgroundColor('#f0f0f0')
            .borderRadius(10)
        }
        .width('100%')
        .height('30%')
        .backgroundColor('#ffffff')
        .borderRadius(10)
        .translate({ x: 0, y: this.panelOffset })
        .animation({
          duration: 500,
          curve: Curve.EaseInOut
        })
      }
      .width('100%')
      .height('100%')
    }
    .width('100%')
    .height('100%')
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
  }
}

