@Entry
@Component
struct ConditionalClickHandler {
  @State isActive: boolean = false;

  build() {
    Column() {
      Button(this.isActive ? "Deactivate" : "Activate")
        .onClick(() => {
          this.isActive = !this.isActive;
          this.handleClick();
        })
        .width(150)
        .height(50)
        .backgroundColor(this.isActive ? Color.Red : Color.Green)
        .fontColor(Color.White)
        .margin(10);

      if (this.isActive) {
        Text("Component is Active")
          .fontSize(20)
          .fontColor(Color.Green)
          .margin(10);
      } else {
        Text("Component is Inactive")
          .fontSize(20)
          .fontColor(Color.Red)
          .margin(10);
      }
    }
    .width("100%")
    .height("100%")
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }

  handleClick() {
