@Component
struct NoteApp {
  @State notes: Array<Note> = [];
  @State newTitle: string = '';
  @State newDescription: string = '';

  build() {
    Column({ space: 10 }) {
      TextInput({ placeholder: 'Enter title...', text: this.newTitle })
        .height(50)
        .width('90%')
        .onChange((value: string) => {
          this.newTitle = value;
        })
        .margin(10);

      TextArea({ placeholder: 'Enter description...', text: this.newDescription })
        .height(100)
        .width('90%')
        .onChange((value: string) => {
          this.newDescription = value;
        })
        .margin(10);

      Button('Add Note')
        .onClick(() => {
          if (this.newTitle.trim() && this.newDescription.trim()) {
            this.notes.push({
              id: Date.now(),
              title: this.newTitle,
              description: this.newDescription
            });
            this.newTitle = '';
            this.newDescription = '';
          }
        })
        .margin(10);

      List({ space: 10 }) {
        ForEach(this.notes, (note: Note) => {
          ListItem() {
            Column({ space: 5 }) {
              Text(note.title)
                .fontSize(18)
                .fontWeight(FontWeight.Bold)
                .margin({ bottom: 5 });

              Text(note.description)
                .fontSize(14)
                .margin({ bottom: 10 });

              Button('Delete')
                .onClick(() => {
                  this.notes = this.notes.filter(n => n.id !== note.id);
                })
                .width('100%')
                .margin({ top: 10 });
            }
            .padding(10)
            .width('100%')
            .backgroundColor('#f5f5f5')
            .borderRadius(8);
          }
        });
      }
      .width('100%')
      .height('70%');
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

