struct FoldedStateResponsiveLayout {
  @State isFolded: boolean = false;

  build() {
    Column() {
      Button(this.isFolded ? 'Unfold' : 'Fold')
        .onClick(() => {
          this.isFolded = !this.isFolded;
        })
        .margin(10)
        .width('90%')
        .height(50)

      if (this.isFolded) {
        Column() {
          Image($r('app.media.app_icon'))
            .width(100)
            .height(100)
            .margin(10)
          Text('Folded Content - Responsive Layout')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin(10)
          Text('This layout adapts to the folded state with compact content.')
            .fontSize(14)
            .margin(5)
