        .width('100%')
        .backgroundColor('#F0F0F0')
        .padding(10)
        .borderRadius(10)
        .margin(10)
      } else {
        Column() {
          Image($r('app.media.app_icon'))
            .width(200)
            .height(200)
            .margin(20)
          Text('Unfolded State - Full Content')
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
          Text('This layout shows all content in expanded state.')
            .fontSize(16)
            .margin(10)
        }
        .width('100%')
        .height('70%')
