@Entry
@Component
struct ColorSelectorApp {
  @State selectedColors: string[] = []
  private colors: string[] = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FF00FF', '#FFA500']

  build() {
    Column() {
      Text('Selected Colors:')
        .fontSize(20)
        .margin({ bottom: 10 })

      Flex({ wrap: FlexWrap.Wrap, justifyContent: FlexAlign.SpaceAround }) {
        ForEach(this.selectedColors, (color: string) => {
          Row()
            .width(50)
            .height(50)
            .backgroundColor(color)
            .borderRadius(25)
            .margin(5)
        })
      }
      .margin({ bottom: 20 })

      Flex({ wrap: FlexWrap.Wrap, justifyContent: FlexAlign.SpaceAround }) {
        ForEach(this.colors, (color: string) => {
          Button()
            .width(50)
            .height(50)
            .backgroundColor(color)
            .borderRadius(25)
            .onClick(() => {
              if (this.selectedColors.includes(color)) {
                this.selectedColors = this.selectedColors.filter(c => c !== color)
              } else {
                this.selectedColors = [...this.selectedColors, color]
              }
            })
            .margin(5)
        })
      }
    }
    .padding(20)
    .backgroundColor('#FFFFFF')
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct RotationGestureStateTransition {
  @State angle: number = 0;
  @State rotationText: string = "Rotation Angle: 0°";
  @State transitionActive: boolean = false;

  build() {
    Column({ space: 20 }) {
      Text(this.rotationText)
        .fontSize(20)
        .fontColor(Color.Black)

      Image($r("app.media.app_icon"))
        .width(100)
        .height(100)
        .rotate({ angle: this.angle })
        .gesture(
          RotationGesture()
            .onActionStart(() => {
              this.transitionActive = true;
              console.info("Rotation started");
            })
            .onActionUpdate((event: RotationGestureEvent) => {
              this.angle = event.angle;
              this.rotationText = `Rotation Angle: ${Math.round(this.angle)}°`;
            })
            .onActionEnd(() => {
              this.transitionActive = false;
              console.info("Rotation ended");
            })
        )
        .backgroundColor(this.transitionActive ? Color.Green : Color.White)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor(Color.Gray)
  }
}

