@Component
struct DoubleTapRecognition {
  @State tapCount: number = 0;
  @State message: string = "Double Tap to Recognize";

  build() {
    Column() {
      Text(this.message)
        .fontSize(24)
        .margin({ bottom: 20 });

      Text(`Tap Count: ${this.tapCount}`)
        .fontSize(18)
        .margin({ bottom: 20 });

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .gesture(
          TapGesture({ count: 2 })
            .onAction(() => {
              this.tapCount++;
              this.message = "Double Tap Recognized!";
              setTimeout(() => {
                this.message = "Double Tap to Recognize";
              }, 1000);
            })
        )
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

