@Component
struct TextSelectionChangeHandler {
  @State text: string = 'This is a sample text for text selection change handlers.'
  @State start: number = 0
  @State end: number = 12
  @State selectedText: string = ''

  build() {
    Column() {
      Text(this.text)
        .fontSize(16)
        .border({ width: 1 })
        .lineHeight(24)
        .margin(30)
        .selection(this.start, this.end)
        .onTextSelectionChange((start: number, end: number) => {
          this.selectedText = this.text.substring(start, end)
          console.info(`Text selection changed: start=${start}, end=${end}, selectedText=${this.selectedText}`)
        })

      Text(`Selected Text: ${this.selectedText}`)
        .fontSize(14)
        .margin(10)

      Button('Update Selection')
        .margin(20)
        .onClick(() => {
          this.start = 8
          this.end = 20
        })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

