@Entry
@Component
struct ContentValidationApp {
  @State inputText: string = ''
  @State errorMessage: string = ''

  validateContent(): boolean {
    if (this.inputText.length < 8) {
      this.errorMessage = 'Input must be at least 8 characters long'
      return false
    }
    if (!/[A-Z]/.test(this.inputText)) {
      this.errorMessage = 'Input must contain at least one uppercase letter'
      return false
    }
    if (!/[0-9]/.test(this.inputText)) {
      this.errorMessage = 'Input must contain at least one number'
      return false
    }
    this.errorMessage = ''
    return true
  }

  build() {
    Column({ space: 20 }) {
      TextInput({ placeholder: 'Enter your password' })
        .onChange((value: string) => {
          this.inputText = value
        })

      Button('Validate Password')
        .onClick(() => {
          if (this.validateContent()) {
            console.info('Password is valid')
          }
        })

      Text(this.errorMessage)
        .fontSize(14)
        .fontColor(Color.Red)
    }
    .padding(20)
    .width('100%')
  }
}

