@Entry
@Component
struct DynamicTemplates {
  @State templates: Array<string> = ['Default Template 1', 'Default Template 2']
  @State newTemplate: string = ''
  @State selectedTemplate: string = ''

  private addTemplate(): void {
    if (this.newTemplate) {
      this.templates.push(this.newTemplate)
      this.newTemplate = ''
    }
  }

  private removeTemplate(index: number): void {
    this.templates.splice(index, 1)
    if (this.selectedTemplate === this.templates[index]) {
      this.selectedTemplate = ''
    }
  }

  private selectTemplate(template: string): void {
    this.selectedTemplate = template
  }

  build() {
    Column({ space: 10 }) {
      TextInput({ placeholder: 'Enter new template name' })
        .onChange((value: string) => {
          this.newTemplate = value
        })
        .margin({ bottom: 20 })

      Button('Add Template')
        .onClick(() => {
          this.addTemplate()
        })
        .margin({ bottom: 20 })

      List({ space: 10 }) {
        ForEach(this.templates, (item: string, index: number) => {
          ListItem() {
            Row({ space: 10 }) {
              Text(item)
                .fontSize(18)
                .onClick(() => {
                  this.selectTemplate(item)
                })
              Button('Remove')
                .onClick(() => {
                  this.removeTemplate(index)
                })
            }
            .padding(10)
            .backgroundColor(this.selectedTemplate === item ? '#007DFF' : '#FFFFFF')
            .borderRadius(5)
            .margin({ bottom: 10 })
          }
        })
      }
      .width('100%')
      .height('60%')

      Text(`Selected Template: ${this.selectedTemplate}`)
        .fontSize(18)
        .margin({ top: 20 })
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#f0f0f0')
  }
}

