@Entry
@Component
struct TimeZoneConfiguration {
    @State currentTimeZone: string = Intl.DateTimeFormat().resolvedOptions().timeZone;
    @State currentTime: string = new Date().toLocaleTimeString();
    @State timezoneOffset: string = '';
    @State adjustedTime: string = '';
    @State errorMessage: string = '';

    validateTimezoneOffset(offset: string): boolean {
        const regex = /^[+-]\d{2}:\d{2}$/;
        return regex.test(offset);
    }

    calculateAdjustedTime(offset: string): void {
        if (!this.validateTimezoneOffset(offset)) {
            this.errorMessage = 'Invalid timezone offset. Use format +/-HH:mm';
            this.adjustedTime = '';
            return;
        }

        this.errorMessage = '';
        const parts = offset.split(':');
        const hours = parseInt(parts[0], 10);
        const minutes = parseInt(parts[1], 10);
        const totalOffsetMinutes = hours * 60 + minutes;
        const now = new Date();
        const utcTime = now.getTime() + now.getTimezoneOffset() * 60000;
        const adjustedTime = new Date(utcTime + totalOffsetMinutes * 60000);

        this.adjustedTime = adjustedTime.toISOString().split('T')[1].slice(0, 8);
    }

    updateTimeZone(newTimeZone: string): void {
        this.currentTimeZone = newTimeZone;
        this.currentTime = new Date().toLocaleTimeString('en-US', { timeZone: this.currentTimeZone });
    }

    build() {
        Column({ space: 8 }) {
            Text(`Current Time Zone: ${this.currentTimeZone}`)
                .fontSize(20)
                .margin({ bottom: 20 });

            Text(`Current Time: ${this.currentTime}`)
                .fontSize(20)
                .margin({ bottom: 20 });

            Button('Change Time Zone')
                .margin(30)
                .onClick(() => {
                    this.updateTimeZone('America/New_York');
                    console.info(`Time Zone Changed to: ${this.currentTimeZone}`);
                    console.info(`Current Time: ${this.currentTime}`);
                });

            TextInput({ placeholder: 'Enter timezone offset (+/-HH:mm)' })
                .width('80%')
                .height(50)
                .margin(10)
                .onChange((value: string) => {
                    this.timezoneOffset = value;
                    this.calculateAdjustedTime(value);
                });

            Text(this.errorMessage)
                .fontSize(16)
                .fontColor(Color.Red)
                .margin(10);

            if (this.adjustedTime) {
                Text(`Adjusted UTC Time: ${this.adjustedTime}`)
                    .fontSize(24)
                    .fontColor(Color.Black)
                    .margin(10);
            }
        }
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
        .alignItems(HorizontalAlign.Center);
    }
}

