@Entry
@Component
struct TouchEventFilterExample {
  @State private touchStartX: number = 0;
  @State private touchStartY: number = 0;
  @State private touchMoveX: number = 0;
  @State private touchMoveY: number = 0;
  @State private message: string = "Touch to Start";

  onTouchStart(event: TouchEvent) {
    if (event.touches.length > 0) {
      this.touchStartX = event.touches[0].x;
      this.touchStartY = event.touches[0].y;
      this.message = `Touch Start: X: ${this.touchStartX}, Y: ${this.touchStartY}`;
    }
  }

  onTouchMove(event: TouchEvent) {
    if (event.touches.length > 0) {
      this.touchMoveX = event.touches[0].x;
      this.touchMoveY = event.touches[0].y;
      this.message = `Touch Move: X: ${this.touchMoveX}, Y: ${this.touchMoveY}`;
      this.filterTouchEvent(event);
    }
  }

  filterTouchEvent(event: TouchEvent) {
    const deltaX = Math.abs(this.touchMoveX - this.touchStartX);
    const deltaY = Math.abs(this.touchMoveY - this.touchStartY);

    if (deltaX > 50 || deltaY > 50) {
      this.message = `Filtered: Significant Movement Detected (X: ${deltaX}, Y: ${deltaY})`;
    } else {
      this.message = `Filtered: Movement Too Small (X: ${deltaX}, Y: ${deltaY})`;
    }
  }

  build() {
    Column({ space: 20 }) {
      Text(this.message)
        .fontSize(20)
