@Component
struct DropdownMenuApp {
  private items: Array<DropdownItem> = [
    new DropdownItem(1, 'Item A', 'This is the content for Item A.'),
    new DropdownItem(2, 'Item B', 'This is the content for Item B.'),
    new DropdownItem(3, 'Item C', 'This is the content for Item C.'),
    new DropdownItem(4, 'Item D', 'This is the content for Item D.')
  ];

  @State selectedItem: DropdownItem | null = null;
  @State isDropdownOpen: boolean = false;

  build() {
    Column() {
      Text('Select an Item from Dropdown')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Button(this.selectedItem ? this.selectedItem.title : 'Select an Item')
        .onClick(() => {
          this.isDropdownOpen = !this.isDropdownOpen;
        })
        .width('80%')
        .height(50)
        .backgroundColor('#f0f0f0')
        .borderRadius(5)
        .margin({ bottom: 10 });

      if (this.isDropdownOpen) {
        List() {
          ForEach(this.items, (item: DropdownItem) => {
            ListItem() {
              Text(item.title)
                .fontSize(18)
                .padding(10)
                .onClick(() => {
                  this.selectedItem = item;
                  this.isDropdownOpen = false;
                });
            }
            .backgroundColor('#FFFFFF')
            .borderRadius(5)
            .margin({ bottom: 5 });
          });
        }
        .width('80%')
        .height(200)
        .backgroundColor('#FFFFFF')
        .borderRadius(5)
        .margin({ bottom: 20 });
      }

      if (this.selectedItem) {
        Text(this.selectedItem.content)
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 20 })
          .padding(10)
          .backgroundColor('#FFFFFF')
          .borderRadius(5)
          .width('80%');
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5');
  }
}

class DropdownItem {
  id: number;
  title: string;
  content: string;

  constructor(id: number, title: string, content: string) {
    this.id = id;
    this.title = title;
    this.content = content;
  }
}

