@Entry
@Component
struct WindowManagementApp {
  @State subWindows: Array<SubWindow> = [];
  @State currentWindowId: number = 0;

  build() {
    Column() {
      Button('Create SubWindow')
        .onClick(() => {
          this.createSubWindow();
        })
        .margin(10)
        .width(200)
        .height(50)

      List({ space: 10 }) {
        ForEach(this.subWindows, (subWindow: SubWindow) => {
          ListItem() {
            Column() {
              Row() {
                Text(`SubWindow ${subWindow.id}`)
                  .fontSize(18)
                  .margin(5)
                Button() {
                  Image($r('app.media.app_icon'))
                    .width(20)
                    .height(20)
                }
                .onClick(() => {
                  this.closeSubWindow(subWindow.id);
                })
                .width(30)
                .height(30)
                .backgroundColor(Color.Transparent)
              }
              Text(subWindow.content)
                .fontSize(14)
                .margin(5)
            }
            .padding(10)
            .border({ width: 1, color: Color.Gray })
            .borderRadius(5)
          }
        })
      }
      .width('100%')
      .height('80%')
    }
    .width('100%')
    .height('100%')
    .padding(10)
  }

  createSubWindow() {
    const newWindowId = this.currentWindowId + 1;
    const newSubWindow: SubWindow = {
      id: newWindowId,
      content: `This is the content of SubWindow ${newWindowId}`
    };
    this.subWindows = [...this.subWindows, newSubWindow];
    this.currentWindowId = newWindowId;
  }

  closeSubWindow(id: number) {
    this.subWindows = this.subWindows.filter(subWindow => subWindow.id !== id);
  }
}

interface SubWindow {
  id: number;
  content: string;
}

@Entry
@Component
struct ImageGallery {
  @State selectedImage: Resource = $r('app.media.app_icon')
  @State showFullScreen: boolean = false

  private images: Resource[] = [
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon'),
    $r('app.media.app_icon')
  ]

  build() {
    Column() {
      if (this.showFullScreen) {
        Stack() {
          Image(this.selectedImage)
            .objectFit(ImageFit.Contain)
            .width('100%')
            .height('100%')

          Button('Close')
            .onClick(() => {
              this.showFullScreen = false
            })
            .position({ x: 20, y: 20 })
            .backgroundColor('#FFFFFF')
            .padding({ left: 10, right: 10, top: 5, bottom: 5 })
            .borderRadius(5)
        }
      } else {
        Grid() {
          ForEach(this.images, (image: Resource) => {
            GridItem() {
              Image(image)
                .width('100%')
                .aspectRatio(1)
                .objectFit(ImageFit.Cover)
                .borderRadius(5)
                .onClick(() => {
                  this.selectedImage = image
                  this.showFullScreen = true
                })
            }
          })
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsGap(10)
        .columnsGap(10)
        .padding(10)
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

@Entry
@Component
struct CircleDrawingDemo {
  private settings: RenderingContextSettings = new RenderingContextSettings(true)
  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings)

  build() {
    Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Center, justifyContent: FlexAlign.Center }) {
      Canvas(this.context)
        .width('100%')
        .height('100%')
        .backgroundColor('#ffff00')
        .onReady(() => {
          // Draw a filled circle
          this.context.beginPath()
          this.context.arc(150, 150, 50, 0, 6.28)
          this.context.fillStyle = '#ff0000'
          this.context.fill()

          // Draw a stroked circle
          this.context.beginPath()
          this.context.arc(300, 150, 50, 0, 6.28)
          this.context.lineWidth = 5
          this.context.strokeStyle = '#0000ff'
          this.context.stroke()
        })
    }
    .width('100%')
    .height('100%')
  }
}

