@Entry
@Component
struct ImageCarousel {
  private swiperController: SwiperController = new SwiperController();

  private carouselItems: Array<CarouselItem> = [
    new CarouselItem(1, $r('app.media.icon'), 'Mountain View'),
    new CarouselItem(2, $r('app.media.icon'), 'Ocean Sunset'),
    new CarouselItem(3, $r('app.media.icon'), 'Forest Path'),
    new CarouselItem(4, $r('app.media.icon'), 'Desert Dunes'),
    new CarouselItem(5, $r('app.media.icon'), 'City Lights')
  ];

  @State currentIndex: number = 0;

  build() {
    Column() {
      Text('Image Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Column() {
        Swiper(this.swiperController) {
          ForEach(this.carouselItems, (item: CarouselItem) => {
            Stack() {
              Image(item.image)
                .width('100%')
                .height(300)
                .objectFit(ImageFit.Cover)
                .borderRadius(16);
            }
          });
        }
        .width('100%')
        .height(300)
        .margin({ bottom: 16 })
        .autoPlay(true)
        .interval(3000)
        .indicator(true)
        .loop(true)
        .duration(500)
        .onChange((index: number) => {
          this.currentIndex = index;
        });

        Text(this.carouselItems[this.currentIndex].caption)
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 8 })
          .textAlign(TextAlign.Center);
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(20);

      Row() {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });

        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

class CarouselItem {
  id: number;
  image: Resource;
  caption: string;

  constructor(id: number, image: Resource, caption: string) {
    this.id = id;
    this.image = image;
    this.caption = caption;
  }
}

@Entry
@Component
struct CustomRefreshList {
  @State refreshing: boolean = false
  @State listData: string[] = ['Item 1', 'Item 2', 'Item 3']
  @State headerText: string = 'Pull to Refresh'

  @Builder
  customItemBuilder(item: string) {
    Row() {
      Image($r('app.media.app_icon'))
        .width(50)
        .height(50)
        .margin(10)
      Column() {
        Text(item)
          .fontSize(18)
          .fontColor('#333333')
        Text('Subtitle for ' + item)
          .fontSize(14)
          .fontColor('#666666')
      }
      .margin({ left: 10 })
    }
    .width('100%')
    .padding(10)
    .backgroundColor('#ffffff')
    .borderRadius(8)
    .margin({ top: 5, bottom: 5 })
  }

  build() {
    Column() {
      Text(this.headerText)
        .fontSize(20)
        .fontColor('#000000')
        .padding(16)
        .backgroundColor('#f0f0f0')
        .width('100%')
        .textAlign(TextAlign.Center)

      Refresh({
        refreshing: this.refreshing,
        offset: 120,
        friction: 100
      }) {
        List() {
          ForEach(this.listData, (item: string) => {
            ListItem() {
              this.customItemBuilder(item)
            }
          }, (item: string) => item)
        }
        .width('100%')
      }
      .onRefreshing(() => {
        this.headerText = 'Refreshing...'
        setTimeout(() => {
          this.listData = ['New Item 1', 'New Item 2', 'New Item 3', 'New Item 4']
          this.refreshing = false
          this.headerText = 'Pull to Refresh'
        }, 2000)
      })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }
}

