@Entry
@Component
struct CountdownTimerFromTen {
  @State timeLeft: number = 10
  @State timerId: number = -1
  @State isCounting: boolean = false

  build() {
    Column() {
      Text(`Time left: ${this.timeLeft} seconds`)
        .fontSize(40)
        .margin({ bottom: 20 })

      Button(this.isCounting ? 'Stop' : 'Start')
        .onClick(() => {
          if (this.isCounting) {
            clearInterval(this.timerId)
            this.isCounting = false
          } else {
            this.isCounting = true
            this.timeLeft = 10
            this.startTimer()
          }
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }

  startTimer() {
    this.timerId = setInterval(() => {
      if (this.timeLeft > 0) {
        this.timeLeft -= 1
      } else {
        clearInterval(this.timerId)
        this.isCounting = false
      }
    }, 1000)
  }
}

