@Entry
@Component
struct RatingApp {
  @State items: Array<Item> = [
    { id: 1, name: 'Item 1', totalRatings: 0, sumRatings: 0, averageRating: 0 },
    { id: 2, name: 'Item 2', totalRatings: 0, sumRatings: 0, averageRating: 0 },
    { id: 3, name: 'Item 3', totalRatings: 0, sumRatings: 0, averageRating: 0 }
  ];

  private rateItem(itemIndex: number, rating: number): void {
    let item = this.items[itemIndex];
    item.totalRatings += 1;
    item.sumRatings += rating;
    item.averageRating = item.sumRatings / item.totalRatings;
    this.items.splice(itemIndex, 1, item);
  }

  build() {
    Column({ space: 20 }) {
      Text('Rate the Items')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .width('100%')
        .textAlign(TextAlign.Center)
        .margin({ top: 20, bottom: 10 });

      List({ space: 10 }) {
        ForEach(this.items, (item: Item, index: number) => {
          ListItem() {
            Column({ space: 10 }) {
              Text(item.name)
                .fontSize(18)
                .fontWeight(FontWeight.Medium);

              Text(`Average: ${item.averageRating.toFixed(1)} (${item.totalRatings} ratings)`)
                .fontSize(14)
                .fontColor(Color.Gray);

              Row({ space: 5 }) {
                ForEach([1, 2, 3, 4, 5], (starValue: number) => {
                  Image($r('app.media.star'))
                    .width(24)
                    .height(24)
                    .objectFit(ImageFit.Contain)
                    .onClick(() => {
                      this.rateItem(index, starValue);
                    })
                    .opacity(starValue <= item.averageRating ? 1 : 0.3);
                })
              }
              .margin({ top: 5 });
            }
            .width('100%')
            .padding(15)
            .backgroundColor('#FFFFFF')
            .borderRadius(8);
          }
          .margin({ bottom: 10 });
        })
      }
      .width('100%')
      .layoutWeight(1);
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5');
  }
}

interface Item {
  id: number;
  name: string;
  totalRatings: number;
  sumRatings: number;
