@Entry
@Component
struct FullScreenSlideshow {
  private swiperController: SwiperController = new SwiperController();

  private slides: Array<Slide> = [
    { id: 1, image: ('$media:slide1'), caption: 'Mountain View' },
    { id: 2, image: ('$media:slide2'), caption: 'Ocean Sunset' },
    { id: 3, image: ('$media:slide3'), caption: 'Forest Path' }
  ];

  @State currentIndex: number = 0;
  @State isFullScreen: boolean = false;

  build() {
    Column() {
      Text('Image Slideshow')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Column() {
        Swiper(this.swiperController) {
          ForEach(this.slides, (slide: Slide) => {
            Stack() {
              Image(slide.image)
                .width('100%')
                .height(300)
                .objectFit(ImageFit.Contain)
                .borderRadius(16)
                .onClick(() => {
                  this.currentIndex = slide.id - 1;
                  this.isFullScreen = true;
                });
            }
          });
        }
        .width('100%')
        .height(300)
        .margin({ bottom: 16 })
        .autoPlay(false)
        .indicator(true)
        .loop(false)
        .onChange((index: number) => {
          this.currentIndex = index;
        });

        Text(this.slides[this.currentIndex].caption)
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .textAlign(TextAlign.Center)
          .margin({ top: 8 });
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(20);

      if (this.isFullScreen) {
        Stack() {
          Image(this.slides[this.currentIndex].image)
            .width('100%')
            .height('100%')
            .objectFit(ImageFit.Contain);

          Column() {
            Text(this.slides[this.currentIndex].caption)
              .fontSize(24)
              .fontWeight(FontWeight.Bold)
              .textAlign(TextAlign.Center)
              .backgroundColor(Color.Black)
              .opacity(0.8)
              .padding(8)
              .borderRadius(8);

            Button('Close')
              .width(100)
              .height(40)
              .margin({ top: 20 })
              .onClick(() => {
                this.isFullScreen = false;
              });
          }
          .alignItems(HorizontalAlign.Center)
          .justifyContent(FlexAlign.Center)
          .width('100%')
          .height('100%');
        }
        .width('100%')
        .height('100%')
        .backgroundColor(Color.Black);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

interface Slide {
  id: number;
  image: string;
  caption: string;
}

