import promptAction from '@ohos.promptAction';

@Entry
@Component
struct LoginApp {
  @State email: string = '';
  @State password: string = '';
  @State errorMessage: string = '';
  @State showDialog: boolean = false;

  validateEmail(email: string): boolean {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return re.test(email);
  }

  validatePassword(password: string): boolean {
    return password.length >= 6;
  }

  handleLogin() {
    if (!this.email || !this.password) {
      this.errorMessage = 'Please fill in all fields.';
      return;
    }

    if (!this.validateEmail(this.email)) {
      this.errorMessage = 'Invalid email format.';
      return;
    }

    if (!this.validatePassword(this.password)) {
      this.errorMessage = 'Password must be at least 6 characters long.';
      return;
    }

    this.showDialog = true;
  }

  build() {
    Column() {
      // Email Input
      Text('Email')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your email' })
        .width('100%')
        .height(40)
        .margin({ bottom: 20 })
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .onChange((value: string) => {
          this.email = value;
        });

      // Password Input
      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .width('100%')
        .height(40)
        .margin({ bottom: 30 })
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .onChange((value: string) => {
          this.password = value;
        });

      // Login Button
      Button('Login')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          this.handleLogin();
        });

      // Error Message Display
      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 20 });
      }

      // Forgot Password Link
      Text('Forgot Password?')
        .fontSize(16)
        .fontColor('#007AFF')
        .margin({ top: 10 })
        .onClick(() => {
          promptAction.showToast({
            message: 'Forgot Password clicked'
          });
        });

      // Dialog
      if (this.showDialog) {
        Column() {
          Text('Login Successful')
            .fontSize(20)
            .margin({ bottom: 20 });

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text('Password: ********')
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.showDialog = false;
            });
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

import promptAction from '@ohos.promptAction';

@Entry
@Component
struct UserRegistrationForm {
  @State name: string = '';
  @State email: string = '';
  @State password: string = '';
  @State showDialog: boolean = false;
  @State errorMessage: string = '';

  validateForm(): boolean {
    this.errorMessage = '';
    if (!this.name || !this.email || !this.password) {
      this.errorMessage = 'All fields are required';
      return false;
    }
    if (!this.validateEmail(this.email)) {
      this.errorMessage = 'Please enter a valid email address';
      return false;
    }
    return true;
  }

  validateEmail(email: string): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }

  build() {
    Column({ space: 20 }) {
      Text('User Registration')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      TextInput({ placeholder: 'Enter your name' })
        .onChange((value: string) => {
          this.name = value;
        })
        .width('100%')
        .height(40)
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .margin({ bottom: 20 });

      TextInput({ placeholder: 'Enter your email' })
        .onChange((value: string) => {
          this.email = value;
        })
        .width('100%')
        .height(40)
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .margin({ bottom: 20 });

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value;
        })
        .width('100%')
        .height(40)
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .margin({ bottom: 30 });

      Button('Submit')
        .onClick(() => {
          if (this.validateForm()) {
            this.showDialog = true;
          } else {
            promptAction.showToast({
              message: this.errorMessage
            });
          }
        })
        .width('100%')
        .height(50)
        .backgroundColor('#007AFF')
        .fontSize(18)
        .fontColor(Color.White);

      if (this.showDialog) {
        Column() {
          Text('Submitted Information')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Name: ${this.name}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Password: ${'*'.repeat(this.password.length)}`)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.showDialog = false;
              this.name = '';
              this.email = '';
              this.password = '';
            })
            .width('100%')
            .height(50)
            .backgroundColor('#007AFF')
            .fontSize(18)
            .fontColor(Color.White);
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ top: 10 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White);
  }
}

