@Component
struct ImageCaptionGridApp {
  @State message: string = ''

  private gridItems: Array<GridItemData> = [
    {image: $r('app.media.icon'), caption: 'Nature'},
    {image: $r('app.media.icon'), caption: 'Animals'},
    {image: $r('app.media.icon'), caption: 'Travel'},
    {image: $r('app.media.icon'), caption: 'Food'},
    {image: $r('app.media.icon'), caption: 'Sports'},
    {image: $r('app.media.icon'), caption: 'Art'},
    {image: $r('app.media.icon'), caption: 'Music'},
    {image: $r('app.media.icon'), caption: 'Technology'}
  ]

  build() {
    Column() {
      Grid() {
        ForEach(this.gridItems, (item: GridItemData) => {
          GridItem() {
            Column() {
              Image(item.image)
                .width('100%')
                .aspectRatio(1)
                .objectFit(ImageFit.Cover)
                .borderRadius(8)
                .onClick(() => {
                  this.message = item.caption
                })
              Text(item.caption)
                .fontSize(14)
                .fontWeight(FontWeight.Medium)
                .margin({ top: 8 })
                .textAlign(TextAlign.Center)
                .maxLines(1)
                .textOverflow({ overflow: TextOverflow.Ellipsis })
            }
            .width('100%')
            .padding(8)
          }
        })
      }
      .columnsTemplate('1fr 1fr')
      .rowsGap(12)
      .columnsGap(12)
      .padding(16)
      .width('100%')

      if (this.message !== '') {
        Text(`Selected: ${this.message}`)
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 24, bottom: 16 })
          .textAlign(TextAlign.Center)
          .backgroundColor(Color.White)
          .padding(12)
          .borderRadius(8)
          .width('90%')
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F0F0F0')
    .justifyContent(FlexAlign.Start)
  }
}

interface GridItemData {
  image: Resource
  caption: string
}

