@Entry
@Component
struct ImageCarousel {
  private swiperController: SwiperController = new SwiperController();

  private carouselItems: Array<CarouselItem> = [
    { id: 1, imageUrl: "https://example.com/image1.jpg" },
    { id: 2, imageUrl: "https://example.com/image2.jpg" },
    { id: 3, imageUrl: "https://example.com/image3.jpg" },
    { id: 4, imageUrl: "https://example.com/image4.jpg" }
  ];

  @State currentIndex: number = 0;

  @Builder
  buildImageStack(item: CarouselItem) {
    Stack() {
      Image(item.imageUrl)
        .width('100%')
        .height(300)
        .objectFit(ImageFit.Cover)
        .borderRadius(16)
        .onError(() => {
          console.error('Failed to load image:', item.imageUrl);
        });
    }
  }

  build() {
    Column() {
      Text('Image Carousel')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Column() {
        Swiper(this.swiperController) {
          ForEach(this.carouselItems, (item: CarouselItem) => {
            this.buildImageStack(item);
          }, (item: CarouselItem) => item.id.toString());
        }
        .width('100%')
        .height(300)
        .margin({ bottom: 16 })
        .autoPlay(true)
        .interval(3000)
        .indicator(true)
        .loop(true)
        .duration(500)
        .onChange((index: number) => {
          this.currentIndex = index;
        });
      }
      .width('100%')
      .padding(16)
      .backgroundColor('#f5f5f5')
      .borderRadius(20);

      Row() {
        Button('Previous')
          .onClick(() => {
            this.swiperController.showPrevious();
          });

        Button('Next')
          .onClick(() => {
            this.swiperController.showNext();
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
    .padding(16);
  }
}

interface CarouselItem {
  id: number;
  imageUrl: string;
}

import promptAction from '@ohos.promptAction';

@Entry
@Component
struct UserForm {
  @State name: string = ''
  @State email: string = ''
  @State phoneNumber: string = ''
  @State showDialog: boolean = false

  validateForm(): boolean {
    if (!this.name || !this.email || !this.phoneNumber) {
      promptAction.showToast({
        message: 'Please fill in all fields'
      })
      return false
    }
    return true
  }

  build() {
    Column() {
      Text('User Information Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 })

      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value
          })
      }

      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value
          })
      }

      Column() {
        Text('Phone Number:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your phone number' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.phoneNumber = value
          })
      }

      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.validateForm()) {
            this.showDialog = true
          }
        })

      if (this.showDialog) {
        Column() {
          Text('Submitted Details')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 })

          Text(`Name: ${this.name}`)
            .fontSize(16)
            .margin({ bottom: 12 })

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 12 })

          Text(`Phone Number: ${this.phoneNumber}`)
            .fontSize(16)
            .margin({ bottom: 20 })

          Button('Close')
            .onClick(() => {
              this.showDialog = false
              this.name = ''
              this.email = ''
              this.phoneNumber = ''
            })
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
  }
}

