@Entry
@Component
struct ImageGalleryApp {
  @State private images: ImageItem[] = [];
  @State private showUploadDialog: boolean = false;
  @State private newImageTitle: string = '';
  @State private newImage: Resource = $r('app.media.app_icon');
  @State private isLoading: boolean = false;

  build() {
    Column() {
      Text('Image Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Button('Upload Image')
        .onClick(() => {
          this.showUploadDialog = true;
        })
        .width('50%')
        .height(40)
        .margin({ bottom: 20 });

      if (this.isLoading) {
        Text('Uploading...')
          .fontSize(16)
          .margin({ bottom: 16 });
      }

      Grid() {
        ForEach(this.images, (imageItem: ImageItem) => {
          GridItem() {
            Column() {
              Image(imageItem.image)
                .width('100%')
                .height(160)
                .borderRadius(8)
                .objectFit(ImageFit.Cover);

              Text(imageItem.title)
                .fontSize(16)
                .fontWeight(FontWeight.Medium)
                .margin({ top: 8 })
                .maxLines(1)
                .textOverflow({ overflow: TextOverflow.Ellipsis });
            }
            .backgroundColor(Color.White)
            .borderRadius(12)
            .padding(16)
            .width('100%');
          }
        });
      }
      .columnsTemplate('1fr 1fr')
      .rowsGap(16)
      .columnsGap(16)
      .padding(16)
      .layoutWeight(1);

      if (this.showUploadDialog) {
        Column() {
          Text('Upload New Image')
            .fontSize(24)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 16 });

          TextInput({ placeholder: 'Enter image title' })
            .onChange((value: string) => {
              this.newImageTitle = value;
            })
            .width('100%')
            .height(40)
            .margin({ bottom: 16 });

          Image(this.newImage)
            .width(120)
            .height(120)
            .objectFit(ImageFit.Cover)
            .borderRadius(8)
            .margin({ bottom: 16 });

          Button('Select Image')
            .onClick(() => {
              this.newImage = $r('app.media.app_icon');
            })
            .width('100%')
            .height(40)
            .margin({ bottom: 16 });

          Row() {
            Button('Cancel')
              .onClick(() => {
                this.showUploadDialog = false;
                this.newImageTitle = '';
              })
              .layoutWeight(1)
              .height(40)
              .margin({ right: 8 });

            Button('Upload')
              .onClick(() => {
                this.handleImageUpload();
              })
              .layoutWeight(1)
              .height(40)
              .margin({ left: 8 });
          }
          .width('100%');
        }
        .padding(24)
        .width('90%')
        .backgroundColor(Color.White)
        .borderRadius(16)
        .alignItems(HorizontalAlign.Center);
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
    .alignItems(HorizontalAlign.Center);
  }

  private handleImageUpload() {
    if (!this.newImageTitle.trim()) {
      return;
    }

    this.isLoading = true;

    setTimeout(() => {
      const newItem: ImageItem = {
        id: this.images.length + 1,
        title: this.newImageTitle,
        image: this.newImage
      };

      this.images = [...this.images, newItem];
      this.showUploadDialog = false;
      this.newImageTitle = '';
      this.newImage = $r('app.media.app_icon');
      this.isLoading = false;
    }, 1000);
  }
}

interface ImageItem {
  id: number;
  title: string;
  image: Resource;
}

