@Entry
@Component
struct ProfileScreen {
  @State userName: string = 'John Doe'
  @State userBio: string = 'Software Developer with 5 years of experience in HarmonyOS and ArkTS development.'
  @State isEditing: boolean = false
  @State newName: string = ''
  @State newBio: string = ''

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .borderRadius(50)
        .margin({ bottom: 20 })

      if (this.isEditing) {
        TextInput({ placeholder: 'Enter new name', text: this.newName })
          .onChange((value: string) => {
            this.newName = value
          })
          .width('100%')
          .height(40)
          .margin({ bottom: 10 })
          .padding(8)
          .border({ width: 1, color: Color.Gray })

        TextInput({ placeholder: 'Enter new bio', text: this.newBio })
          .onChange((value: string) => {
            this.newBio = value
          })
          .width('100%')
          .height(60)
          .margin({ bottom: 10 })
          .padding(8)
          .border({ width: 1, color: Color.Gray })

        Row() {
          Button('Cancel')
            .onClick(() => {
              this.isEditing = false
              this.newName = ''
              this.newBio = ''
            })
            .margin({ right: 10 })

          Button('Save')
            .onClick(() => {
              if (this.newName.trim()) {
                this.userName = this.newName.trim()
              }
              if (this.newBio.trim()) {
                this.userBio = this.newBio.trim()
              }
              this.isEditing = false
              this.newName = ''
              this.newBio = ''
            })
        }
        .margin({ top: 10 })
      } else {
        Text(this.userName)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 10 })
          .textAlign(TextAlign.Center)

        Text(this.userBio)
          .fontSize(16)
          .margin({ bottom: 20 })
          .textAlign(TextAlign.Center)

        Button('Edit Profile')
          .onClick(() => {
            this.isEditing = true
            this.newName = this.userName
            this.newBio = this.userBio
          })
          .width(120)
          .height(40)
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

