      List() {
        ForEach(this.items, (item: Item) => {
          ListItem() {
            Text(item.title)
              .fontSize(18)
              .padding(10)
              .backgroundColor('#f0f0f0')
              .borderRadius(5)
              .margin({ bottom: 10 });
          }
        });
      }
      .width('100%')
      .height('100%')
      .padding({ bottom: 80 });

