@Entry
@Component
struct CalendarWidgetApp {
  @State selectedDate: Date = new Date()
  @State displayDate: string = ''
  @State dateText: string = ''

  aboutToAppear() {
    this.updateDisplayDate()
    this.updateDateText()
  }

  updateDisplayDate() {
    this.displayDate = this.selectedDate.toLocaleDateString()
  }

  updateDateText() {
    this.dateText = this.selectedDate.toLocaleDateString()
  }

  build() {
    Column() {
      Text('Calendar Date Picker')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 })

      DatePicker({
        start: new Date('2000-01-01'),
        end: new Date('2030-12-31'),
        selected: this.selectedDate
      })
        .onDateChange((value: Date) => {
          this.selectedDate = value
          this.updateDisplayDate()
          this.updateDateText()
        })
        .margin({ bottom: 40 })

      Column() {
        Text('Selected Date:')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ bottom: 8 })

        Text(this.displayDate)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .fontColor('#007AFF')
      }
      .padding(16)
      .borderRadius(12)
      .backgroundColor('#F0F0F0')
      .margin({ bottom: 30 })

      Column() {
        Text('Date Text Field:')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ bottom: 8 })

        TextInput({ text: this.dateText })
          .fontSize(18)
          .height(50)
          .width('100%')
          .backgroundColor(Color.White)
          .border({ width: 1, color: '#CCCCCC' })
          .borderRadius(8)
          .padding(10)
          .onChange((value: string) => {
            try {
              const newDate = new Date(value)
              if (!isNaN(newDate.getTime())) {
                this.selectedDate = newDate
                this.updateDisplayDate()
              }
            } catch (error) {
            }
          })
      }
      .padding(16)
      .borderRadius(12)
      .backgroundColor('#F0F0F0')
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White)
  }
}

