@Entry
@Component
struct ContactForm {
  @State name: string = ''
  @State email: string = ''
  @State successMessage: string = ''
  @State errorMessage: string = ''

  validateForm(): boolean {
    if (!this.name.trim()) {
      this.errorMessage = 'Name is required'
      return false
    }
    if (!this.email.trim()) {
      this.errorMessage = 'Email is required'
      return false
    }
    if (!this.email.includes('@')) {
      this.errorMessage = 'Please enter a valid email address'
      return false
    }
    this.errorMessage = ''
    return true
  }

  build() {
    Column() {
      Text('Contact Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 })

      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value
          })
      }

      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value
          })
      }

      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.validateForm()) {
            this.successMessage = 'Form submitted successfully!'
            this.name = ''
            this.email = ''
          }
        })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .margin({ bottom: 20 })
      }

      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(18)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
  }
}

import promptAction from '@ohos.promptAction';

@Entry
@Component
struct UserForm {
  @State name: string = '';
  @State email: string = '';
  @State phoneNumber: string = '';
  @State showSuccessMessage: boolean = false;

  build() {
    Column() {
      Text('User Information Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 });

      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value;
          });
      }

      Column() {
        Text('Email:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your email' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.email = value;
          });
      }

      Column() {
        Text('Phone Number:')
          .fontSize(16)
          .margin({ bottom: 8 });

        TextInput({ placeholder: 'Enter your phone number' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.phoneNumber = value;
          });
      }

      Button('Submit Form')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.name && this.email && this.phoneNumber) {
            this.showSuccessMessage = true;
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields'
            });
          }
        });

      if (this.showSuccessMessage) {
        Column() {
          Text('Form Submitted Successfully!')
            .fontSize(20)
            .fontWeight(FontWeight.Bold)
            .margin({ bottom: 20 });

          Text(`Name: ${this.name}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Email: ${this.email}`)
            .fontSize(16)
            .margin({ bottom: 12 });

          Text(`Phone Number: ${this.phoneNumber}`)
            .fontSize(16)
            .margin({ bottom: 20 });

          Button('Close')
            .onClick(() => {
              this.showSuccessMessage = false;
              this.name = '';
              this.email = '';
              this.phoneNumber = '';
            });
        }
        .width('80%')
        .padding(20)
        .backgroundColor(Color.White)
        .borderRadius(12)
        .shadow({ radius: 4, color: '#1F000000', offsetX: 2, offsetY: 2 })
        .position({ x: '10%', y: '30%' });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF');
  }
}

