import promptAction from '@ohos.promptAction'

@Entry
@Component
struct GreetingApp {
  @State name: string = ''
  @State age: string = ''
  @State showGreeting: boolean = false

  build() {
    Column() {
      Text('User Greeting Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 })

      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value
          })
      }

      Column() {
        Text('Age:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your age' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.age = value
          })
      }

      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.name && this.age) {
            this.showGreeting = true
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields'
            })
          }
        })

      if (this.showGreeting) {
        Text(`Hello, ${this.name}! You are ${this.age} years old.`)
          .fontSize(20)
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
  }
}

@Entry
@Component
struct ProfileScreen {
  @State userName: string = 'John Doe'
  @State userBio: string = 'Software Developer with 5 years of experience in HarmonyOS and ArkTS development.'
  @State isEditing: boolean = false
  @State newName: string = ''
  @State newBio: string = ''

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .borderRadius(50)
        .margin({ bottom: 20 })

      if (this.isEditing) {
        TextInput({ placeholder: 'Enter new name' })
          .onChange((value: string) => {
            this.newName = value
          })
          .margin({ bottom: 10 })

        TextInput({ placeholder: 'Enter new bio' })
          .onChange((value: string) => {
            this.newBio = value
          })
          .margin({ bottom: 10 })

        Button('Save')
          .onClick(() => {
            if (this.newName) {
              this.userName = this.newName
            }
            if (this.newBio) {
              this.userBio = this.newBio
            }
            this.isEditing = false
          })
      } else {
        Text(this.userName)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 10 })

        Text(this.userBio)
          .fontSize(16)
          .margin({ bottom: 20 })

        Button('Edit Profile')
          .onClick(() => {
            this.isEditing = true
          })
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

