      title: 'Forest Path',
      image: $r('app.media.icon'),
      subtitle: 'Nature',
      description: 'A serene path through an ancient forest covered in moss and ferns.'
    },
    {
      id: 4,
      title: 'Desert Dunes',
      image: $r('app.media.icon'),
      subtitle: 'Landscape',
      description: 'Rolling sand dunes stretching as far as the eye can see.'
    }
  ];

