          .margin({ bottom: 16 });

        Text(this.selectedCard.description)
          .fontSize(16)
          .lineHeight(24);

        Button('Close')
          .width('100%')
          .height(40)
          .margin({ top: 24 })
          .onClick(() => {
            this.dialogController.close();
          });
      }
      .padding(24)
      .width('90%')
      .backgroundColor(Color.White)
      .borderRadius(16);
    }
  }

  build() {
    Column() {
      Text('Photo Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Grid() {
        ForEach(this.cards, (card: Card) => {
          GridItem() {
            Column() {
              Image(card.image)
                .width('100%')
                .height(160)
                .borderRadius({ topLeft: 12, topRight: 12 })
                .objectFit(ImageFit.Cover);

              Column() {
                Text(card.title)
                  .fontSize(16)
                  .fontWeight(FontWeight.Medium)
                  .margin({ bottom: 4 });

                Text(card.subtitle)
                  .fontSize(14)
                  .fontColor('#666666');
              }
              .width('100%')
              .padding(12);
            }
            .backgroundColor(Color.White)
            .borderRadius(12)
            .onClick(() => {
              this.selectedCard = card;
              this.dialogController.open();
            });
          }
        });
      }
      .columnsTemplate('1fr 1fr')
      .rowsGap(16)
      .columnsGap(16)
      .padding(16)
      .layoutWeight(1);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }
}

