@Entry
@Component
struct LoginForm {
  @State username: string = ''
  @State password: string = ''
  @State loginMessage: string = ''
  @State isSuccess: boolean = false

  validateLogin(): boolean {
    const validUsername = 'admin'
    const validPassword = 'password123'
    return this.username === validUsername && this.password === validPassword
  }

  build() {
    Column() {
      Text('Login')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 30 })

      Text('Username')
        .fontSize(16)
        .fontWeight(FontWeight.Medium)
        .margin({ bottom: 8 })
        .alignSelf(ItemAlign.Start)
        .width('80%')

      TextInput({ placeholder: 'Enter username', text: this.username })
        .onChange((value: string) => {
          this.username = value
        })
        .width('80%')
        .height(40)
        .backgroundColor('#f8f9fa')
        .borderRadius(8)
        .padding({ left: 12, right: 12 })
        .margin({ bottom: 20 })

      Text('Password')
        .fontSize(16)
        .fontWeight(FontWeight.Medium)
        .margin({ bottom: 8 })
        .alignSelf(ItemAlign.Start)
        .width('80%')

      TextInput({ placeholder: 'Enter password', text: this.password })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .height(40)
        .backgroundColor('#f8f9fa')
        .borderRadius(8)
        .padding({ left: 12, right: 12 })
        .margin({ bottom: 30 })

      Button('Login')
        .onClick(() => {
          if (this.username && this.password) {
            if (this.validateLogin()) {
              this.loginMessage = 'Login successful!'
              this.isSuccess = true
            } else {
              this.loginMessage = 'Invalid credentials'
              this.isSuccess = false
            }
          } else {
            this.loginMessage = 'Please fill all fields'
            this.isSuccess = false
          }
        })
        .width('80%')
        .height(50)
        .backgroundColor('#007AFF')
        .fontColor(Color.White)
        .fontSize(18)
        .fontWeight(FontWeight.Medium)
        .borderRadius(8)

      if (this.loginMessage) {
        Text(this.loginMessage)
          .fontSize(16)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 20 })
          .fontColor(this.isSuccess ? Color.Green : Color.Red)
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

