@Component
struct ImageGridApp {
  @State images: ImageItem[] = [
    {
      id: 1,
      title: 'Mountain View',
      image: $r('app.media.app_icon'),
      active: false
    },
    {
      id: 2,
      title: 'Ocean Waves',
      image: $r('app.media.app_icon'),
      active: false
    },
    {
      id: 3,
      title: 'Forest Trail',
      image: $r('app.media.app_icon'),
      active: false
    },
    {
      id: 4,
      title: 'Desert Dunes',
      image: $r('app.media.app_icon'),
      active: false
    },
    {
      id: 5,
      title: 'City Lights',
      image: $r('app.media.app_icon'),
      active: false
    },
    {
      id: 6,
      title: 'Countryside',
      image: $r('app.media.app_icon'),
      active: false
    }
  ];

  build() {
    Column() {
      Text('Image Gallery')
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Grid() {
        ForEach(this.images, (imageItem: ImageItem) => {
          GridItem() {
            Column() {
              Image(imageItem.image)
                .width('100%')
                .height(160)
                .borderRadius(8)
                .objectFit(ImageFit.Cover)
                .onClick(() => {
                  this.toggleImageActive(imageItem.id);
                });

              if (imageItem.active) {
                Text(imageItem.title)
                  .fontSize(16)
                  .fontWeight(FontWeight.Medium)
                  .margin({ top: 8 })
                  .textAlign(TextAlign.Center);
              }
            }
            .backgroundColor(imageItem.active ? '#e6f7ff' : Color.White)
            .borderRadius(12)
            .padding(16)
            .border({ width: imageItem.active ? 2 : 0, color: '#1890ff' });
          }
        }, (imageItem: ImageItem) => imageItem.id.toString());
      }
      .columnsTemplate('1fr 1fr')
      .rowsGap(16)
      .columnsGap(16)
      .padding(16);
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5');
  }

  toggleImageActive(id: number): void {
    const newImages = this.images.map((item: ImageItem) => {
      if (item.id === id) {
        return {
          id: item.id,
          title: item.title,
          image: item.image,
          active: !item.active
        };
      }
      return item;
    });
    this.images = newImages;
  }
}

interface ImageItem {
  id: number;
  title: string;
  image: Resource;
  active: boolean;
}

