import promptAction from '@ohos.promptAction'

@Entry
@Component
struct GreetingApp {
  @State name: string = ''
  @State age: string = ''
  @State showGreeting: boolean = false
  @State ageGroup: string = ''

  build() {
    Column() {
      Text('User Greeting Form')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 40 })

      Column() {
        Text('Name:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your name' })
          .width('100%')
          .height(40)
          .margin({ bottom: 20 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.name = value
          })
      }

      Column() {
        Text('Age:')
          .fontSize(16)
          .margin({ bottom: 8 })

        TextInput({ placeholder: 'Enter your age' })
          .width('100%')
          .height(40)
          .margin({ bottom: 30 })
          .backgroundColor('#f5f5f5')
          .padding({ left: 12 })
          .onChange((value: string) => {
            this.age = value
          })
      }

      Button('Submit')
        .width('100%')
        .height(50)
        .fontSize(18)
        .backgroundColor('#007AFF')
        .onClick(() => {
          if (this.name && this.age) {
            this.showGreeting = true
            this.ageGroup = this.getAgeGroup(parseInt(this.age))
          } else {
            promptAction.showToast({
              message: 'Please fill in all fields'
            })
          }
        })

      if (this.showGreeting) {
        Text(`Hello, ${this.name}! You are ${this.age} years old and belong to the ${this.ageGroup} age group.`)
          .fontSize(20)
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#FFFFFF')
  }

  getAgeGroup(age: number): string {
    if (age < 13) {
      return 'Child'
    } else if (age >= 13 && age <= 19) {
      return 'Teenager'
    } else if (age >= 20 && age <= 59) {
      return 'Adult'
    } else {
      return 'Senior'
    }
  }
}

