                    .objectFit(ImageFit.Cover)
                    .margin({ right: 12 });

                  Column() {
                    Text(movie.title)
                      .fontSize(18)
                      .fontWeight(FontWeight.Medium)
                      .padding({ bottom: 4 });

                    Text(`Release: ${movie.releaseDate}`)
                      .fontSize(14)
                      .opacity(0.7);
                  }
                  .layoutWeight(1);
                }
                .padding(16)
                .onClick(() => {
                  this.selectedMovie = movie;
                });
              }
            });
          }
          .layoutWeight(1);
        }
      } else {
        Scroll() {
          Column() {
            Image(this.selectedMovie.poster)
              .width('100%')
              .height(280)
              .objectFit(ImageFit.Cover);

            Column() {
              Text(this.selectedMovie.title)
                .fontSize(26)
                .fontWeight(FontWeight.Bold)
                .padding({ top: 20, bottom: 8, left: 16, right: 16 });

              Text(`Release Date: ${this.selectedMovie.releaseDate}`)
                .fontSize(16)
                .opacity(0.8)
                .padding({ bottom: 16, left: 16, right: 16 });

              Text('Description')
                .fontSize(20)
                .fontWeight(FontWeight.Medium)
                .padding({ bottom: 8, left: 16, right: 16 });

              Text(this.selectedMovie.description)
                .fontSize(16)
                .lineHeight(22)
                .padding({ bottom: 24, left: 16, right: 16 });

              Button('Back to List')
                .onClick(() => {
                  this.selectedMovie = null;
                })
                .width('80%')
                .margin({ bottom: 20 });
            }
          }
        }
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF');
  }
}

@Entry
@Component
struct LoginForm {
  @State username: string = ''
  @State password: string = ''
  @State successMessage: string = ''
  @State errorMessage: string = ''

  validateCredentials(): boolean {
    if (this.username === 'admin' && this.password === 'password') {
      this.successMessage = 'Login successful!'
      this.errorMessage = ''
      return true
    } else {
      this.errorMessage = 'Invalid username or password'
      this.successMessage = ''
      return false
    }
  }

  build() {
    Column() {
      Text('Username')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your username' })
        .onChange((value: string) => {
          this.username = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      Text('Password')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 })

      TextInput({ placeholder: 'Enter your password' })
        .type(InputType.Password)
        .onChange((value: string) => {
          this.password = value
        })
        .width('80%')
        .margin({ bottom: 20 })

      Button('Login')
        .onClick(() => {
          if (this.validateCredentials()) {
            console.info(this.successMessage)
          } else {
            console.error(this.errorMessage)
          }
        })
        .width('60%')
        .backgroundColor('#4CAF50')
        .fontSize(18)
        .fontColor(Color.White)

      if (this.successMessage) {
        Text(this.successMessage)
          .fontSize(16)
          .fontColor(Color.Green)
          .margin({ top: 20 })
      }
      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(16)
          .fontColor(Color.Red)
          .margin({ top: 20 })
      }
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .justifyContent(FlexAlign.Center)
  }
}

