@Entry
@Component
struct DataFetchingApp {
    @State isLoading: boolean = false
    @State data: string[] = []

    aboutToAppear() {
        this.fetchData()
    }

    private fetchData() {
        this.isLoading = true
        setTimeout(() => {
            this.data = ['User 1', 'User 2', 'User 3', 'User 4', 'User 5']
            this.isLoading = false
        }, 3000)
    }

    build() {
        Column() {
            if (this.isLoading) {
                CustomSpinner()
            } else {
                List() {
                    ForEach(this.data, (item: string) => {
                        ListItem() {
                            Text(item)
                                .fontSize(24)
                                .fontWeight(FontWeight.Bold)
                                .margin({ top: 10, bottom: 10 })
                        }
                    }, (item: string) => item)
                }
                .width('100%')
                .height('80%')
            }
        }
        .width('100%')
        .height('100%')
        .backgroundColor(Color.White)
    }
}

@Component
struct CustomSpinner {
    @State rotation: number = 0
    private intervalID: number = -1

    aboutToAppear() {
        this.intervalID = setInterval(() => {
            this.rotation = (this.rotation + 12) % 360
        }, 60)
    }

    aboutToDisappear() {
        clearInterval(this.intervalID)
    }

    build() {
        Column() {
            Stack() {
                Circle()
                    .width(80)
                    .height(80)
                    .stroke(Color.Blue)
                    .strokeWidth(8)
                    .strokeDashArray([15, 25])
                    .rotate({ x: 0, y: 0, z: 1, angle: this.rotation })

                Circle()
                    .width(60)
                    .height(60)
                    .stroke(Color.Green)
                    .strokeWidth(6)
                    .strokeDashArray([20, 15])
                    .rotate({ x: 0, y: 0, z: 1, angle: -this.rotation * 1.5 })
            }
            .width(100)
            .height(100)

            Text('Loading...')
                .fontSize(18)
                .fontColor(Color.Gray)
                .margin({ top: 20 })
        }
        .justifyContent(FlexAlign.Center)
        .width('100%')
        .height('100%')
        .backgroundColor(Color.White)
    }
}

