@Entry
@Component
struct TodoList {
  @State tasks: Array<string> = []
  @State completedTasks: Array<boolean> = []
  @State newTask: string = ''

  build() {
    Column() {
      TextInput({ placeholder: 'Enter a new task' })
        .onChange((value: string) => {
          this.newTask = value
        })
        .margin({ bottom: 20 })

      Button('Add Task')
        .onClick(() => {
          if (this.newTask) {
            this.tasks.push(this.newTask)
            this.completedTasks.push(false)
            this.newTask = ''
          }
        })
        .margin({ bottom: 20 })

      ForEach(this.tasks, (task: string, index: number) => {
        Row() {
          Checkbox()
            .select(this.completedTasks[index])
            .onChange((checked: boolean) => {
              this.completedTasks[index] = checked
            })
            .margin({ right: 10 })

          Text(task)
            .decoration({ type: this.completedTasks[index] ? TextDecorationType.LineThrough : TextDecorationType.None })
            .margin({ right: 10 })

          Button() {
            Image($r('app.media.app_icon'))
              .width(20)
              .height(20)
          }
          .onClick(() => {
            this.tasks.splice(index, 1)
            this.completedTasks.splice(index, 1)
          })
        }
        .margin({ top: 10 })
      })
    }
    .padding(20)
  }
}

