@Entry
@Component
struct TouchAreaOptimizationExample {
  @State private isExpanded: boolean = false;
  @State private touchFeedback: boolean = false;

  build() {
    Column() {
      Text('Touch Area Optimization Demo')
        .fontSize(24)
        .fontColor(0x000000)
        .margin({ top: 30, bottom: 20 })

      // Button with optimized touch area using padding
      Button('Tap Here')
        .width(120)
        .height(60)
        .backgroundColor(0x007DFF)
        .fontColor(0xFFFFFF)
        .fontSize(18)
        .padding({ left: 30, right: 30, top: 20, bottom: 20 })
        .onClick(() => {
          console.log('Padded button clicked!');
        })
        .margin({ bottom: 20 })

      // Image with expanded touch area
      Stack() {
        Image($r('app.media.app_icon'))
          .width(80)
          .height(80)
          .onClick(() => {
            console.log('Image clicked!');
          })

        // Invisible touch expansion area
        Rect()
          .width(120)
          .height(120)
          .fill(0x000000)
          .opacity(0)
          .onClick(() => {
            console.log('Expanded image area clicked!');
          })
      }
      .margin({ bottom: 20 })

      // Toggle button for dynamic touch area expansion
      Button(this.isExpanded ? 'Collapse Area' : 'Expand Area')
        .width(150)
        .height(50)
        .backgroundColor(0x4CAF50)
        .fontColor(0xFFFFFF)
        .onClick(() => {
          this.isExpanded = !this.isExpanded;
        })
        .margin({ bottom: 20 })

      // Dynamic touch area expansion
      if (this.isExpanded) {
        Column() {
          Text('Expanded Touch Area')
            .fontSize(16)
            .margin({ bottom: 10 })

          Button('Close')
            .width(100)
            .height(40)
            .backgroundColor(0xFF5722)
            .fontColor(0xFFFFFF)
            .onClick(() => {
              this.isExpanded = false;
            })
            .margin({ top: 10 })
        }
        .width(200)
        .height(120)
        .backgroundColor(0xE3F2FD)
        .padding(20)
        .border({ width: 2, color: 0x2196F3 })
        .borderRadius(8)
      }

      // Custom touch area with visual feedback
      Rect()
        .width(180)
        .height(60)
        .fill(this.touchFeedback ? 0x3F51B5 : 0x2196F3)
        .borderRadius(12)
        .onClick(() => {
          this.touchFeedback = true;
          setTimeout(() => { this.touchFeedback = false; }, 200);
          console.log('Custom touch area clicked!');
        })
        .margin({ top: 20 })

      Text('Tap anywhere in the blue area')
        .fontSize(14)
        .fontColor(0x666666)
        .margin({ top: 10 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(0xF5F5F5)
  }
}

@Entry
@Component
struct ComponentDecoratorExample {
  @State message: string = 'Component Decorators in ArkTS';
  @State counter: number = 0;
  @State isVisible: boolean = true;
  @State textColor: string = '#000000';
  @State bgColor: string = '#FFFFFF';

  @Styles
  primaryButtonStyle() {
    .width(180).height(50).backgroundColor('#0000FF').foregroundColor('#FFFFFF');
  }

  @Styles
  secondaryButtonStyle() {
    .width(180).height(50).backgroundColor('#808080').foregroundColor('#000000');
  }

  build() {
    Column() {
      Text(this.message)
        .fontSize(28)
        .fontWeight(FontWeight.Bold)
        .foregroundColor(this.textColor)
        .margin({ top: 30, bottom: 20 });

      Text(`Counter: ${this.counter}`)
        .fontSize(24)
        .margin(10);

      Image($r('app.media.app_icon'))
        .width(this.isVisible ? 100 : 0)
        .height(this.isVisible ? 100 : 0)
        .margin(10);

      Row() {
        Button('Increment')
          .onClick(() => {
            this.counter += 1;
            this.message = `Count: ${this.counter}`;
          })
          .width(180)
          .height(50)
          .backgroundColor('#808080')
          .foregroundColor('#000000')
          .margin(5);

        Button('Toggle Visibility')
          .onClick(() => {
            this.isVisible = !this.isVisible;
            this.textColor = this.isVisible ? '#000000' : '#808080';
            this.bgColor = this.isVisible ? '#FFFFFF' : '#808080';
          })
          .width(180)
          .height(50)
          .backgroundColor('#808080')
          .foregroundColor('#000000')
          .margin(5);
      }

      Button('Reset All')
        .onClick(() => {
          this.counter = 0;
          this.message = 'Component Decorators in ArkTS';
          this.isVisible = true;
          this.textColor = '#000000';
          this.bgColor = '#FFFFFF';
        })
        .width(200)
        .height(50)
        .backgroundColor('#FF0000')
        .foregroundColor('#FFFFFF')
        .margin(20);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(this.bgColor);
  }
}

@Entry
@Component
struct TextInputCharacterLimitExample {
  @State text: string = ''
  @State errorMessage: string = ''
  controller: TextInputController = new TextInputController()

  private handleInputChange(value: string) {
    if (value.length <= 50) {
      this.text = value
      this.errorMessage = ''
    } else {
      this.errorMessage = 'Input exceeds 50 characters limit!'
    }
  }

  build() {
    Column({ space: 20 }) {
      TextInput({ text: this.text, controller: this.controller, placeholder: 'Enter text (max 50 characters)' })
        .width('90%')
        .height(56)
        .maxLength(50)
        .showUnderline(true)
        .showCounter(true, { thresholdPercentage: 80, highlightBorder: true })
        .border({ width: 1, color: this.errorMessage ? Color.Red : Color.Gray })
        .onChange((value: string) => {
          this.handleInputChange(value)
        })

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(12)
          .fontColor(Color.Red)
          .margin({ top: 5 })
      }

      Text(`Character count: ${this.text.length}/50`)
        .fontSize(14)
        .fontColor(Color.Black)
        .margin({ top: 10 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White)
  }
}

