@Entry
@Component
struct TextAreaFilterExample {
  @State inputText: string = "";
  @State errorMessage: string = "";

  validateInput(value: string): boolean {
    const regex = /^[a-zA-Z0-9\s]*$/;
    return regex.test(value);
  }

  build() {
    Column() {
      TextArea({ placeholder: "Enter alphanumeric text with spaces", text: this.inputText })
        .width("80%")
        .height(150)
        .onChange((value: string) => {
          if (this.validateInput(value)) {
            this.inputText = value;
            this.errorMessage = "";
          } else {
            this.errorMessage = "Only alphanumeric characters and spaces are allowed";
          }
        })

      Text("Filtered Text:")
        .fontSize(16)
        .padding(10)

      Text(this.inputText)
        .fontSize(18)
        .fontColor(Color.Blue)
        .padding(5)

      if (this.errorMessage) {
        Text(this.errorMessage)
          .fontSize(14)
          .fontColor(Color.Red)
          .padding(5)
      }
    }
    .width("100%")
    .height("100%")
    .padding(20)
    .backgroundColor("#ffffff")
  }
}

