@Entry
@Component
struct CustomKeyboardTextArea {
  @State inputText: string = '';
  @State isKeyboardVisible: boolean = true;

  handleButtonClick(button: string): void {
    if (button === 'Backspace') {
      if (this.inputText.length > 0) {
        this.inputText = this.inputText.slice(0, -1);
      }
    } else {
      this.inputText += button;
    }
  }

  build() {
    Column() {
      TextArea({ placeholder: 'Enter text here', text: this.inputText })
        .width('80%')
        .height(150)
        .fontSize(16)
        .margin({ top: 20 })
        .onChange((value: string) => {
          this.inputText = value;
        });

      if (this.isKeyboardVisible) {
        Grid() {
          ForEach(['1', '2', '3', '4', '5', '6', '7', '8', '9', '*', '0', '#'], (button: string) => {
            GridItem() {
              Button(button)
                .width('33%')
                .height(60)
                .backgroundColor(Color.Gray)
                .fontColor(Color.White)
                .onClick(() => this.handleButtonClick(button));
            }
          })
          GridItem() {
            Button('Backspace')
              .width('100%')
              .height(60)
              .backgroundColor(Color.Red)
              .fontColor(Color.White)
              .onClick(() => this.handleButtonClick('Backspace'));
          }
        }
        .columnsTemplate('1fr 1fr 1fr')
        .rowsGap(10)
        .columnsGap(10)
        .margin({ top: 20 })
      }

      Button(this.isKeyboardVisible ? 'Hide Keyboard' : 'Show Keyboard')
        .width('80%')
        .height(50)
        .margin({ top: 20 })
        .onClick(() => {
          this.isKeyboardVisible = !this.isKeyboardVisible;
        });
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White)
  }
}

