@Component
struct SwipeableListItem {
  private item: string = ''
  private index: number = 0
  @State private offsetX: number = 0
  @State private isSwiped: boolean = false
  @State private swipeAction: string = ''

  aboutToAppear() {
    // Initialize properties if needed
  }

  build() {
    Row() {
      Text(this.item)
        .fontSize(18)
        .fontColor(Color.White)
        .padding(10)
        .backgroundColor(Color.Blue)
        .borderRadius(8)
        .width('100%')
        .height(60)
        .gesture(
          PanGesture({ direction: PanDirection.Horizontal })
            .onActionStart(() => {
              this.isSwiped = false
              this.swipeAction = ''
            })
            .onActionUpdate((event: GestureEvent) => {
              this.offsetX = event.offsetX
              if (event.offsetX > 80) {
                this.swipeAction = 'Right Swipe'
              } else if (event.offsetX < -80) {
                this.swipeAction = 'Left Swipe'
              }
            })
            .onActionEnd(() => {
              if (this.offsetX > 80) {
                this.isSwiped = true
                console.log('Swiped Right on ' + this.item)
              } else if (this.offsetX < -80) {
                this.isSwiped = true
                console.log('Swiped Left on ' + this.item)
              }
              animateTo({ duration: 300 }, () => {
                this.offsetX = 0
              })
            })
        )
        .transform({ translate: { x: this.offsetX } })
        .animation({ duration: 300 })

      if (this.swipeAction !== '') {
        Text(this.swipeAction)
          .fontSize(14)
          .fontColor(Color.Black)
          .margin({ left: 10 })
      }
    }
    .width('100%')
    .height(60)
    .margin({ bottom: 10 })
    .justifyContent(FlexAlign.Start)
  }
}

