@Entry
@Component
struct ScalingBehaviorControl {
  @State private scaleX: number = 1.0
  @State private scaleY: number = 1.0
  @State private rotationAngle: number = 0

  build() {
    Column() {
      Text('Component Scaling Behavior Control')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      Row() {
        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
          .scale({ x: this.scaleX, y: this.scaleY })
          .rotate({ angle: this.rotationAngle })
          .margin({ right: 20 })
      }
      .justifyContent(FlexAlign.Center)
      .margin({ bottom: 30 })

      Column() {
        Text(`X Scale: ${this.scaleX.toFixed(1)}`)
          .fontSize(16)
          .margin({ bottom: 5 })

        Slider({
          value: this.scaleX,
          min: 0.1,
          max: 3.0,
          step: 0.1,
          style: SliderStyle.OutSet
        })
        .onChange((value: number) => {
          this.scaleX = value
        })
        .margin({ bottom: 15 })

        Text(`Y Scale: ${this.scaleY.toFixed(1)}`)
          .fontSize(16)
          .margin({ bottom: 5 })

        Slider({
          value: this.scaleY,
          min: 0.1,
          max: 3.0,
          step: 0.1,
          style: SliderStyle.OutSet
        })
        .onChange((value: number) => {
          this.scaleY = value
        })
        .margin({ bottom: 15 })

        Text(`Rotation: ${this.rotationAngle}°`)
          .fontSize(16)
          .margin({ bottom: 5 })

        Slider({
          value: this.rotationAngle,
          min: 0,
          max: 360,
          step: 15,
          style: SliderStyle.OutSet
        })
        .onChange((value: number) => {
          this.rotationAngle = value
        })
        .margin({ bottom: 20 })

        Row() {
          Button('Reset')
            .onClick(() => {
              this.scaleX = 1.0
              this.scaleY = 1.0
              this.rotationAngle = 0
            })
            .margin({ right: 10 })

          Button('Double Size')
            .onClick(() => {
              this.scaleX = 2.0
              this.scaleY = 2.0
            })
            .margin({ right: 10 })

          Button('Half Size')
            .onClick(() => {
              this.scaleX = 0.5
              this.scaleY = 0.5
            })
        }
        .justifyContent(FlexAlign.Center)
      }
      .padding(20)
      .backgroundColor(0xfff8dc)
      .borderRadius(10)
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(0xf5f5f5)
  }
}

import promptAction from '@ohos.promptAction';

@Entry
@Component
struct ActionSheetOffsetApp {
  build() {
    Column() {
      Button('Show Top-Left ActionSheet')
        .onClick(() => {
          promptAction.showDialog({
            title: 'Top-Left Position',
            message: 'ActionSheet with top-left offset',
            buttons: [
              {
                text: 'Option 1',
                color: '#000000'
              },
              {
                text: 'Option 2',
                color: '#000000'
              },
              {
                text: 'Cancel',
                color: '#FF0000'
              }
            ],
            alignment: DialogAlignment.TopStart,
            offset: { dx: 20, dy: 20 }
          }).then((data) => {
            promptAction.showToast({ message: `Selected option ${data.index + 1}` });
          });
        })
        .margin(10)

      Button('Show Center ActionSheet')
        .onClick(() => {
          promptAction.showDialog({
            title: 'Center Position',
            message: 'ActionSheet with center offset',
            buttons: [
              {
                text: 'Confirm',
                color: '#007AFF'
              },
              {
                text: 'Delete',
                color: '#FF3B30'
              }
            ],
            alignment: DialogAlignment.Center,
            offset: { dx: 0, dy: 0 }
          }).then((data) => {
            promptAction.showToast({ message: data.index === 0 ? 'Confirmed' : 'Deleted' });
          });
        })
        .margin(10)

      Button('Show Bottom-Right ActionSheet')
        .onClick(() => {
          promptAction.showDialog({
            title: 'Bottom-Right Position',
            message: 'ActionSheet with bottom-right offset',
            buttons: [
              {
                text: 'Save',
                color: '#34C759'
              },
              {
                text: 'Discard',
                color: '#FF9500'
              }
            ],
            alignment: DialogAlignment.BottomEnd,
            offset: { dx: -20, dy: -20 }
          }).then((data) => {
            promptAction.showToast({ message: data.index === 0 ? 'Saved successfully' : 'Changes discarded' });
          });
        })
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor('#F1F1F1')
  }
}

