@Entry
@Component
struct TextClockModifierExample {
  @State isBold: boolean = false
  @State fontColor: string = "#000000"
  @State fontSize: number = 30
  @State showSeconds: boolean = true
  @State timeFormat: string = "hh:mm:ss"

  build() {
    Column() {
      TextClock()
        .format(this.timeFormat)
        .fontSize(this.fontSize)
        .fontWeight(this.isBold ? FontWeight.Bold : FontWeight.Normal)
        .fontColor(this.fontColor)
        .margin(20)
        .onClick(() => {
          this.isBold = !this.isBold
          this.fontColor = this.isBold ? "#FF0000" : "#000000"
        })

      Row({ space: 10 }) {
        Button("Bold Toggle")
          .width(120)
          .height(40)
          .onClick(() => {
            this.isBold = !this.isBold
          })

        Button("Size +")
          .width(80)
          .height(40)
          .onClick(() => {
            this.fontSize += 5
          })

        Button("Size -")
          .width(80)
          .height(40)
          .onClick(() => {
            this.fontSize = Math.max(20, this.fontSize - 5)
          })
      }
      .margin(10)

      Row({ space: 10 }) {
        Button("Red")
          .width(80)
          .height(40)
          .backgroundColor(Color.Red)
          .onClick(() => {
            this.fontColor = "#FF0000"
          })

        Button("Blue")
          .width(80)
          .height(40)
          .backgroundColor(Color.Blue)
          .onClick(() => {
            this.fontColor = "#0000FF"
          })

        Button("Green")
          .width(80)
          .height(40)
          .backgroundColor(Color.Green)
          .onClick(() => {
            this.fontColor = "#00FF00"
          })
      }
      .margin(10)

      Row({ space: 10 }) {
        Button("12h Format")
          .width(100)
          .height(40)
          .onClick(() => {
            this.timeFormat = this.showSeconds ? "hh:mm:ss a" : "hh:mm a"
          })

        Button("24h Format")
          .width(100)
          .height(40)
          .onClick(() => {
            this.timeFormat = this.showSeconds ? "HH:mm:ss" : "HH:mm"
          })

        Button("Toggle Seconds")
          .width(120)
          .height(40)
          .onClick(() => {
            this.showSeconds = !this.showSeconds
            if (this.timeFormat.includes("HH")) {
              this.timeFormat = this.showSeconds ? "HH:mm:ss" : "HH:mm"
            } else {
              this.timeFormat = this.showSeconds ? "hh:mm:ss a" : "hh:mm a"
            }
          })
      }
      .margin(10)

      Button("Reset All")
        .width(150)
        .height(50)
        .onClick(() => {
          this.isBold = false
          this.fontColor = "#000000"
          this.fontSize = 30
          this.showSeconds = true
          this.timeFormat = "hh:mm:ss"
        })
        .margin(20)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor("#F5F5F5")
  }
}

