@Entry
@Component
struct ColorInversionApp {
  @State originalColor: string = '#3366FF'
  @State invertedColor: string = this.invertColor(this.originalColor)
  @State isInverted: boolean = false

  invertColor(hexColor: string): string {
    let color = hexColor.replace('#', '')
    let r = parseInt(color.substring(0, 2), 16)
    let g = parseInt(color.substring(2, 4), 16)
    let b = parseInt(color.substring(4, 6), 16)
    r = 255 - r
    g = 255 - g
    b = 255 - b
    return `#${r.toString(16).padStart(2, '0')}${g.toString(16).padStart(2, '0')}${b.toString(16).padStart(2, '0')}`
  }

  build() {
    Column() {
      Text('Color Inversion Demo')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 30 })

      Row() {
        Column() {
          Text('Original')
            .fontSize(18)
            .margin({ bottom: 10 })
          Row()
            .width(120)
            .height(120)
            .backgroundColor(this.originalColor)
            .borderRadius(15)
          Text(this.originalColor)
            .fontSize(14)
            .margin({ top: 10 })
        }
        .margin({ right: 20 })

        Column() {
          Text('Inverted')
            .fontSize(18)
            .margin({ bottom: 10 })
          Row()
            .width(120)
            .height(120)
            .backgroundColor(this.invertedColor)
            .borderRadius(15)
          Text(this.invertedColor)
            .fontSize(14)
            .margin({ top: 10 })
        }
      }
      .margin({ bottom: 30 })

      Image($r('app.media.app_icon'))
        .width(150)
        .height(150)
        .colorBlend(this.isInverted ? this.invertedColor : this.originalColor)
        .margin({ bottom: 30 })

      Button('Toggle Inversion')
        .onClick(() => {
          this.isInverted = !this.isInverted
        })
        .margin({ bottom: 20 })

      Button('Change Color')
        .onClick(() => {
          const randomColor = `#${Math.floor(Math.random() * 16777215).toString(16).padStart(6, '0')}`
          this.originalColor = randomColor
          this.invertedColor = this.invertColor(randomColor)
          this.isInverted = false
        })
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

