import promptAction from '@ohos.promptAction';

@Entry
@Component
struct TextDataDetectionCallbackExample {
  @State detectedData: string = '';
  @State inputText: string = '';
  @State detectionResults: string[] = [];

  detectDataTypes(text: string) {
    this.detectionResults = [];

    const emailMatches = text.match(/\S+@\S+\.\S+/g);
    const urlMatches = text.match(/https?:\/\/\S+/g);
    const phoneMatches = text.match(/\+\d[\d -]{8,12}\d|\d{3}[-.]\d{3}[-.]\d{4}/g);

    if (emailMatches) {
      emailMatches.forEach(email => {
        this.detectionResults.push(`Email: ${email}`);
      });
    }

    if (urlMatches) {
      urlMatches.forEach(url => {
        this.detectionResults.push(`URL: ${url}`);
      });
    }

    if (phoneMatches) {
      phoneMatches.forEach(phone => {
        this.detectionResults.push(`Phone: ${phone}`);
      });
    }

    this.detectedData = this.detectionResults.length > 0 ? this.detectionResults.join('\n') : 'No data detected';
  }

  handleDetectionCallback(result: string) {
    promptAction.showToast({ message: result, duration: 3000 });
  }

  build() {
    Column() {
      TextInput({ placeholder: 'Enter text with emails, URLs, or phone numbers' })
        .width('100%')
        .height(50)
        .backgroundColor('#f5f5f5')
        .padding({ left: 12 })
        .onChange((value: string) => {
          this.inputText = value;
          this.detectDataTypes(value);
        })

      Button('Detect Data')
        .width('80%')
        .height(50)
        .margin({ top: 20 })
        .onClick(() => {
          this.detectDataTypes(this.inputText);
          if (this.detectionResults.length > 0) {
            this.handleDetectionCallback(`Found ${this.detectionResults.length} data types`);
          }
        })

      if (this.detectedData) {
        Text(this.detectedData)
          .fontSize(16)
          .margin({ top: 20 })
          .width('90%')
          .textAlign(TextAlign.Start)
          .onClick(() => {
            this.handleDetectionCallback('Click detected data to view details');
          })
      }

      if (this.detectionResults.length > 0) {
        ForEach(this.detectionResults, (result: string, index: number) => {
          Text(result)
            .fontSize(14)
            .margin({ top: 10 })
            .padding(8)
            .backgroundColor('#e8f5e8')
            .borderRadius(5)
            .onClick(() => {
              this.handleDetectionCallback(`Selected: ${result}`);
            })
        })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#ffffff')
  }
}

