@Entry
@Component
struct ProgressBarColorLoader {
  @State progressValue: number = 0;
  @State progressColor: ResourceColor = Color.Blue;
  @State isLoading: boolean = false;

  startLoading() {
    if (this.isLoading) return;

    this.isLoading = true;
    this.progressValue = 0;
    this.progressColor = Color.Orange;

    const interval = setInterval(() => {
      if (this.progressValue < 100) {
        this.progressValue += 5;

        if (this.progressValue <= 30) {
          this.progressColor = Color.Orange;
        } else if (this.progressValue <= 70) {
          this.progressColor = Color.Gray;
        } else {
          this.progressColor = Color.Green;
        }
      } else {
        clearInterval(interval);
        this.isLoading = false;
      }
    }, 200);
  }

  resetProgress() {
    this.progressValue = 0;
    this.progressColor = Color.Blue;
    this.isLoading = false;
  }

  build() {
    Column({ space: 20 }) {
      Text('Progress Bar Color Loader')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 30 });

      Progress({
        value: this.progressValue,
        total: 100,
        type: ProgressType.Linear
      })
      .width('80%')
      .height(25)
      .color(this.progressColor)
      .backgroundColor(0xF0F0F0)
      .borderRadius(12)

      Text(`${this.progressValue}% Complete`)
        .fontSize(16)
        .fontColor(this.progressColor)

      Row({ space: 15 }) {
        Button('Start Loading')
          .onClick(() => {
            this.startLoading();
          })
          .enabled(!this.isLoading)

        Button('Reset')
          .onClick(() => {
            this.resetProgress();
          })
      }
      .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(0xFFFFFF)
    .justifyContent(FlexAlign.Center)
  }
}

