@Entry
@Component
struct DragStatusApp {
  @State dragStatus: DragStatus = DragStatus.Idle;
  @State offsetX: number = 0;
  @State offsetY: number = 0;
  @State initialX: number = 0;
  @State initialY: number = 0;

  private handleTouchDown() {
    this.dragStatus = DragStatus.Dragging;
  }

  private handleTouchMove(event: TouchEvent) {
    if (this.dragStatus === DragStatus.Dragging) {
      this.offsetX = this.initialX + event.touches[0].x;
      this.offsetY = this.initialY + event.touches[0].y;
    }
  }

  private handleTouchUp() {
    this.dragStatus = DragStatus.Ended;
  }

  build() {
    Column() {
      Button(this.dragStatus === DragStatus.Dragging ? 'End Drag' : 'Start Drag')
        .onClick(() => {
          if (this.dragStatus === DragStatus.Dragging) {
            this.dragStatus = DragStatus.Ended;
          } else {
            this.dragStatus = DragStatus.Dragging;
          }
        })
        .margin({ bottom: 20 });

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .position({ x: this.offsetX, y: this.offsetY })
        .onTouch((event: TouchEvent) => {
          if (event.type === TouchType.Down) {
            this.initialX = this.offsetX;
            this.initialY = this.offsetY;
            this.handleTouchDown();
          } else if (event.type === TouchType.Move) {
            this.handleTouchMove(event);
          } else if (event.type === TouchType.Up) {
            this.handleTouchUp();
          }
        });

      Text(`Drag Status: ${DragStatus[this.dragStatus]}`)
        .fontSize(18)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

enum DragStatus {
  Idle,
  Dragging,
  Ended
}

