@Entry
@Component
struct PreviewStyleAnimation {
  @State previewScale: number = 1.0
  @State previewOpacity: number = 1.0
  @State previewRotation: number = 0

  private animatePreview() {
    setInterval(() => {
      animateTo({
        duration: 800,
        curve: Curve.EaseInOut
      }, () => {
        this.previewScale = this.previewScale === 1.0 ? 1.3 : 1.0
        this.previewOpacity = this.previewOpacity === 1.0 ? 0.6 : 1.0
        this.previewRotation = this.previewRotation === 0 ? 45 : 0
      })
    }, 1500)
  }

  aboutToAppear() {
    this.animatePreview()
  }

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(120)
        .height(120)
        .scale({ x: this.previewScale, y: this.previewScale })
        .opacity(this.previewOpacity)
        .rotate({ angle: this.previewRotation })
        .animation({ duration: 800, curve: Curve.EaseInOut })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor($r('sys.color.ohos_id_color_background'))
  }
}

