@Entry
@Component
struct FocusEventHandlingApp {
  @State isFocused: boolean = false;
  @State message: string = 'No component focused';
  @State buttonFocused: boolean = false;
  @State inputFocused: boolean = false;

  build() {
    Column() {
      TextInput({ placeholder: 'Enter text here' })
        .width(300)
        .height(50)
        .backgroundColor(this.inputFocused ? Color.Green : Color.White)
        .onFocus(() => {
          this.isFocused = true;
          this.inputFocused = true;
          this.message = 'TextInput is focused';
          console.info('TextInput gained focus');
        })
        .onBlur(() => {
          this.inputFocused = false;
          this.updateFocusStatus();
          this.message = 'TextInput lost focus';
          console.info('TextInput lost focus');
        })
        .margin(20)

      Button('Focusable Button')
        .width(200)
        .height(50)
        .backgroundColor(this.buttonFocused ? Color.Blue : Color.Gray)
        .onFocus(() => {
          this.isFocused = true;
          this.buttonFocused = true;
          this.message = 'Button is focused';
          console.info('Button gained focus');
        })
        .onBlur(() => {
          this.buttonFocused = false;
          this.updateFocusStatus();
          this.message = 'Button lost focus';
          console.info('Button lost focus');
        })
        .margin(20)

      Text(this.message)
        .fontSize(18)
        .fontColor(Color.Black)
        .margin({ top: 30 })

      Text('Focus Status: ' + (this.isFocused ? 'FOCUSED' : 'NOT FOCUSED'))
        .fontSize(16)
        .fontColor(this.isFocused ? Color.Green : Color.Red)
        .margin({ top: 10 })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(Color.White)
  }

  private updateFocusStatus(): void {
    this.isFocused = this.buttonFocused || this.inputFocused;
    if (!this.isFocused) {
      this.message = 'No component focused';
    }
  }
}

