@Entry
@Component
struct TextChangeHandler {
  @State currentText: string = "Default Text"
  @State previousText: string = ""
  @State changeCount: number = 0

  build() {
    Column() {
      Text("Current Text: " + this.currentText)
        .fontSize(18)
        .margin(10)

      Text("Previous Text: " + this.previousText)
        .fontSize(16)
        .margin(10)
        .fontColor(Color.Gray)

      Text("Change Count: " + this.changeCount)
        .fontSize(16)
        .margin(10)
        .fontColor(Color.Blue)

      TextInput({ placeholder: "Enter text to track changes" })
        .width(300)
        .height(50)
        .margin(20)
        .border({ width: 1, color: Color.Black })
        .onChange((newText: string) => {
          this.previousText = this.currentText
          this.currentText = newText
          this.changeCount += 1
          console.log(`Text changed from "${this.previousText}" to "${this.currentText}"`)
          console.log(`Total changes: ${this.changeCount}`)
        })

      Button("Reset All")
        .width(150)
        .height(40)
        .margin(10)
        .onClick(() => {
          this.previousText = this.currentText
          this.currentText = "Default Text"
          this.changeCount = 0
        })

      Button("Undo Last Change")
        .width(200)
        .height(40)
        .margin(10)
        .onClick(() => {
          if (this.previousText) {
            let temp = this.currentText
            this.currentText = this.previousText
            this.previousText = temp
            this.changeCount += 1
          }
        })
    }
    .width("100%")
    .height("100%")
    .padding(20)
    .backgroundColor("#f5f5f5")
  }
}

