struct DragStatusCallbackExample {
  @State isDragging: boolean = false;
  @State callbacksEnabled: boolean = true;

  private dragStartCallback: () => void = () => {
    if (this.callbacksEnabled) {
      this.isDragging = true;
      console.log("Drag started - callback active");
    }
  };

  private dragEndCallback: () => void = () => {
    if (this.callbacksEnabled) {
      this.isDragging = false;
      console.log("Drag ended - callback active");
    }
  };

  build() {
    Column({ space: 20 }) {
      Text(this.isDragging ? 'Dragging Active' : 'Ready to Drag')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .textAlign(TextAlign.Center)
        .margin({ bottom: 20 });

      Image($r('app.media.icon'))
        .width(120)
        .height(120)
        .border({ width: 2, color: Color.Blue })
        .borderRadius(10)
        .gesture(
          GestureGroup(GestureMode.Parallel,
            PanGesture({ distance: 5 })
              .onActionStart(() => {
                this.dragStartCallback();
              })
              .onActionEnd(() => {
                this.dragEndCallback();
              })
          )
        );

      Button(this.callbacksEnabled ? "Disable Drag Callbacks" : "Callbacks Disabled")
        .width(200)
        .height(40)
        .backgroundColor(this.callbacksEnabled ? Color.Blue : Color.Gray)
        .onClick(() => {
          this.callbacksEnabled = !this.callbacksEnabled;
          console.log(`Drag callbacks ${this.callbacksEnabled ? 'enabled' : 'disabled'}`);
        });

      Text(`Callbacks: ${this.callbacksEnabled ? 'Enabled' : 'Disabled'}`)
        .fontSize(14)
        .fontColor(this.callbacksEnabled ? Color.Green : Color.Red);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#F5F5F5');
  }
}

