@Entry
@Component
struct DragAndDropInfoExample {
  @State dragSource: string = '';
  @State dropTarget: string = '';
  @State dragData: string = '';
  @State isDragging: boolean = false;
  @State dropResult: string = '';

  @State dragHistory: Array<DragHistoryItem> = [];

  private dragHistoryItem: DragHistoryItem = {
    sourceComponent: '',
    targetComponent: '',
    data: '',
    timestamp: 0,
    dragType: '',
    success: false,
    positionX: 0,
    positionY: 0
  };

  build() {
    Column() {
      Text('Drag and Drop Info Demo')
        .fontSize(24)
        .margin({ bottom: 20 });

      Row() {
        Column() {
          Text('Source Items')
            .fontSize(18)
            .margin({ bottom: 10 });

          ForEach(['Item 1', 'Item 2', 'Item 3'], (item: string) => {
            Text(item)
              .fontSize(16)
              .padding(10)
              .backgroundColor(this.isDragging && this.dragData === item ? 0x808080 : 0x0000FF)
              .border({ width: 1, color: 0x000000 })
              .margin({ bottom: 5 })
              .onTouch((event: TouchEvent) => {
                if (event.type === TouchType.Down) {
                  this.dragData = item;
                  this.dragSource = 'SourceColumn';
                  this.isDragging = true;
                }
              });
          });
        }
        .width('45%')
        .padding(10);

        Column() {
          Text('Target Area')
            .fontSize(18)
            .margin({ bottom: 10 });

          Text(this.dropTarget || 'Drop here')
            .fontSize(16)
            .padding(20)
            .backgroundColor(this.dropTarget ? 0x00FF00 : 0xFFFFFF)
            .border({ width: 2, color: 0x000000, style: BorderStyle.Solid })
            .onTouch((event: TouchEvent) => {
              if (event.type === TouchType.Up && this.isDragging) {
                this.dropTarget = this.dragData;
                this.dropResult = 'Success';

                const dragInfo: DragHistoryItem = {
                  sourceComponent: this.dragSource,
                  targetComponent: 'TargetColumn',
                  data: this.dragData,
                  timestamp: new Date().getTime(),
                  dragType: 'text',
                  success: true,
                  positionX: 0,
                  positionY: 0
                };
                this.dragHistory.push(dragInfo);
                this.isDragging = false;
                this.dragData = '';
              }
            });
        }
        .width('45%')
        .padding(10);
      }

      Divider()
        .margin({ top: 20, bottom: 20 });

      Text('Drag History:')
        .fontSize(18)
        .margin({ bottom: 10 });

      Scroll() {
        Column() {
          ForEach(this.dragHistory, (info: DragHistoryItem, index: number) => {
            Column() {
              Text(`Event ${index + 1}: ${info.data}`)
                .fontSize(14);
              Text(`From: ${info.sourceComponent}, To: ${info.targetComponent}`)
                .fontSize(12)
                .fontColor(0x808080);
              Text(`Time: ${new Date(info.timestamp).toLocaleTimeString()}`)
                .fontSize(12)
                .fontColor(0x808080);
            }
            .padding(5)
            .border({ width: 1, color: 0xD3D3D3 })
            .margin({ bottom: 5 });
          });
        }
      }
      .height(150);
    }
    .width('100%')
    .height('100%')
    .padding(20);
  }
}

interface DragHistoryItem {
  sourceComponent: string;
  targetComponent: string;
  data: string;
  timestamp: number;
  dragType: string;
  success: boolean;
  positionX: number;
  positionY: number;
}

