@Entry
@Component
struct AnimationConfigurationExample {
  @State private scaleValue: number = 1.0
  @State private opacityValue: number = 1.0
  @State private rotationValue: number = 0
  @State private isAnimating: boolean = false

  build() {
    Column({ space: 20 }) {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .opacity(this.opacityValue)
        .rotate({ angle: this.rotationValue })
        .animation({
          duration: 1000,
          curve: Curve.EaseInOut,
          iterations: 1,
          playMode: PlayMode.Normal
        })
        .onClick(() => {
          animateTo({
            duration: 1500,
            curve: Curve.EaseInOut
          }, () => {
            this.scaleValue = this.scaleValue === 1.0 ? 1.8 : 1.0
            this.opacityValue = this.opacityValue === 1.0 ? 0.6 : 1.0
            this.rotationValue = this.rotationValue === 0 ? 360 : 0
          })
        })

      Button(this.isAnimating ? "Reset Animation" : "Start Animation")
        .onClick(() => {
          this.isAnimating = !this.isAnimating
          if (this.isAnimating) {
            animateTo({
              duration: 2000,
              curve: Curve.EaseInOut,
              delay: 200
            }, () => {
              this.scaleValue = 2.0
              this.opacityValue = 0.3
              this.rotationValue = 180
            })
          } else {
            animateTo({
              duration: 1000,
              curve: Curve.EaseOut
            }, () => {
              this.scaleValue = 1.0
              this.opacityValue = 1.0
              this.rotationValue = 0
            })
          }
        })
        .margin({ top: 30 })
        .backgroundColor(Color.Blue)
        .fontColor(Color.White)
        .width("60%")
        .height(45)

      Button("Bounce Effect")
        .onClick(() => {
          animateTo({
            duration: 800,
            curve: Curve.EaseOut
          }, () => {
            this.scaleValue = 1.5
          })
          setTimeout(() => {
            animateTo({
              duration: 600,
              curve: Curve.EaseIn
            }, () => {
              this.scaleValue = 1.0
            })
          }, 800)
        })
        .backgroundColor(Color.Green)
        .fontColor(Color.White)
        .width("60%")
        .height(45)
    }
    .width("100%")
    .height("100%")
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(Color.White)
  }
}

