    .backgroundColor("#ffffff");
  }

  private applyNormalAttribute(configType: string): void {
    this.isNormalAttributeApplied = true;

    if (configType === "default") {
      console.log("Applying default normal attribute configuration");
    } else if (configType === "custom") {
      console.log("Applying custom normal attribute configuration");
    }

    console.log("Normal attributes configured and applied to UI elements.");
  }
}

