@Entry
@Component
struct LocationButtonClickHandler {
  @State isLocationActive: boolean = false;
  @State locationStatus: string = 'Location Inactive';
  @State currentLatitude: number = 0;
  @State currentLongitude: number = 0;
  @State clickCount: number = 0;

  build() {
    Column() {
      Button('Activate Location')
        .width('80%')
        .height(60)
        .backgroundColor(this.isLocationActive ? '#4CAF50' : '#2196F3')
        .fontColor(Color.White)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .borderRadius(12)
        .onClick(() => {
          this.isLocationActive = !this.isLocationActive;
          this.clickCount += 1;

          if (this.isLocationActive) {
            this.locationStatus = 'Acquiring Location...';
            setTimeout(() => {
              this.currentLatitude = 34.0522;
              this.currentLongitude = -118.2437;
              this.locationStatus = 'Location Active';
            }, 1500);
          } else {
            this.locationStatus = 'Location Inactive';
            this.currentLatitude = 0;
            this.currentLongitude = 0;
          }
        })
        .margin({ top: 30, bottom: 20 });

      Text(`Status: ${this.locationStatus}`)
        .fontSize(18)
        .fontWeight(FontWeight.Medium)
        .margin({ bottom: 15 });

      Text(`Click Count: ${this.clickCount}`)
        .fontSize(16)
        .margin({ bottom: 20 });

      if (this.isLocationActive) {
        Image($r('app.media.app_icon'))
          .width(120)
          .height(120)
          .margin({ bottom: 20 });

        Text(`Latitude: ${this.currentLatitude.toFixed(4)}`)
          .fontSize(16)
          .margin({ bottom: 8 });

        Text(`Longitude: ${this.currentLongitude.toFixed(4)}`)
          .fontSize(16)
          .margin({ bottom: 20 });

        Button('Refresh Location')
          .width(200)
          .height(45)
          .backgroundColor('#FF9800')
          .fontColor(Color.White)
          .fontSize(16)
          .onClick(() => {
            this.locationStatus = 'Refreshing...';
            setTimeout(() => {
              this.currentLatitude = 34.0522 + (Math.random() - 0.5) * 0.01;
              this.currentLongitude = -118.2437 + (Math.random() - 0.5) * 0.01;
              this.locationStatus = 'Location Updated';
              this.clickCount += 1;
            }, 1000);
          })
          .margin({ bottom: 15 });
      }

      Button('Reset All')
        .width(150)
        .height(40)
        .backgroundColor('#F44336')
        .fontColor(Color.White)
        .fontSize(14)
        .onClick(() => {
          this.isLocationActive = false;
          this.locationStatus = 'Location Inactive';
          this.currentLatitude = 0;
          this.currentLongitude = 0;
          this.clickCount = 0;
        });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#FAFAFA');
  }
}

@Entry
@Component
struct ParallelGestureExample {
  @State offsetX: number = 0;
  @State offsetY: number = 0;
  @State scaleValue: number = 1;
  @State rotationAngle: number = 0;
  @State message: string = 'Perform parallel gestures on the box';

  build() {
    Column() {
      Text(this.message)
        .fontSize(20)
        .margin({ bottom: 20 });

      Row()
        .width(200)
        .height(200)
        .backgroundColor(Color.Green)
        .borderRadius(10)
        .gesture(
          GestureGroup(
            GestureMode.Parallel,
            PanGesture({ direction: PanDirection.All })
              .onActionStart(() => {
                this.message = 'Pan gesture started';
              })
              .onActionUpdate((event: GestureEvent) => {
                this.offsetX = event.offsetX;
                this.offsetY = event.offsetY;
                this.message = `Panning: X: ${this.offsetX}, Y: ${this.offsetY}`;
              })
              .onActionEnd(() => {
                this.message = 'Pan gesture ended';
              }),
            PinchGesture()
              .onActionStart(() => {
                this.message = 'Pinch gesture started';
              })
              .onActionUpdate((event: PinchGestureEvent) => {
                this.scaleValue = event.scale;
                this.message = `Pinching: Scale: ${this.scaleValue.toFixed(2)}`;
              })
              .onActionEnd(() => {
                this.message = 'Pinch gesture ended';
              }),
            RotationGesture()
              .onActionStart(() => {
                this.message = 'Rotation gesture started';
              })
              .onActionUpdate((event: RotationGestureEvent) => {
                this.rotationAngle = event.angle;
                this.message = `Rotating: Angle: ${this.rotationAngle.toFixed(2)}°`;
              })
              .onActionEnd(() => {
                this.message = 'Rotation gesture ended';
              })
          )
        )
        .transform({
          translate: { x: this.offsetX, y: this.offsetY },
          scale: { x: this.scaleValue, y: this.scaleValue },
          rotate: { angle: this.rotationAngle }
        })
        .animation({ duration: 300 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

