@Entry
@Component
struct MotionBlurEffect {
  @State private blurRadius: number = 0;
  @State private imageOpacity: number = 1;
  @State private isAnimating: boolean = false;

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .blur(this.blurRadius)
        .opacity(this.imageOpacity)
        .margin(20)
        .onClick(() => {
          this.isAnimating = !this.isAnimating;
          if (this.isAnimating) {
            this.animateBlurEffect();
          }
        })

      Text("Blur Radius: " + this.blurRadius.toFixed(1))
        .fontSize(16)
        .margin({ top: 10 })

      Slider({ value: this.blurRadius, min: 0, max: 15 })
        .onChange((value: number) => {
          this.blurRadius = value;
          this.isAnimating = false;
        })
        .width('80%')
        .margin(10)

      Text("Opacity: " + this.imageOpacity.toFixed(1))
        .fontSize(16)
        .margin({ top: 10 })

      Slider({ value: this.imageOpacity, min: 0, max: 1 })
        .onChange((value: number) => {
          this.imageOpacity = value;
        })
        .width('80%')
        .margin(10)

      Button(this.isAnimating ? 'Stop Animation' : 'Start Animation')
        .onClick(() => {
          this.isAnimating = !this.isAnimating;
          if (this.isAnimating) {
            this.animateBlurEffect();
          }
        })
        .margin(20)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }

  private animateBlurEffect(): void {
    let targetBlur = this.blurRadius === 0 ? 12 : 0;
    let duration = 1000;

    animateTo({ duration: duration, curve: Curve.EaseInOut }, () => {
      this.blurRadius = targetBlur;
    });
  }
}

