@Entry
@Component
struct SimultaneousGestureBinding {
  @State offsetX: number = 0
  @State offsetY: number = 0
  @State rotation: number = 0
  @State scaleValue: number = 1
  @State message: string = 'Interact with the box'

  build() {
    Column() {
      Text(this.message)
        .fontSize(18)
        .margin({ bottom: 20 })

      Row()
        .width(150)
        .height(150)
        .backgroundColor(Color.Blue)
        .borderRadius(15)
        .gesture(
          GestureGroup(
            GestureMode.Parallel,
            PanGesture({ direction: PanDirection.All })
              .onActionStart(() => {
                this.message = 'Pan gesture started'
              })
              .onActionUpdate((event: GestureEvent) => {
                this.offsetX = event.offsetX
                this.offsetY = event.offsetY
                this.message = `Panning: X: ${this.offsetX.toFixed(1)}, Y: ${this.offsetY.toFixed(1)}`
              })
              .onActionEnd(() => {
                animateTo({ duration: 400 }, () => {
                  this.offsetX = 0
                  this.offsetY = 0
                })
                this.message = 'Interact with the box'
              }),
            PinchGesture()
              .onActionStart(() => {
                this.message = 'Pinch gesture started'
              })
              .onActionUpdate((event: GestureEvent) => {
                this.scaleValue = event.scale
                this.message = `Scaling: ${this.scaleValue.toFixed(2)}`
              })
              .onActionEnd(() => {
                animateTo({ duration: 400 }, () => {
                  this.scaleValue = 1
                })
                this.message = 'Interact with the box'
              }),
            RotationGesture()
              .onActionStart(() => {
                this.message = 'Rotation gesture started'
              })
              .onActionUpdate((event: GestureEvent) => {
                this.rotation = event.angle
                this.message = `Rotating: ${this.rotation.toFixed(1)}\u00b0`
              })
              .onActionEnd(() => {
                animateTo({ duration: 400 }, () => {
                  this.rotation = 0
                })
                this.message = 'Interact with the box'
              })
          )
        )
        .transform([
          { translate: { x: this.offsetX, y: this.offsetY } },
          { scale: { x: this.scaleValue, y: this.scaleValue } },
          { rotate: { angle: this.rotation, centerX: '50%', centerY: '50%' } }
        ])
        .animation({ duration: 400, curve: Curve.EaseOut })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20)
  }
}

