@Component
struct RenderFitConfiguration {
  @State selectedRenderFit: string = 'FIT_ORIGINAL';
  @State isConfigVisible: boolean = false;

  build() {
    Column() {
      Text('RenderFit Configuration')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Button('Show RenderFit Options')
        .width('80%')
        .height(40)
        .backgroundColor('#007AFF')
        .onClick(() => {
          this.isConfigVisible = !this.isConfigVisible;
        });

      if (this.isConfigVisible) {
        Column() {
          Text('Current Selection: ' + this.selectedRenderFit)
            .fontSize(16)
            .margin({ bottom: 10 });

          Button('FIT_ORIGINAL')
            .width('80%')
            .height(40)
            .margin({ bottom: 5 })
            .backgroundColor(this.selectedRenderFit === 'FIT_ORIGINAL' ? '#34C759' : '#CCCCCC')
            .onClick(() => {
              this.selectedRenderFit = 'FIT_ORIGINAL';
            });

          Button('FIT_CENTER')
            .width('80%')
            .height(40)
            .margin({ bottom: 5 })
            .backgroundColor(this.selectedRenderFit === 'FIT_CENTER' ? '#34C759' : '#CCCCCC')
            .onClick(() => {
              this.selectedRenderFit = 'FIT_CENTER';
            });

          Button('FIT_XY')
            .width('80%')
            .height(40)
            .margin({ bottom: 5 })
            .backgroundColor(this.selectedRenderFit === 'FIT_XY' ? '#34C759' : '#CCCCCC')
            .onClick(() => {
              this.selectedRenderFit = 'FIT_XY';
            });

          Button('FIT_START')
            .width('80%')
            .height(40)
            .margin({ bottom: 5 })
            .backgroundColor(this.selectedRenderFit === 'FIT_START' ? '#34C759' : '#CCCCCC')
            .onClick(() => {
              this.selectedRenderFit = 'FIT_START';
            });

          Button('FIT_END')
            .width('80%')
            .height(40)
            .backgroundColor(this.selectedRenderFit === 'FIT_END' ? '#34C759' : '#CCCCCC')
            .onClick(() => {
              this.selectedRenderFit = 'FIT_END';
            });
        }
        .width('100%')
        .margin({ top: 20 })
        .padding(10)
        .backgroundColor('#F5F5F5')
        .borderRadius(8);
      }

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 20 })
        .objectFit(this.getObjectFitValue());
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .padding(20)
  }

  private getObjectFitValue(): ImageFit {
    switch (this.selectedRenderFit) {
      case 'FIT_ORIGINAL':
        return ImageFit.Contain;
      case 'FIT_CENTER':
        return ImageFit.Cover;
      case 'FIT_XY':
        return ImageFit.Fill;
      case 'FIT_START':
        return ImageFit.ScaleDown;
      case 'FIT_END':
        return ImageFit.None;
      default:
        return ImageFit.Contain;
    }
  }
}

