@Entry
@Component
struct CheckboxGroupModifierExample {
  @State selectedOptions: string[] = [];

  private options: Array<Option> = [
    { name: 'option1', label: 'Option 1' },
    { name: 'option2', label: 'Option 2' },
    { name: 'option3', label: 'Option 3' }
  ];

  build() {
    Column() {
      Text('Checkbox Group Example')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 30 })

      Column() {
        ForEach(this.options, (option: Option) => {
          Row() {
            Checkbox({ name: option.name, group: 'checkboxGroup' })
              .select(this.selectedOptions.includes(option.name))
              .selectedColor(0x39a2db)
              .shape(CheckBoxShape.ROUNDED_SQUARE)
              .width(30)
              .height(30)
              .onChange((value: boolean) => {
                let updatedOptions = [...this.selectedOptions];
                if (value) {
                  if (!updatedOptions.includes(option.name)) {
                    updatedOptions.push(option.name);
                  }
                } else {
                  const index = updatedOptions.indexOf(option.name);
                  if (index !== -1) {
                    updatedOptions.splice(index, 1);
                  }
                }
                this.selectedOptions = updatedOptions;
                console.info(option.name + ' state changed to: ' + value);
              })
            Text(option.label)
              .fontSize(16)
              .margin({ left: 10 })
          }
          .margin({ bottom: 20 })
        })
      }

      Text('Selected options: ' + this.selectedOptions.join(', '))
        .fontSize(16)
        .margin({ top: 20 })
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

interface Option {
  name: string;
  label: string;
}

