@Entry
@Component
struct TextTimerControllerExample {
  @State elapsedTime: number = 0;
  @State isRunning: boolean = false;
  private timerId: number = -1;

  build() {
    Column({ space: 20 }) {
      Text(`Elapsed Time: ${this.elapsedTime} seconds`)
        .fontSize(30)
        .fontColor(Color.Black)
        .margin({ bottom: 20 });

      Row({ space: 10 }) {
        Button(this.isRunning ? 'Pause' : 'Start')
          .onClick(() => {
            if (this.isRunning) {
              this.pauseTimer();
            } else {
              this.startTimer();
            }
          })
          .width(100)
          .height(40);

        Button('Reset')
          .onClick(() => {
            this.resetTimer();
          })
          .width(100)
          .height(40);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20);
  }

  startTimer() {
    this.timerId = setInterval(() => {
      this.elapsedTime += 1;
    }, 1000);
    this.isRunning = true;
  }

  pauseTimer() {
    clearInterval(this.timerId);
    this.isRunning = false;
  }

  resetTimer() {
    this.elapsedTime = 0;
    if (this.isRunning) {
      this.pauseTimer();
    }
  }
}

