@Entry
@Component
struct TextTimerInterfaceConfiguration {
  @State isCountDown: boolean = true;
  @State count: number = 60000;
  @State format: string = 'mm:ss.SS';
  @State fontColor: Color = Color.Black;
  @State fontSize: number = 36;
  @State fontStyle: FontStyle = FontStyle.Normal;
  @State fontWeight: FontWeight = FontWeight.Normal;

  textTimerController: TextTimerController = new TextTimerController();
  @State isPaused: boolean = false;

  build() {
    Column({ space: 20 }) {
      TextTimer({
        isCountDown: this.isCountDown,
        count: this.count,
        controller: this.textTimerController
      })
      .format(this.format)
      .fontColor(this.fontColor)
      .fontSize(this.fontSize)
      .fontStyle(this.fontStyle)
      .fontWeight(this.fontWeight)
      .onTimer((utc: number, elapsedTime: number) => {
        console.info(`UTC: ${utc}, Elapsed Time: ${elapsedTime}`);
      })
      .onAppear(() => {
        this.textTimerController.start();
      });

      Button('Toggle Count Down')
        .onClick(() => {
          this.isCountDown = !this.isCountDown;
        })
        .margin(10);

      Button('Change Format')
        .onClick(() => {
          this.format = this.format === 'mm:ss.SS' ? 'HH:mm:ss' : 'mm:ss.SS';
        })
        .margin(10);

      Button('Change Font Color')
        .onClick(() => {
          this.fontColor = this.fontColor === Color.Black ? Color.Red : Color.Black;
        })
        .margin(10);

      Button('Change Font Size')
        .onClick(() => {
          this.fontSize = this.fontSize === 36 ? 48 : 36;
        })
        .margin(10);

      Button('Reset Timer')
        .onClick(() => {
          this.textTimerController.reset();
          this.textTimerController.start();
          this.isPaused = false;
        })
        .margin(10);

      Button('Pause/Resume')
        .onClick(() => {
          if (!this.isPaused) {
            this.textTimerController.pause();
            this.isPaused = true;
          } else {
            this.textTimerController.start();
            this.isPaused = false;
          }
        })
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor(Color.White);
  }
}

