@Entry
@Component
struct FoldStatusApp {
    @State foldStatus: FoldState = FoldState.COLLAPSED;

    build() {
        Column({ space: 10 }) {
            Text('Fold Status: ' + this.getStatusText())
                .fontSize(20)
                .fontColor(Color.Black)

            Button('Toggle Status')
                .onClick(() => {
                    this.toggleStatus()
                })

            if (this.foldStatus === FoldState.EXPANDED) {
                Image($r('app.media.app_icon'))
                    .width(100)
                    .height(100)
                    .margin({ top: 20 })
            }

            if (this.foldStatus === FoldState.PARTIAL) {
                Image($r('app.media.app_icon'))
                    .width(70)
                    .height(70)
                    .margin({ top: 20 })
                    .opacity(0.7)
            }

            Row({ space: 20 }) {
                Button('Expand')
                    .onClick(() => {
                        this.foldStatus = FoldState.EXPANDED
                    })

                Button('Collapse')
                    .onClick(() => {
                        this.foldStatus = FoldState.COLLAPSED
                    })

                Button('Partial')
                    .onClick(() => {
                        this.foldStatus = FoldState.PARTIAL
                    })
            }
            .margin({ top: 20 })
        }
        .padding(20)
        .width('100%')
        .height('100%')
        .justifyContent(FlexAlign.Center)
    }

    private toggleStatus(): void {
        switch (this.foldStatus) {
            case FoldState.COLLAPSED:
                this.foldStatus = FoldState.PARTIAL
                break
            case FoldState.PARTIAL:
                this.foldStatus = FoldState.EXPANDED
                break
            case FoldState.EXPANDED:
                this.foldStatus = FoldState.COLLAPSED
                break
        }
    }

    private getStatusText(): string {
        switch (this.foldStatus) {
            case FoldState.EXPANDED:
                return 'EXPANDED'
            case FoldState.PARTIAL:
                return 'PARTIAL'
            case FoldState.COLLAPSED:
                return 'COLLAPSED'
            default:
                return 'UNKNOWN'
        }
    }
}

enum FoldState {
    COLLAPSED = 'COLLAPSED',
    PARTIAL = 'PARTIAL',
    EXPANDED = 'EXPANDED'
}

