@Entry
@Component
struct TextTimerFontStyleExample {
  @State private elapsedTime: number = 0
  @State private isRunning: boolean = false
  @State private fontColor: string = '#2a58d0'
  @State private fontSize: number = 30
  @State private fontWeight: FontWeight = FontWeight.Bold
  @State private fontStyle: FontStyle = FontStyle.Italic
  private timerId: number = -1

  build() {
    Column() {
      TextTimer({ isCountDown: false, count: this.elapsedTime })
        .fontSize(this.fontSize)
        .fontStyle(this.fontStyle)
        .fontWeight(this.fontWeight)
        .fontColor(this.fontColor)
        .padding(10)
        .backgroundColor('#f0f0f0')
        .width('80%')
        .height(60)
        .margin(10)

      Row() {
        Button(this.isRunning ? 'Stop' : 'Start')
          .onClick(() => {
            if (this.isRunning) {
              clearInterval(this.timerId)
            } else {
              this.timerId = setInterval(() => {
                this.elapsedTime += 1
              }, 1000)
            }
            this.isRunning = !this.isRunning
          })
          .margin(5)

        Button('Change Color')
          .onClick(() => {
            this.updateFontColor()
          })
          .margin(5)

        Button('Font Size')
          .onClick(() => {
            this.updateFontSize()
          })
          .margin(5)
      }

      Row() {
        Button('Bold')
          .onClick(() => {
            this.fontWeight = this.fontWeight === FontWeight.Bold ? FontWeight.Normal : FontWeight.Bold
          })
          .margin(5)

        Button('Italic')
          .onClick(() => {
            this.fontStyle = this.fontStyle === FontStyle.Italic ? FontStyle.Normal : FontStyle.Italic
          })
          .margin(5)
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }

  private updateFontColor(): void {
    const colors = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FF00FF', '#2a58d0']
    const randomIndex = Math.floor(Math.random() * colors.length)
    this.fontColor = colors[randomIndex]
  }

  private updateFontSize(): void {
    const sizes = [20, 24, 30, 36, 40, 48]
    const randomIndex = Math.floor(Math.random() * sizes.length)
    this.fontSize = sizes[randomIndex]
  }
}

@Entry
@Component
struct FormComponentModifierExample {
  @State username: string = ''
  @State email: string = ''
  @State age: number = 18
  @State subscribe: boolean = false
  @State isUsernameValid: boolean = true
  @State isEmailValid: boolean = true
  @State isAgeValid: boolean = true
  @State usernameError: string = ''
  @State emailError: string = ''
  @State ageError: string = ''
  @State isFormValid: boolean = false

  validateUsername(username: string): string | null {
    return username.length >= 3 ? null : 'Username must be at least 3 characters'
  }

  validateEmail(email: string): string | null {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    return emailRegex.test(email) ? null : 'Please enter a valid email'
  }

  validateAge(age: number): string | null {
    return age >= 18 ? null : 'Must be at least 18 years old'
  }

  validateForm(): void {
    const usernameError = this.validateUsername(this.username)
    const emailError = this.validateEmail(this.email)
    const ageError = this.validateAge(this.age)

    this.usernameError = usernameError || ''
    this.emailError = emailError || ''
    this.ageError = ageError || ''

    this.isUsernameValid = !usernameError
    this.isEmailValid = !emailError
    this.isAgeValid = !ageError

    this.isFormValid = !usernameError && !emailError && !ageError
  }

  build() {
    Column({ space: 20 }) {
      Text('Form Component Modifier')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      TextInput({ placeholder: 'Username' })
        .width('100%')
        .height(50)
        .fontSize(16)
        .onChange((value: string) => {
          this.username = value
          this.validateForm()
        })
        .border({
          width: 1,
          color: this.isUsernameValid ? '#ddd' : '#ff0000'
        })

      if (this.usernameError) {
        Text(this.usernameError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      TextInput({ placeholder: 'Email' })
        .width('100%')
        .height(50)
        .fontSize(16)
        .onChange((value: string) => {
          this.email = value
          this.validateForm()
        })
        .border({
          width: 1,
          color: this.isEmailValid ? '#ddd' : '#ff0000'
        })

      if (this.emailError) {
        Text(this.emailError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      Text('Age: ' + this.age)
        .fontSize(16)
        .width('100%')

      Slider({
        value: this.age,
        min: 1,
        max: 100,
        step: 1
      })
      .width('100%')
      .onChange((value: number) => {
        this.age = value
        this.validateForm()
      })

      if (this.ageError) {
        Text(this.ageError)
          .fontSize(12)
          .fontColor('#ff0000')
          .margin({ top: 5 })
      }

      Row() {
        Checkbox()
          .select(this.subscribe)
          .onChange((checked: boolean) => {
            this.subscribe = checked
          })
        Text('Subscribe to newsletter')
          .fontSize(16)
          .margin({ left: 10 })
      }
      .width('100%')
      .margin({ top: 10 })

      Button('Submit', { type: ButtonType.Capsule })
        .width('100%')
        .height(50)
        .enabled(this.isFormValid)
        .onClick(() => {
          console.info('Form submitted:', {
            username: this.username,
            email: this.email,
            age: this.age,
            subscribe: this.subscribe
          })
        })

      Text(this.isFormValid ? 'Form is valid' : 'Please complete all fields')
        .fontSize(14)
        .fontColor(this.isFormValid ? '#008000' : '#ff0000')
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
  }
}

