@Entry
@Component
struct VisualEffectsExample {
  @State shadowOffsetX: number = 5
  @State shadowOffsetY: number = 5
  @State shadowRadius: number = 10
  @State shadowColor: string = "#000000"
  @State borderWidthValue: number = 2
  @State borderColorValue: Color = Color.Red
  @State borderRadiusValue: number = 10
  @State opacityValue: number = 0.8
  @State bgColor: Color = Color.Blue
  @State bgImage: string = ""

  build() {
    Column({ space: 20 }) {
      Text("Custom Visual Effects Demo")
        .fontSize(25)
        .fontWeight(FontWeight.Bold)
        .fontColor(Color.Black)

      Column() {
        Text("Dynamic Visual Effects")
          .fontSize(18)
          .fontColor(Color.White)
          .padding(10)
      }
      .width(300)
      .height(150)
      .backgroundColor(this.bgColor)
      .backgroundImage(this.bgImage)
      .backgroundImageSize(ImageSize.Cover)
      .shadow({
        offsetX: this.shadowOffsetX,
        offsetY: this.shadowOffsetY,
        radius: this.shadowRadius,
        color: this.shadowColor
      })
      .borderRadius(this.borderRadiusValue)
      .border({ width: this.borderWidthValue, color: this.borderColorValue })
      .opacity(this.opacityValue)

      Row({ space: 10 }) {
        Button("Shadow +")
          .width(120)
          .height(40)
          .onClick(() => {
            this.shadowRadius += 2
          })

        Button("Shadow -")
          .width(120)
          .height(40)
          .onClick(() => {
