@Entry
@Component
struct TextTimerEventHandler {
  textTimerController: TextTimerController = new TextTimerController()
  @State timerDisplay: string = "00:00:00"
  @State elapsedTime: number = 0

  build() {
    Column({ space: 10 }) {
      Text(this.timerDisplay)
        .fontSize(24)
        .fontColor(Color.Black)
        .margin(10)

      TextTimer({
        isCountDown: false,
        count: 0,
        controller: this.textTimerController
      })
        .format('HH:mm:ss')
        .fontSize(30)
        .fontColor(Color.Blue)
        .onTimer((utc: number, elapsedTime: number) => {
          this.handleTimerUpdate(utc, elapsedTime)
        })

      Row({ space: 20 }) {
        Button('Start')
          .onClick(() => {
            this.textTimerController.start()
          })
          .fontSize(16)
          .padding(10)

        Button('Pause')
          .onClick(() => {
            this.textTimerController.pause()
          })
          .fontSize(16)
          .padding(10)

        Button('Reset')
          .onClick(() => {
            this.textTimerController.reset()
          })
          .fontSize(16)
          .padding(10)
      }
      .margin(20)
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White)
  }

  private handleTimerUpdate(utc: number, elapsedTime: number) {
    this.elapsedTime = elapsedTime
    this.timerDisplay = this.formatElapsedTime(elapsedTime)
    console.info('Timer UTC: ' + utc + ', Elapsed Time: ' + elapsedTime + 'ms')
  }

  private formatElapsedTime(milliseconds: number): string {
    const totalSeconds = Math.floor(milliseconds / 1000)
    const hours = Math.floor(totalSeconds / 3600)
    const minutes = Math.floor((totalSeconds % 3600) / 60)
    const seconds = totalSeconds % 60
    return `${this.pad(hours)}:${this.pad(minutes)}:${this.pad(seconds)}`
  }

  private pad(num: number): string {
    return num < 10 ? `0${num}` : num.toString()
  }
}

