@Entry
@Component
struct MarqueeUpdateStrategyExample {
  @State marqueeText: string = "Welcome to HarmonyOS Marquee Example";
  @State translateX: number = 0;
  @State updateStrategy: MarqueeStrategy = MarqueeStrategy.RESET;

  build() {
    Column() {
      Text(this.marqueeText)
        .width('100%')
        .height(50)
        .backgroundColor('#f0f0f0')
        .padding(10)
        .textAlign(TextAlign.Center)
        .fontSize(16)
        .fontColor('#000000')
        .translate({ x: this.translateX, y: 0 })
        .onAppear(() => {
          this.startMarquee();
        })

      Row() {
        Button('RESET')
          .onClick(() => {
            this.updateStrategy = MarqueeStrategy.RESET;
            this.updateMarqueeText("Reset Strategy Applied");
          })
          .backgroundColor(this.updateStrategy === MarqueeStrategy.RESET ? '#007aff' : '#cccccc')
          .fontColor('#ffffff')

        Button('CONTINUE')
          .onClick(() => {
            this.updateStrategy = MarqueeStrategy.CONTINUE;
            this.updateMarqueeText("Continue Strategy Applied");
          })
          .margin({ left: 10 })
          .backgroundColor(this.updateStrategy === MarqueeStrategy.CONTINUE ? '#007aff' : '#cccccc')
          .fontColor('#ffffff')

        Button('PAUSE')
          .onClick(() => {
            this.updateStrategy = MarqueeStrategy.PAUSE;
            this.updateMarqueeText("Pause Strategy Applied");
          })
          .margin({ left: 10 })
          .backgroundColor(this.updateStrategy === MarqueeStrategy.PAUSE ? '#007aff' : '#cccccc')
          .fontColor('#ffffff')
      }
      .margin({ top: 20 })

      Button('Update Text')
        .onClick(() => {
          this.updateMarqueeText("New Marquee Content: " + new Date().toLocaleTimeString());
        })
        .margin({ top: 20 })
        .width('80%')
        .height(50)
        .backgroundColor('#34c759')
        .fontColor('#ffffff')
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#ffffff')
  }

  updateMarqueeText(newText: string) {
    switch (this.updateStrategy) {
      case MarqueeStrategy.RESET:
        this.marqueeText = newText;
        this.translateX = 0;
        this.startMarquee();
        break;
      case MarqueeStrategy.CONTINUE:
        this.marqueeText = newText;
        break;
      case MarqueeStrategy.PAUSE:
        this.marqueeText = newText;
        this.translateX = 0;
        break;
    }
  }

  startMarquee() {
    animateTo({
      duration: 10000,
      curve: Curve.Linear,
      iterations: -1,
      delay: 0,
      onFinish: () => {}
    }, () => {
      this.translateX = -500;
    });
  }
}

enum MarqueeStrategy {
  RESET,
  CONTINUE,
  PAUSE
}

