@Component
struct BlurredMenuApp {
  @State private isMenuVisible: boolean = false;
  @State private blurRadius: number = 15;

  build() {
    Column() {
      Button('Toggle Menu')
        .onClick(() => {
          this.isMenuVisible = !this.isMenuVisible;
        })
        .margin(20)

      Slider({
        value: this.blurRadius,
        min: 0,
        max: 30,
        step: 1,
        style: SliderStyle.OutSet
      })
      .width('80%')
      .margin({ top: 10, bottom: 10 })
      .onChange((value: number) => {
        this.blurRadius = value;
      })

