@Component
struct MenuSelectionApp {
  @State selectedItem: string = '';
  private menuItems: string[] = ['Option 1', 'Option 2', 'Option 3', 'Option 4'];

  build() {
    Column() {
      ForEach(this.menuItems, (item: string) => {
        Row() {
          Text(item)
            .fontSize(18)
            .margin({ right: 20 })
          Checkbox({ name: item, group: 'menuGroup' })
            .onChange((value: boolean) => {
              if (value) {
                this.selectedItem = item;
                this.onItemSelected(item);
              } else {
                this.onItemUnchecked(item);
              }
            })
        }
        .padding(10)
