    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5')
  }

  onItemSelected(item: string) {
    console.log(`Menu item selected: ${item}`);
  }

  onItemUnchecked(item: string) {
    console.log(`Menu item unchecked: ${item}`);
  }
}

@Entry
@Component
struct TimePickerFormatConfigExample {
  @State selectedTime: Date = new Date('2024-01-15T14:45:00');
  @State use24HourFormat: boolean = false;

  build() {
    Column({ space: 20 }) {
      Text('Time Format Configuration')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 30 })

      Row({ space: 15 }) {
        Text('12-hour format')
          .fontSize(18)
        Toggle({ type: ToggleType.Switch, isOn: this.use24HourFormat })
          .onChange((isOn: boolean) => {
            this.use24HourFormat = !isOn;
          })
        Text('24-hour format')
          .fontSize(18)
      }
      .margin({ bottom: 20 })

      Text(`Selected Time: ${this.selectedTime.toLocaleTimeString()}`)
        .fontSize(20)
        .fontColor(Color.Blue)
        .margin({ bottom: 20 })

      TimePicker({
        selected: this.selectedTime
      })
      .useMilitaryTime(this.use24HourFormat)
      .onChange((value: TimePickerResult) => {
        if (value.hour >= 0) {
          this.selectedTime.setHours(value.hour, value.minute, value.second);
        }
      })
      .textStyle({
        color: Color.Black,
        font: { size: 18, weight: FontWeight.Normal }
      })
      .selectedTextStyle({
        color: Color.Red,
        font: { size: 22, weight: FontWeight.Bold }
      })
      .margin({ bottom: 30 })

      Text(`Current Format: ${this.use24HourFormat ? '24-hour' : '12-hour'}`)
        .fontSize(16)
        .fontColor(Color.Green)

      Text(`Hour: ${this.selectedTime.getHours()}`)
        .fontSize(16)
        .margin({ top: 15 })

      Text(`Minute: ${this.selectedTime.getMinutes()}`)
        .fontSize(16)
        .margin({ top: 5 })

      Text(`Second: ${this.selectedTime.getSeconds()}`)
        .fontSize(16)
        .margin({ top: 5 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

