      .height('100%')
      .justifyContent(FlexAlign.Center)
      .backgroundColor('#F8F9FA')
    } else if (index === 1) {
      Column() {
        Text('Profile Content')
          .fontSize(24)
          .fontColor('#000000')
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 })
        Image($r('app.media.app_icon'))
          .width(100)
          .height(100)
          .borderRadius(50)
        Text('User Profile Information')
          .fontSize(16)
          .fontColor('#666666')
          .margin({ top: 15 })
      }
      .width('100%')
      .height('100%')
      .justifyContent(FlexAlign.Center)
      .backgroundColor('#FFF8F0')
    } else if (index === 2) {
      Column() {
        Text('Settings Content')
          .fontSize(24)
          .fontColor('#000000')
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 })
        Image($r('app.media.app_icon'))
          .width(80)
          .height(80)
          .borderRadius(5)
        Text('Configure your preferences')
          .fontSize(16)
          .fontColor('#666666')
          .margin({ top: 15 })
      }
      .width('100%')
      .height('100%')
      .justifyContent(FlexAlign.Center)
      .backgroundColor('#F0F8FF')
    } else if (index === 3) {
      Column() {
        Text('About Content')
          .fontSize(24)
          .fontColor('#000000')
          .fontWeight(FontWeight.Bold)
          .margin({ bottom: 20 })
        Image($r('app.media.app_icon'))
          .width(90)
          .height(90)
          .borderRadius(8)
        Text('Application Information')
          .fontSize(16)
          .fontColor('#666666')
          .margin({ top: 15 })
      }
      .width('100%')
      .height('100%')
      .justifyContent(FlexAlign.Center)
      .backgroundColor('#F5F5F5')
    }
  }

  build() {
    Column() {
      Row() {
        this.MenuItemBuilder('Home', 0)
        this.MenuItemBuilder('Profile', 1)
        this.MenuItemBuilder('Settings', 2)
        this.MenuItemBuilder('About', 3)
      }
      .width('100%')
      .height(65)
      .backgroundColor('#FFFFFF')
      .padding({ left: 10, right: 10 })
      .justifyContent(FlexAlign.SpaceBetween)

      this.ContentModifier(this.selectedIndex)
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

