        Text('Oval')
          .fontSize(16)
          .margin({ right: 10 });
        Radio({ value: 'oval', group: 'shapeGroup' })
          .checked(this.shapeType === 'oval')
          .onChange((isChecked: boolean) => {
            if (isChecked) {
              this.shapeType = 'oval';
            }
          });
