        Text('Rounded Rectangle')
          .fontSize(16)
          .margin({ right: 10 });
        Radio({ value: 'roundedRectangle', group: 'shapeGroup' })
          .checked(this.shapeType === 'roundedRectangle')
          .onChange((isChecked: boolean) => {
            if (isChecked) {
              this.shapeType = 'roundedRectangle';
            }
          });
      }.margin({ bottom: 20 });

      Shape() {
        if (this.shapeType === 'rectangle') {
          Rect()
            .width(100)
            .height(100)
            .fill(Color.Blue);
        } else if (this.shapeType === 'circle') {
          Circle()
            .width(100)
            .height(100)
            .fill(Color.Red);
        } else if (this.shapeType === 'oval') {
          Ellipse()
            .width(150)
            .height(100)
            .fill(Color.Green);
        } else if (this.shapeType === 'roundedRectangle') {
          Rect()
            .width(100)
            .height(100)
            .fill(Color.Yellow)
            .borderRadius(20);
        }
      }
      .viewPort({ x: 0, y: 0, width: 200, height: 200 })
      .width(200)
      .height(200)
      .backgroundColor(Color.Gray);
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#ffffff');
  }
}

