@Entry
@Component
struct FlowItemAttributesExample {
  @State private items: string[] = ['Item 1', 'Item 2', 'Item 3', 'Item 4', 'Item 5'];
  @State private selectedIndex: number = -1;

  build() {
    Column() {
      // Grid container with attribute configuration
      Grid() {
        ForEach(this.items, (item: string, index: number) => {
          GridItem() {
            // Grid item content with various attribute methods
            Column() {
              Image($r('app.media.icon'))
                .width(40)
                .height(40)
                .margin({ bottom: 8 })

              Text(item)
                .fontSize(14)
                .fontColor(this.selectedIndex === index ? '#FFFFFF' : '#333333')
                .textAlign(TextAlign.Center)
            }
            .width('100%')
            .height(120)
            .justifyContent(FlexAlign.Center)
            .backgroundColor(this.selectedIndex === index ? '#007DFF' : '#F5F5F5')
            .borderRadius(8)
            .border({
              width: this.selectedIndex === index ? 2 : 1,
              color: this.selectedIndex === index ? '#0055CC' : '#E0E0E0'
            })
          }
          .onClick(() => {
            this.selectedIndex = index;
          })
        })
      }
      .columnsTemplate('1fr 1fr')
      .columnsGap(12)
      .rowsGap(16)
      .width('100%')
      .height('70%')
      .padding(16)
      .backgroundColor('#FAFAFA')

      // Control buttons with attribute methods
      Row() {
        Button('Add Item')
          .fontSize(16)
          .fontWeight(FontWeight.Medium)
          .width('40%')
          .height(40)
          .backgroundColor('#007DFF')
          .borderRadius(20)
          .onClick(() => {
            this.items = [...this.items, `Item ${this.items.length + 1}`];
          })

        Button('Remove Last')
          .fontSize(16)
          .fontWeight(FontWeight.Medium)
          .width('40%')
          .height(40)
          .backgroundColor('#FF3B30')
          .borderRadius(20)
          .margin({ left: 12 })
          .onClick(() => {
            if (this.items.length > 0) {
              this.items = this.items.slice(0, -1);
              if (this.selectedIndex >= this.items.length) {
                this.selectedIndex = -1;
              }
            }
          })
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
      .margin({ top: 16, bottom: 16 })

      // Status display with attribute methods
      Text(`Total Items: ${this.items.length} | Selected: ${this.selectedIndex >= 0 ? this.items[this.selectedIndex] : 'None'}`)
        .fontSize(14)
        .fontColor('#666666')
        .textAlign(TextAlign.Center)
        .width('100%')
        .padding(8)
        .backgroundColor('#F0F0F0')
        .borderRadius(4)
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

