struct RouterActivityChecker {
  @State isRouterActive: boolean = false;
  @State routerStatus: string = 'Unknown';

  build() {
    Column({ space: 20 }) {
      Text('Router Activity Status')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 30 });

      Text(this.routerStatus)
        .fontSize(20)
        .fontColor(this.isRouterActive ? Color.Green : Color.Red)
        .padding(16)
        .border({ width: 2, color: this.isRouterActive ? Color.Green : Color.Red })
        .borderRadius(8)
        .margin({ bottom: 20 });

      Button('Check Router Activity')
        .width(250)
        .height(50)
        .backgroundColor('#007DFF')
        .fontColor(Color.White)
        .onClick(() => {
          this.checkRouterActivity();
        })
        .margin({ bottom: 20 });

      Button('Simulate Router Status Change')
        .width(250)
        .height(50)
        .backgroundColor('#FF9500')
        .fontColor(Color.White)
        .onClick(() => {
          this.simulateRouterStatusChange();
        })
        .margin({ bottom: 30 });

      Image($r('app.media.app_icon'))
        .width(80)
        .height(80)
        .margin({ top: 20 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .padding(20)
    .backgroundColor('#F5F5F5');
  }

  private checkRouterActivity(): void {
    const randomValue = Math.random();
    this.isRouterActive = randomValue > 0.3;
    this.routerStatus = this.isRouterActive ?
      'Router Component is ACTIVE' :
      'Router Component is INACTIVE';
  }

  private simulateRouterStatusChange(): void {
    this.isRouterActive = !this.isRouterActive;
    this.routerStatus = this.isRouterActive ?
      'Router Status Changed to ACTIVE' :
      'Router Status Changed to INACTIVE';
  }
}

