          console.log('Image animation started')
        })
        .onPause(() => {
          console.log('Image animation paused')
        })
        .onRepeat(() => {
          console.log('Image animation repeated')
        })
        .onFinish(() => {
          console.log('Image animation finished')
        })

      Slider({
        value: this.duration,
        min: 500,
