@Entry
@Component
struct FolderStackWithCallbacks {
  @State folderState: number = 0;
  @State folderScale: number = 1.0;
  @State folderOpacity: number = 1.0;

  onFolderStateChange(newState: number) {
    console.log(`Folder state changed to: ${newState === 1 ? 'Open' : 'Closed'}`);

    animateTo({
      duration: 500,
      curve: Curve.EaseInOut
    }, () => {
      this.folderScale = newState === 1 ? 1.2 : 1.0;
      this.folderOpacity = newState === 1 ? 0.8 : 1.0;
    });
  }

  build() {
    Column() {
      Text('Folder Stack Demo')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin(20);

      Stack() {
        if (this.folderState === 1) {
          Column() {
            Image($r('app.media.icon'))
              .width(80)
              .height(80)
              .margin(10);

            Text('Folder Content Area')
              .fontSize(18)
              .margin(10);

            Text('This content appears when folder is open')
              .fontSize(14)
              .margin(5);
          }
          .scale({ x: this.folderScale, y: this.folderScale })
          .opacity(this.folderOpacity)
          .animation({ duration: 500, curve: Curve.EaseInOut });
        } else {
          Text('Folder (Click to expand)')
            .fontSize(16)
            .fontColor(Color.Gray);
        }
      }
      .onClick(() => {
        this.folderState = this.folderState === 1 ? 0 : 1;
        this.onFolderStateChange(this.folderState);
      })
      .width('90%')
      .height(this.folderState === 1 ? '40%' : '15%')
      .backgroundColor(Color.White)
      .borderRadius(15)
      .padding(15)
      .border({ width: 2, color: Color.Gray });

      Row() {
        Button('Open Folder')
          .onClick(() => {
            this.folderState = 1;
            this.onFolderStateChange(1);
          })
          .margin(10)
          .opacity(this.folderState === 1 ? 0.5 : 1.0);

        Button('Close Folder')
          .onClick(() => {
            this.folderState = 0;
            this.onFolderStateChange(0);
          })
          .margin(10)
          .opacity(this.folderState === 1 ? 1.0 : 0.5);
      }
      .margin(20);

      Text(`Current State: ${this.folderState === 1 ? 'OPEN' : 'CLOSED'}`)
        .fontSize(16)
        .fontColor(this.folderState === 1 ? Color.Green : Color.Red)
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .backgroundColor('#f0f0f0');
  }
}

