        .padding(16);

      Row() {
        Button('Add Item')
          .onClick(() => {
            const fruits = ['Kiwi', 'Watermelon', 'Peach', 'Pear', 'Cherry'];
            const randomFruit = fruits[Math.floor(Math.random() * fruits.length)];
            this.items = [...this.items, randomFruit];
          })
          .margin({ right: 10 });

        Button(this.isEditMode ? 'Done' : 'Edit')
          .onClick(() => {
            this.isEditMode = !this.isEditMode;
          });
      }
      .margin({ bottom: 20 });

      List({ space: 8 }) {
        ForEach(this.items, (item: string, index: number) => {
          ListItem() {
            Row() {
              Image($r('app.media.app_icon'))
                .width(32)
                .height(32)
                .margin({ right: 12 });

              Text(item)
