@Entry
@Component
struct TransformationMatrixApp {
  private matrix = [
    1, 0, 0,
    0, 1, 0,
    0, 0, 1
  ];

  build() {
    Column() {
      Text("Transformation Matrix Configuration")
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 30 });

      Image($r('app.media.app_icon'))
        .width(120)
        .height(120)
        .transform({ matrix: this.matrix })
        .margin({ bottom: 30 });

      Column() {
        Button("Scale 1.5x")
          .width(200)
          .onClick(() => {
            this.matrix = [
              1.5, 0, 0,
              0, 1.5, 0,
              0, 0, 1
            ];
          })
          .margin({ bottom: 10 });

        Button("Rotate 45°")
          .width(200)
          .onClick(() => {
            const angle = 45 * (Math.PI / 180);
            this.matrix = [
              Math.cos(angle), -Math.sin(angle), 0,
              Math.sin(angle), Math.cos(angle), 0,
              0, 0, 1
            ];
          })
          .margin({ bottom: 10 });

        Button("Skew")
          .width(200)
          .onClick(() => {
