@Entry
@Component
struct AnimatedFolderStack {
  @State isFolderOpen: boolean = false;
  @State folderScale: number = 1.0;
  @State folderOpacity: number = 1.0;
  @State folderRotation: number = 0;

  build() {
    Column() {
      Button(this.isFolderOpen ? 'Close Folder' : 'Open Folder')
        .onClick(() => {
          this.isFolderOpen = !this.isFolderOpen;
          animateTo({
            duration: 600,
            curve: Curve.EaseInOut
          }, () => {
            this.folderScale = this.isFolderOpen ? 1.1 : 1.0;
            this.folderOpacity = this.isFolderOpen ? 0.9 : 1.0;
            this.folderRotation = this.isFolderOpen ? 5 : 0;
          });
        })
        .margin(20);

      Stack() {
        Column() {
          Image($r('app.media.app_icon'))
            .width(80)
            .height(80)
            .margin(10);

          Text('Folder Content')
            .fontSize(18)
            .margin(10);

          if (this.isFolderOpen) {
            Column() {
              Text('Item 1')
                .fontSize(16)
                .margin(5);
              Text('Item 2')
                .fontSize(16)
                .margin(5);
              Text('Item 3')
                .fontSize(16)
                .margin(5);
            }
            .opacity(this.folderOpacity)
            .animation({ duration: 300, curve: Curve.EaseIn });
          }
        }
        .scale({ x: this.folderScale, y: this.folderScale })
        .opacity(this.folderOpacity)
        .rotate({ angle: this.folderRotation })
        .animation({ duration: 600, curve: Curve.EaseInOut })
      }
      .width('80%')
      .height(this.isFolderOpen ? '60%' : '30%')
      .backgroundColor(Color.White)
      .borderRadius(15)
      .padding(20)
      .shadow({ radius: 10, color: Color.Gray, offsetX: 2, offsetY: 2 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor('#f0f0f0');
  }
}

