@Entry
@Component
struct AngleLimitConfiguration {
  @State angleLimit: number = 45;
  @State currentAngle: number = 30;
  @State isOblique: boolean = false;

  build() {
    Column() {
      Text('Configure Angle Drawing Limits')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 30 })

      Row() {
        Text('Angle Limit (0-90°):')
          .fontSize(18)
          .margin({ right: 15 })

        TextInput({ placeholder: 'Enter limit' })
          .width(120)
          .type(InputType.Number)
          .onChange((value: string) => {
            let newLimit = Number(value);
            if (newLimit >= 0 && newLimit <= 90) {
              this.angleLimit = newLimit;
              this.checkAngleType();
            }
          })
      }
      .margin({ bottom: 20 })

      Row() {
        Text('Test Angle:')
          .fontSize(18)
          .margin({ right: 15 })

        TextInput({ placeholder: 'Enter angle' })
          .width(120)
          .type(InputType.Number)
          .onChange((value: string) => {
            let newAngle = Number(value);
            if (newAngle >= 0 && newAngle <= 180) {
              this.currentAngle = newAngle;
              this.checkAngleType();
            }
          })
      }
      .margin({ bottom: 20 })

      Text(`Current Limit: ${this.angleLimit}°`)
        .fontSize(16)
        .margin({ bottom: 10 })

      Text(`Test Angle: ${this.currentAngle}°`)
        .fontSize(16)
        .margin({ bottom: 10 })

      Text(this.isOblique ?
           'Angle will be drawn as OBLIQUE' :
           'Angle will be drawn as ACUTE')
        .fontSize(18)
        .fontColor(this.isOblique ? '#FF0000' : '#00AA00')
        .margin({ bottom: 30 })

      Button('Apply Configuration')
        .onClick(() => {
          console.log(`Angle limit configured: ${this.angleLimit}°`);
          console.log(`Current test angle: ${this.currentAngle}°`);
          console.log(`Drawing as: ${this.isOblique ? 'Oblique' : 'Acute'}`);
        })
        .width(200)
        .height(40)
        .margin({ bottom: 20 })

      Image($r('app.media.app_icon'))
        .width(80)
        .height(80)
        .margin({ top: 20 })
    }
    .padding(20)
    .alignItems(HorizontalAlign.Center)
    .width('100%')
    .height('100%')
  }

  private checkAngleType(): void {
    this.isOblique = this.currentAngle <= this.angleLimit;
  }
}

