@Entry
@Component
struct CustomBadgePositioning {
  @State customX: number = 50;
  @State customY: number = 50;

  build() {
    Column({ space: 20 }) {
      // Custom positioned badge using Stack and absolute positioning
      Stack() {
        Image($r('app.media.icon'))
          .width(64)
          .height(64)

        Badge({
          value: '1',
          position: BadgePosition.RightTop,
          style: { badgeSize: 20, badgeColor: '#FF0000' } as BadgeStyle
        }) {
          // Empty container for the badge
          Column().width(0).height(0)
        }
        .position({ x: this.customX, y: this.customY })
      }
      .width(100)
      .height(100)
      .border({ width: 1, color: 0xCCCCCC })

      // Controls to adjust badge position
      Row({ space: 10 }) {
        Button('\u2190')
          .width(40)
          .height(40)
          .onClick(() => {
            this.customX = Math.max(0, this.customX - 10);
          })

        Button('\u2192')
          .width(40)
          .height(40)
          .onClick(() => {
            this.customX = Math.min(80, this.customX + 10);
          })
      }

      Row({ space: 10 }) {
        Button('\u2191')
          .width(40)
          .height(40)
          .onClick(() => {
            this.customY = Math.max(0, this.customY - 10);
          })

        Button('\u2193')
          .width(40)
          .height(40)
          .onClick(() => {
            this.customY = Math.min(80, this.customY + 10);
          })
      }

      Text(`Position: X=${this.customX}, Y=${this.customY}`)
        .fontSize(14)
        .fontColor(0x000000)

      // Standard badge positions for comparison
      Row({ space: 20 }) {
        Badge({
          value: '2',
          position: BadgePosition.Left,
          style: { badgeSize: 16, badgeColor: '#007AFF' } as BadgeStyle
        }) {
          Image($r('app.media.icon'))
            .width(32)
            .height(32)
        }

        Badge({
          value: '3',
          position: BadgePosition.Right,
          style: { badgeSize: 16, badgeColor: '#34C759' } as BadgeStyle
        }) {
          Image($r('app.media.icon'))
            .width(32)
            .height(32)
        }

        Badge({
          value: '4',
          position: BadgePosition.RightTop,
          style: { badgeSize: 16, badgeColor: '#FF9500' } as BadgeStyle
        }) {
          Image($r('app.media.icon'))
            .width(32)
            .height(32)
        }
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20)
    .backgroundColor(0xFFFFFF)
  }
}

