@Entry
@Component
struct ComponentLifecycleTracker {
  @State isAttached: boolean = false;
  @State counter: number = 0;

  aboutToAppear() {
    this.isAttached = true;
    console.log('Component attached to view tree');
  }

  aboutToDisappear() {
    this.isAttached = false;
    console.log('Component detached from view tree');
  }

  aboutToUpdate() {
    console.log('Component about to update');
  }

  build() {
    Column() {
      Text(this.isAttached ? 'Attached to view tree' : 'Not attached')
        .fontSize(20)
        .margin(10)
        .fontColor(this.isAttached ? Color.Green : Color.Red)

      Text(`Update count: ${this.counter}`)
        .fontSize(18)
        .margin(10)

      Button('Trigger Update')
        .onClick(() => {
          this.counter += 1;
        })
        .margin(10)

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

