  // Custom suffix builder using @Builder (Example 1 approach)
  @Builder
  FavoriteSuffix() {
    Image(this.isFavorite ? $r('app.media.app_icon') : $r('app.media.app_icon'))
      .width(24)
      .height(24)
      .onClick(() => {
        this.isFavorite = !this.isFavorite
      })
      .margin({ left: 10 })
  }

  // Another suffix builder with text
  @Builder
  TextSuffix() {
    Text('★')
      .fontSize(20)
      .fontColor(Color.Yellow)
      .margin({ left: 8 })
  }

  build() {
    Column({ space: 20 }) {
      // Example 1: Custom suffix using @Builder
      Row() {
        Image($r('app.media.app_icon'))
          .width(32)
          .height(32)
        this.FavoriteSuffix()
      }
      .padding(10)
      .borderRadius(8)
      .backgroundColor(Color.White)

      // Example 2: Component-based approach with suffix
      Row() {
        Image($r('app.media.app_icon'))
          .width(32)
          .height(32)
          .margin({ right: 8 })
        Text('Document')
          .fontSize(16)
        this.TextSuffix()
      }
      .padding(10)
      .borderRadius(8)
      .backgroundColor(Color.White)

      // Multiple icon group with different suffixes
      Row() {
        Image($r('app.media.app_icon'))
          .width(24)
          .height(24)
          .margin({ right: 12 })
        Text('Settings')
          .fontSize(14)
        Text('→')
          .fontSize(18)
          .fontColor(Color.Gray)
          .margin({ left: 15 })
      }
      .padding(12)
      .borderRadius(8)
      .backgroundColor(Color.White)
      .width('90%')

      // Interactive icon group with state
      Row() {
        Image($r('app.media.app_icon'))
          .width(28)
          .height(28)
          .margin({ right: 10 })
        Text('Notifications')
          .fontSize(15)
        Text(this.isFavorite ? '🔔' : '🔕')
          .fontSize(20)
          .margin({ left: 15 })
          .onClick(() => {
            this.isFavorite = !this.isFavorite
          })
      }
      .padding(12)
      .borderRadius(8)
      .backgroundColor(Color.White)
      .width('90%')
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#F5F5F5')
    .justifyContent(FlexAlign.Center)
