@Component
struct MultiSelectChipGroup {
  @State selectedChips: string[] = []
  chips: string[] = ["Option 1", "Option 2", "Option 3", "Option 4", "Option 5"]

  build() {
    Column() {
      Text("Select multiple options:")
        .fontSize(18)
        .padding(10)

      Flex({ wrap: FlexWrap.Wrap }) {
        ForEach(this.chips, (chip: string) => {
          Chip({
            label: chip,
            selected: this.selectedChips.includes(chip),
            onSelect: (selected: boolean) => {
              if (selected) {
                this.selectedChips = [...this.selectedChips, chip]
              } else {
                this.selectedChips = this.selectedChips.filter(item => item !== chip)
              }
            }
          })
          .margin(5)
        })
      }
      .padding(10)

      Text(`Selected: ${this.selectedChips.join(", ")}`)
        .fontSize(16)
        .padding(10)
    }
    .width("100%")
    .height("100%")
    .padding(20)
    .backgroundColor("#ffffff")
  }
}

