import router from '@ohos.router';

@Entry
@Component
struct NavigatorModifierExample {
  @State navigationType: string = 'push';
  @State url: string = 'pages/NextPage';

  validateUrl(url: string): boolean {
    const allowedPattern = /^pages\/[a-zA-Z0-9_]+$/;
    return allowedPattern.test(url);
  }

  handleNavigation() {
    if (!this.validateUrl(this.url)) {
      console.error('Invalid URL');
      return;
    }

    if (this.navigationType === 'push') {
      router.pushUrl({ url: this.url });
    } else if (this.navigationType === 'replace') {
      router.pushUrl({ url: this.url });
    }
  }

  build() {
    Column({ space: 10 }) {
      Row({ space: 10 }) {
        Radio({ value: 'push', group: 'navigationType' })
          .checked(this.navigationType === 'push')
          .onChange((value: boolean) => {
            if (value) {
              this.navigationType = 'push';
            }
          })
        Text('Push Navigation')
      }

      Row({ space: 10 }) {
        Radio({ value: 'replace', group: 'navigationType' })
          .checked(this.navigationType === 'replace')
          .onChange((value: boolean) => {
            if (value) {
              this.navigationType = 'replace';
            }
          })
        Text('Replace Navigation')
      }

      TextInput({ placeholder: 'Enter URL (e.g., pages/NextPage)' })
        .onChange((value: string) => {
          this.url = value;
        })

      Button('Navigate')
        .onClick(() => {
          this.handleNavigation();
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20)
  }
