@Entry
@Component
struct SizePositionHandlingExample {
  @State widthValue: number = 100
  @State heightValue: number = 100
  @State xPos: number = 0
  @State yPos: number = 0
  @State scaleX: number = 1
  @State scaleY: number = 1

  build() {
    Column() {
      Text('Component Size & Position Handling')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      Image($r('app.media.app_icon'))
        .width(this.widthValue)
        .height(this.heightValue)
        .position({ x: this.xPos, y: this.yPos })
        .scale({ x: this.scaleX, y: this.scaleY })
        .backgroundColor(Color.Blue)
        .margin(20)

      Row() {
        Button('+ Width')
          .onClick(() => { this.widthValue += 20 })
        Button('- Width')
          .onClick(() => { this.widthValue = Math.max(50, this.widthValue - 20) })
      }
      .margin({ bottom: 10 })

      Row() {
        Button('+ Height')
          .onClick(() => { this.heightValue += 20 })
        Button('- Height')
          .onClick(() => { this.heightValue = Math.max(50, this.heightValue - 20) })
      }
      .margin({ bottom: 20 })

      Row() {
        Button('Move Left')
          .onClick(() => { this.xPos -= 10 })
        Button('Move Right')
          .onClick(() => { this.xPos += 10 })
      }
      .margin({ bottom: 10 })

      Row() {
        Button('Move Up')
          .onClick(() => { this.yPos -= 10 })
        Button('Move Down')
          .onClick(() => { this.yPos += 10 })
      }
      .margin({ bottom: 20 })

      Row() {
        Button('Scale X+')
          .onClick(() => { this.scaleX += 0.1 })
        Button('Scale X-')
          .onClick(() => { this.scaleX = Math.max(0.1, this.scaleX - 0.1) })
      }
      .margin({ bottom: 10 })

      Row() {
        Button('Scale Y+')
          .onClick(() => { this.scaleY += 0.1 })
        Button('Scale Y-')
          .onClick(() => { this.scaleY = Math.max(0.1, this.scaleY - 0.1) })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(0xF5F5F5)
  }
}

