@Entry
@Component
struct ProgressModifierExample {
  @State progressValue: number = 0;
  @State progressText: string = "Initializing...";

  build() {
    Column() {
      Text("Progress Modifier Example")
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 20 });

      Progress({
        value: this.progressValue,
        total: 100,
        type: ProgressType.Linear
      })
      .size({ width: "80%", height: 20 })
      .color(Color.Blue)
      .margin({ bottom: 20 });

      Text(this.progressText)
        .fontSize(16)
        .margin({ bottom: 20 });

      Row({ space: 10 }) {
        Button("Start Progress")
          .onClick(() => {
            this.progressText = "Progressing...";
            this.startProgress();
          });

        Button("Reset Progress")
          .onClick(() => {
            this.progressValue = 0;
            this.progressText = "Initializing...";
          });
      }
      .margin({ bottom: 20 });

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .margin({ top: 20 });
    }
    .width("100%")
    .height("100%")
    .padding(20)
    .backgroundColor(Color.White);
  }

  private startProgress() {
    let interval = setInterval(() => {
      if (this.progressValue < 100) {
        this.progressValue += 10;
        this.progressText = `Progress: ${this.progressValue}%`;
      } else {
        clearInterval(interval);
        this.progressText = "Completed!";
      }
    }, 500);
  }
}

