@Entry
@Component
struct CanvasTransformationsExample {
  private settings: RenderingContextSettings = new RenderingContextSettings(true);
  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings);

  build() {
    Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Center, justifyContent: FlexAlign.Center }) {
      Text('Canvas Transformations Demo')
        .fontSize(24)
        .margin({ bottom: 20 });

      Canvas(this.context)
        .width('100%')
        .height('350vp')
        .backgroundColor('#FFFFFF')
        .onReady(() => {
          // Original shape
          this.context.fillStyle = '#FF5733';
          this.context.fillRect(20, 20, 100, 100);

          // Translation
          this.context.translate(150, 0);
          this.context.fillStyle = '#33FF57';
          this.context.fillRect(20, 20, 100, 100);

          // Rotation
          this.context.rotate(Math.PI / 6); // 30 degrees
          this.context.fillStyle = '#3375FF';
          this.context.fillRect(20, 20, 100, 100);

          // Scaling
          this.context.scale(1.2, 1.2);
          this.context.fillStyle = '#FF33F5';
          this.context.fillRect(20, 20, 100, 100);

          // Skew
          this.context.transform(1, 0.3, -0.3, 1, 0, 0);
          this.context.fillStyle = '#FFC733';
          this.context.fillRect(20, 20, 100, 100);
        });
    }
    .width('100%')
    .height('100%')
    .padding(15);
  }
}

