struct TipsDialog {
  controller: CustomDialogController | undefined;
  @State fontSize: number = 16;
  @State tipText: string = 'This is customizable tip text at user\'s preferred size';

  build() {
    Column() {
      Text('Tips Dialog Title')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });

      Text(this.tipText)
        .fontSize(this.fontSize)
        .margin({ bottom: 20 });

      Slider({
        value: this.fontSize,
        min: 12,
        max: 24,
        step: 1,
        style: SliderStyle.OutSet
      })
      .onChange((value: number) => {
        this.fontSize = value;
      })
      .margin({ bottom: 10 });

      Row() {
        Button('Small')
          .onClick(() => {
            this.fontSize = 12;
          });
        Button('Medium')
          .onClick(() => {
            this.fontSize = 16;
          });
        Button('Large')
          .onClick(() => {
            this.fontSize = 20;
          });
      }
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ bottom: 20 });

      Row() {
        Button('Confirm')
          .onClick(() => {
            this.controller?.close();
          });
        Button('Cancel')
          .onClick(() => {
            this.controller?.close();
          });
      }
      .justifyContent(FlexAlign.SpaceEvenly)
    }
    .padding(20)
  }
}

