@Entry
@Component
struct TipsDialogWithShadow {
  @State isDialogVisible: boolean = false;
  @State shadowRadius: number = 5;
  @State shadowColor: string = "#000000";
  @State shadowOffsetX: number = 5;
  @State shadowOffsetY: number = 5;

  build() {
    Column({ space: 10 }) {
      Text("TipsDialog Shadow Customization")
        .fontSize(30)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20 });

      Row({ space: 20 }) {
        TextInput({ placeholder: "Shadow Radius" })
          .onChange((value: string) => {
            this.shadowRadius = parseInt(value) || 0;
          })
          .width(100);

        TextInput({ placeholder: "Shadow Color" })
          .onChange((value: string) => {
            this.shadowColor = value;
          })
          .width(100);

        TextInput({ placeholder: "Offset X" })
          .onChange((value: string) => {
            this.shadowOffsetX = parseInt(value) || 0;
          })
          .width(100);

        TextInput({ placeholder: "Offset Y" })
          .onChange((value: string) => {
            this.shadowOffsetY = parseInt(value) || 0;
          })
          .width(100);
      }
      .margin({ top: 20 });

      Button("Show TipsDialog")
        .onClick(() => {
          this.isDialogVisible = true;
        })
        .margin({ top: 20 })
        .width(200)
        .height(50)
        .backgroundColor(Color.Blue)
        .fontColor(Color.White)
        .shadow({
          radius: 5,
          color: "#000000",
          offsetX: 5,
          offsetY: 5
        });

      if (this.isDialogVisible) {
        Stack() {
          Column()
            .width('100%')
            .height('100%')
            .backgroundColor(Color.Black)
            .opacity(0.5);

          Column() {
            Text("Customizable TipsDialog")
              .fontSize(24)
              .fontColor(Color.Black)
              .margin({ top: 20, bottom: 20 });

            Button("Close")
              .onClick(() => {
                this.isDialogVisible = false;
              })
              .margin(20)
              .padding(10)
              .backgroundColor(Color.Red)
              .fontColor(Color.White)
              .fontSize(20);
          }
          .width('80%')
          .height('40%')
          .backgroundColor(Color.White)
          .shadow({
            radius: this.shadowRadius,
            color: this.shadowColor,
            offsetX: this.shadowOffsetX,
            offsetY: this.shadowOffsetY
          })
          .borderRadius(10)
          .align(Alignment.Center);
        }
        .width('100%')
        .height('100%')
        .position({ x: 0, y: 0 })
        .backgroundColor(Color.Transparent);
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(Color.White);
  }
}

