@CustomDialog
struct TipsDialog {
  controller: CustomDialogController;
  @State private scaleValue: number = 0.9;
  @State private opacityValue: number = 0;

  onPageShow() {
    animateTo({
      duration: 300,
      curve: Curve.EaseInOut
    }, () => {
      this.scaleValue = 1.0;
      this.opacityValue = 1.0;
    });
  }

  onPageHide() {
    animateTo({
      duration: 300,
      curve: Curve.EaseInOut
    }, () => {
      this.scaleValue = 0.9;
      this.opacityValue = 0;
    });
  }

  build() {
    Column() {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .opacity(this.opacityValue)

      Text('This is a TipsDialog')
        .fontSize(20)
        .margin(10)

      Button('Close')
        .onClick(() => {
          this.controller.close();
        })
    }
    .padding(20)
    .width('80%')
    .backgroundColor('#FFFFFF')
    .borderRadius(8)
    .shadow({ radius: 8, color: '#00000020' })
  }
}

