@CustomDialog
struct TipsDialog {
  controller: CustomDialogController;
  cancel?: () => void;
  confirm?: () => void;
  secondaryAction?: () => void;

  @State isHovered: boolean = false;

  build() {
    Column() {
      Text('Tips Dialog')
        .fontSize(20)
        .margin(10)

      Flex({ justifyContent: FlexAlign.SpaceAround }) {
        Button('Cancel')
          .onHover((isHovered: boolean) => {
            this.isHovered = isHovered;
          })
          .backgroundColor(this.isHovered ? Color.Blue : Color.Gray)
          .onClick(() => {
            this.controller.close();
            this.cancel?.();
          })

        Button('Secondary')
          .onHover((isHovered: boolean) => {
            this.isHovered = isHovered;
          })
          .backgroundColor(this.isHovered ? Color.Blue : Color.Gray)
          .onClick(() => {
            this.controller.close();
            this.secondaryAction?.();
          })

        Button('Confirm')
          .onHover((isHovered: boolean) => {
            this.isHovered = isHovered;
          })
          .backgroundColor(this.isHovered ? Color.Blue : Color.Gray)
          .onClick(() => {
            this.controller.close();
            this.confirm?.();
          })
      }
    }
    .backgroundColor(Color.White)
    .borderRadius(10)
    .padding(20)
  }
}

@Entry
@Component
struct TipsDialog {
  @Prop title: string = 'Tips';
  @Prop content: string = 'This is a tips dialog';
  @Prop cancel: () => void;
  @Prop confirm: () => void;
  @State rotationX: number = 0;
  @State rotationY: number = 0;
  @State rotationZ: number = 0;
  @State scaleX: number = 1;
  @State scaleY: number = 1;
  @State translateX: number = 0;
  @State translateY: number = 0;

  build() {
    Column() {
      Text(this.title)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 10 });
      Text(this.content)
        .fontSize(16)
        .margin({ bottom: 20 });
      Flex({ justifyContent: FlexAlign.SpaceAround }) {
        Button('Cancel')
          .onClick(() => {
            this.cancel?.();
          });
        Button('Confirm')
          .onClick(() => {
            this.confirm?.();
          });
      }
    }
    .transform({
      rotate: { x: this.rotationX, y: this.rotationY, z: this.rotationZ },
      scale: { x: this.scaleX, y: this.scaleY },
      translate: { x: this.translateX, y: this.translateY }
    })
    .animation({ duration: 300, curve: Curve.EaseInOut })
    .padding(20)
    .borderRadius(10)
    .width('80%')
    .backgroundColor(Color.White);
  }
}

