@Component
struct TipsDialogWithScrollHandlers {
  private scroller: Scroller = new Scroller();
  @State private tips: string[] = ['Tip 1', 'Tip 2', 'Tip 3', 'Tip 4', 'Tip 5'];
  @State private isScrollEnabled: boolean = true;

  build() {
    Column() {
      Scroll(this.scroller) {
        Column() {
          ForEach(this.tips, (tip: string) => {
            Text(tip)
              .width('90%')
              .height(150)
              .backgroundColor(0xFFFFFF)
              .borderRadius(15)
              .fontSize(16)
              .textAlign(TextAlign.Center)
              .margin({ top: 10 })
          }, (tip: string) => tip)
        }
        .width('100%')
      }
      .backgroundColor(0xDCDCDC)
      .scrollable(ScrollDirection.Vertical)
      .scrollBar(BarState.On)
      .scrollBarColor(Color.Gray)
      .scrollBarWidth(10)
      .edgeEffect(EdgeEffect.Spring)
      .onScroll((scrollOffset: number) => {
        if (this.isScrollEnabled) {
          console.info(`Scroll Offset: ${scrollOffset}`);
        }
      })
      .onScrollStop(() => {
        if (this.isScrollEnabled) {
          console.info('Scroll stopped');
        }
      })

      Row() {
        Button(this.isScrollEnabled ? 'Disable Scroll Events' : 'Enable Scroll Events')
          .onClick(() => {
            this.isScrollEnabled = !this.isScrollEnabled;
          })
          .padding(10)
          .margin(5)
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

