@Entry
@Component
struct AlertDialogWithTitles {
  build() {
    Column() {
      Button('Show AlertDialog')
        .onClick(() => {
          this.showAlertDialog();
        })
        .margin(20);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }

  private showAlertDialog() {
    const dialogOptions: promptAction.ShowDialogOptions = {
      title: 'Primary Title', // Primary title
      message: 'Secondary Title', // Secondary title
      buttons: [
        {
          text: 'Cancel',
          color: '#000000'
        },
        {
          text: 'Confirm',
          color: '#FF0000',
          primary: true
        }
      ]
    };

    promptAction.showDialog(dialogOptions).then((result: promptAction.ShowDialogSuccessResponse) => {
      if (result.index === 1) {
        console.info('Confirm button clicked');
      } else {
        console.info('Cancel button clicked');
      }
    }).catch((error: Error) => {
      console.error('Failed to show AlertDialog:', error);
    });
  }
}

