@Entry
@Component
struct CheckboxGroupDetection {
  @State selectedCheckboxes: string[] = [];

  build() {
    Column() {
      // Checkbox 1
      Checkbox({ name: 'checkbox1', group: 'checkboxGroup' })
        .select(false)
        .selectedColor(0x39a2db)
        .shape(CheckBoxShape.ROUNDED_SQUARE)
        .onChange((value: boolean) => {
          this.handleCheckboxChange('checkbox1', value);
        })

      // Checkbox 2
      Checkbox({ name: 'checkbox2', group: 'checkboxGroup' })
        .select(false)
        .selectedColor(0x39a2db)
        .shape(CheckBoxShape.ROUNDED_SQUARE)
        .onChange((value: boolean) => {
          this.handleCheckboxChange('checkbox2', value);
        })

      // Checkbox 3
      Checkbox({ name: 'checkbox3', group: 'checkboxGroup' })
        .select(false)
        .selectedColor(0x39a2db)
        .shape(CheckBoxShape.ROUNDED_SQUARE)
        .onChange((value: boolean) => {
          this.handleCheckboxChange('checkbox3', value);
        })

      // Display selected checkboxes
      Text('Selected Checkboxes: ' + this.selectedCheckboxes.join(', '))
        .fontSize(18)
        .margin({ top: 20 })
    }
    .padding(20)
  }

  private handleCheckboxChange(name: string, value: boolean) {
    if (value) {
      this.selectedCheckboxes.push(name);
    } else {
      const index = this.selectedCheckboxes.indexOf(name);
      if (index !== -1) {
        this.selectedCheckboxes.splice(index, 1);
      }
    }
    console.info('Updated Selected Checkboxes: ', this.selectedCheckboxes);
  }
}

