@Entry
@Component
struct BaseGestureEventExplorer {
  @State private gestureInfo: string = "Perform a gesture to see its event details";

  build() {
    Column({ space: 20 }) {
      Text(this.gestureInfo)
        .fontSize(20)
        .textAlign(TextAlign.Center)
        .margin({ top: 20 });

      Flex({ justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
        Text("Tap to See Event")
          .fontSize(18)
          .padding(20)
          .backgroundColor(0xeeeeee)
          .borderRadius(10)
          .gesture(
            TapGesture()
              .onAction((event: GestureEvent) => {
                this.gestureInfo = `Tap Event: X=${event.offsetX}, Y=${event.offsetY}, Timestamp=${event.timestamp}`;
              })
          );
      }

      Flex({ justifyContent: FlexAlign.Center, alignItems: ItemAlign.Center }) {
        Text("Pan to See Event")
          .fontSize(18)
          .padding(20)
          .backgroundColor(0xeeeeee)
          .borderRadius(10)
          .gesture(
            PanGesture()
              .onActionStart((event: GestureEvent) => {
                this.gestureInfo = `Pan Started: X=${event.offsetX}, Y=${event.offsetY}`;
              })
              .onActionUpdate((event: GestureEvent) => {
