struct SwipeGestureAngleExplorer {
  @State angle: number = 0;
  @State swipeDirection: string = 'None';

  build() {
    Column({ space: 20 }) {
      Text('Exploring SwipeGestureEvent Angle Property')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 30 });

      Image($r('app.media.app_icon'))
        .width(200)
        .height(200)
        .gesture(
          SwipeGesture({ direction: SwipeDirection.All })
            .onAction((event: SwipeGestureEvent) => {
              this.angle = event.angle;
              if (this.angle >= -45 && this.angle < 45) {
                this.swipeDirection = 'Right';
              } else if (this.angle >= 45 && this.angle < 135) {
                this.swipeDirection = 'Down';
              } else if (this.angle >= 135 || this.angle < -135) {
                this.swipeDirection = 'Left';
              } else {
                this.swipeDirection = 'Up';
              }
            })
        )
        .borderRadius(10)
        .backgroundColor(Color.Gray);

      Text(`Angle: ${this.angle.toFixed(2)}°`)
        .fontSize(18)
        .margin({ top: 20 });

      Text(`Direction: ${this.swipeDirection}`)
        .fontSize(18);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

