@Entry
@Component
struct CanvasTextDrawingApp {
  private settings: RenderingContextSettings = new RenderingContextSettings(true)
  private renderContext: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings)
  @State private fontSize: number = 30
  @State private fontColor: string = '#000000'
  @State private textContent: string = 'Hello ArkTS'
  @State private showColorOptions: boolean = false
  private colorOptions: string[] = ['#000000', '#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FF00FF', '#00FFFF']

  build() {
    Column() {
      Canvas(this.renderContext)
        .width('100%')
        .height(200)
        .backgroundColor('#f5f5f5')
        .onReady(() => {
          this.drawText()
        })

      Column() {
        Text('Font Size: ' + this.fontSize)
          .fontSize(16)
          .margin({ top: 10 })

        Slider({
          value: this.fontSize,
          min: 10,
          max: 60,
          step: 1,
          style: SliderStyle.OutSet
        })
        .onChange((value: number) => {
          this.fontSize = value
          this.drawText()
        })
        .width('80%')

        Text('Font Color:')
          .fontSize(16)
          .margin({ top: 10 })

        Row() {
          Text(this.fontColor)
            .fontSize(16)
            .margin({ right: 10 })
          Button('Select Color')
            .onClick(() => {
              this.showColorOptions = !this.showColorOptions
            })
        }

        if (this.showColorOptions) {
          Flex({ wrap: FlexWrap.Wrap }) {
            ForEach(this.colorOptions, (color: string) => {
              Button('')
                .width(40)
                .height(40)
                .backgroundColor(color)
                .onClick(() => {
                  this.fontColor = color
                  this.showColorOptions = false
                  this.drawText()
                })
                .margin(5)
            })
          }
          .width('100%')
          .margin({ top: 10 })
        }

        TextInput({ placeholder: 'Enter text', text: this.textContent })
          .onChange((value: string) => {
            this.textContent = value
            this.drawText()
          })
          .width('80%')
          .margin({ top: 10 })
      }
      .width('100%')
      .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }

  private drawText() {
    this.renderContext.clearRect(0, 0, this.renderContext.width, this.renderContext.height)
    this.renderContext.font = `${this.fontSize}px Arial`
    this.renderContext.fillStyle = this.fontColor
    this.renderContext.textBaseline = 'middle'
    const textWidth = this.renderContext.measureText(this.textContent).width
    const x = (this.renderContext.width - textWidth) / 2
    const y = this.renderContext.height / 2
    this.renderContext.fillText(this.textContent, x, y)
  }
}

