@Entry
@Component
struct GradientCanvasExample {
  private settings: RenderingContextSettings = new RenderingContextSettings(true)
  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings)

  build() {
    Column() {
      Text("Canvas Gradient Effects")
        .fontSize(30)
        .fontColor(Color.Black)
        .textAlign(TextAlign.Center)
        .width('100%')
        .height(100)
      Canvas(this.context)
        .width('100%')
        .height('70%')
        .backgroundColor('#ffffff')
        .onReady(() => {
          // Create a linear gradient
          let linearGradient = this.context.createLinearGradient(50, 50, 350, 150)
          linearGradient.addColorStop(0.0, '#ff0000')
          linearGradient.addColorStop(0.5, '#00ff00')
          linearGradient.addColorStop(1.0, '#0000ff')
          this.context.fillStyle = linearGradient
          this.context.fillRect(50, 50, 300, 100)

          // Create a radial gradient
          let radialGradient = this.context.createRadialGradient(200, 300, 30, 200, 300, 100)
          radialGradient.addColorStop(0.0, '#ffff00')
          radialGradient.addColorStop(0.5, '#00ffff')
          radialGradient.addColorStop(1.0, '#ff00ff')
          this.context.beginPath()
          this.context.arc(200, 300, 80, 0, 2 * Math.PI)
          this.context.fillStyle = radialGradient
          this.context.fill()
        })
    }
    .width('100%')
    .height('100%')
    .linearGradient({
      angle: 0,
      colors: [
        ['#ffffff', 0.0],
        ['#f0f0f0', 1.0]
      ]
    })
  }
}

