@Entry
@Component
struct ConfigureCanvasLineProperties {
  private settings: RenderingContextSettings = new RenderingContextSettings(true)
  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings)
  @State private lineWidth: number = 4
  @State private lineCap: string = 'butt'
  @State private lineJoin: string = 'miter'
  @State private strokeStyle: string = '#0000ff'

  build() {
    Column({ space: 10 }) {
      Canvas(this.context)
        .width('100%')
        .height(300)
        .backgroundColor('#f0f0f0')
        .onReady(() => {
          this.updateCanvas()
        })

      Row({ space: 10 }) {
        Text('Line Width:')
        Slider({
          value: this.lineWidth,
          min: 1,
          max: 20,
          style: SliderStyle.OutSet
        })
        .onChange((value: number) => {
          this.lineWidth = value
          this.updateCanvas()
        })
      }

      Row({ space: 10 }) {
        Text('Line Cap Style:')
        Button('Butt')
          .onClick(() => {
            this.lineCap = 'butt'
            this.updateCanvas()
          })
        Button('Round')
          .onClick(() => {
            this.lineCap = 'round'
            this.updateCanvas()
          })
        Button('Square')
          .onClick(() => {
            this.lineCap = 'square'
            this.updateCanvas()
          })
      }

      Row({ space: 10 }) {
        Text('Line Join Style:')
        Button('Miter')
          .onClick(() => {
            this.lineJoin = 'miter'
            this.updateCanvas()
          })
        Button('Round')
          .onClick(() => {
            this.lineJoin = 'round'
            this.updateCanvas()
          })
        Button('Bevel')
          .onClick(() => {
            this.lineJoin = 'bevel'
            this.updateCanvas()
          })
      }

      Row({ space: 10 }) {
        Text('Stroke Color:')
        Button('Blue')
          .onClick(() => {
            this.strokeStyle = '#0000ff'
            this.updateCanvas()
          })
        Button('Red')
          .onClick(() => {
            this.strokeStyle = '#ff0000'
            this.updateCanvas()
          })
        Button('Green')
          .onClick(() => {
            this.strokeStyle = '#00ff00'
            this.updateCanvas()
          })
      }
    }
    .width('100%')
    .height('100%')
    .padding(10)
  }

  updateCanvas() {
    this.context.clearRect(0, 0, this.context.width, this.context.height)
    this.context.lineWidth = this.lineWidth
    this.context.lineCap = this.lineCap as CanvasLineCap
    this.context.lineJoin = this.lineJoin as CanvasLineJoin
    this.context.strokeStyle = this.strokeStyle
    this.context.beginPath()
    this.context.moveTo(50, 50)
    this.context.lineTo(250, 50)
    this.context.lineTo(250, 150)
    this.context.lineTo(50, 150)
    this.context.closePath()
    this.context.stroke()
  }
}

