@Entry
@Component
struct PanGestureSetDistanceExample {
  @State distance: number = 0;

  setDistance(offsetX: number, offsetY: number) {
    this.distance = Math.sqrt(offsetX * offsetX + offsetY * offsetY);
  }

  build() {
    Column({ space: 20 }) {
      Text('Exploring setDistance in PanGestureOptions')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .gesture(
          PanGesture()
            .onActionStart(() => {
              this.distance = 0;
            })
            .onActionUpdate((event: GestureEvent) => {
              this.setDistance(event.offsetX, event.offsetY);
            })
            .onActionEnd(() => {
              console.log('Pan gesture ended. Distance:', this.distance);
            })
        )
        .margin({ bottom: 20 });

      Text(`Calculated Distance: ${this.distance.toFixed(2)}`)
        .fontSize(20)
        .fontColor('#4CAF50');
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center);
  }
}

