          this.updateSelection('checkbox2', value);
        });

      Text('Checkbox 2')
        .fontSize(16)
        .margin({ left: 10 });

      Checkbox({ name: 'checkbox3', group: 'settingsGroup' })
        .select(false)
        .selectedColor(this.selectedColor)
        .shape(this.shape)
        .onChange((value: boolean) => {
          this.updateSelection('checkbox3', value);
        });

      Text('Checkbox 3')
        .fontSize(16)
        .margin({ left: 10 });

      Text('Selected Checkboxes: ' + this.selectedValues.join(', '))
        .fontSize(16)
        .margin({ top: 20 });

