@Entry
@Component
struct DownloadIconExplorer {
  @State iconStyle: DownloadIconStyle = DownloadIconStyle.NORMAL;
  @State downloadStatus: string = "Idle";
  @State progress: number = 0;
  private isDownloading: boolean = false;

  simulateDownload() {
    if (this.isDownloading) return;
    this.isDownloading = true;
    this.downloadStatus = "Downloading";
    const interval = setInterval(() => {
      this.progress += 10;
      if (this.progress >= 100) {
        clearInterval(interval);
        this.downloadStatus = "Completed";
        this.isDownloading = false;
        this.iconStyle = DownloadIconStyle.COMPLETED;
      }
    }, 500);
  }

  handleError() {
    this.downloadStatus = "Error";
    this.isDownloading = false;
    this.iconStyle = DownloadIconStyle.ERROR;
  }

  build() {
    Column({ space: 10 }) {
      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .objectFit(ImageFit.Contain)
        .onClick(() => {
          this.iconStyle = this.iconStyle === DownloadIconStyle.NORMAL ? DownloadIconStyle.PRESSED : DownloadIconStyle.NORMAL;
        });

      Text(`Status: ${this.downloadStatus}`)
        .fontSize(20)
        .fontColor(Color.Black)
        .margin({ bottom: 10 });

      Text(`Progress: ${this.progress}%`)
        .fontSize(16)
        .fontColor(Color.Gray);

      Button(this.downloadStatus === "Downloading" ? 'Pause' : 'Start Download')
        .onClick(() => {
          if (this.downloadStatus === "Downloading") {
            this.downloadStatus = "Paused";
            this.isDownloading = false;
          } else {
            this.simulateDownload();
          }
        })
        .margin({ top: 20 })
        .enabled(this.downloadStatus !== "Completed" && this.downloadStatus !== "Error");

      Button('Reset')
        .onClick(() => {
          this.progress = 0;
          this.downloadStatus = "Idle";
          this.isDownloading = false;
          this.iconStyle = DownloadIconStyle.NORMAL;
        })
        .margin({ top: 10 })
        .enabled(this.downloadStatus === "Completed" || this.downloadStatus === "Error");
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20)
  }
}

enum DownloadIconStyle {
  NORMAL,
  PRESSED,
  COMPLETED,
  ERROR
}

