@Entry
@Component
struct StepperWithPreviousLabelClick {
  @State currentStep: number = 0;
  private steps: string[] = ["Step 1", "Step 2", "Step 3", "Step 4"];

  build() {
    Column() {
      Text("Stepper with Previous Label Click")
        .alignSelf(ItemAlign.Start)
        .margin({ left: 20, top: 20, bottom: 20 })
        .fontSize(20)
        .fontColor("#ff797979");

      CustomSteps({
        steps: this.steps,
        currentStep: $currentStep,
        onPreviousLabelClick: (index: number) => {
          if (index > 0) {
            this.currentStep = index - 1;
          }
        }
      })

      Button("Next Step")
        .type(ButtonType.Normal)
        .backgroundColor("#ffffffff")
        .fontColor("#ff000000")
        .margin(20)
        .alignSelf(ItemAlign.Start)
        .onClick(() => {
          if (this.currentStep < this.steps.length - 1) {
            this.currentStep += 1;
          } else {
            this.currentStep = 0;
          }
        })

      Text("Current Step: " + this.steps[this.currentStep])
        .alignSelf(ItemAlign.Start)
        .margin({ left: 20, top: 20, bottom: 20 })
        .fontSize(20)
        .fontColor("#ff797979");

    }
    .backgroundColor("#ffe7e7e7")
    .width("100%")
    .height("100%")
  }
}

@Component
struct CustomSteps {
  private steps: string[] = [];
  @Link currentStep: number;
  private onPreviousLabelClick: (index: number) => void = () => {};

  build() {
    Column() {
      ForEach(this.steps, (step: string, index: number) => {
        Row() {
          Text(step)
            .fontSize(16)
            .fontColor(index === this.currentStep ? "#ff1195db" : "#ff000000")
            .onClick(() => {
              if (index < this.currentStep) {
                this.onPreviousLabelClick(index);
              }
            })
        }
        .margin({ bottom: 10 })
      })
    }
    .padding(10)
  }
}

