  isEnabled?: boolean;
  action?: () => void;
}

@Entry
@Component
struct EditableTitleBarMenuItem {
  @State menuItems: MenuItem[] = [
    {
      value: $r('app.media.app_icon'),
      isEnabled: true,
      action: () => {
        promptAction.showToast({ message: 'Menu Item 1 Clicked' });
      }
    },
    {
      value: $r('app.media.app_icon'),
      isEnabled: false,
      action: () => {
        promptAction.showToast({ message: 'Menu Item 2 Clicked' });
      }
    }
  ];

  build() {
    Column() {
      ForEach(this.menuItems, (item: MenuItem, index: number) => (
        Row() {
          Image(item.value)
            .width(30)
            .height(30)
            .margin({ right: 10 })
            .onClick(() => {
              if (item.isEnabled !== false) {
                item.action?.();
              } else {
                promptAction.showToast({ message: 'This menu item is disabled' });
              }
            });

          Checkbox({ name: `checkbox${index}`, group: 'menuGroup' })
            .select(item.isEnabled)
            .onChange((value: boolean) => {
              this.menuItems[index].isEnabled = value;
            });
        }
        .padding(10)
      ))
    }
    .padding(20)
  }
}

@Entry
@Component
struct CircleConfigurator {
  @State private circleSize: number = 100;
  @State private circleFill: Color = Color.Blue;
  @State private circleOpacity: number = 1;
  @State private circleBorderWidth: number = 2;
  @State private circleBorderColor: Color = Color.Black;

  private colors: Color[] = [Color.Blue, Color.Red, Color.Green, Color.Yellow, Color.Pink];

  build() {
    Column({ space: 20 }) {
      // Customizable Circle Component
      Circle()
        .width(this.circleSize)
        .height(this.circleSize)
        .fill(this.circleFill)
        .opacity(this.circleOpacity)
        .border({ width: this.circleBorderWidth, color: this.circleBorderColor })
        .onClick(() => {
          this.nextColor();
        })

      // Sliders for customization
      Slider({
        min: 50,
        max: 200,
        value: this.circleSize
      })
        .onChange((value: number) => {
          this.circleSize = value;
        })
        .width('80%')

      Slider({
        min: 0.1,
        max: 1,
        value: this.circleOpacity,
        step: 0.1
      })
        .onChange((value: number) => {
          this.circleOpacity = value;
        })
        .width('80%')

      Slider({
        min: 1,
        max: 10,
        value: this.circleBorderWidth
      })
        .onChange((value: number) => {
          this.circleBorderWidth = value;
        })
        .width('80%')

      // Display current settings
      Text(`Size: ${this.circleSize}`)
        .fontSize(14)
      Text(`Opacity: ${this.circleOpacity.toFixed(1)}`)
        .fontSize(14)
      Text(`Border Width: ${this.circleBorderWidth}`)
        .fontSize(14)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .backgroundColor(Color.White)
  }

  private nextColor() {
    const currentIndex = this.colors.indexOf(this.circleFill);
    this.circleFill = this.colors[(currentIndex + 1) % this.colors.length];
  }
}

