        .borderRadius(10)
      }
      .width('100%')
      .height('60%')

      // Slider to adjust the blur radius
      Slider({
        value: this.blurRadius,
        min: 0,
        max: 50,
        step: 1,
        style: SliderStyle.OutSet
      })
      .width('80%')
      .margin({ top: 20 })
      .onChange((value: number) => {
        this.blurRadius = value;
      })

      Text(`Blur Radius: ${this.blurRadius}`)
        .fontSize(14)
        .margin({ top: 10 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

@Entry
@Component
struct DraggableColumnSplitExample {
  @State leftWidth: number = 150;
  @State rightWidth: number = 150;
  @State initialX: number = 0;
  @State isDragging: boolean = false;

  build() {
    Column() {
      Text("Drag the divider to adjust the pane sizes")
        .fontSize(16)
        .fontColor(Color.Black)
        .margin({ bottom: 10 });

      Row() {
        Column() {
          Text("Left Pane")
            .fontSize(18)
            .textAlign(TextAlign.Center)
            .width('100%')
            .height('100%')
            .backgroundColor('#FFCCCC');
        }
        .width(this.leftWidth)
        .height(300)

        Stack() {
          Image($r('app.media.app_icon'))
            .width(10)
            .height(300)
            .backgroundColor('#000000')
            .onTouch((event: TouchEvent) => {
              if (event.type === TouchType.Down) {
                this.initialX = event.touches[0].x;
                this.isDragging = true;
              } else if (event.type === TouchType.Move && this.isDragging) {
                const deltaX = event.touches[0].x - this.initialX;
                this.leftWidth += deltaX;
                this.rightWidth -= deltaX;
                this.initialX = event.touches[0].x;
              } else if (event.type === TouchType.Up) {
                this.isDragging = false;
              }
            });
        }
        .width(10)
        .height(300)

        Column() {
          Text("Right Pane")
            .fontSize(18)
            .textAlign(TextAlign.Center)
            .width('100%')
            .height('100%')
            .backgroundColor('#CCFFCC');
        }
        .width(this.rightWidth)
        .height(300)
      }
      .width('90%')
      .height(300)
      .backgroundColor(Color.White)
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.Gray)
  }
}

