@Entry
@Component
struct PinchGestureCallbackExample {
  @State scaleValue: number = 1.0;
  @State callbackLog: string = 'Callbacks will appear here\n';

  build() {
    Column() {
      Text("Pinch Gesture Callbacks")
        .fontSize(20)
        .margin(10);

      Text(`Current Scale: ${this.scaleValue.toFixed(2)}`)
        .fontSize(16)
        .margin(5);

      Image($r("app.media.app_icon"))
        .width(200)
        .height(200)
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .gesture(
          PinchGesture()
            .onActionStart((event: GestureEvent) => {
              this.callbackLog += `Pinch started: center=(${event.offsetX},${event.offsetY})\n`;
            })
            .onActionUpdate((event: GestureEvent) => {
              this.scaleValue *= event.scale;
              this.callbackLog += `Pinch moving: scale=${event.scale.toFixed(2)}\n`;
            })
            .onActionEnd(() => {
              this.callbackLog += "Pinch ended\n";
            })
            .onActionCancel(() => {
              this.callbackLog += "Pinch canceled\n";
            })
        );

      Text(this.callbackLog)
        .fontSize(14)
        .margin(10)
        .border({ width: 1, color: Color.Gray })
        .width('90%')
        .height(200);
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

