@Entry
@Component
struct StepperItemExample {
  @State currentStep: number = 0;
  private steps: string[] = ["Step 1", "Step 2", "Step 3", "Step 4"];

  private getCurrentStepItem(): string {
    return this.steps[this.currentStep];
  }

  private moveToStep(stepIndex: number): void {
    if (stepIndex >= 0 && stepIndex < this.steps.length) {
      this.currentStep = stepIndex;
    }
  }

  private moveToNextStep(): void {
    if (this.currentStep < this.steps.length - 1) {
      this.currentStep++;
    }
  }

  private moveToPreviousStep(): void {
    if (this.currentStep > 0) {
      this.currentStep--;
    }
  }

  build() {
    Column() {
      Text("Stepper Item Example")
        .alignSelf(ItemAlign.Start)
        .margin({ left: 20, top: 20, bottom: 20 })
        .fontSize(20)
        .fontColor("#ff797979");

      Stepper({
        index: this.currentStep
      }) {
        ForEach(this.steps, (step: string, index: number) => {
          StepperItem() {
            Column() {
              Text(step)
                .fontSize(18)
                .margin({ bottom: 10 });

              Image($r("app.media.app_icon"))
                .width(100)
                .height(100)
                .margin({ bottom: 20 });
            }
            .width('100%')
            .height('100%')
            .justifyContent(FlexAlign.Center)
            .alignItems(HorizontalAlign.Center);
          }
        })
      }
      .width("80%")
      .height(50)
      .margin({ bottom: 20 });

      Button("Next Step")
        .onClick(() => {
          this.moveToNextStep();
        })
        .margin({ bottom: 20 });

      Button("Previous Step")
        .onClick(() => {
          this.moveToPreviousStep();
        })
        .margin({ bottom: 20 });

      Button("Go to Last Step")
        .onClick(() => {
          this.moveToStep(this.steps.length - 1);
        })
        .margin({ bottom: 20 });

      Button("Go to First Step")
        .onClick(() => {
          this.moveToStep(0);
        })
        .margin({ bottom: 20 });

      Text(`Current Step: ${this.getCurrentStepItem()}`)
        .fontSize(18)
        .margin({ bottom: 20 });
    }
    .width("100%")
    .height("100%")
    .padding(20)
    .backgroundColor("#ffffff");
  }
}

