  @State subStyledString: string = "This is a styled substring";
  @State attributes: Map<string, string> = new Map();

  build() {
    Column() {
      Text(this.subStyledString)
        .fontSize(20)
        .fontColor(Color.Black)
        .margin({ bottom: 20 })
        .onClick(() => {
          this.attributes = this.getAttributes(this.subStyledString);
        })

      ForEach(Array.from(this.attributes.entries()), (attribute: [string, string]) => {
        Text(`${attribute[0]}: ${attribute[1]}`)
          .fontSize(16)
          .margin({ top: 10 })
      })
    }
    .padding(20)
  }

  private getAttributes(subStyledString: string): Map<string, string> {
    let attributes = new Map<string, string>();
    attributes.set("fontSize", "20");
    attributes.set("fontColor", "Black");
    attributes.set("marginBottom", "20");
    return attributes;
  }
}

