      Button('Reset to Start')
        .onClick(() => {
          this.scroller.scrollTo({ xOffset: 0, yOffset: 0 });
          this.isAtStart = true;
        })
        .margin(10)
        .width('50%')
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

