@Entry
@Component
struct ExceptionPromptWithMargin {
  @State marginValue: number = 20;

  build() {
    Column() {
      Text('Configure Margin for ExceptionPrompt')
        .fontSize(20)
        .margin({ bottom: 10 })

      Row() {
        Text('Margin:')
        TextInput({ placeholder: 'Enter margin value' })
          .type(InputType.Number)
          .onChange((value: string) => {
            this.marginValue = Number(value);
          })
      }
      .margin({ bottom: 20 })

      Button('Show ExceptionPrompt')
        .onClick(() => {
          this.showExceptionPrompt();
        })
        .margin({ bottom: this.marginValue })
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }

  private showExceptionPrompt() {
    let dialogController = new CustomDialogController({
      builder: ExceptionPrompt({
        message: 'This is an ExceptionPrompt with configurable margins',
        type: 'warning',
        duration: 0,
        onClose: this.onClose,
        onConfirm: this.onConfirm,
        controller: undefined
      }),
      autoCancel: true
    });
    dialogController.open();
  }

  onClose() {
    console.info('ExceptionPrompt closed');
  }

  onConfirm() {
    console.info('ExceptionPrompt confirmed');
  }
}

@CustomDialog
struct ExceptionPrompt {
  controller: CustomDialogController;
  message: string = '';
  type: 'success' | 'error' | 'warning' = 'success';
  duration: number = 3000;
  onClose?: () => void;
  onConfirm?: () => void;

  build() {
    Column() {
      Text(this.message)
        .fontSize(18)
        .fontColor(this.type === 'success' ? '#4CAF50' : this.type === 'error' ? '#F44336' : '#FF9800')
        .margin(10);

      Flex({ justifyContent: FlexAlign.SpaceAround }) {
        Button('Close')
          .onClick(() => {
            this.controller.close();
            this.onClose?.();
          });

        Button('Confirm')
          .onClick(() => {
            this.controller.close();
            this.onConfirm?.();
          });
      }
    }
    .padding(20)
    .onAppear(() => {
      if (this.duration > 0) {
        setTimeout(() => {
          this.controller.close();
          this.onClose?.();
        }, this.duration);
      }
    });
  }
}

