@Entry
@Component
struct GestureRecognitionApp {
  @State pressed: boolean = false;
  @State tapCount: number = 0;
  @State offsetX: number = 0;
  @State offsetY: number = 0;

  build() {
    Column({ space: 20 }) {
      Button('Press Me')
        .width(150)
        .height(50)
        .backgroundColor(this.pressed ? Color.Red : Color.Blue)
        .gesture(
          TapGesture({ count: 1 })
            .onAction(() => {
              this.pressed = !this.pressed;
              this.tapCount += 1;
            })
        )
        .onClick(() => {
          console.info('Button Pressed!');
        });

      Text(`Taps: ${this.tapCount}`)
        .fontSize(20)
        .fontColor(Color.Black);

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .gesture(
          TapGesture({ count: 2 })
            .onAction(() => {
              console.info('Double Tap Detected');
            })
        );

      Row()
        .width(300)
        .height(200)
        .backgroundColor(Color.Green)
        .borderRadius(10)
        .gesture(
          PanGesture({ direction: PanDirection.All })
            .onActionStart(() => {
              console.info('Pan Started');
            })
            .onActionUpdate((event: GestureEvent) => {
              this.offsetX = event.offsetX;
              this.offsetY = event.offsetY;
            })
            .onActionEnd(() => {
              animateTo({ duration: 300 }, () => {
                this.offsetX = 0;
                this.offsetY = 0;
              });
            })
        )
        .transform({ translate: { x: this.offsetX, y: this.offsetY } })
        .animation({ duration: 300 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }
}

