@Entry
@Component
struct ExceptionPromptConfig {
  @State isVisible: boolean = true;
  @State message: string = 'An error occurred!';
  @State type: 'success' | 'error' | 'warning' = 'error';
  @State duration: number = 3000;

  dialogController: CustomDialogController = new CustomDialogController({
    builder: ExceptionPrompt({
      message: this.message,
      type: this.type,
      duration: this.duration,
      onClose: this.onClose.bind(this),
      onConfirm: this.onConfirm.bind(this),
      controller: undefined
    }),
    autoCancel: true
  });

  onClose() {
    console.info('Dialog closed');
  }

  onConfirm() {
    console.info('Dialog confirmed');
  }

  build() {
    Column() {
      if (this.isVisible) {
        Text('Configure Exception Prompt')
          .fontSize(20)
          .fontColor(Color.Red)
          .margin({ bottom: 10 });

        Button('Hide Exception Prompt')
          .onClick(() => {
            this.isVisible = false;
          });

        Button('Show Custom Exception Prompt')
          .onClick(() => {
            this.dialogController.open();
          });

        Text('Message:')
          .fontSize(16)
          .margin({ top: 10 });
        TextInput({ placeholder: 'Enter message' })
          .onChange((value: string) => {
            this.message = value;
          });

        Text('Type:')
          .fontSize(16)
          .margin({ top: 10 });
        Radio({ value: 'success', group: 'type' })
          .checked(this.type === 'success')
          .onChange((checked: boolean) => {
            if (checked) this.type = 'success';
          });
        Text('Success')
          .fontSize(14)
          .margin({ right: 20 });
        Radio({ value: 'error', group: 'type' })
          .checked(this.type === 'error')
          .onChange((checked: boolean) => {
            if (checked) this.type = 'error';
          });
        Text('Error')
          .fontSize(14)
          .margin({ right: 20 });
        Radio({ value: 'warning', group: 'type' })
          .checked(this.type === 'warning')
          .onChange((checked: boolean) => {
            if (checked) this.type = 'warning';
          });
        Text('Warning')
          .fontSize(14)
          .margin({ right: 20 });

        Text('Duration (ms):')
          .fontSize(16)
          .margin({ top: 10 });
        Slider({
          value: this.duration,
          min: 1000,
          max: 5000,
          step: 1000,
          style: SliderStyle.OutSet
        })
          .onChange((value: number) => {
            this.duration = value;
          });
      } else {
        Button('Show Exception Prompt')
          .onClick(() => {
            this.isVisible = true;
          });
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .padding(20)
  }
}

@CustomDialog
struct ExceptionPrompt {
  controller: CustomDialogController;
  message: string = '';
  type: 'success' | 'error' | 'warning' = 'success';
  duration: number = 3000;
  onClose?: () => void;
  onConfirm?: () => void;

  build() {
    Column() {
      Text(this.message)
        .fontSize(18)
        .fontColor(this.type === 'success' ? '#4CAF50' : this.type === 'error' ? '#F44336' : '#FF9800')
        .margin(10);

      Flex({ justifyContent: FlexAlign.SpaceAround }) {
        Button('Close')
          .onClick(() => {
            this.controller.close();
            this.onClose?.();
          });

        Button('Confirm')
          .onClick(() => {
            this.controller.close();
            this.onConfirm?.();
          });
      }
    }
    .padding(20)
    .onAppear(() => {
      if (this.duration > 0) {
        setTimeout(() => {
          this.controller.close();
          this.onClose?.();
        }, this.duration);
      }
    });
  }
}

