@Entry
@Component
struct MotionPathTransitionConfigExample {
  @State private translateX: number = 0;
  @State private translateY: number = 0;
  @State private rotationAngle: number = 0;
  @State private scaleValue: number = 1;

  build() {
    Column({ space: 10 }) {
      Text('Motion Path Transition Config Example')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 });

      Image($r('app.media.app_icon'))
        .width(100)
        .height(100)
        .translate({ x: this.translateX, y: this.translateY })
        .rotate({ x: 0, y: 0, z: 1, angle: this.rotationAngle })
        .scale({ x: this.scaleValue, y: this.scaleValue })
        .transition({
          type: TransitionType.All,
          translate: { x: this.translateX, y: this.translateY },
          rotate: { angle: this.rotationAngle },
          scale: { x: this.scaleValue, y: this.scaleValue }
        })
        .onClick(() => {
          animateTo({
            duration: 1500,
            curve: Curve.EaseInOut,
            delay: 200
          }, () => {
            this.translateX = this.translateX === 0 ? 200 : 0;
            this.translateY = this.translateY === 0 ? 200 : 0;
            this.rotationAngle = this.rotationAngle === 0 ? 360 : 0;
            this.scaleValue = this.scaleValue === 1 ? 1.5 : 1;
          });
        });

      Row({ space: 10 }) {
        Button('Animate')
          .onClick(() => {
            animateTo({
              duration: 1500,
              curve: Curve.EaseInOut,
              delay: 200
            }, () => {
              this.translateX = 200;
              this.translateY = 200;
              this.rotationAngle = 360;
              this.scaleValue = 1.5;
            });
          });

        Button('Reset')
          .onClick(() => {
            animateTo({
              duration: 1500,
              curve: Curve.EaseInOut,
              delay: 200
            }, () => {
              this.translateX = 0;
              this.translateY = 0;
              this.rotationAngle = 0;
              this.scaleValue = 1;
            });
          });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor(Color.White);
  }
}

