        if (this.showBackButton) {
          Image($r('app.media.app_icon'))
            .width(30)
            .height(30)
            .margin({ left: 10 })
            .onClick(() => {
              router.back();
            });
        }
        Text('Navigation Destination Query')
          .fontSize(20)
          .fontColor(Color.Black)
          .layoutWeight(1)
          .textAlign(TextAlign.Center);
        Image($r('app.media.app_icon'))
          .width(30)
          .height(30)
          .margin({ right: 10 });
      }
      .width('100%')
      .height(60)
      .backgroundColor(Color.White)
      .zIndex(99);

      Text('Navigation Destination Information')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 10 });

      Text(this.destinationInfo)
        .fontSize(18)
        .padding(16)
        .border({ width: 1, color: '#cccccc' })
        .borderRadius(8)
        .margin({ bottom: 20 });

      Button('Query Destination Info')
        .width('80%')
        .margin({ top: 20 })
        .onClick(() => {
          this.queryDestinationInfo();
        });
    }
    .width('100%')
    .height('100%')
    .padding(16)
    .backgroundColor('#f5f5f5');
  }

  private queryDestinationInfo() {
    const currentDestination = router.getState();
    if (currentDestination) {
      this.destinationInfo = `Current Destination: ${currentDestination.name}`;
      promptAction.showToast({ message: 'Destination information retrieved.' });
    } else {
      this.destinationInfo = 'No destination information available.';
      promptAction.showToast({ message: 'Unable to retrieve destination information.' });
    }
  }
}

