                .backgroundColor('#f0f0f0')
                .width('100%')
            }
          })
        }
        .width('100%')
      }
      .onRefreshing(() => {
        this.refreshing = true;
        this.fetchUpdatedHistory();
      })
    }
    .width('100%')
    .height('100%')
  }
}

