@Entry
@Component
struct CustomGestureImplementation {
  @State offsetX: number = 0;
  @State offsetY: number = 0;
  @State message: string = "Interact with Me";

  build() {
    Column() {
      Text(this.message)
        .fontSize(20)
        .margin({ bottom: 20 });

      // PanGesture example
      Row()
        .width(150)
        .height(150)
        .backgroundColor(Color.Blue)
        .borderRadius(10)
        .gesture(
          PanGesture({ direction: PanDirection.All })
            .onActionStart(() => {
              this.message = "Drag Started";
            })
            .onActionUpdate((event: GestureEvent) => {
              this.offsetX = event.offsetX;
              this.offsetY = event.offsetY;
            })
            .onActionEnd(() => {
              this.message = "Drag Ended";
              animateTo({ duration: 300 }, () => {
                this.offsetX = 0;
                this.offsetY = 0;
              });
            })
        )
        .transform({ translate: { x: this.offsetX, y: this.offsetY } })
        .animation({ duration: 300 });

      // TapGesture example
      Row()
        .width(150)
        .height(50)
        .margin({ top: 20 })
        .backgroundColor(Color.Orange)
        .borderRadius(10)
        .gesture(
          TapGesture({ count: 1 })
            .onAction(() => {
              this.message = "Single Tap Detected";
            })
        );

      // SwipeGesture example
      Row()
        .width(150)
        .height(50)
        .margin({ top: 20 })
        .backgroundColor(Color.Pink)
        .borderRadius(10)
        .gesture(
          SwipeGesture({ direction: SwipeDirection.Vertical })
            .onAction(() => {
              this.message = "Vertical Swipe Detected";
            })
        );
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center);
  }
}

