@Entry
@Component
struct AntiAliasedComponentExample {
  private settings: RenderingContextSettings = new RenderingContextSettings(true);
  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings);

  build() {
    Column() {
      Canvas(this.context)
        .width('100%')
        .height('100%')
        .backgroundColor(Color.White)
        .onReady(() => {
          this.drawAntiAliasedComponent();
        });
    }
    .width('100%')
    .height('100%');
  }

  private drawAntiAliasedComponent() {
    // Enable anti-aliasing
    this.context.imageSmoothingEnabled = true;

    // Draw a rectangle with anti-aliasing
    this.context.beginPath();
    this.context.rect(100, 100, 200, 150);
    this.context.fillStyle = '#FF5733'; // Orange color
    this.context.fill();

    // Stroke the rectangle
    this.context.lineWidth = 2;
    this.context.strokeStyle = '#000000'; // Black color
    this.context.stroke();
  }
}

