        .onClick(() => {
          this.insertTextAtPosition("ArkTS ", 7);
        })
        .margin(10);
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }

  private insertTextAtPosition(text: string, position: number): void {
    const currentValue: string = this.mutableStyledString.toString();
    const newValue: string = currentValue.slice(0, position) + text + currentValue.slice(position);
    const newStyledString = new MutableStyledString(newValue, []);
    this.mutableStyledString = newStyledString;
    this.controller.setStyledString(this.mutableStyledString);
  }
}

