class CustomMutableStyledString {
  private text: string;
  private attributes: Map<number, Map<string, string>>;

  constructor(text: string) {
    this.text = text;
    this.attributes = new Map();
  }

  toString(): string {
    return this.text;
  }

  removeAttributes(start: number, end: number, attributes: string[]): void {
    for (let i = start; i < end; i++) {
      if (this.attributes.has(i)) {
        const attrMap = this.attributes.get(i);
        if (attrMap) {
          for (const attr of attributes) {
            attrMap.delete(attr);
          }
        }
      }
    }
  }
}

