@Entry
@Component
struct FilterResultExplorer {
    @State private filterResult: FilterResult = {
        dimension: "Category",
        selectedValues: ["Electronics", "Books"],
        isExclusive: false,
        isEnabled: true,
        priority: 1
    };

    private toggleExclusive() {
        this.filterResult.isExclusive = !this.filterResult.isExclusive;
    }

    private toggleEnabled() {
        this.filterResult.isEnabled = !this.filterResult.isEnabled;
    }

    private increasePriority() {
        this.filterResult.priority += 1;
    }

    private decreasePriority() {
        this.filterResult.priority = Math.max(0, this.filterResult.priority - 1);
    }

    build() {
        Column() {
            Text(`Dimension: ${this.filterResult.dimension}`)
                .fontSize(18)
                .fontWeight(FontWeight.Bold)
                .margin({ top: 20 });

            Text(`Selected Values: ${this.filterResult.selectedValues.join(", ")}`)
                .fontSize(16)
                .margin({ top: 10 });

            Text(`Is Exclusive: ${this.filterResult.isExclusive}`)
                .fontSize(16)
                .margin({ top: 10 });

            Text(`Is Enabled: ${this.filterResult.isEnabled}`)
                .fontSize(16)
                .margin({ top: 10 });

            Text(`Priority: ${this.filterResult.priority}`)
                .fontSize(16)
                .margin({ top: 10 });

            Button('Toggle Exclusive')
                .onClick(() => this.toggleExclusive())
                .margin({ top: 20 });

            Button('Toggle Enabled')
                .onClick(() => this.toggleEnabled())
                .margin({ top: 10 });

            Button('Increase Priority')
                .onClick(() => this.increasePriority())
                .margin({ top: 10 });

            Button('Decrease Priority')
                .onClick(() => this.decreasePriority())
                .margin({ top: 10 });
        }
        .width('100%')
        .height('100%')
        .padding(20)
        .backgroundColor('#FFFFFF');
    }
}

interface FilterResult {
    dimension: string;
    selectedValues: string[];
    isExclusive: boolean;
    isEnabled: boolean;
    priority: number;
}

