@Entry
@Component
struct FilterStructExample {
  @State originalData: Array<string> = ['Apple', 'Banana', 'Cherry', 'Date', 'Elderberry', 'Fig', 'Grape'];
  @State filteredData: Array<string> = [];
  @State additionalFilters: Array<string> = [];
  @State searchText: string = '';

  applyFilters(): void {
    let tempData: Array<string> = this.originalData;
    if (this.searchText.trim()) {
      tempData = tempData.filter((item: string) =>
        item.toLowerCase().includes(this.searchText.toLowerCase())
      );
    }
    if (this.additionalFilters.length > 0) {
      tempData = tempData.filter((item: string) =>
        this.additionalFilters.every((filter: string) =>
          item.toLowerCase().includes(filter.toLowerCase())
        )
      );
    }
    this.filteredData = tempData;
  }

  build() {
    Column() {
      // Search input for primary filter
      TextInput({ placeholder: 'Search items...', text: this.searchText })
        .onChange((value: string) => {
          this.searchText = value;
          this.applyFilters();
        })
        .width('80%')
        .margin({ top: 20 })
        .backgroundColor('#f5f5f5')
        .borderRadius(8)
        .padding({ left: 10, right: 10, top: 8, bottom: 8 });

      // Input for additional filters
      TextInput({ placeholder: 'Enter additional filter', text: '' })
        .onChange((value: string) => {
          this.additionalFilters = value.trim() ? [value] : [];
          this.applyFilters();
        })
        .width('80%')
        .margin({ top: 10 })
        .backgroundColor('#f5f5f5')
        .borderRadius(8)
        .padding({ left: 10, right: 10, top: 8, bottom: 8 });

      // Display filtered list
      if (this.filteredData.length > 0) {
        List() {
          ForEach(this.filteredData, (item: string) => {
            ListItem() {
              Text(item)
                .fontSize(16)
                .padding(12)
                .backgroundColor('#f0f0f0')
                .width('100%')
            }
          })
        }
        .width('100%')
        .height('40%')
      } else {
        Text('No items match the filters')
          .fontSize(16)
          .fontColor('#999999')
          .margin({ top: 20 })
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .backgroundColor('#ffffff')
  }
}

