@Entry
@Component
struct FilterDisplayContainer {
  @State items: string[] = ['Apple', 'Banana', 'Orange', 'Grapes', 'Mango', 'Pineapple', 'Strawberry'];
  @State searchText: string = '';
  @State filteredItems: string[] = [];
  @State additionalFilters: string[] = [];

  applyFilters() {
    if (this.searchText.trim() === '' && this.additionalFilters.length === 0) {
      this.filteredItems = this.items;
    } else {
      this.filteredItems = this.items.filter(item => {
        const matchesSearch = this.searchText.trim() === '' || item.toLowerCase().includes(this.searchText.toLowerCase());
        const matchesAdditionalFilters = this.additionalFilters.length === 0 ||
          this.additionalFilters.every(filter => item.toLowerCase().includes(filter.toLowerCase()));
        return matchesSearch && matchesAdditionalFilters;
      });
    }
  }

  build() {
    Column() {
      // Search Bar
      TextInput({
        placeholder: 'Search items...',
        text: this.searchText
      })
        .width('90%')
        .onChange((value: string) => {
          this.searchText = value;
          this.applyFilters();
        })
        .margin(16)
        .backgroundColor('#f5f5f5')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      // Additional Filters Input
      TextInput({
        placeholder: 'Add additional filter...',
        text: ''
      })
        .width('90%')
        .onChange((value: string) => {
          this.additionalFilters = value.trim() ? [value] : [];
          this.applyFilters();
        })
        .margin({ left: 16, right: 16, bottom: 16 })
        .backgroundColor('#f5f5f5')
        .borderRadius(8)
        .padding({ left: 12, right: 12, top: 8, bottom: 8 });

      // Filtered Results Container
      Column() {
        if (this.filteredItems.length > 0) {
          ForEach(this.filteredItems, (item: string) => {
            Text(item)
              .fontSize(18)
              .padding(12)
              .backgroundColor(Color.White)
              .borderRadius(8)
              .margin({ bottom: 8 });
          });
        } else {
          Text('No items match the filters')
            .fontSize(16)
            .fontColor(Color.Gray)
            .padding(16);
        }
      }
      .width('90%')
      .padding(16)
      .backgroundColor('#e0e0e0')
      .borderRadius(12)
      .margin({ left: 16, right: 16 });
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

