struct DecorationTypeRetrieverExample {
  @State private decorationType: TextDecorationType = TextDecorationType.None;
  @State private styledText: string = "Example Styled String";

  private updateDecorationType(): void {
    if (this.decorationType === TextDecorationType.None) {
      this.decorationType = TextDecorationType.Underline;
    } else if (this.decorationType === TextDecorationType.Underline) {
      this.decorationType = TextDecorationType.LineThrough;
    } else {
      this.decorationType = TextDecorationType.None;
    }
  }

  private getCurrentDecorationType(): string {
    return this.decorationType.toString();
  }

  build() {
    Column() {
      Text(this.styledText)
        .fontSize(20)
        .decoration({
          type: this.decorationType,
          color: Color.Black
        })
        .padding(10)
        .backgroundColor('#f0f0f0')
        .width('80%')
        .height(50)
        .margin(10)
        .onClick(() => {
          this.updateDecorationType();
        })

      Text(`Current Decoration Type: ${this.getCurrentDecorationType()}`)
        .fontSize(16)
        .margin(10)
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

