@Entry
@Component
struct PolygonParamsExample {
  private settings: RenderingContextSettings = new RenderingContextSettings(true);
  private context: CanvasRenderingContext2D = new CanvasRenderingContext2D(this.settings);

  @State vertices: [number, number][] = [[50, 50], [150, 50], [200, 150], [100, 200], [50, 150]];
  @State fillColor: string = '#ff0000';
  @State strokeColor: string = '#0000ff';
  @State lineWidth: number = 5;

  private drawPolygon() {
    this.context.clearRect(0, 0, 300, 300);
    this.context.beginPath();
    this.context.moveTo(this.vertices[0][0], this.vertices[0][1]);

    for (let i = 1; i < this.vertices.length; i++) {
      this.context.lineTo(this.vertices[i][0], this.vertices[i][1]);
    }

    this.context.closePath();
    this.context.fillStyle = this.fillColor;
    this.context.fill();
    this.context.lineWidth = this.lineWidth;
    this.context.strokeStyle = this.strokeColor;
    this.context.stroke();
  }

  build() {
    Column() {
      Canvas(this.context)
        .width('100%')
        .height('60%')
        .backgroundColor('#ffffff')
        .onReady(() => {
          this.drawPolygon();
        });

      Row() {
        Button('Change Fill Color')
          .onClick(() => {
            this.fillColor = `#${Math.floor(Math.random() * 16777215).toString(16).padStart(6, '0')}`;
            this.drawPolygon();
          })
          .margin(5);

        Button('Change Stroke Color')
          .onClick(() => {
            this.strokeColor = `#${Math.floor(Math.random() * 16777215).toString(16).padStart(6, '0')}`;
            this.drawPolygon();
          })
          .margin(5);

        Button('Change Line Width')
          .onClick(() => {
            this.lineWidth = Math.floor(Math.random() * 10) + 1;
            this.drawPolygon();
          })
          .margin(5);
      }
      .margin(10);
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

