@Entry
@Component
struct ImageErrorHandling {
  @State imageUrl: string = 'app.media.app_icon';
  @State errorMessage: string = '';
  @State showPlaceholder: boolean = true;

  build() {
    Column() {
      if (this.showPlaceholder) {
        Column() {
          LoadingProgress()
            .color(Color.Blue)
            .width(50)
            .height(50)
          Text('Loading image...')
            .margin({ top: 10 })
        }
        .onAppear(() => {
          setTimeout(() => {
            this.showPlaceholder = false;
          }, 2000);
        })
      }

      if (!this.showPlaceholder && !this.errorMessage) {
        Image(this.imageUrl)
          .width(200)
          .height(200)
          .onError(() => {
            this.errorMessage = 'Failed to load image';
            this.showPlaceholder = false;
          })
      }

      if (this.errorMessage) {
        Column() {
          Image($r('app.media.app_icon'))
            .width(100)
            .height(100)
          Text(this.errorMessage)
            .fontColor(Color.Red)
            .margin({ top: 10 })
          Button('Retry')
            .onClick(() => {
              this.errorMessage = '';
              this.showPlaceholder = true;
            })
            .margin({ top: 20 })
        }
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

