  build() {
    Flex({ direction: FlexDirection.Column, alignItems: ItemAlign.Center, justifyContent: FlexAlign.Center }) {
      Canvas(this.renderContext)
        .width('100%')
        .height('100%')
        .backgroundColor('#FFFFFF')
        .onReady(() => {
          // Create a Polygon using Path2D
          let polygon = new Path2D();
          polygon.moveTo(50, 50);
          polygon.lineTo(150, 50);
          polygon.lineTo(200, 150);
          polygon.lineTo(100, 200);
          polygon.lineTo(50, 150);
          polygon.closePath();

          // Explore Polygon parameters
          this.renderContext.fillStyle = '#FFA50080'; // Semi-transparent orange
          this.renderContext.fill(polygon);

          this.renderContext.lineWidth = 4;
          this.renderContext.strokeStyle = '#0000FF'; // Blue stroke
          this.renderContext.stroke(polygon);
        });
    }
    .width('100%')
    .height('100%');
  }
}

import mediaQuery from '@ohos.mediaquery';

@Entry
@Component
struct ViewportFitDetector {
  @State private viewportFit: string = 'auto';
  private viewportFitListener: mediaQuery.MediaQueryListener = mediaQuery.matchMediaSync('(viewport-fit: auto), (viewport-fit: cover), (viewport-fit: contain)');

  aboutToAppear() {
    this.viewportFit = this.getViewportFit(this.viewportFitListener.matches);
    this.viewportFitListener.on('change', (result: mediaQuery.MediaQueryResult) => {
      this.viewportFit = this.getViewportFit(result.matches);
    });
  }

  aboutToDisappear() {
    this.viewportFitListener.off('change');
  }

  getViewportFit(matches: boolean): string {
    if (matches) {
      return 'cover';
    } else {
      return 'auto';
    }
  }

  build() {
    Column() {
      Text(`Viewport Fit: ${this.viewportFit}`)
        .fontSize(20)
        .fontColor(Color.Black)
        .margin(10);

      Image($r('app.media.app_icon'))
        .width('100%')
        .height('100%')
        .objectFit(this.viewportFit === 'cover' ? ImageFit.Cover : ImageFit.Contain)
        .backgroundColor(Color.Gray);
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White);
  }
}

