@Entry
@Component
struct PolylineConfigExample {
  @State points: number[][] = [[50, 50], [150, 150], [250, 50], [350, 150]];
  @State strokeColor: Color = Color.Black;
  @State strokeWidth: number = 3;
  @State strokeDashArray: number[] = [];
  @State strokeLineCap: LineCapStyle = LineCapStyle.Square;

  build() {
    Column() {
      Text('Configurable Polyline Example')
        .fontSize(20)
        .margin(10);

      Stack() {
        ForEach(this.points, (point: number[], index: number) => {
          if (index < this.points.length - 1) {
            Line()
              .startPoint([point[0], point[1]])
              .endPoint([this.points[index + 1][0], this.points[index + 1][1]])
              .stroke(this.strokeColor)
              .strokeWidth(this.strokeWidth)
              .strokeDashArray(this.strokeDashArray)
              .strokeLineCap(this.strokeLineCap);
          }
        });
      }
      .width('100%')
      .height('100%')
      .backgroundColor('#f5f5f5')

      Button('Change Stroke Color')
        .onClick(() => {
          this.strokeColor = this.strokeColor === Color.Black ? Color.Red : Color.Black;
        })
        .margin(10);

      Button('Change Stroke Width')
        .onClick(() => {
          this.strokeWidth = this.strokeWidth === 3 ? 6 : 3;
        })
        .margin(10);

      Button('Toggle Dash Array')
        .onClick(() => {
          this.strokeDashArray = this.strokeDashArray.length === 0 ? [15, 5] : [];
        })
        .margin(10);

      Button('Change Line Cap')
        .onClick(() => {
          this.strokeLineCap = this.strokeLineCap === LineCapStyle.Square ? LineCapStyle.Round : LineCapStyle.Square;
        })
        .margin(10);
    }
    .width('100%')
    .height('100%')
  }
}

