@Entry
@Component
struct PolylinePropertiesConfigurator {
  @State points: number[][] = [[50, 50], [150, 150], [250, 50], [350, 150]];
  @State strokeColor: Color = Color.Black;
  @State strokeWidth: number = 3;
  @State strokeDashArray: number[] = [];
  @State strokeLineCap: LineCapStyle = LineCapStyle.Square;

  build() {
    Column() {
      Stack() {
        ForEach(this.points, (point: number[], index: number) => {
          if (index < this.points.length - 1) {
            Line()
              .startPoint([point[0], point[1]])
              .endPoint([this.points[index + 1][0], this.points[index + 1][1]])
              .stroke(this.strokeColor)
              .strokeWidth(this.strokeWidth)
              .strokeDashArray(this.strokeDashArray)
              .strokeLineCap(this.strokeLineCap);
          }
        });
      }
      .width('100%')
      .height('100%')
      .backgroundColor('#f5f5f5')

      Button('Toggle Stroke Color')
        .onClick(() => {
          this.strokeColor = this.strokeColor === Color.Black ? Color.Red : Color.Black;
        })
        .margin(10);

      Button('Toggle Stroke Width')
        .onClick(() => {
          this.strokeWidth = this.strokeWidth === 3 ? 6 : 3;
        })
        .margin(10);

      Button('Toggle Dash Array')
        .onClick(() => {
          this.strokeDashArray = this.strokeDashArray.length === 0 ? [10, 5] : [];
        })
        .margin(10);

      Button('Toggle Line Cap')
        .onClick(() => {
          this.strokeLineCap = this.strokeLineCap === LineCapStyle.Square ? LineCapStyle.Round : LineCapStyle.Square;
        })
        .margin(10);
    }
    .width('100%')
    .height('100%')
  }
}

@Entry
@Component
struct CheckboxExample {
  @State isSelected: boolean = false;
  @State selectedOptions: string[] = [];

  build() {
    Column() {
      Column() {
        Checkbox({ name: 'checkbox1', group: 'optionsGroup' })
          .select(this.isSelected)
          .selectedColor(0x39a2db)
          .shape(CheckBoxShape.ROUNDED_SQUARE)
          .onChange((value: boolean) => {
            this.isSelected = value;
            console.info('Checkbox state changed to: ' + this.isSelected);
          });

        Text('Single Checkbox')
          .fontSize(16)
          .margin({ left: 10 });
      }
      .margin({ bottom: 20 });

      Column() {
        Text('Multi-Select Options:')
          .fontSize(20)
          .margin({ bottom: 10 });

        Checkbox({ name: 'optionA', group: 'multiGroup' })
          .select(false)
          .selectedColor(0x39a2db)
          .shape(CheckBoxShape.ROUNDED_SQUARE)
          .onChange((value: boolean) => {
            this.updateSelectedOptions('optionA', value);
          });

        Text('Option A')
          .fontSize(16)
          .margin({ left: 10 });

        Checkbox({ name: 'optionB', group: 'multiGroup' })
          .select(false)
          .selectedColor(0x39a2db)
          .shape(CheckBoxShape.ROUNDED_SQUARE)
          .onChange((value: boolean) => {
            this.updateSelectedOptions('optionB', value);
          });

        Text('Option B')
          .fontSize(16)
          .margin({ left: 10 });

        Checkbox({ name: 'optionC', group: 'multiGroup' })
          .select(false)
          .selectedColor(0x39a2db)
          .shape(CheckBoxShape.ROUNDED_SQUARE)
          .onChange((value: boolean) => {
            this.updateSelectedOptions('optionC', value);
          });

        Text('Option C')
          .fontSize(16)
          .margin({ left: 10 });

        Text('Selected: ' + this.selectedOptions.join(', '))
          .fontSize(16)
          .margin({ top: 10 });
      }
      .margin({ bottom: 20 });
    }
    .padding(20);
  }

  updateSelectedOptions(option: string, isSelected: boolean) {
    if (isSelected) {
      this.selectedOptions = [...this.selectedOptions, option];
    } else {
      this.selectedOptions = this.selectedOptions.filter(item => item !== option);
    }
  }
}

@Entry
@Component
struct StyledStringInsertApp {
  @State styledString: string = "Hello, World!";
  @State newString: string = "ArkTS";
  @State insertPosition: number = 7;

  build() {
    Column() {
      Text(this.styledString)
        .fontSize(20)
        .fontColor(Color.Black)
        .fontWeight(FontWeight.Bold)
        .margin(10);

      TextInput({ placeholder: "Enter text to insert" })
        .onChange((value: string) => {
          this.newString = value;
        })
        .margin(10);

      TextInput({ placeholder: "Enter position (0-" + this.styledString.length + ")" })
        .onChange((value: string) => {
          let pos = parseInt(value);
          if (!isNaN(pos) && pos >= 0 && pos <= this.styledString.length) {
            this.insertPosition = pos;
          }
        })
        .margin(10);

      Button("Insert Text")
        .onClick(() => {
          this.styledString = this.insertString(this.styledString, this.newString, this.insertPosition);
        })
        .margin(10);

      Text("Result: " + this.styledString)
        .fontSize(20)
        .fontColor(Color.Blue)
        .margin(10);
    }
    .width("100%")
    .height("100%")
    .padding(20)
    .backgroundColor(Color.White);
  }

  insertString(original: string, newString: string, position: number): string {
    return original.slice(0, position) + newString + original.slice(position);
  }
}

