import { LengthMetrics } from '@kit.ArkUI';

interface StyleRange {
  start: number;
  length: number;
  styledKey: StyledStringKey;
  styledValue: TextStyle;
}

@Entry
@Component
struct StyledStringReplacement {
  originalStyle: TextStyle = new TextStyle({
    fontColor: Color.Blue,
    fontSize: LengthMetrics.vp(18),
    fontWeight: FontWeight.Bold
  });

  newStyle: TextStyle = new TextStyle({
    fontColor: Color.Green,
    fontSize: LengthMetrics.vp(22),
    fontWeight: FontWeight.Normal,
    fontStyle: FontStyle.Italic
  });

  mutableString: MutableStyledString = new MutableStyledString("Replace Style Demo", [{
    start: 0,
    length: 7,
    styledKey: StyledStringKey.FONT,
    styledValue: this.originalStyle
  }]);

  controller: TextController = new TextController();
  options: TextOptions = { controller: this.controller };

  build() {
    Column() {
      Text(undefined, this.options)
        .fontSize(25)
        .margin(20)

      Button('Apply New Style (8-12)')
        .onClick(() => {
          const styleUpdate: StyleRange = {
            start: 8,
            length: 5,
            styledKey: StyledStringKey.FONT,
            styledValue: this.newStyle
          };
          this.mutableString.setStyle(styleUpdate);
          this.controller.setStyledString(this.mutableString);
        })
        .margin(10)
        .width('80%')

      Button('Reset to Original')
        .onClick(() => {
          const resetStyle: StyleRange = {
            start: 0,
            length: 7,
            styledKey: StyledStringKey.FONT,
            styledValue: this.originalStyle
          };
          this.mutableString.setStyle(resetStyle);
          this.controller.setStyledString(this.mutableString);
        })
        .margin(10)
        .width('80%')
    }
    .width('100%')
    .height('100%')
    .onAppear(() => {
      this.controller.setStyledString(this.mutableString);
    })
  }
}

