        .margin({ bottom: 20 });

      Text(this.measurementStatus)
        .fontSize(16)
        .margin({ bottom: 10 });

      Text(`Measured LCP Time: ${this.lcpTime} ms`)
        .fontSize(16)
        .margin({ bottom: 20 });

      Button(this.isMeasuring ? 'Measuring...' : 'Measure LCP')
        .onClick(() => {
          if (!this.isMeasuring) {
            this.measureLCP();
          }
        })
        .margin({ top: 20 })
        .width(200)
        .height(50);
    }
    .padding(20)
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center);
  }

  private measureLCP() {
    this.isMeasuring = true;
    this.measurementStatus = 'Measuring LCP...';

    // Simulate LCP measurement with a delay
    setTimeout(() => {
      this.lcpTime = Math.floor(Math.random() * 1000); // Random LCP time for demonstration
      this.isMeasuring = false;
      this.measurementStatus = 'Measurement complete!';
    }, 1500);
  }
}

