import UIAbility from '@ohos.app.ability.UIAbility';
import AbilityConstant from '@ohos.app.ability.AbilityConstant';
import common from '@ohos.app.ability.common';
import Want from '@ohos.app.ability.Want';

@Entry
@Component
struct FullScreenLaunchComponent {
  @State launchMode: string = 'standard';
  @State backgroundMode: string = 'default';
  @State isLaunched: boolean = false;

  build() {
    Column({ space: 20 }) {
      Text('Atomic Service Launch Options')
        .fontSize(24)
        .fontColor(Color.Black)
        .margin({ bottom: 30 });

      Text('Launch Mode:')
        .fontSize(18)
        .alignSelf(ItemAlign.Start);

      // Launch Mode Selection
      Row() {
        Toggle({ type: ToggleType.Checkbox, isOn: this.launchMode === 'standard' })
          .onChange((isOn: boolean) => {
            if (isOn) this.launchMode = 'standard';
          });
        Text('Standard').fontSize(16).margin({ left: 10 });
      }.margin({ bottom: 20 }).width('100%')

      Row() {
        Toggle({ type: ToggleType.Checkbox, isOn: this.launchMode === 'single' })
          .onChange((isOn: boolean) => {
            if (isOn) this.launchMode = 'single';
          });
        Text('Single').fontSize(16).margin({ left: 10 });
      }.margin({ bottom: 20 }).width('100%')

      Text('Background Mode:')
        .fontSize(18)
        .alignSelf(ItemAlign.Start);

      // Background Mode Selection
      Row() {
        Toggle({ type: ToggleType.Checkbox, isOn: this.backgroundMode === 'default' })
          .onChange((isOn: boolean) => {
            if (isOn) this.backgroundMode = 'default';
          });
        Text('Default').fontSize(16).margin({ left: 10 });
      }.margin({ bottom: 20 }).width('100%')

      Row() {
        Toggle({ type: ToggleType.Checkbox, isOn: this.backgroundMode === 'transparent' })
          .onChange((isOn: boolean) => {
            if (isOn) this.backgroundMode = 'transparent';
          });
        Text('Transparent').fontSize(16).margin({ left: 10 });
      }.margin({ bottom: 20 }).width('100%')

      Button('Launch Atomic Service')
        .width(200)
        .height(50)
        .onClick(() => {
          this.launchAtomicService();
        })
        .margin({ top: 30 });

      if (this.isLaunched) {
        Text('Service Launched Successfully')
          .fontSize(18)
          .fontColor(Color.Green)
          .margin({ top: 20 });
      }
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
  }

  private launchAtomicService() {
    let want: Want = {
      bundleName: 'com.example.atomicService',
      abilityName: 'MainAbility',
      parameters: {
        launchMode: this.launchMode,
        backgroundMode: this.backgroundMode
      }
    };

    let context: common.UIAbilityContext = getContext() as common.UIAbilityContext;
    try {
      context.startAbility(want, (err) => {
        if (err) {
          console.error('Failed to launch atomic service:', err);
        } else {
          this.isLaunched = true;
          console.log('Atomic service launched successfully');
        }
      });
    } catch (error) {
      console.error('StartAbility error:', error);
    }
  }
}

