@Entry
@Component
struct PolylineFoldDisplay {
  @State points: number[][] = [[50, 50], [150, 150], [250, 50], [350, 150], [450, 50]];
  @State folded: boolean = false;

  toggleFold() {
    this.folded = !this.folded;
  }

  build() {
    Column() {
      Stack() {
        ForEach(this.points, (point: number[], index: number) => {
          if (index < this.points.length - 1) {
            Line()
              .startPoint([point[0], point[1]])
              .endPoint([
                this.folded && index % 2 === 0 ? point[0] + 100 : this.points[index + 1][0],
                this.folded && index % 2 === 0 ? point[1] + 100 : this.points[index + 1][1]
              ])
              .stroke(Color.Black)
              .strokeWidth(3);
          }
        });
      }
      .width('100%')
      .height('80%')

      Button(this.folded ? 'Unfold' : 'Fold')
        .onClick(() => this.toggleFold())
        .margin(20)
        .width(100)
        .height(40)
        .backgroundColor(Color.Blue)
        .fontColor(Color.White);

      Text(`ArkTS Version: 3.2.0 (Introduces Draw Fold)`)
        .fontSize(16)
        .margin(10)
        .fontWeight(FontWeight.Medium);
    }
    .width('100%')
    .height('100%')
  }
}

