@Entry
@Component
struct SSLConfiguration {
  @State errorMessage: string = ''
  @State isError: boolean = false
  @State isCertificateAccepted: boolean = false

  handleSSLError(error: SSLError) {
    switch (error.type) {
      case SSLErrorType.CERTIFICATE_EXPIRED:
        this.errorMessage = 'SSL Certificate Expired'
        break
      case SSLErrorType.CERTIFICATE_INVALID:
        this.errorMessage = 'Invalid SSL Certificate detected. Do you want to proceed?'
        break
      case SSLErrorType.CERTIFICATE_UNTRUSTED:
        this.errorMessage = 'SSL Certificate Untrusted'
        break
      case SSLErrorType.CONNECTION_FAILED:
        this.errorMessage = 'SSL Connection Failed'
        break
      default:
        this.errorMessage = 'Unknown SSL Error'
    }
    this.isError = true
  }

  onAcceptCertificate() {
    this.isCertificateAccepted = true
    this.errorMessage = 'Certificate accepted. Proceeding with the request.'
    this.isError = false
  }

  onRejectCertificate() {
    this.isCertificateAccepted = false
    this.errorMessage = 'Certificate rejected. Request aborted.'
    this.isError = false
  }

  build() {
    Column({ space: 20 }) {
      Button('Simulate SSL Error')
        .onClick(() => {
          const error: SSLError = {
            type: SSLErrorType.CERTIFICATE_INVALID,
            message: 'The SSL certificate is invalid.'
          }
          this.handleSSLError(error)
        })
        .width('80%')
        .backgroundColor('#4CAF50')
        .fontColor(Color.White)

      if (this.isError) {
        Text(this.errorMessage)
          .fontSize(16)
          .fontColor(Color.Red)
          .margin({ top: 10 })

        Button('Accept Certificate')
          .onClick(() => this.onAcceptCertificate())
          .width('60%')
          .backgroundColor('#008CBA')
          .fontColor(Color.White)
          .margin({ top: 10 })

        Button('Reject Certificate')
          .onClick(() => this.onRejectCertificate())
          .width('60%')
          .backgroundColor('#f44336')
          .fontColor(Color.White)
          .margin({ top: 10 })
      }

      if (this.isCertificateAccepted) {
        Text(this.errorMessage)
          .fontSize(16)
          .fontColor(Color.Green)
      }
    }
    .padding(20)
    .width('100%')
    .height('100%')
  }
}

enum SSLErrorType {
  CERTIFICATE_EXPIRED,
  CERTIFICATE_INVALID,
  CERTIFICATE_UNTRUSTED,
  CONNECTION_FAILED
}

interface SSLError {
  type: SSLErrorType,
  message: string
}

